    private WorkspaceScopeService $workspaceScope;
    private AIService $aiService;

    public function __construct(?WorkspaceScopeService $workspaceScope = null, ?AIService $aiService = null)
    {
        $this->workspaceScope = $workspaceScope ?? new WorkspaceScopeService();
        $this->aiService = $aiService ?? new AIService();
    }

    public function getDashboardSummary(?array $onboardingStatus = null): array
    {
        $summaryStartedAt = microtime(true);
        $summaryStartQueryCount = Database::getQueryCount();
        $workspaceId = $this->workspaceId();
        $attributionSummary = [];
        $conversionGoalSummary = [];
        $handoffSummary = [];
        $counts = [
            'due_this_week' => $this->countContent("scheduled_at IS NOT NULL AND scheduled_at BETWEEN NOW() AND DATE_ADD(NOW(), INTERVAL 7 DAY) AND status IN ('approved','scheduled')"),
            'drafts' => $this->countContent("status IN ('idea','draft')"),
            'in_review' => $this->countContent("status = 'review'"),
            'scheduled' => $this->countContent("status = 'scheduled'"),
        ];
        if (Database::tableExists('marketing_campaign_briefs')) {
            $counts['briefs_in_progress'] = $this->countRows('marketing_campaign_briefs', "status IN ('draft','active')");
        }
        if (Database::tableExists('marketing_content_approvals')) {
            $counts['approvals_waiting'] = $this->countRows('marketing_content_approvals', "status = 'pending'");
        }
        if (Database::tableExists('marketing_content_comments')) {
            $counts['unresolved_comments'] = $this->countRows('marketing_content_comments', 'resolved_at IS NULL');
        }
        if (Database::tableExists('marketing_calendar_milestones')) {
            $counts['calendar_this_week'] = $this->countRows('marketing_calendar_milestones', "milestone_date BETWEEN CURDATE() AND DATE_ADD(CURDATE(), INTERVAL 7 DAY) AND status = 'planned'");
        }
        if (Database::tableExists('marketing_distribution_posts')) {
            $counts['distribution_queue'] = $this->countRows('marketing_distribution_posts', "status IN ('draft','scheduled')");
            $counts['exported_posts'] = $this->countRows('marketing_distribution_posts', "status = 'exported'");
        }
        if (Database::tableExists('marketing_utm_links')) {
            $counts['utm_links'] = $this->countRows('marketing_utm_links', 'id > 0');
        }
        if (Database::tableExists('marketing_email_campaign_runs')) {
            $counts['email_runs_ready'] = $this->countRows('marketing_email_campaign_runs', "status = 'ready'");
            $counts['email_runs_exported'] = $this->countRows('marketing_email_campaign_runs', "status = 'exported'");
        }
        if (Database::tableExists('marketing_channel_export_bundles')) {
            $counts['channel_exports_ready'] = $this->countRows('marketing_channel_export_bundles', "status = 'ready'");
            $counts['channel_exports_exported'] = $this->countRows('marketing_channel_export_bundles', "status = 'exported'");
        }
        if (Database::tableExists('marketing_channel_media_kits')) {
            $counts['channel_media_kits_ready'] = $this->countRows('marketing_channel_media_kits', "status = 'ready'");
            $counts['channel_media_kits_draft'] = $this->countRows('marketing_channel_media_kits', "status = 'draft'");
        }
        if (Database::tableExists('marketing_ai_quality_checks')) {
            $counts['quality_checks'] = $this->countRows('marketing_ai_quality_checks', "status = 'completed'");
            $counts['quality_risk_items'] = $this->countRows('marketing_ai_quality_checks', "overall_score < 70 AND status = 'completed'");
        }
        if (Database::tableExists('marketing_asset_requests')) {
            $counts['asset_requests_open'] = $this->countRows('marketing_asset_requests', "status IN ('requested','in_progress')");
            $counts['asset_requests_ready'] = $this->countRows('marketing_asset_requests', "status IN ('ready','approved')");
        }
        if (Database::tableExists('marketing_media_production_work_items')) {
            $counts['media_production_open'] = $this->countRows('marketing_media_production_work_items', "status IN ('requested','assigned','in_progress','review','blocked')");
            $counts['media_production_overdue'] = $this->countRows('marketing_media_production_work_items', "due_at IS NOT NULL AND due_at < NOW() AND status NOT IN ('ready','approved','archived')");
            $counts['media_production_blocked'] = $this->countRows('marketing_media_production_work_items', "status = 'blocked'");
        }
        if (Database::tableExists('marketing_media_files')) {
            $counts['media_missing_alt_text'] = $this->countRows('marketing_media_files', "media_type IN ('image','logo','thumbnail','banner') AND COALESCE(alt_text, '') = ''");
            $counts['media_blocked'] = $this->countRows('marketing_media_files', "approval_status IN ('blocked','archived') OR license_status IN ('expired','restricted')");
            $counts['media_expiring'] = $this->countRows('marketing_media_files', "expiry_date IS NOT NULL AND expiry_date <= DATE_ADD(CURDATE(), INTERVAL 30 DAY)");
        }
        if (Database::tableExists('marketing_recurring_rhythms')) {
            $counts['active_rhythms'] = $this->countRows('marketing_recurring_rhythms', "status = 'active'");
        }
        if (Database::tableExists('marketing_planning_queue_items')) {
            $counts['planning_queue_open'] = $this->countRows('marketing_planning_queue_items', "status IN ('planned','in_progress','blocked')");
            $counts['planning_queue_overdue'] = $this->countRows('marketing_planning_queue_items', "due_at IS NOT NULL AND due_at < NOW() AND status NOT IN ('done','archived')");
            $counts['ai_strategy_gaps'] = count($this->listMarketingAiQueueSuggestions('phase_5', 250, 0));
        }
        if (Database::tableExists('marketing_campaign_budgets')) {
            $counts['active_budgets'] = $this->countRows('marketing_campaign_budgets', "status = 'active'");
            $counts['roi_targets'] = Database::tableExists('marketing_roi_targets') ? $this->countRows('marketing_roi_targets', "status IN ('draft','active')") : 0;
        }
        if (Database::tableExists('marketing_launch_readiness_reviews')) {
            $counts['launch_reviews_blocked'] = $this->countRows('marketing_launch_readiness_reviews', "status = 'blocked'");
            $counts['launch_reviews_ready'] = $this->countRows('marketing_launch_readiness_reviews', "status IN ('ready','approved')");
        }
        if (Database::tableExists('marketing_launch_control_records')) {
            $counts['launch_control_ready'] = $this->countRows('marketing_launch_control_records', "status = 'ready'");
            $counts['launch_control_blocked'] = $this->countRows('marketing_launch_control_records', "status = 'blocked'");
            $counts['launch_control_launched'] = $this->countRows('marketing_launch_control_records', "status = 'launched_manual'");
        }
        if (Database::tableExists('marketing_campaign_launch_checklists')) {
            $counts['launch_checklists_open'] = $this->countRows('marketing_campaign_launch_checklists', "status IN ('draft','ready','blocked')");
            $counts['launch_checklists_ready'] = $this->countRows('marketing_campaign_launch_checklists', "status = 'ready'");
            $counts['launch_checklists_blocked'] = $this->countRows('marketing_campaign_launch_checklists', "status = 'blocked'");
        }
        if (Database::tableExists('marketing_guided_workflows')) {
            $counts['guided_workflows_ready'] = $this->countRows('marketing_guided_workflows', "status IN ('ready','completed')");
            $counts['guided_workflows_blocked'] = $this->countRows('marketing_guided_workflows', "status = 'blocked'");
        }
        if (Database::tableExists('marketing_campaign_workspaces')) {
            $counts['campaign_workspaces_ready'] = $this->countRows('marketing_campaign_workspaces', "status = 'ready'");
            $counts['campaign_workspaces_blocked'] = $this->countRows('marketing_campaign_workspaces', "status = 'blocked'");
            $counts['campaign_workspaces_launched'] = $this->countRows('marketing_campaign_workspaces', "status = 'launched'");
        }
        if (Database::tableExists('marketing_audience_activations')) {
            $counts['audience_activations_active'] = $this->countRows('marketing_audience_activations', "status = 'active'");
            $counts['audience_activations_blocked'] = $this->countRows('marketing_audience_activations', "coverage_status = 'blocked' AND status <> 'archived'");
            $counts['audience_activations_ready'] = $this->countRows('marketing_audience_activations', "coverage_status = 'ready' AND status <> 'archived'");
        }
        if (Database::tableExists('marketing_experiments')) {
            $counts['running_experiments'] = $this->countRows('marketing_experiments', "status = 'running'");
        }
        if (Database::tableExists('marketing_tracking_events')) {
            $counts['landing_page_views'] = Database::tableExists('marketing_landing_page_views') ? $this->countRows('marketing_landing_page_views', 'id > 0') : 0;
            $counts['cta_clicks'] = Database::tableExists('marketing_cta_clicks') ? $this->countRows('marketing_cta_clicks', 'id > 0') : 0;
            $counts['conversion_events'] = Database::tableExists('marketing_conversion_events') ? $this->countRows('marketing_conversion_events', 'id > 0') : 0;
        }
        if (Database::tableExists('marketing_attribution_touchpoints')) {
            $attributionSummary = $this->getMarketingAttributionSummary();
            $counts['attribution_touchpoints'] = (int) ($attributionSummary['touchpoints'] ?? 0);
            $counts['influenced_leads'] = (int) ($attributionSummary['influenced_leads'] ?? 0);
            $counts['influenced_deals'] = (int) ($attributionSummary['influenced_deals'] ?? 0);
        }
        if (Database::tableExists('marketing_conversion_goals')) {
            $conversionGoalSummary = $this->getConversionGoalSummary();
            $counts['conversion_goals_active'] = (int) ($conversionGoalSummary['active'] ?? 0);
            $counts['conversion_goals_missing_links'] = (int) ($conversionGoalSummary['missing_links'] ?? 0);
        }
        if (Database::tableExists('marketing_lead_handoffs')) {
            $handoffSummary = $this->getLeadHandoffSummary();
            $counts['lead_handoffs_open'] = (int) ($handoffSummary['open'] ?? 0);
            $counts['lead_handoffs_assigned'] = (int) ($handoffSummary['assigned'] ?? 0);
            $counts['lead_handoffs_overdue'] = (int) ($handoffSummary['overdue'] ?? 0);
            $counts['lead_handoffs_converted'] = (int) ($handoffSummary['converted'] ?? 0);
            $counts['lead_handoffs_sync_pending'] = (int) ($handoffSummary['sync_pending'] ?? 0);
            $counts['lead_handoffs_sync_failed'] = (int) ($handoffSummary['sync_failed'] ?? 0);
        }
        if (Database::tableExists('marketing_action_router_items')) {
            $counts['action_router_open'] = $this->countRows('marketing_action_router_items', "action_status IN ('suggested','accepted')");
            $counts['action_router_high_priority'] = $this->countRows('marketing_action_router_items', "action_status IN ('suggested','accepted') AND priority = 'high'");
        }

        $activeCampaigns = 0;
        if (Database::tableExists('campaigns')) {
            $row = Database::queryOne(
                "SELECT COUNT(*) AS count FROM campaigns WHERE workspace_id = ? AND status = 'active'",
                [$workspaceId]
            );
            $activeCampaigns = (int) ($row['count'] ?? 0);
        }

        $counts += ['active_campaigns' => $activeCampaigns];

        $integrationReadiness = $this->getMarketingIntegrationReadiness(40);
        $crmLifecycleProfile = Database::tableExists('marketing_crm_lifecycle_insights')
            ? $this->getMarketingCrmLifecycleProfile([], 8)
            : [];
        $automationReadiness = $this->getMarketingAutomationReadiness((int) ($_SESSION['user_id'] ?? 0) ?: null);
        $aiWorkspaceBrain = $this->getMarketingAiWorkspaceBrain((int) ($_SESSION['user_id'] ?? 0) ?: null, $integrationReadiness, $automationReadiness);
        $guidedRecommendations = $this->getMarketingGuidedRecommendations((int) ($_SESSION['user_id'] ?? 0) ?: null, 12, $aiWorkspaceBrain);
        $performanceSummary = Database::tableExists('marketing_distribution_posts') ? $this->getPerformanceSummary() : [];
        $campaignRevenueLoop = (array) ($performanceSummary['campaign_revenue_loop'] ?? $this->getCampaignRevenueLoopSummary(null, 6));
        $decisionCenter = Database::tableExists('marketing_decision_center_items')
            ? $this->getMarketingDecisionCenter((int) ($_SESSION['user_id'] ?? 0) ?: null, 6)
            : [];

        $dashboardSummary = [
            'counts' => $counts,
            'due_items' => $this->listContentItems([
                'scheduled_from' => date('Y-m-d'),
                'scheduled_to' => date('Y-m-d', strtotime('+7 days')),
                'exclude_status' => 'archived',
            ], 6, 0),
            'review_items' => $this->listContentItems(['status' => 'review'], 6, 0),
            'recent_items' => $this->listContentItems(['exclude_status' => 'archived'], 6, 0),
            'active_campaigns' => $this->activeCampaigns(5),
            'top_forms' => $this->topForms(5),
            'recent_attributed_revenue' => $this->recentAttributedRevenue(5),
