    public function getCachedDashboardSummary(?array $onboardingStatus = null, int $ttlSeconds = 60): array
    {
        $this->assertMarketingPermission('marketing.read');
        $ttlSeconds = max(0, min($ttlSeconds, 600));
        if ($ttlSeconds <= 0 || !Database::tableExists('marketing_dashboard_summary_cache')) {
            $summary = $this->getDashboardSummary($onboardingStatus);
            $summary['page_speed_profile']['cache_status'] = 'bypassed';
            $summary['page_speed_profile']['cache_ttl_seconds'] = 0;
            return $summary;
        }

        $cacheKey = $this->dashboardSummaryCacheKey();
        $row = Database::queryOne(
            "SELECT payload_json, query_count, build_ms, expires_at, updated_at
             FROM marketing_dashboard_summary_cache
             WHERE workspace_id = ? AND cache_key = ? AND expires_at > NOW()
             LIMIT 1",
            [$this->workspaceId(), $cacheKey]
        );
        if ($row) {
            $payload = json_decode((string) ($row['payload_json'] ?? ''), true);
            if (is_array($payload)) {
                $payload['page_speed_profile'] = (array) ($payload['page_speed_profile'] ?? []);
                $payload['page_speed_profile']['cache_status'] = 'hit';
                $payload['page_speed_profile']['cache_ttl_seconds'] = $ttlSeconds;
                $payload['page_speed_profile']['cache_expires_at'] = (string) ($row['expires_at'] ?? '');
                $payload['page_speed_profile']['cached_build_ms'] = (float) ($row['build_ms'] ?? 0);
                $payload['page_speed_profile']['cached_query_count'] = (int) ($row['query_count'] ?? 0);
                $payload['page_speed_profile']['cache_generated_at'] = (string) ($row['updated_at'] ?? '');
                return $payload;
            }
        }

        $summary = $this->getDashboardSummary($onboardingStatus);
        $profile = (array) ($summary['page_speed_profile'] ?? []);
        $queryCount = (int) ($profile['query_count'] ?? 0);
        $buildMs = (float) ($profile['elapsed_ms'] ?? 0);
        $metadata = [
            'cache_key' => $cacheKey,
            'ttl_seconds' => $ttlSeconds,
            'cached_at' => date('c'),
            'user_id' => $this->currentUserId(),
            'workspace_role' => (string) ($_SESSION['active_workspace_role'] ?? ''),
            'manual_first' => true,
        ];
        Database::execute(
            "INSERT INTO marketing_dashboard_summary_cache
             (workspace_id, cache_key, payload_json, query_count, build_ms, expires_at, cache_metadata_json)
             VALUES (?, ?, ?, ?, ?, DATE_ADD(NOW(), INTERVAL ? SECOND), ?)
             ON DUPLICATE KEY UPDATE
                payload_json = VALUES(payload_json),
                query_count = VALUES(query_count),
                build_ms = VALUES(build_ms),
                expires_at = VALUES(expires_at),
                cache_metadata_json = VALUES(cache_metadata_json),
                updated_at = CURRENT_TIMESTAMP",
            [
                $this->workspaceId(),
                $cacheKey,
                $this->normalizeJsonValue($this->sanitizeJsonCompatible($summary)),
                $queryCount,
                $buildMs,
                $ttlSeconds,
                $this->normalizeJsonValue($metadata),
            ]
        );

        $summary['page_speed_profile']['cache_status'] = 'miss';
        $summary['page_speed_profile']['cache_ttl_seconds'] = $ttlSeconds;
        $summary['page_speed_profile']['cache_expires_at'] = date('c', time() + $ttlSeconds);
        return $summary;
    }

