    private function getCachedMarketingOperatorSummary(string $cacheKey, callable $builder, int $ttlSeconds, string $summaryType): array
    {
        $ttlSeconds = max(0, min($ttlSeconds, 600));
        if ($ttlSeconds <= 0 || !Database::tableExists('marketing_dashboard_summary_cache')) {
            $payload = $builder();
            $payload['performance'] = (array) ($payload['performance'] ?? []);
            $payload['performance']['cache_status'] = 'bypassed';
            $payload['performance']['cache_ttl_seconds'] = 0;
            return $payload;
        }

        $row = Database::queryOne(
            "SELECT payload_json, query_count, build_ms, expires_at, updated_at
             FROM marketing_dashboard_summary_cache
             WHERE workspace_id = ? AND cache_key = ? AND expires_at > NOW()
             LIMIT 1",
            [$this->workspaceId(), $cacheKey]
        );
        if ($row) {
            $payload = json_decode((string) ($row['payload_json'] ?? ''), true);
            if (is_array($payload)) {
                $payload['performance'] = (array) ($payload['performance'] ?? []);
                $payload['performance']['cache_status'] = 'hit';
                $payload['performance']['cache_key'] = $cacheKey;
                $payload['performance']['cache_ttl_seconds'] = $ttlSeconds;
                $payload['performance']['cache_expires_at'] = (string) ($row['expires_at'] ?? '');
                $payload['performance']['cached_build_ms'] = (float) ($row['build_ms'] ?? 0);
                $payload['performance']['cached_query_count'] = (int) ($row['query_count'] ?? 0);
                $payload['performance']['cache_generated_at'] = (string) ($row['updated_at'] ?? '');
                return $payload;
            }
        }

        $startQueryCount = Database::getQueryCount();
        $startedAt = microtime(true);
        $payload = $builder();
        $queryCount = max(0, Database::getQueryCount() - $startQueryCount);
        $buildMs = (microtime(true) - $startedAt) * 1000;
        $metadata = [
            'cache_key' => $cacheKey,
            'summary_type' => $summaryType,
            'ttl_seconds' => $ttlSeconds,
            'cached_at' => date('c'),
            'user_id' => $this->currentUserId(),
            'workspace_role' => (string) ($_SESSION['active_workspace_role'] ?? ''),
            'manual_first' => true,
            'external_api_calls' => false,
            'secret_fields_cached' => false,
        ];
        Database::execute(
            "INSERT INTO marketing_dashboard_summary_cache
             (workspace_id, cache_key, payload_json, query_count, build_ms, expires_at, cache_metadata_json)
             VALUES (?, ?, ?, ?, ?, DATE_ADD(NOW(), INTERVAL ? SECOND), ?)
             ON DUPLICATE KEY UPDATE
                payload_json = VALUES(payload_json),
                query_count = VALUES(query_count),
                build_ms = VALUES(build_ms),
                expires_at = VALUES(expires_at),
                cache_metadata_json = VALUES(cache_metadata_json),
                updated_at = CURRENT_TIMESTAMP",
            [
                $this->workspaceId(),
                $cacheKey,
                $this->normalizeJsonValue($this->sanitizeJsonCompatible($payload)),
                $queryCount,
                $buildMs,
                $ttlSeconds,
                $this->normalizeJsonValue($metadata),
            ]
        );

        $payload['performance'] = (array) ($payload['performance'] ?? []);
        $payload['performance']['cache_status'] = 'miss';
        $payload['performance']['cache_key'] = $cacheKey;
        $payload['performance']['cache_ttl_seconds'] = $ttlSeconds;
        $payload['performance']['cache_expires_at'] = date('c', time() + $ttlSeconds);
        $payload['performance']['build_ms'] = round($buildMs, 2);
        $payload['performance']['query_count'] = $queryCount;

        return $payload;
    }

    private function operatorQueueCacheKey(string $queueType, ?int $userId, int $limit): string
    {
        $role = Security::sanitizeInput((string) ($_SESSION['active_workspace_role'] ?? 'unknown'), 'string');
        $userPart = $userId !== null && $userId > 0 ? (string) $userId : 'all';
        return 'operator_queue:' . $queueType . ':v1:user:' . $userPart . ':role:' . $role . ':limit:' . $limit;
    }

    public function clearMarketingDashboardSummaryCache(?string $cacheKey = null): int
    {
        $this->assertMarketingPermission('marketing.manage');
        if (!Database::tableExists('marketing_dashboard_summary_cache')) {
            return 0;
        }

        if ($cacheKey !== null && trim($cacheKey) !== '') {
            return Database::execute(
                'DELETE FROM marketing_dashboard_summary_cache WHERE workspace_id = ? AND cache_key = ?',
                [$this->workspaceId(), Security::sanitizeInput($cacheKey, 'string')]
            );
        }

        return Database::execute(
            'DELETE FROM marketing_dashboard_summary_cache WHERE workspace_id = ?',
            [$this->workspaceId()]
        );
    }

    public function getMarketingDashboardCacheStatus(): array
    {
        $this->assertMarketingPermission('marketing.read');
        if (!Database::tableExists('marketing_dashboard_summary_cache')) {
            return [
                'available' => false,
                'current' => null,
                'entries' => [],
                'guardrails' => ['workspace_scoped' => true, 'external_api_calls' => false],
            ];
        }

        $cacheKey = $this->dashboardSummaryCacheKey();
        $entries = array_map(
            fn(array $row): array => $this->hydrateJsonFields($row, ['cache_metadata_json']),
            Database::query(
                "SELECT cache_key, query_count, build_ms, expires_at, cache_metadata_json, updated_at,
                        expires_at > NOW() AS is_fresh
                 FROM marketing_dashboard_summary_cache
                 WHERE workspace_id = ?
                 ORDER BY updated_at DESC
                 LIMIT 20",
                [$this->workspaceId()]
            )
        );
        $current = null;
        foreach ($entries as $entry) {
            if ((string) ($entry['cache_key'] ?? '') === $cacheKey) {
                $current = $entry;
                break;
            }
        }

        return [
            'available' => true,
            'cache_key' => $cacheKey,
            'current' => $current,
            'entries' => $entries,
            'guardrails' => [
                'workspace_scoped' => true,
                'user_role_scoped' => true,
                'external_api_calls' => false,
                'secret_fields_cached' => false,
            ],
        ];
    }

    public function getMarketingPageSpeedProfile(?array $dashboardSummary = null, ?int $queryCount = null, ?float $elapsedMs = null): array
    {
        $queryBudget = 450;
        $elapsedBudgetMs = 2500.0;
        $expectedListCaps = [
            'due_items' => 6,
            'review_items' => 6,
            'recent_items' => 6,
            'active_campaigns' => 5,
            'top_forms' => 5,
            'recent_attributed_revenue' => 5,
            'briefs_in_progress' => 5,
            'approvals_waiting' => 5,
            'calendar_this_week' => 6,
            'unresolved_comments' => 6,
            'distribution_queue' => 6,
            'email_runs' => 6,
            'channel_exports' => 6,
            'quality_checks' => 6,
            'asset_requests' => 6,
            'planning_queue' => 6,
            'ai_strategy_gaps' => 6,
            'recurring_rhythms' => 6,
            'experiments' => 6,
        ];

        $listLimits = [];
        $heavyListsLimited = true;
        foreach ($expectedListCaps as $section => $cap) {
            $actual = isset($dashboardSummary[$section]) && is_array($dashboardSummary[$section])
                ? count($dashboardSummary[$section])
                : 0;
            $listLimits[$section] = [
                'cap' => $cap,
                'actual' => $actual,
                'within_cap' => $actual <= $cap,
            ];
            if ($actual > $cap) {
                $heavyListsLimited = false;
            }
        }

        $integrationPerformance = (array) ($dashboardSummary['integration_readiness']['performance'] ?? []);
        $crmPerformance = (array) ($dashboardSummary['crm_lifecycle_profile']['performance'] ?? []);
        $sectionCount = is_array($dashboardSummary) ? count($dashboardSummary) : 0;
        $countMetricCount = isset($dashboardSummary['counts']) && is_array($dashboardSummary['counts'])
            ? count($dashboardSummary['counts'])
            : 0;
        $queryCount = $queryCount ?? Database::getQueryCount();
        $elapsedMs = $elapsedMs !== null ? round($elapsedMs, 2) : null;

        $queryWithinBudget = $queryCount <= $queryBudget;
        $elapsedWithinBudget = $elapsedMs === null || $elapsedMs <= $elapsedBudgetMs;
        $status = ($queryWithinBudget && $elapsedWithinBudget && $heavyListsLimited) ? 'ready' : 'attention';
        $recommendations = [];
        if (!$queryWithinBudget) {
            $recommendations[] = 'Review command-center widgets that can be lazy-loaded or moved to detail pages.';
        }
        if (!$elapsedWithinBudget) {
            $recommendations[] = 'Profile slow dashboard widgets before adding more command-center sections.';
        }
        if (!$heavyListsLimited) {
            $recommendations[] = 'Cap heavy detail lists and keep broad summaries count-based.';
        }

        return [
            'status' => $status,
            'query_count' => $queryCount,
            'query_budget' => $queryBudget,
            'elapsed_ms' => $elapsedMs,
            'elapsed_budget_ms' => $elapsedBudgetMs,
            'sections_rendered' => $sectionCount,
            'count_metrics' => $countMetricCount,
            'direct_summary_counts' => true,
            'heavy_detail_lists_limited' => $heavyListsLimited,
            'dashboard_detail_cap' => 6,
            'integration_detail_limit' => (int) ($integrationPerformance['detail_limit'] ?? 40),
            'crm_lifecycle_detail_limit' => (int) ($crmPerformance['detail_limit'] ?? 8),
            'list_limits' => $listLimits,
            'cache_layers' => [
                'database_table_exists' => true,
                'database_column_exists' => true,
                'dashboard_summary_reuse' => true,
                'dashboard_summary_cache' => Database::tableExists('marketing_dashboard_summary_cache'),
                'external_api_calls' => false,
            ],
            'cache_status' => 'direct',
            'cache_ttl_seconds' => 0,
            'manual_first_boundary' => [
                'external_publish' => false,
                'external_send' => false,
                'external_social_api' => false,
                'external_email_api' => false,
                'external_ad_api' => false,
                'external_seo_api' => false,
            ],
            'recommendations' => $recommendations,
            'generated_at' => date('c'),
        ];
    }

    public function getMarketingCommandFlowSummary(?array $onboardingStatus = null, ?array $counts = null): array
    {
        $onboardingStatus = $onboardingStatus ?? $this->getMarketingOnboardingStatus();
        $counts = $counts ?? [];
        $setupScore = (int) ($onboardingStatus['score'] ?? 0);
        $contentTotal = $this->countContent("status <> 'archived'");
        $briefCount = Database::tableExists('marketing_campaign_briefs') ? $this->countRows('marketing_campaign_briefs', "status <> 'archived'") : 0;
        $segmentCount = Database::tableExists('marketing_audience_segments') ? $this->countRows('marketing_audience_segments', "status <> 'archived'") : 0;
        $landingCount = Database::tableExists('marketing_landing_pages') ? $this->countRows('marketing_landing_pages', "status <> 'archived'") : 0;
        $launchChecklistOpen = (int) ($counts['launch_checklists_open'] ?? (Database::tableExists('marketing_campaign_launch_checklists') ? $this->countRows('marketing_campaign_launch_checklists', "status IN ('draft','ready','blocked')") : 0));
        $launchChecklistReady = (int) ($counts['launch_checklists_ready'] ?? 0);
        $launchChecklistBlocked = (int) ($counts['launch_checklists_blocked'] ?? 0);
        $execution = Database::tableExists('marketing_execution_queue') ? $this->getExecutionControlCenterSummary() : ['counts' => []];
        $executionCounts = (array) ($execution['counts'] ?? []);
        $conversionSignalCount = (int) ($counts['conversion_events'] ?? 0) + (int) ($counts['lead_handoffs_open'] ?? 0) + (int) ($counts['influenced_deals'] ?? 0);

        $stageStatus = static function (int $score): string {
            if ($score >= 80) {
                return 'ready';
            }
            if ($score >= 35) {
                return 'attention';
            }

            return 'missing';
        };
        $stage = static fn(string $key, string $label, int $score, string $metric, string $href): array => [
            'key' => $key,
            'label' => $label,
            'score' => max(0, min(100, $score)),
            'status' => $stageStatus($score),
            'metric' => $metric,
            'href' => $href,
        ];

        $strategyScore = min(100, ($briefCount > 0 ? 35 : 0) + ($segmentCount > 0 ? 30 : 0) + ((int) ($counts['active_campaigns'] ?? 0) > 0 ? 20 : 0) + ($landingCount > 0 ? 15 : 0));
        $contentScore = min(100, ($contentTotal > 0 ? 45 : 0) + ((int) ($counts['in_review'] ?? 0) > 0 ? 10 : 0) + ((int) ($counts['scheduled'] ?? 0) > 0 ? 20 : 0) + ((int) ($counts['channel_exports_ready'] ?? 0) > 0 ? 25 : 0));
        $launchScore = min(100, ($launchChecklistReady > 0 ? 55 : 0) + ((int) ($counts['launch_reviews_ready'] ?? 0) > 0 ? 25 : 0) + ((int) ($counts['launch_control_ready'] ?? 0) > 0 ? 20 : 0));
        $executionScore = min(100, ((int) ($executionCounts['ready_to_execute'] ?? 0) > 0 ? 45 : 0) + ((int) ($executionCounts['manual_exports'] ?? 0) > 0 ? 30 : 0) + ((int) ($executionCounts['blocked'] ?? 0) === 0 ? 25 : 0));
        $measureScore = min(100, ($conversionSignalCount > 0 ? 40 : 0) + ((int) ($counts['utm_links'] ?? 0) > 0 ? 30 : 0) + ((int) ($counts['conversion_goals_active'] ?? 0) > 0 ? 30 : 0));

        $nextActions = [];
        $addAction = static function (array &$actions, string $label, string $href, string $reason, string $priority = 'normal'): void {
            $actions[] = [
                'label' => $label,
                'href' => $href,
                'reason' => $reason,
                'priority' => $priority,
            ];
        };

        if ($setupScore < 80) {
            $addAction($nextActions, 'Complete Marketing Setup', 'marketing_onboarding.php', 'Brand, persona, offer, or starter context is still incomplete.', 'high');
        }
        if ((int) ($counts['active_campaigns'] ?? 0) < 1) {
            $addAction($nextActions, 'Create Or Open Campaign', 'campaigns.php', 'Campaign automation is the anchor for launch reporting and attribution.', 'high');
        }
        if ($briefCount < 1) {
            $addAction($nextActions, 'Draft Campaign Brief', 'marketing_brief_edit.php', 'A brief gives content, landing pages, audience, and launch checks a shared strategy.', 'high');
        }
        if ($segmentCount < 1) {
            $addAction($nextActions, 'Define Audience Segment', 'marketing_segments.php', 'Launches need a CRM-derived audience before manual email or channel export planning.', 'normal');
        }
        if ($contentTotal < 1) {
            $addAction($nextActions, 'Create First Content Item', 'marketing_content_edit.php', 'Content Studio is still empty for this workspace.', 'normal');
        }
        if ($launchChecklistOpen < 1) {
            $addAction($nextActions, 'Run Launch Checklist', 'marketing_launch_checklists.php', 'Use the final checklist to catch missing strategy, media, tracking, exports, and connector readiness.', 'high');
        } elseif ($launchChecklistBlocked > 0) {
            $addAction($nextActions, 'Resolve Blocked Launch Checklist', 'marketing_launch_checklists.php?status=blocked', 'At least one launch is blocked by missing required checks.', 'high');
        }
        if ((int) ($executionCounts['blocked'] ?? 0) > 0) {
            $addAction($nextActions, 'Clear Execution Blockers', 'marketing_execution.php', 'Execution Center has blocked manual export or dry-run work.', 'high');
        }
        if ((int) ($counts['utm_links'] ?? 0) < 1) {
            $addAction($nextActions, 'Create UTM Tracking', 'marketing_utm_links.php', 'Tracking links are needed before performance and attribution can be trusted.', 'normal');
        }
        if ($nextActions === []) {
            $addAction($nextActions, 'Review Performance Snapshot', 'marketing_performance.php', 'The main launch workflow is covered; review conversion, handoff, and ROI signals.', 'normal');
        }

        return [
            'setup_score' => $setupScore,
            'stage_average' => (int) round(($setupScore + $strategyScore + $contentScore + $launchScore + $executionScore + $measureScore) / 6),
            'stages' => [
                $stage('setup', 'Setup', $setupScore, $setupScore . '% ready', 'marketing_onboarding.php'),
                $stage('strategy', 'Strategy', $strategyScore, $briefCount . ' briefs, ' . $segmentCount . ' segments', 'marketing_campaign_workspace.php'),
                $stage('content', 'Content', $contentScore, $contentTotal . ' content items', 'marketing_content.php'),
                $stage('launch', 'Launch', $launchScore, $launchChecklistReady . ' ready, ' . $launchChecklistBlocked . ' blocked', 'marketing_launch_checklists.php'),
                $stage('execution', 'Execution', $executionScore, ((int) ($executionCounts['ready_to_execute'] ?? 0)) . ' ready, ' . ((int) ($executionCounts['blocked'] ?? 0)) . ' blocked', 'marketing_execution.php'),
                $stage('measure', 'Measure', $measureScore, $conversionSignalCount . ' conversion signals', 'marketing_performance.php'),
            ],
            'next_actions' => array_slice($nextActions, 0, 6),
        ];
    }

    public function getMarketingNextBestActions(?int $userId = null, int $limit = 8, array $sources = []): array
    {
        $this->assertMarketingPermission('marketing.read');
        $limit = min(max($limit, 1), 25);
        $userId = $userId ?? $this->currentUserId();
        $actions = [];
        $seen = [];
        $priorityRank = ['high' => 3, 'normal' => 2, 'medium' => 2, 'low' => 1];
        $normalizePriority = static function (mixed $priority): string {
            $priority = strtolower(trim((string) $priority));
            return in_array($priority, ['high', 'normal', 'medium', 'low'], true) ? $priority : 'normal';
        };
        $addAction = static function (
            array &$actions,
            array &$seen,
            array $input,
            string $source,
            string $category,
            string $defaultHref,
            string $defaultPriority
        ) use ($normalizePriority): void {
            $label = trim((string) ($input['label'] ?? $input['title'] ?? $input['next_action'] ?? 'Review marketing action'));
            $href = trim((string) ($input['href'] ?? ''));
            if ($href === '' && !empty($input['id']) && $defaultHref !== '') {
                $href = str_ends_with($defaultHref, '=') ? $defaultHref . (int) $input['id'] : $defaultHref;
            }
            if ($href === '') {
                $href = 'marketing.php';
            }
            $key = strtolower($label . '|' . $href);
            if ($label === '' || isset($seen[$key])) {
                return;
            }
            $seen[$key] = true;
            $reason = trim((string) ($input['reason'] ?? $input['message'] ?? $input['next_action'] ?? $input['description'] ?? 'Review this marketing workflow step.'));
            $actions[] = [
                'label' => $label,
                'href' => $href,
                'reason' => $reason,
                'priority' => $normalizePriority($input['priority'] ?? $defaultPriority),
                'source' => $source,
                'category' => $category,
            ];
        };

        $commandFlow = (array) ($sources['command_flow'] ?? $this->getMarketingCommandFlowSummary());
        foreach ((array) ($commandFlow['next_actions'] ?? []) as $action) {
            $addAction($actions, $seen, (array) $action, 'Command Flow', 'operating_flow', 'marketing.php', 'high');
        }

        $taskHub = (array) ($sources['task_hub'] ?? (Database::tableExists('marketing_task_hub_preferences') ? $this->getMarketingTaskHub($userId) : []));
        foreach ((array) ($taskHub['suggested_actions'] ?? []) as $action) {
            $addAction($actions, $seen, (array) $action, 'Task Hub', 'operator_queue', 'marketing_task_hub.php', 'normal');
        }

        $guided = (array) ($sources['guided_workflows'] ?? (Database::tableExists('marketing_guided_workflows') ? $this->getGuidedMarketingWorkflowSummary() : []));
        foreach ((array) ($guided['next_actions'] ?? []) as $action) {
            $addAction($actions, $seen, (array) $action, 'Guided Workflow', 'workflow', 'marketing_guided_workflows.php', 'normal');
        }

        $production = (array) ($sources['production'] ?? $this->getContentProductionSummary(($userId ?? 0) > 0 ? (int) $userId : null));
        foreach ((array) ($production['next_actions'] ?? []) as $action) {
            $input = (array) $action;
            if (empty($input['label']) && !empty($input['next_action'])) {
                $input['label'] = (string) $input['next_action'];
            }
            if (empty($input['reason']) && !empty($input['title'])) {
                $input['reason'] = 'Content item: ' . (string) $input['title'];
            }
            $addAction($actions, $seen, $input, 'Production', 'content_production', 'marketing_content_view.php?id=', 'medium');
        }

        $guidedRecommendations = (array) ($sources['guided_recommendations'] ?? $this->getMarketingGuidedRecommendations($userId, 8));
        foreach ((array) ($guidedRecommendations['recommendations'] ?? []) as $recommendation) {
            $addAction($actions, $seen, (array) $recommendation, 'Guided Recommendation', 'guided_recommendation', 'marketing.php', 'high');
        }

        usort($actions, static function (array $left, array $right) use ($priorityRank): int {
            $leftRank = $priorityRank[(string) ($left['priority'] ?? 'normal')] ?? 2;
            $rightRank = $priorityRank[(string) ($right['priority'] ?? 'normal')] ?? 2;
            if ($leftRank !== $rightRank) {
                return $rightRank <=> $leftRank;
            }

            return strcmp((string) ($left['source'] ?? ''), (string) ($right['source'] ?? ''));
        });
        $actions = array_slice($actions, 0, $limit);
        $counts = ['high' => 0, 'normal' => 0, 'medium' => 0, 'low' => 0, 'total' => count($actions)];
        foreach ($actions as $action) {
            $priority = (string) ($action['priority'] ?? 'normal');
            $counts[$priority] = (int) ($counts[$priority] ?? 0) + 1;
        }

        return [
            'actions' => $actions,
            'counts' => $counts,
            'guardrails' => [
                'Recommendations use existing CRM and Marketing records.',
                'Actions stay manual-first and do not publish, send, or call external channel APIs.',
                'Use page permissions to decide whether a user can act after opening the recommendation.',
            ],
        ];
    }

