            'distribution' => $this->marketingWorkspaceRecordCount('marketing_distribution_posts', "status NOT IN ('archived')"),
            'channel_exports' => $this->marketingWorkspaceRecordCount('marketing_channel_export_bundles', $this->workflowActiveCondition('marketing_channel_export_bundles')),
            'utm_links' => $this->marketingWorkspaceRecordCount('marketing_utm_links'),
            'analytics' => $this->marketingWorkspaceRecordCount('marketing_analytics_snapshots'),
            'tracking_events' => $this->marketingWorkspaceRecordCount('marketing_tracking_events'),
            'handoffs' => $this->marketingWorkspaceRecordCount('marketing_lead_handoffs'),
        ];

        $actions = [];
        $advancedActions = [];
        $seen = [];
        $advancedSeen = [];
        $addAction = static function (
            array &$actions,
            array &$seen,
            string $key,
            string $label,
            string $href,
            string $reason,
            string $priority = 'normal',
            string $source = 'Workflow Clarity'
        ): void {
            $key = strtolower($key . '|' . $href);
            if (isset($seen[$key])) {
                return;
            }
            $seen[$key] = true;
            $priority = in_array($priority, ['high', 'normal', 'medium', 'low'], true) ? $priority : 'normal';
            $actions[] = [
                'label' => $label,
                'href' => $href,
                'reason' => $reason,
