            return in_array($page, [
                'marketing.php',
                'marketing_onboarding.php',
                'marketing_segments.php',
                'marketing_segment_edit.php',
                'marketing_segment_view.php',
                'marketing_briefs.php',
                'marketing_brief_edit.php',
