            ],
            'setup' => [
                ['setup', 'Complete Setup', 'marketing_onboarding.php', 'Finish the first missing customer, offer, or proof setup item.', 'high'],
                ['audiences', 'Continue To Audiences', 'marketing_segments.php', 'Use the setup context to choose who the campaign is for.', 'normal'],
                ['campaigns', 'Start Campaign Plan', 'marketing_briefs.php', 'Turn the setup context into one campaign brief.', 'normal'],
            ],
            'audiences' => [
                ['segments', 'Create Or Review Audience', 'marketing_segments.php', 'Pick or create the reusable audience for this campaign.', 'high'],
                ['new_segment', 'Create Audience Segment', 'marketing_segment_edit.php', 'Build the audience rules when no usable segment exists.', 'normal'],
                ['campaigns', 'Use Audience In Campaign', 'marketing_briefs.php', 'Move the selected audience into the campaign plan.', 'normal'],
            ],
            'campaigns' => [
                ['new_brief', 'Create Campaign Brief', 'marketing_brief_edit.php', 'Define objective, audience, offer, and message before content work.', 'high'],
                ['briefs', 'Review Campaign Plans', 'marketing_briefs.php', 'Open the current campaign brief library.', 'normal'],
                ['content', 'Create Campaign Content', 'marketing_content.php', 'Move a ready plan into message and content work.', 'normal'],
            ],
            'content' => [
                ['new_content', 'Create Content Item', 'marketing_content_edit.php', 'Start with a draft that can be reviewed, scheduled, and distributed.', 'high'],
                ['content', 'Open Content Board', 'marketing_content.php', 'Review drafts, blockers, and approved messages.', 'normal'],
                ['landing', 'Prepare Landing Page', 'marketing_landing_pages.php', 'Give the campaign a destination before send/export.', 'normal'],
            ],
            'calendar' => [
                ['content', 'Open Content Studio', 'marketing_content.php', 'Connect milestones to content items and owners.', 'high'],
                ['landing', 'Prepare Landing Page', 'marketing_landing_pages.php', 'Move scheduled content toward a campaign destination.', 'normal'],
                ['distribution', 'Prepare Send / Export', 'marketing_distribution.php', 'Package ready content for manual channels.', 'normal'],
            ],
            'reviews' => [
                ['blocked', 'Resolve Blocked Content', 'marketing_content.php?blocked=1', 'Clear blocked reasons, missing context, media, or approval gaps.', 'high'],
                ['content', 'Open Content Board', 'marketing_content.php', 'Use the primary content board to move the draft forward.', 'normal'],
                ['landing', 'Prepare Landing Page', 'marketing_landing_pages.php', 'Move approved content into the destination step.', 'normal'],
            ],
            'landing' => [
                ['new_landing', 'Create Landing Page', 'marketing_landing_page_edit.php', 'Create one destination for the campaign offer and CTA.', 'high'],
                ['landing', 'Review Landing Pages', 'marketing_landing_pages.php', 'Check destination readiness before packaging channels.', 'normal'],
                ['distribution', 'Prepare Send / Export', 'marketing_distribution.php', 'Move a ready destination into manual channel packaging.', 'normal'],
            ],
            'distribution' => [
                ['variant', 'Create Distribution Variant', 'marketing_distribution.php#distribution-tools', 'Turn approved content into a manual channel package.', 'high'],
                ['board', 'Open Distribution Board', 'marketing_distribution.php', 'Review open, exported, and published-proof packages.', 'normal'],
                ['performance', 'Review Results', 'marketing_performance.php', 'After export or publish proof, learn from results.', 'normal'],
            ],
            'performance' => [
                ['performance', 'Review Results', 'marketing_performance.php', 'Check conversion, revenue-loop, and campaign result signals.', 'high'],
                ['distribution', 'Review Send / Export Evidence', 'marketing_distribution.php', 'Confirm the manual launch package has export or publish proof.', 'normal'],
                ['next_campaign', 'Start Next Campaign', 'marketing_briefs.php', 'Use the lesson to shape the next simple campaign plan.', 'normal'],
