                ['guided_workflows', 'Open Guided Workflows', 'marketing_guided_workflows.php', 'Follow advanced guided workflows when the primary route is not enough.', 'normal'],
                ['campaign_workspace', 'Open Campaign Workspace', 'marketing_campaign_workspace.php', 'Inspect campaign go/no-go evidence across objects.', 'normal'],
            ],
            'setup' => [
                ['brand', 'Define Brand Voice', 'marketing_brand.php', 'Store tone, proof, and CTA defaults.', 'high'],
                ['personas', 'Create Personas', 'marketing_personas.php', 'Keep detailed customer profiles for AI and fit checks.', 'normal'],
                ['context', 'Fill Context Hub', 'marketing_context.php', 'Manage offers, proof, compliance notes, and CTAs.', 'normal'],
            ],
            'audiences' => [
                ['personas', 'Open Personas', 'marketing_personas.php', 'Review detailed buyer/customer profiles.', 'normal'],
                ['activation', 'Open Audience Activation', 'marketing_audience_activation.php', 'Check whether the audience can be activated safely.', 'normal'],
