                ['playbooks', 'Open Playbooks', 'marketing_playbooks.php', 'Use repeatable campaign kits.', 'normal'],
                ['launch_checks', 'Open Launch Checklists', 'marketing_launch_checklists.php', 'Run deeper release gates when needed.', 'normal'],
            ],
            'content' => [
                ['reviews', 'Open Reviews', 'marketing_reviews.php', 'Move review-ready content through approvals.', 'normal'],
                ['calendar', 'Open Calendar', 'marketing_calendar.php', 'Schedule content and campaign milestones.', 'normal'],
                ['creative', 'Open Creative Production', 'marketing_creative.php', 'Manage AI visual and creative queues.', 'normal'],
                ['quality', 'Run Quality Checks', 'marketing_quality.php', 'Use brand, persona, compliance, CTA, and SEO checks.', 'normal'],
            ],
            'landing' => [
                ['assets', 'Open Assets', 'marketing_assets.php', 'Manage hero, social, CTA, proof, and gallery media.', 'normal'],
                ['seo', 'Open SEO Topics', 'marketing_seo.php', 'Connect landing pages to search topics.', 'normal'],
                ['launch_checks', 'Open Launch Checklists', 'marketing_launch_checklists.php', 'Move approved pages into launch review.', 'normal'],
            ],
            'distribution' => [
                ['channel_export', 'Build Channel Export', 'marketing_channel_exports.php', 'Package copy, media, captions, links, and checklists.', 'normal'],
                ['utm', 'Create UTM Links', 'marketing_utm_links.php', 'Make manual distribution trackable.', 'normal'],
                ['email_runs', 'Prepare Email Runs', 'marketing_email_runs.php', 'Prepare controlled email run evidence.', 'normal'],
                ['operator_packs', 'Open Operator Packs', 'marketing_operator_export_packs.php', 'Prepare safe manual export packs.', 'normal'],
            ],
            'performance' => [
                ['weekly', 'Open Weekly Report', 'marketing_weekly_report.php', 'Summarize current production, conversion, and review evidence.', 'normal'],
                ['monthly', 'Open Monthly Report', 'marketing_monthly_report.php', 'Review the longer performance cycle.', 'normal'],
                ['handoffs', 'Check Lead Handoffs', 'marketing_handoffs.php', 'Keep marketing qualified outcomes visible to Sales.', 'normal'],
                ['utm', 'Open UTM Links', 'marketing_utm_links.php', 'Inspect campaign tracking links.', 'normal'],
            ],
        ];
        foreach ($surfaceActions[$surface] ?? $surfaceActions['command'] as $action) {
            $addAction($actions, $seen, ...$action);
        }
        foreach ($surfaceAdvancedActions[$surface] ?? $surfaceAdvancedActions['command'] as $action) {
            $addAction($advancedActions, $advancedSeen, ...$action);
        }

        $nextBest = $this->getMarketingNextBestActions($userId, $limit);
        foreach (array_slice((array) ($nextBest['actions'] ?? []), 0, 4) as $action) {
            $href = (string) ($action['href'] ?? 'marketing.php');
            $targetActions = $isPrimaryWorkflowHref($href) ? $actions : $advancedActions;
            $targetSeen = $isPrimaryWorkflowHref($href) ? $seen : $advancedSeen;
            $addAction(
                $targetActions,
                $targetSeen,
                (string) ($action['label'] ?? 'next'),
                (string) ($action['label'] ?? 'Review Marketing Action'),
                $href,
                (string) ($action['reason'] ?? 'Review this marketing workflow step.'),
                (string) ($action['priority'] ?? 'normal'),
                (string) ($action['source'] ?? 'Next Best Action')
            );
            if ($isPrimaryWorkflowHref($href)) {
                $actions = $targetActions;
                $seen = $targetSeen;
            } else {
                $advancedActions = $targetActions;
                $advancedSeen = $targetSeen;
            }
        }

        $surfaceScoreInputs = match ($surface) {
            'setup' => [$counts['brand_profiles'], $counts['personas'], $counts['context_items'], $counts['segments']],
            'audiences' => [$counts['segments'], $counts['contacts'] ?? 0, $counts['handoffs'], $counts['campaigns']],
            'campaigns' => [$counts['campaigns'], $counts['briefs'], $counts['segments'], $counts['landing_pages']],
            'content' => [$counts['briefs'], $counts['content_items'], $counts['calendar'], $counts['reviews'] + $counts['approved_content']],
            'landing' => [$counts['briefs'], $counts['content_items'], $counts['landing_pages'], $counts['approved_content']],
            'calendar' => [$counts['content_items'], $counts['calendar'], max(0, 1 - min(1, $counts['overdue_calendar'])), $counts['reviews'] + $counts['approved_content']],
            'reviews' => [$counts['content_items'], $counts['reviews'] + $counts['approved_content'], $counts['calendar'], $counts['distribution']],
            'distribution' => [$counts['approved_content'], $counts['distribution'], $counts['channel_exports'], $counts['utm_links']],
            'performance' => [$counts['distribution'], $counts['analytics'] + $counts['tracking_events'], $counts['handoffs'], $counts['utm_links']],
            default => [$counts['brand_profiles'] + $counts['personas'], $counts['briefs'], $counts['content_items'], $counts['distribution']],
        };
        $present = 0;
        foreach ($surfaceScoreInputs as $value) {
            if ((int) $value > 0) {
                $present++;
            }
        }
        $score = (int) round(($present / max(1, count($surfaceScoreInputs))) * 100);
        $status = $score >= 80 ? 'ready' : ($score >= 45 ? 'attention' : 'blocked');
        $priorityCounts = ['high' => 0, 'normal' => 0, 'medium' => 0, 'low' => 0];
        foreach ($actions as $action) {
            $priority = (string) ($action['priority'] ?? 'normal');
            $priorityCounts[$priority] = (int) ($priorityCounts[$priority] ?? 0) + 1;
        }

        return [
            'surface' => $surface,
            'requested_surface' => $requestedSurface,
            'title' => $definitions[$surface]['title'],
            'subtitle' => $definitions[$surface]['subtitle'],
            'href' => $definitions[$surface]['href'],
            'status' => $status,
            'score' => $score,
            'actions' => array_slice($actions, 0, $limit),
            'advanced_actions' => array_slice($advancedActions, 0, $limit),
            'counts' => $counts,
            'priority_counts' => $priorityCounts,
            'guardrails' => [
                'workspace_scoped' => true,
                'manual_first' => true,
                'external_send' => false,
                'external_publish' => false,
                'external_api_calls' => false,
                'read_only_recommendations' => true,
            ],
            'recommended_product_decision' => 'Keep the first visible action tied to the simplified manual launch path, then place expert routes inside Advanced Marketing Tools.',
            'generated_at' => date('c'),
        ];
    }

    public function getMarketingDecisionEngine(?int $userId = null, int $limit = 10, array $sources = []): array
    {
        $this->assertMarketingPermission('marketing.read');
        $limit = min(max($limit, 1), 25);
        $userId = $userId ?? ($this->currentUserId() ?: null);
        if (($userId ?? 0) > 0) {
            $this->assertWorkspaceUser((int) $userId, $this->workspaceId());
        }

        $campaignRevenueLoop = (array) ($sources['campaign_revenue_loop'] ?? $this->getCampaignRevenueLoopSummary(null, 6));
        $guidedRecommendations = (array) ($sources['guided_recommendations'] ?? $this->getMarketingGuidedRecommendations($userId, 8));
        $decisionCenter = (array) ($sources['decision_center'] ?? (Database::tableExists('marketing_decision_center_items') ? $this->getMarketingDecisionCenter($userId, 8) : []));
        $pageSpeed = (array) ($sources['page_speed_profile'] ?? []);
        $aiWorkspaceBrain = (array) ($sources['ai_workspace_brain'] ?? $this->getMarketingAiWorkspaceBrain($userId));
        $integrationReadiness = (array) ($sources['integration_readiness'] ?? $this->getMarketingIntegrationReadiness(30));
        $automationReadiness = (array) ($sources['automation_readiness'] ?? $this->getMarketingAutomationReadiness($userId));
        $nextBestActions = (array) ($sources['next_best_actions'] ?? $this->getMarketingNextBestActions($userId, 8, [
            'command_flow' => $sources['command_flow'] ?? null,
            'guided_recommendations' => $guidedRecommendations,
        ]));

        $decisions = [];
        $seen = [];
        $addDecision = static function (
            array &$decisions,
            array &$seen,
            string $key,
            string $title,
            string $decisionType,
            string $priority,
            string $category,
            string $source,
            string $href,
            string $recommendedAction,
            string $rationale,
            string $expectedImpact,
            array $evidence = []
        ): void {
            if (isset($seen[$key])) {
                return;
            }
            $seen[$key] = true;
            $priority = in_array($priority, ['urgent', 'high', 'normal', 'low'], true) ? $priority : 'normal';
            $decisions[] = [
                'key' => $key,
                'title' => $title,
                'decision_type' => $decisionType,
                'decision_status' => 'suggested',
                'priority' => $priority,
                'category' => $category,
                'source' => $source,
                'href' => $href,
                'recommended_action' => $recommendedAction,
                'rationale' => $rationale,
                'expected_impact' => $expectedImpact,
                'evidence' => $evidence,
            ];
        };

        $revenueCounts = (array) ($campaignRevenueLoop['counts'] ?? []);
        $revenueScore = (int) ($campaignRevenueLoop['score'] ?? 0);
        if ($revenueScore < 75 || (int) ($revenueCounts['blocked'] ?? 0) > 0) {
            $addDecision(
                $decisions,
                $seen,
                'prioritize_campaign_revenue_loop',
                'Prioritize campaign-to-revenue gaps',
                'campaign_blocker',
                (int) ($revenueCounts['blocked'] ?? 0) > 0 ? 'urgent' : 'high',
                'revenue_loop',
                'Campaign-To-Revenue Loop',
                'marketing_performance.php',
                'Close the first missing revenue-loop lane before adding more campaign surface.',
                'Campaign readiness is ' . $revenueScore . '%, with ' . (int) ($revenueCounts['blocked'] ?? 0) . ' blocked campaign(s).',
                'Keeps Marketing tied to conversion, handoff, and ROI evidence instead of disconnected activity.',
                [
                    'score' => $revenueScore,
                    'counts' => $revenueCounts,
                    'top_actions' => array_slice((array) ($campaignRevenueLoop['next_actions'] ?? []), 0, 3),
                ]
            );
        }

        if ((int) ($aiWorkspaceBrain['score'] ?? 0) < 80) {
            $addDecision(
                $decisions,
                $seen,
                'complete_ai_context_before_generation',
                'Complete AI context before scaling generation',
                'ai_recommendation',
                'high',
                'ai_context',
                'AI Workspace Brain',
                'marketing_assistants.php',
                'Fill the missing brand, persona, offer, proof, SEO, or campaign context before relying on AI outputs.',
                'AI workspace context score is ' . (int) ($aiWorkspaceBrain['score'] ?? 0) . '%.',
                'Improves draft quality, reduces review risk, and keeps AI recommendations explainable.',
                [
                    'score' => (int) ($aiWorkspaceBrain['score'] ?? 0),
                    'missing_context' => array_slice((array) ($aiWorkspaceBrain['missing_context'] ?? []), 0, 6),
                ]
            );
        }

        $integrationCounts = (array) ($integrationReadiness['counts'] ?? []);
        $integrationGaps = (int) ($integrationCounts['system_connections_attention'] ?? 0) + (int) ($integrationCounts['system_connections_missing'] ?? 0);
        if ($integrationGaps > 0) {
            $addDecision(
                $decisions,
                $seen,
                'resolve_marketing_crm_integration_gaps',
                'Resolve CRM integration gaps',
                'integration_risk',
                $integrationGaps > 3 ? 'high' : 'normal',
                'integration',
                'Integration Readiness',
                'marketing_admin.php',
                'Review forms, campaigns, attribution, handoffs, tasks, and channel export readiness before launch.',
                $integrationGaps . ' Marketing-to-CRM connection(s) need attention.',
                'Prevents Marketing from becoming a standalone content island outside the CRM operating model.',
                [
                    'counts' => $integrationCounts,
                    'recommendations' => array_slice((array) ($integrationReadiness['recommendations'] ?? []), 0, 4),
                ]
            );
        }

        $automationCounts = (array) ($automationReadiness['counts'] ?? []);
        $automationGaps = (int) ($automationCounts['attention'] ?? 0) + (int) ($automationCounts['missing'] ?? 0);
        if ($automationGaps > 0) {
            $addDecision(
                $decisions,
                $seen,
                'keep_automation_manual_first',
                'Keep automation manual-first until loops are ready',
                'integration_risk',
                'normal',
                'automation',
                'Automation Readiness',
                'marketing_operations.php',
                'Prepare reminder, approval, export, report, and dry-run loops before enabling stronger automation.',
                $automationGaps . ' automation readiness loop(s) need attention.',
                'Supports system independence while preventing accidental sends, posts, or connector side effects.',
                [
                    'counts' => $automationCounts,
                    'loops' => array_slice((array) ($automationReadiness['loops'] ?? []), 0, 6),
                ]
            );
        }

        if (($pageSpeed['status'] ?? 'ready') === 'attention') {
            $addDecision(
                $decisions,
                $seen,
                'protect_command_center_speed',
                'Protect Command Center page speed',
                'custom',
                'normal',
                'performance',
                'Page Speed Profile',
                'marketing_admin.php',
                'Cap or lazy-load the slowest dashboard sections before adding more widgets.',
                'The Marketing dashboard speed profile is in attention status.',
                'Keeps the operator dashboard fast enough for daily use.',
                [
                    'query_count' => (int) ($pageSpeed['query_count'] ?? 0),
                    'elapsed_ms' => $pageSpeed['elapsed_ms'] ?? null,
                    'recommendations' => (array) ($pageSpeed['recommendations'] ?? []),
                ]
            );
        }

        foreach (array_slice((array) ($decisionCenter['saved_decisions'] ?? []), 0, 3) as $savedDecision) {
            $addDecision(
                $decisions,
                $seen,
                'saved_decision_' . (int) ($savedDecision['id'] ?? 0),
                (string) ($savedDecision['title'] ?? 'Open marketing decision'),
                (string) ($savedDecision['decision_type'] ?? 'custom'),
                (string) ($savedDecision['priority'] ?? 'normal'),
                'human_decision',
                'Decision Center',
                'marketing_decisions.php',
                (string) ($savedDecision['recommended_action'] ?? 'Decide, defer, or reject this Marketing choice.'),
                (string) ($savedDecision['rationale'] ?? 'A saved Marketing decision is still open.'),
                (string) ($savedDecision['expected_impact'] ?? 'Keeps important operator choices visible and auditable.'),
                ['decision_id' => (int) ($savedDecision['id'] ?? 0)]
            );
        }

        foreach (array_slice((array) ($guidedRecommendations['recommendations'] ?? []), 0, 4) as $recommendation) {
            $addDecision(
                $decisions,
                $seen,
                'guided_' . (string) ($recommendation['key'] ?? md5((string) ($recommendation['label'] ?? 'guided'))),
                (string) ($recommendation['label'] ?? 'Review guided recommendation'),
                (string) (($recommendation['category'] ?? '') === 'media' ? 'media_readiness' : (($recommendation['category'] ?? '') === 'integration' ? 'integration_risk' : 'custom')),
                (string) ($recommendation['priority'] ?? 'normal'),
                (string) ($recommendation['category'] ?? 'guided'),
                'Guided Recommendations',
                (string) ($recommendation['href'] ?? 'marketing.php'),
                (string) ($recommendation['product_decision'] ?? $recommendation['reason'] ?? 'Review this guided recommendation.'),
                (string) ($recommendation['reason'] ?? 'A guided Marketing recommendation needs attention.'),
                'Turns diagnostics into a visible operator choice without taking action automatically.',
                ['evidence_count' => (int) ($recommendation['evidence_count'] ?? 0)]
            );
        }

        foreach (array_slice((array) ($nextBestActions['actions'] ?? []), 0, 4) as $action) {
            $addDecision(
                $decisions,
                $seen,
                'next_best_' . md5((string) ($action['label'] ?? '') . '|' . (string) ($action['href'] ?? '')),
                (string) ($action['label'] ?? 'Review next best action'),
                'custom',
                (string) ($action['priority'] ?? 'normal'),
                (string) ($action['category'] ?? 'operator_action'),
                (string) ($action['source'] ?? 'Next Best Action'),
                (string) ($action['href'] ?? 'marketing.php'),
                'Open the recommended surface and make the next manual operator decision.',
                (string) ($action['reason'] ?? 'A next-best action is available.'),
                'Keeps daily operator work focused on the highest-impact manual step.',
                ['source' => (string) ($action['source'] ?? '')]
            );
        }

        if ($decisions === []) {
            $addDecision(
                $decisions,
                $seen,
                'review_performance_learning_loop',
                'Review performance learning loop',
                'custom',
                'low',
                'performance',
                'Decision Engine',
                'marketing_performance.php',
                'Shift attention from setup to learning: review performance, ROI, attribution, and experiments.',
                'No blocking strategy, context, integration, automation, or speed decisions are open.',
                'Moves the team from setup completion into continuous optimization.',
                []
            );
        }

        $priorityRank = ['urgent' => 4, 'high' => 3, 'normal' => 2, 'medium' => 2, 'low' => 1];
        usort($decisions, static function (array $left, array $right) use ($priorityRank): int {
            $leftRank = $priorityRank[(string) ($left['priority'] ?? 'normal')] ?? 2;
            $rightRank = $priorityRank[(string) ($right['priority'] ?? 'normal')] ?? 2;
            if ($leftRank !== $rightRank) {
                return $rightRank <=> $leftRank;
            }

            return strcmp((string) ($left['title'] ?? ''), (string) ($right['title'] ?? ''));
        });
        $decisions = array_slice($decisions, 0, $limit);
        $counts = ['urgent' => 0, 'high' => 0, 'normal' => 0, 'low' => 0, 'total' => count($decisions)];
        $categories = [];
        foreach ($decisions as $decision) {
            $priority = (string) ($decision['priority'] ?? 'normal');
            $counts[$priority] = (int) ($counts[$priority] ?? 0) + 1;
            $category = (string) ($decision['category'] ?? 'custom');
            $categories[$category] = (int) ($categories[$category] ?? 0) + 1;
        }
        $status = match (true) {
            $counts['urgent'] > 0 => 'urgent',
            $counts['high'] > 0 => 'needs_decision',
            $counts['total'] > 0 => 'ready_with_recommendations',
            default => 'ready',
        };

        return [
            'status' => $status,
            'counts' => $counts,
            'categories' => $categories,
            'decisions' => $decisions,
            'top_decision' => $decisions[0] ?? null,
            'source_scores' => [
                'campaign_revenue_loop' => (int) ($campaignRevenueLoop['score'] ?? 0),
                'ai_workspace_brain' => (int) ($aiWorkspaceBrain['score'] ?? 0),
                'integration_readiness' => (int) ($integrationReadiness['score'] ?? 0),
                'automation_status' => (string) ($automationReadiness['status'] ?? 'unknown'),
                'page_speed_status' => (string) ($pageSpeed['status'] ?? 'unknown'),
            ],
            'guardrails' => [
                'workspace_scoped' => true,
                'manual_first' => true,
                'records_created' => false,
                'external_publish' => false,
                'external_send' => false,
                'external_api_calls' => false,
                'operator_decision_required' => true,
            ],
            'recommended_product_decision' => 'Use the Decision Engine as the ranking layer above Marketing diagnostics: it recommends what humans should decide next, but never sends, publishes, or mutates records by itself.',
            'generated_at' => date('c'),
        ];
    }

    public function getMarketingSystemMap(?array $dashboardSummary = null, ?array $onboardingStatus = null): array
    {
        $this->assertMarketingPermission('marketing.read');
        $summary = $dashboardSummary ?? $this->getCachedDashboardSummary($onboardingStatus, 60);
        $counts = (array) ($summary['counts'] ?? []);
        $onboardingStatus = $onboardingStatus ?? $this->getMarketingOnboardingStatus();
        $scoreForStatus = static function (int $score): string {
            if ($score >= 75) {
                return 'ready';
            }
            if ($score >= 35) {
                return 'attention';
            }

            return 'missing';
        };
        $boundedScore = static fn(int|float $score): int => max(0, min(100, (int) round((float) $score)));
        $presenceScore = static function (array $values) use ($boundedScore): int {
            if ($values === []) {
                return 0;
            }
            $present = 0;
            foreach ($values as $value) {
                if ((int) $value > 0) {
                    $present++;
                }
            }

            return $boundedScore(($present / max(1, count($values))) * 100);
        };
        $metric = static fn(string $label, string|int|float|null $value): array => [
            'label' => $label,
            'value' => $value === null || $value === '' ? 'None' : (string) $value,
        ];
        $stage = static function (
            string $key,
            string $label,
            string $description,
            string $href,
            int $score,
            array $metrics,
            array $tools,
            array $nextActions
        ) use ($scoreForStatus): array {
            return [
                'key' => $key,
                'label' => $label,
                'description' => $description,
                'href' => $href,
                'score' => $score,
                'status' => $scoreForStatus($score),
                'metrics' => $metrics,
                'tools' => $tools,
                'next_actions' => $nextActions,
            ];
        };

        $setupScore = $boundedScore((int) ($onboardingStatus['readiness_score'] ?? $onboardingStatus['score'] ?? 0));
        $aiBrain = (array) ($summary['ai_workspace_brain'] ?? []);
        $integration = (array) ($summary['integration_readiness'] ?? []);
        $automation = (array) ($summary['automation_readiness'] ?? []);
        $pageSpeed = (array) ($summary['page_speed_profile'] ?? []);
        $decisionEngine = (array) ($summary['decision_engine'] ?? []);
        $revenueLoop = (array) ($summary['campaign_revenue_loop'] ?? []);

        $strategyScore = $presenceScore([
            $counts['active_campaigns'] ?? 0,
            $counts['briefs_in_progress'] ?? 0,
            $counts['audience_activations_ready'] ?? $counts['audience_activations_active'] ?? 0,
            $counts['running_experiments'] ?? 0,
        ]);
        $contentScore = $presenceScore([
            $counts['drafts'] ?? 0,
            $counts['in_review'] ?? 0,
            $counts['calendar_this_week'] ?? 0,
            $counts['quality_checks'] ?? 0,
        ]);
        $creativeReadiness = (array) ($summary['creative_readiness'] ?? []);
        $mediaScore = $boundedScore(isset($creativeReadiness['score']) ? (int) $creativeReadiness['score'] : $presenceScore([
            $counts['asset_requests_ready'] ?? 0,
            $counts['media_production_open'] ?? 0,
            $counts['media_missing_alt_text'] ?? 0,
        ]));
        if ((int) ($counts['media_missing_alt_text'] ?? 0) > 0 || (int) ($counts['media_blocked'] ?? 0) > 0) {
            $mediaScore = min($mediaScore, 65);
        }
        $distributionScore = $presenceScore([
            $counts['distribution_queue'] ?? 0,
            $counts['channel_exports_ready'] ?? 0,
            $counts['email_runs_ready'] ?? 0,
            $counts['utm_links'] ?? 0,
        ]);
        $revenueScore = $boundedScore((int) ($revenueLoop['score'] ?? 0));
        $operateScore = $boundedScore(round((
            (int) ($integration['score'] ?? 0)
            + ((string) ($automation['status'] ?? '') === 'ready' ? 100 : 55)
            + ((string) ($pageSpeed['status'] ?? '') === 'attention' ? 55 : 100)
        ) / 3));

        $stages = [
            $stage(
                'setup',
                'Setup',
                'Workspace readiness, starter data, permissions, and first-run orientation.',
                'marketing_onboarding.php',
                $setupScore,
                [
                    $metric('Readiness', $setupScore . '%'),
                    $metric('Missing areas', count((array) ($onboardingStatus['missing_areas'] ?? $onboardingStatus['missing'] ?? []))),
                    $metric('Starter pack', !empty($onboardingStatus['starter_pack']['created_at'] ?? null) ? 'Created' : 'Optional'),
                ],
                ['Marketing Setup', 'System Health', 'Starter Pack'],
                ['Complete missing setup areas', 'Create starter data only when needed'],
            ),
            $stage(
                'context',
                'Context',
                'Brand, personas, offers, proof, compliance, SEO, and AI grounding.',
                'marketing_context.php',
                $boundedScore((int) ($aiBrain['score'] ?? 0)),
                [
                    $metric('AI context score', (int) ($aiBrain['score'] ?? 0) . '%'),
                    $metric('Missing context', count((array) ($aiBrain['missing_context'] ?? []))),
                    $metric('Guided recommendations', count((array) ($summary['guided_recommendations']['recommendations'] ?? []))),
                ],
                ['Context Hub', 'Brand Library', 'Personas', 'SEO Topics', 'Assistants'],
                ['Fill brand and persona gaps', 'Snapshot AI context before major generation'],
            ),
            $stage(
                'strategy',
                'Strategy',
                'Campaign briefs, playbooks, audiences, journeys, offers, and launch direction.',
                'marketing_briefs.php',
                $strategyScore,
                [
                    $metric('Active campaigns', $counts['active_campaigns'] ?? 0),
                    $metric('Briefs in progress', $counts['briefs_in_progress'] ?? 0),
                    $metric('Audience activations ready', $counts['audience_activations_ready'] ?? 0),
                ],
                ['Campaign Workspace', 'Briefs', 'Segments', 'Journeys', 'Playbooks'],
                ['Connect every active campaign to a brief and audience', 'Use persona-offer fit before content production'],
            ),
            $stage(
                'content',
                'Content',
                'Content Studio, editorial calendar, reviews, launch checks, and quality controls.',
                'marketing_content.php',
                $contentScore,
                [
                    $metric('Drafts', $counts['drafts'] ?? 0),
                    $metric('In review', $counts['in_review'] ?? 0),
                    $metric('Calendar this week', $counts['calendar_this_week'] ?? 0),
                    $metric('Quality risk items', $counts['quality_risk_items'] ?? 0),
                ],
                ['Content Studio', 'Calendar', 'Reviews', 'Quality Checks', 'Launch Checklists'],
                ['Move drafts into review queues', 'Resolve quality risk before distribution'],
            ),
            $stage(
                'media',
                'Media',
                'Assets, media rights, creative production, channel visuals, and accessibility.',
                'marketing_assets.php',
                $mediaScore,
                [
                    $metric('Missing alt text', $counts['media_missing_alt_text'] ?? 0),
                    $metric('Blocked media', $counts['media_blocked'] ?? 0),
                    $metric('Open production work', $counts['media_production_open'] ?? 0),
                ],
                ['Assets', 'Creative Production', 'Channel Exports'],
                ['Clear media rights and alt-text warnings', 'Attach approved visuals before exports'],
            ),
            $stage(
                'distribution',
                'Distribution',
                'Manual exports, email runs, UTM links, channel bundles, and execution evidence.',
                'marketing_distribution.php',
                $distributionScore,
                [
                    $metric('Distribution queue', $counts['distribution_queue'] ?? 0),
                    $metric('Channel exports ready', $counts['channel_exports_ready'] ?? 0),
                    $metric('Email runs ready', $counts['email_runs_ready'] ?? 0),
                    $metric('UTM links', $counts['utm_links'] ?? 0),
                ],
                ['Distribution', 'Email Runs', 'Channel Exports', 'UTM Links', 'Execution Center'],
                ['Package approved content for manual channels', 'Keep UTM and export evidence attached'],
            ),
            $stage(
                'revenue',
                'Revenue',
                'Conversion goals, lead handoffs, attribution, ROI, experiments, and performance learning.',
                'marketing_performance.php',
                $revenueScore,
                [
                    $metric('Revenue loop', $revenueScore . '%'),
                    $metric('Lead handoffs open', $counts['lead_handoffs_open'] ?? 0),
                    $metric('Attribution touchpoints', $counts['attribution_touchpoints'] ?? 0),
                    $metric('Conversion goals active', $counts['conversion_goals_active'] ?? 0),
                ],
                ['Performance', 'Lead Handoffs', 'Weekly Report', 'Monthly Report'],
                ['Close campaign-to-revenue gaps', 'Review attribution confidence before budget decisions'],
            ),
            $stage(
                'operate',
                'Operate',
                'Automation readiness, CRM integration, page speed, admin diagnostics, and manual-first guardrails.',
                'marketing_admin.php',
                $operateScore,
                [
                    $metric('Integration score', (int) ($integration['score'] ?? 0) . '%'),
                    $metric('Automation', $automation['status'] ?? 'unknown'),
                    $metric('Page speed', $pageSpeed['status'] ?? 'ready'),
                    $metric('Open decisions', $decisionEngine['counts']['total'] ?? 0),
                ],
                ['Operations', 'Admin Diagnostics', 'Decision Center', 'Action Router'],
                ['Resolve integration gaps before stronger automation', 'Keep dashboards capped and cached'],
            ),
        ];

        $stageCounts = ['ready' => 0, 'attention' => 0, 'missing' => 0, 'total' => count($stages)];
        $totalScore = 0;
        foreach ($stages as $stageItem) {
            $stageCounts[$stageItem['status']]++;
            $totalScore += (int) ($stageItem['score'] ?? 0);
        }
        $averageScore = $boundedScore($totalScore / max(1, count($stages)));
        $status = match (true) {
            $stageCounts['missing'] > 0 => 'missing_foundation',
            $stageCounts['attention'] > 0 => 'needs_attention',
            default => 'ready',
        };

        return [
            'status' => $status,
            'average_score' => $averageScore,
            'counts' => $stageCounts,
            'stages' => $stages,
            'top_stage' => $stages[0] ?? null,
            'lowest_stage' => array_reduce($stages, static function (?array $carry, array $item): array {
                if ($carry === null || (int) ($item['score'] ?? 0) < (int) ($carry['score'] ?? 0)) {
                    return $item;
                }

                return $carry;
            }),
            'next_decision' => $decisionEngine['top_decision'] ?? null,
            'guardrails' => [
                'workspace_scoped' => true,
                'manual_first' => true,
                'external_publish' => false,
                'external_send' => false,
                'external_api_calls' => false,
                'page_speed_aware' => true,
                'integrates_crm_surfaces' => true,
            ],
            'recommended_product_decision' => 'Use the System Map as the orientation layer for Marketing: every page should show where work belongs, what evidence is missing, and the safest next manual action.',
            'generated_at' => date('c'),
        ];
    }

    public function getMarketingWorkflowReadiness(?array $dashboardSummary = null, ?array $onboardingStatus = null): array
    {
        $this->assertMarketingPermission('marketing.read');
        $summary = $dashboardSummary ?? [];
        $onboardingStatus = $onboardingStatus ?? $this->getMarketingOnboardingStatus();
        $counts = (array) ($summary['counts'] ?? []);
        $boundedScore = static fn(int|float $score): int => max(0, min(100, (int) round((float) $score)));
        $statusForScore = static fn(int $score): string => $score >= 80 ? 'ready' : ($score >= 50 ? 'attention' : 'blocked');
        $presentScore = static function (array $values) use ($boundedScore): int {
            if ($values === []) {
                return 0;
            }
            $present = 0;
            foreach ($values as $value) {
                if ((int) $value > 0) {
                    $present++;
                }
            }

            return $boundedScore(($present / max(1, count($values))) * 100);
        };
        $tableCount = function (string $table, string $where = 'id > 0') use (&$counts): int {
            $countKey = preg_replace('/^marketing_/', '', $table) ?: $table;
            if (isset($counts[$countKey])) {
                return (int) $counts[$countKey];
            }
            if (!Database::tableExists($table)) {
                return 0;
            }

            return $this->countRows($table, $where);
        };
        $metric = static fn(string $label, string|int|float|null $value): array => [
            'label' => $label,
            'value' => $value === null || $value === '' ? 'None' : (string) $value,
        ];
        $lane = static function (
            string $key,
            string $label,
            string $href,
            int $score,
            array $metrics,
            array $missing,
            array $nextActions
        ) use ($statusForScore): array {
            return [
                'key' => $key,
                'label' => $label,
                'href' => $href,
                'score' => $score,
                'status' => $statusForScore($score),
                'metrics' => $metrics,
                'missing' => array_slice(array_values(array_unique(array_filter($missing))), 0, 6),
                'next_actions' => array_slice(array_values(array_unique(array_filter($nextActions))), 0, 5),
            ];
        };

        $recordCounts = [
            'brand_profiles' => $tableCount('marketing_brand_profiles'),
            'personas' => $tableCount('marketing_personas'),
            'context_items' => $tableCount('marketing_context_items'),
            'campaign_briefs' => $tableCount('marketing_campaign_briefs', "status <> 'archived'"),
            'audience_segments' => $tableCount('marketing_audience_segments', "status <> 'archived'"),
            'journeys' => $tableCount('marketing_journeys', "status <> 'archived'"),
            'content_items' => $tableCount('marketing_content_items', "status <> 'archived'"),
            'landing_pages' => $tableCount('marketing_landing_pages', "status <> 'archived'"),
            'media_files' => $tableCount('marketing_media_files'),
            'distribution_posts' => $tableCount('marketing_distribution_posts', "status <> 'archived'"),
            'email_runs' => $tableCount('marketing_email_campaign_runs', "status <> 'archived'"),
            'channel_exports' => $tableCount('marketing_channel_export_bundles', "status <> 'archived'"),
            'utm_links' => $tableCount('marketing_utm_links'),
            'conversion_goals' => $tableCount('marketing_conversion_goals', "status <> 'archived'"),
            'lead_handoffs' => $tableCount('marketing_lead_handoffs', "status <> 'archived'"),
            'analytics_snapshots' => $tableCount('marketing_analytics_snapshots'),
            'planning_queue_items' => $tableCount('marketing_planning_queue_items', "status <> 'archived'"),
            'action_router_items' => $tableCount('marketing_action_router_items', "action_status IN ('suggested','accepted')"),
        ];

        $aiBrain = (array) ($summary['ai_workspace_brain'] ?? $this->getMarketingAiWorkspaceBrain((int) ($_SESSION['user_id'] ?? 0) ?: null));
        $systemMap = (array) ($summary['system_map'] ?? []);
        $integration = (array) ($summary['integration_readiness'] ?? $this->getMarketingIntegrationReadiness(40));
        $automation = (array) ($summary['automation_readiness'] ?? $this->getMarketingAutomationReadiness((int) ($_SESSION['user_id'] ?? 0) ?: null));
        $pageSpeed = (array) ($summary['page_speed_profile'] ?? []);
        $revenueLoop = (array) ($summary['campaign_revenue_loop'] ?? []);
        $onboardingScore = $boundedScore((int) ($onboardingStatus['readiness_score'] ?? $onboardingStatus['score'] ?? 0));
        $contextScore = $boundedScore((int) ($aiBrain['score'] ?? 0));
        $systemScore = $boundedScore((int) ($systemMap['average_score'] ?? 0));
        $revenueScore = $boundedScore((int) ($revenueLoop['score'] ?? 0));

        $lanes = [];
        $lanes[] = $lane(
            'setup_context',
            'Setup To Context',
            'marketing_onboarding.php',
            $boundedScore(($onboardingScore + $contextScore + $presentScore([$recordCounts['brand_profiles'], $recordCounts['personas'], $recordCounts['context_items']])) / 3),
            [
                $metric('Setup score', $onboardingScore . '%'),
                $metric('AI context', $contextScore . '%'),
                $metric('Context records', $recordCounts['brand_profiles'] + $recordCounts['personas'] + $recordCounts['context_items']),
            ],
            [
                $recordCounts['brand_profiles'] < 1 ? 'Add a brand profile' : '',
                $recordCounts['personas'] < 1 ? 'Add at least one persona' : '',
                $recordCounts['context_items'] < 1 ? 'Add offers, proof, CTAs, or compliance context' : '',
            ],
            ['Open Marketing Setup', 'Complete Context Hub', 'Run AI context preflight']
        );
        $lanes[] = $lane(
            'campaign_strategy',
            'Campaign Strategy',
            'marketing_campaign_workspace.php',
            $presentScore([
                $counts['active_campaigns'] ?? 0,
                $recordCounts['campaign_briefs'],
                $recordCounts['audience_segments'],
                $recordCounts['landing_pages'],
            ]),
            [
                $metric('Active campaigns', $counts['active_campaigns'] ?? 0),
                $metric('Briefs', $recordCounts['campaign_briefs']),
                $metric('Segments', $recordCounts['audience_segments']),
                $metric('Landing plans', $recordCounts['landing_pages']),
            ],
            [
                ($counts['active_campaigns'] ?? 0) < 1 ? 'Create or activate a campaign' : '',
                $recordCounts['campaign_briefs'] < 1 ? 'Create a campaign brief' : '',
                $recordCounts['audience_segments'] < 1 ? 'Define an audience segment' : '',
                $recordCounts['landing_pages'] < 1 ? 'Create a landing page plan' : '',
            ],
            ['Open Campaign Workspace', 'Create Brief', 'Define Segment']
        );
        $lanes[] = $lane(
            'audience_journey',
            'Audience Journey',
            'marketing_journeys.php',
            $presentScore([
                $recordCounts['audience_segments'],
                $recordCounts['journeys'],
                $counts['audience_activations_ready'] ?? $counts['audience_activations_active'] ?? 0,
                $recordCounts['lead_handoffs'],
            ]),
            [
                $metric('Segments', $recordCounts['audience_segments']),
                $metric('Journeys', $recordCounts['journeys']),
                $metric('Activations ready', $counts['audience_activations_ready'] ?? 0),
                $metric('Lead handoffs', $recordCounts['lead_handoffs']),
            ],
            [
                $recordCounts['audience_segments'] < 1 ? 'Build a reusable audience segment' : '',
                $recordCounts['journeys'] < 1 ? 'Plan a manual journey' : '',
                ($counts['audience_activations_ready'] ?? 0) < 1 ? 'Prepare an audience activation' : '',
            ],
            ['Open Segments', 'Plan Journey', 'Review Handoffs']
        );
        $lanes[] = $lane(
            'content_review',
            'Content Review',
            'marketing_content.php',
            $presentScore([
                $recordCounts['content_items'],
                $counts['calendar_this_week'] ?? 0,
                $counts['approvals_waiting'] ?? $counts['in_review'] ?? 0,
                $counts['quality_checks'] ?? 0,
            ]),
            [
                $metric('Content items', $recordCounts['content_items']),
                $metric('Calendar this week', $counts['calendar_this_week'] ?? 0),
                $metric('In review', $counts['in_review'] ?? 0),
                $metric('Quality checks', $counts['quality_checks'] ?? 0),
            ],
            [
                $recordCounts['content_items'] < 1 ? 'Create the first content item' : '',
                ($counts['calendar_this_week'] ?? 0) < 1 ? 'Place work on the calendar' : '',
                ($counts['quality_checks'] ?? 0) < 1 ? 'Run a quality or brand safety review' : '',
            ],
            ['Open Content Studio', 'Open Calendar', 'Open Reviews']
        );
        $lanes[] = $lane(
            'media_creative',
            'Media Creative',
            'marketing_assets.php',
            $presentScore([
                $recordCounts['media_files'],
                $counts['asset_requests_ready'] ?? 0,
                $counts['media_production_open'] ?? 0,
                $counts['media_missing_alt_text'] ?? 0,
            ]),
            [
                $metric('Media files', $recordCounts['media_files']),
                $metric('Ready asset requests', $counts['asset_requests_ready'] ?? 0),
                $metric('Production open', $counts['media_production_open'] ?? 0),
                $metric('Alt text gaps', $counts['media_missing_alt_text'] ?? 0),
            ],
            [
                $recordCounts['media_files'] < 1 ? 'Upload or reference campaign media' : '',
                ($counts['media_missing_alt_text'] ?? 0) > 0 ? 'Resolve missing alt text' : '',
                ($counts['media_blocked'] ?? 0) > 0 ? 'Clear blocked or expired media' : '',
            ],
            ['Open Assets', 'Open Creative Production', 'Review Media Governance']
        );
        $lanes[] = $lane(
            'landing_conversion',
            'Landing Conversion',
            'marketing_landing_pages.php',
            $presentScore([
                $recordCounts['landing_pages'],
                $recordCounts['conversion_goals'],
                $counts['conversion_events'] ?? 0,
                $counts['landing_page_views'] ?? 0,
            ]),
            [
                $metric('Landing pages', $recordCounts['landing_pages']),
                $metric('Conversion goals', $recordCounts['conversion_goals']),
                $metric('Views', $counts['landing_page_views'] ?? 0),
                $metric('Conversions', $counts['conversion_events'] ?? 0),
            ],
            [
                $recordCounts['landing_pages'] < 1 ? 'Create a landing page plan' : '',
                $recordCounts['conversion_goals'] < 1 ? 'Define conversion goals' : '',
                ($counts['conversion_goals_missing_links'] ?? 0) > 0 ? 'Link conversion goals to campaign/form/landing assets' : '',
            ],
            ['Open Landing Pages', 'Open Conversion Goals', 'Review Preview']
        );
        $lanes[] = $lane(
            'distribution_execution',
            'Distribution Execution',
            'marketing_distribution.php',
            $presentScore([
                $recordCounts['distribution_posts'],
                $recordCounts['email_runs'],
                $recordCounts['channel_exports'],
                $recordCounts['utm_links'],
            ]),
            [
                $metric('Distribution posts', $recordCounts['distribution_posts']),
                $metric('Email runs', $recordCounts['email_runs']),
                $metric('Channel exports', $recordCounts['channel_exports']),
                $metric('UTM links', $recordCounts['utm_links']),
            ],
            [
                $recordCounts['distribution_posts'] < 1 ? 'Create manual distribution variants' : '',
                $recordCounts['email_runs'] < 1 ? 'Plan a manual email run where relevant' : '',
                $recordCounts['utm_links'] < 1 ? 'Generate UTM links for campaign/content combinations' : '',
            ],
            ['Open Distribution', 'Open Email Runs', 'Open Channel Exports']
        );
        $lanes[] = $lane(
            'measurement_handoff',
            'Measurement And Handoff',
            'marketing_performance.php',
            $boundedScore(($presentScore([
                $recordCounts['analytics_snapshots'],
                $recordCounts['lead_handoffs'],
                $counts['attribution_touchpoints'] ?? 0,
                $recordCounts['conversion_goals'],
            ]) + $revenueScore) / 2),
            [
                $metric('Revenue loop', $revenueScore . '%'),
                $metric('Analytics snapshots', $recordCounts['analytics_snapshots']),
                $metric('Attribution touchpoints', $counts['attribution_touchpoints'] ?? 0),
                $metric('Lead handoffs', $recordCounts['lead_handoffs']),
            ],
            [
                $recordCounts['analytics_snapshots'] < 1 ? 'Create or refresh analytics snapshots' : '',
                $recordCounts['lead_handoffs'] < 1 ? 'Connect lead handoff rules' : '',
                ($counts['attribution_touchpoints'] ?? 0) < 1 ? 'Capture attribution touchpoints' : '',
            ],
            ['Open Performance', 'Review Lead Handoffs', 'Open Reports']
        );
        $lanes[] = $lane(
            'operations_governance',
            'Operations Governance',
            'marketing_admin.php',
            $boundedScore((
                (int) ($integration['score'] ?? 0)
                + ((string) ($automation['status'] ?? '') === 'ready' ? 100 : 55)
                + ((string) ($pageSpeed['status'] ?? 'ready') === 'attention' ? 55 : 100)
                + $presentScore([$recordCounts['planning_queue_items'], $recordCounts['action_router_items']])
            ) / 4),
            [
                $metric('Integration score', (int) ($integration['score'] ?? 0) . '%'),
                $metric('Automation', $automation['status'] ?? 'unknown'),
                $metric('Planning queue', $recordCounts['planning_queue_items']),
                $metric('Action router', $recordCounts['action_router_items']),
            ],
            [
                (int) ($integration['score'] ?? 0) < 70 ? 'Resolve integration readiness gaps' : '',
                (string) ($automation['status'] ?? '') !== 'ready' ? 'Review manual automation loops' : '',
                (string) ($pageSpeed['status'] ?? 'ready') === 'attention' ? 'Review page speed guardrails' : '',
            ],
            ['Open Admin Diagnostics', 'Open Operations', 'Open Action Router']
        );

        $statusCounts = ['ready' => 0, 'attention' => 0, 'blocked' => 0, 'total' => count($lanes), 'open_gaps' => 0];
        $totalScore = 0;
        $criticalGaps = [];
        $recommendedActions = [];
        foreach ($lanes as $laneItem) {
            $laneStatus = (string) ($laneItem['status'] ?? 'attention');
            $statusCounts[$laneStatus] = (int) ($statusCounts[$laneStatus] ?? 0) + 1;
            $statusCounts['open_gaps'] += count((array) ($laneItem['missing'] ?? []));
            $totalScore += (int) ($laneItem['score'] ?? 0);
            if ($laneStatus !== 'ready') {
                foreach ((array) ($laneItem['missing'] ?? []) as $gap) {
                    $criticalGaps[] = (string) ($laneItem['label'] ?? 'Workflow') . ': ' . (string) $gap;
                }
            }
            foreach ((array) ($laneItem['next_actions'] ?? []) as $action) {
                $recommendedActions[] = (string) $action;
            }
        }
        $score = $boundedScore($totalScore / max(1, count($lanes)));
        $status = match (true) {
            $statusCounts['blocked'] > 0 => 'blocked',
            $statusCounts['attention'] > 0 => 'attention',
            default => 'ready',
        };

        return [
            'status' => $status,
            'score' => $score,
            'lanes' => $lanes,
            'counts' => $statusCounts,
            'record_counts' => $recordCounts,
            'critical_gaps' => array_slice(array_values(array_unique($criticalGaps)), 0, 12),
            'recommended_actions' => array_slice(array_values(array_unique($recommendedActions)), 0, 12),
            'system_score' => $systemScore,
            'guardrails' => [
                'workspace_scoped' => true,
                'manual_first' => true,
                'read_only_diagnostic' => true,
                'external_publish' => false,
                'external_send' => false,
                'external_api_calls' => false,
                'uses_existing_crm_tools' => true,
                'page_speed_aware' => true,
            ],
            'recommended_product_decision' => 'Use Workflow Readiness as the operator reality check before launching work: it should expose missing setup, context, audience, content, media, landing, distribution, measurement, and governance steps without creating records or calling external systems.',
            'generated_at' => date('c'),
        ];
    }

    public function getMarketingActionRouter(?int $userId = null, int $limit = 12, array $context = []): array
    {
        $this->assertMarketingPermission('marketing.read');
        $limit = min(max($limit, 1), 30);
        $userId = $userId ?? $this->currentUserId();
        $storedItems = $this->listMarketingActionRouterItems(['open' => true], $limit, 0);
        $dynamicCandidates = $this->buildMarketingActionRouterCandidates($userId, $limit, $context);
        $active = [];
        $seen = [];
        foreach ($storedItems as $item) {
            $key = strtolower((string) ($item['action_key'] ?? '') . '|' . (string) ($item['target_href'] ?? ''));
            if ($key === '|') {
                continue;
            }
            $seen[$key] = true;
            $active[] = $item + ['source_mode' => 'stored'];
        }
        foreach ($dynamicCandidates as $candidate) {
            $key = strtolower((string) ($candidate['action_key'] ?? '') . '|' . (string) ($candidate['target_href'] ?? ''));
            if ($key === '|' || isset($seen[$key])) {
                continue;
            }
            $seen[$key] = true;
            $active[] = $candidate + ['source_mode' => 'live'];
            if (count($active) >= $limit) {
                break;
            }
        }

        $counts = [
            'stored_open' => count($storedItems),
            'live_recommendations' => count($dynamicCandidates),
            'active' => count($active),
            'high_priority' => count(array_filter($active, static fn(array $item): bool => (string) ($item['priority'] ?? '') === 'high')),
        ];

        return [
            'items' => $active,
            'stored_items' => $storedItems,
            'live_candidates' => $dynamicCandidates,
            'counts' => $counts,
            'guardrails' => [
                'workspace_scoped' => true,
                'manual_first' => true,
                'external_publish' => false,
                'external_send' => false,
                'external_api_calls' => false,
                'safe_relative_links_only' => true,
            ],
            'recommended_product_decision' => 'Use the Action Router as the bridge between Marketing recommendations and CRM execution surfaces, so content, campaigns, audiences, handoffs, tasks, and attribution do not drift apart.',
        ];
    }

    public function getMarketingCrmIntegrationActionCenter(array $context = [], ?int $userId = null, int $limit = 8): array
    {
        $this->assertMarketingPermission('marketing.read');
        $limit = min(max($limit, 1), 16);
        $userId = $userId ?? $this->currentUserId();
        $profile = $this->getMarketingCrmLifecycleProfile($context, $limit);
        $router = $this->getMarketingActionRouter($userId, $limit, $context);
        $integration = $this->getMarketingIntegrationReadiness(40);
        $counts = (array) ($profile['counts'] ?? []);
        $lanes = [
            'crm_foundation' => [
                'label' => 'CRM Foundation',
                'status' => ((int) ($counts['contacts'] ?? 0) > 0 && (int) ($counts['campaigns'] ?? 0) > 0) ? 'ready' : 'attention',
                'score' => min(100, ((int) ($counts['contacts'] ?? 0) > 0 ? 35 : 0) + ((int) ($counts['companies'] ?? 0) > 0 ? 15 : 0) + ((int) ($counts['open_deals'] ?? 0) > 0 ? 20 : 0) + ((int) ($counts['campaigns'] ?? 0) > 0 ? 30 : 0)),
                'href' => 'contacts.php',
                'summary' => (int) ($counts['contacts'] ?? 0) . ' contact(s), ' . (int) ($counts['open_deals'] ?? 0) . ' open deal(s), ' . (int) ($counts['campaigns'] ?? 0) . ' campaign(s).',
                'action' => 'Keep contacts, companies, deals, and campaigns tied to each Marketing motion.',
            ],
            'conversion_capture' => [
                'label' => 'Conversion Capture',
                'status' => ((int) ($counts['forms'] ?? 0) > 0 && (int) ($counts['landing_pages'] ?? 0) > 0) ? 'ready' : 'attention',
                'score' => min(100, ((int) ($counts['forms'] ?? 0) > 0 ? 30 : 0) + ((int) ($counts['form_submissions'] ?? 0) > 0 ? 25 : 0) + ((int) ($counts['landing_pages'] ?? 0) > 0 ? 25 : 0) + ((int) ($counts['conversion_events'] ?? 0) > 0 ? 20 : 0)),
                'href' => 'forms.php',
                'summary' => (int) ($counts['forms'] ?? 0) . ' form(s), ' . (int) ($counts['form_submissions'] ?? 0) . ' submission(s), ' . (int) ($counts['landing_pages'] ?? 0) . ' landing page(s).',
                'action' => 'Connect forms and landing pages before treating campaign interest as qualified demand.',
            ],
            'execution_handoff' => [
                'label' => 'Execution Handoff',
                'status' => ((int) ($counts['open_tasks'] ?? 0) > 0 || (int) ($counts['lead_handoffs_open'] ?? 0) > 0) ? 'ready' : 'attention',
                'score' => min(100, ((int) ($counts['content_items'] ?? 0) > 0 ? 25 : 0) + ((int) ($counts['distribution_posts'] ?? 0) > 0 ? 20 : 0) + ((int) ($counts['open_tasks'] ?? 0) > 0 ? 25 : 0) + ((int) ($counts['lead_handoffs_open'] ?? 0) > 0 ? 30 : 0)),
                'href' => 'marketing_handoffs.php',
                'summary' => (int) ($counts['content_items'] ?? 0) . ' content item(s), ' . (int) ($counts['open_tasks'] ?? 0) . ' task(s), ' . (int) ($counts['lead_handoffs_open'] ?? 0) . ' handoff(s).',
                'action' => 'Turn Marketing intent into owned tasks, handoffs, and manual distribution work.',
            ],
            'revenue_attribution' => [
                'label' => 'Revenue Attribution',
                'status' => ((int) ($counts['utm_links'] ?? 0) > 0 && ((int) ($counts['attribution_touchpoints'] ?? 0) > 0 || (int) ($counts['won_deals'] ?? 0) > 0)) ? 'ready' : 'attention',
                'score' => min(100, ((int) ($counts['utm_links'] ?? 0) > 0 ? 35 : 0) + ((int) ($counts['attribution_touchpoints'] ?? 0) > 0 ? 35 : 0) + ((int) ($counts['won_deals'] ?? 0) > 0 ? 30 : 0)),
                'href' => 'marketing_performance.php',
                'summary' => (int) ($counts['utm_links'] ?? 0) . ' UTM link(s), ' . (int) ($counts['attribution_touchpoints'] ?? 0) . ' attribution touchpoint(s), ' . (int) ($counts['won_deals'] ?? 0) . ' won deal(s).',
                'action' => 'Keep UTM, attribution, and deal revenue evidence connected before claiming performance.',
            ],
        ];
        $nextActions = [];
        foreach ((array) ($profile['recommendations'] ?? []) as $action) {
            $nextActions[] = [
                'label' => (string) ($action['label'] ?? 'Review CRM lifecycle action'),
                'href' => (string) ($action['href'] ?? 'marketing_action_router.php'),
                'reason' => (string) ($action['reason'] ?? 'Review this CRM lifecycle recommendation.'),
                'priority' => (string) ($action['priority'] ?? 'normal'),
                'source' => 'CRM Lifecycle',
            ];
        }
        foreach (array_slice((array) ($router['items'] ?? []), 0, $limit) as $item) {
            $nextActions[] = [
                'label' => (string) ($item['label'] ?? 'Review Action Router item'),
                'href' => (string) ($item['target_href'] ?? 'marketing_action_router.php'),
                'reason' => (string) ($item['reason'] ?? 'Open the recommended CRM target.'),
                'priority' => (string) ($item['priority'] ?? 'normal'),
                'source' => 'Action Router',
            ];
        }
        $seen = [];
        $nextActions = array_values(array_filter($nextActions, static function (array $action) use (&$seen): bool {
            $key = strtolower((string) ($action['label'] ?? '') . '|' . (string) ($action['href'] ?? ''));
            if ($key === '|' || isset($seen[$key])) {
                return false;
            }
            $seen[$key] = true;
            return true;
        }));

        return [
            'score' => (int) round(array_sum(array_map(static fn(array $lane): int => (int) ($lane['score'] ?? 0), $lanes)) / max(1, count($lanes))),
            'status' => (int) ($profile['score'] ?? 0) >= 80 ? 'ready' : ((int) ($profile['score'] ?? 0) >= 45 ? 'attention' : 'missing'),
            'scope' => (string) ($profile['scope'] ?? 'workspace'),
            'scope_label' => (string) ($profile['scope_label'] ?? 'Workspace lifecycle'),
            'profile' => $profile,
            'router' => $router,
            'lanes' => $lanes,
            'next_actions' => array_slice($nextActions, 0, $limit),
            'system_connections' => array_slice((array) ($integration['system_connections'] ?? []), 0, 12, true),
            'performance' => [
                'detail_limit' => $limit,
                'integration_detail_limit' => 40,
                'page_load_guard' => true,
                'external_api_calls' => false,
            ],
            'guardrails' => [
                'workspace_scoped' => true,
                'manual_first' => true,
                'external_publish' => false,
                'external_send' => false,
                'external_api_calls' => false,
                'uses_existing_crm_tools' => true,
            ],
            'recommended_product_decision' => 'Make Marketing the CRM demand-control layer: every recommendation should resolve into an existing CRM surface, owner, handoff, task, form, deal, or attribution path.',
            'generated_at' => date('c'),
        ];
    }

    public function getCampaignRevenueLoopSummary(?int $campaignId = null, int $limit = 8): array
    {
        $this->assertMarketingPermission('marketing.read');
        $limit = min(max($limit, 1), 20);
        $workspaceId = $this->workspaceId();

        if (($campaignId ?? 0) > 0 && !$this->getCampaignForWorkspace((int) $campaignId)) {
            throw new RuntimeException('Campaign was not found in the active workspace.');
        }

        if (!Database::tableExists('campaigns')) {
            return [
                'score' => 0,
                'status' => 'missing',
                'counts' => ['campaigns' => 0, 'ready' => 0, 'attention' => 0, 'blocked' => 0],
                'lanes' => [],
                'campaigns' => [],
                'next_actions' => [[
                    'label' => 'Create CRM campaign',
                    'href' => 'campaigns.php',
                    'reason' => 'Campaigns anchor Marketing revenue readiness, attribution, handoffs, and ROI reporting.',
                    'priority' => 'high',
                ]],
                'guardrails' => [
                    'workspace_scoped' => true,
                    'manual_first' => true,
                    'external_publish' => false,
                    'external_send' => false,
                    'external_api_calls' => false,
                ],
                'recommended_product_decision' => 'Start every revenue loop from a CRM campaign so content, conversion, handoff, and ROI evidence stay connected.',
                'performance' => ['detail_limit' => $limit, 'external_api_calls' => false],
                'generated_at' => date('c'),
            ];
        }

        $workspaces = $this->listMarketingCampaignWorkspaces(
            ($campaignId ?? 0) > 0 ? ['campaign_id' => (int) $campaignId] : ['open' => true],
            max($limit, 12),
            0
        );

        $start = date('Y-m-d', strtotime('-90 days'));
        $end = date('Y-m-d');
        $roiAnalytics = $this->campaignRoiAnalytics($start, $end);
        $roiByCampaign = [];
        foreach ((array) ($roiAnalytics['campaigns'] ?? []) as $row) {
            $roiByCampaign[(int) ($row['campaign_id'] ?? 0)] = $row;
        }

        $statusFromScore = static function (int $score): string {
            if ($score >= 75) {
                return 'ready';
            }
            if ($score >= 35) {
                return 'attention';
            }

            return 'blocked';
        };
        $lane = static function (string $key, string $label, int $score, string $summary, string $href, string $action) use ($statusFromScore): array {
            return [
                'key' => $key,
                'label' => $label,
                'score' => max(0, min(100, $score)),
                'status' => $statusFromScore($score),
                'summary' => $summary,
                'href' => $href,
                'action' => $action,
            ];
        };
        $linkedCount = static fn(array $linked, string $key): int => (int) ($linked[$key]['count'] ?? 0);
        $addAction = static function (array &$actions, array &$seen, string $label, string $href, string $reason, string $priority = 'normal', int $campaignId = 0): void {
            $key = strtolower($label . '|' . $href . '|' . $campaignId);
            if (isset($seen[$key])) {
                return;
            }
            $seen[$key] = true;
            $actions[] = [
                'label' => $label,
                'href' => $href,
                'reason' => $reason,
                'priority' => $priority,
                'campaign_id' => $campaignId,
            ];
        };

        $campaignGoalStats = function (int $id) use ($workspaceId): array {
            if (!Database::tableExists('marketing_conversion_goals') || !Database::tableExists('marketing_conversion_goal_links')) {
                return ['total' => 0, 'active' => 0, 'average_readiness' => null];
            }
            $row = Database::queryOne(
                "SELECT COUNT(DISTINCT g.id) AS total,
                        SUM(CASE WHEN g.status = 'active' THEN 1 ELSE 0 END) AS active,
                        AVG(g.readiness_score) AS average_readiness
                 FROM marketing_conversion_goals g
                 JOIN marketing_conversion_goal_links l ON l.goal_id = g.id AND l.workspace_id = g.workspace_id
                 WHERE g.workspace_id = ?
                   AND g.status <> 'archived'
                   AND l.linked_type = 'campaign'
                   AND l.linked_id = ?",
                [$workspaceId, $id]
            ) ?: [];

            return [
                'total' => (int) ($row['total'] ?? 0),
                'active' => (int) ($row['active'] ?? 0),
                'average_readiness' => $row['average_readiness'] !== null ? round((float) $row['average_readiness'], 1) : null,
            ];
        };
        $campaignHandoffStats = function (int $id) use ($workspaceId): array {
            if (!Database::tableExists('marketing_lead_handoffs') || !Database::columnExists('marketing_lead_handoffs', 'campaign_id')) {
                return ['total' => 0, 'open' => 0, 'overdue' => 0, 'converted' => 0];
            }
            $row = Database::queryOne(
                "SELECT COUNT(*) AS total,
                        SUM(CASE WHEN status IN ('new','assigned','contacted','qualified') THEN 1 ELSE 0 END) AS open_count,
                        SUM(CASE WHEN sla_due_at IS NOT NULL AND sla_due_at < NOW() AND status IN ('new','assigned','contacted','qualified') THEN 1 ELSE 0 END) AS overdue,
                        SUM(CASE WHEN status = 'converted' OR converted_at IS NOT NULL THEN 1 ELSE 0 END) AS converted
                 FROM marketing_lead_handoffs
                 WHERE workspace_id = ? AND campaign_id = ?",
                [$workspaceId, $id]
            ) ?: [];

            return [
                'total' => (int) ($row['total'] ?? 0),
                'open' => (int) ($row['open_count'] ?? 0),
                'overdue' => (int) ($row['overdue'] ?? 0),
                'converted' => (int) ($row['converted'] ?? 0),
            ];
        };
        $campaignAttributionStats = function (int $id) use ($workspaceId, $start, $end): array {
            $touchpoint = ['touchpoints' => 0, 'conversion_touchpoints' => 0, 'revenue_touchpoints' => 0, 'touchpoint_revenue' => 0.0];
            if (Database::tableExists('marketing_attribution_touchpoints')) {
                $row = Database::queryOne(
                    "SELECT COUNT(*) AS touchpoints,
                            SUM(CASE WHEN touchpoint_type = 'conversion' THEN 1 ELSE 0 END) AS conversion_touchpoints,
                            SUM(CASE WHEN touchpoint_type = 'revenue' THEN 1 ELSE 0 END) AS revenue_touchpoints,
                            COALESCE(SUM(CASE WHEN touchpoint_type = 'revenue' THEN revenue_amount ELSE 0 END), 0) AS touchpoint_revenue
                     FROM marketing_attribution_touchpoints
                     WHERE workspace_id = ? AND campaign_id = ?",
                    [$workspaceId, $id]
                ) ?: [];
                $touchpoint = [
                    'touchpoints' => (int) ($row['touchpoints'] ?? 0),
                    'conversion_touchpoints' => (int) ($row['conversion_touchpoints'] ?? 0),
                    'revenue_touchpoints' => (int) ($row['revenue_touchpoints'] ?? 0),
                    'touchpoint_revenue' => round((float) ($row['touchpoint_revenue'] ?? 0), 2),
                ];
            }

            $credited = ['credited_revenue' => 0.0, 'conversion_count' => 0];
            if (Database::tableExists('attribution_results') && Database::columnExists('attribution_results', 'workspace_id')) {
                $row = Database::queryOne(
                    "SELECT COALESCE(SUM(credited_value), 0) AS credited_revenue, COUNT(*) AS conversion_count
                     FROM attribution_results
                     WHERE workspace_id = ? AND campaign_id = ?
                       AND conversion_at >= ? AND conversion_at < DATE_ADD(?, INTERVAL 1 DAY)",
                    [$workspaceId, $id, $start, $end]
                ) ?: [];
                $credited = [
                    'credited_revenue' => round((float) ($row['credited_revenue'] ?? 0), 2),
                    'conversion_count' => (int) ($row['conversion_count'] ?? 0),
                ];
            }

            return $touchpoint + $credited + [
                'revenue_evidence' => max((float) $touchpoint['touchpoint_revenue'], (float) $credited['credited_revenue']),
            ];
        };
        $campaignBudgetStats = function (int $id) use ($workspaceId): array {
            $budget = ['budget_count' => 0, 'planned_budget' => 0.0, 'actual_spend' => 0.0];
            if (Database::tableExists('marketing_campaign_budgets')) {
                $row = Database::queryOne(
                    "SELECT COUNT(*) AS budget_count,
                            COALESCE(SUM(planned_budget), 0) AS planned_budget,
                            COALESCE(SUM(actual_spend), 0) AS actual_spend
                     FROM marketing_campaign_budgets
                     WHERE workspace_id = ? AND campaign_id = ? AND status <> 'archived'",
                    [$workspaceId, $id]
                ) ?: [];
                $budget = [
                    'budget_count' => (int) ($row['budget_count'] ?? 0),
                    'planned_budget' => round((float) ($row['planned_budget'] ?? 0), 2),
                    'actual_spend' => round((float) ($row['actual_spend'] ?? 0), 2),
                ];
            }
            $target = ['roi_target_count' => 0, 'target_revenue' => 0.0];
            if (Database::tableExists('marketing_roi_targets') && Database::columnExists('marketing_roi_targets', 'campaign_id')) {
                $row = Database::queryOne(
                    "SELECT COUNT(*) AS target_count, COALESCE(SUM(target_revenue), 0) AS target_revenue
                     FROM marketing_roi_targets
                     WHERE workspace_id = ? AND campaign_id = ? AND status <> 'archived'",
                    [$workspaceId, $id]
                ) ?: [];
                $target = [
                    'roi_target_count' => (int) ($row['target_count'] ?? 0),
                    'target_revenue' => round((float) ($row['target_revenue'] ?? 0), 2),
                ];
            }

            return $budget + $target;
        };

        $rows = [];
        $nextActions = [];
        $seenActions = [];
        $laneTotals = [];
        $counts = [
            'campaigns' => 0,
            'ready' => 0,
            'attention' => 0,
            'blocked' => 0,
            'content_items' => 0,
            'landing_pages' => 0,
            'distribution_packages' => 0,
            'utm_links' => 0,
            'conversion_goals' => 0,
            'lead_handoffs' => 0,
            'touchpoints' => 0,
            'attributed_revenue' => 0.0,
            'planned_budget' => 0.0,
            'roi_targets' => 0,
        ];

        foreach ($workspaces as $workspace) {
            $id = (int) ($workspace['campaign_id'] ?? 0);
            if ($id <= 0) {
                continue;
            }
            $linked = (array) ($workspace['linked_summary_json'] ?? []);
            $briefCount = $linkedCount($linked, 'briefs');
            $audienceCount = $linkedCount($linked, 'audience_activations');
            $contentCount = $linkedCount($linked, 'content_items');
            $landingCount = $linkedCount($linked, 'landing_pages');
            $distributionCount = $linkedCount($linked, 'distribution_posts') + $linkedCount($linked, 'channel_exports') + $linkedCount($linked, 'email_runs');
            $utmCount = $linkedCount($linked, 'utm_links');
            $goalStats = $campaignGoalStats($id);
            $handoffStats = $campaignHandoffStats($id);
            $attributionStats = $campaignAttributionStats($id);
            $budgetStats = $campaignBudgetStats($id);
            $roiRow = $roiByCampaign[$id] ?? [];

            $strategyScore = min(100, ($briefCount > 0 ? 70 : 0) + (in_array((string) ($workspace['campaign_status'] ?? ''), ['active', 'completed'], true) ? 30 : 15));
            $audienceScore = min(100, ($audienceCount > 0 ? 80 : 0) + ($briefCount > 0 ? 20 : 0));
            $contentScore = min(100, ($contentCount > 0 ? 75 : 0) + ($linkedCount($linked, 'calendar') > 0 ? 15 : 0) + ($linkedCount($linked, 'planning_queue') > 0 ? 10 : 0));
            $conversionScore = min(100, ($landingCount > 0 ? 45 : 0) + ((int) $goalStats['active'] > 0 ? 40 : 0) + ((float) ($goalStats['average_readiness'] ?? 0) >= 70 ? 15 : 0));
            $distributionScore = min(100, ($distributionCount > 0 ? 70 : 0) + ($linkedCount($linked, 'launch_checklists') > 0 ? 15 : 0) + ($linkedCount($linked, 'launch_control') > 0 ? 15 : 0));
            $trackingScore = min(100, ($utmCount > 0 ? 70 : 0) + ((int) $attributionStats['touchpoints'] > 0 ? 30 : 0));
            $attributionScore = min(100, ((int) $attributionStats['touchpoints'] > 0 ? 45 : 0) + ((int) $attributionStats['conversion_count'] > 0 || (int) $attributionStats['conversion_touchpoints'] > 0 ? 25 : 0) + ((float) $attributionStats['revenue_evidence'] > 0 ? 30 : 0));
            $handoffScore = min(100, ((int) $handoffStats['total'] > 0 ? 65 : 0) + ((int) $handoffStats['converted'] > 0 ? 35 : 0));
            $roiScore = min(100, ((int) $budgetStats['budget_count'] > 0 ? 40 : 0) + ((int) $budgetStats['roi_target_count'] > 0 ? 35 : 0) + (((float) $attributionStats['revenue_evidence'] > 0 || (float) ($roiRow['attributed_revenue'] ?? 0) > 0) ? 25 : 0));

            $lanes = [
                'strategy' => $lane('strategy', 'Strategy', $strategyScore, "{$briefCount} brief(s)", 'marketing_briefs.php?campaign_id=' . $id, 'Clarify objective, offer, audience, owner, and key message.'),
                'audience' => $lane('audience', 'Audience', $audienceScore, "{$audienceCount} activation(s)", 'marketing_audience_activation.php?campaign_id=' . $id, 'Connect a CRM-derived segment or activation.'),
                'content' => $lane('content', 'Content', $contentScore, "{$contentCount} content item(s)", 'marketing_content.php?campaign_id=' . $id, 'Create campaign content and production tasks.'),
                'conversion' => $lane('conversion', 'Conversion', $conversionScore, "{$landingCount} landing page(s), " . (int) $goalStats['active'] . ' active goal(s)', 'marketing_landing_pages.php?campaign_id=' . $id, 'Connect landing page, form, CTA, and conversion goal.'),
                'distribution' => $lane('distribution', 'Distribution', $distributionScore, "{$distributionCount} package(s)", 'marketing_distribution.php?campaign_id=' . $id, 'Build manual distribution, email, or channel export package.'),
                'tracking' => $lane('tracking', 'Tracking', $trackingScore, "{$utmCount} UTM link(s)", 'marketing_utm_links.php?campaign_id=' . $id, 'Create tracking links before launch.'),
                'attribution' => $lane('attribution', 'Attribution', $attributionScore, (int) $attributionStats['touchpoints'] . ' touchpoint(s), $' . number_format((float) $attributionStats['revenue_evidence'], 2) . ' revenue evidence', 'marketing_performance.php?campaign_id=' . $id, 'Connect campaign influence to conversions, deals, and credited revenue.'),
                'sales_handoff' => $lane('sales_handoff', 'Sales Handoff', $handoffScore, (int) $handoffStats['open'] . ' open, ' . (int) $handoffStats['converted'] . ' converted', 'marketing_handoffs.php?campaign_id=' . $id, 'Route qualified demand into owned sales follow-up.'),
                'roi_plan' => $lane('roi_plan', 'ROI Plan', $roiScore, '$' . number_format((float) $budgetStats['planned_budget'], 2) . ' planned, ' . (int) $budgetStats['roi_target_count'] . ' target(s)', 'marketing_performance.php?campaign_id=' . $id, 'Set budget and ROI targets before reading performance.'),
            ];

            foreach ($lanes as $laneKey => $laneData) {
                $laneTotals[$laneKey]['score'] = (int) ($laneTotals[$laneKey]['score'] ?? 0) + (int) $laneData['score'];
                $laneTotals[$laneKey]['count'] = (int) ($laneTotals[$laneKey]['count'] ?? 0) + 1;
                $laneTotals[$laneKey]['label'] = (string) $laneData['label'];
                $laneTotals[$laneKey]['href'] = (string) $laneData['href'];
                $laneTotals[$laneKey]['action'] = (string) $laneData['action'];
            }

            $score = (int) round(array_sum(array_map(static fn(array $laneData): int => (int) $laneData['score'], $lanes)) / count($lanes));
            $status = $statusFromScore($score);
            $counts['campaigns']++;
            $counts[$status]++;
            $counts['content_items'] += $contentCount;
            $counts['landing_pages'] += $landingCount;
            $counts['distribution_packages'] += $distributionCount;
            $counts['utm_links'] += $utmCount;
            $counts['conversion_goals'] += (int) $goalStats['active'];
            $counts['lead_handoffs'] += (int) $handoffStats['total'];
            $counts['touchpoints'] += (int) $attributionStats['touchpoints'];
            $counts['attributed_revenue'] += (float) $attributionStats['revenue_evidence'];
            $counts['planned_budget'] += (float) $budgetStats['planned_budget'];
            $counts['roi_targets'] += (int) $budgetStats['roi_target_count'];

            $rowNextAction = null;
            foreach ($lanes as $laneData) {
                if ((int) $laneData['score'] >= 75) {
                    continue;
                }
                $addAction($nextActions, $seenActions, (string) $laneData['action'], (string) $laneData['href'], (string) $laneData['summary'], (int) $laneData['score'] < 35 ? 'high' : 'normal', $id);
                $rowNextAction = [
                    'label' => (string) $laneData['action'],
                    'href' => (string) $laneData['href'],
                    'reason' => (string) $laneData['summary'],
                    'priority' => (int) $laneData['score'] < 35 ? 'high' : 'normal',
                    'campaign_id' => $id,
                ];
                break;
            }

            $rows[] = [
                'campaign_id' => $id,
                'campaign_name' => (string) ($workspace['campaign_name'] ?? $workspace['workspace_name'] ?? 'Campaign'),
                'campaign_status' => (string) ($workspace['campaign_status'] ?? ''),
                'score' => $score,
                'status' => $status,
                'lanes' => $lanes,
                'pipeline_counts' => [
                    'briefs' => $briefCount,
                    'audience_activations' => $audienceCount,
                    'content_items' => $contentCount,
                    'landing_pages' => $landingCount,
                    'distribution_packages' => $distributionCount,
                    'utm_links' => $utmCount,
                    'conversion_goals' => (int) $goalStats['active'],
                    'lead_handoffs' => (int) $handoffStats['total'],
                    'touchpoints' => (int) $attributionStats['touchpoints'],
                    'conversion_count' => (int) $attributionStats['conversion_count'],
                    'attributed_revenue' => round((float) $attributionStats['revenue_evidence'], 2),
                    'planned_budget' => round((float) $budgetStats['planned_budget'], 2),
                    'roi_targets' => (int) $budgetStats['roi_target_count'],
                    'roi_percent' => $roiRow['roi_percent'] ?? null,
                ],
                'next_action' => $rowNextAction,
            ];
        }

        if ($rows === []) {
            $addAction($nextActions, $seenActions, 'Create CRM campaign', 'campaigns.php', 'Campaigns anchor the Marketing revenue loop.', 'high');
        }
        $summaryLanes = [];
        foreach ($laneTotals as $key => $data) {
            $average = (int) round(((int) $data['score']) / max(1, (int) $data['count']));
            $summaryLanes[$key] = [
                'key' => $key,
                'label' => (string) $data['label'],
                'score' => $average,
                'status' => $statusFromScore($average),
                'href' => (string) $data['href'],
                'action' => (string) $data['action'],
            ];
        }

        usort($rows, static fn(array $left, array $right): int => ((int) $right['score'] <=> (int) $left['score']) ?: strcmp((string) $left['campaign_name'], (string) $right['campaign_name']));
        $overallScore = $rows === [] ? 0 : (int) round(array_sum(array_map(static fn(array $row): int => (int) $row['score'], $rows)) / count($rows));

        return [
            'score' => $overallScore,
            'status' => $statusFromScore($overallScore),
            'selected_campaign_id' => ($campaignId ?? 0) > 0 ? (int) $campaignId : null,
            'window' => ['start' => $start, 'end' => $end],
            'counts' => [
                'campaigns' => (int) $counts['campaigns'],
                'ready' => (int) $counts['ready'],
                'attention' => (int) $counts['attention'],
                'blocked' => (int) $counts['blocked'],
                'content_items' => (int) $counts['content_items'],
                'landing_pages' => (int) $counts['landing_pages'],
                'distribution_packages' => (int) $counts['distribution_packages'],
                'utm_links' => (int) $counts['utm_links'],
                'conversion_goals' => (int) $counts['conversion_goals'],
                'lead_handoffs' => (int) $counts['lead_handoffs'],
                'touchpoints' => (int) $counts['touchpoints'],
                'attributed_revenue' => round((float) $counts['attributed_revenue'], 2),
                'planned_budget' => round((float) $counts['planned_budget'], 2),
                'roi_targets' => (int) $counts['roi_targets'],
                'analytics_total_revenue' => (float) ($roiAnalytics['total_revenue'] ?? 0),
                'analytics_roi_percent' => $roiAnalytics['roi_percent'] ?? null,
            ],
            'lanes' => $summaryLanes,
            'campaigns' => array_slice($rows, 0, $limit),
            'next_actions' => array_slice($nextActions, 0, $limit),
            'guardrails' => [
                'workspace_scoped' => true,
                'manual_first' => true,
                'external_publish' => false,
                'external_send' => false,
                'external_api_calls' => false,
                'uses_existing_crm_tools' => true,
            ],
            'recommended_product_decision' => 'Treat this loop as the launch control board for revenue: do not call a campaign ready until strategy, audience, content, conversion, distribution, tracking, attribution, handoff, and ROI evidence are connected.',
            'performance' => [
                'detail_limit' => $limit,
                'campaign_query_limit' => max($limit, 12),
                'analytics_window_days' => 90,
                'external_api_calls' => false,
                'page_load_guard' => true,
            ],
            'generated_at' => date('c'),
        ];
    }

    public function generateMarketingActionRouterSnapshot(array $context = [], ?int $userId = null, int $limit = 16): array
    {
        $this->assertMarketingPermission('marketing.write');
        if (!Database::tableExists('marketing_action_router_items')) {
            throw new RuntimeException('Marketing Action Router is unavailable.');
        }
        $userId = $userId ?? $this->currentUserId();
        if ($userId > 0) {
            $this->assertWorkspaceUser($userId, $this->workspaceId());
        }

        $candidates = $this->buildMarketingActionRouterCandidates($userId, $limit, $context);
        $upserted = 0;
        foreach ($candidates as $candidate) {
            $item = $this->normalizeMarketingActionRouterCandidate($candidate, $context);
            $this->assertMarketingActionRouterLinks($item);
            Database::execute(
                "INSERT INTO marketing_action_router_items
                 (workspace_id, uuid, action_key, action_type, action_status, priority, label, reason,
                  recommended_action, source, source_record_type, source_record_id, target_system, target_href,
                  target_record_type, target_record_id, contact_id, company_id, deal_id, campaign_id, form_id,
                  task_id, email_template_id, content_item_id, metadata_json, created_by)
                 VALUES (?, ?, ?, ?, 'suggested', ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
                 ON DUPLICATE KEY UPDATE
                    action_type = VALUES(action_type),
                    action_status = IF(action_status IN ('resolved','dismissed','archived'), action_status, 'suggested'),
                    priority = VALUES(priority),
                    label = VALUES(label),
                    reason = VALUES(reason),
                    recommended_action = VALUES(recommended_action),
                    source = VALUES(source),
                    target_system = VALUES(target_system),
                    target_href = VALUES(target_href),
                    target_record_type = VALUES(target_record_type),
                    target_record_id = VALUES(target_record_id),
                    contact_id = VALUES(contact_id),
                    company_id = VALUES(company_id),
                    deal_id = VALUES(deal_id),
                    campaign_id = VALUES(campaign_id),
                    form_id = VALUES(form_id),
                    task_id = VALUES(task_id),
                    email_template_id = VALUES(email_template_id),
                    content_item_id = VALUES(content_item_id),
                    metadata_json = VALUES(metadata_json),
                    updated_at = CURRENT_TIMESTAMP",
                [
                    $this->workspaceId(),
                    $this->generateUuid(),
                    $item['action_key'],
                    $item['action_type'],
                    $item['priority'],
                    $item['label'],
                    $item['reason'],
                    $item['recommended_action'],
                    $item['source'],
                    $item['source_record_type'],
                    $item['source_record_id'],
                    $item['target_system'],
                    $item['target_href'],
                    $item['target_record_type'],
                    $item['target_record_id'],
                    $item['contact_id'],
                    $item['company_id'],
                    $item['deal_id'],
                    $item['campaign_id'],
                    $item['form_id'],
                    $item['task_id'],
                    $item['email_template_id'],
                    $item['content_item_id'],
                    $this->normalizeJsonValue($this->sanitizeJsonCompatible($item['metadata_json'])),
                    $userId > 0 ? $userId : null,
                ]
            );
            $upserted++;
        }

        return [
            'upserted' => $upserted,
            'items' => $this->listMarketingActionRouterItems(['open' => true], $limit, 0),
            'guardrails' => [
                'manual_first' => true,
                'external_publish' => false,
                'external_send' => false,
                'external_api_calls' => false,
            ],
        ];
    }

    public function listMarketingActionRouterItems(array $filters = [], int $limit = 100, int $offset = 0): array
    {
        $this->assertMarketingPermission('marketing.read');
        if (!Database::tableExists('marketing_action_router_items')) {
            return [];
        }
        $limit = min(max($limit, 1), 250);
        $offset = max($offset, 0);
        $where = ['workspace_id = ?'];
        $params = [$this->workspaceId()];

        if (!empty($filters['id'])) {
            $where[] = 'id = ?';
            $params[] = (int) $filters['id'];
        }
        if (!empty($filters['open'])) {
            $where[] = "action_status IN ('suggested','accepted')";
        } elseif (!empty($filters['action_status'])) {
            $where[] = 'action_status = ?';
            $params[] = $this->normalizeEnum((string) $filters['action_status'], self::ACTION_ROUTER_STATUSES, 'action_router_status');
        } else {
            $where[] = "action_status <> 'archived'";
        }
        if (!empty($filters['action_type'])) {
            $where[] = 'action_type = ?';
            $params[] = $this->normalizeEnum((string) $filters['action_type'], self::ACTION_ROUTER_TYPES, 'action_router_type');
        }
        foreach (['contact_id', 'company_id', 'deal_id', 'campaign_id', 'form_id', 'task_id', 'email_template_id', 'content_item_id'] as $field) {
            if (!empty($filters[$field])) {
                $where[] = "{$field} = ?";
                $params[] = (int) $filters[$field];
            }
        }

        return array_map(
            fn(array $row): array => $this->hydrateMarketingActionRouterRow($row),
            Database::query(
                'SELECT * FROM marketing_action_router_items WHERE ' . implode(' AND ', $where)
                . " ORDER BY FIELD(priority, 'high', 'normal', 'medium', 'low'), updated_at DESC, id DESC LIMIT {$limit} OFFSET {$offset}",
                $params
            )
        );
    }

    public function updateMarketingActionRouterItemStatus(int $id, string $status, string $note = '', ?int $userId = null): bool
    {
        $status = $this->normalizeEnum($status, self::ACTION_ROUTER_STATUSES, 'action_router_status');
        if ($status === 'archived') {
            $this->assertMarketingPermission('marketing.manage');
        } else {
            $this->assertMarketingPermission('marketing.write');
        }
        $item = $this->getMarketingActionRouterItem($id);
        if (!$item) {
            throw new RuntimeException('Marketing Action Router item not found.');
        }
        $userId = $userId ?? $this->currentUserId();
        if ($userId > 0) {
            $this->assertWorkspaceUser($userId, $this->workspaceId());
        }
        $terminal = in_array($status, ['resolved', 'dismissed', 'archived'], true);

        return Database::execute(
            "UPDATE marketing_action_router_items
             SET action_status = ?, status_note = ?, resolved_by = ?, resolved_at = " . ($terminal ? 'NOW()' : 'NULL') . ", updated_at = NOW()
             WHERE workspace_id = ? AND id = ?",
            [
                $status,
                $this->nullableSanitizedText($note),
                $terminal && $userId > 0 ? $userId : null,
                $this->workspaceId(),
                $id,
            ]
        ) > 0;
    }

    public function getMarketingActionRouterItem(int $id): ?array
    {
        $rows = $this->listMarketingActionRouterItems(['id' => $id, 'action_status' => 'suggested'], 1, 0);
        if ($rows !== []) {
            return $rows[0];
        }
        $rows = $this->listMarketingActionRouterItems(['id' => $id], 1, 0);
        return $rows[0] ?? null;
    }

    public function refreshMarketingRelationshipGraph(?int $userId = null): array
    {
        $this->assertMarketingPermission('marketing.write');
        if (!Database::tableExists('marketing_relationship_graph_edges')) {
            throw new RuntimeException('Marketing relationship graph is unavailable.');
        }

        $userId = $userId ?? $this->currentUserId();
        if (($userId ?? 0) > 0) {
            $this->assertWorkspaceUser((int) $userId, $this->workspaceId());
        }

        Database::execute(
            "DELETE FROM marketing_relationship_graph_edges
             WHERE workspace_id = ?
               AND JSON_UNQUOTE(JSON_EXTRACT(metadata_json, '$.source')) = 'marketing_relationship_graph_auto'",
            [$this->workspaceId()]
        );

        $edges = $this->buildMarketingRelationshipGraphEdges();
        $created = 0;
        foreach ($edges as $edge) {
            $this->upsertMarketingRelationshipGraphEdge($edge, $userId);
            $created++;
        }

        return [
            'created' => $created,
            'summary' => $this->getMarketingRelationshipGraphSummary(12),
            'guardrails' => [
                'workspace_scoped' => true,
                'manual_first' => true,
                'external_publish' => false,
                'external_send' => false,
            ],
        ];
    }

    public function listMarketingRelationships(array $filters = [], int $limit = 100, int $offset = 0): array
    {
        $this->assertMarketingPermission('marketing.read');
        if (!Database::tableExists('marketing_relationship_graph_edges')) {
            return [];
        }

        $limit = min(max($limit, 1), 250);
        $offset = max($offset, 0);
        $where = ['workspace_id = ?'];
        $params = [$this->workspaceId()];
        foreach (['source_type', 'target_type'] as $field) {
            if (!empty($filters[$field])) {
                $where[] = "{$field} = ?";
                $params[] = $this->normalizeEnum((string) $filters[$field], self::RELATIONSHIP_RECORD_TYPES, $field);
            }
        }
        if (!empty($filters['relationship_type'])) {
            $where[] = 'relationship_type = ?';
            $params[] = $this->normalizeEnum((string) $filters['relationship_type'], self::RELATIONSHIP_TYPES, 'relationship_type');
        }
        if (!empty($filters['relationship_status'])) {
            $where[] = 'relationship_status = ?';
            $params[] = $this->normalizeEnum((string) $filters['relationship_status'], self::RELATIONSHIP_STATUSES, 'relationship_status');
        } elseif (empty($filters['include_archived'])) {
            $where[] = "relationship_status <> 'archived'";
        }
        foreach (['source_id', 'target_id', 'id'] as $field) {
            if (!empty($filters[$field])) {
                $where[] = "{$field} = ?";
                $params[] = (int) $filters[$field];
            }
        }
        if (!empty($filters['record_type']) && !empty($filters['record_id'])) {
            $recordType = $this->normalizeEnum((string) $filters['record_type'], self::RELATIONSHIP_RECORD_TYPES, 'record_type');
            $recordId = (int) $filters['record_id'];
            $where[] = '((source_type = ? AND source_id = ?) OR (target_type = ? AND target_id = ?))';
            array_push($params, $recordType, $recordId, $recordType, $recordId);
        }

        return array_map(
            fn(array $row): array => $this->hydrateMarketingRelationshipRow($row),
            Database::query(
                'SELECT * FROM marketing_relationship_graph_edges WHERE ' . implode(' AND ', $where)
                . " ORDER BY updated_at DESC, id DESC LIMIT {$limit} OFFSET {$offset}",
                $params
            )
        );
    }

    public function getMarketingRelationship(int $id): ?array
    {
        $rows = $this->listMarketingRelationships(['id' => $id, 'include_archived' => true], 1, 0);
        return $rows[0] ?? null;
    }

    public function createMarketingRelationship(array $data, ?int $userId = null): int
    {
        $this->assertMarketingPermission('marketing.write');
        if (!Database::tableExists('marketing_relationship_graph_edges')) {
            throw new RuntimeException('Marketing relationship graph is unavailable.');
        }
        $userId = $userId ?? $this->currentUserId();
        if (($userId ?? 0) > 0) {
            $this->assertWorkspaceUser((int) $userId, $this->workspaceId());
        }

        $edge = $this->normalizeMarketingRelationshipData($data);
        $edge['metadata_json']['source'] = $edge['metadata_json']['source'] ?? 'manual';
        $this->upsertMarketingRelationshipGraphEdge($edge, $userId);

        return (int) Database::lastInsertId();
    }

    public function archiveMarketingRelationship(int $id): bool
    {
        $this->assertMarketingPermission('marketing.manage');
        if (!Database::tableExists('marketing_relationship_graph_edges')) {
            return false;
        }

        return Database::execute(
            "UPDATE marketing_relationship_graph_edges
             SET relationship_status = 'archived', updated_at = NOW()
             WHERE workspace_id = ? AND id = ?",
            [$this->workspaceId(), $id]
        ) > 0;
    }

    public function getMarketingRelationshipGraphSummary(int $limit = 20): array
    {
        $this->assertMarketingPermission('marketing.read');
        $limit = min(max($limit, 1), 50);
        if (!Database::tableExists('marketing_relationship_graph_edges')) {
            return [
                'counts' => ['edges' => 0, 'record_types' => [], 'relationship_types' => []],
                'edges' => [],
                'orphaned' => [],
                'recommended_actions' => ['Run migration 369 to enable the Marketing Relationship Graph.'],
            ];
        }

        $edgeRows = Database::query(
            "SELECT relationship_type, COUNT(*) AS count
             FROM marketing_relationship_graph_edges
             WHERE workspace_id = ? AND relationship_status <> 'archived'
             GROUP BY relationship_type",
            [$this->workspaceId()]
        );
        $relationshipTypes = [];
        foreach ($edgeRows as $row) {
            $relationshipTypes[(string) $row['relationship_type']] = (int) $row['count'];
        }
        $recordRows = Database::query(
            "SELECT source_type AS record_type, COUNT(*) AS count
             FROM marketing_relationship_graph_edges
             WHERE workspace_id = ? AND relationship_status <> 'archived'
             GROUP BY source_type
             UNION ALL
             SELECT target_type AS record_type, COUNT(*) AS count
             FROM marketing_relationship_graph_edges
             WHERE workspace_id = ? AND relationship_status <> 'archived'
             GROUP BY target_type",
            [$this->workspaceId(), $this->workspaceId()]
        );
        $recordTypes = [];
        foreach ($recordRows as $row) {
            $recordTypes[(string) $row['record_type']] = (int) ($recordTypes[(string) $row['record_type']] ?? 0) + (int) $row['count'];
        }
        $total = array_sum($relationshipTypes);
        $orphaned = $this->detectMarketingRelationshipOrphans();
        $recommended = [];
        if ($total === 0) {
            $recommended[] = 'Refresh the relationship graph after adding campaigns, content, landing pages, assets, or distribution records.';
        }
        foreach (array_slice($orphaned, 0, 3) as $orphan) {
            $recommended[] = (string) ($orphan['label'] ?? 'Review orphaned marketing record.');
        }

        return [
            'counts' => [
                'edges' => $total,
                'record_types' => $recordTypes,
                'relationship_types' => $relationshipTypes,
                'orphaned' => count($orphaned),
            ],
            'edges' => $this->listMarketingRelationships([], $limit, 0),
            'orphaned' => array_slice($orphaned, 0, $limit),
            'recommended_actions' => $recommended,
            'guardrails' => [
                'workspace_scoped' => true,
                'manual_first' => true,
                'external_publish' => false,
                'external_send' => false,
            ],
        ];
    }

    public function getMarketingRelationshipMapForRecord(string $recordType, int $recordId, int $limit = 25): array
    {
        $this->assertMarketingPermission('marketing.read');
        $recordType = $this->normalizeEnum($recordType, self::RELATIONSHIP_RECORD_TYPES, 'record_type');
        $this->assertMarketingRelationshipRecord($recordType, $recordId, $this->workspaceId());

        return [
            'record_type' => $recordType,
            'record_id' => $recordId,
            'relationships' => $this->listMarketingRelationships([
                'record_type' => $recordType,
                'record_id' => $recordId,
            ], $limit, 0),
        ];
    }

    public function getMarketingGuidedRecommendations(?int $userId = null, int $limit = 12, ?array $aiWorkspaceBrain = null): array
    {
        $this->assertMarketingPermission('marketing.read');
        $userId = $userId ?? ($this->currentUserId() ?: null);
        $limit = min(max($limit, 1), 25);
        $aiWorkspaceBrain = $aiWorkspaceBrain ?? $this->getMarketingAiWorkspaceBrain($userId);
        $workflowClosure = Database::tableExists('marketing_content_items') ? $this->getMarketingWorkflowClosureSummary(100) : ['counts' => [], 'next_actions' => []];
        $closureCounts = (array) ($workflowClosure['counts'] ?? []);
        $brainCoverage = (array) ($aiWorkspaceBrain['coverage'] ?? []);
        $brainCounts = (array) ($aiWorkspaceBrain['counts'] ?? []);

        $landingMissingHero = 0;
        $landingMissingSocial = 0;
        if (Database::tableExists('marketing_landing_pages') && Database::columnExists('marketing_landing_pages', 'hero_media_file_id')) {
            $statusCondition = Database::columnExists('marketing_landing_pages', 'status') ? "status <> 'archived' AND " : '';
            $landingMissingHero = $this->marketingWorkspaceRecordCount('marketing_landing_pages', $statusCondition . 'hero_media_file_id IS NULL');
        }
        if (Database::tableExists('marketing_landing_pages') && Database::columnExists('marketing_landing_pages', 'social_preview_media_file_id')) {
            $statusCondition = Database::columnExists('marketing_landing_pages', 'status') ? "status <> 'archived' AND " : '';
            $landingMissingSocial = $this->marketingWorkspaceRecordCount('marketing_landing_pages', $statusCondition . 'social_preview_media_file_id IS NULL');
        }

        $recommendations = [];
        $seen = [];
        $addRecommendation = static function (
            array &$recommendations,
            array &$seen,
            string $key,
            string $label,
            string $href,
            string $reason,
            string $priority,
            string $category,
            int $evidenceCount = 0,
            string $productDecision = ''
        ): void {
            if (isset($seen[$key])) {
                return;
            }
            $seen[$key] = true;
            $priority = in_array($priority, ['high', 'normal', 'medium', 'low'], true) ? $priority : 'normal';
            $recommendations[] = [
                'key' => $key,
                'label' => $label,
                'href' => $href,
                'reason' => $reason,
                'priority' => $priority,
                'category' => $category,
                'source' => 'Guided Recommendations',
                'evidence_count' => $evidenceCount,
                'product_decision' => $productDecision,
            ];
        };

        if ((int) ($aiWorkspaceBrain['score'] ?? 0) < 80) {
            $addRecommendation(
                $recommendations,
                $seen,
                'complete_ai_workspace_context',
                'Complete AI Workspace Context',
                'marketing_assistants.php',
                'AI is missing the workspace context it needs to make dependable recommendations.',
                'high',
                'ai_context',
                count((array) ($aiWorkspaceBrain['missing_context'] ?? [])),
                'Treat the AI Workspace Brain as the readiness gate for assistant-driven strategy and copy decisions.'
            );
        }
        if (($brainCoverage['campaign_strategy']['status'] ?? 'missing') !== 'ready') {
            $addRecommendation(
                $recommendations,
                $seen,
                'strengthen_campaign_strategy',
                'Strengthen Campaign Strategy',
                'marketing_campaign_workspace.php',
                'Campaign, brief, and audience strategy are not complete enough for confident launch planning.',
                'high',
                'strategy',
                (int) ($brainCounts['campaign_briefs'] ?? 0),
                'Use campaign briefs and audience segments as the operating anchor before producing more content.'
            );
        }
        if ((int) ($brainCounts['content_items'] ?? 0) === 0) {
            $addRecommendation(
                $recommendations,
                $seen,
                'create_first_content_item',
                'Create First Content Item',
                'marketing_content_edit.php',
                'Content Studio has no active content for this workspace yet.',
                'normal',
                'content',
                0,
                'Start with one content item tied to a campaign brief instead of creating disconnected drafts.'
            );
        }
        if ((int) ($closureCounts['missing_cta'] ?? 0) > 0) {
            $addRecommendation(
                $recommendations,
                $seen,
                'add_clear_content_ctas',
                'Add Clear Content CTAs',
                'marketing_content.php',
                'Some content drafts do not contain a clear next-step CTA.',
                'high',
                'content_quality',
                (int) ($closureCounts['missing_cta'] ?? 0),
                'Every campaign asset should make the next action explicit before review or export.'
            );
        }
        if ((int) ($closureCounts['missing_media'] ?? 0) > 0 || $landingMissingHero > 0 || $landingMissingSocial > 0) {
            $addRecommendation(
                $recommendations,
                $seen,
                'resolve_media_readiness',
                'Resolve Media Readiness',
                'marketing_assets.php',
                'Content or landing pages are missing recommended images, videos, alt text, captions, or preview media.',
                'high',
                'media',
                (int) ($closureCounts['missing_media'] ?? 0) + $landingMissingHero + $landingMissingSocial,
                'Make media readiness visible before manual exports so operators do not publish incomplete assets.'
            );
        }
        if ((int) ($closureCounts['pending_reviews'] ?? 0) > 0 || (int) ($closureCounts['overdue_reviews'] ?? 0) > 0) {
            $addRecommendation(
                $recommendations,
                $seen,
                'clear_review_queue',
                'Clear Review Queue',
                ((int) ($closureCounts['overdue_reviews'] ?? 0) > 0) ? 'marketing_reviews.php?queue=overdue' : 'marketing_reviews.php?queue=pending',
                'Content reviews are pending or overdue.',
                ((int) ($closureCounts['overdue_reviews'] ?? 0) > 0) ? 'high' : 'normal',
                'review',
                (int) ($closureCounts['pending_reviews'] ?? 0) + (int) ($closureCounts['overdue_reviews'] ?? 0),
                'Keep review approvals as a human checkpoint before AI-assisted or manual launch work moves forward.'
            );
        }
        if ((int) ($closureCounts['missing_distribution'] ?? 0) > 0) {
            $addRecommendation(
                $recommendations,
                $seen,
                'create_distribution_variants',
                'Create Distribution Variants',
                'marketing_distribution.php',
                'Approved or scheduled content is missing manual distribution drafts.',
                'normal',
                'distribution',
                (int) ($closureCounts['missing_distribution'] ?? 0),
                'Distribution should package content for manual execution without calling external publishing APIs.'
            );
        }
        if ((int) ($closureCounts['missing_utm'] ?? 0) > 0 || ((int) ($brainCounts['utm_links'] ?? 0) === 0 && (int) ($brainCounts['distribution_posts'] ?? 0) > 0)) {
            $addRecommendation(
                $recommendations,
                $seen,
                'create_utm_tracking',
                'Create UTM Tracking',
                'marketing_utm_links.php',
                'Distribution or campaign-linked content needs UTM links before performance can be trusted.',
                'normal',
                'analytics',
                (int) ($closureCounts['missing_utm'] ?? 0),
                'Tracking links should be ready before exports leave the CRM.'
            );
        }
        if (($brainCoverage['landing_conversion']['status'] ?? 'missing') !== 'ready') {
            $addRecommendation(
                $recommendations,
                $seen,
                'improve_landing_conversion_context',
                'Improve Landing Conversion Context',
                'marketing_landing_pages.php',
                'Landing pages, forms, conversion goals, or tracking signals are incomplete.',
                'normal',
                'conversion',
                (int) ($brainCounts['landing_pages'] ?? 0),
                'Landing plans should include the conversion goal and capture path before launch.'
            );
        }
        if (($brainCoverage['crm_integration']['status'] ?? 'missing') !== 'ready') {
            $addRecommendation(
                $recommendations,
                $seen,
                'review_cross_system_integration',
                'Review Cross-System Integration',
                'marketing_admin.php',
                'Marketing is missing some CRM connections for campaigns, forms, attribution, handoff, or task context.',
                'normal',
                'integration',
                (int) ($aiWorkspaceBrain['integration_summary']['counts']['system_connections_attention'] ?? 0) + (int) ($aiWorkspaceBrain['integration_summary']['counts']['system_connections_missing'] ?? 0),
                'Keep Marketing recommendations connected to the rest of the CRM instead of becoming a standalone content island.'
            );
        }
        if (($brainCoverage['automation_independence']['status'] ?? 'missing') !== 'ready') {
            $addRecommendation(
                $recommendations,
                $seen,
                'prepare_manual_automation_loops',
                'Prepare Manual Automation Loops',
                'marketing_operations.php',
                'Reminder, review, export, report, and dry-run loops are not all ready for operator-controlled cadence.',
                'normal',
                'automation',
                (int) ($aiWorkspaceBrain['automation_summary']['counts']['attention'] ?? 0) + (int) ($aiWorkspaceBrain['automation_summary']['counts']['missing'] ?? 0),
                'Automation should stay system-independent and manual-first until connectors and explicit approvals are ready.'
            );
        }
        if ($recommendations === []) {
            $addRecommendation(
                $recommendations,
                $seen,
                'review_performance_and_roi',
                'Review Performance And ROI',
                'marketing_performance.php',
                'Core setup, content, distribution, and governance signals are ready enough to review performance.',
                'low',
                'analytics',
                0,
                'When the operating system is healthy, shift attention from setup to performance learning.'
            );
        }

        $priorityRank = ['high' => 3, 'normal' => 2, 'medium' => 2, 'low' => 1];
        usort($recommendations, static function (array $left, array $right) use ($priorityRank): int {
            $leftRank = $priorityRank[(string) ($left['priority'] ?? 'normal')] ?? 2;
            $rightRank = $priorityRank[(string) ($right['priority'] ?? 'normal')] ?? 2;
            if ($leftRank !== $rightRank) {
                return $rightRank <=> $leftRank;
            }

            return strcmp((string) ($left['label'] ?? ''), (string) ($right['label'] ?? ''));
        });
        $recommendations = array_slice($recommendations, 0, $limit);
        $counts = ['high' => 0, 'normal' => 0, 'medium' => 0, 'low' => 0, 'total' => count($recommendations)];
        foreach ($recommendations as $recommendation) {
            $priority = (string) ($recommendation['priority'] ?? 'normal');
            $counts[$priority] = (int) ($counts[$priority] ?? 0) + 1;
        }

        return [
            'recommendations' => $recommendations,
            'counts' => $counts,
            'workflow_closure' => [
                'status' => (string) ($workflowClosure['status'] ?? 'clear'),
                'counts' => $closureCounts,
                'next_actions' => (array) ($workflowClosure['next_actions'] ?? []),
            ],
            'ai_workspace_brain' => [
                'score' => (int) ($aiWorkspaceBrain['score'] ?? 0),
                'status' => (string) ($aiWorkspaceBrain['status'] ?? 'thin'),
                'missing_context' => array_slice((array) ($aiWorkspaceBrain['missing_context'] ?? []), 0, 6),
            ],
            'manual_first_boundary' => [
                'external_publish' => false,
                'external_send' => false,
                'external_api_call' => false,
                'operator_decision_required' => true,
            ],
            'recommended_product_decision' => 'Use guided recommendations as the operator-facing queue that turns Marketing diagnostics into the next best manual action.',
            'generated_at' => date('c'),
        ];
    }

    public function getMarketingWorkbenchSummary(?int $userId = null): array
    {
        $userId = $userId ?? $this->currentUserId();
        $hasUser = $userId > 0;
        $assignedItems = $hasUser
            ? $this->listContentItems(['owner_user_id' => $userId, 'exclude_status' => 'archived'], 6, 0)
            : [];
        $pendingReviews = Database::tableExists('marketing_content_approvals')
            ? $this->listContentApprovals($hasUser ? ['reviewer_user_id' => $userId, 'status' => 'pending'] : ['status' => 'pending'], 6, 0)
            : [];
        $upcomingCalendar = Database::tableExists('marketing_calendar_milestones')
            ? $this->listCalendarMilestones(($hasUser ? ['owner_user_id' => $userId] : []) + [
                'date_from' => date('Y-m-d'),
                'date_to' => date('Y-m-d', strtotime('+14 days')),
                'status' => 'planned',
            ], 6, 0)
            : [];
        $blockedItems = $this->listContentItems(($hasUser ? ['owner_user_id' => $userId] : []) + [
            'blocked' => true,
            'exclude_status' => 'archived',
        ], 6, 0);

        $nextActions = [];
        if ($assignedItems === []) {
            $nextActions[] = ['label' => 'Create or assign content', 'href' => 'marketing_content_edit.php'];
        }
        if ($pendingReviews !== []) {
            $nextActions[] = ['label' => 'Review pending approvals', 'href' => 'marketing_reviews.php'];
        }
        if ($upcomingCalendar === []) {
            $nextActions[] = ['label' => 'Add a calendar milestone', 'href' => 'marketing_calendar.php'];
        }
        if ($blockedItems !== []) {
            $nextActions[] = ['label' => 'Resolve blocked content', 'href' => 'marketing_content.php?blocked=1'];
        }
        if ($nextActions === []) {
            $nextActions[] = ['label' => 'Open Content Studio', 'href' => 'marketing_content.php'];
        }

        return [
            'preferences' => $hasUser ? $this->getWorkbenchPreferences($userId) : ['default_view_mode' => 'list'],
            'saved_views' => $hasUser ? $this->listSavedViews('content', $userId) : [],
            'assigned_items' => $assignedItems,
            'pending_reviews' => $pendingReviews,
            'upcoming_calendar' => $upcomingCalendar,
            'blocked_items' => $blockedItems,
            'next_actions' => $nextActions,
            'counts' => [
                'assigned_items' => count($assignedItems),
                'pending_reviews' => count($pendingReviews),
                'upcoming_calendar' => count($upcomingCalendar),
                'blocked_items' => count($blockedItems),
            ],
        ];
    }

    public function getMarketingWorkflowClosureSummary(int $limit = 100): array
    {
        $limit = min(max($limit, 1), 250);
        $items = $this->listContentItems(['exclude_status' => 'archived'], $limit, 0);
        $pendingReviews = Database::tableExists('marketing_content_approvals') ? $this->listContentApprovals(['queue' => 'pending'], 250, 0) : [];
        $overdueReviews = Database::tableExists('marketing_content_approvals') ? $this->listContentApprovals(['queue' => 'overdue'], 250, 0) : [];
        $blockedReviews = Database::tableExists('marketing_content_approvals') ? $this->listContentApprovals(['queue' => 'blocked'], 250, 0) : [];
        $distributionPosts = Database::tableExists('marketing_distribution_posts') ? $this->listDistributionPosts(['open' => true], 250, 0) : [];
        $utmLinks = Database::tableExists('marketing_utm_links') ? $this->listUtmLinks([], 250, 0) : [];

        $pendingApprovalContent = [];
        foreach (array_merge($pendingReviews, $overdueReviews, $blockedReviews) as $approval) {
            $contentId = (int) ($approval['content_item_id'] ?? 0);
            if ($contentId > 0) {
                $pendingApprovalContent[$contentId] = true;
            }
        }

        $distributionByContent = [];
        foreach ($distributionPosts as $post) {
            $contentId = (int) ($post['content_item_id'] ?? 0);
            if ($contentId > 0) {
                $distributionByContent[$contentId] = true;
            }
        }

        $utmByContent = [];
        foreach ($utmLinks as $link) {
            $contentId = (int) ($link['content_item_id'] ?? 0);
            if ($contentId > 0) {
                $utmByContent[$contentId] = true;
            }
        }

        $counts = [
            'active_content' => count($items),
            'blocked_content' => 0,
            'pending_reviews' => count($pendingReviews),
            'overdue_reviews' => count($overdueReviews),
            'blocked_reviews' => count($blockedReviews),
            'open_distribution' => count($distributionPosts),
            'missing_audience' => 0,
            'missing_cta' => 0,
            'missing_media' => 0,
            'missing_approval' => 0,
            'missing_distribution' => 0,
            'missing_utm' => 0,
            'items_with_next_action' => 0,
        ];
        $closureItems = [];
        $reasonCounts = [];

        foreach ($items as $item) {
            $contentId = (int) ($item['id'] ?? 0);
            $flags = [
                'has_pending_approval' => isset($pendingApprovalContent[$contentId]),
                'has_distribution' => isset($distributionByContent[$contentId]),
                'has_utm' => isset($utmByContent[$contentId]),
            ];
            $closure = $this->workflowClosureForContent($item, $flags);
            foreach ((array) ($closure['count_keys'] ?? []) as $countKey) {
                if (isset($counts[$countKey])) {
                    $counts[$countKey]++;
                }
            }
            if (!empty($item['next_action'])) {
                $counts['items_with_next_action']++;
            }
            foreach ((array) ($closure['reason_keys'] ?? []) as $reasonKey) {
                $reasonCounts[$reasonKey] = ($reasonCounts[$reasonKey] ?? 0) + 1;
            }
            if (!empty($closure['reasons'])) {
                $closureItems[] = [
                    'type' => 'content',
                    'id' => $contentId,
                    'title' => (string) ($item['title'] ?? 'Untitled content'),
                    'status' => (string) ($item['status'] ?? ''),
                    'severity' => (string) ($closure['severity'] ?? 'warning'),
                    'reasons' => (array) ($closure['reasons'] ?? []),
                    'next_action' => (string) ($closure['next_action'] ?? 'Review the content workflow blockers.'),
                    'href' => 'marketing_content_view.php?id=' . $contentId,
                ];
            }
        }

        usort($closureItems, static function (array $left, array $right): int {
            $weights = ['blocked' => 3, 'overdue' => 2, 'warning' => 1, 'ready' => 0];
            return ($weights[$right['severity']] ?? 0) <=> ($weights[$left['severity']] ?? 0);
        });

        $nextActions = [];
        if ($counts['overdue_reviews'] > 0) {
            $nextActions[] = ['label' => 'Review overdue approvals', 'href' => 'marketing_reviews.php?queue=overdue'];
        }
        if ($counts['blocked_content'] > 0 || $counts['blocked_reviews'] > 0) {
            $nextActions[] = ['label' => 'Resolve blocked content', 'href' => 'marketing_content.php?blocked=1'];
        }
        if ($counts['missing_audience'] > 0) {
            $nextActions[] = ['label' => 'Add audience or persona context', 'href' => 'marketing_personas.php'];
        }
        if ($counts['missing_media'] > 0) {
            $nextActions[] = ['label' => 'Attach or approve media', 'href' => 'marketing_assets.php'];
        }
        if ($counts['missing_distribution'] > 0) {
            $nextActions[] = ['label' => 'Create manual distribution drafts', 'href' => 'marketing_distribution.php'];
        }
        if ($nextActions === []) {
            $nextActions[] = ['label' => 'Open Content Studio', 'href' => 'marketing_content.php'];
        }

        return [
            'status' => ($counts['blocked_content'] + $counts['overdue_reviews'] + $counts['blocked_reviews']) > 0
                ? 'blocked'
                : ($closureItems !== [] ? 'needs_attention' : 'clear'),
            'counts' => $counts,
            'reason_counts' => $reasonCounts,
            'closure_items' => array_slice($closureItems, 0, 12),
            'review_queues' => [
                'pending' => ['count' => $counts['pending_reviews'], 'href' => 'marketing_reviews.php?queue=pending'],
                'overdue' => ['count' => $counts['overdue_reviews'], 'href' => 'marketing_reviews.php?queue=overdue'],
                'blocked' => ['count' => $counts['blocked_reviews'], 'href' => 'marketing_reviews.php?queue=blocked'],
            ],
            'next_actions' => array_slice($nextActions, 0, 6),
            'manual_first_boundary' => [
                'external_publish' => false,
                'external_send' => false,
                'operator_decision_required' => true,
            ],
        ];
    }

    public function getMarketingTaskHub(?int $userId = null, array $filters = []): array
    {
        $this->assertMarketingPermission('marketing.read');
        $userId = $userId ?? $this->currentUserId();
        $hasUser = ($userId ?? 0) > 0;
        if ($hasUser) {
            $this->assertWorkspaceUser((int) $userId, $this->workspaceId());
        }

        $preferences = $hasUser ? $this->getMarketingTaskHubPreferences((int) $userId) : $this->defaultMarketingTaskHubPreferences();
        $includeTeam = (bool) ($filters['include_team_items'] ?? $preferences['include_team_items'] ?? false);
        $ownerFilter = ($hasUser && !$includeTeam) ? ['owner_user_id' => (int) $userId] : [];
        $reviewerFilter = ($hasUser && !$includeTeam) ? ['reviewer_user_id' => (int) $userId] : [];

        $assignedContent = $hasUser
            ? $this->listContentItems($ownerFilter + ['exclude_status' => 'archived'], 12, 0)
            : [];
        $dueContent = $this->listTaskHubDueContent($includeTeam ? null : ($hasUser ? (int) $userId : null), 12);
        $pendingReviews = Database::tableExists('marketing_content_approvals')
            ? $this->listContentApprovals($reviewerFilter + ['status' => 'pending'], 12, 0)
            : [];
        $overdueReviews = Database::tableExists('marketing_content_approvals')
            ? $this->listContentApprovals($reviewerFilter + ['queue' => 'overdue'], 12, 0)
            : [];
        $upcomingCalendar = Database::tableExists('marketing_calendar_milestones')
            ? $this->listCalendarMilestones(($includeTeam ? [] : $ownerFilter) + [
                'date_from' => date('Y-m-d'),
                'date_to' => date('Y-m-d', strtotime('+14 days')),
                'status' => 'planned',
            ], 12, 0)
            : [];
        $blockedContent = $this->listContentItems(($includeTeam ? [] : $ownerFilter) + [
            'blocked' => true,
            'exclude_status' => 'archived',
        ], 12, 0);
        $blockedLaunches = Database::tableExists('marketing_launch_control_records')
            ? $this->listLaunchControlRecords(['status' => 'blocked'], 12, 0)
            : [];
        $guided = Database::tableExists('marketing_guided_workflows') ? $this->getGuidedMarketingWorkflowSummary() : ['next_actions' => []];
        $recentActions = $this->listTaskHubActionLog(8);

        $suggestedActions = [];
        if ($overdueReviews !== []) {
            $suggestedActions[] = ['label' => 'Clear overdue reviews', 'href' => 'marketing_task_hub.php?queue=overdue'];
        }
        if ($blockedLaunches !== []) {
            $suggestedActions[] = ['label' => 'Resolve blocked launches', 'href' => 'marketing_launch_control.php?status=blocked'];
        }
        if ($dueContent !== []) {
            $suggestedActions[] = ['label' => 'Work due content', 'href' => 'marketing_task_hub.php?queue=my_work'];
        }
        foreach (array_slice((array) ($guided['next_actions'] ?? []), 0, 2) as $action) {
            $suggestedActions[] = ['label' => (string) ($action['label'] ?? 'Review guided workflow'), 'href' => (string) ($action['href'] ?? 'marketing_guided_workflows.php')];
        }
        if ($suggestedActions === []) {
            $suggestedActions[] = ['label' => 'Open guided workflows', 'href' => 'marketing_guided_workflows.php'];
        }

        return [
            'preferences' => $preferences,
            'include_team_items' => $includeTeam,
            'queues' => [
                'assigned_content' => $assignedContent,
                'due_content' => $dueContent,
                'pending_reviews' => $pendingReviews,
                'overdue_reviews' => $overdueReviews,
                'upcoming_calendar' => $upcomingCalendar,
                'blocked_content' => $blockedContent,
                'blocked_launches' => $blockedLaunches,
                'guided_actions' => (array) ($guided['next_actions'] ?? []),
                'recent_actions' => $recentActions,
            ],
            'suggested_actions' => $suggestedActions,
            'counts' => [
                'assigned_content' => count($assignedContent),
                'due_content' => count($dueContent),
                'pending_reviews' => count($pendingReviews),
                'overdue_reviews' => count($overdueReviews),
                'upcoming_calendar' => count($upcomingCalendar),
                'blocked_content' => count($blockedContent),
                'blocked_launches' => count($blockedLaunches),
                'guided_actions' => count((array) ($guided['next_actions'] ?? [])),
            ],
        ];
    }

    public function getMarketingTaskHubPreferences(int $userId): array
    {
        $this->assertMarketingPermission('marketing.read');
        $this->assertWorkspaceUser($userId, $this->workspaceId());
        if (!Database::tableExists('marketing_task_hub_preferences')) {
            return $this->defaultMarketingTaskHubPreferences();
        }

        $row = Database::queryOne(
            'SELECT * FROM marketing_task_hub_preferences WHERE workspace_id = ? AND user_id = ? LIMIT 1',
            [$this->workspaceId(), $userId]
        );
        if (!$row) {
            return $this->defaultMarketingTaskHubPreferences();
        }

        return $this->hydrateJsonFields($row, ['filters_json', 'sort_json']) + $this->defaultMarketingTaskHubPreferences();
    }

    public function updateMarketingTaskHubPreferences(int $userId, array $data): array
    {
        $this->assertMarketingPermission('marketing.write');
        $this->assertWorkspaceUser($userId, $this->workspaceId());
        if (!Database::tableExists('marketing_task_hub_preferences')) {
            throw new RuntimeException('Marketing Task Hub preferences are unavailable.');
        }

        $defaultQueue = $this->normalizeEnum((string) ($data['default_queue'] ?? 'my_work'), self::TASK_HUB_QUEUES, 'task_hub_queue');
        $includeTeam = !empty($data['include_team_items']) ? 1 : 0;
        $filters = $this->sanitizeFlexibleArray($data['filters'] ?? $data['filters_json'] ?? []);
        $sort = $this->sanitizeFlexibleArray($data['sort'] ?? $data['sort_json'] ?? []);

        Database::execute(
            "INSERT INTO marketing_task_hub_preferences
             (workspace_id, user_id, default_queue, include_team_items, filters_json, sort_json)
             VALUES (?, ?, ?, ?, ?, ?)
             ON DUPLICATE KEY UPDATE
                default_queue = VALUES(default_queue),
                include_team_items = VALUES(include_team_items),
                filters_json = VALUES(filters_json),
                sort_json = VALUES(sort_json)",
            [
                $this->workspaceId(),
                $userId,
                $defaultQueue,
                $includeTeam,
                $this->normalizeJsonValue($filters),
                $this->normalizeJsonValue($sort),
            ]
        );

        return $this->getMarketingTaskHubPreferences($userId);
    }

    public function recordMarketingTaskHubAction(string $itemType, ?int $itemId, string $actionType, array $newState = [], string $note = '', ?int $userId = null): int
    {
        $this->assertMarketingPermission('marketing.write');
        if (!Database::tableExists('marketing_task_hub_action_log')) {
            throw new RuntimeException('Marketing Task Hub action log is unavailable.');
        }

        $itemType = $this->normalizeTaskHubItemType($itemType);
        $actionType = $this->normalizeEnum($actionType, self::TASK_HUB_ACTION_TYPES, 'task_hub_action_type');
        if (($itemId ?? 0) > 0) {
            $this->assertTaskHubItemBelongsToWorkspace($itemType, (int) $itemId);
        }
        $userId = $userId ?? $this->currentUserId();
        if (($userId ?? 0) > 0) {
            $this->assertWorkspaceUser((int) $userId, $this->workspaceId());
        }

        Database::execute(
            "INSERT INTO marketing_task_hub_action_log
             (workspace_id, item_type, item_id, action_type, old_state_json, new_state_json, note, created_by)
             VALUES (?, ?, ?, ?, ?, ?, ?, ?)",
            [
                $this->workspaceId(),
                $itemType,
                ($itemId ?? 0) > 0 ? (int) $itemId : null,
                $actionType,
                $this->normalizeJsonValue([]),
                $this->normalizeJsonValue($this->sanitizeFlexibleArray($newState)),
                Security::sanitizeInput($note, 'string'),
                ($userId ?? 0) > 0 ? (int) $userId : null,
            ]
        );

        return (int) Database::lastInsertId();
    }

    public function listMarketingCampaignWorkspaces(array $filters = [], int $limit = 100, int $offset = 0): array
    {
        $this->assertMarketingPermission('marketing.read');
        if (!Database::tableExists('campaigns')) {
            return [];
        }

        $limit = min(max($limit, 1), 250);
        $offset = max($offset, 0);
        $where = ['c.workspace_id = ?'];
        $params = [$this->workspaceId()];
        if (!empty($filters['campaign_id'])) {
            $where[] = 'c.id = ?';
            $params[] = (int) $filters['campaign_id'];
        }
        if (!empty($filters['campaign_status'])) {
            $where[] = 'c.status = ?';
            $params[] = $this->normalizeEnum((string) $filters['campaign_status'], ['draft', 'active', 'paused', 'completed', 'archived'], 'campaign_status');
        }
        if (!empty($filters['open'])) {
            $where[] = "c.status IN ('draft','active','paused')";
        }

        $hasWorkspaceTable = Database::tableExists('marketing_campaign_workspaces');
        $workspaceSelect = $hasWorkspaceTable
            ? "cw.id AS cw_id, cw.uuid AS cw_uuid, cw.workspace_name AS cw_workspace_name, cw.status AS cw_status,
               cw.health_score AS cw_health_score, cw.readiness_json AS cw_readiness_json,
               cw.linked_summary_json AS cw_linked_summary_json, cw.missing_requirements_json AS cw_missing_requirements_json,
               cw.warning_json AS cw_warning_json, cw.next_actions_json AS cw_next_actions_json,
               cw.metadata_json AS cw_metadata_json, cw.owner_user_id AS cw_owner_user_id,
               cw.refreshed_by AS cw_refreshed_by, cw.refreshed_at AS cw_refreshed_at,
               cw.created_by AS cw_created_by, cw.created_at AS cw_created_at, cw.updated_at AS cw_updated_at,
               owner.email AS owner_email, refresher.email AS refreshed_by_email"
            : "NULL AS cw_id, NULL AS cw_uuid, NULL AS cw_workspace_name, NULL AS cw_status,
               NULL AS cw_health_score, NULL AS cw_readiness_json, NULL AS cw_linked_summary_json,
               NULL AS cw_missing_requirements_json, NULL AS cw_warning_json, NULL AS cw_next_actions_json,
               NULL AS cw_metadata_json, NULL AS cw_owner_user_id, NULL AS cw_refreshed_by, NULL AS cw_refreshed_at,
               NULL AS cw_created_by, NULL AS cw_created_at, NULL AS cw_updated_at,
               NULL AS owner_email, NULL AS refreshed_by_email";
        $workspaceJoin = $hasWorkspaceTable
            ? "LEFT JOIN marketing_campaign_workspaces cw ON cw.campaign_id = c.id AND cw.workspace_id = c.workspace_id
               LEFT JOIN users owner ON owner.id = cw.owner_user_id
               LEFT JOIN users refresher ON refresher.id = cw.refreshed_by"
            : '';
        $orderStatusExpression = $hasWorkspaceTable ? 'COALESCE(cw.status, c.status)' : 'c.status';

        $rows = Database::query(
            "SELECT c.id AS campaign_id, c.uuid AS campaign_uuid, c.name AS campaign_name,
                    c.description AS campaign_description, c.objective AS campaign_objective,
                    c.channel_mix AS campaign_channel_mix, c.status AS campaign_status,
                    c.scheduled_start_at AS campaign_start_at, c.scheduled_end_at AS campaign_end_at,
                    c.created_by AS campaign_created_by, c.created_at AS campaign_created_at,
                    c.updated_at AS campaign_updated_at, creator.email AS campaign_created_by_email,
                    {$workspaceSelect}
             FROM campaigns c
             {$workspaceJoin}
             LEFT JOIN users creator ON creator.id = c.created_by
             WHERE " . implode(' AND ', $where) . "
             ORDER BY
                CASE {$orderStatusExpression}
                    WHEN 'blocked' THEN 0
                    WHEN 'ready' THEN 1
                    WHEN 'active' THEN 2
                    WHEN 'draft' THEN 3
                    WHEN 'launched' THEN 4
                    WHEN 'completed' THEN 5
                    ELSE 6
                END ASC,
                c.updated_at DESC
             LIMIT {$limit} OFFSET {$offset}",
            $params
        );

        $statusFilter = trim((string) ($filters['status'] ?? ''));
        $statusFilter = $statusFilter !== ''
            ? $this->normalizeEnum($statusFilter, self::CAMPAIGN_WORKSPACE_STATUSES, 'campaign_workspace_status')
            : '';
        $needsAttention = !empty($filters['needs_attention']);
        $workspaces = [];
        foreach ($rows as $row) {
            $campaign = $this->campaignFromWorkspaceRow($row);
            $workspace = (int) ($row['cw_id'] ?? 0) > 0
                ? $this->hydrateCampaignWorkspaceRow($row)
                : $this->buildMarketingCampaignWorkspace($campaign);
            if ($statusFilter !== '' && (string) ($workspace['status'] ?? '') !== $statusFilter) {
                continue;
            }
            if ($needsAttention && (int) ($workspace['health_score'] ?? 0) >= 85 && empty($workspace['missing_requirements_json'])) {
                continue;
            }
            $workspaces[] = $workspace;
        }

        return $workspaces;
    }

    public function getMarketingCampaignWorkspace(int $campaignId, bool $refresh = false, ?int $userId = null): ?array
    {
        $this->assertMarketingPermission('marketing.read');
        if ($refresh) {
            return $this->refreshMarketingCampaignWorkspace($campaignId, $userId);
        }

        $rows = $this->listMarketingCampaignWorkspaces(['campaign_id' => $campaignId], 1, 0);

        return $rows[0] ?? null;
    }

    public function refreshMarketingCampaignWorkspace(int $campaignId, ?int $userId = null): array
    {
        $this->assertMarketingPermission('marketing.write');
        if (!Database::tableExists('marketing_campaign_workspaces')) {
            throw new RuntimeException('Marketing Campaign Workspace is unavailable.');
        }
        $campaign = $this->getCampaignForWorkspace($campaignId);
        if (!$campaign) {
            throw new RuntimeException('Campaign was not found in the active workspace.');
        }
        $userId = $userId ?? $this->currentUserId();
        if (($userId ?? 0) > 0) {
            $this->assertWorkspaceUser((int) $userId, $this->workspaceId());
        }

        $workspace = $this->buildMarketingCampaignWorkspace($campaign);
        $workspace['metadata_json']['virtual_until_refreshed'] = false;
        $workspace['metadata_json']['refreshed_at'] = date('c');
        Database::execute(
            "INSERT INTO marketing_campaign_workspaces
             (workspace_id, campaign_id, uuid, workspace_name, status, health_score, readiness_json,
              linked_summary_json, missing_requirements_json, warning_json, next_actions_json, metadata_json,
              owner_user_id, refreshed_by, refreshed_at, created_by)
             VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, NOW(), ?)
             ON DUPLICATE KEY UPDATE
                workspace_name = VALUES(workspace_name),
                status = VALUES(status),
                health_score = VALUES(health_score),
                readiness_json = VALUES(readiness_json),
                linked_summary_json = VALUES(linked_summary_json),
                missing_requirements_json = VALUES(missing_requirements_json),
                warning_json = VALUES(warning_json),
                next_actions_json = VALUES(next_actions_json),
                metadata_json = VALUES(metadata_json),
                owner_user_id = VALUES(owner_user_id),
                refreshed_by = VALUES(refreshed_by),
                refreshed_at = NOW()",
            [
                $this->workspaceId(),
                $campaignId,
                $this->generateUuid(),
                $workspace['workspace_name'],
                $workspace['status'],
                (int) $workspace['health_score'],
                $this->normalizeJsonValue($workspace['readiness_json']),
                $this->normalizeJsonValue($workspace['linked_summary_json']),
                $this->normalizeJsonValue($workspace['missing_requirements_json']),
                $this->normalizeJsonValue($workspace['warning_json']),
                $this->normalizeJsonValue($workspace['next_actions_json']),
                $this->normalizeJsonValue($workspace['metadata_json']),
                $workspace['owner_user_id'],
                ($userId ?? 0) > 0 ? (int) $userId : null,
                ($userId ?? 0) > 0 ? (int) $userId : null,
            ]
        );

        return $this->getMarketingCampaignWorkspace($campaignId) ?? $workspace;
    }

    public function getMarketingCampaignWorkspaceSummary(): array
    {
        if (!Database::tableExists('campaigns')) {
            return [
                'counts' => ['total' => 0, 'ready' => 0, 'blocked' => 0, 'active' => 0, 'launched' => 0],
                'average_health' => 0,
                'workspaces' => [],
                'next_actions' => [],
            ];
        }

        $workspaces = $this->listMarketingCampaignWorkspaces(['open' => true], 50, 0);
        $counts = ['total' => count($workspaces), 'ready' => 0, 'blocked' => 0, 'active' => 0, 'launched' => 0];
        $healthTotal = 0;
        $nextActions = [];
        foreach ($workspaces as $workspace) {
            $status = (string) ($workspace['status'] ?? 'draft');
            if (array_key_exists($status, $counts)) {
                $counts[$status]++;
            }
            $healthTotal += (int) ($workspace['health_score'] ?? 0);
            foreach ((array) ($workspace['next_actions_json'] ?? []) as $action) {
                if (count($nextActions) >= 6) {
                    break 2;
                }
                $nextActions[] = $action + ['campaign_id' => (int) ($workspace['campaign_id'] ?? 0)];
            }
        }

        return [
            'counts' => $counts,
            'average_health' => $counts['total'] > 0 ? (int) round($healthTotal / $counts['total']) : 0,
            'workspaces' => array_slice($workspaces, 0, 6),
            'next_actions' => $nextActions,
        ];
    }

    public function getUnifiedCampaignWorkspaceMap(int $campaignId): array
    {
        $this->assertMarketingPermission('marketing.read');
        $workspace = $this->getMarketingCampaignWorkspace($campaignId);
        if (!$workspace) {
            throw new RuntimeException('Campaign was not found in the active workspace.');
        }

        $linked = (array) ($workspace['linked_summary_json'] ?? []);
        $countLinked = static fn(string $key): int => (int) ($linked[$key]['count'] ?? 0);
        $scoreStatus = static function (int $score): string {
            if ($score >= 80) {
                return 'ready';
            }
            if ($score >= 45) {
                return 'attention';
            }

            return 'blocked';
        };
        $boundedScore = static fn(int|float $score): int => max(0, min(100, (int) round((float) $score)));
        $presenceScore = static function (array $values) use ($boundedScore): int {
            $present = 0;
            foreach ($values as $value) {
                if ((int) $value > 0) {
                    $present++;
                }
            }

            return $boundedScore(($present / max(1, count($values))) * 100);
        };
        $lane = static function (
            string $key,
            string $label,
            string $href,
            int $score,
            string $evidence,
            array $metrics,
            array $nextActions
        ) use ($scoreStatus): array {
            return [
                'key' => $key,
                'label' => $label,
                'href' => $href,
                'score' => $score,
                'status' => $scoreStatus($score),
                'evidence' => $evidence,
                'metrics' => $metrics,
                'next_actions' => $nextActions,
            ];
        };

        $operatingRoom = $this->getCampaignOperatingRoom($campaignId);
        $executionReadiness = $this->getCampaignExecutionReadiness($campaignId);
        $relationshipReadiness = $this->getCampaignRelationshipReadiness($campaignId);
        $launchWorkspace = $this->getCampaignLaunchWorkspaceV2Summary($campaignId);
        $revenueLoop = $this->getCampaignRevenueLoopSummary($campaignId, 4);
        $creativeReadiness = Database::tableExists('marketing_campaign_creative_requirements')
            ? $this->getCampaignCreativeReadinessSummary($campaignId)
            : ['status' => 'unavailable', 'counts' => ['ready' => 0, 'total' => 0], 'score' => 0];

        $strategyScore = $boundedScore(round(((int) ($workspace['health_score'] ?? 0) + $presenceScore([
            $countLinked('briefs'),
            $countLinked('audience_activations'),
            $countLinked('landing_pages'),
        ])) / 2));
        $contentScore = $presenceScore([
            $countLinked('content_items'),
            $countLinked('calendar'),
            $countLinked('launch_readiness'),
        ]);
        $distributionScore = $presenceScore([
            $countLinked('distribution_posts'),
            $countLinked('channel_exports'),
            $countLinked('email_runs'),
            $countLinked('utm_links'),
        ]);
        $launchScore = $boundedScore((int) ($launchWorkspace['readiness_score'] ?? 0));
        $relationshipScore = $boundedScore((int) ($relationshipReadiness['score'] ?? $relationshipReadiness['health_score'] ?? 0));
        $revenueScore = $boundedScore((int) ($revenueLoop['score'] ?? 0));
        $mediaScore = $boundedScore((int) ($creativeReadiness['score'] ?? 0));
        if ($mediaScore === 0 && (int) ($creativeReadiness['counts']['total'] ?? 0) > 0) {
            $mediaScore = $presenceScore([
                $creativeReadiness['counts']['ready'] ?? 0,
                $creativeReadiness['counts']['approved'] ?? 0,
                $creativeReadiness['counts']['total'] ?? 0,
            ]);
        }

        $lanes = [
            $lane(
                'strategy',
                'Strategy And Audience',
                'marketing_briefs.php?campaign_id=' . $campaignId,
                $strategyScore,
                'Campaign brief, audience, offer, and landing-page direction.',
                [
                    'Briefs' => $countLinked('briefs'),
                    'Audiences' => $countLinked('audience_activations'),
                    'Landing pages' => $countLinked('landing_pages'),
                ],
                ['Confirm campaign brief owner', 'Connect persona and offer evidence']
            ),
            $lane(
                'content',
                'Content And Review',
                'marketing_content.php?campaign_id=' . $campaignId,
                $contentScore,
                'Content, calendar, reviews, and launch-readiness gates.',
                [
                    'Content items' => $countLinked('content_items'),
                    'Calendar' => $countLinked('calendar'),
                    'Launch reviews' => $countLinked('launch_readiness'),
                ],
                ['Move campaign content toward review', 'Attach content to launch checklist']
            ),
            $lane(
                'media',
                'Media And Creative',
                'marketing_creative.php?campaign_id=' . $campaignId,
                $mediaScore,
                'Creative requirements, assets, approval, and channel media readiness.',
                [
                    'Ready creative' => (int) ($creativeReadiness['counts']['ready'] ?? 0),
                    'Total creative' => (int) ($creativeReadiness['counts']['total'] ?? 0),
                    'Status' => (string) ($creativeReadiness['status'] ?? 'unknown'),
                ],
                ['Resolve media requirements', 'Clear rights and accessibility warnings']
            ),
            $lane(
                'distribution',
                'Distribution Package',
                'marketing_distribution.php?campaign_id=' . $campaignId,
                $distributionScore,
                'Manual export bundles, channel posts, email runs, and UTM links.',
                [
                    'Distribution' => $countLinked('distribution_posts'),
                    'Channel exports' => $countLinked('channel_exports'),
                    'Email runs' => $countLinked('email_runs'),
                    'UTMs' => $countLinked('utm_links'),
                ],
                ['Create export pack', 'Verify UTM and unsubscribe placeholders']
            ),
            $lane(
                'launch',
                'Launch Controls',
                'marketing_launch_control.php?campaign_id=' . $campaignId,
                $launchScore,
                'Launch packet, checklist, action center, and manual launch blockers.',
                [
                    'Readiness' => (int) ($launchWorkspace['readiness_score'] ?? 0) . '%',
                    'High risks' => (int) ($launchWorkspace['counts']['risks_high'] ?? 0),
                    'Export items' => (int) ($launchWorkspace['counts']['export_items_ready'] ?? 0) . '/' . (int) ($launchWorkspace['counts']['export_items_total'] ?? 0),
                ],
                ['Clear high launch risks', 'Save action snapshot before handoff']
            ),
            $lane(
                'crm_relationships',
                'CRM Relationships',
                'marketing_relationships.php?campaign_id=' . $campaignId,
                $relationshipScore,
                'Contacts, deals, tasks, forms, handoffs, and campaign relationship evidence.',
                [
                    'Relationship score' => $relationshipScore . '%',
                    'Execution score' => (int) ($executionReadiness['score'] ?? 0) . '%',
                    'Operating room' => (int) ($operatingRoom['health_score'] ?? 0) . '%',
                ],
                ['Review CRM relationship gaps', 'Keep sales handoff evidence current']
            ),
            $lane(
                'revenue',
                'Revenue Loop',
                'marketing_performance.php?campaign_id=' . $campaignId,
                $revenueScore,
                'Conversion goals, lead handoffs, attribution, budget, experiments, and revenue evidence.',
                [
                    'Revenue loop' => $revenueScore . '%',
                    'Lead handoffs' => (int) ($revenueLoop['counts']['lead_handoffs'] ?? 0),
                    'Attributed revenue' => number_format((float) ($revenueLoop['counts']['attributed_revenue'] ?? 0), 2),
                ],
                ['Close campaign-to-revenue gaps', 'Review ROI before increasing spend']
            ),
        ];

        $totalScore = 0;
        $counts = ['ready' => 0, 'attention' => 0, 'blocked' => 0, 'total' => count($lanes)];
        foreach ($lanes as $laneItem) {
            $totalScore += (int) ($laneItem['score'] ?? 0);
            $laneStatus = (string) ($laneItem['status'] ?? 'blocked');
            $counts[$laneStatus] = (int) ($counts[$laneStatus] ?? 0) + 1;
        }
        $averageScore = $boundedScore($totalScore / max(1, count($lanes)));
        $status = match (true) {
            $counts['blocked'] > 0 => 'blocked',
            $counts['attention'] > 0 => 'needs_attention',
            default => 'ready',
        };
        $lowestLane = array_reduce($lanes, static function (?array $carry, array $item): array {
            if ($carry === null || (int) ($item['score'] ?? 0) < (int) ($carry['score'] ?? 0)) {
                return $item;
            }

            return $carry;
        });

        return [
            'campaign_id' => $campaignId,
            'campaign_name' => (string) ($workspace['campaign_name'] ?? $workspace['workspace_name'] ?? 'Campaign'),
            'status' => $status,
            'average_score' => $averageScore,
            'counts' => $counts,
            'lanes' => $lanes,
            'lowest_lane' => $lowestLane,
            'recommended_product_decision' => 'Use the unified campaign map as the campaign home base: every campaign should expose its weakest lane, connected CRM evidence, manual export readiness, and revenue loop before launch.',
            'guardrails' => [
                'workspace_scoped' => true,
                'manual_first' => true,
                'external_publish' => false,
                'external_send' => false,
                'external_api_calls' => false,
                'crm_integrated' => true,
                'page_speed_aware' => true,
            ],
        ];
    }

    public function getCampaignExecutionBriefing(int $campaignId, ?int $userId = null): array
    {
        $this->assertMarketingPermission('marketing.read');
        $workspace = $this->getMarketingCampaignWorkspace($campaignId);
        if (!$workspace) {
            throw new RuntimeException('Campaign was not found in the active workspace.');
        }

        $map = $this->getUnifiedCampaignWorkspaceMap($campaignId);
        $executionReadiness = $this->getCampaignExecutionReadiness($campaignId);
        $launchWorkspace = $this->getCampaignLaunchWorkspaceV2Summary($campaignId);
        $actionCenter = $this->getCampaignExecutionActionCenter($campaignId, $userId);
        $blockedLanes = array_values(array_filter((array) ($map['lanes'] ?? []), static fn(array $lane): bool => (string) ($lane['status'] ?? '') === 'blocked'));
        $attentionLanes = array_values(array_filter((array) ($map['lanes'] ?? []), static fn(array $lane): bool => (string) ($lane['status'] ?? '') === 'attention'));
        $blockedChecks = (array) ($executionReadiness['blocked_checks'] ?? []);
        $launchRisks = array_values(array_filter((array) ($launchWorkspace['risk_register'] ?? []), static fn(array $risk): bool => in_array((string) ($risk['severity'] ?? ''), ['high', 'blocked'], true)));
        $urgentActions = array_values(array_filter((array) ($actionCenter['actions'] ?? []), static fn(array $action): bool => in_array((string) ($action['priority'] ?? ''), ['urgent', 'high'], true)));
        $readyForManualLaunch = $blockedChecks === []
            && $blockedLanes === []
            && empty($launchWorkspace['risk_register'])
            && !empty($executionReadiness['ready_to_launch']);
        $status = match (true) {
            $readyForManualLaunch => 'ready_for_manual_launch',
            $blockedChecks !== [] || $blockedLanes !== [] || $launchRisks !== [] => 'blocked',
            default => 'needs_attention',
        };

        $nextDecisions = [];
        foreach ($blockedLanes as $lane) {
            $nextDecisions[] = [
                'label' => 'Fix ' . (string) ($lane['label'] ?? 'campaign lane'),
                'href' => (string) ($lane['href'] ?? 'marketing_campaign_workspace.php?campaign_id=' . $campaignId),
                'reason' => (string) ($lane['evidence'] ?? 'A campaign lane is blocked.'),
                'priority' => 'high',
                'source' => 'Unified Campaign Map',
            ];
        }
        foreach ($blockedChecks as $check) {
            $nextDecisions[] = [
                'label' => (string) ($check['label'] ?? 'Resolve execution check'),
                'href' => (string) ($check['href'] ?? 'marketing_campaign_workspace.php?campaign_id=' . $campaignId),
                'reason' => (string) ($check['message'] ?? 'A required execution check is incomplete.'),
                'priority' => 'high',
                'source' => 'Execution Readiness',
            ];
        }
        foreach ($launchRisks as $risk) {
            $nextDecisions[] = [
                'label' => (string) ($risk['label'] ?? 'Clear launch risk'),
                'href' => (string) ($risk['href'] ?? 'marketing_launch_control.php?campaign_id=' . $campaignId),
                'reason' => (string) ($risk['message'] ?? 'A high launch risk is open.'),
                'priority' => 'urgent',
                'source' => 'Launch Workspace',
            ];
        }
        foreach ($urgentActions as $action) {
            $nextDecisions[] = [
                'label' => (string) ($action['label'] ?? 'Review campaign action'),
                'href' => (string) ($action['href'] ?? 'marketing_campaign_workspace.php?campaign_id=' . $campaignId),
                'reason' => (string) ($action['reason'] ?? 'Review this campaign action.'),
                'priority' => (string) ($action['priority'] ?? 'high'),
                'source' => (string) ($action['source'] ?? 'Action Center'),
            ];
        }
        if ($nextDecisions === []) {
            foreach (array_slice(array_merge($attentionLanes, (array) ($map['lanes'] ?? [])), 0, 4) as $lane) {
                $nextDecisions[] = [
                    'label' => 'Improve ' . (string) ($lane['label'] ?? 'campaign lane'),
                    'href' => (string) ($lane['href'] ?? 'marketing_campaign_workspace.php?campaign_id=' . $campaignId),
                    'reason' => (string) ($lane['evidence'] ?? 'Improve this lane before campaign scale.'),
                    'priority' => (string) ($lane['status'] ?? '') === 'ready' ? 'low' : 'medium',
                    'source' => 'Unified Campaign Map',
                ];
            }
        }

        return [
            'campaign_id' => $campaignId,
            'campaign_name' => (string) ($workspace['campaign_name'] ?? $workspace['workspace_name'] ?? 'Campaign'),
            'status' => $status,
            'ready_for_manual_launch' => $readyForManualLaunch,
            'score' => (int) round(((int) ($map['average_score'] ?? 0) + (int) ($executionReadiness['score'] ?? 0) + (int) ($launchWorkspace['readiness_score'] ?? 0)) / 3),
            'counts' => [
                'blocked_lanes' => count($blockedLanes),
                'attention_lanes' => count($attentionLanes),
                'blocked_checks' => count($blockedChecks),
                'high_launch_risks' => count($launchRisks),
                'urgent_actions' => count($urgentActions),
                'next_decisions' => count($nextDecisions),
            ],
            'lowest_lane' => (array) ($map['lowest_lane'] ?? []),
            'next_decisions' => array_slice($nextDecisions, 0, 8),
            'evidence' => [
                'map_status' => (string) ($map['status'] ?? 'needs_attention'),
                'execution_status' => (string) ($executionReadiness['status'] ?? 'blocked'),
                'launch_status' => (string) ($launchWorkspace['status'] ?? 'needs_attention'),
                'action_center_status' => (string) ($actionCenter['status'] ?? 'needs_attention'),
            ],
            'guardrails' => [
                'workspace_scoped' => true,
                'manual_first' => true,
                'read_only_briefing' => true,
                'external_publish' => false,
                'external_send' => false,
                'external_api_calls' => false,
                'requires_human_go_no_go' => true,
            ],
            'recommended_product_decision' => 'Use the Campaign Execution Briefing as the campaign go/no-go surface: it should combine lane readiness, launch risk, CRM evidence, manual exports, and next decisions before a human approves execution.',
            'generated_at' => date('c'),
        ];
    }

    public function getCampaignOperatingRoom(int $campaignId): array
    {
        $this->assertMarketingPermission('marketing.read');
        $workspace = $this->getMarketingCampaignWorkspace($campaignId);
        if (!$workspace) {
            throw new RuntimeException('Campaign was not found in the active workspace.');
        }

        $linked = (array) ($workspace['linked_summary_json'] ?? []);
        $readiness = [];
        foreach ((array) ($workspace['readiness_json'] ?? []) as $check) {
            $key = (string) ($check['key'] ?? '');
            if ($key !== '') {
                $readiness[$key] = $check;
            }
        }
        $countLinked = static fn(string $key): int => (int) ($linked[$key]['count'] ?? 0);
        $checkReady = static fn(array $checks): int => count(array_filter($checks, static fn(array $check): bool => (string) ($check['status'] ?? '') === 'ready'));
        $stage = function (string $key, string $label, string $description, array $checkKeys, array $linkedKeys, string $href) use ($readiness, $linked, $countLinked, $checkReady): array {
            $checks = [];
            foreach ($checkKeys as $checkKey) {
                if (isset($readiness[$checkKey])) {
                    $checks[] = $readiness[$checkKey];
                }
            }
            $linkedTotal = 0;
            $linkedSummary = [];
            foreach ($linkedKeys as $linkedKey) {
                $linkedCount = $countLinked($linkedKey);
                $linkedTotal += $linkedCount;
                $linkedSummary[$linkedKey] = $linked[$linkedKey] ?? ['count' => 0, 'records' => []];
            }
            $score = $checks !== [] ? (int) round(($checkReady($checks) / count($checks)) * 100) : ($linkedTotal > 0 ? 100 : 0);
            $status = $score >= 85 ? 'ready' : ($score > 0 ? 'in_progress' : 'missing');

            return [
                'key' => $key,
                'label' => $label,
                'description' => $description,
                'status' => $status,
                'score' => $score,
                'href' => $href,
                'linked_count' => $linkedTotal,
                'linked_summary' => $linkedSummary,
                'checks' => $checks,
            ];
        };

        $stages = [
            $stage('strategy', 'Strategy', 'Campaign brief, audience, offer, and owner clarity.', ['brief', 'audience'], ['briefs', 'audience_activations'], 'marketing_briefs.php?campaign_id=' . $campaignId),
            $stage('conversion', 'Conversion', 'Landing page, form destination, and tracking readiness.', ['landing_page', 'tracking'], ['landing_pages', 'utm_links'], 'marketing_landing_pages.php?campaign_id=' . $campaignId),
            $stage('production', 'Production', 'Content, media, email, and manual distribution assets.', ['content', 'distribution'], ['content_items', 'distribution_posts', 'channel_exports', 'email_runs'], 'marketing_content.php?campaign_id=' . $campaignId),
            $stage('launch', 'Launch Control', 'Readiness reviews, checklists, and final manual launch gates.', ['readiness', 'launch_control'], ['launch_readiness', 'launch_control', 'launch_checklists'], 'marketing_launch_checklists.php?campaign_id=' . $campaignId),
            $stage('measurement', 'Measurement Loop', 'Budget, experiments, attribution, and performance review.', ['budget', 'experiment'], ['budgets', 'experiments'], 'marketing_performance.php?campaign_id=' . $campaignId),
        ];

        $nextActions = (array) ($workspace['next_actions_json'] ?? []);
        if ($countLinked('launch_checklists') === 0) {
            $nextActions[] = [
                'label' => 'Create campaign launch checklist',
                'href' => 'marketing_launch_checklists.php?campaign_id=' . $campaignId,
                'reason' => 'A checklist connects strategy, content, landing page, media, tracking, and manual launch readiness.',
                'required' => false,
            ];
        }
        if ($countLinked('budgets') === 0 && $countLinked('experiments') === 0) {
            $nextActions[] = [
                'label' => 'Plan measurement loop',
                'href' => 'marketing_performance.php?campaign_id=' . $campaignId,
                'reason' => 'Add budget, ROI, or experiment context so post-launch reporting has a baseline.',
                'required' => false,
            ];
        }

        return [
            'campaign_id' => $campaignId,
            'campaign_name' => (string) ($workspace['campaign_name'] ?? ''),
            'status' => (string) ($workspace['status'] ?? 'draft'),
            'health_score' => (int) ($workspace['health_score'] ?? 0),
            'stages' => $stages,
            'next_actions' => array_slice($nextActions, 0, 8),
            'linked_summary' => $linked,
            'guardrails' => [
                'manual_first' => true,
                'external_publish' => false,
                'external_send' => false,
                'message' => 'The operating room coordinates manual execution readiness without sending or publishing externally.',
            ],
        ];
    }

    public function getCampaignExecutionReadiness(int $campaignId): array
    {
        $this->assertMarketingPermission('marketing.read');
        $room = $this->getCampaignOperatingRoom($campaignId);
        $linked = (array) ($room['linked_summary'] ?? []);
        $countLinked = static fn(string $key): int => (int) ($linked[$key]['count'] ?? 0);
        $checks = [];
        $add = static function (
            array &$checks,
            string $key,
            string $label,
            string $category,
            bool $complete,
            bool $required,
            string $href,
            string $message
        ): void {
            $checks[] = [
                'key' => $key,
                'label' => $label,
                'category' => $category,
                'complete' => $complete,
                'required' => $required,
                'href' => $href,
                'message' => $message,
                'status' => $complete ? 'ready' : ($required ? 'blocked' : 'attention'),
            ];
        };

        $add($checks, 'campaign_strategy', 'Campaign brief and strategy', 'strategy', $countLinked('briefs') > 0, true, 'marketing_briefs.php?campaign_id=' . $campaignId, 'Connect a campaign brief with objective, audience, offer, and key message.');
        $add($checks, 'audience', 'Audience activation or segment', 'strategy', $countLinked('audience_activations') > 0, true, 'marketing_audience_activation.php?campaign_id=' . $campaignId, 'Connect the target audience before manual distribution or email export.');
        $add($checks, 'landing_page', 'Landing page destination', 'conversion', $countLinked('landing_pages') > 0, true, 'marketing_landing_pages.php?campaign_id=' . $campaignId, 'Prepare the conversion destination with form, CTA, and preview readiness.');
        $add($checks, 'content', 'Campaign content', 'production', $countLinked('content_items') > 0, true, 'marketing_content.php?campaign_id=' . $campaignId, 'Create launch content connected to the campaign.');
        $add($checks, 'distribution', 'Distribution or channel export', 'distribution', ($countLinked('distribution_posts') + $countLinked('channel_exports') + $countLinked('email_runs')) > 0, true, 'marketing_distribution.php?campaign_id=' . $campaignId, 'Build manual channel exports, distribution variants, or email-run plans.');
        $add($checks, 'tracking', 'UTM and tracking links', 'measurement', $countLinked('utm_links') > 0, true, 'marketing_utm_links.php?campaign_id=' . $campaignId, 'Generate tracking links before manual launch.');
        $add($checks, 'launch_readiness', 'Launch readiness review', 'governance', $countLinked('launch_readiness') > 0, true, 'marketing_launch_readiness.php?campaign_id=' . $campaignId, 'Run readiness review and clear launch blockers.');
        $add($checks, 'launch_control', 'Launch control record', 'governance', $countLinked('launch_control') > 0, false, 'marketing_launch_control.php?campaign_id=' . $campaignId, 'Prepare manual launch controls for approvals, dry-run, or connector gates.');
        $add($checks, 'launch_checklist', 'Launch checklist', 'governance', $countLinked('launch_checklists') > 0, false, 'marketing_launch_checklists.php?campaign_id=' . $campaignId, 'Create a final checklist for owner, media, tracking, approval, and export readiness.');
        $add($checks, 'budget_or_experiment', 'Budget, ROI, or experiment baseline', 'measurement', ($countLinked('budgets') + $countLinked('experiments')) > 0, false, 'marketing_performance.php?campaign_id=' . $campaignId, 'Add budget, ROI, or experiment context so post-launch performance has a baseline.');

        $required = array_values(array_filter($checks, static fn(array $check): bool => (bool) ($check['required'] ?? false)));
        $blocked = array_values(array_filter($checks, static fn(array $check): bool => !($check['complete'] ?? false) && (bool) ($check['required'] ?? false)));
        $attention = array_values(array_filter($checks, static fn(array $check): bool => !($check['complete'] ?? false) && !(bool) ($check['required'] ?? false)));
        $completeRequired = count($required) - count($blocked);
        $score = $required === [] ? 0 : (int) round(($completeRequired / count($required)) * 100);
        $nextActions = [];
        foreach (array_merge($blocked, $attention) as $check) {
            $nextActions[] = [
                'label' => (string) ($check['label'] ?? 'Review readiness'),
                'href' => (string) ($check['href'] ?? 'marketing_campaign_workspace.php?campaign_id=' . $campaignId),
                'reason' => (string) ($check['message'] ?? ''),
                'priority' => !empty($check['required']) ? 'high' : 'medium',
            ];
            if (count($nextActions) >= 6) {
                break;
            }
        }

        return [
            'campaign_id' => $campaignId,
            'campaign_name' => (string) ($room['campaign_name'] ?? ''),
            'score' => $score,
            'ready_to_launch' => $blocked === [],
            'status' => $blocked === [] ? 'ready_for_manual_execution' : 'blocked',
            'checks' => $checks,
            'blocked_checks' => $blocked,
            'attention_checks' => $attention,
            'next_actions' => $nextActions,
            'guardrails' => [
                'manual_first' => true,
                'external_publish' => false,
                'external_send' => false,
                'message' => 'Execution readiness is a manual launch gate. It does not send email, publish pages, post to channels, or start ads.',
            ],
        ];
    }

    public function getCampaignRelationshipReadiness(int $campaignId): array
    {
        $this->assertMarketingPermission('marketing.read');
        $campaignId = max(0, $campaignId);
        if ($campaignId <= 0) {
            throw new RuntimeException('Campaign was not found in the active workspace.');
        }

        $campaign = $this->getCampaignForWorkspace($campaignId);
        if (!$campaign) {
            throw new RuntimeException('Campaign was not found in the active workspace.');
        }

        $workspace = Database::tableExists('marketing_campaign_workspaces')
            ? $this->getMarketingCampaignWorkspace($campaignId)
            : null;
        if (!$workspace) {
            $workspace = $this->buildMarketingCampaignWorkspace($campaign);
        }

        $linked = (array) ($workspace['linked_summary_json'] ?? []);
        $countLinked = static fn(string $key): int => (int) ($linked[$key]['count'] ?? 0);
        $mediaCount = 0;
        if (
            Database::tableExists('marketing_content_media')
            && Database::tableExists('marketing_content_items')
            && Database::columnExists('marketing_content_items', 'campaign_id')
        ) {
            $mediaRow = Database::queryOne(
                "SELECT COUNT(DISTINCT cm.media_file_id) AS count
                 FROM marketing_content_media cm
                 JOIN marketing_content_items ci ON ci.id = cm.content_item_id AND ci.workspace_id = cm.workspace_id
                 WHERE ci.workspace_id = ? AND ci.campaign_id = ?",
                [$this->workspaceId(), $campaignId]
            );
            $mediaCount = (int) ($mediaRow['count'] ?? 0);
        }

        $relationships = Database::tableExists('marketing_relationship_graph_edges')
            ? $this->listMarketingRelationships(['record_type' => 'campaign', 'record_id' => $campaignId], 80, 0)
            : [];
        $connectedTypes = [];
        foreach ($relationships as $edge) {
            foreach (['source', 'target'] as $side) {
                $type = (string) ($edge[$side . '_type'] ?? '');
                if ($type !== '' && $type !== 'campaign') {
                    $connectedTypes[$type] = true;
                }
            }
        }
        $hasGraphType = static function (array $types) use ($connectedTypes): bool {
            foreach ($types as $type) {
                if (!empty($connectedTypes[$type])) {
                    return true;
                }
            }

            return false;
        };

        $checks = [];
        $addCheck = static function (
            array &$checks,
            string $key,
            string $label,
            string $category,
            bool $sourceReady,
            bool $required,
            int $recordCount,
            string $href,
            string $message,
            bool $graphExpected = false,
            bool $graphConnected = false
        ): void {
            $checks[] = [
                'key' => $key,
                'label' => $label,
                'category' => $category,
                'source_ready' => $sourceReady,
                'required' => $required,
                'record_count' => $recordCount,
                'href' => $href,
                'message' => $message,
                'graph_expected' => $graphExpected,
                'graph_connected' => $graphConnected,
                'status' => !$sourceReady ? ($required ? 'blocked' : 'attention') : (($graphExpected && !$graphConnected) ? 'attention' : 'ready'),
            ];
        };

        $distributionCount = $countLinked('distribution_posts') + $countLinked('channel_exports') + $countLinked('email_runs');
        $measurementCount = $countLinked('budgets') + $countLinked('experiments');
        $governanceCount = $countLinked('launch_readiness') + $countLinked('launch_control') + $countLinked('launch_checklists');
        $audienceCount = $countLinked('audience_activations');
        if (Database::tableExists('marketing_campaign_briefs') && Database::columnExists('marketing_campaign_briefs', 'audience_segment_id')) {
            $audienceRow = Database::queryOne(
                "SELECT COUNT(*) AS count
                 FROM marketing_campaign_briefs
                 WHERE workspace_id = ? AND campaign_id = ? AND audience_segment_id IS NOT NULL",
                [$this->workspaceId(), $campaignId]
            );
            $audienceCount += (int) ($audienceRow['count'] ?? 0);
        }

        $addCheck($checks, 'brief', 'Strategy brief connected', 'strategy', $countLinked('briefs') > 0, true, $countLinked('briefs'), 'marketing_briefs.php?campaign_id=' . $campaignId, 'Connect a campaign brief so objectives, audience, offer, and message are explicit.', true, $hasGraphType(['campaign_brief']));
        $addCheck($checks, 'audience', 'Audience path connected', 'strategy', $audienceCount > 0, true, $audienceCount, 'marketing_audience_activation.php?campaign_id=' . $campaignId, 'Attach an audience activation or segment before distribution.', false, false);
        $addCheck($checks, 'landing_page', 'Conversion destination connected', 'conversion', $countLinked('landing_pages') > 0, true, $countLinked('landing_pages'), 'marketing_landing_pages.php?campaign_id=' . $campaignId, 'Add a landing page or conversion destination for campaign traffic.', true, $hasGraphType(['landing_page']));
        $addCheck($checks, 'content', 'Campaign content connected', 'production', $countLinked('content_items') > 0, true, $countLinked('content_items'), 'marketing_content.php?campaign_id=' . $campaignId, 'Create campaign content records and connect them to the campaign.', true, $hasGraphType(['content_item']));
        $addCheck($checks, 'media', 'Media evidence attached', 'production', $mediaCount > 0, false, $mediaCount, 'marketing_assets.php', 'Attach campaign media to content so export packages have visual evidence.', false, false);
        $addCheck($checks, 'distribution', 'Manual distribution path connected', 'distribution', $distributionCount > 0, true, $distributionCount, 'marketing_distribution.php?campaign_id=' . $campaignId, 'Prepare distribution variants, channel exports, or manual email run packages.', false, false);
        $addCheck($checks, 'tracking', 'Tracking path connected', 'measurement', $countLinked('utm_links') > 0, true, $countLinked('utm_links'), 'marketing_utm_links.php?campaign_id=' . $campaignId, 'Generate UTM links before launch so performance can be traced.', true, $hasGraphType(['utm_link']));
        $addCheck($checks, 'governance', 'Launch governance connected', 'governance', $governanceCount > 0, true, $governanceCount, 'marketing_launch_readiness.php?campaign_id=' . $campaignId, 'Run launch readiness, launch control, or launch checklist before manual execution.', false, false);
        $addCheck($checks, 'measurement', 'Measurement baseline connected', 'measurement', $measurementCount > 0, false, $measurementCount, 'marketing_performance.php?campaign_id=' . $campaignId, 'Add budget, ROI, or experiment context for post-launch reporting.', false, false);

        $required = array_values(array_filter($checks, static fn(array $check): bool => (bool) ($check['required'] ?? false)));
        $blocked = array_values(array_filter($required, static fn(array $check): bool => !($check['source_ready'] ?? false)));
        $attention = array_values(array_filter($checks, static fn(array $check): bool => (string) ($check['status'] ?? '') === 'attention'));
        $sourceReady = count($required) - count($blocked);
        $sourceScore = $required === [] ? 0 : ($sourceReady / count($required)) * 75;
        $graphExpected = array_values(array_filter($checks, static fn(array $check): bool => !empty($check['graph_expected']) && !empty($check['source_ready'])));
        $graphConnected = count(array_filter($graphExpected, static fn(array $check): bool => !empty($check['graph_connected'])));
        $graphScore = $graphExpected === [] ? 25 : ($graphConnected / count($graphExpected)) * 25;
        $score = (int) round($sourceScore + $graphScore);

        $nextActions = [];
        foreach ($blocked as $check) {
            $nextActions[] = [
                'label' => (string) ($check['label'] ?? 'Resolve campaign dependency'),
                'href' => (string) ($check['href'] ?? 'marketing_campaign_workspace.php?campaign_id=' . $campaignId),
                'reason' => (string) ($check['message'] ?? 'Resolve this campaign dependency.'),
                'priority' => 'high',
            ];
        }
        foreach ($attention as $check) {
            if (!empty($check['graph_expected']) && empty($check['graph_connected'])) {
                $nextActions[] = [
                    'label' => 'Refresh relationship graph',
                    'href' => 'marketing_relationships.php',
                    'reason' => (string) ($check['label'] ?? 'Campaign dependency') . ' exists, but the evidence graph has not connected it yet.',
                    'priority' => 'medium',
                ];
            } else {
                $nextActions[] = [
                    'label' => (string) ($check['label'] ?? 'Review campaign dependency'),
                    'href' => (string) ($check['href'] ?? 'marketing_campaign_workspace.php?campaign_id=' . $campaignId),
                    'reason' => (string) ($check['message'] ?? 'Review this campaign dependency.'),
                    'priority' => 'medium',
                ];
            }
        }

        return [
            'campaign_id' => $campaignId,
            'campaign_name' => (string) ($workspace['campaign_name'] ?? $campaign['name'] ?? ''),
            'score' => $score,
            'status' => $blocked !== [] ? 'blocked' : ($graphExpected !== [] && $graphConnected < count($graphExpected) ? 'needs_graph_refresh' : 'relationship_ready'),
            'ready_for_operator_review' => $blocked === [] && ($graphExpected === [] || $graphConnected >= count($graphExpected)),
            'checks' => $checks,
            'blocked_checks' => $blocked,
            'attention_checks' => $attention,
            'relationships' => array_slice($relationships, 0, 12),
            'counts' => [
                'direct_edges' => count($relationships),
                'connected_record_types' => count($connectedTypes),
                'graph_expected' => count($graphExpected),
                'graph_connected' => $graphConnected,
                'media_files' => $mediaCount,
            ],
            'next_actions' => array_slice($nextActions, 0, 8),
            'recommended_product_decision' => 'Use the relationship graph as the campaign evidence layer before relying on AI, automation, or manual launch decisions.',
            'guardrails' => [
                'manual_first' => true,
                'external_publish' => false,
                'external_send' => false,
                'message' => 'Relationship readiness verifies campaign dependencies only. It does not send, publish, advertise, or call external channel APIs.',
            ],
        ];
    }

    public function getCampaignLaunchScorecard(int $campaignId): array
    {
        $this->assertMarketingPermission('marketing.read');
        $campaignId = max(0, $campaignId);
        if ($campaignId <= 0) {
            throw new RuntimeException('Campaign was not found in the active workspace.');
        }

        $briefs = Database::tableExists('marketing_campaign_briefs') ? $this->listCampaignBriefs(['campaign_id' => $campaignId], 25, 0) : [];
        $contentItems = Database::tableExists('marketing_content_items') ? $this->listContentItems(['campaign_id' => $campaignId, 'exclude_status' => 'archived'], 50, 0) : [];
        $landingPages = Database::tableExists('marketing_landing_pages') ? $this->listLandingPages(['campaign_id' => $campaignId], 25, 0) : [];
        $distributionPosts = Database::tableExists('marketing_distribution_posts') ? $this->listDistributionPosts(['campaign_id' => $campaignId], 25, 0) : [];
        $emailRuns = Database::tableExists('marketing_email_campaign_runs') ? $this->listEmailCampaignRuns(['campaign_id' => $campaignId], 25, 0) : [];
        $utmLinks = Database::tableExists('marketing_utm_links') ? $this->listUtmLinks(['campaign_id' => $campaignId], 25, 0) : [];
        $audienceActivations = Database::tableExists('marketing_audience_activations') ? $this->listAudienceActivations(['campaign_id' => $campaignId], 25, 0) : [];
        $channelExports = Database::tableExists('marketing_channel_export_bundles') ? $this->listChannelExportBundles(['campaign_id' => $campaignId], 25, 0) : [];
        $launchChecklists = Database::tableExists('marketing_campaign_launch_checklists') ? $this->listCampaignLaunchChecklists(['campaign_id' => $campaignId], 25, 0) : [];
        $budgets = Database::tableExists('marketing_campaign_budgets') ? $this->listCampaignBudgets(['campaign_id' => $campaignId], 25, 0) : [];
        $experiments = Database::tableExists('marketing_experiments') ? $this->listExperiments(['campaign_id' => $campaignId], 25, 0) : [];

        $audienceReady = $audienceActivations !== [];
        foreach (array_merge($briefs, $landingPages, $emailRuns) as $record) {
            if ((int) ($record['audience_segment_id'] ?? 0) > 0) {
                $audienceReady = true;
                break;
            }
        }
        $offerReady = false;
        foreach ($briefs as $brief) {
            if ((int) ($brief['offer_context_item_id'] ?? 0) > 0 || trim((string) ($brief['offer_text'] ?? $brief['offer_title'] ?? '')) !== '') {
                $offerReady = true;
                break;
            }
        }
        $landingReady = false;
        foreach ($landingPages as $landingPage) {
            if (trim((string) ($landingPage['headline'] ?? '')) !== '' && in_array((string) ($landingPage['status'] ?? ''), ['review', 'approved'], true)) {
                $landingReady = true;
                break;
            }
        }
        $contentReady = false;
        foreach ($contentItems as $contentItem) {
            if (in_array((string) ($contentItem['status'] ?? ''), ['approved', 'scheduled', 'published'], true)) {
                $contentReady = true;
                break;
            }
        }
        $approvalReady = false;
        if (Database::tableExists('marketing_content_approvals') && $contentItems !== []) {
            $contentIds = array_values(array_filter(array_map(static fn(array $row): int => (int) ($row['id'] ?? 0), $contentItems)));
            if ($contentIds !== []) {
                $placeholders = implode(',', array_fill(0, count($contentIds), '?'));
                $approvalRow = Database::queryOne(
                    "SELECT COUNT(*) AS count
                     FROM marketing_content_approvals
                     WHERE workspace_id = ? AND status = 'approved' AND content_item_id IN ({$placeholders})",
                    array_merge([$this->workspaceId()], $contentIds)
                );
                $approvalReady = (int) ($approvalRow['count'] ?? 0) > 0;
            }
        }
        $distributionReady = $distributionPosts !== [] || $emailRuns !== [] || $channelExports !== [];
        $channelExportReady = count(array_filter($channelExports, static fn(array $row): bool => in_array((string) ($row['status'] ?? ''), ['ready', 'exported'], true))) > 0;
        $launchChecklistReady = count(array_filter($launchChecklists, static fn(array $row): bool => (string) ($row['status'] ?? '') === 'ready')) > 0;
        $budgetReady = $budgets !== [] || $experiments !== [];

        $gates = [];
        $addGate = static function (
            array &$gates,
            string $key,
            string $label,
            string $category,
            bool $complete,
            bool $required,
            string $href,
            string $message,
            int $recordCount = 0
        ): void {
            $gates[] = [
                'key' => $key,
                'label' => $label,
                'category' => $category,
                'complete' => $complete,
                'required' => $required,
                'href' => $href,
                'message' => $message,
                'record_count' => $recordCount,
                'status' => $complete ? 'ready' : ($required ? 'blocked' : 'warning'),
            ];
        };

        $addGate($gates, 'strategy_brief', 'Strategy brief complete', 'strategy', $briefs !== [], true, 'marketing_briefs.php?campaign_id=' . $campaignId, 'Create a campaign brief with objective, audience, offer, and launch message.', count($briefs));
        $addGate($gates, 'audience_selected', 'Audience selected', 'strategy', $audienceReady, true, 'marketing_audience_activation.php?campaign_id=' . $campaignId, 'Select a CRM audience segment or audience activation before launch.', count($audienceActivations));
        $addGate($gates, 'offer_selected', 'Offer selected', 'strategy', $offerReady, true, 'marketing_briefs.php?campaign_id=' . $campaignId, 'Connect the offer or write the campaign offer in the brief.', count($briefs));
        $addGate($gates, 'landing_page_ready', 'Landing page ready', 'conversion', $landingReady, true, 'marketing_landing_pages.php?campaign_id=' . $campaignId, 'Prepare a reviewed or approved landing page with a clear headline.', count($landingPages));
        $addGate($gates, 'content_ready', 'Launch content approved', 'production', $contentReady, true, 'marketing_content.php?campaign_id=' . $campaignId, 'Approve or schedule the content that will carry the campaign.', count($contentItems));
        $addGate($gates, 'distribution_ready', 'Distribution/export planned', 'distribution', $distributionReady, true, 'marketing_distribution.php?campaign_id=' . $campaignId, 'Create distribution variants, channel exports, or manual email-run plans.', count($distributionPosts) + count($emailRuns) + count($channelExports));
        $addGate($gates, 'utm_ready', 'UTM links ready', 'measurement', $utmLinks !== [], true, 'marketing_utm_links.php?campaign_id=' . $campaignId, 'Generate UTM tracking links before manual launch.', count($utmLinks));
        $addGate($gates, 'approval_complete', 'Approval complete', 'governance', $approvalReady, true, 'marketing_reviews.php', 'Approve the campaign launch content before it leaves draft workflows.', 0);
        $addGate($gates, 'manual_launch_checklist_complete', 'Manual launch checklist complete', 'governance', $launchChecklistReady, true, 'marketing_launch_checklists.php?campaign_id=' . $campaignId, 'Create and clear the final launch checklist before operator launch.', count($launchChecklists));
        $addGate($gates, 'channel_export_ready', 'Channel export ready', 'distribution', $channelExportReady, false, 'marketing_channel_exports.php?campaign_id=' . $campaignId, 'Mark at least one channel export package ready for manual publishing.', count($channelExports));
        $addGate($gates, 'budget_or_experiment_ready', 'Budget or experiment baseline', 'measurement', $budgetReady, false, 'marketing_performance.php?campaign_id=' . $campaignId, 'Add budget, ROI, or experiment context for post-launch reporting.', count($budgets) + count($experiments));

        $requiredGates = array_values(array_filter($gates, static fn(array $gate): bool => (bool) ($gate['required'] ?? false)));
        $blocked = array_values(array_filter($requiredGates, static fn(array $gate): bool => !($gate['complete'] ?? false)));
        $warnings = array_values(array_filter($gates, static fn(array $gate): bool => !($gate['complete'] ?? false) && !(bool) ($gate['required'] ?? false)));
        $score = $requiredGates === [] ? 0 : (int) round(((count($requiredGates) - count($blocked)) / count($requiredGates)) * 100);
        $nextActions = [];
        foreach (array_merge($blocked, $warnings) as $gate) {
            $nextActions[] = [
                'label' => (string) ($gate['label'] ?? 'Resolve launch gate'),
                'href' => (string) ($gate['href'] ?? 'marketing_campaign_workspace.php?campaign_id=' . $campaignId),
                'reason' => (string) ($gate['message'] ?? ''),
                'priority' => !empty($gate['required']) ? 'high' : 'medium',
            ];
            if (count($nextActions) >= 8) {
                break;
            }
        }

        return [
            'campaign_id' => $campaignId,
            'score' => $score,
            'status' => $blocked === [] ? 'ready_for_manual_launch' : 'blocked',
            'ready_for_manual_launch' => $blocked === [],
            'gates' => $gates,
            'blocked_gates' => $blocked,
            'warning_gates' => $warnings,
            'next_actions' => $nextActions,
            'counts' => [
                'required' => count($requiredGates),
                'blocked' => count($blocked),
                'warnings' => count($warnings),
                'ready' => count(array_filter($gates, static fn(array $gate): bool => (string) ($gate['status'] ?? '') === 'ready')),
            ],
            'guardrails' => [
                'manual_first' => true,
                'external_publish' => false,
                'external_send' => false,
                'message' => 'Launch scorecard is an operator checklist only; it never sends, publishes, posts, or starts ads.',
            ],
        ];
    }

    public function getCampaignLaunchPacket(int $campaignId): array
    {
        $this->assertMarketingPermission('marketing.read');
        $campaign = Database::tableExists('campaigns')
            ? Database::queryOne('SELECT id, name, status, objective FROM campaigns WHERE workspace_id = ? AND id = ?', [$this->workspaceId(), $campaignId])
            : null;
        if (!$campaign) {
            throw new RuntimeException('Campaign was not found in the active workspace.');
        }

        $scorecard = $this->getCampaignLaunchScorecard($campaignId);
        $briefs = Database::tableExists('marketing_campaign_briefs') ? $this->listCampaignBriefs(['campaign_id' => $campaignId], 25, 0) : [];
        $landingPages = Database::tableExists('marketing_landing_pages') ? $this->listLandingPages(['campaign_id' => $campaignId], 25, 0) : [];
        $contentItems = Database::tableExists('marketing_content_items') ? $this->listContentItems(['campaign_id' => $campaignId, 'exclude_status' => 'archived'], 50, 0) : [];
        $distributionPosts = Database::tableExists('marketing_distribution_posts') ? $this->listDistributionPosts(['campaign_id' => $campaignId], 50, 0) : [];
        $emailRuns = Database::tableExists('marketing_email_campaign_runs') ? $this->listEmailCampaignRuns(['campaign_id' => $campaignId], 25, 0) : [];
        $channelExports = Database::tableExists('marketing_channel_export_bundles') ? $this->listChannelExportBundles(['campaign_id' => $campaignId], 25, 0) : [];
        $utmLinks = Database::tableExists('marketing_utm_links') ? $this->listUtmLinks(['campaign_id' => $campaignId], 25, 0) : [];
        $audienceActivations = Database::tableExists('marketing_audience_activations') ? $this->listAudienceActivations(['campaign_id' => $campaignId], 25, 0) : [];
        $launchChecklists = Database::tableExists('marketing_campaign_launch_checklists') ? $this->listCampaignLaunchChecklists(['campaign_id' => $campaignId], 25, 0) : [];
        $budgets = Database::tableExists('marketing_campaign_budgets') ? $this->listCampaignBudgets(['campaign_id' => $campaignId], 25, 0) : [];
        $experiments = Database::tableExists('marketing_experiments') ? $this->listExperiments(['campaign_id' => $campaignId], 25, 0) : [];

        $contentIds = array_values(array_filter(array_map(static fn(array $row): int => (int) ($row['id'] ?? 0), $contentItems)));
        $approvalCounts = ['approved' => 0, 'pending' => 0, 'rejected' => 0];
        if ($contentIds !== [] && Database::tableExists('marketing_content_approvals')) {
            $placeholders = implode(',', array_fill(0, count($contentIds), '?'));
            foreach (Database::query(
                "SELECT status, COUNT(*) AS count
                 FROM marketing_content_approvals
                 WHERE workspace_id = ? AND content_item_id IN ({$placeholders})
                 GROUP BY status",
                array_merge([$this->workspaceId()], $contentIds)
            ) as $row) {
                $approvalCounts[(string) ($row['status'] ?? '')] = (int) ($row['count'] ?? 0);
            }
        }

        $gateStatusByKey = [];
        foreach ((array) ($scorecard['gates'] ?? []) as $gate) {
            $gateStatusByKey[(string) ($gate['key'] ?? '')] = (string) ($gate['status'] ?? 'warning');
        }
        $section = static function (string $key, string $label, array $gateKeys, array $artifacts, string $href) use ($gateStatusByKey): array {
            $statuses = array_map(static fn(string $gateKey): string => $gateStatusByKey[$gateKey] ?? 'blocked', $gateKeys);
            $blocked = count(array_filter($statuses, static fn(string $status): bool => $status === 'blocked'));
            $warnings = count(array_filter($statuses, static fn(string $status): bool => $status === 'warning'));
            return [
                'key' => $key,
                'label' => $label,
                'status' => $blocked > 0 ? 'blocked' : ($warnings > 0 ? 'warning' : 'ready'),
                'href' => $href,
                'artifact_count' => array_sum(array_map(static fn(array $artifact): int => (int) ($artifact['count'] ?? 0), $artifacts)),
                'artifacts' => $artifacts,
            ];
        };

        $sections = [
            $section('strategy', 'Strategy Packet', ['strategy_brief', 'audience_selected', 'offer_selected'], [
                ['label' => 'Briefs', 'count' => count($briefs), 'href' => 'marketing_briefs.php?campaign_id=' . $campaignId],
                ['label' => 'Audience Activations', 'count' => count($audienceActivations), 'href' => 'marketing_audience_activation.php?campaign_id=' . $campaignId],
            ], 'marketing_briefs.php?campaign_id=' . $campaignId),
            $section('conversion', 'Conversion Packet', ['landing_page_ready', 'utm_ready'], [
                ['label' => 'Landing Pages', 'count' => count($landingPages), 'href' => 'marketing_landing_pages.php?campaign_id=' . $campaignId],
                ['label' => 'UTM Links', 'count' => count($utmLinks), 'href' => 'marketing_utm_links.php?campaign_id=' . $campaignId],
            ], 'marketing_landing_pages.php?campaign_id=' . $campaignId),
            $section('production', 'Production Packet', ['content_ready', 'distribution_ready', 'channel_export_ready'], [
                ['label' => 'Content Items', 'count' => count($contentItems), 'href' => 'marketing_content.php?campaign_id=' . $campaignId],
                ['label' => 'Distribution Drafts', 'count' => count($distributionPosts), 'href' => 'marketing_distribution.php?campaign_id=' . $campaignId],
                ['label' => 'Email Runs', 'count' => count($emailRuns), 'href' => 'marketing_email_runs.php?campaign_id=' . $campaignId],
                ['label' => 'Channel Exports', 'count' => count($channelExports), 'href' => 'marketing_channel_exports.php?campaign_id=' . $campaignId],
            ], 'marketing_distribution.php?campaign_id=' . $campaignId),
            $section('governance', 'Governance Packet', ['approval_complete', 'manual_launch_checklist_complete'], [
                ['label' => 'Approved Reviews', 'count' => $approvalCounts['approved'] ?? 0, 'href' => 'marketing_reviews.php'],
                ['label' => 'Pending Reviews', 'count' => $approvalCounts['pending'] ?? 0, 'href' => 'marketing_reviews.php?queue=pending'],
                ['label' => 'Launch Checklists', 'count' => count($launchChecklists), 'href' => 'marketing_launch_checklists.php?campaign_id=' . $campaignId],
            ], 'marketing_launch_checklists.php?campaign_id=' . $campaignId),
            $section('measurement', 'Measurement Packet', ['budget_or_experiment_ready'], [
                ['label' => 'Budgets', 'count' => count($budgets), 'href' => 'marketing_performance.php?campaign_id=' . $campaignId],
                ['label' => 'Experiments', 'count' => count($experiments), 'href' => 'marketing_performance.php?campaign_id=' . $campaignId],
            ], 'marketing_performance.php?campaign_id=' . $campaignId),
        ];

        $readyArtifacts = array_sum(array_map(static fn(array $section): int => (string) ($section['status'] ?? '') === 'ready' ? 1 : 0, $sections));
        $packetActions = (array) ($scorecard['next_actions'] ?? []);
        if ($packetActions === []) {
            $packetActions[] = [
                'label' => 'Review final launch packet',
                'href' => 'marketing_campaign_workspace.php?campaign_id=' . $campaignId,
                'reason' => 'All required gates are clear. Confirm owner evidence before manual launch.',
                'priority' => 'medium',
            ];
        }

        return [
            'campaign_id' => $campaignId,
            'campaign_name' => (string) ($campaign['name'] ?? ''),
            'campaign_status' => (string) ($campaign['status'] ?? ''),
            'score' => (int) ($scorecard['score'] ?? 0),
            'status' => (string) ($scorecard['status'] ?? 'blocked'),
            'ready_for_manual_launch' => (bool) ($scorecard['ready_for_manual_launch'] ?? false),
            'sections' => $sections,
            'packet_actions' => array_slice($packetActions, 0, 8),
            'counts' => [
                'sections_ready' => $readyArtifacts,
                'sections_total' => count($sections),
                'blocked_gates' => count((array) ($scorecard['blocked_gates'] ?? [])),
                'warning_gates' => count((array) ($scorecard['warning_gates'] ?? [])),
                'content_items' => count($contentItems),
                'landing_pages' => count($landingPages),
                'distribution_posts' => count($distributionPosts),
                'channel_exports' => count($channelExports),
                'utm_links' => count($utmLinks),
                'approved_reviews' => $approvalCounts['approved'] ?? 0,
            ],
            'guardrails' => [
                'manual_first' => true,
                'external_publish' => false,
                'external_send' => false,
                'external_ads' => false,
                'message' => 'Launch packet is execution evidence for operators only; it does not send, publish, post, or start ads.',
            ],
        ];
    }

    public function getCampaignLaunchWorkspaceV2Summary(int $campaignId): array
    {
        $this->assertMarketingPermission('marketing.read');
        $workspace = $this->getMarketingCampaignWorkspace($campaignId);
        if (!$workspace) {
            throw new RuntimeException('Campaign was not found in the active workspace.');
        }

        $operatingRoom = $this->getCampaignOperatingRoom($campaignId);
        $executionReadiness = $this->getCampaignExecutionReadiness($campaignId);
        $launchScorecard = $this->getCampaignLaunchScorecard($campaignId);
        $launchPacket = $this->getCampaignLaunchPacket($campaignId);
        $creativeReadiness = Database::tableExists('marketing_campaign_creative_requirements')
            ? $this->getCampaignCreativeReadinessSummary($campaignId)
            : null;
        $linked = (array) ($workspace['linked_summary_json'] ?? []);
        $countLinked = static fn(string $key): int => (int) ($linked[$key]['count'] ?? 0);

        $scoreInputs = [
            (int) ($workspace['health_score'] ?? 0),
            (int) ($operatingRoom['health_score'] ?? 0),
            (int) ($executionReadiness['score'] ?? 0),
            (int) ($launchScorecard['score'] ?? 0),
            (int) ($launchPacket['score'] ?? 0),
        ];
        $readinessScore = (int) round(array_sum($scoreInputs) / max(1, count($scoreInputs)));

        $risks = [];
        $addRisk = static function (
            array &$risks,
            string $source,
            array $item,
            string $severity = 'medium',
            string $fallbackLabel = 'Review campaign launch risk'
        ): void {
            $label = trim((string) ($item['label'] ?? $item['title'] ?? $fallbackLabel));
            if ($label === '') {
                $label = $fallbackLabel;
            }
            $message = trim((string) ($item['message'] ?? $item['reason'] ?? $item['description'] ?? 'Review before manual campaign launch.'));
            $href = (string) ($item['href'] ?? 'marketing_campaign_workspace.php');
            $key = strtolower($source . '|' . $label . '|' . $href);
            if (isset($risks[$key])) {
                return;
            }
            $risks[$key] = [
                'source' => $source,
                'label' => $label,
                'message' => $message,
                'href' => $href,
                'severity' => $severity,
                'status' => (string) ($item['status'] ?? ($severity === 'high' ? 'blocked' : 'warning')),
                'required' => (bool) ($item['required'] ?? $severity === 'high'),
                'category' => (string) ($item['category'] ?? 'launch'),
            ];
        };

        foreach ((array) ($workspace['missing_requirements_json'] ?? []) as $risk) {
            $addRisk($risks, 'Workspace Requirement', (array) $risk, 'high', 'Complete campaign workspace requirement');
        }
        foreach ((array) ($workspace['warning_json'] ?? []) as $risk) {
            $addRisk($risks, 'Workspace Warning', (array) $risk, 'medium', 'Review campaign workspace warning');
        }
        foreach ((array) ($executionReadiness['blocked_checks'] ?? []) as $risk) {
            $addRisk($risks, 'Execution Readiness', (array) $risk, 'high', 'Clear execution readiness gate');
        }
        foreach ((array) ($executionReadiness['attention_checks'] ?? []) as $risk) {
            $addRisk($risks, 'Execution Readiness', (array) $risk, 'medium', 'Review execution readiness recommendation');
        }
        foreach ((array) ($launchScorecard['blocked_gates'] ?? []) as $risk) {
            $addRisk($risks, 'Launch Scorecard', (array) $risk, 'high', 'Clear launch scorecard gate');
        }
        foreach ((array) ($launchScorecard['warning_gates'] ?? []) as $risk) {
            $addRisk($risks, 'Launch Scorecard', (array) $risk, 'medium', 'Review launch scorecard warning');
        }
        foreach ((array) ($launchPacket['sections'] ?? []) as $section) {
            $status = (string) ($section['status'] ?? 'warning');
            if ($status === 'ready') {
                continue;
            }
            $addRisk(
                $risks,
                'Launch Packet',
                [
                    'label' => (string) ($section['label'] ?? 'Launch packet section'),
                    'message' => 'Resolve packet evidence before handing this campaign to an operator.',
                    'href' => (string) ($section['href'] ?? 'marketing_campaign_workspace.php?campaign_id=' . $campaignId),
                    'status' => $status,
                    'category' => (string) ($section['key'] ?? 'launch_packet'),
                ],
                $status === 'blocked' ? 'high' : 'medium',
                'Resolve launch packet section'
            );
        }
        if ($creativeReadiness !== null && (string) ($creativeReadiness['status'] ?? '') !== 'ready') {
            foreach ((array) ($creativeReadiness['queue'] ?? []) as $risk) {
                $addRisk(
                    $risks,
                    'Creative Readiness',
                    [
                        'label' => (string) ($risk['label'] ?? 'Creative requirement'),
                        'message' => (string) ($risk['reason'] ?? 'Resolve campaign creative requirement before export.'),
                        'href' => (string) ($risk['href'] ?? 'marketing_creative.php?campaign_id=' . $campaignId),
                        'status' => (string) ($risk['status'] ?? 'warning'),
                        'category' => 'creative',
                    ],
                    in_array((string) ($risk['status'] ?? ''), ['blocked', 'needs_requirements'], true) ? 'high' : 'medium',
                    'Resolve creative readiness'
                );
            }
        }

        $severityRank = ['high' => 0, 'medium' => 1, 'low' => 2];
        $riskRegister = array_values($risks);
        usort($riskRegister, static function (array $a, array $b) use ($severityRank): int {
            $severity = ($severityRank[(string) ($a['severity'] ?? 'medium')] ?? 1) <=> ($severityRank[(string) ($b['severity'] ?? 'medium')] ?? 1);
            if ($severity !== 0) {
                return $severity;
            }
            return strcmp((string) ($a['label'] ?? ''), (string) ($b['label'] ?? ''));
        });

        $gateStatus = [];
        foreach ((array) ($launchScorecard['gates'] ?? []) as $gate) {
            $gateStatus[(string) ($gate['key'] ?? '')] = (string) ($gate['status'] ?? 'warning');
        }
        $bundleStatus = static function (bool $ready, bool $required = true): string {
            if ($ready) {
                return 'ready';
            }
            return $required ? 'blocked' : 'warning';
        };
        $manualExportBundle = [
            [
                'key' => 'strategy_brief',
                'label' => 'Strategy Brief',
                'status' => $bundleStatus(($gateStatus['strategy_brief'] ?? '') === 'ready'),
                'href' => 'marketing_briefs.php?campaign_id=' . $campaignId,
                'detail' => $countLinked('briefs') . ' brief record(s) connected.',
            ],
            [
                'key' => 'audience',
                'label' => 'Audience Snapshot',
                'status' => $bundleStatus(($gateStatus['audience_selected'] ?? '') === 'ready'),
                'href' => 'marketing_audience_activation.php?campaign_id=' . $campaignId,
                'detail' => $countLinked('audience_activations') . ' activation(s) plus segment references in briefs, landing pages, or email runs.',
            ],
            [
                'key' => 'landing_page',
                'label' => 'Landing Page',
                'status' => $bundleStatus(($gateStatus['landing_page_ready'] ?? '') === 'ready'),
                'href' => 'marketing_landing_pages.php?campaign_id=' . $campaignId,
                'detail' => $countLinked('landing_pages') . ' conversion destination(s).',
            ],
            [
                'key' => 'content',
                'label' => 'Content Pack',
                'status' => $bundleStatus(($gateStatus['content_ready'] ?? '') === 'ready'),
                'href' => 'marketing_content.php?campaign_id=' . $campaignId,
                'detail' => $countLinked('content_items') . ' content item(s) connected.',
            ],
            [
                'key' => 'distribution',
                'label' => 'Distribution Export',
                'status' => $bundleStatus(($gateStatus['distribution_ready'] ?? '') === 'ready'),
                'href' => 'marketing_distribution.php?campaign_id=' . $campaignId,
                'detail' => ($countLinked('distribution_posts') + $countLinked('channel_exports') + $countLinked('email_runs')) . ' manual distribution/export artifact(s).',
            ],
            [
                'key' => 'tracking',
                'label' => 'Tracking Links',
                'status' => $bundleStatus(($gateStatus['utm_ready'] ?? '') === 'ready'),
                'href' => 'marketing_utm_links.php?campaign_id=' . $campaignId,
                'detail' => $countLinked('utm_links') . ' UTM/tracking link(s).',
            ],
            [
                'key' => 'approvals',
                'label' => 'Approval Evidence',
                'status' => $bundleStatus(($gateStatus['approval_complete'] ?? '') === 'ready'),
                'href' => 'marketing_reviews.php',
                'detail' => 'Approved content review evidence required before operator launch.',
            ],
            [
                'key' => 'creative_assets',
                'label' => 'Creative Assets',
                'status' => $creativeReadiness === null ? 'warning' : $bundleStatus((string) ($creativeReadiness['status'] ?? '') === 'ready', false),
                'href' => 'marketing_creative.php?campaign_id=' . $campaignId,
                'detail' => $creativeReadiness === null
                    ? 'Creative requirements are unavailable.'
                    : (int) ($creativeReadiness['counts']['ready'] ?? 0) . '/' . (int) ($creativeReadiness['counts']['total'] ?? 0) . ' campaign creative requirement(s) ready.',
            ],
            [
                'key' => 'launch_checklist',
                'label' => 'Launch Checklist',
                'status' => $bundleStatus(($gateStatus['manual_launch_checklist_complete'] ?? '') === 'ready'),
                'href' => 'marketing_launch_checklists.php?campaign_id=' . $campaignId,
                'detail' => $countLinked('launch_checklists') . ' final launch checklist(s).',
            ],
            [
                'key' => 'measurement',
                'label' => 'Measurement Baseline',
                'status' => $bundleStatus(($gateStatus['budget_or_experiment_ready'] ?? '') === 'ready', false),
                'href' => 'marketing_performance.php?campaign_id=' . $campaignId,
                'detail' => ($countLinked('budgets') + $countLinked('experiments')) . ' budget, ROI, or experiment baseline record(s).',
            ],
        ];

        $nextSteps = [];
        $addAction = static function (array &$nextSteps, array $action, string $source): void {
            $label = trim((string) ($action['label'] ?? 'Review campaign launch'));
            $href = (string) ($action['href'] ?? 'marketing_campaign_workspace.php');
            $key = strtolower($label . '|' . $href);
            if ($label === '' || isset($nextSteps[$key])) {
                return;
            }
            $nextSteps[$key] = [
                'label' => $label,
                'href' => $href,
                'reason' => (string) ($action['reason'] ?? $action['message'] ?? 'Review campaign launch workspace.'),
                'priority' => (string) ($action['priority'] ?? (!empty($action['required']) ? 'high' : 'medium')),
                'source' => $source,
            ];
        };
        foreach ((array) ($workspace['next_actions_json'] ?? []) as $action) {
            $addAction($nextSteps, (array) $action, 'Workspace');
        }
        foreach ((array) ($operatingRoom['next_actions'] ?? []) as $action) {
            $addAction($nextSteps, (array) $action, 'Operating Room');
        }
        foreach ((array) ($executionReadiness['next_actions'] ?? []) as $action) {
            $addAction($nextSteps, (array) $action, 'Execution Readiness');
        }
        foreach ((array) ($launchScorecard['next_actions'] ?? []) as $action) {
            $addAction($nextSteps, (array) $action, 'Launch Scorecard');
        }
        foreach ((array) ($launchPacket['packet_actions'] ?? []) as $action) {
            $addAction($nextSteps, (array) $action, 'Launch Packet');
        }
        if ($nextSteps === []) {
            $addAction($nextSteps, [
                'label' => 'Hand off manual launch packet',
                'href' => 'marketing_campaign_workspace.php?campaign_id=' . $campaignId,
                'reason' => 'All required launch gates are clear. Confirm owner, export files, and measurement baseline before manual execution.',
                'priority' => 'medium',
            ], 'Launch Workspace');
        }

        $highRisks = count(array_filter($riskRegister, static fn(array $risk): bool => (string) ($risk['severity'] ?? '') === 'high'));
        $readyBundleItems = count(array_filter($manualExportBundle, static fn(array $item): bool => (string) ($item['status'] ?? '') === 'ready'));
        $status = match (true) {
            $highRisks > 0 => 'blocked',
            (bool) ($launchScorecard['ready_for_manual_launch'] ?? false)
                && (bool) ($launchPacket['ready_for_manual_launch'] ?? false)
                && (bool) ($executionReadiness['ready_to_launch'] ?? false) => 'ready_for_manual_launch',
            default => 'needs_attention',
        };

        $integrationLinks = [
            ['label' => 'CRM Campaign', 'href' => 'campaigns.php', 'count' => 1],
            ['label' => 'Briefs', 'href' => 'marketing_briefs.php?campaign_id=' . $campaignId, 'count' => $countLinked('briefs')],
            ['label' => 'Audience', 'href' => 'marketing_audience_activation.php?campaign_id=' . $campaignId, 'count' => $countLinked('audience_activations')],
            ['label' => 'Landing Pages', 'href' => 'marketing_landing_pages.php?campaign_id=' . $campaignId, 'count' => $countLinked('landing_pages')],
            ['label' => 'Content Studio', 'href' => 'marketing_content.php?campaign_id=' . $campaignId, 'count' => $countLinked('content_items')],
            ['label' => 'Distribution', 'href' => 'marketing_distribution.php?campaign_id=' . $campaignId, 'count' => $countLinked('distribution_posts')],
            ['label' => 'Creative Requirements', 'href' => 'marketing_creative.php?campaign_id=' . $campaignId, 'count' => (int) ($creativeReadiness['counts']['total'] ?? 0)],
            ['label' => 'Channel Exports', 'href' => 'marketing_channel_exports.php?campaign_id=' . $campaignId, 'count' => $countLinked('channel_exports')],
            ['label' => 'Email Runs', 'href' => 'marketing_email_runs.php?campaign_id=' . $campaignId, 'count' => $countLinked('email_runs')],
            ['label' => 'UTM Links', 'href' => 'marketing_utm_links.php?campaign_id=' . $campaignId, 'count' => $countLinked('utm_links')],
            ['label' => 'Launch Control', 'href' => 'marketing_launch_control.php?campaign_id=' . $campaignId, 'count' => $countLinked('launch_control')],
            ['label' => 'Launch Checklists', 'href' => 'marketing_launch_checklists.php?campaign_id=' . $campaignId, 'count' => $countLinked('launch_checklists')],
            ['label' => 'Performance', 'href' => 'marketing_performance.php?campaign_id=' . $campaignId, 'count' => $countLinked('budgets') + $countLinked('experiments')],
        ];

        return [
            'campaign_id' => $campaignId,
            'campaign_name' => (string) ($workspace['campaign_name'] ?? ''),
            'readiness_score' => $readinessScore,
            'status' => $status,
            'ready_for_manual_launch' => $status === 'ready_for_manual_launch',
            'risk_register' => array_slice($riskRegister, 0, 12),
            'manual_export_bundle' => $manualExportBundle,
            'owner_next_steps' => array_slice(array_values($nextSteps), 0, 10),
            'integration_links' => $integrationLinks,
            'counts' => [
                'risks_high' => $highRisks,
                'risks_total' => count($riskRegister),
                'export_items_ready' => $readyBundleItems,
                'export_items_total' => count($manualExportBundle),
                'next_steps' => count($nextSteps),
            ],
            'component_scores' => [
                'workspace_health' => (int) ($workspace['health_score'] ?? 0),
                'operating_room' => (int) ($operatingRoom['health_score'] ?? 0),
                'execution_readiness' => (int) ($executionReadiness['score'] ?? 0),
                'launch_scorecard' => (int) ($launchScorecard['score'] ?? 0),
                'launch_packet' => (int) ($launchPacket['score'] ?? 0),
            ],
            'guardrails' => [
                'manual_first' => true,
                'external_publish' => false,
                'external_send' => false,
                'external_ads' => false,
                'message' => 'Launch Workspace V2 packages evidence for human operators only; it does not send, publish, post, start ads, or call external channel APIs.',
            ],
        ];
    }

    public function getCampaignExecutionActionCenter(int $campaignId, ?int $userId = null): array
    {
        $this->assertMarketingPermission('marketing.read');
        $workspace = $this->getMarketingCampaignWorkspace($campaignId);
        if (!$workspace) {
            throw new RuntimeException('Campaign was not found in the active workspace.');
        }

        $userId = $userId ?? $this->currentUserId();
        $launch = $this->getCampaignLaunchWorkspaceV2Summary($campaignId);
        $packs = Database::tableExists('marketing_operator_export_packs')
            ? $this->listOperatorExportPacks(['campaign_id' => $campaignId], 10, 0)
            : [];
        $launchChecklists = Database::tableExists('marketing_campaign_launch_checklists')
            ? $this->listCampaignLaunchChecklists(['campaign_id' => $campaignId], 10, 0)
            : [];
        $creativeReadiness = Database::tableExists('marketing_campaign_creative_requirements')
            ? $this->getCampaignCreativeReadinessSummary($campaignId)
            : null;
        $taskHub = Database::tableExists('marketing_task_hub_preferences') && ($userId ?? 0) > 0
            ? $this->getMarketingTaskHub((int) $userId)
            : ['suggested_actions' => [], 'counts' => []];
        $latestSnapshot = Database::tableExists('marketing_execution_action_snapshots')
            ? $this->getLatestCampaignExecutionActionSnapshot($campaignId)
            : null;

        $actions = [];
        $seen = [];
        $priorityRank = ['urgent' => 4, 'high' => 3, 'normal' => 2, 'medium' => 2, 'low' => 1];
        $addAction = static function (
            array &$actions,
            array &$seen,
            array $input,
            string $source,
            string $category,
            string $fallbackHref,
            string $fallbackPriority,
            string $command
        ): void {
            $label = trim((string) ($input['label'] ?? $input['title'] ?? $command));
            if ($label === '') {
                $label = $command;
            }
            $href = trim((string) ($input['href'] ?? '')) ?: $fallbackHref;
            $key = strtolower($label . '|' . $href . '|' . $source);
            if (isset($seen[$key])) {
                return;
            }
            $seen[$key] = true;
            $priority = strtolower(trim((string) ($input['priority'] ?? $fallbackPriority)));
            if (!in_array($priority, ['urgent', 'high', 'normal', 'medium', 'low'], true)) {
                $priority = $fallbackPriority;
            }
            $actions[] = [
                'label' => $label,
                'href' => $href,
                'reason' => trim((string) ($input['reason'] ?? $input['message'] ?? $input['detail'] ?? 'Review this campaign execution action.')),
                'priority' => $priority,
                'source' => $source,
                'category' => $category,
                'command' => $command,
                'status' => (string) ($input['status'] ?? ($priority === 'high' || $priority === 'urgent' ? 'blocked' : 'warning')),
            ];
        };

        foreach ((array) ($launch['risk_register'] ?? []) as $risk) {
            $severity = (string) ($risk['severity'] ?? 'medium');
            $addAction(
                $actions,
                $seen,
                (array) $risk + ['priority' => $severity === 'high' ? 'high' : 'medium'],
                'Risk Register',
                (string) ($risk['category'] ?? 'launch_risk'),
                'marketing_campaign_workspace.php?campaign_id=' . $campaignId,
                $severity === 'high' ? 'high' : 'medium',
                'Unblock campaign risk'
            );
        }
        foreach ((array) ($launch['manual_export_bundle'] ?? []) as $bundle) {
            $status = (string) ($bundle['status'] ?? 'warning');
            if ($status === 'ready') {
                continue;
            }
            $addAction(
                $actions,
                $seen,
                (array) $bundle + ['priority' => $status === 'blocked' ? 'high' : 'medium'],
                'Manual Export Bundle',
                'export_packaging',
                'marketing_campaign_workspace.php?campaign_id=' . $campaignId,
                $status === 'blocked' ? 'high' : 'medium',
                'Prepare export artifact'
            );
        }
        foreach ((array) ($launch['owner_next_steps'] ?? []) as $step) {
            $addAction(
                $actions,
                $seen,
                (array) $step,
                (string) ($step['source'] ?? 'Launch Workspace'),
                'owner_next_step',
                'marketing_campaign_workspace.php?campaign_id=' . $campaignId,
                (string) ($step['priority'] ?? 'normal'),
                'Do next safest step'
            );
        }
        foreach (array_slice((array) ($taskHub['suggested_actions'] ?? []), 0, 3) as $taskAction) {
            $addAction(
                $actions,
                $seen,
                (array) $taskAction,
                'Task Hub',
                'operator_queue',
                'marketing_task_hub.php',
                'normal',
                'Clear operator queue'
            );
        }
        if ($creativeReadiness !== null && (string) ($creativeReadiness['status'] ?? '') !== 'ready') {
            $addAction(
                $actions,
                $seen,
                [
                    'label' => 'Resolve campaign creative requirements',
                    'href' => 'marketing_creative.php?campaign_id=' . $campaignId,
                    'reason' => (int) ($creativeReadiness['counts']['ready'] ?? 0) . '/' . (int) ($creativeReadiness['counts']['total'] ?? 0) . ' creative requirement(s) are launch-ready.',
                    'priority' => (string) ($creativeReadiness['status'] ?? '') === 'blocked' ? 'high' : 'medium',
                    'status' => (string) ($creativeReadiness['status'] ?? 'needs_attention'),
                ],
                'Creative Readiness',
                'creative',
                'marketing_creative.php?campaign_id=' . $campaignId,
                (string) ($creativeReadiness['status'] ?? '') === 'blocked' ? 'high' : 'medium',
                'Attach approved media'
            );
        }

        usort($actions, static function (array $left, array $right) use ($priorityRank): int {
            $leftRank = $priorityRank[(string) ($left['priority'] ?? 'normal')] ?? 2;
            $rightRank = $priorityRank[(string) ($right['priority'] ?? 'normal')] ?? 2;
            if ($leftRank !== $rightRank) {
                return $rightRank <=> $leftRank;
            }

            return strcmp((string) ($left['source'] ?? ''), (string) ($right['source'] ?? ''));
        });

        $quickCommands = [
            [
                'label' => 'Refresh workspace',
                'href' => 'marketing_campaign_workspace.php?campaign_id=' . $campaignId,
                'action' => 'refresh_workspace',
                'requires_write' => true,
                'description' => 'Rebuild readiness from the latest connected Marketing and CRM records.',
            ],
            [
                'label' => 'Create export pack',
                'href' => 'marketing_operator_export_packs.php?campaign_id=' . $campaignId,
                'action' => 'create_operator_export_pack',
                'requires_write' => true,
                'description' => 'Freeze the current manual handoff snapshot for operators.',
            ],
            [
                'label' => 'Save action snapshot',
                'href' => 'marketing_campaign_workspace.php?campaign_id=' . $campaignId,
                'action' => 'save_action_snapshot',
                'requires_write' => true,
                'description' => 'Persist the ranked action center state for audit and operator handoff.',
            ],
            ['label' => 'Launch checklist', 'href' => 'marketing_launch_checklists.php?campaign_id=' . $campaignId, 'action' => 'open_launch_checklist', 'requires_write' => false, 'description' => 'Review final manual go-live steps.'],
            ['label' => 'Creative requirements', 'href' => 'marketing_creative.php?campaign_id=' . $campaignId, 'action' => 'open_creative_requirements', 'requires_write' => false, 'description' => 'Check required campaign media and asset readiness.'],
            ['label' => 'Task Hub', 'href' => 'marketing_task_hub.php', 'action' => 'open_task_hub', 'requires_write' => false, 'description' => 'Open the operator work queue.'],
        ];

        $blockedPacks = count(array_filter($packs, static fn(array $pack): bool => (string) ($pack['status'] ?? '') === 'blocked'));
        $readyPacks = count(array_filter($packs, static fn(array $pack): bool => in_array((string) ($pack['status'] ?? ''), ['ready', 'ready_for_manual_launch'], true)));
        $readyChecklists = count(array_filter($launchChecklists, static fn(array $checklist): bool => in_array((string) ($checklist['status'] ?? ''), ['ready', 'completed'], true)));
        $urgentActions = count(array_filter($actions, static fn(array $action): bool => in_array((string) ($action['priority'] ?? ''), ['urgent', 'high'], true)));
        $status = match (true) {
            (string) ($launch['status'] ?? '') === 'ready_for_manual_launch' && $urgentActions === 0 => 'ready_for_manual_handoff',
            $urgentActions > 0 => 'blocked',
            default => 'needs_attention',
        };

        return [
            'campaign_id' => $campaignId,
            'campaign_name' => (string) ($workspace['campaign_name'] ?? ''),
            'status' => $status,
            'readiness_score' => (int) ($launch['readiness_score'] ?? 0),
            'actions' => array_slice($actions, 0, 10),
            'quick_commands' => $quickCommands,
            'operator_snapshot' => [
                'latest_export_pack' => $packs[0] ?? null,
                'latest_launch_checklist' => $launchChecklists[0] ?? null,
                'creative_readiness' => $creativeReadiness,
                'latest_action_snapshot' => $latestSnapshot,
            ],
            'counts' => [
                'actions_total' => count($actions),
                'urgent_actions' => $urgentActions,
                'export_packs' => count($packs),
                'export_packs_ready' => $readyPacks,
                'export_packs_blocked' => $blockedPacks,
                'launch_checklists' => count($launchChecklists),
                'launch_checklists_ready' => $readyChecklists,
                'task_hub_actions' => count((array) ($taskHub['suggested_actions'] ?? [])),
                'creative_requirements' => (int) ($creativeReadiness['counts']['total'] ?? 0),
                'creative_ready' => (int) ($creativeReadiness['counts']['ready'] ?? 0),
            ],
            'guardrails' => [
                'manual_first' => true,
                'external_publish' => false,
                'external_send' => false,
                'external_ads' => false,
                'message' => 'Execution Action Center ranks the next operator actions only. It does not send, publish, start ads, or call external channel APIs.',
            ],
        ];
    }

    public function createCampaignExecutionActionSnapshot(int $campaignId, ?int $userId = null): array
    {
        $this->assertMarketingPermission('marketing.write');
        if (!Database::tableExists('marketing_execution_action_snapshots')) {
            throw new RuntimeException('Marketing execution action snapshots are unavailable.');
        }

        $campaignId = max(0, $campaignId);
        $workspace = $this->getMarketingCampaignWorkspace($campaignId);
        if (!$workspace) {
            throw new RuntimeException('Campaign was not found in the active workspace.');
        }

        $userId = $userId ?? $this->currentUserId();
        if (($userId ?? 0) > 0) {
            $this->assertWorkspaceUser((int) $userId, $this->workspaceId());
        }

        $actionCenter = $this->getCampaignExecutionActionCenter($campaignId, $userId);
        $counts = (array) ($actionCenter['counts'] ?? []);
        $operatorSnapshot = (array) ($actionCenter['operator_snapshot'] ?? []);
        unset($operatorSnapshot['latest_action_snapshot']);
        Database::execute(
            "UPDATE marketing_execution_action_snapshots
             SET snapshot_status = 'superseded'
             WHERE workspace_id = ? AND campaign_id = ? AND snapshot_status = 'current'",
            [$this->workspaceId(), $campaignId]
        );

        Database::execute(
            "INSERT INTO marketing_execution_action_snapshots
             (workspace_id, campaign_id, uuid, snapshot_status, action_center_status, readiness_score,
              urgent_actions, actions_total, export_packs_ready, export_packs_total,
              launch_checklists_ready, launch_checklists_total, creative_ready, creative_total,
              actions_json, quick_commands_json, operator_snapshot_json, guardrails_json, metadata_json, created_by)
             VALUES (?, ?, ?, 'current', ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)",
            [
                $this->workspaceId(),
                $campaignId,
                $this->generateUuid(),
                $this->normalizeEnum((string) ($actionCenter['status'] ?? 'needs_attention'), ['ready_for_manual_handoff', 'needs_attention', 'blocked'], 'action_center_status'),
                (int) ($actionCenter['readiness_score'] ?? 0),
                (int) ($counts['urgent_actions'] ?? 0),
                (int) ($counts['actions_total'] ?? 0),
                (int) ($counts['export_packs_ready'] ?? 0),
                (int) ($counts['export_packs'] ?? 0),
                (int) ($counts['launch_checklists_ready'] ?? 0),
                (int) ($counts['launch_checklists'] ?? 0),
                (int) ($counts['creative_ready'] ?? 0),
                (int) ($counts['creative_requirements'] ?? 0),
                $this->normalizeJsonValue($this->sanitizeJsonCompatible((array) ($actionCenter['actions'] ?? []))),
                $this->normalizeJsonValue($this->sanitizeJsonCompatible((array) ($actionCenter['quick_commands'] ?? []))),
                $this->normalizeJsonValue($this->sanitizeJsonCompatible($operatorSnapshot)),
                $this->normalizeJsonValue($this->sanitizeJsonCompatible((array) ($actionCenter['guardrails'] ?? []))),
                $this->normalizeJsonValue([
                    'source' => 'marketing_execution_action_center',
                    'campaign_name' => (string) ($actionCenter['campaign_name'] ?? $workspace['campaign_name'] ?? ''),
                    'manual_first' => true,
                    'external_publish' => false,
                    'external_send' => false,
                    'generated_at' => date('c'),
                ]),
                ($userId ?? 0) > 0 ? (int) $userId : null,
            ]
        );

        return $this->getCampaignExecutionActionSnapshot((int) Database::lastInsertId()) ?? [];
    }

    public function listCampaignExecutionActionSnapshots(array $filters = [], int $limit = 100, int $offset = 0): array
    {
        $this->assertMarketingPermission('marketing.read');
        if (!Database::tableExists('marketing_execution_action_snapshots')) {
            return [];
        }

        $limit = min(max($limit, 1), 250);
        $offset = max($offset, 0);
        $where = ['s.workspace_id = ?'];
        $params = [$this->workspaceId()];
        if (!empty($filters['id'])) {
            $where[] = 's.id = ?';
            $params[] = (int) $filters['id'];
        }
        if (!empty($filters['campaign_id'])) {
            $where[] = 's.campaign_id = ?';
            $params[] = (int) $filters['campaign_id'];
        }
        if (!empty($filters['snapshot_status'])) {
            $where[] = 's.snapshot_status = ?';
            $params[] = $this->normalizeEnum((string) $filters['snapshot_status'], ['current', 'superseded', 'archived'], 'snapshot_status');
        }

        $rows = Database::query(
            "SELECT s.*, c.name AS campaign_name, u.email AS created_by_email
             FROM marketing_execution_action_snapshots s
             JOIN campaigns c ON c.id = s.campaign_id AND c.workspace_id = s.workspace_id
             LEFT JOIN users u ON u.id = s.created_by
             WHERE " . implode(' AND ', $where) . "
             ORDER BY s.created_at DESC, s.id DESC
             LIMIT {$limit} OFFSET {$offset}",
            $params
        );

        return array_map(fn(array $row): array => $this->hydrateExecutionActionSnapshotRow($row), $rows);
    }

    public function getCampaignExecutionActionSnapshot(int $id): ?array
    {
        $rows = $this->listCampaignExecutionActionSnapshots(['id' => $id], 1, 0);
        return $rows[0] ?? null;
    }

