    public function getMarketingExecutionEvidenceSummary(?string $periodStart = null, ?string $periodEnd = null, int $limit = 6): array
    {
        $this->assertMarketingPermission('marketing.read');
        $limit = min(max($limit, 1), 25);
        $empty = [
            'status' => 'needs_evidence',
            'period' => ['start' => $periodStart, 'end' => $periodEnd],
            'counts' => [
                'total' => 0,
                'current' => 0,
                'superseded' => 0,
                'archived' => 0,
                'ready_for_manual_handoff' => 0,
                'needs_attention' => 0,
                'blocked' => 0,
                'campaigns_with_current_snapshots' => 0,
                'urgent_actions' => 0,
                'actions_total' => 0,
            ],
            'average_readiness' => null,
            'latest_snapshot_at' => null,
            'latest_snapshots' => [],
            'recommended_actions' => [
                'Save an action snapshot from each active campaign workspace before launch handoff.',
            ],
            'guardrails' => [
                'manual_first' => true,
                'external_publish' => false,
                'external_send' => false,
                'external_ads' => false,
                'message' => 'Execution evidence summarizes saved operator snapshots only. It does not send, publish, start ads, or call external channel APIs.',
            ],
        ];

        if (!Database::tableExists('marketing_execution_action_snapshots')) {
            $empty['status'] = 'unavailable';
            $empty['recommended_actions'] = ['Run the latest Marketing migrations before relying on execution evidence reports.'];
            return $empty;
        }

        $where = ['s.workspace_id = ?'];
        $params = [$this->workspaceId()];
        $normalizedStart = null;
        $normalizedEnd = null;
        if (trim((string) $periodStart) !== '') {
            $normalizedStart = $this->normalizeDate((string) $periodStart, 'execution evidence start date');
            $where[] = 's.created_at >= ?';
            $params[] = $normalizedStart;
        }
        if (trim((string) $periodEnd) !== '') {
            $normalizedEnd = $this->normalizeDate((string) $periodEnd, 'execution evidence end date');
            $where[] = 's.created_at < DATE_ADD(?, INTERVAL 1 DAY)';
            $params[] = $normalizedEnd;
        }

        $whereSql = implode(' AND ', $where);
        $totals = Database::queryOne(
            "SELECT COUNT(*) AS total,
                    SUM(CASE WHEN s.snapshot_status = 'current' THEN 1 ELSE 0 END) AS current_count,
                    SUM(CASE WHEN s.snapshot_status = 'superseded' THEN 1 ELSE 0 END) AS superseded_count,
                    SUM(CASE WHEN s.snapshot_status = 'archived' THEN 1 ELSE 0 END) AS archived_count,
                    SUM(CASE WHEN s.action_center_status = 'ready_for_manual_handoff' THEN 1 ELSE 0 END) AS ready_count,
                    SUM(CASE WHEN s.action_center_status = 'needs_attention' THEN 1 ELSE 0 END) AS attention_count,
                    SUM(CASE WHEN s.action_center_status = 'blocked' THEN 1 ELSE 0 END) AS blocked_count,
                    COUNT(DISTINCT CASE WHEN s.snapshot_status = 'current' THEN s.campaign_id ELSE NULL END) AS current_campaigns,
                    COALESCE(SUM(s.urgent_actions), 0) AS urgent_actions,
                    COALESCE(SUM(s.actions_total), 0) AS actions_total,
                    AVG(s.readiness_score) AS average_readiness,
                    MAX(s.created_at) AS latest_snapshot_at
             FROM marketing_execution_action_snapshots s
             WHERE {$whereSql}",
            $params
        );

        $rows = Database::query(
            "SELECT s.*, c.name AS campaign_name, u.email AS created_by_email
             FROM marketing_execution_action_snapshots s
             JOIN campaigns c ON c.id = s.campaign_id AND c.workspace_id = s.workspace_id
             LEFT JOIN users u ON u.id = s.created_by
             WHERE {$whereSql}
             ORDER BY s.created_at DESC, s.id DESC
             LIMIT {$limit}",
            $params
        );
        $latestSnapshots = array_map(fn(array $row): array => $this->hydrateExecutionActionSnapshotRow($row), $rows);

        $currentCount = (int) ($totals['current_count'] ?? 0);
        $blockedCount = (int) ($totals['blocked_count'] ?? 0);
        $urgentActions = (int) ($totals['urgent_actions'] ?? 0);
        $readyCount = (int) ($totals['ready_count'] ?? 0);
        $status = match (true) {
            $currentCount === 0 => 'needs_evidence',
            $blockedCount > 0 || $urgentActions > 0 => 'blocked',
            $readyCount > 0 => 'ready',
            default => 'needs_attention',
        };

        $recommendedActions = [];
        if ($currentCount === 0) {
            $recommendedActions[] = 'Save at least one current action snapshot from an active campaign workspace.';
        }
        if ($blockedCount > 0) {
            $recommendedActions[] = 'Review blocked campaign snapshots and clear launch blockers before handoff.';
        }
        if ($urgentActions > 0) {
            $recommendedActions[] = 'Resolve urgent operator actions captured in the latest campaign snapshots.';
        }
        if ($recommendedActions === []) {
            $recommendedActions[] = 'Keep saving action snapshots after major launch-readiness changes.';
        }

        return [
            'status' => $status,
            'period' => ['start' => $normalizedStart ?? $periodStart, 'end' => $normalizedEnd ?? $periodEnd],
            'counts' => [
                'total' => (int) ($totals['total'] ?? 0),
                'current' => $currentCount,
                'superseded' => (int) ($totals['superseded_count'] ?? 0),
                'archived' => (int) ($totals['archived_count'] ?? 0),
                'ready_for_manual_handoff' => $readyCount,
                'needs_attention' => (int) ($totals['attention_count'] ?? 0),
                'blocked' => $blockedCount,
                'campaigns_with_current_snapshots' => (int) ($totals['current_campaigns'] ?? 0),
                'urgent_actions' => $urgentActions,
                'actions_total' => (int) ($totals['actions_total'] ?? 0),
            ],
            'average_readiness' => $totals['average_readiness'] !== null ? round((float) $totals['average_readiness'], 1) : null,
            'latest_snapshot_at' => $totals['latest_snapshot_at'] ?? null,
            'latest_snapshots' => $latestSnapshots,
            'recommended_actions' => $recommendedActions,
            'guardrails' => $empty['guardrails'],
        ];
    }

    public function getMarketingDecisionCenter(?int $userId = null, int $limit = 12): array
    {
        $this->assertMarketingPermission('marketing.read');
        $limit = min(max($limit, 1), 50);
        $counts = [
            'total' => 0,
            'open' => 0,
            'accepted' => 0,
            'rejected' => 0,
            'deferred' => 0,
            'archived' => 0,
            'urgent' => 0,
            'high' => 0,
        ];
        if (Database::tableExists('marketing_decision_center_items')) {
            $rows = Database::query(
                "SELECT decision_status, priority, COUNT(*) AS count
                 FROM marketing_decision_center_items
                 WHERE workspace_id = ?
                 GROUP BY decision_status, priority",
                [$this->workspaceId()]
            );
            foreach ($rows as $row) {
                $status = (string) ($row['decision_status'] ?? '');
                $priority = (string) ($row['priority'] ?? '');
                $count = (int) ($row['count'] ?? 0);
                $counts['total'] += $count;
                if (array_key_exists($status, $counts)) {
                    $counts[$status] += $count;
                }
                if ($priority === 'urgent') {
                    $counts['urgent'] += $count;
                }
                if ($priority === 'high') {
                    $counts['high'] += $count;
                }
            }
        }

        $savedDecisions = $this->listMarketingDecisions(['open' => true], $limit, 0);
        $suggestedDecisions = $this->buildMarketingDecisionSuggestions($userId, $limit);
        $status = match (true) {
            $counts['urgent'] > 0 => 'urgent_decisions',
            $counts['open'] > 0 => 'open_decisions',
            $suggestedDecisions !== [] => 'suggested_decisions',
            default => 'ready',
        };

        return [
            'status' => $status,
            'counts' => $counts,
            'saved_decisions' => $savedDecisions,
            'suggested_decisions' => $suggestedDecisions,
            'next_decision' => $savedDecisions[0] ?? $suggestedDecisions[0] ?? null,
            'guardrails' => [
                'manual_first' => true,
                'external_publish' => false,
                'external_send' => false,
                'external_ads' => false,
                'message' => 'Decision Center records human product and launch choices. It does not send, publish, start ads, or call external channel APIs.',
            ],
        ];
    }

    public function listMarketingDecisions(array $filters = [], int $limit = 100, int $offset = 0): array
    {
        $this->assertMarketingPermission('marketing.read');
        if (!Database::tableExists('marketing_decision_center_items')) {
            return [];
        }

        $limit = min(max($limit, 1), 250);
        $offset = max($offset, 0);
        $where = ['d.workspace_id = ?'];
        $params = [$this->workspaceId()];
        if (!empty($filters['id'])) {
            $where[] = 'd.id = ?';
            $params[] = (int) $filters['id'];
        }
        if (!empty($filters['decision_status'])) {
            $where[] = 'd.decision_status = ?';
            $params[] = $this->normalizeEnum((string) $filters['decision_status'], self::DECISION_STATUSES, 'decision_status');
        }
        if (!empty($filters['status'])) {
            $where[] = 'd.decision_status = ?';
            $params[] = $this->normalizeEnum((string) $filters['status'], self::DECISION_STATUSES, 'decision_status');
        }
        if (!empty($filters['open'])) {
            $where[] = "d.decision_status IN ('open','deferred')";
        }
        if (!empty($filters['priority'])) {
            $where[] = 'd.priority = ?';
            $params[] = $this->normalizeEnum((string) $filters['priority'], self::DECISION_PRIORITIES, 'priority');
        }
        if (!empty($filters['decision_type'])) {
            $where[] = 'd.decision_type = ?';
            $params[] = $this->normalizeEnum((string) $filters['decision_type'], self::DECISION_TYPES, 'decision_type');
        }
        if (!empty($filters['source_type'])) {
            $where[] = 'd.source_type = ?';
            $params[] = $this->normalizeEnum((string) $filters['source_type'], self::DECISION_SOURCE_TYPES, 'source_type');
        }
        if (!empty($filters['campaign_id'])) {
            $where[] = 'd.campaign_id = ?';
            $params[] = (int) $filters['campaign_id'];
        }
        if (!empty($filters['owner_user_id'])) {
            $where[] = 'd.owner_user_id = ?';
            $params[] = (int) $filters['owner_user_id'];
        }

        $rows = Database::query(
            "SELECT d.*,
                    c.name AS campaign_name,
                    ci.title AS content_title,
                    lp.title AS landing_page_title,
                    mf.title AS media_title,
                    dp.channel AS distribution_channel,
                    owner.email AS owner_email,
                    creator.email AS created_by_email,
                    decider.email AS decided_by_email
             FROM marketing_decision_center_items d
             LEFT JOIN campaigns c ON c.id = d.campaign_id AND c.workspace_id = d.workspace_id
             LEFT JOIN marketing_content_items ci ON ci.id = d.content_item_id AND ci.workspace_id = d.workspace_id
             LEFT JOIN marketing_landing_pages lp ON lp.id = d.landing_page_id AND lp.workspace_id = d.workspace_id
             LEFT JOIN marketing_media_files mf ON mf.id = d.media_file_id AND mf.workspace_id = d.workspace_id
             LEFT JOIN marketing_distribution_posts dp ON dp.id = d.distribution_post_id AND dp.workspace_id = d.workspace_id
             LEFT JOIN users owner ON owner.id = d.owner_user_id
             LEFT JOIN users creator ON creator.id = d.created_by
             LEFT JOIN users decider ON decider.id = d.decided_by
             WHERE " . implode(' AND ', $where) . "
             ORDER BY FIELD(d.priority, 'urgent', 'high', 'normal', 'low'), d.due_at IS NULL, d.due_at ASC, d.updated_at DESC, d.id DESC
             LIMIT {$limit} OFFSET {$offset}",
            $params
        );

        return array_map(fn(array $row): array => $this->hydrateDecisionCenterRow($row), $rows);
    }

    public function getMarketingDecision(int $id): ?array
    {
        $rows = $this->listMarketingDecisions(['id' => $id], 1, 0);
        return $rows[0] ?? null;
    }

    public function createMarketingDecision(array $data): int
    {
        $this->assertMarketingPermission('marketing.write');
        if (!Database::tableExists('marketing_decision_center_items')) {
            throw new RuntimeException('Marketing Decision Center is unavailable.');
        }

        $normalized = $this->normalizeMarketingDecisionData($data, true);
        Database::execute(
            "INSERT INTO marketing_decision_center_items
             (workspace_id, uuid, title, decision_type, decision_status, priority, source_type, source_id,
              campaign_id, content_item_id, landing_page_id, media_file_id, distribution_post_id,
              recommended_action, rationale, expected_impact, decision_note, due_at, decided_at, decided_by,
              owner_user_id, created_by, evidence_json, metadata_json)
             VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)",
            [
                $this->workspaceId(),
                $this->generateUuid(),
                $normalized['title'],
                $normalized['decision_type'],
                $normalized['decision_status'],
                $normalized['priority'],
                $normalized['source_type'],
                $normalized['source_id'],
                $normalized['campaign_id'],
                $normalized['content_item_id'],
                $normalized['landing_page_id'],
                $normalized['media_file_id'],
                $normalized['distribution_post_id'],
                $normalized['recommended_action'],
                $normalized['rationale'],
                $normalized['expected_impact'],
                $normalized['decision_note'],
                $normalized['due_at'],
                $normalized['decided_at'],
                $normalized['decided_by'],
                $normalized['owner_user_id'],
                $normalized['created_by'],
                $normalized['evidence_json'],
                $normalized['metadata_json'],
            ]
        );

        $id = (int) Database::lastInsertId();
        $this->recordMarketingAuditEvent(
            'decision_created',
            'marketing_decision_center_items',
            $id,
            'Marketing decision created.',
            ['decision_type' => $normalized['decision_type'], 'priority' => $normalized['priority']],
            (int) ($normalized['created_by'] ?? 0) ?: null
        );

        return $id;
    }

    public function updateMarketingDecision(int $id, array $data): bool
    {
        $this->assertMarketingPermission('marketing.write');
        $existing = $this->getMarketingDecision($id);
        if (!$existing) {
            throw new RuntimeException('Marketing decision was not found in the active workspace.');
        }
        if (($data['decision_status'] ?? $data['status'] ?? null) === 'archived') {
            $this->assertMarketingPermission('marketing.manage');
        }

        $normalized = $this->normalizeMarketingDecisionData(array_merge($existing, $data), false);
        unset($normalized['created_by']);
        return $this->updateById('marketing_decision_center_items', $id, $normalized);
    }

    public function decideMarketingDecision(int $id, string $status, string $note = '', ?int $userId = null): bool
    {
        $this->assertMarketingPermission('marketing.write');
        $status = $this->normalizeEnum($status, ['accepted', 'rejected', 'deferred', 'open'], 'decision_status');
        $userId = $userId ?? $this->currentUserId();
        if (($userId ?? 0) > 0) {
            $this->assertWorkspaceUser((int) $userId, $this->workspaceId());
        }

        return $this->updateMarketingDecision($id, [
            'decision_status' => $status,
            'decision_note' => $note,
            'decided_at' => $status === 'open' ? null : date('Y-m-d H:i:s'),
            'decided_by' => $status === 'open' ? null : (($userId ?? 0) > 0 ? (int) $userId : null),
        ]);
    }

    public function archiveMarketingDecision(int $id, ?int $userId = null): bool
    {
        $this->assertMarketingPermission('marketing.manage');
        $userId = $userId ?? $this->currentUserId();

        return $this->updateMarketingDecision($id, [
            'decision_status' => 'archived',
            'decision_note' => 'Archived from Decision Center.',
            'decided_at' => date('Y-m-d H:i:s'),
            'decided_by' => ($userId ?? 0) > 0 ? (int) $userId : null,
        ]);
    }

    private function hydrateExecutionActionSnapshotRow(array $row): array
    {
        $row = $this->hydrateJsonFields($row, [
            'actions_json',
            'quick_commands_json',
            'operator_snapshot_json',
            'guardrails_json',
            'metadata_json',
        ]);
        foreach ([
            'id',
            'workspace_id',
            'campaign_id',
            'readiness_score',
            'urgent_actions',
            'actions_total',
            'export_packs_ready',
            'export_packs_total',
            'launch_checklists_ready',
            'launch_checklists_total',
            'creative_ready',
            'creative_total',
        ] as $field) {
            $row[$field] = (int) ($row[$field] ?? 0);
        }

        return $row;
    }

    private function hydrateDecisionCenterRow(array $row): array
    {
        $row = $this->hydrateJsonFields($row, ['evidence_json', 'metadata_json']);
        foreach ([
            'id',
            'workspace_id',
            'source_id',
            'campaign_id',
            'content_item_id',
            'landing_page_id',
            'media_file_id',
            'distribution_post_id',
            'decided_by',
            'owner_user_id',
            'created_by',
        ] as $field) {
            $row[$field] = isset($row[$field]) && $row[$field] !== null ? (int) $row[$field] : null;
        }

        return $row;
    }

    private function hydrateCampaignCopilotRunRow(array $row): array
    {
        $row = $this->hydrateJsonFields($row, [
            'prompt_context_json',
            'context_used_json',
            'result_json',
            'provider_metadata_json',
        ]);
        foreach (['id', 'workspace_id', 'campaign_id', 'created_by'] as $field) {
            $row[$field] = isset($row[$field]) && $row[$field] !== null ? (int) $row[$field] : null;
        }

        return $row;
    }

    private function buildCampaignCopilotResult(array $console, string $runType): array
    {
        $actions = (array) ($console['action_center']['actions'] ?? []);
        $decisionCount = (int) ($console['counts']['open_decisions'] ?? 0);
        $urgentActions = (int) ($console['counts']['urgent_actions'] ?? 0);
        $mediaWorkCount = (int) ($console['counts']['media_production_work'] ?? 0);
        $mediaBlockedCount = (int) ($console['counts']['media_production_blocked'] ?? 0);
        $hasSnapshot = (bool) ($console['counts']['has_action_snapshot'] ?? 0);
        $recommendations = [];

        if ($urgentActions > 0) {
            $recommendations[] = [
                'label' => 'Clear urgent launch actions',
                'reason' => $urgentActions . ' urgent action(s) are blocking clean manual handoff.',
                'href' => 'marketing_campaign_workspace.php?campaign_id=' . (int) ($console['campaign_id'] ?? 0),
                'priority' => 'urgent',
            ];
        }
        if ($decisionCount > 0) {
            $recommendations[] = [
                'label' => 'Resolve open campaign decisions',
                'reason' => $decisionCount . ' open decision(s) need human approval, rejection, or deferral.',
                'href' => 'marketing_decisions.php',
                'priority' => 'high',
            ];
        }
        if ($mediaWorkCount > 0) {
            $recommendations[] = [
                'label' => 'Review campaign media production work',
                'reason' => $mediaWorkCount . ' media production work item(s) are still active for this campaign.',
                'href' => 'marketing_creative.php?campaign_id=' . (int) ($console['campaign_id'] ?? 0) . '#media-production-workflow',
                'priority' => $mediaBlockedCount > 0 ? 'urgent' : 'high',
            ];
        }
        if (!$hasSnapshot) {
            $recommendations[] = [
                'label' => 'Save action snapshot',
                'reason' => 'No durable action-center evidence is saved for this campaign.',
                'href' => 'marketing_campaign_workspace.php?campaign_id=' . (int) ($console['campaign_id'] ?? 0),
                'priority' => 'high',
            ];
        }
        foreach (array_slice($actions, 0, 3) as $action) {
            $recommendations[] = [
                'label' => (string) ($action['label'] ?? 'Review action'),
                'reason' => (string) ($action['reason'] ?? 'Review this execution action.'),
                'href' => (string) ($action['href'] ?? 'marketing_campaign_workspace.php?campaign_id=' . (int) ($console['campaign_id'] ?? 0)),
                'priority' => (string) ($action['priority'] ?? 'normal'),
            ];
        }
        if ($recommendations === []) {
            $recommendations[] = [
                'label' => 'Prepare operator handoff',
                'reason' => 'The campaign has no urgent blockers in the current console context.',
                'href' => 'marketing_campaign_workspace.php?campaign_id=' . (int) ($console['campaign_id'] ?? 0),
                'priority' => 'normal',
            ];
        }

        $summaryByType = match ($runType) {
            'campaign_plan' => 'Prioritize the next launch path, owner decisions, content sequence, and export package for this campaign.',
            'missing_assets' => 'Review missing creative, media, proof, and accessibility items before manual export.',
            'launch_checklist' => 'Convert current readiness gaps into a launch checklist the operator can verify.',
            'content_sequence' => 'Use current readiness and decisions to order the next content and channel steps.',
            'operator_handoff' => 'Summarize the current evidence and handoff actions for a human operator.',
            'blocked_explanation' => 'Explain what is blocking this campaign and where the operator should intervene.',
            default => 'Summarize campaign readiness and next best manual actions.',
        };

        return [
            'title' => 'Campaign copilot: ' . str_replace('_', ' ', $runType),
            'summary' => $summaryByType,
            'campaign_status' => (string) ($console['status'] ?? 'needs_attention'),
            'readiness_score' => (int) ($console['readiness_score'] ?? 0),
            'recommendations' => array_slice($recommendations, 0, 8),
            'draft_side_effects' => [],
            'allowed_side_effects' => ['create_decisions', 'create_comments', 'create_tool_runs'],
            'manual_first_boundary' => [
                'external_publish' => false,
                'external_send' => false,
                'external_generation' => false,
                'overwrites_records' => false,
            ],
        ];
    }

    /**
     * @return array<int,array<string,mixed>>
     */
    private function buildMarketingDecisionSuggestions(?int $userId = null, int $limit = 12): array
    {
        $suggestions = [];
        $addSuggestion = static function (array &$suggestions, array $decision): void {
            $decision['is_suggestion'] = true;
            $decision['decision_status'] = 'suggested';
            $suggestions[] = $decision;
        };

        $evidence = $this->getMarketingExecutionEvidenceSummary(null, null, 5);
        if ((int) ($evidence['counts']['current'] ?? 0) === 0) {
            $addSuggestion($suggestions, [
                'title' => 'Decide how launch handoff evidence will be captured',
                'decision_type' => 'launch_readiness',
                'priority' => 'high',
                'source_type' => 'readiness',
                'recommended_action' => 'Require each launch campaign to save an action snapshot before operator handoff.',
                'rationale' => 'Current campaigns do not have durable launch action snapshots for reporting or audit.',
                'expected_impact' => 'Improves launch accountability and makes weekly reports more trustworthy.',
                'evidence_json' => $evidence,
            ]);
        }
        if ((int) ($evidence['counts']['urgent_actions'] ?? 0) > 0) {
            $addSuggestion($suggestions, [
                'title' => 'Decide owner for urgent launch actions',
                'decision_type' => 'campaign_blocker',
                'priority' => 'urgent',
                'source_type' => 'readiness',
                'recommended_action' => 'Assign a responsible owner to clear urgent actions before launch.',
                'rationale' => (int) ($evidence['counts']['urgent_actions'] ?? 0) . ' urgent action(s) are captured in saved execution snapshots.',
                'expected_impact' => 'Reduces blocked launch risk and keeps the manual-first launch path clear.',
                'evidence_json' => $evidence,
            ]);
        }

        if (Database::tableExists('marketing_launch_readiness_reviews')) {
            foreach ($this->listLaunchReadinessReviews(['open' => true], 5, 0) as $review) {
                if (!in_array((string) ($review['status'] ?? ''), ['blocked', 'needs_attention', 'draft'], true)) {
                    continue;
                }
                $addSuggestion($suggestions, [
                    'title' => 'Decide launch readiness path for ' . (string) ($review['launch_name'] ?? 'campaign launch'),
                    'decision_type' => 'launch_readiness',
                    'priority' => (string) ($review['status'] ?? '') === 'blocked' ? 'urgent' : 'high',
                    'source_type' => 'readiness',
                    'source_id' => (int) ($review['id'] ?? 0),
                    'campaign_id' => (int) ($review['campaign_id'] ?? 0) ?: null,
                    'recommended_action' => 'Choose whether to unblock, defer, or re-scope this launch before distribution work continues.',
                    'rationale' => 'Launch readiness is ' . (string) ($review['status'] ?? 'draft') . ' with a readiness score of ' . (int) ($review['readiness_score'] ?? 0) . '%.',
                    'expected_impact' => 'Prevents downstream content, media, and channel teams from preparing the wrong launch path.',
                    'evidence_json' => $review,
                ]);
            }
        }

        if (Database::tableExists('marketing_media_files')) {
            $missingAlt = $this->countRows('marketing_media_files', "media_type IN ('image','logo','thumbnail','banner') AND COALESCE(alt_text, '') = '' AND COALESCE(approval_status, 'draft') <> 'archived'");
            if ($missingAlt > 0) {
                $addSuggestion($suggestions, [
                    'title' => 'Decide accessibility owner for marketing media',
                    'decision_type' => 'media_readiness',
                    'priority' => 'high',
                    'source_type' => 'media',
                    'recommended_action' => 'Assign ownership for alt text and caption completion before channel exports are marked ready.',
                    'rationale' => $missingAlt . ' media file(s) are missing alt text.',
                    'expected_impact' => 'Improves accessibility, brand quality, and export readiness.',
                    'evidence_json' => ['missing_alt_text' => $missingAlt],
                ]);
            }
        }

        if (Database::tableExists('marketing_channel_connectors')) {
            $connectorDiagnostics = $this->getChannelConnectorDiagnostics();
            if (empty($connectorDiagnostics['live_execution_enabled']) && (int) ($connectorDiagnostics['total_connectors'] ?? 0) > 0) {
                $addSuggestion($suggestions, [
                    'title' => 'Decide connector activation boundary',
                    'decision_type' => 'integration_risk',
                    'priority' => 'normal',
                    'source_type' => 'readiness',
                    'recommended_action' => 'Keep connectors in dry-run mode until ownership, approval, and diagnostics are ready.',
                    'rationale' => 'Connectors exist, but live execution is not enabled.',
                    'expected_impact' => 'Preserves manual-first safety while preparing future integrations.',
                    'evidence_json' => $connectorDiagnostics,
                ]);
            }
        }

        return array_slice($suggestions, 0, min(max($limit, 1), 50));
    }

    public function listOperatorExportPacks(array $filters = [], int $limit = 100, int $offset = 0): array
    {
        $this->assertMarketingPermission('marketing.read');
        if (!Database::tableExists('marketing_operator_export_packs')) {
            return [];
        }

        $limit = min(max($limit, 1), 250);
        $offset = max($offset, 0);
        $workspace = $this->workspaceClause('oep.');
        $where = [$workspace['sql']];
        $params = $workspace['params'];

        if (!empty($filters['id'])) {
            $where[] = 'oep.id = ?';
            $params[] = (int) $filters['id'];
        }
        if (!empty($filters['campaign_id'])) {
            $where[] = 'oep.campaign_id = ?';
            $params[] = (int) $filters['campaign_id'];
        }
        if (!empty($filters['status'])) {
            $where[] = 'oep.status = ?';
            $params[] = $this->normalizeEnum((string) $filters['status'], ['draft', 'ready', 'blocked', 'archived'], 'operator_export_pack_status');
        }
        if (!empty($filters['open'])) {
            $where[] = "oep.status IN ('draft','ready','blocked')";
        }

        return array_map(
            fn(array $row): array => $this->hydrateJsonFields($row, [
                'risk_snapshot_json',
                'export_bundle_json',
                'next_steps_json',
                'integration_links_json',
                'guardrails_json',
                'metadata_json',
            ]),
            Database::query(
                "SELECT oep.*, c.name AS campaign_name, c.status AS campaign_status,
                        owner.email AS owner_email, preparer.email AS prepared_by_email, creator.email AS created_by_email
                 FROM marketing_operator_export_packs oep
                 JOIN campaigns c ON c.id = oep.campaign_id AND c.workspace_id = oep.workspace_id
                 LEFT JOIN users owner ON owner.id = oep.owner_user_id
                 LEFT JOIN users preparer ON preparer.id = oep.prepared_by
                 LEFT JOIN users creator ON creator.id = oep.created_by
                 WHERE " . implode(' AND ', $where) . "
                 ORDER BY oep.prepared_at DESC, oep.updated_at DESC
                 LIMIT {$limit} OFFSET {$offset}",
                $params
            )
        );
    }

    public function getOperatorExportPack(int $id): ?array
    {
        $rows = $this->listOperatorExportPacks(['id' => $id], 1, 0);
        return $rows[0] ?? null;
    }

    public function buildOperatorExportPackSnapshot(int $campaignId): array
    {
        $this->assertMarketingPermission('marketing.read');
        $workspace = $this->getMarketingCampaignWorkspace($campaignId);
        if (!$workspace) {
            throw new RuntimeException('Campaign was not found in the active workspace.');
        }

        $summary = $this->getCampaignLaunchWorkspaceV2Summary($campaignId);
        $status = match (true) {
            (int) ($summary['counts']['risks_high'] ?? 0) > 0 => 'blocked',
            !empty($summary['ready_for_manual_launch']) => 'ready',
            default => 'draft',
        };

        $copyReadySections = [];
        foreach ((array) ($summary['manual_export_bundle'] ?? []) as $item) {
            $copyReadySections[] = [
                'key' => (string) ($item['key'] ?? ''),
                'label' => (string) ($item['label'] ?? 'Export item'),
                'status' => (string) ($item['status'] ?? 'warning'),
                'detail' => (string) ($item['detail'] ?? ''),
                'href' => (string) ($item['href'] ?? 'marketing_campaign_workspace.php?campaign_id=' . $campaignId),
                'operator_instruction' => $this->operatorExportInstruction((string) ($item['key'] ?? ''), (string) ($item['status'] ?? 'warning')),
            ];
        }

        return [
            'campaign_id' => $campaignId,
            'campaign_name' => (string) ($summary['campaign_name'] ?? $workspace['campaign_name'] ?? 'Campaign'),
            'title' => trim((string) ($summary['campaign_name'] ?? $workspace['campaign_name'] ?? 'Campaign')) . ' Operator Export Pack',
            'status' => $status,
            'readiness_score' => (int) ($summary['readiness_score'] ?? 0),
            'risk_snapshot' => (array) ($summary['risk_register'] ?? []),
            'copy_ready_sections' => $copyReadySections,
            'manual_steps' => (array) ($summary['owner_next_steps'] ?? []),
            'integration_links' => (array) ($summary['integration_links'] ?? []),
            'component_scores' => (array) ($summary['component_scores'] ?? []),
            'guardrails' => (array) ($summary['guardrails'] ?? []),
            'generated_at' => date('c'),
            'metadata' => [
                'source' => 'campaign_launch_workspace_v2',
                'manual_first' => true,
                'external_publish' => false,
                'external_send' => false,
                'external_ads' => false,
                'workspace_status' => (string) ($workspace['status'] ?? 'draft'),
            ],
        ];
    }

    public function createOperatorExportPack(int $campaignId, ?int $userId = null): int
    {
        $this->assertMarketingPermission('marketing.write');
        if (!Database::tableExists('marketing_operator_export_packs')) {
            throw new RuntimeException('Marketing operator export packs are unavailable.');
        }

        $workspace = $this->getMarketingCampaignWorkspace($campaignId);
        if (!$workspace) {
            throw new RuntimeException('Campaign was not found in the active workspace.');
        }

        $userId = $userId ?? $this->currentUserId();
        if (($userId ?? 0) > 0) {
            $this->assertWorkspaceUser((int) $userId, $this->workspaceId());
        }
        $snapshot = $this->buildOperatorExportPackSnapshot($campaignId);
        $ownerUserId = (int) ($workspace['owner_user_id'] ?? 0) ?: (($userId ?? 0) > 0 ? (int) $userId : null);

        Database::execute(
            "INSERT INTO marketing_operator_export_packs
             (workspace_id, campaign_id, uuid, title, status, readiness_score, risk_snapshot_json,
              export_bundle_json, next_steps_json, integration_links_json, guardrails_json, metadata_json,
              owner_user_id, prepared_by, prepared_at, created_by)
             VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, NOW(), ?)",
            [
                $this->workspaceId(),
                $campaignId,
                $this->generateUuid(),
                substr(Security::sanitizeInput((string) ($snapshot['title'] ?? 'Operator Export Pack'), 'string'), 0, 190),
                (string) ($snapshot['status'] ?? 'draft'),
                (int) ($snapshot['readiness_score'] ?? 0),
                $this->normalizeJsonValue((array) ($snapshot['risk_snapshot'] ?? [])),
                $this->normalizeJsonValue((array) ($snapshot['copy_ready_sections'] ?? [])),
                $this->normalizeJsonValue((array) ($snapshot['manual_steps'] ?? [])),
                $this->normalizeJsonValue((array) ($snapshot['integration_links'] ?? [])),
                $this->normalizeJsonValue((array) ($snapshot['guardrails'] ?? [])),
                $this->normalizeJsonValue((array) ($snapshot['metadata'] ?? [])),
                $ownerUserId,
                ($userId ?? 0) > 0 ? (int) $userId : null,
                ($userId ?? 0) > 0 ? (int) $userId : null,
            ]
        );

        return (int) Database::lastInsertId();
    }

    public function archiveOperatorExportPack(int $id, ?int $userId = null): bool
    {
        $this->assertMarketingPermission('marketing.manage');
        $pack = $this->getOperatorExportPack($id);
        if (!$pack) {
            throw new RuntimeException('Marketing operator export pack not found.');
        }
        $userId = $userId ?? $this->currentUserId();
        if (($userId ?? 0) > 0) {
            $this->assertWorkspaceUser((int) $userId, $this->workspaceId());
        }

        Database::execute(
            "UPDATE marketing_operator_export_packs
             SET status = 'archived', archived_at = COALESCE(archived_at, NOW()), metadata_json = JSON_SET(COALESCE(metadata_json, JSON_OBJECT()), '$.archived_by', ?, '$.archived_at', ?)
             WHERE workspace_id = ? AND id = ?",
            [
                ($userId ?? 0) > 0 ? (int) $userId : null,
                date('c'),
                $this->workspaceId(),
                $id,
            ]
        );

        return true;
    }

    private function operatorExportInstruction(string $key, string $status): string
    {
        $verb = $status === 'ready' ? 'Copy or attach' : 'Complete and verify';
        return match ($key) {
            'strategy_brief' => $verb . ' the campaign brief before handoff.',
            'audience' => $verb . ' the audience snapshot, segment logic, and suppression notes.',
            'landing_page' => $verb . ' the landing page preview URL, CTA, form, and owner notes.',
            'content' => $verb . ' the approved content copy, media notes, and channel variants.',
            'distribution' => $verb . ' the manual channel export package and publishing checklist.',
            'tracking' => $verb . ' the destination URL and UTM tracking links.',
            'approvals' => $verb . ' approval evidence and decision notes.',
            'creative_assets' => $verb . ' approved campaign media, asset rights, and accessibility notes.',
            'launch_checklist' => $verb . ' the final launch checklist with owner sign-off.',
            'measurement' => $verb . ' the measurement baseline, ROI target, or experiment notes.',
            default => $verb . ' this launch artifact before manual execution.',
        };
    }

    public function listSavedViews(string $viewType = 'content', ?int $userId = null): array
    {
        if (!Database::tableExists('marketing_saved_views')) {
            return [];
        }

        $viewType = $this->normalizeEnum($viewType, self::SAVED_VIEW_TYPES, 'saved_view_type');
        $userId = $userId ?? $this->currentUserId();
        $params = [$this->workspaceId(), $viewType];
        $access = "scope = 'workspace'";
        if ($userId > 0) {
            $access .= ' OR user_id = ? OR created_by = ?';
            $params[] = $userId;
            $params[] = $userId;
        }

        return array_map(
            fn(array $row): array => $this->hydrateJsonFields($row, ['filters_json', 'sort_json']),
            Database::query(
                "SELECT sv.*, u.email AS created_by_email
                 FROM marketing_saved_views sv
                 LEFT JOIN users u ON u.id = sv.created_by
                 WHERE sv.workspace_id = ? AND sv.view_type = ? AND ({$access})
                 ORDER BY sv.is_default DESC, sv.updated_at DESC, sv.name ASC",
                $params
            )
        );
    }

    public function getSavedView(int $id, ?int $userId = null): ?array
    {
        if (!Database::tableExists('marketing_saved_views')) {
            return null;
        }

        $row = Database::queryOne(
            "SELECT sv.*, u.email AS created_by_email
             FROM marketing_saved_views sv
             LEFT JOIN users u ON u.id = sv.created_by
             WHERE sv.workspace_id = ? AND sv.id = ?",
            [$this->workspaceId(), $id]
        );
        if (!$row) {
            return null;
        }

        $userId = $userId ?? $this->currentUserId();
        if ((string) ($row['scope'] ?? '') !== 'workspace'
            && $userId > 0
            && (int) ($row['user_id'] ?? 0) !== $userId
            && (int) ($row['created_by'] ?? 0) !== $userId) {
            return null;
        }

        return $this->hydrateJsonFields($row, ['filters_json', 'sort_json']);
    }

    public function createSavedView(array $data): int
    {
        $this->assertMarketingPermission('marketing.write');
        $normalized = $this->normalizeSavedViewData($data, true);
        if ((int) $normalized['is_default'] === 1) {
            $this->clearSavedViewDefaults($normalized['view_type'], (int) ($normalized['user_id'] ?? 0), $normalized['scope']);
        }

        Database::execute(
            "INSERT INTO marketing_saved_views
             (workspace_id, uuid, view_type, name, scope, view_mode, filters_json, sort_json, is_default, user_id, created_by)
             VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)",
            [
                $this->workspaceId(),
                $this->generateUuid(),
                $normalized['view_type'],
                $normalized['name'],
                $normalized['scope'],
                $normalized['view_mode'],
                $normalized['filters_json'],
                $normalized['sort_json'],
                $normalized['is_default'],
                $normalized['user_id'],
                $normalized['created_by'],
            ]
        );

        return (int) Database::lastInsertId();
    }

    public function updateSavedView(int $id, array $data): bool
    {
        $this->assertMarketingPermission('marketing.write');
        $existing = $this->getSavedView($id);
        if (!$existing) {
            throw new RuntimeException('Marketing saved view not found.');
        }

        $normalized = $this->normalizeSavedViewData(array_merge($existing, $data), false);
        if (array_key_exists('is_default', $normalized) && (int) $normalized['is_default'] === 1) {
            $viewType = (string) ($normalized['view_type'] ?? $existing['view_type']);
            $scope = (string) ($normalized['scope'] ?? $existing['scope']);
            $ownerId = (int) ($normalized['user_id'] ?? $existing['user_id'] ?? 0);
            $this->clearSavedViewDefaults($viewType, $ownerId, $scope, $id);
        }

        return $this->updateById('marketing_saved_views', $id, $normalized);
    }

    public function deleteSavedView(int $id): bool
    {
        $existing = $this->getSavedView($id);
        if (!$existing) {
            throw new RuntimeException('Marketing saved view not found.');
        }
        $this->assertMarketingPermission((string) ($existing['scope'] ?? '') === 'workspace' ? 'marketing.manage' : 'marketing.write');

        Database::execute(
            'DELETE FROM marketing_saved_views WHERE workspace_id = ? AND id = ?',
            [$this->workspaceId(), $id]
        );

        return true;
    }

    public function getWorkbenchPreferences(?int $userId = null): array
    {
        if (!Database::tableExists('marketing_workbench_preferences')) {
            return ['default_view_mode' => 'list', 'preferences_json' => []];
        }

        $userId = $userId ?? $this->currentUserId();
        if ($userId <= 0) {
            return ['default_view_mode' => 'list', 'preferences_json' => []];
        }

        $row = Database::queryOne(
            'SELECT * FROM marketing_workbench_preferences WHERE workspace_id = ? AND user_id = ?',
            [$this->workspaceId(), $userId]
        );
        if (!$row) {
            return ['default_view_mode' => 'list', 'default_saved_view_id' => null, 'preferences_json' => []];
        }

        return $this->hydrateJsonFields($row, ['preferences_json']);
    }

    public function updateWorkbenchPreferences(array $data, ?int $userId = null): array
    {
        $this->assertMarketingPermission('marketing.write');
        $userId = $userId ?? $this->currentUserId();
        if ($userId <= 0) {
            throw new RuntimeException('A signed-in workspace user is required.');
        }
        $this->assertWorkspaceUser($userId, $this->workspaceId());

        $viewMode = $this->normalizeEnum((string) ($data['default_view_mode'] ?? 'list'), self::WORKBENCH_VIEW_MODES, 'view_mode');
        $savedViewId = (int) ($data['default_saved_view_id'] ?? 0);
        if ($savedViewId > 0 && !$this->getSavedView($savedViewId, $userId)) {
            throw new RuntimeException('Marketing saved view not found.');
        }

        Database::execute(
            "INSERT INTO marketing_workbench_preferences
             (workspace_id, user_id, default_view_mode, default_saved_view_id, preferences_json)
             VALUES (?, ?, ?, ?, ?)
             ON DUPLICATE KEY UPDATE
                default_view_mode = VALUES(default_view_mode),
                default_saved_view_id = VALUES(default_saved_view_id),
                preferences_json = VALUES(preferences_json)",
            [
                $this->workspaceId(),
                $userId,
                $viewMode,
                $savedViewId > 0 ? $savedViewId : null,
                $this->normalizeJsonValue($this->sanitizeFlexibleArray($data['preferences'] ?? $data['preferences_json'] ?? [])),
            ]
        );

        return $this->getWorkbenchPreferences($userId);
    }

    public function listAudienceSegments(array $filters = [], int $limit = 100, int $offset = 0): array
    {
        if (!Database::tableExists('marketing_audience_segments')) {
            return [];
        }

        $limit = min(max($limit, 1), 250);
        $offset = max($offset, 0);
        $workspace = $this->workspaceClause('s.');
        $where = [$workspace['sql']];
        $params = $workspace['params'];

        if (!empty($filters['status'])) {
            $where[] = 's.status = ?';
            $params[] = $this->normalizeEnum((string) $filters['status'], self::AUDIENCE_SEGMENT_STATUSES, 'segment_status');
        } elseif (!empty($filters['exclude_archived'])) {
            $where[] = "s.status <> 'archived'";
        }
        if (!empty($filters['source_scope'])) {
            $where[] = 's.source_scope = ?';
            $params[] = $this->normalizeEnum((string) $filters['source_scope'], self::AUDIENCE_SEGMENT_SOURCE_SCOPES, 'segment_source_scope');
        }
        if (!empty($filters['id'])) {
            $where[] = 's.id = ?';
            $params[] = (int) $filters['id'];
        }

        return array_map(
            fn(array $row): array => $this->hydrateAudienceSegmentRow($row),
            Database::query(
                "SELECT s.*, creator.email AS created_by_email,
                        COUNT(DISTINCT r.id) AS rule_count,
                        COUNT(DISTINCT snap.id) AS snapshot_count,
                        MAX(snap.created_at) AS latest_snapshot_at
                 FROM marketing_audience_segments s
                 LEFT JOIN marketing_segment_rules r ON r.segment_id = s.id AND r.workspace_id = s.workspace_id
                 LEFT JOIN marketing_segment_snapshots snap ON snap.segment_id = s.id AND snap.workspace_id = s.workspace_id
                 LEFT JOIN users creator ON creator.id = s.created_by
                 WHERE " . implode(' AND ', $where) . "
                 GROUP BY s.id
                 ORDER BY s.updated_at DESC, s.name ASC
                 LIMIT {$limit} OFFSET {$offset}",
                $params
            )
        );
    }

    public function getAudienceSegment(int $id): ?array
    {
        $segments = $this->listAudienceSegments(['id' => $id], 1, 0);
        if (empty($segments)) {
            return null;
        }

        $segment = $segments[0];
        $segment['rules'] = $this->listAudienceSegmentRules($id);
        $segment['snapshots'] = $this->listAudienceSegmentSnapshots($id, 10, 0);

        return $segment;
    }

    public function listAudienceSegmentRules(int $segmentId): array
    {
        if (!Database::tableExists('marketing_segment_rules')) {
            return [];
        }
        $this->assertWorkspaceRecord('marketing_audience_segments', $segmentId, $this->workspaceId());

        return array_map(
            fn(array $row): array => $this->hydrateJsonFields($row, ['value_json']),
            Database::query(
                'SELECT * FROM marketing_segment_rules WHERE workspace_id = ? AND segment_id = ? ORDER BY sort_order ASC, id ASC',
                [$this->workspaceId(), $segmentId]
            )
        );
    }

    public function listAudienceSegmentSnapshots(int $segmentId, int $limit = 20, int $offset = 0): array
    {
        if (!Database::tableExists('marketing_segment_snapshots')) {
            return [];
        }
        $this->assertWorkspaceRecord('marketing_audience_segments', $segmentId, $this->workspaceId());
        $limit = min(max($limit, 1), 100);
        $offset = max($offset, 0);

        return array_map(
            fn(array $row): array => $this->hydrateJsonFields($row, ['contact_ids_json', 'sample_contacts_json', 'criteria_json', 'metadata_json']),
            Database::query(
                "SELECT snap.*, creator.email AS created_by_email
                 FROM marketing_segment_snapshots snap
                 LEFT JOIN users creator ON creator.id = snap.created_by
                 WHERE snap.workspace_id = ? AND snap.segment_id = ?
                 ORDER BY snap.created_at DESC
                 LIMIT {$limit} OFFSET {$offset}",
                [$this->workspaceId(), $segmentId]
            )
        );
    }

    public function createAudienceSegment(array $data): int
    {
        $this->assertMarketingPermission('marketing.write');
        $normalized = $this->normalizeAudienceSegmentData($data, true);
        $rules = $this->normalizeAudienceSegmentRules($data['rules'] ?? $data['rules_json'] ?? []);

        Database::beginTransaction();
        try {
            Database::execute(
                "INSERT INTO marketing_audience_segments
                 (workspace_id, uuid, name, description, status, source_scope, rule_logic, metadata_json, created_by)
                 VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)",
                [
                    $this->workspaceId(),
                    $this->generateUuid(),
                    $normalized['name'],
                    $normalized['description'],
                    $normalized['status'],
                    $normalized['source_scope'],
                    $normalized['rule_logic'],
                    $normalized['metadata_json'],
                    $normalized['created_by'],
                ]
            );
            $id = (int) Database::lastInsertId();
            $this->replaceAudienceSegmentRules($id, $rules);
            $preview = $this->previewAudienceSegment($id, 10, false);
            Database::execute(
                'UPDATE marketing_audience_segments SET preview_count = ?, last_previewed_at = NOW() WHERE workspace_id = ? AND id = ?',
                [(int) $preview['count'], $this->workspaceId(), $id]
            );
            Database::commit();

            return $id;
        } catch (Throwable $e) {
            Database::rollBack();
            throw $e;
        }
    }

    public function updateAudienceSegment(int $id, array $data): bool
    {
        $this->assertMarketingPermission('marketing.write');
        $existing = $this->getAudienceSegment($id);
        if (!$existing) {
            throw new RuntimeException('Marketing audience segment not found.');
        }

        $normalized = $this->normalizeAudienceSegmentData(array_merge($existing, $data), false);
        $hasRules = array_key_exists('rules', $data) || array_key_exists('rules_json', $data);
        $rules = $hasRules ? $this->normalizeAudienceSegmentRules($data['rules'] ?? $data['rules_json'] ?? []) : null;

        Database::beginTransaction();
        try {
            $this->updateById('marketing_audience_segments', $id, $normalized);
            if ($rules !== null) {
                $this->replaceAudienceSegmentRules($id, $rules);
            }
            $preview = $this->previewAudienceSegment($id, 10, false);
            Database::execute(
                'UPDATE marketing_audience_segments SET preview_count = ?, last_previewed_at = NOW() WHERE workspace_id = ? AND id = ?',
                [(int) $preview['count'], $this->workspaceId(), $id]
            );
            Database::commit();
        } catch (Throwable $e) {
            Database::rollBack();
            throw $e;
        }

        return true;
    }

    public function deleteAudienceSegment(int $id): bool
    {
        $this->assertMarketingPermission('marketing.manage');
        $workspaceId = $this->workspaceId();
        $this->assertWorkspaceRecord('marketing_audience_segments', $id, $workspaceId);
        Database::beginTransaction();
        try {
            foreach ([
                'marketing_campaign_briefs' => 'audience_segment_id = NULL',
                'marketing_landing_pages' => 'audience_segment_id = NULL',
                'marketing_email_campaign_runs' => 'audience_segment_id = NULL, segment_snapshot_id = NULL',
                'marketing_channel_export_bundles' => 'audience_segment_id = NULL, segment_snapshot_id = NULL',
            ] as $table => $setSql) {
                if (Database::tableExists($table)) {
                    Database::execute(
                        "UPDATE {$table} SET {$setSql} WHERE workspace_id = ? AND audience_segment_id = ?",
                        [$workspaceId, $id]
                    );
                }
            }
            Database::execute(
                'DELETE FROM marketing_audience_segments WHERE workspace_id = ? AND id = ?',
                [$workspaceId, $id]
            );
            Database::commit();
        } catch (Throwable $e) {
            Database::rollBack();
            throw $e;
        }

        return true;
    }

    public function previewAudienceSegment(int $id, int $limit = 50, bool $touch = true): array
    {
        $segment = $this->getAudienceSegment($id);
        if (!$segment) {
            throw new RuntimeException('Marketing audience segment not found.');
        }

        $preview = $this->evaluateAudienceSegmentRules(
            (array) ($segment['rules'] ?? []),
            (string) ($segment['rule_logic'] ?? 'all'),
            $limit
        );
        if ($touch) {
            Database::execute(
                'UPDATE marketing_audience_segments SET preview_count = ?, last_previewed_at = NOW() WHERE workspace_id = ? AND id = ?',
                [(int) $preview['count'], $this->workspaceId(), $id]
            );
        }

        return $preview + [
            'segment_id' => $id,
            'segment_name' => (string) ($segment['name'] ?? ''),
            'rule_logic' => (string) ($segment['rule_logic'] ?? 'all'),
        ];
    }

    public function previewAudienceRules(array $rules, string $ruleLogic = 'all', int $limit = 50): array
    {
        $normalizedRules = $this->normalizeAudienceSegmentRules($rules);
        $logic = $this->normalizeEnum($ruleLogic, self::AUDIENCE_SEGMENT_RULE_LOGIC, 'segment_rule_logic');

        return $this->evaluateAudienceSegmentRules($normalizedRules, $logic, $limit);
    }

    public function createAudienceSegmentSnapshot(int $segmentId, ?int $userId = null): array
    {
        $this->assertMarketingPermission('marketing.write');
        $segment = $this->getAudienceSegment($segmentId);
        if (!$segment) {
            throw new RuntimeException('Marketing audience segment not found.');
        }

        $preview = $this->evaluateAudienceSegmentRules((array) ($segment['rules'] ?? []), (string) $segment['rule_logic'], 5000);
        $criteria = [
            'segment_id' => $segmentId,
            'segment_name' => (string) $segment['name'],
            'rule_logic' => (string) $segment['rule_logic'],
            'rules' => (array) ($segment['rules'] ?? []),
        ];

        Database::execute(
            "INSERT INTO marketing_segment_snapshots
             (workspace_id, segment_id, uuid, name, contact_count, contact_ids_json, sample_contacts_json, criteria_json, metadata_json, created_by)
             VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)",
            [
                $this->workspaceId(),
                $segmentId,
                $this->generateUuid(),
                (string) $segment['name'] . ' snapshot ' . date('Y-m-d H:i'),
                (int) $preview['count'],
                $this->normalizeJsonValue($preview['contact_ids']),
                $this->normalizeJsonValue(array_slice((array) $preview['contacts'], 0, 25)),
                $this->normalizeJsonValue($criteria),
                $this->normalizeJsonValue(['source' => 'marketing_audience_segment', 'manual_first' => true]),
                ($userId ?? $this->currentUserId()) ?: null,
            ]
        );
        $snapshotId = (int) Database::lastInsertId();
        Database::execute(
            'UPDATE marketing_audience_segments SET preview_count = ?, last_previewed_at = NOW(), last_snapshot_at = NOW() WHERE workspace_id = ? AND id = ?',
            [(int) $preview['count'], $this->workspaceId(), $segmentId]
        );

        return $this->hydrateJsonFields(Database::queryOne(
            'SELECT * FROM marketing_segment_snapshots WHERE workspace_id = ? AND id = ?',
            [$this->workspaceId(), $snapshotId]
        ) ?: [], ['contact_ids_json', 'sample_contacts_json', 'criteria_json', 'metadata_json']);
    }

    public function getAudienceSegmentIntelligence(int $segmentId, bool $persist = true): array
    {
        $segment = $this->getAudienceSegment($segmentId);
        if (!$segment) {
            throw new RuntimeException('Marketing audience segment not found.');
        }

        $preview = $this->previewAudienceSegment($segmentId, 500, false);
        $contactIds = array_values(array_unique(array_map('intval', (array) ($preview['contact_ids'] ?? []))));
        $matchedContacts = (int) ($preview['count'] ?? 0);

        $breakdowns = [
            'stage' => $this->audienceContactBreakdown($contactIds, 'stage'),
            'lead_source' => $this->audienceContactBreakdown($contactIds, 'lead_source'),
            'assigned_owner' => $this->audienceContactOwnerBreakdown($contactIds),
        ];
        $evidence = [
            'deals' => $this->audienceDealEvidence($contactIds),
            'form_submissions' => $this->audienceFormSubmissionEvidence($contactIds),
            'handoffs' => $this->audienceHandoffEvidence($contactIds),
            'activities' => $this->audienceActivityEvidence($contactIds),
        ];

        $warnings = [];
        $factors = [];
        $score = 0;
        if ($matchedContacts > 0) {
            $score += 25;
            $factors[] = 'Segment currently matches CRM contacts.';
        } else {
            $warnings[] = 'No contacts currently match this segment.';
        }
        if ((int) ($preview['rules_applied'] ?? 0) > 0) {
            $score += 15;
            $factors[] = 'Segment uses explicit CRM rules.';
        } else {
            $warnings[] = 'No rules are configured; this audience currently represents all workspace contacts.';
        }
        if (!empty($breakdowns['stage']) || !empty($breakdowns['lead_source'])) {
            $score += 10;
            $factors[] = 'Lifecycle or source breakdown is available.';
        }
        if ((int) ($evidence['deals']['count'] ?? 0) > 0) {
            $score += 15;
            $factors[] = 'Matched contacts have linked deal evidence.';
        }
        if ((int) ($evidence['form_submissions']['count'] ?? 0) > 0) {
            $score += 10;
            $factors[] = 'Matched contacts have form submission evidence.';
        }
        if ((int) ($evidence['handoffs']['count'] ?? 0) > 0) {
            $score += 10;
            $factors[] = 'Matched contacts are represented in marketing-to-sales handoffs.';
        }
        if ((int) ($evidence['activities']['count'] ?? 0) > 0) {
            $score += 10;
            $factors[] = 'Matched contacts have CRM activity history.';
        }
        if (!empty($segment['last_snapshot_at'])) {
            $score += 5;
            $factors[] = 'A stable snapshot exists for manual execution.';
        } else {
            $warnings[] = 'No snapshot exists yet; create one before manual exports or campaign execution.';
        }

        $score = min(100, $score);
        $staleReason = $warnings[0] ?? null;
        $intelligence = [
            'segment_id' => $segmentId,
            'segment_name' => (string) ($segment['name'] ?? ''),
            'matched_contacts' => $matchedContacts,
            'sampled_contacts' => count($contactIds),
            'rules_applied' => (int) ($preview['rules_applied'] ?? 0),
            'breakdowns' => $breakdowns,
            'crm_evidence' => $evidence,
            'warnings' => $warnings,
            'recommendations' => $this->audienceIntelligenceRecommendations($matchedContacts, $evidence, $segment),
            'manual_first' => true,
            'external_execution' => false,
        ];
        $fit = [
            'score' => $score,
            'factors' => $factors,
            'warnings' => $warnings,
            'computed_at' => date('c'),
        ];

        if ($persist && Database::columnExists('marketing_audience_segments', 'crm_preview_json')) {
            Database::execute(
                'UPDATE marketing_audience_segments
                 SET crm_preview_json = ?, fit_score = ?, fit_score_json = ?, stale_reason = ?, last_intelligence_at = NOW(), preview_count = ?, last_previewed_at = NOW()
                 WHERE workspace_id = ? AND id = ?',
                [
                    $this->normalizeJsonValue($intelligence),
                    $score,
                    $this->normalizeJsonValue($fit),
                    $staleReason,
                    $matchedContacts,
                    $this->workspaceId(),
                    $segmentId,
                ]
            );
        }

        return $intelligence + [
            'fit_score' => $score,
            'fit_score_json' => $fit,
            'stale_reason' => $staleReason,
        ];
    }

    public function getAudienceJourneyUsabilityCenter(?int $userId = null, int $limit = 8): array
    {
        $this->assertMarketingPermission('marketing.read');
        $limit = min(max($limit, 1), 20);
        $userId = $userId ?? $this->currentUserId();
        if (($userId ?? 0) > 0) {
            $this->assertWorkspaceUser((int) $userId, $this->workspaceId());
        }

        $segments = $this->listAudienceSegments(['exclude_archived' => true], $limit, 0);
        $journeys = $this->listJourneys(['open' => true], $limit, 0);
        $audienceSummary = $this->getCrmAudienceIntelligenceSummary();
        $activationQuality = $this->getAudienceActivationQualitySummary();
        $boundedScore = static fn(int|float $score): int => max(0, min(100, (int) round((float) $score)));
        $segmentCards = [];
        $segmentCounts = [
            'total' => count($segments),
            'ready' => 0,
            'needs_snapshot' => 0,
            'needs_activation' => 0,
            'no_contacts' => 0,
        ];
        foreach ($segments as $segment) {
            $score = 0;
            $warnings = [];
            if ((string) ($segment['status'] ?? '') === 'active') {
                $score += 20;
            } else {
                $warnings[] = 'Activate the segment before campaign execution.';
            }
            if ((int) ($segment['rule_count'] ?? 0) > 0) {
                $score += 20;
            } else {
                $warnings[] = 'Add at least one CRM rule.';
            }
            if ((int) ($segment['preview_count'] ?? 0) > 0) {
                $score += 20;
            } else {
                $warnings[] = 'Preview should match CRM contacts.';
                $segmentCounts['no_contacts']++;
            }
            if ((int) ($segment['snapshot_count'] ?? 0) > 0 || !empty($segment['last_snapshot_at'])) {
                $score += 20;
            } else {
                $warnings[] = 'Create a stable audience snapshot.';
                $segmentCounts['needs_snapshot']++;
            }
            if ((int) ($segment['activation_score'] ?? 0) > 0) {
                $score += min(20, max(5, (int) round(((int) $segment['activation_score']) / 5)));
            } else {
                $warnings[] = 'Connect the segment to a campaign, email run, content item, or channel export.';
                $segmentCounts['needs_activation']++;
            }
            $score = $boundedScore($score);
            $status = $score >= 80 ? 'ready' : ($score >= 45 ? 'attention' : 'blocked');
            if ($status === 'ready') {
                $segmentCounts['ready']++;
            }
            $segmentCards[] = [
                'id' => (int) ($segment['id'] ?? 0),
                'name' => (string) ($segment['name'] ?? 'Audience segment'),
                'href' => 'marketing_segment_view.php?id=' . (int) ($segment['id'] ?? 0),
                'score' => $score,
                'status' => $status,
                'warnings' => array_slice($warnings, 0, 5),
                'next_action' => $warnings[0] ?? 'Use this segment in a campaign journey or manual export.',
                'preview_count' => (int) ($segment['preview_count'] ?? 0),
                'snapshot_count' => (int) ($segment['snapshot_count'] ?? 0),
                'activation_score' => (int) ($segment['activation_score'] ?? 0),
            ];
        }

        $journeyCards = [];
        $journeyCounts = [
            'total' => count($journeys),
            'ready' => 0,
            'warning' => 0,
            'blocked' => 0,
            'missing_audience' => 0,
            'missing_copy' => 0,
        ];
        foreach ($journeys as $journey) {
            $readiness = $this->getJourneyReadiness((int) ($journey['id'] ?? 0));
            $status = (string) ($readiness['status'] ?? 'blocked');
            $journeyCounts[$status] = (int) ($journeyCounts[$status] ?? 0) + 1;
            $journeyCounts['missing_audience'] += (int) ($readiness['counts']['missing_audience'] ?? 0);
            $journeyCounts['missing_copy'] += (int) ($readiness['counts']['missing_step_copy'] ?? 0);
            $recommendations = (array) ($readiness['recommendations'] ?? []);
            $journeyCards[] = [
                'id' => (int) ($journey['id'] ?? 0),
                'name' => (string) ($journey['name'] ?? 'Marketing journey'),
                'href' => 'marketing_journey_view.php?id=' . (int) ($journey['id'] ?? 0),
                'score' => (int) ($readiness['score'] ?? 0),
                'status' => $status,
                'step_count' => (int) ($journey['step_count'] ?? 0),
                'audience_segment_name' => (string) ($journey['audience_segment_name'] ?? ''),
                'campaign_name' => (string) ($journey['campaign_name'] ?? ''),
                'next_action' => (string) ($recommendations[0]['label'] ?? 'Review journey readiness'),
                'next_href' => (string) ($recommendations[0]['href'] ?? 'marketing_journey_view.php?id=' . (int) ($journey['id'] ?? 0)),
            ];
        }

        $scoreParts = [
            (int) ($audienceSummary['readiness_score'] ?? 0),
            (int) ($activationQuality['score'] ?? 0),
            $segmentCounts['total'] > 0 ? (int) round(($segmentCounts['ready'] / max(1, $segmentCounts['total'])) * 100) : 0,
            $journeyCounts['total'] > 0 ? (int) round(($journeyCounts['ready'] / max(1, $journeyCounts['total'])) * 100) : 0,
        ];
        $score = $boundedScore(array_sum($scoreParts) / max(1, count($scoreParts)));
        $status = match (true) {
            $segmentCounts['total'] === 0 && $journeyCounts['total'] === 0 => 'needs_foundation',
            $segmentCounts['no_contacts'] > 0 || $journeyCounts['blocked'] > 0 => 'blocked',
            $segmentCounts['needs_snapshot'] > 0 || $segmentCounts['needs_activation'] > 0 || $journeyCounts['warning'] > 0 => 'attention',
            default => 'ready',
        };
        $decisions = [];
        if ($segmentCounts['total'] === 0) {
            $decisions[] = ['label' => 'Create first CRM audience segment', 'href' => 'marketing_segment_edit.php', 'reason' => 'Journeys and exports need a reusable target audience.', 'priority' => 'high'];
        }
        if ($segmentCounts['needs_snapshot'] > 0) {
            $decisions[] = ['label' => 'Snapshot audience segments', 'href' => 'marketing_segments.php', 'reason' => 'Manual exports and launch reviews need a stable audience count.', 'priority' => 'high'];
        }
        if ($segmentCounts['needs_activation'] > 0) {
            $decisions[] = ['label' => 'Connect audiences to campaigns', 'href' => 'marketing_audience_activation.php', 'reason' => 'Segments need campaign/content/distribution context before execution.', 'priority' => 'high'];
        }
        if ($journeyCounts['total'] === 0) {
            $decisions[] = ['label' => 'Plan first manual journey', 'href' => 'marketing_journey_edit.php', 'reason' => 'Create a simple path before scaling email, WhatsApp, SMS, and task follow-up.', 'priority' => 'medium'];
        }
        if ($journeyCounts['missing_audience'] > 0 || $journeyCounts['missing_copy'] > 0) {
            $decisions[] = ['label' => 'Fix journey blockers', 'href' => 'marketing_journeys.php', 'reason' => 'Journey steps need audience and copy/content before manual execution.', 'priority' => 'high'];
        }
        if ($decisions === []) {
            $decisions[] = ['label' => 'Use ready audiences in campaign launches', 'href' => 'marketing_campaign_workspace.php', 'reason' => 'Audience and journey inputs are usable enough for manual launch planning.', 'priority' => 'low'];
        }

        return [
            'status' => $status,
            'score' => $score,
            'segments' => $segmentCards,
            'journeys' => $journeyCards,
            'counts' => [
                'segments' => $segmentCounts,
                'journeys' => $journeyCounts,
                'audience_contacts' => (int) ($audienceSummary['counts']['contacts'] ?? 0),
                'activation_blocked' => (int) ($activationQuality['counts']['blocked'] ?? 0),
                'activation_warning' => (int) ($activationQuality['counts']['warning'] ?? 0),
            ],
            'rule_starters' => [
                ['label' => 'Qualified form submitters', 'description' => 'Contacts from forms with qualified or high-intent status.', 'href' => 'marketing_segment_edit.php'],
                ['label' => 'Warm pipeline contacts', 'description' => 'Contacts linked to open proposal or negotiation deals.', 'href' => 'marketing_segment_edit.php'],
                ['label' => 'Recent engagement audience', 'description' => 'Contacts with recent CRM activity or form submissions.', 'href' => 'marketing_segment_edit.php'],
            ],
            'journey_starters' => [
                ['label' => 'New lead to sales handoff', 'description' => 'Email or WhatsApp touch, wait, task follow-up, and handoff check.', 'href' => 'marketing_journey_edit.php'],
                ['label' => 'Webinar or event follow-up', 'description' => 'Thank-you message, proof content, wait, and sales task.', 'href' => 'marketing_journey_edit.php'],
                ['label' => 'Dormant lead reactivation', 'description' => 'Value reminder, wait, objection handling, and manual task.', 'href' => 'marketing_journey_edit.php'],
            ],
            'next_decisions' => array_slice($decisions, 0, 8),
            'guardrails' => [
                'workspace_scoped' => true,
                'manual_first' => true,
                'read_only_cockpit' => true,
                'external_send' => false,
                'external_publish' => false,
                'external_execution' => false,
                'external_api_calls' => false,
                'templates_do_not_create_records' => true,
            ],
            'recommended_product_decision' => 'Use the Audience Journey Cockpit as the bridge between CRM segmentation and manual journeys: operators should see usable audience targets, journey blockers, rule starters, and next decisions before exports or launch.',
            'generated_at' => date('c'),
        ];
    }

    public function getCrmAudienceIntelligenceSummary(): array
    {
        $segments = $this->listAudienceSegments([], 100, 0);
        $recommendations = $this->listAudienceRecommendations(['status' => 'suggested'], 12, 0);
        $contactCount = Database::tableExists('contacts') ? $this->countRows('contacts', '1=1') : 0;
        $companyCount = Database::tableExists('companies') ? $this->countRows('companies', '1=1') : 0;
        $dealCount = Database::tableExists('deals') ? $this->countRows('deals', '1=1') : 0;
        $snapshotCount = Database::tableExists('marketing_segment_snapshots') ? $this->countRows('marketing_segment_snapshots', '1=1') : 0;
        $formSubmissionCount = $this->audienceWorkspaceFormSubmissionCount();
        $activityCount = Database::tableExists('activities') ? $this->countRows('activities', '1=1') : 0;
        $pipelineValue = 0.0;
        if (Database::tableExists('deals') && Database::columnExists('deals', 'value')) {
            $row = Database::queryOne('SELECT COALESCE(SUM(value), 0) AS total FROM deals WHERE workspace_id = ?', [$this->workspaceId()]);
            $pipelineValue = round((float) ($row['total'] ?? 0), 2);
        }

        $sourceMix = [
            'lead_source' => Database::tableExists('contacts') && Database::columnExists('contacts', 'lead_source') ? $this->audienceWorkspaceBreakdown('contacts', 'lead_source', 8) : [],
            'lifecycle_stage' => Database::tableExists('contacts') && Database::columnExists('contacts', 'stage') ? $this->audienceWorkspaceBreakdown('contacts', 'stage', 8) : [],
            'deal_stage' => Database::tableExists('deals') && Database::columnExists('deals', 'stage') ? $this->audienceWorkspaceBreakdown('deals', 'stage', 8) : [],
        ];
        $freshness = [
            'contacts' => $this->audienceWorkspaceFreshness('contacts'),
            'deals' => $this->audienceWorkspaceFreshness('deals'),
            'activities' => $this->audienceWorkspaceFreshness('activities'),
            'form_submissions' => $this->audienceWorkspaceFreshness('form_submissions'),
        ];

        $missingData = [];
        $missingLeadSource = Database::tableExists('contacts') && Database::columnExists('contacts', 'lead_source')
            ? $this->countRows('contacts', "(lead_source IS NULL OR lead_source = '')")
            : 0;
        if ($missingLeadSource > 0) {
            $missingData[] = ['key' => 'missing_lead_source', 'label' => 'Contacts missing lead source', 'count' => $missingLeadSource, 'href' => 'contacts.php'];
        }
        $missingStage = Database::tableExists('contacts') && Database::columnExists('contacts', 'stage')
            ? $this->countRows('contacts', "(stage IS NULL OR stage = '')")
            : 0;
        if ($missingStage > 0) {
            $missingData[] = ['key' => 'missing_stage', 'label' => 'Contacts missing lifecycle stage', 'count' => $missingStage, 'href' => 'contacts.php'];
        }
        $missingEngagement = Database::tableExists('contacts') && Database::columnExists('contacts', 'engagement_score')
            ? $this->countRows('contacts', 'engagement_score IS NULL')
            : 0;
        if ($missingEngagement > 0) {
            $missingData[] = ['key' => 'missing_engagement', 'label' => 'Contacts missing engagement score', 'count' => $missingEngagement, 'href' => 'contacts.php'];
        }
        $staleSegments = array_values(array_filter($segments, static function (array $segment): bool {
            if (!empty($segment['stale_reason'])) {
                return true;
            }
            $lastIntelligence = trim((string) ($segment['last_intelligence_at'] ?? ''));
            return $lastIntelligence === '' || (strtotime($lastIntelligence) !== false && strtotime($lastIntelligence) < strtotime('-30 days'));
        }));

        $recommendedAudiences = [];
        $seenRecommendations = [];
        foreach ($recommendations as $recommendation) {
            $title = (string) ($recommendation['title'] ?? '');
            if ($title === '') {
                continue;
            }
            $seenRecommendations[strtolower($title)] = true;
            $recommendedAudiences[] = [
                'title' => $title,
                'reason' => (string) ($recommendation['description'] ?? 'Existing CRM audience suggestion.'),
                'fit_score' => (int) ($recommendation['fit_score'] ?? 0),
                'source' => 'saved_recommendation',
                'href' => 'marketing_segments.php',
            ];
        }
        foreach (['lead_source' => 'Lead source', 'lifecycle_stage' => 'Lifecycle stage', 'deal_stage' => 'Deal stage'] as $mixKey => $label) {
            foreach (array_slice((array) ($sourceMix[$mixKey] ?? []), 0, 3) as $row) {
                $value = trim((string) ($row['label'] ?? ''));
                if ($value === '') {
                    continue;
                }
                $title = $label . ': ' . ucwords(str_replace('_', ' ', $value));
                if (isset($seenRecommendations[strtolower($title)])) {
                    continue;
                }
                $seenRecommendations[strtolower($title)] = true;
                $count = (int) ($row['count'] ?? 0);
                $recommendedAudiences[] = [
                    'title' => $title,
                    'reason' => $count . ' CRM record' . ($count === 1 ? '' : 's') . ' share this signal. Review before creating a segment.',
                    'fit_score' => min(95, 45 + ($count * 5)),
                    'source' => 'read_only_crm_signal',
                    'href' => 'marketing_segment_edit.php',
                ];
            }
        }

        $readinessScore = 0;
        if ($contactCount > 0) {
            $readinessScore += 20;
        }
        if (count($segments) > 0) {
            $readinessScore += 25;
        }
        if ($snapshotCount > 0) {
            $readinessScore += 15;
        }
        if (($sourceMix['lead_source'] ?? []) !== [] || ($sourceMix['lifecycle_stage'] ?? []) !== []) {
            $readinessScore += 15;
        }
        if ($dealCount > 0 || $formSubmissionCount > 0 || $activityCount > 0) {
            $readinessScore += 15;
        }
        if ($recommendedAudiences !== []) {
            $readinessScore += 10;
        }
        $readinessScore = max(0, min(100, $readinessScore - min(20, count($missingData) * 5) - min(15, count($staleSegments) * 3)));

        return [
            'readiness_score' => $readinessScore,
            'status' => $readinessScore >= 80 ? 'ready' : ($readinessScore >= 50 ? 'needs_attention' : 'incomplete'),
            'counts' => [
                'contacts' => $contactCount,
                'companies' => $companyCount,
                'deals' => $dealCount,
                'form_submissions' => $formSubmissionCount,
                'activities' => $activityCount,
                'segments' => count($segments),
                'snapshots' => $snapshotCount,
                'saved_recommendations' => count($recommendations),
                'stale_segments' => count($staleSegments),
                'pipeline_value' => $pipelineValue,
            ],
            'source_mix' => $sourceMix,
            'freshness' => $freshness,
            'missing_data' => $missingData,
            'recommended_audiences' => array_slice($recommendedAudiences, 0, 8),
            'integration_sources' => [
                'contacts' => ['available' => Database::tableExists('contacts'), 'count' => $contactCount],
                'companies' => ['available' => Database::tableExists('companies'), 'count' => $companyCount],
                'deals' => ['available' => Database::tableExists('deals'), 'count' => $dealCount],
                'forms' => ['available' => Database::tableExists('form_submissions'), 'count' => $formSubmissionCount],
                'activities' => ['available' => Database::tableExists('activities'), 'count' => $activityCount],
            ],
            'manual_first_boundary' => [
                'read_only' => true,
                'mutates_crm' => false,
                'external_execution' => false,
            ],
        ];
    }

    public function listAudienceRecommendations(array $filters = [], int $limit = 20, int $offset = 0): array
    {
        if (!Database::tableExists('marketing_audience_recommendations')) {
            return [];
        }

        $limit = min(max($limit, 1), 100);
        $offset = max($offset, 0);
        $where = ['r.workspace_id = ?'];
        $params = [$this->workspaceId()];

        if (!empty($filters['status'])) {
            $where[] = 'r.status = ?';
            $params[] = $this->normalizeEnum((string) $filters['status'], self::AUDIENCE_RECOMMENDATION_STATUSES, 'audience_recommendation_status');
        }
        if (!empty($filters['recommendation_type'])) {
            $where[] = 'r.recommendation_type = ?';
            $params[] = $this->normalizeEnum((string) $filters['recommendation_type'], self::AUDIENCE_RECOMMENDATION_TYPES, 'audience_recommendation_type');
        }

        return array_map(
            fn(array $row): array => $this->hydrateJsonFields($row, ['rule_suggestions_json']),
            Database::query(
                "SELECT r.*, creator.email AS created_by_email
                 FROM marketing_audience_recommendations r
                 LEFT JOIN users creator ON creator.id = r.created_by
                 WHERE " . implode(' AND ', $where) . "
                 ORDER BY r.fit_score DESC, r.updated_at DESC
                 LIMIT {$limit} OFFSET {$offset}",
                $params
            )
        );
    }

    public function listAudienceActivations(array $filters = [], int $limit = 100, int $offset = 0): array
    {
        if (!Database::tableExists('marketing_audience_activations')) {
            return [];
        }

        $limit = min(max($limit, 1), 250);
        $offset = max($offset, 0);
        $workspace = $this->workspaceClause('aa.');
        $where = [$workspace['sql']];
        $params = $workspace['params'];

        if (!empty($filters['open'])) {
            $where[] = "aa.status IN ('planned','active','paused')";
        }
        foreach ([
            'status' => self::AUDIENCE_ACTIVATION_STATUSES,
            'activation_type' => self::AUDIENCE_ACTIVATION_TYPES,
            'coverage_status' => self::AUDIENCE_COVERAGE_STATUSES,
        ] as $field => $allowed) {
            if (!empty($filters[$field])) {
                $where[] = "aa.{$field} = ?";
                $params[] = $this->normalizeEnum((string) $filters[$field], $allowed, $field);
            }
        }
        foreach ([
            'id',
            'audience_segment_id',
            'campaign_id',
            'campaign_brief_id',
            'landing_page_id',
            'content_item_id',
            'distribution_post_id',
            'email_run_id',
            'owner_user_id',
        ] as $field) {
            if (!empty($filters[$field])) {
                $where[] = "aa.{$field} = ?";
                $params[] = (int) $filters[$field];
            }
        }

        return array_map(
            fn(array $row): array => $this->hydrateAudienceActivationRow($row),
            Database::query(
                "SELECT aa.*, seg.name AS audience_segment_name, seg.preview_count AS audience_preview_count,
                        c.name AS campaign_name, b.title AS campaign_brief_title,
                        lp.title AS landing_page_title, m.title AS content_title,
                        d.channel AS distribution_channel, er.name AS email_run_name,
                        owner.email AS owner_email, creator.email AS created_by_email
                 FROM marketing_audience_activations aa
                 JOIN marketing_audience_segments seg ON seg.id = aa.audience_segment_id AND seg.workspace_id = aa.workspace_id
                 LEFT JOIN campaigns c ON c.id = aa.campaign_id AND c.workspace_id = aa.workspace_id
                 LEFT JOIN marketing_campaign_briefs b ON b.id = aa.campaign_brief_id AND b.workspace_id = aa.workspace_id
                 LEFT JOIN marketing_landing_pages lp ON lp.id = aa.landing_page_id AND lp.workspace_id = aa.workspace_id
                 LEFT JOIN marketing_content_items m ON m.id = aa.content_item_id AND m.workspace_id = aa.workspace_id
                 LEFT JOIN marketing_distribution_posts d ON d.id = aa.distribution_post_id AND d.workspace_id = aa.workspace_id
                 LEFT JOIN marketing_email_campaign_runs er ON er.id = aa.email_run_id AND er.workspace_id = aa.workspace_id
                 LEFT JOIN users owner ON owner.id = aa.owner_user_id
                 LEFT JOIN users creator ON creator.id = aa.created_by
                 WHERE " . implode(' AND ', $where) . "
                 ORDER BY
                    CASE aa.coverage_status WHEN 'blocked' THEN 0 WHEN 'warning' THEN 1 WHEN 'ready' THEN 2 ELSE 3 END ASC,
                    CASE aa.status WHEN 'active' THEN 0 WHEN 'planned' THEN 1 WHEN 'paused' THEN 2 ELSE 3 END ASC,
                    aa.updated_at DESC
                 LIMIT {$limit} OFFSET {$offset}",
                $params
            )
        );
    }

    public function getAudienceActivation(int $id): ?array
    {
        $rows = $this->listAudienceActivations(['id' => $id], 1, 0);

        return $rows[0] ?? null;
    }

    public function createAudienceActivation(array $data): int
    {
        $this->assertMarketingPermission('marketing.write');
        if (!Database::tableExists('marketing_audience_activations')) {
            throw new RuntimeException('Marketing audience activation is unavailable.');
        }

        $normalized = $this->normalizeAudienceActivationData($data, true);
        $coverage = $this->calculateAudienceActivationCoverage($normalized);
        $normalized['fit_score'] = (int) $coverage['fit_score'];
        $normalized['coverage_status'] = (string) $coverage['coverage_status'];
        $normalized['coverage_warnings_json'] = $this->normalizeJsonValue($coverage['warnings']);
        $normalized['usage_summary_json'] = $this->normalizeJsonValue($coverage['usage_summary']);

        Database::execute(
            "INSERT INTO marketing_audience_activations
             (workspace_id, uuid, audience_segment_id, activation_name, activation_type, status, campaign_id,
              campaign_brief_id, landing_page_id, content_item_id, distribution_post_id, email_run_id, fit_score,
              coverage_status, coverage_warnings_json, usage_summary_json, metadata_json, owner_user_id, created_by)
             VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)",
            [
                $this->workspaceId(),
                $this->generateUuid(),
                $normalized['audience_segment_id'],
                $normalized['activation_name'],
                $normalized['activation_type'],
                $normalized['status'],
                $normalized['campaign_id'],
                $normalized['campaign_brief_id'],
                $normalized['landing_page_id'],
                $normalized['content_item_id'],
                $normalized['distribution_post_id'],
                $normalized['email_run_id'],
                $normalized['fit_score'],
                $normalized['coverage_status'],
                $normalized['coverage_warnings_json'],
                $normalized['usage_summary_json'],
                $normalized['metadata_json'],
                $normalized['owner_user_id'],
                $normalized['created_by'],
            ]
        );
        $id = (int) Database::lastInsertId();
        $this->touchAudienceActivationScore((int) $normalized['audience_segment_id']);
        $this->recordMarketingAuditEvent(
            'audience_activation_created',
            'marketing_audience_activations',
            $id,
            'Audience activation connected to marketing execution.',
            ['coverage_status' => $normalized['coverage_status'], 'manual_first' => true],
            (int) ($normalized['created_by'] ?? 0) ?: null
        );

        return $id;
    }

    public function updateAudienceActivation(int $id, array $data): bool
    {
        $this->assertMarketingPermission('marketing.write');
        $existing = $this->getAudienceActivation($id);
        if (!$existing) {
            throw new RuntimeException('Marketing audience activation not found.');
        }

        $normalized = $this->normalizeAudienceActivationData(array_merge($existing, $data), false);
        $coverage = $this->calculateAudienceActivationCoverage($normalized);
        $normalized['fit_score'] = (int) $coverage['fit_score'];
        $normalized['coverage_status'] = (string) $coverage['coverage_status'];
        $normalized['coverage_warnings_json'] = $this->normalizeJsonValue($coverage['warnings']);
        $normalized['usage_summary_json'] = $this->normalizeJsonValue($coverage['usage_summary']);

        $result = $this->updateById('marketing_audience_activations', $id, $normalized);
        $this->touchAudienceActivationScore((int) ($normalized['audience_segment_id'] ?? $existing['audience_segment_id'] ?? 0));

        return $result;
    }

    public function archiveAudienceActivation(int $id): bool
    {
        $this->assertMarketingPermission('marketing.manage');
        $activation = $this->getAudienceActivation($id);
        if (!$activation) {
            throw new RuntimeException('Marketing audience activation not found.');
        }

        Database::execute(
            "UPDATE marketing_audience_activations SET status = 'archived' WHERE workspace_id = ? AND id = ?",
            [$this->workspaceId(), $id]
        );
        $this->touchAudienceActivationScore((int) ($activation['audience_segment_id'] ?? 0));

        return true;
    }

    public function mapPersonaToSegment(int $personaId, int $segmentId, array $data = []): int
    {
        $this->assertMarketingPermission('marketing.write');
        if (!Database::tableExists('marketing_persona_segment_map')) {
            throw new RuntimeException('Persona-to-segment mapping is unavailable.');
        }
        $workspaceId = $this->workspaceId();
        $this->assertWorkspaceRecord('marketing_personas', $personaId, $workspaceId);
        $this->assertWorkspaceRecord('marketing_audience_segments', $segmentId, $workspaceId);
        $score = min(100, max(0, (int) ($data['match_score'] ?? 70)));
        $reason = $this->nullableSanitizedText($data['match_reason'] ?? $data['reason'] ?? '');
        $metadata = $this->normalizeJsonValue($this->sanitizeFlexibleArray($data['metadata'] ?? $data['metadata_json'] ?? []));
        $createdBy = (int) ($data['created_by'] ?? $this->currentUserId()) ?: null;

        Database::execute(
            "INSERT INTO marketing_persona_segment_map
             (workspace_id, persona_id, audience_segment_id, match_score, match_reason, metadata_json, created_by)
             VALUES (?, ?, ?, ?, ?, ?, ?)
             ON DUPLICATE KEY UPDATE
                match_score = VALUES(match_score),
                match_reason = VALUES(match_reason),
                metadata_json = VALUES(metadata_json),
                updated_at = NOW()",
            [$workspaceId, $personaId, $segmentId, $score, $reason, $metadata, $createdBy]
        );
        $row = Database::queryOne(
            'SELECT id FROM marketing_persona_segment_map WHERE workspace_id = ? AND persona_id = ? AND audience_segment_id = ? LIMIT 1',
            [$workspaceId, $personaId, $segmentId]
        );
        $this->touchAudienceActivationScore($segmentId);

        return (int) ($row['id'] ?? 0);
    }

    public function listPersonaSegmentMaps(array $filters = [], int $limit = 100, int $offset = 0): array
    {
        if (!Database::tableExists('marketing_persona_segment_map')) {
            return [];
        }

        $limit = min(max($limit, 1), 250);
        $offset = max($offset, 0);
        $where = ['psm.workspace_id = ?'];
        $params = [$this->workspaceId()];
        foreach (['persona_id', 'audience_segment_id', 'id'] as $field) {
            if (!empty($filters[$field])) {
                $where[] = "psm.{$field} = ?";
                $params[] = (int) $filters[$field];
            }
        }

        return array_map(
            fn(array $row): array => $this->hydrateJsonFields($row, ['metadata_json']),
            Database::query(
                "SELECT psm.*, p.name AS persona_name, seg.name AS audience_segment_name, creator.email AS created_by_email
                 FROM marketing_persona_segment_map psm
                 JOIN marketing_personas p ON p.id = psm.persona_id AND p.workspace_id = psm.workspace_id
                 JOIN marketing_audience_segments seg ON seg.id = psm.audience_segment_id AND seg.workspace_id = psm.workspace_id
                 LEFT JOIN users creator ON creator.id = psm.created_by
                 WHERE " . implode(' AND ', $where) . "
                 ORDER BY psm.match_score DESC, p.name ASC, seg.name ASC
                 LIMIT {$limit} OFFSET {$offset}",
                $params
            )
        );
    }

    public function getAudienceActivationSummary(): array
    {
        if (!Database::tableExists('marketing_audience_activations')) {
            return [
                'counts' => ['total' => 0, 'active' => 0, 'blocked' => 0, 'warning' => 0, 'ready' => 0],
                'open' => [],
                'blocked' => [],
            ];
        }

        $counts = [
            'total' => $this->countRows('marketing_audience_activations', "status <> 'archived'"),
            'active' => $this->countRows('marketing_audience_activations', "status = 'active'"),
            'blocked' => $this->countRows('marketing_audience_activations', "coverage_status = 'blocked' AND status <> 'archived'"),
            'warning' => $this->countRows('marketing_audience_activations', "coverage_status = 'warning' AND status <> 'archived'"),
            'ready' => $this->countRows('marketing_audience_activations', "coverage_status = 'ready' AND status <> 'archived'"),
        ];

        return [
            'counts' => $counts,
            'open' => $this->listAudienceActivations(['open' => true], 6, 0),
            'blocked' => $this->listAudienceActivations(['coverage_status' => 'blocked'], 6, 0),
        ];
    }

    public function getAudienceActivationQualitySummary(int $limit = 100): array
    {
        if (!Database::tableExists('marketing_audience_segments')) {
            return [
                'score' => 0,
                'status' => 'unavailable',
                'counts' => ['segments' => 0, 'ready' => 0, 'warning' => 0, 'blocked' => 0],
                'segments' => [],
                'quality_queue' => [],
                'guardrails' => ['manual_first' => true, 'external_send' => false, 'external_publish' => false],
            ];
        }

        $limit = min(max($limit, 10), 250);
        $workspaceId = $this->workspaceId();
        $segments = $this->listAudienceSegments(['exclude_archived' => true], $limit, 0);
        $activations = Database::tableExists('marketing_audience_activations') ? $this->listAudienceActivations(['open' => true], 250, 0) : [];
        $activationsBySegment = [];
        foreach ($activations as $activation) {
            $segmentId = (int) ($activation['audience_segment_id'] ?? 0);
            if ($segmentId > 0) {
                $activationsBySegment[$segmentId][] = $activation;
            }
        }

        $mapCounts = [];
        if (Database::tableExists('marketing_persona_segment_map')) {
            foreach ($this->listPersonaSegmentMaps([], 250, 0) as $map) {
                $segmentId = (int) ($map['audience_segment_id'] ?? 0);
                if ($segmentId > 0) {
                    $mapCounts[$segmentId] = ($mapCounts[$segmentId] ?? 0) + 1;
                }
            }
        }

        $briefCounts = [];
        if (Database::tableExists('marketing_campaign_briefs') && Database::columnExists('marketing_campaign_briefs', 'audience_segment_id')) {
            foreach (Database::query(
                "SELECT audience_segment_id,
                        COUNT(*) AS brief_count,
                        SUM(CASE WHEN offer_context_item_id IS NOT NULL THEN 1 ELSE 0 END) AS offer_count
                 FROM marketing_campaign_briefs
                 WHERE workspace_id = ? AND audience_segment_id IS NOT NULL AND status <> 'archived'
                 GROUP BY audience_segment_id",
                [$workspaceId]
            ) as $row) {
                $briefCounts[(int) ($row['audience_segment_id'] ?? 0)] = [
                    'brief_count' => (int) ($row['brief_count'] ?? 0),
                    'offer_count' => (int) ($row['offer_count'] ?? 0),
                ];
            }
        }

        $snapshotTrends = [];
        if (Database::tableExists('marketing_segment_snapshots')) {
            foreach (Database::query(
                "SELECT segment_id, contact_count, created_at
                 FROM marketing_segment_snapshots
                 WHERE workspace_id = ?
                 ORDER BY segment_id ASC, created_at DESC, id DESC
                 LIMIT 1000",
                [$workspaceId]
            ) as $row) {
                $segmentId = (int) ($row['segment_id'] ?? 0);
                if ($segmentId <= 0) {
                    continue;
                }
                $snapshotTrends[$segmentId] ??= [];
                if (count($snapshotTrends[$segmentId]) < 2) {
                    $snapshotTrends[$segmentId][] = [
                        'contact_count' => (int) ($row['contact_count'] ?? 0),
                        'created_at' => (string) ($row['created_at'] ?? ''),
                    ];
                }
            }
        }

        $activeConsentPolicies = Database::tableExists('marketing_consent_policies')
            ? $this->listConsentPolicies(['active' => true], 50, 0)
            : [];
        $activeSuppressions = Database::tableExists('marketing_suppression_entries')
            ? $this->listSuppressionEntries(['active' => true], 50, 0)
            : [];
        $hasConsentPolicy = $activeConsentPolicies !== [];
        $hasSuppressionEntries = $activeSuppressions !== [];

        $qualitySegments = [];
        $queue = [];
        $counts = [
            'segments' => count($segments),
            'ready' => 0,
            'warning' => 0,
            'blocked' => 0,
            'activation_gaps' => 0,
            'consent_gaps' => 0,
            'suppression_warnings' => 0,
            'persona_offer_gaps' => 0,
            'stale_snapshots' => 0,
            'snapshot_drift' => 0,
            'consent_policies' => count($activeConsentPolicies),
            'suppression_entries' => count($activeSuppressions),
        ];

        foreach ($segments as $segment) {
            $segmentId = (int) ($segment['id'] ?? 0);
            $segmentActivations = $activationsBySegment[$segmentId] ?? [];
            $segmentMaps = (int) ($mapCounts[$segmentId] ?? 0);
            $segmentBriefs = $briefCounts[$segmentId] ?? ['brief_count' => 0, 'offer_count' => 0];
            $trendRows = $snapshotTrends[$segmentId] ?? [];
            $latestSnapshot = $trendRows[0] ?? null;
            $previousSnapshot = $trendRows[1] ?? null;
            $snapshotDelta = null;
            $snapshotDrift = false;
            if ($latestSnapshot !== null && $previousSnapshot !== null) {
                $snapshotDelta = (int) $latestSnapshot['contact_count'] - (int) $previousSnapshot['contact_count'];
                $baseline = max(1, (int) $previousSnapshot['contact_count']);
                $snapshotDrift = abs($snapshotDelta) >= max(5, (int) ceil($baseline * 0.25));
            }

            $warnings = [];
            $score = 0;
            if ((string) ($segment['status'] ?? '') === 'active') {
                $score += 12;
            } else {
                $warnings[] = 'segment_not_active';
            }
            if ((int) ($segment['preview_count'] ?? 0) > 0) {
                $score += 16;
            } else {
                $warnings[] = 'no_matching_contacts';
            }
            if ((int) ($segment['fit_score'] ?? 0) > 0) {
                $score += min(18, (int) round(((int) $segment['fit_score']) / 6));
            } else {
                $warnings[] = 'fit_not_scored';
            }
            if ((int) ($segment['activation_score'] ?? 0) > 0) {
                $score += min(18, (int) round(((int) $segment['activation_score']) / 6));
            } else {
                $warnings[] = 'no_active_activation';
            }
            if ($latestSnapshot !== null) {
                $score += 10;
                $latestCreated = strtotime((string) ($latestSnapshot['created_at'] ?? ''));
                if ($latestCreated !== false && $latestCreated < strtotime('-30 days')) {
                    $warnings[] = 'snapshot_stale';
                    $counts['stale_snapshots']++;
                }
            } else {
                $warnings[] = 'snapshot_missing';
            }
            if ($snapshotDrift) {
                $warnings[] = 'snapshot_drift_detected';
                $counts['snapshot_drift']++;
            } else {
                $score += 5;
            }
            if ($segmentActivations === []) {
                $warnings[] = 'activation_missing';
                $counts['activation_gaps']++;
            } else {
                $score += 10;
                foreach ($segmentActivations as $activation) {
                    foreach ((array) ($activation['coverage_warnings_json'] ?? []) as $warning) {
                        $warnings[] = 'activation_' . (string) $warning;
                    }
                }
            }
            if (!$hasConsentPolicy) {
                $warnings[] = 'consent_policy_missing';
                $counts['consent_gaps']++;
            } else {
                $score += 8;
            }
            if ($hasSuppressionEntries) {
                $warnings[] = 'suppression_list_requires_review';
                $counts['suppression_warnings']++;
            } else {
                $score += 4;
            }
            if ($segmentMaps > 0) {
                $score += 5;
            } else {
                $warnings[] = 'persona_fit_missing';
                $counts['persona_offer_gaps']++;
            }
            if ((int) ($segmentBriefs['offer_count'] ?? 0) > 0) {
                $score += 5;
            } else {
                $warnings[] = 'offer_fit_missing';
                $counts['persona_offer_gaps']++;
            }

            $score = max(0, min(100, $score));
            $critical = array_intersect($warnings, ['no_matching_contacts', 'activation_missing', 'consent_policy_missing']);
            $status = $critical !== [] ? 'blocked' : ($score >= 75 && $warnings === [] ? 'ready' : 'warning');
            $counts[$status]++;

            $quality = [
                'id' => $segmentId,
                'name' => (string) ($segment['name'] ?? 'Audience segment'),
                'status' => $status,
                'score' => $score,
                'preview_count' => (int) ($segment['preview_count'] ?? 0),
                'fit_score' => (int) ($segment['fit_score'] ?? 0),
                'activation_score' => (int) ($segment['activation_score'] ?? 0),
                'activation_count' => count($segmentActivations),
                'persona_map_count' => $segmentMaps,
                'offer_link_count' => (int) ($segmentBriefs['offer_count'] ?? 0),
                'latest_snapshot_count' => $latestSnapshot['contact_count'] ?? null,
                'previous_snapshot_count' => $previousSnapshot['contact_count'] ?? null,
                'snapshot_delta' => $snapshotDelta,
                'warnings' => array_values(array_unique($warnings)),
                'href' => 'marketing_segment_view.php?id=' . $segmentId,
            ];
            $qualitySegments[] = $quality;
            if ($status !== 'ready' || $warnings !== []) {
                $queue[] = [
                    'title' => $quality['name'],
                    'status' => $status,
                    'score' => $score,
                    'warnings' => $quality['warnings'],
                    'next_action' => $this->audienceQualityNextAction($quality['warnings']),
                    'href' => $quality['href'],
                ];
            }
        }

        usort($qualitySegments, static fn(array $a, array $b): int => ((int) $a['score'] <=> (int) $b['score']) ?: strcmp((string) $a['name'], (string) $b['name']));
        usort($queue, static fn(array $a, array $b): int => ((int) $a['score'] <=> (int) $b['score']));
        $overall = $counts['segments'] > 0
            ? (int) round(array_sum(array_column($qualitySegments, 'score')) / max(1, $counts['segments']))
            : 0;

        return [
            'score' => $overall,
            'status' => $overall >= 80 ? 'ready' : ($overall >= 55 ? 'needs_attention' : 'blocked'),
            'counts' => $counts,
            'segments' => array_slice($qualitySegments, 0, 12),
            'quality_queue' => array_slice($queue, 0, 10),
            'consent_policies' => array_slice($activeConsentPolicies, 0, 6),
            'suppression_entries' => array_slice($activeSuppressions, 0, 6),
            'guardrails' => [
                'manual_first' => true,
                'external_send' => false,
                'external_publish' => false,
                'mutates_crm' => false,
                'message' => 'Audience quality checks guide manual planning and do not send, publish, or change CRM records automatically.',
            ],
        ];
    }

    public function suggestAudienceSegmentsFromCrm(int $limit = 8, ?int $userId = null): array
    {
        $this->assertMarketingPermission('marketing.write');
        if (!Database::tableExists('marketing_audience_recommendations') || !Database::tableExists('contacts') || !Database::columnExists('contacts', 'workspace_id')) {
            return [];
        }

        $limit = min(max($limit, 1), 20);
        $createdBy = ($userId ?? $this->currentUserId()) ?: null;
        $suggestions = [];

        foreach ($this->topContactDimensionRows('lead_source', 4) as $row) {
            $value = (string) ($row['value'] ?? '');
            $count = (int) ($row['count'] ?? 0);
            if ($value === '' || $count <= 0) {
                continue;
            }
            $suggestions[] = [
                'recommendation_type' => 'lead_source',
                'title' => 'Lead source: ' . $this->labelizeMarketingValue($value),
                'description' => $count . ' contact(s) share this lead source. Build a focused offer or nurture path for them.',
                'rule_suggestions_json' => [[
                    'source_type' => 'contact',
                    'field_key' => 'lead_source',
                    'operator' => 'equals',
                    'value_text' => $value,
                ]],
                'fit_score' => min(95, 45 + ($count * 5)),
                'created_by' => $createdBy,
            ];
        }

        foreach ($this->topContactDimensionRows('stage', 4) as $row) {
            $value = (string) ($row['value'] ?? '');
            $count = (int) ($row['count'] ?? 0);
            if ($value === '' || $count <= 0) {
                continue;
            }
            $suggestions[] = [
                'recommendation_type' => 'lifecycle_stage',
                'title' => 'Lifecycle stage: ' . $this->labelizeMarketingValue($value),
                'description' => $count . ' contact(s) are in this CRM stage. Use this to tune messaging and sales handoff timing.',
                'rule_suggestions_json' => [[
                    'source_type' => 'contact',
                    'field_key' => 'stage',
                    'operator' => 'equals',
                    'value_text' => $value,
                ]],
                'fit_score' => min(95, 45 + ($count * 5)),
                'created_by' => $createdBy,
            ];
        }

        if (Database::tableExists('deals') && Database::columnExists('deals', 'workspace_id') && Database::columnExists('deals', 'stage')) {
            $dealRows = Database::query(
                "SELECT COALESCE(NULLIF(CAST(stage AS CHAR), ''), 'unknown') AS value, COUNT(*) AS count
                 FROM deals
                 WHERE workspace_id = ?
                 GROUP BY value
                 HAVING count > 0
                 ORDER BY count DESC
                 LIMIT 3",
                [$this->workspaceId()]
            );
            foreach ($dealRows as $row) {
                $value = (string) ($row['value'] ?? '');
                $count = (int) ($row['count'] ?? 0);
                if ($value === '' || $count <= 0) {
                    continue;
                }
                $suggestions[] = [
                    'recommendation_type' => 'deal_stage',
                    'title' => 'Deal stage: ' . $this->labelizeMarketingValue($value),
                    'description' => $count . ' deal(s) sit in this stage. Build content that removes the next sales objection.',
                    'rule_suggestions_json' => [[
                        'source_type' => 'deal',
                        'field_key' => 'stage',
                        'operator' => 'equals',
                        'value_text' => $value,
                    ]],
                    'fit_score' => min(95, 50 + ($count * 5)),
                    'created_by' => $createdBy,
                ];
            }
        }

        foreach (array_slice($suggestions, 0, $limit) as $suggestion) {
            $this->upsertAudienceRecommendation($suggestion);
        }

        return $this->listAudienceRecommendations(['status' => 'suggested'], $limit, 0);
    }

    public function listJourneys(array $filters = [], int $limit = 100, int $offset = 0): array
    {
        if (!Database::tableExists('marketing_journeys')) {
            return [];
        }

        $limit = min(max($limit, 1), 250);
        $offset = max($offset, 0);
        $workspace = $this->workspaceClause('j.');
        $where = [$workspace['sql']];
        $params = $workspace['params'];

        if (!empty($filters['status'])) {
            $where[] = 'j.status = ?';
            $params[] = $this->normalizeEnum((string) $filters['status'], self::JOURNEY_STATUSES, 'journey_status');
        } elseif (!empty($filters['open'])) {
            $where[] = "j.status IN ('draft','active')";
        }
        if (!empty($filters['audience_segment_id'])) {
            $where[] = 'j.audience_segment_id = ?';
            $params[] = (int) $filters['audience_segment_id'];
        }
        if (!empty($filters['campaign_id'])) {
            $where[] = 'j.campaign_id = ?';
            $params[] = (int) $filters['campaign_id'];
        }
        if (!empty($filters['owner_user_id'])) {
            $where[] = 'j.owner_user_id = ?';
            $params[] = (int) $filters['owner_user_id'];
        }
        if (!empty($filters['id'])) {
            $where[] = 'j.id = ?';
            $params[] = (int) $filters['id'];
        }

        return array_map(
            fn(array $row): array => $this->hydrateJourneyRow($row),
            Database::query(
                "SELECT j.*, seg.name AS audience_segment_name, c.name AS campaign_name,
                        owner.email AS owner_email, creator.email AS created_by_email,
                        COUNT(DISTINCT s.id) AS step_count,
                        COUNT(DISTINCT d.id) AS draft_count
                 FROM marketing_journeys j
                 LEFT JOIN marketing_audience_segments seg ON seg.id = j.audience_segment_id AND seg.workspace_id = j.workspace_id
                 LEFT JOIN campaigns c ON c.id = j.campaign_id AND c.workspace_id = j.workspace_id
                 LEFT JOIN users owner ON owner.id = j.owner_user_id
                 LEFT JOIN users creator ON creator.id = j.created_by
                 LEFT JOIN marketing_journey_steps s ON s.journey_id = j.id AND s.workspace_id = j.workspace_id
                 LEFT JOIN marketing_journey_drafts d ON d.journey_id = j.id AND d.workspace_id = j.workspace_id AND d.status <> 'archived'
                 WHERE " . implode(' AND ', $where) . "
                 GROUP BY j.id
                 ORDER BY j.updated_at DESC, j.name ASC
                 LIMIT {$limit} OFFSET {$offset}",
                $params
            )
        );
    }

    public function getJourney(int $id): ?array
    {
        $journeys = $this->listJourneys(['id' => $id], 1, 0);
        if ($journeys === []) {
            return null;
        }

        $journey = $journeys[0];
        $journey['steps'] = $this->listJourneySteps($id);
        $journey['drafts'] = $this->listJourneyDrafts(['journey_id' => $id], 20, 0);

        return $journey;
    }

    public function getJourneyReadiness(int $id): array
    {
        $this->assertMarketingPermission('marketing.read');
        $journey = $this->getJourney($id);
        if (!$journey) {
            throw new RuntimeException('Marketing journey not found.');
        }

        $steps = (array) ($journey['steps'] ?? []);
        $checks = [];
        $recommendations = [];
        $counts = [
            'steps' => count($steps),
            'ready_steps' => 0,
            'blocked_steps' => 0,
            'warning_steps' => 0,
            'missing_audience' => (int) (($journey['audience_segment_id'] ?? 0) <= 0),
            'missing_step_copy' => 0,
            'invalid_wait_steps' => 0,
            'condition_gaps' => 0,
            'draft_side_recommendations' => count((array) ($journey['drafts'] ?? [])),
        ];
        if ($counts['missing_audience'] > 0) {
            $recommendations[] = [
                'label' => 'Connect an audience segment',
                'reason' => 'Journeys need a defined CRM audience before manual export or follow-up planning.',
                'href' => 'marketing_journey_edit.php?id=' . $id,
            ];
        }

        foreach ($steps as $index => $step) {
            $stepType = (string) ($step['step_type'] ?? 'email');
            $title = (string) ($step['title'] ?? ('Step ' . ($index + 1)));
            $issues = [];
            $warnings = [];
            $hasInstructions = trim((string) ($step['instructions'] ?? '')) !== '';
            $hasContent = (int) ($step['content_item_id'] ?? 0) > 0;
            $hasEmailRun = (int) ($step['email_run_id'] ?? 0) > 0;
            $hasTask = (int) ($step['task_id'] ?? 0) > 0;

            if (in_array($stepType, ['email', 'whatsapp', 'sms'], true) && !$hasInstructions && !$hasContent && !$hasEmailRun) {
                $issues[] = 'missing_copy_or_linked_content';
                $counts['missing_step_copy']++;
            }
            if ($stepType === 'task' && !$hasInstructions && !$hasTask) {
                $issues[] = 'missing_task_instruction';
                $counts['missing_step_copy']++;
            }
            if ($stepType === 'wait' && (int) ($step['wait_days'] ?? 0) <= 0) {
                $issues[] = 'wait_duration_required';
                $counts['invalid_wait_steps']++;
            }
            if ($stepType === 'condition' && empty($step['condition_json'])) {
                $issues[] = 'condition_rule_required';
                $counts['condition_gaps']++;
            }
            if ($stepType === 'branch' && empty($step['branch_json'])) {
                $issues[] = 'branch_paths_required';
                $counts['condition_gaps']++;
            }
            if ($hasContent && !in_array((string) ($step['content_status'] ?? ''), ['approved', 'scheduled', 'published'], true)) {
                $warnings[] = 'linked_content_not_approved';
            }

            $status = $issues !== [] ? 'blocked' : ($warnings !== [] ? 'warning' : 'ready');
            $counts[$status === 'ready' ? 'ready_steps' : ($status === 'blocked' ? 'blocked_steps' : 'warning_steps')]++;
            if ($issues !== [] || $warnings !== []) {
                $recommendations[] = [
                    'label' => 'Review step: ' . $title,
                    'reason' => implode(', ', array_merge($issues, $warnings)),
                    'href' => 'marketing_journey_edit.php?id=' . $id,
                ];
            }

            $checks[] = [
                'step_order' => (int) ($step['step_order'] ?? ($index + 1)),
                'step_type' => $stepType,
                'title' => $title,
                'status' => $status,
                'issues' => $issues,
                'warnings' => $warnings,
                'linked_content_status' => (string) ($step['content_status'] ?? ''),
                'message' => $issues === [] && $warnings === []
                    ? 'Step is ready for manual journey planning.'
                    : 'Step needs operator review before manual execution.',
            ];
        }

        $possible = max(1, count($steps) + 1);
        $readyUnits = $counts['ready_steps'] + ($counts['missing_audience'] > 0 ? 0 : 1);
        $score = (int) round(($readyUnits / $possible) * 100);
        $status = ($counts['missing_audience'] > 0 || $counts['blocked_steps'] > 0) ? 'blocked' : ($counts['warning_steps'] > 0 ? 'warning' : 'ready');
        if ($steps === []) {
            $status = 'blocked';
            $recommendations[] = [
                'label' => 'Add journey steps',
                'reason' => 'A journey needs at least one planned step before it can be reviewed.',
                'href' => 'marketing_journey_edit.php?id=' . $id,
            ];
        }

        return [
            'journey_id' => $id,
            'status' => $status,
            'score' => $steps === [] ? 0 : $score,
            'checks' => $checks,
            'counts' => $counts,
            'recommendations' => array_slice($recommendations, 0, 8),
            'manual_first_boundary' => [
                'external_send' => false,
                'external_publish' => false,
                'external_execution' => false,
            ],
            'ai_context' => [
                'recommendation_mode' => 'draft_side_only',
                'can_create_drafts' => true,
                'auto_apply' => false,
            ],
        ];
    }

    public function listJourneySteps(int $journeyId): array
    {
        if (!Database::tableExists('marketing_journey_steps')) {
            return [];
        }
        $this->assertWorkspaceRecord('marketing_journeys', $journeyId, $this->workspaceId());

        return array_map(
            fn(array $row): array => $this->hydrateJsonFields($row, ['condition_json', 'branch_json', 'metadata_json']),
            Database::query(
                "SELECT s.*, ci.title AS content_title, ci.status AS content_status,
                        er.name AS email_run_name, er.status AS email_run_status,
                        t.title AS task_title, creator.email AS created_by_email
                 FROM marketing_journey_steps s
                 LEFT JOIN marketing_content_items ci ON ci.id = s.content_item_id AND ci.workspace_id = s.workspace_id
                 LEFT JOIN marketing_email_campaign_runs er ON er.id = s.email_run_id AND er.workspace_id = s.workspace_id
                 LEFT JOIN tasks t ON t.id = s.task_id AND t.workspace_id = s.workspace_id
                 LEFT JOIN users creator ON creator.id = s.created_by
                 WHERE s.workspace_id = ? AND s.journey_id = ?
                 ORDER BY s.step_order ASC, s.id ASC",
                [$this->workspaceId(), $journeyId]
            )
        );
    }

    public function listJourneyDrafts(array $filters = [], int $limit = 50, int $offset = 0): array
    {
        if (!Database::tableExists('marketing_journey_drafts')) {
            return [];
        }

        $limit = min(max($limit, 1), 100);
        $offset = max($offset, 0);
        $workspace = $this->workspaceClause('d.');
        $where = [$workspace['sql']];
        $params = $workspace['params'];

        if (!empty($filters['journey_id'])) {
            $where[] = 'd.journey_id = ?';
            $params[] = (int) $filters['journey_id'];
        }
        if (!empty($filters['draft_type'])) {
            $where[] = 'd.draft_type = ?';
            $params[] = $this->normalizeEnum((string) $filters['draft_type'], self::JOURNEY_DRAFT_TYPES, 'journey_draft_type');
        }
        if (!empty($filters['status'])) {
            $where[] = 'd.status = ?';
            $params[] = $this->normalizeEnum((string) $filters['status'], self::JOURNEY_DRAFT_STATUSES, 'journey_draft_status');
        } elseif (!empty($filters['exclude_archived'])) {
            $where[] = "d.status <> 'archived'";
        }
        if (!empty($filters['id'])) {
            $where[] = 'd.id = ?';
            $params[] = (int) $filters['id'];
        }

        return array_map(
            fn(array $row): array => $this->hydrateJsonFields($row, ['draft_json', 'provider_json']),
            Database::query(
                "SELECT d.*, j.name AS journey_name, creator.email AS created_by_email
                 FROM marketing_journey_drafts d
                 LEFT JOIN marketing_journeys j ON j.id = d.journey_id AND j.workspace_id = d.workspace_id
                 LEFT JOIN users creator ON creator.id = d.created_by
                 WHERE " . implode(' AND ', $where) . "
                 ORDER BY d.created_at DESC, d.id DESC
                 LIMIT {$limit} OFFSET {$offset}",
                $params
            )
        );
    }

    public function createJourney(array $data): int
    {
        $this->assertMarketingPermission('marketing.write');
        $normalized = $this->normalizeJourneyData($data, true);
        $steps = $this->normalizeJourneySteps($data['steps'] ?? $data['steps_json'] ?? []);

        Database::beginTransaction();
        try {
            Database::execute(
                "INSERT INTO marketing_journeys
                 (workspace_id, uuid, name, description, journey_goal, status, audience_segment_id, campaign_id, owner_user_id, metadata_json, created_by)
                 VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)",
                [
                    $this->workspaceId(),
                    $this->generateUuid(),
                    $normalized['name'],
                    $normalized['description'],
                    $normalized['journey_goal'],
                    $normalized['status'],
                    $normalized['audience_segment_id'],
                    $normalized['campaign_id'],
                    $normalized['owner_user_id'],
                    $normalized['metadata_json'],
                    $normalized['created_by'],
                ]
            );
            $id = (int) Database::lastInsertId();
            $this->replaceJourneySteps($id, $steps);
            Database::commit();

            return $id;
        } catch (Throwable $e) {
            Database::rollBack();
            throw $e;
        }
    }

    public function updateJourney(int $id, array $data): bool
    {
        $this->assertMarketingPermission('marketing.write');
        $existing = $this->getJourney($id);
        if (!$existing) {
            throw new RuntimeException('Marketing journey not found.');
        }

        $hasSteps = array_key_exists('steps', $data) || array_key_exists('steps_json', $data);
        $normalized = $this->normalizeJourneyData(array_merge($existing, $data), false);
        $steps = $hasSteps ? $this->normalizeJourneySteps($data['steps'] ?? $data['steps_json'] ?? []) : null;

        Database::beginTransaction();
        try {
            $this->updateById('marketing_journeys', $id, $normalized);
            if ($steps !== null) {
                $this->replaceJourneySteps($id, $steps);
            }
            Database::commit();
        } catch (Throwable $e) {
            Database::rollBack();
            throw $e;
        }

        return true;
    }

    public function deleteJourney(int $id): bool
    {
        $this->assertMarketingPermission('marketing.manage');
        $this->assertWorkspaceRecord('marketing_journeys', $id, $this->workspaceId());
        Database::execute(
            'DELETE FROM marketing_journeys WHERE workspace_id = ? AND id = ?',
            [$this->workspaceId(), $id]
        );

        return true;
    }

    public function createJourneyDraft(array $data): int
    {
        $this->assertMarketingPermission('marketing.write');
        $normalized = $this->normalizeJourneyDraftData($data, true);

        Database::execute(
            "INSERT INTO marketing_journey_drafts
             (workspace_id, journey_id, uuid, draft_type, prompt, draft_json, status, provider_json, created_by)
             VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)",
            [
                $this->workspaceId(),
                $normalized['journey_id'],
                $this->generateUuid(),
                $normalized['draft_type'],
                $normalized['prompt'],
                $normalized['draft_json'],
                $normalized['status'],
                $normalized['provider_json'],
                $normalized['created_by'],
            ]
        );

        return (int) Database::lastInsertId();
    }

    public function generateJourneyDraft(array $data): array
    {
        $this->assertMarketingPermission('marketing.write');
        $journey = [];
        $journeyId = (int) ($data['journey_id'] ?? 0);
        if ($journeyId > 0) {
            $journey = $this->getJourney($journeyId) ?? [];
            if ($journey === []) {
                throw new RuntimeException('Marketing journey not found.');
            }
        }

        $draft = $this->fallbackJourneyDraft($data, $journey);
        $provider = [
            'mode' => 'deterministic_fallback',
            'fallback_used' => true,
            'manual_first' => true,
            'external_execution' => false,
            'generated_at' => date('c'),
        ];
        $draftId = $this->createJourneyDraft([
            'journey_id' => $journeyId > 0 ? $journeyId : null,
            'draft_type' => 'ai',
            'prompt' => (string) ($data['prompt'] ?? ''),
            'draft_json' => $draft,
            'provider_json' => $provider,
            'created_by' => (int) ($data['created_by'] ?? $this->currentUserId()) ?: null,
        ]);

        return [
            'id' => $draftId,
            'draft' => $draft,
            'provider' => $provider,
            'manual_execution_only' => true,
            'external_execution' => false,
        ];
    }

    public function bulkUpdateContentItems(array $ids, array $updates, ?int $userId = null): array
    {
        $this->assertMarketingPermission('marketing.write');
        $ids = array_values(array_unique(array_filter(array_map('intval', $ids), static fn(int $id): bool => $id > 0)));
        if ($ids === []) {
            throw new \InvalidArgumentException('Select at least one content item.');
        }

        $allowedUpdates = [];
        foreach ([
            'status',
            'owner_user_id',
            'scheduled_at',
            'reviewer_user_id',
            'review_due_at',
            'blocked_reason',
            'production_stage',
            'production_due_at',
            'dependency_status',
            'dependency_notes',
        ] as $field) {
            if (array_key_exists($field, $updates)) {
                $allowedUpdates[$field] = $updates[$field];
            }
        }
        if ($allowedUpdates === []) {
            throw new \InvalidArgumentException('Choose at least one bulk update.');
        }
        $allowedUpdates['change_summary'] = 'Bulk workbench update';

        $updated = [];
        foreach ($ids as $id) {
            if (!$this->getContentItem($id)) {
                throw new RuntimeException('Marketing content item not found.');
            }
            $this->updateContentItem($id, $allowedUpdates);
            $this->recordContentProductionEvent(
                $id,
                'bulk_updated',
                'Content production fields were updated in bulk.',
                [
                    'fields' => array_values(array_diff(array_keys($allowedUpdates), ['change_summary'])),
                ],
                $userId ?? $this->currentUserId()
            );
            $updated[] = $id;
        }

        $this->logBulkAction('content_bulk_update', 'content_items', count($updated), [
            'ids' => $updated,
            'updates' => $this->sanitizeFlexibleArray($allowedUpdates),
        ], $userId ?? $this->currentUserId());

        return [
            'updated_count' => count($updated),
            'ids' => $updated,
        ];
    }

    public function listContentItems(array $filters = [], int $limit = 100, int $offset = 0): array
    {
        $limit = min(max($limit, 1), 250);
        $offset = max($offset, 0);
        $workspace = $this->workspaceClause('m.');
        $where = [$workspace['sql']];
        $params = $workspace['params'];

        foreach (['status', 'content_type', 'channel', 'production_stage', 'dependency_status'] as $field) {
            $value = trim((string) ($filters[$field] ?? ''));
            if ($value === '') {
                continue;
            }
            $where[] = "m.{$field} = ?";
            $params[] = $this->normalizeEnum($value, $this->allowedValuesForField($field), $field);
        }

        if (!empty($filters['exclude_status'])) {
            $where[] = 'm.status <> ?';
            $params[] = $this->normalizeEnum((string) $filters['exclude_status'], self::STATUSES, 'status');
        }
        if (!empty($filters['campaign_id'])) {
            $where[] = 'm.campaign_id = ?';
            $params[] = (int) $filters['campaign_id'];
        }
        if (!empty($filters['campaign_brief_id'])) {
            $where[] = 'm.campaign_brief_id = ?';
            $params[] = (int) $filters['campaign_brief_id'];
        }
        if (!empty($filters['owner_user_id'])) {
            $where[] = 'm.owner_user_id = ?';
            $params[] = (int) $filters['owner_user_id'];
        }
        if (!empty($filters['reviewer_user_id'])) {
            $where[] = 'm.reviewer_user_id = ?';
            $params[] = (int) $filters['reviewer_user_id'];
        }
        if (!empty($filters['blocked'])) {
            $where[] = "m.blocked_reason IS NOT NULL AND m.blocked_reason <> ''";
        }
        if (!empty($filters['scheduled_from'])) {
            $where[] = 'm.scheduled_at >= ?';
            $params[] = $this->normalizeDateBoundary((string) $filters['scheduled_from'], false);
        }
        if (!empty($filters['scheduled_to'])) {
            $where[] = 'm.scheduled_at <= ?';
            $params[] = $this->normalizeDateBoundary((string) $filters['scheduled_to'], true);
        }
        if (!empty($filters['production_due_from'])) {
            $where[] = 'm.production_due_at >= ?';
            $params[] = $this->normalizeDateBoundary((string) $filters['production_due_from'], false);
        }
        if (!empty($filters['production_due_to'])) {
            $where[] = 'm.production_due_at <= ?';
            $params[] = $this->normalizeDateBoundary((string) $filters['production_due_to'], true);
        }
        if (!empty($filters['production_overdue'])) {
            $where[] = "m.production_due_at IS NOT NULL AND m.production_due_at < NOW() AND m.production_stage NOT IN ('published','archived')";
        }

        return array_map(
            fn(array $row): array => $this->hydrateContentItem($row),
            Database::query(
                "SELECT m.*, c.name AS campaign_name, f.name AS form_name, et.name AS email_template_name,
                        t.title AS task_title, mb.title AS campaign_brief_title,
                        bp.name AS brand_profile_name, mp.name AS persona_name,
                        st.keyword AS seo_topic_keyword, lp.title AS landing_page_title,
                        owner.email AS owner_email, reviewer.email AS reviewer_email, creator.email AS created_by_email
                 FROM marketing_content_items m
                 LEFT JOIN campaigns c ON c.id = m.campaign_id AND c.workspace_id = m.workspace_id
                 LEFT JOIN forms f ON f.id = m.form_id AND f.workspace_id = m.workspace_id
                 LEFT JOIN email_templates et ON et.id = m.email_template_id
                    AND (et.workspace_id = m.workspace_id OR (et.workspace_id IS NULL AND COALESCE(et.is_library, 0) = 1))
                 LEFT JOIN tasks t ON t.id = m.task_id AND t.workspace_id = m.workspace_id
                 LEFT JOIN marketing_campaign_briefs mb ON mb.id = m.campaign_brief_id AND mb.workspace_id = m.workspace_id
                 LEFT JOIN marketing_brand_profiles bp ON bp.id = m.brand_profile_id AND bp.workspace_id = m.workspace_id
                 LEFT JOIN marketing_personas mp ON mp.id = m.persona_id AND mp.workspace_id = m.workspace_id
                 LEFT JOIN marketing_seo_topics st ON st.id = m.seo_topic_id AND st.workspace_id = m.workspace_id
                 LEFT JOIN marketing_landing_pages lp ON lp.id = m.landing_page_id AND lp.workspace_id = m.workspace_id
                 LEFT JOIN users owner ON owner.id = m.owner_user_id
                 LEFT JOIN users reviewer ON reviewer.id = m.reviewer_user_id
                 LEFT JOIN users creator ON creator.id = m.created_by
                 WHERE " . implode(' AND ', $where) . "
                 ORDER BY
                    CASE WHEN m.production_due_at IS NULL THEN 1 ELSE 0 END ASC,
                    m.production_due_at ASC,
                    CASE WHEN m.scheduled_at IS NULL THEN 1 ELSE 0 END ASC,
                    m.scheduled_at ASC,
                    m.updated_at DESC
                 LIMIT {$limit} OFFSET {$offset}",
                $params
            )
        );
    }

    public function getContentItem(int $id): ?array
    {
        $workspace = $this->workspaceClause('m.');
        $row = Database::queryOne(
            "SELECT m.*, c.name AS campaign_name, f.name AS form_name, et.name AS email_template_name,
                    t.title AS task_title, mb.title AS campaign_brief_title,
                    bp.name AS brand_profile_name, mp.name AS persona_name,
                    st.keyword AS seo_topic_keyword, lp.title AS landing_page_title,
                    owner.email AS owner_email, reviewer.email AS reviewer_email, creator.email AS created_by_email
             FROM marketing_content_items m
             LEFT JOIN campaigns c ON c.id = m.campaign_id AND c.workspace_id = m.workspace_id
             LEFT JOIN forms f ON f.id = m.form_id AND f.workspace_id = m.workspace_id
             LEFT JOIN email_templates et ON et.id = m.email_template_id
                AND (et.workspace_id = m.workspace_id OR (et.workspace_id IS NULL AND COALESCE(et.is_library, 0) = 1))
             LEFT JOIN tasks t ON t.id = m.task_id AND t.workspace_id = m.workspace_id
             LEFT JOIN marketing_campaign_briefs mb ON mb.id = m.campaign_brief_id AND mb.workspace_id = m.workspace_id
             LEFT JOIN marketing_brand_profiles bp ON bp.id = m.brand_profile_id AND bp.workspace_id = m.workspace_id
             LEFT JOIN marketing_personas mp ON mp.id = m.persona_id AND mp.workspace_id = m.workspace_id
             LEFT JOIN marketing_seo_topics st ON st.id = m.seo_topic_id AND st.workspace_id = m.workspace_id
             LEFT JOIN marketing_landing_pages lp ON lp.id = m.landing_page_id AND lp.workspace_id = m.workspace_id
             LEFT JOIN users owner ON owner.id = m.owner_user_id
             LEFT JOIN users reviewer ON reviewer.id = m.reviewer_user_id
             LEFT JOIN users creator ON creator.id = m.created_by
             WHERE {$workspace['sql']} AND m.id = ?",
            array_merge($workspace['params'], [$id])
        );

        return $row ? $this->hydrateContentItem($row) : null;
    }

    public function createContentItem(array $data): int
    {
        $normalized = $this->normalizeContentData($data, true);
        Database::execute(
            "INSERT INTO marketing_content_items
             (workspace_id, uuid, title, content_type, channel, status,
              production_stage, production_due_at, production_started_at, production_completed_at,
              dependency_status, dependency_notes, production_checklist_json, production_score, next_action,
              funnel_stage, objective, target_audience,
              campaign_brief_id, brand_profile_id, persona_id, seo_topic_id, landing_page_id,
              campaign_id, form_id, email_template_id, task_id, scheduled_at, published_at, draft_body,
              ai_context_json, metadata_json, owner_user_id, reviewer_user_id, review_due_at, blocked_reason,
              readiness_score, approval_checklist_json, required_context_warnings_json, created_by)
             VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)",
            [
                $this->workspaceId(),
                $this->generateUuid(),
                $normalized['title'],
                $normalized['content_type'],
                $normalized['channel'],
                $normalized['status'],
                $normalized['production_stage'],
                $normalized['production_due_at'],
                $normalized['production_started_at'],
                $normalized['production_completed_at'],
                $normalized['dependency_status'],
                $normalized['dependency_notes'],
                $normalized['production_checklist_json'],
                $normalized['production_score'],
                $normalized['next_action'],
                $normalized['funnel_stage'],
                $normalized['objective'],
                $normalized['target_audience'],
                $normalized['campaign_brief_id'] ?? null,
                $normalized['brand_profile_id'] ?? null,
                $normalized['persona_id'] ?? null,
                $normalized['seo_topic_id'] ?? null,
                $normalized['landing_page_id'] ?? null,
                $normalized['campaign_id'],
                $normalized['form_id'],
                $normalized['email_template_id'],
                $normalized['task_id'],
                $normalized['scheduled_at'],
                $normalized['published_at'],
                $normalized['draft_body'],
                $normalized['ai_context_json'],
                $normalized['metadata_json'],
                $normalized['owner_user_id'],
                $normalized['reviewer_user_id'],
                $normalized['review_due_at'],
                $normalized['blocked_reason'],
                $normalized['readiness_score'],
                $normalized['approval_checklist_json'],
                $normalized['required_context_warnings_json'],
                $normalized['created_by'],
            ]
        );

        $contentId = (int) Database::lastInsertId();
        $this->recordContentProductionEvent(
            $contentId,
            'production_updated',
            'Content production record created.',
            [
                'production_stage' => $normalized['production_stage'],
                'dependency_status' => $normalized['dependency_status'],
            ],
            (int) ($normalized['created_by'] ?? $this->currentUserId()) ?: null
        );

        return $contentId;
    }

    public function updateContentItem(int $id, array $data): bool
    {
        $existing = $this->getContentItem($id);
        if (!$existing) {
            throw new RuntimeException('Marketing content item not found.');
        }

        $normalized = $this->normalizeContentData(array_merge($existing, $data), false);
        $updates = [];
        $params = [];
        foreach ($normalized as $field => $value) {
            $updates[] = $field . ' = ?';
            $params[] = $value;
        }

        if ($updates === []) {
            return true;
        }

        $params[] = $this->workspaceId();
        $params[] = $id;
        Database::execute(
            'UPDATE marketing_content_items SET ' . implode(', ', $updates) . ' WHERE workspace_id = ? AND id = ?',
            $params
        );

        if ($this->shouldVersionContent($existing, $normalized)) {
            $versionData = $existing;
            foreach (['title', 'draft_body', 'status'] as $field) {
                if (array_key_exists($field, $normalized)) {
                    $versionData[$field] = $normalized[$field];
                }
            }
            $this->createContentVersion(
                $id,
                $versionData,
                Security::sanitizeInput((string) ($data['change_summary'] ?? 'Content updated'), 'string')
            );
        }

        $this->recordContentProductionUpdateEvents($id, $existing, $normalized, (int) ($data['created_by'] ?? $this->currentUserId()) ?: null);

        return true;
    }

    public function deleteContentItem(int $id): bool
    {
        Database::execute(
            'DELETE FROM marketing_content_items WHERE workspace_id = ? AND id = ?',
            [$this->workspaceId(), $id]
        );

        return true;
    }

    public function getContentProductionSummary(?int $userId = null): array
    {
        $this->assertMarketingPermission('marketing.read');
        if (!Database::columnExists('marketing_content_items', 'production_stage')) {
            return [
                'by_stage' => [],
                'by_dependency_status' => [],
                'due_this_week' => [],
                'overdue' => [],
                'blocked' => [],
                'next_actions' => [],
            ];
        }

        $workspaceId = $this->workspaceId();
        $ownerClause = '';
        $ownerParams = [];
        if (($userId ?? 0) > 0) {
            $ownerClause = ' AND owner_user_id = ?';
            $ownerParams[] = (int) $userId;
        }

        $stageRows = Database::query(
            "SELECT production_stage, COUNT(*) AS count
             FROM marketing_content_items
             WHERE workspace_id = ?{$ownerClause}
             GROUP BY production_stage",
            array_merge([$workspaceId], $ownerParams)
        );
        $dependencyRows = Database::query(
            "SELECT dependency_status, COUNT(*) AS count
             FROM marketing_content_items
             WHERE workspace_id = ?{$ownerClause}
             GROUP BY dependency_status",
            array_merge([$workspaceId], $ownerParams)
        );

        return [
            'by_stage' => array_column($stageRows, 'count', 'production_stage'),
            'by_dependency_status' => array_column($dependencyRows, 'count', 'dependency_status'),
            'due_this_week' => $this->listContentItems([
                'production_due_from' => date('Y-m-d'),
                'production_due_to' => date('Y-m-d', strtotime('+7 days')),
            ] + (($userId ?? 0) > 0 ? ['owner_user_id' => $userId] : []), 8, 0),
            'overdue' => $this->listContentItems(['production_overdue' => true] + (($userId ?? 0) > 0 ? ['owner_user_id' => $userId] : []), 8, 0),
            'blocked' => $this->listContentItems(['dependency_status' => 'blocked'] + (($userId ?? 0) > 0 ? ['owner_user_id' => $userId] : []), 8, 0),
            'next_actions' => Database::query(
                "SELECT id, title, production_stage, production_due_at, next_action
                 FROM marketing_content_items
                 WHERE workspace_id = ?{$ownerClause}
                   AND next_action IS NOT NULL
                   AND next_action <> ''
                   AND production_stage NOT IN ('published','archived')
                 ORDER BY
                    CASE WHEN production_due_at IS NULL THEN 1 ELSE 0 END ASC,
                    production_due_at ASC,
                    updated_at DESC
                 LIMIT 8",
                array_merge([$workspaceId], $ownerParams)
            ),
        ];
    }

    public function getContentProductionCommandQueue(?int $userId = null, int $limit = 8): array
    {
        $this->assertMarketingPermission('marketing.read');
        $limit = min(max($limit, 1), 20);
        if (!Database::tableExists('marketing_content_items') || !Database::columnExists('marketing_content_items', 'production_stage')) {
            return [
                'score' => 0,
                'status' => 'unavailable',
                'summary' => ['by_stage' => [], 'by_dependency_status' => []],
                'queues' => [],
                'next_actions' => [],
                'guardrails' => [
                    'manual_first' => true,
                    'external_publish' => false,
                    'external_send' => false,
                ],
            ];
        }

        $summary = $this->getContentProductionSummary($userId);
        $ownerFilter = (($userId ?? 0) > 0) ? ['owner_user_id' => (int) $userId] : [];
        $reviewQueue = $this->listContentItems(['status' => 'review'] + $ownerFilter, $limit, 0);
        $mediaCandidates = $this->listContentItems(['exclude_status' => 'archived'] + $ownerFilter, min(80, max($limit * 6, 20)), 0);
        $mediaWarnings = array_values(array_filter(
            $mediaCandidates,
            static fn(array $item): bool => !empty($item['_media_readiness']['warnings'] ?? [])
        ));

        $missingLinksWhere = ["workspace_id = ?", "status <> 'archived'", '(campaign_id IS NULL OR campaign_brief_id IS NULL)'];
        $missingLinksParams = [$this->workspaceId()];
        if (($userId ?? 0) > 0) {
            $missingLinksWhere[] = 'owner_user_id = ?';
            $missingLinksParams[] = (int) $userId;
        }
        $missingLinks = Database::query(
            "SELECT id, title, status, content_type, channel, production_stage, production_due_at, next_action,
                    CASE
                        WHEN campaign_id IS NULL AND campaign_brief_id IS NULL THEN 'campaign_and_brief'
                        WHEN campaign_id IS NULL THEN 'campaign'
                        ELSE 'campaign_brief'
                    END AS missing_link
             FROM marketing_content_items
             WHERE " . implode(' AND ', $missingLinksWhere) . "
             ORDER BY updated_at DESC
             LIMIT {$limit}",
            $missingLinksParams
        );

        $blocked = array_slice((array) ($summary['blocked'] ?? []), 0, $limit);
        $overdue = array_slice((array) ($summary['overdue'] ?? []), 0, $limit);
        $dueThisWeek = array_slice((array) ($summary['due_this_week'] ?? []), 0, $limit);
        $nextActionRows = array_slice((array) ($summary['next_actions'] ?? []), 0, $limit);

        $total = array_sum(array_map('intval', (array) ($summary['by_stage'] ?? [])));
        $blockedCount = count($blocked);
        $overdueCount = count($overdue);
        $reviewCount = count($reviewQueue);
        $mediaWarningCount = count($mediaWarnings);
        $missingLinkCount = count($missingLinks);
        $score = $total <= 0
            ? 0
            : max(0, min(100, 100 - ($blockedCount * 14) - ($overdueCount * 10) - ($missingLinkCount * 7) - ($mediaWarningCount * 5)));

        $nextActions = [];
        $addAction = static function (array &$nextActions, string $label, string $href, string $reason, string $priority): void {
            $nextActions[] = [
                'label' => $label,
                'href' => $href,
                'reason' => $reason,
                'priority' => $priority,
            ];
        };
        if ($blockedCount > 0) {
            $addAction($nextActions, 'Resolve blocked content', 'marketing_content.php?blocked=1', $blockedCount . ' blocked item(s) need owner action before production can move.', 'high');
        }
        if ($overdueCount > 0) {
            $addAction($nextActions, 'Review overdue production work', 'marketing_content.php?production_overdue=1', $overdueCount . ' item(s) are past production due date.', 'high');
        }
        if ($reviewCount > 0) {
            $addAction($nextActions, 'Clear review queue', 'marketing_reviews.php', $reviewCount . ' content item(s) are waiting in review.', 'medium');
        }
        if ($mediaWarningCount > 0) {
            $addAction($nextActions, 'Fix media readiness warnings', 'marketing_content.php?media_warning=1', $mediaWarningCount . ' item(s) have missing or weak media readiness.', 'medium');
        }
        if ($missingLinkCount > 0) {
            $addAction($nextActions, 'Connect content to campaigns and briefs', 'marketing_content.php', $missingLinkCount . ' item(s) are missing campaign or brief links.', 'medium');
        }
        foreach ($nextActionRows as $row) {
            if (count($nextActions) >= $limit) {
                break;
            }
            $addAction(
                $nextActions,
                (string) ($row['next_action'] ?? 'Review production next action'),
                'marketing_content_view.php?id=' . (int) ($row['id'] ?? 0),
                (string) ($row['title'] ?? 'Content item'),
                'normal'
            );
        }

        return [
            'score' => $score,
            'status' => $total <= 0 ? 'empty' : ($score >= 85 ? 'healthy' : ($score >= 60 ? 'needs_attention' : 'blocked')),
            'summary' => $summary,
            'counts' => [
                'total' => $total,
                'blocked' => $blockedCount,
                'overdue' => $overdueCount,
                'review_queue' => $reviewCount,
                'media_warnings' => $mediaWarningCount,
                'missing_links' => $missingLinkCount,
            ],
            'queues' => [
                'blocked' => $blocked,
                'overdue' => $overdue,
                'due_this_week' => $dueThisWeek,
                'review_queue' => $reviewQueue,
                'media_warnings' => array_slice($mediaWarnings, 0, $limit),
                'missing_links' => $missingLinks,
            ],
            'next_actions' => array_slice($nextActions, 0, $limit),
            'recommended_product_decision' => 'Use the production command queue as the daily operator view before scheduling or exporting content.',
            'performance' => [
                'limit' => $limit,
                'media_scan_limit' => min(80, max($limit * 6, 20)),
                'page_load_guard' => true,
            ],
            'guardrails' => [
                'manual_first' => true,
                'external_publish' => false,
                'external_send' => false,
                'message' => 'The production command queue prioritizes work only. It does not publish, send, or trigger external channel execution.',
            ],
        ];
    }

    public function updateContentProduction(int $contentItemId, array $data): array
    {
        $this->assertMarketingPermission('marketing.write');
        $existing = $this->getContentItem($contentItemId);
        if (!$existing) {
            throw new RuntimeException('Marketing content item not found.');
        }

        $payload = [];
        foreach ([
            'production_stage',
            'production_due_at',
            'production_started_at',
            'production_completed_at',
            'dependency_status',
            'dependency_notes',
            'production_checklist',
            'production_checklist_json',
            'blocked_reason',
        ] as $field) {
            if (array_key_exists($field, $data)) {
                $payload[$field] = $data[$field];
            }
        }

        if ($payload === []) {
            throw new \InvalidArgumentException('Choose at least one production field to update.');
        }

        $newStage = (string) ($payload['production_stage'] ?? '');
        if ($newStage !== '' && $newStage !== (string) ($existing['production_stage'] ?? '')) {
            if (empty($existing['production_started_at']) && in_array($newStage, ['drafting', 'design', 'review', 'approved', 'scheduled', 'published'], true)) {
                $payload['production_started_at'] = date('Y-m-d\TH:i');
            }
            if (empty($existing['production_completed_at']) && in_array($newStage, ['published', 'archived'], true)) {
                $payload['production_completed_at'] = date('Y-m-d\TH:i');
            }
        }

        $payload['change_summary'] = 'Production workflow updated';
        $payload['created_by'] = (int) ($data['created_by'] ?? $this->currentUserId()) ?: null;
        $this->updateContentItem($contentItemId, $payload);

        return $this->getContentItem($contentItemId) ?: [];
    }

    public function listContentDependencies(int $contentItemId): array
    {
        if (!Database::tableExists('marketing_content_dependencies')) {
            return [];
        }
        $this->assertWorkspaceRecord('marketing_content_items', $contentItemId, $this->workspaceId());

        return array_map(
            fn(array $row): array => $this->hydrateJsonFields($row, ['metadata_json']),
            Database::query(
                "SELECT d.*, owner.email AS owner_email, creator.email AS created_by_email, dc.title AS depends_on_content_title
                 FROM marketing_content_dependencies d
                 LEFT JOIN users owner ON owner.id = d.owner_user_id
                 LEFT JOIN users creator ON creator.id = d.created_by
                 LEFT JOIN marketing_content_items dc ON dc.id = d.depends_on_content_item_id AND dc.workspace_id = d.workspace_id
                 WHERE d.workspace_id = ? AND d.content_item_id = ?
                 ORDER BY
                    FIELD(d.status, 'blocked', 'waiting', 'ready', 'done'),
                    CASE WHEN d.due_at IS NULL THEN 1 ELSE 0 END ASC,
                    d.due_at ASC,
                    d.updated_at DESC",
                [$this->workspaceId(), $contentItemId]
            )
        );
    }

    public function getContentDependency(int $dependencyId): ?array
    {
        if (!Database::tableExists('marketing_content_dependencies')) {
            return null;
        }

        $row = Database::queryOne(
            "SELECT d.*, owner.email AS owner_email, creator.email AS created_by_email, dc.title AS depends_on_content_title
             FROM marketing_content_dependencies d
             LEFT JOIN users owner ON owner.id = d.owner_user_id
             LEFT JOIN users creator ON creator.id = d.created_by
             LEFT JOIN marketing_content_items dc ON dc.id = d.depends_on_content_item_id AND dc.workspace_id = d.workspace_id
             WHERE d.workspace_id = ? AND d.id = ?",
            [$this->workspaceId(), $dependencyId]
        );

        return $row ? $this->hydrateJsonFields($row, ['metadata_json']) : null;
    }

    public function createContentDependency(array $data): int
    {
        $this->assertMarketingPermission('marketing.write');
        $normalized = $this->normalizeContentDependencyData($data, true);
        Database::execute(
            "INSERT INTO marketing_content_dependencies
             (workspace_id, uuid, content_item_id, depends_on_content_item_id, dependency_type, title, status,
              due_at, owner_user_id, notes, metadata_json, created_by)
             VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)",
            [
                $this->workspaceId(),
                $this->generateUuid(),
                $normalized['content_item_id'],
                $normalized['depends_on_content_item_id'],
                $normalized['dependency_type'],
                $normalized['title'],
                $normalized['status'],
                $normalized['due_at'],
                $normalized['owner_user_id'],
                $normalized['notes'],
                $normalized['metadata_json'],
                $normalized['created_by'],
            ]
        );

        $id = (int) Database::lastInsertId();
        $this->refreshContentProductionFromDependencies((int) $normalized['content_item_id']);
        $this->recordContentProductionEvent(
            (int) $normalized['content_item_id'],
            'dependency_added',
            'Production dependency added: ' . $normalized['title'],
            ['dependency_id' => $id, 'status' => $normalized['status'], 'type' => $normalized['dependency_type']],
            (int) ($normalized['created_by'] ?? $this->currentUserId()) ?: null
        );

        return $id;
    }

    public function updateContentDependency(int $dependencyId, array $data): bool
    {
        $this->assertMarketingPermission('marketing.write');
        $existing = $this->getContentDependency($dependencyId);
        if (!$existing) {
            throw new RuntimeException('Marketing content dependency not found.');
        }

        $normalized = $this->normalizeContentDependencyData(array_merge($existing, $data), false);
        $this->updateById('marketing_content_dependencies', $dependencyId, $normalized);
        $this->refreshContentProductionFromDependencies((int) $existing['content_item_id']);
        $this->recordContentProductionEvent(
            (int) $existing['content_item_id'],
            'dependency_updated',
            'Production dependency updated: ' . (string) ($normalized['title'] ?? $existing['title']),
            ['dependency_id' => $dependencyId, 'fields' => array_keys($data)],
            (int) ($data['created_by'] ?? $this->currentUserId()) ?: null
        );

        return true;
    }

    public function deleteContentDependency(int $dependencyId): bool
    {
        $this->assertMarketingPermission('marketing.manage');
        $existing = $this->getContentDependency($dependencyId);
        if (!$existing) {
            throw new RuntimeException('Marketing content dependency not found.');
        }

        Database::execute(
            'DELETE FROM marketing_content_dependencies WHERE workspace_id = ? AND id = ?',
            [$this->workspaceId(), $dependencyId]
        );
        $this->refreshContentProductionFromDependencies((int) $existing['content_item_id']);
        $this->recordContentProductionEvent(
            (int) $existing['content_item_id'],
            'dependency_deleted',
            'Production dependency deleted: ' . (string) ($existing['title'] ?? 'Dependency'),
            ['dependency_id' => $dependencyId],
            $this->currentUserId()
        );

        return true;
    }

    public function listContentProductionEvents(int $contentItemId, int $limit = 25, int $offset = 0): array
    {
