                 LEFT JOIN users actor ON actor.id = e.actor_user_id
                 WHERE e.workspace_id = ? AND e.content_item_id = ?
                 ORDER BY e.created_at DESC, e.id DESC
                 LIMIT {$limit} OFFSET {$offset}",
