            )
        );
    }

    public function listContentMedia(int $contentItemId): array
    {
        if (!Database::tableExists('marketing_content_media')) {
            return [];
        }
        $this->assertWorkspaceRecord('marketing_content_items', $contentItemId, $this->workspaceId());

        return array_map(
            fn(array $row): array => $this->hydrateContentMediaRow($row),
            Database::query(
                "SELECT cm.*,
                        mf.title AS media_title, mf.media_type, mf.source_type AS media_source_type,
                        mf.file_path AS media_file_path, mf.source_url AS media_source_url,
                        mf.mime_type AS media_mime_type, mf.thumbnail_path AS media_thumbnail_path,
                        mf.thumbnail_url AS media_thumbnail_url, mf.alt_text AS media_alt_text,
                        mf.caption AS media_caption, mf.transcript AS media_transcript,
                        mf.usage_rights AS media_usage_rights, mf.approval_status, mf.license_status,
                        mf.expiry_date, mf.accessibility_status, mf.blocked_reason
                 FROM marketing_content_media cm
                 JOIN marketing_media_files mf ON mf.id = cm.media_file_id AND mf.workspace_id = cm.workspace_id
                 WHERE cm.workspace_id = ? AND cm.content_item_id = ?
                 ORDER BY cm.sort_order ASC, cm.id ASC",
                [$this->workspaceId(), $contentItemId]
            )
        );
    }

