    }

    public function attachContentMedia(int $contentItemId, array $data): int
    {
        $this->assertMarketingPermission('marketing.write');
        $normalized = $this->normalizeContentMediaData($contentItemId, $data, true);
        Database::execute(
            "INSERT INTO marketing_content_media
             (workspace_id, uuid, content_item_id, media_file_id, role, channel, crop_guidance, placement_notes,
              caption, alt_text_override, sort_order, metadata_json, created_by)
             VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)",
            [
                $this->workspaceId(),
                $this->generateUuid(),
                $contentItemId,
                $normalized['media_file_id'],
                $normalized['role'],
                $normalized['channel'],
                $normalized['crop_guidance'],
                $normalized['placement_notes'],
                $normalized['caption'],
                $normalized['alt_text_override'],
                $normalized['sort_order'],
                $normalized['metadata_json'],
                $normalized['created_by'],
            ]
        );

        $id = (int) Database::lastInsertId();
        $this->recordMediaAuditEvent(
            'attach',
            (int) $normalized['media_file_id'],
            'Media attached to content.',
            [],
            $normalized['created_by'],
            'marketing_content_items',
            $contentItemId
        );

        return $id;
    }

    public function updateContentMediaAttachment(int $id, array $data): bool
    {
        $this->assertMarketingPermission('marketing.write');
        $existing = $this->getContentMediaAttachment($id);
        if (!$existing) {
            throw new RuntimeException('Marketing content media attachment not found.');
        }

        return $this->updateById(
            'marketing_content_media',
            $id,
            $this->normalizeContentMediaData((int) $existing['content_item_id'], array_merge($existing, $data), false)
        );
    }

    public function detachContentMedia(int $id): bool
    {
        $this->assertMarketingPermission('marketing.write');
        $existing = $this->getContentMediaAttachment($id);
        if (!$existing) {
            throw new RuntimeException('Marketing content media attachment not found.');
        }

        Database::execute(
            'DELETE FROM marketing_content_media WHERE workspace_id = ? AND id = ?',
            [$this->workspaceId(), $id]
        );
        $this->recordMediaAuditEvent('detach', (int) ($existing['media_file_id'] ?? 0), 'Media detached from content.', [], $this->currentUserId(), 'marketing_content_media', $id);

        return true;
    }

    public function replaceContentMedia(int $contentItemId, mixed $entries, ?int $userId = null): array
    {
        $this->assertMarketingPermission('marketing.write');
        $this->assertWorkspaceRecord('marketing_content_items', $contentItemId, $this->workspaceId());
        $rows = $this->normalizeContentMediaEntries($entries);
        $prepared = [];
        foreach ($rows as $index => $row) {
            $prepared[] = $row + [
                'sort_order' => $index + 1,
                'created_by' => $userId ?? $this->currentUserId(),
            ];
            $this->normalizeContentMediaData($contentItemId, $prepared[$index], true);
        }

        Database::execute(
            'DELETE FROM marketing_content_media WHERE workspace_id = ? AND content_item_id = ?',
            [$this->workspaceId(), $contentItemId]
        );

        $ids = [];
        foreach ($prepared as $row) {
            $ids[] = $this->attachContentMedia($contentItemId, $row);
        }

        return [
            'ids' => $ids,
            'attachments' => $this->listContentMedia($contentItemId),
        ];
    }

    public function listCampaignBriefs(array $filters = [], int $limit = 100, int $offset = 0): array
    {
        $limit = min(max($limit, 1), 250);
        $offset = max($offset, 0);
        $workspace = $this->workspaceClause('b.');
        $where = [$workspace['sql']];
        $params = $workspace['params'];

        if (!empty($filters['status'])) {
            $where[] = 'b.status = ?';
            $params[] = $this->normalizeEnum((string) $filters['status'], self::BRIEF_STATUSES, 'brief_status');
        }
        if (!empty($filters['status_open'])) {
            $where[] = "b.status IN ('draft','active')";
        }
        if (!empty($filters['campaign_id'])) {
            $where[] = 'b.campaign_id = ?';
            $params[] = (int) $filters['campaign_id'];
        }
        if (!empty($filters['campaign_playbook_id'])) {
            $where[] = 'b.campaign_playbook_id = ?';
            $params[] = (int) $filters['campaign_playbook_id'];
        }
        if (!empty($filters['persona_id'])) {
            $where[] = 'b.persona_id = ?';
            $params[] = (int) $filters['persona_id'];
        }
        if (!empty($filters['audience_segment_id'])) {
            $where[] = 'b.audience_segment_id = ?';
            $params[] = (int) $filters['audience_segment_id'];
        }
        if (!empty($filters['owner_user_id'])) {
            $where[] = 'b.owner_user_id = ?';
            $params[] = (int) $filters['owner_user_id'];
        }

        return array_map(
            fn(array $row): array => $this->hydrateJsonFields($row, ['channels_json', 'channel_plan_json', 'launch_timeline_json', 'metadata_json', 'missing_strategy_json', 'launch_readiness_json']),
            Database::query(
                "SELECT b.*, c.name AS campaign_name, pb.name AS campaign_playbook_name, seg.name AS audience_segment_name,
                        p.name AS persona_name, lp.title AS landing_page_title,
                        offer.title AS offer_title, pillar.title AS content_pillar_title,
                        owner.email AS owner_email, creator.email AS created_by_email
                 FROM marketing_campaign_briefs b
                 LEFT JOIN campaigns c ON c.id = b.campaign_id AND c.workspace_id = b.workspace_id
                 LEFT JOIN marketing_campaign_playbooks pb ON pb.id = b.campaign_playbook_id AND pb.workspace_id = b.workspace_id
                 LEFT JOIN marketing_audience_segments seg ON seg.id = b.audience_segment_id AND seg.workspace_id = b.workspace_id
                 LEFT JOIN marketing_personas p ON p.id = b.persona_id AND p.workspace_id = b.workspace_id
                 LEFT JOIN marketing_landing_pages lp ON lp.id = b.landing_page_id AND lp.workspace_id = b.workspace_id
                 LEFT JOIN marketing_context_items offer ON offer.id = b.offer_context_item_id AND offer.workspace_id = b.workspace_id
                 LEFT JOIN marketing_context_items pillar ON pillar.id = b.content_pillar_context_item_id AND pillar.workspace_id = b.workspace_id
                 LEFT JOIN users owner ON owner.id = b.owner_user_id
                 LEFT JOIN users creator ON creator.id = b.created_by
                 WHERE " . implode(' AND ', $where) . "
                 ORDER BY
                    CASE WHEN b.start_date IS NULL THEN 1 ELSE 0 END ASC,
                    b.start_date ASC,
                    b.updated_at DESC
                 LIMIT {$limit} OFFSET {$offset}",
                $params
            )
        );
    }

    public function getCampaignBrief(int $id): ?array
    {
        $workspace = $this->workspaceClause('b.');
        $row = Database::queryOne(
            "SELECT b.*, c.name AS campaign_name, pb.name AS campaign_playbook_name, seg.name AS audience_segment_name,
                    p.name AS persona_name, lp.title AS landing_page_title,
                    offer.title AS offer_title, pillar.title AS content_pillar_title,
                    owner.email AS owner_email, creator.email AS created_by_email
             FROM marketing_campaign_briefs b
             LEFT JOIN campaigns c ON c.id = b.campaign_id AND c.workspace_id = b.workspace_id
             LEFT JOIN marketing_campaign_playbooks pb ON pb.id = b.campaign_playbook_id AND pb.workspace_id = b.workspace_id
             LEFT JOIN marketing_audience_segments seg ON seg.id = b.audience_segment_id AND seg.workspace_id = b.workspace_id
             LEFT JOIN marketing_personas p ON p.id = b.persona_id AND p.workspace_id = b.workspace_id
             LEFT JOIN marketing_landing_pages lp ON lp.id = b.landing_page_id AND lp.workspace_id = b.workspace_id
             LEFT JOIN marketing_context_items offer ON offer.id = b.offer_context_item_id AND offer.workspace_id = b.workspace_id
             LEFT JOIN marketing_context_items pillar ON pillar.id = b.content_pillar_context_item_id AND pillar.workspace_id = b.workspace_id
             LEFT JOIN users owner ON owner.id = b.owner_user_id
             LEFT JOIN users creator ON creator.id = b.created_by
             WHERE {$workspace['sql']} AND b.id = ?",
            array_merge($workspace['params'], [$id])
        );

        return $row ? $this->hydrateJsonFields($row, ['channels_json', 'channel_plan_json', 'launch_timeline_json', 'metadata_json', 'missing_strategy_json', 'launch_readiness_json']) : null;
    }

    public function createCampaignBrief(array $data): int
    {
        $normalized = $this->normalizeCampaignBriefData($data, true);
        Database::execute(
            "INSERT INTO marketing_campaign_briefs
             (workspace_id, uuid, title, objective, audience, audience_segment_id, offer_text, key_message, channels_json,
              start_date, end_date, campaign_id, campaign_playbook_id, persona_id, offer_context_item_id, content_pillar_context_item_id,
              landing_page_id, success_metrics, budget_estimate, channel_plan_json, launch_timeline_json,
              owner_user_id, status, metadata_json, context_score, readiness_score, missing_strategy_json, created_by)
             VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)",
            [
                $this->workspaceId(),
                $this->generateUuid(),
                $normalized['title'],
                $normalized['objective'],
                $normalized['audience'],
                $normalized['audience_segment_id'],
                $normalized['offer_text'],
                $normalized['key_message'],
                $normalized['channels_json'],
                $normalized['start_date'],
                $normalized['end_date'],
                $normalized['campaign_id'],
                $normalized['campaign_playbook_id'],
                $normalized['persona_id'],
                $normalized['offer_context_item_id'],
                $normalized['content_pillar_context_item_id'],
                $normalized['landing_page_id'],
                $normalized['success_metrics'],
                $normalized['budget_estimate'],
                $normalized['channel_plan_json'],
                $normalized['launch_timeline_json'],
                $normalized['owner_user_id'],
                $normalized['status'],
                $normalized['metadata_json'],
                $normalized['context_score'],
                $normalized['readiness_score'],
                $normalized['missing_strategy_json'],
                $normalized['created_by'],
            ]
        );

        return (int) Database::lastInsertId();
    }

    public function updateCampaignBrief(int $id, array $data): bool
    {
        $existing = $this->getCampaignBrief($id);
        if (!$existing) {
            throw new RuntimeException('Marketing campaign brief not found.');
        }

        $normalized = $this->normalizeCampaignBriefData(array_merge($existing, $data), false);
        return $this->updateById('marketing_campaign_briefs', $id, $normalized);
    }

    public function deleteCampaignBrief(int $id): bool
    {
        Database::execute(
            'DELETE FROM marketing_campaign_briefs WHERE workspace_id = ? AND id = ?',
            [$this->workspaceId(), $id]
        );

        return true;
    }

    public function listCampaignPlaybooks(array $filters = [], int $limit = 100, int $offset = 0): array
    {
        if (!Database::tableExists('marketing_campaign_playbooks')) {
            return [];
        }

        $limit = min(max($limit, 1), 250);
        $offset = max($offset, 0);
        $where = ['p.workspace_id = ?'];
        $params = [$this->workspaceId()];

        if (!empty($filters['status'])) {
            $where[] = 'p.status = ?';
            $params[] = $this->normalizeEnum((string) $filters['status'], self::CAMPAIGN_PLAYBOOK_STATUSES, 'campaign_playbook_status');
        } elseif (!empty($filters['exclude_archived'])) {
            $where[] = "p.status <> 'archived'";
        }
        if (!empty($filters['playbook_type'])) {
            $where[] = 'p.playbook_type = ?';
            $params[] = $this->normalizeEnum((string) $filters['playbook_type'], self::CAMPAIGN_PLAYBOOK_TYPES, 'campaign_playbook_type');
        }
        if (array_key_exists('is_template', $filters) && $filters['is_template'] !== '') {
            $where[] = 'p.is_template = ?';
            $params[] = !empty($filters['is_template']) ? 1 : 0;
        }
        if (!empty($filters['template_key'])) {
            $where[] = 'p.template_key = ?';
            $params[] = $this->normalizeCampaignPlaybookTemplateKey((string) $filters['template_key']);
        }
        if (!empty($filters['audience_segment_id'])) {
            $where[] = 'p.audience_segment_id = ?';
            $params[] = (int) $filters['audience_segment_id'];
        }
        if (!empty($filters['owner_user_id'])) {
            $where[] = 'p.owner_user_id = ?';
            $params[] = (int) $filters['owner_user_id'];
        }
        if (!empty($filters['id'])) {
            $where[] = 'p.id = ?';
            $params[] = (int) $filters['id'];
        }

        return array_map(
            fn(array $row): array => $this->hydrateCampaignPlaybookRow($row),
            Database::query(
                "SELECT p.*, seg.name AS audience_segment_name, persona.name AS persona_name,
                        offer.title AS offer_title, lp.title AS landing_page_title,
                        owner.email AS owner_email, creator.email AS created_by_email,
                        COUNT(DISTINCT st.id) AS stage_count,
                        COUNT(DISTINCT b.id) AS brief_count
                 FROM marketing_campaign_playbooks p
                 LEFT JOIN marketing_audience_segments seg ON seg.id = p.audience_segment_id AND seg.workspace_id = p.workspace_id
                 LEFT JOIN marketing_personas persona ON persona.id = p.persona_id AND persona.workspace_id = p.workspace_id
                 LEFT JOIN marketing_context_items offer ON offer.id = p.offer_context_item_id AND offer.workspace_id = p.workspace_id
                 LEFT JOIN marketing_landing_pages lp ON lp.id = p.landing_page_id AND lp.workspace_id = p.workspace_id
                 LEFT JOIN users owner ON owner.id = p.owner_user_id
                 LEFT JOIN users creator ON creator.id = p.created_by
                 LEFT JOIN marketing_campaign_playbook_stages st ON st.playbook_id = p.id AND st.workspace_id = p.workspace_id
                 LEFT JOIN marketing_campaign_briefs b ON b.campaign_playbook_id = p.id AND b.workspace_id = p.workspace_id
                 WHERE " . implode(' AND ', $where) . "
                 GROUP BY p.id
                 ORDER BY p.status = 'active' DESC, p.readiness_score DESC, p.updated_at DESC
                 LIMIT {$limit} OFFSET {$offset}",
                $params
            )
        );
    }

    public function getCampaignPlaybook(int $id): ?array
    {
        $playbooks = $this->listCampaignPlaybooks(['id' => $id], 1, 0);
        if ($playbooks === []) {
            return null;
        }

        $playbook = $playbooks[0];
        $playbook['stages'] = $this->listCampaignPlaybookStages($id);

        return $playbook;
    }

    public function listCampaignPlaybookStages(int $playbookId): array
    {
        if (!Database::tableExists('marketing_campaign_playbook_stages')) {
            return [];
        }
        $this->assertWorkspaceRecord('marketing_campaign_playbooks', $playbookId, $this->workspaceId());

        return array_map(
            fn(array $row): array => $this->hydrateJsonFields($row, ['checklist_json', 'metadata_json']),
            Database::query(
                'SELECT * FROM marketing_campaign_playbook_stages WHERE workspace_id = ? AND playbook_id = ? ORDER BY stage_order ASC, id ASC',
                [$this->workspaceId(), $playbookId]
            )
        );
    }

    public function createCampaignPlaybook(array $data): int
    {
        $this->assertMarketingPermission('marketing.write');
        $normalized = $this->normalizeCampaignPlaybookData($data, true);
        $stages = $this->normalizeCampaignPlaybookStages($data['stages'] ?? $data['stages_json'] ?? []);

        Database::beginTransaction();
        try {
            Database::execute(
                "INSERT INTO marketing_campaign_playbooks
                 (workspace_id, uuid, name, description, status, playbook_type, template_key, is_template, campaign_goal, target_audience,
                  audience_segment_id, persona_id, offer_context_item_id, landing_page_id,
                  success_metrics_json, channel_plan_json, checklist_json, default_content_plan_json,
                  default_distribution_plan_json, recommended_assets_json, automation_notes_json, readiness_score,
                  missing_requirements_json, metadata_json, owner_user_id, created_by)
                 VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)",
                [
                    $this->workspaceId(),
                    $this->generateUuid(),
                    $normalized['name'],
                    $normalized['description'],
                    $normalized['status'],
                    $normalized['playbook_type'],
                    $normalized['template_key'],
                    $normalized['is_template'],
                    $normalized['campaign_goal'],
                    $normalized['target_audience'],
                    $normalized['audience_segment_id'],
                    $normalized['persona_id'],
                    $normalized['offer_context_item_id'],
                    $normalized['landing_page_id'],
                    $normalized['success_metrics_json'],
                    $normalized['channel_plan_json'],
                    $normalized['checklist_json'],
                    $normalized['default_content_plan_json'],
                    $normalized['default_distribution_plan_json'],
                    $normalized['recommended_assets_json'],
                    $normalized['automation_notes_json'],
                    $normalized['readiness_score'],
                    $normalized['missing_requirements_json'],
                    $normalized['metadata_json'],
                    $normalized['owner_user_id'],
                    $normalized['created_by'],
                ]
            );
            $id = (int) Database::lastInsertId();
            $this->replaceCampaignPlaybookStages($id, $stages);
            $this->refreshCampaignPlaybookReadiness($id);
            Database::commit();

            return $id;
        } catch (Throwable $e) {
            Database::rollBack();
            throw $e;
        }
    }

    public function updateCampaignPlaybook(int $id, array $data): bool
    {
        $this->assertMarketingPermission('marketing.write');
        $existing = $this->getCampaignPlaybook($id);
        if (!$existing) {
            throw new RuntimeException('Marketing campaign playbook not found.');
        }

        $normalized = $this->normalizeCampaignPlaybookData(array_merge($existing, $data), false);
        $hasStages = array_key_exists('stages', $data) || array_key_exists('stages_json', $data);
        $stages = $hasStages ? $this->normalizeCampaignPlaybookStages($data['stages'] ?? $data['stages_json'] ?? []) : null;

        Database::beginTransaction();
        try {
            $this->updateById('marketing_campaign_playbooks', $id, $normalized);
            if ($stages !== null) {
                $this->replaceCampaignPlaybookStages($id, $stages);
            }
            $this->refreshCampaignPlaybookReadiness($id);
            Database::commit();
        } catch (Throwable $e) {
            Database::rollBack();
            throw $e;
        }

        return true;
    }

    public function deleteCampaignPlaybook(int $id): bool
    {
        $this->assertMarketingPermission('marketing.manage');
        $this->assertWorkspaceRecord('marketing_campaign_playbooks', $id, $this->workspaceId());
        Database::execute(
            "UPDATE marketing_campaign_playbooks SET status = 'archived' WHERE workspace_id = ? AND id = ?",
            [$this->workspaceId(), $id]
        );

        return true;
    }

    public function createCampaignBriefFromPlaybook(int $playbookId, int $userId, array $overrides = []): int
    {
        $this->assertMarketingPermission('marketing.write');
        $playbook = $this->getCampaignPlaybook($playbookId);
        if (!$playbook) {
            throw new RuntimeException('Marketing campaign playbook not found.');
        }
        if ((string) ($playbook['status'] ?? '') === 'archived') {
            throw new RuntimeException('Archived campaign playbooks cannot create briefs.');
        }

        $channelPlan = array_map(
            static fn(array $stage): string => (string) ($stage['title'] ?? ''),
            array_filter((array) ($playbook['stages'] ?? []), static fn(array $stage): bool => in_array((string) ($stage['stage_type'] ?? ''), ['content', 'distribution', 'sales_handoff'], true))
        );
        $payload = array_merge([
            'title' => (string) ($overrides['title'] ?? ((string) $playbook['name'] . ' Brief')),
            'objective' => (string) ($playbook['campaign_goal'] ?? ''),
            'audience' => (string) ($playbook['target_audience'] ?? ''),
            'audience_segment_id' => $playbook['audience_segment_id'] ?? null,
            'persona_id' => $playbook['persona_id'] ?? null,
            'offer_context_item_id' => $playbook['offer_context_item_id'] ?? null,
            'landing_page_id' => $playbook['landing_page_id'] ?? null,
            'success_metrics' => implode("\n", (array) ($playbook['success_metrics_json'] ?? [])),
            'channel_plan' => $channelPlan !== [] ? $channelPlan : (array) ($playbook['channel_plan_json'] ?? []),
            'launch_timeline' => array_map(static fn(array $stage): string => (string) ($stage['title'] ?? ''), (array) ($playbook['stages'] ?? [])),
            'status' => 'draft',
            'owner_user_id' => $playbook['owner_user_id'] ?? null,
            'campaign_playbook_id' => $playbookId,
            'metadata_json' => [
                'source' => 'marketing_campaign_playbook',
                'campaign_playbook_id' => $playbookId,
                'manual_first' => true,
                'external_execution' => false,
            ],
            'created_by' => $userId,
        ], $overrides);

        return $this->createCampaignBrief($payload);
    }

