    public function createCampaignPlaybookFromTemplate(string $templateKey, int $userId, array $overrides = []): int
    {
        $this->assertMarketingPermission('marketing.write');
        $templateKey = $this->normalizeCampaignPlaybookTemplateKey($templateKey);
        $definitions = $this->campaignPlaybookTemplateDefinitions();
        if (!isset($definitions[$templateKey])) {
            throw new \InvalidArgumentException('Unknown campaign playbook template.');
        }

        $existing = Database::queryOne(
            "SELECT id FROM marketing_campaign_playbooks
             WHERE workspace_id = ? AND template_key = ? AND is_template = 1 AND status <> 'archived'
             ORDER BY updated_at DESC, id DESC LIMIT 1",
            [$this->workspaceId(), $templateKey]
        );
        if ($existing) {
            return (int) $existing['id'];
        }

        $definition = $definitions[$templateKey];
        $payload = array_merge($definition, $overrides, [
            'template_key' => $templateKey,
            'is_template' => 1,
            'playbook_type' => (string) ($definition['playbook_type'] ?? 'custom'),
            'status' => (string) ($overrides['status'] ?? 'active'),
            'metadata_json' => array_merge(
                (array) ($overrides['metadata_json'] ?? $overrides['metadata'] ?? []),
                [
                    'source' => 'marketing_system_playbook_template',
                    'template_key' => $templateKey,
                    'manual_first' => true,
                    'external_execution' => false,
                ]
            ),
            'created_by' => $userId,
        ]);

        return $this->createCampaignPlaybook($payload);
    }

    public function applyCampaignPlaybook(int $playbookId, int $userId, array $options = []): array
    {
        $this->assertMarketingPermission('marketing.write');
        if (!Database::tableExists('marketing_playbook_application_runs')) {
            throw new RuntimeException('Marketing playbook application runs table is not available.');
        }

        $playbook = $this->getCampaignPlaybook($playbookId);
        if (!$playbook) {
            throw new RuntimeException('Marketing campaign playbook not found.');
        }
        if ((string) ($playbook['status'] ?? '') === 'archived') {
            throw new RuntimeException('Archived campaign playbooks cannot be applied.');
        }

        $workspaceId = $this->workspaceId();
        $campaignId = (int) ($options['campaign_id'] ?? 0);
        if ($campaignId > 0) {
            $this->assertWorkspaceRecord('campaigns', $campaignId, $workspaceId);
        } else {
            $campaignId = null;
        }

        $scope = [
            'brief' => (bool) ($options['create_brief'] ?? true),
            'landing_page' => (bool) ($options['create_landing_page'] ?? true),
            'content' => (bool) ($options['create_content'] ?? true),
            'distribution' => (bool) ($options['create_distribution'] ?? true),
            'calendar' => (bool) ($options['create_calendar'] ?? true),
            'planning_queue' => (bool) ($options['create_queue'] ?? true),
        ];
        $runName = Security::sanitizeInput((string) ($options['run_name'] ?? ((string) $playbook['name'] . ' Campaign Kit')), 'string');
        $runName = mb_substr($runName !== '' ? $runName : ((string) $playbook['name'] . ' Campaign Kit'), 0, 180);

        $landingPageId = (int) ($playbook['landing_page_id'] ?? 0) ?: null;
        $briefId = null;
        $contentIds = [];
        $distributionIds = [];
        $calendarIds = [];
        $queueIds = [];
        $baseDate = strtotime((string) ($options['start_date'] ?? '+7 days')) ?: strtotime('+7 days');

        Database::beginTransaction();
        try {
            if ($scope['landing_page'] && $landingPageId === null && Database::tableExists('marketing_landing_pages')) {
                $landingPageId = $this->createLandingPage([
                    'title' => $runName . ' Landing Page',
                    'slug' => $this->uniqueMarketingLandingSlug($runName),
                    'headline' => (string) ($playbook['campaign_goal'] ?? $runName),
                    'campaign_id' => $campaignId,
                    'audience_segment_id' => $playbook['audience_segment_id'] ?? null,
                    'metadata_json' => [
                        'source' => 'marketing_campaign_playbook_application',
                        'playbook_id' => $playbookId,
                        'manual_first' => true,
                        'external_publish' => false,
                    ],
                    'created_by' => $userId,
                ]);
            }

            if ($scope['brief']) {
                $briefId = $this->createCampaignBriefFromPlaybook($playbookId, $userId, [
                    'title' => $runName . ' Brief',
                    'campaign_id' => $campaignId,
                    'landing_page_id' => $landingPageId,
                    'created_by' => $userId,
                ]);
            }

            $contentPlan = $this->campaignPlaybookContentPlan($playbook);
            if ($scope['content']) {
                foreach ($contentPlan as $index => $item) {
                    $contentIds[] = $this->createContentItem([
                        'title' => (string) ($item['title'] ?? ($runName . ' Content ' . ($index + 1))),
                        'content_type' => (string) ($item['content_type'] ?? 'social_post'),
                        'channel' => (string) ($item['channel'] ?? 'linkedin'),
                        'status' => 'idea',
                        'funnel_stage' => (string) ($item['funnel_stage'] ?? 'awareness'),
                        'objective' => (string) ($item['objective'] ?? $playbook['campaign_goal'] ?? ''),
                        'target_audience' => (string) ($item['target_audience'] ?? $playbook['target_audience'] ?? ''),
                        'campaign_id' => $campaignId,
                        'campaign_brief_id' => $briefId,
                        'landing_page_id' => $landingPageId,
                        'scheduled_at' => date('Y-m-d\TH:i', strtotime('+' . ($index + 3) . ' days', $baseDate)),
                        'draft_body' => "Draft from playbook: {$runName}\n\nObjective: " . (string) ($item['objective'] ?? $playbook['campaign_goal'] ?? ''),
                        'metadata_json' => [
                            'source' => 'marketing_campaign_playbook_application',
                            'playbook_id' => $playbookId,
                            'manual_first' => true,
                            'external_publish' => false,
                        ],
                        'owner_user_id' => $playbook['owner_user_id'] ?? null,
                        'created_by' => $userId,
                    ]);
                }
            }

            if ($scope['distribution'] && $contentIds !== [] && Database::tableExists('marketing_distribution_posts')) {
                $distributionPlan = $this->campaignPlaybookDistributionPlan($playbook, $contentPlan);
                foreach ($contentIds as $index => $contentId) {
                    $distribution = $distributionPlan[$index] ?? $distributionPlan[0] ?? [];
                    $distributionIds[] = $this->createDistributionPost([
                        'content_item_id' => $contentId,
                        'channel' => (string) ($distribution['channel'] ?? ($contentPlan[$index]['channel'] ?? 'linkedin')),
                        'planned_copy' => 'Manual export draft for ' . ($contentPlan[$index]['title'] ?? $runName),
                        'publishing_checklist' => $distribution['checklist'] ?? ['Copy approved', 'Media checked', 'UTM link ready'],
                        'status' => 'draft',
                        'scheduled_at' => date('Y-m-d\TH:i', strtotime('+' . ($index + 5) . ' days', $baseDate)),
                        'exported_bundle_json' => [
                            'source' => 'marketing_campaign_playbook_application',
                            'playbook_id' => $playbookId,
                            'manual_first' => true,
                            'external_publish' => false,
                        ],
                        'created_by' => $userId,
                    ]);
                }
            }

            if ($scope['calendar'] && Database::tableExists('marketing_calendar_milestones')) {
                foreach ((array) ($playbook['stages'] ?? []) as $index => $stage) {
                    $calendarIds[] = $this->createCalendarMilestone([
                        'title' => (string) ($stage['title'] ?? ($runName . ' Milestone')),
                        'milestone_type' => $this->campaignPlaybookMilestoneType((string) ($stage['stage_type'] ?? 'other')),
                        'channel' => 'other',
                        'milestone_date' => date('Y-m-d', strtotime('+' . ($index + 1) . ' days', $baseDate)),
                        'campaign_id' => $campaignId,
                        'campaign_brief_id' => $briefId,
                        'owner_user_id' => $playbook['owner_user_id'] ?? null,
                        'status' => 'planned',
                        'created_by' => $userId,
                    ]);
                }
            }

            if ($scope['planning_queue'] && Database::tableExists('marketing_planning_queue_items')) {
                foreach ((array) ($playbook['stages'] ?? []) as $index => $stage) {
                    $queueIds[] = $this->createPlanningQueueItem([
                        'title' => (string) ($stage['title'] ?? ($runName . ' Action')),
                        'item_type' => $this->campaignPlaybookQueueType((string) ($stage['stage_type'] ?? 'other')),
                        'priority' => $index < 2 ? 'high' : 'medium',
                        'status' => 'planned',
                        'campaign_id' => $campaignId,
                        'campaign_brief_id' => $briefId,
                        'week_start' => date('Y-m-d', strtotime('monday this week', $baseDate)),
                        'due_at' => date('Y-m-d\TH:i', strtotime('+' . ($index + 2) . ' days', $baseDate)),
                        'owner_user_id' => $playbook['owner_user_id'] ?? null,
                        'metadata_json' => [
                            'source' => 'marketing_campaign_playbook_application',
                            'playbook_id' => $playbookId,
                            'stage_type' => (string) ($stage['stage_type'] ?? 'other'),
                            'manual_first' => true,
                            'external_execution' => false,
                        ],
                        'created_by' => $userId,
                    ]);
                }
            }

            $summary = [
                'briefs_created' => $briefId ? 1 : 0,
                'landing_pages_created' => $landingPageId ? 1 : 0,
                'content_items_created' => count($contentIds),
                'distribution_posts_created' => count($distributionIds),
                'calendar_milestones_created' => count($calendarIds),
                'queue_items_created' => count($queueIds),
                'manual_first' => true,
                'external_publish' => false,
                'external_send' => false,
            ];
            Database::execute(
                "INSERT INTO marketing_playbook_application_runs
                 (workspace_id, playbook_id, campaign_id, campaign_brief_id, landing_page_id, uuid, run_name, status,
                  applied_scope_json, created_content_ids_json, created_distribution_ids_json, created_calendar_ids_json,
                  created_queue_item_ids_json, summary_json, metadata_json, created_by)
                 VALUES (?, ?, ?, ?, ?, ?, ?, 'applied', ?, ?, ?, ?, ?, ?, ?, ?)",
                [
                    $workspaceId,
                    $playbookId,
                    $campaignId,
                    $briefId,
                    $landingPageId,
                    $this->generateUuid(),
                    $runName,
                    $this->normalizeJsonValue($scope),
                    $this->normalizeJsonValue($contentIds),
                    $this->normalizeJsonValue($distributionIds),
                    $this->normalizeJsonValue($calendarIds),
                    $this->normalizeJsonValue($queueIds),
                    $this->normalizeJsonValue($summary),
                    $this->normalizeJsonValue([
                        'source' => 'marketing_campaign_playbook_application',
                        'playbook_id' => $playbookId,
                        'manual_first' => true,
                        'external_execution' => false,
                    ]),
                    $userId,
                ]
            );
            $runId = (int) Database::lastInsertId();
            Database::execute(
                'UPDATE marketing_campaign_playbooks SET last_applied_at = NOW() WHERE workspace_id = ? AND id = ?',
                [$workspaceId, $playbookId]
            );
            Database::commit();
        } catch (Throwable $e) {
            Database::rollBack();
            throw $e;
        }

        if ($campaignId !== null && Database::tableExists('marketing_campaign_workspaces')) {
            try {
                $this->refreshMarketingCampaignWorkspace($campaignId, $userId);
            } catch (Throwable) {
                // Campaign workspace refresh is helpful, but playbook application is the source of truth here.
            }
        }

        return $this->listCampaignPlaybookApplicationRuns(['id' => $runId], 1, 0)[0] ?? [
            'id' => $runId,
            'campaign_brief_id' => $briefId,
            'landing_page_id' => $landingPageId,
            'created_content_ids_json' => $contentIds,
