                'created_calendar_ids_json',
                'created_queue_item_ids_json',
                'summary_json',
                'metadata_json',
            ]),
            Database::query(
                "SELECT r.*, p.name AS playbook_name, c.name AS campaign_name, b.title AS campaign_brief_title, lp.title AS landing_page_title,
                        creator.email AS created_by_email
                 FROM marketing_playbook_application_runs r
                 JOIN marketing_campaign_playbooks p ON p.id = r.playbook_id AND p.workspace_id = r.workspace_id
                 LEFT JOIN campaigns c ON c.id = r.campaign_id AND c.workspace_id = r.workspace_id
                 LEFT JOIN marketing_campaign_briefs b ON b.id = r.campaign_brief_id AND b.workspace_id = r.workspace_id
                 LEFT JOIN marketing_landing_pages lp ON lp.id = r.landing_page_id AND lp.workspace_id = r.workspace_id
                 LEFT JOIN users creator ON creator.id = r.created_by
                 WHERE " . implode(' AND ', $where) . "
                 ORDER BY r.created_at DESC, r.id DESC
                 LIMIT {$limit} OFFSET {$offset}",
                $params
            )
        );
    }

