    public function listLaunchReadinessReviews(array $filters = [], int $limit = 100, int $offset = 0): array
    {
        if (!Database::tableExists('marketing_launch_readiness_reviews')) {
            return [];
        }

        $limit = min(max($limit, 1), 250);
        $offset = max($offset, 0);
        $where = ['r.workspace_id = ?'];
        $params = [$this->workspaceId()];

        if (!empty($filters['open'])) {
            $where[] = "r.status IN ('draft','blocked','ready')";
        }
        if (!empty($filters['status'])) {
            $where[] = 'r.status = ?';
            $params[] = $this->normalizeEnum((string) $filters['status'], self::LAUNCH_READINESS_STATUSES, 'launch_readiness_status');
        }
        foreach (['campaign_id', 'campaign_brief_id', 'landing_page_id', 'content_item_id', 'distribution_post_id', 'email_run_id', 'id'] as $field) {
            if (!empty($filters[$field])) {
                $where[] = "r.{$field} = ?";
                $params[] = (int) $filters[$field];
            }
        }
        if (!empty($filters['launch_from'])) {
            $where[] = 'r.launch_date >= ?';
            $params[] = $this->normalizeDate((string) $filters['launch_from'], 'launch from');
        }
        if (!empty($filters['launch_to'])) {
            $where[] = 'r.launch_date <= ?';
            $params[] = $this->normalizeDate((string) $filters['launch_to'], 'launch to');
        }

        return array_map(
            fn(array $row): array => $this->hydrateJsonFields($row, ['blocking_reasons_json', 'warnings_json', 'checklist_json', 'result_json']),
            Database::query(
                "SELECT r.*, c.name AS campaign_name, b.title AS campaign_brief_title,
                        lp.title AS landing_page_title, m.title AS content_title,
                        d.channel AS distribution_channel, e.name AS email_run_name,
                        t.name AS template_name, reviewer.email AS reviewed_by_email,
                        approver.email AS approved_by_email, creator.email AS created_by_email
                 FROM marketing_launch_readiness_reviews r
                 LEFT JOIN campaigns c ON c.id = r.campaign_id AND c.workspace_id = r.workspace_id
                 LEFT JOIN marketing_campaign_briefs b ON b.id = r.campaign_brief_id AND b.workspace_id = r.workspace_id
                 LEFT JOIN marketing_landing_pages lp ON lp.id = r.landing_page_id AND lp.workspace_id = r.workspace_id
                 LEFT JOIN marketing_content_items m ON m.id = r.content_item_id AND m.workspace_id = r.workspace_id
                 LEFT JOIN marketing_distribution_posts d ON d.id = r.distribution_post_id AND d.workspace_id = r.workspace_id
                 LEFT JOIN marketing_email_campaign_runs e ON e.id = r.email_run_id AND e.workspace_id = r.workspace_id
                 LEFT JOIN marketing_launch_readiness_templates t ON t.id = r.template_id AND t.workspace_id = r.workspace_id
                 LEFT JOIN users reviewer ON reviewer.id = r.reviewed_by
                 LEFT JOIN users approver ON approver.id = r.approved_by
                 LEFT JOIN users creator ON creator.id = r.created_by
                 WHERE " . implode(' AND ', $where) . "
                 ORDER BY
                    CASE WHEN r.status = 'blocked' THEN 0 WHEN r.status = 'ready' THEN 1 ELSE 2 END ASC,
                    CASE WHEN r.launch_date IS NULL THEN 1 ELSE 0 END ASC,
                    r.launch_date ASC,
                    r.updated_at DESC
                 LIMIT {$limit} OFFSET {$offset}",
                $params
            )
        );
    }

    public function getLaunchReadinessReview(int $id): ?array
    {
        $rows = $this->listLaunchReadinessReviews(['id' => $id], 1, 0);
        return $rows[0] ?? null;
    }

    public function evaluateLaunchReadiness(array $data, ?int $userId = null): array
    {
        $this->assertMarketingPermission('marketing.write');
        $normalized = $this->normalizeLaunchReadinessReviewData($data, true);
        $result = $this->buildLaunchReadinessResult($normalized);
        $status = $result['blocking_reasons'] === [] ? 'ready' : 'blocked';
        $userId = $userId ?? (int) ($normalized['created_by'] ?? $this->currentUserId());
        if ($userId > 0) {
            $this->assertWorkspaceUser($userId, $this->workspaceId());
        }

        Database::execute(
            "INSERT INTO marketing_launch_readiness_reviews
             (workspace_id, uuid, campaign_id, campaign_brief_id, landing_page_id, content_item_id, distribution_post_id,
              email_run_id, template_id, launch_name, launch_date, status, readiness_score, blocking_reasons_json,
              warnings_json, checklist_json, result_json, reviewed_by, reviewed_at, created_by)
             VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, NOW(), ?)",
            [
                $this->workspaceId(),
                $this->generateUuid(),
                $normalized['campaign_id'],
                $normalized['campaign_brief_id'],
                $normalized['landing_page_id'],
                $normalized['content_item_id'],
                $normalized['distribution_post_id'],
                $normalized['email_run_id'],
                $normalized['template_id'],
                $normalized['launch_name'],
                $normalized['launch_date'],
                $status,
                (int) $result['score'],
                $this->normalizeJsonValue($result['blocking_reasons']),
                $this->normalizeJsonValue($result['warnings']),
                $this->normalizeJsonValue($result['checklist']),
                $this->normalizeJsonValue($result),
                $userId > 0 ? $userId : null,
                (int) ($normalized['created_by'] ?? 0) ?: ($userId > 0 ? $userId : null),
            ]
        );
        $id = (int) Database::lastInsertId();

        if (!empty($normalized['campaign_brief_id']) && Database::columnExists('marketing_campaign_briefs', 'launch_readiness_score')) {
            Database::execute(
                'UPDATE marketing_campaign_briefs SET launch_readiness_score = ?, launch_blocked_reason = ?, launch_readiness_json = ? WHERE workspace_id = ? AND id = ?',
                [
                    (int) $result['score'],
                    $result['blocking_reasons'] !== [] ? implode(', ', $result['blocking_reasons']) : null,
                    $this->normalizeJsonValue($result),
                    $this->workspaceId(),
                    (int) $normalized['campaign_brief_id'],
                ]
            );
        }

        $this->recordMarketingAuditEvent(
            'launch_readiness_evaluated',
            'marketing_launch_readiness_reviews',
            $id,
            $status === 'ready' ? 'Launch readiness review passed.' : 'Launch readiness review found blockers.',
            ['score' => (int) $result['score'], 'status' => $status, 'manual_first' => true, 'external_execution' => false],
            $userId > 0 ? $userId : null
        );

        return $this->getLaunchReadinessReview($id) ?? ['id' => $id] + $result;
    }

    public function approveLaunchReadiness(int $reviewId, int $userId): bool
    {
        $this->assertMarketingPermission('marketing.manage');
        $review = $this->getLaunchReadinessReview($reviewId);
        if (!$review) {
            throw new RuntimeException('Marketing launch readiness review not found.');
        }
        if ((string) ($review['status'] ?? '') === 'blocked') {
            throw new RuntimeException('Blocked launches cannot be approved until readiness blockers are resolved.');
        }
        if ($userId > 0) {
            $this->assertWorkspaceUser($userId, $this->workspaceId());
        }

        Database::execute(
            "UPDATE marketing_launch_readiness_reviews
             SET status = 'approved', approved_by = ?, approved_at = NOW()
             WHERE workspace_id = ? AND id = ?",
            [$userId > 0 ? $userId : null, $this->workspaceId(), $reviewId]
        );
        $this->recordMarketingAuditEvent(
            'launch_readiness_approved',
            'marketing_launch_readiness_reviews',
            $reviewId,
            'Launch readiness review approved for manual execution.',
            ['manual_first' => true, 'external_execution' => false],
            $userId > 0 ? $userId : null
        );

        return true;
    }

    public function archiveLaunchReadinessReview(int $reviewId): bool
    {
        $this->assertMarketingPermission('marketing.manage');
        $this->assertWorkspaceRecord('marketing_launch_readiness_reviews', $reviewId, $this->workspaceId());
        Database::execute(
            "UPDATE marketing_launch_readiness_reviews SET status = 'archived' WHERE workspace_id = ? AND id = ?",
            [$this->workspaceId(), $reviewId]
        );

        return true;
    }

    public function listLaunchControlRecords(array $filters = [], int $limit = 100, int $offset = 0): array
    {
        if (!Database::tableExists('marketing_launch_control_records')) {
            return [];
        }

        $limit = min(max($limit, 1), 250);
        $offset = max($offset, 0);
        $workspace = $this->workspaceClause('lc.');
        $where = [$workspace['sql']];
        $params = $workspace['params'];

        if (!empty($filters['open'])) {
            $where[] = "lc.status IN ('planning','blocked','ready','paused')";
        }
        if (!empty($filters['status'])) {
            $where[] = 'lc.status = ?';
            $params[] = $this->normalizeEnum((string) $filters['status'], self::LAUNCH_CONTROL_STATUSES, 'launch_control_status');
        }
        foreach ([
            'id',
            'launch_readiness_review_id',
            'campaign_id',
            'campaign_brief_id',
            'landing_page_id',
            'content_item_id',
            'distribution_post_id',
            'email_run_id',
            'audience_activation_id',
            'owner_user_id',
        ] as $field) {
            if (!empty($filters[$field])) {
                $where[] = "lc.{$field} = ?";
                $params[] = (int) $filters[$field];
            }
        }

        return array_map(
            fn(array $row): array => $this->hydrateLaunchControlRow($row),
            Database::query(
                "SELECT lc.*, r.status AS launch_readiness_status, r.readiness_score AS launch_readiness_score,
                        c.name AS campaign_name, b.title AS campaign_brief_title, lp.title AS landing_page_title,
                        m.title AS content_title, d.channel AS distribution_channel, er.name AS email_run_name,
                        aa.activation_name AS audience_activation_name, aa.coverage_status AS audience_activation_coverage,
                        owner.email AS owner_email, preparer.email AS prepared_by_email,
                        launcher.email AS launched_by_email, creator.email AS created_by_email
                 FROM marketing_launch_control_records lc
                 LEFT JOIN marketing_launch_readiness_reviews r ON r.id = lc.launch_readiness_review_id AND r.workspace_id = lc.workspace_id
                 LEFT JOIN campaigns c ON c.id = lc.campaign_id AND c.workspace_id = lc.workspace_id
                 LEFT JOIN marketing_campaign_briefs b ON b.id = lc.campaign_brief_id AND b.workspace_id = lc.workspace_id
                 LEFT JOIN marketing_landing_pages lp ON lp.id = lc.landing_page_id AND lp.workspace_id = lc.workspace_id
                 LEFT JOIN marketing_content_items m ON m.id = lc.content_item_id AND m.workspace_id = lc.workspace_id
                 LEFT JOIN marketing_distribution_posts d ON d.id = lc.distribution_post_id AND d.workspace_id = lc.workspace_id
                 LEFT JOIN marketing_email_campaign_runs er ON er.id = lc.email_run_id AND er.workspace_id = lc.workspace_id
                 LEFT JOIN marketing_audience_activations aa ON aa.id = lc.audience_activation_id AND aa.workspace_id = lc.workspace_id
                 LEFT JOIN users owner ON owner.id = lc.owner_user_id
                 LEFT JOIN users preparer ON preparer.id = lc.prepared_by
                 LEFT JOIN users launcher ON launcher.id = lc.launched_by
                 LEFT JOIN users creator ON creator.id = lc.created_by
                 WHERE " . implode(' AND ', $where) . "
                 ORDER BY
                    CASE lc.status WHEN 'blocked' THEN 0 WHEN 'ready' THEN 1 WHEN 'planning' THEN 2 WHEN 'paused' THEN 3 ELSE 4 END ASC,
                    CASE WHEN lc.launch_date IS NULL THEN 1 ELSE 0 END ASC,
                    lc.launch_date ASC,
                    lc.updated_at DESC
                 LIMIT {$limit} OFFSET {$offset}",
                $params
            )
        );
    }

    public function getLaunchControlRecord(int $id): ?array
    {
        $rows = $this->listLaunchControlRecords(['id' => $id], 1, 0);

        return $rows[0] ?? null;
    }

    public function prepareLaunchControl(array $data, ?int $userId = null): array
    {
        $this->assertMarketingPermission('marketing.write');
        if (!Database::tableExists('marketing_launch_control_records')) {
            throw new RuntimeException('Marketing launch control room is unavailable.');
        }

        $normalized = $this->normalizeLaunchControlData($data, true);
        $result = $this->buildLaunchControlResult($normalized);
        if (empty($normalized['audience_activation_id']) && !empty($result['linked_records']['audience_activation_id'])) {
            $normalized['audience_activation_id'] = (int) $result['linked_records']['audience_activation_id'];
        }
        $status = $result['blockers'] === [] ? 'ready' : 'blocked';
        $userId = $userId ?? (int) ($normalized['created_by'] ?? $this->currentUserId());
        if ($userId > 0) {
            $this->assertWorkspaceUser($userId, $this->workspaceId());
        }

        Database::execute(
            "INSERT INTO marketing_launch_control_records
             (workspace_id, uuid, launch_readiness_review_id, campaign_id, campaign_brief_id, landing_page_id,
              content_item_id, distribution_post_id, email_run_id, audience_activation_id, launch_name, launch_date,
              status, readiness_score, checklist_json, blocker_json, warning_json, manual_launch_log_json,
              metadata_json, owner_user_id, prepared_by, prepared_at, created_by)
             VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, NOW(), ?)",
            [
                $this->workspaceId(),
                $this->generateUuid(),
                $normalized['launch_readiness_review_id'],
                $normalized['campaign_id'],
                $normalized['campaign_brief_id'],
                $normalized['landing_page_id'],
                $normalized['content_item_id'],
                $normalized['distribution_post_id'],
                $normalized['email_run_id'],
                $normalized['audience_activation_id'],
                $normalized['launch_name'],
                $normalized['launch_date'],
                $status,
                (int) $result['score'],
                $this->normalizeJsonValue($result['checklist']),
                $this->normalizeJsonValue($result['blockers']),
                $this->normalizeJsonValue($result['warnings']),
                $this->normalizeJsonValue([]),
                $normalized['metadata_json'],
                $normalized['owner_user_id'],
                $userId > 0 ? $userId : null,
                (int) ($normalized['created_by'] ?? 0) ?: ($userId > 0 ? $userId : null),
            ]
        );
        $id = (int) Database::lastInsertId();
        $this->syncLaunchControlBriefStatus((int) ($normalized['campaign_brief_id'] ?? 0), $status, $result);
        $this->recordMarketingAuditEvent(
            'launch_control_prepared',
            'marketing_launch_control_records',
            $id,
            $status === 'ready' ? 'Launch control record is ready for manual launch approval.' : 'Launch control record has blockers.',
            ['score' => (int) $result['score'], 'status' => $status, 'manual_first' => true],
            $userId > 0 ? $userId : null
        );

        return $this->getLaunchControlRecord($id) ?? ['id' => $id] + $result;
    }

    public function markLaunchControlManuallyLaunched(int $id, int $userId, string $note = ''): bool
    {
        $this->assertMarketingPermission('marketing.manage');
        $record = $this->getLaunchControlRecord($id);
        if (!$record) {
            throw new RuntimeException('Marketing launch control record not found.');
        }
        if ((string) ($record['status'] ?? '') !== 'ready') {
            throw new RuntimeException('Only ready launch control records can be marked manually launched.');
        }
        if ($userId > 0) {
            $this->assertWorkspaceUser($userId, $this->workspaceId());
        }

        $log = (array) ($record['manual_launch_log_json'] ?? []);
        $log[] = [
            'action' => 'launched_manual',
            'note' => Security::sanitizeInput($note, 'string'),
            'user_id' => $userId > 0 ? $userId : null,
            'at' => date('c'),
            'external_publish' => false,
            'external_send' => false,
        ];
        Database::execute(
            "UPDATE marketing_launch_control_records
             SET status = 'launched_manual',
                 launched_by = ?,
                 launched_at = NOW(),
                 manual_launch_log_json = ?
             WHERE workspace_id = ? AND id = ?",
            [$userId > 0 ? $userId : null, $this->normalizeJsonValue($log), $this->workspaceId(), $id]
        );
        $this->syncLaunchControlBriefStatus((int) ($record['campaign_brief_id'] ?? 0), 'launched_manual', ['manual_launch_log' => $log]);
        $this->recordMarketingAuditEvent(
            'launch_control_manual_launch',
            'marketing_launch_control_records',
            $id,
            'Manual launch was recorded. No external publish or send was performed.',
            ['external_publish' => false, 'external_send' => false],
            $userId > 0 ? $userId : null
        );

        return true;
    }

    public function updateLaunchControlStatus(int $id, string $status): bool
    {
        $this->assertMarketingPermission('marketing.write');
        $status = $this->normalizeEnum($status, self::LAUNCH_CONTROL_STATUSES, 'launch_control_status');
        if (in_array($status, ['launched_manual', 'archived'], true)) {
            $this->assertMarketingPermission('marketing.manage');
        }
        $record = $this->getLaunchControlRecord($id);
        if (!$record) {
            throw new RuntimeException('Marketing launch control record not found.');
        }
        Database::execute(
            'UPDATE marketing_launch_control_records SET status = ? WHERE workspace_id = ? AND id = ?',
            [$status, $this->workspaceId(), $id]
        );
        $this->syncLaunchControlBriefStatus((int) ($record['campaign_brief_id'] ?? 0), $status, ['status' => $status]);

        return true;
    }

    public function archiveLaunchControlRecord(int $id): bool
    {
        $this->assertMarketingPermission('marketing.manage');
        $record = $this->getLaunchControlRecord($id);
        if (!$record) {
            throw new RuntimeException('Marketing launch control record not found.');
        }
        Database::execute(
            "UPDATE marketing_launch_control_records SET status = 'archived' WHERE workspace_id = ? AND id = ?",
            [$this->workspaceId(), $id]
        );
        $this->syncLaunchControlBriefStatus((int) ($record['campaign_brief_id'] ?? 0), 'archived', ['status' => 'archived']);

        return true;
    }

    public function getLaunchControlSummary(): array
    {
        if (!Database::tableExists('marketing_launch_control_records')) {
            return [
                'counts' => ['open' => 0, 'blocked' => 0, 'ready' => 0, 'launched_manual' => 0],
                'open' => [],
            ];
        }

        return [
            'counts' => [
                'open' => $this->countRows('marketing_launch_control_records', "status IN ('planning','blocked','ready','paused')"),
                'blocked' => $this->countRows('marketing_launch_control_records', "status = 'blocked'"),
                'ready' => $this->countRows('marketing_launch_control_records', "status = 'ready'"),
                'launched_manual' => $this->countRows('marketing_launch_control_records', "status = 'launched_manual'"),
            ],
            'open' => $this->listLaunchControlRecords(['open' => true], 6, 0),
        ];
    }

    public function listCampaignLaunchChecklists(array $filters = [], int $limit = 100, int $offset = 0): array
    {
        if (!Database::tableExists('marketing_campaign_launch_checklists')) {
            return [];
        }

        $limit = min(max($limit, 1), 250);
        $offset = max($offset, 0);
        $workspace = $this->workspaceClause('cl.');
        $where = [$workspace['sql']];
        $params = $workspace['params'];

        if (!empty($filters['status'])) {
            $where[] = 'cl.status = ?';
            $params[] = $this->normalizeEnum((string) $filters['status'], self::CAMPAIGN_LAUNCH_CHECKLIST_STATUSES, 'campaign_launch_checklist_status');
        }
        if (!empty($filters['open'])) {
            $where[] = "cl.status IN ('draft','ready','blocked')";
        }
        foreach (['id', 'campaign_id', 'campaign_brief_id', 'landing_page_id', 'content_item_id', 'distribution_post_id', 'email_run_id', 'channel_export_bundle_id', 'connector_id', 'owner_user_id'] as $field) {
            if (!empty($filters[$field])) {
                $where[] = "cl.{$field} = ?";
                $params[] = (int) $filters[$field];
            }
        }

        return array_map(
            fn(array $row): array => $this->hydrateJsonFields($row, ['required_checks_json', 'missing_items_json', 'warning_json', 'next_actions_json', 'metadata_json']),
            Database::query(
                "SELECT cl.*, c.name AS campaign_name, b.title AS campaign_brief_title,
                        seg.name AS audience_segment_name, lp.title AS landing_page_title,
                        m.title AS content_title, d.channel AS distribution_channel,
                        er.name AS email_run_name, ceb.channel AS channel_export_channel,
                        cc.name AS connector_name, owner.email AS owner_email, creator.email AS created_by_email
                 FROM marketing_campaign_launch_checklists cl
                 LEFT JOIN campaigns c ON c.id = cl.campaign_id AND c.workspace_id = cl.workspace_id
                 LEFT JOIN marketing_campaign_briefs b ON b.id = cl.campaign_brief_id AND b.workspace_id = cl.workspace_id
                 LEFT JOIN marketing_audience_segments seg ON seg.id = cl.audience_segment_id AND seg.workspace_id = cl.workspace_id
                 LEFT JOIN marketing_landing_pages lp ON lp.id = cl.landing_page_id AND lp.workspace_id = cl.workspace_id
                 LEFT JOIN marketing_content_items m ON m.id = cl.content_item_id AND m.workspace_id = cl.workspace_id
                 LEFT JOIN marketing_distribution_posts d ON d.id = cl.distribution_post_id AND d.workspace_id = cl.workspace_id
                 LEFT JOIN marketing_email_campaign_runs er ON er.id = cl.email_run_id AND er.workspace_id = cl.workspace_id
                 LEFT JOIN marketing_channel_export_bundles ceb ON ceb.id = cl.channel_export_bundle_id AND ceb.workspace_id = cl.workspace_id
                 LEFT JOIN marketing_channel_connectors cc ON cc.id = cl.connector_id AND cc.workspace_id = cl.workspace_id
                 LEFT JOIN users owner ON owner.id = cl.owner_user_id
                 LEFT JOIN users creator ON creator.id = cl.created_by
                 WHERE " . implode(' AND ', $where) . "
                 ORDER BY
                    CASE cl.status WHEN 'blocked' THEN 0 WHEN 'ready' THEN 1 WHEN 'draft' THEN 2 ELSE 3 END ASC,
                    CASE WHEN cl.launch_date IS NULL THEN 1 ELSE 0 END ASC,
                    cl.launch_date ASC,
                    cl.updated_at DESC
                 LIMIT {$limit} OFFSET {$offset}",
                $params
            )
        );
    }

    public function getCampaignLaunchChecklist(int $id): ?array
    {
        $rows = $this->listCampaignLaunchChecklists(['id' => $id], 1, 0);
        return $rows[0] ?? null;
    }

    public function listCampaignLaunchChecklistItems(int $checklistId): array
    {
        if (!Database::tableExists('marketing_campaign_launch_checklist_items')) {
            return [];
        }
        $this->assertWorkspaceRecord('marketing_campaign_launch_checklists', $checklistId, $this->workspaceId());

        return array_map(
            fn(array $row): array => $this->hydrateJsonFields($row, ['metadata_json']),
            Database::query(
                "SELECT *
                 FROM marketing_campaign_launch_checklist_items
                 WHERE workspace_id = ? AND checklist_id = ?
                 ORDER BY is_required DESC, FIELD(status, 'blocked', 'pending', 'warning', 'complete', 'waived'), id ASC",
                [$this->workspaceId(), $checklistId]
            )
        );
    }

    public function createCampaignLaunchChecklist(array $data, ?int $userId = null): int
    {
        $this->assertMarketingPermission('marketing.write');
        if (!Database::tableExists('marketing_campaign_launch_checklists')) {
            throw new RuntimeException('Marketing campaign launch checklists are unavailable.');
        }

        $normalized = $this->normalizeCampaignLaunchChecklistData($data, true);
        $result = $this->buildCampaignLaunchChecklistResult($normalized);
        $status = $result['missing_required'] === [] ? 'ready' : 'blocked';
        Database::execute(
            "INSERT INTO marketing_campaign_launch_checklists
             (workspace_id, uuid, title, status, readiness_score, campaign_id, campaign_brief_id, audience_segment_id,
              landing_page_id, content_item_id, distribution_post_id, email_run_id, channel_export_bundle_id,
              connector_id, launch_date, required_checks_json, missing_items_json, warning_json, next_actions_json,
              metadata_json, owner_user_id, created_by)
             VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)",
            [
                $this->workspaceId(),
                $this->generateUuid(),
                $normalized['title'],
                $status,
                (int) $result['score'],
                $normalized['campaign_id'],
                $normalized['campaign_brief_id'],
                $normalized['audience_segment_id'],
                $normalized['landing_page_id'],
                $normalized['content_item_id'],
                $normalized['distribution_post_id'],
                $normalized['email_run_id'],
                $normalized['channel_export_bundle_id'],
                $normalized['connector_id'],
                $normalized['launch_date'],
                $this->normalizeJsonValue($result['checks']),
                $this->normalizeJsonValue($result['missing_required']),
                $this->normalizeJsonValue($result['warnings']),
                $this->normalizeJsonValue($result['next_actions']),
                $this->normalizeJsonValue(['manual_first' => true, 'external_execution' => false]),
                $normalized['owner_user_id'],
                $normalized['created_by'],
            ]
        );
        $id = (int) Database::lastInsertId();
        $this->saveCampaignLaunchChecklistItems($id, $result['checks'], $userId ?? $this->currentUserId());

        return $id;
    }

    public function refreshCampaignLaunchChecklist(int $id, ?int $userId = null): array
    {
        $this->assertMarketingPermission('marketing.write');
        $checklist = $this->getCampaignLaunchChecklist($id);
        if (!$checklist) {
            throw new RuntimeException('Marketing campaign launch checklist not found.');
        }

        $result = $this->buildCampaignLaunchChecklistResult($checklist);
        $status = (string) ($checklist['status'] ?? 'draft') === 'archived'
            ? 'archived'
            : ($result['missing_required'] === [] ? 'ready' : 'blocked');
        Database::execute(
            "UPDATE marketing_campaign_launch_checklists
             SET status = ?, readiness_score = ?, required_checks_json = ?, missing_items_json = ?,
                 warning_json = ?, next_actions_json = ?, updated_at = NOW()
             WHERE workspace_id = ? AND id = ?",
            [
                $status,
                (int) $result['score'],
                $this->normalizeJsonValue($result['checks']),
                $this->normalizeJsonValue($result['missing_required']),
                $this->normalizeJsonValue($result['warnings']),
                $this->normalizeJsonValue($result['next_actions']),
                $this->workspaceId(),
                $id,
            ]
        );
        $this->saveCampaignLaunchChecklistItems($id, $result['checks'], $userId ?? $this->currentUserId());

        return $this->getCampaignLaunchChecklist($id) ?? [];
    }

