    public function listGuidedMarketingWorkflows(array $filters = [], bool $persist = false, ?int $userId = null): array
    {
        $this->assertMarketingPermission('marketing.read');
        if ($persist) {
            $this->assertMarketingPermission('marketing.write');
        }

        $workflows = [];
        foreach ($this->getGuidedMarketingWorkflowDefinitions() as $workflowKey => $definition) {
            $computed = $this->buildGuidedMarketingWorkflowState($workflowKey, $definition);
            $saved = $this->getGuidedMarketingWorkflowRow($workflowKey);
            if ($saved !== null && in_array((string) ($saved['status'] ?? ''), ['in_progress', 'completed', 'dismissed', 'archived'], true)) {
                $computed['status'] = (string) $saved['status'];
                $computed['completed_at'] = $saved['completed_at'] ?? null;
                $computed['dismissed_at'] = $saved['dismissed_at'] ?? null;
            }
            if ($persist && Database::tableExists('marketing_guided_workflows')) {
                $computed = $this->upsertGuidedMarketingWorkflow($computed, $userId);
            } elseif ($saved !== null) {
                $computed = $computed + $saved;
                $computed['step_state_json'] = $computed['steps'];
                $computed['recommendation_json'] = $computed['recommendation'];
                $computed['missing_requirements_json'] = $computed['missing_requirements'];
                $computed['quick_links_json'] = $computed['quick_links'];
            }

            if (!empty($filters['status']) && (string) $computed['status'] !== (string) $filters['status']) {
                continue;
            }
            if (!empty($filters['workflow_key']) && (string) $computed['workflow_key'] !== (string) $filters['workflow_key']) {
                continue;
            }
            if (empty($filters['include_archived']) && (string) $computed['status'] === 'archived') {
                continue;
            }

            $workflows[] = $computed;
        }

        usort($workflows, static function (array $left, array $right): int {
            $order = ['blocked' => 0, 'in_progress' => 1, 'not_started' => 2, 'ready' => 3, 'completed' => 4, 'dismissed' => 5, 'archived' => 6];
            return (($order[(string) ($left['status'] ?? '')] ?? 9) <=> ($order[(string) ($right['status'] ?? '')] ?? 9))
                ?: ((int) ($right['progress_score'] ?? 0) <=> (int) ($left['progress_score'] ?? 0));
        });

        return $workflows;
    }

    public function refreshGuidedMarketingWorkflows(?int $userId = null): array
    {
        return $this->listGuidedMarketingWorkflows([], true, $userId);
    }

    public function getGuidedMarketingWorkflow(string $workflowKey): ?array
    {
        $workflowKey = $this->normalizeEnum($workflowKey, self::GUIDED_WORKFLOW_KEYS, 'guided_workflow_key');
        $rows = $this->listGuidedMarketingWorkflows(['workflow_key' => $workflowKey, 'include_archived' => true], false);

        return $rows[0] ?? null;
    }

    public function updateGuidedMarketingWorkflowState(string $workflowKey, array $data, ?int $userId = null): array
    {
        $this->assertMarketingPermission('marketing.write');
        if (!Database::tableExists('marketing_guided_workflows')) {
            throw new RuntimeException('Marketing guided workflows are unavailable.');
        }

        $workflowKey = $this->normalizeEnum($workflowKey, self::GUIDED_WORKFLOW_KEYS, 'guided_workflow_key');
        $status = $this->normalizeEnum((string) ($data['status'] ?? 'in_progress'), self::GUIDED_WORKFLOW_STATUSES, 'guided_workflow_status');
        if ($status === 'archived') {
            $this->assertMarketingPermission('marketing.manage');
        }
        $userId = $userId ?? $this->currentUserId();
        if (($userId ?? 0) > 0) {
            $this->assertWorkspaceUser((int) $userId, $this->workspaceId());
        }

        $workflow = $this->upsertGuidedMarketingWorkflow(
            $this->buildGuidedMarketingWorkflowState($workflowKey, $this->getGuidedMarketingWorkflowDefinitions()[$workflowKey]),
            $userId
        );
        $fields = ['status = ?'];
        $params = [$status];
        if ($status === 'completed') {
            $fields[] = 'completed_by = ?';
            $fields[] = 'completed_at = NOW()';
            $params[] = ($userId ?? 0) > 0 ? (int) $userId : null;
        }
        if ($status === 'dismissed') {
            $fields[] = 'dismissed_by = ?';
            $fields[] = 'dismissed_at = NOW()';
            $params[] = ($userId ?? 0) > 0 ? (int) $userId : null;
        }
        $params[] = $this->workspaceId();
        $params[] = (int) $workflow['id'];
        Database::execute(
            'UPDATE marketing_guided_workflows SET ' . implode(', ', $fields) . ' WHERE workspace_id = ? AND id = ?',
            $params
        );
        $this->recordGuidedWorkflowEvent((int) $workflow['id'], $status, (string) ($data['note'] ?? ''), $userId);

        return $this->getGuidedMarketingWorkflow($workflowKey) ?? $workflow;
    }

    public function getGuidedMarketingWorkflowSummary(): array
    {
        $workflows = $this->listGuidedMarketingWorkflows([], false);
        $counts = array_fill_keys(self::GUIDED_WORKFLOW_STATUSES, 0);
        foreach ($workflows as $workflow) {
            $status = (string) ($workflow['status'] ?? 'not_started');
            $counts[$status] = (int) ($counts[$status] ?? 0) + 1;
        }

        return [
            'counts' => $counts,
            'workflows' => $workflows,
            'next_actions' => array_values(array_filter(array_map(
                static fn(array $workflow): array => [
                    'workflow_key' => $workflow['workflow_key'],
                    'label' => (string) ($workflow['recommendation']['label'] ?? $workflow['title']),
                    'href' => (string) ($workflow['recommendation']['href'] ?? $workflow['primary_href'] ?? 'marketing_guided_workflows.php'),
                    'status' => (string) ($workflow['status'] ?? 'not_started'),
                ],
                $workflows
            ), static fn(array $action): bool => !in_array($action['status'], ['completed', 'dismissed', 'archived'], true))),
        ];
    }

    public function getMarketingWorkflowWizardCatalog(?int $userId = null): array
    {
        $this->assertMarketingPermission('marketing.read');
        $userId = $userId ?? ($this->currentUserId() ?: null);
        $workflows = $this->listGuidedMarketingWorkflows([], false);
        $wizardMeta = [
            'campaign_launch' => ['label' => 'Launch A Campaign', 'wizard_type' => 'campaign_launch', 'best_for' => 'Moving from campaign strategy to launch control.', 'primary_action' => 'Start Launch Wizard'],
            'content_production' => ['label' => 'Create Content From Brief', 'wizard_type' => 'content_from_brief', 'best_for' => 'Turning a brief into content, media, calendar, and review work.', 'primary_action' => 'Start Content Wizard'],
            'landing_conversion' => ['label' => 'Create Landing Page', 'wizard_type' => 'landing_page', 'best_for' => 'Preparing landing copy, form, media, conversion goal, and preview readiness.', 'primary_action' => 'Start Landing Wizard'],
            'distribution_export' => ['label' => 'Prepare Channel Export', 'wizard_type' => 'channel_export', 'best_for' => 'Packaging manual social, SMS, WhatsApp, ad, or website exports.', 'primary_action' => 'Start Export Wizard'],
            'email_export' => ['label' => 'Prepare Email Export', 'wizard_type' => 'email_export', 'best_for' => 'Preparing a manual email run with audience, review, unsubscribe, checklist, and CSV/export bundle.', 'primary_action' => 'Start Email Wizard'],
            'review_approval' => ['label' => 'Review And Approve Content', 'wizard_type' => 'review_approval', 'best_for' => 'Moving content through review, comments, quality checks, media readiness, and approval.', 'primary_action' => 'Start Review Wizard'],
            'performance_review' => ['label' => 'Review Performance', 'wizard_type' => 'performance_review', 'best_for' => 'Closing the loop with tracking, attribution, reports, ROI, and handoff feedback.', 'primary_action' => 'Start Performance Wizard'],
        ];

        $wizards = [];
        foreach ($workflows as $workflow) {
            $key = (string) ($workflow['workflow_key'] ?? '');
            $meta = $wizardMeta[$key] ?? [
                'label' => (string) ($workflow['title'] ?? $key),
                'wizard_type' => $key,
                'best_for' => (string) ($workflow['description'] ?? 'Guided Marketing workflow.'),
                'primary_action' => 'Start Wizard',
            ];
            $steps = (array) ($workflow['steps'] ?? []);
            $missingRequired = (array) ($workflow['missing_requirements'] ?? []);
            $readySteps = count(array_filter($steps, static fn(array $step): bool => (string) ($step['status'] ?? '') === 'ready'));
            $status = (string) ($workflow['status'] ?? 'not_started');
            $wizards[] = [
                'workflow_key' => $key,
                'wizard_type' => (string) $meta['wizard_type'],
                'label' => (string) $meta['label'],
                'title' => (string) ($workflow['title'] ?? $meta['label']),
                'description' => (string) ($workflow['description'] ?? ''),
                'best_for' => (string) $meta['best_for'],
                'primary_action' => (string) $meta['primary_action'],
                'href' => 'marketing_guided_workflows.php?workflow_key=' . urlencode($key),
                'primary_href' => (string) ($workflow['primary_href'] ?? 'marketing_guided_workflows.php'),
                'status' => $status,
                'progress_score' => (int) ($workflow['progress_score'] ?? 0),
                'ready_steps' => $readySteps,
                'total_steps' => count($steps),
                'missing_required' => $missingRequired,
                'next_step' => (array) ($workflow['recommendation'] ?? []),
                'can_start' => !in_array($status, ['completed', 'dismissed', 'archived'], true),
                'manual_first_boundary' => [
                    'external_publish' => false,
                    'external_send' => false,
                    'external_api_call' => false,
                    'operator_decision_required' => true,
                ],
            ];
        }

        usort($wizards, static function (array $left, array $right): int {
            $order = ['blocked' => 0, 'not_started' => 1, 'in_progress' => 2, 'ready' => 3, 'completed' => 4, 'dismissed' => 5, 'archived' => 6];
            return (($order[(string) ($left['status'] ?? '')] ?? 9) <=> ($order[(string) ($right['status'] ?? '')] ?? 9))
                ?: ((int) ($right['progress_score'] ?? 0) <=> (int) ($left['progress_score'] ?? 0));
        });

        return [
            'wizards' => $wizards,
            'counts' => [
                'total' => count($wizards),
                'blocked' => count(array_filter($wizards, static fn(array $wizard): bool => (string) ($wizard['status'] ?? '') === 'blocked')),
                'in_progress' => count(array_filter($wizards, static fn(array $wizard): bool => (string) ($wizard['status'] ?? '') === 'in_progress')),
                'ready' => count(array_filter($wizards, static fn(array $wizard): bool => (string) ($wizard['status'] ?? '') === 'ready')),
            ],
            'recommended_product_decision' => 'Use workflow wizards as guided operating rails: they validate readiness and point to manual actions, but they never send, publish, or overwrite work automatically.',
            'manual_first_boundary' => [
                'external_publish' => false,
                'external_send' => false,
                'external_api_call' => false,
                'operator_decision_required' => true,
            ],
            'user_id' => $userId,
            'generated_at' => date('c'),
        ];
    }

    public function startMarketingWorkflowWizard(string $workflowKey, ?int $userId = null): array
    {
        $this->assertMarketingPermission('marketing.write');
        $workflowKey = $this->normalizeEnum($workflowKey, self::GUIDED_WORKFLOW_KEYS, 'guided_workflow_key');
        $workflow = $this->updateGuidedMarketingWorkflowState($workflowKey, [
            'status' => 'in_progress',
            'note' => 'Workflow wizard started by operator.',
        ], $userId ?? $this->currentUserId());

        return $workflow + [
            'wizard_started' => true,
            'manual_first_boundary' => [
                'external_publish' => false,
                'external_send' => false,
                'external_api_call' => false,
                'operator_decision_required' => true,
            ],
        ];
    }

    public function listCalendarMilestones(array $filters = [], int $limit = 100, int $offset = 0): array
    {
        $limit = min(max($limit, 1), 250);
        $offset = max($offset, 0);
        $workspace = $this->workspaceClause('cm.');
        $where = [$workspace['sql']];
        $params = $workspace['params'];

        foreach (['status' => self::MILESTONE_STATUSES, 'milestone_type' => self::MILESTONE_TYPES] as $field => $allowed) {
            if (!empty($filters[$field])) {
                $where[] = "cm.{$field} = ?";
                $params[] = $this->normalizeEnum((string) $filters[$field], $allowed, $field);
            }
        }
        if (!empty($filters['channel'])) {
            $where[] = 'cm.channel = ?';
            $params[] = $this->normalizeEnum((string) $filters['channel'], self::CHANNELS, 'calendar_channel');
        }
        if (!empty($filters['conflict_status'])) {
            $where[] = 'cm.conflict_status = ?';
            $params[] = $this->normalizeEnum((string) $filters['conflict_status'], self::CALENDAR_CONFLICT_STATUSES, 'calendar_conflict_status');
        }
        if (!empty($filters['date_from'])) {
            $where[] = 'cm.milestone_date >= ?';
            $params[] = $this->normalizeDate((string) $filters['date_from'], 'milestone date');
        }
        if (!empty($filters['date_to'])) {
            $where[] = 'cm.milestone_date <= ?';
            $params[] = $this->normalizeDate((string) $filters['date_to'], 'milestone date');
        }
        if (!empty($filters['content_item_id'])) {
            $where[] = 'cm.content_item_id = ?';
            $params[] = (int) $filters['content_item_id'];
        }
        if (!empty($filters['campaign_id'])) {
            $where[] = 'cm.campaign_id = ?';
            $params[] = (int) $filters['campaign_id'];
        }
        if (!empty($filters['campaign_brief_id'])) {
            $where[] = 'cm.campaign_brief_id = ?';
            $params[] = (int) $filters['campaign_brief_id'];
        }
        if (!empty($filters['owner_user_id'])) {
            $where[] = 'cm.owner_user_id = ?';
            $params[] = (int) $filters['owner_user_id'];
        }

        return Database::query(
            "SELECT cm.*, c.name AS campaign_name, m.title AS content_title, b.title AS campaign_brief_title,
                    owner.email AS owner_email
             FROM marketing_calendar_milestones cm
             LEFT JOIN campaigns c ON c.id = cm.campaign_id AND c.workspace_id = cm.workspace_id
             LEFT JOIN marketing_content_items m ON m.id = cm.content_item_id AND m.workspace_id = cm.workspace_id
             LEFT JOIN marketing_campaign_briefs b ON b.id = cm.campaign_brief_id AND b.workspace_id = cm.workspace_id
             LEFT JOIN users owner ON owner.id = cm.owner_user_id
             WHERE " . implode(' AND ', $where) . "
             ORDER BY cm.milestone_date ASC, cm.updated_at DESC
             LIMIT {$limit} OFFSET {$offset}",
            $params
        );
    }

