    public function getEditorialCalendar(array $filters = []): array
    {
        $filters['date_from'] = $filters['date_from'] ?? date('Y-m-01');
        $filters['date_to'] = $filters['date_to'] ?? date('Y-m-t');
        $milestones = $this->listCalendarMilestones($filters, 250, 0);
        $byDate = [];
        $workload = [];
        foreach ($milestones as $milestone) {
            $date = (string) ($milestone['milestone_date'] ?? '');
            if ($date === '') {
                continue;
            }
            $byDate[$date][] = $milestone;
            $workload[$date] = ($workload[$date] ?? 0) + max(1, (int) ($milestone['capacity_weight'] ?? 1));
        }

        return [
            'filters' => $filters,
            'milestones' => $milestones,
            'by_date' => $byDate,
            'workload_by_date' => $workload,
            'conflicts' => $this->detectCalendarConflicts($filters),
            'templates' => $this->listCalendarTemplates([], 50, 0),
            'production_due' => $this->listContentItems([
                'production_due_from' => (string) $filters['date_from'],
                'production_due_to' => (string) $filters['date_to'],
            ], 25, 0),
        ];
    }

    public function detectCalendarConflicts(array $filters = [], int $dailyCapacity = 4): array
    {
        $filters['date_from'] = $filters['date_from'] ?? date('Y-m-01');
        $filters['date_to'] = $filters['date_to'] ?? date('Y-m-t');
        $milestones = $this->listCalendarMilestones($filters, 250, 0);
        $byDate = [];
        foreach ($milestones as $milestone) {
            if ((string) ($milestone['status'] ?? '') !== 'planned') {
                continue;
            }
            $date = (string) ($milestone['milestone_date'] ?? '');
            if ($date === '') {
                continue;
            }
            $byDate[$date][] = $milestone;
        }

        $conflicts = [];
        foreach ($byDate as $date => $rows) {
            $weight = array_sum(array_map(static fn(array $row): int => max(1, (int) ($row['capacity_weight'] ?? 1)), $rows));
            $status = $weight > $dailyCapacity ? 'conflict' : ($weight === $dailyCapacity ? 'warning' : 'clear');
            if ($status === 'clear') {
                continue;
            }
            $conflicts[] = [
                'date' => $date,
                'status' => $status,
                'count' => count($rows),
                'capacity_weight' => $weight,
                'message' => $status === 'conflict'
                    ? 'Calendar capacity is overloaded for this date.'
                    : 'Calendar capacity is at the recommended limit for this date.',
            ];
        }

        return $conflicts;
    }

    public function rescheduleCalendarMilestone(int $id, string $date, ?int $userId = null): bool
    {
        $this->assertMarketingPermission('marketing.write');
        $this->assertWorkspaceRecord('marketing_calendar_milestones', $id, $this->workspaceId());
        $newDate = $this->normalizeDate($date, 'milestone date');
        $this->updateById('marketing_calendar_milestones', $id, [
            'milestone_date' => $newDate,
            'conflict_status' => 'clear',
            'conflict_notes' => null,
        ]);
        $this->recordMarketingAuditEvent(
            'calendar_milestone_rescheduled',
            'marketing_calendar_milestones',
            $id,
            'Marketing calendar milestone rescheduled.',
            ['milestone_date' => $newDate],
            $userId ?? $this->currentUserId()
        );

        return true;
    }

    public function listCalendarTemplates(array $filters = [], int $limit = 100, int $offset = 0): array
    {
