        }
        if (!empty($filters['channel'])) {
            $where[] = 't.channel = ?';
            $params[] = $this->normalizeEnum((string) $filters['channel'], self::CHANNELS, 'calendar_channel');
        }

        return array_map(
            fn(array $row): array => $this->hydrateJsonFields($row, ['checklist_json', 'metadata_json']),
            Database::query(
                "SELECT t.*, owner.email AS owner_email, creator.email AS created_by_email
                 FROM marketing_calendar_templates t
                 LEFT JOIN users owner ON owner.id = t.owner_user_id
                 LEFT JOIN users creator ON creator.id = t.created_by
                 WHERE " . implode(' AND ', $where) . "
                 ORDER BY t.milestone_type ASC, t.offset_days ASC, t.name ASC
                 LIMIT {$limit} OFFSET {$offset}",
                $params
            )
        );
