    public function listContentComments(int $contentItemId, bool $includeResolved = true): array
    {
        $this->assertContentItem($contentItemId);
        $where = 'cc.workspace_id = ? AND cc.content_item_id = ?';
        if (!$includeResolved) {
            $where .= ' AND cc.resolved_at IS NULL';
        }

        return Database::query(
            "SELECT cc.*, creator.email AS created_by_email, resolver.email AS resolved_by_email
             FROM marketing_content_comments cc
             LEFT JOIN users creator ON creator.id = cc.created_by
             LEFT JOIN users resolver ON resolver.id = cc.resolved_by
             WHERE {$where}
             ORDER BY cc.resolved_at IS NULL DESC, cc.created_at DESC",
            [$this->workspaceId(), $contentItemId]
        );
    }

    public function addContentComment(int $contentItemId, string $body, ?int $userId = null): int
    {
        $this->assertContentItem($contentItemId);
        $body = trim((string) Security::sanitizeInput($body, 'string'));
        if ($body === '') {
            throw new \InvalidArgumentException('Comment body is required.');
        }

        Database::execute(
            "INSERT INTO marketing_content_comments (workspace_id, content_item_id, body, created_by)
             VALUES (?, ?, ?, ?)",
            [$this->workspaceId(), $contentItemId, $body, $userId ?? (int) ($_SESSION['user_id'] ?? 0) ?: null]
        );

        return (int) Database::lastInsertId();
    }

    public function resolveContentComment(int $commentId, ?int $userId = null): bool
    {
        Database::execute(
            "UPDATE marketing_content_comments
             SET resolved_at = NOW(), resolved_by = ?
             WHERE workspace_id = ? AND id = ?",
            [$userId ?? (int) ($_SESSION['user_id'] ?? 0) ?: null, $this->workspaceId(), $commentId]
        );

        return true;
    }

    public function requestContentReview(int $contentItemId, ?int $userId = null, ?int $reviewerUserId = null, ?string $reviewDueAt = null): int
    {
        $this->assertContentItem($contentItemId);
        $actorId = $userId ?? (int) ($_SESSION['user_id'] ?? 0) ?: null;
        if ($reviewerUserId !== null && $reviewerUserId > 0) {
            $this->assertWorkspaceUser($reviewerUserId, $this->workspaceId());
        }
        $dueAt = $reviewDueAt !== null && trim($reviewDueAt) !== ''
            ? $this->normalizeDateTime($reviewDueAt)
            : null;
        $this->updateContentItem($contentItemId, [
            'status' => 'review',
            'reviewer_user_id' => $reviewerUserId,
            'review_due_at' => $dueAt,
            'change_summary' => 'Review requested',
        ]);
        Database::execute(
            "INSERT INTO marketing_content_approvals (workspace_id, content_item_id, requested_by, reviewer_user_id, review_due_at, status)
             VALUES (?, ?, ?, ?, ?, 'pending')",
            [$this->workspaceId(), $contentItemId, $actorId, $reviewerUserId, $dueAt]
        );

        return (int) Database::lastInsertId();
    }

    public function decideContentApproval(int $approvalId, string $decision, string $note = '', ?int $userId = null): bool
    {
        $decision = $this->normalizeEnum($decision, ['approved', 'rejected'], 'approval_decision');
        $approval = Database::queryOne(
            "SELECT * FROM marketing_content_approvals WHERE workspace_id = ? AND id = ? LIMIT 1",
            [$this->workspaceId(), $approvalId]
        );
        if (!$approval) {
            throw new RuntimeException('Marketing approval not found.');
        }

        $actorId = $userId ?? (int) ($_SESSION['user_id'] ?? 0) ?: null;
        Database::execute(
            "UPDATE marketing_content_approvals
             SET status = ?, approved_by = ?, decision_note = ?, decided_at = NOW()
             WHERE workspace_id = ? AND id = ?",
            [
                $decision,
                $actorId,
                Security::sanitizeInput($note, 'string') ?: null,
                $this->workspaceId(),
                $approvalId,
            ]
        );

        $this->updateContentItem((int) $approval['content_item_id'], [
            'status' => $decision === 'approved' ? 'approved' : 'draft',
            'change_summary' => $decision === 'approved' ? 'Content approved' : 'Content rejected',
        ]);

        return true;
    }

    public function listContentApprovals(array $filters = [], int $limit = 100, int $offset = 0): array
    {
        $limit = min(max($limit, 1), 250);
        $offset = max($offset, 0);
        $workspace = $this->workspaceClause('a.');
        $where = [$workspace['sql']];
        $params = $workspace['params'];

        if (!empty($filters['status'])) {
            $where[] = 'a.status = ?';
            $params[] = $this->normalizeEnum((string) $filters['status'], self::APPROVAL_STATUSES, 'approval_status');
        }
        if (!empty($filters['content_item_id'])) {
            $where[] = 'a.content_item_id = ?';
            $params[] = (int) $filters['content_item_id'];
        }
        if (!empty($filters['reviewer_user_id'])) {
            $where[] = 'a.reviewer_user_id = ?';
            $params[] = (int) $filters['reviewer_user_id'];
        }
        if (!empty($filters['queue'])) {
            $queue = (string) $filters['queue'];
            if ($queue === 'pending') {
                $where[] = "a.status = 'pending' AND (a.review_due_at IS NULL OR a.review_due_at >= NOW()) AND (m.blocked_reason IS NULL OR m.blocked_reason = '')";
            } elseif ($queue === 'overdue') {
                $where[] = "a.status = 'pending' AND a.review_due_at IS NOT NULL AND a.review_due_at < NOW()";
            } elseif ($queue === 'blocked') {
                $where[] = "a.status = 'pending' AND m.blocked_reason IS NOT NULL AND m.blocked_reason <> ''";
            } elseif (in_array($queue, ['approved', 'rejected'], true)) {
                $where[] = 'a.status = ?';
                $params[] = $queue;
            }
        }

        return array_map(
            fn(array $row): array => $this->hydrateJsonFields($row, ['required_context_warnings_json']),
            Database::query(
                "SELECT a.*, m.title AS content_title, m.blocked_reason, m.readiness_score, m.production_stage,
                        m.production_due_at, m.production_score, m.next_action, m.dependency_status,
                        m.required_context_warnings_json,
                        requester.email AS requested_by_email, reviewer.email AS reviewer_email, approver.email AS approved_by_email
                 FROM marketing_content_approvals a
                 JOIN marketing_content_items m ON m.id = a.content_item_id AND m.workspace_id = a.workspace_id
                 LEFT JOIN users requester ON requester.id = a.requested_by
                 LEFT JOIN users reviewer ON reviewer.id = a.reviewer_user_id
                 LEFT JOIN users approver ON approver.id = a.approved_by
                 WHERE " . implode(' AND ', $where) . "
                 ORDER BY
                    CASE WHEN a.review_due_at IS NULL THEN 1 ELSE 0 END ASC,
                    a.review_due_at ASC,
                    a.requested_at DESC
                 LIMIT {$limit} OFFSET {$offset}",
                $params
            )
        );
    }

    public function listBrandProfiles(int $limit = 100, int $offset = 0): array
    {
        return array_map(
            fn(array $row): array => $this->hydrateJsonFields($row, ['metadata_json']),
            Database::query(
                "SELECT * FROM marketing_brand_profiles
                 WHERE workspace_id = ?
                   AND (metadata_json IS NULL OR COALESCE(JSON_UNQUOTE(JSON_EXTRACT(metadata_json, '$.starter_pack_archived')), 'false') <> 'true')
                 ORDER BY is_default DESC, updated_at DESC, name ASC LIMIT {$limit} OFFSET {$offset}",
                [$this->workspaceId()]
            )
        );
    }

    public function getBrandProfile(int $id): ?array
    {
        $row = Database::queryOne('SELECT * FROM marketing_brand_profiles WHERE workspace_id = ? AND id = ?', [$this->workspaceId(), $id]);
        return $row ? $this->hydrateJsonFields($row, ['metadata_json']) : null;
    }

    public function createBrandProfile(array $data): int
    {
        $normalized = $this->normalizeBrandProfileData($data, true);
        if ((int) $normalized['is_default'] === 1) {
            $this->clearDefaultBrandProfile();
        }
        Database::execute(
            "INSERT INTO marketing_brand_profiles
             (workspace_id, uuid, name, voice, tone, banned_words, value_props, proof_points, cta_defaults, is_default, metadata_json, created_by)
             VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)",
            [
                $this->workspaceId(), $this->generateUuid(), $normalized['name'], $normalized['voice'], $normalized['tone'],
                $normalized['banned_words'], $normalized['value_props'], $normalized['proof_points'], $normalized['cta_defaults'],
                $normalized['is_default'], $normalized['metadata_json'], $normalized['created_by'],
            ]
        );

        return (int) Database::lastInsertId();
    }

    public function updateBrandProfile(int $id, array $data): bool
    {
        if (!$this->getBrandProfile($id)) {
            throw new RuntimeException('Marketing brand profile not found.');
        }
        $normalized = $this->normalizeBrandProfileData($data, false);
        if (isset($normalized['is_default']) && (int) $normalized['is_default'] === 1) {
            $this->clearDefaultBrandProfile();
        }

        return $this->updateById('marketing_brand_profiles', $id, $normalized);
    }

    public function listReusableTemplates(array $filters = [], int $limit = 100, int $offset = 0): array
    {
        if (!Database::tableExists('marketing_reusable_templates')) {
            return [];
        }

        $limit = min(max($limit, 1), 250);
        $offset = max($offset, 0);
        $workspace = $this->workspaceClause('t.');
        $where = [$workspace['sql']];
        $params = $workspace['params'];
        if (!empty($filters['template_type'])) {
            $where[] = 't.template_type = ?';
            $params[] = $this->normalizeEnum((string) $filters['template_type'], self::REUSABLE_TEMPLATE_TYPES, 'template_type');
        }
        if (!empty($filters['status'])) {
            $where[] = 't.status = ?';
            $params[] = $this->normalizeEnum((string) $filters['status'], self::REUSABLE_TEMPLATE_STATUSES, 'template_status');
        } else {
            $where[] = "t.status <> 'archived'";
        }
        if (!empty($filters['channel'])) {
            $where[] = 't.channel = ?';
            $params[] = $this->normalizeEnum((string) $filters['channel'], self::CHANNELS, 'channel');
        }
        if (!empty($filters['content_type'])) {
            $where[] = 't.content_type = ?';
            $params[] = $this->normalizeEnum((string) $filters['content_type'], self::CONTENT_TYPES, 'content_type');
        }
        if (!empty($filters['brand_profile_id'])) {
            $where[] = 't.brand_profile_id = ?';
            $params[] = (int) $filters['brand_profile_id'];
        }
        if (!empty($filters['persona_id'])) {
            $where[] = 't.persona_id = ?';
            $params[] = (int) $filters['persona_id'];
        }

        return array_map(
            fn(array $row): array => $this->hydrateJsonFields($row, ['checklist_json', 'variables_json', 'metadata_json']),
            Database::query(
                "SELECT t.*, bp.name AS brand_profile_name, p.name AS persona_name, ci.title AS offer_title,
                        owner.email AS owner_email, creator.email AS created_by_email
                 FROM marketing_reusable_templates t
                 LEFT JOIN marketing_brand_profiles bp ON bp.id = t.brand_profile_id AND bp.workspace_id = t.workspace_id
                 LEFT JOIN marketing_personas p ON p.id = t.persona_id AND p.workspace_id = t.workspace_id
                 LEFT JOIN marketing_context_items ci ON ci.id = t.offer_context_item_id AND ci.workspace_id = t.workspace_id
                 LEFT JOIN users owner ON owner.id = t.owner_user_id
                 LEFT JOIN users creator ON creator.id = t.created_by
                 WHERE " . implode(' AND ', $where) . "
                 ORDER BY t.usage_count DESC, t.updated_at DESC, t.name ASC
