    public function recommendReusableTemplatesForDraftContext(array $context, int $limit = 6): array
    {
        if (!Database::tableExists('marketing_reusable_templates')) {
            return [];
        }

        $limit = min(max($limit, 1), 20);
        $workspace = $this->workspaceClause('t.');
        $where = [$workspace['sql'], "t.status = 'active'"];
        $scoreParams = [];
        $scoreParts = ['1'];

        $contentType = (string) ($context['content_type'] ?? '');
        if ($contentType !== '' && in_array($contentType, self::CONTENT_TYPES, true)) {
            $scoreParts[] = 'CASE WHEN t.content_type = ? THEN 12 ELSE 0 END';
            $scoreParams[] = $contentType;
        }
        $channel = (string) ($context['channel'] ?? '');
        if ($channel !== '' && in_array($channel, self::CHANNELS, true)) {
            $scoreParts[] = 'CASE WHEN t.channel = ? THEN 10 ELSE 0 END';
            $scoreParams[] = $channel;
        }
        $brandId = (int) ($context['brand_profile_id'] ?? ($context['brand_profile']['id'] ?? 0));
        if ($brandId > 0) {
            $scoreParts[] = 'CASE WHEN t.brand_profile_id = ? THEN 8 ELSE 0 END';
            $scoreParams[] = $brandId;
        }
        $personaId = (int) ($context['persona_id'] ?? ($context['persona']['id'] ?? 0));
        if ($personaId > 0) {
            $scoreParts[] = 'CASE WHEN t.persona_id = ? THEN 8 ELSE 0 END';
            $scoreParams[] = $personaId;
        }

        $scoreSql = implode(' + ', $scoreParts);
        $params = array_merge($scoreParams, $workspace['params']);
        $rows = Database::query(
            "SELECT t.id, t.name, t.template_type, t.channel, t.content_type, t.title_pattern,
                    t.objective, t.body_template, t.cta_template, t.media_notes, t.checklist_json,
                    t.variables_json, t.brand_profile_id, t.persona_id, t.offer_context_item_id,
                    bp.name AS brand_profile_name, p.name AS persona_name, ci.title AS offer_title,
                    ({$scoreSql}) AS match_score
             FROM marketing_reusable_templates t
             LEFT JOIN marketing_brand_profiles bp ON bp.id = t.brand_profile_id AND bp.workspace_id = t.workspace_id
             LEFT JOIN marketing_personas p ON p.id = t.persona_id AND p.workspace_id = t.workspace_id
             LEFT JOIN marketing_context_items ci ON ci.id = t.offer_context_item_id AND ci.workspace_id = t.workspace_id
             WHERE " . implode(' AND ', $where) . "
             ORDER BY match_score DESC, t.usage_count DESC, t.updated_at DESC, t.name ASC
             LIMIT {$limit}",
            $params
        );

        return array_map(
            fn(array $row): array => $this->sanitizeJsonCompatible($this->hydrateJsonFields($row, ['checklist_json', 'variables_json'])),
            $rows
        );
    }

    public function getMarketingTemplateSystemSummary(): array
    {
        $templates = $this->listReusableTemplates(['status' => 'active'], 250, 0);
        $countsByType = array_fill_keys(self::REUSABLE_TEMPLATE_TYPES, 0);
        $countsByChannel = [];
        foreach ($templates as $template) {
            $type = (string) ($template['template_type'] ?? 'other');
            $countsByType[$type] = ($countsByType[$type] ?? 0) + 1;
            $channel = (string) ($template['channel'] ?? '');
            if ($channel !== '') {
                $countsByChannel[$channel] = ($countsByChannel[$channel] ?? 0) + 1;
            }
        }

        $priorityTypes = ['content', 'landing_page', 'email', 'social', 'ad', 'brief'];
        $missingTypes = array_values(array_filter($priorityTypes, static fn(string $type): bool => (int) ($countsByType[$type] ?? 0) === 0));
        $brandProfiles = $this->listBrandProfiles(20, 0);
        $defaultBrand = null;
        foreach ($brandProfiles as $profile) {
            if ((int) ($profile['is_default'] ?? 0) === 1) {
                $defaultBrand = $profile;
                break;
            }
        }
        $ctaCount = Database::tableExists('marketing_context_items')
            ? $this->workflowCount('marketing_context_items', "item_type = 'default_cta' AND status = 'active'")
            : 0;

        $score = 20;
        $score += min(35, count($templates) * 5);
        $score += $defaultBrand ? 20 : 0;
        $score += min(15, $ctaCount * 5);
        $score -= count($missingTypes) * 5;
        $score = max(0, min(100, $score));

        $recommendations = [];
        if (!$defaultBrand) {
            $recommendations[] = ['label' => 'Set a default brand profile', 'href' => 'marketing_brand.php', 'priority' => 'high'];
        }
        if ($ctaCount === 0) {
            $recommendations[] = ['label' => 'Add reusable CTA defaults', 'href' => 'marketing_context.php?type=default_cta', 'priority' => 'medium'];
        }
        foreach (array_slice($missingTypes, 0, 4) as $type) {
            $recommendations[] = [
                'label' => 'Create a ' . str_replace('_', ' ', $type) . ' template',
                'href' => 'marketing_brand.php',
                'priority' => in_array($type, ['content', 'landing_page', 'email'], true) ? 'high' : 'medium',
            ];
        }
        if ($recommendations === []) {
            $recommendations[] = ['label' => 'Use templates in the next content draft', 'href' => 'marketing_content.php', 'priority' => 'normal'];
        }

        return [
            'score' => $score,
            'status' => $score >= 80 ? 'ready' : ($score >= 50 ? 'partial' : 'thin'),
            'counts' => [
                'templates' => count($templates),
                'brand_profiles' => count($brandProfiles),
                'default_ctas' => $ctaCount,
                'missing_priority_types' => count($missingTypes),
            ],
            'counts_by_type' => $countsByType,
            'counts_by_channel' => $countsByChannel,
            'missing_types' => $missingTypes,
            'default_brand' => $defaultBrand ? [
                'id' => (int) ($defaultBrand['id'] ?? 0),
                'name' => (string) ($defaultBrand['name'] ?? ''),
                'voice' => (string) ($defaultBrand['voice'] ?? ''),
                'tone' => (string) ($defaultBrand['tone'] ?? ''),
            ] : null,
            'templates' => array_slice($templates, 0, 8),
            'recommendations' => $recommendations,
            'guardrails' => [
                'manual_first' => true,
                'external_publish' => false,
                'external_send' => false,
                'ai_can_suggest_templates' => true,
                'ai_overwrites_user_work' => false,
            ],
        ];
    }

