    public function listLandingPages(array $filters = [], int $limit = 100, int $offset = 0): array
    {
        $workspace = $this->workspaceClause('lp.');
        $where = [$workspace['sql']];
        $params = $workspace['params'];
        if (!empty($filters['status'])) {
            $where[] = 'lp.status = ?';
            $params[] = $this->normalizeEnum((string) $filters['status'], self::LANDING_PAGE_STATUSES, 'landing_page_status');
        }
        if (!empty($filters['audience_segment_id'])) {
            $where[] = 'lp.audience_segment_id = ?';
            $params[] = (int) $filters['audience_segment_id'];
        }
        if (!empty($filters['campaign_id'])) {
            $where[] = 'lp.campaign_id = ?';
            $params[] = (int) $filters['campaign_id'];
        }

        return array_map(
            fn(array $row): array => $this->hydrateLandingPageRow($row),
            Database::query(
                "SELECT lp.*, f.name AS form_name, f.uuid AS form_uuid, f.preview_token AS form_preview_token,
                        f.design_status AS form_design_status, f.published_revision AS form_published_revision,
                        c.name AS campaign_name, seg.name AS audience_segment_name,
                        goal.title AS conversion_goal_title, goal.goal_type AS conversion_goal_type,
                        pub.status AS publication_status, pub.public_url, pub.public_token,
                        pub.published_at AS publication_published_at, pub.unpublished_at AS publication_unpublished_at,
                        pub.readiness_score AS publication_readiness_score, pub.readiness_json AS publication_readiness_json
                 FROM marketing_landing_pages lp
                 LEFT JOIN forms f ON f.id = lp.form_id AND f.workspace_id = lp.workspace_id
                 LEFT JOIN campaigns c ON c.id = lp.campaign_id AND c.workspace_id = lp.workspace_id
                 LEFT JOIN marketing_audience_segments seg ON seg.id = lp.audience_segment_id AND seg.workspace_id = lp.workspace_id
                 LEFT JOIN marketing_conversion_goals goal ON goal.id = lp.conversion_goal_id AND goal.workspace_id = lp.workspace_id
                 LEFT JOIN marketing_landing_page_publications pub ON pub.landing_page_id = lp.id AND pub.workspace_id = lp.workspace_id
                 WHERE " . implode(' AND ', $where) . "
                 ORDER BY lp.updated_at DESC
                 LIMIT {$limit} OFFSET {$offset}",
                $params
            )
        );
    }

