    public function createLandingPage(array $data): int
    {
        $this->assertMarketingDesignPermission('marketing.write');
        if (array_key_exists('design_document', $data) || array_key_exists('design_document_json', $data)) {
            $rawDocument = $data['design_document'] ?? $data['design_document_json'] ?? [];
            if (is_string($rawDocument)) {
                $decodedDocument = json_decode($rawDocument, true);
                $rawDocument = is_array($decodedDocument) ? $decodedDocument : [];
            }
            $design = new LandingPageDesignService();
            $document = $design->normalizeDocument(is_array($rawDocument) ? $rawDocument : [], $data);
            $data = array_merge($design->legacyFields($document), $data, ['design_document' => $document]);
        }
        $normalized = $this->normalizeLandingPageData($data, true);
        $this->assertUniqueLandingSlug((string) $normalized['slug']);
        Database::beginTransaction();
        try {
            Database::execute(
            "INSERT INTO marketing_landing_pages
             (workspace_id, uuid, title, slug, headline, seo_title, meta_description,
              hero_media_file_id, social_preview_media_file_id, cta_media_file_id, proof_media_file_id, testimonial_media_file_id,
              body_sections_json, section_media_json, gallery_media_json,
              theme_settings_json, cta_variants_json, form_blocks_json, seo_controls_json, social_preview_json, builder_status,
              design_schema_version, design_document_json, design_revision, design_validation_json, design_updated_at,
              cta_blocks_json, proof_blocks_json, faq_blocks_json, thank_you_copy, preview_token, conversion_goal, conversion_goal_id,
              form_id, campaign_id, audience_segment_id, status, metadata_json, created_by)
             VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, NOW(), ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)",
            [
                $this->workspaceId(), $this->generateUuid(), $normalized['title'], $normalized['slug'], $normalized['headline'],
                $normalized['seo_title'], $normalized['meta_description'],
                $normalized['hero_media_file_id'], $normalized['social_preview_media_file_id'], $normalized['cta_media_file_id'],
                $normalized['proof_media_file_id'], $normalized['testimonial_media_file_id'],
                $normalized['body_sections_json'], $normalized['section_media_json'], $normalized['gallery_media_json'],
                $normalized['theme_settings_json'], $normalized['cta_variants_json'], $normalized['form_blocks_json'],
                $normalized['seo_controls_json'], $normalized['social_preview_json'], $normalized['builder_status'],
                $normalized['design_schema_version'], $normalized['design_document_json'], $normalized['design_revision'], $normalized['design_validation_json'],
                $normalized['cta_blocks_json'], $normalized['proof_blocks_json'], $normalized['faq_blocks_json'],
                $normalized['thank_you_copy'], $normalized['preview_token'], $normalized['conversion_goal'], $normalized['conversion_goal_id'],
                $normalized['form_id'], $normalized['campaign_id'], $normalized['audience_segment_id'],
                $normalized['status'], $normalized['metadata_json'], $normalized['created_by'],
            ]
            );

            $id = (int) Database::lastInsertId();
            $this->createLandingPageVersion($id, 'draft', $normalized['created_by'] ?? null);
            if (!empty($normalized['conversion_goal_id'])) {
                $this->linkConversionGoal((int) $normalized['conversion_goal_id'], 'landing_page', $id, (int) ($normalized['created_by'] ?? $this->currentUserId()) ?: null);
            }
            Database::commit();

            return $id;
        } catch (Throwable $e) {
            Database::rollBack();
            throw $e;
        }
    }

    public function updateLandingPage(int $id, array $data): bool
    {
        $this->assertMarketingDesignPermission('marketing.write');
        if (!$this->getLandingPage($id)) {
            throw new RuntimeException('Marketing landing page not found.');
        }
        $existing = $this->getLandingPage($id);
        $normalized = $this->normalizeLandingPageData(array_merge($existing ?? [], $data), false);
        if (isset($normalized['slug'])) {
            $this->assertUniqueLandingSlug((string) $normalized['slug'], $id);
        }

        $updated = $this->updateById('marketing_landing_pages', $id, $normalized);
        if ($updated && Database::columnExists('marketing_landing_pages', 'design_revision')) {
            Database::execute(
                'UPDATE marketing_landing_pages
                 SET design_revision = design_revision + 1, design_updated_at = NOW()
                 WHERE workspace_id = ? AND id = ?',
                [$this->workspaceId(), $id]
            );
        }
        $this->createLandingPageVersion($id, 'draft', (int) ($data['created_by'] ?? $this->currentUserId()) ?: null);
        if (array_key_exists('conversion_goal_id', $normalized) && !empty($normalized['conversion_goal_id'])) {
            $this->linkConversionGoal((int) $normalized['conversion_goal_id'], 'landing_page', $id, (int) ($data['created_by'] ?? $this->currentUserId()) ?: null);
        }

        return $updated;
    }

    /**
     * Return the complete, server-validated contract consumed by Design Studio.
     */
    public function getLandingPageDesignEditorData(int $id): array
    {
        $this->assertMarketingDesignPermission('marketing.read');
        $page = $this->getLandingPage($id);
        if (!$page) {
            throw new RuntimeException('Marketing landing page not found.');
        }

        $design = new LandingPageDesignService();
        $document = $design->normalizeDocument((array) ($page['design_document_json'] ?? []), $page);
        $validation = $design->validateDocument($document, $page);
        $options = $this->landingPageEditorOptionData();
        foreach ($options['media_files'] as &$media) {
            $media['display_url'] = $this->mediaDisplayUrl($media);
        }
        unset($media);

        return [
            'page' => $page,
            'document' => $document,
            'revision' => (int) ($page['design_revision'] ?? 0),
            'validation' => $validation,
            'manifest' => $design->editorManifest(),
            'templates' => $design->templates(),
            'options' => $options,
            'versions' => array_map(static fn(array $version): array => [
                'id' => (int) ($version['id'] ?? 0),
                'type' => (string) ($version['version_type'] ?? 'draft'),
                'number' => (int) ($version['version_number'] ?? 0),
                'title' => (string) ($version['title'] ?? ''),
                'created_at' => (string) ($version['created_at'] ?? ''),
                'created_by_email' => (string) ($version['created_by_email'] ?? ''),
            ], array_slice($this->listLandingPageVersions($id), 0, 30)),
        ];
    }

    /**
     * Autosave with optimistic locking. A stale browser can never overwrite a
     * newer revision silently.
     *
     * @param array<string,mixed> $document
     * @param array<string,mixed> $pageFields
     */
    public function saveLandingPageDesign(int $id, array $document, array $pageFields, int $expectedRevision, ?int $userId = null): array
    {
        $this->assertMarketingDesignPermission('marketing.write');
        $page = $this->getLandingPage($id);
        if (!$page) {
            throw new RuntimeException('Marketing landing page not found.');
        }
        $currentRevision = (int) ($page['design_revision'] ?? 0);
        if ($expectedRevision !== $currentRevision) {
            throw new RuntimeException('This page changed in another session. Reload the latest revision before saving.');
        }

        $design = new LandingPageDesignService();
        $document = $design->normalizeDocument($document, array_merge($page, $pageFields));
        $validation = $design->validateDocument($document, array_merge($page, $pageFields));
        $previousTemplateKey = (string) (($page['design_document_json']['metadata']['template_key'] ?? ''));
        $legacy = $design->legacyFields($document);
        $allowedPageFields = [
            'title', 'slug', 'seo_title', 'meta_description', 'form_id', 'campaign_id',
            'audience_segment_id', 'conversion_goal', 'conversion_goal_id', 'status',
        ];
        $filteredFields = array_intersect_key($pageFields, array_flip($allowedPageFields));
        $normalizedFields = $this->normalizeLandingPageData($filteredFields, false);
        $normalizedLegacy = $this->normalizeLandingPageData($legacy, false);
        $updates = array_merge($normalizedFields, $normalizedLegacy, [
            'design_schema_version' => LandingPageDesignService::SCHEMA_VERSION,
            'design_document_json' => $this->normalizeJsonValue($document),
            'design_validation_json' => $this->normalizeJsonValue($validation),
            'builder_status' => !empty($validation['valid']) ? 'ready' : 'draft',
        ]);
        unset($updates['design_revision']);
        if (isset($updates['slug'])) {
            $this->assertUniqueLandingSlug((string) $updates['slug'], $id);
        }

        $assignments = [];
        $params = [];
        foreach ($updates as $column => $value) {
            if (!preg_match('/^[a-z_]+$/', (string) $column)) {
                continue;
            }
            $assignments[] = $column . ' = ?';
            $params[] = $value;
        }
        $assignments[] = 'design_revision = design_revision + 1';
        $assignments[] = 'design_updated_at = NOW()';
        $params[] = $this->workspaceId();
        $params[] = $id;
        $params[] = $expectedRevision;

        Database::beginTransaction();
        try {
            $changed = Database::execute(
                'UPDATE marketing_landing_pages SET ' . implode(', ', $assignments) .
                ' WHERE workspace_id = ? AND id = ? AND design_revision = ?',
                $params
            );
            if ($changed !== 1) {
                throw new RuntimeException('This page changed in another session. Reload the latest revision before saving.');
            }
            $this->checkpointLandingPageDesignDraft($id, $userId ?? $this->currentUserId());
            $templateKey = trim((string) ($document['metadata']['template_key'] ?? ''));
            if ($templateKey !== '' && $templateKey !== 'legacy_migration' && $templateKey !== $previousTemplateKey) {
                $this->recordDesignTemplateEvent(
                    $id,
                    $templateKey,
                    (string) ($document['metadata']['template_version'] ?? '1.0.0'),
                    'applied',
                    $userId
                );
            }
            Database::commit();
        } catch (Throwable $e) {
            Database::rollBack();
            throw $e;
        }

        return $this->getLandingPageDesignEditorData($id);
    }

    public function restoreLandingPageDesignVersion(int $landingPageId, int $versionId, int $expectedRevision, ?int $userId = null): array
    {
        $this->assertMarketingDesignPermission('marketing.write');
        $version = Database::queryOne(
            'SELECT * FROM marketing_landing_page_versions WHERE workspace_id = ? AND landing_page_id = ? AND id = ? LIMIT 1',
            [$this->workspaceId(), $landingPageId, $versionId]
        );
        if (!$version) {
            throw new RuntimeException('Landing page version not found.');
        }
        $snapshot = json_decode((string) ($version['snapshot_json'] ?? ''), true);
        if (!is_array($snapshot)) {
            throw new RuntimeException('Landing page version snapshot is invalid.');
        }
        $document = $snapshot['design_document_json'] ?? [];
        if (is_string($document)) {
            $decoded = json_decode($document, true);
            $document = is_array($decoded) ? $decoded : [];
        }
        $fields = array_intersect_key($snapshot, array_flip([
            'title', 'slug', 'seo_title', 'meta_description', 'form_id', 'campaign_id',
            'audience_segment_id', 'conversion_goal', 'conversion_goal_id', 'status',
        ]));
        return $this->saveLandingPageDesign($landingPageId, is_array($document) ? $document : [], $fields, $expectedRevision, $userId);
    }

    public function getLandingPagePublishingReadiness(int $id): array
    {
        $page = $this->getLandingPage($id);
        if (!$page) {
            throw new RuntimeException('Marketing landing page not found.');
        }

        return $this->calculateLandingPagePublishingReadiness($page);
    }

    public function getLandingPageVisualCommandQueue(int $limit = 8): array
    {
        $this->assertMarketingDesignPermission('marketing.read');
        $limit = min(max($limit, 1), 20);
        if (!Database::tableExists('marketing_landing_pages')) {
            return [
                'score' => 0,
                'status' => 'unavailable',
                'counts' => [],
                'queues' => [],
                'next_actions' => [],
                'guardrails' => ['manual_first' => true, 'external_publish' => false],
            ];
        }

        $scanLimit = min(80, max($limit * 8, 24));
        $pages = array_values(array_filter(
            $this->listLandingPages([], $scanLimit, 0),
            static fn(array $page): bool => (string) ($page['status'] ?? '') !== 'archived'
        ));
        $queues = [
            'needs_hero_media' => [],
            'needs_social_preview' => [],
            'needs_accessibility' => [],
            'needs_conversion' => [],
            'ready_to_preview' => [],
        ];
        $nextActions = [];

        foreach ($pages as $page) {
            $readiness = $this->calculateLandingPagePublishingReadiness($page);
            $pageSummary = [
                'id' => (int) ($page['id'] ?? 0),
                'title' => (string) ($page['title'] ?? 'Landing page'),
                'slug' => (string) ($page['slug'] ?? ''),
                'status' => (string) ($page['status'] ?? ''),
                'campaign_name' => (string) ($page['campaign_name'] ?? ''),
                'score' => (int) ($readiness['score'] ?? 0),
                'media_warnings' => (array) ($readiness['media_warnings'] ?? []),
                'builder_warnings' => (array) ($readiness['builder_warnings'] ?? []),
            ];
            $mediaWarnings = (array) ($readiness['media_warnings'] ?? []);
            $missing = (array) ($readiness['missing'] ?? []);

            if (in_array('hero_media_recommended', $mediaWarnings, true)) {
                $queues['needs_hero_media'][] = $pageSummary;
            }
            if (in_array('social_preview_media_recommended', $mediaWarnings, true)) {
                $queues['needs_social_preview'][] = $pageSummary;
            }
            if (array_filter($mediaWarnings, static fn(string $warning): bool => str_contains($warning, 'alt_text') || str_contains($warning, 'caption_or_transcript'))) {
                $queues['needs_accessibility'][] = $pageSummary;
            }
            if (in_array('conversion_goal', $missing, true) || empty($page['form_id'])) {
                $queues['needs_conversion'][] = $pageSummary;
            }
            if ((int) ($readiness['score'] ?? 0) >= 90 && $mediaWarnings === []) {
                $queues['ready_to_preview'][] = $pageSummary;
            }
        }

        $addAction = static function (array &$nextActions, string $label, string $href, string $reason, string $priority): void {
            $nextActions[] = [
                'label' => $label,
                'href' => $href,
                'reason' => $reason,
                'priority' => $priority,
            ];
        };
        if ($queues['needs_hero_media'] !== []) {
            $addAction($nextActions, 'Attach hero visuals', 'marketing_landing_pages.php', count($queues['needs_hero_media']) . ' landing page(s) need a hero image or video.', 'high');
        }
        if ($queues['needs_social_preview'] !== []) {
            $addAction($nextActions, 'Attach social preview images', 'marketing_landing_pages.php', count($queues['needs_social_preview']) . ' landing page(s) need social preview media.', 'medium');
        }
        if ($queues['needs_accessibility'] !== []) {
            $addAction($nextActions, 'Fix media accessibility', 'marketing_assets.php', count($queues['needs_accessibility']) . ' landing page(s) have image alt text or video transcript gaps.', 'high');
        }
        if ($queues['needs_conversion'] !== []) {
            $addAction($nextActions, 'Complete conversion wiring', 'marketing_landing_pages.php', count($queues['needs_conversion']) . ' landing page(s) need a form or conversion goal.', 'high');
        }
        if ($queues['ready_to_preview'] !== []) {
            $addAction($nextActions, 'Review token previews', 'marketing_landing_pages.php', count($queues['ready_to_preview']) . ' landing page(s) are visually ready for authenticated preview review.', 'normal');
        }

        $issueCount = count($queues['needs_hero_media']) + count($queues['needs_social_preview']) + count($queues['needs_accessibility']) + count($queues['needs_conversion']);
        $score = $pages === [] ? 0 : max(0, min(100, 100 - (int) round(($issueCount / max(1, count($pages))) * 35)));

        return [
            'score' => $score,
            'status' => $pages === [] ? 'empty' : ($issueCount === 0 ? 'visual_ready' : ($score >= 75 ? 'needs_attention' : 'blocked')),
            'counts' => [
                'scanned' => count($pages),
                'needs_hero_media' => count($queues['needs_hero_media']),
                'needs_social_preview' => count($queues['needs_social_preview']),
                'needs_accessibility' => count($queues['needs_accessibility']),
                'needs_conversion' => count($queues['needs_conversion']),
                'ready_to_preview' => count($queues['ready_to_preview']),
            ],
            'queues' => array_map(static fn(array $items): array => array_slice($items, 0, $limit), $queues),
            'next_actions' => array_slice($nextActions, 0, $limit),
            'recommended_product_decision' => 'Treat landing pages as media-led conversion assets: every page should have a hero visual, social preview, accessible media text, and conversion wiring before manual launch.',
            'performance' => [
                'limit' => $limit,
                'scan_limit' => $scanLimit,
                'page_load_guard' => true,
            ],
            'guardrails' => [
                'manual_first' => true,
                'external_publish' => false,
                'external_send' => false,
                'message' => 'Visual readiness prepares landing pages for review only. It does not publish, host externally, or send traffic.',
            ],
        ];
    }

    public function createMarketingQueueAction(array $data, int $userId): array
    {
        $this->assertMarketingPermission('marketing.write');
        if ($userId > 0) {
            $this->assertWorkspaceUser($userId, $this->workspaceId());
        }

        $surface = $this->normalizeEnum((string) ($data['surface'] ?? $data['action_surface'] ?? ''), self::MARKETING_QUEUE_ACTION_SURFACES, 'queue_action_surface');
        $actionKey = $this->normalizeEnum((string) ($data['action_key'] ?? ''), self::MARKETING_QUEUE_ACTION_KEYS, 'queue_action_key');
        $sourceId = (int) ($data['source_id'] ?? $data['record_id'] ?? 0);
        if ($sourceId <= 0) {
            throw new \InvalidArgumentException('A source record is required for queue follow-through.');
        }

        $result = [
            'surface' => $surface,
            'action_key' => $actionKey,
            'source_id' => $sourceId,
            'created' => [],
            'reused' => [],
            'warnings' => [],
            'guardrails' => [
                'manual_first' => true,
                'external_publish' => false,
                'external_send' => false,
                'external_generation' => false,
            ],
        ];

        if ($surface === 'content_production') {
            $content = $this->getContentItem($sourceId);
            if (!$content) {
                throw new RuntimeException('Marketing content item was not found.');
            }
            return $this->createContentProductionQueueAction($content, $actionKey, $userId, $result);
        }

        $landingPage = $this->getLandingPage($sourceId);
        if (!$landingPage) {
            throw new RuntimeException('Landing page plan was not found.');
        }

        return $this->createLandingVisualQueueAction($landingPage, $actionKey, $userId, $result);
    }

    private function createContentProductionQueueAction(array $content, string $actionKey, int $userId, array $result): array
    {
        $contentId = (int) ($content['id'] ?? 0);
        $title = trim((string) ($content['title'] ?? 'Content item'));
        $metadata = $this->queueActionMetadata('content_production', $actionKey, $contentId, $userId, [
            'content_type' => (string) ($content['content_type'] ?? ''),
            'channel' => (string) ($content['channel'] ?? ''),
            'status' => (string) ($content['status'] ?? ''),
        ]);

        if ($actionKey === 'content_media_request') {
            $assetRequest = $this->createOrReuseQueueAssetRequest([
                'title' => 'Create campaign-ready media for ' . $title,
                'content_item_id' => $contentId,
                'requested_asset_type' => in_array((string) ($content['content_type'] ?? ''), ['video_script'], true) ? 'video' : 'image',
                'channel' => (string) ($content['channel'] ?? ''),
                'description' => 'Create or attach visual media for this content item. Include alt text, caption guidance, usage rights, and placement notes before distribution.',
                'due_at' => date('Y-m-d H:i:s', strtotime('+3 days')),
                'metadata_json' => $metadata,
                'created_by' => $userId,
            ]);
            $this->appendQueueActionReference($result, $assetRequest, 'asset_request');

            $mediaWork = $this->createOrReuseQueueMediaWorkItem([
                'title' => 'Produce content media for ' . $title,
                'work_type' => 'design',
                'priority' => 'high',
                'status' => 'requested',
                'content_item_id' => $contentId,
                'channel' => (string) ($content['channel'] ?? ''),
                'placement' => 'content_media',
                'requested_format' => 'Image or video ready for the selected channel',
                'due_at' => date('Y-m-d H:i:s', strtotime('+3 days')),
                'owner_user_id' => (int) ($content['owner_user_id'] ?? 0) ?: $userId,
                'production_notes' => 'Queue follow-through from Content Studio media warnings. Keep this manual-first and attach approved media when ready.',
                'checklist' => "Confirm format and dimensions\nAdd alt text or transcript\nConfirm usage rights\nAttach to content item",
                'metadata_json' => $metadata,
                'created_by' => $userId,
            ]);
            $this->appendQueueActionReference($result, $mediaWork, 'media_work');
        }

        $task = $this->createOrReuseQueueTask($this->contentQueueTaskPayload($content, $actionKey, $metadata, $userId));
        $this->appendQueueActionReference($result, $task, 'task');

        return $result;
    }

    private function createLandingVisualQueueAction(array $landingPage, string $actionKey, int $userId, array $result): array
    {
        $landingPageId = (int) ($landingPage['id'] ?? 0);
        $title = trim((string) ($landingPage['title'] ?? 'Landing page'));
        $metadata = $this->queueActionMetadata('landing_visual', $actionKey, $landingPageId, $userId, [
            'slug' => (string) ($landingPage['slug'] ?? ''),
            'status' => (string) ($landingPage['status'] ?? ''),
            'publication_status' => (string) ($landingPage['publication_status'] ?? ''),
        ]);

        if (in_array($actionKey, ['landing_hero_visual', 'landing_social_preview', 'landing_accessibility'], true)) {
            $workType = $actionKey === 'landing_accessibility' ? 'quality_review' : 'landing_visual';
            $placement = $actionKey === 'landing_social_preview' ? 'social_preview' : ($actionKey === 'landing_accessibility' ? 'accessibility' : 'hero');
            $mediaWork = $this->createOrReuseQueueMediaWorkItem([
                'title' => $this->landingQueueActionTitle($landingPage, $actionKey),
                'work_type' => $workType,
                'priority' => $actionKey === 'landing_accessibility' ? 'high' : 'normal',
                'status' => 'requested',
                'landing_page_id' => $landingPageId,
                'campaign_id' => (int) ($landingPage['campaign_id'] ?? 0),
                'channel' => 'website',
                'placement' => $placement,
                'requested_format' => $actionKey === 'landing_social_preview' ? 'Social preview image' : 'Landing page image or video',
                'due_at' => date('Y-m-d H:i:s', strtotime('+3 days')),
                'owner_user_id' => $userId,
                'production_notes' => 'Queue follow-through from Landing Visual Readiness. Keep this as a planning and review item until a user manually publishes.',
                'checklist' => "Confirm visual placement\nAdd alt text or caption/transcript\nConfirm usage rights\nPreview authenticated landing page",
                'metadata_json' => $metadata,
                'created_by' => $userId,
            ]);
            $this->appendQueueActionReference($result, $mediaWork, 'media_work');
        }

        $task = $this->createOrReuseQueueTask($this->landingQueueTaskPayload($landingPage, $actionKey, $metadata, $userId));
        $this->appendQueueActionReference($result, $task, 'task');

        return $result;
    }

    private function queueActionMetadata(string $surface, string $actionKey, int $sourceId, int $userId, array $extra = []): array
    {
        return array_merge([
            'source' => 'marketing_queue_action',
            'action_surface' => $surface,
            'action_key' => $actionKey,
            'source_id' => $sourceId,
            'created_by' => $userId,
            'manual_first' => true,
            'external_publish' => false,
            'external_send' => false,
            'external_generation' => false,
        ], $extra);
    }

    private function contentQueueTaskPayload(array $content, string $actionKey, array $metadata, int $userId): array
    {
        $title = trim((string) ($content['title'] ?? 'Content item'));
        $contentId = (int) ($content['id'] ?? 0);
        $map = [
            'content_media_request' => ['Attach media for ' . $title, 'Create or select approved media, add accessibility text, and attach it to this content item before export.', 'high', '+3 days'],
            'content_review_task' => ['Review content: ' . $title, 'Move this content through review, capture decision notes, and keep the version trail intact.', 'high', '+2 days'],
            'content_schedule_task' => ['Rescue overdue content: ' . $title, 'Confirm the next production date, update schedule fields, and clear any overdue blocker.', 'urgent', '+1 day'],
            'content_link_context_task' => ['Link campaign context for ' . $title, 'Connect this content item to its campaign, brief, landing page, or distribution plan so reporting is not isolated.', 'medium', '+4 days'],
            'content_production_task' => ['Finish production for ' . $title, 'Complete the next production action and update status, owner, due date, or blocked reason.', 'medium', '+3 days'],
            'content_unblock_task' => ['Unblock content production: ' . $title, 'Resolve the blocked reason, capture the dependency note, and move this content item back into active production.', 'urgent', '+1 day'],
        ];
        [$taskTitle, $description, $priority, $due] = $map[$actionKey] ?? $map['content_production_task'];

        return [
            'title' => $taskTitle,
            'description' => $description . "\n\nContent: marketing_content_view.php?id=" . $contentId,
            'assigned_to' => (int) ($content['owner_user_id'] ?? 0) ?: $userId,
            'created_by' => $userId,
            'actor_user_id' => $userId,
            'status' => 'pending',
            'priority' => $priority,
            'due_date' => date('Y-m-d', strtotime($due)),
            'source_surface' => 'marketing_queue_action',
            'source_capability_key' => $actionKey,
            'metadata_json' => $metadata,
        ];
    }

    private function landingQueueTaskPayload(array $landingPage, string $actionKey, array $metadata, int $userId): array
    {
        $landingPageId = (int) ($landingPage['id'] ?? 0);
        $map = [
            'landing_hero_visual' => [$this->landingQueueActionTitle($landingPage, $actionKey), 'Select or produce a hero image/video and attach it to the landing page plan.', 'high', '+3 days'],
            'landing_social_preview' => [$this->landingQueueActionTitle($landingPage, $actionKey), 'Add a social preview image so shared links are visually ready for manual launch.', 'medium', '+4 days'],
            'landing_accessibility' => [$this->landingQueueActionTitle($landingPage, $actionKey), 'Add missing image alt text, captions, or video transcripts before preview approval.', 'high', '+2 days'],
            'landing_conversion' => [$this->landingQueueActionTitle($landingPage, $actionKey), 'Connect the landing page form and conversion goal before publishing review.', 'high', '+2 days'],
            'landing_preview_review' => [$this->landingQueueActionTitle($landingPage, $actionKey), 'Open the authenticated preview, verify copy/media/form readiness, and record any launch blockers.', 'medium', '+2 days'],
        ];
        [$taskTitle, $description, $priority, $due] = $map[$actionKey] ?? $map['landing_preview_review'];

        return [
            'title' => $taskTitle,
            'description' => $description . "\n\nLanding page: marketing_landing_page_view.php?id=" . $landingPageId,
            'assigned_to' => $userId,
            'created_by' => $userId,
            'actor_user_id' => $userId,
            'status' => 'pending',
            'priority' => $priority,
            'due_date' => date('Y-m-d', strtotime($due)),
            'source_surface' => 'marketing_queue_action',
            'source_capability_key' => $actionKey,
            'metadata_json' => $metadata,
        ];
    }

    private function landingQueueActionTitle(array $landingPage, string $actionKey): string
    {
        $title = trim((string) ($landingPage['title'] ?? 'Landing page'));
        return match ($actionKey) {
            'landing_hero_visual' => 'Create hero visual for ' . $title,
            'landing_social_preview' => 'Create social preview for ' . $title,
            'landing_accessibility' => 'Fix media accessibility for ' . $title,
            'landing_conversion' => 'Complete conversion wiring for ' . $title,
            default => 'Review landing page preview: ' . $title,
        };
    }

    private function createOrReuseQueueTask(array $taskData): array
    {
        if (!Database::tableExists('tasks')) {
            return ['id' => 0, 'label' => 'Task system unavailable', 'href' => 'marketing.php', 'warning' => 'Task system is unavailable.'];
        }
        if (!Authorization::can('tasks.write')) {
            return ['id' => 0, 'label' => 'Task permission unavailable', 'href' => 'tasks.php', 'warning' => 'Task Hub follow-through was skipped because this user does not have tasks.write.'];
        }

        $metadata = (array) ($taskData['metadata_json'] ?? []);
        $existing = $this->findExistingQueueTask($metadata);
        if ($existing) {
            return ['id' => (int) $existing['id'], 'label' => (string) ($existing['title'] ?? 'Task'), 'href' => 'task_view.php?id=' . (int) $existing['id'], 'reused' => true];
        }

        try {
            $taskId = (new Tasks())->create($taskData);
            return ['id' => $taskId, 'label' => (string) ($taskData['title'] ?? 'Task'), 'href' => 'task_view.php?id=' . $taskId, 'reused' => false];
        } catch (Throwable $e) {
            return ['id' => 0, 'label' => 'Task not created', 'href' => 'marketing.php', 'warning' => $e->getMessage()];
        }
    }

    private function findExistingQueueTask(array $metadata): ?array
    {
        if (!Database::tableExists('tasks') || !Database::columnExists('tasks', 'metadata_json')) {
            return null;
        }

        return Database::queryOne(
            "SELECT id, title
             FROM tasks
             WHERE workspace_id = ?
               AND status IN ('pending','in_progress')
               AND JSON_UNQUOTE(JSON_EXTRACT(COALESCE(metadata_json, '{}'), '$.source')) = 'marketing_queue_action'
               AND JSON_UNQUOTE(JSON_EXTRACT(COALESCE(metadata_json, '{}'), '$.action_surface')) = ?
               AND JSON_UNQUOTE(JSON_EXTRACT(COALESCE(metadata_json, '{}'), '$.action_key')) = ?
               AND CAST(JSON_UNQUOTE(JSON_EXTRACT(COALESCE(metadata_json, '{}'), '$.source_id')) AS UNSIGNED) = ?
             ORDER BY id DESC
             LIMIT 1",
            [
                $this->workspaceId(),
                (string) ($metadata['action_surface'] ?? ''),
                (string) ($metadata['action_key'] ?? ''),
                (int) ($metadata['source_id'] ?? 0),
            ]
        ) ?: null;
    }

    private function createOrReuseQueueAssetRequest(array $data): array
    {
        $metadata = (array) ($data['metadata_json'] ?? []);
        $existing = $this->findExistingQueueRow('marketing_asset_requests', 'content_item_id', (int) ($data['content_item_id'] ?? 0), $metadata);
        if ($existing) {
            return ['id' => (int) $existing['id'], 'label' => (string) ($existing['title'] ?? 'Asset request'), 'href' => 'marketing_creative.php', 'reused' => true];
        }

        if (!Database::tableExists('marketing_asset_requests')) {
            return ['id' => 0, 'label' => 'Asset request system unavailable', 'href' => 'marketing_creative.php', 'warning' => 'Asset requests are unavailable.'];
        }

        $id = $this->createAssetRequest($data);
        return ['id' => $id, 'label' => (string) ($data['title'] ?? 'Asset request'), 'href' => 'marketing_creative.php', 'reused' => false];
    }

    private function createOrReuseQueueMediaWorkItem(array $data): array
    {
        $metadata = (array) ($data['metadata_json'] ?? []);
        $linkColumn = !empty($data['landing_page_id']) ? 'landing_page_id' : 'content_item_id';
        $linkId = (int) ($data[$linkColumn] ?? 0);
        $existing = $this->findExistingQueueRow('marketing_media_production_work_items', $linkColumn, $linkId, $metadata);
        if ($existing) {
            return ['id' => (int) $existing['id'], 'label' => (string) ($existing['title'] ?? 'Media work'), 'href' => 'marketing_creative.php#media-production-workflow', 'reused' => true];
        }

        if (!Database::tableExists('marketing_media_production_work_items')) {
            return ['id' => 0, 'label' => 'Media production workflow unavailable', 'href' => 'marketing_creative.php', 'warning' => 'Media production workflow is unavailable.'];
        }

        $id = $this->createMediaProductionWorkItem($data);
        return ['id' => $id, 'label' => (string) ($data['title'] ?? 'Media work'), 'href' => 'marketing_creative.php#media-production-workflow', 'reused' => false];
    }

    private function findExistingQueueRow(string $table, string $linkColumn, int $linkId, array $metadata): ?array
    {
        if ($linkId <= 0 || !Database::tableExists($table) || !Database::columnExists($table, 'metadata_json') || !Database::columnExists($table, $linkColumn)) {
            return null;
        }

        $statusClause = $table === 'marketing_asset_requests'
            ? "status IN ('requested','in_progress')"
            : "status IN ('requested','assigned','in_progress','review','blocked')";

        return Database::queryOne(
            "SELECT id, title
             FROM {$table}
             WHERE workspace_id = ?
               AND {$linkColumn} = ?
               AND {$statusClause}
               AND JSON_UNQUOTE(JSON_EXTRACT(COALESCE(metadata_json, '{}'), '$.source')) = 'marketing_queue_action'
               AND JSON_UNQUOTE(JSON_EXTRACT(COALESCE(metadata_json, '{}'), '$.action_surface')) = ?
               AND JSON_UNQUOTE(JSON_EXTRACT(COALESCE(metadata_json, '{}'), '$.action_key')) = ?
               AND CAST(JSON_UNQUOTE(JSON_EXTRACT(COALESCE(metadata_json, '{}'), '$.source_id')) AS UNSIGNED) = ?
             ORDER BY id DESC
             LIMIT 1",
            [
                $this->workspaceId(),
                $linkId,
                (string) ($metadata['action_surface'] ?? ''),
                (string) ($metadata['action_key'] ?? ''),
                (int) ($metadata['source_id'] ?? 0),
            ]
        ) ?: null;
    }

    private function appendQueueActionReference(array &$result, array $reference, string $type): void
    {
        $reference['type'] = $type;
        if (!empty($reference['warning'])) {
            $result['warnings'][] = (string) $reference['warning'];
            return;
        }
        if (!empty($reference['reused'])) {
            $result['reused'][] = $reference;
            return;
        }
        if ((int) ($reference['id'] ?? 0) > 0) {
            $result['created'][] = $reference;
        }
    }

    public function getLandingPageBuilderChecklist(int $id): array
    {
        $page = $this->getLandingPage($id);
        if (!$page) {
            throw new RuntimeException('Marketing landing page not found.');
        }

        $publishingReadiness = $this->calculateLandingPagePublishingReadiness($page);
        $versions = $this->listLandingPageVersions($id);
        $publication = $this->getLandingPagePublication($id);
        $checks = [];
        $addCheck = static function (
            array &$checks,
            string $key,
            string $label,
            bool $complete,
            bool $required,
            string $message,
            string $href,
            string $category
        ): void {
            $checks[] = [
                'key' => $key,
                'label' => $label,
                'complete' => $complete,
                'required' => $required,
                'message' => $message,
                'href' => $href,
                'category' => $category,
            ];
        };
        $hasRows = static fn(mixed $value): bool => is_array($value) && $value !== [];
        $hasText = static fn(mixed $value): bool => trim((string) ($value ?? '')) !== '';
        $designDocument = is_array($page['design_document_json'] ?? null) ? $page['design_document_json'] : [];
        $hasDesignConversion = (string) ($designDocument['schema'] ?? '') === LandingPageDesignService::SCHEMA_VERSION
            && !empty((new LandingPageDesignService())->validateDocument($designDocument, $page)['valid']);
        $previewHref = 'marketing_landing_page_preview.php?token=' . urlencode((string) ($page['preview_token'] ?? ''));
        $editHref = 'marketing_landing_page_edit.php?id=' . (int) $id;

        $addCheck(
            $checks,
            'hero_media',
            'Hero media',
            is_array($page['_media']['hero'] ?? null),
            false,
            is_array($page['_media']['hero'] ?? null)
                ? 'Hero image or video is selected.'
                : 'Add a strong hero image or video so the page has an immediate visual anchor.',
            $editHref,
            'visuals'
        );
        $addCheck(
            $checks,
            'social_preview_media',
            'Social preview image',
            is_array($page['_media']['social_preview'] ?? null),
            false,
            is_array($page['_media']['social_preview'] ?? null)
                ? 'Social preview media is ready for manual sharing workflows.'
                : 'Select a social preview image for manual sharing and export bundles.',
            $editHref,
            'visuals'
        );
        $addCheck(
            $checks,
            'media_accessibility',
            'Media accessibility',
            empty(array_filter((array) ($publishingReadiness['media_warnings'] ?? []), static fn(string $warning): bool => str_contains($warning, 'alt_text') || str_contains($warning, 'caption_or_transcript'))),
            true,
            'Images need alt text and videos need a caption or transcript before the page is launch-ready.',
            $editHref,
            'visuals'
        );
        $addCheck(
            $checks,
            'seo_title',
            'SEO title',
            $hasText($page['seo_title'] ?? ''),
            true,
            $hasText($page['seo_title'] ?? '')
                ? 'SEO title is present.'
                : 'Add an SEO title so the page is clear in previews and reports.',
            $editHref,
            'copy'
        );
        $addCheck(
            $checks,
            'meta_description',
            'Meta description',
            $hasText($page['meta_description'] ?? ''),
            true,
            $hasText($page['meta_description'] ?? '')
                ? 'Meta description is present.'
                : 'Add a concise meta description for manual publishing and social previews.',
            $editHref,
            'copy'
        );
        $addCheck(
            $checks,
            'cta_blocks',
            'Conversion action',
            $hasRows($page['cta_blocks_json'] ?? []) || $hasDesignConversion,
            true,
            $hasRows($page['cta_blocks_json'] ?? []) || $hasDesignConversion
                ? 'A safe conversion action is connected.'
                : 'Add a CTA, CRM form, booking, or WhatsApp block with the next action.',
            $editHref,
            'conversion'
        );
        $addCheck(
            $checks,
            'proof_blocks',
            'Proof blocks',
            $hasRows($page['proof_blocks_json'] ?? []),
            false,
            $hasRows($page['proof_blocks_json'] ?? [])
                ? 'Proof is planned.'
                : 'Add proof, testimonial, or result blocks to strengthen conversion confidence.',
            $editHref,
            'conversion'
        );
        $addCheck(
            $checks,
            'faq_blocks',
            'FAQ blocks',
            $hasRows($page['faq_blocks_json'] ?? []),
            false,
            $hasRows($page['faq_blocks_json'] ?? [])
                ? 'FAQ objections are covered.'
                : 'Add FAQ blocks for buyer objections and sales follow-up context.',
            $editHref,
            'conversion'
        );
        $addCheck(
            $checks,
            'form_placement',
            'Form placement',
            ((int) ($page['form_id'] ?? 0) > 0) || $hasRows($page['form_blocks_json'] ?? []),
            true,
            ((int) ($page['form_id'] ?? 0) > 0) || $hasRows($page['form_blocks_json'] ?? [])
                ? 'Form destination or placement plan exists.'
                : 'Link a form or add a form placement block so conversion handoff is clear.',
            $editHref,
            'conversion'
        );
        $addCheck(
            $checks,
            'conversion_goal',
            'Conversion goal',
            $hasText($page['conversion_goal'] ?? ''),
            true,
            'Define the conversion goal used by reports and manual launch checks.',
            $editHref,
            'conversion'
        );
        $addCheck(
            $checks,
            'draft_version',
            'Draft snapshot',
            ((int) ($page['draft_version_id'] ?? 0) > 0) || $versions !== [],
            true,
            'A draft version snapshot gives the team a rollback and audit point.',
            $editHref,
            'governance'
        );
        $addCheck(
            $checks,
            'preview_token',
            'Authenticated preview',
            $hasText($page['preview_token'] ?? ''),
            true,
            $hasText($page['preview_token'] ?? '')
                ? 'Authenticated preview is available.'
                : 'Generate a preview token before internal review.',
            $previewHref,
            'governance'
        );

        $complete = count(array_filter($checks, static fn(array $check): bool => (bool) ($check['complete'] ?? false)));
        $requiredMissing = array_values(array_filter($checks, static fn(array $check): bool => !($check['complete'] ?? false) && (bool) ($check['required'] ?? false)));
        $recommendedMissing = array_values(array_filter($checks, static fn(array $check): bool => !($check['complete'] ?? false) && !(bool) ($check['required'] ?? false)));
        $nextActions = [];
        foreach (array_merge($requiredMissing, $recommendedMissing) as $check) {
            $nextActions[] = [
                'label' => (string) ($check['label'] ?? 'Complete item'),
                'href' => (string) ($check['href'] ?? $editHref),
                'reason' => (string) ($check['message'] ?? ''),
                'priority' => !empty($check['required']) ? 'high' : 'medium',
            ];
            if (count($nextActions) >= 5) {
                break;
            }
        }

        return [
            'score' => $checks === [] ? 0 : (int) round(($complete / count($checks)) * 100),
            'checks' => $checks,
            'required_missing' => $requiredMissing,
            'recommended_missing' => $recommendedMissing,
            'next_actions' => $nextActions,
            'preview_links' => [
                'desktop' => $previewHref . '&viewport=desktop',
                'mobile' => $previewHref . '&viewport=mobile',
            ],
            'publication_status' => (string) ($publication['status'] ?? 'unpublished'),
            'guardrails' => [
                'Authenticated preview is for internal review only.',
                'Publishing remains tokenized and manual-first.',
                'No external hosting, email, social, ad, or SEO API is triggered from this checklist.',
            ],
        ];
    }

    public function listLandingPageSections(array $filters = [], int $limit = 100, int $offset = 0): array
    {
        if (!Database::tableExists('marketing_landing_page_sections')) {
            return [];
        }

        $limit = min(max($limit, 1), 250);
        $offset = max($offset, 0);
        $workspace = $this->workspaceClause('s.');
        $where = [$workspace['sql']];
        $params = $workspace['params'];
        if (!empty($filters['section_type'])) {
            $where[] = 's.section_type = ?';
            $params[] = $this->normalizeEnum((string) $filters['section_type'], self::LANDING_SECTION_TYPES, 'landing_section_type');
        }
        if (!empty($filters['status'])) {
            $where[] = 's.status = ?';
            $params[] = $this->normalizeEnum((string) $filters['status'], self::LANDING_SECTION_STATUSES, 'landing_section_status');
        } elseif (!empty($filters['exclude_archived'])) {
            $where[] = "s.status <> 'archived'";
        }
        if (!empty($filters['id'])) {
            $where[] = 's.id = ?';
            $params[] = (int) $filters['id'];
        }

        return array_map(
            fn(array $row): array => $this->hydrateJsonFields($row, ['content_json', 'media_json', 'theme_json']),
            Database::query(
                "SELECT s.*, creator.email AS created_by_email
                 FROM marketing_landing_page_sections s
                 LEFT JOIN users creator ON creator.id = s.created_by
                 WHERE " . implode(' AND ', $where) . "
                 ORDER BY s.updated_at DESC, s.title ASC
                 LIMIT {$limit} OFFSET {$offset}",
                $params
            )
        );
    }

    public function createLandingPageSection(array $data): int
    {
        $this->assertMarketingDesignPermission('marketing.write');
        $normalized = $this->normalizeLandingPageSectionData($data, true);
        Database::execute(
            "INSERT INTO marketing_landing_page_sections
             (workspace_id, uuid, title, section_type, content_json, media_json, theme_json, status, created_by)
             VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)",
            [
                $this->workspaceId(),
                $this->generateUuid(),
                $normalized['title'],
                $normalized['section_type'],
                $normalized['content_json'],
                $normalized['media_json'],
                $normalized['theme_json'],
                $normalized['status'],
                $normalized['created_by'],
            ]
        );

        return (int) Database::lastInsertId();
    }

    public function updateLandingPageSection(int $id, array $data): bool
    {
        $this->assertMarketingDesignPermission('marketing.write');
        $this->assertWorkspaceRecord('marketing_landing_page_sections', $id, $this->workspaceId());

        return $this->updateById('marketing_landing_page_sections', $id, $this->normalizeLandingPageSectionData($data, false));
    }

    public function listLandingPageVersions(int $landingPageId): array
    {
        if (!Database::tableExists('marketing_landing_page_versions')) {
            return [];
        }
        $this->assertWorkspaceRecord('marketing_landing_pages', $landingPageId, $this->workspaceId());

        return array_map(
            fn(array $row): array => $this->hydrateJsonFields($row, ['snapshot_json']),
            Database::query(
                "SELECT v.*, creator.email AS created_by_email
                 FROM marketing_landing_page_versions v
                 LEFT JOIN users creator ON creator.id = v.created_by
                 WHERE v.workspace_id = ? AND v.landing_page_id = ?
                 ORDER BY v.created_at DESC, v.id DESC",
                [$this->workspaceId(), $landingPageId]
            )
        );
    }

    public function createLandingPageVersion(int $landingPageId, string $versionType = 'draft', ?int $userId = null): array
    {
        $this->assertMarketingDesignPermission($versionType === 'published' ? 'marketing.manage' : 'marketing.write');
        $page = $this->getLandingPage($landingPageId);
        if (!$page) {
            throw new RuntimeException('Marketing landing page not found.');
        }
        $versionType = $this->normalizeEnum($versionType, self::LANDING_VERSION_TYPES, 'landing_version_type');
        $row = Database::queryOne(
            'SELECT COALESCE(MAX(version_number), 0) + 1 AS next_version FROM marketing_landing_page_versions WHERE workspace_id = ? AND landing_page_id = ? AND version_type = ?',
            [$this->workspaceId(), $landingPageId, $versionType]
        );
        $next = (int) ($row['next_version'] ?? 1);
        $snapshot = $this->landingPageSnapshot($page);
        Database::execute(
            "INSERT INTO marketing_landing_page_versions
             (workspace_id, landing_page_id, uuid, version_type, version_number, title, slug, snapshot_json, created_by)
             VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)",
            [
                $this->workspaceId(),
                $landingPageId,
                $this->generateUuid(),
                $versionType,
                $next,
                (string) $page['title'],
                (string) $page['slug'],
                $this->normalizeJsonValue($snapshot),
                ($userId ?? $this->currentUserId()) ?: null,
            ]
        );
        $versionId = (int) Database::lastInsertId();
        Database::execute(
            'UPDATE marketing_landing_pages SET ' . ($versionType === 'published' ? 'published_version_id' : 'draft_version_id') . ' = ? WHERE workspace_id = ? AND id = ?',
            [$versionId, $this->workspaceId(), $landingPageId]
        );

        return $this->hydrateJsonFields(Database::queryOne(
            'SELECT * FROM marketing_landing_page_versions WHERE workspace_id = ? AND id = ?',
            [$this->workspaceId(), $versionId]
        ) ?: [], ['snapshot_json']);
    }

    public function generateLandingPageCopyDraft(array $data): array
    {
        $this->assertMarketingDesignPermission('marketing.write');

        $inputs = [
            'title' => trim((string) ($data['title'] ?? '')),
            'headline' => trim((string) ($data['headline'] ?? '')),
            'seo_title' => trim((string) ($data['seo_title'] ?? '')),
            'meta_description' => trim((string) ($data['meta_description'] ?? '')),
            'conversion_goal' => trim((string) ($data['conversion_goal'] ?? 'lead_capture')),
            'body_sections' => $this->normalizeAiSectionBlocks($data['body_sections'] ?? $data['body_sections_json'] ?? []),
            'cta_blocks' => $this->normalizeAiSectionBlocks($data['cta_blocks'] ?? $data['cta_blocks_json'] ?? []),
            'proof_blocks' => $this->normalizeAiSectionBlocks($data['proof_blocks'] ?? $data['proof_blocks_json'] ?? []),
            'faq_blocks' => $this->normalizeAiSectionBlocks($data['faq_blocks'] ?? $data['faq_blocks_json'] ?? []),
            'thank_you_copy' => trim((string) ($data['thank_you_copy'] ?? '')),
            'campaign_id' => (int) ($data['campaign_id'] ?? 0),
            'form_id' => (int) ($data['form_id'] ?? 0),
            'hero_media_file_id' => (int) ($data['hero_media_file_id'] ?? 0),
            'social_preview_media_file_id' => (int) ($data['social_preview_media_file_id'] ?? 0),
            'cta_media_file_id' => (int) ($data['cta_media_file_id'] ?? 0),
            'proof_media_file_id' => (int) ($data['proof_media_file_id'] ?? 0),
            'testimonial_media_file_id' => (int) ($data['testimonial_media_file_id'] ?? 0),
        ];
        $linkedRecords = $this->buildLandingPageLinkedRecords($inputs);
        $mediaRecommendations = $this->landingPageMediaRecommendations($inputs, $linkedRecords);
        $fallback = $this->fallbackLandingPageCopyDraft($inputs, $linkedRecords);
        $bundle = $this->buildMarketingContextBundle('landing_page_copy', $inputs, $linkedRecords);
        $aiResult = $this->runMarketingAiPrompt(
            'landing_page_copy',
            $bundle,
            $inputs,
            'marketing_landing_page_copy',
            fn(): array => $fallback,
            true
        );
        $structured = $this->normalizeGeneratedLandingPageFields((array) ($aiResult['json'] ?? []), $fallback);

        return [
            'fields' => [
                'headline' => $structured['headline'],
                'seo_title' => $structured['seo_title'],
                'meta_description' => $structured['meta_description'],
                'body_sections' => $this->formatAiSectionBlocksForForm($structured['body_sections']),
                'cta_blocks' => $this->formatAiSectionBlocksForForm($structured['cta_blocks']),
                'proof_blocks' => $this->formatAiSectionBlocksForForm($structured['proof_blocks']),
                'faq_blocks' => $this->formatAiSectionBlocksForForm($structured['faq_blocks']),
                'thank_you_copy' => $structured['thank_you_copy'],
            ],
            'structured_fields' => $structured,
            'ai_context' => [
                'generated_at' => date('c'),
                'prompt_key' => 'landing_page_copy',
                'prompt_version' => (int) ($aiResult['provider']['prompt_version'] ?? 0),
                'context_score' => (float) ($bundle['bundle_quality']['context_quality_score'] ?? 0),
                'provider' => $aiResult['provider'],
                'context_bundle' => $bundle,
                'media_recommendations' => $mediaRecommendations,
            ],
        ];
    }

    public function getContentMediaPlacementGuidance(array $data): array
    {
        $this->assertMarketingPermission('marketing.read');

        $contentId = (int) ($data['content_item_id'] ?? $data['id'] ?? 0);
        $item = [];
        $attachments = [];
        if ($contentId > 0) {
            $item = $this->getContentItem($contentId) ?: [];
            if ($item === []) {
                throw new RuntimeException('Marketing content item not found.');
            }
            $attachments = $this->listContentMedia($contentId);
        }
        $item = array_merge($item, [
            'content_type' => (string) ($data['content_type'] ?? $item['content_type'] ?? ''),
            'channel' => (string) ($data['channel'] ?? $item['channel'] ?? ''),
            'objective' => (string) ($data['objective'] ?? $item['objective'] ?? ''),
            'target_audience' => (string) ($data['target_audience'] ?? $item['target_audience'] ?? ''),
        ]);

        if ($attachments === [] && !empty($data['media_attachments'])) {
            $entries = $this->normalizeContentMediaEntries($data['media_attachments']);
            $mediaRows = $this->mediaRowsById($this->workspaceId(), array_column($entries, 'media_file_id'));
            foreach ($entries as $entry) {
                $media = $mediaRows[(int) ($entry['media_file_id'] ?? 0)] ?? [];
                if ($media === []) {
                    continue;
                }
                $attachments[] = $entry + [
                    'media_title' => (string) ($media['title'] ?? ''),
                    'media_type' => (string) ($media['media_type'] ?? ''),
                    'approval_status' => (string) ($media['approval_status'] ?? ''),
                    'license_status' => (string) ($media['license_status'] ?? ''),
                    'effective_alt_text' => trim((string) ($entry['alt_text_override'] ?? '')) ?: (string) ($media['alt_text'] ?? ''),
                    'effective_caption' => trim((string) ($entry['caption'] ?? '')) ?: (string) ($media['caption'] ?? ''),
                    'media_transcript' => (string) ($media['transcript'] ?? ''),
                ];
            }
        }

        $readiness = $this->contentMediaReadiness($item, $attachments);
        $recommendedRoles = $this->recommendedContentMediaRoles((string) ($item['content_type'] ?? ''), (string) ($item['channel'] ?? ''));
        $availableMedia = $this->rankMediaForPlacement($this->listMediaFiles([], 100, 0), $recommendedRoles);

        return [
            'target_type' => 'content',
            'content_item_id' => $contentId > 0 ? $contentId : null,
            'recommended_roles' => $recommendedRoles,
            'warnings' => (array) ($readiness['warnings'] ?? []),
            'recommendations' => $this->contentMediaWarningMessages((array) ($readiness['warnings'] ?? []), $recommendedRoles),
            'suggested_media' => array_slice($availableMedia, 0, 8),
            'context' => [
                'content_type' => (string) ($item['content_type'] ?? ''),
                'channel' => (string) ($item['channel'] ?? ''),
                'objective' => (string) ($item['objective'] ?? ''),
                'target_audience' => (string) ($item['target_audience'] ?? ''),
                'attachment_count' => count($attachments),
                'available_media_count' => count($availableMedia),
                'approved_media_count' => count(array_filter($availableMedia, static fn(array $media): bool => (string) ($media['approval_status'] ?? '') === 'approved')),
                'manual_first' => true,
            ],
        ];
    }

    public function getLandingPageMediaPlacementGuidance(array $data): array
    {
        $this->assertMarketingDesignPermission('marketing.read');

        $inputs = [
            'title' => trim((string) ($data['title'] ?? '')),
            'headline' => trim((string) ($data['headline'] ?? '')),
            'conversion_goal' => trim((string) ($data['conversion_goal'] ?? 'lead_capture')),
            'campaign_id' => (int) ($data['campaign_id'] ?? 0),
            'form_id' => (int) ($data['form_id'] ?? 0),
            'hero_media_file_id' => (int) ($data['hero_media_file_id'] ?? 0),
            'social_preview_media_file_id' => (int) ($data['social_preview_media_file_id'] ?? 0),
            'cta_media_file_id' => (int) ($data['cta_media_file_id'] ?? 0),
            'proof_media_file_id' => (int) ($data['proof_media_file_id'] ?? 0),
            'testimonial_media_file_id' => (int) ($data['testimonial_media_file_id'] ?? 0),
        ];
        $linkedRecords = $this->buildLandingPageLinkedRecords($inputs);
        $recommendations = $this->landingPageMediaRecommendations($inputs, $linkedRecords);
        $availableMedia = $this->rankMediaForPlacement($this->listMediaFiles([], 100, 0), ['hero', 'social_preview', 'proof', 'cta', 'gallery']);

        return [
            'target_type' => 'landing_page',
            'recommended_slots' => [
                'hero_media_file_id' => 'Hero image/video',
                'social_preview_media_file_id' => 'Social preview image',
                'proof_media_file_id' => 'Proof media',
                'testimonial_media_file_id' => 'Testimonial video',
                'cta_media_file_id' => 'CTA support media',
                'gallery_media_ids' => 'Gallery strip',
            ],
            'recommendations' => $recommendations,
            'suggested_media' => array_slice($availableMedia, 0, 8),
            'context' => [
                'title' => $inputs['title'],
                'headline' => $inputs['headline'],
                'conversion_goal' => $inputs['conversion_goal'],
                'selected_media_count' => count((array) ($linkedRecords['media'] ?? [])),
                'available_media_count' => count($availableMedia),
                'approved_media_count' => count(array_filter($availableMedia, static fn(array $media): bool => (string) ($media['approval_status'] ?? '') === 'approved')),
                'manual_first' => true,
            ],
        ];
    }

    public function listLandingPagePublications(array $filters = [], int $limit = 100, int $offset = 0): array
    {
        if (!Database::tableExists('marketing_landing_page_publications')) {
            return [];
        }

        $limit = min(max($limit, 1), 250);
        $offset = max($offset, 0);
        $workspace = $this->workspaceClause('pub.');
        $where = [$workspace['sql']];
        $params = $workspace['params'];
        if (!empty($filters['status'])) {
            $where[] = 'pub.status = ?';
            $params[] = $this->normalizeEnum((string) $filters['status'], self::LANDING_PUBLICATION_STATUSES, 'publication_status');
        }
        if (!empty($filters['landing_page_id'])) {
            $where[] = 'pub.landing_page_id = ?';
            $params[] = (int) $filters['landing_page_id'];
        }

        return array_map(
            fn(array $row): array => $this->hydrateJsonFields($row, ['readiness_json', 'metadata_json']),
            Database::query(
                "SELECT pub.*, lp.title AS landing_page_title, lp.headline, lp.status AS landing_page_status,
                        f.name AS form_name, c.name AS campaign_name, creator.email AS created_by_email
                 FROM marketing_landing_page_publications pub
                 JOIN marketing_landing_pages lp ON lp.id = pub.landing_page_id AND lp.workspace_id = pub.workspace_id
                 LEFT JOIN forms f ON f.id = lp.form_id AND f.workspace_id = lp.workspace_id
                 LEFT JOIN campaigns c ON c.id = lp.campaign_id AND c.workspace_id = lp.workspace_id
                 LEFT JOIN users creator ON creator.id = pub.created_by
                 WHERE " . implode(' AND ', $where) . "
                 ORDER BY pub.published_at DESC, pub.updated_at DESC
                 LIMIT {$limit} OFFSET {$offset}",
                $params
            )
        );
    }

    public function getLandingPagePublication(int $landingPageId): ?array
    {
        $this->assertWorkspaceRecord('marketing_landing_pages', $landingPageId, $this->workspaceId());
        $rows = $this->listLandingPagePublications(['landing_page_id' => $landingPageId], 1, 0);
        return $rows[0] ?? null;
    }

    public function publishLandingPage(int $landingPageId, ?int $userId = null): array
    {
        $this->assertMarketingDesignPermission('marketing.manage');
        $page = $this->getLandingPage($landingPageId);
        if (!$page) {
            throw new RuntimeException('Marketing landing page not found.');
        }

        $design = new LandingPageDesignService();
        $designDocument = $design->normalizeDocument((array) ($page['design_document_json'] ?? []), $page);
        $designValidation = $design->validateDocument($designDocument, $page);
        if (empty($designValidation['valid'])) {
            throw new RuntimeException('Landing page design is not ready to publish: ' . implode(', ', (array) ($designValidation['errors'] ?? [])));
        }

        $hasVersionedDesign = (string) (($page['design_document_json']['schema'] ?? '')) === LandingPageDesignService::SCHEMA_VERSION;
        $templateKey = trim((string) ($designDocument['metadata']['template_key'] ?? ''));
        $hasStudioTemplate = $templateKey !== '' && $templateKey !== 'legacy_migration';
        $shouldApproveOnPublish = $hasVersionedDesign && $hasStudioTemplate && (string) ($page['status'] ?? '') !== 'approved';
        $pageForReadiness = $page;
        if ($shouldApproveOnPublish) {
            // Publishing is the explicit approval action in Design Studio. Legacy
            // landing pages keep their separate approval workflow below.
            $pageForReadiness['status'] = 'approved';
        }

        $readiness = $this->calculateLandingPagePublishingReadiness($pageForReadiness);
        if (!empty($readiness['missing'])) {
            throw new RuntimeException('Landing page is not ready to publish: ' . implode(', ', array_map(static fn(string $value): string => str_replace('_', ' ', $value), $readiness['missing'])));
        }

        $actorId = $userId ?? $this->currentUserId();
        Database::beginTransaction();
        try {
            if ($shouldApproveOnPublish) {
                Database::execute(
                    "UPDATE marketing_landing_pages SET status = 'approved' WHERE workspace_id = ? AND id = ?",
                    [$this->workspaceId(), $landingPageId]
                );
                $page['status'] = 'approved';
            }

            $existing = $this->getLandingPagePublication($landingPageId);
            $token = (string) ($existing['public_token'] ?? '');
            if ($token === '') {
                $token = $this->generatePreviewToken();
            }
            $publicUrl = 'marketing_landing_public.php?token=' . rawurlencode($token);

            if ($existing) {
                Database::execute(
                    "UPDATE marketing_landing_page_publications
                     SET slug = ?, public_token = ?, public_url = ?, status = 'published',
                         conversion_goal = ?, readiness_score = ?, readiness_json = ?,
                         published_at = COALESCE(published_at, NOW()), unpublished_at = NULL,
                         metadata_json = ?, created_by = COALESCE(created_by, ?)
                     WHERE workspace_id = ? AND landing_page_id = ?",
                    [
                        (string) $page['slug'],
                        $token,
                        $publicUrl,
                        (string) ($page['conversion_goal'] ?? 'lead_capture'),
                        (int) $readiness['score'],
                        $this->normalizeJsonValue($readiness),
                        $this->normalizeJsonValue(['published_from' => 'marketing_landing_page_view', 'updated_at' => date('c')]),
                        $actorId > 0 ? $actorId : null,
                        $this->workspaceId(),
                        $landingPageId,
                    ]
                );
            } else {
                Database::execute(
                    "INSERT INTO marketing_landing_page_publications
                     (workspace_id, landing_page_id, uuid, slug, public_token, public_url, status, conversion_goal,
                      readiness_score, readiness_json, metadata_json, published_at, created_by)
                     VALUES (?, ?, ?, ?, ?, ?, 'published', ?, ?, ?, ?, NOW(), ?)",
                    [
                        $this->workspaceId(),
                        $landingPageId,
                        $this->generateUuid(),
                        (string) $page['slug'],
                        $token,
                        $publicUrl,
                        (string) ($page['conversion_goal'] ?? 'lead_capture'),
                        (int) $readiness['score'],
                        $this->normalizeJsonValue($readiness),
                        $this->normalizeJsonValue(['published_from' => 'marketing_landing_page_view']),
                        $actorId > 0 ? $actorId : null,
                    ]
                );
            }

            $version = $this->createLandingPageVersion($landingPageId, 'published', $actorId > 0 ? $actorId : null);
            Database::execute(
                "UPDATE marketing_landing_pages
                 SET builder_status = 'published', published_version_id = ?
                 WHERE workspace_id = ? AND id = ?",
                [(int) ($version['id'] ?? 0), $this->workspaceId(), $landingPageId]
            );

            if ($templateKey !== '' && $templateKey !== 'legacy_migration') {
                $this->recordDesignTemplateEvent(
                    $landingPageId,
                    $templateKey,
                    (string) ($designDocument['metadata']['template_version'] ?? '1.0.0'),
                    'published',
                    $actorId > 0 ? $actorId : null
                );
            }
            Database::commit();
        } catch (Throwable $e) {
            Database::rollBack();
            throw $e;
        }

        return $this->getLandingPagePublication($landingPageId) ?? [];
    }

    public function unpublishLandingPage(int $landingPageId, ?int $userId = null): bool
    {
        $this->assertMarketingDesignPermission('marketing.manage');
        $publication = $this->getLandingPagePublication($landingPageId);
        if (!$publication) {
            throw new RuntimeException('Marketing landing page publication not found.');
        }

        Database::execute(
            "UPDATE marketing_landing_page_publications
             SET status = 'unpublished',
                 unpublished_at = NOW(),
                 metadata_json = ?
             WHERE workspace_id = ? AND landing_page_id = ?",
            [
                $this->normalizeJsonValue(['unpublished_by' => $userId ?? $this->currentUserId(), 'unpublished_at' => date('c')]),
                $this->workspaceId(),
                $landingPageId,
            ]
        );

        return true;
    }

    public function getPublishedLandingPageByToken(string $token): ?array
    {
        $token = preg_replace('/[^a-zA-Z0-9]/', '', $token) ?: '';
        if ($token === '' || !Database::tableExists('marketing_landing_page_publications')) {
            return null;
        }

        $row = Database::queryOne(
            "SELECT lp.*, pub.public_token, pub.public_url, pub.status AS publication_status,
                    pub.published_at AS publication_published_at, pub.conversion_goal AS publication_conversion_goal,
                    pub.readiness_json AS publication_readiness_json,
                    f.name AS form_name, f.uuid AS form_uuid, f.design_status AS form_design_status,
                    f.published_revision AS form_published_revision, c.name AS campaign_name
             FROM marketing_landing_page_publications pub
             JOIN marketing_landing_pages lp ON lp.id = pub.landing_page_id AND lp.workspace_id = pub.workspace_id
             LEFT JOIN forms f ON f.id = lp.form_id AND f.workspace_id = lp.workspace_id
             LEFT JOIN campaigns c ON c.id = lp.campaign_id AND c.workspace_id = lp.workspace_id
             WHERE pub.public_token = ? AND pub.status = 'published'
             LIMIT 1",
            [$token]
        );

        if (!$row) {
            return null;
        }

        $publishedVersionId = (int) ($row['published_version_id'] ?? 0);
        if ($publishedVersionId > 0) {
            $version = Database::queryOne(
                "SELECT snapshot_json
                 FROM marketing_landing_page_versions
                 WHERE workspace_id = ? AND landing_page_id = ? AND id = ? AND version_type = 'published'
                 LIMIT 1",
                [(int) $row['workspace_id'], (int) $row['id'], $publishedVersionId]
            );
            $snapshot = $version ? json_decode((string) ($version['snapshot_json'] ?? ''), true) : null;
            if (is_array($snapshot)) {
                foreach ($snapshot as $field => $value) {
                    if (in_array($field, ['id', 'workspace_id', 'public_token', 'publication_status'], true)) {
                        continue;
                    }
                    $row[$field] = is_array($value)
                        ? (json_encode($value, JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE) ?: '[]')
                        : $value;
                }
            }
        }

        $publishedFormId = (int) ($row['form_id'] ?? 0);
        if ($publishedFormId > 0) {
            $publishedForm = Database::queryOne(
                'SELECT uuid, name FROM forms WHERE workspace_id = ? AND id = ? LIMIT 1',
                [(int) $row['workspace_id'], $publishedFormId]
            );
            $row['form_uuid'] = (string) ($publishedForm['uuid'] ?? '');
            $row['form_name'] = (string) ($publishedForm['name'] ?? '');
        } else {
            $row['form_uuid'] = '';
            $row['form_name'] = '';
        }

        return $this->hydrateLandingPageRow($row);
    }

    public function recordMarketingTrackingEvent(array $data): array
    {
        if (!Database::tableExists('marketing_tracking_events') || !Database::tableExists('marketing_visitor_sessions')) {
            throw new RuntimeException('Marketing tracking is unavailable.');
        }

        $token = preg_replace('/[^a-zA-Z0-9]/', '', (string) ($data['public_token'] ?? $data['token'] ?? '')) ?: '';
        $page = $token !== '' ? $this->getPublishedLandingPageByToken($token) : null;
        if (!$page) {
            throw new RuntimeException('Published marketing landing page was not found.');
        }

        $workspaceId = (int) ($page['workspace_id'] ?? 0);
        $landingPageId = (int) ($page['id'] ?? 0);
        if ($workspaceId <= 0 || $landingPageId <= 0) {
            throw new RuntimeException('Published marketing landing page is not trackable.');
        }

        $eventType = $this->normalizeEnum((string) ($data['event_type'] ?? 'page_view'), self::TRACKING_EVENT_TYPES, 'tracking_event_type');
        $eventName = Security::sanitizeInput((string) ($data['event_name'] ?? str_replace('_', ' ', $eventType)), 'string');
        if ($eventName === '') {
            $eventName = str_replace('_', ' ', $eventType);
        }
        $pageUrl = $this->sanitizeTrackingUrl((string) ($data['page_url'] ?? $data['url'] ?? ''));
        $referrer = $this->sanitizeTrackingUrl((string) ($data['referrer'] ?? ''));
        $utm = $this->trackingUtmParams($data, $pageUrl);
        $sessionKey = $this->normalizeTrackingSessionKey((string) ($data['session_key'] ?? $data['visitor_id'] ?? ''));
        $visitorSessionId = $this->upsertMarketingVisitorSession($workspaceId, $landingPageId, $sessionKey, $utm, [
            'ip_address' => (string) ($data['ip_address'] ?? ''),
            'user_agent' => (string) ($data['user_agent'] ?? ''),
            'referrer' => $referrer,
        ]);
        $utmLinkId = $this->resolveTrackingUtmLinkId($workspaceId, $utm, $pageUrl);
        $campaignId = (int) ($page['campaign_id'] ?? 0);
        $contentItemId = (int) ($data['content_item_id'] ?? 0);
        if ($contentItemId > 0) {
            $this->assertWorkspaceRecord('marketing_content_items', $contentItemId, $workspaceId);
        }
        $formId = (int) ($data['form_id'] ?? $page['form_id'] ?? 0);
        if ($formId > 0) {
            $this->assertWorkspaceRecord('forms', $formId, $workspaceId);
        }
        $occurredAt = $this->normalizeTrackingOccurredAt((string) ($data['occurred_at'] ?? ''));
        $metadata = $this->sanitizeFlexibleArray($data['metadata'] ?? []);
        $metadata['source'] = 'marketing_tracking_foundation';
        $metadata['manual_first_boundary'] = true;

        Database::execute(
            "INSERT INTO marketing_tracking_events
             (workspace_id, visitor_session_id, landing_page_id, campaign_id, content_item_id, form_id, utm_link_id,
              uuid, event_type, event_name, page_url, referrer, utm_source, utm_medium, utm_campaign, utm_term,
              utm_content, metadata_json, occurred_at)
             VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)",
            [
                $workspaceId,
                $visitorSessionId,
                $landingPageId,
                $campaignId > 0 ? $campaignId : null,
                $contentItemId > 0 ? $contentItemId : null,
                $formId > 0 ? $formId : null,
                $utmLinkId > 0 ? $utmLinkId : null,
                $this->generateUuid(),
                $eventType,
                mb_substr($eventName, 0, 160),
                $pageUrl !== '' ? $pageUrl : null,
                $referrer !== '' ? $referrer : null,
                $utm['utm_source'] ?? null,
                $utm['utm_medium'] ?? null,
                $utm['utm_campaign'] ?? null,
                $utm['utm_term'] ?? null,
                $utm['utm_content'] ?? null,
                $this->normalizeJsonValue($metadata),
                $occurredAt,
            ]
        );
        $eventId = (int) Database::lastInsertId();

        if ($eventType === 'page_view') {
            $this->recordLandingPageView($workspaceId, $landingPageId, $visitorSessionId, $eventId, $token, $pageUrl, $referrer, $occurredAt);
        }
        if ($eventType === 'cta_click') {
            $this->recordCtaClick($workspaceId, $landingPageId, $visitorSessionId, $eventId, $data, $occurredAt);
        }
        $conversionEventId = null;
        if (in_array($eventType, ['conversion', 'form_submit'], true)) {
            $conversionEventId = $this->recordConversionEvent($workspaceId, $landingPageId, $visitorSessionId, $eventId, $formId, $data, $occurredAt);
        }
        $this->recordAttributionForTrackingEvent(
            $workspaceId,
            $landingPageId,
            $visitorSessionId,
            $eventId,
            $campaignId,
            $contentItemId,
            $formId,
            $utmLinkId,
            $eventType,
            $utm,
            $data,
            $occurredAt
        );
        if ($conversionEventId !== null && $conversionEventId > 0) {
            $this->createLeadHandoffFromConversionEvent($conversionEventId, $data);
        }

        return [
            'event_id' => $eventId,
            'conversion_event_id' => $conversionEventId,
            'visitor_session_id' => $visitorSessionId,
            'landing_page_id' => $landingPageId,
            'workspace_id' => $workspaceId,
            'event_type' => $eventType,
            'session_key' => $sessionKey,
        ];
    }

    public function getMarketingTrackingSummary(?int $landingPageId = null): array
    {
        if (!Database::tableExists('marketing_tracking_events')) {
            return [
                'page_views' => 0,
                'cta_clicks' => 0,
                'conversions' => 0,
                'unique_sessions' => 0,
                'conversion_rate' => null,
                'top_landing_pages' => [],
                'by_source' => [],
            ];
        }

        $workspaceId = $this->workspaceId();
        $params = [$workspaceId];
        $landingFilter = '';
        if (($landingPageId ?? 0) > 0) {
            $this->assertWorkspaceRecord('marketing_landing_pages', (int) $landingPageId, $workspaceId);
            $landingFilter = ' AND landing_page_id = ?';
            $params[] = (int) $landingPageId;
        }

        $pageViews = Database::tableExists('marketing_landing_page_views')
            ? (int) (Database::queryOne(
                "SELECT COUNT(*) AS count FROM marketing_landing_page_views WHERE workspace_id = ?{$landingFilter}",
                $params
            )['count'] ?? 0)
            : 0;
        $ctaClicks = Database::tableExists('marketing_cta_clicks')
            ? (int) (Database::queryOne(
                "SELECT COUNT(*) AS count FROM marketing_cta_clicks WHERE workspace_id = ?{$landingFilter}",
                $params
            )['count'] ?? 0)
            : 0;
        $conversions = Database::tableExists('marketing_conversion_events')
            ? (int) (Database::queryOne(
                "SELECT COUNT(*) AS count FROM marketing_conversion_events WHERE workspace_id = ?{$landingFilter}",
                $params
            )['count'] ?? 0)
            : 0;
        $sessions = (int) (Database::queryOne(
            "SELECT COUNT(DISTINCT visitor_session_id) AS count FROM marketing_tracking_events WHERE workspace_id = ?{$landingFilter}",
            $params
        )['count'] ?? 0);

        $topPages = Database::tableExists('marketing_landing_page_views')
            ? Database::query(
                "SELECT lp.id, lp.title, COUNT(v.id) AS view_count,
                        (SELECT COUNT(*) FROM marketing_cta_clicks c WHERE c.workspace_id = v.workspace_id AND c.landing_page_id = v.landing_page_id) AS click_count,
                        (SELECT COUNT(*) FROM marketing_conversion_events ce WHERE ce.workspace_id = v.workspace_id AND ce.landing_page_id = v.landing_page_id) AS conversion_count
                 FROM marketing_landing_page_views v
                 JOIN marketing_landing_pages lp ON lp.id = v.landing_page_id AND lp.workspace_id = v.workspace_id
                 WHERE v.workspace_id = ?" . (($landingPageId ?? 0) > 0 ? ' AND v.landing_page_id = ?' : '') . "
                 GROUP BY lp.id, lp.title, v.workspace_id, v.landing_page_id
                 ORDER BY view_count DESC
                 LIMIT 8",
                ($landingPageId ?? 0) > 0 ? [$workspaceId, (int) $landingPageId] : [$workspaceId]
            )
            : [];
        $bySource = Database::query(
            "SELECT COALESCE(NULLIF(utm_source, ''), 'direct') AS source, COUNT(*) AS event_count
             FROM marketing_tracking_events
             WHERE workspace_id = ?{$landingFilter}
             GROUP BY COALESCE(NULLIF(utm_source, ''), 'direct')
             ORDER BY event_count DESC
             LIMIT 8",
            $params
        );

        return [
            'page_views' => $pageViews,
            'cta_clicks' => $ctaClicks,
            'conversions' => $conversions,
            'unique_sessions' => $sessions,
            'conversion_rate' => $pageViews > 0 ? round(($conversions / $pageViews) * 100, 2) : null,
            'top_landing_pages' => $topPages,
            'by_source' => $bySource,
            'manual_first_boundary' => [
                'external_publish' => false,
                'external_send' => false,
            ],
        ];
    }

    public function getMarketingAttributionSummary(?int $landingPageId = null): array
    {
        if (!Database::tableExists('marketing_attribution_touchpoints')) {
            return [
                'touchpoints' => 0,
                'influenced_leads' => 0,
                'influenced_deals' => 0,
                'influenced_revenue' => 0.0,
                'conversion_touchpoints' => 0,
                'revenue_touchpoints' => 0,
                'by_campaign' => [],
                'by_content' => [],
                'by_source' => [],
                'top_converting_pages' => [],
                'recent_touchpoints' => [],
                'manual_first_boundary' => [
                    'external_publish' => false,
                    'external_send' => false,
                ],
            ];
        }

        $workspaceId = $this->workspaceId();
        $params = [$workspaceId];
        $landingFilter = '';
        if (($landingPageId ?? 0) > 0) {
            $this->assertWorkspaceRecord('marketing_landing_pages', (int) $landingPageId, $workspaceId);
            $landingFilter = ' AND at.landing_page_id = ?';
            $params[] = (int) $landingPageId;
        }

        $totals = Database::queryOne(
            "SELECT
                COUNT(*) AS touchpoints,
                COUNT(DISTINCT CASE WHEN contact_id IS NOT NULL THEN contact_id END) AS influenced_leads,
                COUNT(DISTINCT CASE WHEN deal_id IS NOT NULL THEN deal_id END) AS influenced_deals,
                COALESCE(SUM(CASE WHEN touchpoint_type = 'revenue' THEN revenue_amount ELSE 0 END), 0) AS influenced_revenue,
                SUM(CASE WHEN touchpoint_type = 'conversion' THEN 1 ELSE 0 END) AS conversion_touchpoints,
                SUM(CASE WHEN touchpoint_type = 'revenue' THEN 1 ELSE 0 END) AS revenue_touchpoints
             FROM marketing_attribution_touchpoints at
             WHERE at.workspace_id = ?{$landingFilter}",
            $params
        ) ?: [];

        $byCampaign = Database::query(
            "SELECT at.campaign_id,
                    COALESCE(c.name, NULLIF(at.campaign_name, ''), 'Unassigned campaign') AS campaign_name,
                    COUNT(*) AS touchpoint_count,
                    COUNT(DISTINCT at.contact_id) AS influenced_leads,
                    COUNT(DISTINCT at.deal_id) AS influenced_deals,
                    COALESCE(SUM(CASE WHEN at.touchpoint_type = 'revenue' THEN at.revenue_amount ELSE 0 END), 0) AS influenced_revenue
             FROM marketing_attribution_touchpoints at
             LEFT JOIN campaigns c ON c.id = at.campaign_id AND c.workspace_id = at.workspace_id
             WHERE at.workspace_id = ?{$landingFilter}
             GROUP BY at.campaign_id, COALESCE(c.name, NULLIF(at.campaign_name, ''), 'Unassigned campaign')
             ORDER BY influenced_revenue DESC, touchpoint_count DESC
             LIMIT 8",
            $params
        );

        $byContent = Database::query(
            "SELECT at.content_item_id,
                    COALESCE(m.title, 'Unassigned content') AS content_title,
                    COUNT(*) AS touchpoint_count,
                    COUNT(DISTINCT at.contact_id) AS influenced_leads,
                    COUNT(DISTINCT at.deal_id) AS influenced_deals,
                    COALESCE(SUM(CASE WHEN at.touchpoint_type = 'revenue' THEN at.revenue_amount ELSE 0 END), 0) AS influenced_revenue
             FROM marketing_attribution_touchpoints at
             LEFT JOIN marketing_content_items m ON m.id = at.content_item_id AND m.workspace_id = at.workspace_id
             WHERE at.workspace_id = ?{$landingFilter}
             GROUP BY at.content_item_id, COALESCE(m.title, 'Unassigned content')
             ORDER BY influenced_revenue DESC, touchpoint_count DESC
             LIMIT 8",
            $params
        );

        $bySource = Database::query(
            "SELECT COALESCE(NULLIF(at.source, ''), 'direct') AS source,
                    COALESCE(NULLIF(at.medium, ''), 'unknown') AS medium,
                    COUNT(*) AS touchpoint_count,
                    COUNT(DISTINCT at.contact_id) AS influenced_leads,
                    COALESCE(SUM(CASE WHEN at.touchpoint_type = 'revenue' THEN at.revenue_amount ELSE 0 END), 0) AS influenced_revenue
             FROM marketing_attribution_touchpoints at
             WHERE at.workspace_id = ?{$landingFilter}
             GROUP BY COALESCE(NULLIF(at.source, ''), 'direct'), COALESCE(NULLIF(at.medium, ''), 'unknown')
             ORDER BY influenced_revenue DESC, touchpoint_count DESC
             LIMIT 8",
            $params
        );

        $topPages = Database::query(
            "SELECT at.landing_page_id,
                    COALESCE(lp.title, 'Unknown landing page') AS title,
                    COUNT(*) AS touchpoint_count,
                    SUM(CASE WHEN at.touchpoint_type = 'conversion' THEN 1 ELSE 0 END) AS conversion_count,
                    COALESCE(SUM(CASE WHEN at.touchpoint_type = 'revenue' THEN at.revenue_amount ELSE 0 END), 0) AS influenced_revenue
             FROM marketing_attribution_touchpoints at
             LEFT JOIN marketing_landing_pages lp ON lp.id = at.landing_page_id AND lp.workspace_id = at.workspace_id
             WHERE at.workspace_id = ?{$landingFilter}
             GROUP BY at.landing_page_id, COALESCE(lp.title, 'Unknown landing page')
             ORDER BY conversion_count DESC, influenced_revenue DESC, touchpoint_count DESC
             LIMIT 8",
            $params
        );

        $recent = Database::query(
            "SELECT at.*, lp.title AS landing_page_title, c.name AS campaign_title, m.title AS content_title
             FROM marketing_attribution_touchpoints at
             LEFT JOIN marketing_landing_pages lp ON lp.id = at.landing_page_id AND lp.workspace_id = at.workspace_id
             LEFT JOIN campaigns c ON c.id = at.campaign_id AND c.workspace_id = at.workspace_id
             LEFT JOIN marketing_content_items m ON m.id = at.content_item_id AND m.workspace_id = at.workspace_id
             WHERE at.workspace_id = ?{$landingFilter}
             ORDER BY at.occurred_at DESC, at.id DESC
             LIMIT 8",
            $params
        );

        return [
            'touchpoints' => (int) ($totals['touchpoints'] ?? 0),
            'influenced_leads' => (int) ($totals['influenced_leads'] ?? 0),
            'influenced_deals' => (int) ($totals['influenced_deals'] ?? 0),
            'influenced_revenue' => round((float) ($totals['influenced_revenue'] ?? 0), 2),
            'conversion_touchpoints' => (int) ($totals['conversion_touchpoints'] ?? 0),
            'revenue_touchpoints' => (int) ($totals['revenue_touchpoints'] ?? 0),
            'by_campaign' => $byCampaign,
            'by_content' => $byContent,
            'by_source' => $bySource,
            'top_converting_pages' => $topPages,
            'recent_touchpoints' => array_map(
                fn(array $row): array => $this->hydrateJsonFields($row, ['metadata_json']),
                $recent
            ),
            'manual_first_boundary' => [
                'external_publish' => false,
                'external_send' => false,
            ],
        ];
    }

    public function listConversionGoals(array $filters = [], int $limit = 100, int $offset = 0): array
    {
        if (!Database::tableExists('marketing_conversion_goals')) {
            return [];
        }

        $limit = min(max($limit, 1), 250);
        $offset = max($offset, 0);
        $workspace = $this->workspaceClause('g.');
        $where = [$workspace['sql']];
        $params = $workspace['params'];
        if (!empty($filters['id'])) {
            $where[] = 'g.id = ?';
            $params[] = (int) $filters['id'];
        }
        if (!empty($filters['status'])) {
            $where[] = 'g.status = ?';
            $params[] = $this->normalizeEnum((string) $filters['status'], self::CONVERSION_GOAL_STATUSES, 'conversion_goal_status');
        } elseif (!empty($filters['active'])) {
            $where[] = "g.status = 'active'";
        } elseif (!empty($filters['exclude_archived'])) {
            $where[] = "g.status <> 'archived'";
        }
        if (!empty($filters['goal_type'])) {
            $where[] = 'g.goal_type = ?';
            $params[] = $this->normalizeEnum((string) $filters['goal_type'], self::CONVERSION_GOAL_TYPES, 'conversion_goal_type');
        }
        if (!empty($filters['owner_user_id'])) {
            $where[] = 'g.owner_user_id = ?';
            $params[] = (int) $filters['owner_user_id'];
        }

        return array_map(
            fn(array $row): array => $this->hydrateJsonFields($row, ['readiness_warnings_json', 'metadata_json']),
            Database::query(
                "SELECT g.*, owner.email AS owner_email, creator.email AS created_by_email,
                        (SELECT COUNT(*) FROM marketing_conversion_goal_links l WHERE l.workspace_id = g.workspace_id AND l.goal_id = g.id) AS link_count
                 FROM marketing_conversion_goals g
                 LEFT JOIN users owner ON owner.id = g.owner_user_id
                 LEFT JOIN users creator ON creator.id = g.created_by
                 WHERE " . implode(' AND ', $where) . "
                 ORDER BY g.status = 'active' DESC, g.updated_at DESC, g.title ASC
                 LIMIT {$limit} OFFSET {$offset}",
                $params
            )
        );
    }

    public function getConversionGoal(int $id): ?array
    {
        $goals = $this->listConversionGoals(['id' => $id], 1, 0);
        if ($goals === []) {
            return null;
        }

        $goal = $goals[0];
        $goal['links'] = $this->listConversionGoalLinks($id);

        return $goal;
    }

    public function createConversionGoal(array $data): int
    {
        $this->assertMarketingPermission('marketing.write');
        $normalized = $this->normalizeConversionGoalData($data, true);
        $linkTargets = $this->conversionGoalLinkTargets($data);
        $readiness = $this->calculateConversionGoalReadiness($normalized, count($linkTargets));
        $normalized['readiness_score'] = $readiness['score'];
        $normalized['readiness_warnings_json'] = $this->normalizeJsonValue($readiness['warnings']);

        Database::execute(
            "INSERT INTO marketing_conversion_goals
             (workspace_id, uuid, title, goal_key, goal_type, description, success_metric, target_count,
              target_value, tracking_source, status, readiness_score, readiness_warnings_json, metadata_json,
              owner_user_id, created_by, starts_at, ends_at)
             VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)",
            [
                $this->workspaceId(),
                $this->generateUuid(),
                $normalized['title'],
                $normalized['goal_key'],
                $normalized['goal_type'],
                $normalized['description'],
                $normalized['success_metric'],
                $normalized['target_count'],
                $normalized['target_value'],
                $normalized['tracking_source'],
                $normalized['status'],
                $normalized['readiness_score'],
                $normalized['readiness_warnings_json'],
                $normalized['metadata_json'],
                $normalized['owner_user_id'],
                $normalized['created_by'],
                $normalized['starts_at'],
                $normalized['ends_at'],
            ]
        );
        $goalId = (int) Database::lastInsertId();
        foreach ($linkTargets as $target) {
            $this->linkConversionGoal($goalId, (string) $target['linked_type'], (int) ($target['linked_id'] ?? 0), (int) ($data['created_by'] ?? $this->currentUserId()) ?: null);
        }
        $this->refreshConversionGoalReadiness($goalId);

        return $goalId;
    }

    public function updateConversionGoal(int $id, array $data): bool
    {
        $this->assertMarketingPermission('marketing.write');
        $existing = $this->getConversionGoal($id);
        if (!$existing) {
            throw new RuntimeException('Marketing conversion goal not found.');
        }

        $normalized = $this->normalizeConversionGoalData(array_merge($existing, $data), false, $id);
        $updated = $this->updateById('marketing_conversion_goals', $id, $normalized);
        foreach ($this->conversionGoalLinkTargets($data) as $target) {
            $this->linkConversionGoal($id, (string) $target['linked_type'], (int) ($target['linked_id'] ?? 0), (int) ($data['created_by'] ?? $this->currentUserId()) ?: null);
        }
        $this->refreshConversionGoalReadiness($id);

        return $updated;
    }

    public function linkConversionGoal(int $goalId, string $linkedType, int $linkedId = 0, ?int $userId = null): int
    {
        $this->assertMarketingPermission('marketing.write');
        $workspaceId = $this->workspaceId();
        $goal = $this->getConversionGoal($goalId);
        if (!$goal) {
            throw new RuntimeException('Marketing conversion goal not found.');
        }

        $linkedType = $this->normalizeEnum($linkedType, self::CONVERSION_GOAL_LINK_TYPES, 'conversion_goal_link_type');
        $linkedId = $this->assertConversionGoalLinkTarget($linkedType, $linkedId, $workspaceId);
        $userId = $userId ?? $this->currentUserId();
        if (($userId ?? 0) > 0) {
            $this->assertWorkspaceUser((int) $userId, $workspaceId);
        }

        Database::execute(
            "INSERT INTO marketing_conversion_goal_links
             (workspace_id, goal_id, linked_type, linked_id, metadata_json, created_by)
             VALUES (?, ?, ?, ?, ?, ?)
             ON DUPLICATE KEY UPDATE metadata_json = VALUES(metadata_json)",
            [
                $workspaceId,
                $goalId,
                $linkedType,
                $linkedId > 0 ? $linkedId : null,
                $this->normalizeJsonValue(['manual_first_boundary' => true]),
                ($userId ?? 0) > 0 ? $userId : null,
            ]
        );
        $linkId = (int) Database::lastInsertId();
        if ($linkedType === 'landing_page' && $linkedId > 0 && Database::columnExists('marketing_landing_pages', 'conversion_goal_id')) {
            Database::execute("UPDATE marketing_landing_pages SET conversion_goal_id = ? WHERE workspace_id = ? AND id = ?", [$goalId, $workspaceId, $linkedId]);
        }
        if ($linkedType === 'content_item' && $linkedId > 0 && Database::columnExists('marketing_content_items', 'conversion_goal_id')) {
            Database::execute("UPDATE marketing_content_items SET conversion_goal_id = ? WHERE workspace_id = ? AND id = ?", [$goalId, $workspaceId, $linkedId]);
        }
        if ($linkedType === 'campaign' && $linkedId > 0 && Database::columnExists('marketing_campaign_briefs', 'conversion_goal_id')) {
            Database::execute("UPDATE marketing_campaign_briefs SET conversion_goal_id = ? WHERE workspace_id = ? AND campaign_id = ?", [$goalId, $workspaceId, $linkedId]);
        }
        $this->refreshConversionGoalReadiness($goalId);

        return $linkId;
    }

    public function getConversionGoalSummary(): array
    {
        if (!Database::tableExists('marketing_conversion_goals')) {
            return [
                'total' => 0,
                'active' => 0,
                'draft' => 0,
                'missing_links' => 0,
                'average_readiness' => null,
                'by_type' => [],
                'by_status' => [],
                'goals' => [],
            ];
        }

        $workspaceId = $this->workspaceId();
        $totals = Database::queryOne(
            "SELECT COUNT(*) AS total,
                    SUM(CASE WHEN status = 'active' THEN 1 ELSE 0 END) AS active,
                    SUM(CASE WHEN status = 'draft' THEN 1 ELSE 0 END) AS draft,
                    AVG(readiness_score) AS average_readiness
             FROM marketing_conversion_goals
             WHERE workspace_id = ?",
            [$workspaceId]
        ) ?: [];
        $missingLinks = (int) (Database::queryOne(
            "SELECT COUNT(*) AS count
             FROM marketing_conversion_goals g
             WHERE g.workspace_id = ?
               AND g.status <> 'archived'
               AND NOT EXISTS (
                    SELECT 1 FROM marketing_conversion_goal_links l
                    WHERE l.workspace_id = g.workspace_id AND l.goal_id = g.id
               )",
            [$workspaceId]
        )['count'] ?? 0);

        return [
            'total' => (int) ($totals['total'] ?? 0),
            'active' => (int) ($totals['active'] ?? 0),
            'draft' => (int) ($totals['draft'] ?? 0),
            'missing_links' => $missingLinks,
            'average_readiness' => $totals['average_readiness'] !== null ? round((float) $totals['average_readiness'], 1) : null,
            'by_type' => Database::query(
                "SELECT goal_type, COUNT(*) AS count
                 FROM marketing_conversion_goals
                 WHERE workspace_id = ?
                 GROUP BY goal_type
                 ORDER BY count DESC",
                [$workspaceId]
            ),
            'by_status' => Database::query(
                "SELECT status, COUNT(*) AS count
                 FROM marketing_conversion_goals
                 WHERE workspace_id = ?
                 GROUP BY status
                 ORDER BY count DESC",
                [$workspaceId]
            ),
            'goals' => $this->listConversionGoals(['exclude_archived' => true], 8, 0),
        ];
    }

    public function listLeadHandoffs(array $filters = [], int $limit = 100, int $offset = 0): array
    {
        if (!Database::tableExists('marketing_lead_handoffs')) {
            return [];
        }

        $limit = min(max($limit, 1), 250);
        $offset = max($offset, 0);
        $workspace = $this->workspaceClause('h.');
        $where = [$workspace['sql']];
        $params = $workspace['params'];
        if (!empty($filters['id'])) {
            $where[] = 'h.id = ?';
            $params[] = (int) $filters['id'];
        }
        if (!empty($filters['status'])) {
            $where[] = 'h.status = ?';
            $params[] = $this->normalizeEnum((string) $filters['status'], self::LEAD_HANDOFF_STATUSES, 'lead_handoff_status');
        } elseif (!empty($filters['open'])) {
            $where[] = "h.status IN ('new','assigned','contacted')";
        }
        if (!empty($filters['assigned_to'])) {
            $where[] = 'h.assigned_to = ?';
            $params[] = (int) $filters['assigned_to'];
        }
        if (!empty($filters['overdue'])) {
            $where[] = "h.sla_due_at IS NOT NULL AND h.sla_due_at < NOW() AND h.status IN ('new','assigned')";
        }
        foreach (['contact_id', 'deal_id', 'campaign_id', 'landing_page_id', 'conversion_goal_id'] as $field) {
            if (!empty($filters[$field])) {
                $where[] = "h.{$field} = ?";
                $params[] = (int) $filters[$field];
            }
        }

        return array_map(
            fn(array $row): array => $this->hydrateJsonFields($row, ['metadata_json']),
            Database::query(
                "SELECT h.*,
                        assignee.email AS assigned_to_email,
                        creator.email AS created_by_email,
                        c.email AS contact_email,
                        CONCAT(COALESCE(c.first_name, ''), ' ', COALESCE(c.last_name, '')) AS contact_name,
                        d.title AS deal_title,
                        lp.title AS landing_page_title,
                        camp.name AS campaign_name,
                        item.title AS content_title,
                        form.name AS form_name,
                        goal.title AS conversion_goal_title,
                        task.title AS task_title,
                        rule.name AS handoff_rule_name
                 FROM marketing_lead_handoffs h
                 LEFT JOIN users assignee ON assignee.id = h.assigned_to
                 LEFT JOIN users creator ON creator.id = h.created_by
                 LEFT JOIN contacts c ON c.id = h.contact_id AND c.workspace_id = h.workspace_id
                 LEFT JOIN deals d ON d.id = h.deal_id AND d.workspace_id = h.workspace_id
                 LEFT JOIN marketing_landing_pages lp ON lp.id = h.landing_page_id AND lp.workspace_id = h.workspace_id
                 LEFT JOIN campaigns camp ON camp.id = h.campaign_id AND camp.workspace_id = h.workspace_id
                 LEFT JOIN marketing_content_items item ON item.id = h.content_item_id AND item.workspace_id = h.workspace_id
                 LEFT JOIN forms form ON form.id = h.form_id AND form.workspace_id = h.workspace_id
                 LEFT JOIN marketing_conversion_goals goal ON goal.id = h.conversion_goal_id AND goal.workspace_id = h.workspace_id
                 LEFT JOIN tasks task ON task.id = h.task_id AND task.workspace_id = h.workspace_id
                 LEFT JOIN marketing_handoff_rules rule ON rule.id = h.handoff_rule_id AND rule.workspace_id = h.workspace_id
                 WHERE " . implode(' AND ', $where) . "
                 ORDER BY FIELD(h.status, 'new','assigned','accepted','contacted','qualified','converted','rejected','lost','archived'), h.sla_due_at IS NULL ASC, h.sla_due_at ASC, h.created_at DESC
                 LIMIT {$limit} OFFSET {$offset}",
                $params
            )
        );
    }

    public function getLeadHandoff(int $id): ?array
    {
        $rows = $this->listLeadHandoffs(['id' => $id], 1, 0);
        return $rows[0] ?? null;
    }

    public function listLeadHandoffsForCrmRecord(string $recordType, int $recordId, int $limit = 6): array
    {
        if (!Database::tableExists('marketing_lead_handoffs')) {
            return [];
        }

        $record = $this->normalizeCrmHandoffRecord($recordType, $recordId);
        return $this->listLeadHandoffs([$record['field'] => $recordId], $limit, 0);
    }

    public function getLeadHandoffCrmRecordSummary(string $recordType, int $recordId): array
    {
        if (!Database::tableExists('marketing_lead_handoffs')) {
            return [
                'total' => 0,
                'open' => 0,
                'assigned' => 0,
                'accepted' => 0,
                'overdue' => 0,
                'converted' => 0,
                'lost' => 0,
                'sync_pending' => 0,
                'sync_failed' => 0,
            ];
        }

        $record = $this->normalizeCrmHandoffRecord($recordType, $recordId);
        $totals = Database::queryOne(
            "SELECT COUNT(*) AS total,
                    SUM(CASE WHEN status IN ('new','assigned','contacted') THEN 1 ELSE 0 END) AS open,
                    SUM(CASE WHEN status = 'assigned' THEN 1 ELSE 0 END) AS assigned,
                    SUM(CASE WHEN status = 'accepted' THEN 1 ELSE 0 END) AS accepted,
                    SUM(CASE WHEN sla_due_at IS NOT NULL AND sla_due_at < NOW() AND status IN ('new','assigned') THEN 1 ELSE 0 END) AS overdue,
                    SUM(CASE WHEN status = 'converted' THEN 1 ELSE 0 END) AS converted,
                    SUM(CASE WHEN status = 'lost' THEN 1 ELSE 0 END) AS lost,
                    SUM(CASE WHEN crm_sync_status IN ('pending','partial') THEN 1 ELSE 0 END) AS sync_pending,
                    SUM(CASE WHEN crm_sync_status = 'failed' THEN 1 ELSE 0 END) AS sync_failed
             FROM marketing_lead_handoffs
             WHERE workspace_id = ? AND {$record['field']} = ?",
            [$this->workspaceId(), $recordId]
        ) ?: [];

        return [
            'total' => (int) ($totals['total'] ?? 0),
            'open' => (int) ($totals['open'] ?? 0),
            'assigned' => (int) ($totals['assigned'] ?? 0),
            'accepted' => (int) ($totals['accepted'] ?? 0),
            'overdue' => (int) ($totals['overdue'] ?? 0),
            'converted' => (int) ($totals['converted'] ?? 0),
            'lost' => (int) ($totals['lost'] ?? 0),
            'sync_pending' => (int) ($totals['sync_pending'] ?? 0),
            'sync_failed' => (int) ($totals['sync_failed'] ?? 0),
        ];
    }

