    public function createHandoffRule(array $data): int
    {
        $this->assertMarketingPermission('marketing.manage');
        $normalized = $this->normalizeHandoffRuleData($data, true);

        Database::execute(
            "INSERT INTO marketing_handoff_rules
             (workspace_id, uuid, name, status, priority, source_type, landing_page_id, form_id, campaign_id,
              conversion_goal_id, assigned_to, sla_minutes, task_title_template, metadata_json, created_by)
             VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)",
            [
                $this->workspaceId(),
                $this->generateUuid(),
                $normalized['name'],
                $normalized['status'],
                $normalized['priority'],
                $normalized['source_type'],
                $normalized['landing_page_id'],
                $normalized['form_id'],
                $normalized['campaign_id'],
                $normalized['conversion_goal_id'],
                $normalized['assigned_to'],
                $normalized['sla_minutes'],
                $normalized['task_title_template'],
                $normalized['metadata_json'],
                $normalized['created_by'],
            ]
        );

        return (int) Database::lastInsertId();
    }

    public function createLeadHandoff(array $data): int
    {
        $this->assertMarketingPermission('marketing.write');
        $workspaceId = $this->workspaceId();
        $normalized = $this->normalizeLeadHandoffData($data, true, $workspaceId);
        $handoffId = $this->insertLeadHandoff($normalized);
        $handoff = $this->getLeadHandoff($handoffId);
        if ($handoff && !empty($handoff['assigned_to']) && empty($handoff['task_id'])) {
            $taskId = $this->createLeadHandoffTask($handoff, (int) ($normalized['created_by'] ?? $this->currentUserId()) ?: null);
            Database::execute(
                "UPDATE marketing_lead_handoffs SET task_id = ?, status = IF(status = 'new', 'assigned', status), assigned_at = COALESCE(assigned_at, NOW()) WHERE workspace_id = ? AND id = ?",
                [$taskId > 0 ? $taskId : null, $workspaceId, $handoffId]
            );
        }
        $this->syncLeadHandoffToCrmForWorkspace($handoffId, $workspaceId, (int) ($normalized['created_by'] ?? $this->currentUserId()) ?: null);

        return $handoffId;
    }

    public function createLeadHandoffFromConversionEvent(int $conversionEventId, array $context = []): ?array
    {
        if (!Database::tableExists('marketing_lead_handoffs') || !Database::tableExists('marketing_conversion_events')) {
            return null;
        }

        $row = Database::queryOne(
            "SELECT ce.*, te.campaign_id, te.content_item_id, te.utm_source, te.utm_medium, te.utm_campaign,
                    lp.conversion_goal_id AS landing_conversion_goal_id,
                    lp.created_by AS landing_created_by,
                    d.assigned_to AS deal_assigned_to,
                    c.assigned_to AS contact_assigned_to
             FROM marketing_conversion_events ce
             LEFT JOIN marketing_tracking_events te ON te.id = ce.tracking_event_id AND te.workspace_id = ce.workspace_id
             LEFT JOIN marketing_landing_pages lp ON lp.id = ce.landing_page_id AND lp.workspace_id = ce.workspace_id
             LEFT JOIN deals d ON d.id = ce.deal_id AND d.workspace_id = ce.workspace_id
             LEFT JOIN contacts c ON c.id = ce.contact_id AND c.workspace_id = ce.workspace_id
             WHERE ce.id = ?
             LIMIT 1",
            [$conversionEventId]
        );
        if (!$row) {
            return null;
        }

        $workspaceId = (int) ($row['workspace_id'] ?? 0);
        if ($workspaceId <= 0) {
            return null;
        }
        $existing = Database::queryOne(
            "SELECT id FROM marketing_lead_handoffs WHERE workspace_id = ? AND conversion_event_id = ? LIMIT 1",
            [$workspaceId, $conversionEventId]
        );
        if ($existing) {
            return $this->getLeadHandoffForWorkspace((int) ($existing['id'] ?? 0), $workspaceId);
        }

        $conversionGoalId = (int) ($context['conversion_goal_id'] ?? $row['landing_conversion_goal_id'] ?? 0);
        $rule = $this->matchingHandoffRule($workspaceId, [
            'landing_page_id' => (int) ($row['landing_page_id'] ?? 0),
            'form_id' => (int) ($row['form_id'] ?? 0),
            'campaign_id' => (int) ($row['campaign_id'] ?? 0),
            'conversion_goal_id' => $conversionGoalId,
        ]);
        $assignedTo = (int) ($context['assigned_to'] ?? $rule['assigned_to'] ?? $row['contact_assigned_to'] ?? $row['deal_assigned_to'] ?? 0);
        if ($assignedTo <= 0) {
            $assignedTo = null;
        } else {
            $this->assertWorkspaceUser($assignedTo, $workspaceId);
        }

        $creatorId = $this->fallbackHandoffCreator($workspaceId, (int) ($context['created_by'] ?? $row['landing_created_by'] ?? $assignedTo ?? 0));
        $slaMinutes = max(15, (int) ($context['sla_minutes'] ?? $rule['sla_minutes'] ?? 1440));
        $occurredAt = (string) ($row['occurred_at'] ?? date('Y-m-d H:i:s'));
        $slaDueAt = date('Y-m-d H:i:s', strtotime($occurredAt . ' +' . $slaMinutes . ' minutes'));
        $priority = $this->normalizeEnum((string) ($context['priority'] ?? $rule['priority'] ?? 'high'), self::HANDOFF_PRIORITIES, 'handoff_priority');

        $handoffId = $this->insertLeadHandoff([
            'workspace_id' => $workspaceId,
            'conversion_event_id' => $conversionEventId,
            'tracking_event_id' => (int) ($row['tracking_event_id'] ?? 0) ?: null,
            'visitor_session_id' => (int) ($row['visitor_session_id'] ?? 0) ?: null,
            'landing_page_id' => (int) ($row['landing_page_id'] ?? 0) ?: null,
            'campaign_id' => (int) ($row['campaign_id'] ?? 0) ?: null,
            'content_item_id' => (int) ($row['content_item_id'] ?? 0) ?: null,
            'form_id' => (int) ($row['form_id'] ?? 0) ?: null,
            'conversion_goal_id' => $conversionGoalId > 0 ? $conversionGoalId : null,
            'contact_id' => (int) ($row['contact_id'] ?? 0) ?: null,
            'deal_id' => (int) ($row['deal_id'] ?? 0) ?: null,
            'handoff_rule_id' => !empty($rule['id']) ? (int) $rule['id'] : null,
            'task_id' => null,
            'status' => $assignedTo ? 'assigned' : 'new',
            'priority' => $priority,
            'assigned_to' => $assignedTo,
            'source' => mb_substr(Security::sanitizeInput((string) ($row['utm_source'] ?? $context['source'] ?? 'marketing_conversion'), 'string'), 0, 120),
            'handoff_note' => $this->nullableSanitizedText($context['handoff_note'] ?? 'Marketing conversion captured. Sales follow-up is required.'),
            'rejection_reason' => null,
            'sla_due_at' => $slaDueAt,
            'assigned_at' => $assignedTo ? date('Y-m-d H:i:s') : null,
            'first_contacted_at' => null,
            'qualified_at' => null,
            'rejected_at' => null,
            'converted_at' => null,
            'metadata_json' => $this->normalizeJsonValue([
                'source' => 'marketing_conversion_handoff',
                'conversion_type' => (string) ($row['conversion_type'] ?? ''),
                'conversion_value' => $row['conversion_value'] ?? null,
                'utm_medium' => $row['utm_medium'] ?? null,
                'utm_campaign' => $row['utm_campaign'] ?? null,
                'manual_first_boundary' => true,
            ]),
            'created_by' => $creatorId,
        ]);

        if ($assignedTo) {
            $handoff = $this->getLeadHandoffForWorkspace($handoffId, $workspaceId);
            $taskId = $handoff ? $this->createLeadHandoffTask($handoff, $creatorId) : 0;
            if ($taskId > 0) {
                Database::execute(
                    "UPDATE marketing_lead_handoffs SET task_id = ? WHERE workspace_id = ? AND id = ?",
                    [$taskId, $workspaceId, $handoffId]
                );
            }
            $this->applySalesAssignmentToLinkedRecords($workspaceId, (int) ($row['contact_id'] ?? 0), (int) ($row['deal_id'] ?? 0), $assignedTo);
        }

        $this->syncLeadHandoffToCrmForWorkspace($handoffId, $workspaceId, $creatorId);

        return $this->getLeadHandoffForWorkspace($handoffId, $workspaceId);
    }

    public function updateLeadHandoffStatus(int $id, string $status, array $data = []): bool
    {
        $this->assertMarketingPermission('marketing.write');
        return $this->applyLeadHandoffStatusUpdate($id, $status, $data);
    }

    public function recordLeadHandoffFeedback(int $id, string $outcome, array $data = []): array
    {
        $handoff = $this->getLeadHandoff($id);
        if (!$handoff) {
            throw new RuntimeException('Marketing lead handoff not found.');
        }

        $outcome = $this->normalizeEnum($outcome, self::HANDOFF_FEEDBACK_OUTCOMES, 'handoff_feedback_outcome');
        $currentUserId = $this->currentUserId();
        $canMarketingWrite = Authorization::can('marketing.write');
        $isAssignedSalesOwner = $currentUserId > 0 && (int) ($handoff['assigned_to'] ?? 0) === $currentUserId;
        if (!$canMarketingWrite && !$isAssignedSalesOwner) {
            throw new RuntimeException('You do not have permission to update this handoff feedback.');
        }

        $this->applyLeadHandoffStatusUpdate($id, $outcome, $data + [
            'feedback_outcome' => $outcome,
            'feedback_by' => $currentUserId,
            'created_by' => $currentUserId,
        ]);

        return $this->getLeadHandoff($id) ?? [];
    }

