        $limit = min(max($limit, 1), 250);
        $offset = max($offset, 0);
        $where = ['p.workspace_id = ?'];
        $params = [$this->workspaceId()];
        if (!empty($filters['channel'])) {
            $where[] = 'p.channel IN (?, ?)';
            $params[] = $this->normalizeEnum((string) $filters['channel'], self::CONSENT_CHANNELS, 'consent_channel');
            $params[] = 'all';
        }
        if (!empty($filters['status'])) {
            $where[] = 'p.status = ?';
            $params[] = $this->normalizeEnum((string) $filters['status'], self::CONSENT_POLICY_STATUSES, 'consent_policy_status');
        } elseif (!empty($filters['active'])) {
            $where[] = "p.status = 'active'";
        }
        if (!empty($filters['id'])) {
            $where[] = 'p.id = ?';
            $params[] = (int) $filters['id'];
        }

        return array_map(
            fn(array $row): array => $this->hydrateJsonFields($row, ['metadata_json']),
            Database::query(
                "SELECT p.*, owner.email AS owner_email, creator.email AS created_by_email
                 FROM marketing_consent_policies p
                 LEFT JOIN users owner ON owner.id = p.owner_user_id
                 LEFT JOIN users creator ON creator.id = p.created_by
                 WHERE " . implode(' AND ', $where) . "
                 ORDER BY p.status = 'active' DESC, p.channel ASC, p.policy_name ASC
                 LIMIT {$limit} OFFSET {$offset}",
