    public function evaluateMarketingAudienceSafety(array $context): array
    {
        $channel = $this->normalizeEnum((string) ($context['channel'] ?? 'email'), self::CONSENT_CHANNELS, 'consent_channel');
        $policy = null;
        $policyId = (int) ($context['consent_policy_id'] ?? 0);
        if ($policyId > 0) {
            $rows = $this->listConsentPolicies(['id' => $policyId], 1, 0);
            $policy = $rows[0] ?? null;
            if (!$policy) {
                throw new RuntimeException('Consent policy is not available in the active workspace.');
            }
        }

        $warnings = [];
        $status = (string) ($context['consent_status'] ?? 'not_reviewed');
        if ($policy === null) {
            $warnings[] = 'missing_consent_policy';
            $status = $status === 'blocked' ? 'blocked' : 'needs_review';
        } elseif ((string) ($policy['status'] ?? '') !== 'active') {
            $warnings[] = 'consent_policy_not_active';
            $status = 'needs_review';
        } elseif ((string) ($policy['consent_basis'] ?? '') === 'unknown') {
            $warnings[] = 'unknown_consent_basis';
            $status = 'needs_review';
        } elseif ($status === 'not_reviewed') {
            $status = 'approved';
        }

        $requiresUnsubscribe = $policy === null || (int) ($policy['requires_unsubscribe'] ?? 1) === 1;
        $requiresSuppression = $policy === null || (int) ($policy['requires_suppression_check'] ?? 1) === 1;
        if ($requiresUnsubscribe && trim((string) ($context['unsubscribe_text'] ?? '')) === '') {
            $warnings[] = 'missing_unsubscribe_text';
        }
        if ($requiresSuppression && empty($context['suppression_list_checked_at'])) {
            $warnings[] = 'suppression_not_checked';
        }

        $suppressionEntries = $this->listSuppressionEntries(['channel' => $channel, 'active' => true], 5, 0);
        if ($suppressionEntries !== [] && empty($context['suppression_notes'])) {
            $warnings[] = 'suppression_entries_exist_without_plan';
        }
        if (in_array('missing_unsubscribe_text', $warnings, true) || in_array('suppression_not_checked', $warnings, true)) {
            $status = $status === 'blocked' ? 'blocked' : 'needs_review';
        }

        return [
            'status' => $this->normalizeEnum($status, self::CONSENT_REVIEW_STATUSES, 'consent_status'),
            'warnings' => array_values(array_unique($warnings)),
            'policy' => $policy,
            'suppression_entry_count' => count($suppressionEntries),
            'manual_first' => true,
            'external_send' => false,
        ];
    }

    public function listEmailCampaignRuns(array $filters = [], int $limit = 100, int $offset = 0): array
    {
        if (!Database::tableExists('marketing_email_campaign_runs')) {
            return [];
        }

        $limit = min(max($limit, 1), 250);
        $offset = max($offset, 0);
        $workspace = $this->workspaceClause('er.');
        $where = [$workspace['sql']];
        $params = $workspace['params'];
        if (!empty($filters['status'])) {
            $where[] = 'er.status = ?';
            $params[] = $this->normalizeEnum((string) $filters['status'], self::EMAIL_CAMPAIGN_RUN_STATUSES, 'email_run_status');
        }
        if (!empty($filters['open'])) {
            $where[] = "er.status IN ('draft','ready')";
        }
        if (!empty($filters['campaign_id'])) {
            $where[] = 'er.campaign_id = ?';
            $params[] = (int) $filters['campaign_id'];
        }
        if (!empty($filters['audience_segment_id'])) {
            $where[] = 'er.audience_segment_id = ?';
            $params[] = (int) $filters['audience_segment_id'];
        }
        if (!empty($filters['content_item_id'])) {
            $where[] = 'er.content_item_id = ?';
            $params[] = (int) $filters['content_item_id'];
        }
        if (!empty($filters['id'])) {
            $where[] = 'er.id = ?';
            $params[] = (int) $filters['id'];
        }

        return array_map(
            fn(array $row): array => $this->hydrateJsonFields($row, ['segment_snapshot_json', 'send_checklist_json', 'readiness_warnings_json', 'safety_warnings_json', 'export_bundle_json', 'csv_export_json', 'live_handoff_json', 'performance_json', 'metadata_json']),
            Database::query(
                "SELECT er.*, m.title AS content_title, c.name AS campaign_name, et.name AS email_template_name,
                        cp.policy_name AS consent_policy_name, cp.consent_basis AS consent_basis,
                        seg.name AS audience_segment_name, snap.name AS segment_snapshot_name,
                        creator.email AS created_by_email
                 FROM marketing_email_campaign_runs er
                 LEFT JOIN marketing_content_items m ON m.id = er.content_item_id AND m.workspace_id = er.workspace_id
                 LEFT JOIN campaigns c ON c.id = er.campaign_id AND c.workspace_id = er.workspace_id
                 LEFT JOIN marketing_audience_segments seg ON seg.id = er.audience_segment_id AND seg.workspace_id = er.workspace_id
                 LEFT JOIN marketing_segment_snapshots snap ON snap.id = er.segment_snapshot_id AND snap.workspace_id = er.workspace_id
                 LEFT JOIN marketing_consent_policies cp ON cp.id = er.consent_policy_id AND cp.workspace_id = er.workspace_id
                 LEFT JOIN email_templates et ON et.id = er.email_template_id
                    AND (et.workspace_id = er.workspace_id OR (et.workspace_id IS NULL AND COALESCE(et.is_library, 0) = 1))
                 LEFT JOIN users creator ON creator.id = er.created_by
                 WHERE " . implode(' AND ', $where) . "
                 ORDER BY
                    CASE WHEN er.scheduled_at IS NULL THEN 1 ELSE 0 END ASC,
                    er.scheduled_at ASC,
                    er.updated_at DESC
                 LIMIT {$limit} OFFSET {$offset}",
                $params
            )
        );
    }

    public function getEmailCampaignRun(int $id): ?array
    {
        if (!Database::tableExists('marketing_email_campaign_runs')) {
            return null;
        }

        $rows = $this->listEmailCampaignRuns(['id' => $id], 1, 0);
        if ($rows !== []) {
            return $rows[0];
        }

        $row = Database::queryOne(
            "SELECT er.*, m.title AS content_title, c.name AS campaign_name, et.name AS email_template_name,
                    seg.name AS audience_segment_name, snap.name AS segment_snapshot_name,
                    cp.policy_name AS consent_policy_name, cp.consent_basis AS consent_basis,
                    creator.email AS created_by_email
             FROM marketing_email_campaign_runs er
             LEFT JOIN marketing_content_items m ON m.id = er.content_item_id AND m.workspace_id = er.workspace_id
             LEFT JOIN campaigns c ON c.id = er.campaign_id AND c.workspace_id = er.workspace_id
             LEFT JOIN marketing_audience_segments seg ON seg.id = er.audience_segment_id AND seg.workspace_id = er.workspace_id
             LEFT JOIN marketing_segment_snapshots snap ON snap.id = er.segment_snapshot_id AND snap.workspace_id = er.workspace_id
             LEFT JOIN marketing_consent_policies cp ON cp.id = er.consent_policy_id AND cp.workspace_id = er.workspace_id
             LEFT JOIN email_templates et ON et.id = er.email_template_id
                AND (et.workspace_id = er.workspace_id OR (et.workspace_id IS NULL AND COALESCE(et.is_library, 0) = 1))
             LEFT JOIN users creator ON creator.id = er.created_by
             WHERE er.workspace_id = ? AND er.id = ?",
            [$this->workspaceId(), $id]
        );

        return $row ? $this->hydrateJsonFields($row, ['segment_snapshot_json', 'send_checklist_json', 'readiness_warnings_json', 'safety_warnings_json', 'export_bundle_json', 'csv_export_json', 'live_handoff_json', 'performance_json', 'metadata_json']) : null;
    }

