    public function updateEmailCampaignRun(int $id, array $data): bool
    {
        $existing = $this->getEmailCampaignRun($id);
        if (!$existing) {
            throw new RuntimeException('Marketing email campaign run not found.');
        }

        return $this->updateById('marketing_email_campaign_runs', $id, $this->normalizeEmailCampaignRunData(array_merge($existing, $data), false));
    }

    public function getEmailCampaignExportBundle(int $id): array
    {
        $run = $this->getEmailCampaignRun($id);
        if (!$run) {
            throw new RuntimeException('Marketing email campaign run not found.');
        }

        return [
            'run_id' => (int) $run['id'],
            'name' => (string) $run['name'],
            'subject' => (string) ($run['subject'] ?? ''),
            'preview_text' => (string) ($run['preview_text'] ?? ''),
            'preheader_text' => (string) ($run['preheader_text'] ?? $run['preview_text'] ?? ''),
            'body' => (string) ($run['body_snapshot'] ?? ''),
            'segment' => $run['segment_snapshot_json'] ?? [],
            'audience_segment_id' => !empty($run['audience_segment_id']) ? (int) $run['audience_segment_id'] : null,
            'audience_segment_name' => $run['audience_segment_name'] ?? null,
            'segment_snapshot_id' => !empty($run['segment_snapshot_id']) ? (int) $run['segment_snapshot_id'] : null,
            'segment_snapshot_name' => $run['segment_snapshot_name'] ?? null,
            'suppression_notes' => (string) ($run['suppression_notes'] ?? ''),
            'unsubscribe_text' => (string) ($run['unsubscribe_text'] ?? ''),
            'cta' => [
                'label' => (string) ($run['cta_label'] ?? ''),
                'url' => (string) ($run['cta_url'] ?? ''),
            ],
            'recipient_count' => (int) ($run['recipient_count'] ?? 0),
            'send_checklist' => $run['send_checklist_json'] ?? [],
            'approval_status' => (string) ($run['approval_status'] ?? 'not_requested'),
            'readiness' => [
                'score' => (int) ($run['readiness_score'] ?? 0),
                'warnings' => (array) ($run['readiness_warnings_json'] ?? []),
            ],
            'csv_export' => $this->buildEmailCampaignCsvExportPlan($run),
            'campaign_name' => $run['campaign_name'] ?? null,
            'content_title' => $run['content_title'] ?? null,
            'email_template_name' => $run['email_template_name'] ?? null,
            'no_external_send' => true,
            'generated_at' => date('c'),
        ];
    }

    public function markEmailCampaignRunExported(int $id): array
    {
        $bundle = $this->getEmailCampaignExportBundle($id);
        $this->updateEmailCampaignRun($id, [
            'status' => 'exported',
            'exported_at' => date('Y-m-d\TH:i'),
            'export_bundle_json' => $bundle,
            'csv_export_json' => $bundle['csv_export'] ?? [],
            'csv_exported_at' => date('Y-m-d\TH:i'),
            'performance_json' => ['manual_exported' => true, 'external_send' => false],
        ]);

        return $this->getEmailCampaignRun($id) ?? [];
    }

    public function listAssets(array $filters = [], int $limit = 100, int $offset = 0): array
    {
        $workspace = $this->workspaceClause('a.');
        $where = [$workspace['sql']];
        $params = $workspace['params'];
        if (!empty($filters['asset_type'])) {
            $where[] = 'a.asset_type = ?';
            $params[] = $this->normalizeEnum((string) $filters['asset_type'], self::ASSET_TYPES, 'asset_type');
        }
        if (!empty($filters['channel'])) {
            $where[] = 'a.channel = ?';
            $params[] = Security::sanitizeInput((string) $filters['channel'], 'string');
        }

        return array_map(
            fn(array $row): array => $this->hydrateJsonFields($row, ['metadata_json', 'media_tags_json', 'media_metadata_json']),
            Database::query(
                "SELECT a.*, u.email AS created_by_email,
                        mf.title AS media_title, mf.media_type, mf.source_type AS media_source_type,
                        mf.file_path AS media_file_path, mf.source_url AS media_source_url,
                        mf.thumbnail_path AS media_thumbnail_path, mf.thumbnail_url AS media_thumbnail_url,
                        mf.alt_text AS media_alt_text, mf.caption AS media_caption,
                        mf.tags_json AS media_tags_json, mf.metadata_json AS media_metadata_json
                 FROM marketing_assets a
                 LEFT JOIN marketing_media_files mf ON mf.id = a.media_file_id AND mf.workspace_id = a.workspace_id
                 LEFT JOIN users u ON u.id = a.created_by
                 WHERE " . implode(' AND ', $where) . "
                 ORDER BY a.updated_at DESC
                 LIMIT {$limit} OFFSET {$offset}",
                $params
            )
        );
    }

    public function createAsset(array $data): int
    {
        $normalized = $this->normalizeAssetData($data, true);
        Database::execute(
            "INSERT INTO marketing_assets
             (workspace_id, uuid, media_file_id, title, asset_type, asset_url, channel, usage_rights, metadata_json, created_by)
             VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)",
            [
                $this->workspaceId(), $this->generateUuid(), $normalized['media_file_id'], $normalized['title'], $normalized['asset_type'],
                $normalized['asset_url'], $normalized['channel'], $normalized['usage_rights'],
                $normalized['metadata_json'], $normalized['created_by'],
            ]
        );

        return (int) Database::lastInsertId();
    }

    public function listMediaFiles(array $filters = [], int $limit = 100, int $offset = 0): array
    {
        if (!Database::tableExists('marketing_media_files')) {
            return [];
        }

        $limit = min(max($limit, 1), 250);
        $offset = max($offset, 0);
        $workspace = $this->workspaceClause('mf.');
        $where = [$workspace['sql']];
        $params = $workspace['params'];
        if (!empty($filters['media_type'])) {
            $where[] = 'mf.media_type = ?';
            $params[] = $this->normalizeEnum((string) $filters['media_type'], self::MEDIA_TYPES, 'media_type');
        }
        if (!empty($filters['source_type'])) {
            $where[] = 'mf.source_type = ?';
            $params[] = $this->normalizeEnum((string) $filters['source_type'], self::MEDIA_SOURCE_TYPES, 'source_type');
        }
        if (!empty($filters['owner_user_id'])) {
            $where[] = 'mf.owner_user_id = ?';
            $params[] = (int) $filters['owner_user_id'];
        }

        return array_map(
            fn(array $row): array => $this->hydrateJsonFields($row, ['tags_json', 'metadata_json']),
            Database::query(
                "SELECT mf.*, owner.email AS owner_email, creator.email AS created_by_email
                 FROM marketing_media_files mf
                 LEFT JOIN users owner ON owner.id = mf.owner_user_id
                 LEFT JOIN users creator ON creator.id = mf.created_by
                 WHERE " . implode(' AND ', $where) . "
                 ORDER BY mf.updated_at DESC
                 LIMIT {$limit} OFFSET {$offset}",
                $params
            )
        );
    }

    public function getMediaFile(int $id): ?array
    {
        if (!Database::tableExists('marketing_media_files')) {
            return null;
        }

        $row = Database::queryOne(
            "SELECT mf.*, owner.email AS owner_email, creator.email AS created_by_email
             FROM marketing_media_files mf
             LEFT JOIN users owner ON owner.id = mf.owner_user_id
             LEFT JOIN users creator ON creator.id = mf.created_by
             WHERE mf.workspace_id = ? AND mf.id = ?",
            [$this->workspaceId(), $id]
        );

        return $row ? $this->hydrateJsonFields($row, ['tags_json', 'metadata_json']) : null;
    }

    public function getMediaUsageMap(int $mediaFileId): array
    {
        if (!Database::tableExists('marketing_media_files')) {
            return ['media' => null, 'usage_count' => 0, 'usages' => []];
        }
        $this->assertWorkspaceRecord('marketing_media_files', $mediaFileId, $this->workspaceId());
        $media = $this->getMediaFile($mediaFileId);
        $usages = [];
        $workspaceId = $this->workspaceId();
        $addUsage = static function (array &$items, string $type, string $title, string $href, array $meta = []): void {
            $items[] = [
                'type' => $type,
                'title' => $title,
                'href' => $href,
                'meta' => $meta,
            ];
        };

        if (Database::tableExists('marketing_assets') && Database::columnExists('marketing_assets', 'media_file_id')) {
            foreach (Database::query('SELECT id, title, asset_type, channel FROM marketing_assets WHERE workspace_id = ? AND media_file_id = ? ORDER BY updated_at DESC LIMIT 20', [$workspaceId, $mediaFileId]) as $asset) {
                $addUsage($usages, 'asset', (string) ($asset['title'] ?? 'Marketing asset'), 'marketing_assets.php', [
                    'asset_type' => (string) ($asset['asset_type'] ?? ''),
                    'channel' => (string) ($asset['channel'] ?? ''),
                ]);
            }
        }

        if (Database::tableExists('marketing_content_media')) {
            foreach (Database::query(
                "SELECT cm.id, cm.role, cm.channel, ci.id AS content_id, ci.title AS content_title, ci.status
                 FROM marketing_content_media cm
                 JOIN marketing_content_items ci ON ci.id = cm.content_item_id AND ci.workspace_id = cm.workspace_id
                 WHERE cm.workspace_id = ? AND cm.media_file_id = ?
                 ORDER BY cm.sort_order ASC, cm.updated_at DESC
                 LIMIT 30",
                [$workspaceId, $mediaFileId]
            ) as $contentUsage) {
                $addUsage($usages, 'content', (string) ($contentUsage['content_title'] ?? 'Content item'), 'marketing_content_view.php?id=' . (int) ($contentUsage['content_id'] ?? 0), [
                    'role' => (string) ($contentUsage['role'] ?? ''),
                    'channel' => (string) ($contentUsage['channel'] ?? ''),
                    'status' => (string) ($contentUsage['status'] ?? ''),
                ]);
            }
        }

        if (Database::tableExists('marketing_landing_pages')) {
            $landingRows = Database::query(
                "SELECT id, title, status, hero_media_file_id, social_preview_media_file_id, cta_media_file_id,
                        proof_media_file_id, testimonial_media_file_id
                 FROM marketing_landing_pages
                 WHERE workspace_id = ?
                   AND (
                        hero_media_file_id = ?
                        OR social_preview_media_file_id = ?
                        OR cta_media_file_id = ?
                        OR proof_media_file_id = ?
                        OR testimonial_media_file_id = ?
                   )
                 ORDER BY updated_at DESC
                 LIMIT 30",
                [$workspaceId, $mediaFileId, $mediaFileId, $mediaFileId, $mediaFileId, $mediaFileId]
            );
            $slotLabels = [
                'hero_media_file_id' => 'hero',
                'social_preview_media_file_id' => 'social preview',
                'cta_media_file_id' => 'CTA',
                'proof_media_file_id' => 'proof',
                'testimonial_media_file_id' => 'testimonial',
            ];
            foreach ($landingRows as $landing) {
                $slots = [];
                foreach ($slotLabels as $field => $label) {
                    if ((int) ($landing[$field] ?? 0) === $mediaFileId) {
                        $slots[] = $label;
                    }
                }
                $addUsage($usages, 'landing_page', (string) ($landing['title'] ?? 'Landing page'), 'marketing_landing_page_view.php?id=' . (int) ($landing['id'] ?? 0), [
                    'slots' => implode(', ', $slots),
                    'status' => (string) ($landing['status'] ?? ''),
                ]);
            }
        }

        if (Database::tableExists('marketing_distribution_posts') && Database::tableExists('marketing_assets')) {
            foreach (Database::query(
                "SELECT d.id, d.channel, d.status, ci.title AS content_title, a.title AS asset_title
                 FROM marketing_distribution_posts d
                 JOIN marketing_assets a ON a.id = d.asset_id AND a.workspace_id = d.workspace_id
                 JOIN marketing_content_items ci ON ci.id = d.content_item_id AND ci.workspace_id = d.workspace_id
                 WHERE d.workspace_id = ? AND a.media_file_id = ?
                 ORDER BY d.updated_at DESC
                 LIMIT 30",
                [$workspaceId, $mediaFileId]
            ) as $distribution) {
                $addUsage($usages, 'distribution', (string) ($distribution['content_title'] ?? $distribution['asset_title'] ?? 'Distribution post'), 'marketing_distribution.php', [
                    'channel' => (string) ($distribution['channel'] ?? ''),
                    'status' => (string) ($distribution['status'] ?? ''),
                ]);
            }
        }

        if (Database::tableExists('marketing_channel_media_kits')) {
            foreach (Database::query(
                "SELECT id, title, channel, status
                 FROM marketing_channel_media_kits
                 WHERE workspace_id = ? AND primary_media_file_id = ?
                 ORDER BY updated_at DESC
                 LIMIT 30",
                [$workspaceId, $mediaFileId]
            ) as $kit) {
                $addUsage($usages, 'channel_media_kit', (string) ($kit['title'] ?? 'Channel media kit'), 'marketing_channel_exports.php', [
                    'channel' => (string) ($kit['channel'] ?? ''),
                    'status' => (string) ($kit['status'] ?? ''),
                ]);
            }
        }

        return [
            'media' => $media,
            'display_url' => $media ? $this->mediaDisplayUrl($media) : '',
            'usage_count' => count($usages),
            'usages' => $usages,
        ];
    }

    public function getMarketingMediaWorkflowSummary(int $limit = 100): array
    {
        $mediaFiles = $this->listMediaFiles([], $limit, 0);
        $usageMaps = [];
        $unused = [];
        $missingAlt = [];
        $blocked = [];
        $expiring = [];

        foreach ($mediaFiles as $media) {
            $mediaId = (int) ($media['id'] ?? 0);
            if ($mediaId <= 0) {
                continue;
            }
            $usageMap = $this->getMediaUsageMap($mediaId);
            $usageMaps[$mediaId] = $usageMap;
            if ((int) ($usageMap['usage_count'] ?? 0) === 0) {
                $unused[] = $media;
            }
            if (in_array((string) ($media['media_type'] ?? ''), ['image', 'logo', 'thumbnail', 'banner'], true) && trim((string) ($media['alt_text'] ?? '')) === '') {
                $missingAlt[] = $media;
            }
            if (in_array((string) ($media['approval_status'] ?? ''), ['blocked', 'archived'], true) || in_array((string) ($media['license_status'] ?? ''), ['expired', 'restricted'], true)) {
                $blocked[] = $media;
            }
            $expiry = trim((string) ($media['expiry_date'] ?? ''));
            if ($expiry !== '' && strtotime($expiry) !== false && strtotime($expiry) <= strtotime('+30 days')) {
                $expiring[] = $media;
            }
        }

        $recommendations = [];
        if ($mediaFiles === []) {
            $recommendations[] = ['label' => 'Add campaign media', 'href' => 'marketing_assets.php', 'reason' => 'No image or video records exist yet.'];
        }
        if ($missingAlt !== []) {
            $recommendations[] = ['label' => 'Write missing alt text', 'href' => 'marketing_assets.php', 'reason' => count($missingAlt) . ' image records need accessibility text.'];
        }
        if ($blocked !== []) {
            $recommendations[] = ['label' => 'Review blocked media', 'href' => 'marketing_assets.php', 'reason' => count($blocked) . ' media records are blocked, archived, expired, or restricted.'];
        }
        if ($unused !== []) {
            $recommendations[] = ['label' => 'Attach unused media', 'href' => 'marketing_content.php', 'reason' => count($unused) . ' media records are not used in content, landing pages, exports, or assets.'];
        }
        if ($expiring !== []) {
            $recommendations[] = ['label' => 'Check expiring rights', 'href' => 'marketing_assets.php', 'reason' => count($expiring) . ' media records expire within 30 days.'];
        }
        if ($recommendations === []) {
            $recommendations[] = ['label' => 'Build channel media kits', 'href' => 'marketing_channel_exports.php', 'reason' => 'Media governance looks healthy. Package assets for manual channel export.'];
        }

        usort($mediaFiles, static function (array $left, array $right) use ($usageMaps): int {
            return ((int) ($usageMaps[(int) ($right['id'] ?? 0)]['usage_count'] ?? 0)) <=> ((int) ($usageMaps[(int) ($left['id'] ?? 0)]['usage_count'] ?? 0));
        });

        return [
            'counts' => [
                'media_files' => count($mediaFiles),
                'unused' => count($unused),
                'missing_alt_text' => count($missingAlt),
                'blocked' => count($blocked),
                'expiring' => count($expiring),
            ],
            'usage_maps' => $usageMaps,
            'top_used_media' => array_slice($mediaFiles, 0, 8),
            'recommendations' => array_slice($recommendations, 0, 6),
        ];
    }

    public function getMarketingMediaOperationsSummary(int $limit = 100): array
    {
        $limit = min(max($limit, 1), 250);
        $workflow = $this->getMarketingMediaWorkflowSummary($limit);
        $mediaFiles = $this->listMediaFiles([], $limit, 0);
        $operations = [];
        $counts = [
            'total' => count($mediaFiles),
            'active_in_use' => 0,
            'safe_to_archive' => 0,
            'needs_accessibility' => 0,
            'rights_attention' => 0,
            'export_blocked' => 0,
        ];

        foreach ($mediaFiles as $media) {
            $mediaId = (int) ($media['id'] ?? 0);
            if ($mediaId <= 0) {
                continue;
            }

            $usageMap = (array) (($workflow['usage_maps'][$mediaId] ?? []) ?: $this->getMediaUsageMap($mediaId));
            $usageCount = (int) ($usageMap['usage_count'] ?? 0);
            $mediaType = (string) ($media['media_type'] ?? 'other');
            $approvalStatus = (string) ($media['approval_status'] ?? 'pending');
            $licenseStatus = (string) ($media['license_status'] ?? 'unknown');
            $accessibilityStatus = (string) ($media['accessibility_status'] ?? 'unknown');
            $expiryDate = trim((string) ($media['expiry_date'] ?? ''));
            $isImageLike = in_array($mediaType, ['image', 'logo', 'thumbnail', 'banner'], true);
            $isVideoLike = $mediaType === 'video';
            $isAudioLike = $mediaType === 'audio';
            $needsAlt = $isImageLike && trim((string) ($media['alt_text'] ?? '')) === '';
            $needsCaption = $isVideoLike && trim((string) ($media['caption'] ?? '')) === '' && trim((string) ($media['transcript'] ?? '')) === '';
            $needsTranscript = $isAudioLike && trim((string) ($media['transcript'] ?? '')) === '';
            $accessibilityIssues = [];
            if ($needsAlt || $accessibilityStatus === 'needs_alt_text') {
                $accessibilityIssues[] = 'missing_alt_text';
            }
            if ($needsCaption || $needsTranscript || $accessibilityStatus === 'needs_caption') {
                $accessibilityIssues[] = $isAudioLike ? 'missing_transcript' : 'missing_caption_or_transcript';
            }
            if ($accessibilityStatus === 'blocked') {
                $accessibilityIssues[] = 'accessibility_blocked';
            }
            $accessibilityIssues = array_values(array_unique($accessibilityIssues));

            $expiresSoon = false;
            $expiredByDate = false;
            if ($expiryDate !== '' && strtotime($expiryDate) !== false) {
                $expiryTime = strtotime($expiryDate);
                $expiresSoon = $expiryTime <= strtotime('+30 days');
                $expiredByDate = $expiryTime < strtotime('today');
            }
            $rightsAttention = in_array($licenseStatus, ['expired', 'restricted'], true) || $expiresSoon;
            $governanceBlocked = in_array($approvalStatus, ['blocked', 'rejected', 'archived'], true)
                || in_array($licenseStatus, ['expired', 'restricted'], true)
                || $accessibilityStatus === 'blocked'
                || $expiredByDate;
            $safeToArchive = $usageCount === 0 && $approvalStatus !== 'approved';
            $needsAccessibility = $accessibilityIssues !== [];

            if ($usageCount > 0) {
                $counts['active_in_use']++;
            }
            if ($safeToArchive) {
                $counts['safe_to_archive']++;
            }
            if ($needsAccessibility) {
                $counts['needs_accessibility']++;
            }
            if ($rightsAttention) {
                $counts['rights_attention']++;
            }
            if ($governanceBlocked) {
                $counts['export_blocked']++;
            }

            $recommendedAction = 'Keep ready for manual export.';
            if ($governanceBlocked) {
                $recommendedAction = 'Review governance before this media is used in an export bundle.';
            } elseif ($needsAccessibility) {
                $recommendedAction = 'Add accessibility metadata before using this in public-facing creative.';
            } elseif ($rightsAttention) {
                $recommendedAction = 'Confirm usage rights before the next launch window.';
            } elseif ($safeToArchive) {
                $recommendedAction = 'Safe archive candidate because it has no mapped uses.';
            } elseif ($usageCount === 0) {
                $recommendedAction = 'Attach to content, a landing page, or a channel kit if it should stay active.';
            }

            $operations[] = [
                'media_id' => $mediaId,
                'title' => (string) ($media['title'] ?? 'Media file'),
                'media_type' => $mediaType,
                'display_url' => $this->mediaDisplayUrl($media),
                'usage_count' => $usageCount,
                'usage_map' => $usageMap,
                'safe_to_archive' => $safeToArchive,
                'needs_accessibility' => $needsAccessibility,
                'accessibility_issues' => $accessibilityIssues,
                'accessibility_status' => $needsAccessibility ? implode(', ', $accessibilityIssues) : 'ready',
                'rights_attention' => $rightsAttention,
                'rights_status' => $licenseStatus,
                'expiry_date' => $expiryDate,
                'export_blocked' => $governanceBlocked,
                'approval_status' => $approvalStatus,
                'recommended_action' => $recommendedAction,
                'href' => 'marketing_assets.php#media-' . $mediaId,
            ];
        }

        usort($operations, static function (array $left, array $right): int {
            $leftScore = ((bool) ($left['export_blocked'] ?? false) ? 50 : 0)
                + ((bool) ($left['needs_accessibility'] ?? false) ? 30 : 0)
                + ((bool) ($left['rights_attention'] ?? false) ? 20 : 0)
                + ((bool) ($left['safe_to_archive'] ?? false) ? 10 : 0)
                + min((int) ($left['usage_count'] ?? 0), 9);
            $rightScore = ((bool) ($right['export_blocked'] ?? false) ? 50 : 0)
                + ((bool) ($right['needs_accessibility'] ?? false) ? 30 : 0)
                + ((bool) ($right['rights_attention'] ?? false) ? 20 : 0)
                + ((bool) ($right['safe_to_archive'] ?? false) ? 10 : 0)
                + min((int) ($right['usage_count'] ?? 0), 9);

            return $rightScore <=> $leftScore;
        });

        return [
            'counts' => $counts,
            'operations' => array_slice($operations, 0, $limit),
            'guardrails' => [
                'Archive only media with no mapped uses, and keep approved campaign media unless a manager confirms cleanup.',
                'Blocked, expired, restricted, or accessibility-blocked media should not be marked export-ready.',
                'Images need alt text; videos need captions or transcripts before public-facing use.',
            ],
        ];
    }

    public function getMarketingMediaOperationalReadiness(?int $userId = null, int $limit = 8): array
    {
        $this->assertMarketingPermission('marketing.read');
        $userId = $userId ?? $this->currentUserId();
        if (($userId ?? 0) > 0) {
            $this->assertWorkspaceUser((int) $userId, $this->workspaceId());
        }

        $limit = min(max($limit, 3), 12);
        $scanLimit = max(40, $limit * 8);
        $workflow = Database::tableExists('marketing_media_files') ? $this->getMarketingMediaWorkflowSummary($scanLimit) : ['counts' => [], 'usage_maps' => []];
        $operations = Database::tableExists('marketing_media_files') ? $this->getMarketingMediaOperationsSummary($scanLimit) : ['counts' => [], 'operations' => []];
        $landing = Database::tableExists('marketing_landing_pages') ? $this->getLandingPageVisualCommandQueue($limit) : ['score' => 0, 'counts' => [], 'queues' => []];

        $contentRows = [];
        if (Database::tableExists('marketing_content_items')) {
            $contentMediaJoin = Database::tableExists('marketing_content_media')
                ? 'LEFT JOIN marketing_content_media cm ON cm.content_item_id = ci.id AND cm.workspace_id = ci.workspace_id'
                : '';
            $contentMediaCount = Database::tableExists('marketing_content_media') ? 'COUNT(cm.id)' : '0';
            $contentRows = Database::query(
                "SELECT ci.id, ci.title, ci.content_type, ci.channel, ci.status, ci.scheduled_at, ci.updated_at, {$contentMediaCount} AS media_count
                 FROM marketing_content_items ci
                 {$contentMediaJoin}
                 WHERE ci.workspace_id = ?
                   AND ci.status <> 'archived'
                   AND ci.content_type IN ('blog_post','case_study','social_post','ad_copy','video_script','email','newsletter')
                 GROUP BY ci.id, ci.title, ci.content_type, ci.channel, ci.status, ci.scheduled_at, ci.updated_at
                 HAVING media_count = 0
                 ORDER BY
                    CASE WHEN ci.status IN ('approved','scheduled') THEN 0 ELSE 1 END ASC,
                    ci.scheduled_at ASC,
                    ci.updated_at DESC
                 LIMIT {$limit}",
                [$this->workspaceId()]
            );
        }

        $distributionRows = [];
        if (Database::tableExists('marketing_distribution_posts') && Database::tableExists('marketing_content_items')) {
            $contentMediaExists = Database::tableExists('marketing_content_media')
                ? "OR EXISTS (SELECT 1 FROM marketing_content_media cm WHERE cm.workspace_id = d.workspace_id AND cm.content_item_id = d.content_item_id)"
                : '';
            $distributionRows = Database::query(
                "SELECT d.id, d.channel, d.status, d.scheduled_at, ci.title AS content_title, a.title AS asset_title
                 FROM marketing_distribution_posts d
                 JOIN marketing_content_items ci ON ci.id = d.content_item_id AND ci.workspace_id = d.workspace_id
                 LEFT JOIN marketing_assets a ON a.id = d.asset_id AND a.workspace_id = d.workspace_id
                 WHERE d.workspace_id = ?
                   AND d.status IN ('draft','scheduled','exported')
                   AND NOT (
                        COALESCE(a.media_file_id, 0) > 0
                        {$contentMediaExists}
                   )
                 ORDER BY
                    CASE WHEN d.status = 'scheduled' THEN 0 ELSE 1 END ASC,
                    d.scheduled_at ASC,
                    d.updated_at DESC
                 LIMIT {$limit}",
                [$this->workspaceId()]
            );
        }

        $channelKitRows = [];
        if (Database::tableExists('marketing_channel_media_kits')) {
            foreach ($this->listChannelMediaKits([], $scanLimit, 0) as $kit) {
                $readiness = (array) ($kit['readiness_json'] ?? []);
                if ($readiness === []) {
                    $readiness = $this->channelMediaKitReadiness($kit);
                }
                $isBlocked = empty($readiness['ready']) || !empty($readiness['missing']) || in_array((string) ($kit['status'] ?? ''), ['blocked', 'archived'], true);
                if ($isBlocked) {
                    $channelKitRows[] = [
                        'id' => (int) ($kit['id'] ?? 0),
                        'title' => (string) ($kit['title'] ?? 'Channel media kit'),
                        'channel' => (string) ($kit['channel'] ?? 'other'),
                        'status' => (string) ($kit['status'] ?? 'draft'),
                        'missing' => array_values((array) ($readiness['missing'] ?? [])),
                        'warnings' => array_values((array) ($readiness['warnings'] ?? [])),
                        'href' => 'marketing_channel_exports.php',
                    ];
                }
                if (count($channelKitRows) >= $limit) {
                    break;
                }
            }
        }

        $operationRows = (array) ($operations['operations'] ?? []);
        $accessibilityQueue = array_slice(array_values(array_filter(
            $operationRows,
            static fn(array $row): bool => !empty($row['needs_accessibility'])
        )), 0, $limit);
        $governanceQueue = array_slice(array_values(array_filter(
            $operationRows,
            static fn(array $row): bool => !empty($row['export_blocked']) || !empty($row['rights_attention'])
        )), 0, $limit);

        $landingCounts = (array) ($landing['counts'] ?? []);
        $landingIssueCount = (int) ($landingCounts['needs_hero_media'] ?? 0)
            + (int) ($landingCounts['needs_social_preview'] ?? 0)
            + (int) ($landingCounts['needs_accessibility'] ?? 0);
        $contentWithoutMedia = $this->marketingContentWithoutMediaCount();
        $distributionWithoutMedia = $this->marketingDistributionWithoutMediaCount();
        $channelKitBlocked = $this->marketingChannelMediaKitBlockedCount();
        $mediaTotal = (int) ($operations['counts']['total'] ?? $workflow['counts']['media_files'] ?? 0);
        $activeContent = $this->marketingWorkspaceRecordCount('marketing_content_items', "status <> 'archived'");
        $activeLanding = (int) ($landingCounts['scanned'] ?? $this->marketingWorkspaceRecordCount('marketing_landing_pages', $this->workflowActiveCondition('marketing_landing_pages')));
        $activeDistribution = $this->marketingWorkspaceRecordCount('marketing_distribution_posts', "status IN ('draft','scheduled','exported')");
        $activeChannelKits = $this->marketingWorkspaceRecordCount('marketing_channel_media_kits', "status <> 'archived'");

        $riskCount = (int) ($operations['counts']['export_blocked'] ?? 0)
            + (int) ($operations['counts']['needs_accessibility'] ?? 0)
            + (int) ($operations['counts']['rights_attention'] ?? 0)
            + $contentWithoutMedia
            + $landingIssueCount
            + $distributionWithoutMedia
            + $channelKitBlocked;
        $scopeCount = max(1, $mediaTotal + $activeContent + $activeLanding + $activeDistribution + $activeChannelKits);
        $score = $mediaTotal === 0 && $activeContent === 0 && $activeLanding === 0 && $activeDistribution === 0
            ? 0
            : max(0, min(100, 100 - (int) round(($riskCount / $scopeCount) * 100)));
        $status = $mediaTotal === 0 && $activeContent === 0 && $activeLanding === 0 && $activeDistribution === 0
            ? 'empty'
            : ((int) ($operations['counts']['export_blocked'] ?? 0) > 0 || $channelKitBlocked > 0
                ? 'blocked'
                : ($riskCount > 0 ? 'needs_attention' : 'launch_ready'));

        $actions = [];
        $addAction = static function (array &$items, string $label, string $href, string $reason, string $priority = 'normal'): void {
            $items[] = compact('label', 'href', 'reason', 'priority');
        };
        if ($mediaTotal === 0) {
            $addAction($actions, 'Add media library records', 'marketing_assets.php', 'No images, videos, or reusable media records exist yet.', 'high');
        }
        if ((int) ($operations['counts']['needs_accessibility'] ?? 0) > 0) {
            $addAction($actions, 'Fix alt text and captions', 'marketing_assets.php', (int) ($operations['counts']['needs_accessibility'] ?? 0) . ' media record(s) need accessibility metadata.', 'high');
        }
        if ((int) ($operations['counts']['export_blocked'] ?? 0) > 0) {
            $addAction($actions, 'Resolve blocked media', 'marketing_assets.php', (int) ($operations['counts']['export_blocked'] ?? 0) . ' media record(s) are blocked, expired, restricted, or archived.', 'high');
        }
        if ($contentWithoutMedia > 0) {
            $addAction($actions, 'Attach media to content', 'marketing_content.php?media_warning=1', $contentWithoutMedia . ' content item(s) need an image, banner, thumbnail, or video reference.', 'medium');
        }
        if ($landingIssueCount > 0) {
            $addAction($actions, 'Complete landing visuals', 'marketing_landing_pages.php', $landingIssueCount . ' landing-page media readiness issue(s) are open.', 'medium');
        }
        if ($distributionWithoutMedia > 0) {
            $addAction($actions, 'Add media to distribution posts', 'marketing_distribution.php', $distributionWithoutMedia . ' manual distribution variant(s) have no attached or inherited media.', 'medium');
        }
        if ($channelKitBlocked > 0) {
            $addAction($actions, 'Fix channel media kits', 'marketing_channel_exports.php', $channelKitBlocked . ' channel media kit(s) are missing required media or export fields.', 'high');
        }
        if ($actions === []) {
            $addAction($actions, 'Build launch export packs', 'marketing_channel_exports.php', 'Media readiness is healthy. Package approved content for manual channel export.', 'normal');
        }

        return [
            'title' => 'Media Operational Readiness',
            'subtitle' => 'One launch gate for media accessibility, usage rights, landing visuals, content attachments, distribution variants, and channel kits.',
            'score' => $score,
            'status' => $status,
            'counts' => [
                'total_media' => $mediaTotal,
                'active_in_use' => (int) ($operations['counts']['active_in_use'] ?? 0),
                'unused' => (int) ($workflow['counts']['unused'] ?? 0),
                'missing_alt_text' => (int) ($workflow['counts']['missing_alt_text'] ?? 0),
                'needs_accessibility' => (int) ($operations['counts']['needs_accessibility'] ?? 0),
                'blocked_or_restricted' => (int) ($operations['counts']['export_blocked'] ?? 0),
                'rights_attention' => (int) ($operations['counts']['rights_attention'] ?? 0),
                'content_without_media' => $contentWithoutMedia,
                'landing_media_issues' => $landingIssueCount,
                'distribution_without_media' => $distributionWithoutMedia,
                'channel_kits_blocked' => $channelKitBlocked,
            ],
            'queues' => [
                'accessibility' => $accessibilityQueue,
                'governance' => $governanceQueue,
                'content' => array_map(static fn(array $row): array => [
                    'id' => (int) ($row['id'] ?? 0),
                    'title' => (string) ($row['title'] ?? 'Content item'),
                    'type' => (string) ($row['content_type'] ?? ''),
                    'status' => (string) ($row['status'] ?? ''),
                    'href' => 'marketing_content_view.php?id=' . (int) ($row['id'] ?? 0),
                ], $contentRows),
                'landing_pages' => array_merge(
                    (array) ($landing['queues']['needs_hero_media'] ?? []),
                    (array) ($landing['queues']['needs_social_preview'] ?? []),
                    (array) ($landing['queues']['needs_accessibility'] ?? [])
                ),
                'distribution' => array_map(static fn(array $row): array => [
                    'id' => (int) ($row['id'] ?? 0),
                    'title' => (string) ($row['content_title'] ?? 'Distribution post'),
                    'channel' => (string) ($row['channel'] ?? ''),
                    'status' => (string) ($row['status'] ?? ''),
                    'href' => 'marketing_distribution.php',
                ], $distributionRows),
                'channel_kits' => $channelKitRows,
            ],
            'actions' => array_slice($actions, 0, $limit),
            'guardrails' => [
                'workspace_scoped' => true,
                'manual_first' => true,
                'external_publish' => false,
                'external_send' => false,
                'external_media_generation' => false,
                'destructive_cleanup' => false,
            ],
            'recommended_product_decision' => 'Treat media readiness as a required launch gate across content, landing pages, distribution, and channel exports before operators manually publish or send anything.',
            'performance' => [
                'scan_limit' => $scanLimit,
                'page_load_guard' => true,
            ],
        ];
    }

    public function createMediaFile(array $data): int
    {
        $this->assertMarketingPermission('marketing.write');
        $normalized = $this->normalizeMediaFileData($data, true);
        Database::execute(
            "INSERT INTO marketing_media_files
             (workspace_id, uuid, title, media_type, source_type, file_path, source_url, mime_type, file_size,
              width, height, duration_seconds, thumbnail_path, thumbnail_url, alt_text, caption, transcript,
              usage_rights, approval_status, reviewer_user_id, reviewed_at, expiry_date, license_status,
              accessibility_status, brand_safety_notes, blocked_reason, tags_json, metadata_json, owner_user_id, created_by)
             VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)",
            [
                $this->workspaceId(),
                $this->generateUuid(),
                $normalized['title'],
                $normalized['media_type'],
                $normalized['source_type'],
                $normalized['file_path'],
                $normalized['source_url'],
                $normalized['mime_type'],
                $normalized['file_size'],
                $normalized['width'],
                $normalized['height'],
                $normalized['duration_seconds'],
                $normalized['thumbnail_path'],
                $normalized['thumbnail_url'],
                $normalized['alt_text'],
                $normalized['caption'],
                $normalized['transcript'],
                $normalized['usage_rights'],
                $normalized['approval_status'],
                $normalized['reviewer_user_id'],
                $normalized['reviewed_at'],
                $normalized['expiry_date'],
                $normalized['license_status'],
                $normalized['accessibility_status'],
                $normalized['brand_safety_notes'],
                $normalized['blocked_reason'],
                $normalized['tags_json'],
                $normalized['metadata_json'],
                $normalized['owner_user_id'],
                $normalized['created_by'],
            ]
        );

        $id = (int) Database::lastInsertId();
        $this->recordMediaAuditEvent('upload', $id, 'Media file created.', ['media_type' => $normalized['media_type']], $normalized['created_by']);

        return $id;
    }

    public function updateMediaFile(int $id, array $data): bool
    {
        $this->assertMarketingPermission('marketing.write');
        if (!$this->getMediaFile($id)) {
            throw new RuntimeException('Marketing media file not found.');
        }

        $updated = $this->updateById('marketing_media_files', $id, $this->normalizeMediaFileData($data, false));
        $this->recordMediaAuditEvent('edit', $id, 'Media file updated.', ['fields' => array_keys($data)], (int) ($data['updated_by'] ?? $this->currentUserId()) ?: null);

        return $updated;
    }

    public function deleteMediaFile(int $id): bool
    {
        $this->assertMarketingPermission('marketing.manage');
        $this->recordMediaAuditEvent('archive', $id, 'Media file deleted by manage action.', [], $this->currentUserId());
        $rows = Database::execute("DELETE FROM marketing_media_files WHERE workspace_id = ? AND id = ?", [$this->workspaceId(), $id]);

        return $rows > 0;
    }

    public function createMediaFileFromUpload(array $file, array $data): int
    {
        $this->assertMarketingPermission('marketing.write');
        $stored = $this->storeMarketingMediaUpload($file);

        return $this->createMediaFile($data + $stored + ['source_type' => 'upload']);
    }

    public function mediaDisplayUrl(array $media): string
    {
        $url = trim((string) ($media['source_url'] ?? $media['media_source_url'] ?? ''));
        if ($url !== '') {
            return $url;
        }
        $path = trim((string) ($media['file_path'] ?? $media['media_file_path'] ?? ''));
        if ($path === '') {
            return '';
        }
        if (preg_match('#^https?://#i', $path) === 1 || str_starts_with($path, '/')) {
            return $path;
        }
        if (str_starts_with($path, 'uploads/')) {
            return function_exists('publicUrl') ? publicUrl('../' . $path) : '../' . $path;
        }

        return function_exists('publicUrl') ? publicUrl($path) : $path;
    }

    public function listAiMediaRequests(array $filters = [], int $limit = 100, int $offset = 0): array
    {
        if (!Database::tableExists('marketing_ai_media_requests')) {
            return [];
        }

        $limit = min(max($limit, 1), 250);
        $offset = max($offset, 0);
        $workspace = $this->workspaceClause('r.');
        $where = [$workspace['sql']];
        $params = $workspace['params'];

        if (!empty($filters['status'])) {
            $where[] = 'r.status = ?';
            $params[] = $this->normalizeEnum((string) $filters['status'], self::AI_MEDIA_REQUEST_STATUSES, 'ai_media_status');
        }
        if (!empty($filters['request_type'])) {
            $where[] = 'r.request_type = ?';
            $params[] = $this->normalizeEnum((string) $filters['request_type'], self::AI_MEDIA_REQUEST_TYPES, 'ai_media_request_type');
        }
        foreach (['content_item_id', 'landing_page_id', 'creative_brief_id', 'asset_request_id'] as $field) {
            if (!empty($filters[$field])) {
                $where[] = 'r.' . $field . ' = ?';
                $params[] = (int) $filters[$field];
            }
        }

        return array_map(
            fn(array $row): array => $this->hydrateAiMediaRequestRow($row),
            Database::query(
                "SELECT r.*, creator.email AS created_by_email,
                        m.title AS content_title, lp.title AS landing_page_title,
                        cb.title AS creative_brief_title, ar.title AS asset_request_title,
                        mf.title AS accepted_media_title,
                        (SELECT COUNT(*) FROM marketing_ai_media_outputs o WHERE o.workspace_id = r.workspace_id AND o.request_id = r.id) AS output_count
                 FROM marketing_ai_media_requests r
                 LEFT JOIN users creator ON creator.id = r.created_by
                 LEFT JOIN marketing_content_items m ON m.id = r.content_item_id AND m.workspace_id = r.workspace_id
                 LEFT JOIN marketing_landing_pages lp ON lp.id = r.landing_page_id AND lp.workspace_id = r.workspace_id
                 LEFT JOIN marketing_creative_briefs cb ON cb.id = r.creative_brief_id AND cb.workspace_id = r.workspace_id
                 LEFT JOIN marketing_asset_requests ar ON ar.id = r.asset_request_id AND ar.workspace_id = r.workspace_id
                 LEFT JOIN marketing_media_files mf ON mf.id = r.accepted_media_file_id AND mf.workspace_id = r.workspace_id
                 WHERE " . implode(' AND ', $where) . "
                 ORDER BY r.updated_at DESC, r.id DESC
                 LIMIT {$limit} OFFSET {$offset}",
                $params
            )
        );
    }

    public function getAiMediaRequest(int $id): ?array
    {
        if (!Database::tableExists('marketing_ai_media_requests')) {
            return null;
        }

        $row = Database::queryOne(
            "SELECT r.*, creator.email AS created_by_email,
                    m.title AS content_title, lp.title AS landing_page_title,
                    cb.title AS creative_brief_title, ar.title AS asset_request_title,
                    mf.title AS accepted_media_title,
                    (SELECT COUNT(*) FROM marketing_ai_media_outputs o WHERE o.workspace_id = r.workspace_id AND o.request_id = r.id) AS output_count
             FROM marketing_ai_media_requests r
             LEFT JOIN users creator ON creator.id = r.created_by
             LEFT JOIN marketing_content_items m ON m.id = r.content_item_id AND m.workspace_id = r.workspace_id
             LEFT JOIN marketing_landing_pages lp ON lp.id = r.landing_page_id AND lp.workspace_id = r.workspace_id
             LEFT JOIN marketing_creative_briefs cb ON cb.id = r.creative_brief_id AND cb.workspace_id = r.workspace_id
             LEFT JOIN marketing_asset_requests ar ON ar.id = r.asset_request_id AND ar.workspace_id = r.workspace_id
             LEFT JOIN marketing_media_files mf ON mf.id = r.accepted_media_file_id AND mf.workspace_id = r.workspace_id
             WHERE r.workspace_id = ? AND r.id = ?",
            [$this->workspaceId(), $id]
        );

        return $row ? $this->hydrateAiMediaRequestRow($row) : null;
    }

    public function listAiMediaOutputs(int $requestId): array
    {
        if (!Database::tableExists('marketing_ai_media_outputs') || !$this->getAiMediaRequest($requestId)) {
            return [];
        }

        return array_map(
            fn(array $row): array => $this->hydrateJsonFields($row, ['output_json', 'accepted_media_metadata_json']),
            Database::query(
                "SELECT o.*, mf.title AS accepted_media_title, mf.media_type AS accepted_media_type,
                        mf.source_url AS accepted_media_source_url, mf.file_path AS accepted_media_file_path,
                        mf.metadata_json AS accepted_media_metadata_json
                 FROM marketing_ai_media_outputs o
                 LEFT JOIN marketing_media_files mf ON mf.id = o.accepted_media_file_id AND mf.workspace_id = o.workspace_id
                 WHERE o.workspace_id = ? AND o.request_id = ?
                 ORDER BY o.created_at DESC, o.id DESC",
                [$this->workspaceId(), $requestId]
            )
        );
    }

    public function getAiMediaOutput(int $outputId): ?array
    {
        if (!Database::tableExists('marketing_ai_media_outputs')) {
            return null;
        }

        $row = Database::queryOne(
            "SELECT o.*, r.title AS request_title, r.request_type, r.prompt_text AS request_prompt_text,
                    r.uuid AS request_uuid, r.content_item_id, r.landing_page_id, r.creative_brief_id, r.asset_request_id,
                    mf.title AS accepted_media_title, mf.media_type AS accepted_media_type
             FROM marketing_ai_media_outputs o
             JOIN marketing_ai_media_requests r ON r.id = o.request_id AND r.workspace_id = o.workspace_id
             LEFT JOIN marketing_media_files mf ON mf.id = o.accepted_media_file_id AND mf.workspace_id = o.workspace_id
             WHERE o.workspace_id = ? AND o.id = ?",
            [$this->workspaceId(), $outputId]
        );

        return $row ? $this->hydrateJsonFields($row, ['output_json']) : null;
    }

    public function createAiMediaRequest(array $data): int
    {
        $this->assertMarketingPermission('marketing.write');
        if (!Database::tableExists('marketing_ai_media_requests')) {
            throw new RuntimeException('Marketing AI media requests are unavailable.');
        }

        $normalized = $this->normalizeAiMediaRequestData($data, true);
        Database::execute(
            "INSERT INTO marketing_ai_media_requests
             (workspace_id, uuid, title, request_type, status, content_item_id, landing_page_id, creative_brief_id,
              asset_request_id, prompt_text, prompt_json, context_json, provider_json, result_json, accepted_media_file_id, created_by)
             VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)",
            [
                $this->workspaceId(),
                $this->generateUuid(),
                $normalized['title'],
                $normalized['request_type'],
                $normalized['status'],
                $normalized['content_item_id'],
                $normalized['landing_page_id'],
                $normalized['creative_brief_id'],
                $normalized['asset_request_id'],
                $normalized['prompt_text'],
                $normalized['prompt_json'],
                $normalized['context_json'],
                $normalized['provider_json'],
                $normalized['result_json'],
                $normalized['accepted_media_file_id'],
                $normalized['created_by'],
            ]
        );

        return (int) Database::lastInsertId();
    }

    public function generateAiMediaRequest(array $data): array
    {
        $this->assertMarketingPermission('marketing.write');
        if (!Database::tableExists('marketing_ai_media_requests') || !Database::tableExists('marketing_ai_media_outputs')) {
            throw new RuntimeException('Marketing AI media bridge is unavailable.');
        }

        $normalized = $this->normalizeAiMediaRequestData($data + ['status' => 'generated'], true);
        $linkedRecords = $this->buildAiCreativeLinkedRecords($normalized);
        $context = $this->buildAiMediaBridgeContext($normalized, $linkedRecords);
        $result = $this->fallbackAiMediaBridgeResult($normalized, $context);
        $provider = [
            'provider' => 'manual_ai_media_bridge',
            'external_generation' => false,
            'model' => null,
            'generated_at' => date('c'),
        ];
        $promptJson = [
            'request_type' => $normalized['request_type'],
            'source_prompt' => $normalized['prompt_text'],
            'manual_first' => true,
        ];

        Database::execute(
            "INSERT INTO marketing_ai_media_requests
             (workspace_id, uuid, title, request_type, status, content_item_id, landing_page_id, creative_brief_id,
              asset_request_id, prompt_text, prompt_json, context_json, provider_json, result_json, created_by)
             VALUES (?, ?, ?, ?, 'generated', ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)",
            [
                $this->workspaceId(),
                $this->generateUuid(),
                $normalized['title'],
                $normalized['request_type'],
                $normalized['content_item_id'],
                $normalized['landing_page_id'],
                $normalized['creative_brief_id'],
                $normalized['asset_request_id'],
                $normalized['prompt_text'],
                $this->normalizeJsonValue($promptJson),
                $this->normalizeJsonValue($context),
                $this->normalizeJsonValue($provider),
                $this->normalizeJsonValue($result),
                $normalized['created_by'],
            ]
        );
        $requestId = (int) Database::lastInsertId();

        $outputId = $this->createAiMediaOutput([
            'request_id' => $requestId,
            'output_type' => $result['output_type'],
            'status' => 'generated',
            'title' => $result['output_title'],
            'prompt_text' => $result['prompt_text'],
            'output_url' => $result['output_url'] ?? null,
            'output_json' => $result['output_json'],
            'created_by' => $normalized['created_by'],
        ]);

        return [
            'request' => $this->getAiMediaRequest($requestId) ?? [],
            'outputs' => [$this->getAiMediaOutput($outputId) ?? []],
            'no_external_generation' => true,
        ];
    }

    public function acceptAiMediaOutput(int $outputId, array $data = []): int
    {
        $this->assertMarketingPermission('marketing.write');
        $output = $this->getAiMediaOutput($outputId);
        if (!$output) {
            throw new RuntimeException('Marketing AI media output not found.');
        }
        if ((string) ($output['status'] ?? '') === 'accepted' && !empty($output['accepted_media_file_id'])) {
            return (int) $output['accepted_media_file_id'];
        }

        $outputUrl = trim((string) ($output['output_url'] ?? ''));
        if ($outputUrl !== '' && !$this->isSafeMediaUrl($outputUrl)) {
            throw new \InvalidArgumentException('AI media output URLs must start with http or https.');
        }

        $requestType = (string) ($output['request_type'] ?? 'other');
        $mediaType = $this->mediaTypeFromAiMediaRequestType($requestType);
        $title = Security::sanitizeInput((string) ($data['title'] ?? $output['title'] ?? $output['request_title'] ?? 'AI media output'), 'string');
        $metadata = [
            'source' => 'ai_media_generation_bridge',
            'request_id' => (int) ($output['request_id'] ?? 0),
            'request_uuid' => (string) ($output['request_uuid'] ?? ''),
            'output_id' => (int) ($output['id'] ?? 0),
            'output_type' => (string) ($output['output_type'] ?? ''),
            'request_type' => $requestType,
            'accepted_at' => date('c'),
            'external_generation' => false,
        ];

        $mediaId = $this->createMediaFile([
            'title' => $title,
            'media_type' => $mediaType,
            'source_type' => $outputUrl !== '' ? 'url' : 'reference',
            'source_url' => $outputUrl !== '' ? $outputUrl : null,
            'alt_text' => $data['alt_text'] ?? '',
            'caption' => $data['caption'] ?? (string) ($output['prompt_text'] ?? ''),
            'usage_rights' => $data['usage_rights'] ?? 'AI-assisted concept accepted into the media library for manual review.',
            'tags' => ['ai-media-bridge', $requestType],
            'metadata_json' => $metadata,
            'owner_user_id' => (int) ($data['owner_user_id'] ?? 0) ?: null,
            'created_by' => (int) ($data['created_by'] ?? $this->currentUserId()) ?: null,
        ]);

        Database::execute(
            "UPDATE marketing_ai_media_outputs
             SET status = 'accepted', accepted_media_file_id = ?
             WHERE workspace_id = ? AND id = ?",
            [$mediaId, $this->workspaceId(), $outputId]
        );
        Database::execute(
            "UPDATE marketing_ai_media_requests
             SET status = 'accepted', accepted_media_file_id = ?
             WHERE workspace_id = ? AND id = ?",
            [$mediaId, $this->workspaceId(), (int) ($output['request_id'] ?? 0)]
        );
        $this->recordMediaAuditEvent('attach', $mediaId, 'Accepted AI media bridge output into the media library.', $metadata, (int) ($data['created_by'] ?? $this->currentUserId()) ?: null);

        return $mediaId;
    }

    public function rejectAiMediaOutput(int $outputId): bool
    {
        $this->assertMarketingPermission('marketing.write');
        $output = $this->getAiMediaOutput($outputId);
        if (!$output) {
            throw new RuntimeException('Marketing AI media output not found.');
        }

        Database::execute(
            "UPDATE marketing_ai_media_outputs SET status = 'rejected' WHERE workspace_id = ? AND id = ?",
            [$this->workspaceId(), $outputId]
        );
        Database::execute(
            "UPDATE marketing_ai_media_requests
             SET status = 'rejected'
             WHERE workspace_id = ? AND id = ? AND accepted_media_file_id IS NULL",
            [$this->workspaceId(), (int) ($output['request_id'] ?? 0)]
        );

        return true;
    }

    public function updateMediaGovernance(int $id, array $data, ?int $userId = null): bool
    {
        $this->assertMarketingPermission('marketing.manage');
        $media = $this->getMediaFile($id);
        if (!$media) {
            throw new RuntimeException('Marketing media file not found.');
        }

        $status = (string) ($data['approval_status'] ?? $media['approval_status'] ?? 'pending');
        $eventType = match ($status) {
            'approved' => 'approve',
            'rejected' => 'reject',
            'blocked' => 'block',
            'archived' => 'archive',
            default => 'edit',
        };
        $payload = $data + [
            'reviewer_user_id' => $userId ?? $this->currentUserId(),
            'reviewed_at' => date('Y-m-d\TH:i'),
        ];
        $updated = $this->updateById('marketing_media_files', $id, $this->normalizeMediaFileData($payload, false));
        $this->recordMediaAuditEvent($eventType, $id, 'Media governance updated.', ['approval_status' => $status], $userId ?? $this->currentUserId());

        return $updated;
    }

