    public function getMarketingMediaDiagnostics(): array
    {
        $diagnostics = [
            'tables' => [
                'marketing_media_files' => Database::tableExists('marketing_media_files'),
                'marketing_media_audit_events' => Database::tableExists('marketing_media_audit_events'),
            ],
            'missing_alt_text' => [],
            'missing_thumbnails' => [],
            'unsafe_urls' => [],
            'expired_rights' => [],
            'blocked_media' => [],
            'orphaned_media' => [],
        ];
        if (!Database::tableExists('marketing_media_files')) {
            return $diagnostics;
        }

        $workspaceId = $this->workspaceId();
        $rows = $this->listMediaFiles([], 250, 0);
        foreach ($rows as $media) {
            $id = (int) ($media['id'] ?? 0);
            $title = (string) ($media['title'] ?? ('Media #' . $id));
            $mediaType = (string) ($media['media_type'] ?? '');
            $url = trim((string) ($media['source_url'] ?? ''));
            if (in_array($mediaType, ['image', 'logo', 'thumbnail', 'banner'], true) && trim((string) ($media['alt_text'] ?? '')) === '') {
                $diagnostics['missing_alt_text'][] = ['id' => $id, 'title' => $title];
            }
            if (in_array($mediaType, ['image', 'video'], true) && trim((string) (($media['thumbnail_url'] ?? '') . ($media['thumbnail_path'] ?? ''))) === '') {
                $diagnostics['missing_thumbnails'][] = ['id' => $id, 'title' => $title];
            }
            if ($url !== '' && !$this->isSafeMediaUrl($url)) {
                $diagnostics['unsafe_urls'][] = ['id' => $id, 'title' => $title];
            }
            $expiry = trim((string) ($media['expiry_date'] ?? ''));
            if ((string) ($media['license_status'] ?? '') === 'expired' || ($expiry !== '' && strtotime($expiry) < strtotime('today'))) {
                $diagnostics['expired_rights'][] = ['id' => $id, 'title' => $title, 'expiry_date' => $expiry];
            }
            if (in_array((string) ($media['approval_status'] ?? ''), ['blocked', 'archived'], true)) {
                $diagnostics['blocked_media'][] = ['id' => $id, 'title' => $title, 'reason' => (string) ($media['blocked_reason'] ?? '')];
            }
            $usageCount = $this->mediaUsageCount($id, $workspaceId);
            if ($usageCount === 0) {
                $diagnostics['orphaned_media'][] = ['id' => $id, 'title' => $title];
            }
        }

        $diagnostics['counts'] = [
            'total_media' => count($rows),
            'missing_alt_text' => count($diagnostics['missing_alt_text']),
            'missing_thumbnails' => count($diagnostics['missing_thumbnails']),
            'expired_rights' => count($diagnostics['expired_rights']),
            'blocked_media' => count($diagnostics['blocked_media']),
            'orphaned_media' => count($diagnostics['orphaned_media']),
        ];

        return $diagnostics;
    }

    public function runMarketingMediaCleanup(?int $userId = null, bool $dryRun = true): array
    {
        $this->assertMarketingPermission('marketing.manage');
        $diagnostics = $this->getMarketingMediaDiagnostics();
        $candidates = array_values(array_filter(
            (array) ($diagnostics['orphaned_media'] ?? []),
            function (array $row): bool {
                $id = (int) ($row['id'] ?? 0);
                $media = $id > 0 ? ($this->getMediaFile($id) ?: []) : [];
                $metadata = (array) ($media['metadata_json'] ?? []);
                return $id > 0
                    && ((string) ($media['source_type'] ?? '') === 'upload'
                        || (string) ($metadata['source'] ?? '') === 'marketing_onboarding_starter_pack');
            }
        ));
        $archived = [];
        if (!$dryRun) {
            foreach ($candidates as $candidate) {
                $id = (int) $candidate['id'];
                $this->updateById('marketing_media_files', $id, [
                    'approval_status' => 'archived',
                    'blocked_reason' => 'Archived by unused media cleanup.',
                ]);
                $archived[] = $id;
                $this->recordMediaAuditEvent('cleanup_archive', $id, 'Unused media archived by cleanup.', [], $userId ?? $this->currentUserId());
            }
        }
        $this->recordMediaAuditEvent($dryRun ? 'cleanup_preview' : 'cleanup_archive', null, $dryRun ? 'Media cleanup preview generated.' : 'Media cleanup executed.', ['candidate_count' => count($candidates), 'archived' => $archived], $userId ?? $this->currentUserId());

        return [
            'dry_run' => $dryRun,
            'candidate_count' => count($candidates),
            'candidates' => $candidates,
            'archived_ids' => $archived,
        ];
    }

