    public function listCampaignCreativeRequirements(array $filters = [], int $limit = 100, int $offset = 0): array
    {
        $this->assertMarketingPermission('marketing.read');
        if (!Database::tableExists('marketing_campaign_creative_requirements')) {
            return [];
        }

        $limit = min(max($limit, 1), 250);
        $offset = max($offset, 0);
        $workspace = $this->workspaceClause('ccr.');
        $where = [$workspace['sql']];
        $params = $workspace['params'];
        if (!empty($filters['open'])) {
            $where[] = "ccr.status IN ('planned','requested','in_progress','ready','blocked')";
        }
        if (!empty($filters['campaign_id'])) {
            $where[] = 'ccr.campaign_id = ?';
            $params[] = (int) $filters['campaign_id'];
        }
        if (!empty($filters['status'])) {
            $where[] = 'ccr.status = ?';
            $params[] = $this->normalizeEnum((string) $filters['status'], self::CAMPAIGN_CREATIVE_REQUIREMENT_STATUSES, 'campaign_creative_requirement_status');
        }
        if (!empty($filters['id'])) {
            $where[] = 'ccr.id = ?';
            $params[] = (int) $filters['id'];
        }

        return array_map(
            fn(array $row): array => $this->hydrateJsonFields($row, ['readiness_json', 'metadata_json']),
            Database::query(
                "SELECT ccr.*, c.name AS campaign_name, cb.title AS creative_brief_title,
                        ar.title AS asset_request_title, mf.title AS media_title,
                        mf.media_type, mf.approval_status AS media_approval_status, mf.license_status AS media_license_status,
                        m.title AS content_title, lp.title AS landing_page_title,
                        ceb.channel AS channel_export_channel, owner.email AS owner_email, creator.email AS created_by_email
                 FROM marketing_campaign_creative_requirements ccr
                 JOIN campaigns c ON c.id = ccr.campaign_id AND c.workspace_id = ccr.workspace_id
                 LEFT JOIN marketing_creative_briefs cb ON cb.id = ccr.creative_brief_id AND cb.workspace_id = ccr.workspace_id
                 LEFT JOIN marketing_asset_requests ar ON ar.id = ccr.asset_request_id AND ar.workspace_id = ccr.workspace_id
                 LEFT JOIN marketing_media_files mf ON mf.id = ccr.media_file_id AND mf.workspace_id = ccr.workspace_id
                 LEFT JOIN marketing_content_items m ON m.id = ccr.content_item_id AND m.workspace_id = ccr.workspace_id
                 LEFT JOIN marketing_landing_pages lp ON lp.id = ccr.landing_page_id AND lp.workspace_id = ccr.workspace_id
                 LEFT JOIN marketing_channel_export_bundles ceb ON ceb.id = ccr.channel_export_bundle_id AND ceb.workspace_id = ccr.workspace_id
                 LEFT JOIN users owner ON owner.id = ccr.owner_user_id
                 LEFT JOIN users creator ON creator.id = ccr.created_by
                 WHERE " . implode(' AND ', $where) . "
                 ORDER BY
                    CASE ccr.priority WHEN 'urgent' THEN 0 WHEN 'high' THEN 1 WHEN 'normal' THEN 2 ELSE 3 END ASC,
                    CASE ccr.status WHEN 'blocked' THEN 0 WHEN 'planned' THEN 1 WHEN 'requested' THEN 2 WHEN 'in_progress' THEN 3 WHEN 'ready' THEN 4 ELSE 5 END ASC,
                    ccr.due_at ASC,
                    ccr.updated_at DESC
                 LIMIT {$limit} OFFSET {$offset}",
                $params
            )
        );
    }

