    public function getCampaignCreativeReadinessSummary(int $campaignId): array
    {
        $this->assertMarketingPermission('marketing.read');
        if (!$this->getCampaignForWorkspace($campaignId)) {
            throw new RuntimeException('Campaign was not found in the active workspace.');
        }

        $requirements = $this->listCampaignCreativeRequirements(['campaign_id' => $campaignId, 'open' => true], 100, 0);
        $counts = ['total' => count($requirements), 'ready' => 0, 'blocked' => 0, 'missing_media' => 0, 'needs_accessibility' => 0, 'overdue' => 0];
        $queue = [];
        $now = time();
        foreach ($requirements as $requirement) {
            $status = (string) ($requirement['status'] ?? 'planned');
            if ($status === 'ready' || $status === 'waived') {
                $counts['ready']++;
            }
            if ($status === 'blocked') {
                $counts['blocked']++;
            }
            $readiness = (array) ($requirement['readiness_json'] ?? []);
            if (empty($readiness['media_attached'])) {
                $counts['missing_media']++;
            }
            if (!empty($readiness['accessibility_warning'])) {
                $counts['needs_accessibility']++;
            }
            $dueAt = (string) ($requirement['due_at'] ?? '');
            if ($dueAt !== '' && strtotime($dueAt) !== false && strtotime($dueAt) < $now && !in_array($status, ['ready', 'waived', 'archived'], true)) {
                $counts['overdue']++;
            }
            if ($status !== 'ready' && $status !== 'waived') {
                $queue[] = [
                    'label' => (string) ($requirement['title'] ?? 'Creative requirement'),
                    'status' => $status,
                    'priority' => (string) ($requirement['priority'] ?? 'normal'),
                    'href' => 'marketing_creative.php?campaign_id=' . $campaignId,
                    'reason' => (string) ($readiness['message'] ?? 'Complete this campaign creative requirement before launch.'),
                ];
            }
        }

        $score = $counts['total'] > 0 ? (int) round(($counts['ready'] / $counts['total']) * 100) : 0;
        $status = match (true) {
            $counts['total'] === 0 => 'needs_requirements',
            $counts['blocked'] > 0 => 'blocked',
            $counts['missing_media'] > 0 || $counts['needs_accessibility'] > 0 || $counts['overdue'] > 0 => 'needs_attention',
            $counts['ready'] >= $counts['total'] => 'ready',
            default => 'in_progress',
        };

        if ($requirements === []) {
            $queue[] = [
                'label' => 'Define campaign creative requirements',
                'status' => 'planned',
                'priority' => 'high',
                'href' => 'marketing_creative.php?campaign_id=' . $campaignId,
                'reason' => 'Add the required hero, social, email, video, or proof assets before launch packaging.',
            ];
        }

        return [
            'campaign_id' => $campaignId,
            'status' => $status,
            'readiness_score' => $score,
            'requirements' => $requirements,
            'counts' => $counts,
            'queue' => array_slice($queue, 0, 10),
            'guardrails' => [
                'manual_first' => true,
                'external_generation' => false,
                'external_publish' => false,
                'message' => 'Campaign creative readiness checks local media, approvals, rights, and accessibility only. It does not generate or publish media externally.',
            ],
        ];
    }

    public function updateAssetRequestStatus(int $id, string $status): bool
    {
        $this->assertMarketingPermission('marketing.write');
        $status = $this->normalizeEnum($status, self::ASSET_REQUEST_STATUSES, 'asset_request_status');
        $completedAt = in_array($status, ['ready', 'approved'], true) ? date('Y-m-d H:i:s') : null;
        $rows = Database::execute(
            "UPDATE marketing_asset_requests
             SET status = ?, completed_at = COALESCE(?, completed_at)
             WHERE workspace_id = ? AND id = ?",
            [$status, $completedAt, $this->workspaceId(), $id]
        );

        return $rows > 0;
    }

