                        mf.license_status AS media_license_status, mf.alt_text AS media_alt_text,
                        mf.caption AS media_caption, mf.transcript AS media_transcript,
                        assignee.email AS assigned_to_email, owner.email AS owner_email, creator.email AS created_by_email
                 FROM marketing_media_production_work_items mpw
                 LEFT JOIN campaigns c ON c.id = mpw.campaign_id AND c.workspace_id = mpw.workspace_id
                 LEFT JOIN marketing_content_items m ON m.id = mpw.content_item_id AND m.workspace_id = mpw.workspace_id
                 LEFT JOIN marketing_landing_pages lp ON lp.id = mpw.landing_page_id AND lp.workspace_id = mpw.workspace_id
                 LEFT JOIN marketing_distribution_posts dp ON dp.id = mpw.distribution_post_id AND dp.workspace_id = mpw.workspace_id
                 LEFT JOIN marketing_channel_export_bundles ceb ON ceb.id = mpw.channel_export_bundle_id AND ceb.workspace_id = mpw.workspace_id
                 LEFT JOIN marketing_creative_briefs cb ON cb.id = mpw.creative_brief_id AND cb.workspace_id = mpw.workspace_id
                 LEFT JOIN marketing_asset_requests ar ON ar.id = mpw.asset_request_id AND ar.workspace_id = mpw.workspace_id
                 LEFT JOIN marketing_campaign_creative_requirements ccr ON ccr.id = mpw.campaign_creative_requirement_id AND ccr.workspace_id = mpw.workspace_id
                 LEFT JOIN marketing_media_files mf ON mf.id = mpw.media_file_id AND mf.workspace_id = mpw.workspace_id
                 LEFT JOIN users assignee ON assignee.id = mpw.assigned_to
                 LEFT JOIN users owner ON owner.id = mpw.owner_user_id
                 LEFT JOIN users creator ON creator.id = mpw.created_by
                 WHERE " . implode(' AND ', $where) . "
                 ORDER BY
                    CASE mpw.priority WHEN 'urgent' THEN 0 WHEN 'high' THEN 1 WHEN 'normal' THEN 2 ELSE 3 END ASC,
                    CASE mpw.status WHEN 'blocked' THEN 0 WHEN 'requested' THEN 1 WHEN 'assigned' THEN 2 WHEN 'in_progress' THEN 3 WHEN 'review' THEN 4 WHEN 'ready' THEN 5 ELSE 6 END ASC,
                    CASE WHEN mpw.due_at IS NULL THEN 1 ELSE 0 END ASC,
                    mpw.due_at ASC,
                    mpw.updated_at DESC
                 LIMIT {$limit} OFFSET {$offset}",
                $params
            )
        );
    }

