    public function updateMediaProductionWorkItem(int $id, array $data): bool
    {
        $this->assertMarketingPermission('marketing.write');
        $existing = $this->getMediaProductionWorkItem($id);
        if (!$existing) {
            throw new RuntimeException('Media production work item was not found.');
