    public function archiveMediaProductionWorkItem(int $id, ?int $userId = null): bool
    {
        $this->assertMarketingPermission('marketing.manage');
        if (!$this->getMediaProductionWorkItem($id)) {
            throw new RuntimeException('Media production work item was not found.');
        }

        return $this->updateById('marketing_media_production_work_items', $id, [
            'status' => 'archived',
            'archived_at' => date('Y-m-d H:i:s'),
            'metadata_json' => $this->normalizeJsonValue([
