    public function getMediaProductionWorkflowSummary(?int $userId = null, int $limit = 100): array
    {
        $this->assertMarketingPermission('marketing.read');
        if (!Database::tableExists('marketing_media_production_work_items')) {
            return [
                'counts' => ['total' => 0, 'open' => 0, 'blocked' => 0, 'overdue' => 0, 'ready' => 0, 'assigned_to_me' => 0],
                'queue' => [],
                'due_soon' => [],
                'ready_items' => [],
                'guardrails' => ['manual_first' => true, 'external_publish' => false, 'external_generation' => false],
            ];
        }

        $workspaceId = $this->workspaceId();
        $row = Database::queryOne(
            "SELECT
                COUNT(*) AS total,
                SUM(status IN ('requested','assigned','in_progress','review','blocked')) AS open_count,
                SUM(status = 'blocked') AS blocked_count,
                SUM(status IN ('ready','approved')) AS ready_count,
                SUM(due_at IS NOT NULL AND due_at < NOW() AND status NOT IN ('ready','approved','archived')) AS overdue_count,
                SUM(assigned_to = ?) AS assigned_to_me
             FROM marketing_media_production_work_items
             WHERE workspace_id = ? AND status <> 'archived'",
            [($userId ?? 0) > 0 ? $userId : -1, $workspaceId]
        ) ?: [];

        $byStatusRows = Database::query(
            "SELECT status, COUNT(*) AS count
             FROM marketing_media_production_work_items
             WHERE workspace_id = ? AND status <> 'archived'
             GROUP BY status",
            [$workspaceId]
        );

        $openItems = $this->listMediaProductionWorkItems(['open' => true], min(max($limit, 10), 250), 0);
        $dueSoon = array_values(array_filter($openItems, static function (array $item): bool {
            $dueAt = (string) ($item['due_at'] ?? '');
            return $dueAt !== '' && strtotime($dueAt) !== false && strtotime($dueAt) <= strtotime('+7 days');
        }));

        $queue = [];
        foreach (array_slice($openItems, 0, 12) as $item) {
            $readiness = (array) ($item['readiness_json'] ?? []);
            $queue[] = [
                'id' => (int) ($item['id'] ?? 0),
                'label' => (string) ($item['title'] ?? 'Media production work'),
                'status' => (string) ($item['status'] ?? 'requested'),
                'priority' => (string) ($item['priority'] ?? 'normal'),
                'score' => (int) ($readiness['score'] ?? 0),
                'reason' => (string) ($readiness['message'] ?? 'Review creative production readiness.'),
                'href' => 'marketing_creative.php#media-production-workflow',
            ];
        }

        return [
            'counts' => [
                'total' => (int) ($row['total'] ?? 0),
                'open' => (int) ($row['open_count'] ?? 0),
                'blocked' => (int) ($row['blocked_count'] ?? 0),
                'overdue' => (int) ($row['overdue_count'] ?? 0),
                'ready' => (int) ($row['ready_count'] ?? 0),
                'assigned_to_me' => (int) ($row['assigned_to_me'] ?? 0),
            ],
            'by_status' => array_column($byStatusRows, 'count', 'status'),
            'queue' => $queue,
            'due_soon' => array_slice($dueSoon, 0, 8),
            'ready_items' => $this->listMediaProductionWorkItems(['status' => 'ready'], 8, 0),
            'open_items' => array_slice($openItems, 0, 12),
            'guardrails' => [
                'manual_first' => true,
                'external_publish' => false,
                'external_generation' => false,
                'message' => 'Media production work items coordinate human production and review only; they do not generate, send, or publish externally.',
            ],
        ];
    }

