    public function getCreativeAssetReadiness(int $contentItemId): array
    {
        $content = $this->getContentItem($contentItemId);
        if (!$content) {
            throw new RuntimeException('Marketing content item not found.');
        }

        $openRequests = Database::tableExists('marketing_asset_requests')
            ? (int) (Database::queryOne(
                "SELECT COUNT(*) AS count
                 FROM marketing_asset_requests
                 WHERE workspace_id = ? AND content_item_id = ? AND status IN ('requested','in_progress')",
                [$this->workspaceId(), $contentItemId]
            )['count'] ?? 0)
            : 0;
        $readyRequests = Database::tableExists('marketing_asset_requests')
            ? (int) (Database::queryOne(
                "SELECT COUNT(*) AS count
                 FROM marketing_asset_requests
                 WHERE workspace_id = ? AND content_item_id = ? AND status IN ('ready','approved')",
                [$this->workspaceId(), $contentItemId]
            )['count'] ?? 0)
            : 0;
        $linkedAssets = Database::tableExists('marketing_asset_usage')
            ? (int) (Database::queryOne(
                "SELECT COUNT(DISTINCT asset_id) AS count
                 FROM marketing_asset_usage
                 WHERE workspace_id = ? AND content_item_id = ?",
                [$this->workspaceId(), $contentItemId]
            )['count'] ?? 0)
            : 0;

        return [
            'content_item_id' => $contentItemId,
            'ready' => $linkedAssets > 0 && $openRequests === 0,
            'open_requests' => $openRequests,
            'ready_requests' => $readyRequests,
            'linked_assets' => $linkedAssets,
            'recommendations' => $linkedAssets === 0
                ? ['Attach or record at least one creative asset for this content item.']
                : ($openRequests > 0 ? ['Complete open creative asset requests before launch.'] : []),
        ];
    }

    public function listRecurringRhythms(array $filters = [], int $limit = 100, int $offset = 0): array
    {
        if (!Database::tableExists('marketing_recurring_rhythms')) {
            return [];
        }

        $limit = min(max($limit, 1), 250);
        $offset = max($offset, 0);
        $workspace = $this->workspaceClause('rr.');
        $where = [$workspace['sql']];
        $params = $workspace['params'];
        if (!empty($filters['id'])) {
            $where[] = 'rr.id = ?';
            $params[] = (int) $filters['id'];
        }
        if (!empty($filters['status'])) {
            $where[] = 'rr.status = ?';
            $params[] = $this->normalizeEnum((string) $filters['status'], self::RHYTHM_STATUSES, 'rhythm_status');
        }
        if (!empty($filters['rhythm_type'])) {
            $where[] = 'rr.rhythm_type = ?';
            $params[] = $this->normalizeEnum((string) $filters['rhythm_type'], self::RHYTHM_TYPES, 'rhythm_type');
        }
        if (!empty($filters['cadence'])) {
            $where[] = 'rr.cadence = ?';
            $params[] = $this->normalizeEnum((string) $filters['cadence'], self::RHYTHM_CADENCES, 'rhythm_cadence');
        }
        if (!empty($filters['owner_user_id'])) {
            $where[] = 'rr.owner_user_id = ?';
            $params[] = (int) $filters['owner_user_id'];
        }

        return array_map(
            fn(array $row): array => $this->hydrateJsonFields($row, ['checklist_json', 'metadata_json']),
            Database::query(
                "SELECT rr.*, owner.email AS owner_email, creator.email AS created_by_email
                 FROM marketing_recurring_rhythms rr
                 LEFT JOIN users owner ON owner.id = rr.owner_user_id
                 LEFT JOIN users creator ON creator.id = rr.created_by
                 WHERE " . implode(' AND ', $where) . "
                 ORDER BY
                    CASE WHEN rr.next_run_at IS NULL THEN 1 ELSE 0 END ASC,
                    rr.next_run_at ASC,
                    rr.updated_at DESC
                 LIMIT {$limit} OFFSET {$offset}",
                $params
            )
        );
    }

    public function createRecurringRhythm(array $data): int
    {
        $this->assertMarketingPermission('marketing.write');
        $normalized = $this->normalizeRecurringRhythmData($data);
