             (workspace_id, uuid, name, rhythm_type, cadence, day_of_week, next_run_at,
              owner_user_id, checklist_json, status, metadata_json, created_by)
             VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)",
            [
                $this->workspaceId(),
                $this->generateUuid(),
                $normalized['name'],
                $normalized['rhythm_type'],
                $normalized['cadence'],
                $normalized['day_of_week'],
                $normalized['next_run_at'],
                $normalized['owner_user_id'],
                $normalized['checklist_json'],
                $normalized['status'],
                $normalized['metadata_json'],
                $normalized['created_by'],
            ]
        );

        return (int) Database::lastInsertId();
    }

    public function listPlanningQueueItems(array $filters = [], int $limit = 100, int $offset = 0): array
    {
        if (!Database::tableExists('marketing_planning_queue_items')) {
            return [];
        }

        $limit = min(max($limit, 1), 250);
        $offset = max($offset, 0);
        $workspace = $this->workspaceClause('q.');
        $where = [$workspace['sql']];
        $params = $workspace['params'];
        if (!empty($filters['open'])) {
            $where[] = "q.status IN ('planned','in_progress','blocked')";
        }
        if (!empty($filters['overdue'])) {
            $where[] = "q.due_at IS NOT NULL AND q.due_at < NOW() AND q.status NOT IN ('done','archived')";
        }
        if (!empty($filters['id'])) {
            $where[] = 'q.id = ?';
            $params[] = (int) $filters['id'];
        }
        if (!empty($filters['status'])) {
            $where[] = 'q.status = ?';
            $params[] = $this->normalizeEnum((string) $filters['status'], self::PLANNING_QUEUE_STATUSES, 'queue_status');
        }
        if (!empty($filters['priority'])) {
            $where[] = 'q.priority = ?';
            $params[] = $this->normalizeEnum((string) $filters['priority'], self::PLANNING_QUEUE_PRIORITIES, 'queue_priority');
        }
        if (!empty($filters['item_type'])) {
            $where[] = 'q.item_type = ?';
            $params[] = $this->normalizeEnum((string) $filters['item_type'], self::PLANNING_QUEUE_TYPES, 'queue_type');
        }
        foreach (['rhythm_id', 'content_item_id', 'campaign_brief_id', 'campaign_id', 'owner_user_id'] as $field) {
            if (!empty($filters[$field])) {
                $where[] = "q.{$field} = ?";
                $params[] = (int) $filters[$field];
            }
        }
        if (!empty($filters['week_start'])) {
            $where[] = 'q.week_start = ?';
            $params[] = $this->normalizeWeekStart((string) $filters['week_start']);
        }

        return array_map(
            fn(array $row): array => $this->hydrateJsonFields($row, ['metadata_json']),
            Database::query(
                "SELECT q.*, rr.name AS rhythm_name, m.title AS content_title, b.title AS campaign_brief_title,
                        c.name AS campaign_name, owner.email AS owner_email, creator.email AS created_by_email
                 FROM marketing_planning_queue_items q
                 LEFT JOIN marketing_recurring_rhythms rr ON rr.id = q.rhythm_id AND rr.workspace_id = q.workspace_id
                 LEFT JOIN marketing_content_items m ON m.id = q.content_item_id AND m.workspace_id = q.workspace_id
                 LEFT JOIN marketing_campaign_briefs b ON b.id = q.campaign_brief_id AND b.workspace_id = q.workspace_id
                 LEFT JOIN campaigns c ON c.id = q.campaign_id AND c.workspace_id = q.workspace_id
                 LEFT JOIN users owner ON owner.id = q.owner_user_id
                 LEFT JOIN users creator ON creator.id = q.created_by
                 WHERE " . implode(' AND ', $where) . "
                 ORDER BY
                    q.week_start ASC,
                    CASE q.priority WHEN 'high' THEN 0 WHEN 'medium' THEN 1 ELSE 2 END ASC,
                    CASE WHEN q.due_at IS NULL THEN 1 ELSE 0 END ASC,
                    q.due_at ASC,
                    q.updated_at DESC
                 LIMIT {$limit} OFFSET {$offset}",
                $params
            )
        );
    }

