    public function listMarketingAiQueueSuggestions(string $aiPhase = '', int $limit = 50, int $offset = 0): array
    {
        $rows = $this->listPlanningQueueItems(['open' => true], 250, 0);
        $filtered = array_values(array_filter($rows, static function (array $row) use ($aiPhase): bool {
            $metadata = (array) ($row['metadata_json'] ?? []);
            if ((string) ($metadata['source'] ?? '') !== 'marketing_ai') {
                return false;
            }
            return $aiPhase === '' || (string) ($metadata['ai_phase'] ?? '') === $aiPhase;
        }));

        return array_slice($filtered, max(0, $offset), min(max(1, $limit), 250));
    }

    public function runMarketingStrategyGapAnalysis(array $input = []): array
    {
        $this->assertMarketingPermission('marketing.write');
        if (!Database::tableExists('marketing_assistant_runs') || !Database::tableExists('marketing_planning_queue_items')) {
            throw new RuntimeException('Marketing AI strategy gaps require assistant runs and planning queue tables.');
        }

        $input = $this->sanitizeToolInput($input);
        $userId = (int) ($input['created_by'] ?? $this->currentUserId()) ?: null;
        $context = $this->buildMarketingAiOpportunityContext($input);
        $fallback = $this->deterministicMarketingStrategyGaps($context);
        $bundle = $this->buildMarketingContextBundle('strategy_gap_analysis', $input, ['opportunity_context' => $context]);
        $aiResult = $this->runMarketingAiPrompt(
            'strategy_gap_analysis',
            $bundle,
            $input + ['opportunity_context' => $context],
            'marketing_strategy_gap_analysis',
            fn(): array => $fallback,
            true
        );
        $result = $this->normalizeMarketingAiOpportunityResult((array) ($aiResult['json'] ?? []), $fallback);
        $provider = $aiResult['provider'];
        $provider['side_effects'] = [
            'created_queue_item_ids' => [],
            'external_publish' => false,
            'external_send' => false,
        ];
        $queueIds = $this->createMarketingAiQueueSuggestions(
            (array) ($result['opportunities'] ?? []),
            'phase_5',
            'strategy_gap_analysis',
            $provider,
            (float) ($bundle['bundle_quality']['context_quality_score'] ?? 0),
            $userId
        );
        $provider['side_effects']['created_queue_item_ids'] = $queueIds;

        $runId = $this->createMarketingAssistantRun([
            'assistant_type' => 'strategist',
            'status' => 'completed',
            'prompt_inputs_json' => $input,
            'context_used_json' => [
                'context_completeness' => $context['context_completeness'] ?? [],
                'counts' => $context['counts'] ?? [],
                'context_bundle' => $bundle,
            ],
            'provider_json' => $provider,
            'result_json' => $result + ['queue_item_ids' => $queueIds],
            'created_by' => $userId,
        ]);
        $snapshotId = $this->captureMarketingAiContextSnapshot(
            'strategy_gap',
            'strategy_gap_analysis',
            [
                'context_completeness' => $context['context_completeness'] ?? [],
                'counts' => $context['counts'] ?? [],
                'context_bundle' => $bundle,
            ],
            $provider,
            ['assistant_run_id' => $runId],
            $userId
        );

        return [
            'assistant_run_id' => $runId,
            'context_snapshot_id' => $snapshotId > 0 ? $snapshotId : null,
            'summary' => (string) ($result['summary'] ?? ''),
            'opportunities' => (array) ($result['opportunities'] ?? []),
            'queue_item_ids' => $queueIds,
            'provider' => $provider,
        ];
    }

    public function runMarketingCampaignPlanner(array $input = []): array
    {
        $this->assertMarketingPermission('marketing.write');
        if (!Database::tableExists('marketing_assistant_runs') || !Database::tableExists('marketing_planning_queue_items')) {
            throw new RuntimeException('Marketing AI campaign planner requires assistant runs and planning queue tables.');
        }

        $input = $this->sanitizeToolInput($input);
        $workspaceId = $this->workspaceId();
        foreach ([
            'campaign_id' => 'campaigns',
            'persona_id' => 'marketing_personas',
            'offer_context_item_id' => 'marketing_context_items',
        ] as $field => $table) {
            $id = (int) ($input[$field] ?? 0);
            if ($id > 0) {
                $this->assertWorkspaceRecord($table, $id, $workspaceId);
                if ($field === 'offer_context_item_id') {
                    $this->assertContextItemType($id, 'offer', $workspaceId);
                }
            }
        }

        $userId = (int) ($input['created_by'] ?? $this->currentUserId()) ?: null;
        $linkedRecords = $this->buildCampaignPlannerLinkedRecords($input);
        $context = $this->buildMarketingAiOpportunityContext($input) + ['linked_records' => $linkedRecords];
        $fallback = $this->deterministicMarketingCampaignPlan($input, $linkedRecords, $context);
        $bundle = $this->buildMarketingContextBundle('campaign_planner', $input, $linkedRecords + ['opportunity_context' => $context]);
        $aiResult = $this->runMarketingAiPrompt(
            'campaign_planner',
            $bundle,
            $input + ['opportunity_context' => $context],
            'marketing_campaign_planner',
            fn(): array => $fallback,
            true
        );
        $result = $this->normalizeMarketingCampaignPlannerResult((array) ($aiResult['json'] ?? []), $fallback);
        $provider = $aiResult['provider'];
        $provider['side_effects'] = [
            'created_queue_item_ids' => [],
            'created_brief_id' => null,
            'created_content_item_id' => null,
            'created_landing_page_id' => null,
            'external_publish' => false,
            'external_send' => false,
        ];
        $queueIds = $this->createMarketingAiQueueSuggestions(
            (array) ($result['queue_suggestions'] ?? []),
            'phase_6',
            'campaign_planner',
            $provider,
            (float) ($bundle['bundle_quality']['context_quality_score'] ?? 0),
            $userId
        );
        $provider['side_effects']['created_queue_item_ids'] = $queueIds;

        $runId = $this->createMarketingAssistantRun([
            'assistant_type' => 'content_planner',
            'status' => 'completed',
            'prompt_inputs_json' => $input,
            'context_used_json' => [
                'linked_records' => $linkedRecords,
                'counts' => $context['counts'] ?? [],
                'context_bundle' => $bundle,
            ],
            'provider_json' => $provider,
            'result_json' => $result + ['queue_item_ids' => $queueIds],
            'created_by' => $userId,
        ]);
        $snapshotId = $this->captureMarketingAiContextSnapshot(
            'campaign_planner',
            'campaign_planner',
            [
                'linked_records' => $linkedRecords,
                'counts' => $context['counts'] ?? [],
                'context_bundle' => $bundle,
            ],
            $provider,
            [
                'assistant_run_id' => $runId,
                'campaign_id' => (int) ($input['campaign_id'] ?? 0) ?: null,
            ],
            $userId
        );

        return [
            'assistant_run_id' => $runId,
            'context_snapshot_id' => $snapshotId > 0 ? $snapshotId : null,
            'summary' => (string) ($result['summary'] ?? ''),
            'campaign_concept' => (string) ($result['campaign_concept'] ?? ''),
            'queue_item_ids' => $queueIds,
            'result' => $result,
            'provider' => $provider,
        ];
    }

    public function runMarketingPerformanceAnalysis(array $input = []): array
    {
        $this->assertMarketingPermission('marketing.write');
        if (!Database::tableExists('marketing_assistant_runs') || !Database::tableExists('marketing_planning_queue_items')) {
            throw new RuntimeException('Marketing AI performance analysis requires assistant runs and planning queue tables.');
        }

        $input = $this->sanitizeToolInput($input);
        $userId = (int) ($input['created_by'] ?? $this->currentUserId()) ?: null;
        $context = $this->buildMarketingAiOpportunityContext($input);
        $performance = $this->getPerformanceSummary();
        $fallback = $this->deterministicMarketingPerformanceAnalysis($performance, $context);
        $bundle = $this->buildMarketingContextBundle('performance_analysis', $input, [
            'performance' => $performance,
            'opportunity_context' => $context,
        ]);
        $aiResult = $this->runMarketingAiPrompt(
            'performance_analysis',
            $bundle,
            $input + ['performance' => $performance, 'opportunity_context' => $context],
            'marketing_performance_analysis',
            fn(): array => $fallback,
            true
        );
        $result = $this->normalizeMarketingPerformanceAnalysisResult((array) ($aiResult['json'] ?? []), $fallback);
        $provider = $aiResult['provider'];
        $provider['side_effects'] = [
            'created_queue_item_ids' => [],
            'analytics_snapshot_modified' => false,
            'draft_overwritten' => false,
            'external_publish' => false,
            'external_send' => false,
        ];
        $queueIds = $this->createMarketingAiQueueSuggestions(
            (array) ($result['queue_suggestions'] ?? []),
            'phase_7',
            'performance_analysis',
            $provider,
            (float) ($bundle['bundle_quality']['context_quality_score'] ?? 0),
            $userId
        );
        $provider['side_effects']['created_queue_item_ids'] = $queueIds;

        $runId = $this->createMarketingAssistantRun([
            'assistant_type' => 'performance_analyst',
            'status' => 'completed',
            'prompt_inputs_json' => $input,
            'context_used_json' => [
                'performance' => $performance,
                'counts' => $context['counts'] ?? [],
                'context_bundle' => $bundle,
            ],
            'provider_json' => $provider,
            'result_json' => $result + ['queue_item_ids' => $queueIds],
            'created_by' => $userId,
        ]);
        $snapshotId = $this->captureMarketingAiContextSnapshot(
            'performance_analysis',
            'performance_analysis',
            [
                'performance' => $performance,
                'counts' => $context['counts'] ?? [],
                'context_bundle' => $bundle,
            ],
            $provider,
            ['assistant_run_id' => $runId],
            $userId
        );

        return [
            'assistant_run_id' => $runId,
            'context_snapshot_id' => $snapshotId > 0 ? $snapshotId : null,
            'summary' => (string) ($result['summary'] ?? ''),
            'working' => (array) ($result['working'] ?? []),
            'weak_spots' => (array) ($result['weak_spots'] ?? []),
            'next_tests' => (array) ($result['next_tests'] ?? []),
            'queue_item_ids' => $queueIds,
            'result' => $result,
            'provider' => $provider,
        ];
    }

    public function getMarketingIntegrationReadiness(int $detailLimit = 250): array
    {
        $detailLimit = min(max($detailLimit, 1), 250);
        $distributionPostCount = $this->marketingWorkspaceRecordCount('marketing_distribution_posts');
        $channelBundleCount = $this->marketingWorkspaceRecordCount('marketing_channel_export_bundles');
        $readyBundleCount = $this->marketingWorkspaceRecordCount('marketing_channel_export_bundles', "status = 'ready'");
        $exportedBundleCount = $this->marketingWorkspaceRecordCount('marketing_channel_export_bundles', "status = 'exported'");
        $draftBundleCount = $this->marketingWorkspaceRecordCount('marketing_channel_export_bundles', "status = 'draft'");
        $emailRunCount = $this->marketingWorkspaceRecordCount('marketing_email_campaign_runs');
        $readyEmailRunCount = $this->marketingWorkspaceRecordCount('marketing_email_campaign_runs', "status = 'ready'");
        $exportedEmailRunCount = $this->marketingWorkspaceRecordCount('marketing_email_campaign_runs', "status = 'exported'");
        $landingPageCount = $this->marketingWorkspaceRecordCount('marketing_landing_pages');
        $publishedLandingTokenCount = (
            Database::tableExists('marketing_landing_pages')
            && Database::columnExists('marketing_landing_pages', 'publication_status')
            && Database::columnExists('marketing_landing_pages', 'public_token')
        ) ? $this->marketingWorkspaceRecordCount('marketing_landing_pages', "publication_status = 'published' AND COALESCE(public_token, '') <> ''") : 0;
        $utmLinkCount = $this->marketingWorkspaceRecordCount('marketing_utm_links');
        $pendingApprovalCount = $this->marketingWorkspaceRecordCount('marketing_content_approvals', "status = 'pending'");
        $openAssetRequestCount = $this->marketingWorkspaceRecordCount('marketing_asset_requests', "status IN ('requested','in_progress')");
        $distributionWithoutBundleCount = $this->marketingDistributionWithoutBundleCount();
        $postsMissingChecklistCount = $this->marketingDistributionMissingChecklistCount();
        $emailRunsMissingChecklistCount = $this->marketingEmailRunsMissingChecklistCount();

        $distributionPosts = Database::tableExists('marketing_distribution_posts') ? $this->listDistributionPosts([], $detailLimit, 0) : [];
        $channelBundles = Database::tableExists('marketing_channel_export_bundles') ? $this->listChannelExportBundles([], $detailLimit, 0) : [];
        $emailRuns = Database::tableExists('marketing_email_campaign_runs') ? $this->listEmailCampaignRuns([], $detailLimit, 0) : [];
        $landingPages = Database::tableExists('marketing_landing_pages') ? $this->listLandingPages([], $detailLimit, 0) : [];
        $utmLinks = Database::tableExists('marketing_utm_links') ? $this->listUtmLinks([], $detailLimit, 0) : [];
        $pendingApprovals = Database::tableExists('marketing_content_approvals') ? $this->listContentApprovals(['status' => 'pending'], $detailLimit, 0) : [];
        $openAssetRequests = Database::tableExists('marketing_asset_requests') ? $this->listAssetRequests(['open' => true], $detailLimit, 0) : [];
        $systemConnections = $this->marketingSystemConnectionReadiness();

        $bundledDistributionIds = array_values(array_unique(array_map(
            static fn(array $bundle): int => (int) ($bundle['distribution_post_id'] ?? 0),
            $channelBundles
        )));
        $distributionWithoutBundles = [];
        $postsMissingAssets = [];
        $postsMissingChecklist = [];
        foreach ($distributionPosts as $post) {
            $postId = (int) ($post['id'] ?? 0);
            if (!in_array((string) ($post['status'] ?? ''), ['draft', 'scheduled'], true)) {
                continue;
            }
            if ($postId > 0 && !in_array($postId, $bundledDistributionIds, true)) {
                $distributionWithoutBundles[] = [
                    'id' => $postId,
                    'title' => (string) ($post['content_title'] ?? 'Distribution post'),
                    'channel' => (string) ($post['channel'] ?? 'other'),
                ];
            }
            if (!$this->channelAssetReadiness($post)['ready']) {
                $postsMissingAssets[] = [
                    'id' => $postId,
                    'title' => (string) ($post['content_title'] ?? 'Distribution post'),
                    'channel' => (string) ($post['channel'] ?? 'other'),
                ];
            }
            $requiredFields = (array) ($post['required_fields_json'] ?? []);
            $checklist = (array) ($post['publishing_checklist_json'] ?? []);
            if ($requiredFields === [] || $checklist === []) {
                $postsMissingChecklist[] = [
                    'id' => $postId,
                    'title' => (string) ($post['content_title'] ?? 'Distribution post'),
                    'channel' => (string) ($post['channel'] ?? 'other'),
                ];
            }
        }

        $draftBundles = array_values(array_filter(
            $channelBundles,
            static fn(array $bundle): bool => (string) ($bundle['status'] ?? '') === 'draft'
        ));
        $emailRunsMissingChecklist = [];
        foreach ($emailRuns as $run) {
            if (!in_array((string) ($run['status'] ?? ''), ['draft', 'ready'], true)) {
                continue;
            }
            $missing = [];
            if (trim((string) ($run['subject'] ?? '')) === '') {
                $missing[] = 'subject';
            }
            if (trim((string) ($run['body_snapshot'] ?? '')) === '') {
                $missing[] = 'body_snapshot';
            }
            if ((array) ($run['send_checklist_json'] ?? []) === []) {
                $missing[] = 'send_checklist';
            }
            if ((array) ($run['export_bundle_json'] ?? []) === []) {
                $missing[] = 'export_bundle';
            }
            if ($missing !== []) {
                $emailRunsMissingChecklist[] = [
                    'id' => (int) ($run['id'] ?? 0),
                    'name' => (string) ($run['name'] ?? 'Email run'),
                    'missing' => $missing,
                ];
            }
        }

        $landingNotReady = [];
        $landingReadyWithoutToken = [];
        foreach ($landingPages as $page) {
            $readiness = $this->calculateLandingPagePublishingReadiness($page);
            if (!empty($readiness['missing'])) {
                $landingNotReady[] = [
                    'id' => (int) ($page['id'] ?? 0),
                    'title' => (string) ($page['title'] ?? 'Landing page'),
                    'missing' => (array) $readiness['missing'],
                    'score' => (int) ($readiness['score'] ?? 0),
                ];
                continue;
            }
            if ((string) ($page['publication_status'] ?? '') !== 'published' || trim((string) ($page['public_token'] ?? '')) === '') {
                $landingReadyWithoutToken[] = [
                    'id' => (int) ($page['id'] ?? 0),
                    'title' => (string) ($page['title'] ?? 'Landing page'),
                    'score' => (int) ($readiness['score'] ?? 0),
                ];
            }
        }

        $needsUtm = ($distributionPostCount > 0 || $landingPageCount > 0 || $emailRunCount > 0) && $utmLinkCount === 0;
        $checks = [
            'channel_exports' => [
                'ready' => $distributionWithoutBundleCount === 0 && $draftBundleCount === 0,
                'counts' => [
                    'distribution_posts' => $distributionPostCount,
                    'bundles' => $channelBundleCount,
                    'ready_bundles' => $readyBundleCount,
                    'exported_bundles' => $exportedBundleCount,
                    'distribution_posts_without_bundle' => $distributionWithoutBundleCount,
                ],
                'missing' => [
                    'distribution_posts_without_bundle' => $distributionWithoutBundles,
                    'draft_bundles' => array_map(static fn(array $bundle): int => (int) ($bundle['id'] ?? 0), $draftBundles),
                ],
            ],
            'email_exports' => [
                'ready' => $emailRunsMissingChecklistCount === 0,
                'counts' => [
                    'runs' => $emailRunCount,
                    'ready_runs' => $readyEmailRunCount,
                    'exported_runs' => $exportedEmailRunCount,
                    'runs_missing_checklist' => $emailRunsMissingChecklistCount,
                ],
                'missing' => ['runs_missing_checklist' => $emailRunsMissingChecklist],
            ],
            'landing_page_tokens' => [
                'ready' => $landingNotReady === [] && $landingReadyWithoutToken === [],
                'counts' => [
                    'landing_pages' => $landingPageCount,
                    'published_tokens' => $publishedLandingTokenCount,
                ],
                'missing' => [
                    'not_ready' => $landingNotReady,
                    'ready_without_token' => $landingReadyWithoutToken,
                ],
            ],
            'utm_links' => [
                'ready' => !$needsUtm,
                'counts' => ['utm_links' => $utmLinkCount],
                'missing' => ['needs_utm_links' => $needsUtm],
            ],
            'approvals' => [
                'ready' => $pendingApprovalCount === 0,
                'counts' => ['pending' => $pendingApprovalCount],
                'missing' => ['pending_approvals' => array_map(static fn(array $approval): int => (int) ($approval['id'] ?? 0), $pendingApprovals)],
            ],
            'assets' => [
                'ready' => $postsMissingAssets === [] && $openAssetRequestCount === 0,
                'counts' => [
                    'posts_missing_assets' => count($postsMissingAssets),
                    'open_asset_requests' => $openAssetRequestCount,
                ],
                'missing' => [
                    'posts_missing_assets' => $postsMissingAssets,
                    'open_asset_requests' => array_map(static fn(array $request): int => (int) ($request['id'] ?? 0), $openAssetRequests),
                ],
            ],
            'destination_checklists' => [
                'ready' => $postsMissingChecklistCount === 0 && !$needsUtm && $emailRunsMissingChecklistCount === 0,
                'counts' => ['distribution_posts_missing_checklist' => $postsMissingChecklistCount],
                'missing' => [
                    'distribution_posts_missing_checklist' => $postsMissingChecklist,
                    'utm_links_missing' => $needsUtm,
                    'email_runs_missing_checklist' => $emailRunsMissingChecklist,
                ],
            ],
            'crm_connections' => [
                'ready' => count(array_filter($systemConnections, static fn(array $connection): bool => (string) ($connection['status'] ?? '') !== 'ready')) === 0,
                'counts' => [
                    'ready' => count(array_filter($systemConnections, static fn(array $connection): bool => (string) ($connection['status'] ?? '') === 'ready')),
                    'attention' => count(array_filter($systemConnections, static fn(array $connection): bool => (string) ($connection['status'] ?? '') === 'attention')),
                    'missing' => count(array_filter($systemConnections, static fn(array $connection): bool => (string) ($connection['status'] ?? '') === 'missing')),
                ],
                'missing' => [
                    'connections' => array_values(array_filter(
                        $systemConnections,
                        static fn(array $connection): bool => (string) ($connection['status'] ?? '') !== 'ready'
                    )),
                ],
            ],
        ];

        $recommendations = $this->marketingIntegrationReadinessRecommendations($checks);
        $readyChecks = count(array_filter($checks, static fn(array $check): bool => !empty($check['ready'])));
        $readinessScore = count($checks) > 0 ? (int) round(($readyChecks / count($checks)) * 100) : 100;

        return [
            'status' => $recommendations === [] ? 'ready' : 'attention',
            'score' => $readinessScore,
            'manual_first' => true,
            'readiness_only' => true,
            'external_publish' => false,
            'external_send' => false,
            'external_social_api' => false,
            'external_email_api' => false,
            'external_ad_api' => false,
            'external_seo_api' => false,
            'performance_safe_detail_limit' => $detailLimit,
            'counts' => [
                'distribution_posts' => $distributionPostCount,
                'channel_export_bundles' => $channelBundleCount,
                'email_runs' => $emailRunCount,
                'landing_pages' => $landingPageCount,
                'utm_links' => $utmLinkCount,
                'pending_approvals' => $pendingApprovalCount,
                'open_asset_requests' => $openAssetRequestCount,
                'system_connections_ready' => (int) ($checks['crm_connections']['counts']['ready'] ?? 0),
                'system_connections_attention' => (int) ($checks['crm_connections']['counts']['attention'] ?? 0),
                'system_connections_missing' => (int) ($checks['crm_connections']['counts']['missing'] ?? 0),
            ],
            'checks' => $checks,
            'system_connections' => $systemConnections,
            'recommendations' => $recommendations,
            'performance' => [
                'detail_limit' => $detailLimit,
                'summary_counts_are_direct' => true,
                'heavy_detail_lists_limited' => true,
            ],
            'generated_at' => date('c'),
        ];
    }

    public function getMarketingCrmLifecycleProfile(array $context = [], int $limit = 8): array
    {
        $this->assertMarketingPermission('marketing.read');
        $limit = min(max($limit, 1), 25);
        $crmContext = $this->marketingCrmLifecycleContext($context);
        $counts = [
            'contacts' => $this->marketingCrmLifecycleCount('contacts', $crmContext),
            'companies' => $this->marketingCrmLifecycleCount('companies', $crmContext),
            'open_deals' => $this->marketingCrmLifecycleCount('deals', $crmContext, Database::columnExists('deals', 'stage') ? "stage NOT IN ('closed_lost')" : '1=1'),
            'won_deals' => $this->marketingCrmLifecycleCount('deals', $crmContext, Database::columnExists('deals', 'stage') ? "stage = 'closed_won'" : '0=1'),
            'campaigns' => $this->marketingCrmLifecycleCount('campaigns', $crmContext, Database::columnExists('campaigns', 'status') ? "status <> 'archived'" : '1=1'),
            'forms' => $this->marketingCrmLifecycleCount('forms', $crmContext),
            'form_submissions' => $this->marketingCrmLifecycleFormSubmissionCount($crmContext),
            'open_tasks' => $this->marketingCrmLifecycleCount('tasks', $crmContext, Database::columnExists('tasks', 'status') ? "COALESCE(status, '') NOT IN ('completed','cancelled')" : '1=1'),
            'audience_segments' => $this->marketingCrmLifecycleCount('marketing_audience_segments', $crmContext, Database::columnExists('marketing_audience_segments', 'status') ? "status <> 'archived'" : '1=1'),
            'content_items' => $this->marketingCrmLifecycleCount('marketing_content_items', $crmContext, Database::columnExists('marketing_content_items', 'status') ? "status <> 'archived'" : '1=1'),
            'landing_pages' => $this->marketingCrmLifecycleCount('marketing_landing_pages', $crmContext, Database::columnExists('marketing_landing_pages', 'status') ? "status <> 'archived'" : '1=1'),
            'utm_links' => $this->marketingCrmLifecycleCount('marketing_utm_links', $crmContext),
            'distribution_posts' => $this->marketingCrmLifecycleCount('marketing_distribution_posts', $crmContext, Database::columnExists('marketing_distribution_posts', 'status') ? "status <> 'archived'" : '1=1'),
            'email_runs' => $this->marketingCrmLifecycleCount('marketing_email_campaign_runs', $crmContext, Database::columnExists('marketing_email_campaign_runs', 'status') ? "status <> 'archived'" : '1=1'),
            'lead_handoffs_open' => $this->marketingCrmLifecycleCount('marketing_lead_handoffs', $crmContext, Database::columnExists('marketing_lead_handoffs', 'status') ? "status IN ('new','assigned','accepted','contacted','qualified')" : '1=1'),
            'customer_nurture_profiles' => $this->marketingCrmLifecycleCount('nurture_profiles', $crmContext, Database::columnExists('nurture_profiles', 'nurture_status') ? "nurture_status <> 'exited'" : '1=1'),
            'attribution_touchpoints' => $this->marketingCrmLifecycleCount('marketing_attribution_touchpoints', $crmContext),
            'conversion_events' => $this->marketingCrmLifecycleCount('marketing_conversion_events', $crmContext),
            'stored_insights' => $this->marketingCrmLifecycleCount('marketing_crm_lifecycle_insights', $crmContext, "status <> 'archived'"),
        ];

        $records = [
            'contacts' => $this->marketingCrmLifecycleRows('contacts', 'id, first_name, last_name, email, stage, lead_source, updated_at', $crmContext, '1=1', 'updated_at DESC, id DESC', $limit),
            'companies' => $this->marketingCrmLifecycleRows('companies', 'id, name, industry, status, updated_at', $crmContext, '1=1', 'updated_at DESC, id DESC', $limit),
            'deals' => $this->marketingCrmLifecycleRows('deals', 'id, title, stage, value, currency, probability, expected_close_date, campaign_id, contact_id, company_id, updated_at', $crmContext, '1=1', 'updated_at DESC, id DESC', $limit),
            'campaigns' => $this->marketingCrmLifecycleRows('campaigns', 'id, name, objective, status, updated_at', $crmContext, '1=1', 'updated_at DESC, id DESC', $limit),
            'content_items' => $this->marketingCrmLifecycleRows('marketing_content_items', 'id, title, content_type, channel, status, campaign_id, updated_at', $crmContext, "status <> 'archived'", 'updated_at DESC, id DESC', $limit),
            'landing_pages' => $this->marketingCrmLifecycleRows('marketing_landing_pages', 'id, title, slug, status, campaign_id, form_id, updated_at', $crmContext, "status <> 'archived'", 'updated_at DESC, id DESC', $limit),
            'tasks' => $this->marketingCrmLifecycleRows('tasks', 'id, title, status, priority, due_date, contact_id, deal_id, updated_at', $crmContext, Database::columnExists('tasks', 'status') ? "COALESCE(status, '') NOT IN ('completed','cancelled')" : '1=1', 'updated_at DESC, id DESC', $limit),
            'customer_nurture_profiles' => $this->marketingCrmLifecycleRows('nurture_profiles', 'id, contact_id, lifecycle_lane, nurture_status, next_touch_at, health_score, updated_at', $crmContext, Database::columnExists('nurture_profiles', 'nurture_status') ? "nurture_status <> 'exited'" : '1=1', 'updated_at DESC, id DESC', $limit),
            'attribution_touchpoints' => $this->marketingCrmLifecycleRows('marketing_attribution_touchpoints', 'id, touchpoint_type, source, medium, campaign_name, contact_id, deal_id, occurred_at', $crmContext, '1=1', 'occurred_at DESC, id DESC', $limit),
        ];
        $records['lead_handoffs'] = Database::tableExists('marketing_lead_handoffs')
            ? $this->listLeadHandoffs($this->marketingCrmLifecycleHandoffFilters($crmContext), $limit, 0)
            : [];

        $recommendations = $this->marketingCrmLifecycleRecommendations($crmContext, $counts);
        $readySignals = 0;
        foreach (['contacts', 'campaigns', 'forms', 'content_items', 'landing_pages', 'utm_links', 'attribution_touchpoints', 'lead_handoffs_open', 'customer_nurture_profiles'] as $key) {
            if ((int) ($counts[$key] ?? 0) > 0) {
                $readySignals++;
            }
        }
        $score = (int) round(($readySignals / 9) * 100);
        $status = $score >= 80 ? 'ready' : ($score >= 45 ? 'attention' : 'missing');

        return [
            'scope' => (string) ($crmContext['scope'] ?? 'workspace'),
            'scope_label' => (string) ($crmContext['scope_label'] ?? 'Workspace lifecycle'),
            'ids' => (array) ($crmContext['ids'] ?? []),
            'records' => (array) ($crmContext['records'] ?? []),
            'score' => $score,
            'status' => $status,
            'counts' => $counts,
            'linked_records' => $records,
            'recommendations' => $recommendations,
            'manual_first_boundary' => [
                'external_publish' => false,
                'external_send' => false,
                'external_api_call' => false,
                'operator_confirmation_required' => true,
            ],
            'recommended_product_decision' => 'Treat Marketing as the demand layer of the CRM lifecycle: every campaign, audience, content asset, landing page, and handoff should tie back to contacts, deals, forms, tasks, and attribution.',
            'performance' => [
                'detail_limit' => $limit,
                'summary_counts_are_direct' => true,
                'heavy_detail_lists_limited' => true,
            ],
            'generated_at' => date('c'),
        ];
    }

    public function createMarketingCrmLifecycleInsightSnapshot(array $context = [], ?int $userId = null): array
    {
        $this->assertMarketingPermission('marketing.write');
        if (!Database::tableExists('marketing_crm_lifecycle_insights')) {
            throw new RuntimeException('Marketing CRM lifecycle insights are unavailable.');
        }
        $userId = $userId ?? $this->currentUserId();
        if ($userId > 0) {
            $this->assertWorkspaceUser($userId, $this->workspaceId());
        }
        $profile = $this->getMarketingCrmLifecycleProfile($context, 12);
        $ids = (array) ($profile['ids'] ?? []);

        Database::execute(
            "INSERT INTO marketing_crm_lifecycle_insights
             (workspace_id, uuid, insight_scope, status, readiness_status, lifecycle_score, contact_id, company_id,
              deal_id, campaign_id, form_id, task_id, counts_json, recommendations_json, linked_records_json,
              metadata_json, generated_by, generated_at)
             VALUES (?, ?, ?, 'current', ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, NOW())",
            [
                $this->workspaceId(),
                $this->generateUuid(),
                (string) ($profile['scope'] ?? 'workspace'),
                (string) ($profile['status'] ?? 'attention'),
                (int) ($profile['score'] ?? 0),
                (int) ($ids['contact_id'] ?? 0) ?: null,
                (int) ($ids['company_id'] ?? 0) ?: null,
                (int) ($ids['deal_id'] ?? 0) ?: null,
                (int) ($ids['campaign_id'] ?? 0) ?: null,
                (int) ($ids['form_id'] ?? 0) ?: null,
                (int) ($ids['task_id'] ?? 0) ?: null,
                $this->normalizeJsonValue((array) ($profile['counts'] ?? [])),
                $this->normalizeJsonValue((array) ($profile['recommendations'] ?? [])),
                $this->normalizeJsonValue((array) ($profile['linked_records'] ?? [])),
                $this->normalizeJsonValue([
                    'source' => 'marketing_crm_lifecycle_profile',
                    'scope_label' => (string) ($profile['scope_label'] ?? ''),
                    'manual_first_boundary' => true,
                    'generated_at' => (string) ($profile['generated_at'] ?? date('c')),
                ]),
                $userId > 0 ? $userId : null,
            ]
        );

        return ['id' => (int) Database::lastInsertId(), 'profile' => $profile];
    }

    public function listMarketingCrmLifecycleInsightSnapshots(array $filters = [], int $limit = 100, int $offset = 0): array
    {
        $this->assertMarketingPermission('marketing.read');
        if (!Database::tableExists('marketing_crm_lifecycle_insights')) {
            return [];
        }
        $limit = min(max($limit, 1), 250);
        $offset = max($offset, 0);
        $where = ['workspace_id = ?'];
        $params = [$this->workspaceId()];
        foreach (['contact_id', 'company_id', 'deal_id', 'campaign_id', 'form_id', 'task_id'] as $field) {
            if (!empty($filters[$field])) {
                $where[] = "{$field} = ?";
                $params[] = (int) $filters[$field];
            }
        }
        if (!empty($filters['insight_scope'])) {
            $where[] = 'insight_scope = ?';
            $params[] = (string) $filters['insight_scope'];
        }
        if (!empty($filters['status'])) {
            $where[] = 'status = ?';
            $params[] = (string) $filters['status'];
        } else {
            $where[] = "status <> 'archived'";
        }

        return array_map(
            fn(array $row): array => $this->hydrateJsonFields($row, ['counts_json', 'recommendations_json', 'linked_records_json', 'metadata_json']),
            Database::query(
                'SELECT * FROM marketing_crm_lifecycle_insights WHERE ' . implode(' AND ', $where) . " ORDER BY generated_at DESC, id DESC LIMIT {$limit} OFFSET {$offset}",
                $params
            )
        );
    }

    public function getMarketingAutomationReadiness(?int $userId = null): array
    {
        $contentTotal = $this->countContent("status <> 'archived'");
        $scheduledContent = $this->countContent("scheduled_at IS NOT NULL AND status IN ('approved','scheduled')");
        $reviewItems = $this->countContent("status = 'review'");
        $pendingApprovals = $this->marketingWorkspaceRecordCount('marketing_content_approvals', "status = 'pending'");
        $calendarUpcoming = $this->marketingWorkspaceRecordCount('marketing_calendar_milestones', "milestone_date >= CURDATE() AND status <> 'archived'");
        $distributionOpen = $this->marketingWorkspaceRecordCount('marketing_distribution_posts', "status IN ('draft','scheduled')");
        $distributionScheduled = $this->marketingWorkspaceRecordCount('marketing_distribution_posts', "status = 'scheduled'");
        $channelBundlesReady = $this->marketingWorkspaceRecordCount('marketing_channel_export_bundles', "status = 'ready'");
        $emailRunsOpen = $this->marketingWorkspaceRecordCount('marketing_email_campaign_runs', "status IN ('draft','ready')");
        $emailRunsReady = $this->marketingWorkspaceRecordCount('marketing_email_campaign_runs', "status = 'ready'");
        $launchReadinessReady = $this->marketingWorkspaceRecordCount('marketing_launch_readiness_reviews', "status IN ('ready','approved')");
        $launchControlReady = $this->marketingWorkspaceRecordCount('marketing_launch_control_records', "status = 'ready'");
        $launchChecklistsOpen = $this->marketingWorkspaceRecordCount('marketing_campaign_launch_checklists', "status IN ('draft','ready','blocked')");
        $activeRhythms = $this->marketingWorkspaceRecordCount('marketing_recurring_rhythms', "status = 'active'");
        $openQueue = $this->marketingWorkspaceRecordCount('marketing_planning_queue_items', "status IN ('planned','in_progress','blocked')");
        $overdueQueue = $this->marketingWorkspaceRecordCount('marketing_planning_queue_items', "due_at IS NOT NULL AND due_at < NOW() AND status NOT IN ('done','archived')");
        $checklistTemplates = $this->marketingWorkspaceRecordCount('marketing_checklist_templates', "status = 'active'");
        $scheduledReportDrafts = $this->marketingWorkspaceRecordCount('marketing_scheduled_report_drafts', "status IN ('draft','active')");
        $reportExports = $this->marketingWorkspaceRecordCount('marketing_report_exports', "status IN ('draft','generated')");
        $executionQueueDryRunReady = $this->marketingWorkspaceRecordCount('marketing_execution_queue', "status IN ('approved','queued') AND execution_mode IN ('dry_run','test')");
        $executionQueuePending = $this->marketingWorkspaceRecordCount('marketing_execution_queue', "status IN ('draft','pending_approval')");
        $executionQueueBlocked = $this->marketingWorkspaceRecordCount('marketing_execution_queue', "status IN ('failed','blocked') OR execution_mode = 'live'");
        $aiSuggestions = Database::tableExists('marketing_planning_queue_items') ? count($this->listMarketingAiQueueSuggestions('', 25, 0)) : 0;

        $loops = [];
        $addLoop = static function (
            array &$loops,
            string $key,
            string $label,
            string $description,
            int $readySignal,
            int $supportSignal,
            string $href,
            string $nextAction,
            array $metrics = [],
            string $manualTrigger = 'Operator reviews the queue and takes the next manual action.'
        ): void {
            if ($readySignal > 0) {
                $status = 'ready';
                $score = 100;
            } elseif ($supportSignal > 0) {
                $status = 'attention';
                $score = 60;
            } else {
                $status = 'missing';
                $score = 20;
            }

            $loops[$key] = [
                'key' => $key,
                'label' => $label,
                'description' => $description,
                'status' => $status,
                'score' => $score,
                'ready_signal' => $readySignal,
                'support_signal' => $supportSignal,
                'href' => $href,
                'next_action' => $status === 'ready' ? $manualTrigger : $nextAction,
                'metrics' => $metrics,
                'manual_trigger' => $manualTrigger,
                'external_send' => false,
                'external_publish' => false,
                'external_api_call' => false,
            ];
        };

        $addLoop(
            $loops,
            'content_schedule_reminders',
            'Content Schedule Reminders',
            'Scheduled content and calendar milestones that can drive manual reminder workflows.',
            $scheduledContent + $calendarUpcoming + $distributionScheduled,
            $contentTotal,
            'marketing_calendar.php',
            'Schedule approved content or add calendar milestones before relying on reminder workflows.',
            ['scheduled_content' => $scheduledContent, 'calendar_upcoming' => $calendarUpcoming, 'scheduled_distribution' => $distributionScheduled],
            'Review the calendar and manually confirm due content.'
        );
        $addLoop(
            $loops,
            'review_nudges',
            'Review Nudges',
            'Pending reviews that can be surfaced to operators without auto-approving content.',
            $reviewItems + $pendingApprovals,
            $contentTotal,
            'marketing_reviews.php',
            'Request review for draft content before using review nudges.',
            ['content_in_review' => $reviewItems, 'pending_approvals' => $pendingApprovals],
            'Open reviews and manually approve, reject, or request edits.'
        );
        $addLoop(
            $loops,
            'distribution_export_prep',
            'Distribution Export Prep',
            'Manual channel packaging for posts, bundles, assets, and UTM-ready exports.',
            $channelBundlesReady,
            $distributionOpen,
            'marketing_channel_exports.php',
            'Create channel export bundles for distribution posts.',
            ['distribution_open' => $distributionOpen, 'ready_bundles' => $channelBundlesReady],
            'Package and download/export channel bundles manually.'
        );
        $addLoop(
            $loops,
            'email_export_prep',
            'Email Export Prep',
            'Manual email-run preparation without live sending.',
            $emailRunsReady,
            $emailRunsOpen,
            'marketing_email_runs.php',
            'Complete subject, body, audience, unsubscribe text, checklist, and export bundle.',
            ['email_runs_open' => $emailRunsOpen, 'email_runs_ready' => $emailRunsReady],
            'Export email run assets for a human-controlled send.'
        );
        $addLoop(
            $loops,
            'launch_gate_followup',
            'Launch Gate Follow-Up',
            'Launch readiness, checklists, and launch control items that can be reviewed before go-live.',
            $launchReadinessReady + $launchControlReady,
            $launchChecklistsOpen,
            'marketing_launch_control.php',
            'Create launch readiness reviews and checklists before launch follow-up.',
            ['launch_readiness_ready' => $launchReadinessReady, 'launch_control_ready' => $launchControlReady, 'launch_checklists_open' => $launchChecklistsOpen],
            'Open Launch Control and manually mark launch progress.'
        );
        $addLoop(
            $loops,
            'weekly_planning_rhythm',
            'Weekly Planning Rhythm',
            'Recurring planning rhythms, checklist templates, and open queue items.',
            $activeRhythms + $openQueue,
            $checklistTemplates,
            'marketing_operations.php',
            'Create a rhythm or queue item so weekly planning can repeat predictably.',
            ['active_rhythms' => $activeRhythms, 'open_queue' => $openQueue, 'overdue_queue' => $overdueQueue, 'checklist_templates' => $checklistTemplates],
            'Review the weekly queue and manually assign next steps.'
        );
        $addLoop(
            $loops,
            'report_draft_cycle',
            'Report Draft Cycle',
            'Scheduled report drafts and generated report exports for operator review.',
            $scheduledReportDrafts,
            $reportExports,
            'marketing_admin.php',
            'Create scheduled report drafts or generate a report export.',
            ['scheduled_report_drafts' => $scheduledReportDrafts, 'report_exports' => $reportExports],
            'Review report drafts before sharing outside the CRM.'
        );
        $addLoop(
            $loops,
            'dry_run_execution_queue',
            'Dry-Run Execution Queue',
            'Execution queue items prepared for dry-run or test-mode checks only.',
            $executionQueueDryRunReady,
            $executionQueuePending + $executionQueueBlocked,
            'marketing_execution.php',
            'Prepare dry-run execution queue items and resolve pending approvals or blocked entries.',
            ['dry_run_ready' => $executionQueueDryRunReady, 'pending' => $executionQueuePending, 'blocked_or_live' => $executionQueueBlocked],
            'Run a dry-run/test execution attempt; no external channel API is called.'
        );
        $addLoop(
            $loops,
            'ai_followup_queue',
            'AI Follow-Up Queue',
            'AI-created planning suggestions that stay draft-side until an operator accepts them.',
            $aiSuggestions,
            $openQueue,
            'marketing_operations.php',
            'Run Marketing assistants or strategy gap analysis to generate reviewable queue suggestions.',
            ['ai_suggestions' => $aiSuggestions, 'open_queue' => $openQueue],
            'Review AI queue suggestions before changing real work.'
        );

        $status = 'ready';
        foreach ($loops as $loop) {
            if ((string) ($loop['status'] ?? '') === 'missing') {
                $status = $status === 'ready' ? 'attention' : $status;
            }
            if ((string) ($loop['status'] ?? '') === 'attention') {
                $status = 'attention';
            }
        }
        if ($executionQueueBlocked > 0 || $overdueQueue > 0) {
            $status = 'attention';
        }

        $nextActions = [];
        foreach ($loops as $loop) {
            if ((string) ($loop['status'] ?? '') !== 'ready') {
                $nextActions[] = [
                    'label' => (string) ($loop['label'] ?? 'Automation loop'),
                    'href' => (string) ($loop['href'] ?? 'marketing_operations.php'),
                    'reason' => (string) ($loop['next_action'] ?? 'Review automation readiness.'),
                    'status' => (string) ($loop['status'] ?? 'attention'),
                ];
            }
        }
        if ($nextActions === []) {
            $nextActions[] = [
                'label' => 'Review Manual Automation Queue',
                'href' => 'marketing_operations.php',
                'reason' => 'Automation loops are ready for operator review; no external send or publish is triggered.',
                'status' => 'ready',
            ];
        }

        $scores = array_column($loops, 'score');

        return [
            'status' => $status,
            'score' => $scores !== [] ? (int) round(array_sum($scores) / count($scores)) : 0,
            'loops' => $loops,
            'next_actions' => array_slice($nextActions, 0, 6),
            'counts' => [
                'ready' => count(array_filter($loops, static fn(array $loop): bool => (string) ($loop['status'] ?? '') === 'ready')),
                'attention' => count(array_filter($loops, static fn(array $loop): bool => (string) ($loop['status'] ?? '') === 'attention')),
                'missing' => count(array_filter($loops, static fn(array $loop): bool => (string) ($loop['status'] ?? '') === 'missing')),
                'overdue_queue' => $overdueQueue,
                'blocked_or_live_execution' => $executionQueueBlocked,
            ],
            'recommended_product_decision' => 'Keep Marketing automation manual-first until connectors are ready, approvals are explicit, and an operator confirms each external send or publish.',
            'manual_first_boundary' => [
                'external_publish' => false,
                'external_send' => false,
                'external_api_call' => false,
                'automatic_overwrite' => false,
            ],
            'user_id' => $userId,
            'generated_at' => date('c'),
        ];
    }

    public function getMarketingAiWorkspaceBrain(?int $userId = null, ?array $integrationReadiness = null, ?array $automationReadiness = null): array
    {
        $this->assertMarketingPermission('marketing.read');
        $userId = $userId ?? ($this->currentUserId() ?: null);
        $contextCompleteness = Database::tableExists('marketing_context_items')
            ? $this->getContextCompleteness()
            : ['score' => 0, 'counts' => [], 'missing' => ['marketing_context_items']];
        $integrationReadiness = $integrationReadiness ?? $this->getMarketingIntegrationReadiness(20);
        $automationReadiness = $automationReadiness ?? $this->getMarketingAutomationReadiness($userId);

        $contextCounts = (array) ($contextCompleteness['counts'] ?? []);
        $activeCampaigns = 0;
        if (Database::tableExists('campaigns') && Database::columnExists('campaigns', 'workspace_id')) {
            $row = Database::queryOne(
                "SELECT COUNT(*) AS count FROM campaigns WHERE workspace_id = ? AND status = 'active'",
                [$this->workspaceId()]
            );
            $activeCampaigns = (int) ($row['count'] ?? 0);
        }
        $forms = Database::tableExists('forms') && Database::columnExists('forms', 'workspace_id')
            ? (int) (Database::queryOne("SELECT COUNT(*) AS count FROM forms WHERE workspace_id = ?", [$this->workspaceId()])['count'] ?? 0)
            : 0;

        $counts = [
            'brand_profiles' => $this->marketingWorkspaceRecordCount('marketing_brand_profiles'),
            'personas' => $this->marketingWorkspaceRecordCount('marketing_personas'),
            'offers' => (int) ($contextCounts['offer'] ?? 0),
            'proof_points' => (int) ($contextCounts['proof_point'] ?? 0),
            'content_pillars' => (int) ($contextCounts['content_pillar'] ?? 0),
            'default_ctas' => (int) ($contextCounts['default_cta'] ?? 0),
            'compliance_terms' => (int) ($contextCounts['compliance_term'] ?? 0),
            'competitors' => (int) ($contextCounts['competitor'] ?? 0),
            'differentiators' => (int) ($contextCounts['differentiator'] ?? 0),
            'active_campaigns' => $activeCampaigns,
            'campaign_briefs' => $this->marketingWorkspaceRecordCount('marketing_campaign_briefs', Database::columnExists('marketing_campaign_briefs', 'status') ? "status <> 'archived'" : '1=1'),
            'audience_segments' => $this->marketingWorkspaceRecordCount('marketing_audience_segments', Database::columnExists('marketing_audience_segments', 'status') ? "status <> 'archived'" : '1=1'),
            'content_items' => $this->marketingWorkspaceRecordCount('marketing_content_items', "status <> 'archived'"),
            'content_in_review' => $this->marketingWorkspaceRecordCount('marketing_content_items', "status = 'review'"),
            'content_media' => $this->marketingWorkspaceRecordCount('marketing_content_media'),
            'quality_checks' => $this->marketingWorkspaceRecordCount('marketing_ai_quality_checks', Database::columnExists('marketing_ai_quality_checks', 'status') ? "status = 'completed'" : '1=1'),
            'landing_pages' => $this->marketingWorkspaceRecordCount('marketing_landing_pages', Database::columnExists('marketing_landing_pages', 'status') ? "status <> 'archived'" : '1=1'),
            'forms' => $forms,
            'conversion_goals' => $this->marketingWorkspaceRecordCount('marketing_conversion_goals', Database::columnExists('marketing_conversion_goals', 'status') ? "status <> 'archived'" : '1=1'),
            'media_files' => $this->marketingWorkspaceRecordCount('marketing_media_files'),
            'assets' => $this->marketingWorkspaceRecordCount('marketing_assets'),
            'asset_requests' => $this->marketingWorkspaceRecordCount('marketing_asset_requests', Database::columnExists('marketing_asset_requests', 'status') ? "status NOT IN ('archived','completed')" : '1=1'),
            'creative_briefs' => $this->marketingWorkspaceRecordCount('marketing_creative_briefs', Database::columnExists('marketing_creative_briefs', 'status') ? "status <> 'archived'" : '1=1'),
            'approvals_pending' => $this->marketingWorkspaceRecordCount('marketing_content_approvals', "status = 'pending'"),
            'content_versions' => $this->marketingWorkspaceRecordCount('marketing_content_versions'),
            'comments_open' => $this->marketingWorkspaceRecordCount('marketing_content_comments', "resolved_at IS NULL"),
            'launch_checklists' => $this->marketingWorkspaceRecordCount('marketing_campaign_launch_checklists', Database::columnExists('marketing_campaign_launch_checklists', 'status') ? "status <> 'archived'" : '1=1'),
            'execution_action_snapshots' => $this->marketingWorkspaceRecordCount('marketing_execution_action_snapshots', "snapshot_status = 'current'"),
            'distribution_posts' => $this->marketingWorkspaceRecordCount('marketing_distribution_posts', Database::columnExists('marketing_distribution_posts', 'status') ? "status <> 'archived'" : '1=1'),
            'channel_export_bundles' => $this->marketingWorkspaceRecordCount('marketing_channel_export_bundles'),
            'email_runs' => $this->marketingWorkspaceRecordCount('marketing_email_campaign_runs', Database::columnExists('marketing_email_campaign_runs', 'status') ? "status <> 'archived'" : '1=1'),
            'utm_links' => $this->marketingWorkspaceRecordCount('marketing_utm_links'),
            'analytics_snapshots' => $this->marketingWorkspaceRecordCount('marketing_analytics_snapshots'),
            'tracking_events' => $this->marketingWorkspaceRecordCount('marketing_tracking_events'),
            'attribution_touchpoints' => $this->marketingWorkspaceRecordCount('marketing_attribution_touchpoints'),
            'lead_handoffs' => $this->marketingWorkspaceRecordCount('marketing_lead_handoffs'),
        ];

        $statusForScore = static function (int $score): string {
            if ($score >= 80) {
                return 'ready';
            }
            if ($score >= 35) {
                return 'attention';
            }

            return 'missing';
        };
        $coverage = [];
        $addCoverage = static function (
            array &$coverage,
            string $key,
            string $label,
            int $score,
            string $href,
            string $readyMessage,
            string $missingMessage,
            array $metrics = []
        ) use ($statusForScore): void {
            $score = max(0, min(100, $score));
            $status = $statusForScore($score);
            $coverage[$key] = [
                'key' => $key,
                'label' => $label,
                'score' => $score,
                'status' => $status,
                'href' => $href,
                'message' => $status === 'ready' ? $readyMessage : $missingMessage,
                'metrics' => $metrics,
            ];
        };

        $requiredContext = ['offer', 'proof_point', 'content_pillar', 'default_cta', 'compliance_term', 'competitor', 'differentiator'];
        $presentContext = 0;
        foreach ($requiredContext as $type) {
            if ((int) ($contextCounts[$type] ?? 0) > 0) {
                $presentContext++;
            }
        }
        $contextScore = (int) round(($presentContext / max(1, count($requiredContext))) * 100);

        $addCoverage($coverage, 'brand_voice', 'Brand Voice', $counts['brand_profiles'] > 0 ? 100 : 0, 'marketing_brand.php', 'Brand voice, tone, value props, and CTAs are available for AI.', 'Add a brand profile so AI drafts stop sounding generic.', ['brand_profiles' => $counts['brand_profiles']]);
        $addCoverage($coverage, 'personas', 'Personas', $counts['personas'] > 0 ? 100 : 0, 'marketing_personas.php', 'Audience personas are available for targeting and copy fit.', 'Add at least one persona so AI can write to a concrete buyer.', ['personas' => $counts['personas']]);
        $addCoverage($coverage, 'offer_proof_context', 'Offer And Proof Context', $contextScore, 'marketing_context.php', 'Offers, proof, pillars, CTAs, competitors, differentiators, and compliance terms are covered.', 'Fill the Context Hub with offer, proof, CTA, compliance, competitor, and differentiator records.', array_intersect_key($counts, array_flip(['offers', 'proof_points', 'content_pillars', 'default_ctas', 'compliance_terms', 'competitors', 'differentiators'])));
        $addCoverage($coverage, 'campaign_strategy', 'Campaign Strategy', min(100, ($counts['campaign_briefs'] > 0 ? 45 : 0) + ($counts['active_campaigns'] > 0 ? 30 : 0) + ($counts['audience_segments'] > 0 ? 25 : 0)), 'marketing_campaign_workspace.php', 'Campaign, brief, and audience strategy can guide AI recommendations.', 'Connect an active campaign, campaign brief, and audience segment before relying on AI strategy.', array_intersect_key($counts, array_flip(['active_campaigns', 'campaign_briefs', 'audience_segments'])));
        $addCoverage($coverage, 'content_creation', 'Content Creation', min(100, ($counts['content_items'] > 0 ? 40 : 0) + ($counts['content_in_review'] > 0 ? 15 : 0) + ($counts['content_media'] > 0 ? 20 : 0) + ($counts['quality_checks'] > 0 ? 25 : 0)), 'marketing_content.php', 'Content, media, and quality signals are available for AI drafting.', 'Create content items, attach media, and run quality checks so AI has a real content baseline.', array_intersect_key($counts, array_flip(['content_items', 'content_in_review', 'content_media', 'quality_checks'])));
        $addCoverage($coverage, 'landing_conversion', 'Landing Conversion', min(100, ($counts['landing_pages'] > 0 ? 35 : 0) + ($counts['forms'] > 0 ? 20 : 0) + ($counts['conversion_goals'] > 0 ? 25 : 0) + ($counts['tracking_events'] > 0 ? 20 : 0)), 'marketing_landing_pages.php', 'Landing pages, forms, goals, and tracking can shape conversion recommendations.', 'Add a landing page, form, conversion goal, or tracking signal for stronger conversion guidance.', array_intersect_key($counts, array_flip(['landing_pages', 'forms', 'conversion_goals', 'tracking_events'])));
        $addCoverage($coverage, 'media_creative', 'Media And Creative', min(100, ($counts['media_files'] > 0 ? 45 : 0) + ($counts['assets'] > 0 ? 20 : 0) + ($counts['creative_briefs'] > 0 ? 20 : 0) + ($counts['asset_requests'] > 0 ? 15 : 0)), 'marketing_assets.php', 'Creative assets and media context are available for visual recommendations.', 'Add images, videos, creative briefs, or asset requests to support visual AI recommendations.', array_intersect_key($counts, array_flip(['media_files', 'assets', 'creative_briefs', 'asset_requests'])));
        $addCoverage($coverage, 'review_governance', 'Review Governance', min(100, ($counts['content_versions'] > 0 ? 25 : 0) + ($counts['approvals_pending'] > 0 ? 25 : 0) + ($counts['comments_open'] > 0 ? 15 : 0) + ($counts['launch_checklists'] > 0 ? 35 : 0)), 'marketing_reviews.php', 'Review, version, comments, and launch governance can constrain AI suggestions.', 'Route content through versions, comments, approvals, or launch checklists before AI recommends execution.', array_intersect_key($counts, array_flip(['content_versions', 'approvals_pending', 'comments_open', 'launch_checklists'])));
        $addCoverage($coverage, 'distribution_execution', 'Distribution And Execution', min(100, ($counts['distribution_posts'] > 0 ? 25 : 0) + ($counts['channel_export_bundles'] > 0 ? 30 : 0) + ($counts['email_runs'] > 0 ? 20 : 0) + ($counts['utm_links'] > 0 ? 25 : 0)), 'marketing_channel_exports.php', 'Manual distribution, email runs, exports, and UTMs can guide execution recommendations.', 'Create manual distribution posts, export bundles, email runs, and UTM links before execution planning.', array_intersect_key($counts, array_flip(['distribution_posts', 'channel_export_bundles', 'email_runs', 'utm_links'])));
        $addCoverage($coverage, 'execution_evidence', 'Execution Evidence', $counts['execution_action_snapshots'] > 0 ? 100 : 0, 'marketing_campaign_workspace.php', 'Saved action snapshots can ground AI recommendations in durable launch evidence.', 'Save an execution action snapshot from a campaign workspace before using AI for launch handoff advice.', array_intersect_key($counts, array_flip(['execution_action_snapshots', 'launch_checklists', 'channel_export_bundles'])));
        $addCoverage($coverage, 'analytics_feedback', 'Analytics Feedback', min(100, ($counts['analytics_snapshots'] > 0 ? 25 : 0) + ($counts['tracking_events'] > 0 ? 25 : 0) + ($counts['attribution_touchpoints'] > 0 ? 25 : 0) + ($counts['lead_handoffs'] > 0 ? 25 : 0)), 'marketing_performance.php', 'Analytics, tracking, attribution, and handoff signals can inform AI performance analysis.', 'Capture analytics, tracking, attribution, or lead handoff data before trusting performance advice.', array_intersect_key($counts, array_flip(['analytics_snapshots', 'tracking_events', 'attribution_touchpoints', 'lead_handoffs'])));
        $addCoverage($coverage, 'crm_integration', 'CRM Integration', (int) ($integrationReadiness['score'] ?? 0), 'marketing_admin.php', 'CRM connections are ready enough for Marketing AI to use cross-system context.', 'Review integration readiness so AI can account for campaigns, forms, CRM tasks, attribution, and handoffs.', ['score' => (int) ($integrationReadiness['score'] ?? 0), 'status' => (string) ($integrationReadiness['status'] ?? 'attention')]);
        $addCoverage($coverage, 'automation_independence', 'Automation Independence', (int) ($automationReadiness['score'] ?? 0), 'marketing_operations.php', 'Manual-first automation loops are ready for operator-controlled follow-up.', 'Prepare manual automation loops before AI recommends repeated operating rhythms.', ['score' => (int) ($automationReadiness['score'] ?? 0), 'status' => (string) ($automationReadiness['status'] ?? 'attention')]);

        $scores = array_map(static fn(array $item): int => (int) ($item['score'] ?? 0), $coverage);
        $score = $scores !== [] ? (int) round(array_sum($scores) / count($scores)) : 0;
        $missingContext = array_values(array_map(
            static fn(array $item): array => [
                'key' => (string) ($item['key'] ?? ''),
                'label' => (string) ($item['label'] ?? ''),
                'href' => (string) ($item['href'] ?? 'marketing.php'),
                'message' => (string) ($item['message'] ?? ''),
                'score' => (int) ($item['score'] ?? 0),
            ],
            array_filter($coverage, static fn(array $item): bool => (string) ($item['status'] ?? '') !== 'ready')
        ));
        usort($missingContext, static fn(array $a, array $b): int => ($a['score'] <=> $b['score']));
        $recommendedInputs = array_map(
            static fn(array $item): string => $item['label'] . ': ' . $item['message'],
            array_slice($missingContext, 0, 6)
        );
        if ($recommendedInputs === []) {
            $recommendedInputs[] = 'Use the current workspace context, explain which records informed the result, and keep outputs draft-side until a human reviews them.';
        }

        $usedContextKeys = array_values(array_map(
            static fn(array $item): string => (string) ($item['key'] ?? ''),
            array_filter($coverage, static fn(array $item): bool => (int) ($item['score'] ?? 0) > 0)
        ));

        return [
            'score' => $score,
            'status' => $statusForScore($score) === 'missing' ? 'thin' : $statusForScore($score),
            'coverage' => $coverage,
            'counts' => $counts,
            'missing_context' => $missingContext,
            'recommended_inputs' => $recommendedInputs,
            'used_context_keys' => $usedContextKeys,
            'context_completeness' => $contextCompleteness,
            'integration_summary' => [
                'score' => (int) ($integrationReadiness['score'] ?? 0),
                'status' => (string) ($integrationReadiness['status'] ?? 'attention'),
                'counts' => (array) ($integrationReadiness['counts'] ?? []),
            ],
            'automation_summary' => [
                'score' => (int) ($automationReadiness['score'] ?? 0),
                'status' => (string) ($automationReadiness['status'] ?? 'attention'),
                'counts' => (array) ($automationReadiness['counts'] ?? []),
            ],
            'safe_usage_policy' => [
                'manual_first' => true,
                'external_publish' => false,
                'external_send' => false,
                'external_social_api' => false,
                'external_email_api' => false,
                'external_ad_api' => false,
                'external_seo_api' => false,
                'automatic_overwrite' => false,
                'requires_human_review' => true,
            ],
            'recommended_product_decision' => 'Use this AI workspace brain as the context gate before assistants, drafts, launch recommendations, and automation suggestions. Keep execution manual-first until connectors, approvals, and explicit operator confirmation are all present.',
            'performance' => [
                'summary_counts_are_direct' => true,
                'integration_detail_limit' => (int) ($integrationReadiness['performance']['detail_limit'] ?? 20),
                'heavy_detail_lists_limited' => true,
            ],
            'user_id' => $userId,
            'generated_at' => date('c'),
        ];
    }

    public function runMarketingIntegrationReadinessReview(array $input = []): array
    {
        $this->assertMarketingPermission('marketing.write');
        if (!Database::tableExists('marketing_assistant_runs') || !Database::tableExists('marketing_planning_queue_items')) {
            throw new RuntimeException('Marketing AI integration readiness review requires assistant runs and planning queue tables.');
        }

        $input = $this->sanitizeToolInput($input);
        $userId = (int) ($input['created_by'] ?? $this->currentUserId()) ?: null;
        $readiness = $this->getMarketingIntegrationReadiness();
        $fallback = $this->deterministicMarketingIntegrationReadinessReview($readiness);
        $context = $this->buildMarketingAiOpportunityContext($input);
        $bundle = $this->buildMarketingContextBundle('integration_readiness', $input, [
            'integration_readiness' => $readiness,
            'opportunity_context' => $context,
        ]);
        $aiResult = $this->runMarketingAiPrompt(
            'integration_readiness',
            $bundle,
            $input + ['integration_readiness' => $readiness],
            'marketing_integration_readiness',
            fn(): array => $fallback,
            true
        );
        $result = $this->normalizeMarketingAiOpportunityResult((array) ($aiResult['json'] ?? []), $fallback);
        $provider = $aiResult['provider'];
        $provider['side_effects'] = [
            'created_queue_item_ids' => [],
            'external_publish' => false,
            'external_send' => false,
            'landing_publication_changed' => false,
            'channel_export_status_changed' => false,
            'email_run_status_changed' => false,
        ];
        $queueIds = $this->createMarketingAiQueueSuggestions(
            (array) ($result['opportunities'] ?? []),
            'phase_8',
            'integration_readiness',
            $provider,
            (float) ($bundle['bundle_quality']['context_quality_score'] ?? 0),
            $userId
        );
        $provider['side_effects']['created_queue_item_ids'] = $queueIds;

        $runId = $this->createMarketingAssistantRun([
            'assistant_type' => 'strategist',
            'status' => 'completed',
            'prompt_inputs_json' => $input,
            'context_used_json' => [
                'integration_readiness' => $readiness,
                'counts' => $readiness['counts'] ?? [],
                'context_bundle' => $bundle,
            ],
            'provider_json' => $provider,
            'result_json' => $result + ['queue_item_ids' => $queueIds, 'readiness_status' => $readiness['status'] ?? 'attention'],
            'created_by' => $userId,
        ]);
        $snapshotId = $this->captureMarketingAiContextSnapshot(
            'integration_readiness',
            'integration_readiness',
            [
                'integration_readiness' => $readiness,
                'counts' => $readiness['counts'] ?? [],
                'context_bundle' => $bundle,
            ],
            $provider,
            ['assistant_run_id' => $runId],
            $userId
        );

        return [
            'assistant_run_id' => $runId,
            'context_snapshot_id' => $snapshotId > 0 ? $snapshotId : null,
            'readiness' => $readiness,
            'summary' => (string) ($result['summary'] ?? ''),
            'opportunities' => (array) ($result['opportunities'] ?? []),
            'queue_item_ids' => $queueIds,
            'provider' => $provider,
        ];
    }

    public function updatePlanningQueueStatus(int $id, string $status): bool
    {
        $this->assertMarketingPermission('marketing.write');
        $status = $this->normalizeEnum($status, self::PLANNING_QUEUE_STATUSES, 'queue_status');
        $rows = Database::execute(
            'UPDATE marketing_planning_queue_items SET status = ? WHERE workspace_id = ? AND id = ?',
            [$status, $this->workspaceId(), $id]
        );

        return $rows > 0;
    }

    public function listChecklistTemplates(array $filters = [], int $limit = 100, int $offset = 0): array
    {
        if (!Database::tableExists('marketing_checklist_templates')) {
            return [];
        }

        $limit = min(max($limit, 1), 250);
        $offset = max($offset, 0);
        $workspace = $this->workspaceClause('ct.');
        $where = [$workspace['sql']];
        $params = $workspace['params'];
        if (!empty($filters['id'])) {
            $where[] = 'ct.id = ?';
            $params[] = (int) $filters['id'];
        }
        if (!empty($filters['status'])) {
            $where[] = 'ct.status = ?';
            $params[] = $this->normalizeEnum((string) $filters['status'], self::CHECKLIST_TEMPLATE_STATUSES, 'checklist_status');
        }
        if (!empty($filters['template_type'])) {
            $where[] = 'ct.template_type = ?';
            $params[] = $this->normalizeEnum((string) $filters['template_type'], self::CHECKLIST_TEMPLATE_TYPES, 'checklist_type');
        }

        return array_map(
            fn(array $row): array => $this->hydrateJsonFields($row, ['checklist_json', 'metadata_json']),
            Database::query(
                "SELECT ct.*, creator.email AS created_by_email
                 FROM marketing_checklist_templates ct
                 LEFT JOIN users creator ON creator.id = ct.created_by
                 WHERE " . implode(' AND ', $where) . "
                 ORDER BY ct.updated_at DESC, ct.name ASC
                 LIMIT {$limit} OFFSET {$offset}",
                $params
            )
        );
    }

    public function createChecklistTemplate(array $data): int
    {
        $this->assertMarketingPermission('marketing.write');
        $normalized = $this->normalizeChecklistTemplateData($data);
        Database::execute(
            "INSERT INTO marketing_checklist_templates
             (workspace_id, uuid, name, template_type, checklist_json, status, metadata_json, created_by)
             VALUES (?, ?, ?, ?, ?, ?, ?, ?)",
            [
                $this->workspaceId(),
                $this->generateUuid(),
                $normalized['name'],
                $normalized['template_type'],
                $normalized['checklist_json'],
                $normalized['status'],
                $normalized['metadata_json'],
                $normalized['created_by'],
            ]
        );

        return (int) Database::lastInsertId();
    }

    public function getMarketingOperatingReport(?string $weekStart = null): array
    {
        $weekStart = $this->normalizeWeekStart($weekStart);
        $weekEnd = date('Y-m-d', strtotime($weekStart . ' +6 days'));
        if (!Database::tableExists('marketing_planning_queue_items')) {
            return [
                'week_start' => $weekStart,
                'week_end' => $weekEnd,
                'counts' => [],
                'rhythms' => [],
                'queue' => [],
                'overdue' => [],
                'checklist_templates' => [],
            ];
        }

        $quotedWeekStart = str_replace("'", "''", $weekStart);
        $counts = [
            'active_rhythms' => Database::tableExists('marketing_recurring_rhythms') ? $this->countRows('marketing_recurring_rhythms', "status = 'active'") : 0,
            'queue_this_week' => $this->countRows('marketing_planning_queue_items', "week_start = '{$quotedWeekStart}' AND status <> 'archived'"),
            'open_queue' => $this->countRows('marketing_planning_queue_items', "status IN ('planned','in_progress','blocked')"),
            'blocked_queue' => $this->countRows('marketing_planning_queue_items', "status = 'blocked'"),
            'completed_this_week' => $this->countRows('marketing_planning_queue_items', "week_start = '{$quotedWeekStart}' AND status = 'done'"),
            'overdue_queue' => $this->countRows('marketing_planning_queue_items', "due_at IS NOT NULL AND due_at < NOW() AND status NOT IN ('done','archived')"),
            'checklist_templates' => Database::tableExists('marketing_checklist_templates') ? $this->countRows('marketing_checklist_templates', "status = 'active'") : 0,
        ];

        return [
            'week_start' => $weekStart,
            'week_end' => $weekEnd,
            'counts' => $counts,
            'rhythms' => Database::tableExists('marketing_recurring_rhythms') ? $this->listRecurringRhythms(['status' => 'active'], 8, 0) : [],
            'queue' => $this->listPlanningQueueItems(['week_start' => $weekStart, 'open' => true], 12, 0),
            'overdue' => $this->listPlanningQueueItems(['overdue' => true], 8, 0),
            'checklist_templates' => Database::tableExists('marketing_checklist_templates') ? $this->listChecklistTemplates(['status' => 'active'], 8, 0) : [],
        ];
    }

    public function getMarketingOperatingRhythmCenter(?int $userId = null, int $limit = 8): array
    {
        $this->assertMarketingPermission('marketing.read');
        $limit = min(max($limit, 1), 16);
        $userId = $userId ?? $this->currentUserId();
        if (($userId ?? 0) > 0) {
            $this->assertWorkspaceUser((int) $userId, $this->workspaceId());
        }

        $today = date('Y-m-d');
        $weekStart = $this->normalizeWeekStart();
        $weekEnd = date('Y-m-d', strtotime($weekStart . ' +6 days'));
        $ownerFilter = (($userId ?? 0) > 0) ? ['owner_user_id' => (int) $userId] : [];
        $reviewerFilter = (($userId ?? 0) > 0) ? ['reviewer_user_id' => (int) $userId] : [];
        $handoffOwnerFilter = (($userId ?? 0) > 0) ? ['assigned_to' => (int) $userId] : [];

        $todayContent = $this->listContentItems([
            'production_due_from' => $today,
            'production_due_to' => $today,
            'exclude_status' => 'archived',
        ] + $ownerFilter, $limit, 0);
        $scheduledToday = $this->listContentItems([
            'scheduled_from' => $today,
            'scheduled_to' => $today,
            'exclude_status' => 'archived',
        ] + $ownerFilter, $limit, 0);
        $dueThisWeek = $this->listContentItems([
            'production_due_from' => $today,
            'production_due_to' => $weekEnd,
            'exclude_status' => 'archived',
        ] + $ownerFilter, $limit, 0);
        $blockedContent = $this->listContentItems([
            'blocked' => true,
            'exclude_status' => 'archived',
        ] + $ownerFilter, $limit, 0);

        $planningOpen = Database::tableExists('marketing_planning_queue_items')
            ? $this->listPlanningQueueItems(['open' => true] + $ownerFilter, min(80, max($limit * 8, 24)), 0)
            : [];
        $planningThisWeek = Database::tableExists('marketing_planning_queue_items')
            ? $this->listPlanningQueueItems(['week_start' => $weekStart, 'open' => true] + $ownerFilter, $limit, 0)
            : [];
        $planningOverdue = Database::tableExists('marketing_planning_queue_items')
            ? $this->listPlanningQueueItems(['overdue' => true] + $ownerFilter, $limit, 0)
            : [];
        $planningToday = array_values(array_filter($planningOpen, static function (array $item) use ($today): bool {
            $dueAt = (string) ($item['due_at'] ?? '');
            return $dueAt !== '' && substr($dueAt, 0, 10) === $today;
        }));

        $calendarToday = Database::tableExists('marketing_calendar_milestones')
            ? $this->listCalendarMilestones([
                'date_from' => $today,
                'date_to' => $today,
                'status' => 'planned',
            ] + $ownerFilter, $limit, 0)
            : [];
        $calendarThisWeek = Database::tableExists('marketing_calendar_milestones')
            ? $this->listCalendarMilestones([
                'date_from' => $today,
                'date_to' => $weekEnd,
                'status' => 'planned',
            ] + $ownerFilter, $limit, 0)
            : [];

        $pendingReviews = Database::tableExists('marketing_content_approvals')
            ? $this->listContentApprovals($reviewerFilter + ['status' => 'pending'], $limit, 0)
            : [];
        $overdueReviews = Database::tableExists('marketing_content_approvals')
            ? $this->listContentApprovals($reviewerFilter + ['queue' => 'overdue'], $limit, 0)
            : [];
        $blockedLaunches = Database::tableExists('marketing_launch_control_records')
            ? $this->listLaunchControlRecords(['status' => 'blocked'], $limit, 0)
            : [];
        $openHandoffs = Database::tableExists('marketing_lead_handoffs')
            ? $this->listLeadHandoffs(['open' => true] + $handoffOwnerFilter, $limit, 0)
            : [];
        $openDistribution = Database::tableExists('marketing_distribution_posts')
            ? $this->listDistributionPosts(['open' => true], $limit, 0)
            : [];
        $openEmailRuns = Database::tableExists('marketing_email_campaign_runs')
            ? $this->listEmailCampaignRuns(['open' => true], $limit, 0)
            : [];
        $storedRouterItems = Database::tableExists('marketing_action_router_items')
            ? $this->listMarketingActionRouterItems(['open' => true], $limit, 0)
            : [];

        $laneItem = static function (
            string $title,
            string $href,
            string $source,
            string $dueLabel,
            string $priority = 'normal',
            string $reason = ''
        ): array {
            return [
                'title' => $title,
                'href' => $href,
                'source' => $source,
                'due_label' => $dueLabel,
                'priority' => in_array($priority, ['high', 'medium', 'normal', 'low'], true) ? $priority : 'normal',
                'reason' => $reason,
            ];
        };
        $contentHref = static fn(array $item): string => !empty($item['id'])
            ? 'marketing_content_view.php?id=' . (int) $item['id']
            : 'marketing_content.php';

        $todayItems = [];
        foreach (array_slice($planningToday, 0, $limit) as $item) {
            $todayItems[] = $laneItem((string) ($item['title'] ?? 'Planning item'), 'marketing_operations.php', 'Planning Queue', (string) ($item['due_at'] ?? 'Due today'), (string) ($item['priority'] ?? 'normal'), 'Planning item due today.');
        }
        foreach (array_slice($todayContent, 0, $limit) as $item) {
            $todayItems[] = $laneItem((string) ($item['title'] ?? 'Content item'), $contentHref($item), 'Content Production', (string) ($item['production_due_at'] ?? 'Due today'), 'high', (string) ($item['next_action'] ?? 'Work the production due date.'));
        }
        foreach (array_slice($scheduledToday, 0, $limit) as $item) {
            $todayItems[] = $laneItem((string) ($item['title'] ?? 'Scheduled content'), $contentHref($item), 'Content Schedule', (string) ($item['scheduled_at'] ?? 'Scheduled today'), 'medium', 'Scheduled content needs a manual readiness check.');
        }
        foreach (array_slice($calendarToday, 0, $limit) as $item) {
            $todayItems[] = $laneItem((string) ($item['title'] ?? 'Calendar milestone'), 'marketing_calendar.php', 'Calendar', (string) ($item['milestone_date'] ?? $today), 'normal', 'Calendar milestone scheduled today.');
        }

        $weekItems = [];
        foreach (array_slice($planningThisWeek, 0, $limit) as $item) {
            $weekItems[] = $laneItem((string) ($item['title'] ?? 'Planning item'), 'marketing_operations.php', 'Planning Queue', (string) ($item['due_at'] ?? 'This week'), (string) ($item['priority'] ?? 'normal'), 'Weekly planning queue item.');
        }
        foreach (array_slice($dueThisWeek, 0, $limit) as $item) {
            $weekItems[] = $laneItem((string) ($item['title'] ?? 'Content due this week'), $contentHref($item), 'Content Production', (string) ($item['production_due_at'] ?? 'This week'), 'medium', (string) ($item['next_action'] ?? 'Move this item through production.'));
        }
        foreach (array_slice($calendarThisWeek, 0, $limit) as $item) {
            $weekItems[] = $laneItem((string) ($item['title'] ?? 'Calendar milestone'), 'marketing_calendar.php', 'Calendar', (string) ($item['milestone_date'] ?? $weekEnd), 'normal', 'Upcoming calendar milestone.');
        }

        $blockedItems = [];
        foreach (array_slice($planningOverdue, 0, $limit) as $item) {
            $blockedItems[] = $laneItem((string) ($item['title'] ?? 'Overdue planning item'), 'marketing_operations.php', 'Overdue Planning', (string) ($item['due_at'] ?? 'Overdue'), 'high', 'Planning work is overdue or blocked.');
        }
        foreach (array_slice($blockedContent, 0, $limit) as $item) {
            $blockedItems[] = $laneItem((string) ($item['title'] ?? 'Blocked content'), $contentHref($item), 'Blocked Content', (string) ($item['production_due_at'] ?? 'Blocked'), 'high', (string) ($item['blocked_reason'] ?? 'Content has a blocker.'));
        }
        foreach (array_slice($overdueReviews, 0, $limit) as $item) {
            $blockedItems[] = $laneItem((string) ($item['content_title'] ?? 'Overdue review'), 'marketing_reviews.php?queue=overdue', 'Reviews', (string) ($item['review_due_at'] ?? 'Overdue'), 'high', 'Review SLA has passed.');
        }
        foreach (array_slice($blockedLaunches, 0, $limit) as $item) {
            $blockedItems[] = $laneItem((string) ($item['title'] ?? 'Blocked launch'), 'marketing_launch_control.php?status=blocked', 'Launch Control', 'Blocked', 'high', (string) ($item['blocked_reason'] ?? 'Launch is blocked.'));
        }

        $handoffItems = [];
        foreach (array_slice($openHandoffs, 0, $limit) as $item) {
            $handoffItems[] = $laneItem((string) ($item['title'] ?? $item['contact_email'] ?? 'Lead handoff'), 'marketing_handoffs.php', 'Lead Handoff', (string) ($item['sla_due_at'] ?? 'Open'), 'high', 'Sales or CRM follow-up is waiting.');
        }
        foreach (array_slice($openDistribution, 0, $limit) as $item) {
            $handoffItems[] = $laneItem((string) ($item['content_title'] ?? 'Distribution draft'), 'marketing_distribution.php', 'Distribution', (string) ($item['scheduled_at'] ?? 'Unscheduled'), 'medium', 'Manual distribution work is open.');
        }
        foreach (array_slice($openEmailRuns, 0, $limit) as $item) {
            $handoffItems[] = $laneItem((string) ($item['name'] ?? 'Email run'), 'marketing_email_runs.php', 'Email Runs', (string) ($item['scheduled_at'] ?? 'Unscheduled'), 'medium', 'Manual email campaign run is open.');
        }
        foreach (array_slice($storedRouterItems, 0, $limit) as $item) {
            $handoffItems[] = $laneItem((string) ($item['label'] ?? 'Action router item'), (string) ($item['target_href'] ?? 'marketing_action_router.php'), 'Action Router', (string) ($item['action_status'] ?? 'Open'), (string) ($item['priority'] ?? 'normal'), (string) ($item['reason'] ?? 'Open the recommended CRM target.'));
        }

        $lanes = [
            'today_focus' => [
                'label' => 'Today Focus',
                'href' => 'marketing_task_hub.php?queue=my_work',
                'items' => array_slice($todayItems, 0, $limit),
            ],
            'this_week' => [
                'label' => 'This Week',
                'href' => 'marketing_operations.php',
                'items' => array_slice($weekItems, 0, $limit),
            ],
            'blocked_work' => [
                'label' => 'Blocked And Overdue',
                'href' => 'marketing_task_hub.php?queue=blocked',
                'items' => array_slice($blockedItems, 0, $limit),
            ],
            'handoffs_execution' => [
                'label' => 'Handoffs And Execution',
                'href' => 'marketing_action_router.php',
                'items' => array_slice($handoffItems, 0, $limit),
            ],
        ];

        $counts = [
            'today_focus' => count($todayItems),
            'this_week' => count($weekItems),
            'blocked_work' => count($blockedItems),
            'handoffs_execution' => count($handoffItems),
            'pending_reviews' => count($pendingReviews),
            'overdue_reviews' => count($overdueReviews),
            'planning_overdue' => count($planningOverdue),
        ];

        $nextActions = [];
        if ($counts['blocked_work'] > 0) {
            $nextActions[] = ['label' => 'Clear blocked work first', 'href' => 'marketing_task_hub.php?queue=blocked', 'priority' => 'high', 'reason' => $counts['blocked_work'] . ' blocked or overdue item(s) can stall launch work.'];
        }
        if ($counts['today_focus'] > 0) {
            $nextActions[] = ['label' => 'Work today focus queue', 'href' => 'marketing_task_hub.php?queue=my_work', 'priority' => 'high', 'reason' => $counts['today_focus'] . ' item(s) are due or scheduled today.'];
        }
        if ($counts['pending_reviews'] > 0) {
            $nextActions[] = ['label' => 'Review approval queue', 'href' => 'marketing_reviews.php?queue=pending', 'priority' => 'medium', 'reason' => $counts['pending_reviews'] . ' review request(s) are waiting.'];
        }
        if ($counts['handoffs_execution'] > 0) {
            $nextActions[] = ['label' => 'Open CRM execution handoffs', 'href' => 'marketing_action_router.php', 'priority' => 'medium', 'reason' => 'Marketing work is ready to move into handoff, export, or CRM follow-up.'];
        }
        if ($nextActions === []) {
            $nextActions[] = ['label' => 'Plan this week', 'href' => 'marketing_operations.php', 'priority' => 'normal', 'reason' => 'No urgent operating items are open; review the weekly planning queue.'];
        }

        $score = max(0, min(100, 100
            - ($counts['blocked_work'] * 10)
            - ($counts['overdue_reviews'] * 8)
            - ($counts['planning_overdue'] * 6)
            - (max(0, $counts['today_focus'] - 6) * 3)
        ));

        return [
            'status' => $counts['blocked_work'] > 0 ? 'blocked' : ($counts['today_focus'] > 0 || $counts['pending_reviews'] > 0 ? 'attention' : 'clear'),
            'score' => $score,
            'date_range' => [
                'today' => $today,
                'week_start' => $weekStart,
                'week_end' => $weekEnd,
            ],
            'counts' => $counts,
            'lanes' => $lanes,
            'next_actions' => array_slice($nextActions, 0, $limit),
            'page_speed' => [
                'detail_limit' => $limit,
                'list_queries_are_capped' => true,
                'external_api_calls' => false,
            ],
            'guardrails' => [
                'workspace_scoped' => true,
                'manual_first' => true,
                'external_publish' => false,
                'external_send' => false,
                'operator_decision_required' => true,
            ],
            'recommended_product_decision' => 'Use the Command Center as the daily operating rhythm: today focus first, then weekly planning, blockers, and CRM execution handoffs.',
            'generated_at' => date('c'),
        ];
    }

    public function listMarketingAuditEvents(array $filters = [], int $limit = 100, int $offset = 0): array
    {
        if (!Database::tableExists('marketing_audit_events')) {
            return [];
        }

        $limit = min(max($limit, 1), 250);
        $offset = max($offset, 0);
        $workspace = $this->workspaceClause('ae.');
        $where = [$workspace['sql']];
        $params = $workspace['params'];
        foreach (['event_type', 'target_type'] as $field) {
            $value = trim((string) ($filters[$field] ?? ''));
            if ($value !== '') {
                $where[] = "ae.{$field} = ?";
                $params[] = Security::sanitizeInput($value, 'string');
            }
        }
        if (!empty($filters['target_id'])) {
            $where[] = 'ae.target_id = ?';
            $params[] = (int) $filters['target_id'];
        }

        return array_map(
            fn(array $row): array => $this->hydrateJsonFields($row, ['metadata_json']),
            Database::query(
                "SELECT ae.*, actor.email AS actor_email
                 FROM marketing_audit_events ae
                 LEFT JOIN users actor ON actor.id = ae.actor_user_id
                 WHERE " . implode(' AND ', $where) . "
                 ORDER BY ae.created_at DESC
                 LIMIT {$limit} OFFSET {$offset}",
                $params
            )
        );
    }

    public function recordMarketingAuditEvent(
        string $eventType,
        string $targetType,
        ?int $targetId,
        string $summary,
        array $metadata = [],
        ?int $actorUserId = null
    ): int {
        $this->assertMarketingPermission('marketing.write');
        if (!Database::tableExists('marketing_audit_events')) {
            return 0;
        }

        $eventType = Security::sanitizeInput($eventType, 'string');
        $targetType = Security::sanitizeInput($targetType, 'string');
        $summary = Security::sanitizeInput($summary, 'string');
        if ($eventType === '' || $summary === '') {
            throw new \InvalidArgumentException('Audit event type and summary are required.');
        }
        $actorUserId = $actorUserId ?? $this->currentUserId();
        if ($actorUserId !== null && $actorUserId > 0) {
            $this->assertWorkspaceUser($actorUserId, $this->workspaceId());
        }

        Database::execute(
            "INSERT INTO marketing_audit_events
             (workspace_id, uuid, event_type, target_type, target_id, summary, metadata_json, actor_user_id)
             VALUES (?, ?, ?, ?, ?, ?, ?, ?)",
            [
                $this->workspaceId(),
                $this->generateUuid(),
                $eventType,
                $targetType !== '' ? $targetType : null,
                ($targetId ?? 0) > 0 ? $targetId : null,
                $summary,
                $this->normalizeJsonValue($this->sanitizeFlexibleArray($metadata)),
                ($actorUserId ?? 0) > 0 ? $actorUserId : null,
            ]
        );

        return (int) Database::lastInsertId();
    }

