            'marketing_distribution_posts',
            'marketing_media_files',
            'marketing_media_audit_events',
            'marketing_channel_media_kits',
            'marketing_analytics_snapshots',
            'marketing_recurring_rhythms',
            'marketing_planning_queue_items',
            'marketing_audit_events',
            'marketing_cleanup_runs',
            'marketing_report_exports',
            'marketing_scheduled_report_drafts',
            'marketing_operator_readiness_checks',
            'marketing_visitor_sessions',
            'marketing_tracking_events',
            'marketing_landing_page_views',
            'marketing_cta_clicks',
            'marketing_conversion_events',
            'marketing_attribution_touchpoints',
            'marketing_attribution_summaries',
            'marketing_conversion_goals',
            'marketing_conversion_goal_links',
            'marketing_handoff_rules',
            'marketing_lead_handoffs',
            'marketing_crm_sync_events',
            'marketing_handoff_feedback_events',
            'marketing_audience_recommendations',
            'marketing_audience_activations',
            'marketing_persona_segment_map',
            'marketing_campaign_playbooks',
            'marketing_campaign_playbook_stages',
            'marketing_launch_readiness_templates',
            'marketing_launch_readiness_reviews',
            'marketing_launch_control_records',
            'marketing_guided_workflows',
            'marketing_guided_workflow_events',
            'marketing_task_hub_preferences',
            'marketing_task_hub_action_log',
            'marketing_live_execution_policies',
            'marketing_live_execution_events',
            'marketing_live_email_handoffs',
            'marketing_live_email_handoff_events',
            'marketing_live_email_worker_runs',
            'marketing_live_worker_health_checks',
            'marketing_live_worker_leases',
            'marketing_live_worker_schedules',
            'marketing_live_email_delivery_proofs',
            'marketing_live_email_unsubscribe_tokens',
            'marketing_live_email_unsubscribe_events',
        ];

        $tables = [];
        foreach ($marketingTables as $table) {
            $exists = Database::tableExists($table);
            $tables[$table] = [
                'exists' => $exists,
                'workspace_rows' => $exists && Database::columnExists($table, 'workspace_id') ? $this->countRows($table, 'id > 0') : null,
            ];
        }

        $indexNames = [
            'idx_marketing_content_workspace_updated',
            'idx_marketing_content_workspace_readiness',
            'idx_marketing_approvals_workspace_status_due',
            'idx_marketing_comments_workspace_resolved',
            'idx_marketing_queue_workspace_status_due',
        ];
        $indexes = [];
        foreach ($indexNames as $indexName) {
            $indexes[$indexName] = $this->databaseIndexExists($indexName);
        }

        $latestMigration = Database::tableExists('migrations')
            ? Database::queryOne("SELECT migration_name, executed_at FROM migrations ORDER BY executed_at DESC, id DESC LIMIT 1")
            : null;
        $aiReadiness = $this->marketingAiReadinessDiagnostics($latestMigration ?: null);
        $mediaDiagnostics = $this->getMarketingMediaDiagnostics();
        $liveWorkerHealth = $this->getLiveEmailWorkerHealth(true, $this->currentUserId() ?: null);

        $missingTables = array_keys(array_filter($tables, static fn(array $row): bool => empty($row['exists'])));
        $missingIndexes = array_keys(array_filter($indexes, static fn(bool $exists): bool => !$exists));
        $starterPreview = $this->starterPackCleanupPreview();
        $recommendations = [
            $missingTables !== [] ? 'Run pending migrations: missing marketing tables were detected.' : null,
            $missingIndexes !== [] ? 'Review migration 317: one or more hardening indexes are missing.' : null,
            ($starterPreview['total'] ?? 0) > 0 && empty($starterPreview['archived']) ? 'Starter/demo records are present; use cleanup when the workspace no longer needs demo data.' : null,
            !empty($mediaDiagnostics['counts']['missing_alt_text']) ? 'Add alt text to image-heavy marketing media before export.' : null,
            !empty($mediaDiagnostics['counts']['expired_rights']) ? 'Review expired media usage rights before manual publishing.' : null,
            !empty($mediaDiagnostics['counts']['blocked_media']) ? 'Resolve blocked or archived media before export-ready packaging.' : null,
            in_array((string) ($liveWorkerHealth['status'] ?? 'unknown'), ['stale', 'blocked'], true) ? 'Review Marketing live email worker health before approving more live sends.' : null,
            (string) ($liveWorkerHealth['status'] ?? 'unknown') === 'unknown' && (int) ($liveWorkerHealth['counts']['queued'] ?? 0) > 0 ? 'Configure Marketing live email worker cron before queued handoffs can be sent.' : null,
        ];
        if (empty($aiReadiness['runtime_surface_available'])) {
            $recommendations[] = 'Review AI runtime controls: the marketing surface is not registered.';
        }
        if (!empty($aiReadiness['missing_prompt_keys'])) {
            $recommendations[] = 'Seed Marketing AI prompts: one or more required active prompt registry entries are missing.';
        }
        if (!empty($aiReadiness['missing_operating_prompt_keys'])) {
            $recommendations[] = 'Seed Marketing AI operating-loop prompts: one or more Phase 5-8 prompt registry entries are missing.';
        }
        if (empty($aiReadiness['prompt_seed_migration_recorded'])) {
            $recommendations[] = 'Run migration 319: Marketing AI prompt seed migration is not recorded.';
        }
        if (empty($aiReadiness['operating_prompt_seed_migration_recorded'])) {
            $recommendations[] = 'Run migration 320: Marketing AI operating-loop prompt seed migration is not recorded.';
        }

        return [
            'workspace_id' => $this->workspaceId(),
            'latest_migration' => $latestMigration ?: null,
            'tables' => $tables,
            'indexes' => $indexes,
            'ai_readiness' => $aiReadiness,
            'media_diagnostics' => $mediaDiagnostics,
            'live_worker_health' => $liveWorkerHealth,
            'starter_pack' => $starterPreview,
            'audit_events' => Database::tableExists('marketing_audit_events') ? $this->countRows('marketing_audit_events', 'id > 0') : 0,
            'cleanup_runs' => Database::tableExists('marketing_cleanup_runs') ? $this->countRows('marketing_cleanup_runs', 'id > 0') : 0,
            'recommendations' => array_values(array_filter($recommendations)),
        ];
    }

    public function getMarketingQaConsole(): array
    {
        $this->assertMarketingPermission('marketing.manage');
        $diagnostics = $this->getMarketingDiagnostics();
        $operatorReadiness = $this->getMarketingOperatorReadiness();
        $mediaOperations = $this->getMarketingMediaOperationsSummary(100);
        $permissions = $this->marketingPermissionDiagnostics();
        $pageGuides = $this->marketingPageGuideDiagnostics();
        $workflow = $this->marketingWorkflowQaDiagnostics();
        $liveWorkerHealth = (array) ($diagnostics['live_worker_health'] ?? []);

        $checks = [];
        $addCheck = static function (
            array &$checks,
            string $key,
            string $label,
            string $status,
            string $message,
            string $href,
            int $count = 0,
            array $metadata = []
        ): void {
            $checks[] = [
                'key' => $key,
                'label' => $label,
                'status' => $status,
                'message' => $message,
                'href' => $href,
                'count' => $count,
                'metadata' => $metadata,
            ];
        };

        $missingTables = array_keys(array_filter((array) ($diagnostics['tables'] ?? []), static fn(array $row): bool => empty($row['exists'])));
        $missingIndexes = array_keys(array_filter((array) ($diagnostics['indexes'] ?? []), static fn(bool $exists): bool => !$exists));
        $starterTotal = (int) ($diagnostics['starter_pack']['total'] ?? 0);
        $mediaIssueCount = (int) ($mediaOperations['counts']['needs_accessibility'] ?? 0)
            + (int) ($mediaOperations['counts']['rights_attention'] ?? 0)
            + (int) ($mediaOperations['counts']['export_blocked'] ?? 0);
        $workflowIssueCount = (int) ($workflow['counts']['overdue_reviews'] ?? 0)
            + (int) ($workflow['counts']['stuck_review_content'] ?? 0)
            + (int) ($workflow['counts']['blocked_content'] ?? 0)
            + (int) ($workflow['counts']['landing_pages_missing_required'] ?? 0)
            + (int) ($workflow['counts']['draft_export_bundles'] ?? 0)
            + (int) ($workflow['counts']['blocked_execution_queue'] ?? 0);
        $liveWorkerStatus = (string) ($liveWorkerHealth['status'] ?? 'unknown');
        $liveWorkerQaStatus = match ($liveWorkerStatus) {
            'healthy' => 'ready',
            'blocked', 'stale' => 'blocked',
            default => 'warning',
        };
        $liveWorkerIssueCount = (int) ($liveWorkerHealth['counts']['queued'] ?? 0)
            + (int) ($liveWorkerHealth['counts']['stale'] ?? 0)
            + (int) ($liveWorkerHealth['counts']['blocked'] ?? 0)
            + (int) ($liveWorkerHealth['counts']['failed'] ?? 0);

        $addCheck(
            $checks,
            'schema',
            'Marketing schema and indexes',
            $missingTables === [] ? ($missingIndexes === [] ? 'ready' : 'warning') : 'blocked',
            $missingTables === []
                ? ($missingIndexes === [] ? 'All tracked Marketing tables and hardening indexes are present.' : 'Some hardening indexes are missing and should be reviewed.')
                : 'Missing Marketing tables: ' . implode(', ', $missingTables),
            'marketing_admin.php',
            count($missingTables) + count($missingIndexes),
            ['missing_tables' => $missingTables, 'missing_indexes' => $missingIndexes]
        );
        $addCheck(
            $checks,
            'rbac',
            'Marketing role permissions',
            (string) $permissions['status'],
            (string) $permissions['message'],
            'settings.php?tab=roles',
            (int) $permissions['missing_count'],
            $permissions
        );
        $addCheck(
            $checks,
            'page_guides',
            'Marketing watch guide setup',
            (string) $pageGuides['status'],
            (string) $pageGuides['message'],
            'settings.php?tab=page_videos',
            (int) $pageGuides['missing_count'],
            $pageGuides
        );
        $addCheck(
            $checks,
            'media_operations',
            'Media operations readiness',
            $mediaIssueCount > 0 ? 'warning' : 'ready',
            $mediaIssueCount > 0 ? 'Media has accessibility, rights, or export blocker issues.' : 'Media operations have no launch-blocking issues.',
            'marketing_assets.php',
            $mediaIssueCount,
            $mediaOperations['counts'] ?? []
        );
        $addCheck(
            $checks,
            'workflow_gaps',
            'Workflow and conversion gaps',
            $workflowIssueCount > 0 ? 'warning' : 'ready',
            $workflowIssueCount > 0 ? 'Reviews, landing pages, exports, or execution queues need operator attention.' : 'Workflow queues and conversion planning look clear.',
            'marketing_reviews.php',
            $workflowIssueCount,
            $workflow['counts'] ?? []
        );
        $addCheck(
            $checks,
            'live_worker_health',
            'Live email worker health',
            $liveWorkerQaStatus,
            (string) ($liveWorkerHealth['message'] ?? 'Marketing live email worker health has not been checked.'),
            'marketing_execution.php',
            $liveWorkerIssueCount,
            $liveWorkerHealth
        );
        $addCheck(
            $checks,
            'starter_cleanup',
            'Starter/demo data cleanup',
            $starterTotal > 0 ? 'warning' : 'ready',
            $starterTotal > 0 ? 'Starter/demo records are present; preview cleanup before real workspace use.' : 'No starter/demo records require cleanup.',
            'marketing_admin.php',
            $starterTotal,
            (array) ($diagnostics['starter_pack'] ?? [])
        );
        $addCheck(
            $checks,
            'operator_readiness',
            'Operator readiness checks',
            (string) ($operatorReadiness['status'] ?? 'warning'),
            'Ready: ' . (int) ($operatorReadiness['counts']['ready'] ?? 0) . '; warnings: ' . (int) ($operatorReadiness['counts']['warning'] ?? 0) . '; blocked: ' . (int) ($operatorReadiness['counts']['blocked'] ?? 0) . '.',
            'marketing_operations.php',
            (int) ($operatorReadiness['counts']['warning'] ?? 0) + (int) ($operatorReadiness['counts']['blocked'] ?? 0),
            (array) ($operatorReadiness['counts'] ?? [])
        );
        $addCheck(
            $checks,
            'no_secret_diagnostics',
            'No-secret diagnostics',
            'ready',
            'QA console exposes statuses, counts, labels, and sanitized metadata only.',
            'marketing_admin.php',
            0,
            ['passwords' => false, 'tokens' => false, 'stack_traces' => false]
        );

        $status = 'ready';
        foreach ($checks as $check) {
            if (($check['status'] ?? '') === 'blocked') {
                $status = 'blocked';
                break;
            }
            if (($check['status'] ?? '') === 'warning') {
                $status = 'warning';
            }
        }

        return [
            'status' => $status,
            'generated_at' => date('c'),
            'checks' => $checks,
            'counts' => [
                'ready' => count(array_filter($checks, static fn(array $check): bool => ($check['status'] ?? '') === 'ready')),
                'warning' => count(array_filter($checks, static fn(array $check): bool => ($check['status'] ?? '') === 'warning')),
                'blocked' => count(array_filter($checks, static fn(array $check): bool => ($check['status'] ?? '') === 'blocked')),
                'attention_items' => array_sum(array_map(static fn(array $check): int => (int) ($check['count'] ?? 0), $checks)),
            ],
            'sections' => [
                'diagnostics' => $diagnostics,
                'operator_readiness' => $operatorReadiness,
                'media_operations' => $mediaOperations,
                'permissions' => $permissions,
                'page_guides' => $pageGuides,
                'workflow' => $workflow,
                'live_worker_health' => $liveWorkerHealth,
            ],
            'manual_first_boundary' => [
                'external_publish' => false,
                'external_send' => false,
                'external_generation' => false,
            ],
        ];
    }

    private function marketingPermissionDiagnostics(): array
    {
        $expected = [
            'admin' => ['marketing.read', 'marketing.write', 'marketing.manage'],
            'owner' => ['marketing.read', 'marketing.write', 'marketing.manage'],
            'marketing' => ['marketing.read', 'marketing.write'],
            'sales' => ['marketing.read'],
            'viewer' => ['marketing.read'],
        ];
        $missing = [];
        if (!Database::tableExists('roles') || !Database::tableExists('permissions') || !Database::tableExists('role_permissions')) {
            return [
                'status' => 'blocked',
                'message' => 'RBAC tables are missing.',
                'missing_count' => 1,
                'missing' => ['rbac_tables'],
            ];
        }

        foreach ($expected as $roleSlug => $permissionKeys) {
            $role = Database::queryOne('SELECT id FROM roles WHERE slug = ? LIMIT 1', [$roleSlug]);
            if (!$role) {
                $missing[] = $roleSlug . ':role';
                continue;
            }
            $assigned = Database::query(
                "SELECT p.permission_key
                 FROM role_permissions rp
                 JOIN permissions p ON p.id = rp.permission_id
                 WHERE rp.role_id = ? AND rp.can_access = 1 AND p.permission_key IN ('marketing.read','marketing.write','marketing.manage')",
                [(int) $role['id']]
            );
            $assignedKeys = array_map(static fn(array $row): string => (string) $row['permission_key'], $assigned);
            foreach ($permissionKeys as $permissionKey) {
                if (!in_array($permissionKey, $assignedKeys, true)) {
                    $missing[] = $roleSlug . ':' . $permissionKey;
                }
            }
        }

        return [
            'status' => $missing === [] ? 'ready' : 'blocked',
            'message' => $missing === [] ? 'Expected Marketing role grants are present.' : 'Missing Marketing grants: ' . implode(', ', $missing),
            'missing_count' => count($missing),
            'missing' => $missing,
            'expected' => $expected,
        ];
    }

    private function marketingPageGuideDiagnostics(): array
    {
        $definitions = MarketingPageGuideUi::pageDefinitions();
        $keys = array_values(array_unique(array_map(static fn(array $definition): string => (string) $definition['key'], $definitions)));
        if (!Database::tableExists('marketplace_page_explainers')) {
            return [
                'status' => 'blocked',
                'message' => 'Page guide table is missing.',
                'missing_count' => count($keys),
                'missing_keys' => $keys,
                'active_video_count' => 0,
            ];
        }

        $rows = [];
        if ($keys !== []) {
            $placeholders = implode(',', array_fill(0, count($keys), '?'));
            $rows = Database::query(
                "SELECT page_key, is_active, video_url
                 FROM marketplace_page_explainers
                 WHERE page_key IN ({$placeholders})",
                $keys
            );
        }
        $rowsByKey = [];
        foreach ($rows as $row) {
            $rowsByKey[(string) $row['page_key']] = $row;
        }
        $missingKeys = array_values(array_filter($keys, static fn(string $key): bool => !isset($rowsByKey[$key])));
        $activeVideoCount = count(array_filter($rowsByKey, static fn(array $row): bool => !empty($row['is_active']) && trim((string) ($row['video_url'] ?? '')) !== ''));

        return [
            'status' => $missingKeys === [] ? 'ready' : 'warning',
            'message' => $missingKeys === []
                ? 'Marketing page guide rows are seeded. Active videos remain opt-in per page.'
                : 'Some Marketing page guide rows are missing.',
            'missing_count' => count($missingKeys),
            'missing_keys' => $missingKeys,
            'defined_page_count' => count($keys),
            'seeded_page_count' => count($rowsByKey),
            'active_video_count' => $activeVideoCount,
        ];
    }

    private function marketingWorkflowQaDiagnostics(): array
    {
        $counts = [
            'pending_reviews' => Database::tableExists('marketing_content_approvals') ? $this->countRows('marketing_content_approvals', "status = 'pending'") : 0,
            'overdue_reviews' => Database::tableExists('marketing_content_approvals') ? count($this->listContentApprovals(['queue' => 'overdue'], 250, 0)) : 0,
            'stuck_review_content' => Database::tableExists('marketing_content_items') ? $this->countRows('marketing_content_items', "status = 'review' AND updated_at < DATE_SUB(NOW(), INTERVAL 14 DAY)") : 0,
            'blocked_content' => 0,
            'landing_pages_missing_required' => 0,
            'landing_pages_missing_media' => 0,
            'draft_export_bundles' => Database::tableExists('marketing_channel_export_bundles') ? $this->countRows('marketing_channel_export_bundles', "status = 'draft'") : 0,
            'blocked_execution_queue' => Database::tableExists('marketing_execution_queue') ? $this->countRows('marketing_execution_queue', "status = 'blocked'") : 0,
        ];

        if (Database::tableExists('marketing_content_items')) {
            $blockedConditions = [];
            if (Database::columnExists('marketing_content_items', 'blocked_reason')) {
                $blockedConditions[] = "(blocked_reason IS NOT NULL AND blocked_reason <> '')";
            }
            if (Database::columnExists('marketing_content_items', 'dependency_status')) {
                $blockedConditions[] = "dependency_status = 'blocked'";
            }
            if ($blockedConditions !== []) {
                $counts['blocked_content'] = $this->countRows('marketing_content_items', '(' . implode(' OR ', $blockedConditions) . ')');
            }
        }

        if (Database::tableExists('marketing_landing_pages')) {
            $requiredConditions = [
                "(headline IS NULL OR headline = '')",
                'form_id IS NULL',
            ];
            if (Database::columnExists('marketing_landing_pages', 'seo_title')) {
                $requiredConditions[] = "(seo_title IS NULL OR seo_title = '')";
            }
            if (Database::columnExists('marketing_landing_pages', 'meta_description')) {
                $requiredConditions[] = "(meta_description IS NULL OR meta_description = '')";
            }
            if (Database::columnExists('marketing_landing_pages', 'conversion_goal')) {
                $requiredConditions[] = "(conversion_goal IS NULL OR conversion_goal = '')";
            }
            $counts['landing_pages_missing_required'] = $this->countRows('marketing_landing_pages', "status <> 'archived' AND (" . implode(' OR ', $requiredConditions) . ')');
            if (Database::columnExists('marketing_landing_pages', 'hero_media_file_id') && Database::columnExists('marketing_landing_pages', 'social_preview_media_file_id')) {
                $counts['landing_pages_missing_media'] = $this->countRows('marketing_landing_pages', "status <> 'archived' AND (hero_media_file_id IS NULL OR social_preview_media_file_id IS NULL)");
            }
        }

        return [
            'counts' => $counts,
            'manual_first_boundary' => [
                'external_publish' => false,
                'external_send' => false,
            ],
        ];
    }

    private function marketingAiReadinessDiagnostics(?array $latestMigration): array
    {
        $requiredPromptKeys = self::MARKETING_AI_PROMPT_KEYS;
        $promptRegistryExists = Database::tableExists('ai_prompt_registry');
        $promptRows = [];
        if ($promptRegistryExists) {
            $placeholders = implode(',', array_fill(0, count($requiredPromptKeys), '?'));
            $promptRows = Database::query(
                "SELECT prompt_key, version
                 FROM ai_prompt_registry
                 WHERE surface = ?
                   AND status = 'active'
                   AND prompt_key IN ({$placeholders})
                 ORDER BY prompt_key, version DESC",
                array_merge([self::AI_SURFACE], $requiredPromptKeys)
            );
        }

        $activePromptKeys = [];
        $promptVersions = [];
        foreach ($promptRows as $row) {
            $key = (string) ($row['prompt_key'] ?? '');
            if ($key === '' || !in_array($key, $requiredPromptKeys, true)) {
                continue;
            }
            $activePromptKeys[] = $key;
            $promptVersions[$key] = max((int) ($promptVersions[$key] ?? 0), (int) ($row['version'] ?? 0));
        }
        $activePromptKeys = array_values(array_unique($activePromptKeys));
        sort($activePromptKeys);

        $requiredOperatingPromptKeys = self::MARKETING_AI_OPERATING_PROMPT_KEYS;
        $operatingPromptRows = [];
        if ($promptRegistryExists) {
            $operatingPlaceholders = implode(',', array_fill(0, count($requiredOperatingPromptKeys), '?'));
            $operatingPromptRows = Database::query(
                "SELECT prompt_key, version
                 FROM ai_prompt_registry
                 WHERE surface = ?
                   AND status = 'active'
                   AND prompt_key IN ({$operatingPlaceholders})
                 ORDER BY prompt_key, version DESC",
                array_merge([self::AI_SURFACE], $requiredOperatingPromptKeys)
            );
        }

        $activeOperatingPromptKeys = [];
        $operatingPromptVersions = [];
        foreach ($operatingPromptRows as $row) {
            $key = (string) ($row['prompt_key'] ?? '');
            if ($key === '' || !in_array($key, $requiredOperatingPromptKeys, true)) {
                continue;
            }
            $activeOperatingPromptKeys[] = $key;
            $operatingPromptVersions[$key] = max((int) ($operatingPromptVersions[$key] ?? 0), (int) ($row['version'] ?? 0));
        }
        $activeOperatingPromptKeys = array_values(array_unique($activeOperatingPromptKeys));
        sort($activeOperatingPromptKeys);

        $requiredCreativePromptKeys = self::MARKETING_AI_CREATIVE_PROMPT_KEYS;
        $creativePromptRows = [];
        if ($promptRegistryExists) {
            $creativePlaceholders = implode(',', array_fill(0, count($requiredCreativePromptKeys), '?'));
            $creativePromptRows = Database::query(
                "SELECT prompt_key, version
                 FROM ai_prompt_registry
                 WHERE surface = ?
                   AND status = 'active'
                   AND prompt_key IN ({$creativePlaceholders})
                 ORDER BY prompt_key, version DESC",
                array_merge([self::AI_SURFACE], $requiredCreativePromptKeys)
            );
        }

        $activeCreativePromptKeys = [];
        $creativePromptVersions = [];
        foreach ($creativePromptRows as $row) {
            $key = (string) ($row['prompt_key'] ?? '');
            if ($key === '' || !in_array($key, $requiredCreativePromptKeys, true)) {
                continue;
            }
            $activeCreativePromptKeys[] = $key;
            $creativePromptVersions[$key] = max((int) ($creativePromptVersions[$key] ?? 0), (int) ($row['version'] ?? 0));
        }
        $activeCreativePromptKeys = array_values(array_unique($activeCreativePromptKeys));
        sort($activeCreativePromptKeys);

        $runtimeSurfaces = (new AIRuntimeControlService())->listSurfaces();
        $promptSeedMigrationRecorded = Database::tableExists('migrations')
            && (bool) Database::queryOne(
                'SELECT id FROM migrations WHERE migration_name = ? LIMIT 1',
                [self::MARKETING_AI_PROMPT_SEED_MIGRATION]
            );
        $operatingPromptSeedMigrationRecorded = Database::tableExists('migrations')
            && (bool) Database::queryOne(
                'SELECT id FROM migrations WHERE migration_name = ? LIMIT 1',
                [self::MARKETING_AI_OPERATING_PROMPT_SEED_MIGRATION]
            );
        $creativePromptSeedMigrationRecorded = Database::tableExists('migrations')
            && (bool) Database::queryOne(
                'SELECT id FROM migrations WHERE migration_name = ? LIMIT 1',
                [self::MARKETING_AI_CREATIVE_PROMPT_SEED_MIGRATION]
            );
        $missingPromptKeys = array_values(array_diff($requiredPromptKeys, $activePromptKeys));
        $missingOperatingPromptKeys = array_values(array_diff($requiredOperatingPromptKeys, $activeOperatingPromptKeys));
        $missingCreativePromptKeys = array_values(array_diff($requiredCreativePromptKeys, $activeCreativePromptKeys));
        $ready = $missingPromptKeys === []
            && $promptRegistryExists
            && $promptSeedMigrationRecorded
            && in_array(self::AI_SURFACE, $runtimeSurfaces, true);
        $operatingReady = $missingOperatingPromptKeys === []
            && $promptRegistryExists
            && $operatingPromptSeedMigrationRecorded
            && in_array(self::AI_SURFACE, $runtimeSurfaces, true);
        $creativeReady = $missingCreativePromptKeys === []
            && $promptRegistryExists
            && $creativePromptSeedMigrationRecorded
            && in_array(self::AI_SURFACE, $runtimeSurfaces, true);

        return [
            'surface' => self::AI_SURFACE,
            'runtime_surface_available' => in_array(self::AI_SURFACE, $runtimeSurfaces, true),
            'prompt_registry_table_exists' => $promptRegistryExists,
            'required_prompt_keys' => $requiredPromptKeys,
            'active_prompt_keys' => $activePromptKeys,
            'missing_prompt_keys' => $missingPromptKeys,
            'prompt_versions' => $promptVersions,
            'prompt_count' => count($activePromptKeys),
            'required_operating_prompt_keys' => $requiredOperatingPromptKeys,
            'active_operating_prompt_keys' => $activeOperatingPromptKeys,
            'missing_operating_prompt_keys' => $missingOperatingPromptKeys,
            'operating_prompt_versions' => $operatingPromptVersions,
            'operating_prompt_count' => count($activeOperatingPromptKeys),
            'required_creative_prompt_keys' => $requiredCreativePromptKeys,
            'active_creative_prompt_keys' => $activeCreativePromptKeys,
            'missing_creative_prompt_keys' => $missingCreativePromptKeys,
            'creative_prompt_versions' => $creativePromptVersions,
            'creative_prompt_count' => count($activeCreativePromptKeys),
            'latest_migration_name' => (string) ($latestMigration['migration_name'] ?? ''),
            'latest_required_migration' => self::MARKETING_AI_CREATIVE_PROMPT_SEED_MIGRATION,
            'latest_migration_current' => (string) ($latestMigration['migration_name'] ?? '') === self::MARKETING_AI_CREATIVE_PROMPT_SEED_MIGRATION,
            'prompt_seed_migration_recorded' => $promptSeedMigrationRecorded,
            'operating_prompt_seed_migration_recorded' => $operatingPromptSeedMigrationRecorded,
            'creative_prompt_seed_migration_recorded' => $creativePromptSeedMigrationRecorded,
            'deterministic_fallback_ready' => true,
            'live_provider_required' => false,
            'status' => $ready ? 'ready' : 'attention',
            'operating_status' => $operatingReady ? 'ready' : 'attention',
            'creative_status' => $creativeReady ? 'ready' : 'attention',
        ];
    }

    public function runMarketingCleanup(string $cleanupType, int $userId, bool $dryRun = false): array
    {
        $this->assertMarketingPermission('marketing.manage');
        $cleanupType = $this->normalizeEnum($cleanupType, ['starter_pack'], 'cleanup_type');
        $preview = $this->starterPackCleanupPreview();
        $result = [
            'cleanup_type' => $cleanupType,
            'dry_run' => $dryRun,
            'preview' => $preview,
            'archived' => false,
        ];

        if (!$dryRun) {
            $result['archive'] = $this->archiveMarketingStarterPack($userId);
            $result['archived'] = (bool) ($result['archive']['archived'] ?? false);
        }

        $runId = 0;
        if (Database::tableExists('marketing_cleanup_runs')) {
            Database::execute(
                "INSERT INTO marketing_cleanup_runs
                 (workspace_id, uuid, cleanup_type, status, scope_json, result_json, created_by)
                 VALUES (?, ?, ?, ?, ?, ?, ?)",
                [
                    $this->workspaceId(),
                    $this->generateUuid(),
                    $cleanupType,
                    $dryRun ? 'dry_run' : 'completed',
                    $this->normalizeJsonValue(['workspace_id' => $this->workspaceId(), 'demo_source' => 'marketing_onboarding_starter_pack']),
                    $this->normalizeJsonValue($result),
                    $userId > 0 ? $userId : null,
                ]
            );
            $runId = (int) Database::lastInsertId();
        }

        $result['cleanup_run_id'] = $runId;
        $this->recordMarketingAuditEvent(
            $dryRun ? 'cleanup_previewed' : 'cleanup_completed',
            'marketing_cleanup_runs',
            $runId > 0 ? $runId : null,
            $dryRun ? 'Marketing cleanup preview generated.' : 'Marketing starter/demo cleanup completed.',
            $result,
            $userId
        );

        return $result;
    }

    public function listDistributionPosts(array $filters = [], int $limit = 100, int $offset = 0): array
    {
        $workspace = $this->workspaceClause('d.');
        $where = [$workspace['sql']];
        $params = $workspace['params'];
        if (!empty($filters['open'])) {
            $where[] = "d.status IN ('draft','scheduled')";
        }
        if (!empty($filters['status'])) {
            $where[] = 'd.status = ?';
            $params[] = $this->normalizeEnum((string) $filters['status'], self::DISTRIBUTION_STATUSES, 'distribution_status');
        }
        if (!empty($filters['content_item_id'])) {
            $where[] = 'd.content_item_id = ?';
            $params[] = (int) $filters['content_item_id'];
        }
        if (!empty($filters['campaign_id'])) {
            $where[] = 'm.campaign_id = ?';
            $params[] = (int) $filters['campaign_id'];
        }

        return array_map(
            fn(array $row): array => $this->hydrateJsonFields($row, ['publishing_checklist_json', 'required_fields_json', 'asset_rules_json', 'exported_bundle_json']),
            Database::query(
                "SELECT d.*, m.title AS content_title, a.title AS asset_title
                 FROM marketing_distribution_posts d
                 JOIN marketing_content_items m ON m.id = d.content_item_id AND m.workspace_id = d.workspace_id
                 LEFT JOIN marketing_assets a ON a.id = d.asset_id AND a.workspace_id = d.workspace_id
                 WHERE " . implode(' AND ', $where) . "
                 ORDER BY
                    CASE WHEN d.scheduled_at IS NULL THEN 1 ELSE 0 END ASC,
                    d.scheduled_at ASC,
                    d.updated_at DESC
                 LIMIT {$limit} OFFSET {$offset}",
                $params
            )
        );
    }

    public function createDistributionPost(array $data): int
    {
        $normalized = $this->normalizeDistributionPostData($data, true);
        Database::execute(
            "INSERT INTO marketing_distribution_posts
             (workspace_id, uuid, content_item_id, asset_id, channel, planned_copy, publishing_checklist_json,
              required_fields_json, asset_rules_json, scheduled_at, status, exported_at, published_url, published_at,
              exported_bundle_json, created_by)
             VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)",
            [
                $this->workspaceId(), $this->generateUuid(), $normalized['content_item_id'], $normalized['asset_id'],
                $normalized['channel'], $normalized['planned_copy'], $normalized['publishing_checklist_json'],
                $normalized['required_fields_json'], $normalized['asset_rules_json'], $normalized['scheduled_at'],
                $normalized['status'], $normalized['exported_at'], $normalized['published_url'], $normalized['published_at'],
                $normalized['exported_bundle_json'], $normalized['created_by'],
            ]
        );

        return (int) Database::lastInsertId();
    }

    public function updateDistributionPost(int $id, array $data): bool
    {
        $post = $this->getDistributionPost($id);
        if (!$post) {
            throw new RuntimeException('Marketing distribution post not found.');
        }

        return $this->updateById('marketing_distribution_posts', $id, $this->normalizeDistributionPostData(array_merge($post, $data), false));
    }

    public function getDistributionPost(int $id): ?array
    {
        $rows = $this->listDistributionPosts([], 250, 0);
        foreach ($rows as $row) {
            if ((int) $row['id'] === $id) {
                return $row;
            }
        }

        return null;
    }

    public function exportDistributionPost(int $id): bool
    {
        Database::execute(
            "UPDATE marketing_distribution_posts
             SET status = 'exported', exported_at = COALESCE(exported_at, NOW())
             WHERE workspace_id = ? AND id = ?",
            [$this->workspaceId(), $id]
        );

        return true;
    }

    public function markDistributionPostPublished(int $id, string $publishedUrl, ?string $publishedAt = null): bool
    {
        $url = trim($publishedUrl);
        if (!filter_var($url, FILTER_VALIDATE_URL) || !preg_match('/^https?:\\/\\//i', $url)) {
            throw new \InvalidArgumentException('A valid published URL is required.');
        }

        return $this->updateDistributionPost($id, [
            'status' => 'published',
            'published_url' => $url,
            'published_at' => $publishedAt ?: date('Y-m-d\TH:i'),
        ]);
    }

    public function getDistributionExportBundle(int $id): array
    {
        $post = $this->getDistributionPost($id);
        if (!$post) {
            throw new RuntimeException('Marketing distribution post not found.');
        }
        $mediaKits = Database::tableExists('marketing_channel_media_kits')
            ? $this->listChannelMediaKits(['distribution_post_id' => $id], 5, 0)
            : [];

        $bundle = [
            'content_title' => $post['content_title'] ?? '',
            'channel' => $post['channel'] ?? 'other',
            'planned_copy' => $post['planned_copy'] ?? '',
            'asset_title' => $post['asset_title'] ?? '',
            'media_attachments' => $this->exportableContentMedia((int) ($post['content_item_id'] ?? 0)),
            'channel_media_kits' => $mediaKits,
            'publishing_checklist' => $post['publishing_checklist_json'] ?? [],
            'required_fields' => $post['required_fields_json'] ?? [],
            'asset_rules' => $post['asset_rules_json'] ?? [],
            'generated_at' => date('c'),
        ];
        $this->updateDistributionPost($id, ['exported_bundle_json' => $bundle]);

        return $bundle;
    }

    public function listChannelExportBundles(array $filters = [], int $limit = 100, int $offset = 0): array
    {
        if (!Database::tableExists('marketing_channel_export_bundles')) {
            return [];
        }

        $limit = min(max($limit, 1), 250);
        $offset = max($offset, 0);
        $workspace = $this->workspaceClause('ceb.');
        $where = [$workspace['sql']];
        $params = $workspace['params'];
        if (!empty($filters['open'])) {
            $where[] = "ceb.status IN ('draft','ready')";
        }
        if (!empty($filters['status'])) {
            $where[] = 'ceb.status = ?';
            $params[] = $this->normalizeEnum((string) $filters['status'], self::CHANNEL_EXPORT_STATUSES, 'channel_export_status');
        }
        if (!empty($filters['distribution_post_id'])) {
            $where[] = 'ceb.distribution_post_id = ?';
            $params[] = (int) $filters['distribution_post_id'];
        }
        if (!empty($filters['audience_segment_id'])) {
            $where[] = 'ceb.audience_segment_id = ?';
            $params[] = (int) $filters['audience_segment_id'];
        }
        if (!empty($filters['campaign_id'])) {
            $where[] = 'm.campaign_id = ?';
            $params[] = (int) $filters['campaign_id'];
        }
        if (!empty($filters['id'])) {
            $where[] = 'ceb.id = ?';
            $params[] = (int) $filters['id'];
        }

        return array_map(
            fn(array $row): array => $this->hydrateJsonFields($row, ['required_fields_json', 'asset_readiness_json', 'export_payload_json', 'metadata_json', 'media_kit_readiness_json']),
            Database::query(
                "SELECT ceb.*, d.planned_copy, d.status AS distribution_status,
                        m.title AS content_title, a.title AS asset_title, cmk.title AS media_kit_title,
                        cmk.readiness_json AS media_kit_readiness_json,
                        seg.name AS audience_segment_name, snap.name AS segment_snapshot_name,
                        creator.email AS created_by_email
                 FROM marketing_channel_export_bundles ceb
                 JOIN marketing_distribution_posts d ON d.id = ceb.distribution_post_id AND d.workspace_id = ceb.workspace_id
                 JOIN marketing_content_items m ON m.id = d.content_item_id AND m.workspace_id = d.workspace_id
                 LEFT JOIN marketing_assets a ON a.id = d.asset_id AND a.workspace_id = d.workspace_id
                 LEFT JOIN marketing_channel_media_kits cmk ON cmk.id = ceb.media_kit_id AND cmk.workspace_id = ceb.workspace_id
                 LEFT JOIN marketing_audience_segments seg ON seg.id = ceb.audience_segment_id AND seg.workspace_id = ceb.workspace_id
                 LEFT JOIN marketing_segment_snapshots snap ON snap.id = ceb.segment_snapshot_id AND snap.workspace_id = ceb.workspace_id
                 LEFT JOIN users creator ON creator.id = ceb.created_by
                 WHERE " . implode(' AND ', $where) . "
                 ORDER BY ceb.updated_at DESC
                 LIMIT {$limit} OFFSET {$offset}",
                $params
            )
        );
    }

    public function getChannelExportBundle(int $id): ?array
    {
        $rows = $this->listChannelExportBundles(['id' => $id], 1, 0);
        return $rows[0] ?? null;
    }

    public function createChannelExportBundle(int $distributionPostId, ?int $userId = null): int
    {
        $post = $this->getDistributionPost($distributionPostId);
        if (!$post) {
            throw new RuntimeException('Marketing distribution post not found.');
        }

        $channel = (string) ($post['channel'] ?? 'other');
        $mediaKitId = Database::tableExists('marketing_channel_media_kits')
            ? $this->createChannelMediaKitFromDistribution($distributionPostId, [], $userId)
            : null;
        $mediaKit = $mediaKitId ? ($this->getChannelMediaKit($mediaKitId) ?? []) : [];
        $audienceLink = $this->audienceSegmentLinkForDistributionPost($post);
        $requiredFields = $post['required_fields_json'] ?: $this->defaultChannelRequiredFields($channel);
        $assetReadiness = $this->channelAssetReadiness($post);
        $payload = [
            'content_title' => $post['content_title'] ?? '',
            'channel' => $channel,
            'bundle_type' => $this->channelBundleType($channel),
            'planned_copy' => $post['planned_copy'] ?? '',
            'asset_title' => $post['asset_title'] ?? '',
            'audience_segment_id' => $audienceLink['audience_segment_id'],
            'audience_segment_name' => $audienceLink['audience_segment_name'],
            'segment_snapshot_id' => $audienceLink['segment_snapshot_id'],
            'media_attachments' => $this->exportableContentMedia((int) ($post['content_item_id'] ?? 0)),
            'media_kit' => $mediaKit ? [
                'id' => (int) ($mediaKit['id'] ?? 0),
                'title' => (string) ($mediaKit['title'] ?? ''),
                'status' => (string) ($mediaKit['status'] ?? 'draft'),
                'readiness' => (array) ($mediaKit['readiness_json'] ?? []),
            ] : null,
            'publishing_checklist' => $post['publishing_checklist_json'] ?? [],
            'required_fields' => $requiredFields,
            'asset_readiness' => $assetReadiness,
            'no_external_publish' => true,
            'generated_at' => date('c'),
        ];
        $missing = [];
        if (trim((string) ($post['planned_copy'] ?? '')) === '') {
            $missing[] = 'planned_copy';
        }
        if (!$assetReadiness['ready']) {
            $missing[] = 'asset';
        }

        Database::execute(
            "INSERT INTO marketing_channel_export_bundles
             (workspace_id, distribution_post_id, media_kit_id, audience_segment_id, segment_snapshot_id, uuid, channel, bundle_type, status, required_fields_json,
              asset_readiness_json, export_payload_json, metadata_json, created_by)
             VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)",
            [
                $this->workspaceId(),
                $distributionPostId,
                $mediaKitId,
                $audienceLink['audience_segment_id'],
                $audienceLink['segment_snapshot_id'],
                $this->generateUuid(),
                $channel,
                $this->channelBundleType($channel),
                $missing === [] ? 'ready' : 'draft',
                $this->normalizeJsonValue($requiredFields),
                $this->normalizeJsonValue($assetReadiness),
                $this->normalizeJsonValue($payload),
                $this->normalizeJsonValue(['missing' => $missing, 'external_publish' => false]),
                ($userId ?? $this->currentUserId()) ?: null,
            ]
        );

        return (int) Database::lastInsertId();
    }

    public function markChannelExportBundleExported(int $id): array
    {
        $bundle = $this->getChannelExportBundle($id);
        if (!$bundle) {
            throw new RuntimeException('Marketing channel export bundle not found.');
        }

        Database::execute(
            "UPDATE marketing_channel_export_bundles
             SET status = 'exported', exported_at = COALESCE(exported_at, NOW())
             WHERE workspace_id = ? AND id = ?",
            [$this->workspaceId(), $id]
        );

        return $this->getChannelExportBundle($id) ?? [];
    }

    public function listChannelConnectors(array $filters = [], int $limit = 100, int $offset = 0): array
    {
        if (!Database::tableExists('marketing_channel_connectors')) {
            return [];
        }

        $limit = min(max($limit, 1), 250);
        $offset = max($offset, 0);
        $workspace = $this->workspaceClause('cc.');
        $where = [$workspace['sql']];
        $params = $workspace['params'];

        if (!empty($filters['connector_type'])) {
            $where[] = 'cc.connector_type = ?';
            $params[] = $this->normalizeEnum((string) $filters['connector_type'], self::CHANNEL_CONNECTOR_TYPES, 'connector_type');
        }
        if (!empty($filters['status'])) {
            $where[] = 'cc.status = ?';
            $params[] = $this->normalizeEnum((string) $filters['status'], self::CHANNEL_CONNECTOR_STATUSES, 'connector_status');
        }
        if (!empty($filters['setup_status'])) {
            $where[] = 'cc.setup_status = ?';
            $params[] = $this->normalizeEnum((string) $filters['setup_status'], self::CHANNEL_CONNECTOR_SETUP_STATUSES, 'connector_setup_status');
        }
        if (!empty($filters['owner_user_id'])) {
            $where[] = 'cc.owner_user_id = ?';
            $params[] = (int) $filters['owner_user_id'];
        }

        return array_map(
            fn(array $row): array => $this->hydrateJsonFields($row, ['capabilities_json', 'config_json', 'diagnostics_json', 'setup_checklist_json', 'last_readiness_missing_checks_json', 'live_preflight_json', 'live_throttle_json']),
            Database::query(
                "SELECT cc.*, owner.email AS owner_email, creator.email AS created_by_email,
                        (SELECT COUNT(*) FROM marketing_channel_connector_test_runs tr WHERE tr.workspace_id = cc.workspace_id AND tr.connector_id = cc.id) AS test_run_count,
                        (SELECT tr.status FROM marketing_channel_connector_test_runs tr WHERE tr.workspace_id = cc.workspace_id AND tr.connector_id = cc.id ORDER BY tr.created_at DESC LIMIT 1) AS last_test_status,
                        (SELECT rr.status FROM marketing_channel_connector_readiness_reviews rr WHERE rr.workspace_id = cc.workspace_id AND rr.connector_id = cc.id ORDER BY rr.created_at DESC, rr.id DESC LIMIT 1) AS last_readiness_status,
                        (SELECT rr.readiness_score FROM marketing_channel_connector_readiness_reviews rr WHERE rr.workspace_id = cc.workspace_id AND rr.connector_id = cc.id ORDER BY rr.created_at DESC, rr.id DESC LIMIT 1) AS last_readiness_score,
                        (SELECT rr.missing_checks_json FROM marketing_channel_connector_readiness_reviews rr WHERE rr.workspace_id = cc.workspace_id AND rr.connector_id = cc.id ORDER BY rr.created_at DESC, rr.id DESC LIMIT 1) AS last_readiness_missing_checks_json,
                        " . (Database::tableExists('marketing_channel_connector_health_probes')
                            ? "(SELECT COUNT(*) FROM marketing_channel_connector_health_probes hp WHERE hp.workspace_id = cc.workspace_id AND hp.connector_id = cc.id) AS health_probe_count,
                        (SELECT hp.status FROM marketing_channel_connector_health_probes hp WHERE hp.workspace_id = cc.workspace_id AND hp.connector_id = cc.id ORDER BY hp.created_at DESC, hp.id DESC LIMIT 1) AS last_health_probe_status,
                        (SELECT hp.health_score FROM marketing_channel_connector_health_probes hp WHERE hp.workspace_id = cc.workspace_id AND hp.connector_id = cc.id ORDER BY hp.created_at DESC, hp.id DESC LIMIT 1) AS last_health_probe_score"
                            : "0 AS health_probe_count, NULL AS last_health_probe_status, NULL AS last_health_probe_score") . ",
                        " . (Database::tableExists('marketing_live_connector_secrets')
                            ? "(SELECT COUNT(*) FROM marketing_live_connector_secrets lcs WHERE lcs.workspace_id = cc.workspace_id AND lcs.connector_id = cc.id AND lcs.status = 'active') AS active_secret_count,
                        (SELECT lcs.secret_type FROM marketing_live_connector_secrets lcs WHERE lcs.workspace_id = cc.workspace_id AND lcs.connector_id = cc.id AND lcs.status = 'active' ORDER BY lcs.updated_at DESC, lcs.id DESC LIMIT 1) AS active_secret_type,
                        (SELECT lcs.last_verification_status FROM marketing_live_connector_secrets lcs WHERE lcs.workspace_id = cc.workspace_id AND lcs.connector_id = cc.id AND lcs.status = 'active' ORDER BY lcs.updated_at DESC, lcs.id DESC LIMIT 1) AS active_secret_verification_status,
                        (SELECT lcs.last_verified_at FROM marketing_live_connector_secrets lcs WHERE lcs.workspace_id = cc.workspace_id AND lcs.connector_id = cc.id AND lcs.status = 'active' ORDER BY lcs.updated_at DESC, lcs.id DESC LIMIT 1) AS active_secret_last_verified_at,
                        (SELECT lcs.rotated_at FROM marketing_live_connector_secrets lcs WHERE lcs.workspace_id = cc.workspace_id AND lcs.connector_id = cc.id AND lcs.status = 'active' ORDER BY lcs.updated_at DESC, lcs.id DESC LIMIT 1) AS active_secret_rotated_at,
                        (SELECT lcs.expires_at FROM marketing_live_connector_secrets lcs WHERE lcs.workspace_id = cc.workspace_id AND lcs.connector_id = cc.id AND lcs.status = 'active' ORDER BY lcs.updated_at DESC, lcs.id DESC LIMIT 1) AS active_secret_expires_at,
                        (SELECT lcs.rotation_due_at FROM marketing_live_connector_secrets lcs WHERE lcs.workspace_id = cc.workspace_id AND lcs.connector_id = cc.id AND lcs.status = 'active' ORDER BY lcs.updated_at DESC, lcs.id DESC LIMIT 1) AS active_secret_rotation_due_at,
                        (SELECT lcs.rotation_interval_days FROM marketing_live_connector_secrets lcs WHERE lcs.workspace_id = cc.workspace_id AND lcs.connector_id = cc.id AND lcs.status = 'active' ORDER BY lcs.updated_at DESC, lcs.id DESC LIMIT 1) AS active_secret_rotation_interval_days,
                        (SELECT lcs.freshness_status FROM marketing_live_connector_secrets lcs WHERE lcs.workspace_id = cc.workspace_id AND lcs.connector_id = cc.id AND lcs.status = 'active' ORDER BY lcs.updated_at DESC, lcs.id DESC LIMIT 1) AS active_secret_freshness_status,
                        (SELECT COUNT(*) FROM marketing_live_connector_secrets lcs WHERE lcs.workspace_id = cc.workspace_id AND lcs.connector_id = cc.id AND lcs.status = 'revoked') AS revoked_secret_count"
                            : "0 AS active_secret_count, NULL AS active_secret_type, NULL AS active_secret_verification_status, NULL AS active_secret_last_verified_at, NULL AS active_secret_rotated_at, NULL AS active_secret_expires_at, NULL AS active_secret_rotation_due_at, NULL AS active_secret_rotation_interval_days, NULL AS active_secret_freshness_status, 0 AS revoked_secret_count") . ",
                        " . (Database::tableExists('marketing_live_connector_secret_events')
                            ? "(SELECT COUNT(*) FROM marketing_live_connector_secret_events se WHERE se.workspace_id = cc.workspace_id AND se.connector_id = cc.id) AS secret_event_count"
                            : "0 AS secret_event_count") . "
                 FROM marketing_channel_connectors cc
                 LEFT JOIN users owner ON owner.id = cc.owner_user_id
                 LEFT JOIN users creator ON creator.id = cc.created_by
                 WHERE " . implode(' AND ', $where) . "
                 ORDER BY FIELD(cc.status, 'ready', 'configured', 'draft', 'blocked', 'archived'), cc.updated_at DESC
                 LIMIT {$limit} OFFSET {$offset}",
                $params
            )
        );
    }

    public function getChannelConnector(int $id): ?array
    {
        if (!Database::tableExists('marketing_channel_connectors')) {
            return null;
        }

        $row = Database::queryOne(
            "SELECT cc.*, owner.email AS owner_email, creator.email AS created_by_email
             FROM marketing_channel_connectors cc
             LEFT JOIN users owner ON owner.id = cc.owner_user_id
             LEFT JOIN users creator ON creator.id = cc.created_by
             WHERE cc.workspace_id = ? AND cc.id = ?",
            [$this->workspaceId(), $id]
        );

        return $row ? $this->hydrateJsonFields($row, ['capabilities_json', 'config_json', 'diagnostics_json', 'setup_checklist_json', 'live_preflight_json', 'live_throttle_json']) : null;
    }

    public function createChannelConnector(array $data): int
    {
        $this->assertMarketingPermission('marketing.write');
        if (!Database::tableExists('marketing_channel_connectors')) {
            throw new RuntimeException('Marketing channel connectors are unavailable.');
        }

        $normalized = $this->normalizeChannelConnectorData($data, true);
        Database::execute(
            "INSERT INTO marketing_channel_connectors
             (workspace_id, uuid, name, connector_type, status, execution_mode, live_enabled, live_adapter_key,
              live_hourly_cap, live_daily_cap, live_cooldown_seconds, last_live_attempt_at, live_throttle_json,
              secret_reference, secret_status, setup_status, readiness_score,
               setup_checklist_json, setup_notes, capabilities_json, config_json, diagnostics_json, last_tested_at,
               last_live_check_at, live_preflight_status, live_preflight_checked_at, live_preflight_json,
               last_readiness_review_at, owner_user_id, created_by)
             VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)",
            [
                $this->workspaceId(),
                $this->generateUuid(),
                $normalized['name'],
                $normalized['connector_type'],
                $normalized['status'],
                $normalized['execution_mode'],
                $normalized['live_enabled'],
                $normalized['live_adapter_key'],
                $normalized['live_hourly_cap'],
                $normalized['live_daily_cap'],
                $normalized['live_cooldown_seconds'],
                $normalized['last_live_attempt_at'],
                $normalized['live_throttle_json'],
                $normalized['secret_reference'],
                $normalized['secret_status'],
                $normalized['setup_status'],
                $normalized['readiness_score'],
                $normalized['setup_checklist_json'],
                $normalized['setup_notes'],
                $normalized['capabilities_json'],
                $normalized['config_json'],
                $normalized['diagnostics_json'],
                $normalized['last_tested_at'],
                $normalized['last_live_check_at'],
                $normalized['live_preflight_status'],
                $normalized['live_preflight_checked_at'],
                $normalized['live_preflight_json'],
                $normalized['last_readiness_review_at'],
                $normalized['owner_user_id'],
                $normalized['created_by'],
            ]
        );

        return (int) Database::lastInsertId();
    }

    public function updateChannelConnector(int $id, array $data): bool
    {
        $this->assertMarketingPermission('marketing.write');
        if (!$this->getChannelConnector($id)) {
            throw new RuntimeException('Marketing channel connector not found.');
        }

        return $this->updateById('marketing_channel_connectors', $id, $this->normalizeChannelConnectorData($data, false));
    }

    public function archiveChannelConnector(int $id): bool
    {
        $this->assertMarketingPermission('marketing.manage');
        if (!$this->getChannelConnector($id)) {
            throw new RuntimeException('Marketing channel connector not found.');
        }

        return $this->updateById('marketing_channel_connectors', $id, ['status' => 'archived']);
    }

    public function saveChannelConnectorLiveSecret(int $connectorId, array $data, int $actorId): array
    {
        $this->assertMarketingPermission('marketing.manage');
        if (!Database::tableExists('marketing_live_connector_secrets')) {
            throw new RuntimeException('Marketing live connector secret storage is unavailable.');
        }
        $connector = $this->getChannelConnector($connectorId);
        if (!$connector) {
            throw new RuntimeException('Marketing channel connector not found.');
        }
        $actorId = $actorId > 0 ? $actorId : ($this->currentUserId() ?: 0);
        if ($actorId > 0) {
            $this->assertWorkspaceUser($actorId, $this->workspaceId());
        }

        $reference = trim((string) ($data['secret_reference'] ?? $connector['secret_reference'] ?? ''));
        if ($reference === '') {
            $reference = 'vault://marketing/connector/' . $connectorId;
        }
        $reference = mb_substr(Security::sanitizeInput($reference, 'string'), 0, 190);
        $secretValue = trim((string) ($data['secret_value'] ?? ''));
        if ($secretValue === '') {
            throw new \InvalidArgumentException('Live connector secret value is required.');
        }
        $existingSecret = $this->activeChannelConnectorSecretRow($connectorId, $reference);
        $eventType = $existingSecret ? 'rotated' : 'saved';
        $secretType = $this->normalizeEnum((string) ($data['secret_type'] ?? 'bearer_token'), self::LIVE_CONNECTOR_SECRET_TYPES, 'live_connector_secret_type');
        $headerName = trim((string) ($data['header_name'] ?? ''));
        if ($headerName === '') {
            $headerName = $secretType === 'bearer_token' ? 'Authorization' : 'X-API-Key';
        }
        $headerName = preg_replace('/[^A-Za-z0-9-]/', '', $headerName) ?: ($secretType === 'bearer_token' ? 'Authorization' : 'X-API-Key');
        $headerPrefix = trim((string) ($data['header_prefix'] ?? ''));
        if ($headerPrefix === '' && $secretType === 'bearer_token') {
            $headerPrefix = 'Bearer';
        }
        $headerPrefix = mb_substr(Security::sanitizeInput($headerPrefix, 'string'), 0, 80);
        $label = $this->nullableSanitizedText($data['secret_label'] ?? '') ?: 'Live connector credential';
        $encrypted = Security::encryptSensitiveData($secretValue, $this->marketingLiveConnectorEncryptionKey());
        $expiresAt = $this->normalizeDateTime((string) ($data['expires_at'] ?? ''));
        $rotationIntervalDays = max(0, min(3650, (int) ($data['rotation_interval_days'] ?? 0)));
        $rotationDueAt = $this->normalizeDateTime((string) ($data['rotation_due_at'] ?? ''));
        if ($rotationDueAt === null && $rotationIntervalDays > 0) {
            $rotationDueAt = date('Y-m-d H:i:00', strtotime('+' . $rotationIntervalDays . ' days'));
        }
        $freshness = $this->evaluateChannelConnectorSecretFreshness([
            'status' => 'active',
            'expires_at' => $expiresAt,
            'rotation_due_at' => $rotationDueAt,
            'rotation_interval_days' => $rotationIntervalDays > 0 ? $rotationIntervalDays : null,
        ]);
        $verificationStatus = empty($freshness['blockers']) ? 'passed' : 'failed';
        $metadata = [
            'secret_value_stored' => true,
            'freshness_status' => (string) ($freshness['freshness_status'] ?? 'fresh'),
            'freshness_blockers' => (array) ($freshness['blockers'] ?? []),
            'freshness_warnings' => (array) ($freshness['warnings'] ?? []),
            'raw_secret_values_visible' => false,
            'source' => 'marketing_channel_exports',
            'updated_from_ui' => true,
        ];

        Database::execute(
            "INSERT INTO marketing_live_connector_secrets
             (workspace_id, connector_id, uuid, secret_reference, secret_label, secret_type, header_name,
              header_prefix, encrypted_value, status, last_verified_at, last_verification_status, rotated_at,
              expires_at, rotation_due_at, rotation_interval_days, freshness_status,
              revoked_at, revoked_by, verified_by, metadata_json, created_by, updated_by)
             VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, 'active', NOW(), ?, ?, ?, ?, ?, ?, NULL, NULL, ?, ?, ?, ?)
             ON DUPLICATE KEY UPDATE
                connector_id = VALUES(connector_id),
                secret_label = VALUES(secret_label),
                secret_type = VALUES(secret_type),
                header_name = VALUES(header_name),
                header_prefix = VALUES(header_prefix),
                encrypted_value = VALUES(encrypted_value),
                status = 'active',
                last_verified_at = NOW(),
                last_verification_status = VALUES(last_verification_status),
                rotated_at = NOW(),
                expires_at = VALUES(expires_at),
                rotation_due_at = VALUES(rotation_due_at),
                rotation_interval_days = VALUES(rotation_interval_days),
                freshness_status = VALUES(freshness_status),
                revoked_at = NULL,
                revoked_by = NULL,
                verified_by = VALUES(verified_by),
                metadata_json = VALUES(metadata_json),
                updated_by = VALUES(updated_by),
                updated_at = NOW()",
            [
                $this->workspaceId(),
                $connectorId,
                $this->generateUuid(),
                $reference,
                mb_substr($label, 0, 190),
                $secretType,
                mb_substr($headerName, 0, 120),
                $headerPrefix !== '' ? $headerPrefix : null,
                $encrypted,
                $verificationStatus,
                $eventType === 'rotated' ? date('Y-m-d H:i:s') : null,
                $expiresAt,
                $rotationDueAt,
                $rotationIntervalDays > 0 ? $rotationIntervalDays : null,
                (string) ($freshness['freshness_status'] ?? 'fresh'),
                $actorId > 0 ? $actorId : null,
                $this->normalizeJsonValue($metadata),
                $actorId > 0 ? $actorId : null,
                $actorId > 0 ? $actorId : null,
            ]
        );
        $secretRow = $this->activeChannelConnectorSecretRow($connectorId, $reference);
        $this->updateById('marketing_channel_connectors', $connectorId, [
            'secret_reference' => $reference,
            'secret_status' => 'verified',
            'live_preflight_status' => empty($freshness['blockers']) ? 'not_checked' : 'blocked',
            'live_preflight_checked_at' => null,
            'live_preflight_json' => $this->normalizeJsonValue([
                'secret_rotated_at' => date('c'),
                'secret_freshness_status' => (string) ($freshness['freshness_status'] ?? 'fresh'),
                'secret_freshness_blockers' => (array) ($freshness['blockers'] ?? []),
                'secret_freshness_warnings' => (array) ($freshness['warnings'] ?? []),
                'live_preflight_required' => true,
                'live_preflight_blockers' => (array) ($freshness['blockers'] ?? []),
                'raw_secret_values_visible' => false,
            ]),
        ]);
        $this->recordChannelConnectorSecretEvent([
            'connector_id' => $connectorId,
            'secret_id' => (int) ($secretRow['id'] ?? 0),
            'event_type' => $eventType,
            'status' => 'passed',
            'message' => $eventType === 'rotated'
                ? 'Live connector secret rotated locally and requires live preflight before execution.'
                : 'Live connector secret saved locally and requires live preflight before execution.',
            'metadata' => [
                'secret_reference' => $reference,
                'secret_type' => $secretType,
                'header_name' => mb_substr($headerName, 0, 120),
                'freshness_status' => (string) ($freshness['freshness_status'] ?? 'fresh'),
                'freshness_blockers' => (array) ($freshness['blockers'] ?? []),
                'freshness_warnings' => (array) ($freshness['warnings'] ?? []),
                'secret_value_visible' => false,
                'raw_secret_values_visible' => false,
            ],
            'created_by' => $actorId,
        ]);

        return $this->channelConnectorLiveSecretSummary($connectorId);
    }

    public function channelConnectorLiveSecretSummary(int $connectorId): array
    {
        $this->assertMarketingPermission('marketing.read');
        if (!Database::tableExists('marketing_live_connector_secrets')) {
            return [
                'connector_id' => $connectorId,
                'configured' => false,
                'status' => 'unavailable',
                'secret_safe' => true,
            ];
        }
        $row = Database::queryOne(
            "SELECT id, connector_id, secret_reference, secret_label, secret_type, header_name, header_prefix,
                    status, last_verified_at, last_verification_status, expires_at, rotation_due_at,
                    rotation_interval_days, freshness_status, rotated_at, revoked_at, updated_at
             FROM marketing_live_connector_secrets
             WHERE workspace_id = ? AND connector_id = ? AND status = 'active'
             ORDER BY updated_at DESC, id DESC
             LIMIT 1",
            [$this->workspaceId(), $connectorId]
        );
        if (!$row) {
            return [
                'connector_id' => $connectorId,
                'configured' => false,
                'status' => 'missing',
                'secret_safe' => true,
            ];
        }

        return [
            'connector_id' => (int) ($row['connector_id'] ?? $connectorId),
            'configured' => true,
            'status' => (string) ($row['status'] ?? 'active'),
            'secret_reference' => (string) ($row['secret_reference'] ?? ''),
            'secret_label' => (string) ($row['secret_label'] ?? ''),
            'secret_type' => (string) ($row['secret_type'] ?? 'bearer_token'),
            'header_name' => (string) ($row['header_name'] ?? ''),
            'header_prefix' => (string) ($row['header_prefix'] ?? ''),
            'last_verified_at' => $row['last_verified_at'] ?? null,
            'last_verification_status' => $row['last_verification_status'] ?? null,
            'expires_at' => $row['expires_at'] ?? null,
            'rotation_due_at' => $row['rotation_due_at'] ?? null,
            'rotation_interval_days' => $row['rotation_interval_days'] ?? null,
            'freshness_status' => $row['freshness_status'] ?? null,
            'rotated_at' => $row['rotated_at'] ?? null,
            'revoked_at' => $row['revoked_at'] ?? null,
            'updated_at' => $row['updated_at'] ?? null,
            'secret_value_visible' => false,
            'secret_safe' => true,
        ];
    }

    public function verifyChannelConnectorLiveSecret(int $connectorId, int $actorId): array
    {
        $this->assertMarketingPermission('marketing.manage');
        if (!Database::tableExists('marketing_live_connector_secrets')) {
            throw new RuntimeException('Marketing live connector secret storage is unavailable.');
        }
        $connector = $this->getChannelConnector($connectorId);
        if (!$connector) {
            throw new RuntimeException('Marketing channel connector not found.');
        }
        $actorId = $this->normalizeMarketingActorId($actorId);
        $reference = trim((string) ($connector['secret_reference'] ?? ''));
        $secretRow = $this->activeChannelConnectorSecretRow($connectorId, $reference);
        $resolved = $this->resolveChannelConnectorLiveSecret($connector);
        $secretResolved = !empty($resolved['configured']);
        $freshnessBlockers = (array) ($resolved['proof']['freshness_blockers'] ?? []);
        $freshnessStatus = (string) ($resolved['proof']['freshness_status'] ?? 'unknown');
        $configured = $secretResolved && $freshnessBlockers === [];
        $verificationStatus = $configured ? 'passed' : 'failed';
        $reason = (string) ($resolved['proof']['reason'] ?? ($configured ? 'secret_resolved' : ($freshnessBlockers[0] ?? 'secret_not_resolved')));

        if ($secretRow) {
            Database::execute(
                "UPDATE marketing_live_connector_secrets
                 SET last_verified_at = NOW(),
                     last_verification_status = ?,
                     freshness_status = ?,
                     verified_by = ?,
                     updated_by = ?,
                     updated_at = NOW()
                 WHERE workspace_id = ? AND id = ?",
                [
                    $verificationStatus,
                    $this->normalizeEnum($freshnessStatus, ['fresh', 'rotation_due', 'expired', 'revoked', 'unknown'], 'live_connector_secret_freshness_status'),
                    $actorId > 0 ? $actorId : null,
                    $actorId > 0 ? $actorId : null,
                    $this->workspaceId(),
                    (int) $secretRow['id'],
                ]
            );
        }

        $this->updateById('marketing_channel_connectors', $connectorId, [
            'secret_status' => $configured ? 'verified' : ($freshnessStatus === 'expired' ? 'expired' : 'blocked'),
            'live_preflight_status' => $configured ? 'not_checked' : 'blocked',
            'live_preflight_checked_at' => null,
            'live_preflight_json' => $this->normalizeJsonValue([
                'secret_verified_at' => date('c'),
                'secret_verification_status' => $verificationStatus,
                'secret_verification_reason' => $reason,
                'secret_freshness_status' => $freshnessStatus,
                'secret_freshness_blockers' => $freshnessBlockers,
                'secret_freshness_warnings' => (array) ($resolved['proof']['freshness_warnings'] ?? []),
                'live_preflight_required' => $configured,
                'live_preflight_blockers' => $configured ? [] : ($freshnessBlockers ?: ['connector_secret_verification_failed']),
                'can_run_live_queue' => false,
                'raw_secret_values_visible' => false,
            ]),
        ]);
        $this->recordChannelConnectorSecretEvent([
            'connector_id' => $connectorId,
            'secret_id' => (int) ($secretRow['id'] ?? 0),
            'event_type' => $configured ? 'verified' : 'verification_failed',
            'status' => $configured ? 'passed' : 'failed',
            'message' => $configured
                ? 'Live connector secret decrypted locally and header proof is ready for preflight.'
                : 'Live connector secret verification failed before live preflight.',
            'metadata' => [
                'secret_reference' => $reference,
                'verification_reason' => $reason,
                'secret' => (array) ($resolved['proof'] ?? []),
                'freshness_status' => $freshnessStatus,
                'freshness_blockers' => $freshnessBlockers,
                'secret_value_visible' => false,
                'raw_secret_values_visible' => false,
                'external_api_called' => false,
            ],
            'created_by' => $actorId,
        ]);

        return array_merge($this->channelConnectorLiveSecretSummary($connectorId), [
            'verification_status' => $verificationStatus,
            'verification_reason' => $reason,
            'configured' => $secretResolved,
            'freshness_status' => $freshnessStatus,
            'freshness_blockers' => $freshnessBlockers,
            'secret_value_visible' => false,
            'secret_safe' => true,
        ]);
    }

    public function revokeChannelConnectorLiveSecret(int $connectorId, int $actorId, string $reason = ''): array
    {
        $this->assertMarketingPermission('marketing.manage');
        if (!Database::tableExists('marketing_live_connector_secrets')) {
            throw new RuntimeException('Marketing live connector secret storage is unavailable.');
        }
        $connector = $this->getChannelConnector($connectorId);
        if (!$connector) {
            throw new RuntimeException('Marketing channel connector not found.');
        }
        $actorId = $this->normalizeMarketingActorId($actorId);
        $reason = mb_substr(Security::sanitizeInput(trim($reason), 'string'), 0, 500);
        if ($reason === '') {
            $reason = 'Credential revoked by marketing manager.';
        }
        $secretRow = $this->activeChannelConnectorSecretRow($connectorId, trim((string) ($connector['secret_reference'] ?? '')));

        Database::execute(
            "UPDATE marketing_live_connector_secrets
                 SET status = 'revoked',
                     revoked_at = NOW(),
                     revoked_by = ?,
                     last_verification_status = 'revoked',
                     freshness_status = 'revoked',
                     updated_by = ?,
                 updated_at = NOW()
             WHERE workspace_id = ? AND connector_id = ? AND status = 'active'",
            [
                $actorId > 0 ? $actorId : null,
                $actorId > 0 ? $actorId : null,
                $this->workspaceId(),
                $connectorId,
            ]
        );
        $this->updateById('marketing_channel_connectors', $connectorId, [
            'live_enabled' => 0,
            'secret_status' => 'blocked',
            'live_preflight_status' => 'blocked',
            'live_preflight_checked_at' => null,
            'live_preflight_json' => $this->normalizeJsonValue([
                'secret_revoked_at' => date('c'),
                'secret_revocation_reason' => $reason,
                'live_preflight_blockers' => ['connector_secret_revoked'],
                'can_run_live_queue' => false,
                'raw_secret_values_visible' => false,
            ]),
        ]);
        $this->recordChannelConnectorSecretEvent([
            'connector_id' => $connectorId,
            'secret_id' => (int) ($secretRow['id'] ?? 0),
            'event_type' => 'revoked',
            'status' => 'blocked',
            'message' => 'Live connector secret revoked and connector live capability disabled.',
            'metadata' => [
                'secret_reference' => (string) ($connector['secret_reference'] ?? ''),
                'reason' => $reason,
                'live_enabled_after_revoke' => false,
                'secret_value_visible' => false,
                'raw_secret_values_visible' => false,
            ],
            'created_by' => $actorId,
        ]);

        return [
            'connector_id' => $connectorId,
            'configured' => false,
            'status' => 'revoked',
            'verification_status' => 'revoked',
            'revoked' => true,
            'secret_value_visible' => false,
            'secret_safe' => true,
        ];
    }

    public function listChannelConnectorSecretEvents(int $connectorId, int $limit = 20, int $offset = 0): array
    {
        $this->assertMarketingPermission('marketing.read');
        if (!Database::tableExists('marketing_live_connector_secret_events')) {
            return [];
        }
        if (!$this->getChannelConnector($connectorId)) {
            throw new RuntimeException('Marketing channel connector not found.');
        }
        $limit = min(max($limit, 1), 100);
        $offset = max($offset, 0);

        return array_map(
            fn(array $row): array => $this->hydrateJsonFields($row, ['metadata_json']),
            Database::query(
                "SELECT se.*, creator.email AS created_by_email
                 FROM marketing_live_connector_secret_events se
                 LEFT JOIN users creator ON creator.id = se.created_by
                 WHERE se.workspace_id = ? AND se.connector_id = ?
                 ORDER BY se.created_at DESC, se.id DESC
                 LIMIT {$limit} OFFSET {$offset}",
                [$this->workspaceId(), $connectorId]
            )
        );
    }

    public function listChannelConnectorTestRuns(array $filters = [], int $limit = 100, int $offset = 0): array
    {
        if (!Database::tableExists('marketing_channel_connector_test_runs')) {
            return [];
        }

        $limit = min(max($limit, 1), 250);
        $offset = max($offset, 0);
        $workspace = $this->workspaceClause('tr.');
        $where = [$workspace['sql']];
        $params = $workspace['params'];
        if (!empty($filters['connector_id'])) {
            $where[] = 'tr.connector_id = ?';
            $params[] = (int) $filters['connector_id'];
        }
        if (!empty($filters['status'])) {
            $where[] = 'tr.status = ?';
            $params[] = $this->normalizeEnum((string) $filters['status'], self::CHANNEL_CONNECTOR_TEST_STATUSES, 'connector_test_status');
        }

        return array_map(
            fn(array $row): array => $this->hydrateJsonFields($row, ['input_json', 'result_json', 'diagnostics_json']),
            Database::query(
                "SELECT tr.*, cc.name AS connector_name, cc.connector_type, creator.email AS created_by_email
                 FROM marketing_channel_connector_test_runs tr
                 JOIN marketing_channel_connectors cc ON cc.id = tr.connector_id AND cc.workspace_id = tr.workspace_id
                 LEFT JOIN users creator ON creator.id = tr.created_by
                 WHERE " . implode(' AND ', $where) . "
                 ORDER BY tr.created_at DESC, tr.id DESC
                 LIMIT {$limit} OFFSET {$offset}",
                $params
            )
        );
    }

