    public function evaluateChannelConnectorReadiness(int $connectorId, ?int $userId = null): array
    {
        $this->assertMarketingPermission('marketing.write');
        $connector = $this->getChannelConnector($connectorId);
        if (!$connector) {
            throw new RuntimeException('Marketing channel connector not found.');
        }
        if (!Database::tableExists('marketing_channel_connector_readiness_reviews')) {
            throw new RuntimeException('Marketing connector readiness reviews are unavailable.');
        }

        $diagnostics = $this->buildChannelConnectorDiagnostics($connector);
        $latestTest = $this->listChannelConnectorTestRuns(['connector_id' => $connectorId], 1, 0)[0] ?? null;
        $checklist = (array) ($connector['setup_checklist_json'] ?? []);
        $connectorType = (string) ($connector['connector_type'] ?? 'other');
        $contactChannel = in_array($connectorType, ['email', 'whatsapp', 'sms'], true);

        $requiredChecks = [
            [
                'key' => 'capabilities_ready',
                'label' => 'Required capabilities configured',
                'passed' => empty($diagnostics['missing_capabilities']),
                'message' => empty($diagnostics['missing_capabilities'])
                    ? 'All required dry-run capabilities are configured.'
                    : 'Missing capabilities: ' . implode(', ', (array) $diagnostics['missing_capabilities']),
            ],
            [
                'key' => 'dry_run_test_passed',
                'label' => 'Dry-run diagnostics passed',
                'passed' => (string) ($latestTest['status'] ?? '') === 'passed',
                'message' => (string) ($latestTest['status'] ?? '') === 'passed'
                    ? 'Latest connector diagnostic test passed.'
                    : 'Run a dry-run connector diagnostic before marking this connector ready.',
            ],
            [
                'key' => 'owner_assigned',
                'label' => 'Owner assigned',
                'passed' => (int) ($connector['owner_user_id'] ?? 0) > 0,
                'message' => (int) ($connector['owner_user_id'] ?? 0) > 0
                    ? 'Connector owner is assigned.'
                    : 'Assign an owner before execution work begins.',
            ],
            [
                'key' => 'secret_safe',
                'label' => 'Secrets hidden from diagnostics',
                'passed' => !empty($diagnostics['secret_safe']) && empty($diagnostics['unsafe_config_fields']),
                'message' => empty($diagnostics['unsafe_config_fields'])
                    ? 'Visible diagnostics are sanitized.'
                    : 'Unsafe visible config fields: ' . implode(', ', (array) $diagnostics['unsafe_config_fields']),
            ],
            [
                'key' => 'external_execution_disabled',
                'label' => 'External execution disabled',
                'passed' => empty($diagnostics['live_execution_enabled']) && (string) ($connector['execution_mode'] ?? '') !== 'live',
                'message' => 'Connector remains in manual, test, dry-run, or live-disabled mode.',
            ],
        ];

        if ($contactChannel) {
            $requiredChecks[] = [
                'key' => 'consent_safety_reviewed',
                'label' => 'Consent and opt-out safety reviewed',
                'passed' => $this->connectorChecklistContains($checklist, ['consent', 'opt-in', 'opt in', 'permission'])
                    && ($connectorType !== 'email' || $this->connectorChecklistContains($checklist, ['suppression', 'unsubscribe'])),
                'message' => $connectorType === 'email'
                    ? 'Document consent policy and suppression/unsubscribe review in the setup checklist.'
                    : 'Document opt-in or consent review in the setup checklist.',
            ];
        }

        $passedCount = count(array_filter($requiredChecks, static fn(array $check): bool => !empty($check['passed'])));
        $score = (int) round(($passedCount / max(1, count($requiredChecks))) * 100);
        $missing = array_values(array_map(
            static fn(array $check): string => (string) $check['key'],
            array_filter($requiredChecks, static fn(array $check): bool => empty($check['passed']))
        ));
        $blocked = (string) ($connector['status'] ?? '') === 'archived' || !empty($diagnostics['unsafe_config_fields']);
        $status = $blocked ? 'blocked' : ($missing === [] && $score >= 90 ? 'ready' : 'needs_attention');
        $setupStatus = match ($status) {
            'ready' => 'ready',
            'blocked' => 'blocked',
            default => 'in_progress',
        };
        if (!in_array($setupStatus, self::CHANNEL_CONNECTOR_SETUP_STATUSES, true)) {
            $setupStatus = 'in_progress';
        }

        $recommendation = [
            'next_actions' => array_values(array_map(
                static fn(array $check): string => (string) $check['message'],
                array_filter($requiredChecks, static fn(array $check): bool => empty($check['passed']))
            )),
            'manual_first_boundary' => [
                'external_publish' => false,
                'external_send' => false,
                'external_api_call' => false,
            ],
        ];
        $storedDiagnostics = array_merge($diagnostics, [
            'readiness_status' => $status,
            'readiness_score' => $score,
            'readiness_missing_checks' => $missing,
        ]);

        Database::execute(
            "INSERT INTO marketing_channel_connector_readiness_reviews
             (workspace_id, connector_id, uuid, status, readiness_score, required_checks_json, missing_checks_json,
              recommendation_json, diagnostics_json, metadata_json, created_by)
             VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)",
            [
                $this->workspaceId(),
                $connectorId,
                $this->generateUuid(),
                $status,
                $score,
                $this->normalizeJsonValue($requiredChecks),
                $this->normalizeJsonValue($missing),
                $this->normalizeJsonValue($recommendation),
                $this->normalizeJsonValue($storedDiagnostics),
                $this->normalizeJsonValue([
                    'source' => 'marketing_connector_readiness_setup',
                    'manual_first' => true,
                    'external_execution' => false,
                ]),
                ($userId ?? $this->currentUserId()) ?: null,
            ]
        );

        Database::execute(
            "UPDATE marketing_channel_connectors
             SET setup_status = ?, readiness_score = ?, diagnostics_json = ?, last_readiness_review_at = NOW()
             WHERE workspace_id = ? AND id = ?",
            [
                $setupStatus,
                $score,
                $this->normalizeJsonValue($storedDiagnostics),
                $this->workspaceId(),
                $connectorId,
            ]
        );

        return $this->listChannelConnectorReadinessReviews(['connector_id' => $connectorId], 1, 0)[0] ?? [
            'connector_id' => $connectorId,
            'status' => $status,
            'readiness_score' => $score,
            'missing_checks_json' => $missing,
        ];
    }

    public function getChannelConnectorReadinessSummary(): array
    {
        if (!Database::tableExists('marketing_channel_connectors')) {
            return [
                'total_connectors' => 0,
                'average_readiness_score' => 0,
                'by_setup_status' => array_fill_keys(self::CHANNEL_CONNECTOR_SETUP_STATUSES, 0),
                'ready_connectors' => 0,
                'blocked_connectors' => 0,
                'needs_review_connectors' => 0,
            ];
        }

        $connectors = $this->listChannelConnectors([], 250, 0);
        $bySetupStatus = array_fill_keys(self::CHANNEL_CONNECTOR_SETUP_STATUSES, 0);
        $scoreTotal = 0;
        foreach ($connectors as $connector) {
            $setupStatus = (string) ($connector['setup_status'] ?? 'not_started');
            if (!isset($bySetupStatus[$setupStatus])) {
                $setupStatus = 'not_started';
            }
            $bySetupStatus[$setupStatus]++;
            $scoreTotal += (int) ($connector['readiness_score'] ?? 0);
        }

        return [
            'total_connectors' => count($connectors),
            'average_readiness_score' => count($connectors) > 0 ? (int) round($scoreTotal / count($connectors)) : 0,
            'by_setup_status' => $bySetupStatus,
            'ready_connectors' => $bySetupStatus['ready'] ?? 0,
            'blocked_connectors' => $bySetupStatus['blocked'] ?? 0,
            'needs_review_connectors' => ($bySetupStatus['not_started'] ?? 0) + ($bySetupStatus['in_progress'] ?? 0),
        ];
    }

