    public function runChannelConnectorHealthProbe(int $connectorId, array $input = []): array
    {
        $this->assertMarketingPermission('marketing.write');
        if (!Database::tableExists('marketing_channel_connector_health_probes')) {
            throw new RuntimeException('Marketing connector health probes are unavailable.');
        }
        $connector = $this->getChannelConnector($connectorId);
        if (!$connector) {
            throw new RuntimeException('Marketing channel connector not found.');
        }
        $probeMode = $this->normalizeEnum((string) ($input['probe_mode'] ?? 'local_adapter'), self::CHANNEL_CONNECTOR_HEALTH_PROBE_MODES, 'connector_health_probe_mode');
        $probe = $this->buildChannelConnectorHealthProbe($connector, $probeMode, $input);
        $createdBy = (int) ($input['created_by'] ?? $this->currentUserId()) ?: null;

        Database::execute(
            "INSERT INTO marketing_channel_connector_health_probes
             (workspace_id, connector_id, uuid, probe_mode, status, health_score, adapter_key,
              required_checks_json, passed_checks_json, warnings_json, blockers_json, diagnostics_json,
              external_api_called, created_by)
             VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, 0, ?)",
            [
                $this->workspaceId(),
                $connectorId,
                $this->generateUuid(),
                $probeMode,
                (string) ($probe['status'] ?? 'degraded'),
                (int) ($probe['health_score'] ?? 0),
                (string) ($connector['live_adapter_key'] ?? ''),
                $this->normalizeJsonValue($probe['required_checks'] ?? []),
                $this->normalizeJsonValue($probe['passed_checks'] ?? []),
                $this->normalizeJsonValue($probe['warnings'] ?? []),
                $this->normalizeJsonValue($probe['blockers'] ?? []),
                $this->normalizeJsonValue($probe['diagnostics'] ?? []),
                $createdBy,
            ]
        );

        Database::execute(
            "UPDATE marketing_channel_connectors
             SET health_status = ?,
                 health_score = ?,
                 last_health_probe_at = NOW(),
                 health_probe_json = ?,
                 diagnostics_json = ?
             WHERE workspace_id = ? AND id = ?",
            [
                (string) ($probe['status'] ?? 'degraded'),
                (int) ($probe['health_score'] ?? 0),
                $this->normalizeJsonValue($probe),
                $this->normalizeJsonValue(array_merge($this->buildChannelConnectorDiagnostics($connector), [
                    'health_status' => (string) ($probe['status'] ?? 'degraded'),
                    'health_score' => (int) ($probe['health_score'] ?? 0),
                    'health_blockers' => (array) ($probe['blockers'] ?? []),
                    'health_warnings' => (array) ($probe['warnings'] ?? []),
                ])),
                $this->workspaceId(),
                $connectorId,
            ]
        );

        return $this->listChannelConnectorHealthProbes(['connector_id' => $connectorId], 1, 0)[0] ?? [
            'connector_id' => $connectorId,
            'status' => (string) ($probe['status'] ?? 'degraded'),
            'health_score' => (int) ($probe['health_score'] ?? 0),
        ];
    }

    public function getExecutionControlCenterSummary(): array
    {
        $executionQueue = Database::tableExists('marketing_execution_queue') ? $this->listExecutionQueue([], 100, 0) : [];
        $channelExports = Database::tableExists('marketing_channel_export_bundles') ? $this->listChannelExportBundles(['open' => true], 100, 0) : [];
        $emailRuns = Database::tableExists('marketing_email_campaign_runs') ? $this->listEmailCampaignRuns(['open' => true], 100, 0) : [];
        $distributionPosts = Database::tableExists('marketing_distribution_posts') ? $this->listDistributionPosts(['open' => true], 100, 0) : [];
        $launchReadiness = Database::tableExists('marketing_launch_readiness_reviews') ? $this->listLaunchReadinessReviews(['open' => true], 100, 0) : [];
        $launchControl = Database::tableExists('marketing_launch_control_records') ? $this->listLaunchControlRecords(['open' => true], 100, 0) : [];
        $connectors = Database::tableExists('marketing_channel_connectors') ? $this->listChannelConnectors([], 100, 0) : [];
        $connectorReviews = Database::tableExists('marketing_channel_connector_readiness_reviews') ? $this->listChannelConnectorReadinessReviews([], 12, 0) : [];
        $connectorReadiness = $this->getChannelConnectorReadinessSummary();
        $liveReadiness = Database::tableExists('marketing_live_execution_policies')
            ? $this->getMarketingLiveExecutionReadiness()
            : ['status' => 'disabled', 'policy' => $this->liveExecutionPolicySnapshot($this->defaultMarketingLiveExecutionPolicy()), 'counts' => []];

        $queueReady = array_values(array_filter(
            $executionQueue,
            static fn(array $row): bool => in_array((string) ($row['status'] ?? ''), ['approved', 'queued'], true)
                && in_array((string) ($row['execution_mode'] ?? 'dry_run'), ['dry_run', 'test'], true)
        ));
        $queueBlocked = array_values(array_filter(
            $executionQueue,
            static fn(array $row): bool => in_array((string) ($row['status'] ?? ''), ['blocked', 'failed'], true)
        ));
        $queuePending = array_values(array_filter(
            $executionQueue,
            static fn(array $row): bool => in_array((string) ($row['status'] ?? ''), ['draft', 'pending_approval'], true)
        ));
        $launchBlocked = array_values(array_filter(
            array_merge($launchReadiness, $launchControl),
            static fn(array $row): bool => (string) ($row['status'] ?? '') === 'blocked'
        ));
        $launchReady = array_values(array_filter(
            $launchControl,
            static fn(array $row): bool => (string) ($row['status'] ?? '') === 'ready'
        ));
        $connectorBlocked = array_values(array_filter(
            $connectors,
            static fn(array $row): bool => (string) ($row['setup_status'] ?? '') === 'blocked' || (string) ($row['status'] ?? '') === 'blocked'
        ));
        $connectorNeedsReview = array_values(array_filter(
            $connectors,
            static fn(array $row): bool => in_array((string) ($row['setup_status'] ?? 'not_started'), ['not_started', 'in_progress'], true)
        ));
        $emailNeedsReview = array_values(array_filter(
            $emailRuns,
            static fn(array $row): bool => !empty($row['readiness_warnings_json']) || !empty($row['safety_warnings_json']) || (string) ($row['approval_status'] ?? '') !== 'approved'
        ));
        $channelReady = array_values(array_filter(
            $channelExports,
            static fn(array $row): bool => (string) ($row['status'] ?? '') === 'ready'
        ));

        $nextActions = [];
        if ($connectorNeedsReview !== []) {
            $nextActions[] = ['label' => 'Review connector setup', 'href' => 'marketing_channel_exports.php', 'reason' => 'Connector readiness is incomplete.'];
        }
        if ($queuePending !== []) {
            $nextActions[] = ['label' => 'Resolve pending execution queue', 'href' => 'marketing_channel_exports.php', 'reason' => 'Queue items need approval or dry-run preparation.'];
        }
        if ($launchBlocked !== []) {
            $nextActions[] = ['label' => 'Clear launch blockers', 'href' => 'marketing_launch_control.php?status=blocked', 'reason' => 'Launch readiness/control has blocked items.'];
        }
        if ($emailNeedsReview !== []) {
            $nextActions[] = ['label' => 'Fix email run readiness', 'href' => 'marketing_email_runs.php', 'reason' => 'Email runs have approval, consent, or export warnings.'];
        }
        if ($channelExports !== []) {
            $nextActions[] = ['label' => 'Package manual channel exports', 'href' => 'marketing_channel_exports.php', 'reason' => 'Manual export bundles are waiting.'];
        }
        if ($nextActions === []) {
            $nextActions[] = ['label' => 'Build the next campaign workspace', 'href' => 'marketing_campaign_workspace.php', 'reason' => 'No execution blockers are currently visible.'];
        }

        return [
            'counts' => [
                'ready_to_execute' => count($queueReady) + count($launchReady) + count($channelReady),
                'blocked' => count($queueBlocked) + count($launchBlocked) + count($connectorBlocked),
                'needs_review' => count($queuePending) + count($connectorNeedsReview) + count($emailNeedsReview),
                'manual_exports' => count($channelExports) + count($distributionPosts) + count($emailRuns),
            ],
            'ready_to_execute' => [
                'execution_queue' => array_slice($queueReady, 0, 8),
                'launch_control' => array_slice($launchReady, 0, 8),
                'channel_exports' => array_slice($channelReady, 0, 8),
            ],
            'blocked' => [
                'execution_queue' => array_slice($queueBlocked, 0, 8),
                'launch' => array_slice($launchBlocked, 0, 8),
                'connectors' => array_slice($connectorBlocked, 0, 8),
            ],
            'needs_review' => [
                'execution_queue' => array_slice($queuePending, 0, 8),
                'connectors' => array_slice($connectorNeedsReview, 0, 8),
                'email_runs' => array_slice($emailNeedsReview, 0, 8),
                'connector_reviews' => $connectorReviews,
            ],
            'manual_exports' => [
                'distribution_posts' => array_slice($distributionPosts, 0, 8),
                'channel_exports' => array_slice($channelExports, 0, 8),
                'email_runs' => array_slice($emailRuns, 0, 8),
            ],
            'connectors' => [
                'summary' => $connectorReadiness,
                'diagnostics' => $this->getChannelConnectorDiagnostics(),
            ],
            'live_execution' => $liveReadiness,
            'next_actions' => array_slice($nextActions, 0, 6),
            'manual_first_boundary' => [
                'external_publish' => !empty($liveReadiness['policy']['live_execution_enabled']),
                'external_send' => !empty($liveReadiness['policy']['live_execution_enabled']),
                'external_api_call' => false,
                'live_execution_policy' => (string) ($liveReadiness['status'] ?? 'disabled'),
            ],
        ];
    }

    public function getCampaignExecutionConsole(int $campaignId, ?int $userId = null): array
    {
        $this->assertMarketingPermission('marketing.read');
        $campaignId = max(0, $campaignId);
        $workspace = $this->getMarketingCampaignWorkspace($campaignId);
        if (!$workspace) {
            throw new RuntimeException('Campaign was not found in the active workspace.');
        }

        $actionCenter = $this->getCampaignExecutionActionCenter($campaignId, $userId);
        $launchWorkspace = Database::tableExists('marketing_campaign_workspaces')
            ? $this->getCampaignLaunchWorkspaceV2Summary($campaignId)
            : [];
        $executionReadiness = Database::tableExists('marketing_campaign_workspaces')
            ? $this->getCampaignExecutionReadiness($campaignId)
            : [];
        $launchChecklists = Database::tableExists('marketing_campaign_launch_checklists')
            ? $this->listCampaignLaunchChecklists(['campaign_id' => $campaignId], 5, 0)
            : [];
        $exportPacks = Database::tableExists('marketing_operator_export_packs')
            ? $this->listOperatorExportPacks(['campaign_id' => $campaignId], 5, 0)
            : [];
        $decisions = Database::tableExists('marketing_decision_center_items')
            ? $this->listMarketingDecisions(['campaign_id' => $campaignId, 'open' => true], 6, 0)
            : [];
        $latestSnapshot = Database::tableExists('marketing_execution_action_snapshots')
            ? $this->getLatestCampaignExecutionActionSnapshot($campaignId)
            : null;
        $copilotRuns = Database::tableExists('marketing_campaign_copilot_runs')
            ? $this->listCampaignCopilotRuns(['campaign_id' => $campaignId], 5, 0)
            : [];
        $mediaProduction = Database::tableExists('marketing_media_production_work_items')
            ? $this->listMediaProductionWorkItems(['campaign_id' => $campaignId], 8, 0)
            : [];

        $counts = [
            'urgent_actions' => (int) ($actionCenter['counts']['urgent_actions'] ?? 0),
            'actions_total' => (int) ($actionCenter['counts']['actions_total'] ?? 0),
            'open_decisions' => count($decisions),
            'launch_checklists' => count($launchChecklists),
            'operator_export_packs' => count($exportPacks),
            'has_action_snapshot' => $latestSnapshot !== null ? 1 : 0,
            'copilot_runs' => count($copilotRuns),
            'media_production_work' => count($mediaProduction),
            'media_production_blocked' => count(array_filter($mediaProduction, static fn(array $item): bool => (string) ($item['status'] ?? '') === 'blocked')),
            'media_production_overdue' => count(array_filter($mediaProduction, static fn(array $item): bool => !empty($item['is_overdue']))),
        ];
        $status = match (true) {
            (string) ($actionCenter['status'] ?? '') === 'blocked' || $counts['urgent_actions'] > 0 => 'blocked',
            (string) ($actionCenter['status'] ?? '') === 'ready_for_manual_handoff' && $latestSnapshot !== null => 'ready_for_manual_handoff',
            default => 'needs_attention',
        };

        return [
            'campaign_id' => $campaignId,
            'campaign_name' => (string) ($workspace['campaign_name'] ?? ''),
            'status' => $status,
            'readiness_score' => (int) ($actionCenter['readiness_score'] ?? $launchWorkspace['readiness_score'] ?? 0),
            'workspace' => $workspace,
            'launch_workspace' => $launchWorkspace,
            'execution_readiness' => $executionReadiness,
            'action_center' => $actionCenter,
            'decisions' => $decisions,
            'launch_checklists' => $launchChecklists,
            'operator_export_packs' => $exportPacks,
            'latest_action_snapshot' => $latestSnapshot,
            'copilot_runs' => $copilotRuns,
            'media_production_work' => $mediaProduction,
            'counts' => $counts,
            'guardrails' => [
                'manual_first' => true,
                'external_publish' => false,
                'external_send' => false,
                'external_ads' => false,
                'message' => 'Campaign Execution Console coordinates manual launch work only. It does not send, publish, start ads, or call external channel APIs.',
            ],
        ];
    }

    public function runCampaignCopilot(int $campaignId, string $runType = 'readiness_summary', ?int $userId = null): array
    {
        $this->assertMarketingPermission('marketing.write');
        if (!Database::tableExists('marketing_campaign_copilot_runs')) {
            throw new RuntimeException('Marketing campaign copilot runs are unavailable.');
        }

        $runType = $this->normalizeEnum($runType, self::CAMPAIGN_COPILOT_RUN_TYPES, 'campaign_copilot_run_type');
        $userId = $userId ?? $this->currentUserId();
        if (($userId ?? 0) > 0) {
            $this->assertWorkspaceUser((int) $userId, $this->workspaceId());
        }

        $console = $this->getCampaignExecutionConsole($campaignId, $userId);
        $result = $this->buildCampaignCopilotResult($console, $runType);
        $promptContext = [
            'run_type' => $runType,
            'campaign_id' => (int) ($console['campaign_id'] ?? 0),
            'campaign_name' => (string) ($console['campaign_name'] ?? ''),
            'requested_at' => date('c'),
        ];
        $contextUsed = [
            'action_center_status' => (string) ($console['action_center']['status'] ?? ''),
            'readiness_score' => (int) ($console['readiness_score'] ?? 0),
            'urgent_actions' => (int) ($console['counts']['urgent_actions'] ?? 0),
            'open_decisions' => (int) ($console['counts']['open_decisions'] ?? 0),
            'launch_checklists' => (int) ($console['counts']['launch_checklists'] ?? 0),
            'operator_export_packs' => (int) ($console['counts']['operator_export_packs'] ?? 0),
            'media_production_work' => (int) ($console['counts']['media_production_work'] ?? 0),
            'media_production_blocked' => (int) ($console['counts']['media_production_blocked'] ?? 0),
            'has_action_snapshot' => (bool) ($console['counts']['has_action_snapshot'] ?? 0),
        ];

        Database::execute(
            "INSERT INTO marketing_campaign_copilot_runs
             (workspace_id, campaign_id, uuid, run_type, status, prompt_context_json, context_used_json, result_json, provider_metadata_json, created_by)
             VALUES (?, ?, ?, ?, 'completed', ?, ?, ?, ?, ?)",
            [
                $this->workspaceId(),
                (int) ($console['campaign_id'] ?? $campaignId),
                $this->generateUuid(),
                $runType,
                $this->normalizeJsonValue($this->sanitizeJsonCompatible($promptContext)),
                $this->normalizeJsonValue($this->sanitizeJsonCompatible($contextUsed)),
                $this->normalizeJsonValue($this->sanitizeJsonCompatible($result)),
                $this->normalizeJsonValue([
                    'provider' => 'deterministic_marketing_copilot',
                    'model' => 'manual_first_fallback',
                    'external_generation' => false,
                    'overwrites_records' => false,
                ]),
                ($userId ?? 0) > 0 ? (int) $userId : null,
            ]
        );
        $runId = (int) Database::lastInsertId();
        $this->captureMarketingAiContextSnapshot(
            'campaign_copilot',
            'campaign_copilot_' . $runType,
            [
                'prompt_inputs' => $promptContext,
                'context_bundle' => [
                    'blocks' => [
                        'campaign_execution_console' => $console,
                        'context_used' => $contextUsed,
                    ],
                    'bundle_quality' => [
                        'context_quality_score' => max(0, min(1, ((int) ($console['readiness_score'] ?? 0)) / 100)),
                        'missing_context_flags' => (array) ($console['action_center']['blockers'] ?? []),
                    ],
                ],
                'linked_records' => [
                    'campaign' => [
                        'id' => (int) ($console['campaign_id'] ?? $campaignId),
                        'name' => (string) ($console['campaign_name'] ?? ''),
                    ],
                ],
            ],
            [
                'provider' => 'deterministic_marketing_copilot',
                'model' => 'manual_first_fallback',
                'external_generation' => false,
                'overwrites_records' => false,
            ],
            [
                'campaign_copilot_run_id' => $runId,
                'campaign_id' => (int) ($console['campaign_id'] ?? $campaignId),
            ],
            ($userId ?? 0) > 0 ? (int) $userId : null
        );

        return $this->getCampaignCopilotRun($runId) ?? [];
    }

    public function listCampaignCopilotRuns(array $filters = [], int $limit = 100, int $offset = 0): array
    {
        $this->assertMarketingPermission('marketing.read');
        if (!Database::tableExists('marketing_campaign_copilot_runs')) {
            return [];
        }

        $limit = min(max($limit, 1), 250);
        $offset = max($offset, 0);
        $where = ['r.workspace_id = ?'];
        $params = [$this->workspaceId()];
        if (!empty($filters['id'])) {
            $where[] = 'r.id = ?';
            $params[] = (int) $filters['id'];
        }
        if (!empty($filters['campaign_id'])) {
            $where[] = 'r.campaign_id = ?';
            $params[] = (int) $filters['campaign_id'];
        }
        if (!empty($filters['run_type'])) {
            $where[] = 'r.run_type = ?';
            $params[] = $this->normalizeEnum((string) $filters['run_type'], self::CAMPAIGN_COPILOT_RUN_TYPES, 'campaign_copilot_run_type');
        }
        if (!empty($filters['status'])) {
            $where[] = 'r.status = ?';
            $params[] = $this->normalizeEnum((string) $filters['status'], self::CAMPAIGN_COPILOT_RUN_STATUSES, 'campaign_copilot_status');
        }

        $rows = Database::query(
            "SELECT r.*, c.name AS campaign_name, u.email AS created_by_email
             FROM marketing_campaign_copilot_runs r
             JOIN campaigns c ON c.id = r.campaign_id AND c.workspace_id = r.workspace_id
             LEFT JOIN users u ON u.id = r.created_by
             WHERE " . implode(' AND ', $where) . "
             ORDER BY r.created_at DESC, r.id DESC
             LIMIT {$limit} OFFSET {$offset}",
            $params
        );

        return array_map(fn(array $row): array => $this->hydrateCampaignCopilotRunRow($row), $rows);
    }

    public function getCampaignCopilotRun(int $id): ?array
    {
        $rows = $this->listCampaignCopilotRuns(['id' => $id], 1, 0);
        return $rows[0] ?? null;
    }

    public function runChannelConnectorTest(int $connectorId, array $input = []): array
    {
        $this->assertMarketingPermission('marketing.write');
        $connector = $this->getChannelConnector($connectorId);
        if (!$connector) {
            throw new RuntimeException('Marketing channel connector not found.');
        }
        if (!Database::tableExists('marketing_channel_connector_test_runs')) {
            throw new RuntimeException('Marketing channel connector tests are unavailable.');
        }

        $testMode = $this->normalizeEnum((string) ($input['test_mode'] ?? 'diagnostics'), self::CHANNEL_CONNECTOR_TEST_MODES, 'connector_test_mode');
        if ($testMode === 'live_preflight') {
            $this->assertMarketingPermission('marketing.manage');
        }
        $diagnostics = $testMode === 'live_preflight'
            ? $this->buildChannelConnectorLivePreflight($connector, $input)
            : $this->buildChannelConnectorDiagnostics($connector, $input);
        $status = $diagnostics['ready_for_test'] ? 'passed' : 'blocked';
        $result = [
            'connector_id' => (int) $connector['id'],
            'connector_type' => (string) $connector['connector_type'],
            'execution_mode' => (string) $connector['execution_mode'],
            'external_execution' => false,
            'dry_run_only' => true,
            'live_preflight_only' => $testMode === 'live_preflight',
            'external_api_called' => false,
            'third_party_delivery' => false,
            'live_preflight_blockers' => (array) ($diagnostics['live_preflight_blockers'] ?? []),
            'message' => $diagnostics['ready_for_test']
                ? ($testMode === 'live_preflight'
                    ? 'Connector live preflight passed. No external API call, send, publish, or delivery was made.'
                    : 'Connector framework diagnostics passed in dry-run mode. No external API call was made.')
                : ($testMode === 'live_preflight'
                    ? 'Connector live preflight is blocked until policy, setup readiness, secret reference, adapter, and dry-run evidence are ready.'
                    : 'Connector is blocked until required capabilities and safe configuration are completed.'),
        ];

        Database::execute(
            "INSERT INTO marketing_channel_connector_test_runs
             (workspace_id, connector_id, uuid, status, test_mode, input_json, result_json, diagnostics_json, started_at, completed_at, created_by)
             VALUES (?, ?, ?, ?, ?, ?, ?, ?, NOW(), NOW(), ?)",
            [
                $this->workspaceId(),
                (int) $connector['id'],
                $this->generateUuid(),
                $status,
                $testMode,
                $this->normalizeJsonValue($this->sanitizeVisibleConnectorPayload($input)),
                $this->normalizeJsonValue($result),
                $this->normalizeJsonValue($diagnostics),
                (int) ($input['created_by'] ?? $this->currentUserId()) ?: null,
            ]
        );
        $testId = (int) Database::lastInsertId();
        if ($testMode === 'live_preflight') {
            Database::execute(
                "UPDATE marketing_channel_connectors
                 SET diagnostics_json = ?,
                     last_tested_at = NOW(),
                     last_live_check_at = NOW(),
                     live_preflight_status = ?,
                     live_preflight_checked_at = NOW(),
                     live_preflight_json = ?,
                     status = CASE WHEN status <> 'archived' AND ? = 'passed' THEN 'ready' ELSE status END
                 WHERE workspace_id = ? AND id = ?",
                [
                    $this->normalizeJsonValue($diagnostics),
                    $status,
                    $this->normalizeJsonValue($diagnostics),
                    $status,
                    $this->workspaceId(),
                    (int) $connector['id'],
                ]
            );
        } else {
            Database::execute(
                "UPDATE marketing_channel_connectors
                 SET diagnostics_json = ?, last_tested_at = NOW(), status = CASE WHEN status <> 'archived' THEN ? ELSE status END
                 WHERE workspace_id = ? AND id = ?",
                [
                    $this->normalizeJsonValue($diagnostics),
                    $diagnostics['ready_for_test'] ? 'ready' : 'blocked',
                    $this->workspaceId(),
                    (int) $connector['id'],
                ]
            );
        }

        return $this->listChannelConnectorTestRuns(['connector_id' => (int) $connector['id']], 1, 0)[0] ?? ['id' => $testId] + $result;
    }

    public function getChannelConnectorDiagnostics(): array
    {
        $connectors = $this->listChannelConnectors([], 250, 0);
        $policy = $this->getMarketingLiveExecutionPolicy();
        $setupCounts = array_fill_keys(self::CHANNEL_CONNECTOR_SETUP_STATUSES, 0);
        $livePreflightCounts = array_fill_keys(self::CHANNEL_CONNECTOR_LIVE_PREFLIGHT_STATUSES, 0);
        $readinessScoreTotal = 0;
        $byType = [];
        foreach (self::CHANNEL_CONNECTOR_TYPES as $type) {
            $byType[$type] = [
                'total' => 0,
                'ready' => 0,
                'configured' => 0,
                'blocked' => 0,
            ];
        }
        foreach ($connectors as $connector) {
            $type = (string) ($connector['connector_type'] ?? 'other');
            if (!isset($byType[$type])) {
                $byType[$type] = ['total' => 0, 'ready' => 0, 'configured' => 0, 'blocked' => 0];
            }
            $byType[$type]['total']++;
            $status = (string) ($connector['status'] ?? 'draft');
            if (isset($byType[$type][$status])) {
                $byType[$type][$status]++;
            }
            $setupStatus = (string) ($connector['setup_status'] ?? 'not_started');
            if (isset($setupCounts[$setupStatus])) {
                $setupCounts[$setupStatus]++;
            }
            $preflightStatus = (string) ($connector['live_preflight_status'] ?? 'not_checked');
            if (isset($livePreflightCounts[$preflightStatus])) {
                $livePreflightCounts[$preflightStatus]++;
            }
            $readinessScoreTotal += (int) ($connector['readiness_score'] ?? 0);
        }

        return [
            'total_connectors' => count($connectors),
            'ready_connectors' => count(array_filter($connectors, static fn(array $connector): bool => (string) ($connector['status'] ?? '') === 'ready')),
            'blocked_connectors' => count(array_filter($connectors, static fn(array $connector): bool => (string) ($connector['status'] ?? '') === 'blocked')),
            'setup_ready_connectors' => $setupCounts['ready'] ?? 0,
            'setup_blocked_connectors' => $setupCounts['blocked'] ?? 0,
            'setup_needs_review_connectors' => ($setupCounts['not_started'] ?? 0) + ($setupCounts['in_progress'] ?? 0),
            'average_readiness_score' => count($connectors) > 0 ? (int) round($readinessScoreTotal / count($connectors)) : 0,
            'by_setup_status' => $setupCounts,
            'by_type' => $byType,
            'live_execution_enabled' => !empty($policy['live_execution_enabled']),
            'live_policy_status' => (string) ($policy['status'] ?? 'disabled'),
            'live_enabled_connectors' => count(array_filter($connectors, static fn(array $connector): bool => !empty($connector['live_enabled']))),
            'live_verified_connectors' => count(array_filter($connectors, static fn(array $connector): bool => !empty($connector['live_enabled']) && (string) ($connector['secret_status'] ?? '') === 'verified')),
            'live_preflight_passed_connectors' => $livePreflightCounts['passed'] ?? 0,
            'live_preflight_blocked_connectors' => $livePreflightCounts['blocked'] ?? 0,
            'live_preflight_not_checked_connectors' => $livePreflightCounts['not_checked'] ?? 0,
            'by_live_preflight_status' => $livePreflightCounts,
            'secret_safe' => true,
        ];
    }

    public function getMarketingLiveExecutionPolicy(): array
    {
        $defaults = $this->defaultMarketingLiveExecutionPolicy();
        if (!Database::tableExists('marketing_live_execution_policies')) {
            return $defaults + ['table_available' => false];
        }

        $row = Database::queryOne(
            "SELECT * FROM marketing_live_execution_policies WHERE workspace_id = ? LIMIT 1",
            [$this->workspaceId()]
        );
        if (!$row) {
            return $defaults + ['table_available' => true];
        }

        $policy = $this->hydrateJsonFields($row, ['allowed_connector_types_json', 'allowed_adapter_keys_json', 'safety_checklist_json', 'metadata_json']);
        $policy['live_execution_enabled'] = !empty($policy['live_execution_enabled']);
        $policy['require_manage_approval'] = !empty($policy['require_manage_approval']);
        $policy['emergency_paused'] = !empty($policy['emergency_paused']);
        $policy['table_available'] = true;

        return $policy;
    }

    public function pauseMarketingLiveExecution(int $userId, string $reason = ''): array
    {
        $this->assertMarketingPermission('marketing.manage');
        if (!Database::tableExists('marketing_live_execution_policies')) {
            throw new RuntimeException('Marketing live execution policies are unavailable.');
        }
        $actorId = $userId > 0 ? $userId : ($this->currentUserId() ?: null);
        $reason = mb_substr(Security::sanitizeInput(trim($reason) !== '' ? $reason : 'Emergency stop activated by marketing operator.', 'string'), 0, 1000);
        $this->ensureMarketingLiveExecutionPolicyExists($actorId);

        Database::execute(
            "UPDATE marketing_live_execution_policies
             SET emergency_paused = 1,
                 emergency_paused_at = NOW(),
                 emergency_paused_by = ?,
                 emergency_pause_reason = ?,
                 emergency_resumed_at = NULL,
                 emergency_resumed_by = NULL,
                 updated_by = ?
             WHERE workspace_id = ?",
            [$actorId, $reason, $actorId, $this->workspaceId()]
        );

        $policy = $this->getMarketingLiveExecutionPolicy();
        $this->recordLiveExecutionEvent('policy_updated', 'blocked', [
            'payload' => [
                'emergency_paused' => true,
                'emergency_pause_reason' => $reason,
                'live_execution_enabled' => !empty($policy['live_execution_enabled']),
            ],
            'created_by' => $actorId,
        ]);

        return $policy;
    }

    public function resumeMarketingLiveExecution(int $userId): array
    {
        $this->assertMarketingPermission('marketing.manage');
        if (!Database::tableExists('marketing_live_execution_policies')) {
            throw new RuntimeException('Marketing live execution policies are unavailable.');
        }
        $actorId = $userId > 0 ? $userId : ($this->currentUserId() ?: null);
        $this->ensureMarketingLiveExecutionPolicyExists($actorId);

        Database::execute(
            "UPDATE marketing_live_execution_policies
             SET emergency_paused = 0,
                 emergency_resumed_at = NOW(),
                 emergency_resumed_by = ?,
                 updated_by = ?
             WHERE workspace_id = ?",
            [$actorId, $actorId, $this->workspaceId()]
        );

        $policy = $this->getMarketingLiveExecutionPolicy();
        $this->recordLiveExecutionEvent('policy_updated', 'ready', [
            'payload' => [
                'emergency_paused' => false,
                'live_execution_enabled' => !empty($policy['live_execution_enabled']),
            ],
            'created_by' => $actorId,
        ]);

        return $policy;
    }

    public function updateMarketingLiveExecutionPolicy(array $data, ?int $userId = null): array
    {
        $this->assertMarketingPermission('marketing.manage');
        if (!Database::tableExists('marketing_live_execution_policies')) {
            throw new RuntimeException('Marketing live execution policies are unavailable.');
        }

        $normalized = $this->normalizeMarketingLiveExecutionPolicyData($data);
        $actorId = ($userId ?? $this->currentUserId()) ?: null;
        $existing = Database::queryOne(
            "SELECT id FROM marketing_live_execution_policies WHERE workspace_id = ? LIMIT 1",
            [$this->workspaceId()]
        );

        if ($existing) {
            Database::execute(
                "UPDATE marketing_live_execution_policies
                 SET status = ?, live_execution_enabled = ?, require_manage_approval = ?, allowed_connector_types_json = ?,
                     allowed_adapter_keys_json = ?, daily_live_cap = ?, safety_checklist_json = ?, metadata_json = ?, updated_by = ?
                 WHERE workspace_id = ? AND id = ?",
                [
                    $normalized['status'],
                    $normalized['live_execution_enabled'],
                    $normalized['require_manage_approval'],
                    $normalized['allowed_connector_types_json'],
                    $normalized['allowed_adapter_keys_json'],
                    $normalized['daily_live_cap'],
                    $normalized['safety_checklist_json'],
                    $normalized['metadata_json'],
                    $actorId,
                    $this->workspaceId(),
                    (int) $existing['id'],
                ]
            );
        } else {
            Database::execute(
                "INSERT INTO marketing_live_execution_policies
                 (workspace_id, uuid, status, live_execution_enabled, require_manage_approval, allowed_connector_types_json,
                  allowed_adapter_keys_json, daily_live_cap, safety_checklist_json, metadata_json, created_by, updated_by)
                 VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)",
                [
                    $this->workspaceId(),
                    $this->generateUuid(),
                    $normalized['status'],
                    $normalized['live_execution_enabled'],
                    $normalized['require_manage_approval'],
                    $normalized['allowed_connector_types_json'],
                    $normalized['allowed_adapter_keys_json'],
                    $normalized['daily_live_cap'],
                    $normalized['safety_checklist_json'],
                    $normalized['metadata_json'],
                    $actorId,
                    $actorId,
                ]
            );
        }

        $policy = $this->getMarketingLiveExecutionPolicy();
        $this->recordLiveExecutionEvent('policy_updated', 'info', [
            'payload' => [
                'status' => $policy['status'] ?? 'disabled',
                'live_execution_enabled' => !empty($policy['live_execution_enabled']),
                'allowed_connector_types' => (array) ($policy['allowed_connector_types_json'] ?? []),
                'allowed_adapter_keys' => (array) ($policy['allowed_adapter_keys_json'] ?? []),
            ],
            'created_by' => $actorId,
        ]);

        return $policy;
    }

    public function getMarketingLiveExecutionReadiness(?int $queueId = null): array
    {
        $this->assertMarketingPermission('marketing.read');
        $policy = $this->getMarketingLiveExecutionPolicy();
        $queues = $queueId !== null && $queueId > 0
            ? array_values(array_filter([$this->getExecutionQueueItem($queueId)]))
            : $this->listExecutionQueue([], 50, 0);
        $connectors = $this->listChannelConnectors([], 250, 0);
        $liveCapable = array_values(array_filter($connectors, static fn(array $connector): bool => !empty($connector['live_enabled'])));
        $verified = array_values(array_filter($liveCapable, static fn(array $connector): bool => (string) ($connector['secret_status'] ?? '') === 'verified'));
        $liveQueues = array_values(array_filter($queues, static fn(array $queue): bool => (string) ($queue['execution_mode'] ?? '') === 'live'));
        $scheduledRetries = array_values(array_filter($liveQueues, static fn(array $queue): bool => (string) ($queue['live_retry_status'] ?? 'none') === 'scheduled'));

        $queueReviews = [];
        foreach ($liveQueues as $queue) {
            $connector = !empty($queue['connector_id']) ? $this->getChannelConnector((int) $queue['connector_id']) : null;
            $approval = Database::tableExists('marketing_execution_approvals')
                ? Database::queryOne(
                    "SELECT * FROM marketing_execution_approvals WHERE workspace_id = ? AND queue_id = ? ORDER BY created_at DESC LIMIT 1",
                    [$this->workspaceId(), (int) $queue['id']]
                )
                : null;
            $queueReviews[] = [
                'queue_id' => (int) $queue['id'],
                'execution_type' => (string) ($queue['execution_type'] ?? 'other'),
                'status' => (string) ($queue['status'] ?? 'draft'),
                'connector_id' => (int) ($queue['connector_id'] ?? 0),
                'readiness' => $this->executionQueueReadiness($queue, $connector, $approval, 'live'),
            ];
        }

        $blockedQueues = array_values(array_filter($queueReviews, static fn(array $review): bool => empty($review['readiness']['ready'])));
        $readyQueues = array_values(array_filter($queueReviews, static fn(array $review): bool => !empty($review['readiness']['ready'])));
        $status = !empty($policy['live_execution_enabled']) && $readyQueues !== []
            ? 'live_ready'
            : (!empty($policy['live_execution_enabled']) ? 'test_only' : 'disabled');
        if ($blockedQueues !== [] && !empty($policy['live_execution_enabled'])) {
            $status = 'blocked';
        }
        if (!empty($policy['emergency_paused'])) {
            $status = 'blocked';
        }

        return [
            'status' => $status,
            'policy' => $this->liveExecutionPolicySnapshot($policy),
            'counts' => [
                'connectors' => count($connectors),
                'live_capable_connectors' => count($liveCapable),
                'verified_live_connectors' => count($verified),
                'live_queue_items' => count($liveQueues),
                'ready_live_queue_items' => count($readyQueues),
                'blocked_live_queue_items' => count($blockedQueues),
                'scheduled_live_retries' => count($scheduledRetries),
                'queued_live_email_handoffs_today' => $this->countMarketingLiveEmailHandoffsToday(),
            ],
            'ready_queue_items' => array_slice($readyQueues, 0, 8),
            'blocked_queue_items' => array_slice($blockedQueues, 0, 8),
            'guardrails' => [
                'requires_workspace_policy' => true,
                'requires_ready_connector' => true,
                'requires_verified_secret_reference' => true,
                'requires_connector_live_preflight' => true,
                'requires_explicit_approval' => true,
                'requires_final_live_confirmation' => true,
                'blocks_duplicate_successful_live_run' => true,
                'supports_global_emergency_stop' => true,
                'emergency_paused' => !empty($policy['emergency_paused']),
                'raw_secret_values_visible' => false,
            ],
        ];
    }

    public function getLiveConsentSuppressionReviewQueues(int $limit = 25): array
    {
        $this->assertMarketingPermission('marketing.read');
        if (!Database::tableExists('marketing_execution_queue')) {
            return [
                'missing_unsubscribe' => [],
                'suppression_blocked' => [],
                'whatsapp_template_blocked' => [],
                'consent_warnings' => [],
            ];
        }

        $limit = min(max($limit, 1), 100);
        $queues = array_values(array_filter(
            $this->listExecutionQueue([], 100, 0),
            static fn(array $queue): bool => (string) ($queue['execution_mode'] ?? '') === 'live'
        ));
        $groups = [
            'missing_unsubscribe' => [],
            'suppression_blocked' => [],
            'whatsapp_template_blocked' => [],
            'consent_warnings' => [],
        ];

        foreach ($queues as $queue) {
            $connector = !empty($queue['connector_id']) ? $this->getChannelConnector((int) $queue['connector_id']) : null;
            $approval = Database::tableExists('marketing_execution_approvals')
                ? Database::queryOne(
                    "SELECT * FROM marketing_execution_approvals WHERE workspace_id = ? AND queue_id = ? ORDER BY created_at DESC LIMIT 1",
                    [$this->workspaceId(), (int) $queue['id']]
                )
                : null;
            $readiness = $this->executionQueueReadiness($queue, $connector, $approval, 'live');
            $reasons = (array) ($readiness['blocked_reasons'] ?? []);
            $warnings = (array) ($readiness['warnings'] ?? []);
            $summary = [
                'id' => (int) ($queue['id'] ?? 0),
                'execution_type' => (string) ($queue['execution_type'] ?? 'other'),
                'status' => (string) ($queue['status'] ?? 'draft'),
                'connector_name' => (string) ($queue['connector_name'] ?? ''),
                'blocked_reasons' => $reasons,
                'warnings' => $warnings,
                'consent_suppression' => (array) ($readiness['consent_suppression'] ?? []),
                'updated_at' => $queue['updated_at'] ?? null,
            ];
            if (in_array('email_unsubscribe_text_required', $reasons, true)) {
                $groups['missing_unsubscribe'][] = $summary;
            }
            if (array_filter($reasons, static fn(string $reason): bool => str_contains($reason, 'suppressed'))) {
                $groups['suppression_blocked'][] = $summary;
            }
            if (in_array('whatsapp_template_required_outside_24h_window', $reasons, true)) {
                $groups['whatsapp_template_blocked'][] = $summary;
            }
            if (array_filter($warnings, static fn(string $warning): bool => str_contains($warning, 'consent'))) {
                $groups['consent_warnings'][] = $summary;
            }
        }

        foreach ($groups as $key => $rows) {
            $groups[$key] = array_slice($rows, 0, $limit);
        }

        return $groups;
    }

    public function getMarketingLiveSetupWizard(?int $userId = null): array
    {
        $this->assertMarketingPermission('marketing.read');
        $policy = $this->getMarketingLiveExecutionPolicy();
        $readiness = $this->getMarketingLiveExecutionReadiness();
        $connectors = $this->listChannelConnectors([], 250, 0);
        $liveCapable = array_values(array_filter($connectors, static fn(array $connector): bool => !empty($connector['live_enabled'])));
        $secretSaved = array_values(array_filter($liveCapable, static fn(array $connector): bool => trim((string) ($connector['secret_reference'] ?? '')) !== ''));
        $secretVerified = array_values(array_filter($secretSaved, static fn(array $connector): bool => (string) ($connector['secret_status'] ?? '') === 'verified'));
        $preflightPassed = array_values(array_filter($secretVerified, static fn(array $connector): bool => (string) ($connector['live_preflight_status'] ?? 'not_checked') === 'passed'));
        $throttleConfigured = (int) ($policy['daily_live_cap'] ?? 0) > 0
            || count(array_filter($liveCapable, static fn(array $connector): bool => (int) ($connector['live_hourly_cap'] ?? 0) > 0 || (int) ($connector['live_daily_cap'] ?? 0) > 0 || (int) ($connector['live_cooldown_seconds'] ?? 0) > 0)) > 0;
        $approvedLiveQueues = Database::tableExists('marketing_execution_queue')
            ? (int) (Database::queryOne(
                "SELECT COUNT(*) AS count
                 FROM marketing_execution_queue
                 WHERE workspace_id = ?
                   AND execution_mode = 'live'
                   AND status IN ('approved','queued','succeeded')",
                [$this->workspaceId()]
            )['count'] ?? 0)
            : 0;
        $workerSchedule = $this->liveSetupWorkerScheduleSummary();
        $policyEnabled = !empty($policy['live_execution_enabled']) && (string) ($policy['status'] ?? 'disabled') === 'live_ready';

        $makeStep = function (string $key, string $label, bool $ready, string $href, string $readyMessage, string $missingMessage, array $evidence = [], bool $blocked = false): array {
            return [
                'key' => $key,
                'label' => $label,
                'status' => $ready ? 'ready' : ($blocked ? 'blocked' : 'missing'),
                'href' => $href,
                'message' => $ready ? $readyMessage : $missingMessage,
                'evidence' => $this->sanitizeJsonCompatible($evidence + ['secret_safe' => true, 'raw_secret_values_visible' => false]),
            ];
        };

        $steps = [
            $makeStep('policy_enabled', 'Enable live policy', $policyEnabled, 'marketing_channel_exports.php#live-policy', 'Live execution policy is enabled and marked live-ready.', 'A manager must enable live execution policy.', [
                'policy_status' => (string) ($policy['status'] ?? 'disabled'),
                'live_execution_enabled' => !empty($policy['live_execution_enabled']),
            ], !empty($policy['emergency_paused'])),
            $makeStep('connector_created', 'Create live connector', $liveCapable !== [], 'marketing_channel_exports.php#create-connector', 'At least one connector is marked live-capable.', 'Create or update a connector and mark it live-capable.', [
                'live_capable_connectors' => count($liveCapable),
            ]),
            $makeStep('secret_saved', 'Save secret reference', $secretSaved !== [], 'marketing_channel_exports.php', 'A live connector has a secret reference.', 'Save a secret reference for the live connector.', [
                'connectors_with_secret_reference' => count($secretSaved),
            ]),
            $makeStep('secret_verified', 'Verify connector secret', $secretVerified !== [], 'marketing_channel_exports.php', 'A live connector secret is verified.', 'Verify the connector secret before live execution.', [
                'verified_live_connectors' => count($secretVerified),
            ]),
            $makeStep('preflight_passed', 'Pass live preflight', $preflightPassed !== [], 'marketing_channel_exports.php', 'A live connector has passed live preflight.', 'Run live preflight for the connector.', [
                'preflight_passed_connectors' => count($preflightPassed),
            ]),
            $makeStep('throttle_configured', 'Configure throttle limits', $throttleConfigured, 'marketing_channel_exports.php#live-policy', 'Workspace or connector throttle limits are configured.', 'Set daily/hourly caps or cooldowns before live execution.', [
                'policy_daily_cap' => (int) ($policy['daily_live_cap'] ?? 0),
            ]),
            $makeStep('test_queue_item_approved', 'Approve a live queue item', $approvedLiveQueues > 0 || (int) ($readiness['counts']['ready_live_queue_items'] ?? 0) > 0, 'marketing_channel_exports.php#execution-queue', 'At least one live queue item has approval evidence.', 'Create a test live queue item and approve it.', [
                'approved_live_queue_items' => $approvedLiveQueues,
                'ready_live_queue_items' => (int) ($readiness['counts']['ready_live_queue_items'] ?? 0),
            ]),
            $makeStep('worker_schedule_confirmed', 'Confirm worker schedule', !empty($workerSchedule['confirmed']), 'marketing_execution.php#live-workers', 'A live worker schedule is active or confirmed.', 'Confirm the launcher/orchestrator worker schedule.', $workerSchedule),
        ];

        $readyCount = count(array_filter($steps, static fn(array $step): bool => (string) ($step['status'] ?? '') === 'ready'));
        $score = (int) round(($readyCount / max(count($steps), 1)) * 100);
        $status = $score >= 100 ? 'ready' : ($readyCount > 0 ? 'in_progress' : 'not_started');
        if (!empty($policy['emergency_paused'])) {
            $status = 'blocked';
        }
        $missing = array_values(array_filter($steps, static fn(array $step): bool => (string) ($step['status'] ?? '') !== 'ready'));
        $wizard = [
            'status' => $status,
            'score' => $score,
            'ready_count' => $readyCount,
            'total_steps' => count($steps),
            'steps' => $steps,
            'missing_steps' => $missing,
            'next_step' => $missing[0] ?? null,
            'readiness_status' => (string) ($readiness['status'] ?? 'disabled'),
            'secret_safe' => true,
            'raw_secret_values_visible' => false,
        ];
        $this->persistMarketingLiveSetupSteps($steps, $userId ?? $this->currentUserId());

        return $wizard;
    }

    private function persistMarketingLiveSetupSteps(array $steps, ?int $userId = null): void
    {
        if (!Database::tableExists('marketing_live_setup_steps')) {
            return;
        }
        $actorId = ($userId ?? 0) > 0 ? (int) $userId : null;
        foreach ($steps as $step) {
            Database::execute(
                "INSERT INTO marketing_live_setup_steps
                 (workspace_id, uuid, step_key, label, status, evidence_json, completed_at, completed_by, updated_by)
                 VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)
                 ON DUPLICATE KEY UPDATE
                    label = VALUES(label),
                    status = VALUES(status),
                    evidence_json = VALUES(evidence_json),
                    completed_at = IF(VALUES(status) = 'ready', COALESCE(marketing_live_setup_steps.completed_at, NOW()), NULL),
                    completed_by = IF(VALUES(status) = 'ready', COALESCE(marketing_live_setup_steps.completed_by, VALUES(completed_by)), NULL),
                    updated_by = VALUES(updated_by)",
                [
                    $this->workspaceId(),
                    $this->generateUuid(),
                    (string) $step['key'],
                    mb_substr(Security::sanitizeInput((string) $step['label'], 'string'), 0, 190),
                    $this->normalizeEnum((string) ($step['status'] ?? 'missing'), ['missing', 'ready', 'blocked', 'dismissed'], 'marketing_live_setup_step_status'),
                    $this->normalizeJsonValue($this->sanitizeJsonCompatible($step['evidence'] ?? [])),
                    (string) ($step['status'] ?? '') === 'ready' ? date('Y-m-d H:i:s') : null,
                    (string) ($step['status'] ?? '') === 'ready' ? $actorId : null,
                    $actorId,
                ]
            );
        }
    }

    private function liveSetupWorkerScheduleSummary(): array
    {
        if (!Database::tableExists('marketing_live_worker_schedules')) {
            return [
                'confirmed' => false,
                'worker_schedules' => 0,
                'active_schedules' => 0,
                'confirmed_schedules' => 0,
            ];
        }

        $summary = Database::queryOne(
            "SELECT COUNT(*) AS total_count,
                    SUM(status = 'active') AS active_count,
                    SUM(last_confirmed_at IS NOT NULL) AS confirmed_count
             FROM marketing_live_worker_schedules
             WHERE workspace_id = ?
               AND worker_key IN ('marketing_live_execution_launcher','marketing_live_orchestrator','marketing_live_dispatcher','marketing_live_email_handoffs','marketing_live_channel_handoffs','marketing_live_outcome_sync')",
            [$this->workspaceId()]
        ) ?: [];

        return [
            'confirmed' => (int) ($summary['active_count'] ?? 0) > 0 || (int) ($summary['confirmed_count'] ?? 0) > 0,
            'worker_schedules' => (int) ($summary['total_count'] ?? 0),
            'active_schedules' => (int) ($summary['active_count'] ?? 0),
            'confirmed_schedules' => (int) ($summary['confirmed_count'] ?? 0),
        ];
    }

    public function listLiveExecutionEvents(array $filters = [], int $limit = 100, int $offset = 0): array
    {
        if (!Database::tableExists('marketing_live_execution_events')) {
            return [];
        }
        $limit = min(max($limit, 1), 250);
        $offset = max($offset, 0);
        $workspace = $this->workspaceClause('lee.');
        $where = [$workspace['sql']];
        $params = $workspace['params'];
        foreach (['connector_id', 'queue_id'] as $field) {
            if (!empty($filters[$field])) {
                $where[] = 'lee.' . $field . ' = ?';
                $params[] = (int) $filters[$field];
            }
        }

        return array_map(
            fn(array $row): array => $this->hydrateJsonFields($row, ['payload_json', 'result_json', 'metadata_json']),
            Database::query(
                "SELECT lee.*, cc.name AS connector_name, creator.email AS created_by_email
                 FROM marketing_live_execution_events lee
                 LEFT JOIN marketing_channel_connectors cc ON cc.id = lee.connector_id AND cc.workspace_id = lee.workspace_id
                 LEFT JOIN users creator ON creator.id = lee.created_by
                 WHERE " . implode(' AND ', $where) . "
                 ORDER BY lee.created_at DESC, lee.id DESC
                 LIMIT {$limit} OFFSET {$offset}",
                $params
            )
        );
    }

    public function listLiveWebhookAttempts(array $filters = [], int $limit = 100, int $offset = 0): array
    {
        if (!Database::tableExists('marketing_live_webhook_attempts')) {
            return [];
        }

        $limit = min(max($limit, 1), 250);
        $offset = max($offset, 0);
        $workspace = $this->workspaceClause('lwa.');
        $where = [$workspace['sql']];
        $params = $workspace['params'];
        foreach (['queue_id', 'connector_id'] as $field) {
            if (!empty($filters[$field])) {
                $where[] = 'lwa.' . $field . ' = ?';
                $params[] = (int) $filters[$field];
            }
        }
        if (!empty($filters['status'])) {
            $where[] = 'lwa.status = ?';
