            )
        );
    }

    public function getLiveWebhookAttemptHealth(bool $persist = false, ?int $checkedBy = null): array
    {
        $this->assertMarketingPermission('marketing.read');
        $workerKey = 'marketing_live_outbound_webhooks';
        if (!Database::tableExists('marketing_live_webhook_attempts')) {
            return [
                'worker_key' => $workerKey,
                'status' => 'unknown',
                'message' => 'Marketing live webhook attempt table is unavailable.',
                'counts' => [
                    'queued' => 0,
                    'stale' => 0,
                    'recent_total' => 0,
                    'sent' => 0,
                    'failed' => 0,
                    'blocked' => 0,
                    'pending' => 0,
                    'external_api_called' => 0,
                ],
                'recommended_actions' => ['Run pending migrations before enabling live outbound webhooks.'],
                'secret_safe' => true,
                'external_api_called_by_health_check' => false,
                'third_party_delivery_by_health_check' => false,
            ];
        }

        $workspaceId = $this->workspaceId();
        $latestAttempt = Database::queryOne(
            "SELECT *
             FROM marketing_live_webhook_attempts
             WHERE workspace_id = ?
             ORDER BY attempted_at DESC, created_at DESC, id DESC
             LIMIT 1",
            [$workspaceId]
        ) ?: null;
        if ($latestAttempt) {
            $latestAttempt = $this->hydrateJsonFields($latestAttempt, ['request_headers_json', 'request_payload_json', 'metadata_json']);
        }
        $latestAge = null;
        if (!empty($latestAttempt['attempted_at'])) {
            $age = Database::queryOne('SELECT TIMESTAMPDIFF(MINUTE, ?, NOW()) AS age_minutes', [(string) $latestAttempt['attempted_at']]);
            $latestAge = (int) ($age['age_minutes'] ?? 0);
        }

        $recent = Database::queryOne(
            "SELECT COUNT(*) AS recent_total,
                    SUM(status = 'sent') AS sent_count,
                    SUM(status = 'failed') AS failed_count,
                    SUM(status = 'blocked') AS blocked_count,
                    SUM(status = 'pending') AS pending_count,
                    SUM(external_api_called = 1) AS external_api_called_count,
                    SUM(third_party_delivery = 1) AS third_party_delivery_count
             FROM marketing_live_webhook_attempts
             WHERE workspace_id = ?
               AND created_at >= DATE_SUB(NOW(), INTERVAL 24 HOUR)",
            [$workspaceId]
        ) ?: [];

        $due = ['due_count' => 0, 'oldest_due_age_minutes' => 0, 'stale_due_count' => 0];
        if (Database::tableExists('marketing_execution_queue') && Database::tableExists('marketing_channel_connectors')) {
            $due = Database::queryOne(
                "SELECT COUNT(*) AS due_count,
                        COALESCE(MAX(TIMESTAMPDIFF(MINUTE, COALESCE(eq.live_retry_after, eq.scheduled_at, eq.updated_at, eq.created_at), NOW())), 0) AS oldest_due_age_minutes,
                        SUM(TIMESTAMPDIFF(MINUTE, COALESCE(eq.live_retry_after, eq.scheduled_at, eq.updated_at, eq.created_at), NOW()) >= 30) AS stale_due_count
                 FROM marketing_execution_queue eq
                 JOIN marketing_channel_connectors cc ON cc.id = eq.connector_id AND cc.workspace_id = eq.workspace_id
                 WHERE eq.workspace_id = ?
                   AND eq.execution_mode = 'live'
                   AND eq.execution_type = 'website_webhook'
                   AND cc.live_adapter_key = 'crm_outbound_webhook'
                   AND eq.status IN ('approved', 'queued')
                   AND (eq.scheduled_at IS NULL OR eq.scheduled_at <= NOW())
                   AND (eq.live_retry_after IS NULL OR eq.live_retry_after <= NOW())",
                [$workspaceId]
            ) ?: $due;
        }

        $recentTotal = (int) ($recent['recent_total'] ?? 0);
        $sentCount = (int) ($recent['sent_count'] ?? 0);
        $failedCount = (int) ($recent['failed_count'] ?? 0);
        $blockedCount = (int) ($recent['blocked_count'] ?? 0);
        $pendingCount = (int) ($recent['pending_count'] ?? 0);
        $dueCount = (int) ($due['due_count'] ?? 0);
        $staleDueCount = (int) ($due['stale_due_count'] ?? 0);
        $oldestDueAge = (int) ($due['oldest_due_age_minutes'] ?? 0);
        $latestStatus = (string) ($latestAttempt['status'] ?? '');

        $status = 'healthy';
        $message = 'Outbound webhook live attempts are healthy.';
        if ($latestAttempt === null && $dueCount === 0) {
            $status = 'unknown';
            $message = 'No outbound webhook live attempt has been recorded yet.';
        }
        if ($dueCount > 0 && $latestAttempt === null) {
            $status = 'stale';
            $message = 'Outbound webhook live queue items are waiting, but no webhook attempt evidence exists yet.';
        }
        if ($staleDueCount > 0 || ($dueCount > 0 && $oldestDueAge >= 30)) {
            $status = 'stale';
            $message = 'Outbound webhook live queue items are older than the freshness threshold.';
        }
        if ($latestStatus === 'blocked') {
            $status = 'blocked';
            $message = 'The latest outbound webhook attempt was blocked by safety checks.';
        } elseif ($latestStatus === 'failed') {
            $status = 'attention';
            $message = 'The latest outbound webhook attempt failed and needs operator review.';
        } elseif ($failedCount > 0 || $blockedCount > 0) {
            $status = 'attention';
            $message = 'Recent outbound webhook attempts include blocked or failed evidence.';
        }
        if ((int) ($recent['third_party_delivery_count'] ?? 0) > 0) {
            $status = 'blocked';
            $message = 'Unexpected third-party delivery flag found in outbound webhook evidence.';
        }

        $recommendedActions = [];
        if ($dueCount > 0 && $status === 'stale') {
            $recommendedActions[] = 'Run the Marketing live execution launcher or live dispatcher to process due webhook queue items.';
        }
        if ($latestStatus === 'blocked' || $blockedCount > 0) {
            $recommendedActions[] = 'Review connector preflight blockers, allowed host configuration, and secret freshness before retrying.';
        }
        if ($latestStatus === 'failed' || $failedCount > 0) {
            $recommendedActions[] = 'Inspect the endpoint host, HTTP response preview, timeout, and retry settings for failed attempts.';
        }
        if ($pendingCount > 0) {
            $recommendedActions[] = 'Resolve pending webhook attempts before approving more live webhook queue items.';
        }
        if ($latestAttempt === null && $dueCount === 0) {
            $recommendedActions[] = 'Keep webhook connectors in dry-run and live-preflight until a real queue item is approved.';
        }
        if ($recommendedActions === []) {
            $recommendedActions[] = 'Continue monitoring webhook evidence, response previews, and queue freshness.';
        }

        $health = [
            'worker_key' => $workerKey,
            'status' => $status,
            'message' => $message,
            'stale_threshold_minutes' => 30,
            'last_run_id' => (int) ($latestAttempt['id'] ?? 0) ?: null,
            'last_run_at' => $latestAttempt['attempted_at'] ?? $latestAttempt['created_at'] ?? null,
            'last_run_status' => $latestStatus !== '' ? $latestStatus : null,
            'last_run_age_minutes' => $latestAge,
            'last_health_check_at' => null,
            'latest_attempt' => $latestAttempt ? [
                'id' => (int) ($latestAttempt['id'] ?? 0),
                'status' => $latestStatus,
                'http_method' => (string) ($latestAttempt['http_method'] ?? ''),
                'endpoint_host' => (string) ($latestAttempt['endpoint_host'] ?? ''),
                'endpoint_url_hash' => (string) ($latestAttempt['endpoint_url_hash'] ?? ''),
                'response_status_code' => $latestAttempt['response_status_code'] ?? null,
                'external_api_called' => !empty($latestAttempt['external_api_called']),
                'third_party_delivery' => !empty($latestAttempt['third_party_delivery']),
                'attempted_at' => $latestAttempt['attempted_at'] ?? null,
            ] : null,
            'counts' => [
                'queued' => $dueCount,
                'stale' => $staleDueCount,
                'oldest_due_age_minutes' => $oldestDueAge,
                'recent_total' => $recentTotal,
                'sent' => $sentCount,
                'failed' => $failedCount,
                'blocked' => $blockedCount,
                'pending' => $pendingCount,
                'external_api_called' => (int) ($recent['external_api_called_count'] ?? 0),
            ],
            'recommended_actions' => $recommendedActions,
            'secret_safe' => true,
            'endpoint_url_visible' => false,
            'external_api_called_by_health_check' => false,
            'third_party_delivery_by_health_check' => false,
        ];

        if ($persist && Database::tableExists('marketing_live_worker_health_checks')) {
            $this->recordLiveWorkerHealthCheck($health, $checkedBy);
            $health['last_health_check_at'] = date('Y-m-d H:i:s');
        }

        return $health;
    }

    public function listLiveEmailHandoffs(array $filters = [], int $limit = 100, int $offset = 0): array
    {
        if (!Database::tableExists('marketing_live_email_handoffs')) {
            return [];
        }
        $this->syncLiveEmailHandoffStatuses();
        $limit = min(max($limit, 1), 250);
        $offset = max($offset, 0);
        $workspace = $this->workspaceClause('leh.');
        $where = [$workspace['sql']];
        $params = $workspace['params'];
        foreach (['id', 'queue_id', 'email_run_id', 'connector_id', 'status', 'operator_status'] as $field) {
            if (!empty($filters[$field])) {
                $where[] = 'leh.' . $field . ' = ?';
                $params[] = in_array($field, ['status', 'operator_status'], true) ? (string) $filters[$field] : (int) $filters[$field];
            }
        }

        return array_map(
            fn(array $row): array => $this->hydrateJsonFields($row, ['metadata_json']),
            Database::query(
                "SELECT leh.*, er.name AS email_run_name, cc.name AS connector_name,
                        e.status AS email_status, e.sent_at AS email_sent_at, e.error_message AS email_error_message,
                        eq.status AS queue_status, eq.attempts AS queue_attempts, eq.max_attempts AS queue_max_attempts,
                        eq.scheduled_at AS queue_scheduled_at, eq.processed_at AS queue_processed_at,
                        controller.email AS controlled_by_email, creator.email AS created_by_email
                 FROM marketing_live_email_handoffs leh
                 LEFT JOIN marketing_email_campaign_runs er ON er.id = leh.email_run_id AND er.workspace_id = leh.workspace_id
                 LEFT JOIN marketing_channel_connectors cc ON cc.id = leh.connector_id AND cc.workspace_id = leh.workspace_id
                 LEFT JOIN emails e ON e.id = leh.email_id AND e.workspace_id = leh.workspace_id
                 LEFT JOIN email_queue eq ON eq.id = leh.email_queue_id AND eq.workspace_id = leh.workspace_id
                 LEFT JOIN users controller ON controller.id = leh.controlled_by
                 LEFT JOIN users creator ON creator.id = leh.created_by
                 WHERE " . implode(' AND ', $where) . "
                 ORDER BY leh.created_at DESC, leh.id DESC
                 LIMIT {$limit} OFFSET {$offset}",
                $params
            )
        );
    }

    public function getLiveEmailQueueMonitor(int $limit = 25): array
    {
        $this->assertMarketingPermission('marketing.read');
        $this->syncLiveEmailHandoffStatuses();
        $handoffs = $this->listLiveEmailHandoffs([], $limit, 0);
        $statusCounts = [];
        $operatorCounts = [];
        foreach ($handoffs as $handoff) {
            $status = (string) ($handoff['status'] ?? 'queued');
            $operatorStatus = (string) ($handoff['operator_status'] ?? 'queued');
            $statusCounts[$status] = ($statusCounts[$status] ?? 0) + 1;
            $operatorCounts[$operatorStatus] = ($operatorCounts[$operatorStatus] ?? 0) + 1;
        }

        return [
            'counts' => [
                'total' => count($handoffs),
                'by_status' => $statusCounts,
                'by_operator_status' => $operatorCounts,
                'queued_today' => $this->countMarketingLiveEmailHandoffsToday(),
            ],
            'handoffs' => $handoffs,
            'events' => $this->listLiveEmailHandoffEvents([], 12, 0),
            'worker_health' => $this->getLiveEmailWorkerHealth(false),
            'guardrails' => [
                'worker_suppression_recheck' => true,
                'operator_retry_requires_manage' => true,
                'operator_cancel_requires_manage' => true,
                'external_smtp_from_marketing_page' => false,
            ],
        ];
    }

    public function listLiveEmailHandoffEvents(array $filters = [], int $limit = 100, int $offset = 0): array
    {
        if (!Database::tableExists('marketing_live_email_handoff_events')) {
            return [];
        }
        $limit = min(max($limit, 1), 250);
        $offset = max($offset, 0);
        $workspace = $this->workspaceClause('e.');
        $where = [$workspace['sql']];
        $params = $workspace['params'];
        foreach (['handoff_id', 'queue_id', 'email_run_id', 'event_type'] as $field) {
            if (!empty($filters[$field])) {
                $where[] = 'e.' . $field . ' = ?';
                $params[] = $field === 'event_type' ? (string) $filters[$field] : (int) $filters[$field];
            }
        }

        return array_map(
            fn(array $row): array => $this->hydrateJsonFields($row, ['metadata_json']),
            Database::query(
                "SELECT e.*, creator.email AS created_by_email
                 FROM marketing_live_email_handoff_events e
                 LEFT JOIN users creator ON creator.id = e.created_by
                 WHERE " . implode(' AND ', $where) . "
                 ORDER BY e.created_at DESC, e.id DESC
                 LIMIT {$limit} OFFSET {$offset}",
                $params
            )
        );
    }

    public function getLiveEmailWorkerHealth(bool $persist = false, ?int $checkedBy = null): array
    {
        $this->assertMarketingPermission('marketing.read');
        $workspaceId = $this->workspaceId();
        $workerKey = 'marketing_live_email_handoffs';
        if (!Database::tableExists('marketing_live_email_worker_runs') || !Database::tableExists('marketing_live_email_handoffs')) {
            return [
                'worker_key' => $workerKey,
                'status' => 'unknown',
                'message' => 'Marketing live email worker tables are unavailable.',
                'counts' => ['queued' => 0, 'stale' => 0, 'blocked' => 0, 'failed' => 0],
                'recommended_actions' => ['Run pending migrations before enabling live email processing.'],
                'command' => 'php cli/process_marketing_live_email_handoffs.php all 25',
                'secret_safe' => true,
            ];
        }

        $schedule = $this->liveEmailWorkerScheduleSnapshot($workerKey);
        $throttle = $this->liveEmailWorkerThrottleSnapshot($schedule);
        $scheduleBlockers = $this->liveEmailWorkerScheduleBlockers($schedule, $throttle);
        $staleMinutes = (int) ($schedule['max_stale_minutes'] ?? 30);
        $queued = Database::queryOne(
            "SELECT COUNT(*) AS queued_count,
                    COALESCE(MAX(TIMESTAMPDIFF(MINUTE, leh.created_at, NOW())), 0) AS oldest_age_minutes
             FROM marketing_live_email_handoffs leh
             JOIN emails e ON e.id = leh.email_id AND e.workspace_id = leh.workspace_id
             JOIN email_queue eq ON eq.id = leh.email_queue_id AND eq.workspace_id = leh.workspace_id
             WHERE leh.workspace_id = ?
               AND leh.status = 'queued'
               AND e.status = 'pending'
               AND eq.status = 'pending'
               AND (eq.scheduled_at IS NULL OR eq.scheduled_at <= NOW())",
            [$workspaceId]
        ) ?: [];
        $stale = Database::queryOne(
            "SELECT COUNT(*) AS stale_count
             FROM marketing_live_email_handoffs leh
             JOIN emails e ON e.id = leh.email_id AND e.workspace_id = leh.workspace_id
             JOIN email_queue eq ON eq.id = leh.email_queue_id AND eq.workspace_id = leh.workspace_id
             WHERE leh.workspace_id = ?
               AND leh.status = 'queued'
               AND e.status = 'pending'
               AND eq.status = 'pending'
               AND (eq.scheduled_at IS NULL OR eq.scheduled_at <= NOW())
               AND TIMESTAMPDIFF(MINUTE, leh.created_at, NOW()) >= ?",
            [$workspaceId, $staleMinutes]
        ) ?: [];
        $blockedCount = (int) (Database::queryOne(
            "SELECT COUNT(*) AS count
             FROM marketing_live_email_handoffs
             WHERE workspace_id = ? AND status = 'blocked'",
            [$workspaceId]
        )['count'] ?? 0);
        $failedCount = (int) (Database::queryOne(
            "SELECT COUNT(*) AS count
             FROM marketing_live_email_handoffs
             WHERE workspace_id = ? AND status = 'failed'",
            [$workspaceId]
        )['count'] ?? 0);
        $latestRun = Database::queryOne(
            "SELECT *
             FROM marketing_live_email_worker_runs
             WHERE workspace_id = ?
             ORDER BY started_at DESC, id DESC
             LIMIT 1",
            [$workspaceId]
        ) ?: null;
        $latestHealth = Database::tableExists('marketing_live_worker_health_checks')
            ? (Database::queryOne(
                "SELECT *
                 FROM marketing_live_worker_health_checks
                 WHERE workspace_id = ? AND worker_key = ?
                 LIMIT 1",
                [$workspaceId, $workerKey]
            ) ?: null)
            : null;
        $lease = $this->liveEmailWorkerLeaseSnapshot($workerKey);

        $queuedCount = (int) ($queued['queued_count'] ?? 0);
        $staleCount = (int) ($stale['stale_count'] ?? 0);
        $oldestAge = (int) ($queued['oldest_age_minutes'] ?? 0);
        $latestRunStatus = (string) ($latestRun['status'] ?? '');
        $latestRunAge = null;
        if (!empty($latestRun['started_at'])) {
            $ageRow = Database::queryOne('SELECT TIMESTAMPDIFF(MINUTE, ?, NOW()) AS age_minutes', [(string) $latestRun['started_at']]);
            $latestRunAge = (int) ($ageRow['age_minutes'] ?? 0);
        }

        $status = 'healthy';
        $message = 'Marketing live email worker is healthy.';
        if ($latestRun === null && $queuedCount === 0) {
            $status = 'unknown';
            $message = 'No Marketing live email worker run has been recorded yet.';
        }
        if (!empty($schedule['emergency_paused'])) {
            $status = 'blocked';
            $message = 'Marketing live email worker is emergency paused.';
        } elseif (in_array((string) ($schedule['status'] ?? ''), ['paused', 'disabled'], true) && $queuedCount > 0) {
            $status = 'blocked';
            $message = 'Marketing live email worker schedule is paused or disabled while handoffs are queued.';
        }
        if ($status !== 'blocked' && (string) ($schedule['status'] ?? 'planned') === 'disabled' && $queuedCount > 0) {
            $status = 'stale';
            $message = 'Marketing live email worker schedule is disabled while handoffs are queued.';
        }
        if ($scheduleBlockers !== [] && ($queuedCount > 0 || !empty($schedule['emergency_paused']))) {
            $status = 'blocked';
            $message = 'Marketing live email worker is paused or throttled.';
        }
        if ($scheduleBlockers === [] && !empty($lease['active'])) {
            $status = 'healthy';
            $message = 'Marketing live email worker lease is active and fresh.';
        } elseif ((string) ($lease['status'] ?? '') === 'expired') {
            $status = 'stale';
            $message = 'Marketing live email worker lease has expired without a clean release.';
        } elseif (!empty($schedule['stale'])) {
            $status = 'stale';
            $message = 'Marketing live email worker has missed its configured schedule window.';
        }
        if ($latestRunStatus === 'failed' || $latestRunStatus === 'blocked') {
            $status = 'blocked';
            $message = 'The latest Marketing live email worker run ended blocked or failed.';
        } elseif (
            empty($lease['active'])
            && ($staleCount > 0 || ($queuedCount > 0 && $latestRun === null) || ($queuedCount > 0 && $latestRunAge !== null && $latestRunAge >= $staleMinutes))
        ) {
            $status = 'stale';
            $message = 'Queued Marketing live email handoffs are waiting longer than the freshness threshold.';
        } elseif ($blockedCount > 0 || $failedCount > 0 || $latestRunStatus === 'completed_with_errors') {
            $status = 'attention';
            $message = 'Marketing live email worker has blocked or failed evidence to review.';
        }

        $recommendedActions = [];
        if (in_array($status, ['unknown', 'stale'], true) && $queuedCount > 0) {
            $recommendedActions[] = 'Run or schedule: php cli/process_marketing_live_email_handoffs.php all 25';
        }
        if ($status === 'unknown' && $queuedCount === 0) {
            $recommendedActions[] = 'Keep the Marketing live email worker cron configured before enabling live campaigns.';
        }
        if ((string) ($schedule['status'] ?? 'planned') !== 'active') {
            $recommendedActions[] = 'Activate the Marketing live email worker schedule once cron is installed and verified.';
        }
        if (!empty($schedule['emergency_paused'])) {
            $recommendedActions[] = 'Resume the Marketing live email worker after the emergency pause is resolved.';
        }
        if (in_array('hourly_send_cap_reached', $scheduleBlockers, true) || in_array('daily_send_cap_reached', $scheduleBlockers, true)) {
            $recommendedActions[] = 'Wait for throttle capacity to reset or adjust live email send caps.';
        }
        if (in_array('send_gap_waiting', $scheduleBlockers, true)) {
            $recommendedActions[] = 'Wait for the configured send gap before running the worker again.';
        }
        if (!empty($lease['active'])) {
            $recommendedActions[] = 'A Marketing live email worker lease is active; do not start overlapping workers for this workspace.';
        } elseif ((string) ($lease['status'] ?? '') === 'expired') {
            $recommendedActions[] = 'Review the expired worker lease before starting a replacement worker.';
        }
        if ($blockedCount > 0) {
            $recommendedActions[] = 'Review blocked live email handoffs before retrying or re-queueing.';
        }
        if ($failedCount > 0 || $latestRunStatus === 'failed') {
            $recommendedActions[] = 'Inspect failed worker run evidence and SMTP/queue configuration.';
        }
        if ($recommendedActions === []) {
            $recommendedActions[] = 'Continue monitoring worker run freshness and blocked handoff counts.';
        }

        $health = [
            'worker_key' => $workerKey,
            'status' => $status,
            'message' => $message,
            'stale_threshold_minutes' => $staleMinutes,
            'last_run_id' => (int) ($latestRun['id'] ?? 0) ?: null,
            'last_run_at' => $latestRun['started_at'] ?? null,
            'last_run_status' => $latestRunStatus !== '' ? $latestRunStatus : null,
            'last_run_age_minutes' => $latestRunAge,
            'last_health_check_at' => $latestHealth['checked_at'] ?? null,
            'counts' => [
                'queued' => $queuedCount,
                'stale' => $staleCount,
                'blocked' => $blockedCount,
                'failed' => $failedCount,
                'oldest_queued_age_minutes' => $oldestAge,
            ],
            'lease' => $lease,
            'schedule' => $schedule,
            'throttle' => $throttle,
            'schedule_blockers' => $scheduleBlockers,
            'recommended_actions' => $recommendedActions,
            'command' => (string) ($schedule['command'] ?? 'php cli/process_marketing_live_email_handoffs.php all 25'),
            'secret_safe' => true,
            'external_smtp_from_page' => false,
        ];

        if ($persist && Database::tableExists('marketing_live_worker_health_checks')) {
            $this->recordLiveWorkerHealthCheck($health, $checkedBy);
            $health['last_health_check_at'] = date('Y-m-d H:i:s');
        }

        return $health;
    }

    public function getLiveQueueDispatcherHealth(bool $persist = false, ?int $checkedBy = null): array
    {
        $this->assertMarketingPermission('marketing.read');
        $workerKey = self::LIVE_QUEUE_DISPATCHER_WORKER_KEY;
        if (!Database::tableExists('marketing_live_queue_dispatch_runs') || !Database::tableExists('marketing_execution_queue')) {
            return [
                'worker_key' => $workerKey,
                'status' => 'unknown',
                'message' => 'Marketing live queue dispatcher tables are unavailable.',
                'counts' => ['due_confirmed' => 0, 'stale_confirmed' => 0, 'blocked' => 0, 'failed' => 0],
                'recommended_actions' => ['Run pending migrations before scheduling live queue dispatch.'],
                'command' => $this->liveQueueDispatcherCommand($this->workspaceId(), $this->currentUserId(), 10),
                'secret_safe' => true,
            ];
        }

        $schedule = $this->liveQueueDispatcherScheduleSnapshot();
        $lease = $this->liveEmailWorkerLeaseSnapshot($workerKey);
        $maxStale = max(1, (int) ($schedule['max_stale_minutes'] ?? 30));
        $due = Database::queryOne(
            "SELECT COUNT(*) AS due_count,
                    COALESCE(MAX(TIMESTAMPDIFF(MINUTE, COALESCE(live_retry_after, scheduled_at, live_dispatch_confirmed_at, updated_at), NOW())), 0) AS oldest_age_minutes
             FROM marketing_execution_queue
             WHERE workspace_id = ?
               AND execution_mode = 'live'
               AND live_dispatch_status = 'confirmed'
               AND status IN ('approved','queued')
               AND (scheduled_at IS NULL OR scheduled_at <= NOW())
               AND (live_retry_after IS NULL OR live_retry_after <= NOW())",
            [$this->workspaceId()]
        ) ?: [];
        $stale = Database::queryOne(
            "SELECT COUNT(*) AS stale_count
             FROM marketing_execution_queue
             WHERE workspace_id = ?
               AND execution_mode = 'live'
               AND live_dispatch_status = 'confirmed'
               AND status IN ('approved','queued')
               AND (scheduled_at IS NULL OR scheduled_at <= NOW())
               AND (live_retry_after IS NULL OR live_retry_after <= NOW())
               AND TIMESTAMPDIFF(MINUTE, COALESCE(live_retry_after, scheduled_at, live_dispatch_confirmed_at, updated_at), NOW()) >= ?",
            [$this->workspaceId(), $maxStale]
        ) ?: [];
        $scheduledRetryCount = Database::columnExists('marketing_execution_queue', 'live_retry_status')
            ? (int) (Database::queryOne(
                "SELECT COUNT(*) AS count
                 FROM marketing_execution_queue
                 WHERE workspace_id = ?
                   AND execution_mode = 'live'
                   AND live_retry_status = 'scheduled'
                   AND live_retry_after IS NOT NULL
                   AND live_retry_after > NOW()",
                [$this->workspaceId()]
            )['count'] ?? 0)
            : 0;
        $blockedCount = (int) (Database::queryOne(
            "SELECT COUNT(*) AS count
             FROM marketing_execution_queue
             WHERE workspace_id = ? AND execution_mode = 'live' AND live_dispatch_status = 'blocked'",
            [$this->workspaceId()]
        )['count'] ?? 0);
        $failedCount = (int) (Database::queryOne(
            "SELECT COUNT(*) AS count
             FROM marketing_execution_queue
             WHERE workspace_id = ? AND execution_mode = 'live' AND live_dispatch_status = 'failed'",
            [$this->workspaceId()]
        )['count'] ?? 0);
        $latestRun = Database::queryOne(
            "SELECT *
             FROM marketing_live_queue_dispatch_runs
             WHERE workspace_id = ?
             ORDER BY started_at DESC, id DESC
             LIMIT 1",
            [$this->workspaceId()]
        ) ?: null;

        $dueCount = (int) ($due['due_count'] ?? 0);
        $staleCount = (int) ($stale['stale_count'] ?? 0);
        $oldestAge = (int) ($due['oldest_age_minutes'] ?? 0);
        $latestRunStatus = (string) ($latestRun['status'] ?? '');
        $latestRunAge = null;
        if (!empty($latestRun['started_at'])) {
            $ageRow = Database::queryOne('SELECT TIMESTAMPDIFF(MINUTE, ?, NOW()) AS age_minutes', [(string) $latestRun['started_at']]);
            $latestRunAge = (int) ($ageRow['age_minutes'] ?? 0);
        }

        $status = 'healthy';
        $message = 'Marketing live queue dispatcher is healthy.';
        if ($latestRun === null && $dueCount === 0) {
            $status = 'unknown';
            $message = 'No Marketing live queue dispatcher run has been recorded yet.';
        }
        if (!empty($schedule['emergency_paused'])) {
            $status = 'blocked';
            $message = 'Marketing live queue dispatcher is emergency paused.';
        } elseif (!empty($lease['active']) && $dueCount > 0) {
            $status = 'attention';
            $message = 'A Marketing live queue dispatcher lease is active while confirmed live work is due.';
        } elseif (in_array((string) ($schedule['status'] ?? ''), ['paused', 'disabled'], true) && $dueCount > 0) {
            $status = 'blocked';
            $message = 'Marketing live queue dispatcher schedule is paused or disabled while confirmed live work is due.';
        } elseif ($latestRunStatus === 'failed' || $latestRunStatus === 'blocked') {
            $status = 'blocked';
            $message = 'The latest Marketing live queue dispatcher run ended blocked or failed.';
        } elseif (!empty($schedule['stale']) || $staleCount > 0 || ($dueCount > 0 && $latestRun === null) || ($dueCount > 0 && $latestRunAge !== null && $latestRunAge >= $maxStale)) {
            $status = 'stale';
            $message = 'Due confirmed live queue items are waiting longer than the freshness threshold.';
        } elseif ($blockedCount > 0 || $failedCount > 0 || $latestRunStatus === 'completed_with_errors') {
            $status = 'attention';
            $message = 'Marketing live queue dispatcher has blocked or failed evidence to review.';
        }

        $recommendedActions = [];
        if ((string) ($schedule['status'] ?? 'planned') !== 'active') {
            $recommendedActions[] = 'Activate the Marketing live queue dispatcher schedule once cron is installed and verified.';
        }
        if ($dueCount > 0 && in_array($status, ['unknown', 'stale'], true)) {
            $recommendedActions[] = 'Run or schedule: ' . (string) ($schedule['command'] ?? $this->liveQueueDispatcherCommand($this->workspaceId(), $this->currentUserId(), 10));
        }
        if (!empty($schedule['emergency_paused'])) {
            $recommendedActions[] = 'Resume the Marketing live queue dispatcher after the emergency pause is resolved.';
        }
        if (!empty($lease['active']) && $dueCount > 0) {
            $recommendedActions[] = 'Wait for the active dispatcher lease to finish or investigate a stuck dispatcher run.';
        }
        if ($blockedCount > 0) {
            $recommendedActions[] = 'Review blocked live dispatch queue items before retrying.';
        }
        if ($failedCount > 0 || $latestRunStatus === 'failed') {
            $recommendedActions[] = 'Inspect failed dispatcher run evidence and connector readiness.';
        }
        if ($recommendedActions === []) {
            $recommendedActions[] = 'Continue monitoring dispatcher run freshness and due confirmed queue counts.';
        }

        $health = [
            'worker_key' => $workerKey,
            'status' => $status,
            'message' => $message,
            'stale_threshold_minutes' => $maxStale,
            'last_dispatch_run_id' => (int) ($latestRun['id'] ?? 0) ?: null,
            'last_run_id' => null,
            'last_run_at' => $latestRun['started_at'] ?? null,
            'last_run_status' => $latestRunStatus !== '' ? $latestRunStatus : null,
            'last_run_age_minutes' => $latestRunAge,
            'counts' => [
                'due_confirmed' => $dueCount,
                'stale_confirmed' => $staleCount,
                'blocked' => $blockedCount,
                'failed' => $failedCount,
                'scheduled_retries' => $scheduledRetryCount,
                'oldest_due_age_minutes' => $oldestAge,
            ],
            'lease' => $lease,
            'schedule' => $schedule,
            'recommended_actions' => $recommendedActions,
            'command' => (string) ($schedule['command'] ?? $this->liveQueueDispatcherCommand($this->workspaceId(), $this->currentUserId(), 10)),
            'secret_safe' => true,
            'requires_preconfirmed_queue_items' => true,
        ];

        if ($persist && Database::tableExists('marketing_live_worker_health_checks')) {
            $this->recordLiveWorkerHealthCheck($health, $checkedBy);
            $health['last_health_check_at'] = date('Y-m-d H:i:s');
        }

        return $health;
    }

    public function recordLiveWorkerHealthCheck(array $health, ?int $checkedBy = null): void
    {
        if (!Database::tableExists('marketing_live_worker_health_checks')) {
            return;
        }
        $checkedBy = ($checkedBy ?? $this->currentUserId()) ?: null;
        Database::execute(
            "INSERT INTO marketing_live_worker_health_checks
             (workspace_id, uuid, worker_key, status, last_run_id, last_run_at, queued_count, stale_count,
              blocked_count, failed_count, diagnostics_json, recommended_actions_json, checked_by, checked_at)
             VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, NOW())
             ON DUPLICATE KEY UPDATE
                status = VALUES(status),
                last_run_id = VALUES(last_run_id),
                last_run_at = VALUES(last_run_at),
                queued_count = VALUES(queued_count),
                stale_count = VALUES(stale_count),
                blocked_count = VALUES(blocked_count),
                failed_count = VALUES(failed_count),
                diagnostics_json = VALUES(diagnostics_json),
                recommended_actions_json = VALUES(recommended_actions_json),
                checked_by = VALUES(checked_by),
                checked_at = NOW()",
            [
                $this->workspaceId(),
                $this->generateUuid(),
                (string) ($health['worker_key'] ?? 'marketing_live_email_handoffs'),
                $this->normalizeEnum((string) ($health['status'] ?? 'unknown'), ['healthy', 'attention', 'stale', 'blocked', 'unknown'], 'live_worker_health_status'),
                !empty($health['last_run_id']) ? (int) $health['last_run_id'] : null,
                !empty($health['last_run_at']) ? (string) $health['last_run_at'] : null,
                (int) ($health['counts']['queued'] ?? $health['counts']['due_confirmed'] ?? 0),
                (int) ($health['counts']['stale'] ?? $health['counts']['stale_confirmed'] ?? 0),
                (int) ($health['counts']['blocked'] ?? 0),
                (int) ($health['counts']['failed'] ?? 0),
                $this->normalizeJsonValue($this->sanitizeJsonCompatible($health)),
                $this->normalizeJsonValue($this->sanitizeJsonCompatible((array) ($health['recommended_actions'] ?? []))),
                $checkedBy,
            ]
        );
    }

    public function getMarketingLiveSchedulerValidation(bool $persist = false, ?int $checkedBy = null): array
    {
        $this->assertMarketingPermission('marketing.read');

        $components = [
            $this->liveSchedulerComponentFromHealth(
                'Marketing live execution launcher',
                $this->getLiveExecutionLauncherHealth(false, $checkedBy),
                $this->liveOrchestratorScheduleSnapshot()
            ),
            $this->liveSchedulerComponentFromSchedule(
                self::LIVE_ORCHESTRATOR_WORKER_KEY,
                'Marketing live orchestrator',
                $this->liveOrchestratorScheduleSnapshot(),
                'marketing_live_orchestration_runs'
            ),
            $this->liveSchedulerComponentFromHealth(
                'Marketing live queue dispatcher',
                $this->getLiveQueueDispatcherHealth(false, $checkedBy)
            ),
            $this->liveSchedulerComponentFromHealth(
                'Marketing live email worker',
                $this->getLiveEmailWorkerHealth(false, $checkedBy)
            ),
            $this->liveSchedulerComponentFromSchedule(
                self::LIVE_CHANNEL_WORKER_KEY,
                'Marketing live channel worker',
                $this->liveChannelWorkerScheduleSnapshot(),
                'marketing_live_channel_worker_runs'
            ),
            $this->liveSchedulerComponentFromHealth(
                'Marketing outbound webhook worker',
                $this->getLiveWebhookAttemptHealth(false, $checkedBy)
            ),
            $this->liveSchedulerComponentFromSchedule(
                self::LIVE_OUTCOME_SYNC_WORKER_KEY,
                'Marketing live outcome sync',
                $this->liveOutcomeSyncScheduleSnapshot(),
                'marketing_live_outcome_sync_runs'
            ),
        ];

        $counts = ['ready' => 0, 'action_needed' => 0, 'stale' => 0, 'blocked' => 0, 'unknown' => 0];
        foreach ($components as $component) {
            $status = (string) ($component['status'] ?? 'unknown');
            $counts[$status] = ($counts[$status] ?? 0) + 1;
        }

        $overallStatus = 'ready';
        if (($counts['blocked'] ?? 0) > 0) {
            $overallStatus = 'blocked';
        } elseif (($counts['stale'] ?? 0) > 0) {
            $overallStatus = 'stale';
        } elseif (($counts['action_needed'] ?? 0) > 0) {
            $overallStatus = 'action_needed';
        } elseif (($counts['unknown'] ?? 0) > 0) {
            $overallStatus = 'unknown';
        }

        $validation = [
            'status' => $overallStatus,
            'ready' => $overallStatus === 'ready',
            'components' => $components,
            'counts' => $counts,
            'message' => $overallStatus === 'ready'
                ? 'All Marketing live scheduler components have fresh evidence.'
                : 'Marketing live scheduler validation needs operator attention before production live execution.',
            'command_hints' => array_values(array_unique(array_filter(array_map(
                static fn(array $component): string => trim((string) ($component['command_hint'] ?? '')),
                $components
            )))),
            'secret_safe' => true,
            'raw_secret_values_visible' => false,
            'validated_at' => date('Y-m-d H:i:s'),
        ];

        if ($persist) {
            $this->persistMarketingLiveSchedulerValidation($components, $checkedBy);
        }

        return $validation;
    }

    private function liveSchedulerComponentFromHealth(string $label, array $health, ?array $fallbackSchedule = null): array
    {
        $workerKey = (string) ($health['worker_key'] ?? '');
        $schedule = (array) ($health['schedule'] ?? ($fallbackSchedule ?? []));
        $lease = (array) ($health['lease'] ?? []);
        if ($lease === [] && in_array($workerKey, [
            self::LIVE_ORCHESTRATOR_WORKER_KEY,
            self::LIVE_OUTCOME_SYNC_WORKER_KEY,
            self::LIVE_QUEUE_DISPATCHER_WORKER_KEY,
            self::LIVE_EMAIL_WORKER_KEY,
        ], true)) {
            $lease = $this->liveEmailWorkerLeaseSnapshot($workerKey);
        }

        return [
            'worker_key' => $workerKey !== '' ? $workerKey : strtolower(str_replace(' ', '_', $label)),
            'label' => $label,
            'status' => $this->liveSchedulerStatusFromHealthStatus((string) ($health['status'] ?? 'unknown')),
            'message' => (string) ($health['message'] ?? 'Scheduler component health is unavailable.'),
            'expected_schedule' => $this->liveSchedulerExpectedSchedule($schedule, (int) ($health['stale_threshold_minutes'] ?? 30)),
            'last_observed_run_at' => $health['last_run_at'] ?? null,
            'stale_threshold_minutes' => max(1, (int) ($health['stale_threshold_minutes'] ?? $schedule['max_stale_minutes'] ?? 30)),
            'lease_state' => $lease !== [] ? (string) ($lease['status'] ?? 'unknown') : 'not_applicable',
            'heartbeat_age_seconds' => isset($lease['heartbeat_age_seconds']) ? max(0, (int) $lease['heartbeat_age_seconds']) : null,
            'command_hint' => mb_substr((string) ($health['command'] ?? $schedule['command'] ?? ''), 0, 255),
            'recommended_action' => mb_substr((string) ((array) ($health['recommended_actions'] ?? []))[0] ?? 'Continue monitoring live scheduler evidence.', 0, 255),
            'evidence' => $this->sanitizeJsonCompatible([
                'source' => 'health_check',
                'health_status' => (string) ($health['status'] ?? 'unknown'),
                'last_run_status' => $health['last_run_status'] ?? null,
                'counts' => $health['counts'] ?? [],
                'schedule_status' => $schedule['status'] ?? null,
                'lease_active' => !empty($lease['active']),
                'secret_safe' => true,
                'raw_secret_values_visible' => false,
            ]),
        ];
    }

    private function liveSchedulerComponentFromSchedule(string $workerKey, string $label, array $schedule, string $runTable): array
    {
        $latestRun = $this->latestMarketingLiveWorkerRun($runTable);
        $lease = $workerKey === self::LIVE_CHANNEL_WORKER_KEY
            ? $this->liveChannelWorkerLeaseSnapshot()
            : $this->liveEmailWorkerLeaseSnapshot($workerKey);
        $maxStale = max(1, (int) ($schedule['max_stale_minutes'] ?? 30));
        $scheduleStatus = (string) ($schedule['status'] ?? 'planned');
        $latestRunStatus = (string) ($latestRun['status'] ?? '');
        $latestRunAge = isset($latestRun['age_minutes']) ? (int) $latestRun['age_minutes'] : null;

        $status = 'unknown';
        $message = $label . ' has not recorded worker evidence yet.';
        if (!Database::tableExists($runTable)) {
            $status = 'unknown';
            $message = $label . ' run table is unavailable.';
        } elseif (!empty($schedule['emergency_paused']) || in_array($scheduleStatus, ['paused', 'disabled'], true)) {
            $status = 'blocked';
            $message = $label . ' schedule is paused or disabled.';
        } elseif ($latestRun === null) {
            $status = $scheduleStatus === 'active' ? 'action_needed' : 'unknown';
            $message = $scheduleStatus === 'active'
                ? $label . ' is active but has not recorded a run yet.'
                : $label . ' schedule is not active yet.';
        } elseif (in_array($latestRunStatus, ['failed', 'blocked'], true)) {
            $status = 'blocked';
            $message = 'The latest ' . strtolower($label) . ' run ended blocked or failed.';
        } elseif ($latestRunStatus === 'completed_with_errors') {
            $status = 'action_needed';
            $message = 'The latest ' . strtolower($label) . ' run completed with errors.';
        } elseif ($latestRunAge !== null && $latestRunAge >= $maxStale) {
            $status = 'stale';
            $message = $label . ' has missed its configured freshness window.';
        } elseif ($scheduleStatus === 'active') {
            $status = 'ready';
            $message = $label . ' schedule and recent worker evidence are ready.';
        } else {
            $status = 'action_needed';
            $message = $label . ' has evidence, but the schedule is not active.';
        }

        if (!empty($lease['active']) && $status === 'ready') {
            $message = $label . ' has an active lease and fresh worker evidence.';
        }

        $recommendedAction = $status === 'ready'
            ? 'Continue monitoring worker freshness and lease evidence.'
            : 'Run or schedule: ' . (string) ($schedule['command'] ?? '');

        return [
            'worker_key' => $workerKey,
            'label' => $label,
            'status' => $status,
            'message' => $message,
            'expected_schedule' => $this->liveSchedulerExpectedSchedule($schedule, $maxStale),
            'last_observed_run_at' => $latestRun['started_at'] ?? null,
            'stale_threshold_minutes' => $maxStale,
            'lease_state' => (string) ($lease['status'] ?? 'not_acquired'),
            'heartbeat_age_seconds' => isset($lease['heartbeat_age_seconds']) ? max(0, (int) $lease['heartbeat_age_seconds']) : null,
            'command_hint' => mb_substr((string) ($schedule['command'] ?? ''), 0, 255),
            'recommended_action' => mb_substr($recommendedAction, 0, 255),
            'evidence' => $this->sanitizeJsonCompatible([
                'source' => 'worker_schedule',
                'run_table' => $runTable,
                'latest_run_id' => $latestRun['id'] ?? null,
                'latest_run_status' => $latestRunStatus !== '' ? $latestRunStatus : null,
                'latest_run_age_minutes' => $latestRunAge,
                'schedule_status' => $scheduleStatus,
                'lease_active' => !empty($lease['active']),
                'secret_safe' => true,
                'raw_secret_values_visible' => false,
            ]),
        ];
    }

    private function liveSchedulerStatusFromHealthStatus(string $status): string
    {
        return match ($status) {
            'healthy' => 'ready',
            'attention' => 'action_needed',
            'stale' => 'stale',
            'blocked' => 'blocked',
            default => 'unknown',
        };
    }

    private function liveSchedulerExpectedSchedule(array $schedule, int $defaultStaleMinutes): ?string
    {
        if ($schedule === []) {
            return null;
        }
        $interval = max(1, (int) ($schedule['expected_interval_minutes'] ?? 5));
        $stale = max(1, (int) ($schedule['max_stale_minutes'] ?? $defaultStaleMinutes));
        $status = (string) ($schedule['status'] ?? 'planned');

        return ucfirst($status) . ' every ' . $interval . ' minute(s); stale after ' . $stale . ' minute(s)';
    }

    private function latestMarketingLiveWorkerRun(string $table): ?array
    {
        if (!Database::tableExists($table)) {
            return null;
        }

        $row = Database::queryOne(
            "SELECT *,
                    TIMESTAMPDIFF(MINUTE, started_at, NOW()) AS age_minutes
             FROM {$table}
             WHERE workspace_id = ?
             ORDER BY started_at DESC, id DESC
             LIMIT 1",
            [$this->workspaceId()]
        );

        return $row ?: null;
    }

    private function persistMarketingLiveSchedulerValidation(array $components, ?int $actorId = null): void
    {
        if (!Database::tableExists('marketing_live_scheduler_validations')) {
            return;
        }

        $actorId = ($actorId ?? $this->currentUserId()) ?: null;
        foreach ($components as $component) {
            Database::execute(
                "INSERT INTO marketing_live_scheduler_validations
                 (workspace_id, uuid, worker_key, label, status, expected_schedule, last_observed_run_at,
                  stale_threshold_minutes, lease_state, heartbeat_age_seconds, command_hint, recommended_action,
                  evidence_json, validated_by, validated_at)
                 VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, NOW())
                 ON DUPLICATE KEY UPDATE
                    label = VALUES(label),
                    status = VALUES(status),
                    expected_schedule = VALUES(expected_schedule),
                    last_observed_run_at = VALUES(last_observed_run_at),
                    stale_threshold_minutes = VALUES(stale_threshold_minutes),
                    lease_state = VALUES(lease_state),
                    heartbeat_age_seconds = VALUES(heartbeat_age_seconds),
                    command_hint = VALUES(command_hint),
                    recommended_action = VALUES(recommended_action),
                    evidence_json = VALUES(evidence_json),
                    validated_by = VALUES(validated_by),
                    validated_at = NOW(),
                    updated_at = NOW()",
                [
                    $this->workspaceId(),
                    $this->generateUuid(),
                    mb_substr((string) ($component['worker_key'] ?? 'unknown'), 0, 120),
                    mb_substr((string) ($component['label'] ?? 'Marketing live scheduler'), 0, 160),
                    $this->normalizeEnum((string) ($component['status'] ?? 'unknown'), ['ready', 'action_needed', 'stale', 'blocked', 'unknown'], 'live_scheduler_validation_status'),
                    !empty($component['expected_schedule']) ? mb_substr((string) $component['expected_schedule'], 0, 190) : null,
                    !empty($component['last_observed_run_at']) ? (string) $component['last_observed_run_at'] : null,
                    max(1, (int) ($component['stale_threshold_minutes'] ?? 30)),
                    !empty($component['lease_state']) ? mb_substr((string) $component['lease_state'], 0, 80) : null,
                    isset($component['heartbeat_age_seconds']) ? max(0, (int) $component['heartbeat_age_seconds']) : null,
                    !empty($component['command_hint']) ? mb_substr((string) $component['command_hint'], 0, 255) : null,
                    !empty($component['recommended_action']) ? mb_substr((string) $component['recommended_action'], 0, 255) : null,
                    $this->normalizeJsonValue($this->sanitizeJsonCompatible((array) ($component['evidence'] ?? []))),
                    $actorId,
                ]
            );
        }
    }

