    public function updateLiveOrchestratorSchedule(array $data, int $actorId): array
    {
        $this->assertMarketingPermission('marketing.manage');
        if (!Database::tableExists('marketing_live_worker_schedules')) {
            throw new RuntimeException('Marketing live worker schedule table is unavailable.');
        }

        $actorId = $actorId > 0 ? $actorId : ($this->currentUserId() ?: 0);
        if ($actorId > 0) {
            $this->assertWorkspaceUser($actorId, $this->workspaceId());
        }
        $status = $this->normalizeEnum((string) ($data['status'] ?? 'planned'), self::LIVE_WORKER_SCHEDULE_STATUSES, 'live_orchestrator_schedule_status');
        $expectedInterval = min(max((int) ($data['expected_interval_minutes'] ?? 5), 1), 1440);
        $maxStale = min(max((int) ($data['max_stale_minutes'] ?? max(30, $expectedInterval * 3)), $expectedInterval), 1440);
        $maxPerRun = min(max((int) ($data['max_queue_items_per_run'] ?? $data['max_handoffs_per_run'] ?? 25), 1), 250);
        $command = trim((string) ($data['command'] ?? 'php cli/run_marketing_live_execution.php all ' . $maxPerRun . ' --source=cron'));
        if ($command === '') {
            $command = 'php cli/run_marketing_live_execution.php all ' . $maxPerRun . ' --source=cron';
        }
        $command = mb_substr(Security::sanitizeInput($command, 'string'), 0, 255);
        $label = $this->nullableSanitizedText($data['schedule_label'] ?? $data['label'] ?? 'Marketing live orchestrator');

        Database::execute(
            "INSERT INTO marketing_live_worker_schedules
             (workspace_id, uuid, worker_key, status, schedule_label, command, expected_interval_minutes,
              max_stale_minutes, max_handoffs_per_run, min_seconds_between_sends, hourly_send_cap, daily_send_cap,
              next_check_at, confirmed_by, metadata_json)
             VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, 0, 0, 0, DATE_ADD(NOW(), INTERVAL {$expectedInterval} MINUTE), ?, ?)
             ON DUPLICATE KEY UPDATE
                status = VALUES(status),
                schedule_label = VALUES(schedule_label),
                command = VALUES(command),
                expected_interval_minutes = VALUES(expected_interval_minutes),
                max_stale_minutes = VALUES(max_stale_minutes),
                max_handoffs_per_run = VALUES(max_handoffs_per_run),
                next_check_at = VALUES(next_check_at),
                confirmed_by = VALUES(confirmed_by),
                metadata_json = VALUES(metadata_json)",
            [
                $this->workspaceId(),
                $this->generateUuid(),
                self::LIVE_ORCHESTRATOR_WORKER_KEY,
                $status,
                $label,
                $command,
                $expectedInterval,
                $maxStale,
                $maxPerRun,
                $actorId > 0 ? $actorId : null,
                $this->normalizeJsonValue([
                    'source' => 'marketing_execution_page',
                    'worker_type' => 'live_orchestrator',
                    'max_queue_items_per_run' => $maxPerRun,
                    'coordinates_workers' => ['dispatcher', 'email_handoff_worker', 'outcome_sync'],
                    'raw_secret_values_visible' => false,
                ]),
            ]
        );

        return $this->getLiveOrchestratorSchedule();
    }

