    public function updateLiveEmailWorkerSchedule(array $data, int $actorId): array
    {
        $this->assertMarketingPermission('marketing.manage');
        if (!Database::tableExists('marketing_live_worker_schedules')) {
            throw new RuntimeException('Marketing live worker schedule table is unavailable.');
        }

        $workerKey = 'marketing_live_email_handoffs';
        $status = $this->normalizeEnum((string) ($data['status'] ?? 'planned'), self::LIVE_WORKER_SCHEDULE_STATUSES, 'live_worker_schedule_status');
        $expectedInterval = min(max((int) ($data['expected_interval_minutes'] ?? 5), 1), 1440);
        $maxStale = min(max((int) ($data['max_stale_minutes'] ?? max(30, $expectedInterval * 3)), $expectedInterval), 1440);
        $maxPerRun = min(max((int) ($data['max_handoffs_per_run'] ?? 25), 1), 200);
        $minSecondsBetweenSends = min(max((int) ($data['min_seconds_between_sends'] ?? 0), 0), 3600);
        $hourlySendCap = min(max((int) ($data['hourly_send_cap'] ?? 0), 0), 100000);
        $dailySendCap = min(max((int) ($data['daily_send_cap'] ?? 0), 0), 1000000);
        $command = trim((string) ($data['command'] ?? 'php cli/process_marketing_live_email_handoffs.php all 25'));
        if ($command === '') {
            $command = 'php cli/process_marketing_live_email_handoffs.php all 25';
        }
        $command = mb_substr(Security::sanitizeInput($command, 'string'), 0, 255);
        $label = $this->nullableSanitizedText($data['schedule_label'] ?? $data['label'] ?? null);

        Database::execute(
            "INSERT INTO marketing_live_worker_schedules
             (workspace_id, uuid, worker_key, status, schedule_label, command, expected_interval_minutes,
              max_stale_minutes, max_handoffs_per_run, min_seconds_between_sends, hourly_send_cap, daily_send_cap,
              next_check_at, confirmed_by, metadata_json)
             VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, DATE_ADD(NOW(), INTERVAL {$expectedInterval} MINUTE), ?, ?)
             ON DUPLICATE KEY UPDATE
                status = VALUES(status),
                schedule_label = VALUES(schedule_label),
                command = VALUES(command),
                expected_interval_minutes = VALUES(expected_interval_minutes),
                max_stale_minutes = VALUES(max_stale_minutes),
                max_handoffs_per_run = VALUES(max_handoffs_per_run),
                min_seconds_between_sends = VALUES(min_seconds_between_sends),
                hourly_send_cap = VALUES(hourly_send_cap),
                daily_send_cap = VALUES(daily_send_cap),
                next_check_at = VALUES(next_check_at),
                confirmed_by = VALUES(confirmed_by),
                metadata_json = VALUES(metadata_json)",
            [
                $this->workspaceId(),
                $this->generateUuid(),
                $workerKey,
                $status,
                $label,
                $command,
                $expectedInterval,
                $maxStale,
                $maxPerRun,
                $minSecondsBetweenSends,
                $hourlySendCap,
                $dailySendCap,
                $actorId > 0 ? $actorId : null,
                $this->normalizeJsonValue([
                    'source' => 'marketing_execution_page',
                    'throttle_controls' => [
                        'max_handoffs_per_run' => $maxPerRun,
                        'min_seconds_between_sends' => $minSecondsBetweenSends,
                        'hourly_send_cap' => $hourlySendCap,
                        'daily_send_cap' => $dailySendCap,
                    ],
                    'secret_safe' => true,
                    'raw_secret_values_visible' => false,
                ]),
            ]
        );

        return $this->getLiveEmailWorkerSchedule();
    }

