    public function processLiveEmailUnsubscribeToken(string $token, array $requestMeta = []): array
    {
        if (!Database::tableExists('marketing_live_email_unsubscribe_tokens') || !Database::tableExists('marketing_suppression_entries')) {
            return [
                'success' => false,
                'status' => 'unavailable',
                'message' => 'Marketing unsubscribe processing is unavailable.',
            ];
        }

        $token = trim($token);
        if ($token === '' || strlen($token) < 32) {
            $this->recordLiveEmailUnsubscribeEvent(null, null, 'token_invalid', 'failed', $requestMeta, ['reason' => 'missing_or_short_token']);

            return [
                'success' => false,
                'status' => 'invalid',
                'message' => 'This unsubscribe link is invalid.',
            ];
        }

        $tokenHash = hash('sha256', $token);
        $row = Database::queryOne(
            "SELECT *
             FROM marketing_live_email_unsubscribe_tokens
             WHERE token_hash = ?
             LIMIT 1",
            [$tokenHash]
        );
        if (!$row) {
            $this->recordLiveEmailUnsubscribeEvent(null, null, 'token_invalid', 'failed', $requestMeta, ['reason' => 'token_not_found']);

            return [
                'success' => false,
                'status' => 'invalid',
                'message' => 'This unsubscribe link is invalid or has already been removed.',
            ];
        }

        $workspaceId = (int) ($row['workspace_id'] ?? 0);
        if ($workspaceId <= 0) {
            return [
                'success' => false,
                'status' => 'invalid',
                'message' => 'This unsubscribe link is invalid.',
            ];
        }

        $previousRuntime = \CRM\Services\WorkspaceContext::runtimeSnapshot();
        \CRM\Services\WorkspaceContext::activateRuntimeWorkspace($workspaceId);
        try {
            $status = (string) ($row['status'] ?? 'active');
            $expiresAt = trim((string) ($row['expires_at'] ?? ''));
            if ($expiresAt !== '') {
                $expired = Database::queryOne('SELECT ? < NOW() AS expired', [$expiresAt]);
                if (!empty($expired['expired']) && $status === 'active') {
                    Database::execute(
                        "UPDATE marketing_live_email_unsubscribe_tokens SET status = 'expired' WHERE workspace_id = ? AND id = ?",
                        [$workspaceId, (int) $row['id']]
                    );
                    $row['status'] = 'expired';
                    $status = 'expired';
                }
            }

            if ($status === 'expired') {
                $this->recordLiveEmailUnsubscribeEvent($row, null, 'token_expired', 'blocked', $requestMeta);

                return [
                    'success' => false,
                    'status' => 'expired',
                    'message' => 'This unsubscribe link has expired. Please contact the sender to be removed.',
                    'recipient_email' => (string) ($row['recipient_email'] ?? ''),
                ];
            }

            if ($status === 'revoked') {
                $this->recordLiveEmailUnsubscribeEvent($row, null, 'token_invalid', 'blocked', $requestMeta, ['reason' => 'token_revoked']);

                return [
                    'success' => false,
                    'status' => 'revoked',
                    'message' => 'This unsubscribe link is no longer active.',
                    'recipient_email' => (string) ($row['recipient_email'] ?? ''),
                ];
            }

            $recipientEmail = strtolower(trim((string) ($row['recipient_email'] ?? '')));
            if (!filter_var($recipientEmail, FILTER_VALIDATE_EMAIL)) {
                $this->recordLiveEmailUnsubscribeEvent($row, null, 'token_invalid', 'failed', $requestMeta, ['reason' => 'recipient_invalid']);

                return [
                    'success' => false,
                    'status' => 'invalid',
                    'message' => 'This unsubscribe link is invalid.',
                ];
            }

            if ($status === 'active') {
                Database::execute(
                    "INSERT INTO marketing_suppression_entries
                     (workspace_id, uuid, channel, identifier, identifier_hash, reason, status, source, metadata_json, created_by)
                     VALUES (?, ?, 'email', ?, ?, ?, 'active', 'live_email_unsubscribe', ?, NULL)
                     ON DUPLICATE KEY UPDATE reason = VALUES(reason), status = 'active', source = VALUES(source), metadata_json = VALUES(metadata_json), updated_at = NOW()",
                    [
                        $workspaceId,
                        $this->generateUuid(),
                        $recipientEmail,
                        hash('sha256', 'email:' . $recipientEmail),
                        'Recipient unsubscribed from a live Marketing email.',
                        $this->normalizeJsonValue($this->sanitizeJsonCompatible([
                            'source' => 'marketing_live_email_unsubscribe',
                            'token_id' => (int) $row['id'],
                            'email_run_id' => !empty($row['email_run_id']) ? (int) $row['email_run_id'] : null,
                            'handoff_id' => !empty($row['handoff_id']) ? (int) $row['handoff_id'] : null,
                            'contact_id' => !empty($row['contact_id']) ? (int) $row['contact_id'] : null,
                        ])),
                    ]
                );
                Database::execute(
                    "UPDATE marketing_live_email_unsubscribe_tokens
                     SET status = 'used', used_at = NOW()
                     WHERE workspace_id = ? AND id = ?",
                    [$workspaceId, (int) $row['id']]
                );
                $this->recordLiveEmailUnsubscribeEvent($row, null, 'suppression_created', 'success', $requestMeta);
            } else {
                $this->recordLiveEmailUnsubscribeEvent($row, null, 'token_used', 'success', $requestMeta);
            }

            return [
                'success' => true,
                'status' => 'unsubscribed',
                'message' => 'You have been unsubscribed from future Marketing emails.',
                'recipient_email' => $recipientEmail,
            ];
        } finally {
            \CRM\Services\WorkspaceContext::restoreRuntimeWorkspace($previousRuntime);
        }
    }

    public function processLiveEmailHandoffWorker(array $options = []): array
    {
        if (!Database::tableExists('marketing_live_email_handoffs') || !Database::tableExists('marketing_live_email_worker_runs')) {
            throw new RuntimeException('Marketing live email worker tables are unavailable.');
        }

        $workerKey = 'marketing_live_email_handoffs';
        $requestedLimit = min(max((int) ($options['limit'] ?? 25), 1), 200);
        $schedule = $this->liveEmailWorkerScheduleSnapshot($workerKey);
        $throttle = $this->liveEmailWorkerThrottleSnapshot($schedule);
        $limit = min($requestedLimit, (int) ($schedule['max_handoffs_per_run'] ?? 25));
        if (($throttle['remaining_capacity'] ?? null) !== null) {
            $limit = min($limit, max(0, (int) $throttle['remaining_capacity']));
        }
        if ((int) ($schedule['min_seconds_between_sends'] ?? 0) > 0) {
            $limit = min($limit, 1);
        }
        $source = $this->normalizeEnum((string) ($options['source'] ?? 'cli'), self::LIVE_EMAIL_WORKER_RUN_SOURCES, 'live_email_worker_source');
        $requestedBy = (int) ($options['requested_by'] ?? $this->currentUserId());
        $requestedBy = $requestedBy > 0 ? $requestedBy : null;
        $workspaceId = $this->workspaceId();
        $leaseTtlSeconds = min(max((int) ($options['lease_ttl_seconds'] ?? 900), 60), 3600);
        $lease = null;
        $leaseAcquired = false;

        Database::execute(
            "INSERT INTO marketing_live_email_worker_runs
             (workspace_id, uuid, source, status, limit_count, requested_by, started_at)
             VALUES (?, ?, ?, 'running', ?, ?, NOW())",
            [$workspaceId, $this->generateUuid(), $source, $limit, $requestedBy]
        );
        $runId = (int) Database::lastInsertId();

        $summary = [
            'worker_run_id' => $runId,
            'workspace_id' => $workspaceId,
            'source' => $source,
            'limit' => $limit,
            'requested_limit' => $requestedLimit,
            'schedule' => $schedule,
            'throttle' => $throttle,
            'processed' => 0,
            'sent' => 0,
            'blocked' => 0,
            'failed' => 0,
            'skipped' => 0,
            'errors' => [],
            'handoffs' => [],
            'external_smtp_from_page' => false,
            'processed_by_worker' => true,
            'started_at' => date('c'),
        ];

        try {
            $scheduleBlockers = $this->liveEmailWorkerScheduleBlockers($schedule, $throttle);
            if ($scheduleBlockers !== []) {
                $message = 'Marketing live email worker is paused or throttled: ' . implode(', ', $scheduleBlockers);
                $summary['blocked']++;
                $summary['errors'][] = ['error' => $message, 'blockers' => $scheduleBlockers];
                $summary['completed_at'] = date('c');
                $this->completeLiveEmailWorkerRun($runId, 'blocked', $summary, $message);

                return $this->listLiveEmailWorkerRuns(['id' => $runId], 1, 0)[0] ?? $summary;
            }
            if ($limit <= 0) {
                $message = 'Marketing live email worker throttle capacity is exhausted.';
                $summary['blocked']++;
                $summary['errors'][] = ['error' => $message];
                $summary['completed_at'] = date('c');
                $this->completeLiveEmailWorkerRun($runId, 'blocked', $summary, $message);

                return $this->listLiveEmailWorkerRuns(['id' => $runId], 1, 0)[0] ?? $summary;
            }

            $lease = $this->acquireLiveEmailWorkerLease(
                $runId,
                $workerKey,
                $source,
                $leaseTtlSeconds,
                !empty($options['force_lease'])
            );
            $summary['lease'] = $lease;
            if (empty($lease['acquired'])) {
                $message = 'Another Marketing live email worker lease is active for this workspace.';
                $summary['blocked']++;
                $summary['errors'][] = [
                    'error' => $message,
                    'active_run_id' => $lease['active_run_id'] ?? null,
                    'expires_at' => $lease['expires_at'] ?? null,
                ];
                $summary['completed_at'] = date('c');
                $this->completeLiveEmailWorkerRun($runId, 'blocked', $summary, $message);

                return $this->listLiveEmailWorkerRuns(['id' => $runId], 1, 0)[0] ?? $summary;
            }
            $leaseAcquired = true;

            $policy = $this->getMarketingLiveExecutionPolicy();
            $handoffs = $this->eligibleLiveEmailHandoffsForWorker($limit);
            $emailService = new EmailService();

            foreach ($handoffs as $handoff) {
                $handoffId = (int) ($handoff['id'] ?? 0);
                $emailId = (int) ($handoff['email_id'] ?? 0);
                $emailQueueId = (int) ($handoff['email_queue_id'] ?? 0);
                if ($handoffId <= 0 || $emailId <= 0 || $emailQueueId <= 0) {
                    $summary['skipped']++;
                    continue;
                }
                $this->heartbeatLiveEmailWorkerLease($runId, (string) ($lease['lease_token'] ?? ''), $leaseTtlSeconds);

                $blockers = $this->liveEmailHandoffWorkerBlockers($handoff, $policy);
                if ($blockers !== []) {
                    $message = 'Live email worker blocked this handoff: ' . implode(', ', $blockers);
                    $this->updateLiveEmailHandoffControl($handoffId, 'blocked', 'blocked', 'pending', 'pending', $requestedBy ?? 0, $message);
                    Database::execute(
                        "UPDATE marketing_live_email_handoffs
                         SET worker_run_id = ?, error_message = ?
                         WHERE workspace_id = ? AND id = ?",
                        [$runId, $message, $workspaceId, $handoffId]
                    );
                    $this->recordLiveEmailHandoffEvent($handoffId, 'blocked', 'blocked', $message, ['blockers' => $blockers, 'worker_run_id' => $runId], $requestedBy);
                    $this->recordLiveEmailDeliveryProof($handoffId, $runId, [
                        'email_id' => $emailId,
                        'email_queue_id' => $emailQueueId,
                        'status' => 'blocked',
                        'smtp_method' => 'worker_preflight_block',
                        'error' => $message,
                        'blockers' => $blockers,
                    ], 'blocked', $message);
                    $summary['blocked']++;
                    $summary['handoffs'][] = ['handoff_id' => $handoffId, 'status' => 'blocked', 'blockers' => $blockers];
                    continue;
                }

                $claimed = Database::execute(
                    "UPDATE email_queue
                     SET status = 'processing', attempts = attempts + 1, error_message = NULL
                     WHERE workspace_id = ?
                       AND id = ?
                       AND status = 'pending'
                       AND (scheduled_at IS NULL OR scheduled_at <= NOW())",
                    [$workspaceId, $emailQueueId]
                );
                if ($claimed <= 0) {
                    $summary['skipped']++;
                    $this->recordLiveEmailDeliveryProof($handoffId, $runId, [
                        'email_id' => $emailId,
                        'email_queue_id' => $emailQueueId,
                        'status' => 'skipped',
                        'smtp_method' => 'queue_claim_guard',
                        'error' => 'Email queue row was not claimed by the Marketing live worker.',
                    ], 'skipped', 'Email queue row was not claimed by the Marketing live worker.');
                    $summary['handoffs'][] = ['handoff_id' => $handoffId, 'status' => 'skipped', 'reason' => 'queue_not_claimed'];
                    continue;
                }

                Database::execute(
                    "UPDATE marketing_live_email_handoffs
                     SET worker_run_id = ?, status = 'processing', operator_status = CASE WHEN operator_status = 'queued' THEN 'reviewed' ELSE operator_status END,
                         last_email_status = 'pending', last_queue_status = 'processing', last_checked_at = NOW()
                     WHERE workspace_id = ? AND id = ?",
                    [$runId, $workspaceId, $handoffId]
                );

                $summary['processed']++;
                $lastError = null;
                $deliveryResult = [];
                $sent = false;
                try {
                    $deliveryResult = $emailService->processEmailDetailed($emailId, $lastError, ['queue_claim_managed' => true], $workspaceId);
                    $sent = !empty($deliveryResult['success']);
                    if (!$sent && $lastError === null && !empty($deliveryResult['error'])) {
                        $lastError = (string) $deliveryResult['error'];
                    }
                } catch (Throwable $e) {
                    $sent = false;
                    $lastError = trim((string) $e->getMessage()) ?: 'Email worker failed.';
                    $deliveryResult = [
                        'success' => false,
                        'status' => 'failed',
                        'error' => $lastError,
                        'email_id' => $emailId,
                        'email_queue_id' => $emailQueueId,
                    ];
                    Database::execute(
                        "UPDATE emails SET status = 'failed', error_message = ? WHERE workspace_id = ? AND id = ?",
                        [$lastError, $workspaceId, $emailId]
                    );
                    Database::execute(
                        "UPDATE email_queue SET status = 'failed', error_message = ?, processed_at = NOW() WHERE workspace_id = ? AND id = ?",
                        [$lastError, $workspaceId, $emailQueueId]
                    );
                }

                $updated = $this->listLiveEmailHandoffs(['id' => $handoffId], 1, 0)[0] ?? [];
                $updatedStatus = (string) ($updated['status'] ?? ($sent ? 'sent' : 'failed'));
                $proofStatus = match ($updatedStatus) {
                    'sent' => (string) ($deliveryResult['smtp_method'] ?? '') === 'demo_simulation' ? 'simulated' : 'sent',
                    'blocked' => 'blocked',
                    'skipped' => 'skipped',
                    default => 'failed',
                };
                $this->recordLiveEmailDeliveryProof($handoffId, $runId, $deliveryResult + [
                    'email_id' => $emailId,
                    'email_queue_id' => $emailQueueId,
                ], $proofStatus, $lastError);
                if ($sent || $updatedStatus === 'sent') {
                    $summary['sent']++;
                } elseif ($updatedStatus === 'blocked') {
                    $summary['blocked']++;
                } else {
                    $summary['failed']++;
                    if ($lastError !== null && $lastError !== '') {
                        $summary['errors'][] = ['handoff_id' => $handoffId, 'error' => mb_substr($lastError, 0, 500)];
                    }
                }
                $summary['handoffs'][] = [
                    'handoff_id' => $handoffId,
                    'email_id' => $emailId,
                    'email_queue_id' => $emailQueueId,
                    'status' => $updatedStatus,
                    'error' => $lastError,
                ];
                $this->heartbeatLiveEmailWorkerLease($runId, (string) ($lease['lease_token'] ?? ''), $leaseTtlSeconds);
            }

            $status = $summary['processed'] === 0 && $summary['blocked'] > 0
                ? 'blocked'
                : (($summary['failed'] > 0 || $summary['blocked'] > 0) ? 'completed_with_errors' : 'completed');
            $summary['completed_at'] = date('c');
            $this->completeLiveEmailWorkerRun($runId, $status, $summary);

            return $this->listLiveEmailWorkerRuns(['id' => $runId], 1, 0)[0] ?? $summary;
        } catch (Throwable $e) {
            $summary['errors'][] = ['error' => mb_substr(trim((string) $e->getMessage()), 0, 500)];
            $summary['completed_at'] = date('c');
            $this->completeLiveEmailWorkerRun($runId, 'failed', $summary, $e->getMessage());
            throw $e;
        } finally {
            if ($leaseAcquired && is_array($lease)) {
                $this->releaseLiveEmailWorkerLease($runId, (string) ($lease['lease_token'] ?? ''), 'released');
                $this->markLiveEmailWorkerScheduleConfirmed('marketing_live_email_handoffs', $source, $requestedBy);
            }
        }
    }

    public function processLiveChannelHandoffWorker(array $options = []): array
    {
        if (!Database::tableExists('marketing_live_channel_handoffs') || !Database::tableExists('marketing_live_channel_worker_runs')) {
            throw new RuntimeException('Marketing live channel worker tables are unavailable.');
        }

        $requestedLimit = min(max((int) ($options['limit'] ?? 25), 1), 200);
        $schedule = $this->liveChannelWorkerScheduleSnapshot();
        $throttle = $this->liveChannelWorkerThrottleSnapshot($schedule);
        $limit = min($requestedLimit, (int) ($schedule['max_handoffs_per_run'] ?? 25));
        if (($throttle['remaining_capacity'] ?? null) !== null) {
            $limit = min($limit, max(0, (int) $throttle['remaining_capacity']));
        }
        if ((int) ($schedule['min_seconds_between_sends'] ?? 0) > 0) {
            $limit = min($limit, 1);
        }
        $source = $this->normalizeEnum((string) ($options['source'] ?? 'cli'), self::LIVE_EMAIL_WORKER_RUN_SOURCES, 'live_channel_worker_source');
        $requestedBy = (int) ($options['requested_by'] ?? $this->currentUserId());
        $requestedBy = $requestedBy > 0 ? $requestedBy : null;
        $workspaceId = $this->workspaceId();
        $leaseTtlSeconds = min(max((int) ($options['lease_ttl_seconds'] ?? 900), 60), 3600);
        $lease = null;
        $leaseAcquired = false;

        Database::execute(
            "INSERT INTO marketing_live_channel_worker_runs
             (workspace_id, uuid, source, status, limit_count, requested_by, started_at)
             VALUES (?, ?, ?, 'running', ?, ?, NOW())",
            [$workspaceId, $this->generateUuid(), $source, $limit, $requestedBy]
        );
        $runId = (int) Database::lastInsertId();

        $summary = [
            'worker_run_id' => $runId,
            'workspace_id' => $workspaceId,
            'source' => $source,
            'limit' => $limit,
            'requested_limit' => $requestedLimit,
            'schedule' => $schedule,
            'throttle' => $throttle,
            'processed' => 0,
            'sent' => 0,
            'blocked' => 0,
            'failed' => 0,
            'skipped' => 0,
            'errors' => [],
            'handoffs' => [],
            'processed_by_worker' => true,
            'external_api_called_by_page' => false,
            'raw_secret_values_visible' => false,
            'started_at' => date('c'),
        ];

        try {
            $scheduleBlockers = $this->liveChannelWorkerScheduleBlockers($schedule, $throttle, $source);
            if ($scheduleBlockers !== []) {
                $message = 'Marketing live channel worker is paused, inactive, or throttled: ' . implode(', ', $scheduleBlockers);
                $summary['blocked']++;
                $summary['errors'][] = ['error' => $message, 'blockers' => $scheduleBlockers];
                $summary['completed_at'] = date('c');
                $this->completeLiveChannelWorkerRun($runId, 'blocked', $summary, $message);

                return $this->listLiveChannelWorkerRuns(['id' => $runId], 1, 0)[0] ?? $summary;
            }
            if ($limit <= 0) {
                $message = 'Marketing live channel worker throttle capacity is exhausted.';
                $summary['blocked']++;
                $summary['errors'][] = ['error' => $message];
                $summary['completed_at'] = date('c');
                $this->completeLiveChannelWorkerRun($runId, 'blocked', $summary, $message);

                return $this->listLiveChannelWorkerRuns(['id' => $runId], 1, 0)[0] ?? $summary;
            }

            $lease = $this->acquireLiveChannelWorkerLease($runId, $source, $leaseTtlSeconds, !empty($options['force_lease']));
            $summary['lease'] = $lease;
            if (empty($lease['acquired'])) {
                $message = 'Another Marketing live channel worker lease is active for this workspace.';
                $summary['blocked']++;
                $summary['errors'][] = [
                    'error' => $message,
                    'active_run_id' => $lease['active_channel_worker_run_id'] ?? null,
                    'expires_at' => $lease['expires_at'] ?? null,
                ];
                $summary['completed_at'] = date('c');
                $this->completeLiveChannelWorkerRun($runId, 'blocked', $summary, $message);

                return $this->listLiveChannelWorkerRuns(['id' => $runId], 1, 0)[0] ?? $summary;
            }
            $leaseAcquired = true;

            $policy = $this->getMarketingLiveExecutionPolicy();
            $handoffs = $this->eligibleLiveChannelHandoffsForWorker($limit);
            $whatsAppProcessor = null;

            foreach ($handoffs as $handoff) {
                $handoffId = (int) ($handoff['id'] ?? 0);
                $executionType = (string) ($handoff['execution_type'] ?? '');
                $sourceQueueId = (int) ($handoff['source_queue_id'] ?? 0);
                if ($handoffId <= 0 || $sourceQueueId <= 0 || !in_array($executionType, ['sms', 'whatsapp'], true)) {
                    $summary['skipped']++;
                    continue;
                }

                $this->heartbeatLiveChannelWorkerLease($runId, (string) ($lease['lease_token'] ?? ''), $leaseTtlSeconds);
                $blockers = $this->liveChannelHandoffWorkerBlockers($handoff, $policy);
                if ($blockers !== []) {
                    $message = 'Live channel worker blocked this handoff: ' . implode(', ', $blockers);
                    $this->updateLiveChannelHandoffFromWorker($handoffId, $runId, 'blocked', $message);
                    $this->recordLiveChannelDeliveryProof($handoff, $executionType, [
                        'proof_status' => 'blocked',
                        'handoff_status' => 'blocked',
                        'worker_run_id' => $runId,
                        'error_message' => $message,
                        'blockers' => $blockers,
                        'proof_source' => 'marketing_live_channel_worker_preflight',
                        'external_api_called_by_worker' => false,
                        'raw_secret_values_visible' => false,
                    ]);
                    $summary['blocked']++;
                    $summary['handoffs'][] = ['handoff_id' => $handoffId, 'execution_type' => $executionType, 'status' => 'blocked', 'blockers' => $blockers];
                    continue;
                }

                Database::execute(
                    "UPDATE marketing_live_channel_handoffs
                     SET worker_run_id = ?, status = 'processing', updated_at = NOW()
                     WHERE workspace_id = ? AND id = ? AND status = 'queued'",
                    [$runId, $workspaceId, $handoffId]
                );

                $summary['processed']++;
                $lastError = null;
                $deliveryResult = [];
                try {
                    if ($executionType === 'sms') {
                        $deliveryResult = $this->processLiveSmsQueueItem($sourceQueueId, $workspaceId);
                    } else {
                        $whatsAppProcessor ??= new WhatsAppQueueProcessor();
                        $deliveryResult = $whatsAppProcessor->processQueueItem($sourceQueueId, $workspaceId);
                        $deliveryResult['success'] = (int) ($deliveryResult['sent'] ?? 0) > 0;
                        $deliveryResult['status'] = !empty($deliveryResult['success']) ? 'sent' : 'failed';
                        if (empty($deliveryResult['success']) && empty($deliveryResult['error']) && !empty($deliveryResult['errors'])) {
                            $deliveryResult['error'] = implode('; ', array_map('strval', (array) $deliveryResult['errors']));
                        }
                    }
                } catch (Throwable $e) {
                    $lastError = $this->sanitizeLiveProviderError((string) $e->getMessage());
                    $deliveryResult = [
                        'success' => false,
                        'status' => 'failed',
                        'error' => $lastError,
                    ];
                }

                $sync = $this->syncLiveChannelHandoffEvidenceForQueue(['id' => (int) ($handoff['queue_id'] ?? 0)], $executionType, $runId);
                $updated = Database::queryOne(
                    "SELECT status, error_message
                     FROM marketing_live_channel_handoffs
                     WHERE workspace_id = ? AND id = ?",
                    [$workspaceId, $handoffId]
                ) ?: [];
                $updatedStatus = (string) ($updated['status'] ?? (!empty($deliveryResult['success']) ? 'sent' : 'failed'));
                if ($updatedStatus === 'sent' || !empty($deliveryResult['success'])) {
                    $summary['sent']++;
                } elseif ($updatedStatus === 'blocked') {
                    $summary['blocked']++;
                } else {
                    $summary['failed']++;
                    $lastError = $lastError ?: $this->sanitizeLiveProviderError((string) ($deliveryResult['error'] ?? $updated['error_message'] ?? 'Channel worker failed.'));
                    $summary['errors'][] = ['handoff_id' => $handoffId, 'error' => mb_substr($lastError, 0, 500)];
                }
                $summary['handoffs'][] = [
                    'handoff_id' => $handoffId,
                    'execution_type' => $executionType,
                    'source_queue_id' => $sourceQueueId,
                    'status' => $updatedStatus,
                    'sync' => $sync,
                    'error' => $lastError,
                    'external_api_called_by_page' => false,
                ];
                $this->heartbeatLiveChannelWorkerLease($runId, (string) ($lease['lease_token'] ?? ''), $leaseTtlSeconds);
            }

            $status = $summary['processed'] === 0 && $summary['blocked'] > 0
                ? 'blocked'
                : (($summary['failed'] > 0 || $summary['blocked'] > 0) ? 'completed_with_errors' : 'completed');
            $summary['completed_at'] = date('c');
            $this->completeLiveChannelWorkerRun($runId, $status, $summary);

            return $this->listLiveChannelWorkerRuns(['id' => $runId], 1, 0)[0] ?? $summary;
        } catch (Throwable $e) {
            $summary['errors'][] = ['error' => mb_substr($this->sanitizeLiveProviderError((string) $e->getMessage()), 0, 500)];
            $summary['completed_at'] = date('c');
            $this->completeLiveChannelWorkerRun($runId, 'failed', $summary, $this->sanitizeLiveProviderError((string) $e->getMessage()));
            throw $e;
        } finally {
            if ($leaseAcquired && is_array($lease)) {
                $this->releaseLiveChannelWorkerLease($runId, (string) ($lease['lease_token'] ?? ''), 'released');
                $this->markLiveEmailWorkerScheduleConfirmed(self::LIVE_CHANNEL_WORKER_KEY, $source, $requestedBy);
            }
        }
    }

    public function controlLiveEmailHandoff(int $handoffId, string $action, int $actorId, string $note = ''): array
    {
        if ($handoffId <= 0) {
            throw new \InvalidArgumentException('Live email handoff is required.');
        }
        $action = preg_replace('/[^a-z_]/', '', strtolower($action)) ?: '';
        if (in_array($action, ['retry', 'cancel'], true)) {
            $this->assertMarketingPermission('marketing.manage');
        } else {
            $this->assertMarketingPermission('marketing.write');
        }
        $handoff = Database::queryOne(
            "SELECT *
             FROM marketing_live_email_handoffs
             WHERE workspace_id = ?
               AND id = ?
             LIMIT 1",
            [$this->workspaceId(), $handoffId]
        );
        if (!$handoff) {
            throw new RuntimeException('Live email handoff was not found in the active workspace.');
        }

        $note = $this->nullableSanitizedText($note) ?? '';
        $emailId = (int) ($handoff['email_id'] ?? 0);
        $emailQueueId = (int) ($handoff['email_queue_id'] ?? 0);
        $result = ['handoff_id' => $handoffId, 'action' => $action, 'success' => true];

        if ($action === 'retry') {
            if ($emailId <= 0 || $emailQueueId <= 0) {
                throw new RuntimeException('Live email handoff cannot be retried because its CRM email queue row is missing.');
            }
            Database::execute(
                "UPDATE emails
                 SET status = 'pending', error_message = NULL
                 WHERE workspace_id = ?
                   AND id = ?",
                [$this->workspaceId(), $emailId]
            );
            Database::execute(
                "UPDATE email_queue
                 SET status = 'pending', error_message = NULL, processed_at = NULL
                 WHERE workspace_id = ?
                   AND id = ?",
                [$this->workspaceId(), $emailQueueId]
            );
            $this->updateLiveEmailHandoffControl($handoffId, 'queued', 'retry_requested', 'pending', 'pending', $actorId, $note);
            $this->recordLiveEmailHandoffEvent($handoffId, 'retry_requested', 'info', 'Retry requested by marketing operator.', ['note' => $note], $actorId);
        } elseif ($action === 'cancel') {
            if ($emailId > 0) {
                Database::execute(
                    "UPDATE emails
                     SET status = 'failed', error_message = ?
                     WHERE workspace_id = ?
                       AND id = ?
                       AND status = 'pending'",
                    ['Cancelled by marketing operator before send.', $this->workspaceId(), $emailId]
                );
            }
            if ($emailQueueId > 0) {
                Database::execute(
                    "UPDATE email_queue
                     SET status = 'failed', error_message = ?, processed_at = NOW()
                     WHERE workspace_id = ?
                       AND id = ?
                       AND status IN ('pending', 'failed')",
                    ['Cancelled by marketing operator before send.', $this->workspaceId(), $emailQueueId]
                );
            }
            $this->updateLiveEmailHandoffControl($handoffId, 'cancelled', 'cancelled', 'failed', 'failed', $actorId, $note);
            $this->recordLiveEmailHandoffEvent($handoffId, 'cancelled', 'blocked', 'Cancelled by marketing operator before send.', ['note' => $note], $actorId);
        } elseif ($action === 'recheck_suppression') {
            $blocked = $this->isLiveEmailHandoffSuppressed($handoff);
            if ($blocked) {
                if ($emailId > 0) {
                    Database::execute(
                        "UPDATE emails
                         SET status = 'failed', error_message = ?
                         WHERE workspace_id = ?
                           AND id = ?
                           AND status = 'pending'",
                        ['Marketing live email handoff blocked by active suppression entry.', $this->workspaceId(), $emailId]
                    );
                }
                if ($emailQueueId > 0) {
                    Database::execute(
                        "UPDATE email_queue
                         SET status = 'failed', error_message = ?, processed_at = NOW()
                         WHERE workspace_id = ?
                           AND id = ?",
                        ['Marketing live email handoff blocked by active suppression entry.', $this->workspaceId(), $emailQueueId]
                    );
                }
                $this->updateLiveEmailHandoffControl($handoffId, 'blocked', 'blocked', 'failed', 'failed', $actorId, $note, true);
                $this->recordLiveEmailHandoffEvent($handoffId, 'blocked', 'blocked', 'Suppression recheck blocked this handoff.', ['note' => $note], $actorId);
                $result['blocked'] = true;
            } else {
                $this->updateLiveEmailHandoffControl($handoffId, (string) ($handoff['status'] ?? 'queued'), 'reviewed', null, null, $actorId, $note, true);
                $this->recordLiveEmailHandoffEvent($handoffId, 'suppression_rechecked', 'success', 'Suppression recheck passed.', ['note' => $note], $actorId);
                $result['blocked'] = false;
            }
        } elseif ($action === 'mark_reviewed') {
            $this->updateLiveEmailHandoffControl($handoffId, (string) ($handoff['status'] ?? 'queued'), 'reviewed', null, null, $actorId, $note);
            $this->recordLiveEmailHandoffEvent($handoffId, 'operator_note', 'info', 'Live email handoff reviewed by operator.', ['note' => $note], $actorId);
        } else {
            throw new \InvalidArgumentException('Unsupported live email handoff action.');
        }

        $result['handoff'] = $this->listLiveEmailHandoffs(['id' => $handoffId], 1, 0)[0] ?? null;

        return $result;
    }

    public function listExecutionQueue(array $filters = [], int $limit = 100, int $offset = 0): array
    {
        if (!Database::tableExists('marketing_execution_queue')) {
            return [];
        }

        $limit = min(max($limit, 1), 250);
        $offset = max($offset, 0);
        $workspace = $this->workspaceClause('eq.');
        $where = [$workspace['sql']];
        $params = $workspace['params'];
        if (!empty($filters['id'])) {
            $where[] = 'eq.id = ?';
            $params[] = (int) $filters['id'];
        }
        if (!empty($filters['status'])) {
            $where[] = 'eq.status = ?';
            $params[] = $this->normalizeEnum((string) $filters['status'], self::EXECUTION_STATUSES, 'execution_status');
        }
        if (!empty($filters['execution_type'])) {
            $where[] = 'eq.execution_type = ?';
            $params[] = $this->normalizeEnum((string) $filters['execution_type'], self::EXECUTION_TYPES, 'execution_type');
        }
        foreach (['connector_id', 'content_item_id', 'distribution_post_id', 'email_run_id', 'channel_export_bundle_id', 'landing_page_id'] as $field) {
            if (!empty($filters[$field])) {
                $where[] = 'eq.' . $field . ' = ?';
                $params[] = (int) $filters[$field];
            }
        }

        return array_map(
            fn(array $row): array => $this->hydrateExecutionQueueRow($row),
            Database::query(
                "SELECT eq.*, cc.name AS connector_name, cc.status AS connector_status, cc.connector_type,
                        m.title AS content_title, dp.channel AS distribution_channel,
                        eb.channel AS bundle_channel, lp.title AS landing_page_title,
                        requester.email AS requested_by_email, creator.email AS created_by_email,
                        (SELECT COUNT(*) FROM marketing_execution_attempts ea WHERE ea.workspace_id = eq.workspace_id AND ea.queue_id = eq.id) AS attempt_count,
                        (SELECT ea.status FROM marketing_execution_attempts ea WHERE ea.workspace_id = eq.workspace_id AND ea.queue_id = eq.id ORDER BY ea.created_at DESC LIMIT 1) AS last_attempt_status,
                        (SELECT eap.status FROM marketing_execution_approvals eap WHERE eap.workspace_id = eq.workspace_id AND eap.queue_id = eq.id ORDER BY eap.created_at DESC LIMIT 1) AS approval_status,
                        (SELECT eap.id FROM marketing_execution_approvals eap WHERE eap.workspace_id = eq.workspace_id AND eap.queue_id = eq.id ORDER BY eap.created_at DESC LIMIT 1) AS approval_id
                 FROM marketing_execution_queue eq
                 LEFT JOIN marketing_channel_connectors cc ON cc.id = eq.connector_id AND cc.workspace_id = eq.workspace_id
                 LEFT JOIN marketing_content_items m ON m.id = eq.content_item_id AND m.workspace_id = eq.workspace_id
                 LEFT JOIN marketing_distribution_posts dp ON dp.id = eq.distribution_post_id AND dp.workspace_id = eq.workspace_id
                 LEFT JOIN marketing_channel_export_bundles eb ON eb.id = eq.channel_export_bundle_id AND eb.workspace_id = eq.workspace_id
                 LEFT JOIN marketing_landing_pages lp ON lp.id = eq.landing_page_id AND lp.workspace_id = eq.workspace_id
                 LEFT JOIN users requester ON requester.id = eq.requested_by
                 LEFT JOIN users creator ON creator.id = eq.created_by
                 WHERE " . implode(' AND ', $where) . "
                 ORDER BY CASE WHEN eq.scheduled_at IS NULL THEN 1 ELSE 0 END ASC, eq.scheduled_at ASC, eq.updated_at DESC
                 LIMIT {$limit} OFFSET {$offset}",
                $params
            )
        );
    }

    public function getExecutionQueueItem(int $id): ?array
    {
        $rows = $this->listExecutionQueue(['id' => $id], 1, 0);
        if ($rows !== []) {
            return $rows[0];
        }
        if (!Database::tableExists('marketing_execution_queue')) {
            return null;
        }
        $row = Database::queryOne(
            "SELECT * FROM marketing_execution_queue WHERE workspace_id = ? AND id = ?",
            [$this->workspaceId(), $id]
        );

        return $row ? $this->hydrateExecutionQueueRow($row) : null;
    }

    public function listDueLiveDispatchQueue(int $limit = 20, int $offset = 0): array
    {
        $this->assertMarketingPermission('marketing.read');
        if (!Database::tableExists('marketing_execution_queue') || !Database::columnExists('marketing_execution_queue', 'live_dispatch_status')) {
            return [];
        }

        $limit = min(max($limit, 1), 100);
        $offset = max($offset, 0);

        return array_map(
            fn(array $row): array => $this->hydrateExecutionQueueRow($row),
            Database::query(
                "SELECT eq.*, cc.name AS connector_name, cc.status AS connector_status, cc.connector_type,
                        m.title AS content_title, dp.channel AS distribution_channel,
                        eb.channel AS bundle_channel, lp.title AS landing_page_title,
                        requester.email AS requested_by_email, creator.email AS created_by_email,
                        (SELECT COUNT(*) FROM marketing_execution_attempts ea WHERE ea.workspace_id = eq.workspace_id AND ea.queue_id = eq.id) AS attempt_count,
                        (SELECT ea.status FROM marketing_execution_attempts ea WHERE ea.workspace_id = eq.workspace_id AND ea.queue_id = eq.id ORDER BY ea.created_at DESC LIMIT 1) AS last_attempt_status,
                        (SELECT eap.status FROM marketing_execution_approvals eap WHERE eap.workspace_id = eq.workspace_id AND eap.queue_id = eq.id ORDER BY eap.created_at DESC LIMIT 1) AS approval_status,
                        (SELECT eap.id FROM marketing_execution_approvals eap WHERE eap.workspace_id = eq.workspace_id AND eap.queue_id = eq.id ORDER BY eap.created_at DESC LIMIT 1) AS approval_id,
                        TIMESTAMPDIFF(MINUTE, COALESCE(eq.live_retry_after, eq.scheduled_at, eq.live_dispatch_confirmed_at, eq.updated_at), NOW()) AS due_age_minutes
                 FROM marketing_execution_queue eq
                 LEFT JOIN marketing_channel_connectors cc ON cc.id = eq.connector_id AND cc.workspace_id = eq.workspace_id
                 LEFT JOIN marketing_content_items m ON m.id = eq.content_item_id AND m.workspace_id = eq.workspace_id
                 LEFT JOIN marketing_distribution_posts dp ON dp.id = eq.distribution_post_id AND dp.workspace_id = eq.workspace_id
                 LEFT JOIN marketing_channel_export_bundles eb ON eb.id = eq.channel_export_bundle_id AND eb.workspace_id = eq.workspace_id
                 LEFT JOIN marketing_landing_pages lp ON lp.id = eq.landing_page_id AND lp.workspace_id = eq.workspace_id
                 LEFT JOIN users requester ON requester.id = eq.requested_by
                 LEFT JOIN users creator ON creator.id = eq.created_by
                 WHERE eq.workspace_id = ?
                   AND eq.execution_mode = 'live'
                   AND eq.live_dispatch_status = 'confirmed'
                   AND eq.status IN ('approved','queued')
                   AND (eq.scheduled_at IS NULL OR eq.scheduled_at <= NOW())
                   AND (eq.live_retry_after IS NULL OR eq.live_retry_after <= NOW())
                 ORDER BY CASE WHEN eq.scheduled_at IS NULL THEN 1 ELSE 0 END ASC, eq.scheduled_at ASC, eq.id ASC
                 LIMIT {$limit} OFFSET {$offset}",
                [$this->workspaceId()]
            )
        );
    }

    public function createExecutionQueueItem(array $data): int
    {
        $this->assertMarketingPermission('marketing.write');
        if (!Database::tableExists('marketing_execution_queue')) {
            throw new RuntimeException('Marketing execution queue is unavailable.');
        }
        $normalized = $this->normalizeExecutionQueueData($data, true);
        $queueUuid = $this->generateUuid();
        $liveIdempotencyKey = hash('sha256', $this->workspaceId() . ':' . $queueUuid . ':' . (string) ($normalized['execution_type'] ?? 'other'));
        Database::execute(
            "INSERT INTO marketing_execution_queue
             (workspace_id, uuid, execution_type, status, execution_mode, connector_id, content_item_id,
              distribution_post_id, email_run_id, channel_export_bundle_id, landing_page_id, scheduled_at,
              requested_by, payload_json, readiness_json, metadata_json, live_rehearsal_run_id,
              live_rehearsal_required, live_rehearsal_status, live_rehearsal_evidence_json,
              live_manager_override_json, live_idempotency_key, live_rerun_policy,
              live_retry_status, live_retry_count, live_max_retries, live_retry_backoff_seconds, live_retry_after,
              live_retry_reason, live_retry_json, live_outcome_status, live_outcome_checked_at, live_outcome_json, created_by)
             VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)",
            [
                $this->workspaceId(),
                $queueUuid,
                $normalized['execution_type'],
                $normalized['status'],
                $normalized['execution_mode'],
                $normalized['connector_id'],
                $normalized['content_item_id'],
                $normalized['distribution_post_id'],
                $normalized['email_run_id'],
                $normalized['channel_export_bundle_id'],
                $normalized['landing_page_id'],
                $normalized['scheduled_at'],
                $normalized['requested_by'],
                $normalized['payload_json'],
                $normalized['readiness_json'],
                $normalized['metadata_json'],
                $normalized['live_rehearsal_run_id'],
                $normalized['live_rehearsal_required'],
                $normalized['live_rehearsal_status'],
                $normalized['live_rehearsal_evidence_json'],
                $normalized['live_manager_override_json'],
                $liveIdempotencyKey,
                $normalized['live_rerun_policy'],
                $normalized['live_retry_status'],
                $normalized['live_retry_count'],
                $normalized['live_max_retries'],
                $normalized['live_retry_backoff_seconds'],
                $normalized['live_retry_after'],
                $normalized['live_retry_reason'],
                $normalized['live_retry_json'],
                $normalized['live_outcome_status'],
                $normalized['live_outcome_checked_at'],
                $normalized['live_outcome_json'],
                $normalized['created_by'],
            ]
        );

        return (int) Database::lastInsertId();
    }

    public function listLiveRehearsalRuns(array $filters = [], int $limit = 100, int $offset = 0): array
    {
        if (!Database::tableExists('marketing_live_rehearsal_runs')) {
            return [];
        }

        $limit = min(max($limit, 1), 250);
        $offset = max($offset, 0);
        $workspace = $this->workspaceClause('lr.');
        $where = [$workspace['sql']];
        $params = $workspace['params'];
        if (!empty($filters['id'])) {
            $where[] = 'lr.id = ?';
            $params[] = (int) $filters['id'];
        }
        if (!empty($filters['status'])) {
            $where[] = 'lr.status = ?';
            $params[] = $this->normalizeEnum((string) $filters['status'], self::LIVE_REHEARSAL_STATUSES, 'live_rehearsal_status');
        }
        foreach (['connector_id', 'content_item_id', 'distribution_post_id', 'channel_export_bundle_id', 'promoted_queue_id'] as $field) {
            if (!empty($filters[$field])) {
                $where[] = 'lr.' . $field . ' = ?';
                $params[] = (int) $filters[$field];
            }
        }

        return array_map(
            fn(array $row): array => $this->hydrateLiveRehearsalRunRow($row),
            Database::query(
                "SELECT lr.*, cc.name AS connector_name, cc.connector_type, cc.live_adapter_key,
                        m.title AS content_title, dp.channel AS distribution_channel,
                        ceb.channel AS bundle_channel, requester.email AS requested_by_email,
                        approver.email AS approved_by_email, promoter.email AS promoted_by_email
                 FROM marketing_live_rehearsal_runs lr
                 LEFT JOIN marketing_channel_connectors cc ON cc.id = lr.connector_id AND cc.workspace_id = lr.workspace_id
                 LEFT JOIN marketing_content_items m ON m.id = lr.content_item_id AND m.workspace_id = lr.workspace_id
                 LEFT JOIN marketing_distribution_posts dp ON dp.id = lr.distribution_post_id AND dp.workspace_id = lr.workspace_id
                 LEFT JOIN marketing_channel_export_bundles ceb ON ceb.id = lr.channel_export_bundle_id AND ceb.workspace_id = lr.workspace_id
                 LEFT JOIN users requester ON requester.id = lr.requested_by
                 LEFT JOIN users approver ON approver.id = lr.approved_by
                 LEFT JOIN users promoter ON promoter.id = lr.promoted_by
                 WHERE " . implode(' AND ', $where) . "
                 ORDER BY lr.updated_at DESC, lr.id DESC
                 LIMIT {$limit} OFFSET {$offset}",
                $params
            )
        );
    }

    public function getLiveRehearsalRun(int $id): ?array
    {
        $rows = $this->listLiveRehearsalRuns(['id' => $id], 1, 0);
        return $rows[0] ?? null;
    }

    public function createLiveRehearsalRun(array $data): int
    {
        $this->assertMarketingPermission('marketing.write');
        if (!Database::tableExists('marketing_live_rehearsal_runs')) {
            throw new RuntimeException('Marketing live rehearsal runs are unavailable.');
