    public function syncLiveExecutionQueueOutcomes(?int $queueId = null, int $limit = 250): array
    {
        $this->assertMarketingPermission('marketing.read');
        return $this->syncLiveExecutionQueueOutcomesInternal($queueId, $limit);
    }

    private function syncLiveExecutionQueueOutcomesInternal(?int $queueId = null, int $limit = 250): array
    {
        if (!Database::tableExists('marketing_execution_queue') || !Database::columnExists('marketing_execution_queue', 'live_outcome_status')) {
            return [
                'synced' => 0,
                'counts' => [],
                'available' => false,
            ];
        }

        $limit = min(max($limit, 1), 1000);
        $where = ['eq.workspace_id = ?', "eq.execution_mode = 'live'"];
        $params = [$this->workspaceId()];
        if ($queueId !== null && $queueId > 0) {
            $where[] = 'eq.id = ?';
            $params[] = $queueId;
        }

        $queues = Database::query(
            "SELECT eq.*, cc.live_adapter_key
             FROM marketing_execution_queue eq
             LEFT JOIN marketing_channel_connectors cc ON cc.id = eq.connector_id AND cc.workspace_id = eq.workspace_id
             WHERE " . implode(' AND ', $where) . "
             ORDER BY eq.updated_at DESC, eq.id DESC
             LIMIT {$limit}",
            $params
        );

        $counts = array_fill_keys(self::LIVE_EXECUTION_OUTCOME_STATUSES, 0);
        $synced = 0;
        $eventsRecorded = 0;
        foreach ($queues as $queue) {
            $outcome = $this->deriveLiveExecutionQueueOutcome($queue);
            $status = $this->normalizeEnum((string) ($outcome['status'] ?? 'unknown'), self::LIVE_EXECUTION_OUTCOME_STATUSES, 'live_execution_outcome_status');
            $reconciliation = $this->buildLiveOutcomeReconciliationSummary($queue, $outcome, $status);
            if ($this->recordLiveOutcomeReconciliationEvent($queue, $outcome, $status, $reconciliation)) {
                $eventsRecorded++;
            }
            $queueUpdate = [
                'live_outcome_status' => $status,
                'live_outcome_checked_at' => date('Y-m-d H:i:s'),
                'live_outcome_json' => $this->normalizeJsonValue($outcome),
            ];
            if (Database::columnExists('marketing_execution_queue', 'live_outcome_reconciliation_key')) {
                $queueUpdate['live_outcome_reconciled_at'] = date('Y-m-d H:i:s');
                $queueUpdate['live_outcome_reconciliation_key'] = (string) ($reconciliation['reconciliation_key'] ?? '');
                $queueUpdate['live_outcome_reconciliation_json'] = $this->normalizeJsonValue($reconciliation);
            }
            $this->updateById('marketing_execution_queue', (int) ($queue['id'] ?? 0), $queueUpdate);
            $counts[$status] = ($counts[$status] ?? 0) + 1;
            $synced++;
        }

        return [
            'synced' => $synced,
            'events_recorded' => $eventsRecorded,
            'counts' => array_filter($counts, static fn(int $count): bool => $count > 0),
            'available' => true,
            'checked_at' => date('c'),
            'secret_safe' => true,
        ];
    }

