    public function createLiveProofPack(int $queueId, int $actorId): array
    {
        $this->assertMarketingPermission('marketing.manage');
        if (!Database::tableExists('marketing_live_proof_packs')) {
            throw new RuntimeException('Marketing live proof packs are unavailable.');
        }

        $queue = $this->getExecutionQueueItem($queueId);
        if (!$queue) {
            throw new RuntimeException('Marketing live execution queue item not found.');
        }

        $this->syncLiveExecutionQueueOutcomes($queueId, 1);
        $queue = $this->getExecutionQueueItem($queueId) ?? $queue;
        $connector = !empty($queue['connector_id']) ? $this->getChannelConnector((int) $queue['connector_id']) : null;
        $evidence = $this->buildLiveProofPackEvidence($queue, $connector);
        $summary = $this->buildLiveProofPackSummary($queue, $evidence);
        $proofStatus = $this->normalizeEnum(
            (string) ($summary['proof_status'] ?? 'unknown'),
            ['complete', 'partial', 'blocked', 'failed', 'unknown'],
            'live_proof_pack_status'
        );
        $normalizedOutcomeStatus = mb_substr(
            Security::sanitizeInput((string) ($summary['normalized_outcome_status'] ?? 'unknown'), 'string'),
            0,
            60
        );
        $title = mb_substr(
            'Live proof pack for queue #' . (int) ($queue['id'] ?? 0) . ' - ' . ucwords(str_replace('_', ' ', (string) ($queue['execution_type'] ?? 'other'))),
            0,
            190
        );

        Database::execute(
            "INSERT INTO marketing_live_proof_packs
             (workspace_id, uuid, queue_id, connector_id, title, status, proof_status,
              normalized_outcome_status, evidence_json, summary_json, generated_by, generated_at)
             VALUES (?, ?, ?, ?, ?, 'ready', ?, ?, ?, ?, ?, NOW())",
            [
                $this->workspaceId(),
                $this->generateUuid(),
                (int) ($queue['id'] ?? 0),
                !empty($queue['connector_id']) ? (int) $queue['connector_id'] : null,
                $title,
                $proofStatus,
                $normalizedOutcomeStatus,
                $this->normalizeJsonValue($evidence),
                $this->normalizeJsonValue($summary),
                $actorId > 0 ? $actorId : ($this->currentUserId() ?: null),
            ]
        );

        return $this->getLiveProofPack((int) Database::lastInsertId()) ?? [];
    }

    public function getLiveProofPack(int $id): ?array
    {
        $this->assertMarketingPermission('marketing.read');
        if (!Database::tableExists('marketing_live_proof_packs')) {
