             FROM marketing_live_proof_packs pp
             LEFT JOIN marketing_channel_connectors cc ON cc.id = pp.connector_id AND cc.workspace_id = pp.workspace_id
             LEFT JOIN users generator ON generator.id = pp.generated_by
             WHERE pp.workspace_id = ? AND pp.id = ?",
            [$this->workspaceId(), $id]
        );

        return $row ? $this->hydrateJsonFields($row, ['evidence_json', 'summary_json']) : null;
    }

