    public function getMarketingLiveProofReportSummary(): array
    {
        $this->assertMarketingPermission('marketing.read');
        $workspaceId = $this->workspaceId();
        $queueCounts = Database::tableExists('marketing_execution_queue')
            ? (Database::queryOne(
                "SELECT COUNT(*) AS total,
                        SUM(CASE WHEN execution_mode = 'live' THEN 1 ELSE 0 END) AS live_total,
                        SUM(CASE WHEN execution_mode = 'live' AND status IN ('failed','blocked') THEN 1 ELSE 0 END) AS failed_or_blocked,
                        SUM(CASE WHEN execution_mode = 'live' AND status = 'blocked' THEN 1 ELSE 0 END) AS blocked,
                        SUM(CASE WHEN execution_mode = 'live' AND live_suppression_result = 'blocked' THEN 1 ELSE 0 END) AS suppression_blocked,
                        SUM(CASE WHEN execution_mode = 'live' AND live_outcome_status IN ('failed','bounced') THEN 1 ELSE 0 END) AS outcome_failures
                 FROM marketing_execution_queue
                 WHERE workspace_id = ?",
                [$workspaceId]
            ) ?: [])
            : [];
        $proofRows = Database::tableExists('marketing_live_proof_packs')
            ? Database::query(
                "SELECT proof_status, COUNT(*) AS count
                 FROM marketing_live_proof_packs
                 WHERE workspace_id = ?
                 GROUP BY proof_status",
                [$workspaceId]
            )
            : [];
        $proofCounts = [];
        foreach ($proofRows as $row) {
            $proofCounts[(string) ($row['proof_status'] ?? 'unknown')] = (int) ($row['count'] ?? 0);
        }
        $recentRecoveryCount = Database::tableExists('marketing_live_recovery_events')
            ? (int) (Database::queryOne(
                "SELECT COUNT(*) AS count
                 FROM marketing_live_recovery_events
                 WHERE workspace_id = ? AND created_at >= DATE_SUB(NOW(), INTERVAL 30 DAY)",
                [$workspaceId]
            )['count'] ?? 0)
            : 0;
        $scheduler = $this->getMarketingLiveSchedulerValidation(false);

        return [
            'live_volume' => (int) ($queueCounts['live_total'] ?? 0),
            'failed_or_blocked' => (int) ($queueCounts['failed_or_blocked'] ?? 0),
            'blocked_sends' => (int) ($queueCounts['blocked'] ?? 0),
            'suppression_blocks' => (int) ($queueCounts['suppression_blocked'] ?? 0),
            'outcome_failures' => (int) ($queueCounts['outcome_failures'] ?? 0),
            'proof_packs' => [
                'total' => array_sum($proofCounts),
                'by_status' => $proofCounts,
            ],
            'recent_recovery_events' => $recentRecoveryCount,
            'worker_health' => [
                'status' => (string) ($scheduler['status'] ?? 'unknown'),
                'ready_components' => (int) ($scheduler['counts']['ready'] ?? 0),
                'action_needed_components' => (int) ($scheduler['counts']['action_needed'] ?? 0),
                'stale_components' => (int) ($scheduler['counts']['stale'] ?? 0),
                'blocked_components' => (int) ($scheduler['counts']['blocked'] ?? 0),
            ],
            'secret_safe' => true,
        ];
    }

