    public function getLiveExecutionLauncherHealth(bool $persist = false, ?int $checkedBy = null): array
    {
        $this->assertMarketingPermission('marketing.read');
        $workerKey = 'marketing_live_execution_launcher';
        $command = 'php cli/run_marketing_live_execution.php all 25 --source=cron';
        if (!Database::tableExists('marketing_live_execution_launcher_runs')) {
            return [
                'worker_key' => $workerKey,
                'status' => 'unknown',
                'message' => 'Marketing live execution launcher table is unavailable.',
                'counts' => ['queued' => 0, 'stale' => 0, 'blocked' => 0, 'failed' => 0],
                'recommended_actions' => ['Run pending migrations before scheduling the unified live execution launcher.'],
                'command' => $command,
                'secret_safe' => true,
            ];
        }

        $workspaceId = $this->workspaceId();
        $schedule = $this->liveOrchestratorScheduleSnapshot();
        $staleMinutes = max(1, (int) ($schedule['max_stale_minutes'] ?? 30));
        $latestRun = Database::queryOne(
            "SELECT *,
                    TIMESTAMPDIFF(MINUTE, started_at, NOW()) AS age_minutes
             FROM marketing_live_execution_launcher_runs
             WHERE workspace_id = ?
             ORDER BY started_at DESC, id DESC
             LIMIT 1",
            [$workspaceId]
        ) ?: null;
        $recentCounts = Database::queryOne(
            "SELECT COUNT(*) AS total_count,
                    SUM(status = 'completed') AS completed_count,
                    SUM(status = 'completed_with_errors') AS warning_count,
                    SUM(status = 'blocked') AS blocked_count,
                    SUM(status = 'failed') AS failed_count,
                    SUM(readiness_only = 1) AS readiness_count
             FROM marketing_live_execution_launcher_runs
             WHERE workspace_id = ?
               AND started_at >= DATE_SUB(NOW(), INTERVAL 24 HOUR)",
            [$workspaceId]
        ) ?: [];
        $dueDispatch = Database::tableExists('marketing_execution_queue')
            ? (int) (Database::queryOne(
                "SELECT COUNT(*) AS count
                 FROM marketing_execution_queue
                 WHERE workspace_id = ?
                   AND execution_mode = 'live'
                   AND live_dispatch_status = 'confirmed'
                   AND status IN ('approved','queued')
                   AND (scheduled_at IS NULL OR scheduled_at <= NOW())
                   AND (live_retry_after IS NULL OR live_retry_after <= NOW())",
                [$workspaceId]
            )['count'] ?? 0)
            : 0;
        $emailHandoffs = Database::tableExists('marketing_live_email_handoffs')
            ? (int) (Database::queryOne(
                "SELECT COUNT(*) AS count
                 FROM marketing_live_email_handoffs
                 WHERE workspace_id = ? AND status = 'queued'",
                [$workspaceId]
            )['count'] ?? 0)
            : 0;
        $channelHandoffs = Database::tableExists('marketing_live_channel_handoffs')
            ? (int) (Database::queryOne(
                "SELECT COUNT(*) AS count
                 FROM marketing_live_channel_handoffs
                 WHERE workspace_id = ? AND status = 'queued'",
                [$workspaceId]
            )['count'] ?? 0)
            : 0;
        $dueWork = $dueDispatch + $emailHandoffs + $channelHandoffs;
        $latestRunStatus = (string) ($latestRun['status'] ?? '');
        $latestRunAge = isset($latestRun['age_minutes']) ? (int) $latestRun['age_minutes'] : null;

        $status = 'healthy';
        $message = 'Marketing live execution launcher is healthy.';
        if ($latestRun === null) {
            $status = (string) ($schedule['status'] ?? 'planned') === 'active' || $dueWork > 0 ? 'stale' : 'unknown';
            $message = $status === 'stale'
                ? 'Marketing live execution launcher has not recorded a run while live execution is expected.'
                : 'No Marketing live execution launcher run has been recorded yet.';
        } elseif (in_array($latestRunStatus, ['failed', 'blocked'], true)) {
            $status = 'blocked';
            $message = 'The latest Marketing live execution launcher run ended blocked or failed.';
        } elseif ($latestRunStatus === 'completed_with_errors') {
            $status = 'attention';
            $message = 'The latest Marketing live execution launcher run completed with errors.';
        } elseif ($latestRunAge !== null && $latestRunAge >= $staleMinutes && ((string) ($schedule['status'] ?? 'planned') === 'active' || $dueWork > 0)) {
            $status = 'stale';
            $message = 'Marketing live execution launcher has missed its freshness window.';
        }
        if (!empty($schedule['emergency_paused'])) {
            $status = 'blocked';
            $message = 'Marketing live execution launcher is blocked by the orchestrator emergency pause.';
        } elseif (in_array((string) ($schedule['status'] ?? ''), ['paused', 'disabled'], true) && $dueWork > 0) {
            $status = 'blocked';
            $message = 'Marketing live execution launcher schedule is paused or disabled while live work is waiting.';
        }

        $recommendedActions = [];
        if ((string) ($schedule['status'] ?? 'planned') !== 'active') {
            $recommendedActions[] = 'Activate the unified Marketing live execution schedule after installing the cron entry.';
        }
        if ($latestRun === null || $status === 'stale') {
            $recommendedActions[] = 'Run or schedule: ' . (string) ($schedule['command'] ?? $command);
        }
        if ($status === 'blocked') {
            $recommendedActions[] = 'Review the latest launcher/orchestrator evidence before retrying live execution.';
        }
        if ($dueWork > 0) {
            $recommendedActions[] = 'Live work is waiting; verify policy, connectors, approvals, and worker schedules before the next launcher run.';
        }
        if (!empty($schedule['emergency_paused'])) {
            $recommendedActions[] = 'Resume the orchestrator emergency pause after the incident is resolved.';
        }
        if ($recommendedActions === []) {
            $recommendedActions[] = 'Continue monitoring launcher freshness and recent run evidence.';
        }

        $health = [
            'worker_key' => $workerKey,
            'status' => $status,
            'message' => $message,
            'stale_threshold_minutes' => $staleMinutes,
            'last_run_id' => null,
            'last_launcher_run_id' => (int) ($latestRun['id'] ?? 0) ?: null,
            'last_run_at' => $latestRun['started_at'] ?? null,
            'last_run_status' => $latestRunStatus !== '' ? $latestRunStatus : null,
            'last_run_age_minutes' => $latestRunAge,
            'last_invocation_uuid' => $latestRun['invocation_uuid'] ?? null,
            'last_readiness_only' => !empty($latestRun['readiness_only']),
            'counts' => [
                'queued' => $dueWork,
                'due_dispatch' => $dueDispatch,
                'queued_email_handoffs' => $emailHandoffs,
                'queued_channel_handoffs' => $channelHandoffs,
                'stale' => $status === 'stale' ? 1 : 0,
                'blocked' => (int) ($recentCounts['blocked_count'] ?? 0),
                'failed' => (int) ($recentCounts['failed_count'] ?? 0),
                'recent_total' => (int) ($recentCounts['total_count'] ?? 0),
                'recent_completed' => (int) ($recentCounts['completed_count'] ?? 0),
                'recent_warnings' => (int) ($recentCounts['warning_count'] ?? 0),
                'recent_readiness_checks' => (int) ($recentCounts['readiness_count'] ?? 0),
            ],
            'schedule' => $schedule,
            'recommended_actions' => array_values(array_unique($recommendedActions)),
            'command' => (string) ($schedule['command'] ?? $command),
            'secret_safe' => true,
            'external_api_called_by_health_check' => false,
        ];

        if ($persist && Database::tableExists('marketing_live_worker_health_checks')) {
            $this->recordLiveWorkerHealthCheck($health, $checkedBy);
            $health['last_health_check_at'] = date('Y-m-d H:i:s');
        }

        return $health;
    }

    public function runLiveExecutionOrchestrator(array $options = []): array
    {
        if (!Database::tableExists('marketing_live_orchestration_runs')) {
            throw new RuntimeException('Marketing live orchestration run table is unavailable.');
        }
        $source = $this->normalizeEnum((string) ($options['source'] ?? 'cli'), self::LIVE_EMAIL_WORKER_RUN_SOURCES, 'live_orchestrator_source');
        $requestedLimit = min(max((int) ($options['limit'] ?? $options['limit_count'] ?? 25), 1), 250);
        $schedule = $this->liveOrchestratorScheduleSnapshot();
        $limit = min($requestedLimit, max(1, (int) ($schedule['max_handoffs_per_run'] ?? $requestedLimit)));
        $requestedBy = (int) ($options['requested_by'] ?? $this->currentUserId());
        $requestedBy = $requestedBy > 0 ? $requestedBy : null;
        $leaseTtlSeconds = min(max((int) ($options['lease_ttl_seconds'] ?? 900), 60), 3600);
        $scheduleBlockers = $this->liveOrchestratorScheduleBlockers($schedule, $source);
        $lease = null;
        $leaseAcquired = false;

        Database::execute(
            "INSERT INTO marketing_live_orchestration_runs
             (workspace_id, uuid, source, status, limit_count, requested_by, started_at)
             VALUES (?, ?, ?, 'running', ?, ?, NOW())",
            [$this->workspaceId(), $this->generateUuid(), $source, $limit, $requestedBy]
        );
        $runId = (int) Database::lastInsertId();
        $summary = [
            'run_id' => $runId,
            'source' => $source,
            'limit_count' => $limit,
            'schedule' => $schedule,
            'schedule_blockers' => $scheduleBlockers,
            'steps' => [],
            'counts' => [
                'processed' => 0,
                'succeeded' => 0,
                'blocked' => 0,
                'failed' => 0,
            ],
            'secret_safe' => true,
            'raw_secret_values_visible' => false,
            'external_api_called_by_orchestrator' => false,
        ];

        try {
            if ($scheduleBlockers !== []) {
                $summary['blocked'] = true;
                $this->completeLiveOrchestrationRun($runId, 'blocked', $summary, 'Marketing live orchestrator schedule blocked: ' . implode(', ', $scheduleBlockers));
                return $this->listLiveOrchestrationRuns(['id' => $runId], 1, 0)[0] ?? ['id' => $runId, 'result_json' => $summary];
            }

            $lease = $this->acquireLiveEmailWorkerLease(
                $runId,
                self::LIVE_ORCHESTRATOR_WORKER_KEY,
                $source,
                $leaseTtlSeconds,
                !empty($options['force_lease'])
            );
            $summary['lease'] = $lease;
            if (empty($lease['acquired'])) {
                $summary['lease_blocked'] = true;
                $this->completeLiveOrchestrationRun($runId, 'blocked', $summary, 'Another Marketing live orchestrator lease is active for this workspace.');
                return $this->listLiveOrchestrationRuns(['id' => $runId], 1, 0)[0] ?? ['id' => $runId, 'result_json' => $summary];
            }
            $leaseAcquired = true;

            $this->heartbeatLiveEmailWorkerLease($runId, (string) ($lease['lease_token'] ?? ''), $leaseTtlSeconds, self::LIVE_ORCHESTRATOR_WORKER_KEY);
            $dispatchRun = $this->runLiveExecutionDispatcher([
                'source' => $source,
                'limit_count' => $limit,
                'requested_by' => $requestedBy ?? 0,
            ]);
            $summary['steps']['dispatcher'] = $this->summarizeLiveOrchestratorStep($dispatchRun, [
                'processed_count',
                'succeeded_count',
                'blocked_count',
                'failed_count',
            ]);
            $summary['dispatch_run_id'] = (int) ($dispatchRun['id'] ?? 0) ?: null;
            $summary['counts']['processed'] += (int) ($dispatchRun['processed_count'] ?? 0);
            $summary['counts']['succeeded'] += (int) ($dispatchRun['succeeded_count'] ?? 0);
            $summary['counts']['blocked'] += (int) ($dispatchRun['blocked_count'] ?? 0);
            $summary['counts']['failed'] += (int) ($dispatchRun['failed_count'] ?? 0);

            $this->heartbeatLiveEmailWorkerLease($runId, (string) ($lease['lease_token'] ?? ''), $leaseTtlSeconds, self::LIVE_ORCHESTRATOR_WORKER_KEY);
            $emailRun = $this->processLiveEmailHandoffWorker([
                'source' => $source,
                'limit' => $limit,
                'requested_by' => $requestedBy ?? 0,
            ]);
            $summary['steps']['email_worker'] = $this->summarizeLiveOrchestratorStep($emailRun, [
                'processed_count',
                'sent_count',
                'blocked_count',
                'failed_count',
                'skipped_count',
            ]);
            $summary['email_worker_run_id'] = (int) ($emailRun['id'] ?? 0) ?: null;
            $summary['counts']['processed'] += (int) ($emailRun['processed_count'] ?? 0);
            $summary['counts']['succeeded'] += (int) ($emailRun['sent_count'] ?? 0);
            $summary['counts']['blocked'] += (int) ($emailRun['blocked_count'] ?? 0);
            $summary['counts']['failed'] += (int) ($emailRun['failed_count'] ?? 0);

            $this->heartbeatLiveEmailWorkerLease($runId, (string) ($lease['lease_token'] ?? ''), $leaseTtlSeconds, self::LIVE_ORCHESTRATOR_WORKER_KEY);
            $channelRun = $this->processLiveChannelHandoffWorker([
                'source' => $source,
                'limit' => $limit,
                'requested_by' => $requestedBy ?? 0,
            ]);
            $summary['steps']['channel_worker'] = $this->summarizeLiveOrchestratorStep($channelRun, [
                'processed_count',
                'sent_count',
                'blocked_count',
                'failed_count',
                'skipped_count',
            ]);
            $summary['channel_worker_run_id'] = (int) ($channelRun['id'] ?? 0) ?: null;
            $summary['counts']['processed'] += (int) ($channelRun['processed_count'] ?? 0);
            $summary['counts']['succeeded'] += (int) ($channelRun['sent_count'] ?? 0);
            $summary['counts']['blocked'] += (int) ($channelRun['blocked_count'] ?? 0);
            $summary['counts']['failed'] += (int) ($channelRun['failed_count'] ?? 0);

            $this->heartbeatLiveEmailWorkerLease($runId, (string) ($lease['lease_token'] ?? ''), $leaseTtlSeconds, self::LIVE_ORCHESTRATOR_WORKER_KEY);
            $outcomeRun = $this->runLiveOutcomeSyncWorker([
                'source' => $source,
                'limit' => max($limit, 250),
                'requested_by' => $requestedBy ?? 0,
            ]);
            $summary['steps']['outcome_sync'] = $this->summarizeLiveOrchestratorStep($outcomeRun, [
                'processed_count',
                'delivered_count',
                'failed_count',
                'blocked_count',
                'queued_count',
                'unknown_count',
            ]);
            $summary['outcome_sync_run_id'] = (int) ($outcomeRun['id'] ?? 0) ?: null;
            $summary['counts']['processed'] += (int) ($outcomeRun['processed_count'] ?? 0);
            $summary['counts']['succeeded'] += (int) ($outcomeRun['delivered_count'] ?? 0);
            $summary['counts']['blocked'] += (int) ($outcomeRun['blocked_count'] ?? 0);
            $summary['counts']['failed'] += (int) ($outcomeRun['failed_count'] ?? 0);
            $summary['checked_at'] = date('c');

            $stepStatuses = array_map(static fn(array $step): string => (string) ($step['status'] ?? ''), (array) ($summary['steps'] ?? []));
            $status = ($summary['counts']['failed'] ?? 0) > 0 || in_array('failed', $stepStatuses, true)
                ? 'failed'
                : ((($summary['counts']['blocked'] ?? 0) > 0 || array_intersect($stepStatuses, ['blocked', 'completed_with_errors']) !== [])
                    ? 'completed_with_errors'
                    : 'completed');
            $this->completeLiveOrchestrationRun($runId, $status, $summary);
            $this->markLiveEmailWorkerScheduleConfirmed(self::LIVE_ORCHESTRATOR_WORKER_KEY, $source, $requestedBy);
        } catch (Throwable $e) {
            $summary['error'] = mb_substr(Security::sanitizeInput($e->getMessage(), 'string'), 0, 500);
            $this->completeLiveOrchestrationRun($runId, 'failed', $summary, $summary['error']);
            throw $e;
        } finally {
            if ($leaseAcquired && is_array($lease)) {
                $this->releaseLiveEmailWorkerLease($runId, (string) ($lease['lease_token'] ?? ''), 'released', self::LIVE_ORCHESTRATOR_WORKER_KEY);
            }
        }

        return $this->listLiveOrchestrationRuns(['id' => $runId], 1, 0)[0] ?? ['id' => $runId, 'result_json' => $summary];
    }

    public function listLiveOutcomeSyncRuns(array $filters = [], int $limit = 100, int $offset = 0): array
    {
        if (!Database::tableExists('marketing_live_outcome_sync_runs')) {
            return [];
        }
        $limit = min(max($limit, 1), 250);
        $offset = max($offset, 0);
        $workspace = $this->workspaceClause('r.');
        $where = [$workspace['sql']];
        $params = $workspace['params'];
        foreach (['id', 'status', 'source'] as $field) {
            if (!empty($filters[$field])) {
                $where[] = 'r.' . $field . ' = ?';
                $params[] = $field === 'id' ? (int) $filters[$field] : (string) $filters[$field];
            }
        }

        return array_map(
            fn(array $row): array => $this->hydrateJsonFields($row, ['result_json']),
            Database::query(
                "SELECT r.*, requester.email AS requested_by_email
                 FROM marketing_live_outcome_sync_runs r
                 LEFT JOIN users requester ON requester.id = r.requested_by
                 WHERE " . implode(' AND ', $where) . "
                 ORDER BY r.started_at DESC, r.id DESC
                 LIMIT {$limit} OFFSET {$offset}",
                $params
            )
        );
    }

    public function runLiveOutcomeSyncWorker(array $options = []): array
    {
        if (!Database::tableExists('marketing_live_outcome_sync_runs')) {
            throw new RuntimeException('Marketing live outcome sync run table is unavailable.');
        }
        $source = $this->normalizeEnum((string) ($options['source'] ?? 'cli'), self::LIVE_EMAIL_WORKER_RUN_SOURCES, 'live_outcome_sync_source');
        $requestedLimit = min(max((int) ($options['limit'] ?? $options['limit_count'] ?? 250), 1), 1000);
        $schedule = $this->liveOutcomeSyncScheduleSnapshot();
        $limit = min($requestedLimit, max(1, (int) ($schedule['max_handoffs_per_run'] ?? $requestedLimit)));
        $requestedBy = (int) ($options['requested_by'] ?? $this->currentUserId());
        $requestedBy = $requestedBy > 0 ? $requestedBy : null;
        $leaseTtlSeconds = min(max((int) ($options['lease_ttl_seconds'] ?? 600), 60), 3600);
