        ];

        try {
            if ($scheduleBlockers !== []) {
                $summary['blocked'] = true;
                $this->completeLiveOutcomeSyncRun($runId, 'blocked', $summary, 'Marketing live outcome sync schedule blocked: ' . implode(', ', $scheduleBlockers));
                return $this->listLiveOutcomeSyncRuns(['id' => $runId], 1, 0)[0] ?? ['id' => $runId, 'result_json' => $summary];
