            );
            $summary['lease'] = $lease;
            if (empty($lease['acquired'])) {
                $summary['lease_blocked'] = true;
                $this->completeLiveOutcomeSyncRun($runId, 'blocked', $summary, 'Another Marketing live outcome sync worker lease is active for this workspace.');
                return $this->listLiveOutcomeSyncRuns(['id' => $runId], 1, 0)[0] ?? ['id' => $runId, 'result_json' => $summary];
            }
            $leaseAcquired = true;

            $this->heartbeatLiveEmailWorkerLease($runId, (string) ($lease['lease_token'] ?? ''), $leaseTtlSeconds, self::LIVE_OUTCOME_SYNC_WORKER_KEY);
            $result = $this->syncLiveExecutionQueueOutcomesInternal(null, $limit);
            $summary['synced'] = (int) ($result['synced'] ?? 0);
            $summary['events_recorded'] = (int) ($result['events_recorded'] ?? 0);
            $summary['counts'] = (array) ($result['counts'] ?? []);
            $summary['checked_at'] = date('c');
            $this->completeLiveOutcomeSyncRun($runId, 'completed', $summary);
            $this->markLiveEmailWorkerScheduleConfirmed(self::LIVE_OUTCOME_SYNC_WORKER_KEY, $source, $requestedBy);
        } catch (Throwable $e) {
            $summary['error'] = mb_substr(Security::sanitizeInput($e->getMessage(), 'string'), 0, 500);
            $this->completeLiveOutcomeSyncRun($runId, 'failed', $summary, $summary['error']);
            throw $e;
        } finally {
            if ($leaseAcquired && is_array($lease)) {
                $this->releaseLiveEmailWorkerLease($runId, (string) ($lease['lease_token'] ?? ''), 'released', self::LIVE_OUTCOME_SYNC_WORKER_KEY);
            }
        }

        return $this->listLiveOutcomeSyncRuns(['id' => $runId], 1, 0)[0] ?? ['id' => $runId, 'result_json' => $summary];
    }

    public function confirmExecutionQueueForLiveDispatch(int $queueId, int $userId, string $confirmation): array
    {
        $this->assertMarketingPermission('marketing.manage');
        if (!Database::tableExists('marketing_execution_queue') || !Database::columnExists('marketing_execution_queue', 'live_dispatch_status')) {
            throw new RuntimeException('Marketing live dispatch controls are unavailable.');
        }
        $actorId = $userId > 0 ? $userId : ($this->currentUserId() ?: null);
        if ($actorId !== null) {
            $this->assertWorkspaceUser($actorId, $this->workspaceId());
        }
        $queue = $this->getExecutionQueueItem($queueId);
        if (!$queue) {
            throw new RuntimeException('Marketing execution queue item not found.');
        }
        if ((string) ($queue['execution_mode'] ?? '') !== 'live') {
            throw new \InvalidArgumentException('Only live execution queue items can be confirmed for dispatch.');
        }

        $connector = !empty($queue['connector_id']) ? $this->getChannelConnector((int) $queue['connector_id']) : null;
        $approval = Database::tableExists('marketing_execution_approvals')
            ? Database::queryOne(
                "SELECT * FROM marketing_execution_approvals WHERE workspace_id = ? AND queue_id = ? ORDER BY created_at DESC LIMIT 1",
                [$this->workspaceId(), $queueId]
            )
            : null;
        $readiness = $this->executionQueueReadiness($queue, $connector, $approval, 'live');
        $liveControl = $this->liveRunControlReadiness($queue, ['live_confirmation' => $confirmation]);
        if (empty($liveControl['ready'])) {
            $readiness['ready'] = false;
            $readiness['blocked_reasons'] = array_values(array_unique(array_merge(
                (array) ($readiness['blocked_reasons'] ?? []),
                (array) ($liveControl['blocked_reasons'] ?? [])
            )));
            $readiness['live_control'] = $liveControl;
        } else {
            $readiness['live_control'] = $liveControl;
        }

        if (empty($readiness['ready'])) {
            Database::execute(
                "UPDATE marketing_execution_queue
                 SET readiness_json = ?,
                     live_policy_snapshot_json = ?,
                     live_blocked_reason = ?,
                     live_dispatch_status = 'blocked'
                 WHERE workspace_id = ? AND id = ?",
                [
                    $this->normalizeJsonValue($readiness),
                    $this->normalizeJsonValue((array) ($readiness['policy'] ?? [])),
                    implode(', ', (array) ($readiness['blocked_reasons'] ?? [])),
                    $this->workspaceId(),
                    $queueId,
                ]
            );
            throw new RuntimeException('Live dispatch confirmation is blocked: ' . implode(', ', (array) ($readiness['blocked_reasons'] ?? [])));
        }

        Database::execute(
            "UPDATE marketing_execution_queue
             SET live_dispatch_confirmed_at = NOW(),
                 live_dispatch_confirmed_by = ?,
                 live_dispatch_status = 'confirmed',
                 live_last_confirmed_at = NOW(),
                 live_last_confirmed_by = ?,
                 live_last_confirmation_text = 'RUN LIVE',
                 readiness_json = ?,
                 live_policy_snapshot_json = ?,
                 live_blocked_reason = NULL
             WHERE workspace_id = ? AND id = ?",
            [
                $actorId,
                $actorId,
                $this->normalizeJsonValue($readiness),
                $this->normalizeJsonValue((array) ($readiness['policy'] ?? [])),
                $this->workspaceId(),
                $queueId,
            ]
        );
        $this->recordLiveExecutionEvent('readiness_checked', 'ready', [
            'connector_id' => (int) ($queue['connector_id'] ?? 0),
            'queue_id' => $queueId,
            'execution_mode' => 'live',
            'adapter_key' => (string) ($readiness['adapter_key'] ?? ''),
            'payload' => ['live_dispatch_status' => 'confirmed'],
            'result' => ['ready' => true, 'confirmation_valid' => true],
            'created_by' => $actorId,
        ]);

        return $this->getExecutionQueueItem($queueId) ?? [];
    }

    public function cancelExecutionQueueLiveDispatch(int $queueId, int $userId, string $reason = ''): array
    {
        $this->assertMarketingPermission('marketing.manage');
        if (!Database::tableExists('marketing_execution_queue') || !Database::columnExists('marketing_execution_queue', 'live_dispatch_status')) {
            throw new RuntimeException('Marketing live dispatch controls are unavailable.');
        }
        $actorId = $userId > 0 ? $userId : ($this->currentUserId() ?: null);
        if ($actorId !== null) {
            $this->assertWorkspaceUser($actorId, $this->workspaceId());
        }
        $queue = $this->getExecutionQueueItem($queueId);
        if (!$queue) {
            throw new RuntimeException('Marketing execution queue item not found.');
        }
        if ((string) ($queue['execution_mode'] ?? '') !== 'live') {
            throw new \InvalidArgumentException('Only live execution queue items can have live dispatch cancelled.');
        }
        $dispatchStatus = (string) ($queue['live_dispatch_status'] ?? 'not_ready');
        if (!in_array($dispatchStatus, ['confirmed', 'blocked', 'failed'], true)) {
            throw new RuntimeException('Only confirmed, blocked, or failed live dispatch queue items can be cancelled before retry.');
        }
        if ((string) ($queue['status'] ?? '') === 'succeeded') {
            throw new RuntimeException('Succeeded live execution queue items cannot be cancelled.');
        }

        $reason = $this->nullableSanitizedText($reason) ?: 'Live dispatch cancelled by a Marketing manager before retry.';
        $readiness = (array) ($queue['readiness_json'] ?? []);
        $readiness['live_dispatch_cancelled'] = true;
        $readiness['live_dispatch_cancelled_at'] = date('c');
        $readiness['live_dispatch_cancelled_by'] = $actorId;
        $readiness['live_dispatch_cancel_reason'] = mb_substr($reason, 0, 255);

        Database::execute(
            "UPDATE marketing_execution_queue
             SET live_dispatch_status = 'cancelled',
                 live_dispatch_run_id = NULL,
                 live_blocked_reason = ?,
                 readiness_json = ?
             WHERE workspace_id = ? AND id = ?",
            [
                mb_substr($reason, 0, 255),
                $this->normalizeJsonValue($readiness),
                $this->workspaceId(),
                $queueId,
            ]
        );
        $this->recordLiveExecutionEvent('live_blocked', 'blocked', [
            'connector_id' => (int) ($queue['connector_id'] ?? 0),
            'queue_id' => $queueId,
            'execution_mode' => 'live',
            'adapter_key' => (string) ($queue['live_adapter_key'] ?? ''),
            'payload' => ['live_dispatch_status' => 'cancelled'],
            'result' => [
                'cancelled' => true,
                'previous_dispatch_status' => $dispatchStatus,
                'reason' => mb_substr($reason, 0, 255),
            ],
            'created_by' => $actorId,
        ]);

        return $this->getExecutionQueueItem($queueId) ?? [];
    }

    public function listLiveRecoveryEvents(array $filters = [], int $limit = 100, int $offset = 0): array
    {
        $this->assertMarketingPermission('marketing.read');
        if (!Database::tableExists('marketing_live_recovery_events')) {
            return [];
        }

        $limit = min(max($limit, 1), 250);
        $offset = max($offset, 0);
        $workspace = $this->workspaceClause('r.');
        $where = [$workspace['sql']];
        $params = $workspace['params'];
        if (!empty($filters['queue_id'])) {
            $where[] = 'r.queue_id = ?';
            $params[] = (int) $filters['queue_id'];
        }
        if (!empty($filters['connector_id'])) {
            $where[] = 'r.connector_id = ?';
            $params[] = (int) $filters['connector_id'];
        }
        if (!empty($filters['action_type'])) {
            $where[] = 'r.action_type = ?';
            $params[] = $this->normalizeEnum((string) $filters['action_type'], self::LIVE_RECOVERY_ACTION_TYPES, 'live_recovery_action_type');
        }
        if (!empty($filters['status'])) {
            $where[] = 'r.status = ?';
            $params[] = $this->normalizeEnum((string) $filters['status'], self::LIVE_RECOVERY_STATUSES, 'live_recovery_status');
        }

        return array_map(
            fn(array $row): array => $this->hydrateJsonFields($row, ['metadata_json']),
            Database::query(
                "SELECT r.*, cc.name AS connector_name, creator.email AS created_by_email
                 FROM marketing_live_recovery_events r
                 LEFT JOIN marketing_channel_connectors cc ON cc.id = r.connector_id AND cc.workspace_id = r.workspace_id
                 LEFT JOIN users creator ON creator.id = r.created_by
                 WHERE " . implode(' AND ', $where) . "
                 ORDER BY r.created_at DESC, r.id DESC
                 LIMIT {$limit} OFFSET {$offset}",
                $params
            )
        );
    }

    public function listLiveRecoveryQueue(string $queue = 'retryable', int $limit = 25, int $offset = 0): array
    {
        $this->assertMarketingPermission('marketing.read');
        if (!Database::tableExists('marketing_execution_queue')) {
            return [];
        }

        $limit = min(max($limit, 1), 100);
        $offset = max($offset, 0);
        $queue = $this->normalizeEnum($queue, ['retryable', 'blocked', 'expired', 'cancelled', 'permanent_failed'], 'live_recovery_queue');
        $where = ["eq.workspace_id = ?", "eq.execution_mode = 'live'"];
        $params = [$this->workspaceId()];
        if ($queue === 'retryable') {
            $where[] = "(eq.status IN ('failed','blocked') OR eq.live_dispatch_status IN ('failed','blocked') OR eq.live_retry_status IN ('scheduled','retrying'))";
            $where[] = "eq.status NOT IN ('succeeded','cancelled','archived')";
        } elseif ($queue === 'blocked') {
            $where[] = "(eq.status = 'blocked' OR eq.live_dispatch_status = 'blocked' OR eq.live_recovery_status = 'blocked')";
        } elseif ($queue === 'expired') {
            $where[] = "eq.live_retry_status = 'scheduled'";
            $where[] = "eq.live_retry_after IS NOT NULL AND eq.live_retry_after < NOW()";
            $where[] = "eq.live_dispatch_status <> 'confirmed'";
        } elseif ($queue === 'cancelled') {
            $where[] = "(eq.status = 'cancelled' OR eq.live_dispatch_status = 'cancelled' OR eq.live_recovery_status = 'cancelled')";
        } else {
            $where[] = "(eq.live_retry_status = 'exhausted' OR eq.live_recovery_status = 'permanent_failed')";
        }

        return array_map(
            fn(array $row): array => $this->hydrateExecutionQueueRow($row),
            Database::query(
                "SELECT eq.*, cc.name AS connector_name, cc.status AS connector_status, cc.connector_type,
                        requester.email AS requested_by_email, creator.email AS created_by_email,
                        (SELECT COUNT(*) FROM marketing_execution_attempts ea WHERE ea.workspace_id = eq.workspace_id AND ea.queue_id = eq.id) AS attempt_count,
                        (SELECT ea.status FROM marketing_execution_attempts ea WHERE ea.workspace_id = eq.workspace_id AND ea.queue_id = eq.id ORDER BY ea.created_at DESC LIMIT 1) AS last_attempt_status
                 FROM marketing_execution_queue eq
                 LEFT JOIN marketing_channel_connectors cc ON cc.id = eq.connector_id AND cc.workspace_id = eq.workspace_id
                 LEFT JOIN users requester ON requester.id = eq.requested_by
                 LEFT JOIN users creator ON creator.id = eq.created_by
                 WHERE " . implode(' AND ', $where) . "
                 ORDER BY eq.updated_at DESC, eq.id DESC
                 LIMIT {$limit} OFFSET {$offset}",
                $params
            )
        );
    }

    public function requestLiveQueueRecovery(int $queueId, string $requestedAction, string $reason, int $userId): array
    {
        $this->assertMarketingPermission('marketing.write');
        $queue = $this->assertLiveRecoveryQueue($queueId);
        $actorId = $this->normalizeLiveRecoveryActor($userId);
        $requestedAction = $this->normalizeEnum($requestedAction, self::LIVE_RECOVERY_ACTION_TYPES, 'live_recovery_requested_action');
        if ($requestedAction === 'request_recovery') {
            $requestedAction = 'retry';
        }
        $reason = $this->nullableSanitizedText($reason) ?: 'Recovery requested by marketing operator.';
        $metadata = [
            'requested_action' => $requestedAction,
            'requested_by_role' => 'writer_or_manager',
            'secret_safe' => true,
            'raw_secret_values_visible' => false,
        ];
        $this->recordLiveRecoveryEvent($queue, 'request_recovery', 'requested', $reason, $metadata, $actorId);
        $this->updateLiveRecoveryQueueState($queueId, [
            'live_recovery_status' => 'requested',
            'live_recovery_reason' => mb_substr($reason, 0, 500),
            'live_recovery_json' => $this->normalizeJsonValue($metadata),
        ]);

        return $this->getExecutionQueueItem($queueId) ?? [];
    }

    public function recoverLiveQueueItem(int $queueId, string $action, array $data, int $userId): array
    {
        $this->assertMarketingPermission('marketing.manage');
        $queue = $this->assertLiveRecoveryQueue($queueId);
        $actorId = $this->normalizeLiveRecoveryActor($userId);
        $action = $this->normalizeEnum($action, self::LIVE_RECOVERY_ACTION_TYPES, 'live_recovery_action');
        if ($action === 'request_recovery') {
            throw new \InvalidArgumentException('Use requestLiveQueueRecovery for writer recovery requests.');
        }

        $reason = $this->nullableSanitizedText($data['reason'] ?? $data['note'] ?? '') ?: 'Live recovery action applied by a Marketing manager.';
        $metadata = [
            'action' => $action,
            'secret_safe' => true,
            'raw_secret_values_visible' => false,
        ];

        try {
            if ($action === 'retry') {
                $updated = $this->recoverLiveQueueRetry($queue, $data, $actorId, $reason, $metadata);
            } elseif ($action === 'reschedule') {
                $updated = $this->recoverLiveQueueReschedule($queue, $data, $actorId, $reason, $metadata);
            } elseif ($action === 'cancel') {
                $updated = $this->recoverLiveQueueCancel($queue, $actorId, $reason, $metadata);
            } elseif ($action === 'pause_connector') {
                $updated = $this->recoverLiveQueuePauseConnector($queue, $actorId, $reason, $metadata);
            } elseif ($action === 'rerun_preflight') {
                $updated = $this->recoverLiveQueueRerunPreflight($queue, $actorId, $reason, $metadata);
            } elseif ($action === 'recheck_suppression') {
                $updated = $this->recoverLiveQueueRecheckSuppression($queue, $actorId, $reason, $metadata);
            } else {
                $updated = $this->recoverLiveQueueOperatorNote($queue, $actorId, $reason, $metadata);
            }

            $this->recordLiveRecoveryEvent($queue, $action, 'completed', $reason, $metadata, $actorId, $updated);

            return $updated;
        } catch (Throwable $e) {
            $metadata['error_class'] = get_class($e);
            $metadata['error_message'] = mb_substr(Security::sanitizeInput($e->getMessage(), 'string'), 0, 500);
            $this->recordLiveRecoveryEvent($queue, $action, 'blocked', $reason, $metadata, $actorId);
            throw $e;
        }
    }

    private function assertLiveRecoveryQueue(int $queueId): array
    {
        if (!Database::tableExists('marketing_execution_queue')) {
            throw new RuntimeException('Marketing execution queue is unavailable.');
        }
        $queue = $this->getExecutionQueueItem($queueId);
        if (!$queue) {
            throw new RuntimeException('Marketing execution queue item not found.');
        }
        if ((string) ($queue['execution_mode'] ?? '') !== 'live') {
            throw new \InvalidArgumentException('Only live execution queue items can use live recovery controls.');
        }

        return $queue;
    }

    private function normalizeLiveRecoveryActor(int $userId): ?int
    {
        $actorId = $userId > 0 ? $userId : ($this->currentUserId() ?: null);
        if ($actorId !== null) {
            $this->assertWorkspaceUser($actorId, $this->workspaceId());
        }

        return $actorId;
    }

    private function recoverLiveQueueRetry(array $queue, array $data, ?int $actorId, string $reason, array &$metadata): array
    {
        if ((string) ($queue['status'] ?? '') === 'succeeded') {
            throw new RuntimeException('Succeeded live execution queue items cannot be retried.');
        }
        if ((string) ($queue['status'] ?? '') === 'cancelled' || (string) ($queue['live_dispatch_status'] ?? '') === 'cancelled') {
            throw new RuntimeException('Cancelled live execution queue items cannot be retried.');
        }
        $policy = $this->getMarketingLiveExecutionPolicy();
        if (!empty($policy['emergency_paused'])) {
            throw new RuntimeException('Live recovery retry is blocked by the workspace emergency stop.');
        }
        $maxRetries = max(0, min(25, (int) ($queue['live_max_retries'] ?? 0)));
        $currentRetryCount = max(0, (int) ($queue['live_retry_count'] ?? 0));
        if ($maxRetries <= 0 || $currentRetryCount >= $maxRetries) {
            $this->updateLiveRecoveryQueueState((int) $queue['id'], [
                'live_retry_status' => 'exhausted',
                'live_recovery_status' => 'permanent_failed',
                'live_recovery_reason' => 'Maximum live retry attempts are exhausted.',
                'live_recovery_json' => $this->normalizeJsonValue($metadata + ['max_retries' => $maxRetries, 'current_retry_count' => $currentRetryCount]),
            ]);
            throw new RuntimeException('Maximum live retry attempts are exhausted.');
        }

        $retryAfter = $this->normalizeDateTime((string) ($data['scheduled_at'] ?? $data['retry_after'] ?? ''));
        if ($retryAfter === null) {
            $retryAfter = date('Y-m-d H:i:s');
        }
        $nextRetryCount = $currentRetryCount + 1;
        $metadata['next_retry_count'] = $nextRetryCount;
        $metadata['retry_after'] = $retryAfter;

        $this->updateLiveRecoveryQueueState((int) $queue['id'], [
            'status' => 'queued',
            'scheduled_at' => $retryAfter,
            'live_dispatch_status' => 'confirmed',
            'live_dispatch_run_id' => null,
            'live_retry_status' => 'scheduled',
            'live_retry_count' => $nextRetryCount,
            'live_retry_after' => $retryAfter,
            'live_retry_reason' => mb_substr($reason, 0, 500),
            'live_retry_json' => $this->normalizeJsonValue($metadata),
            'live_recovery_status' => 'retry_scheduled',
            'live_recovery_reason' => mb_substr($reason, 0, 500),
            'live_recovery_json' => $this->normalizeJsonValue($metadata),
            'live_blocked_reason' => null,
        ]);

        return $this->getExecutionQueueItem((int) $queue['id']) ?? [];
    }

    private function recoverLiveQueueReschedule(array $queue, array $data, ?int $actorId, string $reason, array &$metadata): array
    {
        if ((string) ($queue['status'] ?? '') === 'cancelled' || (string) ($queue['live_dispatch_status'] ?? '') === 'cancelled') {
            throw new RuntimeException('Cancelled live execution queue items cannot be rescheduled.');
        }
        $scheduledAt = $this->normalizeDateTime((string) ($data['scheduled_at'] ?? ''));
        if ($scheduledAt === null) {
            throw new \InvalidArgumentException('A valid recovery schedule date is required.');
        }
        $metadata['scheduled_at'] = $scheduledAt;
        $this->updateLiveRecoveryQueueState((int) $queue['id'], [
            'status' => in_array((string) ($queue['status'] ?? ''), ['failed', 'blocked'], true) ? 'queued' : (string) ($queue['status'] ?? 'queued'),
            'scheduled_at' => $scheduledAt,
            'live_retry_after' => $scheduledAt,
            'live_dispatch_status' => 'confirmed',
            'live_recovery_status' => 'rescheduled',
            'live_recovery_reason' => mb_substr($reason, 0, 500),
            'live_recovery_json' => $this->normalizeJsonValue($metadata),
            'live_blocked_reason' => null,
        ]);

        return $this->getExecutionQueueItem((int) $queue['id']) ?? [];
    }

    private function recoverLiveQueueCancel(array $queue, ?int $actorId, string $reason, array &$metadata): array
    {
        if ((string) ($queue['status'] ?? '') === 'succeeded') {
            throw new RuntimeException('Succeeded live execution queue items cannot be cancelled.');
        }
        $metadata['cancelled'] = true;
        $readiness = (array) ($queue['readiness_json'] ?? []);
        $readiness['live_recovery_cancelled'] = true;
        $readiness['live_recovery_cancelled_at'] = date('c');
        $readiness['live_recovery_cancelled_by'] = $actorId;

        $this->updateLiveRecoveryQueueState((int) $queue['id'], [
            'status' => 'cancelled',
            'live_dispatch_status' => 'cancelled',
            'live_retry_status' => 'cancelled',
            'live_retry_after' => null,
            'live_recovery_status' => 'cancelled',
            'live_recovery_reason' => mb_substr($reason, 0, 500),
            'live_recovery_json' => $this->normalizeJsonValue($metadata),
            'live_blocked_reason' => mb_substr($reason, 0, 500),
            'readiness_json' => $this->normalizeJsonValue($readiness),
        ]);

        return $this->getExecutionQueueItem((int) $queue['id']) ?? [];
    }

    private function recoverLiveQueuePauseConnector(array $queue, ?int $actorId, string $reason, array &$metadata): array
    {
        $connectorId = (int) ($queue['connector_id'] ?? 0);
        if ($connectorId <= 0) {
            throw new RuntimeException('This live queue item has no connector to pause.');
        }
        $this->assertWorkspaceRecord('marketing_channel_connectors', $connectorId, $this->workspaceId());
        Database::execute(
            "UPDATE marketing_channel_connectors
             SET status = 'blocked',
                 live_enabled = 0,
                 live_preflight_status = 'blocked',
                 live_preflight_json = ?,
                 updated_at = NOW()
             WHERE workspace_id = ? AND id = ?",
            [
                $this->normalizeJsonValue([
                    'paused_by_recovery' => true,
                    'reason' => mb_substr($reason, 0, 500),
                    'paused_by' => $actorId,
                    'secret_safe' => true,
                ]),
                $this->workspaceId(),
                $connectorId,
            ]
        );
        $metadata['connector_paused'] = true;
        $metadata['connector_id'] = $connectorId;
        $this->updateLiveRecoveryQueueState((int) $queue['id'], [
            'live_recovery_status' => 'blocked',
            'live_recovery_reason' => mb_substr($reason, 0, 500),
            'live_recovery_json' => $this->normalizeJsonValue($metadata),
            'live_blocked_reason' => 'Connector paused by live recovery.',
        ]);

        return $this->getExecutionQueueItem((int) $queue['id']) ?? [];
    }

    private function recoverLiveQueueRerunPreflight(array $queue, ?int $actorId, string $reason, array &$metadata): array
    {
        $connectorId = (int) ($queue['connector_id'] ?? 0);
        if ($connectorId <= 0) {
            throw new RuntimeException('This live queue item has no connector for preflight.');
        }
        $preflight = $this->runChannelConnectorTest($connectorId, [
            'test_mode' => 'live_preflight',
            'created_by' => $actorId,
        ]);
        $metadata['preflight_status'] = (string) ($preflight['status'] ?? 'unknown');
        $metadata['preflight_id'] = (int) ($preflight['id'] ?? 0);
        $this->updateLiveRecoveryQueueState((int) $queue['id'], [
            'live_recovery_status' => (string) ($preflight['status'] ?? '') === 'passed' ? 'none' : 'blocked',
            'live_recovery_reason' => mb_substr($reason, 0, 500),
            'live_recovery_json' => $this->normalizeJsonValue($metadata),
            'live_blocked_reason' => (string) ($preflight['status'] ?? '') === 'passed' ? null : 'Connector live preflight still blocked.',
        ]);

        return $this->getExecutionQueueItem((int) $queue['id']) ?? [];
    }

    private function recoverLiveQueueRecheckSuppression(array $queue, ?int $actorId, string $reason, array &$metadata): array
    {
        $recipient = $this->liveRecoveryRecipientFromQueue($queue);
        $blocked = $recipient !== '' && $this->isMarketingRecipientSuppressed($recipient, (string) ($queue['execution_type'] ?? 'email'));
        $metadata['recipient_preview'] = $this->recipientPreview($recipient);
        $metadata['suppression_result'] = $blocked ? 'blocked' : 'clear';
        $fields = [
            'status' => $blocked ? 'blocked' : (string) ($queue['status'] ?? 'queued'),
            'live_dispatch_status' => $blocked ? 'blocked' : (string) ($queue['live_dispatch_status'] ?? 'not_ready'),
            'live_recovery_status' => $blocked ? 'blocked' : 'none',
            'live_recovery_reason' => mb_substr($reason, 0, 500),
            'live_recovery_json' => $this->normalizeJsonValue($metadata),
            'live_blocked_reason' => $blocked ? 'Recipient is actively suppressed.' : null,
        ];
        if (Database::columnExists('marketing_execution_queue', 'live_suppression_result')) {
            $fields['live_suppression_checked_at'] = date('Y-m-d H:i:s');
            $fields['live_suppression_result'] = $blocked ? 'blocked' : 'clear';
            $fields['live_suppression_blocked_reason'] = $blocked ? 'Recipient is actively suppressed.' : null;
            $fields['live_consent_evidence_json'] = $this->normalizeJsonValue([
                'source' => 'recovery_recheck_suppression',
                'recipient_preview' => $this->recipientPreview($recipient),
                'suppression_result' => $blocked ? 'blocked' : 'clear',
                'checked_at' => date('c'),
                'secret_safe' => true,
            ]);
        }
        $this->updateLiveRecoveryQueueState((int) $queue['id'], $fields);

        return $this->getExecutionQueueItem((int) $queue['id']) ?? [];
    }

    private function recoverLiveQueueOperatorNote(array $queue, ?int $actorId, string $reason, array &$metadata): array
    {
        $this->updateLiveRecoveryQueueState((int) $queue['id'], [
            'live_recovery_status' => (string) ($queue['live_recovery_status'] ?? 'none') ?: 'none',
            'live_recovery_reason' => mb_substr($reason, 0, 500),
            'live_recovery_json' => $this->normalizeJsonValue($metadata),
        ]);

        return $this->getExecutionQueueItem((int) $queue['id']) ?? [];
    }

    private function liveRecoveryRecipientFromQueue(array $queue): string
    {
        $payload = (array) ($queue['payload_json'] ?? []);
        foreach (['recipient', 'to', 'email', 'phone', 'target_recipient'] as $key) {
            if (!empty($payload[$key]) && is_scalar($payload[$key])) {
                return trim((string) $payload[$key]);
            }
        }

        return '';
    }

    private function isMarketingRecipientSuppressed(string $recipient, string $channel): bool
    {
        if ($recipient === '' || !Database::tableExists('marketing_suppression_entries')) {
            return false;
        }
        $channel = in_array($channel, ['email', 'sms', 'whatsapp'], true) ? $channel : 'email';

        return $this->isMarketingIdentifierSuppressed($channel, $recipient);
    }

    private function updateLiveRecoveryQueueState(int $queueId, array $fields): void
    {
        if (!Database::columnExists('marketing_execution_queue', 'live_recovery_status')) {
            return;
        }
        $allowed = [
            'status',
            'scheduled_at',
            'readiness_json',
            'live_dispatch_status',
            'live_dispatch_run_id',
            'live_retry_status',
            'live_retry_count',
            'live_retry_after',
            'live_retry_reason',
            'live_retry_json',
            'live_recovery_status',
            'live_recovery_reason',
            'live_recovery_json',
            'live_blocked_reason',
            'live_consent_basis',
            'live_unsubscribe_evidence_json',
            'live_suppression_checked_at',
            'live_suppression_result',
            'live_suppression_blocked_reason',
            'live_consent_evidence_json',
        ];
        $updates = [];
        $params = [];
        foreach ($allowed as $field) {
            if (array_key_exists($field, $fields)) {
                $updates[] = $field . ' = ?';
                $params[] = $fields[$field];
            }
        }
        if ($updates === []) {
            return;
        }
        $params[] = $this->workspaceId();
        $params[] = $queueId;
        Database::execute(
            "UPDATE marketing_execution_queue
             SET " . implode(', ', $updates) . ", updated_at = NOW()
             WHERE workspace_id = ? AND id = ?",
            $params
        );
    }

    private function recordLiveRecoveryEvent(array $queue, string $action, string $status, string $reason, array $metadata, ?int $actorId, ?array $updatedQueue = null): void
    {
        if (!Database::tableExists('marketing_live_recovery_events')) {
            return;
        }
        $action = $this->normalizeEnum($action, self::LIVE_RECOVERY_ACTION_TYPES, 'live_recovery_action');
        $status = $this->normalizeEnum($status, self::LIVE_RECOVERY_STATUSES, 'live_recovery_event_status');
        Database::execute(
            "INSERT INTO marketing_live_recovery_events
             (workspace_id, uuid, queue_id, connector_id, action_type, status, previous_queue_status,
              previous_dispatch_status, next_queue_status, next_dispatch_status, scheduled_at, reason,
              metadata_json, created_by)
             VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)",
            [
                $this->workspaceId(),
                $this->generateUuid(),
                (int) ($queue['id'] ?? 0),
                !empty($queue['connector_id']) ? (int) $queue['connector_id'] : null,
                $action,
                $status,
                (string) ($queue['status'] ?? ''),
                (string) ($queue['live_dispatch_status'] ?? ''),
                $updatedQueue !== null ? (string) ($updatedQueue['status'] ?? '') : null,
                $updatedQueue !== null ? (string) ($updatedQueue['live_dispatch_status'] ?? '') : null,
                $updatedQueue !== null ? ($updatedQueue['scheduled_at'] ?? null) : null,
                mb_substr($reason, 0, 1000),
                $this->normalizeJsonValue($this->sanitizeJsonCompatible($metadata)),
                $actorId,
            ]
        );
    }

    public function runLiveExecutionDispatcher(array $options = []): array
    {
        $this->assertMarketingPermission('marketing.manage');
        if (!Database::tableExists('marketing_live_queue_dispatch_runs') || !Database::columnExists('marketing_execution_queue', 'live_dispatch_status')) {
            throw new RuntimeException('Marketing live dispatch controls are unavailable.');
        }
        $source = $this->normalizeEnum((string) ($options['source'] ?? 'manual'), self::LIVE_EMAIL_WORKER_RUN_SOURCES, 'live_dispatch_source');
        $limit = min(max((int) ($options['limit'] ?? $options['limit_count'] ?? 25), 1), 100);
        $actorId = (int) ($options['requested_by'] ?? $options['created_by'] ?? $this->currentUserId()) ?: null;
        if ($actorId !== null) {
            $this->assertWorkspaceUser($actorId, $this->workspaceId());
        }
        $schedule = $this->liveQueueDispatcherScheduleSnapshot();
        $limit = min($limit, max(1, (int) ($schedule['max_handoffs_per_run'] ?? $limit)));
        $scheduleBlockers = $this->liveQueueDispatcherScheduleBlockers($schedule, $source);
        $leaseTtlSeconds = min(max((int) ($options['lease_ttl_seconds'] ?? 300), 60), 3600);
        $lease = null;
        $leaseAcquired = false;

        Database::execute(
            "INSERT INTO marketing_live_queue_dispatch_runs
             (workspace_id, uuid, source, status, limit_count, requested_by, started_at)
             VALUES (?, ?, ?, 'running', ?, ?, NOW())",
            [$this->workspaceId(), $this->generateUuid(), $source, $limit, $actorId]
        );
        $runId = (int) Database::lastInsertId();
        $summary = [
            'run_id' => $runId,
            'source' => $source,
            'limit_count' => $limit,
            'processed' => [],
            'skipped' => [],
            'schedule' => $schedule,
            'schedule_blockers' => $scheduleBlockers,
            'lease' => null,
            'external_execution_requires_adapter' => true,
            'raw_secret_values_visible' => false,
        ];
        $processed = 0;
        $succeeded = 0;
        $failed = 0;
        $blocked = 0;
        $skipped = 0;

        try {
            if ($scheduleBlockers !== []) {
                $summary['skipped'][] = 'live_dispatcher_schedule_blocked';
                Database::execute(
                    "UPDATE marketing_live_queue_dispatch_runs
                     SET status = 'blocked',
                         processed_count = 0,
                         succeeded_count = 0,
                         failed_count = 0,
                         blocked_count = 0,
                         skipped_count = 1,
                         result_json = ?,
                         error_message = ?,
                         completed_at = NOW()
                     WHERE workspace_id = ? AND id = ?",
                    [
                        $this->normalizeJsonValue($summary),
                        'Marketing live queue dispatcher schedule blocked: ' . implode(', ', $scheduleBlockers),
                        $this->workspaceId(),
                        $runId,
                    ]
                );
                $this->getLiveQueueDispatcherHealth(true, $actorId);

                return $this->listLiveQueueDispatchRuns(['id' => $runId], 1, 0)[0] ?? ['id' => $runId, 'result_json' => $summary];
            }

            $lease = $this->acquireLiveQueueDispatcherLease(
                $runId,
                $source,
                $leaseTtlSeconds,
                !empty($options['force_lease'])
            );
            $summary['lease'] = $lease;
            if (empty($lease['acquired'])) {
                $summary['skipped'][] = 'live_dispatcher_lease_active';
                $summary['lease_blocked'] = true;
                Database::execute(
                    "UPDATE marketing_live_queue_dispatch_runs
                     SET status = 'blocked',
                         processed_count = 0,
                         succeeded_count = 0,
                         failed_count = 0,
                         blocked_count = 0,
                         skipped_count = 1,
                         result_json = ?,
                         error_message = ?,
                         completed_at = NOW()
                     WHERE workspace_id = ? AND id = ?",
                    [
                        $this->normalizeJsonValue($summary),
                        'Another Marketing live queue dispatcher lease is active for this workspace.',
                        $this->workspaceId(),
                        $runId,
                    ]
                );
                $this->getLiveQueueDispatcherHealth(true, $actorId);

                return $this->listLiveQueueDispatchRuns(['id' => $runId], 1, 0)[0] ?? ['id' => $runId, 'result_json' => $summary];
            }
            $leaseAcquired = true;

            $queues = Database::query(
                "SELECT id
                 FROM marketing_execution_queue
                 WHERE workspace_id = ?
                   AND execution_mode = 'live'
                   AND live_dispatch_status = 'confirmed'
                   AND status IN ('approved','queued')
                   AND (scheduled_at IS NULL OR scheduled_at <= NOW())
                   AND (live_retry_after IS NULL OR live_retry_after <= NOW())
                 ORDER BY CASE WHEN scheduled_at IS NULL THEN 1 ELSE 0 END ASC, scheduled_at ASC, id ASC
                 LIMIT {$limit}",
                [$this->workspaceId()]
            );

            foreach ($queues as $queueRef) {
                $queueId = (int) ($queueRef['id'] ?? 0);
                if ($queueId <= 0) {
                    continue;
                }
                $this->heartbeatLiveQueueDispatcherLease($runId, (string) ($lease['lease_token'] ?? ''), $leaseTtlSeconds);
                Database::execute(
                    "UPDATE marketing_execution_queue
                     SET live_dispatch_status = 'dispatched',
                         live_retry_status = CASE WHEN live_retry_status = 'scheduled' THEN 'retrying' ELSE live_retry_status END,
                         live_dispatch_run_id = ?
                     WHERE workspace_id = ? AND id = ?",
                    [$runId, $this->workspaceId(), $queueId]
                );

                $attempt = $this->runExecutionQueueItem($queueId, [
                    'attempt_mode' => 'live',
                    'live_confirmation' => 'RUN LIVE',
                    'created_by' => $actorId,
                    'dispatch_run_id' => $runId,
                ]);
                $attemptStatus = (string) ($attempt['status'] ?? '');
                $processed++;
                if ($attemptStatus === 'success') {
                    $succeeded++;
                    $dispatchStatus = 'completed';
                } elseif ($attemptStatus === 'blocked') {
                    $blocked++;
                    $dispatchStatus = 'blocked';
                } else {
                    $failed++;
                    $dispatchStatus = 'failed';
                }
                Database::execute(
                    "UPDATE marketing_execution_queue
                     SET live_dispatch_status = ?,
                         live_dispatch_run_id = ?
                     WHERE workspace_id = ? AND id = ?",
                    [$dispatchStatus, $runId, $this->workspaceId(), $queueId]
                );
                $summary['processed'][] = [
                    'queue_id' => $queueId,
                    'attempt_id' => (int) ($attempt['id'] ?? 0),
                    'attempt_status' => $attemptStatus,
                    'dispatch_status' => $dispatchStatus,
                    'blocked_reasons' => (array) ($attempt['result_json']['blocked_reasons'] ?? []),
                ];
                $this->heartbeatLiveQueueDispatcherLease($runId, (string) ($lease['lease_token'] ?? ''), $leaseTtlSeconds);
            }

            if ($processed === 0) {
                $skipped = 0;
                $summary['skipped'][] = 'no_due_confirmed_live_queue_items';
            }
            $status = 'completed';
            if ($processed > 0 && $succeeded === 0 && $failed > 0 && $blocked === 0) {
                $status = 'failed';
            } elseif ($processed > 0 && $succeeded === 0 && $blocked > 0 && $failed === 0) {
                $status = 'blocked';
            } elseif ($failed > 0 || $blocked > 0) {
                $status = 'completed_with_errors';
            }

            Database::execute(
                "UPDATE marketing_live_queue_dispatch_runs
                 SET status = ?,
                     processed_count = ?,
                     succeeded_count = ?,
                     failed_count = ?,
                     blocked_count = ?,
                     skipped_count = ?,
                     result_json = ?,
                     completed_at = NOW()
                 WHERE workspace_id = ? AND id = ?",
                [
                    $status,
                    $processed,
                    $succeeded,
                    $failed,
                    $blocked,
                    $skipped,
                    $this->normalizeJsonValue($summary),
                    $this->workspaceId(),
                    $runId,
                ]
            );
            $this->markLiveEmailWorkerScheduleConfirmed(self::LIVE_QUEUE_DISPATCHER_WORKER_KEY, $source, $actorId);
            $this->getLiveQueueDispatcherHealth(true, $actorId);
        } catch (Throwable $e) {
            $summary['error'] = $e->getMessage();
            Database::execute(
                "UPDATE marketing_live_queue_dispatch_runs
                 SET status = 'failed',
                     processed_count = ?,
                     succeeded_count = ?,
                     failed_count = ?,
                     blocked_count = ?,
                     skipped_count = ?,
                     result_json = ?,
                     error_message = ?,
                     completed_at = NOW()
                 WHERE workspace_id = ? AND id = ?",
                [
                    $processed,
                    $succeeded,
                    $failed,
                    $blocked,
                    $skipped,
                    $this->normalizeJsonValue($summary),
                    $e->getMessage(),
                    $this->workspaceId(),
                    $runId,
                ]
            );
            throw $e;
        } finally {
            if ($leaseAcquired && is_array($lease)) {
                $this->releaseLiveQueueDispatcherLease($runId, (string) ($lease['lease_token'] ?? ''), 'released');
            }
        }

        return $this->listLiveQueueDispatchRuns(['id' => $runId], 1, 0)[0] ?? ['id' => $runId, 'result_json' => $summary];
    }

    public function runExecutionQueueItem(int $queueId, array $input = []): array
    {
        $this->assertMarketingPermission('marketing.write');
        $attemptStartedAt = microtime(true);
        $queue = $this->getExecutionQueueItem($queueId);
        if (!$queue) {
            throw new RuntimeException('Marketing execution queue item not found.');
        }
        $requestedMode = $this->normalizeEnum((string) ($input['attempt_mode'] ?? $queue['execution_mode'] ?? 'dry_run'), self::EXECUTION_MODES, 'execution_mode');
        if ($requestedMode === 'live') {
            $this->assertMarketingPermission('marketing.manage');
        }
        $connector = !empty($queue['connector_id']) ? $this->getChannelConnector((int) $queue['connector_id']) : null;
        $approval = Database::tableExists('marketing_execution_approvals')
            ? Database::queryOne(
                "SELECT * FROM marketing_execution_approvals WHERE workspace_id = ? AND queue_id = ? ORDER BY created_at DESC LIMIT 1",
                [$this->workspaceId(), $queueId]
            )
            : null;
        $readiness = $this->executionQueueReadiness($queue, $connector, $approval, $requestedMode);
        $liveControl = $requestedMode === 'live' ? $this->liveRunControlReadiness($queue, $input) : [];
        if ($requestedMode === 'live' && empty($liveControl['ready'])) {
            $readiness['ready'] = false;
            $readiness['blocked_reasons'] = array_values(array_unique(array_merge(
                (array) ($readiness['blocked_reasons'] ?? []),
                (array) ($liveControl['blocked_reasons'] ?? [])
            )));
            $readiness['live_control'] = $liveControl;
        } elseif ($requestedMode === 'live') {
            $readiness['live_control'] = $liveControl;
            $input['live_idempotency_key'] = (string) ($liveControl['idempotency_key'] ?? '');
        }
        $liveAdapterResult = [];
        if ($requestedMode === 'live' && !empty($readiness['ready']) && $connector !== null) {
            $liveAdapterResult = $this->executeMarketingLiveAdapter($queue, $connector, $input);
        }
        $attemptStatus = $readiness['ready']
            ? ($requestedMode === 'live' ? (!empty($liveAdapterResult['success']) ? 'success' : 'failed') : 'dry_run')
            : 'blocked';
        $queueStatus = match ($attemptStatus) {
            'success' => 'succeeded',
            'failed' => 'failed',
            'dry_run' => 'succeeded',
            default => 'blocked',
        };
        if (
            $attemptStatus === 'blocked'
            && $requestedMode === 'live'
            && (string) ($queue['status'] ?? '') === 'succeeded'
            && in_array('live_success_already_recorded', (array) ($readiness['blocked_reasons'] ?? []), true)
        ) {
            $queueStatus = 'succeeded';
        }
        $result = [
            'queue_id' => $queueId,
            'attempt_mode' => $requestedMode,
            'external_execution' => false,
            'dry_run_only' => $requestedMode !== 'live',
            'live_execution' => $requestedMode === 'live',
            'ready' => (bool) $readiness['ready'],
            'blocked_reasons' => (array) $readiness['blocked_reasons'],
            'live_control' => $requestedMode === 'live' ? $liveControl : [],
            'idempotency_key' => $requestedMode === 'live' ? (string) ($liveControl['idempotency_key'] ?? '') : null,
            'adapter_result' => $liveAdapterResult,
            'message' => $requestedMode === 'live'
                ? (string) ($liveAdapterResult['message'] ?? 'Live execution remains blocked until policy, connector, approval, and adapter are ready.')
                : 'Dry-run/test execution completed with no external send or publish.',
        ];
        $adapterEvidence = $this->buildLiveAdapterAttemptEvidence(
            $queue,
            $connector ?? [],
            $requestedMode,
            $attemptStatus,
            $readiness,
            $liveControl,
            $liveAdapterResult,
            $input,
            (int) round((microtime(true) - $attemptStartedAt) * 1000)
        );
        if ($requestedMode === 'live') {
            $result['adapter_evidence'] = [
                'adapter_key' => $adapterEvidence['adapter_key'],
                'provider_reference' => $adapterEvidence['provider_reference'],
                'failure_class' => $adapterEvidence['failure_class'],
                'duration_ms' => $adapterEvidence['duration_ms'],
                'secret_safe' => true,
            ];
        }
        Database::execute(
            "INSERT INTO marketing_execution_attempts
             (workspace_id, queue_id, connector_id, uuid, status, attempt_mode, adapter_key,
              provider_reference, failure_class, duration_ms, request_evidence_json, response_evidence_json,
              adapter_contract_json, idempotency_key, live_confirmation_text, result_json, error_message,
              started_at, completed_at, created_by)
             VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, NOW(), NOW(), ?)",
            [
                $this->workspaceId(),
                $queueId,
                !empty($queue['connector_id']) ? (int) $queue['connector_id'] : null,
                $this->generateUuid(),
                $attemptStatus,
                $requestedMode,
                $adapterEvidence['adapter_key'],
                $adapterEvidence['provider_reference'],
                $adapterEvidence['failure_class'],
                $adapterEvidence['duration_ms'],
                $this->normalizeJsonValue($adapterEvidence['request']),
                $this->normalizeJsonValue($adapterEvidence['response']),
                $this->normalizeJsonValue($adapterEvidence['contract']),
                $requestedMode === 'live' ? (string) ($liveControl['idempotency_key'] ?? '') ?: null : null,
                $requestedMode === 'live' ? (string) ($liveControl['confirmation_text'] ?? '') ?: null : null,
                $this->normalizeJsonValue($result),
                $attemptStatus === 'blocked' ? implode(', ', (array) $readiness['blocked_reasons']) : null,
                (int) ($input['created_by'] ?? $this->currentUserId()) ?: null,
            ]
        );
        $attemptId = (int) Database::lastInsertId();
        if ($requestedMode === 'live' && $connector !== null && in_array($attemptStatus, ['success', 'failed'], true)) {
            $freshConnector = $this->getChannelConnector((int) ($connector['id'] ?? 0)) ?: $connector;
            $throttleAfterAttempt = $this->connectorLiveThrottleSnapshot($freshConnector);
            $throttleAfterAttempt['last_attempt_status'] = $attemptStatus;
            $throttleAfterAttempt['last_attempt_id'] = $attemptId;
            Database::execute(
                "UPDATE marketing_channel_connectors
                 SET last_live_attempt_at = NOW(),
                     live_throttle_json = ?
                 WHERE workspace_id = ? AND id = ?",
                [
                    $this->normalizeJsonValue($throttleAfterAttempt),
                    $this->workspaceId(),
                    (int) ($connector['id'] ?? 0),
                ]
            );
            $readiness['connector_live_throttle_after_attempt'] = $throttleAfterAttempt;
        }
        $liveRetryPlan = [];
        $liveRetryUpdate = [];
        if ($requestedMode === 'live' && $attemptStatus === 'failed') {
            $liveRetryPlan = $this->buildLiveRetryPlanAfterFailedAttempt($queue, $attemptId, $liveAdapterResult, $readiness);
            $liveRetryUpdate = (array) ($liveRetryPlan['queue_update'] ?? []);
            $readiness['live_retry_plan'] = $liveRetryPlan['summary'] ?? [];
            if ((string) ($liveRetryPlan['status'] ?? '') === 'scheduled') {
                $queueStatus = 'queued';
            }
        } elseif ($requestedMode === 'live' && $attemptStatus === 'success' && Database::columnExists('marketing_execution_queue', 'live_retry_status')) {
            $liveRetryUpdate = [
                'live_retry_status' => 'none',
                'live_retry_after' => null,
                'live_retry_reason' => null,
            ];
        }
        $queueUpdate = [
            'status' => $queueStatus,
            'readiness_json' => $this->normalizeJsonValue($readiness),
            'live_policy_snapshot_json' => $requestedMode === 'live' ? $this->normalizeJsonValue((array) ($readiness['policy'] ?? [])) : null,
            'live_blocked_reason' => $attemptStatus === 'blocked' ? implode(', ', (array) $readiness['blocked_reasons']) : null,
            'live_approved_at' => $requestedMode === 'live' && (string) ($approval['status'] ?? '') === 'approved' ? date('Y-m-d H:i:s') : null,
        ];
        if ($requestedMode === 'live' && !empty($liveControl['confirmation_valid'])) {
            $queueUpdate['live_last_confirmed_at'] = date('Y-m-d H:i:s');
            $queueUpdate['live_last_confirmed_by'] = (int) ($input['created_by'] ?? $this->currentUserId()) ?: null;
            $queueUpdate['live_last_confirmation_text'] = (string) ($liveControl['confirmation_text'] ?? '');
        }
        if ($requestedMode === 'live' && Database::columnExists('marketing_execution_queue', 'live_suppression_result')) {
            $consentSuppression = (array) ($readiness['consent_suppression'] ?? []);
            $queueUpdate['live_consent_basis'] = !empty($consentSuppression['consent_basis'])
                ? mb_substr(Security::sanitizeInput((string) $consentSuppression['consent_basis'], 'string'), 0, 120)
                : null;
            $queueUpdate['live_unsubscribe_evidence_json'] = $this->normalizeJsonValue($this->sanitizeJsonCompatible((array) ($consentSuppression['unsubscribe_evidence'] ?? [])));
            $queueUpdate['live_suppression_checked_at'] = date('Y-m-d H:i:s');
            $queueUpdate['live_suppression_result'] = $this->normalizeEnum(
                (string) ($consentSuppression['suppression_result'] ?? 'not_checked'),
                ['not_checked', 'clear', 'blocked', 'warning'],
                'live_suppression_result'
            );
            $blockedReasons = (array) ($consentSuppression['blocked_reasons'] ?? []);
            $queueUpdate['live_suppression_blocked_reason'] = $blockedReasons !== []
                ? mb_substr(implode(', ', array_unique(array_map('strval', $blockedReasons))), 0, 1000)
                : null;
            $queueUpdate['live_consent_evidence_json'] = $this->normalizeJsonValue($this->sanitizeJsonCompatible((array) ($consentSuppression['evidence'] ?? [])));
            $result['consent_suppression'] = [
                'suppression_result' => $queueUpdate['live_suppression_result'],
                'blocked_reasons' => $blockedReasons,
                'secret_safe' => true,
            ];
        }
        if ($requestedMode === 'live' && Database::columnExists('marketing_execution_queue', 'live_dispatch_status')) {
            $dispatchRunId = (int) ($input['dispatch_run_id'] ?? 0);
            if ($dispatchRunId > 0) {
                $queueUpdate['live_dispatch_run_id'] = $dispatchRunId;
                $queueUpdate['live_dispatch_status'] = match ($attemptStatus) {
                    'success' => 'completed',
                    'failed' => (string) ($liveRetryPlan['status'] ?? '') === 'scheduled' ? 'confirmed' : 'failed',
                    default => 'blocked',
                };
            }
        }
        if ($requestedMode === 'live' && Database::columnExists('marketing_execution_queue', 'live_outcome_status')) {
            $initialOutcome = $this->initialLiveOutcomeFromAttempt($attemptStatus, $liveAdapterResult);
            $queueUpdate['live_outcome_status'] = (string) ($initialOutcome['status'] ?? 'unknown');
            $queueUpdate['live_outcome_checked_at'] = date('Y-m-d H:i:s');
            $queueUpdate['live_outcome_json'] = $this->normalizeJsonValue($initialOutcome);
        }
        if ($liveRetryUpdate !== []) {
            $queueUpdate = array_merge($queueUpdate, $liveRetryUpdate);
        }
        $this->updateById('marketing_execution_queue', $queueId, $queueUpdate);
        if ($requestedMode === 'live') {
            $this->recordLiveExecutionEvent(
                $attemptStatus === 'success' ? 'live_succeeded' : ($attemptStatus === 'failed' ? 'live_failed' : 'live_blocked'),
                $attemptStatus === 'success' ? 'success' : ($attemptStatus === 'failed' ? 'failed' : 'blocked'),
                [
                    'connector_id' => (int) ($queue['connector_id'] ?? 0),
                    'queue_id' => $queueId,
                    'execution_mode' => 'live',
                    'adapter_key' => (string) ($readiness['adapter_key'] ?? ''),
                    'payload' => $this->sanitizeVisibleConnectorPayload($queue['payload_json'] ?? []),
                    'result' => $result,
                    'created_by' => (int) ($input['created_by'] ?? $this->currentUserId()) ?: null,
                ]
            );
        }

        return $this->listExecutionAttempts(['queue_id' => $queueId], 1, 0)[0] ?? ['id' => $attemptId, 'result_json' => $result];
    }

    public function listChannelMediaKits(array $filters = [], int $limit = 100, int $offset = 0): array
    {
        if (!Database::tableExists('marketing_channel_media_kits')) {
            return [];
        }

        $limit = min(max($limit, 1), 250);
        $offset = max($offset, 0);
        $workspace = $this->workspaceClause('cmk.');
        $where = [$workspace['sql']];
        $params = $workspace['params'];

        if (!empty($filters['id'])) {
            $where[] = 'cmk.id = ?';
            $params[] = (int) $filters['id'];
        }
        if (!empty($filters['status'])) {
            $where[] = 'cmk.status = ?';
            $params[] = $this->normalizeEnum((string) $filters['status'], self::CHANNEL_MEDIA_KIT_STATUSES, 'channel_media_kit_status');
        }
        if (!empty($filters['channel'])) {
            $where[] = 'cmk.channel = ?';
            $params[] = $this->normalizeEnum((string) $filters['channel'], self::CHANNELS, 'channel');
        }
        foreach (['content_item_id', 'landing_page_id', 'distribution_post_id', 'utm_link_id', 'primary_media_file_id'] as $field) {
            if (!empty($filters[$field])) {
                $where[] = 'cmk.' . $field . ' = ?';
                $params[] = (int) $filters[$field];
            }
        }

        return array_map(
            fn(array $row): array => $this->hydrateChannelMediaKitRow($row),
            Database::query(
                "SELECT cmk.*,
                        m.title AS content_title,
                        lp.title AS landing_page_title,
                        d.planned_copy AS distribution_planned_copy,
                        u.generated_url AS utm_generated_url,
                        u.url AS utm_base_url,
                        mf.title AS primary_media_title,
                        mf.media_type AS primary_media_type,
                        mf.source_type AS primary_media_source_type,
                        mf.file_path AS primary_media_file_path,
                        mf.source_url AS primary_media_source_url,
                        mf.thumbnail_path AS primary_media_thumbnail_path,
                        mf.thumbnail_url AS primary_media_thumbnail_url,
                        mf.alt_text AS primary_media_alt_text,
                        mf.caption AS primary_media_caption,
                        creator.email AS created_by_email
                 FROM marketing_channel_media_kits cmk
                 LEFT JOIN marketing_content_items m ON m.id = cmk.content_item_id AND m.workspace_id = cmk.workspace_id
                 LEFT JOIN marketing_landing_pages lp ON lp.id = cmk.landing_page_id AND lp.workspace_id = cmk.workspace_id
                 LEFT JOIN marketing_distribution_posts d ON d.id = cmk.distribution_post_id AND d.workspace_id = cmk.workspace_id
                 LEFT JOIN marketing_utm_links u ON u.id = cmk.utm_link_id AND u.workspace_id = cmk.workspace_id
                 LEFT JOIN marketing_media_files mf ON mf.id = cmk.primary_media_file_id AND mf.workspace_id = cmk.workspace_id
                 LEFT JOIN users creator ON creator.id = cmk.created_by
                 WHERE " . implode(' AND ', $where) . "
                 ORDER BY cmk.updated_at DESC, cmk.id DESC
                 LIMIT {$limit} OFFSET {$offset}",
                $params
            )
        );
    }

    public function getChannelMediaKit(int $id): ?array
    {
        $rows = $this->listChannelMediaKits(['id' => $id], 1, 0);
        return $rows[0] ?? null;
    }

    public function createChannelMediaKit(array $data): int
    {
        $this->assertMarketingPermission('marketing.write');
        if (!Database::tableExists('marketing_channel_media_kits')) {
            throw new RuntimeException('Marketing channel media kits are unavailable.');
        }

        $normalized = $this->normalizeChannelMediaKitData($data, true);
        Database::execute(
            "INSERT INTO marketing_channel_media_kits
             (workspace_id, uuid, title, channel, status, content_item_id, landing_page_id, distribution_post_id,
              utm_link_id, primary_media_file_id, destination_url, required_dimensions_json, aspect_ratios_json,
              copy_fields_json, media_slots_json, destination_rules_json, export_checklist_json, readiness_json,
              export_payload_json, metadata_json, exported_at, created_by)
             VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)",
            [
                $this->workspaceId(),
                $this->generateUuid(),
                $normalized['title'],
                $normalized['channel'],
                $normalized['status'],
                $normalized['content_item_id'],
                $normalized['landing_page_id'],
                $normalized['distribution_post_id'],
                $normalized['utm_link_id'],
                $normalized['primary_media_file_id'],
                $normalized['destination_url'],
                $normalized['required_dimensions_json'],
                $normalized['aspect_ratios_json'],
                $normalized['copy_fields_json'],
                $normalized['media_slots_json'],
                $normalized['destination_rules_json'],
                $normalized['export_checklist_json'],
                $normalized['readiness_json'],
                $normalized['export_payload_json'],
                $normalized['metadata_json'],
                $normalized['exported_at'],
                $normalized['created_by'],
            ]
        );

        return (int) Database::lastInsertId();
    }

    public function updateChannelMediaKit(int $id, array $data): bool
    {
        $this->assertMarketingPermission('marketing.write');
        $existing = $this->getChannelMediaKit($id);
        if (!$existing) {
            throw new RuntimeException('Marketing channel media kit not found.');
        }

        return $this->updateById('marketing_channel_media_kits', $id, $this->normalizeChannelMediaKitData(array_merge($existing, $data), false));
    }

    public function createChannelMediaKitFromDistribution(int $distributionPostId, array $data = [], ?int $userId = null): int
    {
        $post = $this->getDistributionPost($distributionPostId);
        if (!$post) {
            throw new RuntimeException('Marketing distribution post not found.');
        }

        $content = $this->getContentItem((int) ($post['content_item_id'] ?? 0)) ?: [];
        $media = $this->exportableContentMedia((int) ($post['content_item_id'] ?? 0));
        $primaryMediaId = (int) ($data['primary_media_file_id'] ?? 0);
        if ($primaryMediaId <= 0 && !empty($media[0]['media_file_id'])) {
            $primaryMediaId = (int) $media[0]['media_file_id'];
        }

        $utmId = (int) ($data['utm_link_id'] ?? 0);
        if ($utmId <= 0 && Database::tableExists('marketing_utm_links')) {
            $utm = Database::queryOne(
                "SELECT id
                 FROM marketing_utm_links
                 WHERE workspace_id = ? AND content_item_id = ?
                 ORDER BY created_at DESC
                 LIMIT 1",
                [$this->workspaceId(), (int) ($post['content_item_id'] ?? 0)]
            );
            $utmId = (int) ($utm['id'] ?? 0);
        }

        $requirements = $this->channelMediaKitRequirements((string) ($post['channel'] ?? 'other'));

        return $this->createChannelMediaKit($data + [
            'title' => trim((string) (($content['title'] ?? '') . ' ' . ucwords(str_replace('_', ' ', (string) ($post['channel'] ?? 'other'))) . ' Media Kit')),
            'channel' => (string) ($post['channel'] ?? 'other'),
            'content_item_id' => (int) ($post['content_item_id'] ?? 0),
            'landing_page_id' => (int) ($data['landing_page_id'] ?? ($content['landing_page_id'] ?? 0)),
            'distribution_post_id' => $distributionPostId,
            'utm_link_id' => $utmId,
            'primary_media_file_id' => $primaryMediaId,
            'copy_fields' => [
                'required' => (array) ($requirements['copy_fields']['required'] ?? ['planned_copy']),
                'values' => ['planned_copy' => (string) ($post['planned_copy'] ?? '')],
            ],
            'metadata_json' => [
                'source' => 'distribution_post',
                'distribution_status' => (string) ($post['status'] ?? ''),
                'manual_export_only' => true,
            ],
            'created_by' => ($userId ?? $this->currentUserId()) ?: null,
        ]);
    }

    public function generateChannelMediaKitExport(int $id): array
    {
        $kit = $this->getChannelMediaKit($id);
        if (!$kit) {
            throw new RuntimeException('Marketing channel media kit not found.');
        }

        $payload = $this->buildChannelMediaKitPayload($kit);
        $this->updateById('marketing_channel_media_kits', $id, [
            'export_payload_json' => $this->normalizeJsonValue($payload),
        ]);

        return $payload;
    }

    public function markChannelMediaKitExported(int $id): array
    {
        $this->assertMarketingPermission('marketing.write');
        $kit = $this->getChannelMediaKit($id);
        if (!$kit) {
            throw new RuntimeException('Marketing channel media kit not found.');
        }
        $readiness = $this->channelMediaKitReadiness($kit);
        $this->updateById('marketing_channel_media_kits', $id, [
            'readiness_json' => $this->normalizeJsonValue($readiness),
        ]);
        if (empty($readiness['ready'])) {
            throw new RuntimeException('Channel media kit is not export-ready.');
        }

        Database::execute(
            "UPDATE marketing_channel_media_kits
             SET status = 'exported', exported_at = COALESCE(exported_at, NOW())
             WHERE workspace_id = ? AND id = ?",
            [$this->workspaceId(), $id]
        );
        if (!empty($kit['primary_media_file_id'])) {
            $this->recordMediaAuditEvent('export_use', (int) $kit['primary_media_file_id'], 'Media used in manual channel export kit.', [], $this->currentUserId(), 'marketing_channel_media_kits', $id);
        }
        foreach ((array) ($kit['export_payload_json']['media']['content_attachments'] ?? []) as $attachment) {
            if (!empty($attachment['media_file_id'])) {
                $this->recordMediaAuditEvent('export_use', (int) $attachment['media_file_id'], 'Attached content media used in manual channel export kit.', [], $this->currentUserId(), 'marketing_channel_media_kits', $id);
            }
        }

        return $this->getChannelMediaKit($id) ?? [];
    }

    public function listContentQualityChecks(array $filters = [], int $limit = 50, int $offset = 0): array
    {
        if (!Database::tableExists('marketing_ai_quality_checks')) {
            return [];
        }

        $limit = min(max($limit, 1), 250);
        $offset = max($offset, 0);
        $workspace = $this->workspaceClause('q.');
        $where = [$workspace['sql']];
        $params = $workspace['params'];
        if (!empty($filters['content_item_id'])) {
            $where[] = 'q.content_item_id = ?';
            $params[] = (int) $filters['content_item_id'];
        }
        if (!empty($filters['id'])) {
            $where[] = 'q.id = ?';
            $params[] = (int) $filters['id'];
        }
        if (!empty($filters['status'])) {
            $where[] = 'q.status = ?';
            $params[] = $this->normalizeEnum((string) $filters['status'], self::QUALITY_CHECK_STATUSES, 'quality_status');
        } else {
            $where[] = "q.status <> 'archived'";
        }

        return array_map(
            fn(array $row): array => $this->hydrateJsonFields($row, [
                'brand_voice_json',
                'persona_fit_json',
                'compliance_json',
                'cta_quality_json',
                'seo_readiness_json',
                'approval_risk_json',
                'recommendations_json',
                'metadata_json',
            ]),
            Database::query(
                "SELECT q.*, m.title AS content_title, m.status AS content_status, m.channel AS content_channel,
                        creator.email AS created_by_email
                 FROM marketing_ai_quality_checks q
                 JOIN marketing_content_items m ON m.id = q.content_item_id AND m.workspace_id = q.workspace_id
                 LEFT JOIN users creator ON creator.id = q.created_by
                 WHERE " . implode(' AND ', $where) . "
                 ORDER BY q.created_at DESC, q.id DESC
                 LIMIT {$limit} OFFSET {$offset}",
                $params
            )
        );
    }

    public function getContentQualityCheck(int $id): ?array
    {
        $checks = $this->listContentQualityChecks(['id' => $id], 1, 0);
        if ($checks !== []) {
            return $checks[0];
        }

        if (!Database::tableExists('marketing_ai_quality_checks')) {
            return null;
        }

        $workspace = $this->workspaceClause('q.');
        $row = Database::queryOne(
            "SELECT q.*, m.title AS content_title, m.status AS content_status, m.channel AS content_channel,
                    creator.email AS created_by_email
             FROM marketing_ai_quality_checks q
             JOIN marketing_content_items m ON m.id = q.content_item_id AND m.workspace_id = q.workspace_id
             LEFT JOIN users creator ON creator.id = q.created_by
             WHERE {$workspace['sql']} AND q.id = ?",
            array_merge($workspace['params'], [$id])
        );

        return $row ? $this->hydrateJsonFields($row, [
            'brand_voice_json',
            'persona_fit_json',
            'compliance_json',
            'cta_quality_json',
            'seo_readiness_json',
            'approval_risk_json',
            'recommendations_json',
            'metadata_json',
        ]) : null;
    }

    public function getLatestContentQualityCheck(int $contentItemId): ?array
    {
        $checks = $this->listContentQualityChecks(['content_item_id' => $contentItemId], 1, 0);
        return $checks[0] ?? null;
    }

    public function runContentQualityCheck(int $contentItemId, ?int $userId = null): array
    {
        $this->assertMarketingPermission('marketing.write');
        if (!Database::tableExists('marketing_ai_quality_checks')) {
            throw new RuntimeException('Marketing quality checks are unavailable.');
        }

        $content = $this->getContentItem($contentItemId);
        if (!$content) {
            throw new RuntimeException('Marketing content item not found.');
        }

        $deterministic = $this->evaluateContentQuality($content);
        $draftContext = $this->buildDraftContext($content);
        $qualityInputs = [
            'content' => [
                'title' => $content['title'] ?? '',
                'content_type' => $content['content_type'] ?? '',
                'channel' => $content['channel'] ?? '',
                'status' => $content['status'] ?? '',
                'objective' => $content['objective'] ?? '',
                'target_audience' => $content['target_audience'] ?? '',
                'draft_body' => $content['draft_body'] ?? '',
            ],
            'deterministic_quality' => $deterministic,
        ];
        $bundle = $this->buildMarketingContextBundle('quality_review', $qualityInputs, [
            'brand_profile' => $draftContext['brand_profile'] ?? [],
            'persona' => $draftContext['persona'] ?? [],
            'campaign_brief' => $draftContext['campaign_brief'] ?? [],
            'landing_page' => $draftContext['landing_page'] ?? [],
            'seo_topic' => $draftContext['seo_topic'] ?? [],
        ]);
        $aiResult = $this->runMarketingAiPrompt(
            'quality_review',
            $bundle,
            $qualityInputs,
            'marketing_quality_review',
            fn(): array => $deterministic,
            true
        );
        $result = $this->normalizeQualityReviewResult((array) ($aiResult['json'] ?? []), $deterministic);
        $usedAi = !empty($aiResult['text']) && (string) ($aiResult['provider']['json_decode_status'] ?? '') === 'valid';
        $result['metadata'] = array_merge((array) ($result['metadata'] ?? []), [
            'engine' => $usedAi ? 'ai_quality_review' : 'deterministic_quality_fallback',
            'external_publish' => false,
            'draft_overwritten' => false,
            'checked_at' => date('c'),
            'ai_quality_review' => [
                'attempted' => (string) ($aiResult['provider']['json_decode_status'] ?? 'not_attempted') !== 'not_attempted',
                'used' => $usedAi,
                'prompt_key' => 'quality_review',
                'prompt_version' => (int) ($aiResult['provider']['prompt_version'] ?? 0),
                'context_score' => (float) ($bundle['bundle_quality']['context_quality_score'] ?? 0),
                'provider' => $aiResult['provider'],
                'deterministic_overall_score' => (int) ($deterministic['overall_score'] ?? 0),
            ],
        ]);
        Database::execute(
            "INSERT INTO marketing_ai_quality_checks
             (workspace_id, content_item_id, uuid, overall_score, brand_voice_json, persona_fit_json,
              compliance_json, cta_quality_json, seo_readiness_json, approval_risk_json,
              recommendations_json, metadata_json, status, created_by)
             VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, 'completed', ?)",
            [
                $this->workspaceId(),
                $contentItemId,
                $this->generateUuid(),
                $result['overall_score'],
                $this->normalizeJsonValue($result['brand_voice']),
                $this->normalizeJsonValue($result['persona_fit']),
                $this->normalizeJsonValue($result['compliance']),
                $this->normalizeJsonValue($result['cta_quality']),
                $this->normalizeJsonValue($result['seo_readiness']),
                $this->normalizeJsonValue($result['approval_risk']),
                $this->normalizeJsonValue($result['recommendations']),
                $this->normalizeJsonValue($result['metadata']),
                ($userId ?? $this->currentUserId()) ?: null,
            ]
        );

        return $this->getLatestContentQualityCheck($contentItemId) ?? [];
    }

    public function getMarketingQualityReviewSummary(int $limit = 100): array
    {
        $limit = min(max($limit, 1), 250);
        $checks = $this->listContentQualityChecks([], $limit, 0);
        $items = $this->listContentItems(['exclude_status' => 'archived'], $limit, 0);
        $latestByContent = [];
        foreach ($checks as $check) {
            $contentId = (int) ($check['content_item_id'] ?? 0);
            if ($contentId > 0 && !isset($latestByContent[$contentId])) {
                $latestByContent[$contentId] = $check;
            }
        }

        $dimensionKeys = ['brand_voice', 'persona_fit', 'compliance', 'cta_quality', 'seo_readiness', 'approval_risk'];
        $dimensions = [];
        foreach ($dimensionKeys as $key) {
            $dimensions[$key] = [
                'key' => $key,
                'label' => ucwords(str_replace('_', ' ', $key)),
                'average_score' => 0,
                'issue_count' => 0,
                'status' => 'unknown',
            ];
        }

        $counts = [
            'total_checks' => count($checks),
            'content_items' => count($items),
            'reviewed_content' => count($latestByContent),
            'needs_review' => 0,
            'risk_items' => 0,
            'draft_safe_checks' => 0,
            'draft_overwrite_flags' => 0,
            'external_publish_flags' => 0,
            'ai_used' => 0,
            'fallback_used' => 0,
            'media_accessibility_issues' => 0,
            'media_export_blocked' => 0,
        ];

        $dimensionTotals = array_fill_keys($dimensionKeys, 0);
        $dimensionSamples = array_fill_keys($dimensionKeys, 0);
        foreach ($checks as $check) {
            $metadata = (array) ($check['metadata_json'] ?? []);
            if (!empty($metadata['draft_overwritten'])) {
                $counts['draft_overwrite_flags']++;
            } else {
                $counts['draft_safe_checks']++;
            }
            if (!empty($metadata['external_publish'])) {
                $counts['external_publish_flags']++;
            }
            if (!empty($metadata['ai_quality_review']['used'])) {
                $counts['ai_used']++;
            } else {
                $counts['fallback_used']++;
            }

            foreach ($dimensionKeys as $key) {
                $section = (array) ($check[$key . '_json'] ?? []);
                $score = (int) ($section['score'] ?? 0);
                if ($score > 0) {
                    $dimensionTotals[$key] += $score;
                    $dimensionSamples[$key]++;
                }
                $details = (array) ($section['details'] ?? []);
                $riskLevel = (string) ($details['risk_level'] ?? '');
                if ($score > 0 && ($score < 70 || in_array($riskLevel, ['medium', 'high'], true))) {
                    $dimensions[$key]['issue_count']++;
                }
            }
        }

        $mediaOperations = Database::tableExists('marketing_media_files')
            ? $this->getMarketingMediaOperationsSummary(min($limit, 100))
            : ['counts' => [], 'operations' => [], 'guardrails' => []];
        $counts['media_accessibility_issues'] = (int) ($mediaOperations['counts']['needs_accessibility'] ?? 0);
        $counts['media_export_blocked'] = (int) ($mediaOperations['counts']['export_blocked'] ?? 0);

        foreach ($dimensionKeys as $key) {
            $samples = max(1, (int) ($dimensionSamples[$key] ?? 0));
            $average = $dimensionSamples[$key] > 0 ? (int) round($dimensionTotals[$key] / $samples) : 0;
            $dimensions[$key]['average_score'] = $average;
            $dimensions[$key]['status'] = $average >= 80 ? 'ready' : ($average >= 65 ? 'watch' : ($average > 0 ? 'needs_review' : 'unknown'));
        }
        $mediaScore = 100 - min(80, ($counts['media_accessibility_issues'] * 10) + ($counts['media_export_blocked'] * 15));
        $dimensions['media_accessibility'] = [
            'key' => 'media_accessibility',
            'label' => 'Media Accessibility',
            'average_score' => max(0, $mediaScore),
            'issue_count' => $counts['media_accessibility_issues'] + $counts['media_export_blocked'],
            'status' => ($counts['media_accessibility_issues'] + $counts['media_export_blocked']) > 0 ? 'needs_review' : 'ready',
        ];

        $contentNeedingReview = [];
        $mediaQualityByContent = $this->contentMediaQualityDetailsForItems($items);
        foreach ($items as $item) {
            $contentId = (int) ($item['id'] ?? 0);
            if ($contentId <= 0) {
                continue;
            }
            $latest = $latestByContent[$contentId] ?? null;
            $issues = [];
            $score = null;
            $riskLevel = 'unknown';
            if (!$latest) {
                $issues[] = 'No quality check has been run yet.';
            } else {
                $score = (int) ($latest['overall_score'] ?? 0);
                $riskLevel = (string) ($latest['approval_risk_json']['details']['risk_level'] ?? 'unknown');
                if ($score < 75) {
                    $issues[] = 'Latest quality score is below approval threshold.';
                }
                if (in_array($riskLevel, ['medium', 'high'], true)) {
                    $issues[] = 'Approval risk is ' . $riskLevel . '.';
                }
                foreach ($dimensionKeys as $key) {
                    $sectionScore = (int) ($latest[$key . '_json']['score'] ?? 0);
                    if ($sectionScore > 0 && $sectionScore < 70) {
                        $issues[] = ucwords(str_replace('_', ' ', $key)) . ' needs review.';
                    }
                }
            }

            $mediaQuality = $mediaQualityByContent[$contentId] ?? $this->contentMediaQualityDetails($item);
            foreach ((array) ($mediaQuality['issues'] ?? []) as $issue) {
                $issues[] = ucwords(str_replace('_', ' ', (string) $issue)) . '.';
            }

            $issues = array_values(array_unique(array_filter($issues)));
            if ($issues === []) {
                continue;
            }

            $counts['needs_review']++;
            if ($score !== null && ($score < 70 || in_array($riskLevel, ['medium', 'high'], true))) {
                $counts['risk_items']++;
            }
            $contentNeedingReview[] = [
                'content_item_id' => $contentId,
                'title' => (string) ($item['title'] ?? 'Untitled content'),
                'status' => (string) ($item['status'] ?? ''),
                'channel' => (string) ($item['channel'] ?? ''),
                'overall_score' => $score,
                'risk_level' => $riskLevel,
                'issues' => $issues,
                'href' => 'marketing_content_view.php?id=' . $contentId,
            ];
        }

        usort($contentNeedingReview, static function (array $left, array $right): int {
            $leftScore = $left['overall_score'] === null ? -1 : (int) $left['overall_score'];
            $rightScore = $right['overall_score'] === null ? -1 : (int) $right['overall_score'];
            return $leftScore <=> $rightScore;
        });

        $averageScore = 0;
        if ($checks !== []) {
            $averageScore = (int) round(array_sum(array_map(static fn(array $check): int => (int) ($check['overall_score'] ?? 0), $checks)) / count($checks));
        }

        $recommendedActions = [];
        if ($counts['total_checks'] === 0) {
            $recommendedActions[] = 'Run the first quality check on active content before moving items to approval.';
        }
        if ($counts['needs_review'] > 0) {
            $recommendedActions[] = 'Review the lowest-scoring or unchecked content before requesting approval.';
        }
        if ($counts['media_accessibility_issues'] > 0) {
            $recommendedActions[] = 'Add alt text, captions, or transcripts to media before export.';
        }
        if ($counts['media_export_blocked'] > 0) {
            $recommendedActions[] = 'Resolve blocked, expired, restricted, or accessibility-blocked media before manual publishing.';
        }
        if ($counts['fallback_used'] > 0 && $counts['ai_used'] === 0) {
            $recommendedActions[] = 'AI is optional here; deterministic fallback checks are keeping manual review usable.';
        }
        if ($recommendedActions === []) {
            $recommendedActions[] = 'Quality checks are healthy. Keep reviewing new drafts before approval.';
        }

        return [
            'counts' => $counts,
            'average_score' => $averageScore,
            'status' => ($counts['risk_items'] + $counts['external_publish_flags'] + $counts['draft_overwrite_flags']) > 0
                ? 'needs_review'
                : ($counts['needs_review'] > 0 ? 'watch' : 'ready'),
            'dimensions' => array_values($dimensions),
            'content_needing_review' => array_slice($contentNeedingReview, 0, 12),
            'recommended_actions' => array_values(array_unique($recommendedActions)),
            'media_operations' => [
                'counts' => (array) ($mediaOperations['counts'] ?? []),
                'guardrails' => (array) ($mediaOperations['guardrails'] ?? []),
            ],
            'ai_safety' => [
                'draft_overwrite' => $counts['draft_overwrite_flags'] > 0,
                'external_publish' => $counts['external_publish_flags'] > 0,
                'manual_review_required' => true,
                'auto_apply' => false,
            ],
            'manual_first_boundary' => [
                'external_publish' => false,
                'external_send' => false,
                'draft_overwrite' => false,
                'review_mode' => 'advisory_only',
            ],
        ];
    }

    public function listUtmLinks(array $filters = [], int $limit = 100, int $offset = 0): array
    {
        $workspace = $this->workspaceClause('u.');
        $where = [$workspace['sql']];
        $params = $workspace['params'];
        if (!empty($filters['campaign_id'])) {
            $where[] = 'u.campaign_id = ?';
            $params[] = (int) $filters['campaign_id'];
        }
        if (!empty($filters['content_item_id'])) {
            $where[] = 'u.content_item_id = ?';
            $params[] = (int) $filters['content_item_id'];
        }

        return Database::query(
            "SELECT u.*, c.name AS campaign_name, m.title AS content_title
             FROM marketing_utm_links u
             LEFT JOIN campaigns c ON c.id = u.campaign_id AND c.workspace_id = u.workspace_id
             LEFT JOIN marketing_content_items m ON m.id = u.content_item_id AND m.workspace_id = u.workspace_id
             WHERE " . implode(' AND ', $where) . "
             ORDER BY u.created_at DESC
             LIMIT {$limit} OFFSET {$offset}",
            $params
        );
    }

    public function createUtmLink(array $data): int
    {
        $normalized = $this->normalizeUtmLinkData($data);
        Database::execute(
            "INSERT INTO marketing_utm_links
             (workspace_id, uuid, campaign_id, content_item_id, url, utm_source, utm_medium, utm_campaign, utm_term, utm_content, generated_url, created_by)
             VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)",
            [
                $this->workspaceId(), $this->generateUuid(), $normalized['campaign_id'], $normalized['content_item_id'],
                $normalized['url'], $normalized['utm_source'], $normalized['utm_medium'], $normalized['utm_campaign'],
                $normalized['utm_term'], $normalized['utm_content'], $normalized['generated_url'], $normalized['created_by'],
            ]
        );

        return (int) Database::lastInsertId();
    }

    public function listCampaignBudgets(array $filters = [], int $limit = 100, int $offset = 0): array
    {
        if (!Database::tableExists('marketing_campaign_budgets')) {
            return [];
        }
        $limit = min(max($limit, 1), 250);
        $offset = max($offset, 0);
        $workspace = $this->workspaceClause('b.');
        $where = [$workspace['sql']];
        $params = $workspace['params'];
        if (!empty($filters['id'])) {
            $where[] = 'b.id = ?';
            $params[] = (int) $filters['id'];
        }
        if (!empty($filters['status'])) {
            $where[] = 'b.status = ?';
            $params[] = $this->normalizeEnum((string) $filters['status'], self::BUDGET_STATUSES, 'budget_status');
        }
        if (!empty($filters['campaign_id'])) {
            $where[] = 'b.campaign_id = ?';
            $params[] = (int) $filters['campaign_id'];
        }

        return array_map(
            fn(array $row): array => $this->hydrateJsonFields($row, ['metadata_json']),
            Database::query(
                "SELECT b.*, c.name AS campaign_name, cb.title AS campaign_brief_title,
                        owner.email AS owner_email, creator.email AS created_by_email,
                        COALESCE((SELECT SUM(s.amount) FROM marketing_channel_spend s WHERE s.workspace_id = b.workspace_id AND s.budget_id = b.id), 0) AS channel_spend_total,
                        COALESCE((SELECT SUM(t.target_revenue) FROM marketing_roi_targets t WHERE t.workspace_id = b.workspace_id AND t.budget_id = b.id AND t.status <> 'archived'), 0) AS target_revenue_total
                 FROM marketing_campaign_budgets b
                 LEFT JOIN campaigns c ON c.id = b.campaign_id AND c.workspace_id = b.workspace_id
                 LEFT JOIN marketing_campaign_briefs cb ON cb.id = b.campaign_brief_id AND cb.workspace_id = b.workspace_id
                 LEFT JOIN users owner ON owner.id = b.owner_user_id
                 LEFT JOIN users creator ON creator.id = b.created_by
                 WHERE " . implode(' AND ', $where) . "
                 ORDER BY FIELD(b.status, 'active', 'draft', 'closed', 'archived'), b.updated_at DESC
                 LIMIT {$limit} OFFSET {$offset}",
                $params
            )
        );
    }

