    public function getBudgetRoiSummary(): array
    {
        if (!Database::tableExists('marketing_campaign_budgets')) {
            return ['planned_budget' => 0.0, 'actual_spend' => 0.0, 'target_revenue' => 0.0, 'roi_percent' => null, 'by_channel' => []];
        }
        $workspaceId = $this->workspaceId();
        $budget = Database::queryOne(
            "SELECT COALESCE(SUM(planned_budget), 0) AS planned_budget,
                    COALESCE(SUM(committed_budget), 0) AS committed_budget,
                    COALESCE(SUM(actual_spend), 0) AS actual_spend
             FROM marketing_campaign_budgets
             WHERE workspace_id = ? AND status <> 'archived'",
            [$workspaceId]
        ) ?: [];
        $targets = Database::tableExists('marketing_roi_targets')
            ? (Database::queryOne(
                "SELECT COALESCE(SUM(target_revenue), 0) AS target_revenue,
                        COALESCE(SUM(target_leads), 0) AS target_leads,
                        COALESCE(SUM(target_conversions), 0) AS target_conversions
                 FROM marketing_roi_targets
                 WHERE workspace_id = ? AND status <> 'archived'",
                [$workspaceId]
            ) ?: [])
            : [];
        $byChannel = Database::tableExists('marketing_channel_spend')
            ? Database::query(
                "SELECT channel, COALESCE(SUM(amount), 0) AS spend
                 FROM marketing_channel_spend
                 WHERE workspace_id = ?
                 GROUP BY channel
                 ORDER BY spend DESC",
                [$workspaceId]
            )
            : [];
        $revenue = $this->revenueAttributionAnalytics(date('Y-m-d', strtotime('-90 days')), date('Y-m-d'));
        $actualSpend = (float) ($budget['actual_spend'] ?? 0);
        $actualRevenue = (float) ($revenue['total_revenue'] ?? 0);

        return [
            'planned_budget' => round((float) ($budget['planned_budget'] ?? 0), 2),
            'committed_budget' => round((float) ($budget['committed_budget'] ?? 0), 2),
            'actual_spend' => round($actualSpend, 2),
            'target_revenue' => round((float) ($targets['target_revenue'] ?? 0), 2),
            'target_leads' => (int) ($targets['target_leads'] ?? 0),
            'target_conversions' => (int) ($targets['target_conversions'] ?? 0),
            'attributed_revenue' => round($actualRevenue, 2),
            'roi_percent' => $actualSpend > 0 ? round((($actualRevenue - $actualSpend) / $actualSpend) * 100, 1) : null,
            'by_channel' => $byChannel,
            'manual_planning_only' => true,
        ];
    }

    public function listExperiments(array $filters = [], int $limit = 100, int $offset = 0): array
    {
        if (!Database::tableExists('marketing_experiments')) {
            return [];
        }
        $limit = min(max($limit, 1), 250);
        $offset = max($offset, 0);
        $workspace = $this->workspaceClause('e.');
        $where = [$workspace['sql']];
        $params = $workspace['params'];
        if (!empty($filters['id'])) {
            $where[] = 'e.id = ?';
            $params[] = (int) $filters['id'];
        }
        if (!empty($filters['status'])) {
            $where[] = 'e.status = ?';
            $params[] = $this->normalizeEnum((string) $filters['status'], self::EXPERIMENT_STATUSES, 'experiment_status');
        }
        if (!empty($filters['experiment_type'])) {
            $where[] = 'e.experiment_type = ?';
            $params[] = $this->normalizeEnum((string) $filters['experiment_type'], self::EXPERIMENT_TYPES, 'experiment_type');
        }
        if (!empty($filters['campaign_id'])) {
            $where[] = 'e.campaign_id = ?';
            $params[] = (int) $filters['campaign_id'];
        }

        return array_map(
            fn(array $row): array => $this->hydrateJsonFields($row, ['metadata_json']),
            Database::query(
                "SELECT e.*, c.name AS campaign_name, m.title AS content_title, lp.title AS landing_page_title,
                        winner.name AS winner_variant_name, owner.email AS owner_email,
                        (SELECT COUNT(*) FROM marketing_experiment_variants v WHERE v.workspace_id = e.workspace_id AND v.experiment_id = e.id) AS variant_count,
                        (SELECT COUNT(*) FROM marketing_experiment_results r WHERE r.workspace_id = e.workspace_id AND r.experiment_id = e.id) AS result_count
                 FROM marketing_experiments e
                 LEFT JOIN campaigns c ON c.id = e.campaign_id AND c.workspace_id = e.workspace_id
                 LEFT JOIN marketing_content_items m ON m.id = e.content_item_id AND m.workspace_id = e.workspace_id
                 LEFT JOIN marketing_landing_pages lp ON lp.id = e.landing_page_id AND lp.workspace_id = e.workspace_id
                 LEFT JOIN marketing_experiment_variants winner ON winner.id = e.winner_variant_id AND winner.workspace_id = e.workspace_id
                 LEFT JOIN users owner ON owner.id = e.owner_user_id
                 WHERE " . implode(' AND ', $where) . "
                 ORDER BY FIELD(e.status, 'running', 'draft', 'paused', 'completed', 'archived'), e.updated_at DESC
                 LIMIT {$limit} OFFSET {$offset}",
                $params
            )
        );
    }

