    public function recommendExperimentWinner(int $experimentId): array
    {
        $experiment = $this->getExperiment($experimentId);
        if (!$experiment) {
            throw new RuntimeException('Marketing experiment not found.');
        }
        $metric = (string) ($experiment['success_metric'] ?? 'conversion_rate');
        $rows = Database::tableExists('marketing_experiment_results')
            ? Database::query(
                "SELECT v.id AS variant_id, v.name AS variant_name,
                        COALESCE(SUM(r.metric_value * GREATEST(r.sample_size, 1)) / NULLIF(SUM(GREATEST(r.sample_size, 1)), 0), 0) AS weighted_metric,
                        COALESCE(SUM(r.sample_size), 0) AS sample_size
                 FROM marketing_experiment_variants v
                 LEFT JOIN marketing_experiment_results r ON r.variant_id = v.id AND r.workspace_id = v.workspace_id AND r.metric_name = ?
                 WHERE v.workspace_id = ? AND v.experiment_id = ?
                 GROUP BY v.id, v.name
                 ORDER BY weighted_metric DESC, sample_size DESC",
                [$metric, $this->workspaceId(), $experimentId]
            )
            : [];
        $winner = $rows[0] ?? null;
        if ($winner && (float) ($winner['weighted_metric'] ?? 0) > 0) {
            Database::execute(
                "UPDATE marketing_experiments SET winner_variant_id = ?, status = 'completed' WHERE workspace_id = ? AND id = ?",
                [(int) $winner['variant_id'], $this->workspaceId(), $experimentId]
            );
            Database::execute(
                "UPDATE marketing_experiment_variants SET status = CASE WHEN id = ? THEN 'winner' ELSE status END WHERE workspace_id = ? AND experiment_id = ?",
                [(int) $winner['variant_id'], $this->workspaceId(), $experimentId]
            );
        }

        return [
            'experiment_id' => $experimentId,
            'success_metric' => $metric,
            'winner' => $winner,
            'variants' => $rows,
            'manual_recommendation_only' => true,
        ];
    }

