        if (!empty($filters['id'])) {
            $where[] = 're.id = ?';
            $params[] = (int) $filters['id'];
        }
        if (!empty($filters['report_type'])) {
            $where[] = 're.report_type = ?';
            $params[] = $this->normalizeEnum((string) $filters['report_type'], self::REPORT_EXPORT_TYPES, 'report_type');
        }
        if (!empty($filters['status'])) {
            $where[] = 're.status = ?';
            $params[] = $this->normalizeEnum((string) $filters['status'], self::REPORT_EXPORT_STATUSES, 'report_status');
        }

        return array_map(
