    public function createMarketingReportExport(string $reportType = 'operator', array $options = [], ?int $exportedBy = null): int
    {
        $this->assertMarketingPermission('marketing.manage');
        if (!Database::tableExists('marketing_report_exports')) {
            throw new RuntimeException('Marketing report exports are unavailable.');
        }

        $reportType = $this->normalizeEnum($reportType, self::REPORT_EXPORT_TYPES, 'report_type');
        $format = $this->normalizeEnum((string) ($options['report_format'] ?? 'json'), self::REPORT_EXPORT_FORMATS, 'report_format');
        $status = $this->normalizeEnum((string) ($options['status'] ?? 'generated'), self::REPORT_EXPORT_STATUSES, 'report_status');
        $periodStart = !empty($options['period_start']) ? $this->normalizeDate((string) $options['period_start'], 'report period start') : null;
        $periodEnd = !empty($options['period_end']) ? $this->normalizeDate((string) $options['period_end'], 'report period end') : null;
        $exportedBy = $exportedBy ?? $this->currentUserId();
        if (($exportedBy ?? 0) > 0) {
            $this->assertWorkspaceUser((int) $exportedBy, $this->workspaceId());
        }

        $payload = $this->buildMarketingReportPayload($reportType, $options, $periodStart, $periodEnd);
        $metadata = [
            'source' => 'marketing_operator_reporting',
            'manual_first_boundary' => true,
            'external_publish' => false,
            'external_send' => false,
            'created_from' => Security::sanitizeInput((string) ($options['created_from'] ?? 'marketing_admin'), 'string'),
        ];

        Database::execute(
            "INSERT INTO marketing_report_exports
             (workspace_id, uuid, report_type, report_format, status, period_start, period_end, payload_json, metadata_json, exported_by)
             VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)",
            [
                $this->workspaceId(),
                $this->generateUuid(),
                $reportType,
                $format,
                $status,
                $periodStart,
                $periodEnd,
                $this->normalizeJsonValue($payload),
                $this->normalizeJsonValue($metadata),
                ($exportedBy ?? 0) > 0 ? (int) $exportedBy : null,
            ]
        );

        $id = (int) Database::lastInsertId();
        $this->recordMarketingAuditEvent(
            'report_export_created',
            'marketing_report_exports',
            $id,
            'Marketing operator report export generated.',
            ['report_type' => $reportType, 'report_format' => $format],
            $exportedBy
        );

        return $id;
    }

