    public function createScheduledReportDraft(array $data): int
    {
        $this->assertMarketingPermission('marketing.manage');
        if (!Database::tableExists('marketing_scheduled_report_drafts')) {
            throw new RuntimeException('Marketing scheduled report drafts are unavailable.');
        }

        $title = Security::sanitizeInput((string) ($data['title'] ?? ''), 'string');
        if ($title === '') {
            throw new \InvalidArgumentException('Scheduled report title is required.');
        }
        $reportType = $this->normalizeEnum((string) ($data['report_type'] ?? 'weekly'), self::REPORT_EXPORT_TYPES, 'report_type');
        $cadence = $this->normalizeEnum((string) ($data['cadence'] ?? 'weekly'), self::SCHEDULED_REPORT_CADENCES, 'report_cadence');
        $status = $this->normalizeEnum((string) ($data['status'] ?? 'draft'), self::SCHEDULED_REPORT_STATUSES, 'scheduled_report_status');
        $createdBy = (int) ($data['created_by'] ?? $this->currentUserId());
        if ($createdBy > 0) {
            $this->assertWorkspaceUser($createdBy, $this->workspaceId());
        }

        Database::execute(
            "INSERT INTO marketing_scheduled_report_drafts
             (workspace_id, uuid, title, report_type, cadence, next_run_at, recipients_json, filters_json, status, metadata_json, created_by)
             VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)",
            [
                $this->workspaceId(),
                $this->generateUuid(),
                $title,
                $reportType,
                $cadence,
                $this->normalizeDateTime((string) ($data['next_run_at'] ?? '')),
                $this->normalizeJsonValue($this->normalizeReportRecipients($data['recipients'] ?? [])),
                $this->normalizeJsonValue($this->sanitizeFlexibleArray($data['filters'] ?? [])),
                $status,
                $this->normalizeJsonValue([
                    'source' => 'marketing_operator_reporting',
                    'manual_draft_only' => true,
                    'external_send' => false,
                ]),
                $createdBy > 0 ? $createdBy : null,
            ]
        );

        $id = (int) Database::lastInsertId();
        $this->recordMarketingAuditEvent(
            'scheduled_report_draft_created',
            'marketing_scheduled_report_drafts',
            $id,
            'Marketing scheduled report draft created.',
            ['report_type' => $reportType, 'cadence' => $cadence],
            $createdBy
        );

        return $id;
    }

    public function getMarketingOperatorReadiness(): array
    {
        $this->assertMarketingPermission('marketing.manage');
        $checks = $this->buildMarketingOperatorReadinessChecks();
        $status = 'ready';
        foreach ($checks as $check) {
            if (($check['status'] ?? '') === 'blocked') {
                $status = 'blocked';
                break;
            }
            if (($check['status'] ?? '') === 'warning') {
                $status = 'warning';
            }
        }

        if (Database::tableExists('marketing_operator_readiness_checks')) {
            foreach ($checks as $check) {
                Database::execute(
                    "INSERT INTO marketing_operator_readiness_checks
                        (workspace_id, check_key, label, status, message, metadata_json, checked_at)
                     VALUES (?, ?, ?, ?, ?, ?, NOW())
                     ON DUPLICATE KEY UPDATE
                        label = VALUES(label),
                        status = VALUES(status),
                        message = VALUES(message),
                        metadata_json = VALUES(metadata_json),
                        checked_at = NOW()",
                    [
                        $this->workspaceId(),
                        (string) $check['key'],
                        (string) $check['label'],
                        $this->normalizeEnum((string) $check['status'], self::OPERATOR_READINESS_STATUSES, 'operator_readiness_status'),
                        (string) $check['message'],
                        $this->normalizeJsonValue($this->sanitizeFlexibleArray($check['metadata'] ?? [])),
                    ]
                );
            }
        }

        return [
            'status' => $status,
            'checked_at' => date('c'),
            'checks' => $checks,
            'counts' => [
                'ready' => count(array_filter($checks, static fn(array $check): bool => ($check['status'] ?? '') === 'ready')),
                'warning' => count(array_filter($checks, static fn(array $check): bool => ($check['status'] ?? '') === 'warning')),
                'blocked' => count(array_filter($checks, static fn(array $check): bool => ($check['status'] ?? '') === 'blocked')),
            ],
            'manual_first_boundary' => [
                'external_publish' => false,
                'external_send' => false,
                'external_generation' => false,
            ],
        ];
    }

    public function getPerformanceSummary(): array
    {
        $byChannel = Database::query(
            "SELECT channel, COUNT(*) AS post_count,
                    SUM(CASE WHEN status = 'exported' THEN 1 ELSE 0 END) AS exported_count,
                    SUM(CASE WHEN status = 'published' THEN 1 ELSE 0 END) AS published_count
             FROM marketing_distribution_posts
             WHERE workspace_id = ?
             GROUP BY channel
             ORDER BY post_count DESC",
            [$this->workspaceId()]
        );
        $analytics = $this->getMarketingAnalyticsSummary('monthly');

        return [
            'by_channel' => $byChannel,
            'utm_links' => Database::tableExists('marketing_utm_links') ? $this->countRows('marketing_utm_links', 'id > 0') : 0,
            'recent_attributed_revenue' => $this->recentAttributedRevenue(10),
            'campaign_roi' => $analytics['campaign_roi'],
            'content_influence' => $analytics['content_influence'],
            'form_conversion' => $analytics['form_conversion'],
            'landing_page_funnel' => $analytics['landing_page_funnel'],
            'utm_performance' => $analytics['utm_performance'],
            'revenue_attribution' => $analytics['revenue_attribution'],
            'budget_roi' => $this->getBudgetRoiSummary(),
            'experiments' => Database::tableExists('marketing_experiments') ? $this->listExperiments(['status' => 'running'], 6, 0) : [],
            'tracking' => Database::tableExists('marketing_tracking_events') ? $this->getMarketingTrackingSummary() : [],
            'attribution_pipeline' => Database::tableExists('marketing_attribution_touchpoints') ? $this->getMarketingAttributionSummary() : [],
            'conversion_goals' => Database::tableExists('marketing_conversion_goals') ? $this->getConversionGoalSummary() : [],
            'lead_handoffs' => Database::tableExists('marketing_lead_handoffs') ? $this->getLeadHandoffSummary() : [],
            'campaign_revenue_loop' => $this->getCampaignRevenueLoopSummary(null, 8),
        ];
    }

    public function getMarketingAnalyticsSummary(string $periodType = 'weekly', ?string $anchorDate = null): array
    {
        [$start, $end] = $this->analyticsPeriod($periodType, $anchorDate);
        $workspaceId = $this->workspaceId();
        $rangeParams = [$workspaceId, $start, date('Y-m-d', strtotime($end . ' +1 day'))];

        $contentByStatus = Database::query(
            "SELECT status, COUNT(*) AS count
             FROM marketing_content_items
             WHERE workspace_id = ? AND created_at >= ? AND created_at < ?
             GROUP BY status",
            $rangeParams
        );
        $contentByChannel = Database::query(
            "SELECT channel, COUNT(*) AS count
             FROM marketing_content_items
             WHERE workspace_id = ? AND created_at >= ? AND created_at < ?
             GROUP BY channel",
            $rangeParams
        );

        $reviewBottlenecks = Database::tableExists('marketing_content_approvals')
            ? [
                'pending' => $this->countRows('marketing_content_approvals', "status = 'pending'"),
                'overdue' => count($this->listContentApprovals(['queue' => 'overdue'], 250, 0)),
                'approved_period' => $this->countRows('marketing_content_approvals', "status = 'approved' AND decided_at >= '{$start}' AND decided_at < DATE_ADD('{$end}', INTERVAL 1 DAY)"),
                'rejected_period' => $this->countRows('marketing_content_approvals', "status = 'rejected' AND decided_at >= '{$start}' AND decided_at < DATE_ADD('{$end}', INTERVAL 1 DAY)"),
            ]
            : ['pending' => 0, 'overdue' => 0, 'approved_period' => 0, 'rejected_period' => 0];

        $briefReadiness = Database::tableExists('marketing_campaign_briefs')
            ? Database::queryOne(
                "SELECT COUNT(*) AS brief_count, AVG(readiness_score) AS average_readiness
                 FROM marketing_campaign_briefs
                 WHERE workspace_id = ? AND updated_at >= ? AND updated_at < ?",
                $rangeParams
            )
            : ['brief_count' => 0, 'average_readiness' => null];

        $landingByGoal = Database::tableExists('marketing_landing_pages')
            ? Database::query(
                "SELECT COALESCE(conversion_goal, 'lead_capture') AS conversion_goal, COUNT(*) AS count
                 FROM marketing_landing_pages
                 WHERE workspace_id = ?
                 GROUP BY COALESCE(conversion_goal, 'lead_capture')",
                [$workspaceId]
            )
            : [];

        $utmBySource = Database::tableExists('marketing_utm_links')
            ? Database::query(
                "SELECT COALESCE(utm_source, 'unknown') AS utm_source, COUNT(*) AS count
                 FROM marketing_utm_links
                 WHERE workspace_id = ? AND created_at >= ? AND created_at < ?
                 GROUP BY COALESCE(utm_source, 'unknown')",
                $rangeParams
            )
            : [];

        $campaignRoi = $this->campaignRoiAnalytics($start, $end);
        $contentInfluence = $this->contentInfluenceAnalytics($start, $end);
        $landingPageFunnel = $this->landingPageFunnelAnalytics($start, $end);
        $formConversion = $this->formConversionAnalytics($start, $end);
        $utmPerformance = $this->utmPerformanceAnalytics($start, $end);
        $revenueAttribution = $this->revenueAttributionAnalytics($start, $end);
        $executionEvidence = Database::tableExists('marketing_execution_action_snapshots')
            ? $this->getMarketingExecutionEvidenceSummary($start, $end, 5)
            : [];

        return [
            'period' => ['type' => $periodType, 'start' => $start, 'end' => $end],
            'content_velocity' => [
                'total_created' => array_sum(array_map(static fn(array $row): int => (int) $row['count'], $contentByStatus)),
                'by_status' => $contentByStatus,
                'by_channel' => $contentByChannel,
            ],
            'review_bottlenecks' => $reviewBottlenecks,
            'campaign_performance' => [
                'active_campaigns' => count($this->activeCampaigns(250)),
                'brief_count' => (int) ($briefReadiness['brief_count'] ?? 0),
                'average_readiness' => $briefReadiness['average_readiness'] !== null ? round((float) $briefReadiness['average_readiness'], 1) : null,
            ],
            'campaign_roi' => $campaignRoi,
            'content_influence' => $contentInfluence,
            'landing_page_conversion' => [
                'pages' => Database::tableExists('marketing_landing_pages') ? $this->countRows('marketing_landing_pages', 'id > 0') : 0,
                'by_goal' => $landingByGoal,
            ],
            'landing_page_funnel' => $landingPageFunnel,
            'form_submissions' => $this->formSubmissionAnalytics($start, $end),
            'form_conversion' => $formConversion,
            'utm_usage' => [
                'total' => Database::tableExists('marketing_utm_links') ? $this->countRows('marketing_utm_links', "created_at >= '{$start}' AND created_at < DATE_ADD('{$end}', INTERVAL 1 DAY)") : 0,
                'by_source' => $utmBySource,
            ],
            'utm_performance' => $utmPerformance,
            'attributed_revenue' => $this->attributedRevenueAnalytics($start, $end),
            'revenue_attribution' => $revenueAttribution,
            'execution_evidence' => $executionEvidence,
        ];
    }

    public function createMarketingAnalyticsSnapshot(string $periodType = 'weekly', ?string $anchorDate = null, ?int $createdBy = null): int
    {
        if (!Database::tableExists('marketing_analytics_snapshots')) {
            throw new RuntimeException('Marketing analytics snapshots are unavailable.');
        }

        $summary = $this->getMarketingAnalyticsSummary($periodType, $anchorDate);
        Database::execute(
            "INSERT INTO marketing_analytics_snapshots
             (workspace_id, uuid, period_type, period_start, period_end, content_velocity_json, review_bottlenecks_json,
              campaign_performance_json, campaign_roi_json, content_influence_json, landing_page_conversion_json,
              landing_page_funnel_json, form_submissions_json, form_conversion_json, utm_usage_json, utm_performance_json,
              attributed_revenue_json, revenue_attribution_json, created_by)
             VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)",
            [
                $this->workspaceId(),
                $this->generateUuid(),
                $summary['period']['type'],
                $summary['period']['start'],
                $summary['period']['end'],
                $this->normalizeJsonValue($summary['content_velocity']),
                $this->normalizeJsonValue($summary['review_bottlenecks']),
                $this->normalizeJsonValue($summary['campaign_performance']),
                $this->normalizeJsonValue($summary['campaign_roi']),
                $this->normalizeJsonValue($summary['content_influence']),
                $this->normalizeJsonValue($summary['landing_page_conversion']),
                $this->normalizeJsonValue($summary['landing_page_funnel']),
                $this->normalizeJsonValue($summary['form_submissions']),
                $this->normalizeJsonValue($summary['form_conversion']),
                $this->normalizeJsonValue($summary['utm_usage']),
                $this->normalizeJsonValue($summary['utm_performance']),
                $this->normalizeJsonValue($summary['attributed_revenue']),
                $this->normalizeJsonValue($summary['revenue_attribution']),
                $createdBy ?? (int) ($_SESSION['user_id'] ?? 0) ?: null,
            ]
        );

        return (int) Database::lastInsertId();
    }

    public function listMarketingAnalyticsSnapshots(string $periodType = '', int $limit = 20, int $offset = 0): array
    {
        if (!Database::tableExists('marketing_analytics_snapshots')) {
            return [];
        }

        $where = ['workspace_id = ?'];
        $params = [$this->workspaceId()];
        if ($periodType !== '') {
            $where[] = 'period_type = ?';
            $params[] = $this->normalizeEnum($periodType, ['weekly', 'monthly'], 'analytics_period');
        }

        return array_map(
            fn(array $row): array => $this->hydrateJsonFields($row, [
                'content_velocity_json',
                'review_bottlenecks_json',
                'campaign_performance_json',
                'campaign_roi_json',
                'content_influence_json',
                'landing_page_conversion_json',
                'landing_page_funnel_json',
                'form_submissions_json',
                'form_conversion_json',
                'utm_usage_json',
                'utm_performance_json',
                'attributed_revenue_json',
                'revenue_attribution_json',
            ]),
            Database::query(
                "SELECT * FROM marketing_analytics_snapshots
                 WHERE " . implode(' AND ', $where) . "
                 ORDER BY period_start DESC, created_at DESC
                 LIMIT {$limit} OFFSET {$offset}",
                $params
            )
        );
    }

    public function listMarketingAssistantRuns(array $filters = [], int $limit = 50, int $offset = 0): array
    {
        if (!Database::tableExists('marketing_assistant_runs')) {
            return [];
        }

        $where = ['ar.workspace_id = ?'];
        $params = [$this->workspaceId()];
        if (!empty($filters['assistant_type'])) {
            $where[] = 'ar.assistant_type = ?';
            $params[] = $this->normalizeEnum((string) $filters['assistant_type'], self::ASSISTANT_TYPES, 'assistant_type');
        }
        if (!empty($filters['content_item_id'])) {
            $where[] = 'ar.linked_content_item_id = ?';
            $params[] = (int) $filters['content_item_id'];
        }

        return array_map(
            fn(array $row): array => $this->hydrateJsonFields($row, ['prompt_inputs_json', 'context_used_json', 'provider_json', 'result_json']),
            Database::query(
                "SELECT ar.*, content.title AS linked_content_title, created_content.title AS created_content_title
                 FROM marketing_assistant_runs ar
                 LEFT JOIN marketing_content_items content ON content.id = ar.linked_content_item_id AND content.workspace_id = ar.workspace_id
                 LEFT JOIN marketing_content_items created_content ON created_content.id = ar.created_content_item_id AND created_content.workspace_id = ar.workspace_id
                 WHERE " . implode(' AND ', $where) . "
                 ORDER BY ar.created_at DESC, ar.id DESC
                 LIMIT {$limit} OFFSET {$offset}",
                $params
            )
        );
    }

    public function captureMarketingAiContextSnapshot(
        string $surface,
        string $promptKey,
        array $context,
        array $provider = [],
        array $links = [],
        ?int $userId = null
    ): int {
        $this->assertMarketingPermission('marketing.write');
        if (!Database::tableExists('marketing_ai_context_snapshots')) {
            return 0;
        }

        $surface = $this->normalizeMarketingAiContextSurface($surface);
        $promptKey = Security::sanitizeInput(trim($promptKey), 'string');
        if ($promptKey === '') {
            $promptKey = 'unknown';
        }

        $workspaceId = $this->workspaceId();
        $links = $this->normalizeMarketingAiContextSnapshotLinks($links, $workspaceId);
        $evidence = $this->extractMarketingAiContextSnapshotEvidence($context, $provider);
        $contextBundle = (array) ($context['context_bundle'] ?? $context['context_bundle_json'] ?? $context);
        $contextBundle = $this->sanitizeJsonCompatible($contextBundle);
        $contextHash = $this->marketingAiContextHash($contextBundle);
        $metadata = $this->sanitizeJsonCompatible($links['metadata_json'] ?? $links['metadata'] ?? []);
        $metadata = array_replace($metadata, [
            'source' => 'marketing_ai_context_evidence',
            'manual_first' => true,
            'external_publish' => false,
            'external_send' => false,
            'captured_at' => date('c'),
        ]);
        $userId = $userId ?? $this->currentUserId();
        if (($userId ?? 0) > 0) {
            $this->assertWorkspaceUser((int) $userId, $workspaceId);
        }

        Database::execute(
            "INSERT INTO marketing_ai_context_snapshots
             (workspace_id, uuid, surface, prompt_key, context_hash, context_score, workspace_brain_score,
              missing_context_json, recommended_inputs_json, linked_records_json, context_bundle_json, provider_json,
              metadata_json, assistant_run_id, content_tool_run_id, creative_run_id, campaign_copilot_run_id,
              content_item_id, campaign_id, campaign_brief_id, landing_page_id, created_by)
             VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)",
            [
                $workspaceId,
                $this->generateUuid(),
                $surface,
                $promptKey,
                $contextHash,
                $evidence['context_score'],
                $evidence['workspace_brain_score'],
                $this->normalizeJsonValue($evidence['missing_context']),
                $this->normalizeJsonValue($evidence['recommended_inputs']),
                $this->normalizeJsonValue($evidence['linked_records']),
                $this->normalizeJsonValue($contextBundle),
                $this->normalizeJsonValue($this->sanitizeJsonCompatible($provider)),
                $this->normalizeJsonValue($metadata),
                $links['assistant_run_id'],
                $links['content_tool_run_id'],
                $links['creative_run_id'],
                $links['campaign_copilot_run_id'],
                $links['content_item_id'],
                $links['campaign_id'],
                $links['campaign_brief_id'],
                $links['landing_page_id'],
                ($userId ?? 0) > 0 ? (int) $userId : null,
            ]
        );

        return (int) Database::lastInsertId();
    }

    public function listMarketingAiContextSnapshots(array $filters = [], int $limit = 100, int $offset = 0): array
    {
        $this->assertMarketingPermission('marketing.read');
        if (!Database::tableExists('marketing_ai_context_snapshots')) {
            return [];
        }

        $limit = min(max($limit, 1), 250);
        $offset = max($offset, 0);
        $where = ['s.workspace_id = ?'];
        $params = [$this->workspaceId()];
        if (!empty($filters['surface'])) {
            $where[] = 's.surface = ?';
            $params[] = $this->normalizeMarketingAiContextSurface((string) $filters['surface']);
        }
        if (!empty($filters['prompt_key'])) {
            $where[] = 's.prompt_key = ?';
            $params[] = Security::sanitizeInput((string) $filters['prompt_key'], 'string');
        }
        foreach ([
            'assistant_run_id',
            'content_tool_run_id',
            'creative_run_id',
            'campaign_copilot_run_id',
            'content_item_id',
            'campaign_id',
            'campaign_brief_id',
            'landing_page_id',
        ] as $field) {
            if (!empty($filters[$field])) {
                $where[] = 's.' . $field . ' = ?';
                $params[] = (int) $filters[$field];
            }
        }

        return array_map(
            fn(array $row): array => $this->hydrateMarketingAiContextSnapshotRow($row),
            Database::query(
                "SELECT s.*, ar.assistant_type, ci.title AS content_title, c.name AS campaign_name,
                        b.title AS campaign_brief_title, lp.title AS landing_page_title, creator.email AS created_by_email
                 FROM marketing_ai_context_snapshots s
                 LEFT JOIN marketing_assistant_runs ar ON ar.id = s.assistant_run_id AND ar.workspace_id = s.workspace_id
                 LEFT JOIN marketing_content_items ci ON ci.id = s.content_item_id AND ci.workspace_id = s.workspace_id
                 LEFT JOIN campaigns c ON c.id = s.campaign_id AND c.workspace_id = s.workspace_id
                 LEFT JOIN marketing_campaign_briefs b ON b.id = s.campaign_brief_id AND b.workspace_id = s.workspace_id
                 LEFT JOIN marketing_landing_pages lp ON lp.id = s.landing_page_id AND lp.workspace_id = s.workspace_id
                 LEFT JOIN users creator ON creator.id = s.created_by
                 WHERE " . implode(' AND ', $where) . "
                 ORDER BY s.created_at DESC, s.id DESC
                 LIMIT {$limit} OFFSET {$offset}",
                $params
            )
        );
    }

    public function getMarketingAiContextSnapshot(int $id): ?array
    {
        $this->assertMarketingPermission('marketing.read');
        if (!Database::tableExists('marketing_ai_context_snapshots')) {
            return null;
        }

        $row = Database::queryOne(
            "SELECT s.*, ar.assistant_type, ci.title AS content_title, c.name AS campaign_name,
                    b.title AS campaign_brief_title, lp.title AS landing_page_title, creator.email AS created_by_email
             FROM marketing_ai_context_snapshots s
             LEFT JOIN marketing_assistant_runs ar ON ar.id = s.assistant_run_id AND ar.workspace_id = s.workspace_id
             LEFT JOIN marketing_content_items ci ON ci.id = s.content_item_id AND ci.workspace_id = s.workspace_id
             LEFT JOIN campaigns c ON c.id = s.campaign_id AND c.workspace_id = s.workspace_id
             LEFT JOIN marketing_campaign_briefs b ON b.id = s.campaign_brief_id AND b.workspace_id = s.workspace_id
             LEFT JOIN marketing_landing_pages lp ON lp.id = s.landing_page_id AND lp.workspace_id = s.workspace_id
             LEFT JOIN users creator ON creator.id = s.created_by
             WHERE s.workspace_id = ? AND s.id = ?
             LIMIT 1",
            [$this->workspaceId(), $id]
        );

        return $row ? $this->hydrateMarketingAiContextSnapshotRow($row) : null;
    }

    public function getMarketingAiContextEvidence(?int $userId = null, int $limit = 8): array
    {
        $this->assertMarketingPermission('marketing.read');
        $limit = min(max($limit, 1), 25);
        if (!Database::tableExists('marketing_ai_context_snapshots')) {
            return [
                'status' => 'unavailable',
                'counts' => ['total' => 0, 'surfaces' => []],
                'latest_snapshots' => [],
                'recommended_actions' => ['Run migration 368 to enable AI context evidence.'],
            ];
        }

        $workspaceId = $this->workspaceId();
        $totals = Database::queryOne(
            "SELECT COUNT(*) AS total,
                    COUNT(DISTINCT context_hash) AS distinct_contexts,
                    ROUND(AVG(context_score), 4) AS average_context_score,
                    ROUND(AVG(workspace_brain_score), 0) AS average_workspace_brain_score,
                    MAX(created_at) AS latest_snapshot_at
             FROM marketing_ai_context_snapshots
             WHERE workspace_id = ?",
            [$workspaceId]
        ) ?: [];
        $surfaceRows = Database::query(
            "SELECT surface, COUNT(*) AS count
             FROM marketing_ai_context_snapshots
             WHERE workspace_id = ?
             GROUP BY surface
             ORDER BY count DESC, surface ASC",
            [$workspaceId]
        );
        $surfaces = [];
        foreach ($surfaceRows as $row) {
            $surfaces[(string) $row['surface']] = (int) $row['count'];
        }
        $missingRows = Database::query(
            "SELECT missing_context_json
             FROM marketing_ai_context_snapshots
             WHERE workspace_id = ?
             ORDER BY created_at DESC, id DESC
             LIMIT 25",
            [$workspaceId]
        );
        $missingCounts = [];
        foreach ($missingRows as $row) {
            foreach ((array) (json_decode((string) ($row['missing_context_json'] ?? '[]'), true) ?: []) as $missing) {
                $missing = Security::sanitizeInput((string) $missing, 'string');
                if ($missing !== '') {
                    $missingCounts[$missing] = (int) ($missingCounts[$missing] ?? 0) + 1;
                }
            }
        }
        arsort($missingCounts);

        $latestSnapshots = $this->listMarketingAiContextSnapshots([], $limit, 0);
        $total = (int) ($totals['total'] ?? 0);
        $averageScore = round((float) ($totals['average_context_score'] ?? 0), 4);
        $status = $total === 0 ? 'needs_evidence' : ($averageScore >= 0.7 ? 'ready' : 'attention');
        $recommended = [];
        if ($total === 0) {
            $recommended[] = 'Run a content draft or assistant to capture the first AI context evidence snapshot.';
        }
        if ($missingCounts !== []) {
            $recommended[] = 'Fill the most common missing AI context: ' . implode(', ', array_slice(array_keys($missingCounts), 0, 3)) . '.';
        }
        if (empty($surfaces['content_draft'])) {
            $recommended[] = 'Generate a content draft after adding brand, persona, offer, and campaign context.';
        }
        if (empty($surfaces['assistant'])) {
            $recommended[] = 'Run an assistant from the Assistant Command Center to prove advisory context use.';
        }

        return [
            'status' => $status,
            'counts' => [
                'total' => $total,
                'distinct_contexts' => (int) ($totals['distinct_contexts'] ?? 0),
                'surfaces' => $surfaces,
                'missing_context' => $missingCounts,
            ],
            'average_context_score' => $averageScore,
            'average_workspace_brain_score' => (int) ($totals['average_workspace_brain_score'] ?? 0),
            'latest_snapshot_at' => $totals['latest_snapshot_at'] ?? null,
            'latest_snapshots' => $latestSnapshots,
            'recommended_actions' => array_values(array_unique($recommended)),
            'guardrails' => [
                'Context evidence is audit-only and never publishes, sends, or overwrites drafts.',
                'Snapshots store sanitized context bundles, linked record ids, provider metadata, and missing inputs.',
            ],
        ];
    }

    public function getMarketingAiContextControlPanel(array $input = [], ?int $userId = null): array
    {
        $this->assertMarketingPermission('marketing.read');
        $input = $this->sanitizeToolInput($input);
        $userId = $userId ?? ($this->currentUserId() ?: null);
        if (($userId ?? 0) > 0) {
            $this->assertWorkspaceUser((int) $userId, $this->workspaceId());
        }

        $assistantType = (string) ($input['assistant_type'] ?? 'strategist');
        if (!in_array($assistantType, self::ASSISTANT_TYPES, true)) {
            $assistantType = 'strategist';
        }
        $promptKey = $this->marketingAssistantPromptKey($assistantType);
        $workspaceBrain = $this->getMarketingAiWorkspaceBrain($userId);
        $contextEvidence = $this->getMarketingAiContextEvidence($userId, 6);
        $linkedRecords = [];
        $selectedRecords = [];
        $missingInputs = [];

        $recordCard = static function (
            string $key,
            string $label,
            string $href,
            array $record,
            string $missingMessage,
            string $readyMessage = ''
        ) use (&$selectedRecords, &$missingInputs): void {
            $ready = $record !== [];
            $selectedRecords[$key] = [
                'key' => $key,
                'label' => $label,
                'href' => $href,
                'status' => $ready ? 'ready' : 'missing',
                'title' => $ready
                    ? (string) ($record['title'] ?? $record['name'] ?? $record['keyword'] ?? $label)
                    : $missingMessage,
                'message' => $ready ? ($readyMessage !== '' ? $readyMessage : 'Selected context is available.') : $missingMessage,
            ];
            if (!$ready) {
                $missingInputs[] = $missingMessage;
            }
        };

        $contentId = (int) ($input['content_item_id'] ?? $input['id'] ?? 0);
        $content = $contentId > 0 ? ($this->getContentItem($contentId) ?? []) : [];
        if ($content !== []) {
            $linkedRecords['content_item'] = $content;
        }

        $campaignBriefId = (int) ($input['campaign_brief_id'] ?? $content['campaign_brief_id'] ?? 0);
        $landingPageId = (int) ($input['landing_page_id'] ?? $content['landing_page_id'] ?? 0);
        $brandProfileId = (int) ($input['brand_profile_id'] ?? $content['brand_profile_id'] ?? 0);
        $personaId = (int) ($input['persona_id'] ?? $content['persona_id'] ?? 0);
        $seoTopicId = (int) ($input['seo_topic_id'] ?? $content['seo_topic_id'] ?? 0);
        $campaignId = (int) ($input['campaign_id'] ?? $content['campaign_id'] ?? 0);

        $campaignBrief = $campaignBriefId > 0 ? ($this->getCampaignBrief($campaignBriefId) ?? []) : [];
        if ($campaignBrief !== []) {
            $linkedRecords['campaign_brief'] = $campaignBrief;
            $campaignId = $campaignId > 0 ? $campaignId : (int) ($campaignBrief['campaign_id'] ?? 0);
            $landingPageId = $landingPageId > 0 ? $landingPageId : (int) ($campaignBrief['landing_page_id'] ?? 0);
            $personaId = $personaId > 0 ? $personaId : (int) ($campaignBrief['persona_id'] ?? 0);
        }

        $landingPage = $landingPageId > 0 ? ($this->getLandingPage($landingPageId) ?? []) : [];
        if ($landingPage !== []) {
            $linkedRecords['landing_page'] = $landingPage;
            $campaignId = $campaignId > 0 ? $campaignId : (int) ($landingPage['campaign_id'] ?? 0);
        }

        $brandProfile = $brandProfileId > 0 ? ($this->getBrandProfile($brandProfileId) ?? []) : [];
        $persona = $personaId > 0 ? ($this->getPersona($personaId) ?? []) : [];
        $seoTopic = $seoTopicId > 0 ? ($this->getSeoTopic($seoTopicId) ?? []) : [];
        $campaign = [];
        if ($campaignId > 0 && Database::tableExists('campaigns')) {
            $campaign = Database::queryOne(
                "SELECT id, name, description, objective, channel_mix, status
                 FROM campaigns
                 WHERE workspace_id = ? AND id = ?",
                [$this->workspaceId(), $campaignId]
            ) ?: [];
        }
        $contentMedia = $contentId > 0 && Database::tableExists('marketing_content_media')
            ? $this->listContentMedia($contentId)
            : [];

        foreach ([
            'campaign' => $campaign,
            'brand_profile' => $brandProfile,
            'persona' => $persona,
            'seo_topic' => $seoTopic,
            'content_media' => $contentMedia,
        ] as $key => $record) {
            if ($record !== []) {
                $linkedRecords[$key] = $record;
            }
        }

        $recordCard('content_item', 'Content Item', $contentId > 0 ? 'marketing_content_view.php?id=' . $contentId : 'marketing_content.php', $content, 'Link a content item when the assistant should use a specific draft.', 'The selected content item can shape the assistant response.');
        $recordCard('campaign_brief', 'Campaign Brief', $campaignBriefId > 0 ? 'marketing_brief_view.php?id=' . $campaignBriefId : 'marketing_briefs.php', $campaignBrief, 'Link a campaign brief for strategy, offer, audience, channels, and timeline.');
        $recordCard('brand_profile', 'Brand Profile', 'marketing_brand.php', $brandProfile, 'Select or create a brand profile so AI applies voice, tone, proof, and CTA rules.');
        $recordCard('persona', 'Persona', 'marketing_personas.php', $persona, 'Select or create a persona so AI can tune pains, goals, objections, and channels.');
        $recordCard('landing_page', 'Landing Page', $landingPageId > 0 ? 'marketing_landing_page_view.php?id=' . $landingPageId : 'marketing_landing_pages.php', $landingPage, 'Link a landing page when the assistant should respect conversion copy and form placement.');
        $recordCard('media', 'Media Context', 'marketing_assets.php', $contentMedia, 'Attach media when the assistant should consider visuals, captions, alt text, or channel media requirements.');

        if ($content !== []) {
            if (trim((string) ($content['objective'] ?? '')) === '') {
                $missingInputs[] = 'Add a content objective before asking AI for strategy or copy.';
            }
            if (trim((string) ($content['target_audience'] ?? '')) === '') {
                $missingInputs[] = 'Add a target audience before asking AI to write or repurpose content.';
            }
            if ((int) ($content['campaign_id'] ?? 0) < 1 && $campaign === []) {
                $missingInputs[] = 'Connect a campaign so AI can align recommendations to CRM campaign reporting.';
            }
        }
        foreach ((array) ($workspaceBrain['missing_context'] ?? []) as $missing) {
            $missingRow = is_array($missing) ? $missing : ['label' => $missing];
            $label = trim((string) ($missingRow['label'] ?? ''));
            $message = trim((string) ($missingRow['message'] ?? ''));
            if ($label !== '') {
                $missingInputs[] = $message !== '' ? $label . ': ' . $message : $label;
            }
        }
        $missingInputs = array_values(array_unique(array_filter($missingInputs)));

        $bundle = $this->buildMarketingContextBundle($promptKey, $input + ['assistant_type' => $assistantType], $linkedRecords);
        $quality = (array) ($bundle['bundle_quality'] ?? []);
        $selectedScore = (int) round(((float) ($quality['context_quality_score'] ?? 0)) * 100);
        $workspaceScore = (int) ($workspaceBrain['score'] ?? 0);
        $score = (int) round(($selectedScore * 0.6) + ($workspaceScore * 0.4));
        $status = $score >= 80 ? 'ready' : ($score >= 45 ? 'attention' : 'thin');
        $recommendedActions = [];
        if ($missingInputs !== []) {
            $recommendedActions[] = 'Fill the top missing context before running high-stakes copy, launch, or performance analysis.';
        }
        if ($content === []) {
            $recommendedActions[] = 'Optionally link a content item when you want record-specific draft or rewrite guidance.';
        }
        if ($contextEvidence['status'] ?? '' === 'needs_evidence') {
            $recommendedActions[] = 'Run one assistant or content draft after adding context to capture an audit snapshot.';
        }
        if ($recommendedActions === []) {
            $recommendedActions[] = 'Run the assistant with this context, then review before saving or applying any draft-side change.';
        }

        return [
            'score' => $score,
            'status' => $status,
            'assistant_type' => $assistantType,
            'prompt_key' => $promptKey,
            'selected_records' => $selectedRecords,
            'linked_record_keys' => array_keys($linkedRecords),
            'missing_inputs' => array_slice($missingInputs, 0, 12),
            'context_bundle_quality' => $quality,
            'workspace_brain' => [
                'score' => $workspaceScore,
                'status' => (string) ($workspaceBrain['status'] ?? 'thin'),
                'used_context_keys' => array_slice((array) ($workspaceBrain['used_context_keys'] ?? []), 0, 12),
            ],
            'evidence' => [
                'status' => (string) ($contextEvidence['status'] ?? 'needs_evidence'),
                'snapshot_count' => (int) ($contextEvidence['counts']['total'] ?? 0),
                'average_context_score' => (float) ($contextEvidence['average_context_score'] ?? 0),
            ],
            'recommended_actions' => $recommendedActions,
            'safe_usage_policy' => [
                'manual_first' => true,
                'draft_side_only' => true,
                'external_publish' => false,
                'external_send' => false,
                'external_media_generation' => false,
                'automatic_overwrite' => false,
                'requires_human_review' => true,
            ],
            'recommended_product_decision' => 'Make AI context visible before every assistant run: operators should see selected records, missing inputs, evidence history, and the manual-first boundary before generation.',
            'generated_at' => date('c'),
        ];
    }

    public function getMarketingAiContextQualityGate(array $input = [], ?int $userId = null): array
    {
        $this->assertMarketingPermission('marketing.read');
        $input = $this->sanitizeToolInput($input);
        $control = $this->getMarketingAiContextControlPanel($input, $userId);
        $brain = (array) ($control['workspace_brain'] ?? []);
        $evidence = (array) ($control['evidence'] ?? []);
        $selectedRecords = (array) ($control['selected_records'] ?? []);
        $missingInputs = (array) ($control['missing_inputs'] ?? []);
        $readyRecords = count(array_filter($selectedRecords, static fn(array $record): bool => (string) ($record['status'] ?? '') === 'ready'));
        $recordTotal = count($selectedRecords);
        $score = (int) ($control['score'] ?? 0);
        $criticalMissing = [];
        foreach ($missingInputs as $missing) {
            $text = strtolower((string) $missing);
            if (
                str_contains($text, 'brand')
                || str_contains($text, 'persona')
                || str_contains($text, 'offer')
                || str_contains($text, 'campaign')
                || str_contains($text, 'compliance')
            ) {
                $criticalMissing[] = (string) $missing;
            }
        }
        $status = match (true) {
            $score >= 80 && $criticalMissing === [] => 'ready',
            $score >= 55 => 'needs_context',
            default => 'blocked',
        };
        $generationMode = match ($status) {
            'ready' => 'safe_to_generate_with_review',
            'needs_context' => 'generate_only_for_low_risk_drafts',
            default => 'manual_context_required',
        };
        $recommendations = [];
        if ($criticalMissing !== []) {
            $recommendations[] = 'Fill critical context before high-stakes AI generation: ' . implode('; ', array_slice($criticalMissing, 0, 3));
        }
        if ((int) ($brain['score'] ?? 0) < 80) {
            $recommendations[] = 'Improve workspace brain coverage before scaling AI-assisted campaign or content production.';
        }
        if ((int) ($evidence['snapshot_count'] ?? 0) < 1) {
            $recommendations[] = 'Capture at least one AI context evidence snapshot after adding core context.';
        }
        if ($readyRecords < max(1, (int) ceil($recordTotal / 2))) {
            $recommendations[] = 'Select more record-specific context when asking for campaign, content, or landing-page outputs.';
        }
        if ($recommendations === []) {
            $recommendations[] = 'Proceed with AI generation, then review and apply manually.';
        }

        return [
            'status' => $status,
            'score' => $score,
            'generation_mode' => $generationMode,
            'critical_missing' => array_values(array_unique($criticalMissing)),
            'record_coverage' => [
                'ready' => $readyRecords,
                'total' => $recordTotal,
                'score' => $recordTotal > 0 ? (int) round(($readyRecords / $recordTotal) * 100) : 0,
            ],
            'workspace_brain' => $brain,
            'evidence' => $evidence,
            'control_panel' => $control,
            'recommendations' => array_slice(array_values(array_unique($recommendations)), 0, 6),
            'guardrails' => [
                'workspace_scoped' => true,
                'draft_side_only' => true,
                'manual_review_required' => true,
                'automatic_overwrite' => false,
                'external_publish' => false,
                'external_send' => false,
                'external_api_calls' => false,
            ],
            'recommended_product_decision' => 'Treat this gate as the visible AI preflight: high-stakes generation should wait until brand, persona, offer, campaign, compliance, and evidence context are strong enough.',
            'generated_at' => date('c'),
        ];
    }

    public function getMarketingAssistantCommandCenter(?int $userId = null): array
    {
        $this->assertMarketingPermission('marketing.read');
        $recentRuns = $this->listMarketingAssistantRuns([], 50, 0);
        $runsByType = array_fill_keys(self::ASSISTANT_TYPES, 0);
        $statusCounts = [];
        $lastRunByType = [];
        foreach ($recentRuns as $run) {
            $type = (string) ($run['assistant_type'] ?? '');
            if (isset($runsByType[$type])) {
                $runsByType[$type]++;
                $lastRunByType[$type] ??= $run;
            }
            $status = (string) ($run['status'] ?? 'unknown');
            $statusCounts[$status] = (int) ($statusCounts[$status] ?? 0) + 1;
        }

        $definitions = [
            'strategist' => ['label' => 'Strategist', 'best_for' => 'Positioning, offer, audience, and campaign trade-off decisions.', 'prompt_hint' => 'What strategy decision should Marketing make next?', 'side_effect' => 'Recommendation only'],
            'content_planner' => ['label' => 'Content Planner', 'best_for' => 'Campaign content calendars, topic coverage, and draft-side content plans.', 'prompt_hint' => 'What campaign or theme needs a content plan?', 'side_effect' => 'Can create draft content when explicitly checked'],
            'seo_researcher' => ['label' => 'SEO Researcher', 'best_for' => 'Keyword intent, content gaps, and search-oriented page recommendations.', 'prompt_hint' => 'Which topic, landing page, or audience should SEO support?', 'side_effect' => 'Recommendation only'],
            'copywriter' => ['label' => 'Copywriter', 'best_for' => 'First drafts, rewrites, CTA sharpening, and channel-specific copy.', 'prompt_hint' => 'What copy should be drafted or improved?', 'side_effect' => 'Creates a draft-side content tool run when linked to content'],
            'email_sequence_builder' => ['label' => 'Email Sequence Builder', 'best_for' => 'Manual email sequence planning and export-ready nurture structure.', 'prompt_hint' => 'What audience and offer should the sequence support?', 'side_effect' => 'Recommendation only'],
            'landing_page_optimizer' => ['label' => 'Landing Page Optimizer', 'best_for' => 'Hero, proof, CTA, FAQ, form placement, and conversion copy reviews.', 'prompt_hint' => 'Which landing page or conversion goal needs improvement?', 'side_effect' => 'Recommendation only'],
            'repurposing' => ['label' => 'Repurposing Assistant', 'best_for' => 'Turning long-form ideas into channel variants and manual distribution drafts.', 'prompt_hint' => 'What content should be repurposed and for which channels?', 'side_effect' => 'Recommendation only'],
            'performance_analyst' => ['label' => 'Performance Analyst', 'best_for' => 'Reading attribution, conversion, handoff, and campaign performance signals.', 'prompt_hint' => 'Which content, campaign, or reporting period needs analysis?', 'side_effect' => 'Can add a draft-side comment when linked to content'],
        ];
        $commands = [];
        foreach (self::ASSISTANT_TYPES as $type) {
            $definition = $definitions[$type] ?? ['label' => ucwords(str_replace('_', ' ', $type)), 'best_for' => 'Marketing support.', 'prompt_hint' => 'What should this assistant help with?', 'side_effect' => 'Recommendation only'];
            $commands[] = [
                'assistant_type' => $type,
                'label' => $definition['label'],
                'best_for' => $definition['best_for'],
                'prompt_hint' => $definition['prompt_hint'],
                'side_effect' => $definition['side_effect'],
                'recent_runs' => (int) ($runsByType[$type] ?? 0),
                'last_status' => (string) ($lastRunByType[$type]['status'] ?? 'not_run'),
            ];
        }
        $workspaceBrain = $this->getMarketingAiWorkspaceBrain($userId);
        $contextCompleteness = Database::tableExists('marketing_context_items') ? $this->getContextCompleteness() : ['score' => 0, 'missing' => []];
        $contextCompleteness['workspace_brain_score'] = (int) ($workspaceBrain['score'] ?? 0);
        $contextCompleteness['workspace_brain_status'] = (string) ($workspaceBrain['status'] ?? 'thin');
        $contextCompleteness['missing_workspace_context'] = (array) ($workspaceBrain['missing_context'] ?? []);

        return [
            'commands' => $commands,
            'recent_runs' => array_slice($recentRuns, 0, 8),
            'status_counts' => $statusCounts,
            'context_completeness' => $contextCompleteness,
            'workspace_brain' => $workspaceBrain,
            'context_evidence' => $this->getMarketingAiContextEvidence($userId, 8),
            'next_best_actions' => $this->getMarketingNextBestActions($userId, 5),
            'guardrails' => [
                'Assistants use saved Marketing and CRM context before generating recommendations.',
                'The AI workspace brain explains missing context and the records that shaped each suggestion.',
                'Assistant outputs are draft-side: recommendations, content drafts, comments, or tool runs.',
                'No assistant publishes, sends email, posts to social, changes ads, or overwrites user drafts automatically.',
            ],
        ];
    }

    public function runMarketingAssistant(string $assistantType, array $input = []): array
    {
        if (!Database::tableExists('marketing_assistant_runs')) {
            throw new RuntimeException('Marketing assistants are unavailable.');
        }

        $assistantType = $this->normalizeEnum($assistantType, self::ASSISTANT_TYPES, 'assistant_type');
        $input = $this->sanitizeToolInput($input);
        $linkedContentId = (int) ($input['content_item_id'] ?? 0);
        $linkedBriefId = (int) ($input['campaign_brief_id'] ?? 0);
        $linkedLandingId = (int) ($input['landing_page_id'] ?? 0);
        if ($linkedContentId > 0) {
            $this->assertWorkspaceRecord('marketing_content_items', $linkedContentId, $this->workspaceId());
        }
        if ($linkedBriefId > 0) {
            $this->assertWorkspaceRecord('marketing_campaign_briefs', $linkedBriefId, $this->workspaceId());
        }
        if ($linkedLandingId > 0) {
            $this->assertWorkspaceRecord('marketing_landing_pages', $linkedLandingId, $this->workspaceId());
        }

        $linkedRecords = [];
        if ($linkedContentId > 0) {
            $linkedRecords['content_item'] = $this->getContentItem($linkedContentId) ?? [];
        }
        if ($linkedBriefId > 0) {
            $linkedRecords['campaign_brief'] = $this->getCampaignBrief($linkedBriefId) ?? [];
        }
        if ($linkedLandingId > 0) {
            $linkedRecords['landing_page'] = $this->getLandingPage($linkedLandingId) ?? [];
        }
        $promptKey = $this->marketingAssistantPromptKey($assistantType);
        $bundleInputs = $input + ['assistant_type' => $assistantType];
        $bundle = $this->buildMarketingContextBundle($promptKey, $bundleInputs, $linkedRecords);
        $context = [
            'context_completeness' => Database::tableExists('marketing_context_items') ? $this->getContextCompleteness() : [],
            'workspace_brain' => (array) ($bundle['blocks']['workspace_brain'] ?? []),
            'analytics' => Database::tableExists('marketing_analytics_snapshots') ? $this->getMarketingAnalyticsSummary('weekly') : [],
            'recent_content' => $this->listContentItems(['exclude_status' => 'archived'], 5, 0),
            'linked_records' => $linkedRecords,
            'prompt_key' => $promptKey,
            'context_score' => (float) ($bundle['bundle_quality']['context_quality_score'] ?? 0),
            'context_bundle' => $bundle,
        ];
        $aiResult = $this->runMarketingAiPrompt(
            $promptKey,
            $bundle,
            $bundleInputs,
            'marketing_assistant_' . $assistantType,
            fn(): string => $this->assistantRecommendation($assistantType, $input, $context)
        );
        $resultText = $aiResult['text'];
        $result = ['recommendation' => $resultText];
        $provider = $aiResult['provider'];
        $provider['message'] = $provider['message'] ?? 'Assistant completed with CRM context and no external publishing.';
        $provider['context_score'] = (float) ($bundle['bundle_quality']['context_quality_score'] ?? 0);
        $provider['workspace_brain_score'] = (int) ($context['workspace_brain']['score'] ?? 0);
        $provider['missing_context'] = array_slice((array) ($context['workspace_brain']['missing_context'] ?? []), 0, 6);
        $provider['recommended_context_inputs'] = (array) ($context['workspace_brain']['recommended_inputs'] ?? []);
        $createdContentId = null;
        $createdCommentId = null;
        $createdToolRunId = null;
        $status = 'completed';

        try {
            if ($assistantType === 'content_planner' && !empty($input['create_draft'])) {
                $createdContentId = $this->createContentItem([
                    'title' => 'Assistant Plan: ' . substr((string) ($input['prompt'] ?? 'Marketing content'), 0, 80),
                    'content_type' => 'blog_post',
                    'channel' => 'blog',
                    'status' => 'idea',
                    'draft_body' => $resultText,
                    'campaign_brief_id' => $linkedBriefId ?: null,
                    'created_by' => (int) ($input['created_by'] ?? ($_SESSION['user_id'] ?? 0)) ?: null,
                ]);
            }
            if ($assistantType === 'copywriter' && $linkedContentId > 0) {
                $toolRun = $this->runContentTool($linkedContentId, 'first_draft', ['created_by' => (int) ($input['created_by'] ?? ($_SESSION['user_id'] ?? 0)) ?: null]);
                $createdToolRunId = (int) $toolRun['id'];
            }
            if ($assistantType === 'performance_analyst' && $linkedContentId > 0) {
                $createdCommentId = $this->addContentComment($linkedContentId, $resultText, (int) ($input['created_by'] ?? ($_SESSION['user_id'] ?? 0)) ?: null);
            }
        } catch (Throwable $e) {
            $status = 'failed';
            $result = ['error' => $e->getMessage(), 'recommendation' => $resultText];
            $provider['success'] = false;
            $provider['message'] = $e->getMessage();
        }
        $provider['side_effects'] = [
            'created_content_item_id' => $createdContentId,
            'created_comment_id' => $createdCommentId,
            'created_tool_run_id' => $createdToolRunId,
            'external_publish' => false,
            'external_send' => false,
        ];

        $runId = $this->createMarketingAssistantRun([
            'assistant_type' => $assistantType,
            'status' => $status,
            'prompt_inputs_json' => $input,
            'context_used_json' => $context,
            'provider_json' => $provider,
            'result_json' => $result,
            'linked_content_item_id' => $linkedContentId ?: null,
            'linked_campaign_brief_id' => $linkedBriefId ?: null,
            'linked_landing_page_id' => $linkedLandingId ?: null,
            'created_content_item_id' => $createdContentId,
            'created_comment_id' => $createdCommentId,
            'created_tool_run_id' => $createdToolRunId,
            'created_by' => (int) ($input['created_by'] ?? ($_SESSION['user_id'] ?? 0)) ?: null,
        ]);
        $snapshotId = $this->captureMarketingAiContextSnapshot(
            'assistant',
            $promptKey,
            $context,
            $provider,
            [
                'assistant_run_id' => $runId,
                'content_item_id' => $linkedContentId ?: null,
                'campaign_brief_id' => $linkedBriefId ?: null,
                'landing_page_id' => $linkedLandingId ?: null,
            ],
            (int) ($input['created_by'] ?? ($_SESSION['user_id'] ?? 0)) ?: null
        );

        return [
            'id' => $runId,
            'assistant_type' => $assistantType,
            'status' => $status,
            'result' => $result,
            'created_content_item_id' => $createdContentId,
            'created_comment_id' => $createdCommentId,
            'created_tool_run_id' => $createdToolRunId,
            'context_snapshot_id' => $snapshotId > 0 ? $snapshotId : null,
        ];
    }

    public function listContextItems(array $filters = [], int $limit = 100, int $offset = 0): array
    {
        $workspace = $this->workspaceClause('ci.');
        $where = [$workspace['sql']];
        $params = $workspace['params'];
        if (!empty($filters['item_type'])) {
            $where[] = 'ci.item_type = ?';
            $params[] = $this->normalizeEnum((string) $filters['item_type'], self::CONTEXT_ITEM_TYPES, 'context_type');
        }
        if (!empty($filters['status'])) {
            $where[] = 'ci.status = ?';
            $params[] = $this->normalizeEnum((string) $filters['status'], self::CONTEXT_STATUSES, 'context_status');
        } elseif (empty($filters['include_archived'])) {
            $where[] = "ci.status <> 'archived'";
        }
        if (!empty($filters['persona_id'])) {
            $where[] = 'ci.persona_id = ?';
            $params[] = (int) $filters['persona_id'];
        }

        return array_map(
            fn(array $row): array => $this->hydrateJsonFields($row, ['metadata_json']),
            Database::query(
                "SELECT ci.*, p.name AS persona_name, u.email AS created_by_email
                 FROM marketing_context_items ci
                 LEFT JOIN marketing_personas p ON p.id = ci.persona_id AND p.workspace_id = ci.workspace_id
                 LEFT JOIN users u ON u.id = ci.created_by
                 WHERE " . implode(' AND ', $where) . "
                 ORDER BY FIELD(ci.item_type, 'offer','content_pillar','proof_point','differentiator','default_cta','competitor','compliance_term'),
                          ci.updated_at DESC
                 LIMIT {$limit} OFFSET {$offset}",
                $params
            )
        );
    }

    public function createContextItem(array $data): int
    {
        $normalized = $this->normalizeContextItemData($data, true);
        Database::execute(
            "INSERT INTO marketing_context_items
             (workspace_id, uuid, item_type, title, body, channel, persona_id, status, metadata_json, created_by)
             VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)",
            [
                $this->workspaceId(),
                $this->generateUuid(),
                $normalized['item_type'],
                $normalized['title'],
                $normalized['body'],
                $normalized['channel'],
                $normalized['persona_id'],
                $normalized['status'],
                $normalized['metadata_json'],
                $normalized['created_by'],
            ]
        );

        return (int) Database::lastInsertId();
    }

    public function getContextCompleteness(): array
    {
        $types = self::CONTEXT_ITEM_TYPES;
        $counts = [];
        if (Database::tableExists('marketing_brand_profiles')) {
            $counts['brand_profile'] = count($this->listBrandProfiles(1, 0));
        }
        if (Database::tableExists('marketing_personas')) {
            $counts['persona'] = count($this->listPersonas(1, 0));
        }
        foreach ($types as $type) {
            $row = Database::queryOne(
                "SELECT COUNT(*) AS count FROM marketing_context_items WHERE workspace_id = ? AND item_type = ? AND status = 'active'",
                [$this->workspaceId(), $type]
            );
            $counts[$type] = (int) ($row['count'] ?? 0);
        }

        $required = array_merge(['brand_profile', 'persona'], $types);
        $complete = 0;
        $missing = [];
        foreach ($required as $key) {
            if ((int) ($counts[$key] ?? 0) > 0) {
                $complete++;
            } else {
                $missing[] = $key;
            }
        }

        return [
            'score' => (int) round(($complete / max(1, count($required))) * 100),
            'counts' => $counts,
            'missing' => $missing,
        ];
    }

    public function getMarketingOnboardingStatus(): array
    {
        $steps = $this->marketingOnboardingSteps();
        $complete = 0;
        $missing = [];

        foreach ($steps as $key => $step) {
            if (!empty($step['complete'])) {
                $complete++;
            } else {
                $missing[] = $key;
            }
        }

        $score = (int) round(($complete / max(1, count($steps))) * 100);
        $state = $this->upsertMarketingOnboardingState($score);
        $starterPack = $this->starterPackState($state);

        return [
            'score' => $score,
            'complete_count' => $complete,
            'total_count' => count($steps),
            'steps' => $steps,
            'missing' => $missing,
            'state' => $state,
            'starter_pack' => $starterPack,
        ];
    }

