    private function normalizeHandoffRuleData(array $data, bool $forCreate): array
    {
        $workspaceId = $this->workspaceId();
        $normalized = [];

        if ($forCreate || array_key_exists('name', $data)) {
            $name = Security::sanitizeInput((string) ($data['name'] ?? ''), 'string');
            if ($name === '') {
                throw new \InvalidArgumentException('Handoff rule name is required.');
            }
            $normalized['name'] = mb_substr($name, 0, 180);
        }
        if ($forCreate || array_key_exists('status', $data)) {
            $normalized['status'] = $this->normalizeEnum((string) ($data['status'] ?? 'draft'), self::HANDOFF_RULE_STATUSES, 'handoff_rule_status');
        }
        if ($forCreate || array_key_exists('priority', $data)) {
            $normalized['priority'] = $this->normalizeEnum((string) ($data['priority'] ?? 'high'), self::HANDOFF_PRIORITIES, 'handoff_priority');
        }
        if ($forCreate || array_key_exists('source_type', $data)) {
            $normalized['source_type'] = $this->normalizeEnum((string) ($data['source_type'] ?? 'any'), self::HANDOFF_SOURCE_TYPES, 'handoff_source_type');
        }

        foreach ([
            'landing_page_id' => 'marketing_landing_pages',
            'form_id' => 'forms',
            'campaign_id' => 'campaigns',
            'conversion_goal_id' => 'marketing_conversion_goals',
        ] as $field => $table) {
            if ($forCreate || array_key_exists($field, $data)) {
                $id = (int) ($data[$field] ?? 0);
                if ($id > 0) {
                    $this->assertWorkspaceRecord($table, $id, $workspaceId);
                    $normalized[$field] = $id;
                } else {
                    $normalized[$field] = null;
                }
            }
        }

        if ($forCreate || array_key_exists('assigned_to', $data)) {
            $assignedTo = (int) ($data['assigned_to'] ?? 0);
            if ($assignedTo > 0) {
                $this->assertWorkspaceUser($assignedTo, $workspaceId);
                $normalized['assigned_to'] = $assignedTo;
            } else {
                $normalized['assigned_to'] = null;
            }
        }
        if ($forCreate || array_key_exists('sla_minutes', $data)) {
            $normalized['sla_minutes'] = min(max((int) ($data['sla_minutes'] ?? 1440), 15), 43200);
        }
        if ($forCreate || array_key_exists('task_title_template', $data)) {
            $template = Security::sanitizeInput((string) ($data['task_title_template'] ?? ''), 'string');
            $normalized['task_title_template'] = $template !== '' ? mb_substr($template, 0, 255) : null;
        }
        if ($forCreate || array_key_exists('metadata_json', $data)) {
            $normalized['metadata_json'] = $this->normalizeJsonValue($data['metadata_json'] ?? null);
        }
        if ($forCreate) {
            $createdBy = (int) ($data['created_by'] ?? $this->currentUserId());
            if ($createdBy > 0) {
                $this->assertWorkspaceUser($createdBy, $workspaceId);
            }
            $normalized['created_by'] = $createdBy > 0 ? $createdBy : null;
        }

        return $normalized;
    }

    private function normalizeLeadHandoffData(array $data, bool $forCreate, int $workspaceId): array
    {
        $normalized = ['workspace_id' => $workspaceId];

        foreach ([
            'conversion_event_id' => 'marketing_conversion_events',
            'tracking_event_id' => 'marketing_tracking_events',
            'visitor_session_id' => 'marketing_visitor_sessions',
            'landing_page_id' => 'marketing_landing_pages',
            'campaign_id' => 'campaigns',
            'content_item_id' => 'marketing_content_items',
            'form_id' => 'forms',
            'conversion_goal_id' => 'marketing_conversion_goals',
            'contact_id' => 'contacts',
            'deal_id' => 'deals',
            'handoff_rule_id' => 'marketing_handoff_rules',
            'task_id' => 'tasks',
        ] as $field => $table) {
            if ($forCreate || array_key_exists($field, $data)) {
                $id = (int) ($data[$field] ?? 0);
                if ($id > 0) {
                    $this->assertWorkspaceRecord($table, $id, $workspaceId);
                    $normalized[$field] = $id;
                } else {
                    $normalized[$field] = null;
                }
            }
        }

        if ($forCreate || array_key_exists('status', $data)) {
            $normalized['status'] = $this->normalizeEnum((string) ($data['status'] ?? 'new'), self::LEAD_HANDOFF_STATUSES, 'lead_handoff_status');
        }
        if ($forCreate || array_key_exists('priority', $data)) {
            $normalized['priority'] = $this->normalizeEnum((string) ($data['priority'] ?? 'high'), self::HANDOFF_PRIORITIES, 'handoff_priority');
        }
        if ($forCreate || array_key_exists('assigned_to', $data)) {
            $assignedTo = (int) ($data['assigned_to'] ?? 0);
            if ($assignedTo > 0) {
                $this->assertWorkspaceUser($assignedTo, $workspaceId);
                $normalized['assigned_to'] = $assignedTo;
                if (($normalized['status'] ?? 'new') === 'new') {
                    $normalized['status'] = 'assigned';
                }
            } else {
                $normalized['assigned_to'] = null;
            }
        }
        if ($forCreate || array_key_exists('source', $data)) {
            $source = Security::sanitizeInput((string) ($data['source'] ?? 'manual'), 'string');
            $normalized['source'] = $source !== '' ? mb_substr($source, 0, 120) : null;
        }
        if ($forCreate || array_key_exists('handoff_note', $data)) {
            $normalized['handoff_note'] = $this->nullableSanitizedText($data['handoff_note'] ?? '');
        }
        if ($forCreate || array_key_exists('rejection_reason', $data)) {
            $normalized['rejection_reason'] = $this->nullableSanitizedText($data['rejection_reason'] ?? '');
        }
        if ($forCreate || array_key_exists('sla_due_at', $data)) {
            $normalized['sla_due_at'] = $this->normalizeOptionalDateTime($data['sla_due_at'] ?? null);
        }
        foreach (['assigned_at', 'first_contacted_at', 'qualified_at', 'rejected_at', 'converted_at'] as $field) {
            if ($forCreate || array_key_exists($field, $data)) {
                $normalized[$field] = $this->normalizeOptionalDateTime($data[$field] ?? null);
            }
        }
        if ($forCreate || array_key_exists('metadata_json', $data)) {
            $normalized['metadata_json'] = $this->normalizeJsonValue($data['metadata_json'] ?? null);
        }
        if ($forCreate) {
            $createdBy = (int) ($data['created_by'] ?? $this->currentUserId());
            if ($createdBy > 0) {
                $this->assertWorkspaceUser($createdBy, $workspaceId);
            }
            $normalized['created_by'] = $createdBy > 0 ? $createdBy : null;
        }

        return $normalized;
    }

    private function insertLeadHandoff(array $data): int
    {
        Database::execute(
            "INSERT INTO marketing_lead_handoffs
             (workspace_id, uuid, conversion_event_id, tracking_event_id, visitor_session_id, landing_page_id,
              campaign_id, content_item_id, form_id, conversion_goal_id, contact_id, deal_id, handoff_rule_id,
              task_id, status, priority, assigned_to, source, handoff_note, rejection_reason, sla_due_at,
              assigned_at, first_contacted_at, qualified_at, rejected_at, converted_at, metadata_json, created_by)
             VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)",
            [
                (int) $data['workspace_id'],
                $this->generateUuid(),
                $data['conversion_event_id'] ?? null,
                $data['tracking_event_id'] ?? null,
                $data['visitor_session_id'] ?? null,
                $data['landing_page_id'] ?? null,
                $data['campaign_id'] ?? null,
                $data['content_item_id'] ?? null,
                $data['form_id'] ?? null,
                $data['conversion_goal_id'] ?? null,
                $data['contact_id'] ?? null,
                $data['deal_id'] ?? null,
                $data['handoff_rule_id'] ?? null,
                $data['task_id'] ?? null,
                $data['status'] ?? 'new',
                $data['priority'] ?? 'high',
                $data['assigned_to'] ?? null,
                $data['source'] ?? null,
                $data['handoff_note'] ?? null,
                $data['rejection_reason'] ?? null,
                $data['sla_due_at'] ?? null,
                $data['assigned_at'] ?? null,
                $data['first_contacted_at'] ?? null,
                $data['qualified_at'] ?? null,
                $data['rejected_at'] ?? null,
                $data['converted_at'] ?? null,
                $data['metadata_json'] ?? null,
                $data['created_by'] ?? null,
            ]
        );

        return (int) Database::lastInsertId();
    }

    private function matchingHandoffRule(int $workspaceId, array $conversion): ?array
    {
        if (!Database::tableExists('marketing_handoff_rules')) {
            return null;
        }

        $landingPageId = (int) ($conversion['landing_page_id'] ?? 0);
        $formId = (int) ($conversion['form_id'] ?? 0);
        $campaignId = (int) ($conversion['campaign_id'] ?? 0);
        $conversionGoalId = (int) ($conversion['conversion_goal_id'] ?? 0);

        $rules = Database::query(
            "SELECT *
             FROM marketing_handoff_rules
             WHERE workspace_id = ?
               AND status = 'active'
               AND (landing_page_id IS NULL OR landing_page_id = ?)
               AND (form_id IS NULL OR form_id = ?)
               AND (campaign_id IS NULL OR campaign_id = ?)
               AND (conversion_goal_id IS NULL OR conversion_goal_id = ?)
               AND (
                    source_type = 'any'
                    OR (source_type = 'landing_page' AND landing_page_id = ?)
                    OR (source_type = 'form' AND form_id = ?)
                    OR (source_type = 'campaign' AND campaign_id = ?)
                    OR (source_type = 'conversion_goal' AND conversion_goal_id = ?)
               )
             ORDER BY
               ((landing_page_id IS NOT NULL) + (form_id IS NOT NULL) + (campaign_id IS NOT NULL) + (conversion_goal_id IS NOT NULL)) DESC,
               FIELD(priority, 'urgent','high','medium','low'),
               updated_at DESC
             LIMIT 1",
            [
                $workspaceId,
                $landingPageId > 0 ? $landingPageId : -1,
                $formId > 0 ? $formId : -1,
                $campaignId > 0 ? $campaignId : -1,
                $conversionGoalId > 0 ? $conversionGoalId : -1,
                $landingPageId,
                $formId,
                $campaignId,
                $conversionGoalId,
            ]
        );

        return $rules[0] ?? null;
    }

    private function getLeadHandoffForWorkspace(int $id, int $workspaceId): ?array
    {
        if (!Database::tableExists('marketing_lead_handoffs')) {
            return null;
        }

        $row = Database::queryOne(
            "SELECT h.*,
                    assignee.email AS assigned_to_email,
                    c.email AS contact_email,
                    CONCAT(COALESCE(c.first_name, ''), ' ', COALESCE(c.last_name, '')) AS contact_name,
                    d.title AS deal_title,
                    lp.title AS landing_page_title,
                    camp.name AS campaign_name,
                    item.title AS content_title,
                    form.name AS form_name,
                    goal.title AS conversion_goal_title,
                    task.title AS task_title,
                    rule.name AS handoff_rule_name,
                    rule.task_title_template AS handoff_task_title_template
             FROM marketing_lead_handoffs h
             LEFT JOIN users assignee ON assignee.id = h.assigned_to
             LEFT JOIN contacts c ON c.id = h.contact_id AND c.workspace_id = h.workspace_id
             LEFT JOIN deals d ON d.id = h.deal_id AND d.workspace_id = h.workspace_id
             LEFT JOIN marketing_landing_pages lp ON lp.id = h.landing_page_id AND lp.workspace_id = h.workspace_id
             LEFT JOIN campaigns camp ON camp.id = h.campaign_id AND camp.workspace_id = h.workspace_id
             LEFT JOIN marketing_content_items item ON item.id = h.content_item_id AND item.workspace_id = h.workspace_id
             LEFT JOIN forms form ON form.id = h.form_id AND form.workspace_id = h.workspace_id
             LEFT JOIN marketing_conversion_goals goal ON goal.id = h.conversion_goal_id AND goal.workspace_id = h.workspace_id
             LEFT JOIN tasks task ON task.id = h.task_id AND task.workspace_id = h.workspace_id
             LEFT JOIN marketing_handoff_rules rule ON rule.id = h.handoff_rule_id AND rule.workspace_id = h.workspace_id
             WHERE h.workspace_id = ? AND h.id = ?
             LIMIT 1",
            [$workspaceId, $id]
        );

        return $row ? $this->hydrateJsonFields($row, ['metadata_json']) : null;
    }

    /**
     * @return array{table:string,field:string}
     */
    private function normalizeCrmHandoffRecord(string $recordType, int $recordId): array
    {
        $recordType = $this->normalizeEnum(strtolower(trim($recordType)), ['contact', 'deal'], 'crm_record_type');
        if ($recordId <= 0) {
            throw new RuntimeException('CRM record id is required.');
        }

        $map = [
            'contact' => ['table' => 'contacts', 'field' => 'contact_id'],
            'deal' => ['table' => 'deals', 'field' => 'deal_id'],
        ];
        $record = $map[$recordType];
        $this->assertWorkspaceRecord($record['table'], $recordId, $this->workspaceId());

        return $record;
    }

    private function applyLeadHandoffStatusUpdate(int $id, string $status, array $data = []): bool
    {
        $handoff = $this->getLeadHandoff($id);
        if (!$handoff) {
            throw new RuntimeException('Marketing lead handoff not found.');
        }

        $workspaceId = $this->workspaceId();
        $status = $this->normalizeEnum($status, self::LEAD_HANDOFF_STATUSES, 'lead_handoff_status');
        $fields = ['status' => $status];
        $timestampField = match ($status) {
            'accepted' => 'accepted_at',
            'contacted' => 'first_contacted_at',
            'qualified' => 'qualified_at',
            'rejected' => 'rejected_at',
            'lost' => 'lost_at',
            'converted' => 'converted_at',
            default => null,
        };
        if ($timestampField !== null) {
            $fields[$timestampField] = date('Y-m-d H:i:s');
        }
        if (array_key_exists('assigned_to', $data)) {
            $assignedTo = (int) ($data['assigned_to'] ?? 0);
            if ($assignedTo > 0) {
                $this->assertWorkspaceUser($assignedTo, $workspaceId);
                $fields['assigned_to'] = $assignedTo;
                $fields['assigned_at'] = date('Y-m-d H:i:s');
                if ($status === 'new') {
                    $fields['status'] = 'assigned';
                    $status = 'assigned';
                }
            }
        }

        $feedbackOutcome = null;
        if (!empty($data['feedback_outcome']) || in_array($status, self::HANDOFF_FEEDBACK_OUTCOMES, true)) {
            $feedbackOutcome = $this->normalizeEnum((string) ($data['feedback_outcome'] ?? $status), self::HANDOFF_FEEDBACK_OUTCOMES, 'handoff_feedback_outcome');
            $reason = $this->nullableSanitizedText($data['feedback_reason'] ?? $data['rejection_reason'] ?? $data['loss_reason'] ?? '');
            $note = $this->nullableSanitizedText($data['feedback_note'] ?? '');
            $feedbackBy = (int) ($data['feedback_by'] ?? $data['created_by'] ?? $this->currentUserId());
            if ($feedbackBy > 0) {
                $this->assertWorkspaceUser($feedbackBy, $workspaceId);
                $fields['feedback_by'] = $feedbackBy;
            }
            $fields['sales_outcome'] = $feedbackOutcome;
            $fields['feedback_reason'] = $reason !== null ? mb_substr($reason, 0, 255) : null;
            $fields['feedback_note'] = $note;
            $fields['feedback_at'] = date('Y-m-d H:i:s');
            if ($feedbackOutcome === 'rejected') {
                $fields['rejection_reason'] = $fields['feedback_reason'];
            }
        } elseif (array_key_exists('rejection_reason', $data)) {
            $fields['rejection_reason'] = $this->nullableSanitizedText($data['rejection_reason'] ?? '');
        }

        $updated = $this->updateById('marketing_lead_handoffs', $id, $fields);
        if ($updated && $feedbackOutcome !== null) {
            $this->insertLeadHandoffFeedbackEvent($handoff, $status, $feedbackOutcome, $fields, $data);
        }

        $updatedHandoff = $this->getLeadHandoff($id);
        if ($updatedHandoff && !empty($updatedHandoff['assigned_to']) && empty($updatedHandoff['task_id'])) {
            $taskId = $this->createLeadHandoffTask($updatedHandoff, (int) ($data['created_by'] ?? $this->currentUserId()) ?: null);
            if ($taskId > 0) {
                Database::execute(
                    "UPDATE marketing_lead_handoffs SET task_id = ? WHERE workspace_id = ? AND id = ?",
                    [$taskId, $workspaceId, $id]
                );
            }
        }
        $this->syncLeadHandoffToCrmForWorkspace($id, $workspaceId, (int) ($data['created_by'] ?? $this->currentUserId()) ?: null);

        return $updated;
    }

    private function insertLeadHandoffFeedbackEvent(array $handoff, string $newStatus, string $outcome, array $fields, array $data): void
    {
        if (!Database::tableExists('marketing_handoff_feedback_events')) {
            return;
        }

        Database::execute(
            "INSERT INTO marketing_handoff_feedback_events
             (workspace_id, uuid, lead_handoff_id, previous_status, new_status, outcome, reason, note, metadata_json, created_by)
             VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)",
            [
                $this->workspaceId(),
                $this->generateUuid(),
                (int) ($handoff['id'] ?? 0),
                (string) ($handoff['status'] ?? 'new'),
                $newStatus,
                $outcome,
                $fields['feedback_reason'] ?? null,
                $fields['feedback_note'] ?? null,
                $this->normalizeJsonValue([
                    'source' => 'sales_feedback_loop',
                    'assigned_to' => (int) ($handoff['assigned_to'] ?? 0),
                    'manual_first_boundary' => true,
                ] + (array) ($data['metadata'] ?? [])),
                (int) ($fields['feedback_by'] ?? $data['created_by'] ?? $this->currentUserId()) ?: null,
            ]
        );
    }

    private function fallbackHandoffCreator(int $workspaceId, int $preferredUserId = 0): ?int
    {
        if ($preferredUserId > 0) {
            try {
                $this->assertWorkspaceUser($preferredUserId, $workspaceId);
                return $preferredUserId;
            } catch (Throwable $e) {
                // Fall through to a workspace owner/active member below.
            }
        }

        if (Database::tableExists('workspace_memberships')) {
            $row = Database::queryOne(
                "SELECT user_id
                 FROM workspace_memberships
                 WHERE workspace_id = ?
                   AND membership_status = 'active'
                 ORDER BY is_owner DESC, FIELD(role_slug, 'owner','admin','marketing','sales','viewer'), id ASC
                 LIMIT 1",
                [$workspaceId]
            );
            if (!empty($row['user_id'])) {
                return (int) $row['user_id'];
            }
        }

        return null;
    }

    private function createLeadHandoffTask(array $handoff, ?int $createdBy = null): int
    {
        if (!Database::tableExists('tasks') || empty($handoff['assigned_to'])) {
            return 0;
        }

        $workspaceId = (int) ($handoff['workspace_id'] ?? $this->workspaceId());
        $assignedTo = (int) ($handoff['assigned_to'] ?? 0);
        $creatorId = $this->fallbackHandoffCreator($workspaceId, (int) ($createdBy ?? 0)) ?? $assignedTo;
        if ($creatorId <= 0 || $assignedTo <= 0) {
            return 0;
        }

        $titleTemplate = trim((string) ($handoff['handoff_task_title_template'] ?? ''));
        $leadLabel = trim((string) ($handoff['contact_email'] ?? $handoff['contact_name'] ?? $handoff['landing_page_title'] ?? 'marketing lead'));
        $title = $titleTemplate !== ''
            ? strtr($titleTemplate, [
                '{lead}' => $leadLabel,
                '{campaign}' => (string) ($handoff['campaign_name'] ?? 'campaign'),
                '{goal}' => (string) ($handoff['conversion_goal_title'] ?? 'conversion'),
            ])
            : 'Follow up marketing lead: ' . $leadLabel;
        $title = mb_substr(Security::sanitizeInput($title, 'string'), 0, 255);
        if ($title === '') {
            $title = 'Follow up marketing lead';
        }

        $descriptionParts = [
            'Marketing captured a lead handoff that needs sales follow-up.',
            'Source: ' . ((string) ($handoff['source'] ?? '') ?: 'marketing_conversion'),
            !empty($handoff['campaign_name']) ? 'Campaign: ' . (string) $handoff['campaign_name'] : null,
            !empty($handoff['landing_page_title']) ? 'Landing page: ' . (string) $handoff['landing_page_title'] : null,
            !empty($handoff['conversion_goal_title']) ? 'Goal: ' . (string) $handoff['conversion_goal_title'] : null,
            !empty($handoff['handoff_note']) ? 'Note: ' . (string) $handoff['handoff_note'] : null,
        ];
        $description = implode("\n", array_values(array_filter($descriptionParts, static fn($value): bool => $value !== null && $value !== '')));

        Database::execute(
            "INSERT INTO tasks (workspace_id, title, description, contact_id, assigned_to, created_by, status, priority, due_date)
             VALUES (?, ?, ?, ?, ?, ?, 'pending', ?, ?)",
            [
                $workspaceId,
                $title,
                $description,
                !empty($handoff['contact_id']) ? (int) $handoff['contact_id'] : null,
                $assignedTo,
                $creatorId,
                $this->normalizeEnum((string) ($handoff['priority'] ?? 'high'), self::HANDOFF_PRIORITIES, 'handoff_priority'),
                $handoff['sla_due_at'] ?? null,
            ]
        );

        $taskId = (int) Database::lastInsertId();
        if ($taskId > 0 && Database::columnExists('tasks', 'metadata_json')) {
            Database::execute(
                "UPDATE tasks
                 SET metadata_json = ?
                 WHERE workspace_id = ? AND id = ?",
                [
                    $this->normalizeJsonValue([
                        'source' => 'marketing_sales_handoff',
                        'marketing_lead_handoff_id' => (int) ($handoff['id'] ?? 0),
                        'manual_first_boundary' => true,
                    ]),
                    $workspaceId,
                    $taskId,
                ]
            );
        }

        return $taskId;
    }

    private function applySalesAssignmentToLinkedRecords(int $workspaceId, int $contactId, int $dealId, int $assignedTo): void
    {
        if ($assignedTo <= 0) {
            return;
        }
        if ($contactId > 0 && Database::tableExists('contacts')) {
            Database::execute(
                "UPDATE contacts
                 SET assigned_to = COALESCE(assigned_to, ?)
                 WHERE workspace_id = ? AND id = ?",
                [$assignedTo, $workspaceId, $contactId]
            );
        }
        if ($dealId > 0 && Database::tableExists('deals')) {
            Database::execute(
                "UPDATE deals
                 SET assigned_to = COALESCE(assigned_to, ?)
                 WHERE workspace_id = ? AND id = ?",
                [$assignedTo, $workspaceId, $dealId]
            );
        }
    }

    private function syncLeadHandoffToCrmForWorkspace(int $handoffId, int $workspaceId, ?int $actorUserId = null): array
    {
        if (!Database::tableExists('marketing_lead_handoffs')) {
            return ['status' => 'skipped', 'activity_id' => null, 'notification_id' => null, 'events' => []];
        }

        $handoff = $this->getLeadHandoffForWorkspace($handoffId, $workspaceId);
        if (!$handoff) {
            return ['status' => 'skipped', 'activity_id' => null, 'notification_id' => null, 'events' => []];
        }

        $events = [];
        $activityId = (int) ($handoff['crm_activity_id'] ?? 0) ?: null;
        $notificationId = (int) ($handoff['notification_id'] ?? 0) ?: null;
        $actorUserId = $this->fallbackHandoffCreator($workspaceId, (int) ($actorUserId ?? $handoff['created_by'] ?? $handoff['assigned_to'] ?? 0));

        if ($activityId === null && !empty($handoff['contact_id']) && Database::tableExists('activities')) {
            try {
                $activityId = $this->createLeadHandoffActivity($handoff, $workspaceId, $actorUserId);
                if ($activityId > 0) {
                    $events[] = $this->recordLeadHandoffCrmSyncEvent($workspaceId, $handoffId, 'activity', 'synced', 'Created contact timeline activity.', $activityId, null, $actorUserId);
                }
            } catch (Throwable $e) {
                $events[] = $this->recordLeadHandoffCrmSyncEvent($workspaceId, $handoffId, 'activity', 'failed', $e->getMessage(), null, null, $actorUserId);
            }
        } elseif ($activityId === null) {
            $events[] = $this->recordLeadHandoffCrmSyncEvent($workspaceId, $handoffId, 'activity', 'skipped', 'No linked contact is available for activity timeline sync.', null, null, $actorUserId);
        }

        if ($notificationId === null && !empty($handoff['assigned_to']) && Database::tableExists('notifications')) {
            try {
                $notificationId = $this->createLeadHandoffNotification($handoff, $workspaceId);
                if ($notificationId > 0) {
                    $events[] = $this->recordLeadHandoffCrmSyncEvent($workspaceId, $handoffId, 'notification', 'synced', 'Created assigned owner notification.', null, $notificationId, $actorUserId);
                }
            } catch (Throwable $e) {
                $events[] = $this->recordLeadHandoffCrmSyncEvent($workspaceId, $handoffId, 'notification', 'failed', $e->getMessage(), null, null, $actorUserId);
            }
        } elseif ($notificationId === null) {
            $events[] = $this->recordLeadHandoffCrmSyncEvent($workspaceId, $handoffId, 'notification', 'skipped', 'No assigned owner is available for notification sync.', null, null, $actorUserId);
        }

        $failed = count(array_filter($events, static fn(array $event): bool => ($event['status'] ?? '') === 'failed')) > 0;
        $synced = count(array_filter($events, static fn(array $event): bool => ($event['status'] ?? '') === 'synced')) > 0;
        $skipped = count(array_filter($events, static fn(array $event): bool => ($event['status'] ?? '') === 'skipped')) > 0;
        $hasCrmReferences = $activityId !== null || $notificationId !== null;
        $status = $failed
            ? 'failed'
            : ($synced ? ($skipped ? 'partial' : 'synced') : ($hasCrmReferences ? ($skipped ? 'partial' : 'synced') : 'skipped'));

        $updates = [
            'crm_sync_status = ?',
            'crm_synced_at = NOW()',
        ];
        $params = [$status];
        if ($activityId !== null) {
            $updates[] = 'crm_activity_id = ?';
            $params[] = $activityId;
        }
        if ($notificationId !== null) {
            $updates[] = 'notification_id = ?';
            $params[] = $notificationId;
        }
        $params[] = $workspaceId;
        $params[] = $handoffId;
        Database::execute(
            "UPDATE marketing_lead_handoffs SET " . implode(', ', $updates) . " WHERE workspace_id = ? AND id = ?",
            $params
        );

        return [
            'status' => $status,
            'activity_id' => $activityId,
            'notification_id' => $notificationId,
            'events' => $events,
        ];
    }

    private function createLeadHandoffActivity(array $handoff, int $workspaceId, ?int $actorUserId): int
    {
        $contactId = (int) ($handoff['contact_id'] ?? 0);
        if ($contactId <= 0) {
            return 0;
        }
        $leadLabel = trim((string) ($handoff['contact_email'] ?? $handoff['contact_name'] ?? 'marketing lead'));
        $description = 'Marketing handoff created for ' . ($leadLabel !== '' ? $leadLabel : 'marketing lead') . '.';
        if (!empty($handoff['campaign_name'])) {
            $description .= ' Campaign: ' . (string) $handoff['campaign_name'] . '.';
        }
        if (!empty($handoff['conversion_goal_title'])) {
            $description .= ' Goal: ' . (string) $handoff['conversion_goal_title'] . '.';
        }

        Database::execute(
            "INSERT INTO activities (workspace_id, contact_id, user_id, activity_type, description, metadata)
             VALUES (?, ?, ?, 'marketing_handoff', ?, ?)",
            [
                $workspaceId,
                $contactId,
                $actorUserId,
                Security::sanitizeInput($description, 'string'),
                $this->normalizeJsonValue([
                    'source' => 'marketing_crm_handoff_sync',
                    'marketing_lead_handoff_id' => (int) ($handoff['id'] ?? 0),
                    'task_id' => (int) ($handoff['task_id'] ?? 0) ?: null,
                    'manual_first_boundary' => true,
                ]),
            ]
        );

        return (int) Database::lastInsertId();
    }

    private function createLeadHandoffNotification(array $handoff, int $workspaceId): int
    {
        $assignedTo = (int) ($handoff['assigned_to'] ?? 0);
        if ($assignedTo <= 0) {
            return 0;
        }

        $leadLabel = trim((string) ($handoff['contact_email'] ?? $handoff['contact_name'] ?? 'marketing lead'));
        $title = 'New marketing lead handoff';
        $message = 'Marketing captured a lead that needs follow-up: ' . ($leadLabel !== '' ? $leadLabel : 'marketing lead') . '.';
        if (!empty($handoff['sla_due_at'])) {
            $message .= ' SLA due: ' . (string) $handoff['sla_due_at'] . '.';
        }

        Database::execute(
            "INSERT INTO notifications (workspace_id, user_id, type, title, message, entity_type, entity_id, link, is_read)
             VALUES (?, ?, 'marketing_handoff', ?, ?, 'marketing_lead_handoff', ?, ?, 0)",
            [
                $workspaceId,
                $assignedTo,
                $title,
                Security::sanitizeInput($message, 'string'),
                (int) ($handoff['id'] ?? 0),
                'marketing_handoffs.php?status=assigned',
            ]
        );

        return (int) Database::lastInsertId();
    }

    private function recordLeadHandoffCrmSyncEvent(
        int $workspaceId,
        int $handoffId,
        string $syncType,
        string $status,
        string $message,
        ?int $activityId,
        ?int $notificationId,
        ?int $createdBy
    ): array {
        $event = [
            'id' => 0,
            'sync_type' => $syncType,
            'status' => $status,
            'message' => mb_substr(Security::sanitizeInput($message, 'string'), 0, 255),
            'activity_id' => $activityId,
            'notification_id' => $notificationId,
        ];
        if (!Database::tableExists('marketing_crm_sync_events')) {
            return $event;
        }

        Database::execute(
            "INSERT INTO marketing_crm_sync_events
             (workspace_id, uuid, lead_handoff_id, activity_id, notification_id, sync_type, status, message, metadata_json, created_by)
             VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)",
            [
                $workspaceId,
                $this->generateUuid(),
                $handoffId,
                $activityId,
                $notificationId,
                $syncType,
                $status,
                $event['message'],
                $this->normalizeJsonValue([
                    'source' => 'marketing_crm_handoff_sync',
                    'manual_first_boundary' => true,
                ]),
                $createdBy,
            ]
        );
        $event['id'] = (int) Database::lastInsertId();

        return $event;
    }

    private function normalizeOptionalDateTime(mixed $value): ?string
    {
        $value = trim((string) ($value ?? ''));
        if ($value === '') {
            return null;
        }
        $timestamp = strtotime($value);
        if ($timestamp === false) {
            throw new \InvalidArgumentException('Invalid handoff date value.');
        }

        return date('Y-m-d H:i:s', $timestamp);
    }

    public function audienceSegmentRuleOptions(): array
    {
        $fields = [];
        foreach ($this->audienceSegmentRuleFields() as $sourceType => $definitions) {
            $fields[$sourceType] = array_map(
                static fn(array $definition): array => [
                    'key' => (string) $definition['key'],
                    'label' => (string) $definition['label'],
                    'operators' => (array) $definition['operators'],
                ],
                array_values($definitions)
            );
        }

        return [
            'source_types' => self::AUDIENCE_SEGMENT_SOURCE_TYPES,
            'operators' => self::AUDIENCE_SEGMENT_OPERATORS,
            'fields' => $fields,
        ];
    }

    private function normalizeAudienceSegmentData(array $data, bool $forCreate): array
    {
        $normalized = [];

        if ($forCreate || array_key_exists('name', $data)) {
            $name = Security::sanitizeInput((string) ($data['name'] ?? ''), 'string');
            if ($name === '') {
                throw new \InvalidArgumentException('Audience segment name is required.');
            }
            $normalized['name'] = substr($name, 0, 180);
        }

        if ($forCreate || array_key_exists('description', $data)) {
            $normalized['description'] = $this->nullableSanitizedText($data['description'] ?? '');
        }
        if ($forCreate || array_key_exists('status', $data)) {
            $normalized['status'] = $this->normalizeEnum((string) ($data['status'] ?? 'draft'), self::AUDIENCE_SEGMENT_STATUSES, 'segment_status');
        }
        if ($forCreate || array_key_exists('source_scope', $data)) {
            $normalized['source_scope'] = $this->normalizeEnum((string) ($data['source_scope'] ?? 'contacts'), self::AUDIENCE_SEGMENT_SOURCE_SCOPES, 'segment_source_scope');
        }
        if ($forCreate || array_key_exists('rule_logic', $data)) {
            $normalized['rule_logic'] = $this->normalizeEnum((string) ($data['rule_logic'] ?? 'all'), self::AUDIENCE_SEGMENT_RULE_LOGIC, 'segment_rule_logic');
        }
        if ($forCreate || array_key_exists('metadata_json', $data)) {
            $normalized['metadata_json'] = $this->normalizeJsonValue($data['metadata_json'] ?? null);
        }
        if ($forCreate) {
            $normalized['created_by'] = (int) ($data['created_by'] ?? $this->currentUserId()) ?: null;
        }

        return $normalized;
    }

    private function normalizeAudienceActivationData(array $data, bool $forCreate): array
    {
        $workspaceId = $this->workspaceId();
        $normalized = [];

        $linkTables = [
            'campaign_id' => 'campaigns',
            'campaign_brief_id' => 'marketing_campaign_briefs',
            'landing_page_id' => 'marketing_landing_pages',
            'content_item_id' => 'marketing_content_items',
            'distribution_post_id' => 'marketing_distribution_posts',
            'email_run_id' => 'marketing_email_campaign_runs',
        ];
        foreach ($linkTables as $field => $table) {
            if ($forCreate || array_key_exists($field, $data)) {
                $id = (int) ($data[$field] ?? 0);
                if ($id > 0) {
                    $this->assertWorkspaceRecord($table, $id, $workspaceId);
                    $normalized[$field] = $id;
                } else {
                    $normalized[$field] = null;
                }
            }
        }

        if (!empty($normalized['distribution_post_id'])) {
            $post = $this->getDistributionPost((int) $normalized['distribution_post_id']);
            if ($post && empty($normalized['content_item_id'])) {
                $normalized['content_item_id'] = (int) ($post['content_item_id'] ?? 0) ?: null;
            }
        }
        if (!empty($normalized['email_run_id'])) {
            $run = $this->getEmailCampaignRun((int) $normalized['email_run_id']);
            if ($run) {
                if (empty($normalized['content_item_id'])) {
                    $normalized['content_item_id'] = (int) ($run['content_item_id'] ?? 0) ?: null;
                }
                if (empty($normalized['campaign_id'])) {
                    $normalized['campaign_id'] = (int) ($run['campaign_id'] ?? 0) ?: null;
                }
                if (empty($data['audience_segment_id']) && !empty($run['audience_segment_id'])) {
                    $data['audience_segment_id'] = (int) $run['audience_segment_id'];
                }
            }
        }
        if (!empty($normalized['content_item_id'])) {
            $content = $this->getContentItem((int) $normalized['content_item_id']);
            if ($content) {
                foreach ([
                    'campaign_id' => 'campaign_id',
                    'campaign_brief_id' => 'campaign_brief_id',
                    'landing_page_id' => 'landing_page_id',
                ] as $target => $source) {
                    if (empty($normalized[$target]) && !empty($content[$source])) {
                        $normalized[$target] = (int) $content[$source];
                    }
                }
            }
        }
        if (!empty($normalized['campaign_brief_id'])) {
            $brief = $this->getCampaignBrief((int) $normalized['campaign_brief_id']);
            if ($brief) {
                if (empty($normalized['campaign_id'])) {
                    $normalized['campaign_id'] = (int) ($brief['campaign_id'] ?? 0) ?: null;
                }
                if (empty($normalized['landing_page_id'])) {
                    $normalized['landing_page_id'] = (int) ($brief['landing_page_id'] ?? 0) ?: null;
                }
                if (empty($data['audience_segment_id']) && !empty($brief['audience_segment_id'])) {
                    $data['audience_segment_id'] = (int) $brief['audience_segment_id'];
                }
            }
        }
        if (!empty($normalized['landing_page_id'])) {
            $landing = $this->getLandingPage((int) $normalized['landing_page_id']);
            if ($landing) {
                if (empty($normalized['campaign_id'])) {
                    $normalized['campaign_id'] = (int) ($landing['campaign_id'] ?? 0) ?: null;
                }
                if (empty($data['audience_segment_id']) && !empty($landing['audience_segment_id'])) {
                    $data['audience_segment_id'] = (int) $landing['audience_segment_id'];
                }
            }
        }

        if ($forCreate || array_key_exists('audience_segment_id', $data)) {
            $segmentId = (int) ($data['audience_segment_id'] ?? 0);
            if ($segmentId <= 0) {
                throw new \InvalidArgumentException('Audience segment is required for activation.');
            }
            $this->assertWorkspaceRecord('marketing_audience_segments', $segmentId, $workspaceId);
            $normalized['audience_segment_id'] = $segmentId;
        }
        if ($forCreate || array_key_exists('activation_type', $data)) {
            $type = (string) ($data['activation_type'] ?? '');
            if ($type === '') {
                $type = $this->inferAudienceActivationType($normalized);
            }
            $normalized['activation_type'] = $this->normalizeEnum($type, self::AUDIENCE_ACTIVATION_TYPES, 'audience_activation_type');
        }
        if ($forCreate || array_key_exists('status', $data)) {
            $normalized['status'] = $this->normalizeEnum((string) ($data['status'] ?? 'planned'), self::AUDIENCE_ACTIVATION_STATUSES, 'audience_activation_status');
        }
        if ($forCreate || array_key_exists('activation_name', $data) || array_key_exists('name', $data)) {
            $name = Security::sanitizeInput((string) ($data['activation_name'] ?? $data['name'] ?? ''), 'string');
            if ($name === '') {
                $name = $this->deriveAudienceActivationName($normalized);
            }
            if ($name === '') {
                throw new \InvalidArgumentException('Audience activation name is required.');
            }
            $normalized['activation_name'] = mb_substr($name, 0, 180);
        }
        if ($forCreate || array_key_exists('owner_user_id', $data)) {
            $ownerId = (int) ($data['owner_user_id'] ?? 0);
            if ($ownerId > 0) {
                $this->assertWorkspaceUser($ownerId, $workspaceId);
                $normalized['owner_user_id'] = $ownerId;
            } else {
                $normalized['owner_user_id'] = null;
            }
        }
        if ($forCreate || array_key_exists('metadata_json', $data) || array_key_exists('metadata', $data)) {
            $metadata = $this->sanitizeFlexibleArray($data['metadata'] ?? $data['metadata_json'] ?? []);
            $metadata['manual_first_boundary'] = true;
            $metadata['external_execution'] = false;
            $normalized['metadata_json'] = $this->normalizeJsonValue($metadata);
        }
        if ($forCreate) {
            $createdBy = (int) ($data['created_by'] ?? $this->currentUserId()) ?: null;
            if (($createdBy ?? 0) > 0) {
                $this->assertWorkspaceUser((int) $createdBy, $workspaceId);
            }
            $normalized['created_by'] = $createdBy;
        }

        return $normalized;
    }

    private function inferAudienceActivationType(array $normalized): string
    {
        foreach ([
            'email_run_id' => 'email_run',
            'distribution_post_id' => 'distribution',
            'content_item_id' => 'content',
            'landing_page_id' => 'landing_page',
            'campaign_brief_id' => 'brief',
            'campaign_id' => 'campaign',
        ] as $field => $type) {
            if (!empty($normalized[$field])) {
                return $type;
            }
        }

        return 'other';
    }

    private function deriveAudienceActivationName(array $normalized): string
    {
        foreach ([
            'campaign_brief_id' => ['getter' => 'getCampaignBrief', 'field' => 'title'],
            'landing_page_id' => ['getter' => 'getLandingPage', 'field' => 'title'],
            'content_item_id' => ['getter' => 'getContentItem', 'field' => 'title'],
            'email_run_id' => ['getter' => 'getEmailCampaignRun', 'field' => 'name'],
        ] as $field => $config) {
            if (!empty($normalized[$field])) {
                $record = $this->{$config['getter']}((int) $normalized[$field]);
                if ($record && !empty($record[$config['field']])) {
                    return (string) $record[$config['field']] . ' audience activation';
                }
            }
        }
        if (!empty($normalized['campaign_id'])) {
            $campaign = Database::queryOne('SELECT name FROM campaigns WHERE workspace_id = ? AND id = ? LIMIT 1', [$this->workspaceId(), (int) $normalized['campaign_id']]);
            if (!empty($campaign['name'])) {
                return (string) $campaign['name'] . ' audience activation';
            }
        }
        if (!empty($normalized['audience_segment_id'])) {
            $segment = Database::queryOne('SELECT name FROM marketing_audience_segments WHERE workspace_id = ? AND id = ? LIMIT 1', [$this->workspaceId(), (int) $normalized['audience_segment_id']]);
            if (!empty($segment['name'])) {
                return (string) $segment['name'] . ' activation';
            }
        }

        return '';
    }

    private function calculateAudienceActivationCoverage(array $activation): array
    {
        $workspaceId = $this->workspaceId();
        $segmentId = (int) ($activation['audience_segment_id'] ?? 0);
        $segment = $segmentId > 0
            ? Database::queryOne('SELECT * FROM marketing_audience_segments WHERE workspace_id = ? AND id = ? LIMIT 1', [$workspaceId, $segmentId])
            : null;
        if (!$segment) {
            throw new RuntimeException('Audience segment was not found in the active workspace.');
        }

        $warnings = [];
        $score = 0;
        $usage = [
            'segment_name' => (string) ($segment['name'] ?? ''),
            'segment_status' => (string) ($segment['status'] ?? ''),
            'preview_count' => (int) ($segment['preview_count'] ?? 0),
            'last_snapshot_at' => $segment['last_snapshot_at'] ?? null,
            'linked_records' => [],
        ];

        if ((string) ($segment['status'] ?? '') === 'active') {
            $score += 20;
        } else {
            $warnings[] = 'segment_not_active';
        }
        if ((int) ($segment['fit_score'] ?? 0) > 0) {
            $score += min(20, (int) round(((int) $segment['fit_score']) / 5));
        }
        if ((int) ($segment['preview_count'] ?? 0) > 0) {
            $score += 12;
        } else {
            $warnings[] = 'segment_has_no_preview_contacts';
        }
        if (!empty($segment['last_snapshot_at'])) {
            $score += 8;
        } else {
            $warnings[] = 'segment_snapshot_missing';
        }
        $personaMapCount = Database::tableExists('marketing_persona_segment_map')
            ? (int) (Database::queryOne(
                'SELECT COUNT(*) AS count FROM marketing_persona_segment_map WHERE workspace_id = ? AND audience_segment_id = ?',
                [$workspaceId, $segmentId]
            )['count'] ?? 0)
            : 0;
        if ($personaMapCount > 0) {
            $score += 10;
        } else {
            $warnings[] = 'persona_mapping_missing';
        }

        $linkWeights = [
            'campaign_id' => ['label' => 'campaign', 'weight' => 8],
            'campaign_brief_id' => ['label' => 'brief', 'weight' => 12],
            'landing_page_id' => ['label' => 'landing_page', 'weight' => 12],
            'content_item_id' => ['label' => 'content', 'weight' => 10],
            'distribution_post_id' => ['label' => 'distribution', 'weight' => 8],
            'email_run_id' => ['label' => 'email_run', 'weight' => 8],
        ];
        foreach ($linkWeights as $field => $meta) {
            $id = (int) ($activation[$field] ?? 0);
            if ($id > 0) {
                $usage['linked_records'][$field] = $id;
                $score += (int) $meta['weight'];
            }
        }
        if (empty($usage['linked_records'])) {
            $warnings[] = 'activation_has_no_execution_link';
        }
        if (empty($activation['campaign_id']) && empty($activation['campaign_brief_id'])) {
            $warnings[] = 'campaign_context_missing';
        }
        if (empty($activation['landing_page_id'])) {
            $warnings[] = 'landing_page_missing';
        } else {
            $landing = $this->getLandingPage((int) $activation['landing_page_id']);
            if ($landing && empty($landing['form_id']) && empty($landing['conversion_goal_id'])) {
                $warnings[] = 'landing_conversion_path_missing';
            }
        }
        if (empty($activation['content_item_id']) && empty($activation['distribution_post_id']) && empty($activation['email_run_id'])) {
            $warnings[] = 'content_or_channel_plan_missing';
        }
        if (!empty($activation['content_item_id'])) {
            $content = $this->getContentItem((int) $activation['content_item_id']);
            if ($content && !in_array((string) ($content['status'] ?? ''), ['approved', 'scheduled', 'published'], true)) {
                $warnings[] = 'content_not_approved';
            }
        }
        if (!empty($activation['email_run_id'])) {
            $run = $this->getEmailCampaignRun((int) $activation['email_run_id']);
            foreach ((array) ($run['readiness_warnings_json'] ?? []) as $warning) {
                $warnings[] = 'email_' . (string) $warning;
            }
        }

        $criticalWarnings = array_intersect($warnings, ['activation_has_no_execution_link']);
        $coverageStatus = $criticalWarnings !== []
            ? 'blocked'
            : ($warnings === [] ? 'ready' : 'warning');

        return [
            'fit_score' => min(100, $score),
            'coverage_status' => $coverageStatus,
            'warnings' => array_values(array_unique($warnings)),
            'usage_summary' => $usage + [
                'persona_map_count' => $personaMapCount,
                'manual_first' => true,
                'external_execution' => false,
                'evaluated_at' => date('c'),
            ],
        ];
    }

    private function hydrateAudienceActivationRow(array $row): array
    {
        $row = $this->hydrateJsonFields($row, ['coverage_warnings_json', 'usage_summary_json', 'metadata_json']);
        $row['fit_score'] = (int) ($row['fit_score'] ?? 0);
        $row['audience_preview_count'] = (int) ($row['audience_preview_count'] ?? 0);

        return $row;
    }

    private function audienceQualityNextAction(array $warnings): string
    {
        $warnings = array_map('strval', $warnings);
        if (in_array('consent_policy_missing', $warnings, true) || in_array('suppression_list_requires_review', $warnings, true)) {
            return 'Review consent policy and suppression plan before export.';
        }
        if (in_array('activation_missing', $warnings, true) || in_array('no_active_activation', $warnings, true)) {
            return 'Create or connect an audience activation to a campaign, email run, or launch checklist.';
        }
        if (in_array('snapshot_missing', $warnings, true) || in_array('snapshot_stale', $warnings, true) || in_array('snapshot_drift_detected', $warnings, true)) {
            return 'Create a fresh audience snapshot and compare the audience size before launch.';
        }
        if (in_array('persona_fit_missing', $warnings, true) || in_array('offer_fit_missing', $warnings, true)) {
            return 'Connect persona and offer context so the audience has a clear message fit.';
        }
        if (in_array('no_matching_contacts', $warnings, true)) {
            return 'Adjust segment rules until CRM contacts match the audience.';
        }

        return 'Review audience readiness before manual execution.';
    }

    private function touchAudienceActivationScore(int $segmentId): void
    {
        if ($segmentId <= 0 || !Database::tableExists('marketing_audience_activations') || !Database::columnExists('marketing_audience_segments', 'activation_score')) {
            return;
        }

        $row = Database::queryOne(
            "SELECT COALESCE(MAX(fit_score), 0) AS score,
                    MAX(updated_at) AS latest
             FROM marketing_audience_activations
             WHERE workspace_id = ? AND audience_segment_id = ? AND status <> 'archived'",
            [$this->workspaceId(), $segmentId]
        );
        $score = (int) ($row['score'] ?? 0);
        $latest = $row['latest'] ?? null;
        $warnings = [];
        if ($score <= 0) {
            $warnings[] = 'no_active_activation';
        }
        Database::execute(
            'UPDATE marketing_audience_segments
             SET activation_score = ?, activation_warnings_json = ?, last_activation_at = ?
             WHERE workspace_id = ? AND id = ?',
            [
                $score,
                $this->normalizeJsonValue($warnings),
                $latest,
                $this->workspaceId(),
                $segmentId,
            ]
        );
    }

    private function normalizeAudienceSegmentRules(mixed $rules): array
    {
        if (is_string($rules)) {
            $decoded = json_decode($rules, true);
            $rules = json_last_error() === JSON_ERROR_NONE ? $decoded : [];
        }
        if (!is_array($rules)) {
            return [];
        }

        $fieldDefinitions = $this->audienceSegmentRuleFields();
        $normalized = [];
        foreach (array_values($rules) as $index => $rule) {
            if (!is_array($rule)) {
                continue;
            }
            $sourceType = $this->normalizeEnum((string) ($rule['source_type'] ?? 'contact'), self::AUDIENCE_SEGMENT_SOURCE_TYPES, 'segment_rule_source');
            $fieldKey = Security::sanitizeInput((string) ($rule['field_key'] ?? ''), 'string');
            if ($fieldKey === '' || !isset($fieldDefinitions[$sourceType][$fieldKey])) {
                continue;
            }
            $definition = $fieldDefinitions[$sourceType][$fieldKey];
            $operator = $this->normalizeEnum((string) ($rule['operator'] ?? 'equals'), (array) $definition['operators'], 'segment_rule_operator');
            $valueText = Security::sanitizeInput((string) ($rule['value_text'] ?? $rule['value'] ?? ''), 'string');
            $valueJson = $rule['value_json'] ?? null;
            if (is_string($valueJson)) {
                $decoded = json_decode($valueJson, true);
                $valueJson = json_last_error() === JSON_ERROR_NONE ? $decoded : null;
            }

            $normalized[] = [
                'source_type' => $sourceType,
                'field_key' => $fieldKey,
                'operator' => $operator,
                'value_text' => $valueText !== '' ? substr($valueText, 0, 500) : null,
                'value_json' => $this->normalizeJsonValue($valueJson),
                'sort_order' => (int) ($rule['sort_order'] ?? $index),
            ];
        }

        return $normalized;
    }

    private function replaceAudienceSegmentRules(int $segmentId, array $rules): void
    {
        $this->assertWorkspaceRecord('marketing_audience_segments', $segmentId, $this->workspaceId());
        Database::execute(
            'DELETE FROM marketing_segment_rules WHERE workspace_id = ? AND segment_id = ?',
            [$this->workspaceId(), $segmentId]
        );

        foreach (array_values($rules) as $index => $rule) {
            Database::execute(
                "INSERT INTO marketing_segment_rules
                 (workspace_id, segment_id, source_type, field_key, operator, value_text, value_json, sort_order)
                 VALUES (?, ?, ?, ?, ?, ?, ?, ?)",
                [
                    $this->workspaceId(),
                    $segmentId,
                    $rule['source_type'],
                    $rule['field_key'],
                    $rule['operator'],
                    $rule['value_text'],
                    $rule['value_json'],
                    (int) ($rule['sort_order'] ?? $index),
                ]
            );
        }
    }

    private function hydrateAudienceSegmentRow(array $row): array
    {
        $row = $this->hydrateJsonFields($row, ['metadata_json', 'crm_preview_json', 'fit_score_json', 'activation_warnings_json']);
        $row['rule_count'] = (int) ($row['rule_count'] ?? 0);
        $row['snapshot_count'] = (int) ($row['snapshot_count'] ?? 0);
        $row['preview_count'] = (int) ($row['preview_count'] ?? 0);
        $row['fit_score'] = (int) ($row['fit_score'] ?? 0);
        $row['activation_score'] = (int) ($row['activation_score'] ?? 0);

        return $row;
    }

    private function audienceContactBreakdown(array $contactIds, string $column): array
    {
        if ($contactIds === [] || !Database::tableExists('contacts') || !Database::columnExists('contacts', 'workspace_id') || !Database::columnExists('contacts', $column)) {
            return [];
        }

        $placeholders = implode(',', array_fill(0, count($contactIds), '?'));
        return array_map(
            static fn(array $row): array => [
                'label' => (string) ($row['label'] ?? 'Unknown'),
                'count' => (int) ($row['count'] ?? 0),
            ],
            Database::query(
                "SELECT COALESCE(NULLIF(CAST({$column} AS CHAR), ''), 'Unknown') AS label, COUNT(*) AS count
                 FROM contacts
                 WHERE workspace_id = ? AND id IN ({$placeholders})
                 GROUP BY label
                 ORDER BY count DESC, label ASC
                 LIMIT 8",
                array_merge([$this->workspaceId()], $contactIds)
            )
        );
    }

    private function audienceContactOwnerBreakdown(array $contactIds): array
    {
        if ($contactIds === [] || !Database::tableExists('contacts') || !Database::columnExists('contacts', 'workspace_id') || !Database::columnExists('contacts', 'assigned_to')) {
            return [];
        }

        $placeholders = implode(',', array_fill(0, count($contactIds), '?'));
        return array_map(
            static fn(array $row): array => [
                'label' => (string) ($row['label'] ?? 'Unassigned'),
                'count' => (int) ($row['count'] ?? 0),
            ],
            Database::query(
                "SELECT COALESCE(NULLIF(u.email, ''), 'Unassigned') AS label, COUNT(*) AS count
                 FROM contacts c
                 LEFT JOIN users u ON u.id = c.assigned_to
                 WHERE c.workspace_id = ? AND c.id IN ({$placeholders})
                 GROUP BY label
                 ORDER BY count DESC, label ASC
                 LIMIT 8",
                array_merge([$this->workspaceId()], $contactIds)
            )
        );
    }

    private function audienceDealEvidence(array $contactIds): array
    {
        $empty = ['count' => 0, 'open_count' => 0, 'won_count' => 0, 'lost_count' => 0, 'pipeline_value' => 0.0, 'stages' => []];
        if ($contactIds === [] || !Database::tableExists('deals') || !Database::columnExists('deals', 'workspace_id') || !Database::columnExists('deals', 'contact_id')) {
            return $empty;
        }

        $placeholders = implode(',', array_fill(0, count($contactIds), '?'));
        $summary = Database::queryOne(
            "SELECT COUNT(*) AS count,
                    SUM(CASE WHEN stage = 'closed_won' THEN 1 ELSE 0 END) AS won_count,
                    SUM(CASE WHEN stage = 'closed_lost' THEN 1 ELSE 0 END) AS lost_count,
                    SUM(CASE WHEN stage NOT IN ('closed_won','closed_lost') THEN 1 ELSE 0 END) AS open_count,
                    SUM(COALESCE(value, 0)) AS pipeline_value
             FROM deals
             WHERE workspace_id = ? AND contact_id IN ({$placeholders})",
            array_merge([$this->workspaceId()], $contactIds)
        ) ?: [];
        $stages = Database::query(
            "SELECT COALESCE(NULLIF(CAST(stage AS CHAR), ''), 'Unknown') AS label, COUNT(*) AS count
             FROM deals
             WHERE workspace_id = ? AND contact_id IN ({$placeholders})
             GROUP BY label
             ORDER BY count DESC, label ASC
             LIMIT 8",
            array_merge([$this->workspaceId()], $contactIds)
        );

        return [
            'count' => (int) ($summary['count'] ?? 0),
            'open_count' => (int) ($summary['open_count'] ?? 0),
            'won_count' => (int) ($summary['won_count'] ?? 0),
            'lost_count' => (int) ($summary['lost_count'] ?? 0),
            'pipeline_value' => (float) ($summary['pipeline_value'] ?? 0),
            'stages' => array_map(static fn(array $row): array => ['label' => (string) $row['label'], 'count' => (int) $row['count']], $stages),
        ];
    }

    private function audienceFormSubmissionEvidence(array $contactIds): array
    {
        $empty = ['count' => 0, 'forms' => []];
        if ($contactIds === [] || !Database::tableExists('form_submissions') || !Database::columnExists('form_submissions', 'contact_id')) {
            return $empty;
        }

        $workspaceSql = Database::columnExists('form_submissions', 'workspace_id') ? 'fs.workspace_id = ? AND ' : '';
        $params = Database::columnExists('form_submissions', 'workspace_id') ? [$this->workspaceId()] : [];
        $placeholders = implode(',', array_fill(0, count($contactIds), '?'));
        $params = array_merge($params, $contactIds);
        $summary = Database::queryOne(
            "SELECT COUNT(*) AS count
             FROM form_submissions fs
             WHERE {$workspaceSql}fs.contact_id IN ({$placeholders})",
            $params
        ) ?: [];
        $forms = Database::query(
            "SELECT COALESCE(NULLIF(CAST(fs.form_id AS CHAR), ''), 'Unknown form') AS label, COUNT(*) AS count
             FROM form_submissions fs
             WHERE {$workspaceSql}fs.contact_id IN ({$placeholders})
             GROUP BY label
             ORDER BY count DESC, label ASC
             LIMIT 8",
            $params
        );

        return [
            'count' => (int) ($summary['count'] ?? 0),
            'forms' => array_map(static fn(array $row): array => ['label' => (string) $row['label'], 'count' => (int) $row['count']], $forms),
        ];
    }

    private function audienceHandoffEvidence(array $contactIds): array
    {
        $empty = ['count' => 0, 'outcomes' => []];
        if ($contactIds === [] || !Database::tableExists('marketing_lead_handoffs') || !Database::columnExists('marketing_lead_handoffs', 'contact_id')) {
            return $empty;
        }

        $placeholders = implode(',', array_fill(0, count($contactIds), '?'));
        $summary = Database::queryOne(
            "SELECT COUNT(*) AS count
             FROM marketing_lead_handoffs
             WHERE workspace_id = ? AND contact_id IN ({$placeholders})",
            array_merge([$this->workspaceId()], $contactIds)
        ) ?: [];
        $outcomes = Database::query(
            "SELECT COALESCE(NULLIF(COALESCE(sales_outcome, status), ''), 'Unknown') AS label, COUNT(*) AS count
             FROM marketing_lead_handoffs
             WHERE workspace_id = ? AND contact_id IN ({$placeholders})
             GROUP BY label
             ORDER BY count DESC, label ASC
             LIMIT 8",
            array_merge([$this->workspaceId()], $contactIds)
        );

        return [
            'count' => (int) ($summary['count'] ?? 0),
            'outcomes' => array_map(static fn(array $row): array => ['label' => (string) $row['label'], 'count' => (int) $row['count']], $outcomes),
        ];
    }

    private function audienceActivityEvidence(array $contactIds): array
    {
        if ($contactIds === [] || !Database::tableExists('activities') || !Database::columnExists('activities', 'workspace_id') || !Database::columnExists('activities', 'contact_id')) {
            return ['count' => 0, 'types' => []];
        }

        $placeholders = implode(',', array_fill(0, count($contactIds), '?'));
        $summary = Database::queryOne(
            "SELECT COUNT(*) AS count
             FROM activities
             WHERE workspace_id = ? AND contact_id IN ({$placeholders})",
            array_merge([$this->workspaceId()], $contactIds)
        ) ?: [];
        $typeColumn = Database::columnExists('activities', 'activity_type') ? 'activity_type' : 'type';
        $types = Database::columnExists('activities', $typeColumn) ? Database::query(
            "SELECT COALESCE(NULLIF(CAST({$typeColumn} AS CHAR), ''), 'Activity') AS label, COUNT(*) AS count
             FROM activities
             WHERE workspace_id = ? AND contact_id IN ({$placeholders})
             GROUP BY label
             ORDER BY count DESC, label ASC
             LIMIT 8",
            array_merge([$this->workspaceId()], $contactIds)
        ) : [];

        return [
            'count' => (int) ($summary['count'] ?? 0),
            'types' => array_map(static fn(array $row): array => ['label' => (string) $row['label'], 'count' => (int) $row['count']], $types),
        ];
    }

    private function audienceIntelligenceRecommendations(int $matchedContacts, array $evidence, array $segment): array
    {
        $recommendations = [];
        if ($matchedContacts === 0) {
            $recommendations[] = 'Relax one or more filters, or use CRM suggestions to find an audience with existing contacts.';
        }
        if (empty($segment['rules'])) {
            $recommendations[] = 'Add at least one CRM rule so campaigns can target a repeatable audience.';
        }
        if ((int) ($evidence['deals']['count'] ?? 0) === 0) {
            $recommendations[] = 'Pair this audience with offer or nurture content before expecting pipeline attribution.';
        }
        if ((int) ($evidence['handoffs']['count'] ?? 0) === 0) {
            $recommendations[] = 'Create a sales handoff rule once this audience begins producing qualified conversion events.';
        }
        if (empty($segment['last_snapshot_at'])) {
            $recommendations[] = 'Create a snapshot before manual email exports, channel bundles, or sales follow-up.';
        }

        return $recommendations;
    }

    private function topContactDimensionRows(string $column, int $limit): array
    {
        if (!Database::tableExists('contacts') || !Database::columnExists('contacts', 'workspace_id') || !Database::columnExists('contacts', $column)) {
            return [];
        }

        $limit = min(max($limit, 1), 10);
        return Database::query(
            "SELECT COALESCE(NULLIF(CAST({$column} AS CHAR), ''), '') AS value, COUNT(*) AS count
             FROM contacts
             WHERE workspace_id = ?
             GROUP BY value
             HAVING value <> '' AND count > 0
             ORDER BY count DESC, value ASC
             LIMIT {$limit}",
            [$this->workspaceId()]
        );
    }

    private function upsertAudienceRecommendation(array $data): void
    {
        if (!Database::tableExists('marketing_audience_recommendations')) {
            return;
        }

        Database::execute(
            "INSERT INTO marketing_audience_recommendations
             (workspace_id, uuid, recommendation_type, title, description, rule_suggestions_json, fit_score, status, created_by)
             VALUES (?, ?, ?, ?, ?, ?, ?, 'suggested', ?)
             ON DUPLICATE KEY UPDATE
                description = VALUES(description),
                rule_suggestions_json = VALUES(rule_suggestions_json),
                fit_score = GREATEST(fit_score, VALUES(fit_score)),
                updated_at = NOW()",
            [
                $this->workspaceId(),
                $this->generateUuid(),
                $this->normalizeEnum((string) ($data['recommendation_type'] ?? 'lead_source'), self::AUDIENCE_RECOMMENDATION_TYPES, 'audience_recommendation_type'),
                substr(Security::sanitizeInput((string) ($data['title'] ?? 'Audience suggestion'), 'string'), 0, 180),
                $this->nullableSanitizedText($data['description'] ?? ''),
                $this->normalizeJsonValue($this->sanitizeFlexibleArray($data['rule_suggestions_json'] ?? [])),
                max(0, min(100, (int) ($data['fit_score'] ?? 0))),
                ((int) ($data['created_by'] ?? 0)) > 0 ? (int) $data['created_by'] : null,
            ]
        );
    }

    private function labelizeMarketingValue(string $value): string
    {
        $value = trim(str_replace(['_', '-'], ' ', $value));
        return $value === '' ? 'Unknown' : ucwords($value);
    }

    private function hydrateJourneyRow(array $row): array
    {
        $row = $this->hydrateJsonFields($row, ['metadata_json']);
        $row['step_count'] = (int) ($row['step_count'] ?? 0);
        $row['draft_count'] = (int) ($row['draft_count'] ?? 0);

        return $row;
    }

    private function normalizeJourneyData(array $data, bool $forCreate): array
    {
        $workspaceId = $this->workspaceId();
        $normalized = [];

        if ($forCreate || array_key_exists('name', $data)) {
            $name = Security::sanitizeInput((string) ($data['name'] ?? ''), 'string');
            if ($name === '') {
                throw new \InvalidArgumentException('Journey name is required.');
            }
            $normalized['name'] = substr($name, 0, 180);
        }

        foreach (['description', 'journey_goal'] as $field) {
            if ($forCreate || array_key_exists($field, $data)) {
                $normalized[$field] = $this->nullableSanitizedText($data[$field] ?? '');
            }
        }

        if ($forCreate || array_key_exists('status', $data)) {
            $normalized['status'] = $this->normalizeEnum((string) ($data['status'] ?? 'draft'), self::JOURNEY_STATUSES, 'journey_status');
        }

        foreach (['audience_segment_id' => 'marketing_audience_segments', 'campaign_id' => 'campaigns'] as $field => $table) {
            if ($forCreate || array_key_exists($field, $data)) {
                $id = (int) ($data[$field] ?? 0);
                if ($id > 0) {
                    $this->assertWorkspaceRecord($table, $id, $workspaceId);
                    $normalized[$field] = $id;
                } else {
                    $normalized[$field] = null;
                }
            }
        }

        if ($forCreate || array_key_exists('owner_user_id', $data)) {
            $ownerId = (int) ($data['owner_user_id'] ?? 0);
            if ($ownerId > 0) {
                $this->assertWorkspaceUser($ownerId, $workspaceId);
                $normalized['owner_user_id'] = $ownerId;
            } else {
                $normalized['owner_user_id'] = null;
            }
        }

        if ($forCreate || array_key_exists('metadata_json', $data) || array_key_exists('metadata', $data)) {
            $metadata = $this->sanitizeFlexibleArray($data['metadata'] ?? $data['metadata_json'] ?? []);
            $metadata['manual_first'] = $metadata['manual_first'] ?? true;
            $metadata['external_execution'] = false;
            $normalized['metadata_json'] = $this->normalizeJsonValue($metadata);
        }

        if ($forCreate) {
            $normalized['created_by'] = (int) ($data['created_by'] ?? $this->currentUserId()) ?: null;
        }

        return $normalized;
    }

    /**
     * @return array<int,array<string,mixed>>
     */
    private function normalizeJourneySteps(mixed $steps): array
    {
        if (is_string($steps)) {
            $decoded = json_decode($steps, true);
            $steps = is_array($decoded) ? $decoded : [];
        }
        if (!is_array($steps)) {
            return [];
        }

        $normalized = [];
        foreach (array_values($steps) as $index => $step) {
            if (!is_array($step)) {
                continue;
            }
            $title = Security::sanitizeInput((string) ($step['title'] ?? ''), 'string');
            $instructions = trim((string) ($step['instructions'] ?? ''));
            $hasLinkedRecord = ((int) ($step['content_item_id'] ?? 0)) > 0
                || ((int) ($step['email_run_id'] ?? 0)) > 0
                || ((int) ($step['task_id'] ?? 0)) > 0;
            if ($title === '' && $instructions === '' && !$hasLinkedRecord) {
                continue;
            }

            $stepType = $this->normalizeEnum((string) ($step['step_type'] ?? 'email'), self::JOURNEY_STEP_TYPES, 'journey_step_type');
            $normalized[] = [
                'step_order' => max(1, (int) ($step['step_order'] ?? ($index + 1))),
                'step_type' => $stepType,
                'title' => $title !== '' ? substr($title, 0, 180) : $this->defaultJourneyStepTitle($stepType, $index + 1),
                'instructions' => $this->nullableSanitizedText($instructions),
                'wait_days' => array_key_exists('wait_days', $step) && trim((string) $step['wait_days']) !== ''
                    ? max(0, (int) $step['wait_days'])
                    : null,
                'content_item_id' => (int) ($step['content_item_id'] ?? 0) ?: null,
                'email_run_id' => (int) ($step['email_run_id'] ?? 0) ?: null,
                'task_id' => (int) ($step['task_id'] ?? 0) ?: null,
                'condition_json' => $this->normalizeJsonValue($this->sanitizeFlexibleArray($step['condition'] ?? $step['condition_json'] ?? [])),
                'branch_json' => $this->normalizeJsonValue($this->sanitizeFlexibleArray($step['branch'] ?? $step['branch_json'] ?? [])),
                'metadata_json' => $this->normalizeJsonValue($this->sanitizeFlexibleArray($step['metadata'] ?? $step['metadata_json'] ?? [])),
                'created_by' => (int) ($step['created_by'] ?? $this->currentUserId()) ?: null,
            ];
        }

        usort(
            $normalized,
            static fn(array $left, array $right): int => ((int) $left['step_order'] <=> (int) $right['step_order'])
        );

        foreach (array_values($normalized) as $index => $step) {
            $normalized[$index]['step_order'] = $index + 1;
            foreach (['content_item_id' => 'marketing_content_items', 'email_run_id' => 'marketing_email_campaign_runs', 'task_id' => 'tasks'] as $field => $table) {
                $id = (int) ($normalized[$index][$field] ?? 0);
                if ($id > 0) {
                    $this->assertWorkspaceRecord($table, $id, $this->workspaceId());
                } else {
                    $normalized[$index][$field] = null;
                }
            }
        }

        return $normalized;
    }

    private function replaceJourneySteps(int $journeyId, array $steps): void
    {
        $this->assertWorkspaceRecord('marketing_journeys', $journeyId, $this->workspaceId());
        Database::execute(
            'DELETE FROM marketing_journey_steps WHERE workspace_id = ? AND journey_id = ?',
            [$this->workspaceId(), $journeyId]
        );

        foreach ($steps as $step) {
            Database::execute(
                "INSERT INTO marketing_journey_steps
                 (workspace_id, journey_id, uuid, step_order, step_type, title, instructions, wait_days,
                  content_item_id, email_run_id, task_id, condition_json, branch_json, metadata_json, created_by)
                 VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)",
                [
                    $this->workspaceId(),
                    $journeyId,
                    $this->generateUuid(),
                    (int) $step['step_order'],
                    $step['step_type'],
                    $step['title'],
                    $step['instructions'],
                    $step['wait_days'],
                    $step['content_item_id'],
                    $step['email_run_id'],
                    $step['task_id'],
                    $step['condition_json'],
                    $step['branch_json'],
                    $step['metadata_json'],
                    $step['created_by'],
                ]
            );
        }
    }

    private function normalizeJourneyDraftData(array $data, bool $forCreate): array
    {
        $normalized = [];

        if ($forCreate || array_key_exists('journey_id', $data)) {
            $journeyId = (int) ($data['journey_id'] ?? 0);
            if ($journeyId > 0) {
                $this->assertWorkspaceRecord('marketing_journeys', $journeyId, $this->workspaceId());
                $normalized['journey_id'] = $journeyId;
            } else {
                $normalized['journey_id'] = null;
            }
        }

        if ($forCreate || array_key_exists('draft_type', $data)) {
            $normalized['draft_type'] = $this->normalizeEnum((string) ($data['draft_type'] ?? 'manual'), self::JOURNEY_DRAFT_TYPES, 'journey_draft_type');
        }
        if ($forCreate || array_key_exists('prompt', $data)) {
            $normalized['prompt'] = $this->nullableSanitizedText($data['prompt'] ?? '');
        }
        if ($forCreate || array_key_exists('draft_json', $data) || array_key_exists('draft', $data)) {
            $normalized['draft_json'] = $this->normalizeJsonValue($this->sanitizeFlexibleArray($data['draft'] ?? $data['draft_json'] ?? []));
        }
        if ($forCreate || array_key_exists('status', $data)) {
            $normalized['status'] = $this->normalizeEnum((string) ($data['status'] ?? 'draft'), self::JOURNEY_DRAFT_STATUSES, 'journey_draft_status');
        }
        if ($forCreate || array_key_exists('provider_json', $data) || array_key_exists('provider', $data)) {
            $normalized['provider_json'] = $this->normalizeJsonValue($this->sanitizeFlexibleArray($data['provider'] ?? $data['provider_json'] ?? []));
        }
        if ($forCreate) {
            $normalized['created_by'] = (int) ($data['created_by'] ?? $this->currentUserId()) ?: null;
        }

        return $normalized;
    }

    private function fallbackJourneyDraft(array $input, array $journey = []): array
    {
        $name = trim((string) ($journey['name'] ?? $input['name'] ?? 'Manual marketing journey')) ?: 'Manual marketing journey';
        $goal = trim((string) ($journey['journey_goal'] ?? $input['journey_goal'] ?? $input['prompt'] ?? 'Move the audience to a clear next step'));
        $audience = trim((string) ($journey['audience_segment_name'] ?? $input['audience_segment_name'] ?? 'selected audience'));
        $campaign = trim((string) ($journey['campaign_name'] ?? $input['campaign_name'] ?? 'campaign plan'));
        $existingSteps = (array) ($journey['steps'] ?? []);
        $steps = [];

        if ($existingSteps !== []) {
            foreach ($existingSteps as $step) {
                $steps[] = [
                    'step_type' => (string) ($step['step_type'] ?? 'task'),
                    'title' => (string) ($step['title'] ?? 'Journey step'),
                    'instructions' => (string) ($step['instructions'] ?? ''),
                    'manual_execution_only' => true,
                ];
            }
        } else {
            $steps = [
                [
                    'step_type' => 'email',
                    'title' => 'Send welcome or campaign context',
                    'instructions' => 'Export or draft the first message manually and confirm audience fit before use.',
                    'manual_execution_only' => true,
                ],
                [
                    'step_type' => 'wait',
                    'title' => 'Wait and review engagement',
                    'instructions' => 'Pause for two to three days, then review replies, form submissions, and CRM activity.',
                    'wait_days' => 3,
                    'manual_execution_only' => true,
                ],
                [
                    'step_type' => 'task',
                    'title' => 'Follow up with engaged contacts',
                    'instructions' => 'Create human follow-up tasks for contacts showing clear intent.',
                    'manual_execution_only' => true,
                ],
                [
                    'step_type' => 'branch',
                    'title' => 'Branch based on response',
                    'instructions' => 'Route high-intent contacts to sales follow-up and low-intent contacts to nurture content.',
                    'manual_execution_only' => true,
                ],
            ];
        }

        return [
            'journey_name' => $name,
            'goal' => $goal,
            'audience' => $audience,
            'campaign' => $campaign,
            'recommended_steps' => $steps,
            'review_checklist' => [
                'Confirm audience segment and snapshot before export.',
                'Confirm every message has a CTA and unsubscribe/suppression plan where relevant.',
                'Assign manual owners for follow-up tasks.',
                'Keep execution manual until a connector is ready and explicitly approved.',
            ],
            'manual_execution_only' => true,
            'external_execution' => false,
        ];
    }

    private function defaultJourneyStepTitle(string $stepType, int $position): string
    {
        return 'Step ' . $position . ': ' . ucwords(str_replace('_', ' ', $stepType));
    }

    private function evaluateAudienceSegmentRules(array $rules, string $ruleLogic, int $limit = 50): array
    {
        $limit = min(max($limit, 1), 5000);
        $logic = $this->normalizeEnum($ruleLogic, self::AUDIENCE_SEGMENT_RULE_LOGIC, 'segment_rule_logic');
        $where = ['c.workspace_id = ?'];
        $params = [$this->workspaceId()];
        $ruleSql = [];
        $ruleParams = [];

        foreach ($rules as $rule) {
            if (!is_array($rule)) {
                continue;
            }
            $built = $this->buildAudienceRuleSql($rule);
            if ($built === null) {
                continue;
            }
            $ruleSql[] = '(' . $built['sql'] . ')';
            array_push($ruleParams, ...$built['params']);
        }

        if ($ruleSql !== []) {
            $where[] = '(' . implode($logic === 'any' ? ' OR ' : ' AND ', $ruleSql) . ')';
            array_push($params, ...$ruleParams);
        }

        $whereSql = implode(' AND ', $where);
        $count = (int) (Database::queryOne(
            "SELECT COUNT(DISTINCT c.id) AS count FROM contacts c WHERE {$whereSql}",
            $params
        )['count'] ?? 0);

        $contacts = Database::query(
            "SELECT DISTINCT c.id, c.first_name, c.last_name, c.email, c.phone, c.company, c.stage, c.lead_source, c.created_at
             FROM contacts c
             WHERE {$whereSql}
             ORDER BY c.updated_at DESC, c.id DESC
             LIMIT {$limit}",
            $params
        );

        return [
            'count' => $count,
            'contacts' => $contacts,
            'contact_ids' => array_map(static fn(array $row): int => (int) $row['id'], $contacts),
            'rules_applied' => count($ruleSql),
            'manual_first' => true,
        ];
    }

    private function buildAudienceRuleSql(array $rule): ?array
    {
        $sourceType = (string) ($rule['source_type'] ?? '');
        $fieldKey = (string) ($rule['field_key'] ?? '');
        $operator = (string) ($rule['operator'] ?? 'equals');
        $value = (string) ($rule['value_text'] ?? '');
        $definitions = $this->audienceSegmentRuleFields();
        if (!isset($definitions[$sourceType][$fieldKey])) {
            return null;
        }
        $definition = $definitions[$sourceType][$fieldKey];

        if ($sourceType === 'contact') {
            return $this->buildAudienceScalarCondition((string) $definition['expression'], $operator, $value);
        }

        $condition = $this->buildAudienceScalarCondition((string) $definition['expression'], $operator, $value);
        if ($condition === null) {
            return null;
        }
        $existsSql = (string) $definition['exists_sql'];
        if ($operator === 'not_exists') {
            return ['sql' => "NOT EXISTS ({$existsSql})", 'params' => [$this->workspaceId()]];
        }
        if ($operator === 'exists') {
            return ['sql' => "EXISTS ({$existsSql})", 'params' => [$this->workspaceId()]];
        }

        return [
            'sql' => "EXISTS ({$existsSql} AND {$condition['sql']})",
            'params' => array_merge([$this->workspaceId()], $condition['params']),
        ];
    }

    private function buildAudienceScalarCondition(string $expression, string $operator, string $value): ?array
    {
        $value = trim($value);
        if ($operator === 'exists') {
            return ['sql' => "{$expression} IS NOT NULL AND CAST({$expression} AS CHAR) <> ''", 'params' => []];
        }
        if ($operator === 'not_exists') {
            return ['sql' => "({$expression} IS NULL OR CAST({$expression} AS CHAR) = '')", 'params' => []];
        }
        if (!in_array($operator, ['exists', 'not_exists'], true) && $value === '') {
            return null;
        }

        if (in_array($operator, ['in', 'not_in'], true)) {
            $values = array_values(array_filter(array_map('trim', preg_split('/[,;\n]+/', $value) ?: []), static fn(string $item): bool => $item !== ''));
            if ($values === []) {
                return null;
            }
            $placeholders = implode(',', array_fill(0, count($values), '?'));
            return [
                'sql' => "{$expression} " . ($operator === 'in' ? 'IN' : 'NOT IN') . " ({$placeholders})",
                'params' => $values,
            ];
        }

        if ($operator === 'between') {
            $parts = array_values(array_filter(array_map('trim', preg_split('/[,|]+/', $value) ?: []), static fn(string $item): bool => $item !== ''));
            if (count($parts) < 2) {
                return null;
            }
            return ['sql' => "{$expression} BETWEEN ? AND ?", 'params' => [$parts[0], $parts[1]]];
        }

        return match ($operator) {
            'equals' => ['sql' => "{$expression} = ?", 'params' => [$value]],
            'not_equals' => ['sql' => "{$expression} <> ?", 'params' => [$value]],
            'contains' => ['sql' => "{$expression} LIKE ?", 'params' => ['%' . $value . '%']],
            'not_contains' => ['sql' => "({$expression} IS NULL OR {$expression} NOT LIKE ?)", 'params' => ['%' . $value . '%']],
            'greater_than' => ['sql' => "{$expression} > ?", 'params' => [$value]],
            'less_than' => ['sql' => "{$expression} < ?", 'params' => [$value]],
            'after' => ['sql' => "{$expression} > ?", 'params' => [$value]],
            'before' => ['sql' => "{$expression} < ?", 'params' => [$value]],
            default => null,
        };
    }

    private function audienceSegmentRuleFields(): array
    {
        $basicOperators = ['equals', 'not_equals', 'contains', 'not_contains', 'in', 'not_in', 'exists', 'not_exists'];
        $numberOperators = ['equals', 'not_equals', 'greater_than', 'less_than', 'between', 'exists', 'not_exists'];
        $dateOperators = ['after', 'before', 'between', 'exists', 'not_exists'];

        return [
            'contact' => [
                'stage' => ['key' => 'stage', 'label' => 'Contact stage', 'expression' => 'c.stage', 'operators' => $basicOperators],
                'lead_source' => ['key' => 'lead_source', 'label' => 'Lead source', 'expression' => 'c.lead_source', 'operators' => $basicOperators],
                'email' => ['key' => 'email', 'label' => 'Email', 'expression' => 'c.email', 'operators' => $basicOperators],
                'company' => ['key' => 'company', 'label' => 'Company', 'expression' => 'c.company', 'operators' => $basicOperators],
                'job_title' => ['key' => 'job_title', 'label' => 'Job title', 'expression' => 'c.job_title', 'operators' => $basicOperators],
                'location' => ['key' => 'location', 'label' => 'Location', 'expression' => 'c.location', 'operators' => $basicOperators],
                'engagement_score' => ['key' => 'engagement_score', 'label' => 'Engagement score', 'expression' => 'c.engagement_score', 'operators' => $numberOperators],
                'created_at' => ['key' => 'created_at', 'label' => 'Created date', 'expression' => 'c.created_at', 'operators' => $dateOperators],
                'updated_at' => ['key' => 'updated_at', 'label' => 'Updated date', 'expression' => 'c.updated_at', 'operators' => $dateOperators],
            ],
            'company' => [
                'name' => ['key' => 'name', 'label' => 'Company name', 'expression' => 'co.name', 'exists_sql' => 'SELECT 1 FROM companies co WHERE co.id = c.company_id AND co.workspace_id = ?', 'operators' => $basicOperators],
                'industry' => ['key' => 'industry', 'label' => 'Company industry', 'expression' => 'co.industry', 'exists_sql' => 'SELECT 1 FROM companies co WHERE co.id = c.company_id AND co.workspace_id = ?', 'operators' => $basicOperators],
                'size' => ['key' => 'size', 'label' => 'Company size', 'expression' => 'co.size', 'exists_sql' => 'SELECT 1 FROM companies co WHERE co.id = c.company_id AND co.workspace_id = ?', 'operators' => $basicOperators],
            ],
            'deal' => [
                'stage' => ['key' => 'stage', 'label' => 'Deal stage', 'expression' => 'd.stage', 'exists_sql' => 'SELECT 1 FROM deals d WHERE d.contact_id = c.id AND d.workspace_id = ?', 'operators' => $basicOperators],
                'value' => ['key' => 'value', 'label' => 'Deal value', 'expression' => 'd.value', 'exists_sql' => 'SELECT 1 FROM deals d WHERE d.contact_id = c.id AND d.workspace_id = ?', 'operators' => $numberOperators],
                'campaign_id' => ['key' => 'campaign_id', 'label' => 'Deal campaign ID', 'expression' => 'd.campaign_id', 'exists_sql' => 'SELECT 1 FROM deals d WHERE d.contact_id = c.id AND d.workspace_id = ?', 'operators' => $numberOperators],
                'lead_source' => ['key' => 'lead_source', 'label' => 'Deal lead source', 'expression' => 'd.lead_source', 'exists_sql' => 'SELECT 1 FROM deals d WHERE d.contact_id = c.id AND d.workspace_id = ?', 'operators' => $basicOperators],
            ],
            'form_submission' => [
                'form_id' => ['key' => 'form_id', 'label' => 'Form public ID', 'expression' => 'fs.form_id', 'exists_sql' => 'SELECT 1 FROM form_submissions fs WHERE fs.contact_id = c.id AND fs.workspace_id = ?', 'operators' => $basicOperators],
                'form_definition_id' => ['key' => 'form_definition_id', 'label' => 'Form definition ID', 'expression' => 'fs.form_definition_id', 'exists_sql' => 'SELECT 1 FROM form_submissions fs WHERE fs.contact_id = c.id AND fs.workspace_id = ?', 'operators' => $numberOperators],
                'utm_source' => ['key' => 'utm_source', 'label' => 'UTM source', 'expression' => 'fs.utm_source', 'exists_sql' => 'SELECT 1 FROM form_submissions fs WHERE fs.contact_id = c.id AND fs.workspace_id = ?', 'operators' => $basicOperators],
                'utm_campaign' => ['key' => 'utm_campaign', 'label' => 'UTM campaign', 'expression' => 'fs.utm_campaign', 'exists_sql' => 'SELECT 1 FROM form_submissions fs WHERE fs.contact_id = c.id AND fs.workspace_id = ?', 'operators' => $basicOperators],
                'submitted_at' => ['key' => 'submitted_at', 'label' => 'Submitted date', 'expression' => 'fs.submitted_at', 'exists_sql' => 'SELECT 1 FROM form_submissions fs WHERE fs.contact_id = c.id AND fs.workspace_id = ?', 'operators' => $dateOperators],
            ],
            'tag' => [
                'name' => ['key' => 'name', 'label' => 'Tag name', 'expression' => 't.name', 'exists_sql' => "SELECT 1 FROM tag_assignments ta JOIN tags t ON t.id = ta.tag_id AND t.workspace_id = ta.workspace_id WHERE ta.entity_type = 'contact' AND ta.entity_id = c.id AND ta.workspace_id = ?", 'operators' => $basicOperators],
                'tag_id' => ['key' => 'tag_id', 'label' => 'Tag ID', 'expression' => 'ta.tag_id', 'exists_sql' => "SELECT 1 FROM tag_assignments ta JOIN tags t ON t.id = ta.tag_id AND t.workspace_id = ta.workspace_id WHERE ta.entity_type = 'contact' AND ta.entity_id = c.id AND ta.workspace_id = ?", 'operators' => $numberOperators],
            ],
            'activity' => [
                'activity_type' => ['key' => 'activity_type', 'label' => 'Activity type', 'expression' => 'a.activity_type', 'exists_sql' => 'SELECT 1 FROM activities a WHERE a.contact_id = c.id AND a.workspace_id = ?', 'operators' => $basicOperators],
                'description' => ['key' => 'description', 'label' => 'Activity description', 'expression' => 'a.description', 'exists_sql' => 'SELECT 1 FROM activities a WHERE a.contact_id = c.id AND a.workspace_id = ?', 'operators' => $basicOperators],
                'created_at' => ['key' => 'created_at', 'label' => 'Activity date', 'expression' => 'a.created_at', 'exists_sql' => 'SELECT 1 FROM activities a WHERE a.contact_id = c.id AND a.workspace_id = ?', 'operators' => $dateOperators],
            ],
        ];
    }

    private function normalizeSavedViewData(array $data, bool $forCreate): array
    {
        $workspaceId = $this->workspaceId();
        $normalized = [];

        if ($forCreate || array_key_exists('name', $data)) {
            $name = Security::sanitizeInput((string) ($data['name'] ?? ''), 'string');
            if ($name === '') {
                throw new \InvalidArgumentException('Saved view name is required.');
            }
            $normalized['name'] = substr($name, 0, 120);
        }

        foreach ([
            'view_type' => self::SAVED_VIEW_TYPES,
            'scope' => self::SAVED_VIEW_SCOPES,
            'view_mode' => self::WORKBENCH_VIEW_MODES,
        ] as $field => $allowed) {
            if ($forCreate || array_key_exists($field, $data)) {
                $default = $field === 'view_type' ? 'content' : ($field === 'scope' ? 'private' : 'list');
                $normalized[$field] = $this->normalizeEnum((string) ($data[$field] ?? $default), $allowed, $field);
            }
        }

        if ($forCreate || array_key_exists('filters', $data) || array_key_exists('filters_json', $data)) {
            $normalized['filters_json'] = $this->normalizeJsonValue($this->sanitizeFlexibleArray($data['filters'] ?? $data['filters_json'] ?? []));
        }
        if ($forCreate || array_key_exists('sort', $data) || array_key_exists('sort_json', $data)) {
            $normalized['sort_json'] = $this->normalizeJsonValue($this->sanitizeFlexibleArray($data['sort'] ?? $data['sort_json'] ?? []));
        }
        if ($forCreate || array_key_exists('is_default', $data)) {
            $normalized['is_default'] = !empty($data['is_default']) ? 1 : 0;
        }

        if ($forCreate || array_key_exists('user_id', $data)) {
            $userId = (int) ($data['user_id'] ?? $this->currentUserId());
            if ($userId > 0) {
                $this->assertWorkspaceUser($userId, $workspaceId);
                $normalized['user_id'] = $userId;
            } else {
                $normalized['user_id'] = null;
            }
        }

        if ($forCreate) {
            $createdBy = (int) ($data['created_by'] ?? $this->currentUserId());
            $normalized['created_by'] = $createdBy > 0 ? $createdBy : null;
        }

        return $normalized;
    }

    private function normalizeContentData(array $data, bool $forCreate): array
    {
        $workspaceId = $this->workspaceId();
        $normalized = [];

        $title = Security::sanitizeInput((string) ($data['title'] ?? ''), 'string');
        if ($forCreate || array_key_exists('title', $data)) {
            if ($title === '') {
                throw new \InvalidArgumentException('Content title is required.');
            }
            $normalized['title'] = $title;
        }

        foreach ([
            'content_type' => self::CONTENT_TYPES,
            'channel' => self::CHANNELS,
            'status' => self::STATUSES,
        ] as $field => $allowed) {
            if ($forCreate || array_key_exists($field, $data)) {
                $default = $field === 'content_type' ? 'social_post' : ($field === 'channel' ? 'other' : 'idea');
                $normalized[$field] = $this->normalizeEnum((string) ($data[$field] ?? $default), $allowed, $field);
            }
        }

        if ($forCreate || array_key_exists('production_stage', $data)) {
            $defaultStage = $this->defaultProductionStageForStatus((string) ($normalized['status'] ?? $data['status'] ?? 'idea'));
            $normalized['production_stage'] = $this->normalizeEnum(
                (string) ($data['production_stage'] ?? $defaultStage),
                self::CONTENT_PRODUCTION_STAGES,
                'production_stage'
            );
        }

        foreach (['production_due_at', 'production_started_at', 'production_completed_at'] as $field) {
            if ($forCreate || array_key_exists($field, $data)) {
                $normalized[$field] = $this->normalizeDateTime((string) ($data[$field] ?? ''));
            }
        }

        if ($forCreate || array_key_exists('dependency_status', $data)) {
            $normalized['dependency_status'] = $this->normalizeEnum(
                (string) ($data['dependency_status'] ?? 'clear'),
                self::CONTENT_DEPENDENCY_HEALTH_STATUSES,
                'dependency_status'
            );
        }

        if ($forCreate || array_key_exists('dependency_notes', $data)) {
            $normalized['dependency_notes'] = $this->nullableSanitizedText($data['dependency_notes'] ?? '');
        }

        if ($forCreate || array_key_exists('production_checklist_json', $data) || array_key_exists('production_checklist', $data)) {
            $normalized['production_checklist_json'] = $this->normalizeStringListJson($data['production_checklist'] ?? $data['production_checklist_json'] ?? []);
        }

        foreach (['funnel_stage', 'objective', 'target_audience'] as $field) {
            if ($forCreate || array_key_exists($field, $data)) {
                $value = Security::sanitizeInput((string) ($data[$field] ?? ''), 'string');
                $normalized[$field] = $value !== '' ? $value : null;
            }
        }

        foreach ([
            'campaign_brief_id' => 'marketing_campaign_briefs',
            'brand_profile_id' => 'marketing_brand_profiles',
            'persona_id' => 'marketing_personas',
            'seo_topic_id' => 'marketing_seo_topics',
            'landing_page_id' => 'marketing_landing_pages',
            'campaign_id' => 'campaigns',
            'form_id' => 'forms',
            'task_id' => 'tasks',
        ] as $field => $table) {
            if ($forCreate || array_key_exists($field, $data)) {
                $id = (int) ($data[$field] ?? 0);
                if ($id > 0) {
                    $this->assertWorkspaceRecord($table, $id, $workspaceId);
                    $normalized[$field] = $id;
                } else {
                    $normalized[$field] = null;
                }
            }
        }

        if ($forCreate || array_key_exists('email_template_id', $data)) {
            $id = (int) ($data['email_template_id'] ?? 0);
            if ($id > 0) {
                $this->assertEmailTemplateAvailable($id, $workspaceId);
                $normalized['email_template_id'] = $id;
            } else {
                $normalized['email_template_id'] = null;
            }
        }

        foreach (['scheduled_at', 'published_at'] as $field) {
            if ($forCreate || array_key_exists($field, $data)) {
                $normalized[$field] = $this->normalizeDateTime((string) ($data[$field] ?? ''));
            }
        }

        if ($forCreate || array_key_exists('draft_body', $data)) {
            $normalized['draft_body'] = trim((string) ($data['draft_body'] ?? '')) ?: null;
        }

        foreach (['ai_context_json', 'metadata_json'] as $field) {
            if ($forCreate || array_key_exists($field, $data)) {
                $value = $data[$field] ?? null;
                $normalized[$field] = $value === null || $value === ''
                    ? null
                    : (is_string($value) ? $value : json_encode($value, JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE));
            }
        }

        if ($forCreate || array_key_exists('owner_user_id', $data)) {
            $ownerId = (int) ($data['owner_user_id'] ?? 0);
            if ($ownerId > 0) {
                $this->assertWorkspaceUser($ownerId, $workspaceId);
                $normalized['owner_user_id'] = $ownerId;
            } else {
                $normalized['owner_user_id'] = null;
            }
        }

        if ($forCreate || array_key_exists('reviewer_user_id', $data)) {
            $reviewerId = (int) ($data['reviewer_user_id'] ?? 0);
            if ($reviewerId > 0) {
                $this->assertWorkspaceUser($reviewerId, $workspaceId);
                $normalized['reviewer_user_id'] = $reviewerId;
            } else {
                $normalized['reviewer_user_id'] = null;
            }
        }

        if ($forCreate || array_key_exists('review_due_at', $data)) {
            $normalized['review_due_at'] = $this->normalizeDateTime((string) ($data['review_due_at'] ?? ''));
        }

        if ($forCreate || array_key_exists('blocked_reason', $data)) {
            $normalized['blocked_reason'] = $this->nullableSanitizedText($data['blocked_reason'] ?? '');
        }

        if ($forCreate || array_key_exists('approval_checklist_json', $data) || array_key_exists('approval_checklist', $data)) {
            $normalized['approval_checklist_json'] = $this->normalizeStringListJson($data['approval_checklist'] ?? $data['approval_checklist_json'] ?? []);
        }

        $governance = $this->calculateContentReadiness($normalized + $data);
        $normalized['readiness_score'] = $governance['score'];
        $normalized['required_context_warnings_json'] = $governance['warnings'] === []
            ? null
            : json_encode($governance['warnings'], JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE);

        $production = $this->calculateContentProductionReadiness($normalized + $data);
        $normalized['production_score'] = $production['score'];
        $normalized['next_action'] = $production['next_action'];

        if ($forCreate) {
            $normalized['created_by'] = (int) ($data['created_by'] ?? ($_SESSION['user_id'] ?? 0)) ?: null;
        }

        return $normalized;
    }

    private function normalizeContentMediaData(int $contentItemId, array $data, bool $forCreate): array
    {
        $workspaceId = $this->workspaceId();
        $this->assertWorkspaceRecord('marketing_content_items', $contentItemId, $workspaceId);
        $normalized = [];

        if ($forCreate || array_key_exists('media_file_id', $data)) {
            $mediaId = (int) ($data['media_file_id'] ?? 0);
            if ($mediaId <= 0) {
                throw new \InvalidArgumentException('Choose a media file to attach.');
            }
            $this->assertWorkspaceRecord('marketing_media_files', $mediaId, $workspaceId);
            $normalized['media_file_id'] = $mediaId;
        }

        if ($forCreate || array_key_exists('role', $data)) {
            $normalized['role'] = $this->normalizeEnum((string) ($data['role'] ?? 'attachment'), self::CONTENT_MEDIA_ROLES, 'content_media_role');
        }

        if ($forCreate || array_key_exists('channel', $data)) {
            $channel = trim((string) ($data['channel'] ?? ''));
            $normalized['channel'] = $channel !== ''
                ? $this->normalizeEnum($channel, self::CHANNELS, 'content_media_channel')
                : null;
        }

        foreach (['crop_guidance', 'placement_notes', 'caption', 'alt_text_override'] as $field) {
            if ($forCreate || array_key_exists($field, $data)) {
                $normalized[$field] = $this->nullableSanitizedText($data[$field] ?? '');
            }
        }

        if ($forCreate || array_key_exists('sort_order', $data)) {
            $normalized['sort_order'] = max(0, (int) ($data['sort_order'] ?? 0));
        }

        if ($forCreate || array_key_exists('metadata_json', $data) || array_key_exists('metadata', $data)) {
            $normalized['metadata_json'] = $this->normalizeJsonValue($this->sanitizeFlexibleArray($data['metadata'] ?? $data['metadata_json'] ?? []));
        }

        if ($forCreate) {
            $createdBy = (int) ($data['created_by'] ?? $this->currentUserId());
            $normalized['created_by'] = $createdBy > 0 ? $createdBy : null;
        }

        return $normalized;
    }

    /**
     * @return array<int,array<string,mixed>>
     */
    private function normalizeContentMediaEntries(mixed $entries): array
    {
        if (is_string($entries)) {
            $decoded = json_decode($entries, true);
            $entries = is_array($decoded) ? $decoded : preg_split('/\r?\n+/', $entries);
        }

        $rows = [];
        foreach ((array) $entries as $entry) {
            if (is_array($entry)) {
                $mediaId = (int) ($entry['media_file_id'] ?? $entry['media_id'] ?? 0);
                $role = (string) ($entry['role'] ?? 'attachment');
                $channel = (string) ($entry['channel'] ?? '');
                $caption = (string) ($entry['caption'] ?? '');
                $altText = (string) ($entry['alt_text_override'] ?? $entry['alt_text'] ?? '');
                $placement = (string) ($entry['placement_notes'] ?? $entry['placement'] ?? '');
                $crop = (string) ($entry['crop_guidance'] ?? $entry['crop'] ?? '');
            } else {
                $parts = array_map('trim', explode('|', (string) $entry));
                $role = (string) ($parts[0] ?? 'attachment');
                $mediaId = (int) ($parts[1] ?? 0);
                $caption = (string) ($parts[2] ?? '');
                $altText = (string) ($parts[3] ?? '');
                $placement = (string) ($parts[4] ?? '');
                $crop = (string) ($parts[5] ?? '');
                $channel = (string) ($parts[6] ?? '');
            }

            if ($mediaId <= 0) {
                continue;
            }

            $rows[] = [
                'media_file_id' => $mediaId,
                'role' => $role !== '' ? $role : 'attachment',
                'channel' => $channel,
                'caption' => $caption,
                'alt_text_override' => $altText,
                'placement_notes' => $placement,
                'crop_guidance' => $crop,
            ];
        }

        return $rows;
    }

    private function hydrateCampaignPlaybookRow(array $row): array
