            'default_distribution_plan_json',
            'recommended_assets_json',
            'automation_notes_json',
            'missing_requirements_json',
            'metadata_json',
        ]);
        $row['stage_count'] = (int) ($row['stage_count'] ?? 0);
        $row['brief_count'] = (int) ($row['brief_count'] ?? 0);
        $row['readiness_score'] = (int) ($row['readiness_score'] ?? 0);
        $row['is_template'] = (int) ($row['is_template'] ?? 0);

        return $row;
    }

    private function normalizeCampaignPlaybookData(array $data, bool $forCreate): array
    {
        $workspaceId = $this->workspaceId();
        $normalized = [];

        if ($forCreate || array_key_exists('name', $data)) {
            $name = Security::sanitizeInput((string) ($data['name'] ?? ''), 'string');
            if ($name === '') {
                throw new \InvalidArgumentException('Campaign playbook name is required.');
            }
            $normalized['name'] = mb_substr($name, 0, 180);
        }

        foreach (['description', 'campaign_goal', 'target_audience'] as $field) {
            if ($forCreate || array_key_exists($field, $data)) {
                $normalized[$field] = $this->nullableSanitizedText($data[$field] ?? '');
            }
        }

        if ($forCreate || array_key_exists('status', $data)) {
            $normalized['status'] = $this->normalizeEnum((string) ($data['status'] ?? 'draft'), self::CAMPAIGN_PLAYBOOK_STATUSES, 'campaign_playbook_status');
        }
        if ($forCreate || array_key_exists('playbook_type', $data)) {
            $normalized['playbook_type'] = $this->normalizeEnum((string) ($data['playbook_type'] ?? 'custom'), self::CAMPAIGN_PLAYBOOK_TYPES, 'campaign_playbook_type');
        }
        if ($forCreate || array_key_exists('template_key', $data)) {
            $templateKey = $this->normalizeCampaignPlaybookTemplateKey((string) ($data['template_key'] ?? ''));
            $normalized['template_key'] = $templateKey !== '' ? $templateKey : null;
        }
        if ($forCreate || array_key_exists('is_template', $data)) {
            $normalized['is_template'] = !empty($data['is_template']) ? 1 : 0;
        }

        foreach ([
            'audience_segment_id' => 'marketing_audience_segments',
            'persona_id' => 'marketing_personas',
            'offer_context_item_id' => 'marketing_context_items',
            'landing_page_id' => 'marketing_landing_pages',
        ] as $field => $table) {
            if ($forCreate || array_key_exists($field, $data)) {
                $id = (int) ($data[$field] ?? 0);
                if ($id > 0) {
                    $this->assertWorkspaceRecord($table, $id, $workspaceId);
                    if ($field === 'offer_context_item_id') {
                        $this->assertContextItemType($id, 'offer', $workspaceId);
                    }
                    $normalized[$field] = $id;
                } else {
                    $normalized[$field] = null;
                }
            }
        }

        foreach ([
            'success_metrics_json' => ['success_metrics', 'success_metrics_json'],
            'channel_plan_json' => ['channel_plan', 'channel_plan_json'],
            'checklist_json' => ['checklist', 'checklist_json'],
        ] as $dbField => $inputFields) {
            if ($forCreate || array_key_exists($inputFields[0], $data) || array_key_exists($inputFields[1], $data)) {
                $sourceField = array_key_exists($inputFields[0], $data) ? $inputFields[0] : $inputFields[1];
                $normalized[$dbField] = $this->normalizeStringListJson($data[$sourceField] ?? []);
            }
        }
        foreach ([
            'default_content_plan_json' => ['default_content_plan', 'default_content_plan_json'],
            'default_distribution_plan_json' => ['default_distribution_plan', 'default_distribution_plan_json'],
            'recommended_assets_json' => ['recommended_assets', 'recommended_assets_json'],
            'automation_notes_json' => ['automation_notes', 'automation_notes_json'],
        ] as $dbField => $inputFields) {
            if ($forCreate || array_key_exists($inputFields[0], $data) || array_key_exists($inputFields[1], $data)) {
                $sourceField = array_key_exists($inputFields[0], $data) ? $inputFields[0] : $inputFields[1];
                $normalized[$dbField] = $this->normalizeJsonValue($this->sanitizeFlexibleArray($data[$sourceField] ?? []));
            }
        }

        if ($forCreate || array_key_exists('owner_user_id', $data)) {
            $ownerId = (int) ($data['owner_user_id'] ?? 0);
            if ($ownerId > 0) {
                $this->assertWorkspaceUser($ownerId, $workspaceId);
                $normalized['owner_user_id'] = $ownerId;
            } else {
                $normalized['owner_user_id'] = null;
            }
        }

        if ($forCreate || array_key_exists('metadata_json', $data) || array_key_exists('metadata', $data)) {
            $metadata = $this->sanitizeFlexibleArray($data['metadata'] ?? $data['metadata_json'] ?? []);
            $metadata['manual_first'] = $metadata['manual_first'] ?? true;
            $metadata['external_execution'] = false;
            $normalized['metadata_json'] = $this->normalizeJsonValue($metadata);
        }

        $normalized['readiness_score'] = (int) ($data['readiness_score'] ?? 0);
        $normalized['missing_requirements_json'] = $this->normalizeJsonValue($data['missing_requirements_json'] ?? []);

        if ($forCreate) {
            $normalized['created_by'] = (int) ($data['created_by'] ?? $this->currentUserId()) ?: null;
        }

        return $normalized;
    }

    private function normalizeCampaignPlaybookStages(mixed $stages): array
    {
        if (is_string($stages)) {
            $decoded = json_decode($stages, true);
            $stages = json_last_error() === JSON_ERROR_NONE ? $decoded : [];
        }
        if (!is_array($stages)) {
            return [];
        }

        $normalized = [];
        foreach (array_values($stages) as $index => $stage) {
            if (!is_array($stage)) {
                continue;
            }
            $title = Security::sanitizeInput((string) ($stage['title'] ?? ''), 'string');
            if ($title === '') {
                continue;
            }
            $normalized[] = [
                'stage_order' => max(1, (int) ($stage['stage_order'] ?? ($index + 1))),
                'stage_type' => $this->normalizeEnum((string) ($stage['stage_type'] ?? 'strategy'), self::CAMPAIGN_PLAYBOOK_STAGE_TYPES, 'campaign_playbook_stage_type'),
                'title' => mb_substr($title, 0, 180),
                'instructions' => $this->nullableSanitizedText($stage['instructions'] ?? ''),
                'required_record_type' => $this->normalizeEnum((string) ($stage['required_record_type'] ?? 'none'), self::CAMPAIGN_PLAYBOOK_REQUIRED_RECORD_TYPES, 'campaign_playbook_required_record_type'),
                'checklist_json' => $this->normalizeStringListJson($stage['checklist'] ?? $stage['checklist_json'] ?? []),
                'metadata_json' => $this->normalizeJsonValue($this->sanitizeFlexibleArray($stage['metadata'] ?? $stage['metadata_json'] ?? [])),
            ];
        }

        usort($normalized, static fn(array $left, array $right): int => (int) $left['stage_order'] <=> (int) $right['stage_order']);
        foreach (array_values($normalized) as $index => $stage) {
            $normalized[$index]['stage_order'] = $index + 1;
        }

        return $normalized;
    }

    private function replaceCampaignPlaybookStages(int $playbookId, array $stages): void
    {
        $this->assertWorkspaceRecord('marketing_campaign_playbooks', $playbookId, $this->workspaceId());
        Database::execute(
            'DELETE FROM marketing_campaign_playbook_stages WHERE workspace_id = ? AND playbook_id = ?',
            [$this->workspaceId(), $playbookId]
        );

        foreach ($stages as $stage) {
            Database::execute(
                "INSERT INTO marketing_campaign_playbook_stages
                 (workspace_id, playbook_id, stage_order, stage_type, title, instructions, required_record_type, checklist_json, metadata_json)
                 VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)",
                [
                    $this->workspaceId(),
                    $playbookId,
                    $stage['stage_order'],
                    $stage['stage_type'],
                    $stage['title'],
                    $stage['instructions'],
                    $stage['required_record_type'],
                    $stage['checklist_json'],
                    $stage['metadata_json'],
                ]
            );
        }
    }

    private function refreshCampaignPlaybookReadiness(int $playbookId): array
    {
        $playbook = $this->getCampaignPlaybook($playbookId);
        if (!$playbook) {
            throw new RuntimeException('Marketing campaign playbook not found.');
        }

        $readiness = $this->calculateCampaignPlaybookReadiness($playbook, (array) ($playbook['stages'] ?? []));
        Database::execute(
            'UPDATE marketing_campaign_playbooks SET readiness_score = ?, missing_requirements_json = ? WHERE workspace_id = ? AND id = ?',
            [
                (int) $readiness['score'],
                $this->normalizeJsonValue($readiness['missing']),
                $this->workspaceId(),
                $playbookId,
            ]
        );

        return $readiness;
    }

    private function calculateCampaignPlaybookReadiness(array $playbook, array $stages): array
    {
        $score = 0;
        $missing = [];
        $requirements = [
            'campaign_goal' => !empty($playbook['campaign_goal']),
            'target_audience' => !empty($playbook['target_audience']),
            'audience_segment' => !empty($playbook['audience_segment_id']),
            'persona' => !empty($playbook['persona_id']),
            'offer' => !empty($playbook['offer_context_item_id']),
            'landing_page' => !empty($playbook['landing_page_id']),
            'channel_plan' => !empty($playbook['channel_plan_json']),
            'success_metrics' => !empty($playbook['success_metrics_json']),
        ];

        foreach ($requirements as $key => $met) {
            if ($met) {
                $score += 9;
            } else {
                $missing[] = $key;
            }
        }

        $stageTypes = array_values(array_unique(array_map(static fn(array $stage): string => (string) ($stage['stage_type'] ?? ''), $stages)));
        foreach (['strategy', 'content', 'conversion', 'distribution', 'sales_handoff'] as $stageType) {
            if (in_array($stageType, $stageTypes, true)) {
                $score += 5;
            } else {
                $missing[] = 'stage_' . $stageType;
            }
        }
        if (count($stages) >= 4) {
            $score += 3;
        } else {
            $missing[] = 'at_least_four_stages';
        }

        return [
            'score' => min(100, $score),
            'missing' => array_values(array_unique($missing)),
        ];
    }

    private function normalizeCampaignPlaybookTemplateKey(string $value): string
    {
        $key = strtolower((string) preg_replace('/[^a-z0-9]+/i', '_', trim($value)));
        return mb_substr(trim($key, '_'), 0, 120);
    }

