    private function buildCampaignLaunchChecklistResult(array $input): array
    {
        $brief = !empty($input['campaign_brief_id']) ? ($this->getCampaignBrief((int) $input['campaign_brief_id']) ?? []) : [];
        $content = !empty($input['content_item_id']) ? ($this->getContentItem((int) $input['content_item_id']) ?? []) : [];
        $landing = !empty($input['landing_page_id']) ? ($this->getLandingPage((int) $input['landing_page_id']) ?? []) : [];
        $distribution = !empty($input['distribution_post_id']) ? ($this->getDistributionPost((int) $input['distribution_post_id']) ?? []) : [];
        $emailRun = !empty($input['email_run_id']) ? ($this->getEmailCampaignRun((int) $input['email_run_id']) ?? []) : [];
        $bundle = !empty($input['channel_export_bundle_id']) ? ($this->getChannelExportBundle((int) $input['channel_export_bundle_id']) ?? []) : [];
        $connector = !empty($input['connector_id']) ? ($this->getChannelConnector((int) $input['connector_id']) ?? []) : [];

        $campaignId = (int) ($input['campaign_id'] ?? $brief['campaign_id'] ?? $content['campaign_id'] ?? $landing['campaign_id'] ?? $emailRun['campaign_id'] ?? 0);
        $audienceSegmentId = (int) ($input['audience_segment_id'] ?? $brief['audience_segment_id'] ?? $landing['audience_segment_id'] ?? $emailRun['audience_segment_id'] ?? 0);
        $contentId = (int) ($input['content_item_id'] ?? 0);
        $checks = [];
        $score = 0;
        $possible = 0;
        $missingRequired = [];
        $warnings = [];
        $nextActions = [];

        $addCheck = function (
            string $key,
            string $label,
            bool $complete,
            bool $required,
            string $href,
            string $recommendation,
            string $sourceType = '',
            ?int $sourceId = null,
            int $weight = 10
        ) use (&$checks, &$score, &$possible, &$missingRequired, &$warnings, &$nextActions): void {
            $possible += $weight;
            if ($complete) {
                $score += $weight;
            } elseif ($required) {
                $missingRequired[] = $key;
                $nextActions[] = ['label' => $label, 'href' => $href, 'reason' => $recommendation];
            } else {
                $warnings[] = $key;
            }

            $checks[] = [
                'key' => $key,
                'label' => $label,
                'status' => $complete ? 'complete' : ($required ? 'blocked' : 'warning'),
                'required' => $required,
                'href' => $href,
                'recommendation' => $recommendation,
                'source_record_type' => $sourceType !== '' ? $sourceType : null,
                'source_record_id' => $sourceId,
                'weight' => $weight,
            ];
        };

        $contentApproved = in_array((string) ($content['status'] ?? ''), ['approved', 'scheduled', 'published'], true);
        $distributionReady = !empty($distribution) && !in_array((string) ($distribution['status'] ?? ''), ['archived'], true);
        $bundleReady = !empty($bundle) && in_array((string) ($bundle['status'] ?? ''), ['draft', 'ready', 'exported'], true);
        $connectorReady = !empty($connector)
            && (string) ($connector['setup_status'] ?? '') === 'ready'
            && (int) ($connector['readiness_score'] ?? 0) >= 90
            && !in_array((string) ($connector['status'] ?? ''), ['blocked', 'archived'], true);
        $emailSafe = empty($emailRun)
            || (empty($emailRun['readiness_warnings_json']) && empty($emailRun['safety_warnings_json']));

        $addCheck('brief_ready', 'Campaign brief connected', !empty($brief), true, 'marketing_briefs.php', 'Connect a campaign brief before launch.', 'campaign_brief', (int) ($input['campaign_brief_id'] ?? 0), 12);
        $addCheck('audience_ready', 'Audience selected', $audienceSegmentId > 0, true, 'marketing_segments.php', 'Connect an audience segment or audience activation before launch.', 'audience_segment', $audienceSegmentId > 0 ? $audienceSegmentId : null, 12);
        $addCheck('landing_ready', 'Landing page connected', !empty($landing), true, 'marketing_landing_pages.php', 'Connect the conversion landing page or plan.', 'landing_page', (int) ($input['landing_page_id'] ?? 0), 10);
        $addCheck('content_approved', 'Launch content approved', !empty($content) && $contentApproved, true, 'marketing_content.php', 'Move launch content to approved, scheduled, or published status.', 'content', $contentId > 0 ? $contentId : null, 12);
        $addCheck('distribution_ready', 'Distribution variant ready', $distributionReady, true, 'marketing_distribution.php', 'Create a distribution variant for manual publishing.', 'distribution_post', (int) ($input['distribution_post_id'] ?? 0), 10);
        $addCheck('tracking_ready', 'UTM tracking ready', $this->campaignLaunchChecklistHasUtm($campaignId, $contentId), true, 'marketing_utm_links.php', 'Create a UTM tracking link for this campaign or content.', 'utm_link', null, 10);
        $addCheck('channel_export_ready', 'Channel export package ready', $bundleReady, true, 'marketing_channel_exports.php', 'Create a channel export bundle for manual publishing.', 'channel_export_bundle', (int) ($input['channel_export_bundle_id'] ?? 0), 10);
        $addCheck('connector_ready', 'Connector readiness reviewed', $connectorReady, true, 'marketing_channel_exports.php', 'Run connector dry-run diagnostics and readiness review.', 'channel_connector', (int) ($input['connector_id'] ?? 0), 10);
        $addCheck('email_safety_ready', 'Email safety reviewed', $emailSafe, !empty($emailRun), 'marketing_email_runs.php', 'Resolve consent, suppression, approval, and export warnings on the email run.', 'email_run', (int) ($input['email_run_id'] ?? 0), 8);
        $addCheck('media_ready', 'Launch media ready', $this->campaignLaunchChecklistMediaReady($content, $landing, $distribution), false, 'marketing_assets.php', 'Attach approved image or video media before public-facing export.', 'media', null, 6);
        $addCheck('owner_ready', 'Launch owner assigned', (int) ($input['owner_user_id'] ?? 0) > 0, false, 'marketing_execution.php', 'Assign a launch owner for accountability.', 'user', (int) ($input['owner_user_id'] ?? 0) ?: null, 4);

        return [
            'score' => $possible > 0 ? (int) round(($score / $possible) * 100) : 0,
            'checks' => $checks,
            'missing_required' => array_values(array_unique($missingRequired)),
            'warnings' => array_values(array_unique($warnings)),
            'next_actions' => array_slice($nextActions, 0, 8),
        ];
    }

    private function campaignLaunchChecklistHasUtm(int $campaignId, int $contentId): bool
    {
        if (!Database::tableExists('marketing_utm_links')) {
            return false;
        }
        $conditions = [];
        $params = [$this->workspaceId()];
        if ($campaignId > 0) {
            $conditions[] = 'campaign_id = ?';
            $params[] = $campaignId;
        }
        if ($contentId > 0) {
            $conditions[] = 'content_item_id = ?';
            $params[] = $contentId;
        }
        if ($conditions === []) {
            return false;
        }

        $row = Database::queryOne(
            "SELECT COUNT(*) AS count FROM marketing_utm_links WHERE workspace_id = ? AND (" . implode(' OR ', $conditions) . ")",
            $params
        );

        return (int) ($row['count'] ?? 0) > 0;
    }

    private function campaignLaunchChecklistMediaReady(array $content, array $landing, array $distribution): bool
    {
        $contentId = (int) ($content['id'] ?? 0);
        if ($contentId > 0 && Database::tableExists('marketing_content_media')) {
            $row = Database::queryOne(
                "SELECT COUNT(*) AS count FROM marketing_content_media WHERE workspace_id = ? AND content_item_id = ?",
                [$this->workspaceId(), $contentId]
            );
            if ((int) ($row['count'] ?? 0) > 0) {
                return true;
            }
        }

        foreach (['hero_media_file_id', 'social_preview_media_file_id', 'cta_media_file_id', 'proof_media_file_id'] as $field) {
            if ((int) ($landing[$field] ?? 0) > 0) {
                return true;
            }
        }

        return (int) ($distribution['asset_id'] ?? 0) > 0;
    }

    private function saveCampaignLaunchChecklistItems(int $checklistId, array $checks, ?int $userId = null): void
    {
        if (!Database::tableExists('marketing_campaign_launch_checklist_items')) {
            return;
        }
        $this->assertWorkspaceRecord('marketing_campaign_launch_checklists', $checklistId, $this->workspaceId());
        Database::execute(
            'DELETE FROM marketing_campaign_launch_checklist_items WHERE workspace_id = ? AND checklist_id = ?',
            [$this->workspaceId(), $checklistId]
        );

        foreach ($checks as $check) {
            $status = $this->normalizeEnum((string) ($check['status'] ?? 'pending'), self::CAMPAIGN_LAUNCH_CHECKLIST_ITEM_STATUSES, 'campaign_launch_checklist_item_status');
            Database::execute(
                "INSERT INTO marketing_campaign_launch_checklist_items
                 (workspace_id, checklist_id, check_key, label, status, is_required, source_record_type,
                  source_record_id, recommendation, metadata_json)
                 VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)",
                [
                    $this->workspaceId(),
                    $checklistId,
                    Security::sanitizeInput((string) ($check['key'] ?? ''), 'string'),
                    mb_substr(Security::sanitizeInput((string) ($check['label'] ?? 'Checklist item'), 'string'), 0, 190),
                    $status,
                    !empty($check['required']) ? 1 : 0,
                    !empty($check['source_record_type']) ? Security::sanitizeInput((string) $check['source_record_type'], 'string') : null,
                    (int) ($check['source_record_id'] ?? 0) > 0 ? (int) $check['source_record_id'] : null,
                    $this->nullableSanitizedText($check['recommendation'] ?? ''),
                    $this->normalizeJsonValue(['weight' => (int) ($check['weight'] ?? 0), 'updated_by' => $userId]),
                ]
            );
        }
    }

    private function campaignPlaybookContentPlan(array $playbook): array
    {
        $plan = (array) ($playbook['default_content_plan_json'] ?? []);
        if ($plan === []) {
            $channels = (array) ($playbook['channel_plan_json'] ?? []);
            $plan = [
                [
                    'title' => (string) ($playbook['name'] ?? 'Campaign') . ' announcement',
                    'content_type' => 'email',
                    'channel' => 'email',
                    'funnel_stage' => 'conversion',
                    'objective' => (string) ($playbook['campaign_goal'] ?? ''),
                ],
                [
                    'title' => (string) ($playbook['name'] ?? 'Campaign') . ' social post',
                    'content_type' => 'social_post',
                    'channel' => 'linkedin',
                    'funnel_stage' => 'awareness',
                    'objective' => (string) ($channels[0] ?? $playbook['campaign_goal'] ?? ''),
                ],
                [
                    'title' => (string) ($playbook['name'] ?? 'Campaign') . ' support copy',
                    'content_type' => 'blog_post',
                    'channel' => 'blog',
                    'funnel_stage' => 'consideration',
                    'objective' => (string) ($channels[1] ?? $playbook['campaign_goal'] ?? ''),
                ],
            ];
        }

        $normalized = [];
        foreach (array_values($plan) as $item) {
            if (!is_array($item)) {
                continue;
            }
            $title = Security::sanitizeInput((string) ($item['title'] ?? ''), 'string');
            if ($title === '') {
                continue;
            }
            $normalized[] = [
                'title' => mb_substr($title, 0, 180),
                'content_type' => $this->normalizeEnum((string) ($item['content_type'] ?? 'social_post'), self::CONTENT_TYPES, 'content_type'),
                'channel' => $this->normalizeEnum((string) ($item['channel'] ?? 'linkedin'), self::CHANNELS, 'channel'),
                'funnel_stage' => $this->normalizeEnum((string) ($item['funnel_stage'] ?? 'awareness'), self::FUNNEL_STAGES, 'funnel_stage'),
                'objective' => $this->nullableSanitizedText($item['objective'] ?? ''),
                'target_audience' => $this->nullableSanitizedText($item['target_audience'] ?? ''),
            ];
        }

        $fallbacks = [
            ['title' => (string) ($playbook['name'] ?? 'Campaign') . ' launch email', 'content_type' => 'email', 'channel' => 'email', 'funnel_stage' => 'conversion'],
            ['title' => (string) ($playbook['name'] ?? 'Campaign') . ' social post', 'content_type' => 'social_post', 'channel' => 'linkedin', 'funnel_stage' => 'awareness'],
            ['title' => (string) ($playbook['name'] ?? 'Campaign') . ' support article', 'content_type' => 'blog_post', 'channel' => 'blog', 'funnel_stage' => 'consideration'],
        ];
        foreach ($fallbacks as $fallback) {
            if (count($normalized) >= 3) {
                break;
            }
            $normalized[] = $fallback + [
                'objective' => (string) ($playbook['campaign_goal'] ?? ''),
                'target_audience' => (string) ($playbook['target_audience'] ?? ''),
            ];
        }

        return array_slice($normalized, 0, 8);
    }

    private function campaignPlaybookDistributionPlan(array $playbook, array $contentPlan): array
    {
        $plan = (array) ($playbook['default_distribution_plan_json'] ?? []);
        if ($plan === []) {
            $plan = array_map(
                static fn(array $item): array => [
                    'channel' => (string) ($item['channel'] ?? 'linkedin'),
                    'checklist' => ['Copy approved', 'Media checked', 'UTM link ready'],
                ],
                $contentPlan
            );
        }

        $normalized = [];
        foreach (array_values($plan) as $item) {
            if (!is_array($item)) {
                continue;
            }
            $normalized[] = [
                'channel' => $this->normalizeEnum((string) ($item['channel'] ?? 'linkedin'), self::CHANNELS, 'channel'),
                'checklist' => $this->sanitizeStringList($item['checklist'] ?? $item['checklist_json'] ?? []),
            ];
        }

        return array_slice($normalized, 0, max(1, count($contentPlan)));
    }

    private function sanitizeStringList(mixed $value): array
    {
        if (is_string($value)) {
            $decoded = json_decode($value, true);
            $value = json_last_error() === JSON_ERROR_NONE ? $decoded : preg_split('/\r\n|\r|\n|,/', $value);
        }
        if (!is_array($value)) {
            return [];
        }

        $items = [];
        foreach ($value as $item) {
            if (!is_scalar($item)) {
                continue;
            }
            $text = Security::sanitizeInput((string) $item, 'string');
            if ($text !== '') {
                $items[] = mb_substr($text, 0, 220);
            }
        }

        return array_values(array_unique($items));
    }

    private function campaignPlaybookMilestoneType(string $stageType): string
    {
        return match ($stageType) {
            'content' => 'review',
            'conversion', 'distribution' => 'publish',
            'sales_handoff' => 'deadline',
            'reporting' => 'deadline',
            default => 'other',
        };
    }

    private function campaignPlaybookQueueType(string $stageType): string
    {
        return match ($stageType) {
            'content' => 'content',
            'reporting' => 'report',
            'strategy', 'conversion', 'distribution' => 'campaign',
            default => 'other',
        };
    }

    private function uniqueMarketingLandingSlug(string $source): string
    {
        $base = strtolower((string) preg_replace('/[^a-z0-9]+/i', '-', trim($source)));
        $base = trim($base, '-') ?: 'campaign-landing';
        $base = mb_substr($base, 0, 80);
        $slug = $base;
        $suffix = 1;
        while (Database::queryOne('SELECT id FROM marketing_landing_pages WHERE workspace_id = ? AND slug = ? LIMIT 1', [$this->workspaceId(), $slug])) {
            $suffix++;
            $slug = mb_substr($base, 0, 72) . '-' . $suffix;
        }

        return $slug;
    }

    private function normalizeLaunchReadinessTemplateData(array $data, bool $forCreate): array
    {
        $workspaceId = $this->workspaceId();
        $normalized = [];
        if ($forCreate || array_key_exists('name', $data)) {
            $name = Security::sanitizeInput((string) ($data['name'] ?? ''), 'string');
            if ($name === '') {
                throw new \InvalidArgumentException('Launch readiness template name is required.');
            }
            $normalized['name'] = mb_substr($name, 0, 180);
        }
        if ($forCreate || array_key_exists('template_key', $data)) {
            $source = trim((string) ($data['template_key'] ?? ($normalized['name'] ?? 'launch_template')));
            $key = strtolower((string) preg_replace('/[^a-z0-9]+/i', '_', $source));
            $key = trim($key, '_') ?: 'launch_template';
            $normalized['template_key'] = mb_substr($key, 0, 120);
        }
        if ($forCreate || array_key_exists('campaign_type', $data)) {
            $normalized['campaign_type'] = $this->normalizeEnum((string) ($data['campaign_type'] ?? 'launch'), self::LAUNCH_CAMPAIGN_TYPES, 'launch_campaign_type');
        }
        foreach ([
            'required_checks_json' => ['required_checks', 'required_checks_json'],
            'recommended_checks_json' => ['recommended_checks', 'recommended_checks_json'],
        ] as $dbField => $inputFields) {
            if ($forCreate || array_key_exists($inputFields[0], $data) || array_key_exists($inputFields[1], $data)) {
                $sourceField = array_key_exists($inputFields[0], $data) ? $inputFields[0] : $inputFields[1];
                $normalized[$dbField] = $this->normalizeStringListJson($data[$sourceField] ?? []);
            }
        }
        if ($forCreate || array_key_exists('metadata_json', $data) || array_key_exists('metadata', $data)) {
            $metadata = $this->sanitizeFlexibleArray($data['metadata'] ?? $data['metadata_json'] ?? []);
            $metadata['manual_first'] = $metadata['manual_first'] ?? true;
            $metadata['external_execution'] = false;
            $normalized['metadata_json'] = $this->normalizeJsonValue($metadata);
        }
        if ($forCreate || array_key_exists('owner_user_id', $data)) {
            $ownerId = (int) ($data['owner_user_id'] ?? 0);
            if ($ownerId > 0) {
                $this->assertWorkspaceUser($ownerId, $workspaceId);
                $normalized['owner_user_id'] = $ownerId;
            } else {
                $normalized['owner_user_id'] = null;
            }
        }
        if ($forCreate) {
            $createdBy = (int) ($data['created_by'] ?? $this->currentUserId());
            $normalized['created_by'] = $createdBy > 0 ? $createdBy : null;
        }

        return $normalized;
    }

    private function normalizeLaunchReadinessReviewData(array $data, bool $forCreate): array
    {
        $workspaceId = $this->workspaceId();
        $normalized = [];
        $linkTables = [
            'campaign_id' => 'campaigns',
            'campaign_brief_id' => 'marketing_campaign_briefs',
            'landing_page_id' => 'marketing_landing_pages',
            'content_item_id' => 'marketing_content_items',
            'distribution_post_id' => 'marketing_distribution_posts',
            'email_run_id' => 'marketing_email_campaign_runs',
            'template_id' => 'marketing_launch_readiness_templates',
        ];

        foreach ($linkTables as $field => $table) {
            if ($forCreate || array_key_exists($field, $data)) {
                $id = (int) ($data[$field] ?? 0);
                if ($id > 0) {
                    $this->assertWorkspaceRecord($table, $id, $workspaceId);
                    $normalized[$field] = $id;
                } else {
                    $normalized[$field] = null;
                }
            }
        }

        if (!empty($normalized['distribution_post_id'])) {
            $post = $this->getDistributionPost((int) $normalized['distribution_post_id']);
            if ($post && empty($normalized['content_item_id'])) {
                $normalized['content_item_id'] = (int) ($post['content_item_id'] ?? 0) ?: null;
            }
        }
        if (!empty($normalized['email_run_id'])) {
            $run = $this->getEmailCampaignRun((int) $normalized['email_run_id']);
            if ($run) {
                if (empty($normalized['campaign_id'])) {
                    $normalized['campaign_id'] = (int) ($run['campaign_id'] ?? 0) ?: null;
                }
                if (empty($normalized['content_item_id'])) {
                    $normalized['content_item_id'] = (int) ($run['content_item_id'] ?? 0) ?: null;
                }
            }
        }
        if (!empty($normalized['content_item_id'])) {
            $content = $this->getContentItem((int) $normalized['content_item_id']);
            if ($content) {
                foreach ([
                    'campaign_id' => 'campaign_id',
                    'campaign_brief_id' => 'campaign_brief_id',
                    'landing_page_id' => 'landing_page_id',
                ] as $target => $source) {
                    if (empty($normalized[$target]) && !empty($content[$source])) {
                        $normalized[$target] = (int) $content[$source];
                    }
                }
            }
        }
        if (!empty($normalized['campaign_brief_id'])) {
            $brief = $this->getCampaignBrief((int) $normalized['campaign_brief_id']);
            if ($brief) {
                if (empty($normalized['campaign_id'])) {
                    $normalized['campaign_id'] = (int) ($brief['campaign_id'] ?? 0) ?: null;
                }
                if (empty($normalized['landing_page_id'])) {
                    $normalized['landing_page_id'] = (int) ($brief['landing_page_id'] ?? 0) ?: null;
                }
            }
        }
        if (!empty($normalized['landing_page_id'])) {
            $landing = $this->getLandingPage((int) $normalized['landing_page_id']);
            if ($landing && empty($normalized['campaign_id'])) {
                $normalized['campaign_id'] = (int) ($landing['campaign_id'] ?? 0) ?: null;
            }
        }

        if ($forCreate || array_key_exists('launch_name', $data)) {
            $name = Security::sanitizeInput((string) ($data['launch_name'] ?? ''), 'string');
            if ($name === '') {
                $name = $this->deriveLaunchName($normalized);
            }
            if ($name === '') {
                throw new \InvalidArgumentException('Launch name is required.');
            }
            $normalized['launch_name'] = mb_substr($name, 0, 180);
        }
        if ($forCreate || array_key_exists('launch_date', $data)) {
            $date = trim((string) ($data['launch_date'] ?? ''));
            $normalized['launch_date'] = $date !== '' ? $this->normalizeDate($date, 'launch date') : null;
        }
        if ($forCreate || array_key_exists('checklist', $data) || array_key_exists('checklist_json', $data)) {
            $normalized['checklist_json'] = $this->normalizeStringListJson($data['checklist'] ?? $data['checklist_json'] ?? []);
        }
        if ($forCreate) {
            $createdBy = (int) ($data['created_by'] ?? $this->currentUserId());
            $normalized['created_by'] = $createdBy > 0 ? $createdBy : null;
        }

        return $normalized;
    }

    private function deriveLaunchName(array $normalized): string
    {
        if (!empty($normalized['campaign_brief_id'])) {
            $brief = $this->getCampaignBrief((int) $normalized['campaign_brief_id']);
            if ($brief && !empty($brief['title'])) {
                return (string) $brief['title'];
            }
        }
        if (!empty($normalized['content_item_id'])) {
            $content = $this->getContentItem((int) $normalized['content_item_id']);
            if ($content && !empty($content['title'])) {
                return (string) $content['title'];
            }
        }
        if (!empty($normalized['landing_page_id'])) {
            $landing = $this->getLandingPage((int) $normalized['landing_page_id']);
            if ($landing && !empty($landing['title'])) {
                return (string) $landing['title'];
            }
        }
        if (!empty($normalized['campaign_id'])) {
            $campaign = Database::queryOne('SELECT name FROM campaigns WHERE workspace_id = ? AND id = ? LIMIT 1', [$this->workspaceId(), (int) $normalized['campaign_id']]);
            if ($campaign && !empty($campaign['name'])) {
                return (string) $campaign['name'];
            }
        }

        return '';
    }

    private function buildLaunchReadinessResult(array $input): array
    {
        $brief = !empty($input['campaign_brief_id']) ? ($this->getCampaignBrief((int) $input['campaign_brief_id']) ?? []) : [];
        $content = !empty($input['content_item_id']) ? ($this->getContentItem((int) $input['content_item_id']) ?? []) : [];
        $landing = !empty($input['landing_page_id']) ? ($this->getLandingPage((int) $input['landing_page_id']) ?? []) : [];
        $distribution = !empty($input['distribution_post_id']) ? ($this->getDistributionPost((int) $input['distribution_post_id']) ?? []) : [];
        $emailRun = !empty($input['email_run_id']) ? ($this->getEmailCampaignRun((int) $input['email_run_id']) ?? []) : [];
        $audienceActivation = $this->findAudienceActivationForLaunch($input, $brief, $content, $landing, $distribution, $emailRun);
        $checklist = $this->decodeJsonLike($input['checklist_json'] ?? []);

        $checks = [];
        $score = 0;
        $blockers = [];
        $warnings = [];
        $add = function (string $key, string $label, bool $ready, bool $required, string $message, int $weight) use (&$checks, &$score, &$blockers, &$warnings): void {
            $checks[] = [
                'key' => $key,
                'label' => $label,
                'status' => $ready ? 'ready' : ($required ? 'blocked' : 'warning'),
                'required' => $required,
                'message' => $message,
                'weight' => $weight,
            ];
            if ($ready) {
                $score += $weight;
            } elseif ($required) {
                $blockers[] = $key;
            } else {
                $warnings[] = $key;
            }
        };

        $audienceReady = !empty($brief['audience_segment_id'])
            || trim((string) ($brief['audience'] ?? '')) !== ''
            || !empty($emailRun['audience_segment_id'])
            || !empty($emailRun['segment_snapshot_id'])
            || (int) ($emailRun['recipient_count'] ?? 0) > 0
            || ($audienceActivation !== [] && !in_array((string) ($audienceActivation['coverage_status'] ?? ''), ['blocked', 'unknown'], true));
        $add('audience_ready', 'Audience selected', $audienceReady, true, $audienceReady ? 'Audience context is present.' : 'Select an audience segment, brief audience, or email recipient plan.', 10);
        if ($audienceActivation !== [] && (string) ($audienceActivation['coverage_status'] ?? '') === 'warning') {
            $warnings[] = 'audience_activation_warning';
        }
        if ($audienceActivation !== [] && (string) ($audienceActivation['coverage_status'] ?? '') === 'blocked') {
            $blockers[] = 'audience_activation_blocked';
        }

        $offerReady = !empty($brief['offer_context_item_id']) || trim((string) ($brief['offer_text'] ?? '')) !== '';
        $add('offer_ready', 'Offer defined', $offerReady, true, $offerReady ? 'The brief has an offer.' : 'Define the offer before launch.', 10);

        $ctaReady = $this->launchHasCta($brief, $content, $landing, $emailRun);
        $add('cta_ready', 'CTA present', $ctaReady, true, $ctaReady ? 'CTA or conversion goal is present.' : 'Add a CTA or conversion goal.', 10);

        $landingReady = $landing !== [];
        $add('landing_page_ready', 'Landing page linked', $landingReady, true, $landingReady ? 'A landing page plan is linked.' : 'Link a landing page plan for the launch.', 10);
        if ($landingReady && !in_array((string) ($landing['status'] ?? 'draft'), ['approved'], true)) {
            $warnings[] = 'landing_page_not_approved';
        }

        $contentReady = $content !== [];
        $add('content_ready', 'Content linked', $contentReady, true, $contentReady ? 'Launch content is linked.' : 'Link the source launch content.', 10);

        $approvalReady = $this->launchContentApprovalReady($content);
        $add('approval_ready', 'Approval complete', $approvalReady, true, $approvalReady ? 'Content has an approved/scheduled/published status or approval.' : 'Move content through review approval before launch.', 10);

        $distributionReady = $distribution !== [];
        $add('distribution_ready', 'Distribution package ready', $distributionReady, true, $distributionReady ? 'A distribution variant is linked.' : 'Create a manual distribution post or export package.', 10);
        if ($distributionReady && in_array((string) ($distribution['status'] ?? ''), ['draft', 'scheduled'], true)) {
            $warnings[] = 'distribution_not_exported';
        }

        $utmReady = $this->launchHasUtmLink($input, $content, $distribution);
        $add('utm_ready', 'UTM tracking exists', $utmReady, true, $utmReady ? 'A UTM link exists for the campaign/content path.' : 'Create a UTM link before manual distribution.', 10);

        $mediaReady = $this->launchMediaReady($content, $landing, $distribution);
        $mediaRequired = $this->launchMediaRequired($content, $landing, $distribution);
        $add('media_ready', 'Media ready for channel', $mediaReady, $mediaRequired, $mediaReady ? 'Required or recommended media is attached.' : 'Attach approved media, hero media, or channel kit media.', 10);

        $emailReady = true;
        if ($this->launchNeedsEmailRun($content, $distribution, $emailRun)) {
            $emailReady = $emailRun !== []
                && !in_array('missing_unsubscribe_text', (array) ($emailRun['readiness_warnings_json'] ?? []), true)
                && !in_array('missing_send_checklist', (array) ($emailRun['readiness_warnings_json'] ?? []), true);
        }
        $add('email_run_ready', 'Email run checklist', $emailReady, !$emailReady, $emailReady ? 'Email launch requirements are clear or not needed.' : 'Prepare email run audience, unsubscribe text, and send checklist.', 5);

        $manualFirstReady = true;
        $add('manual_first_boundary', 'Manual-first boundary', $manualFirstReady, true, 'No external publishing or sending is performed by this review.', 5);

        if ($checklist === []) {
            $warnings[] = 'manual_launch_checklist_missing';
        }
        $score = min(100, $score);

        return [
            'score' => $score,
            'status' => $blockers === [] ? 'ready' : 'blocked',
            'blocking_reasons' => array_values(array_unique($blockers)),
            'warnings' => array_values(array_unique($warnings)),
            'checklist' => $checklist,
            'checks' => $checks,
            'linked_records' => [
                'campaign_id' => $input['campaign_id'] ?? null,
                'campaign_brief_id' => $input['campaign_brief_id'] ?? null,
                'landing_page_id' => $input['landing_page_id'] ?? null,
                'content_item_id' => $input['content_item_id'] ?? null,
                'distribution_post_id' => $input['distribution_post_id'] ?? null,
                'email_run_id' => $input['email_run_id'] ?? null,
                'audience_activation_id' => $audienceActivation['id'] ?? null,
            ],
            'audience_activation' => $audienceActivation,
            'manual_first' => true,
            'external_publish' => false,
            'external_send' => false,
            'evaluated_at' => date('c'),
        ];
    }

    private function findAudienceActivationForLaunch(array $input, array $brief, array $content, array $landing, array $distribution, array $emailRun): array
    {
        if (!Database::tableExists('marketing_audience_activations')) {
            return [];
        }

        $candidates = [];
        foreach ([
            'campaign_id' => $input['campaign_id'] ?? $brief['campaign_id'] ?? $content['campaign_id'] ?? $landing['campaign_id'] ?? $emailRun['campaign_id'] ?? null,
            'campaign_brief_id' => $input['campaign_brief_id'] ?? $content['campaign_brief_id'] ?? null,
            'landing_page_id' => $input['landing_page_id'] ?? $brief['landing_page_id'] ?? $content['landing_page_id'] ?? null,
            'content_item_id' => $input['content_item_id'] ?? $distribution['content_item_id'] ?? $emailRun['content_item_id'] ?? null,
            'distribution_post_id' => $input['distribution_post_id'] ?? null,
            'email_run_id' => $input['email_run_id'] ?? null,
            'audience_segment_id' => $brief['audience_segment_id'] ?? $landing['audience_segment_id'] ?? $emailRun['audience_segment_id'] ?? null,
        ] as $field => $value) {
            $id = (int) ($value ?? 0);
            if ($id > 0) {
                $candidates[$field] = $id;
            }
        }
        if ($candidates === []) {
            return [];
        }

        $clauses = [];
        $params = [$this->workspaceId()];
        foreach ($candidates as $field => $id) {
            $clauses[] = "aa.{$field} = ?";
            $params[] = $id;
        }

        $rows = Database::query(
            "SELECT aa.*, seg.name AS audience_segment_name
             FROM marketing_audience_activations aa
             JOIN marketing_audience_segments seg ON seg.id = aa.audience_segment_id AND seg.workspace_id = aa.workspace_id
             WHERE aa.workspace_id = ?
               AND aa.status <> 'archived'
               AND (" . implode(' OR ', $clauses) . ")
             ORDER BY
                CASE aa.coverage_status WHEN 'ready' THEN 0 WHEN 'warning' THEN 1 WHEN 'unknown' THEN 2 ELSE 3 END ASC,
                aa.fit_score DESC,
                aa.updated_at DESC
             LIMIT 1",
            $params
        );

        return !empty($rows[0]) ? $this->hydrateAudienceActivationRow($rows[0]) : [];
    }

    private function normalizeLaunchControlData(array $data, bool $forCreate): array
    {
        $workspaceId = $this->workspaceId();
        $normalized = [];
        $linkTables = [
            'launch_readiness_review_id' => 'marketing_launch_readiness_reviews',
            'campaign_id' => 'campaigns',
            'campaign_brief_id' => 'marketing_campaign_briefs',
            'landing_page_id' => 'marketing_landing_pages',
            'content_item_id' => 'marketing_content_items',
            'distribution_post_id' => 'marketing_distribution_posts',
            'email_run_id' => 'marketing_email_campaign_runs',
            'audience_activation_id' => 'marketing_audience_activations',
        ];
        foreach ($linkTables as $field => $table) {
            if ($forCreate || array_key_exists($field, $data)) {
                $id = (int) ($data[$field] ?? 0);
                if ($id > 0) {
                    $this->assertWorkspaceRecord($table, $id, $workspaceId);
                    $normalized[$field] = $id;
                } else {
                    $normalized[$field] = null;
                }
            }
        }

        if (!empty($normalized['launch_readiness_review_id'])) {
            $review = $this->getLaunchReadinessReview((int) $normalized['launch_readiness_review_id']);
            if ($review) {
                foreach ([
                    'campaign_id',
                    'campaign_brief_id',
                    'landing_page_id',
                    'content_item_id',
                    'distribution_post_id',
                    'email_run_id',
                ] as $field) {
                    if (empty($normalized[$field]) && !empty($review[$field])) {
                        $normalized[$field] = (int) $review[$field];
                    }
                }
                if (empty($normalized['audience_activation_id']) && !empty($review['result_json']['audience_activation']['id'])) {
                    $normalized['audience_activation_id'] = (int) $review['result_json']['audience_activation']['id'];
                }
                if (empty($data['launch_name']) && !empty($review['launch_name'])) {
                    $data['launch_name'] = (string) $review['launch_name'];
                }
                if (empty($data['launch_date']) && !empty($review['launch_date'])) {
                    $data['launch_date'] = (string) $review['launch_date'];
                }
            }
        }
        if (!empty($normalized['distribution_post_id'])) {
            $post = $this->getDistributionPost((int) $normalized['distribution_post_id']);
            if ($post && empty($normalized['content_item_id'])) {
                $normalized['content_item_id'] = (int) ($post['content_item_id'] ?? 0) ?: null;
            }
        }
        if (!empty($normalized['email_run_id'])) {
            $run = $this->getEmailCampaignRun((int) $normalized['email_run_id']);
            if ($run) {
                if (empty($normalized['campaign_id'])) {
                    $normalized['campaign_id'] = (int) ($run['campaign_id'] ?? 0) ?: null;
                }
                if (empty($normalized['content_item_id'])) {
                    $normalized['content_item_id'] = (int) ($run['content_item_id'] ?? 0) ?: null;
                }
            }
        }
        if (!empty($normalized['content_item_id'])) {
            $content = $this->getContentItem((int) $normalized['content_item_id']);
            if ($content) {
                foreach ([
                    'campaign_id' => 'campaign_id',
                    'campaign_brief_id' => 'campaign_brief_id',
                    'landing_page_id' => 'landing_page_id',
                ] as $target => $source) {
                    if (empty($normalized[$target]) && !empty($content[$source])) {
                        $normalized[$target] = (int) $content[$source];
                    }
                }
            }
        }
        if (!empty($normalized['campaign_brief_id'])) {
            $brief = $this->getCampaignBrief((int) $normalized['campaign_brief_id']);
            if ($brief) {
                if (empty($normalized['campaign_id'])) {
                    $normalized['campaign_id'] = (int) ($brief['campaign_id'] ?? 0) ?: null;
                }
                if (empty($normalized['landing_page_id'])) {
                    $normalized['landing_page_id'] = (int) ($brief['landing_page_id'] ?? 0) ?: null;
                }
            }
        }
        if (!empty($normalized['landing_page_id'])) {
            $landing = $this->getLandingPage((int) $normalized['landing_page_id']);
            if ($landing && empty($normalized['campaign_id'])) {
                $normalized['campaign_id'] = (int) ($landing['campaign_id'] ?? 0) ?: null;
            }
        }

        if ($forCreate || array_key_exists('launch_name', $data)) {
            $name = Security::sanitizeInput((string) ($data['launch_name'] ?? ''), 'string');
            if ($name === '') {
                $name = $this->deriveLaunchName($normalized);
            }
            if ($name === '') {
                throw new \InvalidArgumentException('Launch control name is required.');
            }
            $normalized['launch_name'] = mb_substr($name, 0, 180);
        }
        if ($forCreate || array_key_exists('launch_date', $data)) {
            $date = trim((string) ($data['launch_date'] ?? ''));
            $normalized['launch_date'] = $date !== '' ? $this->normalizeDate($date, 'launch date') : null;
        }
        if ($forCreate || array_key_exists('owner_user_id', $data)) {
            $ownerId = (int) ($data['owner_user_id'] ?? 0);
            if ($ownerId > 0) {
                $this->assertWorkspaceUser($ownerId, $workspaceId);
                $normalized['owner_user_id'] = $ownerId;
            } else {
                $normalized['owner_user_id'] = null;
            }
        }
        if ($forCreate || array_key_exists('metadata_json', $data) || array_key_exists('metadata', $data)) {
            $metadata = $this->sanitizeFlexibleArray($data['metadata'] ?? $data['metadata_json'] ?? []);
            $metadata['manual_first_boundary'] = true;
            $metadata['external_publish'] = false;
            $metadata['external_send'] = false;
            $normalized['metadata_json'] = $this->normalizeJsonValue($metadata);
        }
        if ($forCreate) {
            $createdBy = (int) ($data['created_by'] ?? $this->currentUserId()) ?: null;
            if (($createdBy ?? 0) > 0) {
                $this->assertWorkspaceUser((int) $createdBy, $workspaceId);
            }
            $normalized['created_by'] = $createdBy;
        }

        return $normalized;
    }

    private function buildLaunchControlResult(array $input): array
    {
        $review = !empty($input['launch_readiness_review_id']) ? ($this->getLaunchReadinessReview((int) $input['launch_readiness_review_id']) ?? []) : [];
        $brief = !empty($input['campaign_brief_id']) ? ($this->getCampaignBrief((int) $input['campaign_brief_id']) ?? []) : [];
        $content = !empty($input['content_item_id']) ? ($this->getContentItem((int) $input['content_item_id']) ?? []) : [];
        $landing = !empty($input['landing_page_id']) ? ($this->getLandingPage((int) $input['landing_page_id']) ?? []) : [];
        $distribution = !empty($input['distribution_post_id']) ? ($this->getDistributionPost((int) $input['distribution_post_id']) ?? []) : [];
        $emailRun = !empty($input['email_run_id']) ? ($this->getEmailCampaignRun((int) $input['email_run_id']) ?? []) : [];
        $audienceActivation = !empty($input['audience_activation_id'])
            ? ($this->getAudienceActivation((int) $input['audience_activation_id']) ?? [])
            : $this->findAudienceActivationForLaunch($input, $brief, $content, $landing, $distribution, $emailRun);

        $checks = [];
        $score = 0;
        $blockers = [];
        $warnings = [];
        $add = function (string $key, string $label, bool $ready, bool $required, string $message, int $weight) use (&$checks, &$score, &$blockers, &$warnings): void {
            $checks[] = [
                'key' => $key,
                'label' => $label,
                'status' => $ready ? 'ready' : ($required ? 'blocked' : 'warning'),
                'required' => $required,
                'message' => $message,
                'weight' => $weight,
            ];
            if ($ready) {
                $score += $weight;
            } elseif ($required) {
                $blockers[] = $key;
            } else {
                $warnings[] = $key;
            }
        };

        $reviewReady = $review !== [] && in_array((string) ($review['status'] ?? ''), ['ready', 'approved'], true);
        $add('launch_readiness_ready', 'Launch readiness review', $reviewReady, true, $reviewReady ? 'Readiness review is ready or approved.' : 'Run launch readiness and resolve blockers first.', 12);

        $activationReady = $audienceActivation !== [] && !in_array((string) ($audienceActivation['coverage_status'] ?? ''), ['blocked', 'unknown'], true);
        $audienceReady = $activationReady
            || !empty($brief['audience_segment_id'])
            || trim((string) ($brief['audience'] ?? '')) !== ''
            || !empty($emailRun['audience_segment_id'])
            || (int) ($emailRun['recipient_count'] ?? 0) > 0;
        $add('audience_ready', 'Audience activated', $audienceReady, true, $audienceReady ? 'Audience is selected or activated.' : 'Connect an activated segment before launch.', 10);
        if ($audienceActivation !== [] && (string) ($audienceActivation['coverage_status'] ?? '') === 'warning') {
            $warnings[] = 'audience_activation_warning';
        }

        $offerReady = !empty($brief['offer_context_item_id']) || trim((string) ($brief['offer_text'] ?? '')) !== '';
        $add('offer_ready', 'Offer ready', $offerReady, true, $offerReady ? 'Offer context is present.' : 'Define the offer before launch.', 10);

        $landingReady = $landing !== [];
        $add('landing_page_ready', 'Landing page ready', $landingReady, true, $landingReady ? 'Landing page is linked.' : 'Link a landing page plan.', 10);
        $formReady = $landing !== [] && (!empty($landing['form_id']) || !empty($landing['conversion_goal_id']) || !empty($landing['conversion_goal']));
        $add('form_or_goal_ready', 'Form or conversion goal', $formReady, true, $formReady ? 'Lead capture or conversion goal is configured.' : 'Connect a form or conversion goal.', 10);

        $contentReady = $content !== [] && in_array((string) ($content['status'] ?? ''), ['approved', 'scheduled', 'published'], true);
        $add('content_prepared', 'Content prepared', $contentReady, true, $contentReady ? 'Launch content is approved or scheduled.' : 'Prepare and approve launch content.', 10);

        $approvalReady = $this->launchContentApprovalReady($content);
        $add('approval_complete', 'Approval complete', $approvalReady, true, $approvalReady ? 'Content approval is complete.' : 'Complete content approval.', 10);

        $distributionReady = $distribution !== [] && !in_array((string) ($distribution['status'] ?? ''), ['cancelled'], true);
        $add('distribution_planned', 'Distribution planned', $distributionReady, true, $distributionReady ? 'Manual distribution package is linked.' : 'Create a manual distribution or export package.', 10);

        $utmReady = $this->launchHasUtmLink($input, $content, $distribution);
        $add('tracking_ready', 'UTM tracking ready', $utmReady, true, $utmReady ? 'UTM tracking exists.' : 'Create UTM tracking before manual launch.', 10);

        $ownerReady = !empty($input['owner_user_id']);
        $add('launch_owner_confirmed', 'Launch owner confirmed', $ownerReady, false, $ownerReady ? 'Launch owner is assigned.' : 'Assign a launch owner for accountability.', 8);

        $add('manual_first_boundary', 'Manual-first boundary', true, true, 'Launch control records status only; no external publishing or sending happens here.', 10);

        foreach ((array) ($review['blocking_reasons_json'] ?? []) as $blocker) {
            if (!in_array((string) $blocker, ['audience_ready'], true)) {
                $blockers[] = 'readiness_' . (string) $blocker;
            }
        }
        foreach ((array) ($review['warnings_json'] ?? []) as $warning) {
            $warnings[] = 'readiness_' . (string) $warning;
        }
        $score = min(100, $score);

        return [
            'score' => $score,
            'status' => $blockers === [] ? 'ready' : 'blocked',
            'checklist' => $checks,
            'blockers' => array_values(array_unique($blockers)),
            'warnings' => array_values(array_unique($warnings)),
            'linked_records' => [
                'launch_readiness_review_id' => $input['launch_readiness_review_id'] ?? null,
                'campaign_id' => $input['campaign_id'] ?? null,
                'campaign_brief_id' => $input['campaign_brief_id'] ?? null,
                'landing_page_id' => $input['landing_page_id'] ?? null,
                'content_item_id' => $input['content_item_id'] ?? null,
                'distribution_post_id' => $input['distribution_post_id'] ?? null,
                'email_run_id' => $input['email_run_id'] ?? null,
                'audience_activation_id' => $audienceActivation['id'] ?? null,
            ],
            'audience_activation' => $audienceActivation,
            'manual_first' => true,
            'external_publish' => false,
            'external_send' => false,
            'prepared_at' => date('c'),
        ];
    }

    private function hydrateLaunchControlRow(array $row): array
    {
        $row = $this->hydrateJsonFields($row, ['checklist_json', 'blocker_json', 'warning_json', 'manual_launch_log_json', 'metadata_json', 'launch_control_json']);
        $row['readiness_score'] = (int) ($row['readiness_score'] ?? 0);

        return $row;
    }

    private function syncLaunchControlBriefStatus(int $briefId, string $status, array $result): void
    {
        if ($briefId <= 0 || !Database::columnExists('marketing_campaign_briefs', 'launch_control_status')) {
            return;
        }

        Database::execute(
            'UPDATE marketing_campaign_briefs
             SET launch_control_status = ?, launch_control_json = ?
             WHERE workspace_id = ? AND id = ?',
            [
                $status,
                $this->normalizeJsonValue($result),
                $this->workspaceId(),
                $briefId,
            ]
        );
    }

    private function buildGuidedMarketingWorkflowState(string $workflowKey, array $definition): array
    {
        $steps = [];
        foreach ((array) ($definition['steps'] ?? []) as $step) {
            $ready = $this->guidedMarketingWorkflowStepReady((string) $step['key']);
            $steps[] = [
                'key' => (string) $step['key'],
                'label' => (string) $step['label'],
                'href' => (string) $step['href'],
                'required' => (bool) ($step['required'] ?? false),
                'description' => (string) ($step['description'] ?? ''),
                'status' => $ready ? 'ready' : ((bool) ($step['required'] ?? false) ? 'blocked' : 'missing'),
            ];
        }

        $total = max(count($steps), 1);
        $readyCount = count(array_filter($steps, static fn(array $step): bool => (string) $step['status'] === 'ready'));
        $missingRequired = array_values(array_filter($steps, static fn(array $step): bool => (bool) ($step['required'] ?? false) && (string) $step['status'] !== 'ready'));
        $currentStep = null;
        foreach ($steps as $step) {
            if ((string) $step['status'] !== 'ready') {
                $currentStep = $step;
                break;
            }
        }
        $progress = (int) floor(($readyCount / $total) * 100);
        $status = 'not_started';
        if ($progress >= 100) {
            $status = 'ready';
        } elseif ($readyCount > 0 && $missingRequired !== []) {
            $status = 'blocked';
        } elseif ($readyCount > 0) {
            $status = 'in_progress';
        }

        $recommendation = $currentStep !== null
            ? [
                'label' => 'Next: ' . (string) $currentStep['label'],
                'href' => (string) $currentStep['href'],
                'step_key' => (string) $currentStep['key'],
                'message' => (string) $currentStep['description'],
            ]
            : [
                'label' => 'Workflow ready',
                'href' => (string) ($definition['primary_href'] ?? 'marketing_guided_workflows.php'),
                'step_key' => 'ready',
                'message' => 'This workflow has enough inputs to move forward.',
            ];

        return [
            'workflow_key' => $workflowKey,
            'title' => (string) ($definition['title'] ?? $workflowKey),
            'description' => (string) ($definition['description'] ?? ''),
            'primary_href' => (string) ($definition['primary_href'] ?? 'marketing_guided_workflows.php'),
            'status' => $status,
            'current_step_key' => $currentStep['key'] ?? null,
            'progress_score' => $progress,
            'steps' => $steps,
            'recommendation' => $recommendation,
            'missing_requirements' => array_values(array_map(
                static fn(array $step): array => [
                    'key' => (string) $step['key'],
                    'label' => (string) $step['label'],
                    'href' => (string) $step['href'],
                    'message' => (string) $step['description'],
                ],
                $missingRequired
            )),
            'quick_links' => array_values(array_map(
                static fn(array $step): array => [
                    'label' => (string) $step['label'],
                    'href' => (string) $step['href'],
                    'status' => (string) $step['status'],
                ],
                $steps
            )),
        ];
    }

    private function guidedMarketingWorkflowStepReady(string $stepKey): bool
    {
        return match ($stepKey) {
            'context_ready' => $this->workflowCount('marketing_brand_profiles') > 0
                && $this->workflowCount('marketing_personas') > 0
                && $this->workflowCount('marketing_context_items', "item_type IN ('offer','proof_point','content_pillar','default_cta')") > 0,
            'audience_defined' => $this->workflowCount('marketing_audience_segments', "status = 'active'") > 0,
            'brief_ready' => $this->workflowCount('marketing_campaign_briefs', $this->workflowActiveCondition('marketing_campaign_briefs')) > 0,
            'landing_ready' => $this->workflowCount('marketing_landing_pages', $this->workflowActiveCondition('marketing_landing_pages')) > 0,
            'content_ready' => $this->workflowCount('marketing_content_items', "status IN ('approved','scheduled','published')") > 0,
            'audience_activated' => $this->workflowCount('marketing_audience_activations', "status IN ('ready','active','completed') AND coverage_status <> 'blocked'") > 0,
            'readiness_ready' => $this->workflowCount('marketing_launch_readiness_reviews', "status IN ('ready','approved')") > 0,
            'launch_control_ready' => $this->workflowCount('marketing_launch_control_records', "status IN ('ready','launched_manual','completed')") > 0,
            'content_exists' => $this->workflowCount('marketing_content_items', $this->workflowActiveCondition('marketing_content_items')) > 0,
            'media_available' => $this->workflowCount('marketing_media_files') > 0 || $this->workflowCount('marketing_assets') > 0,
            'calendar_planned' => $this->workflowCount('marketing_calendar_milestones', $this->workflowActiveCondition('marketing_calendar_milestones')) > 0,
            'approval_started' => $this->workflowCount('marketing_content_approvals') > 0
                || $this->workflowCount('marketing_content_items', "status IN ('approved','scheduled','published')") > 0,
            'quality_checked' => $this->workflowCount('marketing_ai_quality_checks') > 0,
            'production_queue_ready' => $this->workflowCount('marketing_planning_queue_items', $this->workflowActiveCondition('marketing_planning_queue_items')) > 0
                || $this->workflowCount('marketing_content_production_events') > 0,
            'landing_exists' => $this->workflowCount('marketing_landing_pages', $this->workflowActiveCondition('marketing_landing_pages')) > 0,
            'form_connected' => $this->workflowCount('forms') > 0,
            'conversion_goal_ready' => $this->workflowCount('marketing_conversion_goals', $this->workflowActiveCondition('marketing_conversion_goals')) > 0,
            'seo_ready' => $this->workflowCount('marketing_seo_topics', $this->workflowActiveCondition('marketing_seo_topics')) > 0,
            'visual_ready' => $this->workflowCount('marketing_media_files', "media_type IN ('image','video','logo','thumbnail','banner')") > 0,
            'preview_ready' => $this->workflowCount('marketing_landing_page_publications') > 0,
            'distribution_exists' => $this->workflowCount('marketing_distribution_posts', $this->workflowActiveCondition('marketing_distribution_posts')) > 0,
            'utm_ready' => $this->workflowCount('marketing_utm_links') > 0,
            'channel_export_ready' => $this->workflowCount('marketing_channel_export_bundles', $this->workflowActiveCondition('marketing_channel_export_bundles')) > 0,
            'media_kit_ready' => $this->workflowCount('marketing_channel_media_kits') > 0
                || $this->workflowCount('marketing_media_files', "approval_status = 'approved'") > 0,
            'execution_queue_ready' => $this->workflowCount('marketing_execution_queue') > 0,
            'email_run_ready' => $this->workflowCount('marketing_email_campaign_runs', "status IN ('ready','exported')") > 0
                || $this->workflowCount('marketing_email_campaign_runs') > 0,
            'email_unsubscribe_ready' => $this->workflowCount('marketing_email_campaign_runs', "COALESCE(unsubscribe_text, '') <> '' OR COALESCE(suppression_notes, '') <> ''") > 0,
            'email_export_bundle_ready' => $this->workflowCount('marketing_email_campaign_runs', "export_bundle_json IS NOT NULL OR csv_export_json IS NOT NULL OR status = 'exported'") > 0,
            'review_queue_ready' => $this->workflowCount('marketing_content_approvals', "status IN ('pending','approved','rejected')") > 0
                || $this->workflowCount('marketing_content_items', "status IN ('review','approved','scheduled','published')") > 0,
            'content_version_ready' => $this->workflowCount('marketing_content_versions') > 0,
            'comments_available' => $this->workflowCount('marketing_content_comments') > 0,
            'approval_complete' => $this->workflowCount('marketing_content_approvals', "status = 'approved'") > 0
                || $this->workflowCount('marketing_content_items', "status IN ('approved','scheduled','published')") > 0,
            'analytics_snapshot_ready' => $this->workflowCount('marketing_analytics_snapshots') > 0,
            'tracking_signal_ready' => $this->workflowCount('marketing_tracking_events') > 0
                || $this->workflowCount('marketing_landing_page_views') > 0
                || $this->workflowCount('marketing_cta_clicks') > 0,
            'attribution_ready' => $this->workflowCount('marketing_attribution_summaries') > 0
                || $this->workflowCount('marketing_attribution_touchpoints') > 0,
            'reports_ready' => $this->workflowCount('marketing_report_exports') > 0
                || $this->workflowCount('marketing_scheduled_report_drafts') > 0,
            'handoff_feedback_ready' => $this->workflowCount('marketing_lead_handoffs') > 0
                || $this->workflowCount('marketing_handoff_feedback_events') > 0,
            default => false,
        };
    }

    private function workflowCount(string $table, string $condition = '1=1'): int
    {
        if (!Database::tableExists($table)) {
            return 0;
        }

        return $this->countRows($table, $condition);
    }

    private function workflowActiveCondition(string $table): string
    {
        return Database::columnExists($table, 'status') ? "status <> 'archived'" : '1=1';
    }

    private function getGuidedMarketingWorkflowRow(string $workflowKey): ?array
    {
        if (!Database::tableExists('marketing_guided_workflows')) {
            return null;
        }

        $row = Database::queryOne(
            'SELECT * FROM marketing_guided_workflows WHERE workspace_id = ? AND workflow_key = ? LIMIT 1',
            [$this->workspaceId(), $workflowKey]
        );

        return $row ? $this->hydrateGuidedMarketingWorkflowRow($row) : null;
    }

    private function upsertGuidedMarketingWorkflow(array $state, ?int $userId = null): array
    {
        $saved = $this->getGuidedMarketingWorkflowRow((string) $state['workflow_key']);
        $status = (string) $state['status'];
        if ($saved !== null && in_array((string) ($saved['status'] ?? ''), ['completed', 'dismissed', 'archived'], true)) {
            $status = (string) $saved['status'];
        }
        $userId = $userId ?? $this->currentUserId();
        $userId = ($userId ?? 0) > 0 ? (int) $userId : null;
        if ($userId !== null) {
            $this->assertWorkspaceUser($userId, $this->workspaceId());
        }

        if ($saved === null) {
            Database::execute(
                "INSERT INTO marketing_guided_workflows
                 (workspace_id, uuid, workflow_key, title, status, current_step_key, progress_score,
                  step_state_json, recommendation_json, missing_requirements_json, quick_links_json,
                  refreshed_by, refreshed_at, created_by)
                 VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, NOW(), ?)",
                [
                    $this->workspaceId(),
                    $this->generateUuid(),
                    (string) $state['workflow_key'],
                    (string) $state['title'],
                    $status,
                    $state['current_step_key'] ?? null,
                    (int) $state['progress_score'],
                    $this->normalizeJsonValue($state['steps']),
                    $this->normalizeJsonValue($state['recommendation']),
                    $this->normalizeJsonValue($state['missing_requirements']),
                    $this->normalizeJsonValue($state['quick_links']),
                    $userId,
                    $userId,
                ]
            );
        } else {
            Database::execute(
                "UPDATE marketing_guided_workflows
                 SET title = ?,
                     status = ?,
                     current_step_key = ?,
                     progress_score = ?,
                     step_state_json = ?,
                     recommendation_json = ?,
                     missing_requirements_json = ?,
                     quick_links_json = ?,
                     refreshed_by = ?,
                     refreshed_at = NOW()
                 WHERE workspace_id = ? AND id = ?",
                [
                    (string) $state['title'],
                    $status,
                    $state['current_step_key'] ?? null,
                    (int) $state['progress_score'],
                    $this->normalizeJsonValue($state['steps']),
                    $this->normalizeJsonValue($state['recommendation']),
                    $this->normalizeJsonValue($state['missing_requirements']),
                    $this->normalizeJsonValue($state['quick_links']),
                    $userId,
                    $this->workspaceId(),
                    (int) $saved['id'],
                ]
            );
        }

        return $this->getGuidedMarketingWorkflowRow((string) $state['workflow_key']) ?? $state;
    }

    private function hydrateGuidedMarketingWorkflowRow(array $row): array
    {
        $row = $this->hydrateJsonFields($row, ['step_state_json', 'recommendation_json', 'missing_requirements_json', 'quick_links_json']);
        $row['progress_score'] = (int) ($row['progress_score'] ?? 0);
        $row['steps'] = (array) ($row['step_state_json'] ?? []);
        $row['recommendation'] = (array) ($row['recommendation_json'] ?? []);
        $row['missing_requirements'] = (array) ($row['missing_requirements_json'] ?? []);
        $row['quick_links'] = (array) ($row['quick_links_json'] ?? []);

        return $row;
    }

    private function recordGuidedWorkflowEvent(int $workflowId, string $eventType, string $note, ?int $userId = null): void
    {
        if ($workflowId <= 0 || !Database::tableExists('marketing_guided_workflow_events')) {
            return;
        }

        Database::execute(
            "INSERT INTO marketing_guided_workflow_events
             (workspace_id, workflow_id, event_type, event_note, metadata_json, created_by)
             VALUES (?, ?, ?, ?, ?, ?)",
            [
                $this->workspaceId(),
                $workflowId,
                mb_substr(Security::sanitizeInput($eventType, 'string'), 0, 80),
                Security::sanitizeInput($note, 'string'),
                $this->normalizeJsonValue(['manual_first' => true, 'external_publish' => false, 'external_send' => false]),
                ($userId ?? 0) > 0 ? (int) $userId : null,
            ]
        );
    }

    private function defaultMarketingTaskHubPreferences(): array
    {
        return [
            'default_queue' => 'my_work',
            'include_team_items' => 0,
            'filters_json' => [],
            'sort_json' => ['due' => 'ascending'],
        ];
    }

    private function listTaskHubDueContent(?int $ownerUserId, int $limit): array
    {
        if (!Database::tableExists('marketing_content_items')) {
            return [];
        }

        $limit = min(max($limit, 1), 50);
        $where = ['m.workspace_id = ?', "m.status <> 'archived'", "((m.production_due_at IS NOT NULL AND m.production_due_at <= DATE_ADD(NOW(), INTERVAL 7 DAY)) OR (m.scheduled_at IS NOT NULL AND m.scheduled_at <= DATE_ADD(NOW(), INTERVAL 7 DAY)))"];
        $params = [$this->workspaceId()];
        if (($ownerUserId ?? 0) > 0) {
            $where[] = 'm.owner_user_id = ?';
            $params[] = (int) $ownerUserId;
        }

        return array_map(
            fn(array $row): array => $this->hydrateJsonFields($row, ['required_context_warnings_json', 'approval_checklist_json']),
            Database::query(
                "SELECT m.id, m.title, m.status, m.channel, m.content_type, m.production_stage, m.production_due_at,
                        m.scheduled_at, m.next_action, m.dependency_status, m.blocked_reason,
                        m.required_context_warnings_json, m.approval_checklist_json,
                        owner.email AS owner_email
                 FROM marketing_content_items m
                 LEFT JOIN users owner ON owner.id = m.owner_user_id
                 WHERE " . implode(' AND ', $where) . "
                 ORDER BY
                    CASE WHEN m.production_due_at IS NULL THEN 1 ELSE 0 END ASC,
                    m.production_due_at ASC,
                    m.scheduled_at ASC,
                    m.updated_at DESC
                 LIMIT {$limit}",
                $params
            )
        );
    }

    private function listTaskHubActionLog(int $limit): array
    {
        if (!Database::tableExists('marketing_task_hub_action_log')) {
            return [];
        }

        $limit = min(max($limit, 1), 50);

        return array_map(
            fn(array $row): array => $this->hydrateJsonFields($row, ['old_state_json', 'new_state_json']),
            Database::query(
                "SELECT a.*, creator.email AS created_by_email
                 FROM marketing_task_hub_action_log a
                 LEFT JOIN users creator ON creator.id = a.created_by
                 WHERE a.workspace_id = ?
                 ORDER BY a.created_at DESC
                 LIMIT {$limit}",
                [$this->workspaceId()]
            )
        );
    }

    private function normalizeTaskHubItemType(string $itemType): string
    {
        $itemType = Security::sanitizeInput($itemType, 'string');
        $allowed = ['content', 'approval', 'calendar', 'launch_control', 'guided_workflow', 'planning_queue'];
        if (!in_array($itemType, $allowed, true)) {
            throw new \InvalidArgumentException('Invalid task hub item type.');
        }

        return $itemType;
    }

    private function assertTaskHubItemBelongsToWorkspace(string $itemType, int $itemId): void
    {
        $table = match ($itemType) {
            'content' => 'marketing_content_items',
            'approval' => 'marketing_content_approvals',
            'calendar' => 'marketing_calendar_milestones',
            'launch_control' => 'marketing_launch_control_records',
            'guided_workflow' => 'marketing_guided_workflows',
            'planning_queue' => 'marketing_planning_queue_items',
            default => '',
        };
        if ($table === '' || !Database::tableExists($table)) {
            throw new RuntimeException('Task Hub item type is unavailable.');
        }
        $this->assertWorkspaceRecord($table, $itemId, $this->workspaceId());
    }

    private function launchHasCta(array $brief, array $content, array $landing, array $emailRun): bool
    {
        if (trim((string) ($emailRun['cta_label'] ?? '')) !== '' && trim((string) ($emailRun['cta_url'] ?? '')) !== '') {
            return true;
        }
        if (!empty($landing['conversion_goal']) || !empty($landing['conversion_goal_id']) || !empty($landing['cta_blocks_json']) || !empty($landing['cta_variants_json'])) {
            return true;
        }
        $draft = strtolower((string) ($content['draft_body'] ?? ''));
        if (str_contains($draft, 'call to action') || str_contains($draft, 'book') || str_contains($draft, 'sign up') || str_contains($draft, 'learn more')) {
            return true;
        }
        $message = strtolower((string) ($brief['key_message'] ?? ''));
        return str_contains($message, 'book') || str_contains($message, 'sign up') || str_contains($message, 'learn more');
    }

    private function launchContentApprovalReady(array $content): bool
    {
        if ($content === []) {
            return false;
        }
        if (in_array((string) ($content['status'] ?? ''), ['approved', 'scheduled', 'published'], true)) {
            return true;
        }
        if (!Database::tableExists('marketing_content_approvals')) {
            return false;
        }
        $row = Database::queryOne(
            "SELECT id FROM marketing_content_approvals
             WHERE workspace_id = ? AND content_item_id = ? AND status = 'approved'
             LIMIT 1",
            [$this->workspaceId(), (int) ($content['id'] ?? 0)]
        );

        return (bool) $row;
    }

    private function launchHasUtmLink(array $input, array $content, array $distribution): bool
    {
        if (!Database::tableExists('marketing_utm_links')) {
            return false;
        }
        $campaignId = (int) ($input['campaign_id'] ?? $content['campaign_id'] ?? 0);
        $contentId = (int) ($input['content_item_id'] ?? $content['id'] ?? $distribution['content_item_id'] ?? 0);
        if ($campaignId <= 0 && $contentId <= 0) {
            return false;
        }
        $where = ['workspace_id = ?'];
        $params = [$this->workspaceId()];
        if ($campaignId > 0 && $contentId > 0) {
            $where[] = '(campaign_id = ? OR content_item_id = ?)';
            $params[] = $campaignId;
            $params[] = $contentId;
        } elseif ($campaignId > 0) {
            $where[] = 'campaign_id = ?';
            $params[] = $campaignId;
        } else {
            $where[] = 'content_item_id = ?';
            $params[] = $contentId;
        }

        $row = Database::queryOne('SELECT id FROM marketing_utm_links WHERE ' . implode(' AND ', $where) . ' LIMIT 1', $params);

        return (bool) $row;
    }

    private function launchMediaRequired(array $content, array $landing, array $distribution): bool
    {
        $channel = (string) ($distribution['channel'] ?? $content['channel'] ?? '');
        if (in_array($channel, ['instagram', 'facebook', 'linkedin', 'x', 'ads', 'youtube', 'website'], true)) {
            return true;
        }
        return $landing !== [] && empty($landing['hero_media_file_id']);
    }

    private function launchMediaReady(array $content, array $landing, array $distribution): bool
    {
        if (!empty($landing['hero_media_file_id']) || !empty($landing['social_preview_media_file_id']) || !empty($landing['cta_media_file_id'])) {
            return true;
        }
        $contentId = (int) ($content['id'] ?? $distribution['content_item_id'] ?? 0);
        if ($contentId > 0 && Database::tableExists('marketing_content_media')) {
            $row = Database::queryOne(
                "SELECT id FROM marketing_content_media
                 WHERE workspace_id = ? AND content_item_id = ?
                 LIMIT 1",
                [$this->workspaceId(), $contentId]
            );
            if ($row) {
                return true;
            }
        }
        if (!empty($distribution['id']) && Database::tableExists('marketing_channel_media_kits')) {
            $row = Database::queryOne(
                "SELECT id FROM marketing_channel_media_kits
                 WHERE workspace_id = ? AND distribution_post_id = ? AND primary_media_file_id IS NOT NULL
                 LIMIT 1",
                [$this->workspaceId(), (int) $distribution['id']]
            );
            return (bool) $row;
        }

        return false;
    }

    private function launchNeedsEmailRun(array $content, array $distribution, array $emailRun): bool
    {
        if ($emailRun !== []) {
            return true;
        }
        $channel = (string) ($distribution['channel'] ?? $content['channel'] ?? '');
        $type = (string) ($content['content_type'] ?? '');
        return in_array($channel, ['email', 'newsletter'], true) || in_array($type, ['email', 'newsletter'], true);
    }

    private function normalizeCampaignBriefData(array $data, bool $forCreate): array
    {
        $workspaceId = $this->workspaceId();
        $normalized = [];

        if ($forCreate || array_key_exists('title', $data)) {
            $title = Security::sanitizeInput((string) ($data['title'] ?? ''), 'string');
            if ($title === '') {
                throw new \InvalidArgumentException('Brief title is required.');
            }
            $normalized['title'] = $title;
        }

        foreach (['objective', 'audience', 'offer_text', 'key_message'] as $field) {
            if ($forCreate || array_key_exists($field, $data)) {
                $value = trim((string) ($data[$field] ?? ''));
                $normalized[$field] = $value !== '' ? Security::sanitizeInput($value, 'string') : null;
            }
        }

        if ($forCreate || array_key_exists('audience_segment_id', $data)) {
            $id = (int) ($data['audience_segment_id'] ?? 0);
            if ($id > 0) {
                $this->assertWorkspaceRecord('marketing_audience_segments', $id, $workspaceId);
                $normalized['audience_segment_id'] = $id;
            } else {
                $normalized['audience_segment_id'] = null;
            }
        }
        if ($forCreate || array_key_exists('channels', $data) || array_key_exists('channels_json', $data)) {
            $normalized['channels_json'] = $this->normalizeStringListJson($data['channels'] ?? $data['channels_json'] ?? []);
        }

        foreach (['start_date', 'end_date'] as $field) {
            if ($forCreate || array_key_exists($field, $data)) {
                $value = trim((string) ($data[$field] ?? ''));
                $normalized[$field] = $value !== '' ? $this->normalizeDate($value, str_replace('_', ' ', $field)) : null;
            }
        }

        if ($forCreate || array_key_exists('campaign_id', $data)) {
            $id = (int) ($data['campaign_id'] ?? 0);
            if ($id > 0) {
                $this->assertWorkspaceRecord('campaigns', $id, $workspaceId);
                $normalized['campaign_id'] = $id;
            } else {
                $normalized['campaign_id'] = null;
            }
        }

        if ($forCreate || array_key_exists('campaign_playbook_id', $data)) {
            $id = (int) ($data['campaign_playbook_id'] ?? 0);
            if ($id > 0) {
                $this->assertWorkspaceRecord('marketing_campaign_playbooks', $id, $workspaceId);
                $normalized['campaign_playbook_id'] = $id;
            } else {
                $normalized['campaign_playbook_id'] = null;
            }
        }

        foreach ([
            'persona_id' => ['table' => 'marketing_personas'],
            'offer_context_item_id' => ['table' => 'marketing_context_items', 'item_type' => 'offer'],
            'content_pillar_context_item_id' => ['table' => 'marketing_context_items', 'item_type' => 'content_pillar'],
            'landing_page_id' => ['table' => 'marketing_landing_pages'],
        ] as $field => $link) {
            if ($forCreate || array_key_exists($field, $data)) {
                $id = (int) ($data[$field] ?? 0);
                if ($id > 0) {
                    $this->assertWorkspaceRecord($link['table'], $id, $workspaceId);
                    if (!empty($link['item_type'])) {
                        $this->assertContextItemType($id, (string) $link['item_type'], $workspaceId);
                    }
                    $normalized[$field] = $id;
                } else {
                    $normalized[$field] = null;
                }
            }
        }

        foreach (['success_metrics'] as $field) {
            if ($forCreate || array_key_exists($field, $data)) {
                $normalized[$field] = $this->nullableSanitizedText($data[$field] ?? '');
            }
        }

        if ($forCreate || array_key_exists('budget_estimate', $data)) {
            $amount = trim((string) ($data['budget_estimate'] ?? ''));
            $normalized['budget_estimate'] = $amount !== '' ? max(0.0, round((float) $amount, 2)) : null;
        }

        if ($forCreate || array_key_exists('channel_plan', $data) || array_key_exists('channel_plan_json', $data)) {
            $normalized['channel_plan_json'] = $this->normalizeStringListJson($data['channel_plan'] ?? $data['channel_plan_json'] ?? []);
        }

        if ($forCreate || array_key_exists('launch_timeline', $data) || array_key_exists('launch_timeline_json', $data)) {
            $normalized['launch_timeline_json'] = $this->normalizeStringListJson($data['launch_timeline'] ?? $data['launch_timeline_json'] ?? []);
        }

        if ($forCreate || array_key_exists('owner_user_id', $data)) {
            $ownerId = (int) ($data['owner_user_id'] ?? 0);
            if ($ownerId > 0) {
                $this->assertWorkspaceUser($ownerId, $workspaceId);
                $normalized['owner_user_id'] = $ownerId;
            } else {
                $normalized['owner_user_id'] = null;
            }
        }

        if ($forCreate || array_key_exists('status', $data)) {
            $normalized['status'] = $this->normalizeEnum((string) ($data['status'] ?? 'draft'), self::BRIEF_STATUSES, 'brief_status');
        }

        if ($forCreate || array_key_exists('metadata_json', $data)) {
            $normalized['metadata_json'] = $this->normalizeJsonValue($data['metadata_json'] ?? null);
        }

        $readiness = $this->calculateCampaignReadiness($normalized + $data);
        $normalized['context_score'] = $readiness['score'];
        $normalized['readiness_score'] = $readiness['score'];
        $normalized['missing_strategy_json'] = $readiness['missing'] === []
            ? null
            : json_encode($readiness['missing'], JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE);

        if ($forCreate) {
            $normalized['created_by'] = (int) ($data['created_by'] ?? ($_SESSION['user_id'] ?? 0)) ?: null;
        }

        return $normalized;
    }

    private function normalizeBrandProfileData(array $data, bool $forCreate): array
    {
        $normalized = [];
        if ($forCreate || array_key_exists('name', $data)) {
            $name = Security::sanitizeInput((string) ($data['name'] ?? ''), 'string');
            if ($name === '') {
                throw new \InvalidArgumentException('Brand profile name is required.');
            }
            $normalized['name'] = $name;
        }
        foreach (['voice', 'tone', 'banned_words', 'value_props', 'proof_points', 'cta_defaults'] as $field) {
            if ($forCreate || array_key_exists($field, $data)) {
                $normalized[$field] = $this->nullableSanitizedText($data[$field] ?? '');
            }
        }
        if ($forCreate || array_key_exists('is_default', $data)) {
            $normalized['is_default'] = !empty($data['is_default']) ? 1 : 0;
        }
        if ($forCreate || array_key_exists('metadata_json', $data)) {
            $normalized['metadata_json'] = $this->normalizeJsonValue($data['metadata_json'] ?? null);
        }
        if ($forCreate) {
            $normalized['created_by'] = (int) ($data['created_by'] ?? ($_SESSION['user_id'] ?? 0)) ?: null;
        }

        return $normalized;
    }

    private function normalizeReusableTemplateData(array $data, bool $forCreate): array
    {
        $workspaceId = $this->workspaceId();
        $normalized = [];
        if ($forCreate || array_key_exists('name', $data)) {
            $name = Security::sanitizeInput((string) ($data['name'] ?? ''), 'string');
            if ($name === '') {
                throw new \InvalidArgumentException('Marketing template name is required.');
            }
            $normalized['name'] = mb_substr($name, 0, 190);
        }
        if ($forCreate || array_key_exists('template_key', $data)) {
            $keySource = strtolower(trim((string) ($data['template_key'] ?? ($normalized['name'] ?? $data['name'] ?? ''))));
            $key = trim((string) preg_replace('/[^a-z0-9_\\-]+/', '_', $keySource), '_-');
            $normalized['template_key'] = $key !== '' ? mb_substr($key, 0, 120) : null;
        }
        if ($forCreate || array_key_exists('template_type', $data)) {
            $normalized['template_type'] = $this->normalizeEnum((string) ($data['template_type'] ?? 'content'), self::REUSABLE_TEMPLATE_TYPES, 'template_type');
        }
        if ($forCreate || array_key_exists('status', $data)) {
