    private function landingPageSnapshot(array $page): array
    {
        $fields = [
            'id',
            'title',
            'slug',
            'headline',
            'seo_title',
            'meta_description',
            'body_sections_json',
            'section_media_json',
            'gallery_media_json',
            'theme_settings_json',
            'cta_variants_json',
            'form_blocks_json',
            'seo_controls_json',
            'social_preview_json',
            'design_schema_version',
            'design_document_json',
            'design_revision',
            'design_validation_json',
            'design_updated_at',
            'cta_blocks_json',
            'proof_blocks_json',
            'faq_blocks_json',
            'thank_you_copy',
            'preview_token',
            'conversion_goal',
            'conversion_goal_id',
            'form_id',
            'campaign_id',
            'audience_segment_id',
            'status',
            'builder_status',
        ];
        $snapshot = [];
        foreach ($fields as $field) {
            $snapshot[$field] = $page[$field] ?? null;
        }
        $snapshot['manual_first'] = true;
        $snapshot['external_hosting'] = false;
        $snapshot['captured_at'] = date('c');

        return $snapshot;
    }

    private function checkpointLandingPageDesignDraft(int $landingPageId, ?int $userId): void
    {
        $page = $this->getLandingPage($landingPageId);
        if (!$page || !Database::tableExists('marketing_landing_page_versions')) {
            return;
        }
        $latest = Database::queryOne(
            "SELECT id, created_at
             FROM marketing_landing_page_versions
             WHERE workspace_id = ? AND landing_page_id = ? AND version_type = 'draft'
             ORDER BY created_at DESC, id DESC
             LIMIT 1",
            [$this->workspaceId(), $landingPageId]
        );
        $recent = $latest && strtotime((string) ($latest['created_at'] ?? '')) >= (time() - 300);
        if ($recent) {
            Database::execute(
                'UPDATE marketing_landing_page_versions
                 SET title = ?, slug = ?, snapshot_json = ?, created_by = COALESCE(?, created_by)
                 WHERE workspace_id = ? AND landing_page_id = ? AND id = ?',
                [
                    (string) ($page['title'] ?? ''),
                    (string) ($page['slug'] ?? ''),
                    $this->normalizeJsonValue($this->landingPageSnapshot($page)),
                    $userId ?: null,
                    $this->workspaceId(),
                    $landingPageId,
                    (int) $latest['id'],
                ]
            );
            Database::execute(
                'UPDATE marketing_landing_pages SET draft_version_id = ? WHERE workspace_id = ? AND id = ?',
                [(int) $latest['id'], $this->workspaceId(), $landingPageId]
            );
            return;
        }
        $this->createLandingPageVersion($landingPageId, 'draft', $userId);
    }

    private function recordDesignTemplateEvent(
        int $landingPageId,
        string $templateKey,
        string $templateVersion,
        string $eventType,
        ?int $userId
    ): void {
        if (!Database::tableExists('marketing_design_template_events')) {
            return;
        }
        $eventType = $this->normalizeEnum($eventType, ['previewed', 'applied', 'published'], 'design_template_event_type');
        Database::execute(
            'INSERT INTO marketing_design_template_events
             (workspace_id, landing_page_id, template_key, template_version, event_type, metadata_json, created_by)
             VALUES (?, ?, ?, ?, ?, ?, ?)',
            [
                $this->workspaceId(),
                $landingPageId,
                mb_substr(Security::sanitizeInput($templateKey, 'string'), 0, 120),
                mb_substr(Security::sanitizeInput($templateVersion, 'string'), 0, 32),
                $eventType,
                $this->normalizeJsonValue(['schema' => LandingPageDesignService::SCHEMA_VERSION]),
                ($userId ?? $this->currentUserId()) ?: null,
            ]
        );
    }

