    private function normalizeConversionGoalData(array $data, bool $forCreate, ?int $existingId = null): array
    {
        $workspaceId = $this->workspaceId();
        $normalized = [];
        if ($forCreate || array_key_exists('title', $data)) {
            $title = Security::sanitizeInput((string) ($data['title'] ?? ''), 'string');
            if ($title === '') {
                throw new \InvalidArgumentException('Conversion goal title is required.');
            }
            $normalized['title'] = mb_substr($title, 0, 180);
        }
        if ($forCreate || array_key_exists('goal_key', $data) || array_key_exists('title', $data)) {
            $source = (string) ($data['goal_key'] ?? $normalized['title'] ?? $data['title'] ?? '');
            $goalKey = $this->slugify($source);
            if ($goalKey === '') {
                throw new \InvalidArgumentException('Conversion goal key is required.');
            }
            $normalized['goal_key'] = $this->uniqueConversionGoalKey($goalKey, $existingId);
        }
        if ($forCreate || array_key_exists('goal_type', $data)) {
            $normalized['goal_type'] = $this->normalizeEnum((string) ($data['goal_type'] ?? 'lead'), self::CONVERSION_GOAL_TYPES, 'conversion_goal_type');
        }
        if ($forCreate || array_key_exists('description', $data)) {
            $normalized['description'] = $this->nullableSanitizedText($data['description'] ?? '');
        }
        if ($forCreate || array_key_exists('success_metric', $data)) {
            $normalized['success_metric'] = $this->nullableSanitizedText($data['success_metric'] ?? '');
        }
        foreach (['target_count' => 'integer', 'target_value' => 'decimal'] as $field => $type) {
            if ($forCreate || array_key_exists($field, $data)) {
                $value = trim((string) ($data[$field] ?? ''));
                if ($value === '') {
                    $normalized[$field] = null;
                } elseif ($type === 'integer' && ctype_digit($value)) {
                    $normalized[$field] = max(0, (int) $value);
                } elseif ($type === 'decimal' && is_numeric($value)) {
                    $normalized[$field] = round(max(0, (float) $value), 2);
                } else {
                    throw new \InvalidArgumentException('Invalid ' . str_replace('_', ' ', $field) . '.');
                }
            }
        }
        if ($forCreate || array_key_exists('tracking_source', $data)) {
            $normalized['tracking_source'] = $this->normalizeEnum((string) ($data['tracking_source'] ?? 'manual'), self::CONVERSION_GOAL_TRACKING_SOURCES, 'conversion_goal_tracking_source');
        }
        if ($forCreate || array_key_exists('status', $data)) {
            $normalized['status'] = $this->normalizeEnum((string) ($data['status'] ?? 'draft'), self::CONVERSION_GOAL_STATUSES, 'conversion_goal_status');
        }
        if ($forCreate || array_key_exists('owner_user_id', $data)) {
            $ownerId = (int) ($data['owner_user_id'] ?? 0);
            if ($ownerId > 0) {
                $this->assertWorkspaceUser($ownerId, $workspaceId);
                $normalized['owner_user_id'] = $ownerId;
            } else {
                $normalized['owner_user_id'] = null;
            }
        }
        foreach (['starts_at', 'ends_at'] as $field) {
            if ($forCreate || array_key_exists($field, $data)) {
                $value = trim((string) ($data[$field] ?? ''));
                $normalized[$field] = $value !== '' ? $this->normalizeDate($value, str_replace('_', ' ', $field)) : null;
            }
        }
        if ($forCreate || array_key_exists('metadata_json', $data)) {
            $metadata = $this->sanitizeFlexibleArray($data['metadata_json'] ?? []);
            $metadata['manual_first_boundary'] = true;
            $normalized['metadata_json'] = $this->normalizeJsonValue($metadata);
        }
        if ($forCreate) {
            $createdBy = (int) ($data['created_by'] ?? $this->currentUserId()) ?: null;
            if (($createdBy ?? 0) > 0) {
                $this->assertWorkspaceUser((int) $createdBy, $workspaceId);
            }
            $normalized['created_by'] = $createdBy;
        }

        return $normalized;
    }

    private function uniqueConversionGoalKey(string $goalKey, ?int $existingId = null): string
    {
        $base = mb_substr($goalKey, 0, 100);
        $candidate = $base;
        $suffix = 2;
        while (true) {
            $params = [$this->workspaceId(), $candidate];
            $where = 'workspace_id = ? AND goal_key = ?';
            if ($existingId !== null) {
                $where .= ' AND id <> ?';
                $params[] = $existingId;
            }
            $row = Database::queryOne("SELECT id FROM marketing_conversion_goals WHERE {$where} LIMIT 1", $params);
            if (!$row) {
                return $candidate;
            }
            $candidate = mb_substr($base, 0, 100) . '-' . $suffix;
            $suffix++;
        }
    }

    /**
     * @return array<int,array{linked_type:string,linked_id:int}>
     */
    private function conversionGoalLinkTargets(array $data): array
    {
        $targets = [];
        foreach ([
            'campaign_id' => 'campaign',
            'landing_page_id' => 'landing_page',
            'form_id' => 'form',
            'content_item_id' => 'content_item',
            'email_run_id' => 'email_run',
            'channel_export_id' => 'channel_export',
        ] as $field => $type) {
            $id = (int) ($data[$field] ?? 0);
            if ($id > 0) {
                $targets[] = ['linked_type' => $type, 'linked_id' => $id];
            }
        }
        $linkedType = trim((string) ($data['linked_type'] ?? ''));
        $linkedId = (int) ($data['linked_id'] ?? 0);
        if ($linkedType !== '') {
            $targets[] = ['linked_type' => $linkedType, 'linked_id' => $linkedId];
        }

        $unique = [];
        foreach ($targets as $target) {
            $key = $target['linked_type'] . ':' . $target['linked_id'];
            $unique[$key] = $target;
        }

        return array_values($unique);
    }

    /**
     * @return array{score:int,warnings:string[]}
     */
    private function calculateConversionGoalReadiness(array $goal, int $linkCount): array
    {
        $warnings = [];
        if (trim((string) ($goal['success_metric'] ?? '')) === '') {
            $warnings[] = 'Add a success metric so the goal can be judged consistently.';
        }
        if (($goal['target_count'] ?? null) === null && ($goal['target_value'] ?? null) === null) {
            $warnings[] = 'Add a target count or target value.';
        }
        if ($linkCount < 1) {
            $warnings[] = 'Link at least one campaign, landing page, form, or content item.';
        }
        if (($goal['status'] ?? 'draft') === 'active' && ($goal['starts_at'] ?? null) === null) {
            $warnings[] = 'Set a start date for active goals.';
        }

        return [
            'score' => max(0, 100 - (count($warnings) * 25)),
            'warnings' => $warnings,
        ];
    }

    private function refreshConversionGoalReadiness(int $goalId): void
    {
        $goal = $this->getConversionGoal($goalId);
        if (!$goal) {
            return;
        }
        $readiness = $this->calculateConversionGoalReadiness($goal, count((array) ($goal['links'] ?? [])));
        Database::execute(
            "UPDATE marketing_conversion_goals
             SET readiness_score = ?, readiness_warnings_json = ?, updated_at = NOW()
             WHERE workspace_id = ? AND id = ?",
            [
                $readiness['score'],
                $this->normalizeJsonValue($readiness['warnings']),
                $this->workspaceId(),
                $goalId,
            ]
        );
    }

    /**
     * @return array<int,array<string,mixed>>
     */
    private function listConversionGoalLinks(int $goalId): array
    {
        if (!Database::tableExists('marketing_conversion_goal_links')) {
            return [];
        }

        return array_map(
            fn(array $row): array => $this->hydrateJsonFields($row, ['metadata_json']),
            Database::query(
                "SELECT *
                 FROM marketing_conversion_goal_links
                 WHERE workspace_id = ? AND goal_id = ?
                 ORDER BY created_at DESC, id DESC",
                [$this->workspaceId(), $goalId]
            )
        );
    }

    private function assertConversionGoalLinkTarget(string $linkedType, int $linkedId, int $workspaceId): int
    {
        if ($linkedType === 'manual') {
            return 0;
        }
        $table = match ($linkedType) {
            'campaign' => 'campaigns',
            'landing_page' => 'marketing_landing_pages',
            'form' => 'forms',
            'content_item' => 'marketing_content_items',
            'email_run' => 'marketing_email_campaign_runs',
            'channel_export' => 'marketing_channel_export_bundles',
            default => '',
        };
        if ($table === '' || $linkedId <= 0) {
            throw new \InvalidArgumentException('A valid linked record is required for this conversion goal.');
        }
        $this->assertWorkspaceRecord($table, $linkedId, $workspaceId);

        return $linkedId;
    }

    private function normalizeEmailCampaignRunData(array $data, bool $forCreate): array
    {
        $workspaceId = $this->workspaceId();
        $normalized = [];
        $audienceSegment = null;
        $segmentSnapshot = null;

        if ($forCreate || array_key_exists('name', $data)) {
            $name = Security::sanitizeInput((string) ($data['name'] ?? ''), 'string');
            if ($name === '') {
                throw new \InvalidArgumentException('Email campaign run name is required.');
            }
            $normalized['name'] = $name;
        }

        foreach (['content_item_id' => 'marketing_content_items', 'campaign_id' => 'campaigns'] as $field => $table) {
            if ($forCreate || array_key_exists($field, $data)) {
                $id = (int) ($data[$field] ?? 0);
                if ($id > 0) {
                    $this->assertWorkspaceRecord($table, $id, $workspaceId);
                    $normalized[$field] = $id;
                } else {
                    $normalized[$field] = null;
                }
            }
        }

        if ($forCreate || array_key_exists('audience_segment_id', $data)) {
            $id = (int) ($data['audience_segment_id'] ?? 0);
            if ($id > 0) {
                $audienceSegment = Database::queryOne(
                    'SELECT id, name, preview_count FROM marketing_audience_segments WHERE workspace_id = ? AND id = ?',
                    [$workspaceId, $id]
                );
                if (!$audienceSegment) {
                    throw new \InvalidArgumentException('Selected audience segment is not available in this workspace.');
                }
                $normalized['audience_segment_id'] = $id;
            } else {
                $normalized['audience_segment_id'] = null;
            }
        }
        if ($forCreate || array_key_exists('consent_policy_id', $data)) {
            $id = (int) ($data['consent_policy_id'] ?? 0);
            if ($id > 0) {
                $policy = Database::queryOne(
                    'SELECT id FROM marketing_consent_policies WHERE workspace_id = ? AND id = ?',
                    [$workspaceId, $id]
                );
                if (!$policy) {
                    throw new RuntimeException('Consent policy is not available in the active workspace.');
                }
                $normalized['consent_policy_id'] = $id;
            } else {
                $normalized['consent_policy_id'] = null;
            }
        }

        if ($forCreate || array_key_exists('segment_snapshot_id', $data)) {
            $id = (int) ($data['segment_snapshot_id'] ?? 0);
            if ($id > 0) {
                $segmentSnapshot = Database::queryOne(
                    'SELECT * FROM marketing_segment_snapshots WHERE workspace_id = ? AND id = ?',
                    [$workspaceId, $id]
                );
                if (!$segmentSnapshot) {
                    throw new \InvalidArgumentException('Selected audience snapshot is not available in this workspace.');
                }
                if (!empty($normalized['audience_segment_id']) && (int) $segmentSnapshot['segment_id'] !== (int) $normalized['audience_segment_id']) {
                    throw new \InvalidArgumentException('Selected audience snapshot does not belong to the selected segment.');
                }
                $normalized['segment_snapshot_id'] = $id;
                if (empty($normalized['audience_segment_id'])) {
                    $normalized['audience_segment_id'] = (int) $segmentSnapshot['segment_id'];
                }
            } else {
                $normalized['segment_snapshot_id'] = null;
            }
        }

        if ($forCreate || array_key_exists('email_template_id', $data)) {
            $id = (int) ($data['email_template_id'] ?? 0);
            if ($id > 0) {
                $this->assertEmailTemplateAvailable($id, $workspaceId);
                $normalized['email_template_id'] = $id;
            } else {
                $normalized['email_template_id'] = null;
            }
        }

        foreach (['subject', 'preview_text', 'preheader_text', 'segment_name', 'suppression_notes', 'unsubscribe_text', 'cta_label'] as $field) {
            if ($forCreate || array_key_exists($field, $data)) {
                $normalized[$field] = $this->nullableSanitizedText($data[$field] ?? '');
            }
        }
        if ($forCreate || array_key_exists('consent_status', $data)) {
            $normalized['consent_status'] = $this->normalizeEnum((string) ($data['consent_status'] ?? 'not_reviewed'), self::CONSENT_REVIEW_STATUSES, 'consent_status');
        }
        if ($forCreate || array_key_exists('cta_url', $data)) {
            $ctaUrl = $this->nullableSanitizedText($data['cta_url'] ?? '');
            if ($ctaUrl !== null && !preg_match('/^https?:\/\//i', $ctaUrl)) {
                throw new \InvalidArgumentException('CTA URL must start with http or https.');
            }
            $normalized['cta_url'] = $ctaUrl;
        }
        if (!empty($segmentSnapshot) && empty($normalized['segment_name'])) {
            $normalized['segment_name'] = (string) ($segmentSnapshot['name'] ?? '');
        } elseif (!empty($audienceSegment) && empty($normalized['segment_name'])) {
            $normalized['segment_name'] = (string) ($audienceSegment['name'] ?? '');
        }

        if ($forCreate || array_key_exists('body_snapshot', $data) || array_key_exists('content_item_id', $data)) {
            $body = trim((string) ($data['body_snapshot'] ?? ''));
            if ($body === '' && !empty($normalized['content_item_id'])) {
                $content = $this->getContentItem((int) $normalized['content_item_id']);
                $body = trim((string) ($content['draft_body'] ?? ''));
            }
            $normalized['body_snapshot'] = $body !== '' ? $body : null;
        }

        $hasManualSegmentSnapshot = array_key_exists('segment_snapshot', $data)
            || array_key_exists('segment_snapshot_json', $data)
            || array_key_exists('segment_criteria', $data)
            || (array_key_exists('segment_name', $data) && empty($segmentSnapshot));
        if ($hasManualSegmentSnapshot || ($forCreate && empty($segmentSnapshot))) {
            $segment = $data['segment_snapshot'] ?? $data['segment_snapshot_json'] ?? [];
            if (!is_array($segment)) {
                $segment = [];
            }
            if (!empty($data['segment_criteria'])) {
                $segment['criteria'] = Security::sanitizeInput((string) $data['segment_criteria'], 'string');
            }
            if (!empty($data['segment_name'])) {
                $segment['name'] = Security::sanitizeInput((string) $data['segment_name'], 'string');
            }
            $segment['source'] = $segment['source'] ?? 'manual';
            $normalized['segment_snapshot_json'] = $this->normalizeJsonValue($this->sanitizeFlexibleArray($segment));
        } elseif (!empty($segmentSnapshot)) {
            $normalized['segment_snapshot_json'] = $this->normalizeJsonValue([
                'source' => 'marketing_segment_snapshot',
                'snapshot_id' => (int) $segmentSnapshot['id'],
                'segment_id' => (int) $segmentSnapshot['segment_id'],
                'name' => (string) $segmentSnapshot['name'],
                'contact_count' => (int) $segmentSnapshot['contact_count'],
                'criteria' => json_decode((string) ($segmentSnapshot['criteria_json'] ?? '[]'), true) ?: [],
                'sample_contacts' => json_decode((string) ($segmentSnapshot['sample_contacts_json'] ?? '[]'), true) ?: [],
            ]);
        }

        if (array_key_exists('recipient_count', $data)) {
            $normalized['recipient_count'] = max(0, (int) ($data['recipient_count'] ?? 0));
        } elseif (!empty($segmentSnapshot)) {
            $normalized['recipient_count'] = max(0, (int) ($segmentSnapshot['contact_count'] ?? 0));
        } elseif (!empty($audienceSegment)) {
            $normalized['recipient_count'] = max(0, (int) ($audienceSegment['preview_count'] ?? 0));
        } elseif ($forCreate) {
            $normalized['recipient_count'] = 0;
        }
        if ($forCreate || array_key_exists('send_checklist', $data) || array_key_exists('send_checklist_json', $data)) {
            $normalized['send_checklist_json'] = $this->normalizeStringListJson($data['send_checklist'] ?? $data['send_checklist_json'] ?? []);
        }
        if ($forCreate || array_key_exists('approval_status', $data)) {
            $normalized['approval_status'] = $this->normalizeEnum((string) ($data['approval_status'] ?? 'not_requested'), self::EMAIL_CAMPAIGN_APPROVAL_STATUSES, 'email_approval_status');
        }
        foreach (['export_bundle_json', 'csv_export_json', 'performance_json', 'metadata_json'] as $field) {
            if ($forCreate || array_key_exists($field, $data)) {
                $normalized[$field] = $this->normalizeJsonValue($data[$field] ?? null);
            }
        }
        foreach (['scheduled_at', 'exported_at', 'csv_exported_at'] as $field) {
            if ($forCreate || array_key_exists($field, $data)) {
                $normalized[$field] = $this->normalizeDateTime((string) ($data[$field] ?? ''));
            }
        }
        if ($forCreate || array_key_exists('suppression_list_checked_at', $data) || array_key_exists('suppression_list_checked', $data)) {
            if (!empty($data['suppression_list_checked'])) {
                $normalized['suppression_list_checked_at'] = date('Y-m-d H:i:s');
            } else {
                $normalized['suppression_list_checked_at'] = $this->normalizeDateTime((string) ($data['suppression_list_checked_at'] ?? ''));
            }
        }
        if ($forCreate || array_key_exists('status', $data)) {
            $normalized['status'] = $this->normalizeEnum((string) ($data['status'] ?? 'draft'), self::EMAIL_CAMPAIGN_RUN_STATUSES, 'email_run_status');
        }
        $safety = $this->evaluateMarketingAudienceSafety([
            'channel' => 'email',
            'consent_policy_id' => $normalized['consent_policy_id'] ?? $data['consent_policy_id'] ?? null,
            'consent_status' => $normalized['consent_status'] ?? $data['consent_status'] ?? 'not_reviewed',
            'unsubscribe_text' => $normalized['unsubscribe_text'] ?? $data['unsubscribe_text'] ?? '',
            'suppression_notes' => $normalized['suppression_notes'] ?? $data['suppression_notes'] ?? '',
            'suppression_list_checked_at' => $normalized['suppression_list_checked_at'] ?? $data['suppression_list_checked_at'] ?? null,
        ]);
        $normalized['consent_status'] = $safety['status'];
        $normalized['safety_warnings_json'] = $safety['warnings'] === []
            ? null
            : $this->normalizeJsonValue($safety['warnings']);
        $readiness = $this->calculateEmailCampaignRunReadiness($normalized + $data);
        $normalized['readiness_score'] = $readiness['score'];
        $normalized['readiness_warnings_json'] = $readiness['warnings'] === []
            ? null
            : $this->normalizeJsonValue($readiness['warnings']);
        if ($forCreate) {
            $normalized['created_by'] = (int) ($data['created_by'] ?? ($_SESSION['user_id'] ?? 0)) ?: null;
        }

        return $normalized;
    }

    private function normalizeConsentPolicyData(array $data): array
    {
        $workspaceId = $this->workspaceId();
        $name = Security::sanitizeInput((string) ($data['policy_name'] ?? $data['name'] ?? ''), 'string');
        if ($name === '') {
            throw new \InvalidArgumentException('Consent policy name is required.');
        }
        $ownerId = (int) ($data['owner_user_id'] ?? 0);
        if ($ownerId > 0) {
            $this->assertWorkspaceUser($ownerId, $workspaceId);
        }

        return [
            'policy_name' => mb_substr($name, 0, 180),
            'channel' => $this->normalizeEnum((string) ($data['channel'] ?? 'email'), self::CONSENT_CHANNELS, 'consent_channel'),
            'consent_basis' => $this->normalizeEnum((string) ($data['consent_basis'] ?? 'manual_review'), self::CONSENT_BASES, 'consent_basis'),
            'requires_unsubscribe' => array_key_exists('requires_unsubscribe', $data) ? (!empty($data['requires_unsubscribe']) ? 1 : 0) : 1,
            'requires_suppression_check' => array_key_exists('requires_suppression_check', $data) ? (!empty($data['requires_suppression_check']) ? 1 : 0) : 1,
            'status' => $this->normalizeEnum((string) ($data['status'] ?? 'active'), self::CONSENT_POLICY_STATUSES, 'consent_policy_status'),
            'notes' => $this->nullableSanitizedText($data['notes'] ?? ''),
            'metadata_json' => $this->normalizeJsonValue($this->sanitizeFlexibleArray($data['metadata'] ?? $data['metadata_json'] ?? [])),
            'owner_user_id' => $ownerId > 0 ? $ownerId : null,
            'created_by' => (int) ($data['created_by'] ?? $this->currentUserId()) ?: null,
        ];
    }

    private function normalizeSuppressionEntryData(array $data): array
    {
        $identifier = trim((string) ($data['identifier'] ?? ''));
        if ($identifier === '') {
            throw new \InvalidArgumentException('Suppression identifier is required.');
        }
        $identifier = mb_substr(Security::sanitizeInput($identifier, 'string'), 0, 255);
        $channel = $this->normalizeEnum((string) ($data['channel'] ?? 'email'), self::CONSENT_CHANNELS, 'suppression_channel');

        return [
            'channel' => $channel,
            'identifier' => $identifier,
            'identifier_hash' => hash('sha256', strtolower($channel . ':' . $identifier)),
            'reason' => $this->nullableSanitizedText($data['reason'] ?? ''),
            'status' => (string) ($data['status'] ?? 'active') === 'archived' ? 'archived' : 'active',
            'source' => mb_substr(Security::sanitizeInput((string) ($data['source'] ?? 'manual'), 'string'), 0, 120),
            'metadata_json' => $this->normalizeJsonValue($this->sanitizeFlexibleArray($data['metadata'] ?? $data['metadata_json'] ?? [])),
            'created_by' => (int) ($data['created_by'] ?? $this->currentUserId()) ?: null,
        ];
    }

    private function calculateEmailCampaignRunReadiness(array $run): array
    {
        $warnings = [];
        $exportFields = [];
        $subject = trim((string) ($run['subject'] ?? ''));
        $preheader = trim((string) ($run['preheader_text'] ?? $run['preview_text'] ?? ''));
        $body = trim((string) ($run['body_snapshot'] ?? ''));
        $recipientCount = (int) ($run['recipient_count'] ?? 0);

        if ($subject === '') {
            $warnings[] = 'missing_subject';
            $exportFields[] = 'subject';
        }
        if ($preheader === '') {
            $warnings[] = 'missing_preheader';
            $exportFields[] = 'preheader';
        }
        if ($body === '') {
            $warnings[] = 'missing_body';
            $exportFields[] = 'body';
        }
        $segmentJsonRaw = $run['segment_snapshot_json'] ?? [];
        if (is_string($segmentJsonRaw)) {
            $decodedSegmentJson = json_decode($segmentJsonRaw, true);
            $segmentJsonRaw = json_last_error() === JSON_ERROR_NONE && is_array($decodedSegmentJson) ? $decodedSegmentJson : [];
        }
        $segmentJson = (array) $segmentJsonRaw;
        $hasManualSegmentJson = array_diff(array_keys($segmentJson), ['source']) !== [];
        $hasAudience = !empty($run['audience_segment_id'])
            || !empty($run['segment_snapshot_id'])
            || trim((string) ($run['segment_name'] ?? '')) !== ''
            || $hasManualSegmentJson
            || $recipientCount > 0;
        if (!$hasAudience) {
            $warnings[] = 'missing_audience';
            $exportFields[] = 'audience';
        }
        if ($recipientCount <= 0) {
            $warnings[] = 'missing_recipient_count';
            $exportFields[] = 'recipient_count';
        }
        if ((string) ($run['approval_status'] ?? 'not_requested') !== 'approved') {
            $warnings[] = 'approval_not_approved';
        }
        if (trim((string) ($run['cta_url'] ?? '')) === '' || trim((string) ($run['cta_label'] ?? '')) === '') {
            $warnings[] = 'missing_cta';
        }
        if (trim((string) ($run['unsubscribe_text'] ?? '')) === '') {
            $warnings[] = 'missing_unsubscribe_text';
        }
        if (trim((string) ($run['suppression_notes'] ?? '')) === '') {
            $warnings[] = 'missing_suppression_plan';
        }
        $safetyWarnings = $run['safety_warnings_json'] ?? [];
        if (is_string($safetyWarnings)) {
            $decodedSafetyWarnings = json_decode($safetyWarnings, true);
            $safetyWarnings = json_last_error() === JSON_ERROR_NONE && is_array($decodedSafetyWarnings) ? $decodedSafetyWarnings : [];
        }
        foreach ((array) $safetyWarnings as $safetyWarning) {
            if (is_scalar($safetyWarning)) {
                $warnings[] = 'audience_safety:' . (string) $safetyWarning;
            }
        }
        if ((array) ($run['send_checklist_json'] ?? []) === []) {
            $warnings[] = 'missing_send_checklist';
        }
        if ($exportFields !== []) {
            $warnings[] = 'missing_export_fields:' . implode(',', array_values(array_unique($exportFields)));
        }

        $warnings = array_values(array_unique($warnings));

        return [
            'score' => max(0, 100 - (count($warnings) * 12)),
            'warnings' => $warnings,
        ];
    }

    private function buildEmailCampaignCsvExportPlan(array $run): array
    {
        $segment = (array) ($run['segment_snapshot_json'] ?? []);
        $sampleContacts = (array) ($segment['sample_contacts'] ?? $segment['contacts'] ?? []);
        $rows = [];
        foreach (array_slice($sampleContacts, 0, 25) as $contact) {
            if (!is_array($contact)) {
                continue;
            }
            $rows[] = [
                'email' => (string) ($contact['email'] ?? ''),
                'first_name' => (string) ($contact['first_name'] ?? ''),
                'last_name' => (string) ($contact['last_name'] ?? ''),
                'subject' => (string) ($run['subject'] ?? ''),
                'preheader' => (string) ($run['preheader_text'] ?? $run['preview_text'] ?? ''),
                'cta_url' => (string) ($run['cta_url'] ?? ''),
                'unsubscribe_text' => (string) ($run['unsubscribe_text'] ?? ''),
            ];
        }

        return [
            'format' => 'csv',
            'filename' => 'marketing-email-run-' . (int) ($run['id'] ?? 0) . '.csv',
            'headers' => ['email', 'first_name', 'last_name', 'subject', 'preheader', 'body', 'cta_label', 'cta_url', 'unsubscribe_text'],
            'recipient_count' => (int) ($run['recipient_count'] ?? 0),
            'sample_rows' => $rows,
            'suppression_notes' => (string) ($run['suppression_notes'] ?? ''),
            'manual_export_only' => true,
            'external_send' => false,
            'generated_at' => date('c'),
        ];
    }

    private function normalizeContextItemData(array $data, bool $forCreate): array
    {
        $workspaceId = $this->workspaceId();
        $normalized = [];
        if ($forCreate || array_key_exists('item_type', $data)) {
            $normalized['item_type'] = $this->normalizeEnum((string) ($data['item_type'] ?? 'offer'), self::CONTEXT_ITEM_TYPES, 'context_type');
        }
        if ($forCreate || array_key_exists('title', $data)) {
            $title = Security::sanitizeInput((string) ($data['title'] ?? ''), 'string');
            if ($title === '') {
                throw new \InvalidArgumentException('Context title is required.');
            }
            $normalized['title'] = $title;
        }
        foreach (['body', 'channel'] as $field) {
            if ($forCreate || array_key_exists($field, $data)) {
                $normalized[$field] = $this->nullableSanitizedText($data[$field] ?? '');
            }
        }
        if ($forCreate || array_key_exists('persona_id', $data)) {
            $personaId = (int) ($data['persona_id'] ?? 0);
            if ($personaId > 0) {
                $this->assertWorkspaceRecord('marketing_personas', $personaId, $workspaceId);
                $normalized['persona_id'] = $personaId;
            } else {
                $normalized['persona_id'] = null;
            }
        }
        if ($forCreate || array_key_exists('status', $data)) {
            $normalized['status'] = $this->normalizeEnum((string) ($data['status'] ?? 'active'), self::CONTEXT_STATUSES, 'context_status');
        }
        if ($forCreate || array_key_exists('metadata_json', $data)) {
            $normalized['metadata_json'] = $this->normalizeJsonValue($data['metadata_json'] ?? null);
        }
        if ($forCreate) {
            $normalized['created_by'] = (int) ($data['created_by'] ?? ($_SESSION['user_id'] ?? 0)) ?: null;
        }

        return $normalized;
    }

    private function normalizeAssetData(array $data, bool $forCreate): array
    {
