    private function normalizeMediaFileData(array $data, bool $forCreate): array
    {
        $workspaceId = $this->workspaceId();
        $normalized = [];
        if ($forCreate || array_key_exists('title', $data)) {
            $title = Security::sanitizeInput((string) ($data['title'] ?? ''), 'string');
            if ($title === '') {
                throw new \InvalidArgumentException('Media title is required.');
            }
            $normalized['title'] = $title;
        }
        if ($forCreate || array_key_exists('media_type', $data)) {
            $normalized['media_type'] = $this->normalizeEnum((string) ($data['media_type'] ?? 'other'), self::MEDIA_TYPES, 'media_type');
        }
        if ($forCreate || array_key_exists('source_type', $data)) {
            $normalized['source_type'] = $this->normalizeEnum((string) ($data['source_type'] ?? 'url'), self::MEDIA_SOURCE_TYPES, 'source_type');
        }

        foreach (['file_path', 'source_url', 'thumbnail_path', 'thumbnail_url'] as $field) {
            if ($forCreate || array_key_exists($field, $data)) {
                $value = $this->nullableSanitizedText($data[$field] ?? '');
                if ($field === 'file_path' || $field === 'thumbnail_path') {
                    $value = $this->sanitizeMediaPath($value);
                }
                if (($field === 'source_url' || $field === 'thumbnail_url') && $value !== null && !$this->isSafeMediaUrl($value)) {
                    throw new \InvalidArgumentException('Media URLs must start with http or https.');
                }
                $normalized[$field] = $value;
            }
        }

        foreach (['mime_type', 'alt_text', 'caption', 'transcript', 'usage_rights', 'brand_safety_notes', 'blocked_reason'] as $field) {
            if ($forCreate || array_key_exists($field, $data)) {
                $normalized[$field] = $this->nullableSanitizedText($data[$field] ?? '');
            }
        }

        foreach ([
            'approval_status' => self::MEDIA_APPROVAL_STATUSES,
            'license_status' => self::MEDIA_LICENSE_STATUSES,
            'accessibility_status' => self::MEDIA_ACCESSIBILITY_STATUSES,
        ] as $field => $allowed) {
            if ($forCreate || array_key_exists($field, $data)) {
                $default = $field === 'approval_status' ? 'pending' : 'unknown';
                $normalized[$field] = $this->normalizeEnum((string) ($data[$field] ?? $default), $allowed, $field);
            }
        }
        if ($forCreate || array_key_exists('reviewer_user_id', $data)) {
            $reviewerId = (int) ($data['reviewer_user_id'] ?? 0);
            if ($reviewerId > 0) {
                $this->assertWorkspaceUser($reviewerId, $workspaceId);
                $normalized['reviewer_user_id'] = $reviewerId;
            } else {
                $normalized['reviewer_user_id'] = null;
            }
        }
        if ($forCreate || array_key_exists('reviewed_at', $data)) {
            $normalized['reviewed_at'] = $this->normalizeDateTime((string) ($data['reviewed_at'] ?? ''));
        }
        if ($forCreate || array_key_exists('expiry_date', $data)) {
            $value = trim((string) ($data['expiry_date'] ?? ''));
            $normalized['expiry_date'] = $value !== '' ? $this->normalizeDate($value, 'media expiry date') : null;
        }

        foreach (['file_size', 'width', 'height'] as $field) {
            if ($forCreate || array_key_exists($field, $data)) {
                $value = trim((string) ($data[$field] ?? ''));
                $normalized[$field] = $value !== '' ? max(0, (int) $value) : null;
            }
        }
        if ($forCreate || array_key_exists('duration_seconds', $data)) {
            $value = trim((string) ($data['duration_seconds'] ?? ''));
            $normalized['duration_seconds'] = $value !== '' ? max(0, round((float) $value, 2)) : null;
        }
        if (!empty($normalized['file_size']) && (int) $normalized['file_size'] > self::MEDIA_UPLOAD_MAX_BYTES) {
            throw new \InvalidArgumentException('Media file exceeds the 50 MB upload limit.');
        }

        if ($forCreate || array_key_exists('tags', $data) || array_key_exists('tags_json', $data)) {
            $normalized['tags_json'] = $this->normalizeStringListJson($data['tags'] ?? $data['tags_json'] ?? []);
        }
        if ($forCreate || array_key_exists('metadata_json', $data)) {
            $normalized['metadata_json'] = $this->normalizeJsonValue($this->sanitizeFlexibleArray($data['metadata_json'] ?? []));
        }
        if ($forCreate || array_key_exists('owner_user_id', $data)) {
            $ownerId = (int) ($data['owner_user_id'] ?? 0);
            if ($ownerId > 0) {
                $this->assertWorkspaceUser($ownerId, $workspaceId);
                $normalized['owner_user_id'] = $ownerId;
            } else {
                $normalized['owner_user_id'] = null;
            }
        }
        if ($forCreate) {
            $sourceType = (string) ($normalized['source_type'] ?? 'url');
            if ($sourceType === 'url' && empty($normalized['source_url'])) {
                throw new \InvalidArgumentException('A source URL is required for URL media.');
            }
            if ($sourceType === 'upload' && empty($normalized['file_path'])) {
                throw new \InvalidArgumentException('An uploaded file path is required for uploaded media.');
            }
            $normalized['created_by'] = (int) ($data['created_by'] ?? ($_SESSION['user_id'] ?? 0)) ?: null;
        }

        return $normalized;
    }

    private function normalizeCreativeBriefData(array $data): array
    {
        $workspaceId = $this->workspaceId();
        $title = Security::sanitizeInput((string) ($data['title'] ?? ''), 'string');
        if ($title === '') {
            throw new \InvalidArgumentException('Creative brief title is required.');
        }

        $contentId = (int) ($data['content_item_id'] ?? 0);
        if ($contentId > 0) {
            $this->assertWorkspaceRecord('marketing_content_items', $contentId, $workspaceId);
        }
        $campaignId = (int) ($data['campaign_id'] ?? 0);
        if ($campaignId > 0) {
            $this->assertWorkspaceRecord('campaigns', $campaignId, $workspaceId);
        }
        $ownerId = (int) ($data['owner_user_id'] ?? 0);
        if ($ownerId > 0) {
            $this->assertWorkspaceUser($ownerId, $workspaceId);
        }

        return [
            'title' => $title,
            'content_item_id' => $contentId > 0 ? $contentId : null,
            'campaign_id' => $campaignId > 0 ? $campaignId : null,
            'asset_type' => $this->normalizeEnum((string) ($data['asset_type'] ?? 'image'), self::ASSET_TYPES, 'asset_type'),
            'channel' => $this->nullableSanitizedText($data['channel'] ?? ''),
            'objective' => $this->nullableSanitizedText($data['objective'] ?? ''),
            'specs_json' => $this->normalizeJsonValue($this->sanitizeFlexibleArray($data['specs'] ?? $data['specs_json'] ?? [])),
            'status' => $this->normalizeEnum((string) ($data['status'] ?? 'draft'), self::CREATIVE_BRIEF_STATUSES, 'creative_brief_status'),
            'owner_user_id' => $ownerId > 0 ? $ownerId : null,
            'metadata_json' => $this->normalizeJsonValue($data['metadata_json'] ?? null),
            'created_by' => (int) ($data['created_by'] ?? ($_SESSION['user_id'] ?? 0)) ?: null,
        ];
    }

    private function normalizeAssetRequestData(array $data): array
    {
        $workspaceId = $this->workspaceId();
        $title = Security::sanitizeInput((string) ($data['title'] ?? ''), 'string');
        if ($title === '') {
            throw new \InvalidArgumentException('Asset request title is required.');
        }

        $briefId = (int) ($data['creative_brief_id'] ?? 0);
        if ($briefId > 0) {
            $this->assertWorkspaceRecord('marketing_creative_briefs', $briefId, $workspaceId);
        }
        $contentId = (int) ($data['content_item_id'] ?? 0);
        if ($contentId > 0) {
            $this->assertWorkspaceRecord('marketing_content_items', $contentId, $workspaceId);
        }
        $assigneeId = (int) ($data['assigned_to'] ?? 0);
        if ($assigneeId > 0) {
            $this->assertWorkspaceUser($assigneeId, $workspaceId);
        }

        return [
            'title' => $title,
            'creative_brief_id' => $briefId > 0 ? $briefId : null,
            'content_item_id' => $contentId > 0 ? $contentId : null,
            'requested_asset_type' => $this->normalizeEnum((string) ($data['requested_asset_type'] ?? 'image'), self::ASSET_TYPES, 'asset_type'),
            'channel' => $this->nullableSanitizedText($data['channel'] ?? ''),
            'description' => $this->nullableSanitizedText($data['description'] ?? ''),
            'due_at' => trim((string) ($data['due_at'] ?? '')) !== '' ? $this->normalizeDateTime((string) $data['due_at']) : null,
            'status' => $this->normalizeEnum((string) ($data['status'] ?? 'requested'), self::ASSET_REQUEST_STATUSES, 'asset_request_status'),
            'assigned_to' => $assigneeId > 0 ? $assigneeId : null,
            'metadata_json' => $this->normalizeJsonValue($data['metadata_json'] ?? null),
            'created_by' => (int) ($data['created_by'] ?? ($_SESSION['user_id'] ?? 0)) ?: null,
        ];
    }

    private function hydrateMediaProductionWorkItemRow(array $row): array
    {
        $row = $this->hydrateJsonFields($row, ['checklist_json', 'readiness_json', 'metadata_json']);
        $dueAt = (string) ($row['due_at'] ?? '');
        $row['is_overdue'] = $dueAt !== ''
            && strtotime($dueAt) !== false
            && strtotime($dueAt) < time()
            && !in_array((string) ($row['status'] ?? ''), ['ready', 'approved', 'archived'], true);

        return $row;
    }

    private function normalizeMediaProductionWorkItemData(array $data, bool $forCreate, array $existing = []): array
    {
        $workspaceId = $this->workspaceId();
        $normalized = [];

        if ($forCreate || array_key_exists('title', $data)) {
            $title = Security::sanitizeInput((string) ($data['title'] ?? ''), 'string');
            if ($title === '') {
                throw new \InvalidArgumentException('Media production work title is required.');
            }
            $normalized['title'] = mb_substr($title, 0, 190);
        }
        if ($forCreate || array_key_exists('work_type', $data)) {
            $normalized['work_type'] = $this->normalizeEnum((string) ($data['work_type'] ?? 'design'), self::MEDIA_PRODUCTION_WORK_TYPES, 'media_production_work_type');
        }
        if ($forCreate || array_key_exists('status', $data)) {
            $normalized['status'] = $this->normalizeEnum((string) ($data['status'] ?? 'requested'), self::MEDIA_PRODUCTION_WORK_STATUSES, 'media_production_status');
        }
        if ($forCreate || array_key_exists('priority', $data)) {
            $normalized['priority'] = $this->normalizeEnum((string) ($data['priority'] ?? 'normal'), self::MEDIA_PRODUCTION_WORK_PRIORITIES, 'media_production_priority');
        }

        foreach ([
            'campaign_id' => 'campaigns',
            'content_item_id' => 'marketing_content_items',
            'landing_page_id' => 'marketing_landing_pages',
            'distribution_post_id' => 'marketing_distribution_posts',
            'channel_export_bundle_id' => 'marketing_channel_export_bundles',
            'creative_brief_id' => 'marketing_creative_briefs',
            'asset_request_id' => 'marketing_asset_requests',
            'campaign_creative_requirement_id' => 'marketing_campaign_creative_requirements',
            'media_file_id' => 'marketing_media_files',
        ] as $field => $table) {
            if ($forCreate || array_key_exists($field, $data)) {
                $id = (int) ($data[$field] ?? 0);
                if ($id > 0) {
                    $this->assertWorkspaceRecord($table, $id, $workspaceId);
                    $normalized[$field] = $id;
                } else {
                    $normalized[$field] = null;
                }
            }
        }

        foreach (['channel', 'placement', 'requested_format', 'dimensions', 'blocked_reason', 'production_notes'] as $field) {
            if ($forCreate || array_key_exists($field, $data)) {
                $normalized[$field] = $this->nullableSanitizedText($data[$field] ?? '');
            }
        }
        foreach (['due_at', 'started_at', 'completed_at'] as $field) {
            if ($forCreate || array_key_exists($field, $data)) {
                $normalized[$field] = trim((string) ($data[$field] ?? '')) !== ''
                    ? $this->normalizeDateTime((string) $data[$field])
                    : null;
            }
        }
        foreach (['assigned_to', 'owner_user_id'] as $field) {
            if ($forCreate || array_key_exists($field, $data)) {
                $userId = (int) ($data[$field] ?? 0);
                if ($userId > 0) {
                    $this->assertWorkspaceUser($userId, $workspaceId);
                    $normalized[$field] = $userId;
                } else {
                    $normalized[$field] = null;
                }
            }
        }
        if ($forCreate || array_key_exists('checklist', $data) || array_key_exists('checklist_json', $data)) {
            $normalized['checklist_json'] = $this->normalizeStringListJson($data['checklist'] ?? $data['checklist_json'] ?? []);
        }
        if ($forCreate || array_key_exists('metadata_json', $data)) {
            $normalized['metadata_json'] = $this->normalizeJsonValue($data['metadata_json'] ?? null);
        }
        if ($forCreate) {
            $normalized['created_by'] = (int) ($data['created_by'] ?? ($_SESSION['user_id'] ?? 0)) ?: null;
        }

        $merged = array_merge($existing, $normalized);
        $status = (string) ($merged['status'] ?? 'requested');
        if (array_key_exists('status', $normalized)) {
            if (empty($merged['started_at']) && in_array($status, ['assigned', 'in_progress', 'review', 'ready', 'approved'], true)) {
                $normalized['started_at'] = date('Y-m-d H:i:s');
                $merged['started_at'] = $normalized['started_at'];
            }
            if (empty($merged['completed_at']) && in_array($status, ['ready', 'approved'], true)) {
                $normalized['completed_at'] = date('Y-m-d H:i:s');
                $merged['completed_at'] = $normalized['completed_at'];
            }
        }

        $this->assertMediaProductionWorkLinksConsistent($merged);
        $normalized['readiness_json'] = $this->normalizeJsonValue($this->calculateMediaProductionWorkReadiness($merged));

        return $normalized;
    }

    private function assertMediaProductionWorkLinksConsistent(array $item): void
    {
        $campaignId = (int) ($item['campaign_id'] ?? 0);
        if ($campaignId <= 0) {
            return;
        }

        foreach ([
            'content_item_id' => 'marketing_content_items',
            'landing_page_id' => 'marketing_landing_pages',
            'creative_brief_id' => 'marketing_creative_briefs',
            'campaign_creative_requirement_id' => 'marketing_campaign_creative_requirements',
        ] as $field => $table) {
            $id = (int) ($item[$field] ?? 0);
            if ($id <= 0 || !Database::tableExists($table) || !Database::columnExists($table, 'campaign_id')) {
                continue;
            }
            $row = Database::queryOne("SELECT campaign_id FROM {$table} WHERE workspace_id = ? AND id = ? LIMIT 1", [$this->workspaceId(), $id]);
            $linkedCampaignId = (int) ($row['campaign_id'] ?? 0);
            if ($linkedCampaignId > 0 && $linkedCampaignId !== $campaignId) {
                throw new RuntimeException('Linked production records must belong to the selected campaign.');
            }
        }
    }

    private function calculateMediaProductionWorkReadiness(array $item): array
    {
        $decodeList = static function (mixed $value): array {
            if (is_array($value)) {
                return $value;
            }
            if (is_string($value) && $value !== '') {
                $decoded = json_decode($value, true);
                return is_array($decoded) ? $decoded : [];
            }

            return [];
        };

        $warnings = [];
        $blocking = [];
        $checklist = $decodeList($item['checklist_json'] ?? []);
        $hasLinkedSource = false;
        foreach (['campaign_id', 'content_item_id', 'landing_page_id', 'distribution_post_id', 'channel_export_bundle_id', 'creative_brief_id', 'asset_request_id', 'campaign_creative_requirement_id'] as $field) {
            if ((int) ($item[$field] ?? 0) > 0) {
                $hasLinkedSource = true;
                break;
            }
        }

        $checks = [
            'assigned_owner' => ((int) ($item['assigned_to'] ?? 0) > 0 || (int) ($item['owner_user_id'] ?? 0) > 0),
            'due_date' => trim((string) ($item['due_at'] ?? '')) !== '',
            'linked_source' => $hasLinkedSource,
            'format' => trim((string) ($item['requested_format'] ?? '')) !== '' || trim((string) ($item['dimensions'] ?? '')) !== '',
            'checklist' => $checklist !== [],
            'not_blocked' => (string) ($item['status'] ?? '') !== 'blocked' && trim((string) ($item['blocked_reason'] ?? '')) === '',
        ];

        foreach ($checks as $key => $passed) {
            if (!$passed) {
                $warnings[] = $key;
            }
        }

        $mediaId = (int) ($item['media_file_id'] ?? 0);
        $media = $mediaId > 0 && Database::tableExists('marketing_media_files')
            ? Database::queryOne('SELECT * FROM marketing_media_files WHERE workspace_id = ? AND id = ? LIMIT 1', [$this->workspaceId(), $mediaId])
            : null;
        if ($mediaId > 0 && !$media) {
            $blocking[] = 'media_missing';
        }
        if ($media) {
            $mediaType = (string) ($media['media_type'] ?? '');
            $approval = (string) ($media['approval_status'] ?? 'pending');
            $license = (string) ($media['license_status'] ?? 'unknown');
            if (in_array($approval, ['blocked', 'rejected', 'archived'], true) || in_array($license, ['expired', 'restricted'], true)) {
                $blocking[] = 'media_governance_blocked';
            }
            if (in_array($mediaType, ['image', 'logo', 'thumbnail', 'banner'], true) && trim((string) ($media['alt_text'] ?? '')) === '') {
                $warnings[] = 'media_alt_text';
            }
            if ($mediaType === 'video' && trim((string) ($media['caption'] ?? $media['transcript'] ?? '')) === '') {
                $warnings[] = 'media_caption_or_transcript';
            }
            if ($approval !== 'approved') {
                $warnings[] = 'media_not_approved';
            }
        }

        $passed = count(array_filter($checks));
        $score = (int) round(($passed / count($checks)) * 100);
        if ($media && in_array((string) ($media['approval_status'] ?? ''), ['approved'], true)) {
            $score = min(100, $score + 10);
        }
        if ($blocking !== []) {
            $score = min($score, 50);
        }
        if ((string) ($item['status'] ?? '') === 'approved') {
            $score = 100;
        }

        $message = match (true) {
            $blocking !== [] => 'Resolve media governance or linked record blockers before this work can be used.',
            (string) ($item['status'] ?? '') === 'blocked' => 'This media production work item is blocked.',
            $score >= 90 => 'Media production work is ready for manual use or approval.',
            !$checks['assigned_owner'] => 'Assign an owner or producer for this media work.',
            !$checks['due_date'] => 'Set a production due date.',
            !$checks['linked_source'] => 'Link this work to a campaign, content item, export, brief, request, or landing page.',
            !$checks['format'] => 'Add the requested format, dimensions, or placement details.',
            !$checks['checklist'] => 'Add a production checklist so handoff and QA are clear.',
            default => 'Review the remaining production readiness warnings.',
        };

        return [
            'score' => max(0, min(100, $score)),
            'status' => $blocking !== [] ? 'blocked' : ($score >= 90 ? 'ready' : 'needs_attention'),
            'message' => $message,
            'warnings' => array_values(array_unique($warnings)),
            'blocking' => array_values(array_unique($blocking)),
            'manual_first' => true,
            'external_generation' => false,
            'external_publish' => false,
        ];
    }

    private function normalizeCampaignCreativeRequirementData(array $data): array
    {
        $workspaceId = $this->workspaceId();
        $campaignId = (int) ($data['campaign_id'] ?? 0);
        if ($campaignId <= 0 || !$this->getCampaignForWorkspace($campaignId)) {
            throw new \InvalidArgumentException('Campaign is required for a creative requirement.');
        }

        $title = Security::sanitizeInput((string) ($data['title'] ?? ''), 'string');
        if ($title === '') {
            throw new \InvalidArgumentException('Creative requirement title is required.');
        }

        $creativeBriefId = (int) ($data['creative_brief_id'] ?? 0);
        if ($creativeBriefId > 0) {
            $brief = $this->getCampaignCreativeLinkedRow('marketing_creative_briefs', $creativeBriefId);
            if (!$brief) {
                throw new RuntimeException('Creative brief was not found in the active workspace.');
            }
            if ((int) ($brief['campaign_id'] ?? 0) > 0 && (int) ($brief['campaign_id'] ?? 0) !== $campaignId) {
                throw new RuntimeException('Creative brief must belong to the selected campaign.');
            }
        }
        $assetRequestId = (int) ($data['asset_request_id'] ?? 0);
        if ($assetRequestId > 0 && !$this->getCampaignCreativeLinkedRow('marketing_asset_requests', $assetRequestId)) {
            throw new RuntimeException('Asset request was not found in the active workspace.');
        }
        $mediaFileId = (int) ($data['media_file_id'] ?? 0);
        if ($mediaFileId > 0 && !$this->getMediaFile($mediaFileId)) {
            throw new RuntimeException('Media file was not found in the active workspace.');
        }
        $contentItemId = (int) ($data['content_item_id'] ?? 0);
        if ($contentItemId > 0) {
            $content = $this->assertContentItem($contentItemId);
            if ((int) ($content['campaign_id'] ?? 0) > 0 && (int) ($content['campaign_id'] ?? 0) !== $campaignId) {
                throw new RuntimeException('Content item must belong to the selected campaign.');
            }
        }
        $landingPageId = (int) ($data['landing_page_id'] ?? 0);
        if ($landingPageId > 0) {
            $landingPage = $this->getLandingPage($landingPageId);
            if (!$landingPage) {
                throw new RuntimeException('Landing page was not found in the active workspace.');
            }
            if ((int) ($landingPage['campaign_id'] ?? 0) > 0 && (int) ($landingPage['campaign_id'] ?? 0) !== $campaignId) {
                throw new RuntimeException('Landing page must belong to the selected campaign.');
            }
        }
        $channelExportBundleId = (int) ($data['channel_export_bundle_id'] ?? 0);
        if ($channelExportBundleId > 0 && !$this->getChannelExportBundleForCampaignRequirement($channelExportBundleId, $campaignId)) {
            throw new RuntimeException('Channel export bundle must belong to the selected campaign.');
        }
        $ownerId = (int) ($data['owner_user_id'] ?? 0);
        if ($ownerId > 0) {
            $this->assertWorkspaceUser($ownerId, $workspaceId);
        }

        $base = [
            'campaign_id' => $campaignId,
            'title' => substr($title, 0, 190),
            'requirement_type' => $this->normalizeEnum((string) ($data['requirement_type'] ?? 'image'), self::CAMPAIGN_CREATIVE_REQUIREMENT_TYPES, 'campaign_creative_requirement_type'),
            'channel' => $this->nullableSanitizedText($data['channel'] ?? ''),
            'placement' => $this->nullableSanitizedText($data['placement'] ?? ''),
            'priority' => $this->normalizeEnum((string) ($data['priority'] ?? 'normal'), self::CAMPAIGN_CREATIVE_REQUIREMENT_PRIORITIES, 'campaign_creative_requirement_priority'),
            'required_count' => max(1, (int) ($data['required_count'] ?? 1)),
            'creative_brief_id' => $creativeBriefId > 0 ? $creativeBriefId : null,
            'asset_request_id' => $assetRequestId > 0 ? $assetRequestId : null,
            'media_file_id' => $mediaFileId > 0 ? $mediaFileId : null,
            'content_item_id' => $contentItemId > 0 ? $contentItemId : null,
            'landing_page_id' => $landingPageId > 0 ? $landingPageId : null,
            'channel_export_bundle_id' => $channelExportBundleId > 0 ? $channelExportBundleId : null,
            'due_at' => trim((string) ($data['due_at'] ?? '')) !== '' ? $this->normalizeDateTime((string) $data['due_at']) : null,
            'notes' => $this->nullableSanitizedText($data['notes'] ?? ''),
            'owner_user_id' => $ownerId > 0 ? $ownerId : null,
            'created_by' => (int) ($data['created_by'] ?? ($_SESSION['user_id'] ?? 0)) ?: null,
        ];
        $readiness = $this->campaignCreativeRequirementReadiness($base);
        $base['status'] = array_key_exists('status', $data)
            ? $this->normalizeEnum((string) $data['status'], self::CAMPAIGN_CREATIVE_REQUIREMENT_STATUSES, 'campaign_creative_requirement_status')
            : (string) ($readiness['suggested_status'] ?? 'planned');
        $base['readiness_json'] = $readiness;
        $base['metadata_json'] = $this->sanitizeFlexibleArray($data['metadata_json'] ?? []);

        return $base;
    }

    private function campaignCreativeRequirementReadiness(array $data): array
    {
        $media = !empty($data['media_file_id']) ? $this->getMediaFile((int) $data['media_file_id']) : null;
        $mediaAttached = $media !== null;
        $approval = (string) ($media['approval_status'] ?? 'pending');
        $license = (string) ($media['license_status'] ?? 'unknown');
        $mediaType = (string) ($media['media_type'] ?? $data['requirement_type'] ?? 'image');
        $accessibilityWarning = false;
        if ($mediaAttached && in_array($mediaType, ['image', 'logo', 'thumbnail', 'banner'], true) && trim((string) ($media['alt_text'] ?? '')) === '') {
            $accessibilityWarning = true;
        }
        if ($mediaAttached && $mediaType === 'video' && trim((string) ($media['transcript'] ?? $media['caption'] ?? '')) === '') {
            $accessibilityWarning = true;
        }
        $licenseBlocked = in_array($license, ['expired', 'restricted'], true);
        $approvalBlocked = in_array($approval, ['blocked', 'rejected', 'archived'], true);
        $mediaReady = $mediaAttached && $approval === 'approved' && !$licenseBlocked && !$accessibilityWarning;
        $suggestedStatus = match (true) {
            $approvalBlocked || $licenseBlocked => 'blocked',
            $mediaReady => 'ready',
            !empty($data['asset_request_id']) => 'requested',
            !empty($data['creative_brief_id']) => 'in_progress',
            default => 'planned',
        };
        $message = match (true) {
            !$mediaAttached => 'Attach approved campaign media or create an asset request.',
            $approvalBlocked => 'Attached media is blocked, rejected, or archived.',
            $licenseBlocked => 'Attached media has expired or restricted usage rights.',
            $accessibilityWarning => 'Attached media needs alt text, caption, or transcript before export.',
            $mediaReady => 'Approved media is attached and ready for manual campaign export.',
            default => 'Review media approval and accessibility before export.',
        };

        return [
            'media_attached' => $mediaAttached,
            'media_approved' => $approval === 'approved',
            'license_ok' => !$licenseBlocked,
            'accessibility_warning' => $accessibilityWarning,
            'suggested_status' => $suggestedStatus,
            'message' => $message,
            'media' => $media ? [
                'id' => (int) ($media['id'] ?? 0),
                'title' => (string) ($media['title'] ?? ''),
                'media_type' => $mediaType,
                'approval_status' => $approval,
                'license_status' => $license,
            ] : null,
        ];
    }

    private function getCampaignCreativeLinkedRow(string $table, int $id): ?array
    {
        if (!Database::tableExists($table) || $id <= 0) {
            return null;
        }

        return Database::queryOne(
            "SELECT * FROM {$table} WHERE workspace_id = ? AND id = ? LIMIT 1",
            [$this->workspaceId(), $id]
        ) ?: null;
    }

    private function getChannelExportBundleForCampaignRequirement(int $bundleId, int $campaignId): ?array
    {
        if (!Database::tableExists('marketing_channel_export_bundles')) {
            return null;
        }

        return Database::queryOne(
            "SELECT ceb.*
             FROM marketing_channel_export_bundles ceb
             JOIN marketing_distribution_posts dp ON dp.id = ceb.distribution_post_id AND dp.workspace_id = ceb.workspace_id
             JOIN marketing_content_items ci ON ci.id = dp.content_item_id AND ci.workspace_id = dp.workspace_id
             WHERE ceb.workspace_id = ? AND ceb.id = ? AND ci.campaign_id = ?
             LIMIT 1",
            [$this->workspaceId(), $bundleId, $campaignId]
        ) ?: null;
    }

