    private function normalizeDistributionPostData(array $data, bool $forCreate): array
    {
        $workspaceId = $this->workspaceId();
        $normalized = [];
        if ($forCreate || array_key_exists('content_item_id', $data)) {
            $contentId = (int) ($data['content_item_id'] ?? 0);
            if ($contentId <= 0) {
                throw new \InvalidArgumentException('Distribution post source content is required.');
            }
            $this->assertWorkspaceRecord('marketing_content_items', $contentId, $workspaceId);
            $normalized['content_item_id'] = $contentId;
        }
        if ($forCreate || array_key_exists('asset_id', $data)) {
            $assetId = (int) ($data['asset_id'] ?? 0);
            if ($assetId > 0) {
                $this->assertWorkspaceRecord('marketing_assets', $assetId, $workspaceId);
                $normalized['asset_id'] = $assetId;
            } else {
                $normalized['asset_id'] = null;
            }
        }
        if ($forCreate || array_key_exists('channel', $data)) {
            $normalized['channel'] = $this->normalizeEnum((string) ($data['channel'] ?? 'other'), self::CHANNELS, 'channel');
        }
        if ($forCreate || array_key_exists('planned_copy', $data)) {
            $copy = trim((string) ($data['planned_copy'] ?? ''));
            if ($copy === '' && !empty($normalized['content_item_id'])) {
                $content = $this->getContentItem((int) $normalized['content_item_id']);
                $copy = (string) ($content['draft_body'] ?? '');
            }
            $normalized['planned_copy'] = $copy !== '' ? $copy : null;
        }
        foreach ([
            'publishing_checklist_json' => 'publishing_checklist',
            'required_fields_json' => 'required_fields',
            'asset_rules_json' => 'asset_rules',
        ] as $jsonField => $formField) {
            if ($forCreate || array_key_exists($formField, $data) || array_key_exists($jsonField, $data)) {
                $normalized[$jsonField] = $this->normalizeStringListJson($data[$formField] ?? $data[$jsonField] ?? []);
            }
        }
        if ($forCreate || array_key_exists('scheduled_at', $data)) {
            $normalized['scheduled_at'] = $this->normalizeDateTime((string) ($data['scheduled_at'] ?? ''));
        }
        if ($forCreate || array_key_exists('status', $data)) {
            $normalized['status'] = $this->normalizeEnum((string) ($data['status'] ?? 'draft'), self::DISTRIBUTION_STATUSES, 'distribution_status');
        }
        if ($forCreate || array_key_exists('exported_at', $data)) {
            $normalized['exported_at'] = $this->normalizeDateTime((string) ($data['exported_at'] ?? ''));
        }
        if ($forCreate || array_key_exists('published_url', $data)) {
            $url = trim((string) ($data['published_url'] ?? ''));
            if ($url !== '' && (!filter_var($url, FILTER_VALIDATE_URL) || !preg_match('/^https?:\\/\\//i', $url))) {
                throw new \InvalidArgumentException('A valid published URL is required.');
            }
            $normalized['published_url'] = $url !== '' ? $url : null;
        }
        if ($forCreate || array_key_exists('published_at', $data)) {
            $normalized['published_at'] = $this->normalizeDateTime((string) ($data['published_at'] ?? ''));
        }
        if ($forCreate || array_key_exists('exported_bundle_json', $data)) {
            $normalized['exported_bundle_json'] = $this->normalizeJsonValue($data['exported_bundle_json'] ?? null);
        }
        if ($forCreate) {
            $normalized['created_by'] = (int) ($data['created_by'] ?? ($_SESSION['user_id'] ?? 0)) ?: null;
        }

        return $normalized;
    }

