        if ($forCreate || array_key_exists('checklist', $data) || array_key_exists('checklist_json', $data)) {
            $normalized['checklist_json'] = $this->normalizeJsonValue($this->sanitizeJsonCompatible($data['checklist'] ?? $data['checklist_json'] ?? []));
