        if ($forCreate || array_key_exists('approval', $data) || array_key_exists('approval_json', $data)) {
            $normalized['approval_json'] = $this->normalizeJsonValue($this->sanitizeJsonCompatible($data['approval'] ?? $data['approval_json'] ?? []));
        }
        if ($forCreate || array_key_exists('manager_override', $data) || array_key_exists('manager_override_json', $data)) {
