        }
        if ($forCreate || array_key_exists('live_retry', $data) || array_key_exists('live_retry_json', $data)) {
            $normalized['live_retry_json'] = $this->normalizeJsonValue($this->sanitizeJsonCompatible($data['live_retry'] ?? $data['live_retry_json'] ?? []));
        }
        if ($forCreate || array_key_exists('live_outcome_status', $data)) {
            $normalized['live_outcome_status'] = $this->normalizeEnum(
                (string) ($data['live_outcome_status'] ?? 'not_started'),
                self::LIVE_EXECUTION_OUTCOME_STATUSES,
                'live_execution_outcome_status'
            );
        }
        if ($forCreate || array_key_exists('live_outcome_checked_at', $data)) {
            $normalized['live_outcome_checked_at'] = $this->normalizeDateTime((string) ($data['live_outcome_checked_at'] ?? ''));
        }
        if ($forCreate || array_key_exists('live_outcome', $data) || array_key_exists('live_outcome_json', $data)) {
            $normalized['live_outcome_json'] = $this->normalizeJsonValue($this->sanitizeJsonCompatible($data['live_outcome'] ?? $data['live_outcome_json'] ?? []));
        }
        if ($forCreate) {
            $normalized['created_by'] = (int) ($data['created_by'] ?? $this->currentUserId()) ?: null;
        }

        return $normalized;
    }

    private function executionQueueReadiness(array $queue, ?array $connector, ?array $approval, string $attemptMode): array
    {
        $blocked = [];
        $warnings = [];
        $policy = $this->getMarketingLiveExecutionPolicy();
        $adapterKey = (string) ($connector['live_adapter_key'] ?? '');
        if ($connector === null) {
            $warnings[] = 'connector_not_selected';
        }
        if ($attemptMode === 'live') {
            $allowedConnectorTypes = (array) ($policy['allowed_connector_types_json'] ?? []);
            $allowedAdapterKeys = (array) ($policy['allowed_adapter_keys_json'] ?? []);
            if (empty($policy['live_execution_enabled']) || !in_array((string) ($policy['status'] ?? 'disabled'), ['test_only', 'live_ready'], true)) {
                $blocked[] = 'live_policy_disabled';
            }
            if (!empty($policy['emergency_paused'])) {
                $blocked[] = 'live_execution_emergency_paused';
            }
            if ($connector === null || (string) ($connector['status'] ?? '') !== 'ready') {
                $blocked[] = 'ready_connector_required';
            } elseif ($allowedConnectorTypes !== [] && !in_array((string) ($connector['connector_type'] ?? 'other'), $allowedConnectorTypes, true)) {
                $blocked[] = 'connector_type_not_allowed';
            }
            if ($connector !== null && empty($connector['live_enabled'])) {
                $blocked[] = 'connector_live_not_enabled';
            }
            if ($connector !== null && (string) ($connector['secret_status'] ?? 'not_configured') !== 'verified') {
                $blocked[] = 'verified_secret_reference_required';
            }
            if ($connector !== null && (string) ($connector['live_preflight_status'] ?? 'not_checked') !== 'passed') {
                $blocked[] = 'connector_live_preflight_required';
            }
            if ($adapterKey === '') {
                $blocked[] = 'live_adapter_not_attached';
            } elseif ($allowedAdapterKeys !== [] && !in_array($adapterKey, $allowedAdapterKeys, true)) {
                $blocked[] = 'live_adapter_not_allowed';
            } elseif (!in_array($adapterKey, self::LIVE_EXECUTION_ADAPTER_KEYS, true)) {
                $blocked[] = 'live_adapter_not_implemented';
            }
            if ((string) ($approval['status'] ?? '') !== 'approved') {
                $blocked[] = 'explicit_approval_required';
            }
            if ($adapterKey === 'crm_email_queue_handoff') {
                $emailReadiness = $this->liveEmailQueueReadiness($queue, $policy);
                array_push($blocked, ...(array) ($emailReadiness['blocked_reasons'] ?? []));
                array_push($warnings, ...(array) ($emailReadiness['warnings'] ?? []));
            }
            if ($adapterKey === 'crm_sms_queue_handoff') {
                $smsReadiness = $this->liveMessagingQueueReadiness($queue, $policy, 'sms');
                array_push($blocked, ...(array) ($smsReadiness['blocked_reasons'] ?? []));
                array_push($warnings, ...(array) ($smsReadiness['warnings'] ?? []));
            }
            if ($adapterKey === 'crm_whatsapp_queue_handoff') {
                $whatsappReadiness = $this->liveMessagingQueueReadiness($queue, $policy, 'whatsapp');
                array_push($blocked, ...(array) ($whatsappReadiness['blocked_reasons'] ?? []));
                array_push($warnings, ...(array) ($whatsappReadiness['warnings'] ?? []));
            }
            if (in_array($adapterKey, ['crm_email_queue_handoff', 'crm_sms_queue_handoff', 'crm_whatsapp_queue_handoff'], true)) {
                $consentSuppression = $this->evaluateLiveConsentSuppression($queue, $connector, $adapterKey);
                array_push($blocked, ...(array) ($consentSuppression['blocked_reasons'] ?? []));
                array_push($warnings, ...(array) ($consentSuppression['warnings'] ?? []));
            } else {
                $consentSuppression = [];
            }
            if ($connector !== null) {
                $connectorThrottle = $this->connectorLiveThrottleSnapshot($connector);
                array_push($blocked, ...(array) ($connectorThrottle['blocked_reasons'] ?? []));
                array_push($warnings, ...(array) ($connectorThrottle['warnings'] ?? []));
            } else {
                $connectorThrottle = [];
            }
            $retryStatus = (string) ($queue['live_retry_status'] ?? 'none');
            if ($retryStatus === 'scheduled' && !empty($queue['live_retry_after'])) {
                $retryAfterTs = strtotime((string) $queue['live_retry_after']);
                if ($retryAfterTs !== false && $retryAfterTs > time()) {
                    $blocked[] = 'live_retry_backoff_active';
                }
            }
            if ($retryStatus === 'exhausted') {
                $blocked[] = 'live_retries_exhausted';
            }
            if (!empty($queue['live_rehearsal_required'])) {
                $rehearsalEvidence = $this->decodeJsonLike($queue['live_rehearsal_evidence_json'] ?? $queue['live_rehearsal_evidence'] ?? []);
                $managerOverride = $this->decodeJsonLike($queue['live_manager_override_json'] ?? $queue['live_manager_override'] ?? []);
                $hasCompletedRehearsal = in_array((string) ($queue['live_rehearsal_status'] ?? ''), ['approved', 'promoted'], true)
                    && (string) ($rehearsalEvidence['dry_run_status'] ?? '') === 'passed'
                    && (int) ($queue['live_rehearsal_run_id'] ?? 0) > 0;
                $hasManagerOverride = !empty($managerOverride['manager_override_recorded'])
                    && (int) ($managerOverride['approved_by'] ?? 0) > 0
                    && trim((string) ($managerOverride['reason'] ?? '')) !== '';
                if (!$hasCompletedRehearsal && !$hasManagerOverride) {
                    $blocked[] = 'live_rehearsal_evidence_required';
                }
            }
        } else {
            $connectorThrottle = [];
        }
        if ($attemptMode !== 'live' && (string) ($queue['status'] ?? 'draft') === 'archived') {
            $blocked[] = 'queue_item_archived';
        }
        $payload = $this->decodeJsonLike($queue['payload_json'] ?? $queue['payload'] ?? []);
        if ($payload === []) {
            $warnings[] = 'payload_recommended';
        }

        return [
            'ready' => $blocked === [],
            'blocked_reasons' => array_values(array_unique($blocked)),
            'warnings' => array_values(array_unique($warnings)),
            'attempt_mode' => $attemptMode,
            'live_execution_enabled' => !empty($policy['live_execution_enabled']),
            'adapter_key' => $adapterKey !== '' ? $adapterKey : null,
            'connector_live_preflight_status' => $connector !== null ? (string) ($connector['live_preflight_status'] ?? 'not_checked') : null,
            'connector_live_throttle' => $connectorThrottle,
            'external_execution' => false,
            'policy' => $this->liveExecutionPolicySnapshot($policy),
            'consent_suppression' => $consentSuppression ?? [],
            'checked_at' => date('c'),
        ];
    }

    private function connectorLiveThrottleSnapshot(array $connector): array
    {
        if (!Database::tableExists('marketing_execution_attempts') || !Database::tableExists('marketing_execution_queue')) {
            return [
                'enabled' => false,
                'blocked_reasons' => [],
                'warnings' => ['connector_throttle_unavailable'],
                'secret_safe' => true,
            ];
        }
        $connectorId = (int) ($connector['id'] ?? 0);
        if ($connectorId <= 0) {
            return [
                'enabled' => false,
                'blocked_reasons' => [],
                'warnings' => ['connector_missing_for_throttle'],
                'secret_safe' => true,
            ];
        }
        $hourlyCap = max(0, (int) ($connector['live_hourly_cap'] ?? 0));
        $dailyCap = max(0, (int) ($connector['live_daily_cap'] ?? 0));
        $cooldownSeconds = max(0, (int) ($connector['live_cooldown_seconds'] ?? 0));
        $hourlyUsed = (int) (Database::queryOne(
            "SELECT COUNT(*) AS count
             FROM marketing_execution_attempts ea
             JOIN marketing_execution_queue eq ON eq.id = ea.queue_id AND eq.workspace_id = ea.workspace_id
             WHERE ea.workspace_id = ?
               AND eq.connector_id = ?
               AND ea.attempt_mode = 'live'
               AND ea.status IN ('success', 'failed')
               AND ea.started_at >= DATE_SUB(NOW(), INTERVAL 1 HOUR)",
            [$this->workspaceId(), $connectorId]
        )['count'] ?? 0);
        $dailyUsed = (int) (Database::queryOne(
            "SELECT COUNT(*) AS count
             FROM marketing_execution_attempts ea
             JOIN marketing_execution_queue eq ON eq.id = ea.queue_id AND eq.workspace_id = ea.workspace_id
             WHERE ea.workspace_id = ?
               AND eq.connector_id = ?
               AND ea.attempt_mode = 'live'
               AND ea.status IN ('success', 'failed')
               AND ea.started_at >= CURRENT_DATE()",
            [$this->workspaceId(), $connectorId]
        )['count'] ?? 0);
        $lastAttemptAt = $connector['last_live_attempt_at'] ?? null;
        if (empty($lastAttemptAt)) {
            $lastAttemptAt = Database::queryOne(
                "SELECT MAX(ea.started_at) AS last_attempt_at
                 FROM marketing_execution_attempts ea
                 JOIN marketing_execution_queue eq ON eq.id = ea.queue_id AND eq.workspace_id = ea.workspace_id
                 WHERE ea.workspace_id = ?
                   AND eq.connector_id = ?
                   AND ea.attempt_mode = 'live'
                   AND ea.status IN ('success', 'failed')",
                [$this->workspaceId(), $connectorId]
            )['last_attempt_at'] ?? null;
        }
        $cooldownRemaining = 0;
        if ($cooldownSeconds > 0 && !empty($lastAttemptAt)) {
            $lastTs = strtotime((string) $lastAttemptAt);
            if ($lastTs !== false) {
                $cooldownRemaining = max(0, ($lastTs + $cooldownSeconds) - time());
            }
        }

        $blocked = [];
        $warnings = [];
        if ($hourlyCap > 0 && $hourlyUsed >= $hourlyCap) {
            $blocked[] = 'connector_hourly_live_cap_exceeded';
        }
        if ($dailyCap > 0 && $dailyUsed >= $dailyCap) {
            $blocked[] = 'connector_daily_live_cap_exceeded';
        }
        if ($cooldownRemaining > 0) {
            $blocked[] = 'connector_live_cooldown_active';
        }
        if ($hourlyCap === 0 && $dailyCap === 0 && $cooldownSeconds === 0) {
            $warnings[] = 'connector_live_throttle_not_configured';
        }

        return [
            'enabled' => $hourlyCap > 0 || $dailyCap > 0 || $cooldownSeconds > 0,
            'connector_id' => $connectorId,
            'hourly_cap' => $hourlyCap,
            'hourly_used' => $hourlyUsed,
            'hourly_remaining' => $hourlyCap > 0 ? max(0, $hourlyCap - $hourlyUsed) : null,
            'daily_cap' => $dailyCap,
            'daily_used' => $dailyUsed,
            'daily_remaining' => $dailyCap > 0 ? max(0, $dailyCap - $dailyUsed) : null,
            'cooldown_seconds' => $cooldownSeconds,
            'cooldown_remaining_seconds' => $cooldownRemaining,
            'last_live_attempt_at' => $lastAttemptAt,
            'blocked_reasons' => array_values(array_unique($blocked)),
            'warnings' => array_values(array_unique($warnings)),
            'checked_at' => date('c'),
            'secret_safe' => true,
        ];
    }

    private function buildLiveRetryPlanAfterFailedAttempt(array $queue, int $attemptId, array $adapterResult, array $readiness): array
    {
        if (!Database::columnExists('marketing_execution_queue', 'live_retry_status')) {
            return [
                'status' => 'unavailable',
                'queue_update' => [],
                'summary' => [
                    'retry_available' => false,
                    'reason' => 'live_retry_columns_unavailable',
                    'secret_safe' => true,
                ],
            ];
        }

        $rerunPolicy = $this->normalizeEnum(
            (string) ($queue['live_rerun_policy'] ?? 'block_after_success'),
            self::LIVE_EXECUTION_RERUN_POLICIES,
            'live_execution_rerun_policy'
        );
        $currentRetryCount = max(0, (int) ($queue['live_retry_count'] ?? 0));
        $maxRetries = max(0, min(25, (int) ($queue['live_max_retries'] ?? 0)));
        $backoffSeconds = max(60, min(604800, (int) ($queue['live_retry_backoff_seconds'] ?? 900)));
        $reason = mb_substr((string) ($adapterResult['message'] ?? 'Live adapter attempt failed.'), 0, 500);
        $baseSummary = [
            'retry_available' => $rerunPolicy === 'allow_failed_retry' && $maxRetries > 0,
            'rerun_policy' => $rerunPolicy,
            'attempt_id' => $attemptId,
            'current_retry_count' => $currentRetryCount,
            'max_retries' => $maxRetries,
            'backoff_seconds' => $backoffSeconds,
            'adapter_status' => (string) ($adapterResult['status'] ?? 'failed'),
            'blocked_reasons' => (array) ($readiness['blocked_reasons'] ?? []),
            'secret_safe' => true,
        ];

        if ($rerunPolicy !== 'allow_failed_retry') {
            $summary = $baseSummary + ['reason' => 'live_rerun_policy_does_not_allow_failed_retry'];
            return [
                'status' => 'exhausted',
                'summary' => $summary,
                'queue_update' => [
                    'live_retry_status' => 'exhausted',
                    'live_retry_after' => null,
                    'live_retry_reason' => 'Live retry is not allowed by this queue rerun policy.',
                    'live_retry_json' => $this->normalizeJsonValue($summary),
                ],
            ];
        }
        if ($maxRetries <= 0) {
            $summary = $baseSummary + ['reason' => 'live_max_retries_not_configured'];
            return [
                'status' => 'exhausted',
                'summary' => $summary,
                'queue_update' => [
                    'live_retry_status' => 'exhausted',
                    'live_retry_after' => null,
                    'live_retry_reason' => 'No live retries are configured for this queue item.',
                    'live_retry_json' => $this->normalizeJsonValue($summary),
                ],
            ];
        }
        if ($currentRetryCount >= $maxRetries) {
            $summary = $baseSummary + ['reason' => 'live_max_retries_exhausted'];
            return [
                'status' => 'exhausted',
                'summary' => $summary,
                'queue_update' => [
                    'live_retry_status' => 'exhausted',
                    'live_retry_after' => null,
                    'live_retry_reason' => 'Maximum live retry count reached.',
                    'live_retry_json' => $this->normalizeJsonValue($summary),
                ],
            ];
        }

        $nextRetryCount = $currentRetryCount + 1;
        $retryAfter = date('Y-m-d H:i:s', time() + $backoffSeconds);
        $summary = $baseSummary + [
            'reason' => 'failed_live_attempt_scheduled_for_retry',
            'next_retry_count' => $nextRetryCount,
            'retry_after' => $retryAfter,
            'message' => $reason,
        ];

        return [
            'status' => 'scheduled',
            'summary' => $summary,
            'queue_update' => [
                'status' => 'queued',
                'live_dispatch_status' => 'confirmed',
                'live_retry_status' => 'scheduled',
                'live_retry_count' => $nextRetryCount,
                'live_retry_after' => $retryAfter,
                'live_retry_reason' => $reason,
                'live_retry_json' => $this->normalizeJsonValue($summary),
                'live_blocked_reason' => null,
            ],
        ];
    }

    private function initialLiveOutcomeFromAttempt(string $attemptStatus, array $adapterResult): array
    {
        $adapterKey = (string) ($adapterResult['adapter_key'] ?? '');
        $queueHandoffAdapters = ['crm_email_queue_handoff', 'crm_sms_queue_handoff', 'crm_whatsapp_queue_handoff'];
        $status = match ($attemptStatus) {
            'success' => in_array($adapterKey, $queueHandoffAdapters, true) ? 'queued' : 'delivered',
            'blocked' => 'blocked',
            'failed' => 'failed',
            default => 'unknown',
        };

        return [
            'status' => $status,
            'source' => 'live_attempt',
            'adapter_key' => $adapterKey,
            'attempt_status' => $attemptStatus,
            'message' => (string) ($adapterResult['message'] ?? ''),
            'email_queue_handoff_only' => !empty($adapterResult['email_queue_handoff_only']),
            'channel_queue_handoff_only' => !empty($adapterResult['channel_queue_handoff_only']),
            'execution_type' => (string) ($adapterResult['execution_type'] ?? ''),
            'queued_recipients' => (int) ($adapterResult['queued_recipients'] ?? 0),
            'blocked_recipients' => (int) ($adapterResult['blocked_recipients'] ?? 0),
            'failed_recipients' => (int) ($adapterResult['failed_recipients'] ?? 0),
            'webhook_status' => (string) ($adapterResult['webhook_status'] ?? ''),
            'publication_status' => (string) ($adapterResult['publication_status'] ?? ''),
            'checked_at' => date('c'),
            'secret_safe' => true,
        ];
    }

    private function buildLiveOutcomeReconciliationSummary(array $queue, array $outcome, string $queueStatus): array
    {
        $fingerprint = $this->liveOutcomeFingerprint($outcome, $queueStatus);

        return [
            'reconciliation_key' => hash('sha256', $this->workspaceId() . ':' . (int) ($queue['id'] ?? 0) . ':' . $fingerprint),
            'fingerprint' => $fingerprint,
            'normalized_status' => $this->normalizeLiveOutcomeEventStatus($queueStatus, $outcome),
            'queue_outcome_status' => $queueStatus,
            'source_type' => $this->liveOutcomeSourceType((string) ($outcome['adapter_key'] ?? $queue['live_adapter_key'] ?? '')),
            'source_reference' => $this->liveOutcomeSourceReference($outcome),
            'checked_at' => date('c'),
            'secret_safe' => true,
        ];
    }

    private function liveOutcomeFingerprint(array $outcome, string $queueStatus): string
    {
        $stable = $outcome;
        unset($stable['checked_at']);
        if (isset($stable['channel_sync']) && is_array($stable['channel_sync'])) {
            unset($stable['channel_sync']['checked_at']);
        }
        ksort($stable);

        return hash('sha256', $queueStatus . ':' . (json_encode($stable, JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE) ?: ''));
    }

    private function normalizeLiveOutcomeEventStatus(string $status, array $outcome = []): string
    {
        $status = strtolower(trim($status));
        $sourceStatus = strtolower(trim((string) ($outcome['proof_status'] ?? $outcome['webhook_status'] ?? $outcome['publication_status'] ?? '')));
        $candidate = $sourceStatus !== '' ? $sourceStatus : $status;

        return match ($candidate) {
            'queued', 'pending', 'reviewed' => 'queued',
            'processing', 'running' => 'processing',
            'sent', 'simulated' => 'sent',
            'delivered', 'published', 'partially_delivered' => 'delivered',
            'opened', 'open', 'read' => 'opened',
            'clicked', 'click' => 'clicked',
            'replied', 'reply' => 'replied',
            'bounced', 'bounce', 'undelivered' => 'bounced',
            'failed', 'error' => 'failed',
            'blocked', 'skipped' => 'blocked',
            'cancelled', 'canceled', 'unpublished' => 'cancelled',
            default => 'unknown',
        };
    }

    private function liveOutcomeSourceType(string $adapterKey): string
    {
        return match ($adapterKey) {
            'crm_email_queue_handoff' => 'email',
            'crm_sms_queue_handoff' => 'sms',
            'crm_whatsapp_queue_handoff' => 'whatsapp',
            'crm_outbound_webhook', 'crm_internal_webhook' => 'webhook',
            'crm_landing_publication' => 'landing_page',
            default => 'queue',
        };
    }

    private function liveOutcomeSourceReference(array $outcome): ?string
    {
        foreach (['provider_reference', 'provider_message_id', 'endpoint_url_hash', 'public_url'] as $key) {
            $value = trim((string) ($outcome[$key] ?? ''));
            if ($value !== '') {
                return mb_substr(Security::sanitizeInput($value, 'string'), 0, 255);
            }
        }
        if (!empty($outcome['handoff_counts'])) {
            return 'handoff_counts:' . hash('sha256', json_encode($outcome['handoff_counts'], JSON_UNESCAPED_SLASHES) ?: '');
        }

        return null;
    }

    private function recordLiveOutcomeReconciliationEvent(array $queue, array $outcome, string $queueStatus, array $reconciliation): bool
    {
        if (!Database::tableExists('marketing_live_outcome_reconciliation_events')) {
            return false;
        }
        $key = (string) ($reconciliation['reconciliation_key'] ?? '');
        if ($key === '') {
            return false;
        }

        $existing = Database::queryOne(
            "SELECT id FROM marketing_live_outcome_reconciliation_events WHERE workspace_id = ? AND reconciliation_key = ? LIMIT 1",
            [$this->workspaceId(), $key]
        );
        if ($existing) {
            return false;
        }

        $evidence = [
            'queue_id' => (int) ($queue['id'] ?? 0),
            'adapter_key' => (string) ($outcome['adapter_key'] ?? $queue['live_adapter_key'] ?? ''),
            'queue_status' => (string) ($outcome['queue_status'] ?? $queue['status'] ?? ''),
            'queue_outcome_status' => $queueStatus,
            'handoff_counts' => (array) ($outcome['handoff_counts'] ?? []),
            'webhook_status' => (string) ($outcome['webhook_status'] ?? ''),
            'publication_status' => (string) ($outcome['publication_status'] ?? ''),
            'source_reference_present' => !empty($reconciliation['source_reference']),
            'raw_secret_values_visible' => false,
            'secret_safe' => true,
        ];

        Database::execute(
            "INSERT INTO marketing_live_outcome_reconciliation_events
             (workspace_id, uuid, queue_id, connector_id, adapter_key, normalized_status, queue_outcome_status,
              source_type, source_reference, reconciliation_key, evidence_json, reconciled_at)
             VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, NOW())
             ON DUPLICATE KEY UPDATE reconciliation_key = reconciliation_key",
            [
                $this->workspaceId(),
                $this->generateUuid(),
                (int) ($queue['id'] ?? 0),
                !empty($queue['connector_id']) ? (int) $queue['connector_id'] : null,
                !empty($outcome['adapter_key']) ? mb_substr(Security::sanitizeInput((string) $outcome['adapter_key'], 'string'), 0, 120) : null,
                $this->normalizeLiveOutcomeEventStatus((string) ($reconciliation['normalized_status'] ?? $queueStatus), $outcome),
                mb_substr(Security::sanitizeInput($queueStatus, 'string'), 0, 60),
                $this->normalizeEnum((string) ($reconciliation['source_type'] ?? 'other'), ['email', 'sms', 'whatsapp', 'webhook', 'landing_page', 'queue', 'other'], 'live_outcome_source_type'),
                !empty($reconciliation['source_reference']) ? mb_substr(Security::sanitizeInput((string) $reconciliation['source_reference'], 'string'), 0, 255) : null,
                $key,
                $this->normalizeJsonValue($this->sanitizeJsonCompatible($evidence + ['reconciliation' => $reconciliation])),
            ]
        );

        return true;
    }

    private function buildLiveProofPackEvidence(array $queue, ?array $connector): array
    {
        $queueId = (int) ($queue['id'] ?? 0);
        $approval = Database::tableExists('marketing_execution_approvals')
            ? (Database::queryOne(
                "SELECT a.*, requester.email AS requested_by_email, approver.email AS approved_by_email
                 FROM marketing_execution_approvals a
                 LEFT JOIN users requester ON requester.id = a.requested_by
                 LEFT JOIN users approver ON approver.id = a.approved_by
                 WHERE a.workspace_id = ? AND a.queue_id = ?
                 ORDER BY a.created_at DESC, a.id DESC
                 LIMIT 1",
                [$this->workspaceId(), $queueId]
            ) ?: [])
            : [];
        $attempts = array_map(
            fn(array $attempt): array => $this->liveProofPackAttemptSummary($attempt),
            $this->listExecutionAttempts(['queue_id' => $queueId], 20, 0)
        );
        $emailDeliveryProofs = [];
        $emailHandoffs = $this->listLiveEmailHandoffs(['queue_id' => $queueId], 20, 0);
        foreach ($emailHandoffs as $handoff) {
            foreach ($this->listLiveEmailDeliveryProofs(['handoff_id' => (int) ($handoff['id'] ?? 0)], 20, 0) as $proof) {
                $emailDeliveryProofs[] = $this->liveProofPackEmailProofSummary($proof);
            }
        }
        $channelDeliveryProofs = array_map(
            fn(array $proof): array => $this->liveProofPackChannelProofSummary($proof),
            $this->listLiveChannelDeliveryProofs(['queue_id' => $queueId], 20, 0)
        );
        $recoveryEvents = array_map(
            fn(array $event): array => $this->liveProofPackRecoveryEventSummary($event),
            $this->listLiveRecoveryEvents(['queue_id' => $queueId], 20, 0)
        );
        $reconciliationEvents = array_map(
            fn(array $event): array => $this->liveProofPackReconciliationEventSummary($event),
            $this->listLiveOutcomeReconciliationEvents(['queue_id' => $queueId], 20, 0)
        );
        $webhookAttempts = array_map(
            fn(array $attempt): array => $this->liveProofPackWebhookAttemptSummary($attempt),
            $this->listLiveWebhookAttempts(['queue_id' => $queueId], 20, 0)
        );

        $connectorEvidence = $connector ? [
            'id' => (int) ($connector['id'] ?? 0),
            'name' => (string) ($connector['name'] ?? ''),
            'connector_type' => (string) ($connector['connector_type'] ?? 'other'),
            'status' => (string) ($connector['status'] ?? 'draft'),
            'setup_status' => (string) ($connector['setup_status'] ?? 'not_started'),
            'readiness_score' => (int) ($connector['readiness_score'] ?? 0),
            'live_enabled' => !empty($connector['live_enabled']),
            'live_adapter_key' => (string) ($connector['live_adapter_key'] ?? ''),
            'secret_status' => (string) ($connector['secret_status'] ?? 'not_configured'),
            'secret_reference_present' => trim((string) ($connector['secret_reference'] ?? '')) !== '',
            'secret_reference_visible' => false,
            'live_preflight_status' => (string) ($connector['live_preflight_status'] ?? 'not_checked'),
            'live_preflight_checked_at' => (string) ($connector['live_preflight_checked_at'] ?? ''),
            'throttle' => [
                'hourly_cap' => (int) ($connector['live_hourly_cap'] ?? 0),
                'daily_cap' => (int) ($connector['live_daily_cap'] ?? 0),
                'cooldown_seconds' => (int) ($connector['live_cooldown_seconds'] ?? 0),
            ],
        ] : [
            'id' => null,
            'status' => 'missing',
            'secret_reference_visible' => false,
        ];
        $policy = $this->getMarketingLiveExecutionPolicy();
        $confirmationText = (string) ($queue['live_last_confirmation_text'] ?? '');

        $evidence = [
            'generated_at' => date('c'),
            'workspace_id' => $this->workspaceId(),
            'queue' => [
                'id' => $queueId,
                'uuid' => (string) ($queue['uuid'] ?? ''),
                'execution_type' => (string) ($queue['execution_type'] ?? 'other'),
                'execution_mode' => (string) ($queue['execution_mode'] ?? 'dry_run'),
                'status' => (string) ($queue['status'] ?? 'draft'),
                'scheduled_at' => (string) ($queue['scheduled_at'] ?? ''),
                'connector_id' => !empty($queue['connector_id']) ? (int) $queue['connector_id'] : null,
                'live_dispatch_status' => (string) ($queue['live_dispatch_status'] ?? 'not_ready'),
                'live_idempotency_key_hash' => $this->hashLiveProofValue((string) ($queue['live_idempotency_key'] ?? '')),
                'live_retry_status' => (string) ($queue['live_retry_status'] ?? 'none'),
                'live_retry_count' => (int) ($queue['live_retry_count'] ?? 0),
                'live_recovery_status' => (string) ($queue['live_recovery_status'] ?? 'none'),
                'live_outcome_status' => (string) ($queue['live_outcome_status'] ?? 'unknown'),
                'live_outcome_checked_at' => (string) ($queue['live_outcome_checked_at'] ?? ''),
                'payload_preview' => $this->sanitizeVisibleConnectorPayload($queue['payload_json'] ?? []),
            ],
            'policy' => [
                'status' => (string) ($policy['status'] ?? 'disabled'),
                'live_execution_enabled' => !empty($policy['live_execution_enabled']),
                'require_manage_approval' => !empty($policy['require_manage_approval']),
                'emergency_paused' => !empty($policy['emergency_paused']),
                'daily_live_cap' => (int) ($policy['daily_live_cap'] ?? 0),
                'allowed_connector_types' => array_values(array_map('strval', (array) ($policy['allowed_connector_types_json'] ?? []))),
                'allowed_adapter_keys' => array_values(array_map('strval', (array) ($policy['allowed_adapter_keys_json'] ?? []))),
            ],
            'connector' => $connectorEvidence,
            'approval' => [
                'id' => !empty($approval['id']) ? (int) $approval['id'] : null,
                'status' => (string) ($approval['status'] ?? 'missing'),
                'requested_at' => (string) ($approval['requested_at'] ?? ''),
                'decided_at' => (string) ($approval['decided_at'] ?? ''),
                'requested_by_present' => !empty($approval['requested_by']),
                'approved_by_present' => !empty($approval['approved_by']),
                'decision_note_present' => trim((string) ($approval['decision_note'] ?? '')) !== '',
            ],
            'confirmation' => [
                'phrase_present' => trim($confirmationText) !== '',
                'phrase_hash' => $this->hashLiveProofValue($confirmationText),
                'confirmed_at' => (string) ($queue['live_last_confirmed_at'] ?? ''),
                'confirmed_by_present' => !empty($queue['live_last_confirmed_by']),
                'raw_phrase_visible' => false,
            ],
            'consent_suppression' => [
                'consent_basis' => (string) ($queue['live_consent_basis'] ?? ''),
                'unsubscribe_evidence' => (array) ($queue['live_unsubscribe_evidence_json'] ?? []),
                'suppression_checked_at' => (string) ($queue['live_suppression_checked_at'] ?? ''),
                'suppression_result' => (string) ($queue['live_suppression_result'] ?? 'not_checked'),
                'blocked_reason' => (string) ($queue['live_suppression_blocked_reason'] ?? ''),
                'evidence' => (array) ($queue['live_consent_evidence_json'] ?? []),
            ],
            'adapter_attempts' => $attempts,
            'delivery_proofs' => [
                'email' => $emailDeliveryProofs,
                'channel' => $channelDeliveryProofs,
            ],
            'outcome' => [
                'status' => (string) ($queue['live_outcome_status'] ?? 'unknown'),
                'checked_at' => (string) ($queue['live_outcome_checked_at'] ?? ''),
                'reconciliation_key_present' => !empty($queue['live_outcome_reconciliation_key']),
                'reconciliation' => (array) ($queue['live_outcome_reconciliation_json'] ?? []),
                'events' => $reconciliationEvents,
            ],
            'recovery_events' => $recoveryEvents,
            'webhook_attempts' => $webhookAttempts,
            'safety' => [
                'raw_secrets_visible' => false,
                'raw_recipient_values_visible' => false,
                'raw_confirmation_phrase_visible' => false,
                'stack_traces_visible' => false,
                'secret_safe' => true,
            ],
        ];

        return $this->sanitizeLiveProofPackArray($evidence);
    }

    private function buildLiveProofPackSummary(array $queue, array $evidence): array
    {
        $attempts = (array) ($evidence['adapter_attempts'] ?? []);
        $emailProofs = (array) ($evidence['delivery_proofs']['email'] ?? []);
        $channelProofs = (array) ($evidence['delivery_proofs']['channel'] ?? []);
        $reconciliationEvents = (array) ($evidence['outcome']['events'] ?? []);
        $outcomeStatus = (string) ($queue['live_outcome_status'] ?? ($evidence['outcome']['status'] ?? 'unknown'));
        $queueStatus = (string) ($queue['status'] ?? 'draft');
        $suppressionResult = (string) ($queue['live_suppression_result'] ?? '');
        $attemptStatuses = array_values(array_map(static fn(array $attempt): string => (string) ($attempt['status'] ?? ''), $attempts));

        if (in_array($outcomeStatus, ['failed', 'bounced'], true) || $queueStatus === 'failed' || in_array('failed', $attemptStatuses, true)) {
            $proofStatus = 'failed';
        } elseif ($queueStatus === 'blocked' || $outcomeStatus === 'blocked' || $suppressionResult === 'blocked' || in_array('blocked', $attemptStatuses, true)) {
            $proofStatus = 'blocked';
        } elseif ($outcomeStatus !== '' && !in_array($outcomeStatus, ['unknown', 'not_started'], true) && ($attempts !== [] || $emailProofs !== [] || $channelProofs !== [] || $reconciliationEvents !== [])) {
            $proofStatus = 'complete';
        } elseif ($attempts !== [] || $emailProofs !== [] || $channelProofs !== [] || $reconciliationEvents !== []) {
            $proofStatus = 'partial';
        } else {
            $proofStatus = 'unknown';
        }

        return $this->sanitizeLiveProofPackArray([
            'proof_status' => $proofStatus,
            'normalized_outcome_status' => $this->normalizeLiveOutcomeEventStatus($outcomeStatus),
            'queue_id' => (int) ($queue['id'] ?? 0),
            'execution_type' => (string) ($queue['execution_type'] ?? 'other'),
            'queue_status' => $queueStatus,
            'connector_id' => !empty($queue['connector_id']) ? (int) $queue['connector_id'] : null,
            'counts' => [
                'adapter_attempts' => count($attempts),
                'email_delivery_proofs' => count($emailProofs),
                'channel_delivery_proofs' => count($channelProofs),
                'reconciliation_events' => count($reconciliationEvents),
                'recovery_events' => count((array) ($evidence['recovery_events'] ?? [])),
                'webhook_attempts' => count((array) ($evidence['webhook_attempts'] ?? [])),
            ],
            'includes' => [
                'policy_state' => !empty($evidence['policy']),
                'connector_readiness' => !empty($evidence['connector']),
                'approval_evidence' => !empty($evidence['approval']),
                'confirmation_hash' => !empty($evidence['confirmation']['phrase_hash']),
                'adapter_evidence' => $attempts !== [],
                'delivery_proof' => $emailProofs !== [] || $channelProofs !== [],
                'recovery_events' => !empty($evidence['recovery_events']),
                'consent_suppression' => !empty($evidence['consent_suppression']),
            ],
            'safety' => [
                'secrets_excluded' => true,
                'recipient_values_redacted' => true,
                'raw_confirmation_excluded' => true,
                'secret_safe' => true,
            ],
            'generated_at' => date('c'),
        ]);
    }

