    private function hashLiveProofValue(string $value): ?string
    {
        $value = trim($value);
        return $value !== '' ? hash('sha256', $this->workspaceId() . ':' . $value) : null;
    }

    private function sanitizeLiveProofPackArray(array $value): array
    {
        $sanitized = $this->sanitizeLiveProofPackValue($value);
        return is_array($sanitized) ? $sanitized : [];
    }

    private function sanitizeLiveProofPackValue(mixed $value, string|int|null $key = null): mixed
    {
        $keyString = is_int($key) ? '' : strtolower((string) $key);
        if (is_array($value)) {
            $clean = [];
            foreach ($value as $childKey => $childValue) {
                $cleanKey = is_int($childKey)
                    ? $childKey
                    : (preg_replace('/[^a-zA-Z0-9_]/', '', (string) $childKey) ?: '');
                if ($cleanKey === '') {
                    continue;
                }
                $clean[$cleanKey] = $this->sanitizeLiveProofPackValue($childValue, $cleanKey);
            }

            return $clean;
        }
        if (is_bool($value) || is_int($value) || is_float($value) || $value === null) {
            return $value;
        }

        $string = Security::sanitizeInput((string) $value, 'string');
        if (preg_match('/(password|secret|token|api_key|apikey|authorization|credential|private_key|confirmation_text|live_confirmation_text|raw_phrase)/i', $keyString) === 1) {
            return trim($string) !== '' ? '[redacted]' : null;
        }
        if (preg_match('/(recipient_email|to_email|from_email|email|phone|recipient_identifier|target_recipient)/i', $keyString) === 1) {
            return trim($string) !== '' ? '[redacted:' . substr(hash('sha256', $this->workspaceId() . ':' . $string), 0, 12) . ']' : '';
        }

        $string = preg_replace('/Bearer\s+[A-Za-z0-9._~+\\-\\/]+=*/i', 'Bearer [redacted]', $string) ?? $string;
        $string = preg_replace('/vault:\\/\\/[^\\s,"\']+/i', '[secret-reference]', $string) ?? $string;
        $string = preg_replace('/sk-[A-Za-z0-9_\\-]{10,}/i', '[secret-token]', $string) ?? $string;
        $string = preg_replace_callback(
            '/[A-Z0-9._%+\\-]+@[A-Z0-9.\\-]+\\.[A-Z]{2,}/i',
            fn(array $matches): string => '[email:' . substr(hash('sha256', $this->workspaceId() . ':' . $matches[0]), 0, 12) . ']',
            $string
        ) ?? $string;

        return $string;
    }

    private function deriveLiveExecutionQueueOutcome(array $queue): array
    {
        $queueId = (int) ($queue['id'] ?? 0);
        $adapterKey = (string) ($queue['live_adapter_key'] ?? '');
        $queueStatus = (string) ($queue['status'] ?? '');
        $base = [
            'queue_id' => $queueId,
            'adapter_key' => $adapterKey,
            'queue_status' => $queueStatus,
            'source' => 'live_outcome_reconciliation',
            'checked_at' => date('c'),
            'secret_safe' => true,
        ];

        if ($adapterKey === 'crm_email_queue_handoff' && Database::tableExists('marketing_live_email_handoffs')) {
            $counts = Database::queryOne(
                "SELECT COUNT(*) AS total,
                        SUM(CASE WHEN status = 'sent' THEN 1 ELSE 0 END) AS sent_count,
                        SUM(CASE WHEN status = 'failed' THEN 1 ELSE 0 END) AS failed_count,
                        SUM(CASE WHEN status = 'blocked' THEN 1 ELSE 0 END) AS blocked_count,
                        SUM(CASE WHEN status = 'processing' THEN 1 ELSE 0 END) AS processing_count,
                        SUM(CASE WHEN status IN ('queued','reviewed') THEN 1 ELSE 0 END) AS queued_count,
                        SUM(CASE WHEN status = 'cancelled' THEN 1 ELSE 0 END) AS cancelled_count
                 FROM marketing_live_email_handoffs
                 WHERE workspace_id = ? AND queue_id = ?",
                [$this->workspaceId(), $queueId]
            ) ?: [];
            $total = (int) ($counts['total'] ?? 0);
            $sent = (int) ($counts['sent_count'] ?? 0);
            $failed = (int) ($counts['failed_count'] ?? 0);
            $blocked = (int) ($counts['blocked_count'] ?? 0);
            $processing = (int) ($counts['processing_count'] ?? 0);
            $queued = (int) ($counts['queued_count'] ?? 0);
            $cancelled = (int) ($counts['cancelled_count'] ?? 0);

            if ($total <= 0) {
                $status = $queueStatus === 'failed' ? 'failed' : ($queueStatus === 'blocked' ? 'blocked' : 'not_started');
            } elseif ($sent > 0 && $sent === $total) {
                $status = 'delivered';
            } elseif ($sent > 0 && ($failed > 0 || $blocked > 0 || $queued > 0 || $processing > 0 || $cancelled > 0)) {
                $status = 'partially_delivered';
            } elseif ($processing > 0) {
                $status = 'processing';
            } elseif ($queued > 0) {
                $status = 'queued';
            } elseif ($blocked > 0) {
                $status = 'blocked';
            } elseif ($cancelled > 0) {
                $status = 'cancelled';
            } else {
                $status = 'failed';
            }

            return $base + [
                'status' => $status,
                'handoff_counts' => [
                    'total' => $total,
                    'sent' => $sent,
                    'failed' => $failed,
                    'blocked' => $blocked,
                    'processing' => $processing,
                    'queued' => $queued,
                    'cancelled' => $cancelled,
                ],
            ];
        }

        if (in_array($adapterKey, ['crm_sms_queue_handoff', 'crm_whatsapp_queue_handoff'], true) && Database::tableExists('marketing_live_channel_handoffs')) {
            $executionType = $adapterKey === 'crm_sms_queue_handoff' ? 'sms' : 'whatsapp';
            $channelSync = $this->syncLiveChannelHandoffEvidenceForQueue($queue, $executionType);
            $counts = Database::queryOne(
                "SELECT COUNT(*) AS total,
                        SUM(CASE WHEN status = 'sent' THEN 1 ELSE 0 END) AS sent_count,
                        SUM(CASE WHEN status = 'failed' THEN 1 ELSE 0 END) AS failed_count,
                        SUM(CASE WHEN status = 'blocked' THEN 1 ELSE 0 END) AS blocked_count,
                        SUM(CASE WHEN status = 'processing' THEN 1 ELSE 0 END) AS processing_count,
                        SUM(CASE WHEN status = 'queued' THEN 1 ELSE 0 END) AS queued_count,
                        SUM(CASE WHEN status = 'cancelled' THEN 1 ELSE 0 END) AS cancelled_count
                 FROM marketing_live_channel_handoffs
                 WHERE workspace_id = ? AND queue_id = ? AND execution_type = ?",
                [$this->workspaceId(), $queueId, $executionType]
            ) ?: [];
            $total = (int) ($counts['total'] ?? 0);
            $sent = (int) ($counts['sent_count'] ?? 0);
            $failed = (int) ($counts['failed_count'] ?? 0);
            $blocked = (int) ($counts['blocked_count'] ?? 0);
            $processing = (int) ($counts['processing_count'] ?? 0);
            $queued = (int) ($counts['queued_count'] ?? 0);
            $cancelled = (int) ($counts['cancelled_count'] ?? 0);

            if ($total <= 0) {
                $status = $queueStatus === 'failed' ? 'failed' : ($queueStatus === 'blocked' ? 'blocked' : 'not_started');
            } elseif ($sent > 0 && $sent === $total) {
                $status = 'delivered';
            } elseif ($sent > 0 && ($failed > 0 || $blocked > 0 || $queued > 0 || $processing > 0 || $cancelled > 0)) {
                $status = 'partially_delivered';
            } elseif ($processing > 0) {
                $status = 'processing';
            } elseif ($queued > 0) {
                $status = 'queued';
            } elseif ($blocked > 0) {
                $status = 'blocked';
            } elseif ($cancelled > 0) {
                $status = 'cancelled';
            } else {
                $status = 'failed';
            }

            return $base + [
                'status' => $status,
                'execution_type' => $executionType,
                'channel_sync' => $channelSync,
                'handoff_counts' => [
                    'total' => $total,
                    'sent' => $sent,
                    'failed' => $failed,
                    'blocked' => $blocked,
                    'processing' => $processing,
                    'queued' => $queued,
                    'cancelled' => $cancelled,
                ],
            ];
        }

        if ($adapterKey === 'crm_outbound_webhook' && Database::tableExists('marketing_live_webhook_attempts')) {
            $attempt = Database::queryOne(
                "SELECT status, response_status_code, endpoint_host, endpoint_url_hash, attempted_at, error_message
                 FROM marketing_live_webhook_attempts
                 WHERE workspace_id = ? AND queue_id = ?
                 ORDER BY attempted_at DESC, id DESC
                 LIMIT 1",
                [$this->workspaceId(), $queueId]
            ) ?: [];
            $attemptStatus = (string) ($attempt['status'] ?? '');
            $status = match ($attemptStatus) {
                'sent' => 'delivered',
                'blocked' => 'blocked',
                'failed' => 'failed',
                default => $queueStatus === 'failed' ? 'failed' : ($queueStatus === 'succeeded' ? 'delivered' : 'unknown'),
            };

            return $base + [
                'status' => $status,
                'webhook_status' => $attemptStatus,
                'response_status_code' => $attempt['response_status_code'] ?? null,
                'endpoint_host' => (string) ($attempt['endpoint_host'] ?? ''),
                'endpoint_url_hash' => (string) ($attempt['endpoint_url_hash'] ?? ''),
                'attempted_at' => $attempt['attempted_at'] ?? null,
                'error_message' => (string) ($attempt['error_message'] ?? ''),
            ];
        }

        if ($adapterKey === 'crm_landing_publication' && Database::tableExists('marketing_landing_page_publications')) {
            $landingPageId = (int) ($queue['landing_page_id'] ?? 0);
            $publication = $landingPageId > 0
                ? (Database::queryOne(
                    "SELECT status, public_url, published_at, unpublished_at
                     FROM marketing_landing_page_publications
                     WHERE workspace_id = ? AND landing_page_id = ?
                     ORDER BY updated_at DESC, id DESC
                     LIMIT 1",
                    [$this->workspaceId(), $landingPageId]
                ) ?: [])
                : [];
            $publicationStatus = (string) ($publication['status'] ?? '');
            $status = match ($publicationStatus) {
                'published' => 'delivered',
                'unpublished' => 'cancelled',
                default => $queueStatus === 'failed' ? 'failed' : ($queueStatus === 'succeeded' ? 'delivered' : 'unknown'),
            };

            return $base + [
                'status' => $status,
                'landing_page_id' => $landingPageId,
                'publication_status' => $publicationStatus,
                'public_url' => (string) ($publication['public_url'] ?? ''),
                'published_at' => $publication['published_at'] ?? null,
                'unpublished_at' => $publication['unpublished_at'] ?? null,
            ];
        }

        $status = match ($queueStatus) {
            'succeeded' => 'delivered',
            'failed' => 'failed',
            'blocked' => 'blocked',
            'cancelled' => 'cancelled',
            'running' => 'processing',
            'queued', 'approved' => 'queued',
            default => 'not_started',
        };

        return $base + ['status' => $status];
    }

    private function liveRunControlReadiness(array $queue, array $input): array
    {
        $blocked = [];
        $confirmation = strtoupper(trim((string) ($input['live_confirmation'] ?? $input['live_confirmation_text'] ?? '')));
        $confirmationValid = $confirmation === 'RUN LIVE';
        if (!$confirmationValid) {
            $blocked[] = 'live_confirmation_required';
        }

        $queueId = (int) ($queue['id'] ?? 0);
        $successfulLiveAttempts = 0;
        if ($queueId > 0 && Database::tableExists('marketing_execution_attempts')) {
            $successfulLiveAttempts = (int) (Database::queryOne(
                "SELECT COUNT(*) AS count
                 FROM marketing_execution_attempts
                 WHERE workspace_id = ?
                   AND queue_id = ?
                   AND attempt_mode = 'live'
                   AND status = 'success'",
                [$this->workspaceId(), $queueId]
            )['count'] ?? 0);
        }

        $rerunPolicy = $this->normalizeEnum(
            (string) ($queue['live_rerun_policy'] ?? 'block_after_success'),
            self::LIVE_EXECUTION_RERUN_POLICIES,
            'live_execution_rerun_policy'
        );
        if ($successfulLiveAttempts > 0 && $rerunPolicy !== 'allow_manual_rerun') {
            $blocked[] = 'live_success_already_recorded';
        }

        $idempotencyKey = (string) ($queue['live_idempotency_key'] ?? '');
        if ($idempotencyKey === '') {
            $idempotencyKey = hash('sha256', $this->workspaceId() . ':' . (string) ($queue['uuid'] ?? $queueId));
        }

        return [
            'ready' => $blocked === [],
            'blocked_reasons' => array_values(array_unique($blocked)),
            'confirmation_required' => true,
            'confirmation_valid' => $confirmationValid,
            'confirmation_text' => $confirmationValid ? 'RUN LIVE' : '',
            'idempotency_key' => $idempotencyKey,
            'rerun_policy' => $rerunPolicy,
            'successful_live_attempts' => $successfulLiveAttempts,
        ];
    }

    private function liveEmailQueueReadiness(array $queue, array $policy): array
    {
        $blocked = [];
        $warnings = [];
        $runId = (int) ($queue['email_run_id'] ?? 0);
        $recipientCount = 0;

        if ((string) ($queue['execution_type'] ?? '') !== 'email') {
            $blocked[] = 'email_execution_type_required';
        }
        if ($runId <= 0) {
            $blocked[] = 'email_run_required';
        }

        $run = $runId > 0 ? $this->getEmailCampaignRun($runId) : null;
        if ($runId > 0 && !$run) {
            $blocked[] = 'email_run_not_found';
        }

        if ($run) {
            if (!in_array((string) ($run['status'] ?? 'draft'), ['ready', 'exported'], true)) {
                $blocked[] = 'email_run_not_ready';
            }
            if ((string) ($run['approval_status'] ?? 'not_requested') !== 'approved') {
                $blocked[] = 'email_run_approval_required';
            }
            if ((string) ($run['consent_status'] ?? 'not_reviewed') !== 'approved') {
                $blocked[] = 'email_consent_not_approved';
            }
            if (trim((string) ($run['subject'] ?? '')) === '') {
                $blocked[] = 'email_subject_required';
            }
            if (trim((string) ($run['body_snapshot'] ?? '')) === '') {
                $blocked[] = 'email_body_required';
            }
            if (trim((string) ($run['unsubscribe_text'] ?? '')) === '') {
                $blocked[] = 'email_unsubscribe_required';
            }
            if (!empty($run['safety_warnings_json'])) {
                $blocked[] = 'email_safety_warnings_present';
            }
            $readinessWarnings = (array) ($run['readiness_warnings_json'] ?? []);
            if ($readinessWarnings !== []) {
                $warnings[] = 'email_readiness_warnings_present';
            }

            $recipients = $this->resolveLiveEmailRecipients($run, $queue);
            $recipientCount = count($recipients);
            if ($recipientCount <= 0) {
                $blocked[] = 'email_recipients_required';
            }
            $dailyCap = (int) ($policy['daily_live_cap'] ?? 0);
            if ($dailyCap > 0 && $recipientCount > 0) {
                $usedToday = $this->countMarketingLiveEmailHandoffsToday();
                if (($usedToday + $recipientCount) > $dailyCap) {
                    $blocked[] = 'daily_live_cap_exceeded';
                }
            }
            if (Database::tableExists('marketing_live_email_handoffs')) {
                $existingHandoffs = (int) (Database::queryOne(
                    "SELECT COUNT(*) AS count
                     FROM marketing_live_email_handoffs
                     WHERE workspace_id = ?
                       AND queue_id = ?
                       AND email_run_id = ?
                       AND status = 'queued'",
                    [$this->workspaceId(), (int) ($queue['id'] ?? 0), $runId]
                )['count'] ?? 0);
                if ($existingHandoffs > 0) {
                    $blocked[] = 'email_handoff_already_queued';
                }
            }
        }

        return [
            'blocked_reasons' => array_values(array_unique($blocked)),
            'warnings' => array_values(array_unique($warnings)),
            'email_run_id' => $runId,
            'recipient_count' => $recipientCount,
        ];
    }

    private function liveMessagingQueueReadiness(array $queue, array $policy, string $channel): array
    {
        $channel = $this->normalizeEnum($channel, ['sms', 'whatsapp'], 'live_messaging_channel');
        $blocked = [];
        $warnings = [];
        $message = $this->liveMessagingPayloadMessage($queue, $channel);
        $recipients = $this->resolveLiveMessagingRecipients($queue, $channel);
        $payload = $this->decodeJsonLike($queue['payload_json'] ?? $queue['payload'] ?? []);

        if ((string) ($queue['execution_type'] ?? '') !== $channel) {
            $blocked[] = $channel . '_execution_type_required';
        }
        if ($message === '') {
            $blocked[] = $channel . '_message_required';
        }
        if ($recipients === []) {
            $blocked[] = $channel . '_recipients_required';
        }
        foreach ($recipients as $recipient) {
            $phone = trim((string) ($recipient['phone'] ?? ''));
            if ($phone === '') {
                $blocked[] = $channel . '_recipient_phone_required';
            } elseif ($this->isMarketingIdentifierSuppressed($channel, $phone)) {
                $blocked[] = $channel . '_recipient_suppressed';
            }
        }
        if ($channel === 'sms' && mb_strlen($message) > 320) {
            $warnings[] = 'sms_message_over_320_chars';
        }
        if ($channel === 'whatsapp' && empty($payload['template_name'])) {
            $outsideWindow = array_values(array_filter(
                $recipients,
                fn(array $recipient): bool => !$this->isWhatsAppMessagingWindowOpen((int) ($recipient['contact_id'] ?? 0))
            ));
            if ($outsideWindow !== []) {
                $blocked[] = 'whatsapp_template_required_outside_24h_window';
            }
        }
        if (empty($payload['consent_reviewed']) && empty($payload['opt_in_reviewed'])) {
            $warnings[] = $channel . '_consent_review_recommended';
        }
        if (!Database::tableExists('marketing_live_channel_handoffs')) {
            $blocked[] = 'live_channel_handoff_table_unavailable';
        } else {
            $existingHandoffs = (int) (Database::queryOne(
                "SELECT COUNT(*) AS count
                 FROM marketing_live_channel_handoffs
                 WHERE workspace_id = ?
                   AND queue_id = ?
                   AND execution_type = ?
                   AND status IN ('queued','processing','sent')",
                [$this->workspaceId(), (int) ($queue['id'] ?? 0), $channel]
            )['count'] ?? 0);
            if ($existingHandoffs > 0) {
                $blocked[] = $channel . '_handoff_already_queued';
            }
        }
        $dailyCap = (int) ($policy['daily_live_cap'] ?? 0);
        if ($dailyCap > 0 && count($recipients) > 0 && Database::tableExists('marketing_live_channel_handoffs')) {
            $usedToday = (int) (Database::queryOne(
                "SELECT COUNT(*) AS count
                 FROM marketing_live_channel_handoffs
                 WHERE workspace_id = ?
                   AND execution_type = ?
                   AND status IN ('queued','processing','sent')
                   AND created_at >= CURRENT_DATE()",
                [$this->workspaceId(), $channel]
            )['count'] ?? 0);
            if (($usedToday + count($recipients)) > $dailyCap) {
                $blocked[] = 'daily_live_cap_exceeded';
            }
        }

        return [
            'blocked_reasons' => array_values(array_unique($blocked)),
            'warnings' => array_values(array_unique($warnings)),
            'execution_type' => $channel,
            'recipient_count' => count($recipients),
            'message_length' => mb_strlen($message),
            'queue_handoff_only' => true,
        ];
    }

    private function evaluateLiveConsentSuppression(array $queue, ?array $connector, string $adapterKey): array
    {
        $blocked = [];
        $warnings = [];
        $evidence = [
            'queue_id' => (int) ($queue['id'] ?? 0),
            'connector_id' => (int) ($connector['id'] ?? 0),
            'adapter_key' => $adapterKey,
            'checked_at' => date('c'),
            'secret_safe' => true,
            'raw_secret_values_visible' => false,
        ];
        $unsubscribeEvidence = [];
        $consentBasis = '';
        $suppressionResult = 'clear';

        if (!Database::tableExists('marketing_suppression_entries')) {
            $blocked[] = 'suppression_table_unavailable';
            $suppressionResult = 'blocked';
        }

        if ($adapterKey === 'crm_email_queue_handoff') {
            $runId = (int) ($queue['email_run_id'] ?? 0);
            $run = $runId > 0 ? $this->getEmailCampaignRun($runId) : null;
            $recipients = $run ? $this->resolveLiveEmailRecipients($run, $queue) : [];
            $unsubscribeText = trim((string) ($run['unsubscribe_text'] ?? ''));
            $consentBasis = trim((string) ($run['consent_basis'] ?? $run['consent_status'] ?? 'manual_review'));
            $unsubscribeEvidence = [
                'required' => true,
                'present' => $unsubscribeText !== '',
                'text_hash' => $unsubscribeText !== '' ? hash('sha256', $unsubscribeText) : null,
                'run_id' => $runId,
                'raw_unsubscribe_text_visible' => false,
            ];
            if (!$run) {
                $blocked[] = 'email_run_required_for_consent_check';
            }
            if ($unsubscribeText === '') {
                $blocked[] = 'email_unsubscribe_text_required';
                $suppressionResult = 'blocked';
            }
            $suppressed = [];
            foreach ($recipients as $recipient) {
                $email = strtolower(trim((string) ($recipient['email'] ?? '')));
                if ($email !== '' && $this->isMarketingIdentifierSuppressed('email', $email)) {
                    $suppressed[] = $this->recipientPreview($email);
                }
            }
            if ($suppressed !== []) {
                $blocked[] = 'email_recipient_suppressed';
                $suppressionResult = 'blocked';
            }
            $evidence += [
                'channel' => 'email',
                'recipient_count' => count($recipients),
                'suppressed_recipient_count' => count($suppressed),
                'suppressed_recipient_previews' => array_slice($suppressed, 0, 10),
                'consent_status' => (string) ($run['consent_status'] ?? 'not_reviewed'),
                'suppression_list_checked_at' => $run['suppression_list_checked_at'] ?? null,
            ];
            if ((string) ($run['consent_status'] ?? '') !== 'approved') {
                $warnings[] = 'email_consent_status_not_approved';
            }
        } elseif (in_array($adapterKey, ['crm_sms_queue_handoff', 'crm_whatsapp_queue_handoff'], true)) {
            $channel = $adapterKey === 'crm_sms_queue_handoff' ? 'sms' : 'whatsapp';
            $payload = $this->decodeJsonLike($queue['payload_json'] ?? $queue['payload'] ?? []);
            $recipients = $this->resolveLiveMessagingRecipients($queue, $channel);
            $consentBasis = trim((string) ($payload['consent_basis'] ?? ($payload['consent_reviewed'] ?? false ? 'manual_review' : '')));
            $suppressed = [];
            $outsideWindow = [];
            foreach ($recipients as $recipient) {
                $phone = trim((string) ($recipient['phone'] ?? ''));
                if ($phone !== '' && $this->isMarketingIdentifierSuppressed($channel, $phone)) {
                    $suppressed[] = $this->recipientPreview($phone);
                }
                if ($channel === 'whatsapp' && empty($payload['template_name']) && !$this->isWhatsAppMessagingWindowOpen((int) ($recipient['contact_id'] ?? 0))) {
                    $outsideWindow[] = $this->recipientPreview($phone);
                }
            }
            if ($suppressed !== []) {
                $blocked[] = $channel . '_recipient_suppressed';
                $suppressionResult = 'blocked';
            }
            if ($channel === 'whatsapp' && $outsideWindow !== []) {
                $blocked[] = 'whatsapp_template_required_outside_24h_window';
                $suppressionResult = 'blocked';
            }
            if ($consentBasis === '') {
                $warnings[] = $channel . '_consent_basis_missing';
                if ($suppressionResult !== 'blocked') {
                    $suppressionResult = 'warning';
                }
            }
            $evidence += [
                'channel' => $channel,
                'recipient_count' => count($recipients),
                'suppressed_recipient_count' => count($suppressed),
                'suppressed_recipient_previews' => array_slice($suppressed, 0, 10),
                'whatsapp_template_name_present' => $channel === 'whatsapp' ? !empty($payload['template_name']) : null,
                'whatsapp_outside_window_count' => count($outsideWindow),
                'whatsapp_outside_window_previews' => array_slice($outsideWindow, 0, 10),
            ];
        } else {
            $warnings[] = 'live_consent_suppression_not_applicable';
            $suppressionResult = 'not_checked';
        }

        if ($suppressionResult === 'clear' && $blocked !== []) {
            $suppressionResult = 'blocked';
        }

        return [
            'ready' => $blocked === [],
            'blocked_reasons' => array_values(array_unique($blocked)),
            'warnings' => array_values(array_unique($warnings)),
            'suppression_result' => $suppressionResult,
            'consent_basis' => $consentBasis !== '' ? mb_substr(Security::sanitizeInput($consentBasis, 'string'), 0, 120) : null,
            'unsubscribe_evidence' => $unsubscribeEvidence,
            'evidence' => $evidence,
        ];
    }

    private function defaultMarketingLiveExecutionPolicy(): array
    {
        return [
            'status' => 'disabled',
            'live_execution_enabled' => false,
            'require_manage_approval' => true,
            'allowed_connector_types_json' => ['email', 'sms', 'whatsapp', 'website_webhook'],
            'allowed_adapter_keys_json' => ['crm_email_queue_handoff', 'crm_sms_queue_handoff', 'crm_whatsapp_queue_handoff', 'crm_internal_webhook', 'crm_landing_publication', 'crm_outbound_webhook'],
            'daily_live_cap' => 0,
            'emergency_paused' => false,
            'emergency_paused_at' => null,
            'emergency_paused_by' => null,
            'emergency_pause_reason' => null,
            'emergency_resumed_at' => null,
            'emergency_resumed_by' => null,
            'safety_checklist_json' => [
                'Workspace owner has enabled live execution.',
                'Connector has a verified secret reference.',
                'Connector live preflight has passed.',
                'Queue item has explicit approval.',
                'Adapter is available and scoped to this CRM workspace.',
                'Live email handoffs use the CRM email queue and never expose provider secrets.',
                'Live SMS and WhatsApp handoffs use CRM channel queues after consent and suppression review.',
            ],
            'metadata_json' => [
                'source' => 'default_live_execution_policy',
                'raw_secret_values_visible' => false,
            ],
        ];
    }

    private function ensureMarketingLiveExecutionPolicyExists(?int $actorId = null): void
    {
        if (!Database::tableExists('marketing_live_execution_policies')) {
            return;
        }
        $existing = Database::queryOne(
            "SELECT id FROM marketing_live_execution_policies WHERE workspace_id = ? LIMIT 1",
            [$this->workspaceId()]
        );
        if ($existing) {
            return;
        }

        $defaults = $this->defaultMarketingLiveExecutionPolicy();
        Database::execute(
            "INSERT INTO marketing_live_execution_policies
             (workspace_id, uuid, status, live_execution_enabled, require_manage_approval, allowed_connector_types_json,
              allowed_adapter_keys_json, daily_live_cap, safety_checklist_json, metadata_json, created_by, updated_by)
             VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)",
            [
                $this->workspaceId(),
                $this->generateUuid(),
                $defaults['status'],
                !empty($defaults['live_execution_enabled']) ? 1 : 0,
                !empty($defaults['require_manage_approval']) ? 1 : 0,
                $this->normalizeJsonValue((array) $defaults['allowed_connector_types_json']),
                $this->normalizeJsonValue((array) $defaults['allowed_adapter_keys_json']),
                (int) $defaults['daily_live_cap'],
                $this->normalizeJsonValue((array) $defaults['safety_checklist_json']),
                $this->normalizeJsonValue((array) $defaults['metadata_json']),
                $actorId ?: null,
                $actorId ?: null,
            ]
        );
    }

    private function normalizeMarketingLiveExecutionPolicyData(array $data): array
    {
        $status = $this->normalizeEnum((string) ($data['status'] ?? 'disabled'), self::LIVE_EXECUTION_POLICY_STATUSES, 'live_execution_policy_status');
        $enabled = !empty($data['live_execution_enabled']) && $status !== 'disabled' && $status !== 'blocked';
        $allowedTypes = $this->normalizeStringList($data['allowed_connector_types'] ?? $data['allowed_connector_types_json'] ?? ['email', 'website_webhook']);
        $allowedTypes = array_values(array_intersect($allowedTypes, self::CHANNEL_CONNECTOR_TYPES));
        if ($allowedTypes === []) {
            $allowedTypes = ['email', 'website_webhook'];
        }
        $allowedAdapters = $this->normalizeStringList($data['allowed_adapter_keys'] ?? $data['allowed_adapter_keys_json'] ?? self::LIVE_EXECUTION_ADAPTER_KEYS);
        $allowedAdapters = array_values(array_intersect($allowedAdapters, self::LIVE_EXECUTION_ADAPTER_KEYS));
        if ($allowedAdapters === []) {
            $allowedAdapters = self::LIVE_EXECUTION_ADAPTER_KEYS;
        }

        return [
            'status' => $status,
            'live_execution_enabled' => $enabled ? 1 : 0,
            'require_manage_approval' => !empty($data['require_manage_approval']) ? 1 : 0,
            'allowed_connector_types_json' => $this->normalizeJsonValue($allowedTypes),
            'allowed_adapter_keys_json' => $this->normalizeJsonValue($allowedAdapters),
            'daily_live_cap' => max(0, min(100000, (int) ($data['daily_live_cap'] ?? 0))),
            'safety_checklist_json' => $this->normalizeStringListJson($data['safety_checklist'] ?? $data['safety_checklist_json'] ?? []),
            'metadata_json' => $this->normalizeJsonValue($this->sanitizeJsonCompatible($data['metadata'] ?? $data['metadata_json'] ?? [
                'raw_secret_values_visible' => false,
                'external_execution_requires_adapter' => true,
            ])),
        ];
    }

    /**
     * @return string[]
     */
    private function normalizeStringList(mixed $value): array
    {
        if (is_string($value)) {
            $decoded = json_decode($value, true);
            $value = is_array($decoded) ? $decoded : preg_split('/[,\\r\\n]+/', $value);
        }
        $items = [];
        foreach ((array) $value as $item) {
            $item = preg_replace('/[^a-z0-9_]/', '', strtolower((string) $item)) ?: '';
            if ($item !== '') {
                $items[] = $item;
            }
        }

        return array_values(array_unique($items));
    }

    private function liveExecutionPolicySnapshot(array $policy): array
    {
        return [
            'status' => (string) ($policy['status'] ?? 'disabled'),
            'live_execution_enabled' => !empty($policy['live_execution_enabled']),
            'require_manage_approval' => !empty($policy['require_manage_approval']),
            'allowed_connector_types' => (array) ($policy['allowed_connector_types_json'] ?? []),
            'allowed_adapter_keys' => (array) ($policy['allowed_adapter_keys_json'] ?? []),
            'daily_live_cap' => (int) ($policy['daily_live_cap'] ?? 0),
            'emergency_paused' => !empty($policy['emergency_paused']),
            'emergency_paused_at' => $policy['emergency_paused_at'] ?? null,
            'emergency_pause_reason' => isset($policy['emergency_pause_reason'])
                ? mb_substr(Security::sanitizeInput((string) $policy['emergency_pause_reason'], 'string'), 0, 500)
                : null,
            'raw_secret_values_visible' => false,
        ];
    }

    private function recordLiveExecutionEvent(string $eventType, string $status, array $data = []): void
    {
        if (!Database::tableExists('marketing_live_execution_events')) {
            return;
        }

        Database::execute(
            "INSERT INTO marketing_live_execution_events
             (workspace_id, uuid, connector_id, queue_id, event_type, status, execution_mode, adapter_key,
              payload_json, result_json, metadata_json, created_by)
             VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)",
            [
                $this->workspaceId(),
                $this->generateUuid(),
                !empty($data['connector_id']) ? (int) $data['connector_id'] : null,
                !empty($data['queue_id']) ? (int) $data['queue_id'] : null,
                $this->normalizeEnum($eventType, ['policy_updated', 'readiness_checked', 'live_blocked', 'live_attempt_recorded', 'adapter_missing', 'adapter_ready', 'live_succeeded', 'live_failed'], 'live_event_type'),
                $this->normalizeEnum($status, ['info', 'ready', 'blocked', 'success', 'failed'], 'live_event_status'),
                $this->normalizeEnum((string) ($data['execution_mode'] ?? 'live'), self::EXECUTION_MODES, 'execution_mode'),
                ($data['adapter_key'] ?? '') !== '' ? Security::sanitizeInput((string) $data['adapter_key'], 'string') : null,
                $this->normalizeJsonValue($this->sanitizeJsonCompatible($data['payload'] ?? [])),
                $this->normalizeJsonValue($this->sanitizeJsonCompatible($data['result'] ?? [])),
                $this->normalizeJsonValue($this->sanitizeJsonCompatible($data['metadata'] ?? [])),
                (int) ($data['created_by'] ?? $this->currentUserId()) ?: null,
            ]
        );
    }

    private function executeMarketingLiveAdapter(array $queue, array $connector, array $input): array
    {
        $adapterKey = (string) ($connector['live_adapter_key'] ?? '');
        if (!in_array($adapterKey, self::LIVE_EXECUTION_ADAPTER_KEYS, true)) {
            return [
                'success' => false,
                'message' => 'Live adapter is not implemented.',
                'external_api_called' => false,
                'adapter_key' => $adapterKey,
            ];
        }

        if ($adapterKey === 'crm_email_queue_handoff') {
            return $this->executeMarketingEmailQueueHandoff($queue, $connector, $input);
        }

        if ($adapterKey === 'crm_sms_queue_handoff') {
            return $this->executeMarketingMessagingQueueHandoff($queue, $connector, $input, 'sms');
        }

        if ($adapterKey === 'crm_whatsapp_queue_handoff') {
            return $this->executeMarketingMessagingQueueHandoff($queue, $connector, $input, 'whatsapp');
        }

        if ($adapterKey === 'crm_landing_publication') {
            return $this->executeMarketingLandingPublication($queue, $connector, $input);
        }

        if ($adapterKey === 'crm_outbound_webhook') {
            return $this->executeMarketingOutboundWebhook($queue, $connector, $input);
        }

        return [
            'success' => true,
            'message' => 'CRM internal webhook adapter recorded a live execution event.',
            'adapter_key' => $adapterKey,
            'live_execution' => true,
            'external_api_called' => false,
            'third_party_delivery' => false,
            'queue_id' => (int) ($queue['id'] ?? 0),
            'connector_id' => (int) ($connector['id'] ?? 0),
            'idempotency_key' => (string) ($input['live_idempotency_key'] ?? $queue['live_idempotency_key'] ?? ''),
            'payload_preview' => $this->sanitizeVisibleConnectorPayload($input['payload'] ?? $queue['payload_json'] ?? []),
            'completed_at' => date('c'),
        ];
    }

    /**
     * @return array{adapter_key:?string,provider_reference:?string,failure_class:?string,duration_ms:int,request:array<string,mixed>,response:array<string,mixed>,contract:array<string,mixed>}
     */
    private function buildLiveAdapterAttemptEvidence(
        array $queue,
        array $connector,
        string $requestedMode,
        string $attemptStatus,
        array $readiness,
        array $liveControl,
        array $adapterResult,
        array $input,
        int $durationMs
    ): array {
        $adapterKey = $requestedMode === 'live'
            ? (string) (($connector['live_adapter_key'] ?? '') ?: ($readiness['adapter_key'] ?? ''))
            : null;
        $providerReference = $requestedMode === 'live'
            ? $this->liveAdapterProviderReference($adapterResult)
            : null;
        $failureClass = $requestedMode === 'live'
            ? $this->classifyLiveAdapterFailure($attemptStatus, $readiness, $adapterResult)
            : null;
        $idempotencyKey = $requestedMode === 'live'
            ? (string) (($liveControl['idempotency_key'] ?? '') ?: ($queue['live_idempotency_key'] ?? ''))
            : '';

        return [
            'adapter_key' => $adapterKey !== '' ? $adapterKey : null,
            'provider_reference' => $providerReference,
            'failure_class' => $failureClass,
            'duration_ms' => max(0, $durationMs),
            'request' => $this->sanitizeJsonCompatible([
                'queue_id' => (int) ($queue['id'] ?? 0),
                'connector_id' => !empty($connector['id']) ? (int) $connector['id'] : null,
                'execution_type' => (string) ($queue['execution_type'] ?? 'other'),
                'attempt_mode' => $requestedMode,
                'adapter_key' => (string) ($adapterKey ?? ''),
                'idempotency_key' => $idempotencyKey,
                'payload_preview' => $this->sanitizeVisibleConnectorPayload($input['payload'] ?? $queue['payload_json'] ?? []),
                'live_confirmation_provided' => trim((string) ($liveControl['confirmation_text'] ?? '')) !== '',
                'manager_permission_enforced' => $requestedMode === 'live',
            ]),
            'response' => $this->sanitizeJsonCompatible([
                'status' => $attemptStatus,
                'success' => $attemptStatus === 'success',
                'message' => (string) ($adapterResult['message'] ?? ''),
                'provider_reference' => (string) ($providerReference ?? ''),
                'adapter_result' => $this->sanitizeVisibleConnectorPayload($adapterResult),
                'failure_class' => (string) ($failureClass ?? ''),
                'duration_ms' => max(0, $durationMs),
            ]),
            'contract' => [
                'requires_live_policy' => true,
                'requires_ready_connector' => true,
                'requires_verified_secret_reference' => true,
                'requires_live_preflight' => true,
                'requires_execution_approval' => true,
                'requires_final_confirmation' => true,
                'requires_manager_permission' => true,
                'emergency_stop_respected' => true,
                'throttle_respected' => true,
                'secret_safe' => true,
                'raw_secret_values_visible' => false,
                'external_api_called' => !empty($adapterResult['external_api_called']),
                'third_party_delivery' => !empty($adapterResult['third_party_delivery']),
            ],
        ];
    }

    private function liveAdapterProviderReference(array $adapterResult): ?string
    {
        foreach (['provider_reference', 'provider_message_id', 'message_id'] as $field) {
            $value = trim((string) ($adapterResult[$field] ?? ''));
            if ($value !== '') {
                return mb_substr(Security::sanitizeInput($value, 'string'), 0, 255);
            }
        }
        if (!empty($adapterResult['webhook_attempt_id'])) {
            return 'webhook_attempt:' . (int) $adapterResult['webhook_attempt_id'];
        }
        foreach (['email_queue_ids' => 'email_queue', 'source_queue_ids' => 'channel_queue'] as $field => $prefix) {
            $ids = array_values(array_filter(array_map('intval', (array) ($adapterResult[$field] ?? []))));
            if ($ids !== []) {
                return mb_substr($prefix . ':' . implode(',', array_slice($ids, 0, 10)), 0, 255);
            }
        }
        if (!empty($adapterResult['summary']) && is_array($adapterResult['summary'])) {
            return $this->liveAdapterProviderReference((array) $adapterResult['summary']);
        }

        return null;
    }

    private function classifyLiveAdapterFailure(string $attemptStatus, array $readiness, array $adapterResult): ?string
    {
        if (in_array($attemptStatus, ['success', 'dry_run'], true)) {
            return null;
        }
        $reasons = array_values(array_unique(array_merge(
            (array) ($readiness['blocked_reasons'] ?? []),
            (array) ($adapterResult['blocked_reasons'] ?? [])
        )));
        $reasonText = implode(' ', $reasons) . ' ' . strtolower((string) ($adapterResult['message'] ?? ''));
        return match (true) {
            str_contains($reasonText, 'policy') => 'blocked_policy',
            str_contains($reasonText, 'emergency') => 'blocked_emergency_stop',
            str_contains($reasonText, 'approval') => 'blocked_approval',
            str_contains($reasonText, 'confirmation') => 'blocked_confirmation',
            str_contains($reasonText, 'preflight') => 'blocked_preflight',
            str_contains($reasonText, 'secret') => 'blocked_secret',
            str_contains($reasonText, 'throttle') || str_contains($reasonText, 'cap') => 'blocked_throttle',
            str_contains($reasonText, 'suppressed') || str_contains($reasonText, 'unsubscribe') => 'blocked_compliance',
            str_contains($reasonText, 'recipient') => 'recipient_validation_failed',
            str_contains($reasonText, 'adapter') => 'adapter_contract_failed',
            str_contains($reasonText, 'queue') || str_contains($reasonText, 'handoff') => 'queue_handoff_failed',
            !empty($adapterResult['external_api_called']) => 'provider_call_failed',
            $attemptStatus === 'blocked' => 'blocked_readiness',
            default => 'adapter_failed',
        };
    }

    private function executeMarketingOutboundWebhook(array $queue, array $connector, array $input): array
    {
        $webhook = $this->outboundWebhookConfig($connector);
        $payload = $this->sanitizeVisibleConnectorPayload($input['payload'] ?? $queue['payload_json'] ?? []);
        $requestPayload = [
            'workspace_id' => $this->workspaceId(),
            'queue_id' => (int) ($queue['id'] ?? 0),
            'execution_type' => (string) ($queue['execution_type'] ?? 'website_webhook'),
            'idempotency_key' => (string) ($input['live_idempotency_key'] ?? $queue['live_idempotency_key'] ?? ''),
            'payload' => $payload,
            'sent_at' => date('c'),
        ];
        $actorId = (int) ($input['created_by'] ?? $queue['requested_by'] ?? $this->currentUserId());

        if (!empty($webhook['blockers'])) {
            $attemptId = $this->recordLiveWebhookAttempt([
                'queue_id' => (int) ($queue['id'] ?? 0),
                'connector_id' => (int) ($connector['id'] ?? 0),
                'status' => 'blocked',
                'http_method' => (string) ($webhook['http_method'] ?? 'POST'),
                'endpoint_host' => (string) ($webhook['endpoint_host'] ?? ''),
                'endpoint_url_hash' => (string) ($webhook['endpoint_url_hash'] ?? ''),
                'request_headers' => (array) ($webhook['headers'] ?? []),
                'request_payload' => $requestPayload,
                'error_message' => 'Webhook blocked: ' . implode(', ', (array) $webhook['blockers']),
                'external_api_called' => false,
                'attempt_count' => 0,
                'metadata' => [
                    'blockers' => (array) $webhook['blockers'],
                'warnings' => (array) ($webhook['warnings'] ?? []),
                'secret' => (array) ($webhook['secret'] ?? []),
                'raw_secret_values_visible' => false,
            ],
                'created_by' => $actorId,
            ]);

            return [
                'success' => false,
                'message' => 'CRM outbound webhook adapter is blocked by connector safety checks.',
                'adapter_key' => 'crm_outbound_webhook',
                'live_execution' => true,
                'external_api_called' => false,
                'third_party_delivery' => false,
                'webhook_attempt_id' => $attemptId,
                'webhook_status' => 'blocked',
                'blocked_reasons' => (array) $webhook['blockers'],
                'endpoint_host' => (string) ($webhook['endpoint_host'] ?? ''),
                'endpoint_url_hash' => (string) ($webhook['endpoint_url_hash'] ?? ''),
                'secret_reference_resolved' => !empty($webhook['secret']['configured']),
            ];
        }

        $attemptsAllowed = ((int) ($webhook['max_retries'] ?? 0)) + 1;
        $lastResult = [
            'success' => false,
            'status_code' => null,
            'response_preview' => '',
            'error_message' => 'Webhook was not attempted.',
            'duration_ms' => 0,
        ];
        for ($attempt = 1; $attempt <= $attemptsAllowed; $attempt++) {
            $lastResult = $this->performOutboundWebhookRequest(
                (string) $webhook['endpoint_url'],
                (string) $webhook['http_method'],
                (array) $webhook['headers'],
                $requestPayload,
                (int) $webhook['timeout_seconds']
            );
            if (!empty($lastResult['success'])) {
                break;
            }
        }

        $status = !empty($lastResult['success']) ? 'sent' : 'failed';
        $attemptId = $this->recordLiveWebhookAttempt([
            'queue_id' => (int) ($queue['id'] ?? 0),
            'connector_id' => (int) ($connector['id'] ?? 0),
            'status' => $status,
            'http_method' => (string) ($webhook['http_method'] ?? 'POST'),
            'endpoint_host' => (string) ($webhook['endpoint_host'] ?? ''),
            'endpoint_url_hash' => (string) ($webhook['endpoint_url_hash'] ?? ''),
            'request_headers' => (array) ($webhook['headers'] ?? []),
            'request_payload' => $requestPayload,
            'response_status_code' => $lastResult['status_code'] ?? null,
            'response_preview' => (string) ($lastResult['response_preview'] ?? ''),
            'error_message' => (string) ($lastResult['error_message'] ?? ''),
            'duration_ms' => (int) ($lastResult['duration_ms'] ?? 0),
            'attempt_count' => $attemptsAllowed,
            'external_api_called' => true,
            'metadata' => [
                'warnings' => (array) ($webhook['warnings'] ?? []),
                'secret' => (array) ($webhook['secret'] ?? []),
                'timeout_seconds' => (int) ($webhook['timeout_seconds'] ?? 5),
                'max_retries' => (int) ($webhook['max_retries'] ?? 0),
                'raw_secret_values_visible' => false,
            ],
            'created_by' => $actorId,
        ]);

        return [
            'success' => $status === 'sent',
            'message' => $status === 'sent'
                ? 'CRM outbound webhook adapter completed an allowlisted HTTP handoff.'
                : 'CRM outbound webhook adapter attempted the allowlisted HTTP handoff but it failed.',
            'adapter_key' => 'crm_outbound_webhook',
            'live_execution' => true,
            'external_api_called' => true,
            'third_party_delivery' => false,
            'webhook_attempt_id' => $attemptId,
            'webhook_status' => $status,
            'endpoint_host' => (string) ($webhook['endpoint_host'] ?? ''),
            'endpoint_url_hash' => (string) ($webhook['endpoint_url_hash'] ?? ''),
            'secret_reference_resolved' => !empty($webhook['secret']['configured']),
            'response_status_code' => $lastResult['status_code'] ?? null,
            'duration_ms' => (int) ($lastResult['duration_ms'] ?? 0),
        ];
    }

    private function performOutboundWebhookRequest(string $url, string $method, array $headers, array $payload, int $timeoutSeconds): array
    {
        $started = microtime(true);
        $body = json_encode($this->sanitizeJsonCompatible($payload), JSON_UNESCAPED_SLASHES) ?: '{}';
        $headerLines = [];
        foreach ($headers as $name => $value) {
            $headerLines[] = $name . ': ' . $value;
        }

        try {
            if (function_exists('curl_init')) {
                $ch = curl_init($url);
                curl_setopt($ch, CURLOPT_RETURNTRANSFER, true);
                curl_setopt($ch, CURLOPT_CUSTOMREQUEST, $method);
                curl_setopt($ch, CURLOPT_TIMEOUT, $timeoutSeconds);
                curl_setopt($ch, CURLOPT_CONNECTTIMEOUT, $timeoutSeconds);
                curl_setopt($ch, CURLOPT_HTTPHEADER, $headerLines);
                if ($method !== 'GET') {
                    curl_setopt($ch, CURLOPT_POSTFIELDS, $body);
                }
                $responseBody = curl_exec($ch);
                $error = curl_error($ch);
                $statusCode = (int) curl_getinfo($ch, CURLINFO_RESPONSE_CODE);
                curl_close($ch);

                return [
                    'success' => $error === '' && $statusCode >= 200 && $statusCode < 300,
                    'status_code' => $statusCode > 0 ? $statusCode : null,
                    'response_preview' => mb_substr(Security::sanitizeInput((string) $responseBody, 'string'), 0, 1000),
                    'error_message' => $error !== '' ? mb_substr(Security::sanitizeInput($error, 'string'), 0, 500) : '',
                    'duration_ms' => (int) round((microtime(true) - $started) * 1000),
                ];
            }

            $context = stream_context_create([
                'http' => [
                    'method' => $method,
                    'header' => implode("\r\n", $headerLines),
                    'content' => $method !== 'GET' ? $body : '',
                    'timeout' => $timeoutSeconds,
                    'ignore_errors' => true,
                ],
            ]);
            $responseBody = @file_get_contents($url, false, $context);
            $statusCode = null;
            foreach (($http_response_header ?? []) as $header) {
                if (preg_match('/^HTTP\/\S+\s+(\d+)/', (string) $header, $matches)) {
                    $statusCode = (int) $matches[1];
                    break;
                }
            }

            return [
                'success' => $responseBody !== false && $statusCode !== null && $statusCode >= 200 && $statusCode < 300,
                'status_code' => $statusCode,
                'response_preview' => mb_substr(Security::sanitizeInput((string) $responseBody, 'string'), 0, 1000),
                'error_message' => $responseBody === false ? 'HTTP request failed.' : '',
                'duration_ms' => (int) round((microtime(true) - $started) * 1000),
            ];
        } catch (Throwable $e) {
            return [
                'success' => false,
                'status_code' => null,
                'response_preview' => '',
                'error_message' => mb_substr(Security::sanitizeInput($e->getMessage(), 'string'), 0, 500),
                'duration_ms' => (int) round((microtime(true) - $started) * 1000),
            ];
        }
    }

    private function recordLiveWebhookAttempt(array $data): int
    {
        if (!Database::tableExists('marketing_live_webhook_attempts')) {
            return 0;
        }

        Database::execute(
            "INSERT INTO marketing_live_webhook_attempts
             (workspace_id, uuid, queue_id, connector_id, adapter_key, provider_reference, failure_class, status, http_method, endpoint_host, endpoint_url_hash,
               request_headers_json, request_payload_json, response_status_code, response_preview, error_message,
               duration_ms, attempt_count, external_api_called, third_party_delivery, metadata_json, attempted_at, created_by)
              VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, NOW(), ?)",
            [
                $this->workspaceId(),
                $this->generateUuid(),
                !empty($data['queue_id']) ? (int) $data['queue_id'] : null,
                !empty($data['connector_id']) ? (int) $data['connector_id'] : null,
                ($data['adapter_key'] ?? '') !== '' ? mb_substr(Security::sanitizeInput((string) $data['adapter_key'], 'string'), 0, 120) : 'crm_outbound_webhook',
                ($data['provider_reference'] ?? '') !== '' ? mb_substr(Security::sanitizeInput((string) $data['provider_reference'], 'string'), 0, 255) : null,
                ($data['failure_class'] ?? '') !== '' ? mb_substr(Security::sanitizeInput((string) $data['failure_class'], 'string'), 0, 80) : null,
                $this->normalizeEnum((string) ($data['status'] ?? 'failed'), ['pending', 'sent', 'failed', 'blocked'], 'live_webhook_attempt_status'),
                mb_substr(Security::sanitizeInput((string) ($data['http_method'] ?? 'POST'), 'string'), 0, 12),
                ($data['endpoint_host'] ?? '') !== '' ? mb_substr(Security::sanitizeInput((string) $data['endpoint_host'], 'string'), 0, 190) : null,
                ($data['endpoint_url_hash'] ?? '') !== '' ? (string) $data['endpoint_url_hash'] : null,
                $this->normalizeJsonValue($this->sanitizeVisibleConnectorPayload($data['request_headers'] ?? [])),
                $this->normalizeJsonValue($this->sanitizeVisibleConnectorPayload($data['request_payload'] ?? [])),
                isset($data['response_status_code']) ? (int) $data['response_status_code'] : null,
                ($data['response_preview'] ?? '') !== '' ? mb_substr(Security::sanitizeInput((string) $data['response_preview'], 'string'), 0, 1000) : null,
                ($data['error_message'] ?? '') !== '' ? mb_substr(Security::sanitizeInput((string) $data['error_message'], 'string'), 0, 1000) : null,
                isset($data['duration_ms']) ? max(0, (int) $data['duration_ms']) : null,
                max(0, (int) ($data['attempt_count'] ?? 1)),
                !empty($data['external_api_called']) ? 1 : 0,
                !empty($data['third_party_delivery']) ? 1 : 0,
                $this->normalizeJsonValue($this->sanitizeJsonCompatible($data['metadata'] ?? [])),
                (int) ($data['created_by'] ?? $this->currentUserId()) ?: null,
            ]
        );

        return (int) Database::lastInsertId();
    }

    private function executeMarketingLandingPublication(array $queue, array $connector, array $input): array
    {
        $payload = $this->decodeJsonLike($input['payload'] ?? $queue['payload_json'] ?? []);
        $landingPageId = (int) ($queue['landing_page_id'] ?? $payload['landing_page_id'] ?? 0);
        if ($landingPageId <= 0) {
            return [
                'success' => false,
                'message' => 'A workspace landing page is required for the CRM landing publication adapter.',
                'adapter_key' => 'crm_landing_publication',
                'live_execution' => true,
                'external_api_called' => false,
                'third_party_delivery' => false,
                'landing_publication_changed' => false,
            ];
        }

        $page = $this->getLandingPage($landingPageId);
        if (!$page) {
            return [
                'success' => false,
                'message' => 'Marketing landing page was not found in the active workspace.',
                'adapter_key' => 'crm_landing_publication',
                'live_execution' => true,
                'external_api_called' => false,
                'third_party_delivery' => false,
                'landing_publication_changed' => false,
            ];
        }

        $action = $this->normalizeEnum((string) ($payload['publication_action'] ?? $payload['action'] ?? 'publish'), ['publish', 'unpublish'], 'landing_publication_action');
        $actorId = (int) ($input['created_by'] ?? $queue['requested_by'] ?? $this->currentUserId());
        try {
            if ($action === 'unpublish') {
                $this->unpublishLandingPage($landingPageId, $actorId > 0 ? $actorId : null);
                $publication = $this->getLandingPagePublication($landingPageId) ?? [];

                return [
                    'success' => true,
                    'message' => 'CRM landing publication adapter unpublished the tokenized landing page.',
                    'adapter_key' => 'crm_landing_publication',
                    'live_execution' => true,
                    'external_api_called' => false,
                    'third_party_delivery' => false,
                    'landing_publication_changed' => true,
                    'publication_action' => 'unpublish',
                    'landing_page_id' => $landingPageId,
                    'publication_status' => (string) ($publication['status'] ?? 'unpublished'),
                    'public_url' => (string) ($publication['public_url'] ?? ''),
                    'public_token_present' => !empty($publication['public_token']),
                    'queue_id' => (int) ($queue['id'] ?? 0),
                    'connector_id' => (int) ($connector['id'] ?? 0),
                    'idempotency_key' => (string) ($input['live_idempotency_key'] ?? $queue['live_idempotency_key'] ?? ''),
                    'completed_at' => date('c'),
                ];
            }

            $publication = $this->publishLandingPage($landingPageId, $actorId > 0 ? $actorId : null);

            return [
                'success' => true,
                'message' => 'CRM landing publication adapter published the tokenized landing page.',
                'adapter_key' => 'crm_landing_publication',
                'live_execution' => true,
                'external_api_called' => false,
                'third_party_delivery' => false,
                'landing_publication_changed' => true,
                'publication_action' => 'publish',
                'landing_page_id' => $landingPageId,
                'publication_status' => (string) ($publication['status'] ?? 'published'),
                'public_url' => (string) ($publication['public_url'] ?? ''),
                'public_token_present' => !empty($publication['public_token']),
                'queue_id' => (int) ($queue['id'] ?? 0),
                'connector_id' => (int) ($connector['id'] ?? 0),
                'idempotency_key' => (string) ($input['live_idempotency_key'] ?? $queue['live_idempotency_key'] ?? ''),
                'completed_at' => date('c'),
            ];
        } catch (Throwable $e) {
            return [
                'success' => false,
                'message' => $e->getMessage(),
                'adapter_key' => 'crm_landing_publication',
                'live_execution' => true,
                'external_api_called' => false,
                'third_party_delivery' => false,
                'landing_publication_changed' => false,
                'publication_action' => $action,
                'landing_page_id' => $landingPageId,
                'queue_id' => (int) ($queue['id'] ?? 0),
                'connector_id' => (int) ($connector['id'] ?? 0),
                'idempotency_key' => (string) ($input['live_idempotency_key'] ?? $queue['live_idempotency_key'] ?? ''),
                'completed_at' => date('c'),
            ];
        }
    }

    private function executeMarketingMessagingQueueHandoff(array $queue, array $connector, array $input, string $channel): array
    {
        $channel = $this->normalizeEnum($channel, ['sms', 'whatsapp'], 'live_messaging_channel');
        $adapterKey = $channel === 'sms' ? 'crm_sms_queue_handoff' : 'crm_whatsapp_queue_handoff';
        if (!Database::tableExists('marketing_live_channel_handoffs')) {
            return [
                'success' => false,
                'message' => 'Marketing live channel handoff table is unavailable.',
                'adapter_key' => $adapterKey,
                'external_api_called' => false,
            ];
        }

        $policy = $this->getMarketingLiveExecutionPolicy();
        $readiness = $this->liveMessagingQueueReadiness($queue, $policy, $channel);
        $blockers = (array) ($readiness['blocked_reasons'] ?? []);
        if ($blockers !== []) {
            return [
                'success' => false,
                'message' => 'Live ' . strtoupper($channel) . ' queue handoff is blocked: ' . implode(', ', $blockers),
                'adapter_key' => $adapterKey,
                'blocked_reasons' => $blockers,
                'external_api_called' => false,
            ];
        }

        $payload = $this->decodeJsonLike($input['payload'] ?? $queue['payload_json'] ?? []);
        $message = $this->liveMessagingPayloadMessage($queue, $channel);
        $recipients = $this->resolveLiveMessagingRecipients($queue, $channel);
        $actorId = (int) ($input['created_by'] ?? $queue['requested_by'] ?? $this->currentUserId()) ?: null;
        $queued = [];
        $failed = [];
        $blocked = [];

        foreach ($recipients as $recipient) {
            $contactId = (int) ($recipient['contact_id'] ?? 0);
            $recipientValue = trim((string) ($recipient['phone'] ?? ''));
            if ($contactId <= 0 || $recipientValue === '') {
                $failed[] = ['contact_id' => $contactId, 'recipient_identifier' => $recipientValue, 'error' => 'Recipient contact or phone is invalid.'];
                continue;
            }
            if ($this->isMarketingIdentifierSuppressed($channel, $recipientValue)) {
                $handoffId = $this->recordMarketingLiveChannelHandoff($queue, $connector, [
                    'execution_type' => $channel,
                    'contact_id' => $contactId,
                    'recipient_identifier' => $recipientValue,
                    'source_table' => $channel === 'sms' ? 'sms_messages' : 'whatsapp_messages',
                    'status' => 'blocked',
                    'error_message' => 'Recipient is on the active Marketing suppression list.',
                    'metadata' => [
                        'reason' => 'suppressed_recipient',
                        'live_idempotency_key' => (string) ($input['live_idempotency_key'] ?? $queue['live_idempotency_key'] ?? ''),
                    ],
                    'created_by' => $actorId,
                ]);
                $blocked[] = ['handoff_id' => $handoffId, 'contact_id' => $contactId, 'recipient_identifier' => $recipientValue, 'reason' => 'suppressed_recipient'];
                continue;
            }

            try {
                if ($channel === 'sms') {
                    $service = new SMSService();
                    $uuid = $service->storeMessage($contactId, $recipientValue, $message, [
                        'workspace_id' => $this->workspaceId(),
                        'user_id' => $actorId,
                        'scheduled_at' => $this->normalizeDateTime((string) ($queue['scheduled_at'] ?? '')),
                        'priority' => 5,
                        'media_url' => $payload['media_url'] ?? null,
                        'idempotency_key' => 'marketing-live:' . (string) ($input['live_idempotency_key'] ?? $queue['live_idempotency_key'] ?? $handoffId) . ':' . $contactId,
                        'consent_confirmed_at' => date('Y-m-d H:i:s'),
                        'consent_source' => 'marketing_live_governance',
                    ]);
                    $messageRow = Database::queryOne(
                        "SELECT id, status
                         FROM sms_messages
                         WHERE workspace_id = ? AND uuid = ?
                         LIMIT 1",
                        [$this->workspaceId(), $uuid]
                    ) ?: [];
                    $sourceTable = 'sms_messages';
                    $sourceMessageId = (int) ($messageRow['id'] ?? 0);
                    $sourceQueueId = $sourceMessageId > 0
                        ? (int) (Database::queryOne(
                            "SELECT id FROM sms_queue WHERE workspace_id = ? AND message_id = ? ORDER BY id DESC LIMIT 1",
                            [$this->workspaceId(), $sourceMessageId]
                        )['id'] ?? 0)
                        : 0;
                } else {
                    $service = new WhatsAppService();
                    $messageType = !empty($payload['template_name']) ? 'template' : 'text';
                    $uuid = $service->storeMessage($contactId, $recipientValue, $messageType, $message, [
                        'workspace_id' => $this->workspaceId(),
                        'user_id' => $actorId,
                        'priority' => 5,
                        'scheduled_at' => $this->normalizeDateTime((string) ($queue['scheduled_at'] ?? '')),
                        'template_name' => $payload['template_name'] ?? null,
                        'template_params' => $payload['template_params'] ?? null,
                    ]);
                    $messageRow = Database::queryOne(
                        "SELECT id, status
                         FROM whatsapp_messages
                         WHERE workspace_id = ? AND uuid = ?
                         LIMIT 1",
                        [$this->workspaceId(), $uuid]
                    ) ?: [];
                    $sourceTable = 'whatsapp_messages';
                    $sourceMessageId = (int) ($messageRow['id'] ?? 0);
                    $sourceQueueId = $sourceMessageId > 0
                        ? (int) (Database::queryOne(
                            "SELECT id FROM whatsapp_queue WHERE workspace_id = ? AND message_id = ? ORDER BY id DESC LIMIT 1",
                            [$this->workspaceId(), $sourceMessageId]
                        )['id'] ?? 0)
                        : 0;
                }

                if ($sourceMessageId <= 0 || $sourceQueueId <= 0) {
                    throw new RuntimeException('The CRM ' . strtoupper($channel) . ' queue row was not created.');
                }

                $handoffId = $this->recordMarketingLiveChannelHandoff($queue, $connector, [
                    'execution_type' => $channel,
                    'contact_id' => $contactId,
                    'recipient_identifier' => $recipientValue,
                    'source_table' => $sourceTable,
                    'source_message_id' => $sourceMessageId,
                    'source_queue_id' => $sourceQueueId,
                    'status' => 'queued',
                    'metadata' => [
                        'queue_handoff_only' => true,
                        'external_provider_called_by_marketing' => false,
                        'live_idempotency_key' => (string) ($input['live_idempotency_key'] ?? $queue['live_idempotency_key'] ?? ''),
                    ],
                    'created_by' => $actorId,
                ]);
                $queued[] = [
                    'handoff_id' => $handoffId,
                    'contact_id' => $contactId,
                    'recipient_identifier' => $recipientValue,
                    'source_message_id' => $sourceMessageId,
                    'source_queue_id' => $sourceQueueId,
                ];
            } catch (Throwable $e) {
                $error = mb_substr(trim((string) $e->getMessage()) ?: 'Live channel queue handoff failed.', 0, 500);
                $handoffId = $this->recordMarketingLiveChannelHandoff($queue, $connector, [
                    'execution_type' => $channel,
                    'contact_id' => $contactId,
                    'recipient_identifier' => $recipientValue,
                    'source_table' => $channel === 'sms' ? 'sms_messages' : 'whatsapp_messages',
                    'status' => 'failed',
                    'error_message' => $error,
                    'metadata' => [
                        'queue_handoff_only' => true,
                        'external_provider_called_by_marketing' => false,
                    ],
                    'created_by' => $actorId,
                ]);
                $failed[] = ['handoff_id' => $handoffId, 'contact_id' => $contactId, 'recipient_identifier' => $recipientValue, 'error' => $error];
            }
        }

        $summary = [
            'queue_id' => (int) ($queue['id'] ?? 0),
            'connector_id' => (int) ($connector['id'] ?? 0),
            'adapter_key' => $adapterKey,
            'execution_type' => $channel,
            'idempotency_key' => (string) ($input['live_idempotency_key'] ?? $queue['live_idempotency_key'] ?? ''),
            'queued_count' => count($queued),
            'blocked_count' => count($blocked),
            'failed_count' => count($failed),
            'recipient_count' => count($recipients),
            'source_message_ids' => array_values(array_filter(array_map(static fn(array $item): int => (int) ($item['source_message_id'] ?? 0), $queued))),
            'source_queue_ids' => array_values(array_filter(array_map(static fn(array $item): int => (int) ($item['source_queue_id'] ?? 0), $queued))),
            'queue_handoff_only' => true,
            'external_api_called' => false,
            'third_party_delivery' => false,
            'completed_at' => date('c'),
        ];

        return [
            'success' => $queued !== [] && $failed === [] && $blocked === [],
            'message' => $failed === [] && $blocked === []
                ? 'CRM ' . strtoupper($channel) . ' queue handoff completed. The existing channel queue processor is responsible for provider delivery.'
                : 'CRM ' . strtoupper($channel) . ' queue handoff completed with blocked or failed recipients.',
            'adapter_key' => $adapterKey,
            'live_execution' => true,
            'external_api_called' => false,
            'third_party_delivery' => false,
            'queue_handoff_only' => true,
            'channel_queue_handoff_only' => true,
            'execution_type' => $channel,
            'queue_id' => (int) ($queue['id'] ?? 0),
            'connector_id' => (int) ($connector['id'] ?? 0),
            'idempotency_key' => $summary['idempotency_key'],
            'queued_recipients' => count($queued),
            'blocked_recipients' => count($blocked),
            'failed_recipients' => count($failed),
            'source_message_ids' => $summary['source_message_ids'],
            'source_queue_ids' => $summary['source_queue_ids'],
            'summary' => $summary,
            'completed_at' => date('c'),
        ];
    }

    private function executeMarketingEmailQueueHandoff(array $queue, array $connector, array $input): array
    {
        $runId = (int) ($queue['email_run_id'] ?? 0);
        $run = $runId > 0 ? $this->getEmailCampaignRun($runId) : null;
        if (!$run) {
            return [
                'success' => false,
                'message' => 'Marketing email run is required for the CRM email queue handoff adapter.',
                'adapter_key' => 'crm_email_queue_handoff',
                'external_api_called' => false,
            ];
        }

        $recipients = $this->resolveLiveEmailRecipients($run, $queue);
        if ($recipients === []) {
            return [
                'success' => false,
                'message' => 'No workspace contacts with valid email addresses were available for this email run.',
                'adapter_key' => 'crm_email_queue_handoff',
                'external_api_called' => false,
            ];
        }

        $policy = $this->getMarketingLiveExecutionPolicy();
        $dailyCap = (int) ($policy['daily_live_cap'] ?? 0);
        $usedToday = $this->countMarketingLiveEmailHandoffsToday();
        if ($dailyCap > 0 && ($usedToday + count($recipients)) > $dailyCap) {
            return [
                'success' => false,
                'message' => 'Daily live email handoff cap would be exceeded.',
                'adapter_key' => 'crm_email_queue_handoff',
                'daily_live_cap' => $dailyCap,
                'used_today' => $usedToday,
                'requested_recipients' => count($recipients),
                'external_api_called' => false,
            ];
        }

        $existingHandoffs = Database::tableExists('marketing_live_email_handoffs')
            ? (int) (Database::queryOne(
                "SELECT COUNT(*) AS count
                 FROM marketing_live_email_handoffs
                 WHERE workspace_id = ?
                   AND queue_id = ?
                   AND email_run_id = ?
                   AND status = 'queued'",
                [$this->workspaceId(), (int) ($queue['id'] ?? 0), $runId]
            )['count'] ?? 0)
            : 0;
        if ($existingHandoffs > 0) {
            return [
                'success' => false,
                'message' => 'This execution queue item has already handed this email run to the CRM email queue.',
                'adapter_key' => 'crm_email_queue_handoff',
                'external_api_called' => false,
            ];
        }

        $emailService = new EmailService();
        $subject = trim((string) ($run['subject'] ?? ''));
        $preheader = trim((string) ($run['preheader_text'] ?? $run['preview_text'] ?? ''));
        $bodySnapshot = trim((string) ($run['body_snapshot'] ?? ''));
        $unsubscribeText = trim((string) ($run['unsubscribe_text'] ?? ''));
        $bodyText = trim(strip_tags($bodySnapshot));
        if ($bodyText === '') {
            $bodyText = $bodySnapshot;
        }
        if ($unsubscribeText !== '' && !str_contains(strtolower($bodyText), strtolower($unsubscribeText))) {
            $bodyText .= "\n\n" . $unsubscribeText;
        }
        $hasHtmlBody = $bodySnapshot !== strip_tags($bodySnapshot);
        $bodyHtml = $hasHtmlBody
            ? $bodySnapshot
            : nl2br(htmlspecialchars($bodyText, ENT_QUOTES, 'UTF-8'));
        if ($preheader !== '') {
            $bodyHtml = '<span style="display:none!important;visibility:hidden;opacity:0;color:transparent;height:0;width:0;overflow:hidden;">'
                . htmlspecialchars($preheader, ENT_QUOTES, 'UTF-8')
                . '</span>' . $bodyHtml;
        }

        $queued = [];
        $failed = [];
        foreach ($recipients as $recipient) {
            $contactId = (int) ($recipient['contact_id'] ?? 0);
            $email = trim((string) ($recipient['email'] ?? ''));
            if ($contactId <= 0 || !filter_var($email, FILTER_VALIDATE_EMAIL)) {
                $failed[] = ['recipient_email' => $email, 'error' => 'Recipient contact or email is invalid.'];
                $this->recordMarketingLiveEmailHandoff($queue, $connector, $run, [
                    'contact_id' => $contactId > 0 ? $contactId : null,
                    'recipient_email' => $email !== '' ? $email : 'unknown',
                    'status' => 'failed',
                    'error_message' => 'Recipient contact or email is invalid.',
                    'metadata' => ['reason' => 'invalid_recipient'],
                    'created_by' => (int) ($input['created_by'] ?? $this->currentUserId()) ?: null,
                ]);
                continue;
            }

            $unsubscribe = ['id' => null, 'url' => '', 'token' => ''];
            try {
                $unsubscribe = $this->createLiveEmailUnsubscribeToken([
                    'email_run_id' => $runId,
                    'queue_id' => (int) ($queue['id'] ?? 0),
                    'contact_id' => $contactId,
                    'recipient_email' => $email,
                    'metadata' => [
                        'source' => 'crm_email_queue_handoff',
                        'email_queue_handoff_only' => true,
                    ],
                    'created_by' => (int) ($input['created_by'] ?? $this->currentUserId()) ?: null,
                ]);
                $recipientBody = $this->appendLiveEmailUnsubscribeNotice(
                    $bodyText,
                    $bodyHtml,
                    (string) ($unsubscribe['url'] ?? ''),
                    $unsubscribeText
                );
                $uuid = $emailService->send($contactId, $email, $subject, (string) $recipientBody['body_text'], [
                    'workspace_id' => $this->workspaceId(),
                    'user_id' => (int) ($input['created_by'] ?? $this->currentUserId()) ?: null,
                    'body_html' => (string) $recipientBody['body_html'],
                    'scheduled_at' => $this->normalizeDateTime((string) ($queue['scheduled_at'] ?? '')),
                    'priority' => 5,
                    'sender_profile' => 'outreach',
                ]);
                $emailRow = Database::queryOne(
                    'SELECT id, uuid FROM emails WHERE workspace_id = ? AND uuid = ? LIMIT 1',
                    [$this->workspaceId(), $uuid]
                ) ?: [];
                $emailId = (int) ($emailRow['id'] ?? 0);
                $queueRow = $emailId > 0
                    ? (Database::queryOne(
                        "SELECT id
                         FROM email_queue
                         WHERE workspace_id = ?
                           AND email_id = ?
                         ORDER BY id DESC
                         LIMIT 1",
                        [$this->workspaceId(), $emailId]
                    ) ?: [])
                    : [];
                $emailQueueId = (int) ($queueRow['id'] ?? 0);
                $handoffId = $this->recordMarketingLiveEmailHandoff($queue, $connector, $run, [
                    'email_id' => $emailId > 0 ? $emailId : null,
                    'email_queue_id' => $emailQueueId > 0 ? $emailQueueId : null,
                    'contact_id' => $contactId,
                    'recipient_email' => $email,
                    'status' => 'queued',
                    'metadata' => [
                        'email_uuid' => $uuid,
                        'email_queue_handoff_only' => true,
                        'external_smtp_called' => false,
                        'live_idempotency_key' => (string) ($input['live_idempotency_key'] ?? $queue['live_idempotency_key'] ?? ''),
                        'unsubscribe_token_id' => (int) ($unsubscribe['id'] ?? 0) ?: null,
                        'unsubscribe_link_added' => (string) ($unsubscribe['url'] ?? '') !== '',
                    ],
                    'created_by' => (int) ($input['created_by'] ?? $this->currentUserId()) ?: null,
                ]);
                $this->attachLiveEmailUnsubscribeTokenToHandoff(!empty($unsubscribe['id']) ? (int) $unsubscribe['id'] : null, $handoffId);
                $queued[] = [
                    'contact_id' => $contactId,
                    'recipient_email' => $email,
                    'email_id' => $emailId,
                    'email_queue_id' => $emailQueueId,
                    'unsubscribe_token_id' => (int) ($unsubscribe['id'] ?? 0) ?: null,
                ];
            } catch (Throwable $e) {
                $error = trim((string) $e->getMessage()) ?: 'Email queue handoff failed.';
                if (!empty($unsubscribe['id']) && Database::tableExists('marketing_live_email_unsubscribe_tokens')) {
                    Database::execute(
                        "UPDATE marketing_live_email_unsubscribe_tokens
                         SET status = 'revoked'
                         WHERE workspace_id = ? AND id = ?",
                        [$this->workspaceId(), (int) $unsubscribe['id']]
                    );
                }
                $failed[] = ['contact_id' => $contactId, 'recipient_email' => $email, 'error' => $error];
                $this->recordMarketingLiveEmailHandoff($queue, $connector, $run, [
                    'contact_id' => $contactId,
                    'recipient_email' => $email,
                    'status' => 'failed',
                    'error_message' => $error,
                    'metadata' => ['email_queue_handoff_only' => true, 'external_smtp_called' => false],
                    'created_by' => (int) ($input['created_by'] ?? $this->currentUserId()) ?: null,
                ]);
            }
        }

        $handoffStatus = $queued === []
            ? 'failed'
            : ($failed === [] ? 'queued' : 'partially_queued');
        $summary = [
            'queue_id' => (int) ($queue['id'] ?? 0),
            'connector_id' => (int) ($connector['id'] ?? 0),
            'adapter_key' => 'crm_email_queue_handoff',
            'idempotency_key' => (string) ($input['live_idempotency_key'] ?? $queue['live_idempotency_key'] ?? ''),
            'queued_count' => count($queued),
            'failed_count' => count($failed),
            'recipient_count' => count($recipients),
            'email_ids' => array_values(array_filter(array_map(static fn(array $item): int => (int) ($item['email_id'] ?? 0), $queued))),
            'email_queue_ids' => array_values(array_filter(array_map(static fn(array $item): int => (int) ($item['email_queue_id'] ?? 0), $queued))),
            'unsubscribe_token_ids' => array_values(array_filter(array_map(static fn(array $item): int => (int) ($item['unsubscribe_token_id'] ?? 0), $queued))),
            'external_smtp_called' => false,
            'email_queue_handoff_only' => true,
            'completed_at' => date('c'),
        ];
        if (Database::columnExists('marketing_email_campaign_runs', 'live_handoff_status')) {
            $this->updateById('marketing_email_campaign_runs', $runId, [
                'live_handoff_status' => $handoffStatus,
                'live_handoff_at' => date('Y-m-d H:i:s'),
                'live_handoff_json' => $this->normalizeJsonValue($summary + ['failures' => array_slice($failed, 0, 10)]),
            ]);
        }

        return [
            'success' => $queued !== [] && $failed === [],
            'message' => $failed === []
                ? 'CRM email queue handoff completed. The existing email worker is responsible for delivery.'
                : 'CRM email queue handoff completed with failures that need review.',
            'adapter_key' => 'crm_email_queue_handoff',
            'live_execution' => true,
            'external_api_called' => false,
            'third_party_delivery' => false,
            'email_queue_handoff_only' => true,
            'queue_id' => (int) ($queue['id'] ?? 0),
            'connector_id' => (int) ($connector['id'] ?? 0),
            'email_run_id' => $runId,
            'idempotency_key' => $summary['idempotency_key'],
            'queued_recipients' => count($queued),
            'failed_recipients' => count($failed),
            'email_queue_ids' => $summary['email_queue_ids'],
            'completed_at' => date('c'),
        ];
    }

    /**
     * @return array<int,array{contact_id:int,email:string,first_name:string,last_name:string}>
     */
    private function resolveLiveEmailRecipients(array $emailRun, array $queue): array
    {
        $workspaceId = $this->workspaceId();
        $payload = $this->decodeJsonLike($queue['payload_json'] ?? $queue['payload'] ?? []);
        $contactIds = [];
        $emails = [];
        $collectIds = static function (mixed $value) use (&$contactIds): void {
            if (is_string($value)) {
                $decoded = json_decode($value, true);
                $value = is_array($decoded) ? $decoded : preg_split('/[,;\s]+/', $value);
            }
            foreach ((array) $value as $item) {
                $id = (int) $item;
                if ($id > 0) {
                    $contactIds[] = $id;
                }
            }
        };
        $collectEmails = static function (mixed $value) use (&$emails): void {
            if (is_string($value)) {
                $decoded = json_decode($value, true);
                $value = is_array($decoded) ? $decoded : preg_split('/[,;\s]+/', $value);
            }
            foreach ((array) $value as $item) {
                if (is_array($item)) {
                    $candidate = trim((string) ($item['email'] ?? $item['to_email'] ?? ''));
                } else {
                    $candidate = trim((string) $item);
                }
                if ($candidate !== '' && filter_var($candidate, FILTER_VALIDATE_EMAIL)) {
                    $emails[] = strtolower($candidate);
                }
            }
        };

        $collectIds($payload['contact_ids'] ?? $payload['recipient_contact_ids'] ?? []);
        $collectEmails($payload['recipient_emails'] ?? $payload['emails'] ?? []);

        $segmentSnapshotId = (int) ($emailRun['segment_snapshot_id'] ?? 0);
        if ($segmentSnapshotId > 0 && Database::tableExists('marketing_segment_snapshots')) {
            $snapshot = Database::queryOne(
                'SELECT contact_ids_json, sample_contacts_json FROM marketing_segment_snapshots WHERE workspace_id = ? AND id = ?',
                [$workspaceId, $segmentSnapshotId]
            ) ?: [];
            $collectIds(json_decode((string) ($snapshot['contact_ids_json'] ?? '[]'), true) ?: []);
            $sampleContacts = json_decode((string) ($snapshot['sample_contacts_json'] ?? '[]'), true) ?: [];
            foreach ((array) $sampleContacts as $contact) {
                if (is_array($contact)) {
                    $collectIds([$contact['id'] ?? $contact['contact_id'] ?? 0]);
                    $collectEmails([$contact]);
                }
            }
        }

        $segment = (array) ($emailRun['segment_snapshot_json'] ?? []);
        foreach (['contact_ids', 'recipient_contact_ids'] as $key) {
            if (!empty($segment[$key])) {
                $collectIds($segment[$key]);
            }
        }
        foreach (['sample_contacts', 'contacts', 'recipients'] as $key) {
            foreach ((array) ($segment[$key] ?? []) as $contact) {
                if (is_array($contact)) {
                    $collectIds([$contact['id'] ?? $contact['contact_id'] ?? 0]);
                    $collectEmails([$contact]);
                }
            }
        }

        if ($contactIds === [] && !empty($emailRun['audience_segment_id'])) {
            try {
                $preview = $this->previewAudienceSegment((int) $emailRun['audience_segment_id'], 5000, false);
                $collectIds($preview['contact_ids'] ?? []);
                foreach ((array) ($preview['contacts'] ?? []) as $contact) {
                    if (is_array($contact)) {
                        $collectEmails([$contact]);
                    }
                }
            } catch (Throwable) {
                // Keep live execution conservative: unresolved audience previews simply produce no recipients.
            }
        }

        $contacts = [];
        $contactIds = array_values(array_unique(array_filter(array_map('intval', $contactIds), static fn(int $id): bool => $id > 0)));
        if ($contactIds !== []) {
            $placeholders = implode(',', array_fill(0, count($contactIds), '?'));
            $rows = Database::query(
                "SELECT id, first_name, last_name, email
                 FROM contacts
                 WHERE workspace_id = ?
                   AND id IN ({$placeholders})
                   AND email IS NOT NULL
                   AND email <> ''",
                array_merge([$workspaceId], $contactIds)
            );
            foreach ($rows as $row) {
                $email = strtolower(trim((string) ($row['email'] ?? '')));
                if ($email !== '' && filter_var($email, FILTER_VALIDATE_EMAIL)) {
                    $contacts[$email] = [
                        'contact_id' => (int) $row['id'],
                        'email' => $email,
                        'first_name' => (string) ($row['first_name'] ?? ''),
                        'last_name' => (string) ($row['last_name'] ?? ''),
                    ];
                }
            }
        }

        $emails = array_values(array_unique($emails));
        if ($emails !== []) {
            $placeholders = implode(',', array_fill(0, count($emails), '?'));
            $rows = Database::query(
                "SELECT id, first_name, last_name, email
                 FROM contacts
                 WHERE workspace_id = ?
                   AND LOWER(email) IN ({$placeholders})",
                array_merge([$workspaceId], $emails)
            );
            foreach ($rows as $row) {
                $email = strtolower(trim((string) ($row['email'] ?? '')));
                if ($email !== '' && filter_var($email, FILTER_VALIDATE_EMAIL)) {
                    $contacts[$email] = [
                        'contact_id' => (int) $row['id'],
                        'email' => $email,
                        'first_name' => (string) ($row['first_name'] ?? ''),
                        'last_name' => (string) ($row['last_name'] ?? ''),
                    ];
                }
            }
        }

        if ($contacts === []) {
            return [];
        }

        return array_values($contacts);
    }

    /**
     * @return array<int,array{contact_id:int,phone:string,first_name:string,last_name:string}>
     */
    private function resolveLiveMessagingRecipients(array $queue, string $channel): array
    {
        $workspaceId = $this->workspaceId();
        $payload = $this->decodeJsonLike($queue['payload_json'] ?? $queue['payload'] ?? []);
        $contactIds = [];
        $collectIds = static function (mixed $value) use (&$contactIds): void {
            if (is_string($value)) {
                $decoded = json_decode($value, true);
                $value = is_array($decoded) ? $decoded : preg_split('/[,;\s]+/', $value);
            }
            foreach ((array) $value as $item) {
                if (is_array($item)) {
                    $item = $item['id'] ?? $item['contact_id'] ?? 0;
                }
                $id = (int) $item;
                if ($id > 0) {
                    $contactIds[] = $id;
                }
            }
        };

        foreach (['contact_ids', 'recipient_contact_ids', 'contacts', 'recipients'] as $key) {
            if (!empty($payload[$key])) {
                $collectIds($payload[$key]);
            }
        }

        if ($contactIds === [] && !empty($queue['channel_export_bundle_id']) && Database::tableExists('marketing_channel_export_bundles')) {
            $bundle = $this->getChannelExportBundle((int) $queue['channel_export_bundle_id']);
            foreach (['recipient_contact_ids', 'contact_ids'] as $key) {
                if (!empty($bundle['payload_json'][$key])) {
                    $collectIds($bundle['payload_json'][$key]);
                }
            }
        }

        if ($contactIds === []) {
            return [];
        }

        $contactIds = array_values(array_unique(array_filter(array_map('intval', $contactIds), static fn(int $id): bool => $id > 0)));
        $placeholders = implode(',', array_fill(0, count($contactIds), '?'));
        $rows = Database::query(
            "SELECT id, first_name, last_name, phone
             FROM contacts
             WHERE workspace_id = ?
               AND id IN ({$placeholders})
               AND phone IS NOT NULL
               AND phone <> ''",
            array_merge([$workspaceId], $contactIds)
        );

        $contacts = [];
        foreach ($rows as $row) {
            $phone = $this->normalizeLiveMessagingIdentifier((string) ($row['phone'] ?? ''), $channel);
            if ($phone === '') {
                continue;
            }
            $contacts[$phone] = [
                'contact_id' => (int) $row['id'],
                'phone' => $phone,
                'first_name' => (string) ($row['first_name'] ?? ''),
                'last_name' => (string) ($row['last_name'] ?? ''),
            ];
        }

        return array_values($contacts);
    }

    private function liveMessagingPayloadMessage(array $queue, string $channel): string
    {
        $payload = $this->decodeJsonLike($queue['payload_json'] ?? $queue['payload'] ?? []);
        foreach (['message', 'message_body', 'body', 'copy', 'planned_copy', 'text'] as $key) {
            $candidate = trim((string) ($payload[$key] ?? ''));
            if ($candidate !== '') {
                return mb_substr(Security::sanitizeInput($candidate, 'string'), 0, $channel === 'sms' ? 1600 : 4096);
            }
        }

        if (!empty($queue['distribution_post_id'])) {
            $post = $this->getDistributionPost((int) $queue['distribution_post_id']);
            $candidate = trim((string) ($post['planned_copy'] ?? ''));
            if ($candidate !== '') {
                return mb_substr(Security::sanitizeInput($candidate, 'string'), 0, $channel === 'sms' ? 1600 : 4096);
            }
        }
        if (!empty($queue['content_item_id'])) {
            $content = $this->getContentItem((int) $queue['content_item_id']);
            $candidate = trim((string) ($content['draft_body'] ?? ''));
            if ($candidate !== '') {
                return mb_substr(Security::sanitizeInput($candidate, 'string'), 0, $channel === 'sms' ? 1600 : 4096);
            }
        }

        return '';
    }

    private function normalizeLiveMessagingIdentifier(string $identifier, string $channel): string
    {
        $identifier = trim($identifier);
        if ($identifier === '') {
            return '';
        }

        $digits = preg_replace('/[^\d+]/', '', $identifier) ?: '';
        if ($channel === 'whatsapp') {
            return ltrim(ltrim($digits, '+'), '0');
        }
        if (!str_starts_with($digits, '+')) {
            $digitsOnly = preg_replace('/\D/', '', $digits) ?: '';
            if ($digitsOnly === '') {
                return '';
            }
            return '+' . $digitsOnly;
        }

        return $digits;
    }

    private function isMarketingIdentifierSuppressed(string $channel, string $identifier): bool
    {
        if (!Database::tableExists('marketing_suppression_entries')) {
            return false;
        }
        $channel = in_array($channel, ['email', 'sms', 'whatsapp'], true) ? $channel : 'email';
        $identifier = $channel === 'email'
            ? strtolower(trim($identifier))
            : $this->normalizeLiveMessagingIdentifier($identifier, $channel);
        if ($identifier === '') {
            return false;
        }
        $channelHash = hash('sha256', strtolower($channel . ':' . $identifier));
        $allHash = hash('sha256', strtolower('all:' . $identifier));
        $rawHash = hash('sha256', strtolower($identifier));

        return (bool) Database::queryOne(
            "SELECT id
             FROM marketing_suppression_entries
             WHERE workspace_id = ?
               AND status = 'active'
               AND channel IN (?, 'all')
               AND (identifier_hash IN (?, ?, ?) OR LOWER(identifier) = LOWER(?))
             LIMIT 1",
            [$this->workspaceId(), $channel, $channelHash, $allHash, $rawHash, $identifier]
        );
    }

    private function isWhatsAppMessagingWindowOpen(int $contactId): bool
    {
        if ($contactId <= 0 || !Database::tableExists('communications')) {
            return false;
        }

        return (bool) Database::queryOne(
            "SELECT 1 AS within_window
             FROM communications
             WHERE workspace_id = ?
               AND contact_id = ?
               AND channel = 'whatsapp'
               AND direction = 'inbound'
               AND created_at >= DATE_SUB(NOW(), INTERVAL 24 HOUR)
             LIMIT 1",
            [$this->workspaceId(), $contactId]
        );
    }

    private function recordMarketingLiveChannelHandoff(array $queue, array $connector, array $data): int
    {
        if (!Database::tableExists('marketing_live_channel_handoffs')) {
            return 0;
        }

        Database::execute(
            "INSERT INTO marketing_live_channel_handoffs
             (workspace_id, uuid, queue_id, connector_id, adapter_key, execution_type, contact_id, recipient_identifier,
              source_table, source_message_id, source_queue_id, status, provider_message_id, idempotency_key,
              failure_class, consent_basis, suppression_checked_at, suppression_result, suppression_blocked_reason,
              consent_evidence_json, whatsapp_template_evidence_json, error_message, metadata_json, created_by)
             VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, NOW(), ?, ?, ?, ?, ?, ?, ?)",
            [
                $this->workspaceId(),
                $this->generateUuid(),
                (int) ($queue['id'] ?? 0),
                !empty($connector['id']) ? (int) $connector['id'] : null,
                ($connector['live_adapter_key'] ?? '') !== '' ? mb_substr(Security::sanitizeInput((string) $connector['live_adapter_key'], 'string'), 0, 120) : null,
                $this->normalizeEnum((string) ($data['execution_type'] ?? 'sms'), ['sms', 'whatsapp'], 'live_channel_handoff_type'),
                !empty($data['contact_id']) ? (int) $data['contact_id'] : null,
                mb_substr(Security::sanitizeInput((string) ($data['recipient_identifier'] ?? 'unknown'), 'string'), 0, 255),
                mb_substr(Security::sanitizeInput((string) ($data['source_table'] ?? 'unknown'), 'string'), 0, 64),
                !empty($data['source_message_id']) ? (int) $data['source_message_id'] : null,
                !empty($data['source_queue_id']) ? (int) $data['source_queue_id'] : null,
                $this->normalizeEnum((string) ($data['status'] ?? 'queued'), ['queued', 'processing', 'sent', 'failed', 'blocked', 'cancelled'], 'live_channel_handoff_status'),
                !empty($data['provider_message_id']) ? mb_substr(Security::sanitizeInput((string) $data['provider_message_id'], 'string'), 0, 255) : null,
                ($data['idempotency_key'] ?? $queue['live_idempotency_key'] ?? '') !== '' ? mb_substr(Security::sanitizeInput((string) ($data['idempotency_key'] ?? $queue['live_idempotency_key']), 'string'), 0, 64) : null,
                ($data['failure_class'] ?? '') !== '' ? mb_substr(Security::sanitizeInput((string) $data['failure_class'], 'string'), 0, 80) : null,
                ($data['consent_basis'] ?? '') !== '' ? mb_substr(Security::sanitizeInput((string) $data['consent_basis'], 'string'), 0, 120) : null,
                $this->normalizeEnum((string) ($data['suppression_result'] ?? ((string) ($data['status'] ?? '') === 'blocked' ? 'blocked' : 'clear')), ['not_checked', 'clear', 'blocked', 'warning'], 'live_handoff_suppression_result'),
                $this->nullableSanitizedText($data['suppression_blocked_reason'] ?? ((string) ($data['status'] ?? '') === 'blocked' ? ($data['error_message'] ?? 'Recipient blocked by live consent/suppression gate.') : '')),
                $this->normalizeJsonValue($this->sanitizeJsonCompatible($data['consent_evidence'] ?? [])),
                $this->normalizeJsonValue($this->sanitizeJsonCompatible($data['whatsapp_template_evidence'] ?? [])),
                $this->nullableSanitizedText($data['error_message'] ?? ''),
                $this->normalizeJsonValue($this->sanitizeJsonCompatible($data['metadata'] ?? [])),
                (int) ($data['created_by'] ?? $this->currentUserId()) ?: null,
            ]
        );

        return (int) Database::lastInsertId();
    }

    private function syncLiveChannelHandoffEvidenceForQueue(array $queue, string $executionType, int $workerRunId = 0): array
    {
        $executionType = $this->normalizeEnum($executionType, ['sms', 'whatsapp'], 'live_channel_sync_type');
        if (!Database::tableExists('marketing_live_channel_handoffs')) {
            return ['available' => false, 'synced' => 0, 'proofs_recorded' => 0];
        }

        $queueId = (int) ($queue['id'] ?? 0);
        if ($queueId <= 0) {
            return ['available' => true, 'synced' => 0, 'proofs_recorded' => 0];
        }

        if ($executionType === 'sms') {
            if (!Database::tableExists('sms_queue') || !Database::tableExists('sms_messages')) {
                return [
                    'available' => false,
                    'execution_type' => 'sms',
                    'synced' => 0,
                    'proofs_recorded' => 0,
                    'message' => 'SMS queue tables are unavailable for live channel evidence sync.',
                ];
            }
            $handoffs = Database::query(
                "SELECT h.*,
                        sq.status AS source_queue_status,
                        sq.attempts AS source_queue_attempts,
                        sq.max_attempts AS source_queue_max_attempts,
                        sq.last_attempt_at AS source_queue_last_attempt_at,
                        sm.status AS source_message_status,
                        sm.provider_message_id AS source_provider_message_id,
                        sm.error_message AS source_error_message,
                        sm.to_number AS source_recipient_identifier,
                        sm.updated_at AS source_message_updated_at
                 FROM marketing_live_channel_handoffs h
                 LEFT JOIN sms_queue sq ON sq.id = h.source_queue_id AND sq.workspace_id = h.workspace_id
                 LEFT JOIN sms_messages sm ON sm.id = h.source_message_id AND sm.workspace_id = h.workspace_id
                 WHERE h.workspace_id = ?
                   AND h.queue_id = ?
                   AND h.execution_type = 'sms'
                   AND h.source_message_id IS NOT NULL
                   AND h.source_queue_id IS NOT NULL",
                [$this->workspaceId(), $queueId]
            );
        } else {
            if (!Database::tableExists('whatsapp_queue') || !Database::tableExists('whatsapp_messages')) {
                return [
                    'available' => false,
                    'execution_type' => 'whatsapp',
                    'synced' => 0,
                    'proofs_recorded' => 0,
                    'message' => 'WhatsApp queue tables are unavailable for live channel evidence sync.',
                ];
            }
            $handoffs = Database::query(
                "SELECT h.*,
                        wq.status AS source_queue_status,
                        wq.attempts AS source_queue_attempts,
                        wq.max_attempts AS source_queue_max_attempts,
                        wq.processed_at AS source_queue_last_attempt_at,
                        wq.error_message AS source_queue_error_message,
                        wm.status AS source_message_status,
                        wm.whatsapp_message_id AS source_provider_message_id,
                        wm.error_message AS source_error_message,
                        wm.to_number AS source_recipient_identifier,
                        wm.sent_at AS source_sent_at,
                        wm.delivered_at AS source_delivered_at,
                        wm.read_at AS source_read_at,
                        wm.updated_at AS source_message_updated_at
                 FROM marketing_live_channel_handoffs h
                 LEFT JOIN whatsapp_queue wq ON wq.id = h.source_queue_id AND wq.workspace_id = h.workspace_id
                 LEFT JOIN whatsapp_messages wm ON wm.id = h.source_message_id AND wm.workspace_id = h.workspace_id
                 WHERE h.workspace_id = ?
                   AND h.queue_id = ?
                   AND h.execution_type = 'whatsapp'
                   AND h.source_message_id IS NOT NULL
                   AND h.source_queue_id IS NOT NULL",
                [$this->workspaceId(), $queueId]
            );
        }

        $synced = 0;
        $proofsRecorded = 0;
        foreach ($handoffs as $handoff) {
            $evidence = $this->deriveLiveChannelHandoffEvidence($handoff, $executionType);
            if ($workerRunId > 0) {
                $evidence['worker_run_id'] = $workerRunId;
            }
            $handoffStatus = (string) ($evidence['handoff_status'] ?? 'queued');
            $proofStatus = (string) ($evidence['proof_status'] ?? 'unknown');
            $providerMessageId = trim((string) ($evidence['provider_message_id'] ?? ''));
            $errorMessage = trim((string) ($evidence['error_message'] ?? ''));
            $metadata = $this->decodeJsonLike($handoff['metadata_json'] ?? []);
            $metadata['latest_outcome_sync'] = [
                'proof_status' => $proofStatus,
                'handoff_status' => $handoffStatus,
                'source_queue_status' => (string) ($evidence['source_queue_status'] ?? ''),
                'source_message_status' => (string) ($evidence['source_message_status'] ?? ''),
                'synced_at' => date('c'),
                'raw_secret_values_visible' => false,
            ];

            Database::execute(
                "UPDATE marketing_live_channel_handoffs
                 SET status = ?,
                     worker_run_id = COALESCE(?, worker_run_id),
                     provider_message_id = ?,
                     error_message = ?,
                     metadata_json = ?,
                     updated_at = NOW()
                 WHERE workspace_id = ? AND id = ?",
                [
                    $this->normalizeEnum($handoffStatus, ['queued', 'processing', 'sent', 'failed', 'blocked', 'cancelled'], 'live_channel_handoff_status'),
                    $workerRunId > 0 ? $workerRunId : null,
                    $providerMessageId !== '' ? mb_substr(Security::sanitizeInput($providerMessageId, 'string'), 0, 255) : null,
                    $errorMessage !== '' ? mb_substr(Security::sanitizeInput($errorMessage, 'string'), 0, 500) : null,
                    $this->normalizeJsonValue($this->sanitizeJsonCompatible($metadata)),
                    $this->workspaceId(),
                    (int) ($handoff['id'] ?? 0),
                ]
            );
            $synced++;

            if ($this->recordLiveChannelDeliveryProof($handoff, $executionType, $evidence)) {
                $proofsRecorded++;
            }
        }

        return [
            'available' => true,
            'execution_type' => $executionType,
            'synced' => $synced,
            'proofs_recorded' => $proofsRecorded,
            'proof_table_available' => Database::tableExists('marketing_live_channel_delivery_proofs'),
            'external_api_called_by_marketing' => false,
            'checked_at' => date('c'),
        ];
    }

    private function deriveLiveChannelHandoffEvidence(array $handoff, string $executionType): array
    {
        $currentHandoffStatus = (string) ($handoff['status'] ?? 'queued');
        $queueStatus = strtolower(trim((string) ($handoff['source_queue_status'] ?? '')));
        $messageStatus = strtolower(trim((string) ($handoff['source_message_status'] ?? '')));
        $providerMessageId = trim((string) ($handoff['source_provider_message_id'] ?? ''));
        $errorMessage = trim((string) ($handoff['source_error_message'] ?? $handoff['source_queue_error_message'] ?? $handoff['error_message'] ?? ''));

        if (in_array($currentHandoffStatus, ['blocked', 'cancelled'], true)) {
            $handoffStatus = $currentHandoffStatus;
            $proofStatus = $currentHandoffStatus;
        } elseif (in_array($messageStatus, ['failed', 'undelivered'], true) || $queueStatus === 'failed') {
            $handoffStatus = 'failed';
            $proofStatus = $messageStatus === 'undelivered' ? 'undelivered' : 'failed';
        } elseif (in_array($messageStatus, ['read', 'delivered', 'sent'], true)) {
            $handoffStatus = 'sent';
            $proofStatus = $messageStatus;
        } elseif ($queueStatus === 'completed') {
            $handoffStatus = 'sent';
            $proofStatus = 'sent';
        } elseif ($queueStatus === 'processing') {
            $handoffStatus = 'processing';
            $proofStatus = 'processing';
        } elseif (in_array($queueStatus, ['pending', 'queued'], true) || in_array($messageStatus, ['pending', 'queued'], true)) {
            $handoffStatus = 'queued';
            $proofStatus = 'queued';
        } else {
            $handoffStatus = $currentHandoffStatus !== '' ? $currentHandoffStatus : 'queued';
            $proofStatus = 'unknown';
        }

        return [
            'handoff_status' => $handoffStatus,
            'proof_status' => $proofStatus,
            'execution_type' => $executionType,
            'provider_message_id' => $providerMessageId,
            'recipient_identifier' => (string) ($handoff['source_recipient_identifier'] ?? $handoff['recipient_identifier'] ?? ''),
            'error_message' => $errorMessage,
            'source_queue_status' => $queueStatus,
            'source_message_status' => $messageStatus,
            'source_queue_attempts' => (int) ($handoff['source_queue_attempts'] ?? 0),
            'source_queue_max_attempts' => (int) ($handoff['source_queue_max_attempts'] ?? 0),
            'source_queue_last_attempt_at' => $handoff['source_queue_last_attempt_at'] ?? null,
            'source_sent_at' => $handoff['source_sent_at'] ?? null,
            'source_delivered_at' => $handoff['source_delivered_at'] ?? null,
            'source_read_at' => $handoff['source_read_at'] ?? null,
            'source_message_updated_at' => $handoff['source_message_updated_at'] ?? null,
            'source_message_id' => (int) ($handoff['source_message_id'] ?? 0),
            'source_queue_id' => (int) ($handoff['source_queue_id'] ?? 0),
            'source_table' => (string) ($handoff['source_table'] ?? ($executionType === 'sms' ? 'sms_messages' : 'whatsapp_messages')),
            'queue_handoff_only' => true,
            'external_api_called_by_marketing' => false,
            'raw_secret_values_visible' => false,
        ];
    }

    private function recordLiveChannelDeliveryProof(array $handoff, string $executionType, array $evidence): bool
    {
        if (!Database::tableExists('marketing_live_channel_delivery_proofs')) {
            return false;
        }

        $handoffId = (int) ($handoff['id'] ?? 0);
        $queueId = (int) ($handoff['queue_id'] ?? 0);
        $sourceMessageId = (int) ($handoff['source_message_id'] ?? 0);
        $sourceQueueId = (int) ($handoff['source_queue_id'] ?? 0);
        if ($handoffId <= 0 || $queueId <= 0 || $sourceMessageId <= 0 || $sourceQueueId <= 0) {
            return false;
        }

        $proofStatus = $this->normalizeEnum(
            (string) ($evidence['proof_status'] ?? 'unknown'),
            self::LIVE_CHANNEL_DELIVERY_PROOF_STATUSES,
            'live_channel_delivery_proof_status'
        );
        $providerMessageId = trim((string) ($evidence['provider_message_id'] ?? ''));
        $recipientIdentifier = trim((string) ($evidence['recipient_identifier'] ?? $handoff['recipient_identifier'] ?? ''));
        $errorMessage = trim((string) ($evidence['error_message'] ?? ''));
        $workerRunId = (int) ($evidence['worker_run_id'] ?? $handoff['worker_run_id'] ?? 0);
        $safeEvidence = $this->sanitizeJsonCompatible($evidence + [
            'proof_source' => 'marketing_live_channel_outcome_sync',
            'external_api_called_by_marketing' => false,
            'raw_secret_values_visible' => false,
        ]);

        Database::execute(
            "INSERT INTO marketing_live_channel_delivery_proofs
             (workspace_id, uuid, handoff_id, worker_run_id, queue_id, connector_id, execution_type, source_table,
              source_message_id, source_queue_id, proof_status, provider_message_id, recipient_identifier,
              evidence_json, error_message, proved_at)
             VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, NOW())
             ON DUPLICATE KEY UPDATE
                worker_run_id = COALESCE(VALUES(worker_run_id), worker_run_id),
                provider_message_id = VALUES(provider_message_id),
                recipient_identifier = VALUES(recipient_identifier),
                evidence_json = VALUES(evidence_json),
                error_message = VALUES(error_message),
                proved_at = NOW(),
                updated_at = NOW()",
            [
                $this->workspaceId(),
                $this->generateUuid(),
                $handoffId,
                $workerRunId > 0 ? $workerRunId : null,
                $queueId,
                !empty($handoff['connector_id']) ? (int) $handoff['connector_id'] : null,
                $executionType,
                mb_substr(Security::sanitizeInput((string) ($handoff['source_table'] ?? ($executionType === 'sms' ? 'sms_messages' : 'whatsapp_messages')), 'string'), 0, 80),
                $sourceMessageId,
                $sourceQueueId,
                $proofStatus,
                $providerMessageId !== '' ? mb_substr(Security::sanitizeInput($providerMessageId, 'string'), 0, 255) : null,
                $recipientIdentifier !== '' ? mb_substr(Security::sanitizeInput($recipientIdentifier, 'string'), 0, 255) : null,
                $this->normalizeJsonValue($safeEvidence),
                $errorMessage !== '' ? mb_substr(Security::sanitizeInput($errorMessage, 'string'), 0, 500) : null,
            ]
        );

        return true;
    }

    private function countMarketingLiveEmailHandoffsToday(): int
    {
        if (!Database::tableExists('marketing_live_email_handoffs')) {
            return 0;
        }

        return (int) (Database::queryOne(
            "SELECT COUNT(*) AS count
             FROM marketing_live_email_handoffs
             WHERE workspace_id = ?
               AND status = 'queued'
               AND created_at >= CURDATE()",
            [$this->workspaceId()]
        )['count'] ?? 0);
    }

    private function recordMarketingLiveEmailHandoff(array $queue, array $connector, array $run, array $data): int
    {
        if (!Database::tableExists('marketing_live_email_handoffs')) {
            return 0;
        }

        Database::execute(
            "INSERT INTO marketing_live_email_handoffs
             (workspace_id, uuid, queue_id, email_run_id, connector_id, email_id, email_queue_id,
              contact_id, recipient_email, adapter_key, idempotency_key, provider_reference, failure_class,
              consent_basis, unsubscribe_text_evidence, suppression_checked_at, suppression_result,
              suppression_blocked_reason, consent_evidence_json, status, error_message, metadata_json, created_by)
              VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, NOW(), ?, ?, ?, ?, ?, ?, ?)",
            [
                $this->workspaceId(),
                $this->generateUuid(),
                (int) ($queue['id'] ?? 0),
                (int) ($run['id'] ?? 0),
                !empty($connector['id']) ? (int) $connector['id'] : null,
                !empty($data['email_id']) ? (int) $data['email_id'] : null,
                !empty($data['email_queue_id']) ? (int) $data['email_queue_id'] : null,
                !empty($data['contact_id']) ? (int) $data['contact_id'] : null,
                mb_substr(Security::sanitizeInput((string) ($data['recipient_email'] ?? 'unknown'), 'string'), 0, 255),
                ($connector['live_adapter_key'] ?? '') !== '' ? mb_substr(Security::sanitizeInput((string) $connector['live_adapter_key'], 'string'), 0, 120) : null,
                ($data['idempotency_key'] ?? $queue['live_idempotency_key'] ?? '') !== '' ? mb_substr(Security::sanitizeInput((string) ($data['idempotency_key'] ?? $queue['live_idempotency_key']), 'string'), 0, 64) : null,
                ($data['provider_reference'] ?? '') !== '' ? mb_substr(Security::sanitizeInput((string) $data['provider_reference'], 'string'), 0, 255) : (!empty($data['email_queue_id']) ? 'email_queue:' . (int) $data['email_queue_id'] : null),
                ($data['failure_class'] ?? '') !== '' ? mb_substr(Security::sanitizeInput((string) $data['failure_class'], 'string'), 0, 80) : null,
                ($data['consent_basis'] ?? $run['consent_basis'] ?? $run['consent_status'] ?? '') !== '' ? mb_substr(Security::sanitizeInput((string) ($data['consent_basis'] ?? $run['consent_basis'] ?? $run['consent_status']), 'string'), 0, 120) : null,
                ($data['unsubscribe_text_evidence'] ?? '') !== ''
                    ? mb_substr(Security::sanitizeInput((string) $data['unsubscribe_text_evidence'], 'string'), 0, 1000)
                    : (trim((string) ($run['unsubscribe_text'] ?? '')) !== '' ? 'hash:' . hash('sha256', (string) $run['unsubscribe_text']) : null),
                $this->normalizeEnum((string) ($data['suppression_result'] ?? ((string) ($data['status'] ?? '') === 'blocked' ? 'blocked' : 'clear')), ['not_checked', 'clear', 'blocked', 'warning'], 'live_email_handoff_suppression_result'),
                $this->nullableSanitizedText($data['suppression_blocked_reason'] ?? ((string) ($data['status'] ?? '') === 'blocked' ? ($data['error_message'] ?? 'Recipient blocked by live consent/suppression gate.') : '')),
                $this->normalizeJsonValue($this->sanitizeJsonCompatible($data['consent_evidence'] ?? [])),
                $this->normalizeEnum((string) ($data['status'] ?? 'queued'), ['queued', 'processing', 'sent', 'cancelled', 'skipped', 'failed', 'blocked'], 'live_email_handoff_status'),
                $this->nullableSanitizedText($data['error_message'] ?? ''),
                $this->normalizeJsonValue($this->sanitizeJsonCompatible($data['metadata'] ?? [])),
                (int) ($data['created_by'] ?? $this->currentUserId()) ?: null,
            ]
        );

        return (int) Database::lastInsertId();
    }

    private function eligibleLiveEmailHandoffsForWorker(int $limit): array
    {
        if (!Database::tableExists('marketing_live_email_handoffs')) {
            return [];
        }

        return Database::query(
            "SELECT leh.*,
                    e.status AS email_status,
                    eq.status AS queue_status,
                    eq.scheduled_at AS queue_scheduled_at,
                    eq.attempts AS queue_attempts,
                    eq.max_attempts AS queue_max_attempts,
                    meq.execution_type,
                    meq.execution_mode,
                    meq.status AS execution_queue_status,
                    er.status AS email_run_status,
                    er.approval_status AS email_run_approval_status,
                    er.consent_status AS email_run_consent_status,
                    er.subject AS email_run_subject,
                    er.body_snapshot AS email_run_body_snapshot,
                    er.unsubscribe_text AS email_run_unsubscribe_text,
                    cc.connector_type,
                    cc.status AS connector_status,
                    cc.live_enabled,
                    cc.live_adapter_key,
                    cc.secret_status,
                    approval.status AS execution_approval_status
             FROM marketing_live_email_handoffs leh
             JOIN emails e ON e.id = leh.email_id AND e.workspace_id = leh.workspace_id
             JOIN email_queue eq ON eq.id = leh.email_queue_id AND eq.workspace_id = leh.workspace_id
             JOIN marketing_execution_queue meq ON meq.id = leh.queue_id AND meq.workspace_id = leh.workspace_id
             JOIN marketing_email_campaign_runs er ON er.id = leh.email_run_id AND er.workspace_id = leh.workspace_id
             LEFT JOIN marketing_channel_connectors cc ON cc.id = leh.connector_id AND cc.workspace_id = leh.workspace_id
             LEFT JOIN marketing_execution_approvals approval ON approval.id = (
                SELECT a.id
                FROM marketing_execution_approvals a
                WHERE a.workspace_id = leh.workspace_id
                  AND a.queue_id = leh.queue_id
                ORDER BY a.created_at DESC, a.id DESC
                LIMIT 1
             )
             WHERE leh.workspace_id = ?
               AND leh.status = 'queued'
               AND leh.operator_status NOT IN ('cancelled','blocked','completed')
               AND e.status = 'pending'
               AND eq.status = 'pending'
               AND (eq.scheduled_at IS NULL OR eq.scheduled_at <= NOW())
             ORDER BY eq.priority DESC, leh.created_at ASC, leh.id ASC
             LIMIT {$limit}",
            [$this->workspaceId()]
        );
    }

    private function recordLiveEmailDeliveryProof(
        int $handoffId,
        int $workerRunId,
        array $deliveryResult,
        string $proofStatus,
        ?string $errorMessage = null
    ): void {
        if ($handoffId <= 0 || !Database::tableExists('marketing_live_email_delivery_proofs')) {
            return;
        }

        $handoff = Database::queryOne(
            "SELECT id, email_id, email_queue_id, recipient_email
             FROM marketing_live_email_handoffs
             WHERE workspace_id = ? AND id = ?
             LIMIT 1",
            [$this->workspaceId(), $handoffId]
        );
        if (!$handoff) {
            return;
        }

        $safeEvidence = [
            'success' => !empty($deliveryResult['success']),
            'status' => (string) ($deliveryResult['status'] ?? $proofStatus),
            'email_uuid' => (string) ($deliveryResult['email_uuid'] ?? ''),
            'provider_key' => (string) ($deliveryResult['provider_key'] ?? ''),
            'smtp_profile' => (string) ($deliveryResult['smtp_profile'] ?? ''),
            'smtp_method' => (string) ($deliveryResult['smtp_method'] ?? ''),
            'communication_id' => !empty($deliveryResult['communication_id']) ? (int) $deliveryResult['communication_id'] : null,
            'sync_error' => isset($deliveryResult['sync_error']) ? mb_substr(Security::sanitizeInput((string) $deliveryResult['sync_error'], 'string'), 0, 500) : null,
            'blockers' => array_values((array) ($deliveryResult['blockers'] ?? [])),
            'external_smtp_from_page' => false,
            'raw_secret_values_visible' => false,
            'proof_source' => 'marketing_live_email_worker',
        ];

        Database::execute(
            "INSERT INTO marketing_live_email_delivery_proofs
             (workspace_id, uuid, handoff_id, worker_run_id, email_id, email_queue_id, proof_status,
              provider_key, smtp_profile, smtp_method, message_id, communication_id, from_email, to_email,
              evidence_json, error_message, proved_at)
             VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, NOW())",
            [
                $this->workspaceId(),
                $this->generateUuid(),
                $handoffId,
                $workerRunId > 0 ? $workerRunId : null,
                !empty($deliveryResult['email_id']) ? (int) $deliveryResult['email_id'] : (!empty($handoff['email_id']) ? (int) $handoff['email_id'] : null),
                !empty($deliveryResult['email_queue_id']) ? (int) $deliveryResult['email_queue_id'] : (!empty($handoff['email_queue_id']) ? (int) $handoff['email_queue_id'] : null),
                $this->normalizeEnum($proofStatus, self::LIVE_EMAIL_DELIVERY_PROOF_STATUSES, 'live_email_delivery_proof_status'),
                !empty($deliveryResult['provider_key']) ? mb_substr(Security::sanitizeInput((string) $deliveryResult['provider_key'], 'string'), 0, 120) : null,
                !empty($deliveryResult['smtp_profile']) ? mb_substr(Security::sanitizeInput((string) $deliveryResult['smtp_profile'], 'string'), 0, 120) : null,
                !empty($deliveryResult['smtp_method']) ? mb_substr(Security::sanitizeInput((string) $deliveryResult['smtp_method'], 'string'), 0, 120) : null,
                !empty($deliveryResult['message_id']) ? mb_substr(Security::sanitizeInput((string) $deliveryResult['message_id'], 'string'), 0, 255) : null,
                !empty($deliveryResult['communication_id']) ? (int) $deliveryResult['communication_id'] : null,
                !empty($deliveryResult['from_email']) ? mb_substr(Security::sanitizeInput((string) $deliveryResult['from_email'], 'string'), 0, 255) : null,
                !empty($deliveryResult['to_email'])
                    ? mb_substr(Security::sanitizeInput((string) $deliveryResult['to_email'], 'string'), 0, 255)
                    : mb_substr(Security::sanitizeInput((string) ($handoff['recipient_email'] ?? ''), 'string'), 0, 255),
                $this->normalizeJsonValue($this->sanitizeJsonCompatible($safeEvidence)),
                $errorMessage !== null && trim($errorMessage) !== '' ? mb_substr(Security::sanitizeInput($errorMessage, 'string'), 0, 500) : null,
            ]
        );
    }

    private function createLiveEmailUnsubscribeToken(array $data): array
    {
        if (!Database::tableExists('marketing_live_email_unsubscribe_tokens')) {
            return ['token' => '', 'url' => '', 'id' => null];
        }

        $recipientEmail = strtolower(trim((string) ($data['recipient_email'] ?? '')));
        if (!filter_var($recipientEmail, FILTER_VALIDATE_EMAIL)) {
            return ['token' => '', 'url' => '', 'id' => null];
        }

        $token = bin2hex(random_bytes(24));
        Database::execute(
            "INSERT INTO marketing_live_email_unsubscribe_tokens
             (workspace_id, uuid, token_hash, email_run_id, queue_id, handoff_id, contact_id, recipient_email,
              status, expires_at, metadata_json, created_by)
             VALUES (?, ?, ?, ?, ?, ?, ?, ?, 'active', DATE_ADD(NOW(), INTERVAL 1 YEAR), ?, ?)",
            [
                $this->workspaceId(),
                $this->generateUuid(),
                hash('sha256', $token),
                !empty($data['email_run_id']) ? (int) $data['email_run_id'] : null,
                !empty($data['queue_id']) ? (int) $data['queue_id'] : null,
                !empty($data['handoff_id']) ? (int) $data['handoff_id'] : null,
                !empty($data['contact_id']) ? (int) $data['contact_id'] : null,
                $recipientEmail,
                $this->normalizeJsonValue($this->sanitizeJsonCompatible($data['metadata'] ?? [])),
                !empty($data['created_by']) ? (int) $data['created_by'] : null,
            ]
        );

        return [
            'token' => $token,
            'url' => $this->absoluteMarketingPublicUrl('marketing_unsubscribe.php?t=' . rawurlencode($token)),
            'id' => (int) Database::lastInsertId(),
        ];
    }

    private function attachLiveEmailUnsubscribeTokenToHandoff(?int $tokenId, int $handoffId): void
    {
        if (($tokenId ?? 0) <= 0 || $handoffId <= 0 || !Database::tableExists('marketing_live_email_unsubscribe_tokens')) {
            return;
        }

        Database::execute(
            "UPDATE marketing_live_email_unsubscribe_tokens
             SET handoff_id = ?
             WHERE workspace_id = ? AND id = ?",
            [$handoffId, $this->workspaceId(), (int) $tokenId]
        );
    }

    private function appendLiveEmailUnsubscribeNotice(string $bodyText, string $bodyHtml, string $unsubscribeUrl, string $unsubscribeText): array
    {
        if ($unsubscribeUrl === '') {
            return ['body_text' => $bodyText, 'body_html' => $bodyHtml];
        }

        $textNotice = 'Unsubscribe: ' . $unsubscribeUrl;
        if (!str_contains($bodyText, $unsubscribeUrl)) {
            $bodyText = rtrim($bodyText) . "\n\n" . $textNotice;
        }

        $escapedUrl = htmlspecialchars($unsubscribeUrl, ENT_QUOTES, 'UTF-8');
        $escapedText = htmlspecialchars($unsubscribeText !== '' ? $unsubscribeText : 'Unsubscribe from future marketing emails.', ENT_QUOTES, 'UTF-8');
        $htmlNotice = '<p style="font-size:12px;color:#667085;margin-top:24px;">'
            . $escapedText . ' <a href="' . $escapedUrl . '">Manage email preferences</a>.</p>';
        if (!str_contains($bodyHtml, $unsubscribeUrl)) {
            $bodyHtml = rtrim($bodyHtml) . $htmlNotice;
        }

        return ['body_text' => $bodyText, 'body_html' => $bodyHtml];
    }

    private function absoluteMarketingPublicUrl(string $path): string
    {
        $path = ltrim($path, '/');
        $base = rtrim((string) ($_ENV['APP_URL'] ?? getenv('APP_URL') ?: 'http://localhost/crm'), '/');
        if ($base === '') {
            $base = 'http://localhost/crm';
        }
        if (!str_ends_with($base, '/public')) {
            $base .= '/public';
        }

        return $base . '/' . $path;
    }

    private function recordLiveEmailUnsubscribeEvent(?array $tokenRow, ?int $workspaceId, string $eventType, string $status, array $requestMeta = [], array $metadata = []): void
    {
        if (!Database::tableExists('marketing_live_email_unsubscribe_events')) {
            return;
        }
        $workspaceId = $workspaceId ?: (int) ($tokenRow['workspace_id'] ?? 0);
        if ($workspaceId <= 0) {
            return;
        }

        $ip = trim((string) ($requestMeta['ip'] ?? $requestMeta['remote_addr'] ?? ''));
        $agent = trim((string) ($requestMeta['user_agent'] ?? $requestMeta['http_user_agent'] ?? ''));
        Database::execute(
            "INSERT INTO marketing_live_email_unsubscribe_events
             (workspace_id, uuid, token_id, email_run_id, handoff_id, contact_id, recipient_email,
              event_type, status, ip_hash, user_agent_hash, metadata_json)
             VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)",
            [
                $workspaceId,
                $this->generateUuid(),
                !empty($tokenRow['id']) ? (int) $tokenRow['id'] : null,
                !empty($tokenRow['email_run_id']) ? (int) $tokenRow['email_run_id'] : null,
                !empty($tokenRow['handoff_id']) ? (int) $tokenRow['handoff_id'] : null,
                !empty($tokenRow['contact_id']) ? (int) $tokenRow['contact_id'] : null,
                !empty($tokenRow['recipient_email']) ? mb_substr(Security::sanitizeInput((string) $tokenRow['recipient_email'], 'string'), 0, 255) : null,
                $this->normalizeEnum($eventType, self::LIVE_EMAIL_UNSUBSCRIBE_EVENT_TYPES, 'live_email_unsubscribe_event'),
                $this->normalizeEnum($status, ['info', 'success', 'blocked', 'failed'], 'live_email_unsubscribe_event_status'),
                $ip !== '' ? hash('sha256', $ip) : null,
                $agent !== '' ? hash('sha256', $agent) : null,
                $this->normalizeJsonValue($this->sanitizeJsonCompatible($metadata + [
                    'source' => 'marketing_live_email_unsubscribe',
                    'raw_ip_visible' => false,
                    'raw_user_agent_visible' => false,
                ])),
            ]
        );
    }

    private function liveEmailWorkerThrottleSnapshot(array $schedule): array
    {
        $hourlyCap = max(0, (int) ($schedule['hourly_send_cap'] ?? 0));
        $dailyCap = max(0, (int) ($schedule['daily_send_cap'] ?? 0));
        $minSeconds = max(0, (int) ($schedule['min_seconds_between_sends'] ?? 0));
        $sentHour = 0;
        $sentDay = 0;
        $lastSendAt = null;
        $lastSendAgeSeconds = null;

        if (Database::tableExists('marketing_live_email_delivery_proofs')) {
            $sentHour = (int) (Database::queryOne(
                "SELECT COUNT(*) AS count
                 FROM marketing_live_email_delivery_proofs
                 WHERE workspace_id = ?
                   AND proof_status IN ('sent', 'simulated')
                   AND proved_at >= DATE_SUB(NOW(), INTERVAL 1 HOUR)",
                [$this->workspaceId()]
            )['count'] ?? 0);
            $sentDay = (int) (Database::queryOne(
                "SELECT COUNT(*) AS count
                 FROM marketing_live_email_delivery_proofs
                 WHERE workspace_id = ?
                   AND proof_status IN ('sent', 'simulated')
                   AND proved_at >= CURDATE()",
                [$this->workspaceId()]
            )['count'] ?? 0);
            $last = Database::queryOne(
                "SELECT MAX(proved_at) AS last_send_at,
                        TIMESTAMPDIFF(SECOND, MAX(proved_at), NOW()) AS age_seconds
                 FROM marketing_live_email_delivery_proofs
                 WHERE workspace_id = ?
                   AND proof_status IN ('sent', 'simulated')",
                [$this->workspaceId()]
            ) ?: [];
            $lastSendAt = $last['last_send_at'] ?? null;
            $lastSendAgeSeconds = $lastSendAt !== null ? (int) ($last['age_seconds'] ?? 0) : null;
        }

        $hourlyRemaining = $hourlyCap > 0 ? max(0, $hourlyCap - $sentHour) : null;
        $dailyRemaining = $dailyCap > 0 ? max(0, $dailyCap - $sentDay) : null;
        $remainingValues = array_values(array_filter([$hourlyRemaining, $dailyRemaining], static fn($value): bool => $value !== null));
        $remainingCapacity = $remainingValues !== [] ? min($remainingValues) : null;
        $gapRemaining = $minSeconds > 0 && $lastSendAgeSeconds !== null
            ? max(0, $minSeconds - $lastSendAgeSeconds)
            : 0;

        return [
            'hourly_send_cap' => $hourlyCap,
            'daily_send_cap' => $dailyCap,
            'sent_last_hour' => $sentHour,
            'sent_today' => $sentDay,
            'hourly_remaining' => $hourlyRemaining,
            'daily_remaining' => $dailyRemaining,
            'remaining_capacity' => $remainingCapacity,
            'min_seconds_between_sends' => $minSeconds,
            'last_send_at' => $lastSendAt,
            'last_send_age_seconds' => $lastSendAgeSeconds,
            'send_gap_remaining_seconds' => $gapRemaining,
            'throttled' => ($remainingCapacity !== null && $remainingCapacity <= 0) || $gapRemaining > 0,
        ];
    }

    private function liveEmailWorkerScheduleBlockers(array $schedule, array $throttle): array
    {
        $blockers = [];
        if (!empty($schedule['emergency_paused'])) {
            $blockers[] = 'emergency_paused';
        }
        $status = (string) ($schedule['status'] ?? 'planned');
        if ($status === 'paused') {
            $blockers[] = 'worker_schedule_paused';
        } elseif ($status === 'disabled') {
            $blockers[] = 'worker_schedule_disabled';
        }
        if (($throttle['hourly_remaining'] ?? null) !== null && (int) $throttle['hourly_remaining'] <= 0) {
            $blockers[] = 'hourly_send_cap_reached';
        }
        if (($throttle['daily_remaining'] ?? null) !== null && (int) $throttle['daily_remaining'] <= 0) {
            $blockers[] = 'daily_send_cap_reached';
        }
        if ((int) ($throttle['send_gap_remaining_seconds'] ?? 0) > 0) {
            $blockers[] = 'send_gap_waiting';
        }

        return array_values(array_unique($blockers));
    }

    private function liveQueueDispatcherScheduleBlockers(array $schedule, string $source): array
    {
        $blockers = [];
        if (!empty($schedule['emergency_paused'])) {
            $blockers[] = 'dispatcher_emergency_paused';
        }
        $status = (string) ($schedule['status'] ?? 'planned');
        if (in_array($source, ['cli', 'cron', 'api'], true)) {
            if (empty($schedule['configured'])) {
                $blockers[] = 'dispatcher_schedule_not_configured';
            }
            if ($status !== 'active') {
                $blockers[] = 'dispatcher_schedule_not_active';
            }
        }
        if ($status === 'disabled') {
            $blockers[] = 'dispatcher_schedule_disabled';
        }

        return array_values(array_unique($blockers));
    }

