    private function liveOrchestratorScheduleSnapshot(): array
    {
        $command = 'php cli/run_marketing_live_execution.php all 25 --source=cron';
        $schedule = $this->liveEmailWorkerScheduleSnapshot(self::LIVE_ORCHESTRATOR_WORKER_KEY);
        if ((string) ($schedule['status'] ?? '') === 'unavailable') {
            $schedule['schedule_label'] = 'Marketing live orchestrator';
            $schedule['command'] = $command;

            return $schedule;
        }
        if (empty($schedule['configured'])) {
            $schedule['schedule_label'] = 'Marketing live orchestrator';
            $schedule['command'] = $command;
            $schedule['max_handoffs_per_run'] = 25;
            $schedule['message'] = 'Marketing live orchestrator schedule has not been configured yet.';

            return $schedule;
        }
        if ((string) ($schedule['schedule_label'] ?? '') === 'Marketing live email worker') {
            $schedule['schedule_label'] = 'Marketing live orchestrator';
        }
        if (in_array((string) ($schedule['command'] ?? ''), [
            'php cli/process_marketing_live_email_handoffs.php all 25',
            'php scripts/run_marketing_live_orchestrator.php all 25',
        ], true)) {
            $schedule['command'] = $command;
        }
        $schedule['message'] = !empty($schedule['emergency_paused'])
            ? 'Marketing live orchestrator is emergency paused.'
            : (!empty($schedule['stale'])
                ? 'Marketing live orchestrator has missed its configured freshness window.'
                : ((string) ($schedule['status'] ?? 'planned') === 'active'
                    ? 'Marketing live orchestrator schedule is active.'
                    : 'Marketing live orchestrator schedule is not active.'));

        return $schedule;
    }

