    private function liveEmailWorkerScheduleSnapshot(string $workerKey): array
    {
        $default = [
            'worker_key' => $workerKey,
            'status' => 'planned',
            'schedule_label' => 'Marketing live email worker',
            'command' => 'php cli/process_marketing_live_email_handoffs.php all 25',
            'expected_interval_minutes' => 5,
            'max_stale_minutes' => 30,
            'max_handoffs_per_run' => 25,
            'min_seconds_between_sends' => 0,
            'hourly_send_cap' => 0,
            'daily_send_cap' => 0,
            'emergency_paused' => false,
            'emergency_paused_at' => null,
            'emergency_paused_by' => null,
            'emergency_pause_reason' => null,
            'last_confirmed_at' => null,
            'next_check_at' => null,
            'confirmed_by' => null,
            'configured' => false,
            'message' => 'Marketing live email worker schedule has not been configured yet.',
        ];
        if (!Database::tableExists('marketing_live_worker_schedules')) {
            return array_merge($default, ['status' => 'unavailable', 'message' => 'Marketing live worker schedule table is unavailable.']);
        }

        $row = Database::queryOne(
            "SELECT *,
                    TIMESTAMPDIFF(MINUTE, last_confirmed_at, NOW()) AS last_confirmed_age_minutes,
                    TIMESTAMPDIFF(MINUTE, NOW(), next_check_at) AS minutes_until_next_check
             FROM marketing_live_worker_schedules
             WHERE workspace_id = ? AND worker_key = ?
             LIMIT 1",
            [$this->workspaceId(), $workerKey]
        );
        if (!$row) {
            return $default;
        }

        $status = (string) ($row['status'] ?? 'planned');
        $lastConfirmedAge = isset($row['last_confirmed_age_minutes']) ? (int) $row['last_confirmed_age_minutes'] : null;
        $maxStale = max(1, (int) ($row['max_stale_minutes'] ?? 30));
        $stale = $status === 'active' && $lastConfirmedAge !== null && $lastConfirmedAge >= $maxStale;
        $emergencyPausedAt = $row['emergency_paused_at'] ?? null;
        $emergencyPaused = !empty($emergencyPausedAt);

        return [
            'worker_key' => $workerKey,
            'status' => $status,
            'schedule_label' => (string) (($row['schedule_label'] ?? null) ?: 'Marketing live email worker'),
            'command' => (string) (($row['command'] ?? null) ?: 'php cli/process_marketing_live_email_handoffs.php all 25'),
            'expected_interval_minutes' => max(1, (int) ($row['expected_interval_minutes'] ?? 5)),
            'max_stale_minutes' => $maxStale,
            'max_handoffs_per_run' => min(max((int) ($row['max_handoffs_per_run'] ?? 25), 1), 200),
            'min_seconds_between_sends' => min(max((int) ($row['min_seconds_between_sends'] ?? 0), 0), 3600),
            'hourly_send_cap' => min(max((int) ($row['hourly_send_cap'] ?? 0), 0), 100000),
            'daily_send_cap' => min(max((int) ($row['daily_send_cap'] ?? 0), 0), 1000000),
            'emergency_paused' => $emergencyPaused,
            'emergency_paused_at' => $emergencyPausedAt,
            'emergency_paused_by' => !empty($row['emergency_paused_by']) ? (int) $row['emergency_paused_by'] : null,
            'emergency_pause_reason' => $row['emergency_pause_reason'] ?? null,
            'last_confirmed_at' => $row['last_confirmed_at'] ?? null,
            'last_confirmed_age_minutes' => $lastConfirmedAge,
            'next_check_at' => $row['next_check_at'] ?? null,
            'minutes_until_next_check' => isset($row['minutes_until_next_check']) ? (int) $row['minutes_until_next_check'] : null,
            'confirmed_by' => !empty($row['confirmed_by']) ? (int) $row['confirmed_by'] : null,
            'configured' => true,
            'stale' => $stale,
            'message' => $emergencyPaused
                ? 'Marketing live email worker is emergency paused.'
                : ($stale
                ? 'Marketing live email worker has missed its configured freshness window.'
                : ($status === 'active' ? 'Marketing live email worker schedule is active.' : 'Marketing live email worker schedule is not active.')),
        ];
    }

    private function markLiveEmailWorkerScheduleConfirmed(string $workerKey, string $source, ?int $actorId = null): void
    {
        if (!Database::tableExists('marketing_live_worker_schedules')) {
            return;
        }
        $schedule = $this->liveEmailWorkerScheduleSnapshot($workerKey);
        $interval = max(1, (int) ($schedule['expected_interval_minutes'] ?? 5));
        Database::execute(
            "UPDATE marketing_live_worker_schedules
             SET last_confirmed_at = NOW(),
                 next_check_at = DATE_ADD(NOW(), INTERVAL {$interval} MINUTE),
                 confirmed_by = ?,
                 metadata_json = ?,
                 updated_at = NOW()
             WHERE workspace_id = ? AND worker_key = ?",
            [
                ($actorId ?? $this->currentUserId()) ?: null,
                $this->normalizeJsonValue([
                    'last_confirmation_source' => $source,
                    'secret_safe' => true,
                    'raw_secret_values_visible' => false,
                ]),
                $this->workspaceId(),
                $workerKey,
            ]
        );
    }

    private function liveEmailWorkerLeaseSnapshot(string $workerKey): array
    {
        if (!Database::tableExists('marketing_live_worker_leases')) {
            return [
                'worker_key' => $workerKey,
                'status' => 'unavailable',
                'active' => false,
                'message' => 'Marketing live worker lease table is unavailable.',
            ];
        }

        $lease = Database::queryOne(
            "SELECT *,
                    TIMESTAMPDIFF(SECOND, heartbeat_at, NOW()) AS heartbeat_age_seconds,
                    TIMESTAMPDIFF(SECOND, NOW(), expires_at) AS seconds_until_expiry
             FROM marketing_live_worker_leases
             WHERE workspace_id = ? AND worker_key = ?
             LIMIT 1",
            [$this->workspaceId(), $workerKey]
        );
        if (!$lease) {
            return [
                'worker_key' => $workerKey,
                'status' => 'not_acquired',
                'active' => false,
                'message' => 'No Marketing live worker lease has been acquired yet.',
            ];
        }

        $status = (string) ($lease['status'] ?? 'released');
        $secondsUntilExpiry = isset($lease['seconds_until_expiry']) ? (int) $lease['seconds_until_expiry'] : null;
        $active = $status === 'running' && $secondsUntilExpiry !== null && $secondsUntilExpiry > 0;
        if ($status === 'running' && !$active) {
            $status = 'expired';
        }
        $metadata = !empty($lease['metadata_json']) && is_string($lease['metadata_json'])
            ? (json_decode((string) $lease['metadata_json'], true) ?: [])
            : (is_array($lease['metadata_json'] ?? null) ? $lease['metadata_json'] : []);

        return [
            'worker_key' => $workerKey,
            'status' => $status,
            'active' => $active,
            'run_id' => !empty($lease['run_id']) ? (int) $lease['run_id'] : null,
            'dispatch_run_id' => !empty($lease['dispatch_run_id']) ? (int) $lease['dispatch_run_id'] : null,
            'source' => (string) ($lease['source'] ?? 'cli'),
            'acquired_at' => $lease['acquired_at'] ?? null,
            'heartbeat_at' => $lease['heartbeat_at'] ?? null,
            'heartbeat_age_seconds' => isset($lease['heartbeat_age_seconds']) ? max(0, (int) $lease['heartbeat_age_seconds']) : null,
            'expires_at' => $lease['expires_at'] ?? null,
            'seconds_until_expiry' => $secondsUntilExpiry,
            'released_at' => $lease['released_at'] ?? null,
            'metadata_json' => $metadata,
            'message' => $active
                ? 'A Marketing live worker lease is currently active.'
                : ($status === 'expired' ? 'The latest Marketing live worker lease has expired.' : 'No active Marketing live worker lease is running.'),
        ];
    }

    private function acquireLiveEmailWorkerLease(int $runId, string $workerKey, string $source, int $ttlSeconds, bool $force = false): array
    {
        if (!Database::tableExists('marketing_live_worker_leases')) {
            return [
                'acquired' => true,
                'worker_key' => $workerKey,
                'lease_token' => null,
                'status' => 'unavailable',
                'message' => 'Lease table unavailable; worker continues for backwards compatibility.',
            ];
        }

        $ttlSeconds = min(max($ttlSeconds, 60), 3600);
        $leaseToken = $this->generateUuid();
        Database::execute(
            "INSERT IGNORE INTO marketing_live_worker_leases
             (workspace_id, uuid, worker_key, status, metadata_json, created_at, updated_at)
             VALUES (?, ?, ?, 'released', ?, NOW(), NOW())",
            [
                $this->workspaceId(),
                $this->generateUuid(),
                $workerKey,
                $this->normalizeJsonValue(['source' => 'lease_placeholder', 'secret_safe' => true]),
            ]
        );

        $updated = Database::execute(
            "UPDATE marketing_live_worker_leases
             SET run_id = ?,
                 lease_token = ?,
                 source = ?,
                 status = 'running',
                 acquired_at = NOW(),
                 heartbeat_at = NOW(),
                 expires_at = DATE_ADD(NOW(), INTERVAL {$ttlSeconds} SECOND),
                 released_at = NULL,
                 metadata_json = ?,
                 updated_at = NOW()
             WHERE workspace_id = ?
               AND worker_key = ?
               AND (? = 1 OR status <> 'running' OR expires_at IS NULL OR expires_at <= NOW())",
            [
                $runId,
                $leaseToken,
                $this->normalizeEnum($source, self::LIVE_EMAIL_WORKER_RUN_SOURCES, 'live_email_worker_source'),
                $this->normalizeJsonValue([
                    'run_id' => $runId,
                    'lease_ttl_seconds' => $ttlSeconds,
                    'force_lease' => $force,
                    'secret_safe' => true,
                    'raw_secret_values_visible' => false,
                ]),
                $this->workspaceId(),
                $workerKey,
                $force ? 1 : 0,
            ]
        );

        $snapshot = $this->liveEmailWorkerLeaseSnapshot($workerKey);
        $acquired = $updated > 0 && (int) ($snapshot['run_id'] ?? 0) === $runId;
        if ($acquired) {
            return array_merge($snapshot, [
                'acquired' => true,
                'lease_token' => $leaseToken,
                'lease_ttl_seconds' => $ttlSeconds,
            ]);
        }

        return array_merge($snapshot, [
            'acquired' => false,
            'lease_token' => null,
            'lease_ttl_seconds' => $ttlSeconds,
            'active_run_id' => $snapshot['run_id'] ?? null,
            'message' => 'A Marketing live worker lease is already active for this workspace.',
        ]);
    }

    private function acquireLiveQueueDispatcherLease(int $dispatchRunId, string $source, int $ttlSeconds, bool $force = false): array
    {
        $workerKey = self::LIVE_QUEUE_DISPATCHER_WORKER_KEY;
        if (!Database::tableExists('marketing_live_worker_leases')) {
            return [
                'acquired' => true,
                'worker_key' => $workerKey,
                'lease_token' => null,
                'status' => 'unavailable',
                'message' => 'Lease table unavailable; dispatcher continues for backwards compatibility.',
            ];
        }

        $ttlSeconds = min(max($ttlSeconds, 60), 3600);
        $leaseToken = $this->generateUuid();
        Database::execute(
            "INSERT IGNORE INTO marketing_live_worker_leases
             (workspace_id, uuid, worker_key, status, metadata_json, created_at, updated_at)
             VALUES (?, ?, ?, 'released', ?, NOW(), NOW())",
            [
                $this->workspaceId(),
                $this->generateUuid(),
                $workerKey,
                $this->normalizeJsonValue(['source' => 'dispatcher_lease_placeholder', 'secret_safe' => true]),
            ]
        );

        $hasDispatchRunColumn = Database::columnExists('marketing_live_worker_leases', 'dispatch_run_id');
        $setDispatchRun = $hasDispatchRunColumn ? 'dispatch_run_id = ?,' : '';
        $params = [
            $leaseToken,
            $this->normalizeEnum($source, self::LIVE_EMAIL_WORKER_RUN_SOURCES, 'live_dispatch_source'),
            $this->normalizeJsonValue([
                'dispatch_run_id' => $dispatchRunId,
                'lease_ttl_seconds' => $ttlSeconds,
                'force_lease' => $force,
                'secret_safe' => true,
                'raw_secret_values_visible' => false,
            ]),
            $this->workspaceId(),
            $workerKey,
            $force ? 1 : 0,
        ];
        if ($hasDispatchRunColumn) {
            array_unshift($params, $dispatchRunId);
        }

        $updated = Database::execute(
            "UPDATE marketing_live_worker_leases
             SET run_id = NULL,
                 {$setDispatchRun}
                 lease_token = ?,
                 source = ?,
                 status = 'running',
                 acquired_at = NOW(),
                 heartbeat_at = NOW(),
                 expires_at = DATE_ADD(NOW(), INTERVAL {$ttlSeconds} SECOND),
                 released_at = NULL,
                 metadata_json = ?,
                 updated_at = NOW()
             WHERE workspace_id = ?
               AND worker_key = ?
               AND (? = 1 OR status <> 'running' OR expires_at IS NULL OR expires_at <= NOW())",
            $params
        );

        $snapshot = $this->liveEmailWorkerLeaseSnapshot($workerKey);
        $snapshotDispatchRunId = (int) ($snapshot['dispatch_run_id'] ?? ($snapshot['metadata_json']['dispatch_run_id'] ?? 0));
        $acquired = $updated > 0 && $snapshotDispatchRunId === $dispatchRunId;
        if ($acquired) {
            return array_merge($snapshot, [
                'acquired' => true,
                'lease_token' => $leaseToken,
                'lease_ttl_seconds' => $ttlSeconds,
            ]);
        }

        return array_merge($snapshot, [
            'acquired' => false,
            'lease_token' => null,
            'lease_ttl_seconds' => $ttlSeconds,
            'active_dispatch_run_id' => $snapshot['dispatch_run_id'] ?? ($snapshot['metadata_json']['dispatch_run_id'] ?? null),
            'message' => 'A Marketing live queue dispatcher lease is already active for this workspace.',
        ]);
    }

    private function heartbeatLiveEmailWorkerLease(int $runId, string $leaseToken, int $ttlSeconds, string $workerKey = 'marketing_live_email_handoffs'): bool
    {
        if ($leaseToken === '' || !Database::tableExists('marketing_live_worker_leases')) {
            return true;
        }
        $ttlSeconds = min(max($ttlSeconds, 60), 3600);

        return Database::execute(
            "UPDATE marketing_live_worker_leases
             SET heartbeat_at = NOW(),
                 expires_at = DATE_ADD(NOW(), INTERVAL {$ttlSeconds} SECOND),
                 updated_at = NOW()
             WHERE workspace_id = ?
               AND worker_key = ?
               AND run_id = ?
               AND lease_token = ?
               AND status = 'running'",
            [$this->workspaceId(), $workerKey, $runId, $leaseToken]
        ) > 0;
    }

    private function releaseLiveEmailWorkerLease(int $runId, string $leaseToken, string $status, string $workerKey = 'marketing_live_email_handoffs'): void
    {
        if ($leaseToken === '' || !Database::tableExists('marketing_live_worker_leases')) {
            return;
        }

        Database::execute(
            "UPDATE marketing_live_worker_leases
             SET status = ?,
                 released_at = NOW(),
                 heartbeat_at = NOW(),
                 updated_at = NOW()
             WHERE workspace_id = ?
               AND worker_key = ?
               AND run_id = ?
               AND lease_token = ?",
            [
                $this->normalizeEnum($status, self::LIVE_WORKER_LEASE_STATUSES, 'live_worker_lease_status'),
                $this->workspaceId(),
                $workerKey,
                $runId,
                $leaseToken,
            ]
        );
    }

    private function heartbeatLiveQueueDispatcherLease(int $dispatchRunId, string $leaseToken, int $ttlSeconds): bool
    {
        if ($leaseToken === '' || !Database::tableExists('marketing_live_worker_leases')) {
            return true;
        }
        $ttlSeconds = min(max($ttlSeconds, 60), 3600);
        $dispatchRunClause = Database::columnExists('marketing_live_worker_leases', 'dispatch_run_id')
            ? 'AND dispatch_run_id = ?'
            : '';
        $params = [$this->workspaceId(), self::LIVE_QUEUE_DISPATCHER_WORKER_KEY];
        if ($dispatchRunClause !== '') {
            $params[] = $dispatchRunId;
        }
        $params[] = $leaseToken;

        return Database::execute(
            "UPDATE marketing_live_worker_leases
             SET heartbeat_at = NOW(),
                 expires_at = DATE_ADD(NOW(), INTERVAL {$ttlSeconds} SECOND),
                 updated_at = NOW()
             WHERE workspace_id = ?
               AND worker_key = ?
               {$dispatchRunClause}
               AND lease_token = ?
               AND status = 'running'",
            $params
        ) > 0;
    }

    private function releaseLiveQueueDispatcherLease(int $dispatchRunId, string $leaseToken, string $status): void
    {
        if ($leaseToken === '' || !Database::tableExists('marketing_live_worker_leases')) {
            return;
        }
        $dispatchRunClause = Database::columnExists('marketing_live_worker_leases', 'dispatch_run_id')
            ? 'AND dispatch_run_id = ?'
            : '';
        $params = [
            $this->normalizeEnum($status, self::LIVE_WORKER_LEASE_STATUSES, 'live_worker_lease_status'),
            $this->workspaceId(),
            self::LIVE_QUEUE_DISPATCHER_WORKER_KEY,
        ];
        if ($dispatchRunClause !== '') {
            $params[] = $dispatchRunId;
        }
        $params[] = $leaseToken;

        Database::execute(
            "UPDATE marketing_live_worker_leases
             SET status = ?,
                 released_at = NOW(),
                 heartbeat_at = NOW(),
                 updated_at = NOW()
             WHERE workspace_id = ?
               AND worker_key = ?
               {$dispatchRunClause}
               AND lease_token = ?",
            $params
        );
    }

    private function liveChannelWorkerScheduleSnapshot(): array
    {
        $command = 'php cli/process_marketing_live_channel_handoffs.php all 25';
        $schedule = $this->liveEmailWorkerScheduleSnapshot(self::LIVE_CHANNEL_WORKER_KEY);
        if ((string) ($schedule['status'] ?? '') === 'unavailable') {
            $schedule['schedule_label'] = 'Marketing live channel worker';
            $schedule['command'] = $command;

            return $schedule;
        }
        if (empty($schedule['configured'])) {
            $schedule['schedule_label'] = 'Marketing live channel worker';
            $schedule['command'] = $command;
            $schedule['max_handoffs_per_run'] = 25;
            $schedule['message'] = 'Marketing live channel worker schedule has not been configured yet.';

            return $schedule;
        }
        if ((string) ($schedule['schedule_label'] ?? '') === 'Marketing live email worker') {
            $schedule['schedule_label'] = 'Marketing live channel worker';
        }
        if ((string) ($schedule['command'] ?? '') === 'php cli/process_marketing_live_email_handoffs.php all 25') {
            $schedule['command'] = $command;
        }
        $schedule['message'] = !empty($schedule['emergency_paused'])
            ? 'Marketing live channel worker is emergency paused.'
            : (!empty($schedule['stale'])
                ? 'Marketing live channel worker has missed its configured freshness window.'
                : ((string) ($schedule['status'] ?? 'planned') === 'active'
                    ? 'Marketing live channel worker schedule is active.'
                    : 'Marketing live channel worker schedule is not active.'));

        return $schedule;
    }

    private function liveChannelWorkerThrottleSnapshot(array $schedule): array
    {
        $hourlyCap = max(0, (int) ($schedule['hourly_send_cap'] ?? 0));
        $dailyCap = max(0, (int) ($schedule['daily_send_cap'] ?? 0));
        $minSeconds = max(0, (int) ($schedule['min_seconds_between_sends'] ?? 0));
        $sentHour = 0;
        $sentDay = 0;
        $lastSendAt = null;
        $lastSendAgeSeconds = null;

        if (Database::tableExists('marketing_live_channel_delivery_proofs')) {
            $sentStatuses = "('sent','delivered','read')";
            $sentHour = (int) (Database::queryOne(
                "SELECT COUNT(*) AS count
                 FROM marketing_live_channel_delivery_proofs
                 WHERE workspace_id = ?
                   AND proof_status IN {$sentStatuses}
                   AND proved_at >= DATE_SUB(NOW(), INTERVAL 1 HOUR)",
                [$this->workspaceId()]
            )['count'] ?? 0);
            $sentDay = (int) (Database::queryOne(
                "SELECT COUNT(*) AS count
                 FROM marketing_live_channel_delivery_proofs
                 WHERE workspace_id = ?
                   AND proof_status IN {$sentStatuses}
                   AND proved_at >= CURDATE()",
                [$this->workspaceId()]
            )['count'] ?? 0);
            $last = Database::queryOne(
                "SELECT MAX(proved_at) AS last_send_at,
                        TIMESTAMPDIFF(SECOND, MAX(proved_at), NOW()) AS age_seconds
                 FROM marketing_live_channel_delivery_proofs
                 WHERE workspace_id = ?
                   AND proof_status IN {$sentStatuses}",
                [$this->workspaceId()]
            ) ?: [];
            $lastSendAt = $last['last_send_at'] ?? null;
            $lastSendAgeSeconds = $lastSendAt !== null ? (int) ($last['age_seconds'] ?? 0) : null;
        }

        $hourlyRemaining = $hourlyCap > 0 ? max(0, $hourlyCap - $sentHour) : null;
        $dailyRemaining = $dailyCap > 0 ? max(0, $dailyCap - $sentDay) : null;
        $remainingValues = array_values(array_filter([$hourlyRemaining, $dailyRemaining], static fn($value): bool => $value !== null));
        $remainingCapacity = $remainingValues !== [] ? min($remainingValues) : null;
        $gapRemaining = $minSeconds > 0 && $lastSendAgeSeconds !== null
            ? max(0, $minSeconds - $lastSendAgeSeconds)
            : 0;

        return [
            'hourly_send_cap' => $hourlyCap,
            'daily_send_cap' => $dailyCap,
            'sent_last_hour' => $sentHour,
            'sent_today' => $sentDay,
            'hourly_remaining' => $hourlyRemaining,
            'daily_remaining' => $dailyRemaining,
            'remaining_capacity' => $remainingCapacity,
            'min_seconds_between_sends' => $minSeconds,
            'last_send_at' => $lastSendAt,
            'last_send_age_seconds' => $lastSendAgeSeconds,
            'send_gap_remaining_seconds' => $gapRemaining,
            'throttled' => ($remainingCapacity !== null && $remainingCapacity <= 0) || $gapRemaining > 0,
        ];
    }

    private function liveChannelWorkerScheduleBlockers(array $schedule, array $throttle, string $source): array
    {
        $blockers = [];
        if (!empty($schedule['emergency_paused'])) {
            $blockers[] = 'channel_worker_emergency_paused';
        }
        $status = (string) ($schedule['status'] ?? 'planned');
        if (in_array($source, ['cli', 'cron', 'api'], true)) {
            if (empty($schedule['configured'])) {
                $blockers[] = 'channel_worker_schedule_not_configured';
            }
            if ($status !== 'active') {
                $blockers[] = 'channel_worker_schedule_not_active';
            }
        }
        if ($status === 'paused') {
            $blockers[] = 'channel_worker_schedule_paused';
        } elseif ($status === 'disabled') {
            $blockers[] = 'channel_worker_schedule_disabled';
        }
        if (($throttle['hourly_remaining'] ?? null) !== null && (int) $throttle['hourly_remaining'] <= 0) {
            $blockers[] = 'channel_worker_hourly_send_cap_reached';
        }
        if (($throttle['daily_remaining'] ?? null) !== null && (int) $throttle['daily_remaining'] <= 0) {
            $blockers[] = 'channel_worker_daily_send_cap_reached';
        }
        if ((int) ($throttle['send_gap_remaining_seconds'] ?? 0) > 0) {
            $blockers[] = 'channel_worker_send_gap_waiting';
        }

        return array_values(array_unique($blockers));
    }

