    private function acquireLiveChannelWorkerLease(int $runId, string $source, int $ttlSeconds, bool $force = false): array
    {
        $workerKey = self::LIVE_CHANNEL_WORKER_KEY;
        if (!Database::tableExists('marketing_live_worker_leases')) {
            return [
                'acquired' => true,
                'worker_key' => $workerKey,
                'lease_token' => null,
                'status' => 'unavailable',
                'message' => 'Lease table unavailable; worker continues for backwards compatibility.',
            ];
        }
        if (!Database::columnExists('marketing_live_worker_leases', 'channel_worker_run_id')) {
            return [
                'acquired' => false,
                'worker_key' => $workerKey,
                'lease_token' => null,
                'status' => 'unavailable',
                'message' => 'Lease table is missing channel worker support. Run the latest migrations.',
            ];
        }

        $ttlSeconds = min(max($ttlSeconds, 60), 3600);
        $leaseToken = $this->generateUuid();
        Database::execute(
            "INSERT IGNORE INTO marketing_live_worker_leases
             (workspace_id, uuid, worker_key, status, metadata_json, created_at, updated_at)
             VALUES (?, ?, ?, 'released', ?, NOW(), NOW())",
            [
                $this->workspaceId(),
                $this->generateUuid(),
                $workerKey,
                $this->normalizeJsonValue(['source' => 'channel_worker_lease_placeholder', 'secret_safe' => true]),
            ]
        );

        $updated = Database::execute(
            "UPDATE marketing_live_worker_leases
             SET run_id = NULL,
                 dispatch_run_id = NULL,
                 channel_worker_run_id = ?,
                 lease_token = ?,
                 source = ?,
                 status = 'running',
                 acquired_at = NOW(),
                 heartbeat_at = NOW(),
                 expires_at = DATE_ADD(NOW(), INTERVAL {$ttlSeconds} SECOND),
                 released_at = NULL,
                 metadata_json = ?,
                 updated_at = NOW()
             WHERE workspace_id = ?
               AND worker_key = ?
               AND (? = 1 OR status <> 'running' OR expires_at IS NULL OR expires_at <= NOW())",
            [
                $runId,
                $leaseToken,
                $this->normalizeEnum($source, self::LIVE_EMAIL_WORKER_RUN_SOURCES, 'live_channel_worker_source'),
                $this->normalizeJsonValue([
                    'channel_worker_run_id' => $runId,
                    'lease_ttl_seconds' => $ttlSeconds,
                    'force_lease' => $force,
                    'secret_safe' => true,
                    'raw_secret_values_visible' => false,
                ]),
                $this->workspaceId(),
                $workerKey,
                $force ? 1 : 0,
            ]
        );

        $snapshot = $this->liveChannelWorkerLeaseSnapshot();
        $acquired = $updated > 0 && (int) ($snapshot['channel_worker_run_id'] ?? 0) === $runId;
        if ($acquired) {
            return array_merge($snapshot, [
                'acquired' => true,
                'lease_token' => $leaseToken,
                'lease_ttl_seconds' => $ttlSeconds,
            ]);
        }

        return array_merge($snapshot, [
            'acquired' => false,
            'lease_token' => null,
            'lease_ttl_seconds' => $ttlSeconds,
            'active_channel_worker_run_id' => $snapshot['channel_worker_run_id'] ?? null,
            'message' => 'A Marketing live channel worker lease is already active for this workspace.',
        ]);
    }

    private function heartbeatLiveChannelWorkerLease(int $runId, string $leaseToken, int $ttlSeconds): bool
    {
        if ($leaseToken === '' || !Database::tableExists('marketing_live_worker_leases') || !Database::columnExists('marketing_live_worker_leases', 'channel_worker_run_id')) {
            return true;
        }
        $ttlSeconds = min(max($ttlSeconds, 60), 3600);

        return Database::execute(
            "UPDATE marketing_live_worker_leases
             SET heartbeat_at = NOW(),
                 expires_at = DATE_ADD(NOW(), INTERVAL {$ttlSeconds} SECOND),
                 updated_at = NOW()
             WHERE workspace_id = ?
               AND worker_key = ?
               AND channel_worker_run_id = ?
               AND lease_token = ?
               AND status = 'running'",
            [$this->workspaceId(), self::LIVE_CHANNEL_WORKER_KEY, $runId, $leaseToken]
        ) > 0;
    }

    private function releaseLiveChannelWorkerLease(int $runId, string $leaseToken, string $status): void
    {
        if ($leaseToken === '' || !Database::tableExists('marketing_live_worker_leases') || !Database::columnExists('marketing_live_worker_leases', 'channel_worker_run_id')) {
            return;
        }

        Database::execute(
            "UPDATE marketing_live_worker_leases
             SET status = ?,
                 released_at = NOW(),
                 heartbeat_at = NOW(),
                 updated_at = NOW()
             WHERE workspace_id = ?
               AND worker_key = ?
               AND channel_worker_run_id = ?
               AND lease_token = ?",
            [
                $this->normalizeEnum($status, self::LIVE_WORKER_LEASE_STATUSES, 'live_worker_lease_status'),
                $this->workspaceId(),
                self::LIVE_CHANNEL_WORKER_KEY,
                $runId,
                $leaseToken,
            ]
        );
    }

    private function eligibleLiveChannelHandoffsForWorker(int $limit): array
    {
        if (!Database::tableExists('marketing_live_channel_handoffs')) {
            return [];
        }
        $limit = min(max($limit, 1), 200);
        $canProcessSms = Database::tableExists('sms_queue') && Database::tableExists('sms_messages');
        $canProcessWhatsapp = Database::tableExists('whatsapp_queue') && Database::tableExists('whatsapp_messages');
        if (!$canProcessSms && !$canProcessWhatsapp) {
            return [];
        }

        $rows = [];
        if ($canProcessSms) {
            $rows = array_merge($rows, Database::query(
                "SELECT h.*,
                        meq.execution_type AS queue_execution_type,
                        meq.execution_mode,
                        meq.status AS execution_queue_status,
                        meq.scheduled_at AS execution_queue_scheduled_at,
                        cc.connector_type,
                        cc.status AS connector_status,
                        cc.live_enabled,
                        cc.live_adapter_key,
                        cc.secret_status,
                        cc.live_preflight_status,
                        approval.status AS execution_approval_status,
                        sq.status AS source_queue_status,
                        sq.attempts AS source_queue_attempts,
                        sq.max_attempts AS source_queue_max_attempts,
                        sq.scheduled_at AS source_queue_scheduled_at,
                        sq.last_attempt_at AS source_queue_last_attempt_at,
                        NULL AS source_queue_error_message,
                        sm.status AS source_message_status,
                        sm.provider_message_id AS source_provider_message_id,
                        sm.error_message AS source_error_message,
                        sm.to_number AS source_recipient_identifier,
                        sm.message_type AS source_message_type,
                        NULL AS whatsapp_template_name
                 FROM marketing_live_channel_handoffs h
                 JOIN marketing_execution_queue meq ON meq.id = h.queue_id AND meq.workspace_id = h.workspace_id
                 JOIN sms_queue sq ON sq.id = h.source_queue_id AND sq.workspace_id = h.workspace_id
                 JOIN sms_messages sm ON sm.id = h.source_message_id AND sm.workspace_id = h.workspace_id
                 LEFT JOIN marketing_channel_connectors cc ON cc.id = h.connector_id AND cc.workspace_id = h.workspace_id
                 LEFT JOIN marketing_execution_approvals approval ON approval.id = (
                    SELECT a.id
                    FROM marketing_execution_approvals a
                    WHERE a.workspace_id = h.workspace_id
                      AND a.queue_id = h.queue_id
                    ORDER BY a.created_at DESC, a.id DESC
                    LIMIT 1
                 )
                 WHERE h.workspace_id = ?
                   AND h.status = 'queued'
                   AND h.execution_type = 'sms'
                   AND sq.status = 'pending'
                   AND (sq.scheduled_at IS NULL OR sq.scheduled_at <= NOW())
                 ORDER BY h.created_at ASC, h.id ASC
                 LIMIT {$limit}",
                [$this->workspaceId()]
            ));
        }
        if ($canProcessWhatsapp) {
            $rows = array_merge($rows, Database::query(
                "SELECT h.*,
                        meq.execution_type AS queue_execution_type,
                        meq.execution_mode,
                        meq.status AS execution_queue_status,
                        meq.scheduled_at AS execution_queue_scheduled_at,
                        cc.connector_type,
                        cc.status AS connector_status,
                        cc.live_enabled,
                        cc.live_adapter_key,
                        cc.secret_status,
                        cc.live_preflight_status,
                        approval.status AS execution_approval_status,
                        wq.status AS source_queue_status,
                        wq.attempts AS source_queue_attempts,
                        wq.max_attempts AS source_queue_max_attempts,
                        wq.scheduled_at AS source_queue_scheduled_at,
                        wq.processed_at AS source_queue_last_attempt_at,
                        wq.error_message AS source_queue_error_message,
                        wm.status AS source_message_status,
                        wm.whatsapp_message_id AS source_provider_message_id,
                        wm.error_message AS source_error_message,
                        wm.to_number AS source_recipient_identifier,
                        wm.message_type AS source_message_type,
                        wm.template_name AS whatsapp_template_name
                 FROM marketing_live_channel_handoffs h
                 JOIN marketing_execution_queue meq ON meq.id = h.queue_id AND meq.workspace_id = h.workspace_id
                 JOIN whatsapp_queue wq ON wq.id = h.source_queue_id AND wq.workspace_id = h.workspace_id
                 JOIN whatsapp_messages wm ON wm.id = h.source_message_id AND wm.workspace_id = h.workspace_id
                 LEFT JOIN marketing_channel_connectors cc ON cc.id = h.connector_id AND cc.workspace_id = h.workspace_id
                 LEFT JOIN marketing_execution_approvals approval ON approval.id = (
                    SELECT a.id
                    FROM marketing_execution_approvals a
                    WHERE a.workspace_id = h.workspace_id
                      AND a.queue_id = h.queue_id
                    ORDER BY a.created_at DESC, a.id DESC
                    LIMIT 1
                 )
                 WHERE h.workspace_id = ?
                   AND h.status = 'queued'
                   AND h.execution_type = 'whatsapp'
                   AND wq.status = 'pending'
                   AND (wq.scheduled_at IS NULL OR wq.scheduled_at <= NOW())
                 ORDER BY h.created_at ASC, h.id ASC
                 LIMIT {$limit}",
                [$this->workspaceId()]
            ));
        }

        usort($rows, static function (array $left, array $right): int {
            $leftCreated = (string) ($left['created_at'] ?? '');
            $rightCreated = (string) ($right['created_at'] ?? '');
            if ($leftCreated === $rightCreated) {
                return (int) ($left['id'] ?? 0) <=> (int) ($right['id'] ?? 0);
            }

            return strcmp($leftCreated, $rightCreated);
        });

        return array_slice($rows, 0, $limit);
    }

    private function liveChannelHandoffWorkerBlockers(array $handoff, array $policy): array
    {
        $blockers = [];
        $executionType = $this->normalizeEnum((string) ($handoff['execution_type'] ?? 'sms'), ['sms', 'whatsapp'], 'live_channel_handoff_type');
        $allowedConnectorTypes = (array) ($policy['allowed_connector_types_json'] ?? []);
        $allowedAdapterKeys = (array) ($policy['allowed_adapter_keys_json'] ?? []);
        $adapterKey = (string) ($handoff['live_adapter_key'] ?? '');
        $connectorType = (string) ($handoff['connector_type'] ?? 'other');
        $expectedAdapter = $executionType === 'sms' ? 'crm_sms_queue_handoff' : 'crm_whatsapp_queue_handoff';

        if (empty($policy['live_execution_enabled']) || (string) ($policy['status'] ?? 'disabled') !== 'live_ready') {
            $blockers[] = 'live_policy_not_ready';
        }
        if (!empty($policy['emergency_paused'])) {
            $blockers[] = 'live_execution_emergency_paused';
        }
        if ((string) ($handoff['queue_execution_type'] ?? '') !== $executionType || (string) ($handoff['execution_mode'] ?? '') !== 'live') {
            $blockers[] = 'live_channel_execution_queue_required';
        }
        if ((string) ($handoff['execution_approval_status'] ?? '') !== 'approved') {
            $blockers[] = 'execution_approval_required';
        }
        if (in_array((string) ($handoff['execution_queue_status'] ?? ''), ['cancelled', 'archived', 'blocked', 'failed'], true)) {
            $blockers[] = 'execution_queue_closed_or_failed';
        }
        if ((string) ($handoff['connector_status'] ?? '') !== 'ready') {
            $blockers[] = 'ready_connector_required';
        }
        if (empty($handoff['live_enabled'])) {
            $blockers[] = 'connector_live_not_enabled';
        }
        if ((string) ($handoff['secret_status'] ?? 'not_configured') !== 'verified') {
            $blockers[] = 'verified_secret_reference_required';
        }
        if ((string) ($handoff['live_preflight_status'] ?? 'not_checked') !== 'passed') {
            $blockers[] = 'connector_live_preflight_required';
        }
        if ($allowedConnectorTypes !== [] && !in_array($connectorType, $allowedConnectorTypes, true)) {
            $blockers[] = 'connector_type_not_allowed';
        }
        if ($adapterKey !== $expectedAdapter) {
            $blockers[] = $executionType . '_queue_handoff_adapter_required';
        } elseif ($allowedAdapterKeys !== [] && !in_array($adapterKey, $allowedAdapterKeys, true)) {
            $blockers[] = 'live_adapter_not_allowed';
        }
        if ((string) ($handoff['source_queue_status'] ?? '') !== 'pending') {
            $blockers[] = 'source_queue_not_pending';
        }
        $scheduledAt = $handoff['source_queue_scheduled_at'] ?? null;
        if (!empty($scheduledAt)) {
            $scheduledTs = strtotime((string) $scheduledAt);
            if ($scheduledTs !== false && $scheduledTs > time()) {
                $blockers[] = 'source_queue_not_due';
            }
        }
        if ((int) ($handoff['source_queue_attempts'] ?? 0) >= (int) ($handoff['source_queue_max_attempts'] ?? 3)) {
            $blockers[] = 'source_queue_max_attempts_reached';
        }
        $recipientIdentifier = trim((string) ($handoff['source_recipient_identifier'] ?? $handoff['recipient_identifier'] ?? ''));
        if ($recipientIdentifier === '') {
            $blockers[] = 'recipient_identifier_required';
        } elseif ($this->isMarketingIdentifierSuppressed($executionType, $recipientIdentifier)) {
            $blockers[] = 'recipient_suppressed';
        }
        if ($executionType === 'whatsapp') {
            $messageType = (string) ($handoff['source_message_type'] ?? 'text');
            $templateName = trim((string) ($handoff['whatsapp_template_name'] ?? ''));
            if ($messageType !== 'template' && $templateName === '' && !$this->isWhatsAppMessagingWindowOpen((int) ($handoff['contact_id'] ?? 0))) {
                $blockers[] = 'whatsapp_messaging_window_required';
            }
        }

        return array_values(array_unique($blockers));
    }

    private function updateLiveChannelHandoffFromWorker(int $handoffId, int $runId, string $status, string $message = ''): void
    {
        if (!Database::tableExists('marketing_live_channel_handoffs')) {
            return;
        }
        $status = $this->normalizeEnum($status, ['queued', 'processing', 'sent', 'failed', 'blocked', 'cancelled'], 'live_channel_handoff_status');
        Database::execute(
            "UPDATE marketing_live_channel_handoffs
             SET worker_run_id = ?,
                 status = ?,
                 error_message = ?,
                 updated_at = NOW()
             WHERE workspace_id = ? AND id = ?",
            [
                $runId > 0 ? $runId : null,
                $status,
                trim($message) !== '' ? mb_substr(Security::sanitizeInput($message, 'string'), 0, 500) : null,
                $this->workspaceId(),
                $handoffId,
            ]
        );
    }

    private function processLiveSmsQueueItem(int $sourceQueueId, int $workspaceId): array
    {
        $smsQueue = new \CRM\Services\SMSQueue();
        $job = $smsQueue->pop($workspaceId, $sourceQueueId);
        if (!$job) {
            throw new RuntimeException('SMS queue row is not claimable for this workspace.');
        }

        $service = new SMSService();
        try {
            $result = $service->sendSMS(
                (string) ($job['to_number'] ?? ''),
                (string) ($job['message_body'] ?? ''),
                [
                    'workspace_id' => $workspaceId,
                    'media_url' => !empty($job['media_url']) ? (string) $job['media_url'] : null,
                    'rate_reserved' => true,
                ]
            );
            $providerMessageId = trim((string) ($result['sid'] ?? $result['id'] ?? $result['message_id'] ?? ''));
            $providerStatus = strtolower(trim((string) ($result['status'] ?? 'sent')));
            $messageStatus = in_array($providerStatus, ['sent', 'delivered'], true) ? $providerStatus : 'sent';
            Database::execute(
                "UPDATE sms_messages
                 SET status = ?,
                     provider_message_id = ?,
                     error_message = NULL
                 WHERE workspace_id = ? AND id = ?",
                [
                    $this->normalizeEnum($messageStatus, ['pending', 'queued', 'sent', 'delivered', 'failed', 'undelivered'], 'sms_message_status'),
                    $providerMessageId !== '' ? mb_substr(Security::sanitizeInput($providerMessageId, 'string'), 0, 255) : null,
                    $workspaceId,
                    (int) ($job['message_id'] ?? 0),
                ]
            );
            $smsQueue->complete($sourceQueueId, $workspaceId, (string) ($job['claim_token'] ?? ''));

            return [
                'success' => true,
                'status' => $messageStatus,
                'provider_message_id' => $providerMessageId,
                'sms_message_id' => (int) ($job['message_id'] ?? 0),
                'sms_queue_id' => $sourceQueueId,
                'result' => $this->sanitizeJsonCompatible($result),
            ];
        } catch (Throwable $e) {
            $error = $this->sanitizeLiveProviderError((string) $e->getMessage());
            $smsQueue->fail($sourceQueueId, $error, $workspaceId, (string) ($job['claim_token'] ?? ''));

            throw new RuntimeException($error);
        }
    }

    private function sanitizeLiveProviderError(string $error): string
    {
        $safe = Security::sanitizeInput(trim($error) !== '' ? $error : 'Live provider worker failed.', 'string');
        $safe = preg_replace('/Bearer\s+[A-Za-z0-9._\-~+\/]+=*/i', 'Bearer [hidden]', $safe) ?? $safe;
        $safe = preg_replace('/sk-[A-Za-z0-9_\-]+/i', 'sk-[hidden]', $safe) ?? $safe;
        $safe = preg_replace('/AC[a-f0-9]{32}/i', 'AC[hidden]', $safe) ?? $safe;
        $safe = preg_replace('/Current value in \$_ENV:\s*[\'"][^\'"]+[\'"]/i', 'Current environment value is hidden', $safe) ?? $safe;

        return mb_substr($safe, 0, 500);
    }

    private function liveEmailHandoffWorkerBlockers(array $handoff, array $policy): array
    {
        $blockers = [];
        $allowedConnectorTypes = (array) ($policy['allowed_connector_types_json'] ?? []);
        $allowedAdapterKeys = (array) ($policy['allowed_adapter_keys_json'] ?? []);
        $adapterKey = (string) ($handoff['live_adapter_key'] ?? '');
        $connectorType = (string) ($handoff['connector_type'] ?? 'other');

        if (empty($policy['live_execution_enabled']) || (string) ($policy['status'] ?? 'disabled') !== 'live_ready') {
            $blockers[] = 'live_policy_not_ready';
        }
        if ((string) ($handoff['execution_type'] ?? '') !== 'email' || (string) ($handoff['execution_mode'] ?? '') !== 'live') {
            $blockers[] = 'live_email_execution_queue_required';
        }
        if ((string) ($handoff['execution_approval_status'] ?? '') !== 'approved') {
            $blockers[] = 'execution_approval_required';
        }
        if ((string) ($handoff['connector_status'] ?? '') !== 'ready') {
            $blockers[] = 'ready_connector_required';
        }
        if (empty($handoff['live_enabled'])) {
            $blockers[] = 'connector_live_not_enabled';
        }
        if ((string) ($handoff['secret_status'] ?? 'not_configured') !== 'verified') {
            $blockers[] = 'verified_secret_reference_required';
        }
        if ($allowedConnectorTypes !== [] && !in_array($connectorType, $allowedConnectorTypes, true)) {
            $blockers[] = 'connector_type_not_allowed';
        }
        if ($adapterKey !== 'crm_email_queue_handoff') {
            $blockers[] = 'email_queue_handoff_adapter_required';
        } elseif ($allowedAdapterKeys !== [] && !in_array($adapterKey, $allowedAdapterKeys, true)) {
            $blockers[] = 'live_adapter_not_allowed';
        }
        if ((string) ($handoff['email_run_approval_status'] ?? '') !== 'approved') {
            $blockers[] = 'email_run_approval_required';
        }
        if ((string) ($handoff['email_run_consent_status'] ?? '') !== 'approved') {
            $blockers[] = 'email_consent_not_approved';
        }
        if (trim((string) ($handoff['email_run_subject'] ?? '')) === '') {
            $blockers[] = 'email_subject_required';
        }
        if (trim((string) ($handoff['email_run_body_snapshot'] ?? '')) === '') {
            $blockers[] = 'email_body_required';
        }
        if (trim((string) ($handoff['email_run_unsubscribe_text'] ?? '')) === '') {
            $blockers[] = 'email_unsubscribe_required';
        }
        if ((int) ($handoff['queue_attempts'] ?? 0) >= (int) ($handoff['queue_max_attempts'] ?? 3)) {
            $blockers[] = 'email_queue_max_attempts_reached';
        }

        return array_values(array_unique($blockers));
    }

