    private function summarizeLiveOrchestratorStep(array $run, array $countFields): array
    {
        $summary = [
            'id' => !empty($run['id']) ? (int) $run['id'] : null,
            'status' => (string) ($run['status'] ?? 'unknown'),
            'source' => (string) ($run['source'] ?? ''),
            'started_at' => $run['started_at'] ?? null,
            'completed_at' => $run['completed_at'] ?? null,
            'secret_safe' => true,
        ];
        foreach ($countFields as $field) {
            $summary[$field] = (int) ($run[$field] ?? 0);
        }
        if (!empty($run['error_message'])) {
            $summary['error_message'] = mb_substr(Security::sanitizeInput((string) $run['error_message'], 'string'), 0, 500);
        }

        return $summary;
    }

