             WHERE workspace_id = ? AND id = ?",
            [
                $this->normalizeEnum($status, self::LIVE_EMAIL_WORKER_RUN_STATUSES, 'live_outcome_sync_status'),
                (int) ($summary['synced'] ?? 0),
                (int) ($counts['sent'] ?? 0) + (int) ($counts['delivered'] ?? 0) + (int) ($counts['opened'] ?? 0) + (int) ($counts['clicked'] ?? 0) + (int) ($counts['replied'] ?? 0) + (int) ($counts['partially_delivered'] ?? 0),
                (int) ($counts['failed'] ?? 0) + (int) ($counts['bounced'] ?? 0),
                (int) ($counts['blocked'] ?? 0),
                (int) ($counts['queued'] ?? 0) + (int) ($counts['processing'] ?? 0),
                (int) ($counts['unknown'] ?? 0) + (int) ($counts['not_started'] ?? 0),
                $this->normalizeJsonValue($this->sanitizeJsonCompatible($summary)),
                $errorMessage !== null ? mb_substr(Security::sanitizeInput($errorMessage, 'string'), 0, 500) : null,
                $this->workspaceId(),
                $runId,
            ]
        );
    }

    private function syncLiveEmailHandoffStatuses(): void
    {
        if (!Database::tableExists('marketing_live_email_handoffs') || !Database::columnExists('marketing_live_email_handoffs', 'last_checked_at')) {
            return;
        }

        Database::execute(
            "UPDATE marketing_live_email_handoffs leh
             LEFT JOIN emails e ON e.id = leh.email_id AND e.workspace_id = leh.workspace_id
             LEFT JOIN email_queue eq ON eq.id = leh.email_queue_id AND eq.workspace_id = leh.workspace_id
             SET leh.last_email_status = e.status,
                 leh.last_queue_status = eq.status,
                 leh.last_checked_at = NOW(),
                 leh.status = CASE
                    WHEN leh.status IN ('cancelled', 'blocked', 'skipped') THEN leh.status
                    WHEN e.status = 'sent' OR eq.status = 'completed' THEN 'sent'
                    WHEN e.status = 'failed' OR eq.status = 'failed' THEN 'failed'
                    WHEN eq.status = 'processing' THEN 'processing'
                    ELSE leh.status
                 END,
                 leh.operator_status = CASE
                    WHEN leh.operator_status IN ('cancelled', 'blocked') THEN leh.operator_status
                    WHEN e.status = 'sent' OR eq.status = 'completed' THEN 'completed'
                    WHEN e.status = 'failed' OR eq.status = 'failed' THEN 'blocked'
                    ELSE leh.operator_status
                 END
             WHERE leh.workspace_id = ?",
            [$this->workspaceId()]
        );
    }

    private function updateLiveEmailHandoffControl(
        int $handoffId,
        string $status,
        string $operatorStatus,
        ?string $emailStatus,
        ?string $queueStatus,
        int $actorId,
        string $note,
        bool $suppressionRechecked = false
    ): void {
        $fields = [
            'status = ?',
            'operator_status = ?',
            'last_checked_at = NOW()',
            'operator_note = ?',
            'controlled_by = ?',
            'controlled_at = NOW()',
        ];
        $params = [
            $this->normalizeEnum($status, self::LIVE_EMAIL_HANDOFF_STATUSES, 'live_email_handoff_status'),
            $this->normalizeEnum($operatorStatus, self::LIVE_EMAIL_HANDOFF_OPERATOR_STATUSES, 'live_email_handoff_operator_status'),
            $note !== '' ? $note : null,
            $actorId > 0 ? $actorId : null,
        ];
        if ($emailStatus !== null) {
            $fields[] = 'last_email_status = ?';
            $params[] = $emailStatus;
        }
        if ($queueStatus !== null) {
            $fields[] = 'last_queue_status = ?';
            $params[] = $queueStatus;
        }
        if ($suppressionRechecked) {
            $fields[] = 'suppression_rechecked_at = NOW()';
        }
        $params[] = $this->workspaceId();
        $params[] = $handoffId;

        Database::execute(
            "UPDATE marketing_live_email_handoffs
             SET " . implode(', ', $fields) . "
             WHERE workspace_id = ?
               AND id = ?",
            $params
        );
    }

    private function recordLiveEmailHandoffEvent(
        int $handoffId,
        string $eventType,
        string $status,
        string $message,
        array $metadata = [],
        ?int $createdBy = null
    ): void {
        if (!Database::tableExists('marketing_live_email_handoff_events')) {
            return;
        }
        $handoff = Database::queryOne(
            "SELECT queue_id, email_run_id
             FROM marketing_live_email_handoffs
             WHERE workspace_id = ?
               AND id = ?
             LIMIT 1",
            [$this->workspaceId(), $handoffId]
        );
        if (!$handoff) {
            return;
        }

        Database::execute(
            "INSERT INTO marketing_live_email_handoff_events
             (workspace_id, uuid, handoff_id, queue_id, email_run_id, event_type, status, message, metadata_json, created_by)
             VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)",
            [
                $this->workspaceId(),
                $this->generateUuid(),
                $handoffId,
                (int) ($handoff['queue_id'] ?? 0) ?: null,
                (int) ($handoff['email_run_id'] ?? 0) ?: null,
                $this->normalizeEnum($eventType, ['status_synced', 'suppression_rechecked', 'retry_requested', 'cancelled', 'blocked', 'sent', 'failed', 'operator_note'], 'live_email_handoff_event_type'),
                $this->normalizeEnum($status, ['info', 'success', 'blocked', 'failed'], 'live_email_handoff_event_status'),
                mb_substr(Security::sanitizeInput($message, 'string'), 0, 500),
                $this->normalizeJsonValue($this->sanitizeJsonCompatible($metadata)),
                ($createdBy ?? $this->currentUserId()) ?: null,
            ]
        );
    }

    private function isLiveEmailHandoffSuppressed(array $handoff): bool
    {
        if (!Database::tableExists('marketing_suppression_entries')) {
            return false;
        }
        $email = strtolower(trim((string) ($handoff['recipient_email'] ?? '')));
        if ($email === '') {
            return false;
        }
        $hashes = [
            hash('sha256', 'email:' . $email),
            hash('sha256', 'all:' . $email),
        ];
        $row = Database::queryOne(
            "SELECT id
             FROM marketing_suppression_entries
             WHERE workspace_id = ?
               AND status = 'active'
               AND channel IN ('email', 'all')
               AND identifier_hash IN (?, ?)
             LIMIT 1",
            [$this->workspaceId(), $hashes[0], $hashes[1]]
        );

        return (bool) $row;
    }

    private function normalizeChannelConnectorData(array $data, bool $forCreate): array
    {
        $workspaceId = $this->workspaceId();
        $normalized = [];
        if ($forCreate || array_key_exists('name', $data)) {
            $name = Security::sanitizeInput((string) ($data['name'] ?? ''), 'string');
            if ($name === '') {
                throw new \InvalidArgumentException('Channel connector name is required.');
            }
            $normalized['name'] = $name;
        }
        if ($forCreate || array_key_exists('connector_type', $data)) {
            $normalized['connector_type'] = $this->normalizeEnum((string) ($data['connector_type'] ?? 'other'), self::CHANNEL_CONNECTOR_TYPES, 'connector_type');
        }
        if ($forCreate || array_key_exists('status', $data)) {
            $normalized['status'] = $this->normalizeEnum((string) ($data['status'] ?? 'draft'), self::CHANNEL_CONNECTOR_STATUSES, 'connector_status');
        }
        if ($forCreate || array_key_exists('execution_mode', $data)) {
            $normalized['execution_mode'] = $this->normalizeEnum((string) ($data['execution_mode'] ?? 'dry_run'), self::CHANNEL_CONNECTOR_MODES, 'connector_mode');
        }
        if ($forCreate || array_key_exists('live_enabled', $data)) {
            $normalized['live_enabled'] = !empty($data['live_enabled']) ? 1 : 0;
        }
        if ($forCreate || array_key_exists('live_adapter_key', $data)) {
            $adapterKey = preg_replace('/[^a-z0-9_]/', '', strtolower((string) ($data['live_adapter_key'] ?? ''))) ?: '';
            $normalized['live_adapter_key'] = $adapterKey !== '' ? $adapterKey : null;
        }
        if ($forCreate || array_key_exists('live_hourly_cap', $data)) {
            $normalized['live_hourly_cap'] = max(0, min(100000, (int) ($data['live_hourly_cap'] ?? 0)));
        }
        if ($forCreate || array_key_exists('live_daily_cap', $data)) {
            $normalized['live_daily_cap'] = max(0, min(1000000, (int) ($data['live_daily_cap'] ?? 0)));
        }
        if ($forCreate || array_key_exists('live_cooldown_seconds', $data)) {
            $normalized['live_cooldown_seconds'] = max(0, min(86400, (int) ($data['live_cooldown_seconds'] ?? 0)));
        }
        if ($forCreate || array_key_exists('last_live_attempt_at', $data)) {
            $normalized['last_live_attempt_at'] = $this->normalizeDateTime((string) ($data['last_live_attempt_at'] ?? ''));
        }
        if ($forCreate || array_key_exists('live_throttle', $data) || array_key_exists('live_throttle_json', $data)) {
            $normalized['live_throttle_json'] = $this->normalizeJsonValue($this->sanitizeJsonCompatible($data['live_throttle'] ?? $data['live_throttle_json'] ?? []));
        }
        if ($forCreate || array_key_exists('secret_reference', $data)) {
            $secretReference = Security::sanitizeInput((string) ($data['secret_reference'] ?? ''), 'string');
            $normalized['secret_reference'] = $secretReference !== '' ? $secretReference : null;
        }
        if ($forCreate || array_key_exists('secret_status', $data)) {
            $normalized['secret_status'] = $this->normalizeEnum((string) ($data['secret_status'] ?? 'not_configured'), self::LIVE_EXECUTION_SECRET_STATUSES, 'secret_status');
        }
        if ($forCreate || array_key_exists('setup_status', $data)) {
            $normalized['setup_status'] = $this->normalizeEnum((string) ($data['setup_status'] ?? 'not_started'), self::CHANNEL_CONNECTOR_SETUP_STATUSES, 'connector_setup_status');
        }
        if ($forCreate || array_key_exists('readiness_score', $data)) {
            $normalized['readiness_score'] = max(0, min(100, (int) ($data['readiness_score'] ?? 0)));
        }
        if ($forCreate || array_key_exists('setup_checklist', $data) || array_key_exists('setup_checklist_json', $data)) {
            $normalized['setup_checklist_json'] = $this->normalizeStringListJson($data['setup_checklist'] ?? $data['setup_checklist_json'] ?? []);
        }
        if ($forCreate || array_key_exists('setup_notes', $data)) {
            $normalized['setup_notes'] = $this->nullableSanitizedText($data['setup_notes'] ?? '');
        }
        foreach ([
            'capabilities_json' => 'capabilities',
            'config_json' => 'config',
            'diagnostics_json' => 'diagnostics',
        ] as $jsonField => $inputField) {
            if ($forCreate || array_key_exists($inputField, $data) || array_key_exists($jsonField, $data)) {
                $value = $data[$inputField] ?? $data[$jsonField] ?? [];
                if ($jsonField === 'capabilities_json') {
                    $value = $this->normalizeConnectorCapabilities($value, (string) ($normalized['connector_type'] ?? $data['connector_type'] ?? 'other'));
                }
                if ($jsonField === 'config_json' || $jsonField === 'diagnostics_json') {
                    $value = $this->sanitizeVisibleConnectorPayload($value);
                }
                $normalized[$jsonField] = $this->normalizeJsonValue($value);
            }
        }
        if ($forCreate || array_key_exists('last_tested_at', $data)) {
            $normalized['last_tested_at'] = $this->normalizeDateTime((string) ($data['last_tested_at'] ?? ''));
        }
        if ($forCreate || array_key_exists('last_live_check_at', $data)) {
            $normalized['last_live_check_at'] = $this->normalizeDateTime((string) ($data['last_live_check_at'] ?? ''));
        }
        if ($forCreate || array_key_exists('live_preflight_status', $data)) {
            $normalized['live_preflight_status'] = $this->normalizeEnum((string) ($data['live_preflight_status'] ?? 'not_checked'), self::CHANNEL_CONNECTOR_LIVE_PREFLIGHT_STATUSES, 'connector_live_preflight_status');
        }
        if ($forCreate || array_key_exists('live_preflight_checked_at', $data)) {
            $normalized['live_preflight_checked_at'] = $this->normalizeDateTime((string) ($data['live_preflight_checked_at'] ?? ''));
        }
        if ($forCreate || array_key_exists('live_preflight', $data) || array_key_exists('live_preflight_json', $data)) {
            $normalized['live_preflight_json'] = $this->normalizeJsonValue($this->sanitizeJsonCompatible($data['live_preflight'] ?? $data['live_preflight_json'] ?? []));
        }
        if ($forCreate || array_key_exists('last_readiness_review_at', $data)) {
            $normalized['last_readiness_review_at'] = $this->normalizeDateTime((string) ($data['last_readiness_review_at'] ?? ''));
        }
        if ($forCreate || array_key_exists('owner_user_id', $data)) {
            $ownerId = (int) ($data['owner_user_id'] ?? 0);
            if ($ownerId > 0) {
                $this->assertWorkspaceUser($ownerId, $workspaceId);
                $normalized['owner_user_id'] = $ownerId;
            } else {
                $normalized['owner_user_id'] = null;
            }
        }
        if ($forCreate) {
            $normalized['created_by'] = (int) ($data['created_by'] ?? $this->currentUserId()) ?: null;
        }

        return $normalized;
    }

    private function normalizeConnectorCapabilities(mixed $value, string $connectorType): array
    {
        if (is_string($value)) {
            $decoded = json_decode($value, true);
            $value = is_array($decoded) ? $decoded : preg_split('/[,\\r\\n]+/', $value);
        }
        $items = [];
        foreach ((array) $value as $key => $item) {
            if (is_array($item)) {
                foreach ($item as $nested) {
                    $capability = preg_replace('/[^a-z0-9_]/', '', strtolower((string) $nested)) ?: '';
                    if ($capability !== '') {
                        $items[] = $capability;
                    }
                }
                continue;
            }
            $capability = preg_replace('/[^a-z0-9_]/', '', strtolower((string) (is_int($key) ? $item : $key))) ?: '';
            if ($capability !== '') {
                $items[] = $capability;
            }
        }

        if ($items === []) {
            $items = $this->defaultConnectorCapabilities($connectorType);
        }

        return array_values(array_unique($items));
    }

    private function sanitizeVisibleConnectorPayload(mixed $value): array
    {
        if (is_string($value)) {
            $decoded = json_decode($value, true);
            $value = is_array($decoded) ? $decoded : [];
        }
        if (!is_array($value)) {
            return [];
        }

        $clean = [];
        foreach ($value as $key => $item) {
            $cleanKey = is_int($key)
                ? $key
                : (preg_replace('/[^a-zA-Z0-9_]/', '', (string) $key) ?: '');
            if ($cleanKey === '') {
                continue;
            }
            $isSecretKey = !is_int($cleanKey) && preg_match('/(password|secret|token|api_key|apikey|authorization|credential|private_key)/i', (string) $cleanKey) === 1;
            if ($isSecretKey) {
                if (is_array($item)) {
                    $safeSecret = $this->sanitizeVisibleConnectorPayload($item);
                    $safeSecret['secret_value_visible'] = false;
                    $safeSecret['secret_safe'] = true;
                    $clean[$cleanKey] = $safeSecret;
                    continue;
                }
                $clean[$cleanKey] = trim((string) $item) !== '' ? '[configured]' : null;
                continue;
            }
            if (is_array($item)) {
                $clean[$cleanKey] = $this->sanitizeVisibleConnectorPayload($item);
            } elseif (is_bool($item) || is_int($item) || is_float($item) || $item === null) {
                $clean[$cleanKey] = $item;
            } else {
                $clean[$cleanKey] = Security::sanitizeInput((string) $item, 'string');
            }
        }

        return $clean;
    }

    private function connectorChecklistContains(array $checklist, array $needles): bool
    {
        $haystack = strtolower(implode(' ', array_map('strval', $checklist)));
        foreach ($needles as $needle) {
            if ($needle !== '' && str_contains($haystack, strtolower($needle))) {
                return true;
            }
        }

        return false;
    }

    private function buildChannelConnectorDiagnostics(array $connector, array $input = []): array
    {
        $capabilities = array_map('strval', (array) ($connector['capabilities_json'] ?? []));
        $required = $this->requiredConnectorCapabilities((string) ($connector['connector_type'] ?? 'other'));
        $missing = array_values(array_diff($required, $capabilities));
        $config = $this->sanitizeVisibleConnectorPayload($connector['config_json'] ?? []);
        $unsafe = [];
        foreach ($config as $key => $value) {
            if (str_contains(strtolower((string) $key), 'url') && is_string($value) && $value !== '' && !filter_var($value, FILTER_VALIDATE_URL)) {
                $unsafe[] = (string) $key;
            }
        }
        $mode = (string) ($connector['execution_mode'] ?? 'dry_run');
        $status = (string) ($connector['status'] ?? 'draft');
        $policy = $this->getMarketingLiveExecutionPolicy();
        $ready = $missing === [] && $unsafe === [] && $status !== 'archived';

        return [
            'ready_for_test' => $ready,
            'missing_capabilities' => $missing,
            'unsafe_config_fields' => $unsafe,
            'connector_status' => $status,
            'execution_mode' => $mode,
            'live_execution_enabled' => !empty($policy['live_execution_enabled']) && !empty($connector['live_enabled']),
            'connector_live_enabled' => !empty($connector['live_enabled']),
            'live_adapter_key' => (string) ($connector['live_adapter_key'] ?? ''),
            'secret_status' => (string) ($connector['secret_status'] ?? 'not_configured'),
            'external_api_called' => false,
            'secret_safe' => true,
            'checked_at' => date('c'),
            'notes' => [
                'Live execution requires workspace policy, a ready connector, verified secret reference, explicit approval, and an implemented adapter.',
                'Visible diagnostics mask secret-like fields.',
            ],
            'input' => $this->sanitizeVisibleConnectorPayload($input),
        ];
    }

    private function buildChannelConnectorHealthProbe(array $connector, string $probeMode, array $input = []): array
    {
        $diagnostics = $this->buildChannelConnectorDiagnostics($connector, $input);
        $adapterKey = (string) ($connector['live_adapter_key'] ?? '');
        $webhookConfig = $adapterKey === 'crm_outbound_webhook' ? $this->outboundWebhookConfig($connector) : null;
        $latestDryRun = Database::tableExists('marketing_channel_connector_test_runs')
            ? Database::queryOne(
                "SELECT status, test_mode, created_at
                 FROM marketing_channel_connector_test_runs
                 WHERE workspace_id = ?
                   AND connector_id = ?
                   AND test_mode IN ('diagnostics', 'dry_run', 'capability_check')
                 ORDER BY created_at DESC, id DESC
                 LIMIT 1",
                [$this->workspaceId(), (int) ($connector['id'] ?? 0)]
            )
            : null;
        $policy = $this->getMarketingLiveExecutionPolicy();

        $checks = [
            [
                'key' => 'connector_not_archived',
                'label' => 'Connector is active',
                'passed' => (string) ($connector['status'] ?? 'draft') !== 'archived',
                'message' => 'Archived connectors cannot be live operational.',
                'severity' => 'blocker',
            ],
            [
                'key' => 'capabilities_ready',
                'label' => 'Required capabilities are configured',
                'passed' => empty($diagnostics['missing_capabilities']),
                'message' => 'Missing capabilities: ' . implode(', ', (array) ($diagnostics['missing_capabilities'] ?? [])),
                'severity' => 'blocker',
            ],
            [
                'key' => 'visible_config_safe',
                'label' => 'Visible config is sanitized',
                'passed' => empty($diagnostics['unsafe_config_fields']),
                'message' => 'Unsafe visible config fields: ' . implode(', ', (array) ($diagnostics['unsafe_config_fields'] ?? [])),
                'severity' => 'blocker',
            ],
            [
                'key' => 'adapter_attached',
                'label' => 'Live adapter is attached',
                'passed' => $adapterKey !== '',
                'message' => 'Attach a live adapter key before live execution.',
                'severity' => 'blocker',
            ],
            [
                'key' => 'adapter_implemented',
                'label' => 'Live adapter is implemented',
                'passed' => $adapterKey !== '' && in_array($adapterKey, self::LIVE_EXECUTION_ADAPTER_KEYS, true),
                'message' => 'Live adapter is not implemented.',
                'severity' => 'blocker',
            ],
            [
                'key' => 'setup_ready',
                'label' => 'Setup readiness is high',
                'passed' => (string) ($connector['setup_status'] ?? '') === 'ready' && (int) ($connector['readiness_score'] ?? 0) >= 90,
                'message' => 'Run connector readiness review and clear setup gaps.',
                'severity' => 'warning',
            ],
            [
                'key' => 'dry_run_passed',
                'label' => 'Dry-run diagnostics passed',
                'passed' => (string) ($latestDryRun['status'] ?? '') === 'passed',
                'message' => 'Run a passing dry-run diagnostic before live operations.',
                'severity' => 'warning',
            ],
        ];

        if ($probeMode === 'live_ready') {
            $checks[] = [
                'key' => 'policy_live_ready',
                'label' => 'Workspace live policy is ready',
                'passed' => !empty($policy['live_execution_enabled']) && (string) ($policy['status'] ?? 'disabled') === 'live_ready',
                'message' => 'Enable the workspace live execution policy before dispatch.',
                'severity' => 'blocker',
            ];
            $checks[] = [
                'key' => 'connector_live_enabled',
                'label' => 'Connector live capability is enabled',
                'passed' => !empty($connector['live_enabled']),
                'message' => 'Enable live capability for this connector after review.',
                'severity' => 'blocker',
            ];
        }

        if ($adapterKey === 'crm_outbound_webhook') {
            $webhookBlockers = (array) ($webhookConfig['blockers'] ?? []);
            $webhookWarnings = (array) ($webhookConfig['warnings'] ?? []);
            $checks[] = [
                'key' => 'webhook_endpoint_safe',
                'label' => 'Webhook endpoint is allowlisted and safe',
                'passed' => $webhookBlockers === [],
                'message' => $webhookBlockers === [] ? 'Webhook endpoint config is safe.' : 'Webhook blockers: ' . implode(', ', $webhookBlockers),
                'severity' => 'blocker',
            ];
            $checks[] = [
                'key' => 'webhook_runtime_available',
                'label' => 'HTTP runtime is available',
                'passed' => function_exists('curl_init') || (bool) ini_get('allow_url_fopen'),
                'message' => 'Enable cURL or allow_url_fopen for outbound webhook handoff.',
                'severity' => 'blocker',
            ];
            foreach ($webhookWarnings as $warning) {
                $checks[] = [
                    'key' => 'webhook_warning_' . preg_replace('/[^a-z0-9_]/', '', strtolower((string) $warning)),
                    'label' => 'Webhook warning',
                    'passed' => false,
                    'message' => (string) $warning,
                    'severity' => 'warning',
                ];
            }
        }

        $required = [];
        $passed = [];
        $warnings = [];
        $blockers = [];
        foreach ($checks as $check) {
            $required[] = (string) $check['key'];
            if (!empty($check['passed'])) {
                $passed[] = (string) $check['key'];
                continue;
            }
            if ((string) ($check['severity'] ?? 'warning') === 'blocker') {
                $blockers[] = (string) $check['key'];
            } else {
                $warnings[] = (string) $check['key'];
            }
        }
        $score = (int) round((count($passed) / max(1, count($required))) * 100);
        $status = $blockers !== [] ? 'blocked' : ($score >= 85 ? 'healthy' : 'degraded');

        return [
            'probe_mode' => $probeMode,
            'status' => $status,
            'health_score' => $score,
            'adapter_key' => $adapterKey,
            'required_checks' => $required,
            'passed_checks' => $passed,
            'warnings' => array_values(array_unique($warnings)),
            'blockers' => array_values(array_unique($blockers)),
            'check_details' => $checks,
            'diagnostics' => array_merge($diagnostics, [
                'latest_dry_run_status' => (string) ($latestDryRun['status'] ?? 'missing'),
                'latest_dry_run_at' => $latestDryRun['created_at'] ?? null,
                'policy_live_execution_enabled' => !empty($policy['live_execution_enabled']),
                'policy_status' => (string) ($policy['status'] ?? 'disabled'),
                'webhook' => $webhookConfig !== null ? [
                    'endpoint_host' => (string) ($webhookConfig['endpoint_host'] ?? ''),
                    'endpoint_url_hash' => $webhookConfig['endpoint_url_hash'] ?? null,
                    'blockers' => (array) ($webhookConfig['blockers'] ?? []),
                    'warnings' => (array) ($webhookConfig['warnings'] ?? []),
                    'secret' => (array) ($webhookConfig['secret'] ?? []),
                ] : null,
                'external_api_called' => false,
                'third_party_delivery' => false,
                'secret_safe' => true,
            ]),
            'external_api_called' => false,
            'third_party_delivery' => false,
            'secret_safe' => true,
            'checked_at' => date('c'),
        ];
    }

    private function buildChannelConnectorLivePreflight(array $connector, array $input = []): array
    {
        $diagnostics = $this->buildChannelConnectorDiagnostics($connector, $input);
        $policy = $this->getMarketingLiveExecutionPolicy();
        $adapterKey = (string) ($connector['live_adapter_key'] ?? '');
        $connectorType = (string) ($connector['connector_type'] ?? 'other');
        $allowedTypes = (array) ($policy['allowed_connector_types_json'] ?? []);
        $allowedAdapters = (array) ($policy['allowed_adapter_keys_json'] ?? []);
        $latestDryRun = Database::tableExists('marketing_channel_connector_test_runs')
            ? Database::queryOne(
                "SELECT status, test_mode, created_at
                 FROM marketing_channel_connector_test_runs
                 WHERE workspace_id = ?
                   AND connector_id = ?
                   AND test_mode IN ('diagnostics', 'dry_run', 'capability_check')
                 ORDER BY created_at DESC, id DESC
                 LIMIT 1",
                [$this->workspaceId(), (int) ($connector['id'] ?? 0)]
            )
            : null;
        $latestHealthProbe = Database::tableExists('marketing_channel_connector_health_probes')
            ? Database::queryOne(
                "SELECT status, health_score, probe_mode, created_at, blockers_json, warnings_json, diagnostics_json
                 FROM marketing_channel_connector_health_probes
                 WHERE workspace_id = ? AND connector_id = ?
                 ORDER BY created_at DESC, id DESC
                 LIMIT 1",
                [$this->workspaceId(), (int) ($connector['id'] ?? 0)]
            )
            : null;
        $webhookConfig = null;

        $blockers = [];
        $warnings = [];
        if (empty($policy['live_execution_enabled']) || (string) ($policy['status'] ?? 'disabled') !== 'live_ready') {
            $blockers[] = 'live_policy_not_ready';
        }
        if ((string) ($connector['status'] ?? 'draft') !== 'ready') {
            $blockers[] = 'ready_connector_required';
        }
        if ((string) ($connector['setup_status'] ?? 'not_started') !== 'ready' || (int) ($connector['readiness_score'] ?? 0) < 90) {
            $blockers[] = 'connector_setup_readiness_required';
        }
        if (empty($connector['live_enabled'])) {
            $blockers[] = 'connector_live_not_enabled';
        }
        if ((string) ($connector['secret_status'] ?? 'not_configured') !== 'verified') {
            $blockers[] = 'verified_secret_reference_required';
        }
        if ($adapterKey === '') {
            $blockers[] = 'live_adapter_not_attached';
        } elseif (!in_array($adapterKey, self::LIVE_EXECUTION_ADAPTER_KEYS, true)) {
            $blockers[] = 'live_adapter_not_implemented';
        }
        if ($adapterKey === 'crm_outbound_webhook') {
            $webhookConfig = $this->outboundWebhookConfig($connector);
            array_push($blockers, ...(array) ($webhookConfig['blockers'] ?? []));
            array_push($warnings, ...(array) ($webhookConfig['warnings'] ?? []));
        }
        if ($allowedTypes !== [] && !in_array($connectorType, $allowedTypes, true)) {
            $blockers[] = 'connector_type_not_allowed';
        }
        if ($allowedAdapters !== [] && $adapterKey !== '' && !in_array($adapterKey, $allowedAdapters, true)) {
            $blockers[] = 'live_adapter_not_allowed';
        }
        if ((string) ($latestDryRun['status'] ?? '') !== 'passed') {
            $blockers[] = 'dry_run_test_required';
        }
        $connectorThrottle = $this->connectorLiveThrottleSnapshot($connector);
        array_push($blockers, ...(array) ($connectorThrottle['blocked_reasons'] ?? []));
        array_push($warnings, ...(array) ($connectorThrottle['warnings'] ?? []));
        if ($latestHealthProbe) {
            $latestHealthProbe = $this->hydrateJsonFields($latestHealthProbe, ['blockers_json', 'warnings_json', 'diagnostics_json']);
            if ((string) ($latestHealthProbe['status'] ?? '') === 'blocked') {
                $blockers[] = 'connector_health_blocked';
            } elseif ((int) ($latestHealthProbe['health_score'] ?? 0) < 70) {
                $blockers[] = 'connector_health_score_low';
            } elseif ((string) ($latestHealthProbe['status'] ?? '') === 'degraded') {
                $warnings[] = 'connector_health_degraded';
            }
        } else {
            $warnings[] = 'connector_health_probe_recommended';
        }
        if (!empty($diagnostics['missing_capabilities'])) {
            $blockers[] = 'required_capabilities_missing';
        }
        if (!empty($diagnostics['unsafe_config_fields'])) {
            $blockers[] = 'unsafe_visible_config';
        }
        if ((string) ($connector['execution_mode'] ?? '') === 'live_disabled') {
            $warnings[] = 'connector_mode_live_disabled';
        }

        $blockers = array_values(array_unique($blockers));
        $warnings = array_values(array_unique($warnings));
        $ready = $blockers === [];

        return array_merge($diagnostics, [
            'ready_for_test' => $ready,
            'ready_for_live_preflight' => $ready,
            'live_preflight_status' => $ready ? 'passed' : 'blocked',
            'live_preflight_blockers' => $blockers,
            'live_preflight_warnings' => $warnings,
            'can_run_live_queue' => $ready,
            'latest_dry_run_status' => (string) ($latestDryRun['status'] ?? 'missing'),
            'latest_dry_run_at' => $latestDryRun['created_at'] ?? null,
            'connector_live_throttle' => $connectorThrottle,
            'latest_health_probe_status' => $latestHealthProbe ? (string) ($latestHealthProbe['status'] ?? 'unknown') : 'missing',
            'latest_health_probe_score' => $latestHealthProbe ? (int) ($latestHealthProbe['health_score'] ?? 0) : null,
            'latest_health_probe_at' => $latestHealthProbe['created_at'] ?? null,
            'latest_health_probe_blockers' => (array) ($latestHealthProbe['blockers_json'] ?? []),
            'latest_health_probe_warnings' => (array) ($latestHealthProbe['warnings_json'] ?? []),
            'live_policy_status' => (string) ($policy['status'] ?? 'disabled'),
            'policy_live_execution_enabled' => !empty($policy['live_execution_enabled']),
            'policy_allowed_connector_types' => $allowedTypes,
            'policy_allowed_adapter_keys' => $allowedAdapters,
            'secret' => (array) ($webhookConfig['secret'] ?? ['configured' => false, 'secret_safe' => true]),
            'external_api_called' => false,
            'external_execution' => false,
            'third_party_delivery' => false,
            'live_preflight_only' => true,
            'secret_safe' => true,
            'checked_at' => date('c'),
            'notes' => [
                'Live preflight checks policy, connector readiness, verified secret references, adapter availability, and dry-run evidence.',
                'No external API call, send, publish, or delivery occurs during preflight.',
                'Queue items still require explicit approval before any live adapter can run.',
            ],
        ]);
    }

    private function outboundWebhookConfig(array $connector): array
    {
        $config = $this->sanitizeVisibleConnectorPayload($connector['config_json'] ?? []);
        $endpointUrl = trim((string) ($config['endpoint_url'] ?? $config['webhook_url'] ?? ''));
        $method = strtoupper(preg_replace('/[^A-Z]/', '', (string) ($config['http_method'] ?? $config['method'] ?? 'POST')) ?: 'POST');
        if (!in_array($method, ['GET', 'POST', 'PUT', 'PATCH'], true)) {
            $method = 'POST';
        }
        $timeoutSeconds = max(1, min(15, (int) ($config['timeout_seconds'] ?? $config['timeout'] ?? 5)));
        $maxRetries = max(0, min(3, (int) ($config['max_retries'] ?? $config['retries'] ?? 0)));
        $allowedHosts = $this->normalizeWebhookAllowedHosts($config['allowed_hosts'] ?? $config['allowed_host'] ?? []);
        $headers = $this->safeWebhookHeaders((array) ($config['headers'] ?? []));
        $resolvedSecret = $this->resolveChannelConnectorLiveSecret($connector);
        if (!empty($resolvedSecret['configured'])) {
            $headers = array_merge($headers, (array) ($resolvedSecret['headers'] ?? []));
        }
        $blockers = [];
        $warnings = [];
        $parts = $endpointUrl !== '' ? parse_url($endpointUrl) : false;
        $scheme = is_array($parts) ? strtolower((string) ($parts['scheme'] ?? '')) : '';
        $host = is_array($parts) ? strtolower((string) ($parts['host'] ?? '')) : '';
        $requiresSecret = !empty($config['requires_secret'])
            || !empty($config['requires_auth'])
            || in_array(strtolower((string) ($config['auth_required'] ?? '')), ['1', 'true', 'yes', 'required'], true);

        if ($endpointUrl === '' || !is_array($parts) || $scheme === '' || $host === '') {
            $blockers[] = 'webhook_endpoint_required';
        }
        if ($allowedHosts === []) {
            $blockers[] = 'webhook_allowed_host_required';
        } elseif ($host !== '' && !$this->webhookHostAllowed($host, $allowedHosts)) {
            $blockers[] = 'webhook_host_not_allowed';
        }
        if ($scheme !== '' && $scheme !== 'https' && !$this->isLocalWebhookHost($host)) {
            $blockers[] = 'webhook_https_required';
        }
        if ($this->isLocalWebhookHost($host)) {
            $warnings[] = 'webhook_localhost_endpoint';
        }
        if ($requiresSecret && empty($resolvedSecret['configured'])) {
            $blockers[] = 'connector_secret_value_required';
        } elseif (!empty($connector['secret_reference']) && (string) ($connector['secret_status'] ?? '') === 'verified' && empty($resolvedSecret['configured'])) {
            $warnings[] = 'connector_secret_value_not_stored';
        }
        array_push($blockers, ...(array) ($resolvedSecret['proof']['freshness_blockers'] ?? []));
        array_push($warnings, ...(array) ($resolvedSecret['proof']['freshness_warnings'] ?? []));

        return [
            'endpoint_url' => $endpointUrl,
            'endpoint_host' => $host,
            'endpoint_url_hash' => $endpointUrl !== '' ? hash('sha256', $endpointUrl) : null,
            'http_method' => $method,
            'timeout_seconds' => $timeoutSeconds,
            'max_retries' => $maxRetries,
            'allowed_hosts' => $allowedHosts,
            'headers' => $headers,
            'secret' => (array) ($resolvedSecret['proof'] ?? ['configured' => false, 'secret_safe' => true]),
            'blockers' => array_values(array_unique($blockers)),
            'warnings' => array_values(array_unique($warnings)),
        ];
    }

    private function resolveChannelConnectorLiveSecret(array $connector): array
    {
        $reference = trim((string) ($connector['secret_reference'] ?? ''));
        if ($reference === '' || !Database::tableExists('marketing_live_connector_secrets')) {
            return [
                'configured' => false,
                'headers' => [],
                'proof' => [
                    'configured' => false,
                    'secret_safe' => true,
                    'reason' => $reference === '' ? 'missing_secret_reference' : 'secret_store_unavailable',
                ],
            ];
        }

        $row = Database::queryOne(
            "SELECT *
             FROM marketing_live_connector_secrets
             WHERE workspace_id = ?
               AND secret_reference = ?
               AND connector_id = ?
               AND status = 'active'
             ORDER BY updated_at DESC, id DESC
             LIMIT 1",
            [$this->workspaceId(), $reference, (int) ($connector['id'] ?? 0)]
        );
        if (!$row) {
            return [
                'configured' => false,
                'headers' => [],
                'proof' => [
                    'configured' => false,
                    'secret_reference' => $reference,
                    'secret_safe' => true,
                    'reason' => 'active_secret_not_found',
                ],
            ];
        }
        $freshness = $this->evaluateChannelConnectorSecretFreshness($row);

        try {
            $secretValue = Security::decryptSensitiveData((string) ($row['encrypted_value'] ?? ''), $this->marketingLiveConnectorEncryptionKey());
        } catch (Throwable $e) {
            return [
                'configured' => false,
                'headers' => [],
                'proof' => [
                    'configured' => false,
                    'secret_reference' => $reference,
                    'secret_type' => (string) ($row['secret_type'] ?? ''),
                    'freshness_status' => (string) ($freshness['freshness_status'] ?? 'unknown'),
                    'freshness_blockers' => (array) ($freshness['blockers'] ?? []),
                    'freshness_warnings' => (array) ($freshness['warnings'] ?? []),
                    'freshness' => $freshness,
                    'secret_safe' => true,
                    'reason' => 'secret_decryption_failed',
                ],
            ];
        }
        if (trim($secretValue) === '') {
            return [
                'configured' => false,
                'headers' => [],
                'proof' => [
                    'configured' => false,
                    'secret_reference' => $reference,
                    'secret_type' => (string) ($row['secret_type'] ?? ''),
                    'freshness_status' => (string) ($freshness['freshness_status'] ?? 'unknown'),
                    'freshness_blockers' => (array) ($freshness['blockers'] ?? []),
                    'freshness_warnings' => (array) ($freshness['warnings'] ?? []),
                    'freshness' => $freshness,
                    'secret_safe' => true,
                    'reason' => 'secret_empty',
                ],
            ];
        }

        $secretType = $this->normalizeEnum((string) ($row['secret_type'] ?? 'bearer_token'), self::LIVE_CONNECTOR_SECRET_TYPES, 'live_connector_secret_type');
        $headerName = preg_replace('/[^A-Za-z0-9-]/', '', (string) ($row['header_name'] ?? '')) ?: ($secretType === 'bearer_token' ? 'Authorization' : 'X-API-Key');
        $prefix = trim((string) ($row['header_prefix'] ?? ''));
        $headerValue = $prefix !== '' ? $prefix . ' ' . $secretValue : $secretValue;

        return [
            'configured' => true,
            'headers' => [$headerName => $headerValue],
            'proof' => [
                'configured' => true,
                'secret_reference' => $reference,
                'secret_type' => $secretType,
                'header_name' => $headerName,
                'header_prefix' => $prefix,
                'last_verified_at' => $row['last_verified_at'] ?? null,
                'last_verification_status' => $row['last_verification_status'] ?? null,
                'expires_at' => $row['expires_at'] ?? null,
                'rotation_due_at' => $row['rotation_due_at'] ?? null,
                'rotation_interval_days' => $row['rotation_interval_days'] ?? null,
                'freshness_status' => (string) ($freshness['freshness_status'] ?? 'fresh'),
                'freshness_blockers' => (array) ($freshness['blockers'] ?? []),
                'freshness_warnings' => (array) ($freshness['warnings'] ?? []),
                'freshness' => $freshness,
                'rotated_at' => $row['rotated_at'] ?? null,
                'secret_value_visible' => false,
                'secret_safe' => true,
            ],
        ];
    }

    private function activeChannelConnectorSecretRow(int $connectorId, string $reference = ''): ?array
    {
        if (!Database::tableExists('marketing_live_connector_secrets')) {
            return null;
        }
        $where = ['workspace_id = ?', 'connector_id = ?', "status = 'active'"];
        $params = [$this->workspaceId(), $connectorId];
        if (trim($reference) !== '') {
            $where[] = 'secret_reference = ?';
            $params[] = trim($reference);
        }

        return Database::queryOne(
            'SELECT *
             FROM marketing_live_connector_secrets
             WHERE ' . implode(' AND ', $where) . '
             ORDER BY updated_at DESC, id DESC
             LIMIT 1',
            $params
        ) ?: null;
    }

    private function evaluateChannelConnectorSecretFreshness(array $row): array
    {
        $status = (string) ($row['status'] ?? 'active');
        $expiresAt = $row['expires_at'] ?? null;
        $rotationDueAt = $row['rotation_due_at'] ?? null;
        $rotationIntervalDays = isset($row['rotation_interval_days']) ? (int) $row['rotation_interval_days'] : null;
        $blockers = [];
        $warnings = [];
        $freshnessStatus = (string) ($row['freshness_status'] ?? 'fresh');
        $now = time();

        if ($status === 'revoked') {
            $blockers[] = 'connector_secret_revoked';
            $freshnessStatus = 'revoked';
        }
        if (!empty($expiresAt)) {
            $expiresAtTs = strtotime((string) $expiresAt);
            if ($expiresAtTs !== false) {
                if ($expiresAtTs <= $now) {
                    $blockers[] = 'connector_secret_expired';
                    $freshnessStatus = 'expired';
                } elseif ($expiresAtTs <= strtotime('+7 days', $now)) {
                    $warnings[] = 'connector_secret_expires_soon';
                    $freshnessStatus = $freshnessStatus === 'fresh' ? 'fresh' : $freshnessStatus;
                }
            }
        }
        if (!empty($rotationDueAt)) {
            $rotationDueTs = strtotime((string) $rotationDueAt);
            if ($rotationDueTs !== false) {
                if ($rotationDueTs <= $now) {
                    $blockers[] = 'connector_secret_rotation_due';
                    if ($freshnessStatus !== 'expired' && $freshnessStatus !== 'revoked') {
                        $freshnessStatus = 'rotation_due';
                    }
                } elseif ($rotationDueTs <= strtotime('+7 days', $now)) {
                    $warnings[] = 'connector_secret_rotation_due_soon';
                }
            }
        }
        if ($freshnessStatus === '' || !in_array($freshnessStatus, ['fresh', 'rotation_due', 'expired', 'revoked', 'unknown'], true)) {
            $freshnessStatus = $blockers === [] ? 'fresh' : 'unknown';
        }
        if ($blockers === [] && in_array($freshnessStatus, ['rotation_due', 'expired', 'revoked'], true)) {
            $freshnessStatus = 'fresh';
        }

        return [
            'freshness_status' => $freshnessStatus,
            'blockers' => array_values(array_unique($blockers)),
            'warnings' => array_values(array_unique($warnings)),
            'expires_at' => $expiresAt,
            'rotation_due_at' => $rotationDueAt,
            'rotation_interval_days' => $rotationIntervalDays,
            'checked_at' => date('c'),
            'secret_safe' => true,
        ];
    }

    private function normalizeMarketingActorId(int $actorId): int
    {
        $actorId = $actorId > 0 ? $actorId : ($this->currentUserId() ?: 0);
        if ($actorId > 0) {
            $this->assertWorkspaceUser($actorId, $this->workspaceId());
        }

        return $actorId;
    }

    private function recordChannelConnectorSecretEvent(array $data): void
    {
        if (!Database::tableExists('marketing_live_connector_secret_events')) {
            return;
        }
        $eventType = $this->normalizeEnum((string) ($data['event_type'] ?? 'saved'), self::LIVE_CONNECTOR_SECRET_EVENT_TYPES, 'live_connector_secret_event_type');
        $status = $this->normalizeEnum((string) ($data['status'] ?? 'info'), self::LIVE_CONNECTOR_SECRET_EVENT_STATUSES, 'live_connector_secret_event_status');
        $connectorId = (int) ($data['connector_id'] ?? 0);
        $secretId = (int) ($data['secret_id'] ?? 0);
        $createdBy = (int) ($data['created_by'] ?? 0);
        $message = mb_substr(Security::sanitizeInput((string) ($data['message'] ?? ''), 'string'), 0, 500);
        $metadata = $this->sanitizeVisibleConnectorPayload((array) ($data['metadata'] ?? []));
        $metadata['secret_value_visible'] = false;
        $metadata['raw_secret_values_visible'] = false;

        Database::execute(
            "INSERT INTO marketing_live_connector_secret_events
             (workspace_id, connector_id, secret_id, uuid, event_type, status, message, metadata_json, created_by)
             VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)",
            [
                $this->workspaceId(),
                $connectorId,
                $secretId > 0 ? $secretId : null,
                $this->generateUuid(),
                $eventType,
                $status,
                $message !== '' ? $message : null,
                $this->normalizeJsonValue($metadata),
                $createdBy > 0 ? $createdBy : null,
            ]
        );
    }

    private function marketingLiveConnectorEncryptionKey(): string
    {
        $seed = (string) ($_ENV['APP_KEY'] ?? $_ENV['APP_SECRET'] ?? $_ENV['DB_PASS'] ?? 'crm-local-secret');
        return hash('sha256', $seed, true);
    }

    private function normalizeWebhookAllowedHosts(mixed $value): array
    {
        if (is_string($value)) {
            $decoded = json_decode($value, true);
            $value = is_array($decoded) ? $decoded : preg_split('/[,\\r\\n]+/', $value);
        }
        $hosts = [];
        foreach ((array) $value as $item) {
            $host = strtolower(trim((string) $item));
            $host = preg_replace('/[^a-z0-9.\\-*]/', '', $host) ?: '';
            if ($host !== '') {
                $hosts[] = $host;
            }
        }

        return array_values(array_unique($hosts));
    }

    private function webhookHostAllowed(string $host, array $allowedHosts): bool
    {
        foreach ($allowedHosts as $allowedHost) {
            $allowedHost = strtolower((string) $allowedHost);
            if ($host === $allowedHost) {
                return true;
            }
            if (str_starts_with($allowedHost, '*.') && str_ends_with($host, substr($allowedHost, 1))) {
                return true;
            }
        }

        return false;
    }

    private function isLocalWebhookHost(string $host): bool
    {
        return in_array(strtolower($host), ['localhost', '127.0.0.1', '::1'], true);
    }

    private function safeWebhookHeaders(array $headers): array
    {
        $safe = [];
        foreach ($headers as $key => $value) {
            $name = is_int($key) ? '' : preg_replace('/[^A-Za-z0-9-]/', '', (string) $key);
            if ($name === '' || preg_match('/(authorization|cookie|secret|token|api[-_]?key|credential|password)/i', $name)) {
                continue;
            }
            $safe[$name] = mb_substr(Security::sanitizeInput((string) $value, 'string'), 0, 500);
        }
        $safe['Content-Type'] = $safe['Content-Type'] ?? 'application/json';
        $safe['Accept'] = $safe['Accept'] ?? 'application/json';

        return $safe;
    }

    private function defaultConnectorCapabilities(string $connectorType): array
    {
        return match ($connectorType) {
            'email' => ['csv_export', 'dry_run', 'unsubscribe_check'],
            'whatsapp' => ['copy_export', 'media_attachment_check', 'dry_run'],
            'sms' => ['copy_export', 'character_count', 'dry_run'],
            'linkedin', 'facebook_instagram', 'x' => ['copy_export', 'media_kit_export', 'dry_run'],
            'youtube' => ['thumbnail_check', 'description_export', 'dry_run'],
            'ads' => ['campaign_bundle_export', 'utm_check', 'dry_run'],
            'website_webhook' => ['webhook_payload_preview', 'token_preview', 'dry_run'],
            default => ['manual_export', 'dry_run'],
        };
    }

    private function requiredConnectorCapabilities(string $connectorType): array
    {
        return match ($connectorType) {
            'email' => ['csv_export', 'unsubscribe_check', 'dry_run'],
            'whatsapp' => ['copy_export', 'dry_run'],
            'sms' => ['copy_export', 'dry_run'],
            'linkedin', 'facebook_instagram', 'x' => ['copy_export', 'media_kit_export', 'dry_run'],
            'youtube' => ['thumbnail_check', 'dry_run'],
            'ads' => ['campaign_bundle_export', 'utm_check', 'dry_run'],
            'website_webhook' => ['webhook_payload_preview', 'dry_run'],
            default => ['manual_export', 'dry_run'],
        };
    }

    private function normalizeChannelMediaKitData(array $data, bool $forCreate): array
    {
        $workspaceId = $this->workspaceId();
        $normalized = [];

        if ($forCreate || array_key_exists('title', $data)) {
            $title = Security::sanitizeInput((string) ($data['title'] ?? ''), 'string');
            if ($title === '') {
                throw new \InvalidArgumentException('Channel media kit title is required.');
            }
            $normalized['title'] = $title;
        }
        if ($forCreate || array_key_exists('channel', $data)) {
            $normalized['channel'] = $this->normalizeEnum((string) ($data['channel'] ?? 'other'), self::CHANNELS, 'channel');
        }

        foreach ([
            'content_item_id' => 'marketing_content_items',
            'landing_page_id' => 'marketing_landing_pages',
            'distribution_post_id' => 'marketing_distribution_posts',
            'utm_link_id' => 'marketing_utm_links',
            'primary_media_file_id' => 'marketing_media_files',
        ] as $field => $table) {
            if ($forCreate || array_key_exists($field, $data)) {
                $id = (int) ($data[$field] ?? 0);
                if ($id > 0) {
                    $this->assertWorkspaceRecord($table, $id, $workspaceId);
                    $normalized[$field] = $id;
                } else {
                    $normalized[$field] = null;
                }
            }
        }

        if (($normalized['distribution_post_id'] ?? null) && empty($normalized['content_item_id'])) {
            $post = $this->getDistributionPost((int) $normalized['distribution_post_id']);
            $normalized['content_item_id'] = (int) ($post['content_item_id'] ?? 0) ?: null;
        }

        if ($forCreate || array_key_exists('destination_url', $data)) {
            $url = trim((string) ($data['destination_url'] ?? ''));
            if ($url === '' && !empty($normalized['utm_link_id'])) {
                $utm = Database::queryOne(
                    'SELECT generated_url FROM marketing_utm_links WHERE workspace_id = ? AND id = ?',
                    [$workspaceId, (int) $normalized['utm_link_id']]
                );
                $url = (string) ($utm['generated_url'] ?? '');
            }
            if ($url !== '' && (!filter_var($url, FILTER_VALIDATE_URL) || !preg_match('/^https?:\\/\\//i', $url))) {
                throw new \InvalidArgumentException('A valid destination URL is required.');
            }
            $normalized['destination_url'] = $url !== '' ? $url : null;
        }

        $channel = (string) ($normalized['channel'] ?? ($data['channel'] ?? 'other'));
        $requirements = $this->channelMediaKitRequirements($channel);
        foreach ([
            'required_dimensions_json' => ['required_dimensions', $requirements['required_dimensions']],
            'aspect_ratios_json' => ['aspect_ratios', $requirements['aspect_ratios']],
            'copy_fields_json' => ['copy_fields', $requirements['copy_fields']],
            'media_slots_json' => ['media_slots', $requirements['media_slots']],
            'destination_rules_json' => ['destination_rules', $requirements['destination_rules']],
            'export_checklist_json' => ['export_checklist', $requirements['export_checklist']],
        ] as $jsonField => [$formField, $default]) {
            if ($forCreate || array_key_exists($formField, $data) || array_key_exists($jsonField, $data)) {
                $value = $data[$formField] ?? $data[$jsonField] ?? $default;
                $normalized[$jsonField] = $this->normalizeJsonValue($this->sanitizeJsonCompatible($value));
            }
        }

        $draft = array_merge($data, $normalized);
        $readiness = $this->channelMediaKitReadiness($draft);
        if ($forCreate || array_key_exists('readiness_json', $data)) {
            $normalized['readiness_json'] = $this->normalizeJsonValue($readiness);
        }
        if ($forCreate || array_key_exists('status', $data)) {
            $requested = (string) ($data['status'] ?? ($readiness['ready'] ? 'ready' : 'draft'));
            $normalized['status'] = $this->normalizeEnum($requested, self::CHANNEL_MEDIA_KIT_STATUSES, 'channel_media_kit_status');
            if ($normalized['status'] === 'ready' && empty($readiness['ready'])) {
                $normalized['status'] = 'draft';
            }
        }
        if ($forCreate || array_key_exists('export_payload', $data) || array_key_exists('export_payload_json', $data)) {
            $payload = $data['export_payload'] ?? $data['export_payload_json'] ?? $this->buildChannelMediaKitPayload($draft + [
                'readiness_json' => $readiness,
                'required_dimensions_json' => $this->decodeJsonLike($normalized['required_dimensions_json'] ?? $requirements['required_dimensions']),
                'aspect_ratios_json' => $this->decodeJsonLike($normalized['aspect_ratios_json'] ?? $requirements['aspect_ratios']),
                'copy_fields_json' => $this->decodeJsonLike($normalized['copy_fields_json'] ?? $requirements['copy_fields']),
                'media_slots_json' => $this->decodeJsonLike($normalized['media_slots_json'] ?? $requirements['media_slots']),
                'destination_rules_json' => $this->decodeJsonLike($normalized['destination_rules_json'] ?? $requirements['destination_rules']),
                'export_checklist_json' => $this->decodeJsonLike($normalized['export_checklist_json'] ?? $requirements['export_checklist']),
            ]);
            $normalized['export_payload_json'] = $this->normalizeJsonValue($payload);
        }
        if ($forCreate || array_key_exists('metadata_json', $data)) {
            $normalized['metadata_json'] = $this->normalizeJsonValue($this->sanitizeJsonCompatible($data['metadata'] ?? $data['metadata_json'] ?? []));
        }
        if ($forCreate || array_key_exists('exported_at', $data)) {
            $normalized['exported_at'] = $this->normalizeDateTime((string) ($data['exported_at'] ?? ''));
        }
        if ($forCreate) {
            $normalized['created_by'] = (int) ($data['created_by'] ?? $this->currentUserId()) ?: null;
        }

        return $normalized;
    }

    private function normalizeCampaignBudgetData(array $data, bool $forCreate): array
    {
        $workspaceId = $this->workspaceId();
        $normalized = [];
        if ($forCreate || array_key_exists('title', $data)) {
            $title = Security::sanitizeInput((string) ($data['title'] ?? ''), 'string');
            if ($title === '') {
                throw new \InvalidArgumentException('Campaign budget title is required.');
            }
            $normalized['title'] = $title;
        }
        foreach ([
            'campaign_id' => 'campaigns',
            'campaign_brief_id' => 'marketing_campaign_briefs',
        ] as $field => $table) {
            if ($forCreate || array_key_exists($field, $data)) {
                $id = (int) ($data[$field] ?? 0);
                if ($id > 0) {
                    $this->assertWorkspaceRecord($table, $id, $workspaceId);
                    $normalized[$field] = $id;
                } else {
                    $normalized[$field] = null;
                }
            }
        }
        if ($forCreate || array_key_exists('budget_period', $data)) {
            $normalized['budget_period'] = $this->normalizeEnum((string) ($data['budget_period'] ?? 'campaign'), self::BUDGET_PERIODS, 'budget_period');
        }
        foreach (['planned_budget', 'committed_budget', 'actual_spend'] as $field) {
            if ($forCreate || array_key_exists($field, $data)) {
                $normalized[$field] = max(0, round((float) ($data[$field] ?? 0), 2));
            }
        }
        if ($forCreate || array_key_exists('currency', $data)) {
            $currency = strtoupper(preg_replace('/[^A-Z]/i', '', (string) ($data['currency'] ?? 'USD')) ?: 'USD');
            $normalized['currency'] = substr($currency, 0, 3);
        }
        foreach (['start_date', 'end_date'] as $field) {
            if ($forCreate || array_key_exists($field, $data)) {
                $value = trim((string) ($data[$field] ?? ''));
                $normalized[$field] = $value !== '' ? $this->normalizeDate($value, str_replace('_', ' ', $field)) : null;
            }
        }
        if ($forCreate || array_key_exists('status', $data)) {
            $normalized['status'] = $this->normalizeEnum((string) ($data['status'] ?? 'draft'), self::BUDGET_STATUSES, 'budget_status');
        }
        if ($forCreate || array_key_exists('metadata_json', $data)) {
            $normalized['metadata_json'] = $this->normalizeJsonValue($this->sanitizeJsonCompatible($data['metadata'] ?? $data['metadata_json'] ?? []));
        }
        if ($forCreate || array_key_exists('owner_user_id', $data)) {
            $ownerId = (int) ($data['owner_user_id'] ?? 0);
            if ($ownerId > 0) {
                $this->assertWorkspaceUser($ownerId, $workspaceId);
                $normalized['owner_user_id'] = $ownerId;
            } else {
                $normalized['owner_user_id'] = null;
            }
        }
        if ($forCreate) {
            $normalized['created_by'] = (int) ($data['created_by'] ?? $this->currentUserId()) ?: null;
        }

        return $normalized;
    }

    private function normalizeChannelSpendData(array $data): array
    {
        $workspaceId = $this->workspaceId();
        $budgetId = (int) ($data['budget_id'] ?? 0);
        if ($budgetId > 0) {
            $this->assertWorkspaceRecord('marketing_campaign_budgets', $budgetId, $workspaceId);
        }
        $campaignId = (int) ($data['campaign_id'] ?? 0);
        if ($campaignId > 0) {
            $this->assertWorkspaceRecord('campaigns', $campaignId, $workspaceId);
        } elseif ($budgetId > 0) {
            $budget = $this->getCampaignBudget($budgetId);
            $campaignId = (int) ($budget['campaign_id'] ?? 0);
        }
        $channel = strtolower(trim((string) ($data['channel'] ?? 'other')));
        $channel = preg_replace('/[^a-z0-9_\\-]/', '', $channel) ?: 'other';
        $date = trim((string) ($data['spend_date'] ?? date('Y-m-d')));
        $currency = strtoupper(preg_replace('/[^A-Z]/i', '', (string) ($data['currency'] ?? 'USD')) ?: 'USD');

        return [
            'budget_id' => $budgetId > 0 ? $budgetId : null,
            'campaign_id' => $campaignId > 0 ? $campaignId : null,
            'channel' => substr($channel, 0, 80),
            'spend_date' => $this->normalizeDate($date, 'spend date'),
            'amount' => max(0, round((float) ($data['amount'] ?? 0), 2)),
            'currency' => substr($currency, 0, 3),
            'vendor' => $this->nullableSanitizedText($data['vendor'] ?? ''),
            'description' => $this->nullableSanitizedText($data['description'] ?? ''),
            'metadata_json' => $this->normalizeJsonValue($this->sanitizeJsonCompatible($data['metadata'] ?? $data['metadata_json'] ?? [])),
            'created_by' => (int) ($data['created_by'] ?? $this->currentUserId()) ?: null,
        ];
    }

