            'end_date' => $end !== '' ? $this->normalizeDate($end, 'experiment end date') : null,
            'metadata_json' => $this->normalizeJsonValue($this->sanitizeJsonCompatible($data['metadata'] ?? $data['metadata_json'] ?? [])),
            'owner_user_id' => $ownerId > 0 ? $ownerId : null,
            'created_by' => (int) ($data['created_by'] ?? $this->currentUserId()) ?: null,
