    private function normalizeExperimentVariantData(array $data): array
    {
        $workspaceId = $this->workspaceId();
        $experimentId = (int) ($data['experiment_id'] ?? 0);
        if ($experimentId <= 0) {
            throw new \InvalidArgumentException('Experiment is required for variants.');
        }
        $this->assertWorkspaceRecord('marketing_experiments', $experimentId, $workspaceId);
        $name = Security::sanitizeInput((string) ($data['name'] ?? ''), 'string');
        if ($name === '') {
            throw new \InvalidArgumentException('Experiment variant name is required.');
        }
        $key = strtolower(trim((string) ($data['variant_key'] ?? substr($name, 0, 20))));
        $key = preg_replace('/[^a-z0-9_\\-]/', '', $key) ?: 'variant';

        return [
            'experiment_id' => $experimentId,
            'variant_key' => substr($key, 0, 80),
            'name' => $name,
            'description' => $this->nullableSanitizedText($data['description'] ?? ''),
            'payload_json' => $this->normalizeJsonValue($this->sanitizeJsonCompatible($data['payload'] ?? $data['payload_json'] ?? [])),
            'traffic_weight' => min(100, max(0, round((float) ($data['traffic_weight'] ?? 50), 2))),
            'status' => $this->normalizeEnum((string) ($data['status'] ?? 'draft'), self::EXPERIMENT_VARIANT_STATUSES, 'experiment_variant_status'),
            'created_by' => (int) ($data['created_by'] ?? $this->currentUserId()) ?: null,
        ];
    }

    private function normalizeExperimentResultData(array $data): array
    {
        $workspaceId = $this->workspaceId();
        $experimentId = (int) ($data['experiment_id'] ?? 0);
        $variantId = (int) ($data['variant_id'] ?? 0);
        if ($experimentId <= 0 || $variantId <= 0) {
            throw new \InvalidArgumentException('Experiment and variant are required for results.');
        }
        $this->assertWorkspaceRecord('marketing_experiments', $experimentId, $workspaceId);
        $this->assertWorkspaceRecord('marketing_experiment_variants', $variantId, $workspaceId);
        $variant = Database::queryOne(
            "SELECT id FROM marketing_experiment_variants WHERE workspace_id = ? AND experiment_id = ? AND id = ?",
            [$workspaceId, $experimentId, $variantId]
        );
        if (!$variant) {
            throw new RuntimeException('Experiment variant does not belong to the selected experiment.');
        }
        $metric = Security::sanitizeInput((string) ($data['metric_name'] ?? 'conversion_rate'), 'string') ?: 'conversion_rate';
        $observed = trim((string) ($data['observed_at'] ?? ''));

        return [
            'experiment_id' => $experimentId,
            'variant_id' => $variantId,
            'metric_name' => substr($metric, 0, 120),
            'metric_value' => round((float) ($data['metric_value'] ?? 0), 4),
            'sample_size' => max(0, (int) ($data['sample_size'] ?? 0)),
            'observed_at' => $observed !== '' ? $this->normalizeDateTime($observed) : date('Y-m-d H:i:s'),
            'metadata_json' => $this->normalizeJsonValue($this->sanitizeJsonCompatible($data['metadata'] ?? $data['metadata_json'] ?? [])),
            'created_by' => (int) ($data['created_by'] ?? $this->currentUserId()) ?: null,
        ];
    }

    private function normalizeUtmLinkData(array $data): array
    {
        $workspaceId = $this->workspaceId();
        $url = trim((string) ($data['url'] ?? ''));
        if (!filter_var($url, FILTER_VALIDATE_URL) || !preg_match('/^https?:\\/\\//i', $url)) {
            throw new \InvalidArgumentException('A valid HTTP or HTTPS URL is required.');
        }

        $normalized = [
            'url' => $url,
            'created_by' => (int) ($data['created_by'] ?? ($_SESSION['user_id'] ?? 0)) ?: null,
        ];
        foreach (['campaign_id' => 'campaigns', 'content_item_id' => 'marketing_content_items'] as $field => $table) {
            $id = (int) ($data[$field] ?? 0);
            if ($id > 0) {
                $this->assertWorkspaceRecord($table, $id, $workspaceId);
                $normalized[$field] = $id;
            } else {
                $normalized[$field] = null;
            }
        }
        foreach (['utm_source', 'utm_medium', 'utm_campaign', 'utm_term', 'utm_content'] as $field) {
            $normalized[$field] = $this->nullableSanitizedText($data[$field] ?? '');
        }
        $normalized['generated_url'] = $this->appendUtmQuery($url, array_filter([
            'utm_source' => $normalized['utm_source'],
            'utm_medium' => $normalized['utm_medium'],
            'utm_campaign' => $normalized['utm_campaign'],
            'utm_term' => $normalized['utm_term'],
            'utm_content' => $normalized['utm_content'],
        ], static fn($value): bool => $value !== null && $value !== ''));

        return $normalized;
    }

