            $normalized['template_key'] = trim($key, '_-');
            if ($normalized['template_key'] === '') {
                throw new \InvalidArgumentException('Calendar template key is required.');
            }
        }
        if ($forCreate || array_key_exists('milestone_type', $data)) {
