        }
        if ($forCreate || array_key_exists('channel', $data)) {
            $channel = trim((string) ($data['channel'] ?? ''));
            $normalized['channel'] = $channel !== '' ? $this->normalizeEnum($channel, self::CHANNELS, 'calendar_channel') : null;
        }
        if ($forCreate || array_key_exists('offset_days', $data)) {
            $normalized['offset_days'] = max(-365, min(365, (int) ($data['offset_days'] ?? 0)));
        }
        if ($forCreate || array_key_exists('default_title', $data)) {
            $title = Security::sanitizeInput((string) ($data['default_title'] ?? $data['name'] ?? ''), 'string');
            if ($title === '') {
                throw new \InvalidArgumentException('Calendar template default title is required.');
            }
            $normalized['default_title'] = $title;
        }
        if ($forCreate || array_key_exists('checklist_json', $data) || array_key_exists('checklist', $data)) {
            $normalized['checklist_json'] = $this->normalizeStringListJson($data['checklist'] ?? $data['checklist_json'] ?? []);
        }
        if ($forCreate || array_key_exists('metadata_json', $data) || array_key_exists('metadata', $data)) {
            $normalized['metadata_json'] = $this->normalizeJsonValue($this->sanitizeFlexibleArray($data['metadata'] ?? $data['metadata_json'] ?? []));
        }
        if ($forCreate || array_key_exists('owner_user_id', $data)) {
            $ownerId = (int) ($data['owner_user_id'] ?? 0);
            if ($ownerId > 0) {
                $this->assertWorkspaceUser($ownerId, $workspaceId);
                $normalized['owner_user_id'] = $ownerId;
            } else {
                $normalized['owner_user_id'] = null;
            }
        }
        if ($forCreate) {
            $createdBy = (int) ($data['created_by'] ?? $this->currentUserId());
            $normalized['created_by'] = $createdBy > 0 ? $createdBy : null;
        }

        return $normalized;
    }

    private function updateById(string $table, int $id, array $data): bool
    {
        if ($data === []) {
            return true;
        }

        $updates = [];
        $params = [];
        foreach ($data as $field => $value) {
            $updates[] = $field . ' = ?';
            $params[] = $value;
        }
        $params[] = $this->workspaceId();
        $params[] = $id;

        Database::execute(
            "UPDATE {$table} SET " . implode(', ', $updates) . " WHERE workspace_id = ? AND id = ?",
            $params
        );

        return true;
    }

    private function shouldVersionContent(array $existing, array $normalized): bool
    {
        foreach (['title', 'draft_body', 'status'] as $field) {
            if (array_key_exists($field, $normalized) && (string) ($existing[$field] ?? '') !== (string) ($normalized[$field] ?? '')) {
                return Database::tableExists('marketing_content_versions');
            }
        }

        return false;
    }

    private function createContentVersion(int $contentItemId, array $content, string $summary): int
    {
        $row = Database::queryOne(
            'SELECT COALESCE(MAX(version_number), 0) + 1 AS next_version FROM marketing_content_versions WHERE workspace_id = ? AND content_item_id = ?',
            [$this->workspaceId(), $contentItemId]
        );
        $next = (int) ($row['next_version'] ?? 1);
        Database::execute(
            "INSERT INTO marketing_content_versions
             (workspace_id, content_item_id, version_number, title, draft_body, status, change_summary, created_by)
             VALUES (?, ?, ?, ?, ?, ?, ?, ?)",
            [
                $this->workspaceId(),
                $contentItemId,
                $next,
                (string) ($content['title'] ?? ''),
                $content['draft_body'] ?? null,
                (string) ($content['status'] ?? 'draft'),
                $summary !== '' ? $summary : 'Content updated',
                (int) ($_SESSION['user_id'] ?? 0) ?: null,
            ]
        );

        return (int) Database::lastInsertId();
    }

    private function assertContentItem(int $contentItemId): array
    {
        $item = $this->getContentItem($contentItemId);
        if (!$item) {
            throw new RuntimeException('Marketing content item not found.');
        }

        return $item;
    }

    private function listOpenComments(int $limit): array
    {
        return Database::query(
            "SELECT cc.*, m.title AS content_title, creator.email AS created_by_email
             FROM marketing_content_comments cc
             JOIN marketing_content_items m ON m.id = cc.content_item_id AND m.workspace_id = cc.workspace_id
             LEFT JOIN users creator ON creator.id = cc.created_by
             WHERE cc.workspace_id = ? AND cc.resolved_at IS NULL
             ORDER BY cc.created_at DESC
             LIMIT {$limit}",
            [$this->workspaceId()]
        );
    }

    private function getCampaignForWorkspace(int $campaignId): ?array
    {
        if (!Database::tableExists('campaigns') || $campaignId <= 0) {
            return null;
        }

        $row = Database::queryOne(
            "SELECT c.*, creator.email AS created_by_email
             FROM campaigns c
             LEFT JOIN users creator ON creator.id = c.created_by
             WHERE c.workspace_id = ? AND c.id = ?
             LIMIT 1",
            [$this->workspaceId(), $campaignId]
        );
        if (!$row) {
            return null;
        }

        return $this->hydrateJsonFields($row, ['channel_mix']);
    }

    private function campaignFromWorkspaceRow(array $row): array
    {
        $campaign = [
            'id' => (int) ($row['campaign_id'] ?? $row['id'] ?? 0),
            'uuid' => (string) ($row['campaign_uuid'] ?? $row['uuid'] ?? ''),
            'name' => (string) ($row['campaign_name'] ?? $row['name'] ?? ''),
            'description' => (string) ($row['campaign_description'] ?? $row['description'] ?? ''),
            'objective' => (string) ($row['campaign_objective'] ?? $row['objective'] ?? ''),
            'channel_mix' => $row['campaign_channel_mix'] ?? $row['channel_mix'] ?? [],
            'status' => (string) ($row['campaign_status'] ?? $row['status'] ?? 'draft'),
            'scheduled_start_at' => $row['campaign_start_at'] ?? $row['scheduled_start_at'] ?? null,
            'scheduled_end_at' => $row['campaign_end_at'] ?? $row['scheduled_end_at'] ?? null,
            'created_by' => $row['campaign_created_by'] ?? $row['created_by'] ?? null,
            'created_at' => $row['campaign_created_at'] ?? $row['created_at'] ?? null,
            'updated_at' => $row['campaign_updated_at'] ?? $row['updated_at'] ?? null,
            'created_by_email' => (string) ($row['campaign_created_by_email'] ?? $row['created_by_email'] ?? ''),
        ];

        return $this->hydrateJsonFields($campaign, ['channel_mix']);
    }

    private function hydrateCampaignWorkspaceRow(array $row): array
    {
        $workspace = [
            'id' => (int) ($row['cw_id'] ?? $row['id'] ?? 0),
            'workspace_id' => $this->workspaceId(),
            'campaign_id' => (int) ($row['campaign_id'] ?? 0),
            'uuid' => (string) ($row['cw_uuid'] ?? $row['uuid'] ?? ''),
            'workspace_name' => (string) ($row['cw_workspace_name'] ?? $row['workspace_name'] ?? ''),
            'status' => (string) ($row['cw_status'] ?? $row['status'] ?? 'draft'),
            'health_score' => (int) ($row['cw_health_score'] ?? $row['health_score'] ?? 0),
            'readiness_json' => $row['cw_readiness_json'] ?? $row['readiness_json'] ?? [],
            'linked_summary_json' => $row['cw_linked_summary_json'] ?? $row['linked_summary_json'] ?? [],
            'missing_requirements_json' => $row['cw_missing_requirements_json'] ?? $row['missing_requirements_json'] ?? [],
            'warning_json' => $row['cw_warning_json'] ?? $row['warning_json'] ?? [],
            'next_actions_json' => $row['cw_next_actions_json'] ?? $row['next_actions_json'] ?? [],
            'metadata_json' => $row['cw_metadata_json'] ?? $row['metadata_json'] ?? [],
            'owner_user_id' => $row['cw_owner_user_id'] ?? $row['owner_user_id'] ?? null,
            'owner_email' => (string) ($row['owner_email'] ?? ''),
            'refreshed_by' => $row['cw_refreshed_by'] ?? $row['refreshed_by'] ?? null,
            'refreshed_by_email' => (string) ($row['refreshed_by_email'] ?? ''),
            'refreshed_at' => $row['cw_refreshed_at'] ?? $row['refreshed_at'] ?? null,
            'created_by' => $row['cw_created_by'] ?? $row['created_by'] ?? null,
            'created_at' => $row['cw_created_at'] ?? $row['created_at'] ?? null,
            'updated_at' => $row['cw_updated_at'] ?? $row['updated_at'] ?? null,
            'campaign' => $this->campaignFromWorkspaceRow($row),
        ];

        $workspace = $this->hydrateJsonFields($workspace, [
            'readiness_json',
            'linked_summary_json',
            'missing_requirements_json',
            'warning_json',
            'next_actions_json',
            'metadata_json',
        ]);
        $workspace['campaign_name'] = (string) ($workspace['campaign']['name'] ?? '');
        $workspace['campaign_status'] = (string) ($workspace['campaign']['status'] ?? '');

        return $workspace;
    }

    private function buildMarketingCampaignWorkspace(array $campaign): array
    {
        $campaignId = (int) ($campaign['id'] ?? $campaign['campaign_id'] ?? 0);
        if ($campaignId <= 0) {
            throw new RuntimeException('Campaign was not found in the active workspace.');
        }

        $briefs = Database::tableExists('marketing_campaign_briefs') ? $this->listCampaignBriefs(['campaign_id' => $campaignId], 8, 0) : [];
        $contentItems = Database::tableExists('marketing_content_items') ? $this->listContentItems(['campaign_id' => $campaignId, 'exclude_status' => 'archived'], 8, 0) : [];
        $landingPages = Database::tableExists('marketing_landing_pages') ? $this->listLandingPages(['campaign_id' => $campaignId], 8, 0) : [];
        $distributionPosts = Database::tableExists('marketing_distribution_posts') ? $this->listDistributionPosts(['campaign_id' => $campaignId], 8, 0) : [];
        $emailRuns = Database::tableExists('marketing_email_campaign_runs') ? $this->listEmailCampaignRuns(['campaign_id' => $campaignId], 8, 0) : [];
        $utmLinks = Database::tableExists('marketing_utm_links') ? $this->listUtmLinks(['campaign_id' => $campaignId], 8, 0) : [];
        $launchReadiness = Database::tableExists('marketing_launch_readiness_reviews') ? $this->listLaunchReadinessReviews(['campaign_id' => $campaignId], 8, 0) : [];
        $launchControl = Database::tableExists('marketing_launch_control_records') ? $this->listLaunchControlRecords(['campaign_id' => $campaignId], 8, 0) : [];
        $audienceActivations = Database::tableExists('marketing_audience_activations') ? $this->listAudienceActivations(['campaign_id' => $campaignId], 8, 0) : [];
        $calendar = Database::tableExists('marketing_calendar_milestones') ? $this->listCalendarMilestones(['campaign_id' => $campaignId], 8, 0) : [];
        $planning = Database::tableExists('marketing_planning_queue_items') ? $this->listPlanningQueueItems(['campaign_id' => $campaignId], 8, 0) : [];
        $channelExports = Database::tableExists('marketing_channel_export_bundles') ? $this->listChannelExportBundles(['campaign_id' => $campaignId], 8, 0) : [];
        $launchChecklists = Database::tableExists('marketing_campaign_launch_checklists') ? $this->listCampaignLaunchChecklists(['campaign_id' => $campaignId], 8, 0) : [];
        $budgets = Database::tableExists('marketing_campaign_budgets') ? $this->listCampaignBudgets(['campaign_id' => $campaignId], 8, 0) : [];
        $experiments = Database::tableExists('marketing_experiments') ? $this->listExperiments(['campaign_id' => $campaignId], 8, 0) : [];

        $audienceCoverage = count($audienceActivations);
        foreach ($briefs as $brief) {
            if ((int) ($brief['audience_segment_id'] ?? 0) > 0) {
                $audienceCoverage++;
            }
        }
        foreach ($landingPages as $landingPage) {
            if ((int) ($landingPage['audience_segment_id'] ?? 0) > 0) {
                $audienceCoverage++;
            }
        }
        foreach ($emailRuns as $emailRun) {
            if ((int) ($emailRun['audience_segment_id'] ?? 0) > 0) {
                $audienceCoverage++;
            }
        }

        $checks = [];
        $missing = [];
        $warnings = [];
        $nextActions = [];
        $addCheck = function (string $key, string $label, bool $passed, bool $required, string $href, string $message) use (&$checks, &$missing, &$warnings, &$nextActions): void {
            $status = $passed ? 'ready' : ($required ? 'missing' : 'warning');
            $check = [
                'key' => $key,
                'label' => $label,
                'status' => $status,
                'required' => $required,
                'href' => $href,
                'message' => $message,
            ];
            $checks[] = $check;
            if ($passed) {
                return;
            }
            if ($required) {
                $missing[] = $check;
            } else {
                $warnings[] = $check;
            }
            $nextActions[] = [
                'label' => $label,
                'href' => $href,
                'reason' => $message,
                'required' => $required,
            ];
        };

        $addCheck('brief', 'Add campaign brief', count($briefs) > 0, true, 'marketing_brief_edit.php?campaign_id=' . $campaignId, 'Campaign needs a connected brief before launch.');
        $addCheck('audience', 'Activate audience', $audienceCoverage > 0, true, 'marketing_audience_activation.php?campaign_id=' . $campaignId, 'Campaign needs a segment or audience activation.');
        $addCheck('landing_page', 'Create landing page plan', count($landingPages) > 0, true, 'marketing_landing_page_edit.php?campaign_id=' . $campaignId, 'Campaign needs a conversion destination.');
        $addCheck('content', 'Create campaign content', count($contentItems) > 0, true, 'marketing_content_edit.php?campaign_id=' . $campaignId, 'Campaign needs launch content.');
        $addCheck('distribution', 'Build distribution package', count($distributionPosts) + count($channelExports) > 0, true, 'marketing_distribution.php?campaign_id=' . $campaignId, 'Campaign needs a manual export or distribution package.');
        $addCheck('tracking', 'Generate tracking links', count($utmLinks) > 0, true, 'marketing_utm_links.php?campaign_id=' . $campaignId, 'Campaign needs UTM/tracking links before launch.');
        $addCheck('readiness', 'Run launch readiness', count($launchReadiness) > 0, true, 'marketing_launch_readiness.php?campaign_id=' . $campaignId, 'Campaign needs a readiness review.');
        $addCheck('launch_checklist', 'Create launch checklist', count($launchChecklists) > 0, false, 'marketing_launch_checklists.php?campaign_id=' . $campaignId, 'Launch checklists make manual go-live steps visible before execution.');
        $addCheck('launch_control', 'Prepare launch control', count($launchControl) > 0, false, 'marketing_launch_control.php?campaign_id=' . $campaignId, 'Prepare final manual launch controls when readiness is complete.');
        $addCheck('budget', 'Add budget or ROI plan', count($budgets) > 0, false, 'marketing_performance.php', 'Budget and ROI context improves reporting confidence.');
        $addCheck('experiment', 'Plan an experiment', count($experiments) > 0, false, 'marketing_performance.php', 'A/B tests or hypotheses improve optimization after launch.');

        $requiredChecks = array_values(array_filter($checks, static fn(array $check): bool => (bool) $check['required']));
        $readyRequired = count(array_filter($requiredChecks, static fn(array $check): bool => (string) $check['status'] === 'ready'));
        $healthScore = count($requiredChecks) > 0 ? (int) round(($readyRequired / count($requiredChecks)) * 100) : 0;
        $campaignStatus = (string) ($campaign['status'] ?? 'draft');
        $launchStatus = (string) ($launchControl[0]['status'] ?? '');
        $status = match (true) {
            $campaignStatus === 'archived' => 'archived',
            $campaignStatus === 'completed' => 'completed',
            in_array($launchStatus, ['launched_manual', 'completed'], true) => 'launched',
            $missing !== [] => 'blocked',
            $healthScore >= 85 => 'ready',
            $campaignStatus === 'active' || $campaignStatus === 'paused' => 'active',
            default => 'draft',
        };
        $ownerUserId = (int) ($briefs[0]['owner_user_id'] ?? 0) ?: ((int) ($campaign['created_by'] ?? 0) ?: null);
        $campaignName = Security::sanitizeInput((string) ($campaign['name'] ?? 'Campaign workspace'), 'string');
        if ($campaignName === '') {
            $campaignName = 'Campaign workspace';
        }

        return [
            'id' => 0,
            'workspace_id' => $this->workspaceId(),
            'campaign_id' => $campaignId,
            'uuid' => '',
            'workspace_name' => substr($campaignName . ' Workspace', 0, 180),
            'status' => $status,
            'health_score' => $healthScore,
            'readiness_json' => $checks,
            'linked_summary_json' => [
                'campaign' => [
                    'id' => $campaignId,
                    'name' => $campaignName,
                    'status' => $campaignStatus,
                    'objective' => (string) ($campaign['objective'] ?? ''),
                ],
                'briefs' => ['count' => count($briefs), 'records' => $this->campaignWorkspaceRecordSummaries($briefs)],
                'audience_activations' => ['count' => count($audienceActivations), 'records' => $this->campaignWorkspaceRecordSummaries($audienceActivations)],
                'landing_pages' => ['count' => count($landingPages), 'records' => $this->campaignWorkspaceRecordSummaries($landingPages)],
                'content_items' => ['count' => count($contentItems), 'records' => $this->campaignWorkspaceRecordSummaries($contentItems)],
                'distribution_posts' => ['count' => count($distributionPosts), 'records' => $this->campaignWorkspaceRecordSummaries($distributionPosts)],
                'channel_exports' => ['count' => count($channelExports), 'records' => $this->campaignWorkspaceRecordSummaries($channelExports)],
                'email_runs' => ['count' => count($emailRuns), 'records' => $this->campaignWorkspaceRecordSummaries($emailRuns)],
                'utm_links' => ['count' => count($utmLinks), 'records' => $this->campaignWorkspaceRecordSummaries($utmLinks)],
                'launch_readiness' => ['count' => count($launchReadiness), 'records' => $this->campaignWorkspaceRecordSummaries($launchReadiness)],
                'launch_control' => ['count' => count($launchControl), 'records' => $this->campaignWorkspaceRecordSummaries($launchControl)],
                'launch_checklists' => ['count' => count($launchChecklists), 'records' => $this->campaignWorkspaceRecordSummaries($launchChecklists)],
                'calendar' => ['count' => count($calendar), 'records' => $this->campaignWorkspaceRecordSummaries($calendar)],
                'planning_queue' => ['count' => count($planning), 'records' => $this->campaignWorkspaceRecordSummaries($planning)],
                'budgets' => ['count' => count($budgets), 'records' => $this->campaignWorkspaceRecordSummaries($budgets)],
                'experiments' => ['count' => count($experiments), 'records' => $this->campaignWorkspaceRecordSummaries($experiments)],
            ],
            'missing_requirements_json' => $missing,
            'warning_json' => $warnings,
            'next_actions_json' => array_slice($nextActions, 0, 8),
            'metadata_json' => [
                'computed_at' => date('c'),
                'manual_first_boundary' => true,
                'external_publish' => false,
                'external_send' => false,
                'virtual_until_refreshed' => true,
            ],
            'owner_user_id' => $ownerUserId,
            'owner_email' => '',
            'refreshed_by' => null,
            'refreshed_by_email' => '',
            'refreshed_at' => null,
            'created_by' => null,
            'created_at' => null,
            'updated_at' => null,
            'campaign' => $campaign,
            'campaign_name' => $campaignName,
            'campaign_status' => $campaignStatus,
        ];
    }

    /**
     * @return array<int,array<string,mixed>>
     */
    private function campaignWorkspaceRecordSummaries(array $rows): array
    {
        $summaries = [];
        foreach (array_slice($rows, 0, 6) as $row) {
            $summaries[] = [
                'id' => (int) ($row['id'] ?? 0),
                'title' => (string) ($row['title'] ?? $row['name'] ?? $row['launch_name'] ?? $row['activation_name'] ?? $row['channel'] ?? 'Marketing record'),
                'status' => (string) ($row['status'] ?? $row['coverage_status'] ?? ''),
                'date' => (string) ($row['scheduled_at'] ?? $row['launch_date'] ?? $row['milestone_date'] ?? $row['updated_at'] ?? ''),
            ];
        }

        return $summaries;
    }

    private function countRows(string $table, string $condition): int
    {
        $row = Database::queryOne(
            "SELECT COUNT(*) AS count FROM {$table} WHERE workspace_id = ? AND {$condition}",
            [$this->workspaceId()]
        );

        return (int) ($row['count'] ?? 0);
    }

    private function marketingWorkspaceRecordCount(string $table, string $condition = '1=1'): int
    {
        if (!Database::tableExists($table) || !Database::columnExists($table, 'workspace_id')) {
            return 0;
        }

        return $this->countRows($table, $condition);
    }

    private function marketingDistributionWithoutBundleCount(): int
    {
        if (!Database::tableExists('marketing_distribution_posts') || !Database::columnExists('marketing_distribution_posts', 'workspace_id')) {
            return 0;
        }
        if (!Database::tableExists('marketing_channel_export_bundles') || !Database::columnExists('marketing_channel_export_bundles', 'distribution_post_id')) {
            return $this->countRows('marketing_distribution_posts', "status IN ('draft','scheduled')");
        }

        $row = Database::queryOne(
            "SELECT COUNT(*) AS count
             FROM marketing_distribution_posts d
             WHERE d.workspace_id = ?
               AND d.status IN ('draft','scheduled')
               AND NOT EXISTS (
                   SELECT 1
                   FROM marketing_channel_export_bundles b
                   WHERE b.workspace_id = d.workspace_id
                     AND b.distribution_post_id = d.id
               )",
            [$this->workspaceId()]
        );

        return (int) ($row['count'] ?? 0);
    }

    private function marketingContentWithoutMediaCount(): int
    {
        if (!Database::tableExists('marketing_content_items') || !Database::columnExists('marketing_content_items', 'workspace_id')) {
            return 0;
        }
        if (!Database::tableExists('marketing_content_media')) {
            return $this->countRows(
                'marketing_content_items',
                "status <> 'archived' AND content_type IN ('blog_post','case_study','social_post','ad_copy','video_script','email','newsletter')"
            );
        }

        $row = Database::queryOne(
            "SELECT COUNT(*) AS count
             FROM marketing_content_items ci
             WHERE ci.workspace_id = ?
               AND ci.status <> 'archived'
               AND ci.content_type IN ('blog_post','case_study','social_post','ad_copy','video_script','email','newsletter')
               AND NOT EXISTS (
                   SELECT 1
                   FROM marketing_content_media cm
                   WHERE cm.workspace_id = ci.workspace_id
                     AND cm.content_item_id = ci.id
               )",
            [$this->workspaceId()]
        );

        return (int) ($row['count'] ?? 0);
    }

    private function marketingDistributionWithoutMediaCount(): int
    {
        if (!Database::tableExists('marketing_distribution_posts') || !Database::columnExists('marketing_distribution_posts', 'workspace_id')) {
            return 0;
        }
        if (!Database::tableExists('marketing_assets')) {
            return $this->countRows('marketing_distribution_posts', "status IN ('draft','scheduled','exported')");
        }

        $contentMediaExists = Database::tableExists('marketing_content_media')
            ? "OR EXISTS (
                    SELECT 1
                    FROM marketing_content_media cm
                    WHERE cm.workspace_id = d.workspace_id
                      AND cm.content_item_id = d.content_item_id
               )"
            : '';
        $row = Database::queryOne(
            "SELECT COUNT(*) AS count
             FROM marketing_distribution_posts d
             LEFT JOIN marketing_assets a ON a.id = d.asset_id AND a.workspace_id = d.workspace_id
             WHERE d.workspace_id = ?
               AND d.status IN ('draft','scheduled','exported')
               AND NOT (
                   COALESCE(a.media_file_id, 0) > 0
                   {$contentMediaExists}
               )",
            [$this->workspaceId()]
        );

        return (int) ($row['count'] ?? 0);
    }

    private function marketingChannelMediaKitBlockedCount(): int
    {
        if (!Database::tableExists('marketing_channel_media_kits') || !Database::columnExists('marketing_channel_media_kits', 'workspace_id')) {
            return 0;
        }

        $blocked = 0;
        foreach ($this->listChannelMediaKits([], 250, 0) as $kit) {
            $readiness = (array) ($kit['readiness_json'] ?? []);
            if ($readiness === []) {
                $readiness = $this->channelMediaKitReadiness($kit);
            }
            if (empty($readiness['ready']) || !empty($readiness['missing']) || in_array((string) ($kit['status'] ?? ''), ['blocked', 'archived'], true)) {
                $blocked++;
            }
        }

        return $blocked;
    }

    private function marketingDistributionMissingChecklistCount(): int
    {
        if (!Database::tableExists('marketing_distribution_posts') || !Database::columnExists('marketing_distribution_posts', 'workspace_id')) {
            return 0;
        }
        if (!Database::columnExists('marketing_distribution_posts', 'publishing_checklist_json') || !Database::columnExists('marketing_distribution_posts', 'required_fields_json')) {
            return 0;
        }

        $row = Database::queryOne(
            "SELECT COUNT(*) AS count
             FROM marketing_distribution_posts
             WHERE workspace_id = ?
               AND status IN ('draft','scheduled')
               AND (
                   publishing_checklist_json IS NULL
                   OR JSON_LENGTH(publishing_checklist_json) = 0
                   OR required_fields_json IS NULL
                   OR JSON_LENGTH(required_fields_json) = 0
               )",
            [$this->workspaceId()]
        );

        return (int) ($row['count'] ?? 0);
    }

    private function marketingEmailRunsMissingChecklistCount(): int
    {
        if (!Database::tableExists('marketing_email_campaign_runs') || !Database::columnExists('marketing_email_campaign_runs', 'workspace_id')) {
            return 0;
        }

        $conditions = [];
        foreach (['subject', 'body_snapshot'] as $column) {
            if (Database::columnExists('marketing_email_campaign_runs', $column)) {
                $conditions[] = "COALESCE({$column}, '') = ''";
            }
        }
        foreach (['send_checklist_json', 'export_bundle_json'] as $column) {
            if (Database::columnExists('marketing_email_campaign_runs', $column)) {
                $conditions[] = "{$column} IS NULL OR JSON_LENGTH({$column}) = 0";
            }
        }
        if ($conditions === []) {
            return 0;
        }

        $row = Database::queryOne(
            "SELECT COUNT(*) AS count
             FROM marketing_email_campaign_runs
             WHERE workspace_id = ?
               AND status IN ('draft','ready')
               AND (" . implode(' OR ', array_map(static fn(string $condition): string => '(' . $condition . ')', $conditions)) . ')',
            [$this->workspaceId()]
        );

        return (int) ($row['count'] ?? 0);
    }

    private function marketingEmailTemplateIntegrationCount(): int
    {
        if (!Database::tableExists('email_templates')) {
            return 0;
        }

        $where = ['COALESCE(et.is_active, 1) = 1'];
        $params = [];
        if (Database::columnExists('email_templates', 'workspace_id')) {
            $where[] = 'et.workspace_id = ?';
            $params[] = $this->workspaceId();
        }
        if (Database::columnExists('email_templates', 'is_library')) {
            $where[] = 'COALESCE(et.is_library, 0) = 0';
        }
        if (Database::columnExists('email_templates', 'is_ai_generated')) {
            $where[] = "(COALESCE(et.is_ai_generated, 0) = 0 OR et.smart_template_set_id IS NULL OR sts.status = 'active')";
        }

        $row = Database::queryOne(
            'SELECT COUNT(*) AS count
             FROM email_templates et
             LEFT JOIN smart_template_sets sts ON sts.id = et.smart_template_set_id
             WHERE ' . implode(' AND ', $where),
            $params
        );

        return (int) ($row['count'] ?? 0);
    }

    private function marketingCrmLifecycleContext(array $input): array
    {
        $workspaceId = $this->workspaceId();
        $ids = [];
        foreach (['contact_id', 'company_id', 'deal_id', 'campaign_id', 'form_id', 'task_id'] as $field) {
            $ids[$field] = max(0, (int) ($input[$field] ?? 0));
        }

        $records = [];
        if ($ids['deal_id'] > 0) {
            $records['deal'] = $this->marketingCrmScopedRow('deals', $ids['deal_id']) ?? [];
            if ($records['deal'] !== []) {
                $ids['contact_id'] = $ids['contact_id'] ?: (int) ($records['deal']['contact_id'] ?? 0);
                $ids['company_id'] = $ids['company_id'] ?: (int) ($records['deal']['company_id'] ?? 0);
                $ids['campaign_id'] = $ids['campaign_id'] ?: (int) ($records['deal']['campaign_id'] ?? 0);
            }
        }
        if ($ids['contact_id'] > 0) {
            $records['contact'] = $this->marketingCrmScopedRow('contacts', $ids['contact_id']) ?? [];
            if ($records['contact'] !== []) {
                $ids['company_id'] = $ids['company_id'] ?: (int) ($records['contact']['company_id'] ?? 0);
            }
        }
        if ($ids['company_id'] > 0) {
            $records['company'] = $this->marketingCrmScopedRow('companies', $ids['company_id']) ?? [];
        }
        if ($ids['campaign_id'] > 0) {
            $records['campaign'] = $this->marketingCrmScopedRow('campaigns', $ids['campaign_id']) ?? [];
        }
        if ($ids['form_id'] <= 0) {
            $ids['form_id'] = $this->marketingCrmLifecycleDerivedFormId($ids);
        }
        if ($ids['form_id'] > 0) {
            $records['form'] = $this->marketingCrmScopedRow('forms', $ids['form_id']) ?? [];
        }
        if ($ids['task_id'] > 0) {
            $records['task'] = $this->marketingCrmScopedRow('tasks', $ids['task_id']) ?? [];
            if ($records['task'] !== []) {
                $ids['contact_id'] = $ids['contact_id'] ?: (int) ($records['task']['contact_id'] ?? 0);
                $ids['deal_id'] = $ids['deal_id'] ?: (int) ($records['task']['deal_id'] ?? 0);
            }
        }

        $scope = 'workspace';
        foreach (['deal', 'contact', 'company', 'campaign', 'form', 'task'] as $candidate) {
            if (!empty($records[$candidate])) {
                $scope = $candidate;
                break;
            }
        }

        return [
            'workspace_id' => $workspaceId,
            'scope' => $scope,
            'scope_label' => $this->marketingCrmLifecycleScopeLabel($scope, $records),
            'ids' => $ids,
            'records' => $records,
        ];
    }

    private function marketingCrmScopedRow(string $table, int $id): ?array
    {
        if ($id <= 0 || !Database::tableExists($table) || !Database::columnExists($table, 'workspace_id')) {
            return null;
        }
        $this->assertWorkspaceRecord($table, $id, $this->workspaceId());

        return Database::queryOne(
            "SELECT * FROM {$table} WHERE workspace_id = ? AND id = ? LIMIT 1",
            [$this->workspaceId(), $id]
        ) ?: null;
    }

    private function marketingCrmLifecycleScopeLabel(string $scope, array $records): string
    {
        return match ($scope) {
            'deal' => 'Deal: ' . (string) ($records['deal']['title'] ?? 'CRM deal'),
            'contact' => 'Contact: ' . trim((string) (($records['contact']['first_name'] ?? '') . ' ' . ($records['contact']['last_name'] ?? ''))) ?: 'Contact lifecycle',
            'company' => 'Company: ' . (string) ($records['company']['name'] ?? 'CRM company'),
            'campaign' => 'Campaign: ' . (string) ($records['campaign']['name'] ?? 'CRM campaign'),
            'form' => 'Form: ' . (string) ($records['form']['name'] ?? 'CRM form'),
            'task' => 'Task: ' . (string) ($records['task']['title'] ?? 'CRM task'),
            default => 'Workspace lifecycle',
        };
    }

    private function marketingCrmLifecycleCondition(string $table, array $context): array
    {
        if (!Database::tableExists($table)) {
            return ['sql' => '0=1', 'params' => []];
        }
        $ids = (array) ($context['ids'] ?? []);
        $clauses = [];
        $params = [];
        $addId = static function (array &$clauses, array &$params, string $field, int $value): void {
            if ($value > 0) {
                $clauses[] = "{$field} = ?";
                $params[] = $value;
            }
        };

        if ($table === 'companies') {
            $addId($clauses, $params, 'id', (int) ($ids['company_id'] ?? 0));
        } elseif ($table === 'contacts') {
            $addId($clauses, $params, 'id', (int) ($ids['contact_id'] ?? 0));
            if ($clauses === [] && Database::columnExists($table, 'company_id')) {
                $addId($clauses, $params, 'company_id', (int) ($ids['company_id'] ?? 0));
            }
        } elseif ($table === 'deals') {
            $addId($clauses, $params, 'id', (int) ($ids['deal_id'] ?? 0));
        } elseif ($table === 'campaigns') {
            $addId($clauses, $params, 'id', (int) ($ids['campaign_id'] ?? 0));
        } elseif ($table === 'forms') {
            $addId($clauses, $params, 'id', (int) ($ids['form_id'] ?? 0));
        } elseif ($table === 'tasks') {
            $addId($clauses, $params, 'id', (int) ($ids['task_id'] ?? 0));
        }

        foreach (['contact_id', 'company_id', 'deal_id', 'campaign_id', 'form_id', 'task_id'] as $field) {
            if ($table === 'form_submissions' && !in_array($field, ['contact_id'], true)) {
                continue;
            }
            if (!Database::columnExists($table, $field)) {
                continue;
            }
            $value = (int) ($ids[$field] ?? 0);
            if ($value > 0 && !in_array("{$field} = ?", $clauses, true)) {
                $clauses[] = "{$field} = ?";
                $params[] = $value;
            }
        }

        if ($table === 'form_submissions' && (int) ($ids['form_id'] ?? 0) > 0 && Database::columnExists('form_submissions', 'form_definition_id')) {
            $clauses[] = 'form_definition_id = ?';
            $params[] = (int) $ids['form_id'];
        }

        return [
            'sql' => $clauses !== [] ? implode(' AND ', $clauses) : '1=1',
            'params' => $params,
        ];
    }

    private function marketingCrmLifecycleDerivedFormId(array $ids): int
    {
        $workspaceId = $this->workspaceId();
        foreach ([
            ['marketing_lead_handoffs', ['deal_id', 'contact_id', 'campaign_id']],
            ['marketing_landing_pages', ['campaign_id']],
            ['marketing_content_items', ['campaign_id']],
        ] as [$table, $fields]) {
            if (!Database::tableExists($table) || !Database::columnExists($table, 'workspace_id') || !Database::columnExists($table, 'form_id')) {
                continue;
            }
            $where = ['workspace_id = ?', 'form_id IS NOT NULL'];
            $params = [$workspaceId];
            foreach ($fields as $field) {
                if ((int) ($ids[$field] ?? 0) > 0 && Database::columnExists($table, $field)) {
                    $where[] = "{$field} = ?";
                    $params[] = (int) $ids[$field];
                }
            }
            if (count($where) <= 2) {
                continue;
            }
            $row = Database::queryOne(
                "SELECT form_id FROM {$table} WHERE " . implode(' AND ', $where) . ' ORDER BY updated_at DESC, id DESC LIMIT 1',
                $params
            );
            $formId = (int) ($row['form_id'] ?? 0);
            if ($formId > 0) {
                return $formId;
            }
        }

        return 0;
    }

    private function marketingCrmLifecycleCount(string $table, array $context, string $baseCondition = '1=1'): int
    {
        if (!Database::tableExists($table) || !Database::columnExists($table, 'workspace_id')) {
            return 0;
        }
        $condition = $this->marketingCrmLifecycleCondition($table, $context);
        $where = [$condition['sql']];
        if (trim($baseCondition) !== '' && $baseCondition !== '1=1') {
            $where[] = '(' . $baseCondition . ')';
        }
        $row = Database::queryOne(
            "SELECT COUNT(*) AS count FROM {$table} WHERE workspace_id = ? AND " . implode(' AND ', $where),
            array_merge([$this->workspaceId()], (array) $condition['params'])
        );

        return (int) ($row['count'] ?? 0);
    }

    private function marketingCrmLifecycleRows(string $table, string $fields, array $context, string $baseCondition = '1=1', string $orderBy = 'id DESC', int $limit = 8): array
    {
        if (!Database::tableExists($table) || !Database::columnExists($table, 'workspace_id')) {
            return [];
        }
        $selectFields = [];
        foreach (array_map('trim', explode(',', $fields)) as $field) {
            $column = preg_replace('/[^a-zA-Z0-9_]/', '', $field);
            if ($column !== '' && Database::columnExists($table, $column)) {
                $selectFields[] = $column;
            }
        }
        if ($selectFields === []) {
            $selectFields[] = 'id';
        }
        if (!in_array('id', $selectFields, true) && Database::columnExists($table, 'id')) {
            array_unshift($selectFields, 'id');
        }

        $condition = $this->marketingCrmLifecycleCondition($table, $context);
        $where = [$condition['sql']];
        if (trim($baseCondition) !== '' && $baseCondition !== '1=1') {
            $where[] = '(' . $baseCondition . ')';
        }
        $safeOrder = $this->marketingCrmSafeOrderBy($table, $orderBy);
        $limit = min(max($limit, 1), 25);

        return Database::query(
            'SELECT ' . implode(', ', $selectFields) . " FROM {$table} WHERE workspace_id = ? AND " . implode(' AND ', $where) . " ORDER BY {$safeOrder} LIMIT {$limit}",
            array_merge([$this->workspaceId()], (array) $condition['params'])
        );
    }

    private function marketingCrmSafeOrderBy(string $table, string $orderBy): string
    {
        foreach (array_map('trim', explode(',', $orderBy)) as $part) {
            if (preg_match('/^([a-zA-Z0-9_]+)\s+(ASC|DESC)$/i', $part, $matches) && Database::columnExists($table, $matches[1])) {
                return $matches[1] . ' ' . strtoupper($matches[2]);
            }
        }

        return Database::columnExists($table, 'id') ? 'id DESC' : 'created_at DESC';
    }

    private function marketingCrmLifecycleFormSubmissionCount(array $context): int
    {
        if (!Database::tableExists('form_submissions')) {
            return 0;
        }
        $condition = $this->marketingCrmLifecycleCondition('form_submissions', $context);
        if (Database::columnExists('form_submissions', 'workspace_id')) {
            $row = Database::queryOne(
                'SELECT COUNT(*) AS count FROM form_submissions WHERE workspace_id = ? AND ' . $condition['sql'],
                array_merge([$this->workspaceId()], (array) $condition['params'])
            );

            return (int) ($row['count'] ?? 0);
        }
        if (Database::columnExists('form_submissions', 'contact_id') && Database::tableExists('contacts')) {
            $where = ["contact_id IN (SELECT id FROM contacts WHERE workspace_id = ?)"];
            $params = [$this->workspaceId()];
            if ($condition['sql'] !== '1=1') {
                $where[] = $condition['sql'];
                $params = array_merge($params, (array) $condition['params']);
            }
            $row = Database::queryOne('SELECT COUNT(*) AS count FROM form_submissions WHERE ' . implode(' AND ', $where), $params);

            return (int) ($row['count'] ?? 0);
        }

        return 0;
    }

    private function marketingCrmLifecycleHandoffFilters(array $context): array
    {
        $ids = (array) ($context['ids'] ?? []);
        $filters = [];
        foreach (['contact_id', 'deal_id', 'campaign_id', 'form_id'] as $field) {
            if ((int) ($ids[$field] ?? 0) > 0) {
                $filters[$field] = (int) $ids[$field];
            }
        }

        return $filters !== [] ? $filters : ['open' => true];
    }

    private function marketingCrmLifecycleRecommendations(array $context, array $counts): array
    {
        $scope = (string) ($context['scope'] ?? 'workspace');
        $ids = (array) ($context['ids'] ?? []);
        $recommendations = [];
        $add = static function (array &$recommendations, string $key, string $label, string $href, string $reason, string $priority = 'normal'): void {
            $recommendations[] = [
                'key' => $key,
                'label' => $label,
                'href' => $href,
                'reason' => $reason,
                'priority' => $priority,
            ];
        };

        if ((int) ($counts['contacts'] ?? 0) === 0) {
            $add($recommendations, 'capture_contacts', 'Capture CRM Contacts', 'contacts.php', 'Marketing needs CRM contacts before audience, nurture, handoff, and attribution workflows are meaningful.', 'high');
        }
        if ((int) ($counts['audience_segments'] ?? 0) === 0) {
            $add($recommendations, 'define_audience_segment', 'Define Audience Segment', 'marketing_segments.php', 'Create a CRM-derived audience segment so campaigns and manual exports have a clear target.', 'high');
        }
        if ((int) ($counts['campaigns'] ?? 0) === 0) {
            $add($recommendations, 'connect_campaign', 'Connect A CRM Campaign', 'campaigns.php', 'Campaign records anchor briefs, UTM links, landing pages, attribution, and reporting.', 'high');
        }
        if ((int) ($counts['forms'] ?? 0) === 0 || (int) ($counts['form_submissions'] ?? 0) === 0) {
            $add($recommendations, 'connect_forms', 'Connect Forms And Lead Capture', 'forms.php', 'Forms and submissions give Marketing conversion evidence before sales handoff.', 'normal');
        }
        if ((int) ($counts['content_items'] ?? 0) === 0) {
            $href = !empty($ids['campaign_id']) ? 'marketing_content_edit.php?campaign_id=' . (int) $ids['campaign_id'] : 'marketing_content_edit.php';
            $add($recommendations, 'create_content', 'Create Lifecycle Content', $href, 'No linked content is available for this CRM context yet.', 'normal');
        }
        if ((int) ($counts['landing_pages'] ?? 0) === 0) {
            $add($recommendations, 'create_landing_page', 'Plan Landing Page', 'marketing_landing_page_edit.php', 'A reviewed landing page gives this lifecycle path a conversion destination.', 'normal');
        }
        if ((int) ($counts['utm_links'] ?? 0) === 0) {
            $add($recommendations, 'create_utm_links', 'Create UTM Tracking', 'marketing_utm_links.php', 'UTM links are needed before distribution can be tied back to CRM revenue and conversion signals.', 'normal');
        }
        if ((int) ($counts['attribution_touchpoints'] ?? 0) === 0) {
            $add($recommendations, 'verify_attribution', 'Verify Attribution Signals', 'marketing_performance.php', 'No attribution touchpoints are linked to this CRM lifecycle context yet.', 'normal');
        }
        if ($scope !== 'workspace' && (int) ($counts['lead_handoffs_open'] ?? 0) === 0) {
            $add($recommendations, 'setup_handoff', 'Prepare Lead Handoff', 'marketing_handoffs.php', 'This CRM record has no open Marketing handoff, so sales follow-up may not be visible.', 'high');
        }
        if ((int) ($counts['open_tasks'] ?? 0) === 0 && (int) ($counts['lead_handoffs_open'] ?? 0) > 0) {
            $add($recommendations, 'create_follow_up_task', 'Create Follow-up Task', 'tasks.php', 'Open marketing handoffs should have a CRM task or owner follow-up path.', 'high');
        }
        if ($scope !== 'workspace'
            && (int) ($counts['won_deals'] ?? 0) > 0
            && (int) ($counts['customer_nurture_profiles'] ?? 0) === 0
        ) {
            $href = !empty($ids['contact_id'])
                ? 'nurture_view.php?contact_id=' . (int) $ids['contact_id']
                : 'nurture.php';
            $add($recommendations, 'open_customer_nurture', 'Open Customer Care', $href, 'This CRM record has purchase evidence, so the outreach path should continue as post-purchase customer care.', 'high');
        }

        return array_slice($recommendations, 0, 10);
    }

    private function buildMarketingActionRouterCandidates(?int $userId, int $limit, array $context = []): array
    {
        $limit = min(max($limit, 1), 40);
        $candidates = [];
        $seen = [];
        $add = function (array $candidate) use (&$candidates, &$seen, $context): void {
            $normalized = $this->normalizeMarketingActionRouterCandidate($candidate, $context);
            $key = strtolower((string) $normalized['action_key'] . '|' . (string) $normalized['target_href']);
            if (isset($seen[$key])) {
                return;
            }
            $seen[$key] = true;
            $candidates[] = $normalized;
        };

        $profile = $this->getMarketingCrmLifecycleProfile($context, 8);
        $profileIds = (array) ($profile['ids'] ?? []);
        foreach ((array) ($profile['recommendations'] ?? []) as $recommendation) {
            $input = (array) $recommendation;
            $input['source'] = 'CRM Lifecycle';
            $input['source_record_type'] = (string) ($profile['scope'] ?? 'workspace');
            $input['source_record_id'] = $this->marketingActionRouterPrimarySourceId($profileIds, (string) ($profile['scope'] ?? 'workspace'));
            $input['metadata_json'] = [
                'source_score' => (int) ($profile['score'] ?? 0),
                'scope_label' => (string) ($profile['scope_label'] ?? 'Workspace lifecycle'),
                'crm_counts' => (array) ($profile['counts'] ?? []),
            ];
            $add($input);
        }

        $nextBest = $this->getMarketingNextBestActions($userId, min($limit, 12));
        foreach ((array) ($nextBest['actions'] ?? []) as $action) {
            $input = (array) $action;
            $input['source'] = (string) ($input['source'] ?? 'Next Best Action');
            $input['source_record_type'] = 'workspace';
            $input['source_record_id'] = 0;
            $input['metadata_json'] = [
                'category' => (string) ($input['category'] ?? 'marketing'),
                'source_counts' => (array) ($nextBest['counts'] ?? []),
            ];
            $add($input);
        }

        $integrationReadiness = $this->getMarketingIntegrationReadiness();
        foreach ((array) ($integrationReadiness['system_connections'] ?? []) as $connection) {
            if (!empty($connection['ready'])) {
                continue;
            }
            $input = [
                'key' => 'integration_' . (string) ($connection['key'] ?? 'connection'),
                'label' => 'Connect ' . (string) ($connection['label'] ?? 'CRM System'),
                'href' => (string) ($connection['href'] ?? 'marketing_admin.php'),
                'reason' => (string) ($connection['action'] ?? 'Complete this connected CRM setup step.'),
                'recommended_action' => (string) ($connection['action'] ?? 'Complete this connected CRM setup step.'),
                'priority' => (string) ($connection['status'] ?? '') === 'missing' ? 'high' : 'normal',
                'source' => 'Integration Readiness',
                'source_record_type' => 'workspace',
                'source_record_id' => 0,
                'metadata_json' => [
                    'connection_status' => (string) ($connection['status'] ?? 'attention'),
                    'connection_count' => (int) ($connection['count'] ?? 0),
                    'readiness_score' => (int) ($integrationReadiness['score'] ?? 0),
                ],
            ];
            $add($input);
        }

        $priorityRank = ['high' => 4, 'normal' => 3, 'medium' => 2, 'low' => 1];
        usort($candidates, static function (array $left, array $right) use ($priorityRank): int {
            $leftRank = $priorityRank[(string) ($left['priority'] ?? 'normal')] ?? 3;
            $rightRank = $priorityRank[(string) ($right['priority'] ?? 'normal')] ?? 3;
            if ($leftRank !== $rightRank) {
                return $rightRank <=> $leftRank;
            }

            return strcmp((string) ($left['label'] ?? ''), (string) ($right['label'] ?? ''));
        });

        return array_slice($candidates, 0, $limit);
    }

    private function normalizeMarketingActionRouterCandidate(array $candidate, array $context = []): array
    {
        $label = trim((string) ($candidate['label'] ?? $candidate['title'] ?? 'Review CRM marketing action'));
        if ($label === '') {
            $label = 'Review CRM marketing action';
        }
        $href = $this->normalizeMarketingActionRouterHref((string) ($candidate['href'] ?? 'marketing.php'));
        $ids = $this->marketingActionRouterIdsFromContext($context, $href, $candidate);
        $sourceRecordType = trim((string) ($candidate['source_record_type'] ?? 'workspace')) ?: 'workspace';
        $sourceRecordId = max(0, (int) ($candidate['source_record_id'] ?? 0));
        $actionKey = trim((string) ($candidate['action_key'] ?? $candidate['key'] ?? ''));
        if ($actionKey === '') {
            $actionKey = strtolower(preg_replace('/[^a-z0-9]+/i', '_', $label . '_' . $href) ?: 'marketing_action');
        }
        $actionKey = substr(Security::sanitizeInput($actionKey, 'string'), 0, 160);
        if ($actionKey === '') {
            $actionKey = 'marketing_action_' . substr(sha1($label . $href), 0, 24);
        }
        $targetSystem = $this->marketingActionRouterTargetSystem($href);
        $targetRecord = $this->marketingActionRouterTargetRecord($href, $ids);
        $priority = strtolower(trim((string) ($candidate['priority'] ?? 'normal')));
        if (!in_array($priority, self::ACTION_ROUTER_PRIORITIES, true)) {
            $priority = 'normal';
        }

        return [
            'action_key' => $actionKey,
            'action_type' => $this->marketingActionRouterType($href, $actionKey),
            'action_status' => 'suggested',
            'priority' => $priority,
            'label' => substr(Security::sanitizeInput($label, 'string'), 0, 190),
            'reason' => $this->nullableSanitizedText($candidate['reason'] ?? $candidate['message'] ?? $candidate['description'] ?? ''),
            'recommended_action' => $this->nullableSanitizedText($candidate['recommended_action'] ?? $candidate['reason'] ?? ''),
            'source' => $this->nullableSanitizedText($candidate['source'] ?? 'Marketing Action Router'),
            'source_record_type' => substr(Security::sanitizeInput($sourceRecordType, 'string'), 0, 80),
            'source_record_id' => $sourceRecordId,
            'target_system' => $targetSystem,
            'target_href' => $href,
            'target_record_type' => $targetRecord['type'],
            'target_record_id' => $targetRecord['id'],
            'contact_id' => $ids['contact_id'],
            'company_id' => $ids['company_id'],
            'deal_id' => $ids['deal_id'],
            'campaign_id' => $ids['campaign_id'],
            'form_id' => $ids['form_id'],
            'task_id' => $ids['task_id'],
            'email_template_id' => $ids['email_template_id'],
            'content_item_id' => $ids['content_item_id'],
            'metadata_json' => array_merge(
                [
                    'manual_first' => true,
                    'external_publish' => false,
                    'external_send' => false,
                    'target_system' => $targetSystem,
                ],
                (array) ($candidate['metadata_json'] ?? $candidate['metadata'] ?? [])
            ),
        ];
    }

    private function normalizeMarketingActionRouterHref(string $href): string
    {
        $href = trim(str_replace('\\', '/', $href));
        if ($href === '') {
            return 'marketing.php';
        }
        if (preg_match('#^(https?:)?//#i', $href) || preg_match('#^(javascript|data):#i', $href) || str_contains($href, '..')) {
            return 'marketing.php';
        }

        return substr(Security::sanitizeInput($href, 'string'), 0, 255);
    }

    private function marketingActionRouterIdsFromContext(array $context, string $href, array $candidate): array
    {
        $ids = [];
        foreach (['contact_id', 'company_id', 'deal_id', 'campaign_id', 'form_id', 'task_id', 'email_template_id', 'content_item_id'] as $field) {
            $ids[$field] = max(0, (int) ($candidate[$field] ?? $context[$field] ?? 0));
        }

        $query = (string) (parse_url($href, PHP_URL_QUERY) ?: '');
        parse_str($query, $params);
        $recordId = max(0, (int) ($params['id'] ?? 0));
        $path = basename((string) (parse_url($href, PHP_URL_PATH) ?: $href));
        if ($recordId > 0) {
            if (in_array($path, ['contact_view.php', 'contact_edit.php'], true)) {
                $ids['contact_id'] = $ids['contact_id'] ?: $recordId;
            } elseif (in_array($path, ['company_view.php', 'company_edit.php'], true)) {
                $ids['company_id'] = $ids['company_id'] ?: $recordId;
            } elseif (in_array($path, ['deal_view.php', 'deal_edit.php'], true)) {
                $ids['deal_id'] = $ids['deal_id'] ?: $recordId;
            } elseif (in_array($path, ['campaign_view.php', 'campaign_edit.php'], true)) {
                $ids['campaign_id'] = $ids['campaign_id'] ?: $recordId;
            } elseif (in_array($path, ['form_edit.php'], true)) {
                $ids['form_id'] = $ids['form_id'] ?: $recordId;
            } elseif (in_array($path, ['task_view.php', 'task_edit.php'], true)) {
                $ids['task_id'] = $ids['task_id'] ?: $recordId;
            } elseif (in_array($path, ['email_template_view.php', 'email_template_edit.php'], true)) {
                $ids['email_template_id'] = $ids['email_template_id'] ?: $recordId;
            } elseif ($path === 'marketing_content_view.php') {
                $ids['content_item_id'] = $ids['content_item_id'] ?: $recordId;
            }
        }

        foreach (['campaign_id', 'form_id', 'content_item_id'] as $queryField) {
            if (!empty($params[$queryField])) {
                $ids[$queryField] = $ids[$queryField] ?: max(0, (int) $params[$queryField]);
            }
        }

        return $ids;
    }

    private function marketingActionRouterPrimarySourceId(array $ids, string $scope): int
    {
        return match ($scope) {
            'contact' => (int) ($ids['contact_id'] ?? 0),
            'company' => (int) ($ids['company_id'] ?? 0),
            'deal' => (int) ($ids['deal_id'] ?? 0),
            'campaign' => (int) ($ids['campaign_id'] ?? 0),
            'form' => (int) ($ids['form_id'] ?? 0),
            'task' => (int) ($ids['task_id'] ?? 0),
            default => 0,
        };
    }

    private function marketingActionRouterTargetSystem(string $href): string
    {
        $path = basename((string) (parse_url($href, PHP_URL_PATH) ?: $href));
        return match (true) {
            str_starts_with($path, 'contact') => 'contacts',
            str_starts_with($path, 'compan') => 'companies',
            str_starts_with($path, 'deal') => 'deals',
            str_starts_with($path, 'campaign') => 'campaigns',
            str_starts_with($path, 'form') => 'forms',
            str_starts_with($path, 'task') => 'tasks',
            str_starts_with($path, 'email_template') => 'email_templates',
            default => str_starts_with($path, 'marketing') ? 'marketing' : 'crm',
        };
    }

    private function marketingActionRouterTargetRecord(string $href, array $ids): array
    {
        $system = $this->marketingActionRouterTargetSystem($href);
        return match ($system) {
            'contacts' => ['type' => 'contact', 'id' => (int) ($ids['contact_id'] ?? 0) ?: null],
            'companies' => ['type' => 'company', 'id' => (int) ($ids['company_id'] ?? 0) ?: null],
            'deals' => ['type' => 'deal', 'id' => (int) ($ids['deal_id'] ?? 0) ?: null],
            'campaigns' => ['type' => 'campaign', 'id' => (int) ($ids['campaign_id'] ?? 0) ?: null],
            'forms' => ['type' => 'form', 'id' => (int) ($ids['form_id'] ?? 0) ?: null],
            'tasks' => ['type' => 'task', 'id' => (int) ($ids['task_id'] ?? 0) ?: null],
            'email_templates' => ['type' => 'email_template', 'id' => (int) ($ids['email_template_id'] ?? 0) ?: null],
            default => ['type' => !empty($ids['content_item_id']) ? 'content_item' : null, 'id' => !empty($ids['content_item_id']) ? (int) $ids['content_item_id'] : null],
        };
    }

    private function marketingActionRouterType(string $href, string $key): string
    {
        $value = strtolower($href . ' ' . $key);
        return match (true) {
            str_contains($value, 'segment') || str_contains($value, 'audience') => 'audience',
            str_contains($value, 'campaign') => 'campaign',
            str_contains($value, 'content') => 'content',
            str_contains($value, 'landing') => 'landing_page',
            str_contains($value, 'utm') || str_contains($value, 'attribution') || str_contains($value, 'performance') => 'tracking',
            str_contains($value, 'handoff') => 'handoff',
            str_contains($value, 'task') => 'task',
            str_contains($value, 'form') => 'form',
            str_contains($value, 'email_template') => 'email_template',
            str_contains($value, 'deal') => 'deal',
            str_contains($value, 'contact') => 'contact',
            str_contains($value, 'compan') => 'company',
            str_contains($value, 'decision') => 'decision',
            str_contains($value, 'connect') || str_contains($value, 'setup') => 'crm_setup',
            default => 'custom',
        };
    }

    private function assertMarketingActionRouterLinks(array $item): void
    {
        $workspaceId = $this->workspaceId();
        foreach ([
            'contact_id' => 'contacts',
            'company_id' => 'companies',
            'deal_id' => 'deals',
            'campaign_id' => 'campaigns',
            'form_id' => 'forms',
            'task_id' => 'tasks',
            'content_item_id' => 'marketing_content_items',
        ] as $field => $table) {
            $id = (int) ($item[$field] ?? 0);
            if ($id > 0) {
                $this->assertWorkspaceRecord($table, $id, $workspaceId);
            }
        }
        $emailTemplateId = (int) ($item['email_template_id'] ?? 0);
        if ($emailTemplateId > 0) {
            $this->assertEmailTemplateAvailable($emailTemplateId, $workspaceId);
        }
    }

    private function hydrateMarketingActionRouterRow(array $row): array
    {
        $row = $this->hydrateJsonFields($row, ['metadata_json']);
        $row['manual_first_boundary'] = [
            'external_publish' => false,
            'external_send' => false,
            'external_api_call' => false,
            'operator_confirmation_required' => true,
        ];

        return $row;
    }

    private function hydrateMarketingRelationshipRow(array $row): array
    {
        $row = $this->hydrateJsonFields($row, ['evidence_json', 'metadata_json']);
        foreach (['id', 'workspace_id', 'source_id', 'target_id', 'created_by'] as $field) {
            $row[$field] = isset($row[$field]) && $row[$field] !== null ? (int) $row[$field] : null;
        }

        return $row;
    }

    private function buildMarketingRelationshipGraphEdges(): array
    {
        $workspaceId = $this->workspaceId();
        $edges = [];
        $add = function (
            string $sourceType,
            int $sourceId,
            string $sourceTitle,
            string $targetType,
            int $targetId,
            string $targetTitle,
            string $relationshipType,
            string $label,
            array $evidence = []
        ) use (&$edges): void {
            if ($sourceId <= 0 || $targetId <= 0) {
                return;
            }
            $edges[] = [
                'source_type' => $sourceType,
                'source_id' => $sourceId,
                'source_title' => $sourceTitle,
                'target_type' => $targetType,
                'target_id' => $targetId,
                'target_title' => $targetTitle,
                'relationship_type' => $relationshipType,
                'relationship_status' => 'active',
                'label' => $label,
                'evidence_json' => $evidence,
                'metadata_json' => ['source' => 'marketing_relationship_graph_auto', 'manual_first' => true],
            ];
        };

        if (Database::tableExists('marketing_content_items') && Database::tableExists('campaigns') && Database::columnExists('marketing_content_items', 'campaign_id')) {
            foreach (Database::query(
                "SELECT ci.id AS source_id, ci.title AS source_title, c.id AS target_id, c.name AS target_title
                 FROM marketing_content_items ci
                 JOIN campaigns c ON c.id = ci.campaign_id AND c.workspace_id = ci.workspace_id
                 WHERE ci.workspace_id = ? AND ci.campaign_id IS NOT NULL",
                [$workspaceId]
            ) as $row) {
                $add('content_item', (int) $row['source_id'], (string) $row['source_title'], 'campaign', (int) $row['target_id'], (string) $row['target_title'], 'supports', 'Content supports campaign', ['field' => 'marketing_content_items.campaign_id']);
            }
        }

        if (Database::tableExists('marketing_content_items') && Database::tableExists('marketing_campaign_briefs') && Database::columnExists('marketing_content_items', 'campaign_brief_id')) {
            foreach (Database::query(
                "SELECT ci.id AS source_id, ci.title AS source_title, b.id AS target_id, b.title AS target_title
                 FROM marketing_content_items ci
                 JOIN marketing_campaign_briefs b ON b.id = ci.campaign_brief_id AND b.workspace_id = ci.workspace_id
                 WHERE ci.workspace_id = ? AND ci.campaign_brief_id IS NOT NULL",
                [$workspaceId]
            ) as $row) {
                $add('content_item', (int) $row['source_id'], (string) $row['source_title'], 'campaign_brief', (int) $row['target_id'], (string) $row['target_title'], 'depends_on', 'Content depends on brief', ['field' => 'marketing_content_items.campaign_brief_id']);
            }
        }

        if (Database::tableExists('marketing_campaign_briefs') && Database::tableExists('campaigns') && Database::columnExists('marketing_campaign_briefs', 'campaign_id')) {
            foreach (Database::query(
                "SELECT b.id AS source_id, b.title AS source_title, c.id AS target_id, c.name AS target_title
                 FROM marketing_campaign_briefs b
                 JOIN campaigns c ON c.id = b.campaign_id AND c.workspace_id = b.workspace_id
                 WHERE b.workspace_id = ? AND b.campaign_id IS NOT NULL",
                [$workspaceId]
            ) as $row) {
                $add('campaign_brief', (int) $row['source_id'], (string) $row['source_title'], 'campaign', (int) $row['target_id'], (string) $row['target_title'], 'supports', 'Brief supports campaign', ['field' => 'marketing_campaign_briefs.campaign_id']);
            }
        }

        if (Database::tableExists('marketing_campaign_briefs') && Database::tableExists('marketing_personas') && Database::columnExists('marketing_campaign_briefs', 'persona_id')) {
            foreach (Database::query(
                "SELECT b.id AS source_id, b.title AS source_title, p.id AS target_id, p.name AS target_title
                 FROM marketing_campaign_briefs b
                 JOIN marketing_personas p ON p.id = b.persona_id AND p.workspace_id = b.workspace_id
                 WHERE b.workspace_id = ? AND b.persona_id IS NOT NULL",
                [$workspaceId]
            ) as $row) {
                $add('campaign_brief', (int) $row['source_id'], (string) $row['source_title'], 'persona', (int) $row['target_id'], (string) $row['target_title'], 'targets', 'Brief targets persona', ['field' => 'marketing_campaign_briefs.persona_id']);
            }
        }

        if (Database::tableExists('marketing_campaign_briefs') && Database::tableExists('marketing_context_items') && Database::columnExists('marketing_campaign_briefs', 'offer_context_item_id')) {
            foreach (Database::query(
                "SELECT b.id AS source_id, b.title AS source_title, ci.id AS target_id, ci.title AS target_title
                 FROM marketing_campaign_briefs b
                 JOIN marketing_context_items ci ON ci.id = b.offer_context_item_id AND ci.workspace_id = b.workspace_id
                 WHERE b.workspace_id = ? AND b.offer_context_item_id IS NOT NULL",
                [$workspaceId]
            ) as $row) {
                $add('campaign_brief', (int) $row['source_id'], (string) $row['source_title'], 'context_item', (int) $row['target_id'], (string) $row['target_title'], 'uses', 'Brief uses offer context', ['field' => 'marketing_campaign_briefs.offer_context_item_id']);
            }
        }

        if (Database::tableExists('marketing_landing_pages') && Database::tableExists('campaigns') && Database::columnExists('marketing_landing_pages', 'campaign_id')) {
            foreach (Database::query(
                "SELECT lp.id AS source_id, lp.title AS source_title, c.id AS target_id, c.name AS target_title
                 FROM marketing_landing_pages lp
                 JOIN campaigns c ON c.id = lp.campaign_id AND c.workspace_id = lp.workspace_id
                 WHERE lp.workspace_id = ? AND lp.campaign_id IS NOT NULL",
                [$workspaceId]
            ) as $row) {
                $add('landing_page', (int) $row['source_id'], (string) $row['source_title'], 'campaign', (int) $row['target_id'], (string) $row['target_title'], 'converts_to', 'Landing page converts campaign traffic', ['field' => 'marketing_landing_pages.campaign_id']);
            }
        }

        if (Database::tableExists('marketing_landing_pages') && Database::tableExists('forms') && Database::columnExists('marketing_landing_pages', 'form_id')) {
            foreach (Database::query(
                "SELECT lp.id AS source_id, lp.title AS source_title, f.id AS target_id, f.name AS target_title
                 FROM marketing_landing_pages lp
                 JOIN forms f ON f.id = lp.form_id AND f.workspace_id = lp.workspace_id
                 WHERE lp.workspace_id = ? AND lp.form_id IS NOT NULL",
                [$workspaceId]
            ) as $row) {
                $add('landing_page', (int) $row['source_id'], (string) $row['source_title'], 'form', (int) $row['target_id'], (string) $row['target_title'], 'uses', 'Landing page uses form', ['field' => 'marketing_landing_pages.form_id']);
            }
        }

        if (Database::tableExists('marketing_distribution_posts') && Database::tableExists('marketing_content_items') && Database::columnExists('marketing_distribution_posts', 'content_item_id')) {
            foreach (Database::query(
                "SELECT dp.id AS source_id, CONCAT('Distribution: ', dp.channel) AS source_title, ci.id AS target_id, ci.title AS target_title
                 FROM marketing_distribution_posts dp
                 JOIN marketing_content_items ci ON ci.id = dp.content_item_id AND ci.workspace_id = dp.workspace_id
                 WHERE dp.workspace_id = ? AND dp.content_item_id IS NOT NULL",
                [$workspaceId]
            ) as $row) {
                $add('distribution_post', (int) $row['source_id'], (string) $row['source_title'], 'content_item', (int) $row['target_id'], (string) $row['target_title'], 'distributed_as', 'Distribution variant uses content', ['field' => 'marketing_distribution_posts.content_item_id']);
            }
        }

        if (Database::tableExists('marketing_content_media') && Database::tableExists('marketing_media_files')) {
            foreach (Database::query(
                "SELECT cm.id, ci.id AS source_id, ci.title AS source_title, mf.id AS target_id, mf.title AS target_title, cm.role
                 FROM marketing_content_media cm
                 JOIN marketing_content_items ci ON ci.id = cm.content_item_id AND ci.workspace_id = cm.workspace_id
                 JOIN marketing_media_files mf ON mf.id = cm.media_file_id AND mf.workspace_id = cm.workspace_id
                 WHERE cm.workspace_id = ?",
                [$workspaceId]
            ) as $row) {
                $add('content_item', (int) $row['source_id'], (string) $row['source_title'], 'media_file', (int) $row['target_id'], (string) $row['target_title'], 'uses', 'Content uses media', ['media_role' => (string) ($row['role'] ?? '')]);
            }
        }

        if (Database::tableExists('marketing_utm_links') && Database::tableExists('campaigns') && Database::columnExists('marketing_utm_links', 'campaign_id')) {
            foreach (Database::query(
                "SELECT u.id AS source_id, u.url AS source_title, c.id AS target_id, c.name AS target_title
                 FROM marketing_utm_links u
                 JOIN campaigns c ON c.id = u.campaign_id AND c.workspace_id = u.workspace_id
                 WHERE u.workspace_id = ? AND u.campaign_id IS NOT NULL",
                [$workspaceId]
            ) as $row) {
                $add('utm_link', (int) $row['source_id'], (string) $row['source_title'], 'campaign', (int) $row['target_id'], (string) $row['target_title'], 'tracks', 'UTM tracks campaign', ['field' => 'marketing_utm_links.campaign_id']);
            }
        }

        if (Database::tableExists('marketing_utm_links') && Database::tableExists('marketing_content_items') && Database::columnExists('marketing_utm_links', 'content_item_id')) {
            foreach (Database::query(
                "SELECT u.id AS source_id, u.url AS source_title, ci.id AS target_id, ci.title AS target_title
                 FROM marketing_utm_links u
                 JOIN marketing_content_items ci ON ci.id = u.content_item_id AND ci.workspace_id = u.workspace_id
                 WHERE u.workspace_id = ? AND u.content_item_id IS NOT NULL",
                [$workspaceId]
            ) as $row) {
                $add('utm_link', (int) $row['source_id'], (string) $row['source_title'], 'content_item', (int) $row['target_id'], (string) $row['target_title'], 'tracks', 'UTM tracks content', ['field' => 'marketing_utm_links.content_item_id']);
            }
        }

        if (Database::tableExists('marketing_email_campaign_runs') && Database::tableExists('marketing_audience_segments') && Database::columnExists('marketing_email_campaign_runs', 'audience_segment_id')) {
            foreach (Database::query(
                "SELECT er.id AS source_id, er.name AS source_title, seg.id AS target_id, seg.name AS target_title
                 FROM marketing_email_campaign_runs er
                 JOIN marketing_audience_segments seg ON seg.id = er.audience_segment_id AND seg.workspace_id = er.workspace_id
                 WHERE er.workspace_id = ? AND er.audience_segment_id IS NOT NULL",
                [$workspaceId]
            ) as $row) {
                $add('email_run', (int) $row['source_id'], (string) $row['source_title'], 'audience_segment', (int) $row['target_id'], (string) $row['target_title'], 'targets', 'Email run targets audience segment', ['field' => 'marketing_email_campaign_runs.audience_segment_id']);
            }
        }

        return $edges;
    }

    private function normalizeMarketingRelationshipData(array $data): array
    {
        $workspaceId = $this->workspaceId();
        $sourceType = $this->normalizeEnum((string) ($data['source_type'] ?? ''), self::RELATIONSHIP_RECORD_TYPES, 'source_type');
        $targetType = $this->normalizeEnum((string) ($data['target_type'] ?? ''), self::RELATIONSHIP_RECORD_TYPES, 'target_type');
        $sourceId = (int) ($data['source_id'] ?? 0);
        $targetId = (int) ($data['target_id'] ?? 0);
        $this->assertMarketingRelationshipRecord($sourceType, $sourceId, $workspaceId);
        $this->assertMarketingRelationshipRecord($targetType, $targetId, $workspaceId);
        $relationshipType = $this->normalizeEnum((string) ($data['relationship_type'] ?? 'references'), self::RELATIONSHIP_TYPES, 'relationship_type');
        $status = $this->normalizeEnum((string) ($data['relationship_status'] ?? 'active'), self::RELATIONSHIP_STATUSES, 'relationship_status');
        $label = Security::sanitizeInput((string) ($data['label'] ?? 'Marketing relationship'), 'string');

        return [
            'source_type' => $sourceType,
            'source_id' => $sourceId,
            'source_title' => Security::sanitizeInput((string) ($data['source_title'] ?? $this->marketingRelationshipRecordTitle($sourceType, $sourceId)), 'string'),
            'target_type' => $targetType,
            'target_id' => $targetId,
            'target_title' => Security::sanitizeInput((string) ($data['target_title'] ?? $this->marketingRelationshipRecordTitle($targetType, $targetId)), 'string'),
            'relationship_type' => $relationshipType,
            'relationship_status' => $status,
            'label' => $label !== '' ? $label : 'Marketing relationship',
            'evidence_json' => $this->sanitizeJsonCompatible($data['evidence'] ?? $data['evidence_json'] ?? []),
            'metadata_json' => $this->sanitizeJsonCompatible($data['metadata'] ?? $data['metadata_json'] ?? []),
        ];
    }

    private function upsertMarketingRelationshipGraphEdge(array $edge, ?int $userId = null): void
    {
        $edge = $this->normalizeMarketingRelationshipData($edge);
        Database::execute(
            "INSERT INTO marketing_relationship_graph_edges
             (workspace_id, uuid, source_type, source_id, target_type, target_id, relationship_type, relationship_status,
              label, source_title, target_title, evidence_json, metadata_json, created_by)
             VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
             ON DUPLICATE KEY UPDATE
                id = LAST_INSERT_ID(id),
                relationship_status = VALUES(relationship_status),
                label = VALUES(label),
                source_title = VALUES(source_title),
                target_title = VALUES(target_title),
                evidence_json = VALUES(evidence_json),
                metadata_json = VALUES(metadata_json),
                updated_at = NOW()",
            [
                $this->workspaceId(),
                $this->generateUuid(),
                $edge['source_type'],
                $edge['source_id'],
                $edge['target_type'],
                $edge['target_id'],
                $edge['relationship_type'],
                $edge['relationship_status'],
                $edge['label'],
                $edge['source_title'],
                $edge['target_title'],
                $this->normalizeJsonValue($edge['evidence_json']),
                $this->normalizeJsonValue($edge['metadata_json']),
                ($userId ?? 0) > 0 ? (int) $userId : null,
            ]
        );
    }

    private function marketingRelationshipRecordTable(string $recordType): string
    {
        return [
            'campaign' => 'campaigns',
            'campaign_brief' => 'marketing_campaign_briefs',
            'content_item' => 'marketing_content_items',
            'landing_page' => 'marketing_landing_pages',
            'media_file' => 'marketing_media_files',
            'persona' => 'marketing_personas',
            'context_item' => 'marketing_context_items',
            'audience_segment' => 'marketing_audience_segments',
            'journey' => 'marketing_journeys',
            'distribution_post' => 'marketing_distribution_posts',
            'utm_link' => 'marketing_utm_links',
            'email_run' => 'marketing_email_campaign_runs',
            'channel_export' => 'marketing_channel_export_bundles',
            'asset' => 'marketing_assets',
            'form' => 'forms',
            'task' => 'tasks',
        ][$recordType] ?? '';
    }

    private function marketingRelationshipRecordTitleColumn(string $recordType): string
    {
        return [
            'campaign' => 'name',
            'campaign_brief' => 'title',
            'content_item' => 'title',
            'landing_page' => 'title',
            'media_file' => 'title',
            'persona' => 'name',
            'context_item' => 'title',
            'audience_segment' => 'name',
            'journey' => 'name',
            'distribution_post' => 'channel',
            'utm_link' => 'url',
            'email_run' => 'name',
            'channel_export' => 'name',
            'asset' => 'title',
            'form' => 'name',
            'task' => 'title',
        ][$recordType] ?? 'id';
    }

    private function assertMarketingRelationshipRecord(string $recordType, int $recordId, int $workspaceId): void
    {
        $table = $this->marketingRelationshipRecordTable($recordType);
        if ($table === '' || $recordId <= 0) {
            throw new RuntimeException('Marketing relationship record type is unsupported.');
        }
        $this->assertWorkspaceRecord($table, $recordId, $workspaceId);
    }

    private function marketingRelationshipRecordTitle(string $recordType, int $recordId): string
    {
        $table = $this->marketingRelationshipRecordTable($recordType);
        if ($table === '' || !Database::tableExists($table)) {
            return $recordType . ' #' . $recordId;
        }
        $column = $this->marketingRelationshipRecordTitleColumn($recordType);
        if (!Database::columnExists($table, $column)) {
            return $recordType . ' #' . $recordId;
        }
        $row = Database::queryOne(
            "SELECT {$column} AS title FROM {$table} WHERE workspace_id = ? AND id = ? LIMIT 1",
            [$this->workspaceId(), $recordId]
        );

        return trim((string) ($row['title'] ?? '')) !== '' ? (string) $row['title'] : $recordType . ' #' . $recordId;
    }

    private function detectMarketingRelationshipOrphans(): array
    {
        $workspaceId = $this->workspaceId();
        $orphans = [];
        if (Database::tableExists('marketing_content_items')) {
            $campaignColumn = Database::columnExists('marketing_content_items', 'campaign_id') ? 'campaign_id' : 'NULL';
            $briefColumn = Database::columnExists('marketing_content_items', 'campaign_brief_id') ? 'campaign_brief_id' : 'NULL';
            foreach (Database::query(
                "SELECT id, title
                 FROM marketing_content_items
                 WHERE workspace_id = ?
                   AND status <> 'archived'
                   AND ({$campaignColumn} IS NULL OR {$campaignColumn} = 0)
                   AND ({$briefColumn} IS NULL OR {$briefColumn} = 0)
                 ORDER BY updated_at DESC
                 LIMIT 10",
                [$workspaceId]
            ) as $row) {
                $orphans[] = ['record_type' => 'content_item', 'record_id' => (int) $row['id'], 'title' => (string) $row['title'], 'label' => 'Content has no linked campaign or brief.'];
            }
        }
        if (Database::tableExists('marketing_landing_pages') && Database::columnExists('marketing_landing_pages', 'campaign_id')) {
            foreach (Database::query(
                "SELECT id, title
                 FROM marketing_landing_pages
                 WHERE workspace_id = ? AND status <> 'archived' AND (campaign_id IS NULL OR campaign_id = 0)
                 ORDER BY updated_at DESC
                 LIMIT 10",
                [$workspaceId]
            ) as $row) {
                $orphans[] = ['record_type' => 'landing_page', 'record_id' => (int) $row['id'], 'title' => (string) $row['title'], 'label' => 'Landing page has no linked campaign.'];
            }
        }
        if (Database::tableExists('marketing_media_files') && Database::tableExists('marketing_content_media')) {
            foreach (Database::query(
                "SELECT mf.id, mf.title
                 FROM marketing_media_files mf
                 LEFT JOIN marketing_content_media cm ON cm.media_file_id = mf.id AND cm.workspace_id = mf.workspace_id
                 WHERE mf.workspace_id = ? AND COALESCE(mf.approval_status, '') <> 'archived' AND cm.id IS NULL
                 ORDER BY mf.updated_at DESC
                 LIMIT 10",
                [$workspaceId]
            ) as $row) {
                $orphans[] = ['record_type' => 'media_file', 'record_id' => (int) $row['id'], 'title' => (string) $row['title'], 'label' => 'Media is not attached to content yet.'];
            }
        }

        return $orphans;
    }

    private function marketingSystemConnectionReadiness(): array
    {
        $campaignCount = $this->marketingWorkspaceRecordCount('campaigns', "status <> 'archived'");
        $activeCampaignCount = $this->marketingWorkspaceRecordCount('campaigns', "status = 'active'");
        $formCount = $this->marketingWorkspaceRecordCount('forms');
        $formSubmissionCount = $this->audienceWorkspaceFormSubmissionCount();
        $contactCount = $this->marketingWorkspaceRecordCount('contacts');
        $companyCount = $this->marketingWorkspaceRecordCount('companies');
        $dealCount = $this->marketingWorkspaceRecordCount('deals', "stage NOT IN ('closed_lost')");
        $openTaskCount = $this->marketingWorkspaceRecordCount('tasks', "COALESCE(status, '') NOT IN ('completed', 'cancelled')");
        $emailTemplateCount = $this->marketingEmailTemplateIntegrationCount();
        $utmCount = $this->marketingWorkspaceRecordCount('marketing_utm_links');
        $trackingEventCount = $this->marketingWorkspaceRecordCount('marketing_tracking_events');
        $attributionTouchpointCount = $this->marketingWorkspaceRecordCount('marketing_attribution_touchpoints');
        $conversionEventCount = $this->marketingWorkspaceRecordCount('marketing_conversion_events');
        $handoffRuleCount = $this->marketingWorkspaceRecordCount('marketing_handoff_rules', "status = 'active'");
        $leadHandoffCount = $this->marketingWorkspaceRecordCount('marketing_lead_handoffs', "status NOT IN ('converted', 'lost', 'archived')");
        $mediaCount = $this->marketingWorkspaceRecordCount('marketing_media_files', "COALESCE(approval_status, '') <> 'archived'");
        $assetCount = $this->marketingWorkspaceRecordCount('marketing_assets');

        $add = static function (
            array &$connections,
            string $key,
            string $label,
            bool $available,
            bool $ready,
            int $count,
            string $detail,
            string $href,
            string $action,
            array $metadata = []
        ): void {
            $connections[$key] = [
                'key' => $key,
                'label' => $label,
                'status' => !$available ? 'missing' : ($ready ? 'ready' : 'attention'),
                'ready' => $available && $ready,
                'available' => $available,
                'count' => $count,
                'detail' => $detail,
                'href' => $href,
                'action' => $action,
                'metadata' => $metadata,
            ];
        };

        $connections = [];
        $add(
            $connections,
            'crm_campaigns',
            'CRM Campaigns',
            Database::tableExists('campaigns') && Database::columnExists('campaigns', 'workspace_id'),
            $campaignCount > 0,
            $campaignCount,
            $activeCampaignCount . ' active campaign(s) connected to this workspace.',
            'campaigns.php',
            'Create or link a CRM campaign before planning campaign execution.',
            ['active' => $activeCampaignCount]
        );
        $add(
            $connections,
            'forms_and_submissions',
            'Forms and Submissions',
            Database::tableExists('forms') && Database::columnExists('forms', 'workspace_id'),
            $formCount > 0,
            $formCount,
            $formSubmissionCount . ' form submission(s) available for conversion signals.',
            'forms.php',
            'Create a form and connect landing pages or campaigns to it.',
            ['submissions' => $formSubmissionCount]
        );
        $add(
            $connections,
            'contacts_and_companies',
            'Contacts and Companies',
            Database::tableExists('contacts') && Database::columnExists('contacts', 'workspace_id'),
            $contactCount > 0,
            $contactCount,
            $companyCount . ' company record(s) available for account context.',
            'contacts.php',
            'Import or capture contacts so Marketing can build real audiences.',
            ['companies' => $companyCount]
        );
        $add(
            $connections,
            'deals_pipeline',
            'Deals Pipeline',
            Database::tableExists('deals') && Database::columnExists('deals', 'workspace_id'),
            $dealCount > 0,
            $dealCount,
            'Pipeline records are used for ROI and attribution checks.',
            'deals.php',
            'Connect campaign outcomes to deals so performance is tied to revenue.'
        );
        $add(
            $connections,
            'tasks_and_handoffs',
            'Tasks and Handoffs',
            Database::tableExists('tasks') && Database::columnExists('tasks', 'workspace_id'),
            $openTaskCount > 0 || $handoffRuleCount > 0 || $leadHandoffCount > 0,
            $openTaskCount + $handoffRuleCount + $leadHandoffCount,
            $openTaskCount . ' open task(s), ' . $handoffRuleCount . ' active handoff rule(s), ' . $leadHandoffCount . ' open handoff(s).',
            'marketing_lead_handoffs.php',
            'Set up lead handoff rules or follow-up tasks for campaign responses.',
            ['open_tasks' => $openTaskCount, 'handoff_rules' => $handoffRuleCount, 'lead_handoffs' => $leadHandoffCount]
        );
        $add(
            $connections,
            'email_templates',
            'Email Templates',
            Database::tableExists('email_templates'),
            $emailTemplateCount > 0,
            $emailTemplateCount,
            'Reusable templates power manual email runs and sequence planning.',
            'email_templates.php',
            'Create or activate email templates before exporting email campaign runs.'
        );
        $add(
            $connections,
            'utm_and_tracking',
            'UTM and Tracking',
            Database::tableExists('marketing_utm_links') || Database::tableExists('marketing_tracking_events'),
            $utmCount > 0 || $trackingEventCount > 0,
            $utmCount + $trackingEventCount,
            $utmCount . ' UTM link(s), ' . $trackingEventCount . ' tracking event(s).',
            'marketing_utm_links.php',
            'Create UTM links and verify tracking events before judging performance.',
            ['utm_links' => $utmCount, 'tracking_events' => $trackingEventCount]
        );
        $add(
            $connections,
            'attribution_and_conversion',
            'Attribution and Conversion',
            Database::tableExists('marketing_attribution_touchpoints') || Database::tableExists('marketing_conversion_events'),
            $attributionTouchpointCount > 0 || $conversionEventCount > 0,
            $attributionTouchpointCount + $conversionEventCount,
            $attributionTouchpointCount . ' attribution touchpoint(s), ' . $conversionEventCount . ' conversion event(s).',
            'marketing_performance.php',
            'Capture conversion or attribution signals so Marketing can prove influence.',
            ['touchpoints' => $attributionTouchpointCount, 'conversion_events' => $conversionEventCount]
        );
        $add(
            $connections,
            'media_and_assets',
            'Media and Assets',
            Database::tableExists('marketing_media_files') || Database::tableExists('marketing_assets'),
            $mediaCount > 0 || $assetCount > 0,
            $mediaCount + $assetCount,
            $mediaCount . ' media file(s), ' . $assetCount . ' asset record(s).',
            'marketing_assets.php',
            'Add approved media and assets before building channel-ready campaigns.',
            ['media_files' => $mediaCount, 'assets' => $assetCount]
        );

        return $connections;
    }

    private function audienceWorkspaceBreakdown(string $table, string $field, int $limit = 8): array
    {
        if (!Database::tableExists($table) || !Database::columnExists($table, $field) || !Database::columnExists($table, 'workspace_id')) {
            return [];
        }
        $limit = min(max($limit, 1), 25);

        return array_map(
            static fn(array $row): array => [
                'label' => (string) ($row['label'] ?? 'Unknown'),
                'count' => (int) ($row['count'] ?? 0),
            ],
            Database::query(
                "SELECT COALESCE(NULLIF({$field}, ''), 'Unknown') AS label, COUNT(*) AS count
                 FROM {$table}
                 WHERE workspace_id = ?
                 GROUP BY COALESCE(NULLIF({$field}, ''), 'Unknown')
                 ORDER BY count DESC, label ASC
                 LIMIT {$limit}",
                [$this->workspaceId()]
            )
        );
    }

    private function audienceWorkspaceFreshness(string $table): array
    {
        if (!Database::tableExists($table)) {
            return ['available' => false, 'latest_at' => null, 'age_days' => null, 'status' => 'missing'];
        }

        $dateColumn = null;
        foreach (['updated_at', 'created_at', 'submitted_at', 'activity_date'] as $candidate) {
            if (Database::columnExists($table, $candidate)) {
                $dateColumn = $candidate;
                break;
            }
        }
        if ($dateColumn === null) {
            return ['available' => true, 'latest_at' => null, 'age_days' => null, 'status' => 'unknown'];
        }

        $where = Database::columnExists($table, 'workspace_id') ? 'workspace_id = ?' : '1=1';
        $params = Database::columnExists($table, 'workspace_id') ? [$this->workspaceId()] : [];
        if (!Database::columnExists($table, 'workspace_id') && Database::columnExists($table, 'contact_id') && Database::tableExists('contacts')) {
            $where = "contact_id IN (SELECT id FROM contacts WHERE workspace_id = ?)";
            $params = [$this->workspaceId()];
        } elseif (!Database::columnExists($table, 'workspace_id')) {
            return ['available' => true, 'latest_at' => null, 'age_days' => null, 'status' => 'unscoped'];
        }
        $row = Database::queryOne("SELECT MAX({$dateColumn}) AS latest_at FROM {$table} WHERE {$where}", $params);
        $latest = trim((string) ($row['latest_at'] ?? ''));
        if ($latest === '' || strtotime($latest) === false) {
            return ['available' => true, 'latest_at' => null, 'age_days' => null, 'status' => 'empty'];
        }

        $ageDays = max(0, (int) floor((time() - strtotime($latest)) / 86400));
        return [
            'available' => true,
            'latest_at' => $latest,
            'age_days' => $ageDays,
            'status' => $ageDays <= 14 ? 'fresh' : ($ageDays <= 45 ? 'aging' : 'stale'),
        ];
    }

    private function audienceWorkspaceFormSubmissionCount(): int
    {
        if (!Database::tableExists('form_submissions')) {
            return 0;
        }
        if (Database::columnExists('form_submissions', 'workspace_id')) {
            return $this->countRows('form_submissions', '1=1');
        }
        if (Database::columnExists('form_submissions', 'contact_id') && Database::tableExists('contacts')) {
            $row = Database::queryOne(
                "SELECT COUNT(*) AS count
                 FROM form_submissions
                 WHERE contact_id IN (SELECT id FROM contacts WHERE workspace_id = ?)",
                [$this->workspaceId()]
            );
            return (int) ($row['count'] ?? 0);
        }

        return 0;
    }

    private function mediaUsageCount(int $mediaFileId, int $workspaceId): int
    {
        $count = 0;
        foreach ([
            ['marketing_assets', 'media_file_id'],
            ['marketing_content_media', 'media_file_id'],
            ['marketing_channel_media_kits', 'primary_media_file_id'],
        ] as [$table, $field]) {
            if (!Database::tableExists($table) || !Database::columnExists($table, $field)) {
                continue;
            }
            $row = Database::queryOne("SELECT COUNT(*) AS count FROM {$table} WHERE workspace_id = ? AND {$field} = ?", [$workspaceId, $mediaFileId]);
            $count += (int) ($row['count'] ?? 0);
        }
        if (Database::tableExists('marketing_landing_pages')) {
            $row = Database::queryOne(
                "SELECT COUNT(*) AS count
                 FROM marketing_landing_pages
                 WHERE workspace_id = ?
                   AND (
                        hero_media_file_id = ?
                        OR social_preview_media_file_id = ?
                        OR cta_media_file_id = ?
                        OR proof_media_file_id = ?
                        OR testimonial_media_file_id = ?
                   )",
                [$workspaceId, $mediaFileId, $mediaFileId, $mediaFileId, $mediaFileId, $mediaFileId]
            );
            $count += (int) ($row['count'] ?? 0);
        }

        return $count;
    }

    private function recordMediaAuditEvent(string $eventType, ?int $mediaFileId, string $message, array $metadata = [], ?int $userId = null, ?string $contextType = null, ?int $contextId = null): void
    {
        if (!Database::tableExists('marketing_media_audit_events')) {
            return;
        }

        Database::execute(
            "INSERT INTO marketing_media_audit_events
             (workspace_id, media_file_id, uuid, event_type, context_type, context_id, message, metadata_json, created_by)
             VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)",
            [
                $this->workspaceId(),
                $mediaFileId,
                $this->generateUuid(),
                $this->normalizeEnum($eventType, ['upload','edit','approve','reject','block','archive','attach','detach','export_use','cleanup_preview','cleanup_archive'], 'media_audit_event'),
                $contextType,
                $contextId,
                $message !== '' ? Security::sanitizeInput($message, 'string') : null,
                $this->normalizeJsonValue($this->sanitizeJsonCompatible($metadata)),
                $userId ?: null,
            ]
        );
    }

    private function dashboardSummaryCacheKey(): string
    {
        $userId = $this->currentUserId();
        $role = Security::sanitizeInput((string) ($_SESSION['active_workspace_role'] ?? 'unknown'), 'string') ?: 'unknown';

        return 'command_center:v2:user:' . max(0, $userId) . ':role:' . $role;
    }

    private function calculateCampaignReadiness(array $brief): array
    {
        $checks = [
            'objective' => $brief['objective'] ?? null,
            'audience' => $brief['audience'] ?? null,
            'persona' => $brief['persona_id'] ?? null,
            'offer' => $brief['offer_context_item_id'] ?? null,
            'content_pillar' => $brief['content_pillar_context_item_id'] ?? null,
            'success_metrics' => $brief['success_metrics'] ?? null,
            'channel_plan' => $brief['channel_plan_json'] ?? $brief['channel_plan'] ?? null,
            'launch_timeline' => $brief['launch_timeline_json'] ?? $brief['launch_timeline'] ?? null,
            'landing_page' => $brief['landing_page_id'] ?? null,
        ];
        $complete = 0;
        $missing = [];
        foreach ($checks as $key => $value) {
            $filled = is_array($value) ? $value !== [] : trim((string) ($value ?? '')) !== '' && (string) $value !== '0';
            if ($filled) {
                $complete++;
            } else {
                $missing[] = $key;
            }
        }

        return [
            'score' => (int) round(($complete / count($checks)) * 100),
            'missing' => $missing,
        ];
    }

    private function calculateContentReadiness(array $item): array
    {
        $checks = [
            'objective' => $item['objective'] ?? null,
            'audience' => $item['target_audience'] ?? null,
            'draft_body' => $item['draft_body'] ?? null,
            'channel' => $item['channel'] ?? null,
            'content_type' => $item['content_type'] ?? null,
            'campaign_or_brief' => ($item['campaign_id'] ?? null) ?: ($item['campaign_brief_id'] ?? null),
            'brand_or_context' => ($item['brand_profile_id'] ?? null) ?: ($item['persona_id'] ?? null) ?: ($item['seo_topic_id'] ?? null),
        ];
        $complete = 0;
        $warnings = [];
        foreach ($checks as $key => $value) {
            $filled = is_array($value) ? $value !== [] : trim((string) ($value ?? '')) !== '' && (string) $value !== '0';
            if ($filled) {
                $complete++;
            } else {
                $warnings[] = $key;
            }
        }

        if (!empty($item['blocked_reason'])) {
            $warnings[] = 'blocked_reason';
        }

        return [
            'score' => (int) round(($complete / count($checks)) * 100),
            'warnings' => array_values(array_unique($warnings)),
        ];
    }

    private function calculateContentProductionReadiness(array $item, array $dependencies = []): array
    {
        $checks = [
            'owner' => $item['owner_user_id'] ?? null,
            'due_date' => ($item['production_due_at'] ?? null) ?: ($item['scheduled_at'] ?? null),
            'draft_body' => $item['draft_body'] ?? null,
            'campaign_or_brief' => ($item['campaign_id'] ?? null) ?: ($item['campaign_brief_id'] ?? null),
            'checklist' => $item['production_checklist_json'] ?? $item['production_checklist'] ?? [],
            'dependencies_clear' => (string) ($item['dependency_status'] ?? 'clear') === 'clear' ? 'clear' : '',
            'not_blocked' => empty($item['blocked_reason']) ? 'clear' : '',
        ];

        if ($dependencies !== []) {
            $open = array_filter($dependencies, static fn(array $row): bool => !in_array((string) ($row['status'] ?? ''), ['ready', 'done'], true));
            $blocked = array_filter($dependencies, static fn(array $row): bool => (string) ($row['status'] ?? '') === 'blocked');
            $checks['dependencies_clear'] = $open === [] && $blocked === [] ? 'clear' : '';
        }

        $complete = 0;
        $missing = [];
        foreach ($checks as $key => $value) {
            $value = $key === 'checklist' ? $this->decodeJsonLike($value) : $value;
            $filled = is_array($value) ? $value !== [] : trim((string) ($value ?? '')) !== '' && (string) $value !== '0';
            if ($filled) {
                $complete++;
            } else {
                $missing[] = $key;
            }
        }

        $stage = (string) ($item['production_stage'] ?? 'idea');
        $stageAction = match ($stage) {
            'idea' => 'Create a brief and assign an owner.',
            'briefing' => 'Lock audience, offer, and campaign context.',
            'drafting' => 'Finish the working draft and attach required media.',
            'design' => 'Complete visual assets and media approvals.',
            'review' => 'Resolve review comments and approval decisions.',
            'approved' => 'Schedule distribution or connect this to a launch plan.',
            'scheduled' => 'Confirm distribution assets, UTM links, and publish checklist.',
            'blocked' => 'Resolve the blocker or dependency before moving forward.',
            'published' => 'Review performance and repurpose the content.',
            'archived' => 'No next action for archived content.',
            default => 'Update the production stage.',
        };
        $missingAction = [
            'owner' => 'Assign an owner.',
            'due_date' => 'Set a production due date.',
            'draft_body' => 'Add or generate the working draft.',
            'campaign_or_brief' => 'Link a campaign or campaign brief.',
            'checklist' => 'Add a production checklist.',
            'dependencies_clear' => 'Resolve open production dependencies.',
            'not_blocked' => 'Clear the blocked reason.',
        ];
        $nextAction = $missing !== []
            ? ($missingAction[$missing[0]] ?? $stageAction)
            : $stageAction;

        return [
            'score' => (int) round(($complete / count($checks)) * 100),
            'missing' => array_values(array_unique($missing)),
            'next_action' => $nextAction,
        ];
    }

    private function defaultProductionStageForStatus(string $status): string
    {
        return match ($status) {
            'draft' => 'drafting',
            'review' => 'review',
            'approved' => 'approved',
            'scheduled' => 'scheduled',
            'published' => 'published',
            'archived' => 'archived',
            default => 'idea',
        };
    }

    private function normalizeContentDependencyData(array $data, bool $forCreate): array
    {
        $workspaceId = $this->workspaceId();
        $normalized = [];
        if ($forCreate || array_key_exists('content_item_id', $data)) {
            $contentItemId = (int) ($data['content_item_id'] ?? 0);
            if ($contentItemId <= 0) {
                throw new \InvalidArgumentException('Content item is required for a dependency.');
            }
            $this->assertWorkspaceRecord('marketing_content_items', $contentItemId, $workspaceId);
            $normalized['content_item_id'] = $contentItemId;
        }
        if ($forCreate || array_key_exists('depends_on_content_item_id', $data)) {
            $dependsOnId = (int) ($data['depends_on_content_item_id'] ?? 0);
            if ($dependsOnId > 0) {
                $this->assertWorkspaceRecord('marketing_content_items', $dependsOnId, $workspaceId);
                if ($dependsOnId === (int) ($normalized['content_item_id'] ?? $data['content_item_id'] ?? 0)) {
                    throw new \InvalidArgumentException('A content item cannot depend on itself.');
                }
                $normalized['depends_on_content_item_id'] = $dependsOnId;
            } else {
                $normalized['depends_on_content_item_id'] = null;
            }
        }
        if ($forCreate || array_key_exists('dependency_type', $data)) {
            $normalized['dependency_type'] = $this->normalizeEnum((string) ($data['dependency_type'] ?? 'other'), self::CONTENT_DEPENDENCY_TYPES, 'dependency_type');
        }
        if ($forCreate || array_key_exists('title', $data)) {
            $title = Security::sanitizeInput((string) ($data['title'] ?? ''), 'string');
            if ($title === '') {
                throw new \InvalidArgumentException('Dependency title is required.');
            }
            $normalized['title'] = $title;
        }
        if ($forCreate || array_key_exists('status', $data)) {
            $normalized['status'] = $this->normalizeEnum((string) ($data['status'] ?? 'waiting'), self::CONTENT_DEPENDENCY_STATUSES, 'content_dependency_status');
        }
        if ($forCreate || array_key_exists('due_at', $data)) {
            $normalized['due_at'] = $this->normalizeDateTime((string) ($data['due_at'] ?? ''));
        }
        if ($forCreate || array_key_exists('owner_user_id', $data)) {
            $ownerId = (int) ($data['owner_user_id'] ?? 0);
            if ($ownerId > 0) {
                $this->assertWorkspaceUser($ownerId, $workspaceId);
                $normalized['owner_user_id'] = $ownerId;
            } else {
                $normalized['owner_user_id'] = null;
            }
        }
        if ($forCreate || array_key_exists('notes', $data)) {
            $normalized['notes'] = $this->nullableSanitizedText($data['notes'] ?? '');
        }
        if ($forCreate || array_key_exists('metadata_json', $data) || array_key_exists('metadata', $data)) {
            $normalized['metadata_json'] = $this->normalizeJsonValue($this->sanitizeFlexibleArray($data['metadata'] ?? $data['metadata_json'] ?? []));
        }
        if ($forCreate) {
            $createdBy = (int) ($data['created_by'] ?? $this->currentUserId());
            if ($createdBy > 0) {
                $this->assertWorkspaceUser($createdBy, $workspaceId);
                $normalized['created_by'] = $createdBy;
            } else {
                $normalized['created_by'] = null;
            }
        }

        return $normalized;
    }

    private function refreshContentProductionFromDependencies(int $contentItemId): void
    {
        if (!Database::tableExists('marketing_content_dependencies') || !Database::columnExists('marketing_content_items', 'dependency_status')) {
            return;
        }

        $item = $this->getContentItem($contentItemId);
        if (!$item) {
            return;
        }
        $dependencies = $this->listContentDependencies($contentItemId);
        $hasBlocked = false;
        $hasWaiting = false;
        foreach ($dependencies as $dependency) {
            $status = (string) ($dependency['status'] ?? '');
            $hasBlocked = $hasBlocked || $status === 'blocked';
            $hasWaiting = $hasWaiting || $status === 'waiting';
        }
        $dependencyStatus = $hasBlocked ? 'blocked' : ($hasWaiting ? 'waiting' : 'clear');
        $production = $this->calculateContentProductionReadiness($item + ['dependency_status' => $dependencyStatus], $dependencies);

        Database::execute(
            'UPDATE marketing_content_items
             SET dependency_status = ?, production_score = ?, next_action = ?
             WHERE workspace_id = ? AND id = ?',
            [$dependencyStatus, $production['score'], $production['next_action'], $this->workspaceId(), $contentItemId]
        );
    }

    private function recordContentProductionUpdateEvents(int $contentItemId, array $existing, array $normalized, ?int $actorUserId = null): void
    {
        if (!Database::tableExists('marketing_content_production_events')) {
            return;
        }

        $stageChanged = array_key_exists('production_stage', $normalized)
            && (string) ($existing['production_stage'] ?? '') !== (string) ($normalized['production_stage'] ?? '');
        if ($stageChanged) {
            $this->recordContentProductionEvent(
                $contentItemId,
                'stage_changed',
                'Production stage changed from ' . $this->labelForEventValue((string) ($existing['production_stage'] ?? '')) . ' to ' . $this->labelForEventValue((string) ($normalized['production_stage'] ?? '')) . '.',
                ['fields' => ['production_stage']],
                $actorUserId,
                (string) ($existing['production_stage'] ?? ''),
                (string) ($normalized['production_stage'] ?? '')
            );
        }

        $tracked = ['production_due_at', 'dependency_status', 'dependency_notes', 'production_checklist_json', 'blocked_reason'];
        $changed = [];
        foreach ($tracked as $field) {
            if (array_key_exists($field, $normalized) && $this->productionFieldChanged($existing[$field] ?? null, $normalized[$field] ?? null)) {
                $changed[] = $field;
            }
        }
        if ($changed !== []) {
            $eventType = in_array('production_checklist_json', $changed, true)
                ? 'checklist_updated'
                : ((in_array('blocked_reason', $changed, true) || in_array('dependency_status', $changed, true))
                    ? ((string) ($normalized['dependency_status'] ?? '') === 'blocked' || !empty($normalized['blocked_reason']) ? 'blocked' : 'unblocked')
                    : 'production_updated');
            $this->recordContentProductionEvent(
                $contentItemId,
                $eventType,
                'Content production details updated.',
                ['fields' => $changed],
                $actorUserId
            );
        }
    }

    private function productionFieldChanged(mixed $old, mixed $new): bool
    {
        if (is_array($old)) {
            $old = json_encode($old, JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE);
        }
        if (is_array($new)) {
            $new = json_encode($new, JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE);
        }

        return (string) ($old ?? '') !== (string) ($new ?? '');
    }

    private function recordContentProductionEvent(
        int $contentItemId,
        string $eventType,
        string $summary,
        array $metadata = [],
        ?int $actorUserId = null,
        ?string $fromStage = null,
        ?string $toStage = null
    ): void {
        if (!Database::tableExists('marketing_content_production_events')) {
            return;
        }

        Database::execute(
            "INSERT INTO marketing_content_production_events
             (workspace_id, uuid, content_item_id, event_type, from_stage, to_stage, summary, metadata_json, actor_user_id)
             VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)",
            [
                $this->workspaceId(),
                $this->generateUuid(),
                $contentItemId,
                $this->normalizeEnum($eventType, self::CONTENT_PRODUCTION_EVENT_TYPES, 'content_production_event_type'),
                $fromStage !== '' ? $fromStage : null,
                $toStage !== '' ? $toStage : null,
                Security::sanitizeInput($summary, 'string') ?: 'Content production updated.',
                $this->normalizeJsonValue($this->sanitizeFlexibleArray($metadata)),
                ($actorUserId ?? 0) > 0 ? $actorUserId : null,
            ]
        );
    }

    private function labelForEventValue(string $value): string
    {
        $value = trim($value);
        return $value === '' ? 'unset' : ucwords(str_replace('_', ' ', $value));
    }

    private function calculateLandingPagePublishingReadiness(array $page): array
    {
        $designDocument = is_array($page['design_document_json'] ?? null) ? $page['design_document_json'] : [];
        $hasVersionedDesign = (string) ($designDocument['schema'] ?? '') === LandingPageDesignService::SCHEMA_VERSION;
        if ($hasVersionedDesign) {
            $designValidation = (new LandingPageDesignService())->validateDocument($designDocument, $page);
            $requiredChecks = [
                'approved_status' => (string) ($page['status'] ?? '') === 'approved' ? 'approved' : '',
                'slug' => $page['slug'] ?? null,
                'design_document' => !empty($designValidation['valid']) ? LandingPageDesignService::SCHEMA_VERSION : '',
                'conversion_goal' => $page['conversion_goal'] ?? null,
            ];
        } else {
            $requiredChecks = [
                'approved_status' => (string) ($page['status'] ?? '') === 'approved' ? 'approved' : '',
                'slug' => $page['slug'] ?? null,
                'headline' => $page['headline'] ?? null,
                'body_sections' => $page['body_sections_json'] ?? [],
                'cta_blocks' => $page['cta_blocks_json'] ?? [],
                'conversion_goal' => $page['conversion_goal'] ?? null,
            ];
        }
        $recommendedChecks = [
            'hero_media' => $page['_media']['hero'] ?? null,
            'social_preview_media' => $page['_media']['social_preview'] ?? null,
        ];
        $complete = 0;
        $missing = [];
        $checkResults = [];

        foreach ($requiredChecks as $key => $value) {
            $filled = is_array($value) ? $value !== [] : trim((string) ($value ?? '')) !== '' && (string) $value !== '0';
            $checkResults[$key] = $filled;
            if ($filled) {
                $complete++;
            } else {
                $missing[] = $key;
            }
        }

        $mediaWarnings = [];
        foreach ($recommendedChecks as $key => $value) {
            $filled = is_array($value) ? $value !== [] : trim((string) ($value ?? '')) !== '' && (string) $value !== '0';
            $checkResults[$key] = $filled;
            if (!$filled) {
                $mediaWarnings[] = $key . '_recommended';
            }
        }
        foreach (['hero', 'social_preview', 'cta', 'proof', 'testimonial'] as $slot) {
            $media = $page['_media'][$slot] ?? null;
            if (!is_array($media)) {
                continue;
            }
            if ((string) ($media['media_type'] ?? '') === 'image' && trim((string) ($media['alt_text'] ?? '')) === '') {
                $mediaWarnings[] = $slot . '_alt_text';
            }
            if ((string) ($media['media_type'] ?? '') === 'video' && trim((string) ($media['transcript'] ?? $media['caption'] ?? '')) === '') {
                $mediaWarnings[] = $slot . '_caption_or_transcript';
            }
        }
        $builderWarnings = [];
        foreach ([
            'theme_settings' => $page['theme_settings_json'] ?? [],
            'form_blocks' => $page['form_blocks_json'] ?? [],
            'seo_controls' => $page['seo_controls_json'] ?? [],
            'social_preview_controls' => $page['social_preview_json'] ?? [],
            'draft_version' => $page['draft_version_id'] ?? null,
            'conversion_goal_record' => $page['conversion_goal_id'] ?? null,
        ] as $key => $value) {
            $filled = is_array($value) ? $value !== [] : trim((string) ($value ?? '')) !== '' && (string) $value !== '0';
            $checkResults[$key] = $filled;
            if (!$filled) {
                $builderWarnings[] = $key . '_recommended';
            }
        }

        return [
            'score' => (int) round(($complete / count($requiredChecks)) * 100),
            'missing' => $missing,
            'checks' => $checkResults,
            'media_warnings' => $mediaWarnings,
            'builder_warnings' => $builderWarnings,
        ];
    }

    private function clearDefaultBrandProfile(): void
    {
        Database::execute('UPDATE marketing_brand_profiles SET is_default = 0 WHERE workspace_id = ?', [$this->workspaceId()]);
    }

    private function assertUniqueLandingSlug(string $slug, int $ignoreId = 0): void
    {
        $params = [$this->workspaceId(), $slug];
        $where = 'workspace_id = ? AND slug = ?';
        if ($ignoreId > 0) {
            $where .= ' AND id <> ?';
            $params[] = $ignoreId;
        }
        $row = Database::queryOne("SELECT id FROM marketing_landing_pages WHERE {$where} LIMIT 1", $params);
        if ($row) {
            throw new \InvalidArgumentException('Landing page slug must be unique in this workspace.');
        }
    }

    private function slugify(string $value): string
    {
        $value = strtolower(trim($value));
        $value = preg_replace('/[^a-z0-9]+/', '-', $value) ?: '';
        return trim($value, '-');
    }

    private function appendUtmQuery(string $url, array $params): string
    {
        if ($params === []) {
            return $url;
        }

        $separator = str_contains($url, '?') ? '&' : '?';
        return $url . $separator . http_build_query($params);
    }

    private function campaignRoiAnalytics(string $start, string $end): array
    {
        if (!Database::tableExists('campaigns') || !Database::columnExists('campaigns', 'workspace_id')) {
            return ['total_revenue' => 0.0, 'total_budget' => 0.0, 'roi_percent' => null, 'campaigns' => []];
        }

        $campaigns = Database::query(
            "SELECT id, name, status
             FROM campaigns
             WHERE workspace_id = ?
             ORDER BY updated_at DESC
             LIMIT 50",
            [$this->workspaceId()]
        );

        $rows = [];
        $totalRevenue = 0.0;
        $totalBudget = 0.0;
        foreach ($campaigns as $campaign) {
            $campaignId = (int) $campaign['id'];
            $budget = 0.0;
            if (Database::tableExists('marketing_campaign_briefs') && Database::columnExists('marketing_campaign_briefs', 'budget_estimate')) {
                $budgetRow = Database::queryOne(
                    "SELECT COALESCE(SUM(budget_estimate), 0) AS total_budget
                     FROM marketing_campaign_briefs
                     WHERE workspace_id = ? AND campaign_id = ?",
                    [$this->workspaceId(), $campaignId]
                );
                $budget = (float) ($budgetRow['total_budget'] ?? 0);
            }

            $revenue = 0.0;
            $conversionCount = 0;
            if (Database::tableExists('attribution_results') && Database::columnExists('attribution_results', 'workspace_id')) {
                $revenueRow = Database::queryOne(
                    "SELECT COALESCE(SUM(credited_value), 0) AS credited_revenue, COUNT(*) AS conversion_count
                     FROM attribution_results
                     WHERE workspace_id = ? AND campaign_id = ?
                       AND conversion_at >= ? AND conversion_at < DATE_ADD(?, INTERVAL 1 DAY)",
                    [$this->workspaceId(), $campaignId, $start, $end]
                );
                $revenue = (float) ($revenueRow['credited_revenue'] ?? 0);
                $conversionCount = (int) ($revenueRow['conversion_count'] ?? 0);
            }

            $contentCount = Database::tableExists('marketing_content_items')
                ? (int) (Database::queryOne(
                    "SELECT COUNT(*) AS count FROM marketing_content_items WHERE workspace_id = ? AND campaign_id = ?",
                    [$this->workspaceId(), $campaignId]
                )['count'] ?? 0)
                : 0;
            $utmCount = Database::tableExists('marketing_utm_links')
                ? (int) (Database::queryOne(
                    "SELECT COUNT(*) AS count FROM marketing_utm_links WHERE workspace_id = ? AND campaign_id = ?",
                    [$this->workspaceId(), $campaignId]
                )['count'] ?? 0)
                : 0;
            $formSubmissions = (Database::tableExists('form_submissions') && Database::columnExists('form_submissions', 'campaign_id') && Database::columnExists('form_submissions', 'workspace_id'))
                ? (int) (Database::queryOne(
                    "SELECT COUNT(*) AS count
                     FROM form_submissions
                     WHERE workspace_id = ? AND campaign_id = ?
                       AND submitted_at >= ? AND submitted_at < DATE_ADD(?, INTERVAL 1 DAY)",
                    [$this->workspaceId(), $campaignId, $start, $end]
                )['count'] ?? 0)
                : 0;

            $totalRevenue += $revenue;
            $totalBudget += $budget;
            $rows[] = [
                'campaign_id' => $campaignId,
                'campaign_name' => (string) $campaign['name'],
                'status' => (string) $campaign['status'],
                'budget_estimate' => round($budget, 2),
                'attributed_revenue' => round($revenue, 2),
                'roi_percent' => $budget > 0 ? round((($revenue - $budget) / $budget) * 100, 1) : null,
                'conversion_count' => $conversionCount,
                'content_count' => $contentCount,
                'utm_link_count' => $utmCount,
                'form_submissions' => $formSubmissions,
            ];
        }

        usort($rows, static fn(array $a, array $b): int => ($b['attributed_revenue'] <=> $a['attributed_revenue']) ?: ($b['content_count'] <=> $a['content_count']));

        return [
            'total_revenue' => round($totalRevenue, 2),
            'total_budget' => round($totalBudget, 2),
            'roi_percent' => $totalBudget > 0 ? round((($totalRevenue - $totalBudget) / $totalBudget) * 100, 1) : null,
            'campaigns' => array_slice($rows, 0, 20),
        ];
    }

    private function contentInfluenceAnalytics(string $start, string $end): array
    {
        if (!Database::tableExists('marketing_content_items')) {
            return ['total_content' => 0, 'influenced_content' => 0, 'items' => []];
        }

        $distributionCount = Database::tableExists('marketing_distribution_posts')
            ? "(SELECT COUNT(*) FROM marketing_distribution_posts d WHERE d.workspace_id = m.workspace_id AND d.content_item_id = m.id)"
            : '0';
        $distributionLiveCount = Database::tableExists('marketing_distribution_posts')
            ? "(SELECT COUNT(*) FROM marketing_distribution_posts d WHERE d.workspace_id = m.workspace_id AND d.content_item_id = m.id AND d.status IN ('exported','published'))"
            : '0';
        $utmCount = Database::tableExists('marketing_utm_links')
            ? "(SELECT COUNT(*) FROM marketing_utm_links u WHERE u.workspace_id = m.workspace_id AND u.content_item_id = m.id)"
            : '0';
        $revenue = (Database::tableExists('attribution_results') && Database::columnExists('attribution_results', 'workspace_id'))
            ? "(SELECT COALESCE(SUM(ar.credited_value), 0) FROM attribution_results ar WHERE ar.workspace_id = m.workspace_id AND ar.campaign_id = m.campaign_id AND ar.conversion_at >= '{$start}' AND ar.conversion_at < DATE_ADD('{$end}', INTERVAL 1 DAY))"
            : '0';

        $items = Database::query(
            "SELECT m.id, m.title, m.channel, m.status, c.name AS campaign_name,
                    {$distributionCount} AS distribution_count,
                    {$distributionLiveCount} AS distributed_count,
                    {$utmCount} AS utm_link_count,
                    {$revenue} AS attributed_revenue
             FROM marketing_content_items m
             LEFT JOIN campaigns c ON c.id = m.campaign_id AND c.workspace_id = m.workspace_id
             WHERE m.workspace_id = ?
             ORDER BY attributed_revenue DESC, distribution_count DESC, m.updated_at DESC
             LIMIT 20",
            [$this->workspaceId()]
        );

        $influenced = 0;
        foreach ($items as &$item) {
            $item['distribution_count'] = (int) ($item['distribution_count'] ?? 0);
            $item['distributed_count'] = (int) ($item['distributed_count'] ?? 0);
            $item['utm_link_count'] = (int) ($item['utm_link_count'] ?? 0);
            $item['attributed_revenue'] = round((float) ($item['attributed_revenue'] ?? 0), 2);
            if ($item['distribution_count'] > 0 || $item['utm_link_count'] > 0 || $item['attributed_revenue'] > 0) {
                $influenced++;
            }
        }
        unset($item);

        $total = (int) (Database::queryOne(
            "SELECT COUNT(*) AS count
             FROM marketing_content_items
             WHERE workspace_id = ? AND created_at >= ? AND created_at < DATE_ADD(?, INTERVAL 1 DAY)",
            [$this->workspaceId(), $start, $end]
        )['count'] ?? 0);

        return [
            'total_content' => $total,
            'influenced_content' => $influenced,
            'items' => $items,
        ];
    }

    private function landingPageFunnelAnalytics(string $start, string $end): array
    {
        if (!Database::tableExists('marketing_landing_pages')) {
            return ['total_pages' => 0, 'published_pages' => 0, 'with_forms' => 0, 'submissions' => 0, 'pages' => []];
        }

        $submissionSql = '0';
        $params = [];
        if (Database::tableExists('form_submissions') && Database::tableExists('forms')) {
            $workspaceFilter = Database::columnExists('form_submissions', 'workspace_id') ? 'AND fs.workspace_id = lp.workspace_id' : '';
            $submissionSql = "(SELECT COUNT(*)
                               FROM forms f
                               JOIN form_submissions fs ON (fs.form_definition_id = f.id OR fs.form_id = f.uuid)
                               WHERE f.id = lp.form_id {$workspaceFilter}
                                 AND fs.submitted_at >= ? AND fs.submitted_at < DATE_ADD(?, INTERVAL 1 DAY))";
            $params[] = $start;
            $params[] = $end;
        }
        $publicationSql = Database::tableExists('marketing_landing_page_publications')
            ? "(SELECT COUNT(*) FROM marketing_landing_page_publications p WHERE p.workspace_id = lp.workspace_id AND p.landing_page_id = lp.id AND p.status = 'published')"
            : '0';
        $params[] = $this->workspaceId();

        $pages = Database::query(
            "SELECT lp.id, lp.title, lp.slug, lp.status, COALESCE(lp.conversion_goal, 'lead_capture') AS conversion_goal,
                    CASE WHEN lp.form_id IS NULL THEN 0 ELSE 1 END AS has_form,
                    {$publicationSql} AS published_count,
                    {$submissionSql} AS submissions
             FROM marketing_landing_pages lp
             WHERE lp.workspace_id = ?
             ORDER BY submissions DESC, lp.updated_at DESC
             LIMIT 20",
            $params
        );

        $published = 0;
        $withForms = 0;
        $submissions = 0;
        foreach ($pages as &$page) {
            $page['has_form'] = (int) ($page['has_form'] ?? 0);
            $page['published_count'] = (int) ($page['published_count'] ?? 0);
            $page['submissions'] = (int) ($page['submissions'] ?? 0);
            $published += $page['published_count'] > 0 ? 1 : 0;
            $withForms += $page['has_form'] > 0 ? 1 : 0;
            $submissions += $page['submissions'];
        }
        unset($page);

        return [
            'total_pages' => (int) $this->countRows('marketing_landing_pages', 'id > 0'),
            'published_pages' => $published,
            'with_forms' => $withForms,
            'submissions' => $submissions,
            'pages' => $pages,
        ];
    }

    private function formConversionAnalytics(string $start, string $end): array
    {
        if (!Database::tableExists('forms') || !Database::tableExists('form_submissions') || !Database::columnExists('form_submissions', 'workspace_id')) {
            return ['total_submissions' => 0, 'unique_contacts' => 0, 'conversion_rate' => null, 'top_forms' => []];
        }

        $dateColumn = Database::columnExists('form_submissions', 'submitted_at') ? 'submitted_at' : 'created_at';
        $total = Database::queryOne(
            "SELECT COUNT(*) AS count, COUNT(DISTINCT contact_id) AS unique_contacts
             FROM form_submissions
             WHERE workspace_id = ? AND {$dateColumn} >= ? AND {$dateColumn} < DATE_ADD(?, INTERVAL 1 DAY)",
            [$this->workspaceId(), $start, $end]
        );
        $match = Database::columnExists('form_submissions', 'form_definition_id')
            ? '(fs.form_definition_id = f.id OR fs.form_id = f.uuid)'
            : 'fs.form_id = f.uuid';
        $forms = Database::query(
            "SELECT f.id, f.name,
                    (SELECT COUNT(*)
                     FROM form_submissions fs
                     WHERE fs.workspace_id = f.workspace_id AND {$match}
                       AND fs.{$dateColumn} >= ? AND fs.{$dateColumn} < DATE_ADD(?, INTERVAL 1 DAY)) AS submissions,
                    (SELECT COUNT(DISTINCT fs.contact_id)
                     FROM form_submissions fs
                     WHERE fs.workspace_id = f.workspace_id AND {$match}
                       AND fs.{$dateColumn} >= ? AND fs.{$dateColumn} < DATE_ADD(?, INTERVAL 1 DAY)) AS unique_contacts
             FROM forms f
             WHERE f.workspace_id = ?
             ORDER BY submissions DESC, f.updated_at DESC
             LIMIT 10",
            [$start, $end, $start, $end, $this->workspaceId()]
        );

        return [
            'total_submissions' => (int) ($total['count'] ?? 0),
            'unique_contacts' => (int) ($total['unique_contacts'] ?? 0),
            'conversion_rate' => null,
            'top_forms' => $forms,
            'tracking_note' => 'Conversion rate is shown after page-view tracking is workspace-scoped.',
        ];
    }

    private function utmPerformanceAnalytics(string $start, string $end): array
    {
        if (!Database::tableExists('marketing_utm_links')) {
            return ['total_links' => 0, 'by_source_medium' => [], 'by_campaign' => [], 'by_content' => [], 'click_tracking_available' => false];
        }

        $total = Database::queryOne(
            "SELECT COUNT(*) AS count
             FROM marketing_utm_links
             WHERE workspace_id = ? AND created_at >= ? AND created_at < DATE_ADD(?, INTERVAL 1 DAY)",
            [$this->workspaceId(), $start, $end]
        );
        $bySourceMedium = Database::query(
            "SELECT COALESCE(utm_source, 'unknown') AS utm_source, COALESCE(utm_medium, 'unknown') AS utm_medium, COUNT(*) AS count
             FROM marketing_utm_links
             WHERE workspace_id = ? AND created_at >= ? AND created_at < DATE_ADD(?, INTERVAL 1 DAY)
             GROUP BY COALESCE(utm_source, 'unknown'), COALESCE(utm_medium, 'unknown')
             ORDER BY count DESC
             LIMIT 10",
            [$this->workspaceId(), $start, $end]
        );
        $byCampaign = Database::query(
            "SELECT COALESCE(c.name, u.utm_campaign, 'Unassigned') AS campaign_name, COUNT(*) AS count
             FROM marketing_utm_links u
             LEFT JOIN campaigns c ON c.id = u.campaign_id AND c.workspace_id = u.workspace_id
             WHERE u.workspace_id = ? AND u.created_at >= ? AND u.created_at < DATE_ADD(?, INTERVAL 1 DAY)
             GROUP BY COALESCE(c.name, u.utm_campaign, 'Unassigned')
             ORDER BY count DESC
             LIMIT 10",
            [$this->workspaceId(), $start, $end]
        );
        $byContent = Database::query(
            "SELECT COALESCE(m.title, 'Unlinked Content') AS content_title, COUNT(*) AS count
             FROM marketing_utm_links u
             LEFT JOIN marketing_content_items m ON m.id = u.content_item_id AND m.workspace_id = u.workspace_id
             WHERE u.workspace_id = ? AND u.created_at >= ? AND u.created_at < DATE_ADD(?, INTERVAL 1 DAY)
             GROUP BY COALESCE(m.title, 'Unlinked Content')
             ORDER BY count DESC
             LIMIT 10",
            [$this->workspaceId(), $start, $end]
        );

        return [
            'total_links' => (int) ($total['count'] ?? 0),
            'by_source_medium' => $bySourceMedium,
            'by_campaign' => $byCampaign,
            'by_content' => $byContent,
            'click_tracking_available' => false,
        ];
    }

    private function revenueAttributionAnalytics(string $start, string $end): array
    {
        if (!Database::tableExists('attribution_results') || !Database::columnExists('attribution_results', 'workspace_id')) {
            return ['total_revenue' => 0.0, 'conversion_count' => 0, 'by_campaign' => [], 'by_channel' => [], 'by_event' => []];
        }

        $total = Database::queryOne(
            "SELECT COALESCE(SUM(credited_value), 0) AS credited_revenue, COUNT(*) AS conversion_count
             FROM attribution_results
             WHERE workspace_id = ? AND conversion_at >= ? AND conversion_at < DATE_ADD(?, INTERVAL 1 DAY)",
            [$this->workspaceId(), $start, $end]
        );
        $byCampaign = Database::query(
            "SELECT COALESCE(c.name, 'Unassigned Campaign') AS campaign_name, COALESCE(SUM(ar.credited_value), 0) AS credited_revenue, COUNT(*) AS conversion_count
             FROM attribution_results ar
             LEFT JOIN campaigns c ON c.id = ar.campaign_id AND c.workspace_id = ar.workspace_id
             WHERE ar.workspace_id = ? AND ar.conversion_at >= ? AND ar.conversion_at < DATE_ADD(?, INTERVAL 1 DAY)
             GROUP BY COALESCE(c.name, 'Unassigned Campaign')
             ORDER BY credited_revenue DESC
             LIMIT 10",
            [$this->workspaceId(), $start, $end]
        );
        $byChannel = Database::query(
            "SELECT channel, COALESCE(SUM(credited_value), 0) AS credited_revenue, COUNT(*) AS conversion_count
             FROM attribution_results
             WHERE workspace_id = ? AND conversion_at >= ? AND conversion_at < DATE_ADD(?, INTERVAL 1 DAY)
             GROUP BY channel
             ORDER BY credited_revenue DESC
             LIMIT 10",
            [$this->workspaceId(), $start, $end]
        );
        $byEvent = Database::query(
            "SELECT conversion_event, COALESCE(SUM(credited_value), 0) AS credited_revenue, COUNT(*) AS conversion_count
             FROM attribution_results
             WHERE workspace_id = ? AND conversion_at >= ? AND conversion_at < DATE_ADD(?, INTERVAL 1 DAY)
             GROUP BY conversion_event
             ORDER BY credited_revenue DESC
             LIMIT 10",
            [$this->workspaceId(), $start, $end]
        );

        return [
            'total_revenue' => round((float) ($total['credited_revenue'] ?? 0), 2),
            'conversion_count' => (int) ($total['conversion_count'] ?? 0),
            'by_campaign' => $byCampaign,
            'by_channel' => $byChannel,
            'by_event' => $byEvent,
        ];
    }

    private function evaluateContentQuality(array $content): array
    {
        $draft = trim((string) ($content['draft_body'] ?? ''));
        $title = trim((string) ($content['title'] ?? ''));
        $copy = strtolower($title . "\n" . $draft);
        $recommendations = [];
        $brand = null;
        if (!empty($content['brand_profile_id'])) {
            $brand = $this->getBrandProfile((int) $content['brand_profile_id']);
        }
        if (!$brand) {
            $brand = $this->listBrandProfiles(1)[0] ?? null;
        }
        $persona = !empty($content['persona_id']) ? $this->getPersona((int) $content['persona_id']) : null;
        $seoTopic = !empty($content['seo_topic_id']) ? $this->getSeoTopic((int) $content['seo_topic_id']) : null;
        $complianceTerms = $this->listContextItems(['item_type' => 'compliance_term', 'status' => 'active'], 25, 0);

        $bannedWords = $this->splitQualityTerms((string) ($brand['banned_words'] ?? ''));
        $bannedHits = [];
        foreach ($bannedWords as $word) {
            if ($word !== '' && str_contains($copy, strtolower($word))) {
                $bannedHits[] = $word;
            }
        }
        $brandScore = $brand ? 80 : 50;
        if ($draft === '') {
            $brandScore -= 25;
            $recommendations[] = 'Add draft copy before running final brand review.';
        }
        if (!$brand) {
            $recommendations[] = 'Create or link a brand profile so voice and banned-word checks have context.';
        }
        if ($bannedHits !== []) {
            $brandScore = min($brandScore, 35);
            $recommendations[] = 'Remove brand-banned words: ' . implode(', ', $bannedHits) . '.';
        }
        if ($brand && trim((string) ($brand['voice'] ?? '')) === '' && trim((string) ($brand['tone'] ?? '')) === '') {
            $brandScore -= 10;
            $recommendations[] = 'Add voice or tone guidance to the linked brand profile.';
        }

        $personaScore = $persona ? 82 : ((trim((string) ($content['target_audience'] ?? '')) !== '') ? 65 : 45);
        if (!$persona && trim((string) ($content['target_audience'] ?? '')) === '') {
            $recommendations[] = 'Link a persona or define a target audience before approval.';
        }

        $complianceScore = $complianceTerms !== [] ? 84 : 65;
        if ($complianceTerms === []) {
            $recommendations[] = 'Add compliance terms in the Context Hub for stronger approval-risk checks.';
        }
        $riskPhrases = ['guaranteed', 'guarantee', 'risk-free', '100%'];
        $riskHits = [];
        foreach ($riskPhrases as $phrase) {
            if (str_contains($copy, $phrase)) {
                $riskHits[] = $phrase;
            }
        }
        if ($riskHits !== []) {
            $complianceScore = min($complianceScore, 45);
            $recommendations[] = 'Review compliance-sensitive claims: ' . implode(', ', $riskHits) . '.';
        }

        $hasCta = preg_match('/\b(book|schedule|contact|download|start|reply|call|request|learn more|get|buy|subscribe)\b/i', $draft) === 1;
        $ctaScore = $hasCta ? 86 : 52;
        if (!$hasCta) {
            $recommendations[] = 'Add one clear call to action.';
        }

        $seoScore = 76;
        $keyword = trim((string) ($seoTopic['keyword'] ?? ''));
        if (in_array((string) ($content['content_type'] ?? ''), ['blog_post', 'case_study'], true)) {
            if ($keyword === '') {
                $seoScore = 55;
                $recommendations[] = 'Link an SEO topic for search-focused content.';
            } elseif (!str_contains($copy, strtolower($keyword))) {
                $seoScore = 65;
                $recommendations[] = 'Work the linked SEO keyword into the title or body: ' . $keyword . '.';
            } else {
                $seoScore = 88;
            }
        }

        $mediaReadiness = $this->contentMediaQualityDetails($content);
        foreach ((array) ($mediaReadiness['recommendations'] ?? []) as $recommendation) {
            $recommendations[] = (string) $recommendation;
        }

        $riskScore = 90;
        $riskLevel = 'low';
        $riskFactors = [];
        if ($draft === '') {
            $riskFactors[] = 'blank_draft';
            $riskScore -= 30;
        }
        if ($bannedHits !== []) {
            $riskFactors[] = 'brand_banned_words';
            $riskScore -= 35;
        }
        if ($riskHits !== []) {
            $riskFactors[] = 'compliance_claims';
            $riskScore -= 25;
        }
        if (!$hasCta) {
            $riskFactors[] = 'missing_cta';
            $riskScore -= 10;
        }
        if ((int) ($mediaReadiness['score'] ?? 100) < 75) {
            $riskFactors[] = 'media_readiness';
            $riskScore -= in_array('media_governance_blocked', (array) ($mediaReadiness['issues'] ?? []), true) ? 25 : 12;
        }
        if ($riskScore < 55) {
            $riskLevel = 'high';
        } elseif ($riskScore < 75) {
            $riskLevel = 'medium';
        }

        $sections = [
            'brand_voice' => $this->qualitySection($brandScore, [
                'brand_profile_id' => $brand['id'] ?? null,
                'brand_profile_name' => $brand['name'] ?? null,
                'banned_word_hits' => $bannedHits,
            ]),
            'persona_fit' => $this->qualitySection($personaScore, [
                'persona_id' => $persona['id'] ?? null,
                'persona_name' => $persona['name'] ?? null,
                'target_audience' => $content['target_audience'] ?? null,
            ]),
            'compliance' => $this->qualitySection($complianceScore, [
                'terms_count' => count($complianceTerms),
                'risk_phrase_hits' => $riskHits,
            ]),
            'cta_quality' => $this->qualitySection($ctaScore, ['has_cta' => $hasCta]),
            'seo_readiness' => $this->qualitySection($seoScore, [
                'seo_topic_id' => $seoTopic['id'] ?? null,
                'keyword' => $keyword !== '' ? $keyword : null,
            ]),
            'approval_risk' => $this->qualitySection(max(0, $riskScore), [
                'risk_level' => $riskLevel,
                'risk_factors' => $riskFactors,
                'media_readiness' => $mediaReadiness,
            ]),
        ];
        $overall = (int) round(array_sum(array_map(static fn(array $section): int => (int) $section['score'], $sections)) / count($sections));

        return $sections + [
            'overall_score' => $overall,
            'recommendations' => array_values(array_unique($recommendations)),
            'metadata' => [
                'engine' => 'deterministic_quality_fallback',
                'external_publish' => false,
                'draft_overwritten' => false,
                'checked_at' => date('c'),
                'media_accessibility' => $mediaReadiness,
            ],
        ];
    }

    private function contentMediaQualityDetails(array $content): array
    {
        $contentId = (int) ($content['id'] ?? 0);
        $attachments = [];

        if ($contentId > 0 && Database::tableExists('marketing_content_media')) {
            $attachments = $this->listContentMedia($contentId);
        }

        return $this->buildContentMediaQualityDetails($content, $attachments);
    }

    private function contentMediaQualityDetailsForItems(array $items): array
    {
        if ($items === [] || !Database::tableExists('marketing_content_media')) {
            return [];
        }

        $ids = array_values(array_unique(array_filter(array_map(static fn(array $item): int => (int) ($item['id'] ?? 0), $items))));
        if ($ids === []) {
            return [];
        }

        $placeholders = implode(',', array_fill(0, count($ids), '?'));
        $rows = Database::query(
            "SELECT cm.*,
                    mf.title AS media_title, mf.media_type, mf.source_type AS media_source_type,
                    mf.file_path AS media_file_path, mf.source_url AS media_source_url,
                    mf.mime_type AS media_mime_type, mf.thumbnail_path AS media_thumbnail_path,
                    mf.thumbnail_url AS media_thumbnail_url, mf.alt_text AS media_alt_text,
                    mf.caption AS media_caption, mf.transcript AS media_transcript,
                    mf.usage_rights AS media_usage_rights, mf.approval_status, mf.license_status,
                    mf.expiry_date, mf.accessibility_status, mf.blocked_reason
             FROM marketing_content_media cm
             JOIN marketing_media_files mf ON mf.id = cm.media_file_id AND mf.workspace_id = cm.workspace_id
             WHERE cm.workspace_id = ? AND cm.content_item_id IN ({$placeholders})
             ORDER BY cm.content_item_id ASC, cm.sort_order ASC, cm.id ASC",
            array_merge([$this->workspaceId()], $ids)
        );

        $attachmentsByContent = [];
        foreach ($rows as $row) {
            $contentId = (int) ($row['content_item_id'] ?? 0);
            if ($contentId <= 0) {
                continue;
            }
            $attachmentsByContent[$contentId][] = $this->hydrateContentMediaRow($row);
        }

        $qualityByContent = [];
        foreach ($items as $item) {
            $contentId = (int) ($item['id'] ?? 0);
            if ($contentId > 0) {
                $qualityByContent[$contentId] = $this->buildContentMediaQualityDetails($item, (array) ($attachmentsByContent[$contentId] ?? []));
            }
        }

        return $qualityByContent;
    }

    private function buildContentMediaQualityDetails(array $content, array $attachments): array
    {
        $contentType = (string) ($content['content_type'] ?? '');
        $channel = (string) ($content['channel'] ?? '');
        $issues = [];
        $recommendations = [];

        $hasImageOrVideo = false;
        $hasFeatured = false;
        $hasVideoReference = false;
        foreach ($attachments as $attachment) {
            $mediaType = (string) ($attachment['media_type'] ?? '');
            $role = (string) ($attachment['role'] ?? '');
            if (in_array($mediaType, ['image', 'logo', 'thumbnail', 'banner', 'video'], true)) {
                $hasImageOrVideo = true;
            }
            if (in_array($role, ['featured', 'thumbnail', 'banner'], true)) {
                $hasFeatured = true;
            }
            if ($mediaType === 'video' || in_array($role, ['video_source', 'reference'], true)) {
                $hasVideoReference = true;
            }

            $effectiveAlt = trim((string) ($attachment['effective_alt_text'] ?? $attachment['media_alt_text'] ?? ''));
            $effectiveCaption = trim((string) ($attachment['effective_caption'] ?? $attachment['media_caption'] ?? ''));
            $transcript = trim((string) ($attachment['media_transcript'] ?? ''));
            $approvalStatus = (string) ($attachment['approval_status'] ?? '');
            $licenseStatus = (string) ($attachment['license_status'] ?? '');
            $expiryDate = trim((string) ($attachment['expiry_date'] ?? ''));

            if (in_array($mediaType, ['image', 'logo', 'thumbnail', 'banner'], true) && $effectiveAlt === '') {
                $issues[] = 'missing_alt_text';
                $recommendations[] = 'Add alt text to "' . (string) ($attachment['media_title'] ?? 'attached image') . '" before approval.';
            }
            if ($mediaType === 'video' && $effectiveCaption === '' && $transcript === '') {
                $issues[] = 'video_caption_or_transcript';
                $recommendations[] = 'Add a caption or transcript to "' . (string) ($attachment['media_title'] ?? 'attached video') . '" before approval.';
            }
            $expiredByDate = $expiryDate !== '' && strtotime($expiryDate) !== false && strtotime($expiryDate) < strtotime('today');
            if (in_array($approvalStatus, ['blocked', 'rejected', 'archived'], true) || in_array($licenseStatus, ['expired', 'restricted'], true) || $expiredByDate) {
                $issues[] = 'media_governance_blocked';
                $recommendations[] = 'Resolve media governance or usage-rights blockers before this draft is export-ready.';
            }
        }

        if (in_array($contentType, ['blog_post', 'case_study'], true) && !$hasFeatured) {
            $issues[] = 'featured_image_recommended';
            $recommendations[] = 'Attach a featured image before final approval.';
        }
        if (in_array($contentType, ['social_post', 'ad_copy'], true) && !$hasImageOrVideo) {
            $issues[] = 'channel_media_recommended';
            $recommendations[] = 'Attach a channel-ready image or video before distribution.';
        }
        if (in_array($contentType, ['email', 'newsletter'], true) && !$hasFeatured && $channel !== 'sms') {
            $issues[] = 'banner_media_recommended';
            $recommendations[] = 'Consider adding a banner image for the email or newsletter draft.';
        }
        if ($contentType === 'video_script' && !$hasVideoReference) {
            $issues[] = 'video_reference_recommended';
            $recommendations[] = 'Attach source or reference media for the video script.';
        }

        $issues = array_values(array_unique($issues));
        $score = 90;
        foreach ($issues as $issue) {
            $score -= match ($issue) {
                'media_governance_blocked' => 35,
                'missing_alt_text', 'video_caption_or_transcript' => 18,
                default => 8,
            };
        }

        return [
            'score' => max(0, min(100, $score)),
            'status' => $issues === [] ? 'ready' : (in_array('media_governance_blocked', $issues, true) ? 'blocked' : 'needs_review'),
            'attachments_count' => count($attachments),
            'issues' => $issues,
            'recommendations' => array_values(array_unique($recommendations)),
        ];
    }

    private function normalizeQualityReviewResult(array $candidate, array $fallback): array
    {
        $sections = [];
        foreach (['brand_voice', 'persona_fit', 'compliance', 'cta_quality', 'seo_readiness', 'approval_risk'] as $key) {
            $sections[$key] = $this->normalizeQualityReviewSection($candidate[$key] ?? null, (array) ($fallback[$key] ?? []));
        }

        $recommendations = $this->normalizeAiStringList($candidate['recommendations'] ?? []);
        if ($recommendations === []) {
            $recommendations = $this->normalizeAiStringList($fallback['recommendations'] ?? []);
        }

        $overall = is_numeric($candidate['overall_score'] ?? null)
            ? (int) round((float) $candidate['overall_score'])
            : (int) round(array_sum(array_map(static fn(array $section): int => (int) $section['score'], $sections)) / max(1, count($sections)));

        return $sections + [
            'overall_score' => max(0, min(100, $overall)),
            'recommendations' => $recommendations,
            'metadata' => (array) ($fallback['metadata'] ?? []),
        ];
    }

    private function normalizeQualityReviewSection($candidate, array $fallback): array
    {
        if (is_numeric($candidate)) {
            return $this->qualitySection((int) round((float) $candidate), (array) ($fallback['details'] ?? []));
        }
        if (is_array($candidate)) {
            $score = is_numeric($candidate['score'] ?? null)
                ? (int) round((float) $candidate['score'])
                : (int) ($fallback['score'] ?? 0);
            $details = (array) ($candidate['details'] ?? []);
            if ($details === []) {
                $details = array_diff_key($candidate, ['score' => true]);
            }
            if ($details === []) {
                $details = (array) ($fallback['details'] ?? []);
            }

            return $this->qualitySection($score, $details);
        }

        return $this->qualitySection((int) ($fallback['score'] ?? 0), (array) ($fallback['details'] ?? []));
    }

    private function qualitySection(int $score, array $details): array
    {
        return [
            'score' => max(0, min(100, $score)),
            'details' => $details,
        ];
    }

    private function splitQualityTerms(string $value): array
    {
        $parts = preg_split('/[\r\n,;]+/', $value) ?: [];
        return array_values(array_filter(array_map(static fn(string $part): string => trim($part), $parts)));
    }

    private function channelBundleType(string $channel): string
    {
        return match ($channel) {
            'whatsapp' => 'whatsapp',
            'sms' => 'sms',
            'ads' => 'ad',
            'email', 'newsletter' => 'newsletter',
            'linkedin', 'facebook', 'instagram', 'x', 'youtube' => 'social',
            default => 'custom',
        };
    }

    private function defaultChannelRequiredFields(string $channel): array
    {
        return match ($this->channelBundleType($channel)) {
            'social' => ['caption', 'destination_url', 'asset'],
            'whatsapp' => ['message', 'opt_in_audience_note'],
            'sms' => ['message_under_160_chars', 'opt_out_copy'],
            'ad' => ['headline', 'primary_text', 'destination_url', 'asset'],
            'newsletter' => ['subject', 'preview_text', 'body', 'cta'],
            default => ['copy', 'destination_url'],
        };
    }

    private function audienceSegmentLinkForDistributionPost(array $post): array
    {
        $segmentId = null;
        $segmentName = null;
        $contentId = (int) ($post['content_item_id'] ?? 0);
        $content = $contentId > 0 ? ($this->getContentItem($contentId) ?? []) : [];

        if (!empty($content['landing_page_id'])) {
            $landingPage = $this->getLandingPage((int) $content['landing_page_id']);
            if (!empty($landingPage['audience_segment_id'])) {
                $segmentId = (int) $landingPage['audience_segment_id'];
                $segmentName = (string) ($landingPage['audience_segment_name'] ?? '');
            }
        }

        if ($segmentId === null && !empty($content['campaign_brief_id'])) {
            $brief = $this->getCampaignBrief((int) $content['campaign_brief_id']);
            if (!empty($brief['audience_segment_id'])) {
                $segmentId = (int) $brief['audience_segment_id'];
                $segmentName = (string) ($brief['audience_segment_name'] ?? '');
            }
        }

        if ($segmentId === null && !empty($content['campaign_id'])) {
            $brief = Database::queryOne(
                "SELECT b.audience_segment_id, seg.name AS audience_segment_name
                 FROM marketing_campaign_briefs b
                 LEFT JOIN marketing_audience_segments seg ON seg.id = b.audience_segment_id AND seg.workspace_id = b.workspace_id
                 WHERE b.workspace_id = ? AND b.campaign_id = ? AND b.audience_segment_id IS NOT NULL
                 ORDER BY b.updated_at DESC
                 LIMIT 1",
                [$this->workspaceId(), (int) $content['campaign_id']]
            );
            if (!empty($brief['audience_segment_id'])) {
                $segmentId = (int) $brief['audience_segment_id'];
                $segmentName = (string) ($brief['audience_segment_name'] ?? '');
            }
        }

        if ($segmentId !== null && $segmentName === '') {
            $segment = $this->getAudienceSegment($segmentId);
            $segmentName = (string) ($segment['name'] ?? '');
        }

        return [
            'audience_segment_id' => $segmentId,
            'audience_segment_name' => $segmentName !== '' ? $segmentName : null,
            'segment_snapshot_id' => null,
        ];
    }

    private function channelMediaKitRequirements(string $channel): array
    {
        $channel = $this->normalizeEnum($channel, self::CHANNELS, 'channel');
        $base = [
            'required_dimensions' => [],
            'aspect_ratios' => [],
            'copy_fields' => [
                'required' => ['planned_copy'],
                'values' => [],
            ],
            'media_slots' => [],
            'destination_rules' => [
                'required_url' => in_array($channel, ['linkedin', 'facebook', 'instagram', 'x', 'ads', 'youtube', 'website', 'email', 'newsletter'], true),
                'allowed_schemes' => ['https', 'http'],
                'utm_recommended' => in_array($channel, ['linkedin', 'facebook', 'instagram', 'x', 'ads', 'website', 'email', 'newsletter'], true),
            ],
            'export_checklist' => [
                'Review copy',
                'Confirm media rights',
                'Confirm alt text or captions',
                'Confirm destination link',
                'Manual publish only',
            ],
        ];

        return match ($channel) {
            'instagram' => array_replace_recursive($base, [
                'required_dimensions' => ['feed_portrait' => '1080x1350', 'square' => '1080x1080', 'reel' => '1080x1920'],
                'aspect_ratios' => ['4:5', '1:1', '9:16'],
                'media_slots' => [[
                    'key' => 'instagram_primary_visual',
                    'label' => 'Instagram image or video',
                    'required' => true,
                    'accepted_types' => ['image', 'video'],
                    'accepted_roles' => ['featured', 'inline', 'thumbnail', 'video_source'],
                ]],
            ]),
            'youtube' => array_replace_recursive($base, [
                'required_dimensions' => ['thumbnail' => '1280x720'],
                'aspect_ratios' => ['16:9'],
                'media_slots' => [[
                    'key' => 'youtube_thumbnail',
                    'label' => 'YouTube thumbnail',
                    'required' => true,
                    'accepted_types' => ['image', 'thumbnail'],
                    'accepted_roles' => ['thumbnail', 'featured'],
                ]],
            ]),
            'email', 'newsletter' => array_replace_recursive($base, [
                'required_dimensions' => ['banner' => '1200x400'],
                'aspect_ratios' => ['3:1'],
                'media_slots' => [[
                    'key' => 'email_banner',
                    'label' => 'Email or newsletter banner',
                    'required' => true,
                    'accepted_types' => ['image', 'banner'],
                    'accepted_roles' => ['banner', 'featured'],
                ]],
            ]),
            'website' => array_replace_recursive($base, [
                'required_dimensions' => ['hero' => '1600x900', 'social_preview' => '1200x630'],
                'aspect_ratios' => ['16:9', '1.91:1'],
                'media_slots' => [[
                    'key' => 'website_hero',
                    'label' => 'Website hero image or video',
                    'required' => true,
                    'accepted_types' => ['image', 'video', 'banner'],
                    'accepted_roles' => ['featured', 'banner', 'video_source'],
                ]],
            ]),
            'ads' => array_replace_recursive($base, [
                'required_dimensions' => ['square' => '1080x1080', 'landscape' => '1200x628'],
                'aspect_ratios' => ['1:1', '1.91:1'],
                'media_slots' => [[
                    'key' => 'ad_creative',
                    'label' => 'Ad creative image or video',
                    'required' => true,
                    'accepted_types' => ['image', 'video'],
                    'accepted_roles' => ['featured', 'inline', 'thumbnail', 'video_source'],
                ]],
            ]),
            'linkedin', 'facebook' => array_replace_recursive($base, [
                'required_dimensions' => ['feed' => '1200x1200', 'link_preview' => '1200x627'],
                'aspect_ratios' => ['1:1', '1.91:1'],
                'media_slots' => [[
                    'key' => $channel . '_primary_visual',
                    'label' => ucfirst($channel) . ' image or video',
                    'required' => true,
                    'accepted_types' => ['image', 'video'],
                    'accepted_roles' => ['featured', 'inline', 'thumbnail', 'video_source'],
                ]],
            ]),
            'whatsapp' => array_replace_recursive($base, [
                'destination_rules' => ['required_url' => false, 'utm_recommended' => false],
                'media_slots' => [[
                    'key' => 'whatsapp_optional_attachment',
                    'label' => 'WhatsApp image or video attachment',
                    'required' => false,
                    'accepted_types' => ['image', 'video', 'document'],
                    'accepted_roles' => ['attachment', 'inline'],
                ]],
            ]),
            'sms' => array_replace_recursive($base, [
                'copy_fields' => ['required' => ['message_under_160_chars'], 'values' => []],
                'destination_rules' => ['required_url' => false, 'utm_recommended' => false],
                'export_checklist' => ['Confirm opt-out copy', 'Keep message concise', 'Manual send only'],
            ]),
            default => $base,
        };
    }

    private function channelMediaKitReadiness(array $kit): array
    {
        $channel = (string) ($kit['channel'] ?? 'other');
        $requirements = $this->channelMediaKitRequirements($channel);
        $mediaSlots = $this->decodeJsonLike($kit['media_slots_json'] ?? $kit['media_slots'] ?? $requirements['media_slots']);
        $copyFields = $this->decodeJsonLike($kit['copy_fields_json'] ?? $kit['copy_fields'] ?? $requirements['copy_fields']);
        $destinationRules = $this->decodeJsonLike($kit['destination_rules_json'] ?? $kit['destination_rules'] ?? $requirements['destination_rules']);
        $warnings = [];
        $missing = [];

        $copyValues = (array) ($copyFields['values'] ?? $copyFields);
        $plannedCopy = trim((string) ($copyValues['planned_copy'] ?? $kit['distribution_planned_copy'] ?? $kit['planned_copy'] ?? ''));
        $requiredCopy = (array) ($copyFields['required'] ?? ['planned_copy']);
        if (in_array('planned_copy', $requiredCopy, true) && $plannedCopy === '') {
            $missing[] = 'planned_copy';
        }
        if (in_array('message_under_160_chars', $requiredCopy, true) && $plannedCopy !== '' && mb_strlen($plannedCopy) > 160) {
            $warnings[] = 'sms_copy_over_160_chars';
        }

        $destinationUrl = trim((string) ($kit['destination_url'] ?? $kit['utm_generated_url'] ?? ''));
        if (!empty($destinationRules['required_url']) && $destinationUrl === '') {
            $missing[] = 'destination_url';
        }
        if (!empty($destinationRules['utm_recommended']) && empty($kit['utm_link_id'])) {
            $warnings[] = 'utm_link_recommended';
        }

        $primaryMedia = null;
        $primaryMediaId = (int) ($kit['primary_media_file_id'] ?? 0);
        if ($primaryMediaId > 0) {
            $primaryMedia = $this->getMediaFile($primaryMediaId);
        }
        $contentMedia = [];
        $contentId = (int) ($kit['content_item_id'] ?? 0);
        if ($contentId > 0 && Database::tableExists('marketing_content_media')) {
            $contentMedia = $this->listContentMedia($contentId);
        }

        foreach ($mediaSlots as $slot) {
            $slot = (array) $slot;
            if (empty($slot['required'])) {
                continue;
            }
            if (!$this->channelMediaSlotSatisfied($slot, $primaryMedia, $contentMedia)) {
                $key = (string) ($slot['key'] ?? 'required_media');
                $missing[] = $key;
            }
        }

        foreach (array_filter(array_merge($primaryMedia ? [$primaryMedia] : [], $contentMedia)) as $media) {
            $type = (string) ($media['media_type'] ?? '');
            $approval = (string) ($media['approval_status'] ?? '');
            $license = (string) ($media['license_status'] ?? '');
            $expiry = trim((string) ($media['expiry_date'] ?? ''));
            if (in_array($approval, ['blocked', 'archived'], true) || in_array($license, ['expired', 'restricted'], true) || ($expiry !== '' && strtotime($expiry) < strtotime('today'))) {
                $missing[] = 'media_governance_blocked';
                $warnings[] = 'expired_or_blocked_media';
            }
            if (in_array($type, ['image', 'logo', 'thumbnail', 'banner'], true)) {
                $alt = trim((string) ($media['alt_text'] ?? $media['effective_alt_text'] ?? $media['media_alt_text'] ?? ''));
                if ($alt === '') {
                    $warnings[] = 'alt_text_missing';
                }
            }
            if ($type === 'video') {
                $caption = trim((string) ($media['caption'] ?? $media['effective_caption'] ?? $media['transcript'] ?? $media['media_transcript'] ?? ''));
                if ($caption === '') {
                    $warnings[] = 'video_caption_or_transcript_recommended';
                }
            }
        }

        return [
            'ready' => $missing === [],
            'missing' => array_values(array_unique($missing)),
            'warnings' => array_values(array_unique($warnings)),
            'checked_at' => date('c'),
            'manual_export_only' => true,
        ];
    }

    private function channelMediaSlotSatisfied(array $slot, ?array $primaryMedia, array $contentMedia): bool
    {
        $acceptedTypes = array_map('strval', (array) ($slot['accepted_types'] ?? []));
        $acceptedRoles = array_map('strval', (array) ($slot['accepted_roles'] ?? []));
        $matchesType = static fn(array $media): bool => $acceptedTypes === [] || in_array((string) ($media['media_type'] ?? ''), $acceptedTypes, true);

        if ($primaryMedia && $matchesType($primaryMedia)) {
            return true;
        }

        foreach ($contentMedia as $media) {
            $roleMatches = $acceptedRoles === [] || in_array((string) ($media['role'] ?? ''), $acceptedRoles, true);
            if ($roleMatches && $matchesType($media)) {
                return true;
            }
        }

        return false;
    }

    private function buildChannelMediaKitPayload(array $kit): array
    {
        $requirements = [
            'required_dimensions' => $this->decodeJsonLike($kit['required_dimensions_json'] ?? []),
            'aspect_ratios' => $this->decodeJsonLike($kit['aspect_ratios_json'] ?? []),
            'copy_fields' => $this->decodeJsonLike($kit['copy_fields_json'] ?? []),
            'media_slots' => $this->decodeJsonLike($kit['media_slots_json'] ?? []),
            'destination_rules' => $this->decodeJsonLike($kit['destination_rules_json'] ?? []),
            'export_checklist' => $this->decodeJsonLike($kit['export_checklist_json'] ?? []),
        ];
        $readiness = $this->decodeJsonLike($kit['readiness_json'] ?? []);
        if ($readiness === []) {
            $readiness = $this->channelMediaKitReadiness($kit);
        }

        $content = !empty($kit['content_item_id']) ? ($this->getContentItem((int) $kit['content_item_id']) ?: []) : [];
        $landingPage = !empty($kit['landing_page_id']) ? ($this->getLandingPage((int) $kit['landing_page_id']) ?: []) : [];
        $utm = [];
        if (!empty($kit['utm_link_id'])) {
            $utm = Database::queryOne(
                'SELECT * FROM marketing_utm_links WHERE workspace_id = ? AND id = ?',
                [$this->workspaceId(), (int) $kit['utm_link_id']]
            ) ?: [];
        }
        $primaryMedia = !empty($kit['primary_media_file_id']) ? ($this->getMediaFile((int) $kit['primary_media_file_id']) ?: []) : [];
        if ($primaryMedia) {
            $primaryMedia['display_url'] = $this->mediaDisplayUrl($primaryMedia);
        }
        $contentMedia = !empty($kit['content_item_id']) ? $this->exportableContentMedia((int) $kit['content_item_id']) : [];

        return [
            'kit_id' => (int) ($kit['id'] ?? 0),
            'title' => (string) ($kit['title'] ?? ''),
            'channel' => (string) ($kit['channel'] ?? 'other'),
            'status' => (string) ($kit['status'] ?? 'draft'),
            'copy' => [
                'planned_copy' => (string) (($requirements['copy_fields']['values']['planned_copy'] ?? null) ?: ($kit['distribution_planned_copy'] ?? $content['draft_body'] ?? '')),
                'content_title' => $content['title'] ?? ($kit['content_title'] ?? null),
                'landing_page_headline' => $landingPage['headline'] ?? null,
            ],
            'media' => [
                'primary' => $primaryMedia ? [
                    'media_file_id' => (int) ($primaryMedia['id'] ?? 0),
                    'title' => (string) ($primaryMedia['title'] ?? ''),
                    'media_type' => (string) ($primaryMedia['media_type'] ?? ''),
                    'url' => (string) ($primaryMedia['display_url'] ?? ''),
                    'alt_text' => (string) ($primaryMedia['alt_text'] ?? ''),
                    'caption' => (string) ($primaryMedia['caption'] ?? ''),
                ] : null,
                'content_attachments' => $contentMedia,
                'landing_page_media' => (array) ($landingPage['_media'] ?? []),
            ],
            'links' => [
                'destination_url' => (string) (($kit['destination_url'] ?? '') ?: ($utm['generated_url'] ?? '')),
                'utm_url' => (string) ($utm['generated_url'] ?? ''),
                'base_url' => (string) ($utm['url'] ?? ''),
            ],
            'requirements' => $requirements,
            'readiness' => $readiness,
            'no_external_publish' => true,
            'generated_at' => date('c'),
        ];
    }

    private function channelAssetReadiness(array $post): array
    {
        $channel = (string) ($post['channel'] ?? 'other');
        $assetRequired = in_array($channel, ['instagram', 'facebook', 'ads', 'youtube'], true);
        $media = $this->exportableContentMedia((int) ($post['content_item_id'] ?? 0));
        $hasAsset = trim((string) ($post['asset_title'] ?? '')) !== '' || $media !== [];

        return [
            'asset_required' => $assetRequired,
            'has_asset' => $hasAsset,
            'ready' => !$assetRequired || $hasAsset,
            'asset_title' => $post['asset_title'] ?? null,
            'media_attachment_count' => count($media),
        ];
    }

    private function buildMarketingReportPayload(string $reportType, array $options, ?string $periodStart, ?string $periodEnd): array
    {
        $payload = [
            'report_type' => $reportType,
            'period_start' => $periodStart,
            'period_end' => $periodEnd,
            'generated_at' => date('c'),
            'workspace_id' => $this->workspaceId(),
            'manual_first_boundary' => [
                'external_publish' => false,
                'external_send' => false,
                'external_generation' => false,
            ],
        ];

        if ($reportType === 'weekly' || $reportType === 'monthly') {
            $payload['analytics'] = $this->getMarketingAnalyticsSummary($reportType);
            $analyticsPeriod = (array) ($payload['analytics']['period'] ?? []);
            $payload['execution_evidence'] = $this->getMarketingExecutionEvidenceSummary(
                $periodStart ?? (string) ($analyticsPeriod['start'] ?? ''),
                $periodEnd ?? (string) ($analyticsPeriod['end'] ?? ''),
                5
            );
            $payload['planning_queue'] = Database::tableExists('marketing_planning_queue_items')
                ? $this->listPlanningQueueItems(['open' => true], 25, 0)
                : [];
            return $this->sanitizeFlexibleArray($payload);
        }

        if ($reportType === 'performance') {
            $payload['performance'] = $this->getPerformanceSummary();
            return $this->sanitizeFlexibleArray($payload);
        }

        if ($reportType === 'budget') {
            $payload['budget_roi'] = $this->getBudgetRoiSummary();
            return $this->sanitizeFlexibleArray($payload);
        }

        if ($reportType === 'experiments') {
            $payload['experiments'] = Database::tableExists('marketing_experiments')
                ? $this->listExperiments([], 50, 0)
                : [];
            return $this->sanitizeFlexibleArray($payload);
        }

        $payload['diagnostics'] = $this->getMarketingDiagnostics();
        $payload['operator_readiness'] = $this->getMarketingOperatorReadiness();
        $payload['execution_evidence'] = $this->getMarketingExecutionEvidenceSummary($periodStart, $periodEnd, 8);
        $payload['connector_diagnostics'] = Database::tableExists('marketing_channel_connectors')
            ? $this->getChannelConnectorDiagnostics()
            : ['total_connectors' => 0, 'live_execution_enabled' => false, 'secret_safe' => true];
        if ($reportType === 'custom') {
            $payload['requested_sections'] = $this->sanitizeFlexibleArray($options['sections'] ?? []);
        }

        return $this->sanitizeFlexibleArray($payload);
    }

    private function normalizeMarketingDecisionData(array $data, bool $forCreate): array
    {
        $workspaceId = $this->workspaceId();
        $title = mb_substr(Security::sanitizeInput((string) ($data['title'] ?? ''), 'string'), 0, 255);
        if ($title === '') {
            throw new \InvalidArgumentException('Decision title is required.');
        }

        $nullableId = static function (mixed $value): ?int {
            if ($value === null || $value === '') {
                return null;
            }
            $id = (int) $value;
            return $id > 0 ? $id : null;
        };

        $decisionStatus = $this->normalizeEnum((string) ($data['decision_status'] ?? $data['status'] ?? 'open'), self::DECISION_STATUSES, 'decision_status');
        $decidedAt = $data['decided_at'] ?? null;
        $decidedBy = $nullableId($data['decided_by'] ?? null);
        if (in_array($decisionStatus, ['accepted', 'rejected', 'deferred', 'archived'], true) && !$decidedAt) {
            $decidedAt = date('Y-m-d H:i:s');
        }
        if ($decidedBy !== null) {
            $this->assertWorkspaceUser($decidedBy, $workspaceId);
        }

        $ownerUserId = $nullableId($data['owner_user_id'] ?? null);
        if ($ownerUserId !== null) {
            $this->assertWorkspaceUser($ownerUserId, $workspaceId);
        }

        $createdBy = $nullableId($data['created_by'] ?? ($forCreate ? $this->currentUserId() : null));
        if ($createdBy !== null) {
            $this->assertWorkspaceUser($createdBy, $workspaceId);
        }

        $sourceType = $this->normalizeEnum((string) ($data['source_type'] ?? 'custom'), self::DECISION_SOURCE_TYPES, 'source_type');
        $sourceId = $nullableId($data['source_id'] ?? null);
        $campaignId = $nullableId($data['campaign_id'] ?? null);
        $contentItemId = $nullableId($data['content_item_id'] ?? null);
        $landingPageId = $nullableId($data['landing_page_id'] ?? null);
        $mediaFileId = $nullableId($data['media_file_id'] ?? null);
        $distributionPostId = $nullableId($data['distribution_post_id'] ?? null);

        if ($campaignId !== null) {
            $this->assertWorkspaceRecord('campaigns', $campaignId, $workspaceId);
        }
        if ($contentItemId !== null) {
            $this->assertWorkspaceRecord('marketing_content_items', $contentItemId, $workspaceId);
        }
        if ($landingPageId !== null) {
            $this->assertWorkspaceRecord('marketing_landing_pages', $landingPageId, $workspaceId);
        }
        if ($mediaFileId !== null) {
            $this->assertWorkspaceRecord('marketing_media_files', $mediaFileId, $workspaceId);
        }
        if ($distributionPostId !== null) {
            $this->assertWorkspaceRecord('marketing_distribution_posts', $distributionPostId, $workspaceId);
        }
        if ($sourceId !== null) {
            match ($sourceType) {
                'campaign' => $this->assertWorkspaceRecord('campaigns', $sourceId, $workspaceId),
                'content' => $this->assertWorkspaceRecord('marketing_content_items', $sourceId, $workspaceId),
                'landing_page' => $this->assertWorkspaceRecord('marketing_landing_pages', $sourceId, $workspaceId),
                'media' => $this->assertWorkspaceRecord('marketing_media_files', $sourceId, $workspaceId),
                'distribution' => $this->assertWorkspaceRecord('marketing_distribution_posts', $sourceId, $workspaceId),
                default => null,
            };
        }

        $metadata = $data['metadata_json'] ?? $data['metadata'] ?? [];
        if (!is_array($metadata)) {
            $metadata = [];
        }
        $metadata = array_merge([
            'source' => 'marketing_decision_center',
            'manual_first' => true,
            'external_publish' => false,
            'external_send' => false,
        ], $metadata);

        $evidence = $data['evidence_json'] ?? $data['evidence'] ?? [];
        if (!is_array($evidence)) {
            $evidence = [];
        }

        return [
            'title' => $title,
            'decision_type' => $this->normalizeEnum((string) ($data['decision_type'] ?? 'custom'), self::DECISION_TYPES, 'decision_type'),
            'decision_status' => $decisionStatus,
            'priority' => $this->normalizeEnum((string) ($data['priority'] ?? 'normal'), self::DECISION_PRIORITIES, 'priority'),
            'source_type' => $sourceType,
            'source_id' => $sourceId,
            'campaign_id' => $campaignId,
            'content_item_id' => $contentItemId,
            'landing_page_id' => $landingPageId,
            'media_file_id' => $mediaFileId,
            'distribution_post_id' => $distributionPostId,
            'recommended_action' => trim(Security::sanitizeInput((string) ($data['recommended_action'] ?? ''), 'string')) ?: null,
            'rationale' => trim(Security::sanitizeInput((string) ($data['rationale'] ?? ''), 'string')) ?: null,
            'expected_impact' => trim(Security::sanitizeInput((string) ($data['expected_impact'] ?? ''), 'string')) ?: null,
            'decision_note' => trim(Security::sanitizeInput((string) ($data['decision_note'] ?? ''), 'string')) ?: null,
            'due_at' => $this->normalizeDateTime((string) ($data['due_at'] ?? '')),
            'decided_at' => $decidedAt ? $this->normalizeDateTime((string) $decidedAt) : null,
            'decided_by' => $decidedBy,
            'owner_user_id' => $ownerUserId,
            'created_by' => $createdBy,
            'evidence_json' => $this->normalizeJsonValue($this->sanitizeJsonCompatible($evidence)),
            'metadata_json' => $this->normalizeJsonValue($this->sanitizeJsonCompatible($metadata)),
        ];
    }

    private function normalizeReportRecipients(mixed $value): array
    {
        if (is_string($value)) {
            $value = preg_split('/[,\\r\\n]+/', $value) ?: [];
        }

        $recipients = [];
        foreach ((array) $value as $recipient) {
            $recipient = Security::sanitizeInput((string) $recipient, 'string');
            if ($recipient === '') {
                continue;
            }
            $recipients[] = mb_substr($recipient, 0, 180);
        }

        return array_values(array_unique(array_slice($recipients, 0, 25)));
    }

    private function buildMarketingOperatorReadinessChecks(): array
    {
        $latestMigration = Database::tableExists('migrations')
            ? (Database::queryOne("SELECT migration_name, executed_at FROM migrations ORDER BY executed_at DESC, id DESC LIMIT 1") ?: null)
            : null;
        $requiredTables = [
            'marketing_content_items',
            'marketing_report_exports',
            'marketing_scheduled_report_drafts',
            'marketing_operator_readiness_checks',
            'marketing_execution_queue',
            'marketing_channel_connectors',
            'marketing_campaign_budgets',
            'marketing_experiments',
            'marketing_audit_events',
            'marketing_cleanup_runs',
            'marketing_tracking_events',
            'marketing_visitor_sessions',
            'marketing_landing_page_views',
            'marketing_cta_clicks',
            'marketing_conversion_events',
            'marketing_attribution_touchpoints',
            'marketing_attribution_summaries',
            'marketing_conversion_goals',
            'marketing_conversion_goal_links',
            'marketing_handoff_rules',
            'marketing_lead_handoffs',
            'marketing_crm_sync_events',
        ];
        $missingTables = array_values(array_filter(
            $requiredTables,
            static fn(string $table): bool => !Database::tableExists($table)
        ));
        $diagnostics = $this->getMarketingDiagnostics();
        $aiReadiness = (array) ($diagnostics['ai_readiness'] ?? []);
        $mediaCounts = (array) ($diagnostics['media_diagnostics']['counts'] ?? []);
        $connectorDiagnostics = Database::tableExists('marketing_channel_connectors')
            ? $this->getChannelConnectorDiagnostics()
            : ['total_connectors' => 0, 'live_execution_enabled' => false, 'secret_safe' => true];
        $executionCounts = Database::tableExists('marketing_execution_queue')
            ? (Database::queryOne(
                "SELECT
                    SUM(CASE WHEN status = 'blocked' THEN 1 ELSE 0 END) AS blocked_count,
                    SUM(CASE WHEN execution_mode = 'live' THEN 1 ELSE 0 END) AS live_count,
                    COUNT(*) AS total_count
                 FROM marketing_execution_queue
                 WHERE workspace_id = ?",
                [$this->workspaceId()]
            ) ?: [])
            : ['blocked_count' => 0, 'live_count' => 0, 'total_count' => 0];
        $mediaIssueCount = (int) ($mediaCounts['missing_alt_text'] ?? 0)
            + (int) ($mediaCounts['expired_rights'] ?? 0)
            + (int) ($mediaCounts['blocked_media'] ?? 0)
            + (int) ($mediaCounts['unsafe_urls'] ?? 0);
        $starterTotal = (int) ($diagnostics['starter_pack']['total'] ?? 0);

        $aiReady = (string) ($aiReadiness['status'] ?? 'attention') === 'ready'
            && (string) ($aiReadiness['operating_status'] ?? 'attention') === 'ready'
            && (string) ($aiReadiness['creative_status'] ?? 'attention') === 'ready';
        $connectorSafe = empty($connectorDiagnostics['live_execution_enabled']) && !empty($connectorDiagnostics['secret_safe']);
        $executionWarnings = (int) ($executionCounts['blocked_count'] ?? 0) + (int) ($executionCounts['live_count'] ?? 0);

        return [
            [
                'key' => 'latest_migration',
                'label' => 'Latest migration',
                'status' => (string) ($latestMigration['migration_name'] ?? '') === '337_create_marketing_tracking_foundation.sql' ? 'ready' : 'warning',
                'message' => $latestMigration ? 'Latest recorded migration: ' . (string) $latestMigration['migration_name'] : 'Migration table is unavailable.',
                'metadata' => ['migration' => $latestMigration],
            ],
            [
                'key' => 'required_tables',
                'label' => 'Required release tables',
                'status' => $missingTables === [] ? 'ready' : 'blocked',
                'message' => $missingTables === [] ? 'All required Marketing release tables are present.' : 'Missing required tables: ' . implode(', ', $missingTables),
                'metadata' => ['missing_tables' => $missingTables],
            ],
            [
                'key' => 'ai_registry',
                'label' => 'AI prompt registry',
                'status' => $aiReady ? 'ready' : 'warning',
                'message' => $aiReady ? 'Marketing AI prompt registry is seeded for draft-side use.' : 'One or more Marketing AI prompt sets need review.',
                'metadata' => [
                    'status' => $aiReadiness['status'] ?? null,
                    'operating_status' => $aiReadiness['operating_status'] ?? null,
                    'creative_status' => $aiReadiness['creative_status'] ?? null,
                ],
            ],
            [
                'key' => 'connector_safety',
                'label' => 'Connector safety',
                'status' => $connectorSafe ? 'ready' : 'blocked',
                'message' => $connectorSafe ? 'Connector diagnostics are secret-safe and live execution remains disabled.' : 'Connector diagnostics need review before any live execution path.',
                'metadata' => $connectorDiagnostics,
            ],
            [
                'key' => 'execution_queue',
                'label' => 'Execution queue guardrails',
                'status' => $executionWarnings > 0 ? 'warning' : 'ready',
                'message' => $executionWarnings > 0 ? 'Execution queue has blocked or live-mode items that need operator review.' : 'Execution queue has no blocked or live-mode items.',
                'metadata' => $executionCounts,
            ],
            [
                'key' => 'media_governance',
                'label' => 'Media governance',
                'status' => $mediaIssueCount > 0 ? 'warning' : 'ready',
                'message' => $mediaIssueCount > 0 ? 'Media diagnostics found accessibility, rights, blocked media, or unsafe URL issues.' : 'Media diagnostics have no release-blocking issues.',
                'metadata' => ['issue_count' => $mediaIssueCount, 'counts' => $mediaCounts],
            ],
            [
                'key' => 'demo_cleanup',
                'label' => 'Demo and starter cleanup',
                'status' => $starterTotal > 0 ? 'warning' : 'ready',
                'message' => $starterTotal > 0 ? 'Starter/demo records are present; preview cleanup before real workspace use.' : 'No starter/demo records require cleanup.',
                'metadata' => $diagnostics['starter_pack'] ?? [],
            ],
            [
                'key' => 'operator_reporting',
                'label' => 'Operator reporting',
                'status' => $missingTables === [] ? 'ready' : 'blocked',
                'message' => Database::tableExists('marketing_report_exports') ? 'Report export and scheduled draft tables are available.' : 'Operator report export table is missing.',
                'metadata' => [
                    'exports' => Database::tableExists('marketing_report_exports') ? $this->countRows('marketing_report_exports', 'id > 0') : 0,
                    'scheduled_drafts' => Database::tableExists('marketing_scheduled_report_drafts') ? $this->countRows('marketing_scheduled_report_drafts', 'id > 0') : 0,
                ],
            ],
            [
                'key' => 'diagnostic_secrecy',
                'label' => 'No-secret diagnostics',
                'status' => 'ready',
                'message' => 'Diagnostics expose counts, statuses, and sanitized metadata only.',
                'metadata' => ['stack_traces' => false, 'passwords' => false, 'tokens' => false],
            ],
        ];
    }

    private function sanitizeTrackingUrl(string $url): string
    {
        $url = trim($url);
        if ($url === '') {
            return '';
        }
        if (mb_strlen($url) > 700) {
            $url = mb_substr($url, 0, 700);
        }
        if (preg_match('#^https?://#i', $url) !== 1 && !str_starts_with($url, '/')) {
            return '';
        }

        return Security::sanitizeInput($url, 'string');
    }

    /**
     * @return array<string,string|null>
     */
    private function trackingUtmParams(array $data, string $pageUrl): array
    {
        $params = [];
        if ($pageUrl !== '') {
            $query = parse_url($pageUrl, PHP_URL_QUERY);
            if (is_string($query) && $query !== '') {
                parse_str($query, $params);
            }
        }

        $utm = [];
        foreach (['utm_source', 'utm_medium', 'utm_campaign', 'utm_term', 'utm_content'] as $key) {
            $value = (string) ($data[$key] ?? $params[$key] ?? '');
            $value = Security::sanitizeInput($value, 'string');
            $utm[$key] = $value !== '' ? mb_substr($value, 0, $key === 'utm_campaign' || $key === 'utm_term' || $key === 'utm_content' ? 160 : 120) : null;
        }

        return $utm;
    }

    private function normalizeTrackingSessionKey(string $value): string
    {
        $value = preg_replace('/[^a-zA-Z0-9_-]/', '', $value) ?: '';
        if ($value === '') {
            $value = bin2hex(random_bytes(16));
        }

        return mb_substr($value, 0, 80);
    }

    /**
     * @param array<string,string|null> $utm
     * @param array<string,string> $requestContext
     */
    private function upsertMarketingVisitorSession(int $workspaceId, int $landingPageId, string $sessionKey, array $utm, array $requestContext): int
    {
        $ipHash = trim((string) ($requestContext['ip_address'] ?? '')) !== ''
            ? hash('sha256', trim((string) $requestContext['ip_address']))
            : null;
        $userAgentHash = trim((string) ($requestContext['user_agent'] ?? '')) !== ''
            ? hash('sha256', trim((string) $requestContext['user_agent']))
            : null;
        $metadata = [
            'tracking_scope' => 'marketing_landing_page',
            'raw_ip_stored' => false,
            'raw_user_agent_stored' => false,
        ];

        Database::execute(
            "INSERT INTO marketing_visitor_sessions
                (workspace_id, landing_page_id, uuid, session_key, first_utm_source, first_utm_medium,
                 first_utm_campaign, first_referrer, ip_hash, user_agent_hash, metadata_json, first_seen_at, last_seen_at)
             VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, NOW(), NOW())
             ON DUPLICATE KEY UPDATE
                id = LAST_INSERT_ID(id),
                landing_page_id = COALESCE(landing_page_id, VALUES(landing_page_id)),
                last_seen_at = NOW(),
                updated_at = NOW()",
            [
                $workspaceId,
                $landingPageId,
                $this->generateUuid(),
                $sessionKey,
                $utm['utm_source'] ?? null,
                $utm['utm_medium'] ?? null,
                $utm['utm_campaign'] ?? null,
                $this->sanitizeTrackingUrl((string) ($requestContext['referrer'] ?? '')) ?: null,
                $ipHash,
                $userAgentHash,
                $this->normalizeJsonValue($metadata),
            ]
        );

        return (int) Database::lastInsertId();
    }

    /**
     * @param array<string,string|null> $utm
     */
    private function resolveTrackingUtmLinkId(int $workspaceId, array $utm, string $pageUrl): ?int
    {
        if (!Database::tableExists('marketing_utm_links')) {
            return null;
        }
        if ($pageUrl !== '') {
            $row = Database::queryOne(
                "SELECT id FROM marketing_utm_links WHERE workspace_id = ? AND (generated_url = ? OR url = ?) LIMIT 1",
                [$workspaceId, $pageUrl, $pageUrl]
            );
            if ($row) {
                return (int) ($row['id'] ?? 0) ?: null;
            }
        }

        $source = (string) ($utm['utm_source'] ?? '');
        $medium = (string) ($utm['utm_medium'] ?? '');
        $campaign = (string) ($utm['utm_campaign'] ?? '');
        if ($source === '' && $medium === '' && $campaign === '') {
            return null;
        }

        $row = Database::queryOne(
            "SELECT id
             FROM marketing_utm_links
             WHERE workspace_id = ?
               AND (? = '' OR utm_source = ?)
               AND (? = '' OR utm_medium = ?)
               AND (? = '' OR utm_campaign = ?)
             ORDER BY created_at DESC
             LIMIT 1",
            [$workspaceId, $source, $source, $medium, $medium, $campaign, $campaign]
        );

        return $row ? ((int) ($row['id'] ?? 0) ?: null) : null;
    }

    private function normalizeTrackingOccurredAt(string $value): string
    {
        $value = trim($value);
        if ($value === '') {
            return date('Y-m-d H:i:s');
        }
        $value = str_replace('T', ' ', substr($value, 0, 19));
        $parsed = \DateTimeImmutable::createFromFormat('!Y-m-d H:i:s', $value)
            ?: \DateTimeImmutable::createFromFormat('!Y-m-d H:i', substr($value, 0, 16));
        if (!$parsed) {
            return date('Y-m-d H:i:s');
        }

        return $parsed->format('Y-m-d H:i:s');
    }

    private function recordLandingPageView(
        int $workspaceId,
        int $landingPageId,
        int $visitorSessionId,
        int $eventId,
        string $token,
        string $pageUrl,
        string $referrer,
        string $occurredAt
    ): void {
        if (!Database::tableExists('marketing_landing_page_views')) {
            return;
        }

        Database::execute(
            "INSERT INTO marketing_landing_page_views
             (workspace_id, landing_page_id, visitor_session_id, tracking_event_id, uuid, public_token_hash, page_url, referrer, occurred_at)
             VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)",
            [
                $workspaceId,
                $landingPageId,
                $visitorSessionId,
                $eventId,
                $this->generateUuid(),
                $token !== '' ? hash('sha256', $token) : null,
                $pageUrl !== '' ? $pageUrl : null,
                $referrer !== '' ? $referrer : null,
                $occurredAt,
            ]
        );
    }

    private function recordCtaClick(int $workspaceId, int $landingPageId, int $visitorSessionId, int $eventId, array $data, string $occurredAt): void
    {
        if (!Database::tableExists('marketing_cta_clicks')) {
            return;
        }

        Database::execute(
            "INSERT INTO marketing_cta_clicks
             (workspace_id, landing_page_id, visitor_session_id, tracking_event_id, uuid, cta_label, cta_destination, occurred_at)
             VALUES (?, ?, ?, ?, ?, ?, ?, ?)",
            [
                $workspaceId,
                $landingPageId,
                $visitorSessionId,
                $eventId,
                $this->generateUuid(),
                mb_substr(Security::sanitizeInput((string) ($data['cta_label'] ?? 'CTA'), 'string'), 0, 180),
                $this->sanitizeTrackingUrl((string) ($data['cta_destination'] ?? '')) ?: null,
                $occurredAt,
            ]
        );
    }

    private function recordConversionEvent(int $workspaceId, int $landingPageId, int $visitorSessionId, int $eventId, int $formId, array $data, string $occurredAt): ?int
    {
        if (!Database::tableExists('marketing_conversion_events')) {
            return null;
        }

        $contactId = (int) ($data['contact_id'] ?? 0);
        if ($contactId > 0) {
            $this->assertWorkspaceRecord('contacts', $contactId, $workspaceId);
        }
        $dealId = (int) ($data['deal_id'] ?? 0);
        if ($dealId > 0) {
            $this->assertWorkspaceRecord('deals', $dealId, $workspaceId);
        }
        $conversionType = $this->normalizeEnum((string) ($data['conversion_type'] ?? (($data['event_type'] ?? '') === 'form_submit' ? 'form_submit' : 'lead_capture')), self::CONVERSION_EVENT_TYPES, 'conversion_type');
        $conversionValue = trim((string) ($data['conversion_value'] ?? ''));

        Database::execute(
            "INSERT INTO marketing_conversion_events
             (workspace_id, landing_page_id, visitor_session_id, tracking_event_id, form_id, contact_id, deal_id,
              uuid, conversion_type, conversion_value, metadata_json, occurred_at)
             VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)",
            [
                $workspaceId,
                $landingPageId,
                $visitorSessionId,
                $eventId,
                $formId > 0 ? $formId : null,
                $contactId > 0 ? $contactId : null,
                $dealId > 0 ? $dealId : null,
                $this->generateUuid(),
                $conversionType,
                is_numeric($conversionValue) ? round((float) $conversionValue, 2) : null,
                $this->normalizeJsonValue($this->sanitizeFlexibleArray($data['conversion_metadata'] ?? [])),
                $occurredAt,
            ]
        );

        return (int) Database::lastInsertId();
    }

    private function recordAttributionForTrackingEvent(
        int $workspaceId,
        int $landingPageId,
        int $visitorSessionId,
        int $eventId,
        int $campaignId,
        int $contentItemId,
        int $formId,
        ?int $utmLinkId,
        string $eventType,
        array $utm,
        array $data,
        string $occurredAt
    ): void {
        if (!Database::tableExists('marketing_attribution_touchpoints')) {
            return;
        }

        $contactId = (int) ($data['contact_id'] ?? 0);
        if ($contactId > 0) {
            $this->assertWorkspaceRecord('contacts', $contactId, $workspaceId);
        }
        $dealId = (int) ($data['deal_id'] ?? 0);
        if ($dealId > 0) {
            $this->assertWorkspaceRecord('deals', $dealId, $workspaceId);
        }

        $source = mb_substr(Security::sanitizeInput((string) ($utm['utm_source'] ?? $data['source'] ?? ''), 'string'), 0, 120);
        $medium = mb_substr(Security::sanitizeInput((string) ($utm['utm_medium'] ?? $data['medium'] ?? ''), 'string'), 0, 120);
        $campaignName = mb_substr(Security::sanitizeInput((string) ($utm['utm_campaign'] ?? $data['campaign_name'] ?? ''), 'string'), 0, 160);
        $channel = mb_substr(Security::sanitizeInput((string) ($data['channel'] ?? $medium ?: $eventType), 'string'), 0, 80);
        $modelCandidate = strtolower(trim((string) ($data['attribution_model'] ?? 'linear')));
        $model = in_array($modelCandidate, self::ATTRIBUTION_MODELS, true) ? $modelCandidate : 'linear';
        $weight = (float) ($data['touchpoint_weight'] ?? 1);
        if ($weight <= 0 || $weight > 1) {
            $weight = 1;
        }
        $metadata = $this->sanitizeFlexibleArray($data['attribution_metadata'] ?? $data['metadata'] ?? []);
        $metadata['source'] = 'marketing_attribution_pipeline';
        $metadata['tracking_event_type'] = $eventType;
        $metadata['manual_first_boundary'] = true;

        $existingSessionTouches = (int) (Database::queryOne(
            "SELECT COUNT(*) AS count
             FROM marketing_attribution_touchpoints
             WHERE workspace_id = ? AND visitor_session_id = ?",
            [$workspaceId, $visitorSessionId]
        )['count'] ?? 0);
        $touchpointType = match ($eventType) {
            'page_view' => $existingSessionTouches === 0 ? 'first_touch' : 'assist',
            'cta_click', 'form_start', 'custom' => 'assist',
            'form_submit', 'conversion' => 'conversion',
            default => 'assist',
        };

        if ($touchpointType === 'conversion') {
            $this->attachAttributionIdentityToSession($workspaceId, $visitorSessionId, $contactId, $dealId);
        }

        $this->insertMarketingAttributionTouchpoint([
            'workspace_id' => $workspaceId,
            'visitor_session_id' => $visitorSessionId,
            'tracking_event_id' => $eventId,
            'landing_page_id' => $landingPageId,
            'campaign_id' => $campaignId > 0 ? $campaignId : null,
            'content_item_id' => $contentItemId > 0 ? $contentItemId : null,
            'form_id' => $formId > 0 ? $formId : null,
            'utm_link_id' => $utmLinkId > 0 ? $utmLinkId : null,
            'contact_id' => $contactId > 0 ? $contactId : null,
            'deal_id' => $dealId > 0 ? $dealId : null,
            'touchpoint_type' => $touchpointType,
            'attribution_model' => $model,
            'source' => $source !== '' ? $source : null,
            'medium' => $medium !== '' ? $medium : null,
            'campaign_name' => $campaignName !== '' ? $campaignName : null,
            'channel' => $channel !== '' ? $channel : null,
            'touchpoint_weight' => $weight,
            'revenue_amount' => null,
            'metadata_json' => $metadata,
            'occurred_at' => $occurredAt,
        ]);

        if ($touchpointType === 'conversion') {
            $revenueAmount = $this->resolveAttributionRevenueAmount($workspaceId, $dealId, $data);
            if ($revenueAmount !== null && $revenueAmount > 0) {
                $revenueMetadata = $metadata;
                $revenueMetadata['conversion_value_source'] = is_numeric((string) ($data['conversion_value'] ?? '')) ? 'tracking_payload' : 'linked_deal';
                $this->insertMarketingAttributionTouchpoint([
                    'workspace_id' => $workspaceId,
                    'visitor_session_id' => $visitorSessionId,
                    'tracking_event_id' => $eventId,
                    'landing_page_id' => $landingPageId,
                    'campaign_id' => $campaignId > 0 ? $campaignId : null,
                    'content_item_id' => $contentItemId > 0 ? $contentItemId : null,
                    'form_id' => $formId > 0 ? $formId : null,
                    'utm_link_id' => $utmLinkId > 0 ? $utmLinkId : null,
                    'contact_id' => $contactId > 0 ? $contactId : null,
                    'deal_id' => $dealId > 0 ? $dealId : null,
                    'touchpoint_type' => 'revenue',
                    'attribution_model' => $model,
                    'source' => $source !== '' ? $source : null,
                    'medium' => $medium !== '' ? $medium : null,
                    'campaign_name' => $campaignName !== '' ? $campaignName : null,
                    'channel' => $channel !== '' ? $channel : null,
                    'touchpoint_weight' => $weight,
                    'revenue_amount' => $revenueAmount,
                    'metadata_json' => $revenueMetadata,
                    'occurred_at' => $occurredAt,
                ]);
            }
        }
    }

    private function insertMarketingAttributionTouchpoint(array $data): int
    {
        Database::execute(
            "INSERT INTO marketing_attribution_touchpoints
             (workspace_id, uuid, visitor_session_id, tracking_event_id, landing_page_id, campaign_id, content_item_id,
              form_id, utm_link_id, contact_id, deal_id, touchpoint_type, attribution_model, source, medium,
              campaign_name, channel, touchpoint_weight, revenue_amount, metadata_json, occurred_at)
             VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)",
            [
                (int) $data['workspace_id'],
                $this->generateUuid(),
                $data['visitor_session_id'] ?? null,
                $data['tracking_event_id'] ?? null,
                $data['landing_page_id'] ?? null,
                $data['campaign_id'] ?? null,
                $data['content_item_id'] ?? null,
                $data['form_id'] ?? null,
                $data['utm_link_id'] ?? null,
                $data['contact_id'] ?? null,
                $data['deal_id'] ?? null,
                $this->normalizeEnum((string) ($data['touchpoint_type'] ?? 'assist'), self::ATTRIBUTION_TOUCHPOINT_TYPES, 'touchpoint_type'),
                $this->normalizeEnum((string) ($data['attribution_model'] ?? 'linear'), self::ATTRIBUTION_MODELS, 'attribution_model'),
                $data['source'] ?? null,
                $data['medium'] ?? null,
                $data['campaign_name'] ?? null,
                $data['channel'] ?? null,
                round((float) ($data['touchpoint_weight'] ?? 1), 4),
                isset($data['revenue_amount']) ? round((float) $data['revenue_amount'], 2) : null,
                $this->normalizeJsonValue($this->sanitizeFlexibleArray($data['metadata_json'] ?? [])),
                (string) ($data['occurred_at'] ?? date('Y-m-d H:i:s')),
            ]
        );

        return (int) Database::lastInsertId();
    }

    private function attachAttributionIdentityToSession(int $workspaceId, int $visitorSessionId, int $contactId, int $dealId): void
    {
        $set = [];
        $params = [];
        if ($contactId > 0) {
            $set[] = 'contact_id = COALESCE(contact_id, ?)';
            $params[] = $contactId;
        }
        if ($dealId > 0) {
            $set[] = 'deal_id = COALESCE(deal_id, ?)';
            $params[] = $dealId;
        }
        if ($set === []) {
            return;
        }

        $params[] = $workspaceId;
        $params[] = $visitorSessionId;
        Database::execute(
            "UPDATE marketing_attribution_touchpoints
             SET " . implode(', ', $set) . ", updated_at = NOW()
             WHERE workspace_id = ? AND visitor_session_id = ?",
            $params
        );
    }

    private function resolveAttributionRevenueAmount(int $workspaceId, int $dealId, array $data): ?float
    {
        $conversionValue = trim((string) ($data['conversion_value'] ?? ''));
        if ($conversionValue !== '' && is_numeric($conversionValue)) {
            return round(max(0, (float) $conversionValue), 2);
        }
        if ($dealId <= 0 || !Database::tableExists('deals')) {
            return null;
        }

        $row = Database::queryOne(
            "SELECT value FROM deals WHERE workspace_id = ? AND id = ? LIMIT 1",
            [$workspaceId, $dealId]
        );
        if (!$row || !is_numeric((string) ($row['value'] ?? ''))) {
            return null;
        }

        return round(max(0, (float) $row['value']), 2);
    }

    private function nullableSanitizedText(mixed $value): ?string
    {
        $value = trim((string) $value);
        return $value !== '' ? Security::sanitizeInput($value, 'string') : null;
    }

    private function storeMarketingMediaUpload(array $file): array
    {
        $error = (int) ($file['error'] ?? UPLOAD_ERR_NO_FILE);
        if ($error !== UPLOAD_ERR_OK) {
            throw new \InvalidArgumentException('Media upload failed or no file was selected.');
        }

        $tmpName = (string) ($file['tmp_name'] ?? '');
        $originalName = (string) ($file['name'] ?? 'media-file');
        if ($tmpName === '' || !is_file($tmpName)) {
            throw new \InvalidArgumentException('Uploaded media file could not be read.');
        }

        $fileSize = (int) ($file['size'] ?? filesize($tmpName));
        if ($fileSize <= 0 || $fileSize > self::MEDIA_UPLOAD_MAX_BYTES) {
            throw new \InvalidArgumentException('Media file exceeds the 50 MB upload limit.');
        }

        $extension = strtolower(pathinfo($originalName, PATHINFO_EXTENSION));
        if (!in_array($extension, self::MEDIA_UPLOAD_EXTENSIONS, true)) {
            throw new \InvalidArgumentException('Unsupported media file type.');
        }

        $mimeType = $this->detectMimeType($tmpName, (string) ($file['type'] ?? ''));
        $mediaType = $this->mediaTypeFromMimeAndExtension($mimeType, $extension);
        $workspaceId = $this->workspaceId();
        $uuid = $this->generateUuid();
        $targetDirectory = dirname(__DIR__) . '/uploads/marketing/media/' . $workspaceId;
        if (!is_dir($targetDirectory) && !mkdir($targetDirectory, 0775, true) && !is_dir($targetDirectory)) {
            throw new RuntimeException('Unable to create marketing media upload directory.');
        }

        $targetName = $uuid . '.' . $extension;
        $targetPath = $targetDirectory . '/' . $targetName;
        $moved = is_uploaded_file($tmpName)
            ? move_uploaded_file($tmpName, $targetPath)
            : rename($tmpName, $targetPath);
        if (!$moved) {
            throw new RuntimeException('Unable to store uploaded marketing media.');
        }

        $dimensions = [];
        if ($mediaType === 'image') {
            $size = @getimagesize($targetPath);
            if (is_array($size)) {
                $dimensions = ['width' => (int) ($size[0] ?? 0), 'height' => (int) ($size[1] ?? 0)];
            }
        }

        return [
            'file_path' => 'uploads/marketing/media/' . $workspaceId . '/' . $targetName,
            'source_url' => null,
            'mime_type' => $mimeType,
            'file_size' => $fileSize,
            'media_type' => $mediaType,
            'width' => $dimensions['width'] ?? null,
            'height' => $dimensions['height'] ?? null,
            'metadata_json' => [
                'original_name' => Security::sanitizeInput($originalName, 'string'),
                'stored_at' => date('c'),
            ],
        ];
    }

    private function detectMimeType(string $path, string $fallback = ''): string
    {
        $mime = '';
        if (function_exists('finfo_open')) {
            $finfo = finfo_open(FILEINFO_MIME_TYPE);
            if ($finfo) {
                $mime = (string) finfo_file($finfo, $path);
                finfo_close($finfo);
            }
        }

        return $mime !== '' ? $mime : Security::sanitizeInput($fallback, 'string');
    }

    private function mediaTypeFromMimeAndExtension(string $mimeType, string $extension): string
    {
        if (str_starts_with($mimeType, 'image/')) {
            return 'image';
        }
        if (str_starts_with($mimeType, 'video/')) {
            return 'video';
        }
        if (str_starts_with($mimeType, 'audio/')) {
            return 'audio';
        }
        if (in_array($extension, ['pdf', 'doc', 'docx', 'ppt', 'pptx'], true)) {
            return 'document';
        }

        return 'other';
    }

    private function sanitizeMediaPath(?string $path): ?string
    {
        if ($path === null) {
            return null;
        }
        $path = str_replace('\\', '/', trim($path));
        if ($path === '' || str_contains($path, '..') || preg_match('#^[a-z]+:#i', $path) === 1) {
            throw new \InvalidArgumentException('Media file paths must be relative safe paths.');
        }

        return $path;
    }

    private function isSafeMediaUrl(string $url): bool
    {
        return preg_match('#^https?://#i', trim($url)) === 1 && filter_var($url, FILTER_VALIDATE_URL) !== false;
    }

    private function hydrateJsonFields(array $row, array $fields): array
    {
        foreach ($fields as $field) {
            $row[$field] = !empty($row[$field]) && is_string($row[$field])
                ? (json_decode($row[$field], true) ?: [])
                : (is_array($row[$field] ?? null) ? $row[$field] : []);
        }

        return $row;
    }

    private function hydrateChannelMediaKitRow(array $row): array
    {
        $row = $this->hydrateJsonFields($row, [
            'required_dimensions_json',
            'aspect_ratios_json',
            'copy_fields_json',
            'media_slots_json',
            'destination_rules_json',
            'export_checklist_json',
            'readiness_json',
            'export_payload_json',
            'metadata_json',
        ]);
        $row['primary_media_display_url'] = $this->mediaDisplayUrl([
            'source_url' => $row['primary_media_source_url'] ?? '',
            'file_path' => $row['primary_media_file_path'] ?? '',
        ]);

        return $row;
    }

    private function hydrateAiMediaRequestRow(array $row): array
    {
        return $this->hydrateJsonFields($row, [
            'prompt_json',
            'context_json',
            'provider_json',
            'result_json',
        ]);
    }

    private function normalizeAiMediaRequestData(array $data, bool $forCreate): array
    {
        $workspaceId = $this->workspaceId();
        $normalized = [];
        if ($forCreate || array_key_exists('title', $data)) {
            $title = Security::sanitizeInput((string) ($data['title'] ?? ''), 'string');
            if ($title === '') {
                throw new \InvalidArgumentException('AI media request title is required.');
            }
            $normalized['title'] = $title;
        }
        if ($forCreate || array_key_exists('request_type', $data)) {
            $normalized['request_type'] = $this->normalizeEnum((string) ($data['request_type'] ?? 'image'), self::AI_MEDIA_REQUEST_TYPES, 'ai_media_request_type');
        }
        if ($forCreate || array_key_exists('status', $data)) {
            $normalized['status'] = $this->normalizeEnum((string) ($data['status'] ?? 'draft'), self::AI_MEDIA_REQUEST_STATUSES, 'ai_media_status');
        }

        foreach ([
            'content_item_id' => 'marketing_content_items',
            'landing_page_id' => 'marketing_landing_pages',
            'creative_brief_id' => 'marketing_creative_briefs',
            'asset_request_id' => 'marketing_asset_requests',
            'accepted_media_file_id' => 'marketing_media_files',
        ] as $field => $table) {
            if ($forCreate || array_key_exists($field, $data)) {
                $id = (int) ($data[$field] ?? 0);
                if ($id > 0) {
                    $this->assertWorkspaceRecord($table, $id, $workspaceId);
                    $normalized[$field] = $id;
                } else {
                    $normalized[$field] = null;
                }
            }
        }

        if ($forCreate || array_key_exists('prompt_text', $data)) {
            $normalized['prompt_text'] = $this->nullableSanitizedText($data['prompt_text'] ?? '');
        }
        foreach (['prompt_json', 'context_json', 'provider_json', 'result_json'] as $field) {
            if ($forCreate || array_key_exists($field, $data)) {
                $normalized[$field] = $this->normalizeJsonValue($this->sanitizeJsonCompatible($data[$field] ?? []));
            }
        }
        if ($forCreate) {
            $normalized['created_by'] = (int) ($data['created_by'] ?? ($_SESSION['user_id'] ?? 0)) ?: null;
        }

        return $normalized;
    }

    private function createAiMediaOutput(array $data): int
    {
        $requestId = (int) ($data['request_id'] ?? 0);
        $request = $requestId > 0 ? $this->getAiMediaRequest($requestId) : null;
        if (!$request) {
            throw new RuntimeException('Marketing AI media request not found.');
        }
        $outputType = $this->normalizeEnum((string) ($data['output_type'] ?? 'prompt'), self::AI_MEDIA_OUTPUT_TYPES, 'ai_media_output_type');
        $status = $this->normalizeEnum((string) ($data['status'] ?? 'generated'), self::AI_MEDIA_OUTPUT_STATUSES, 'ai_media_output_status');
        $outputUrl = $this->nullableSanitizedText($data['output_url'] ?? '');
        if ($outputUrl !== null && !$this->isSafeMediaUrl($outputUrl)) {
            throw new \InvalidArgumentException('AI media output URLs must start with http or https.');
        }

        Database::execute(
            "INSERT INTO marketing_ai_media_outputs
             (workspace_id, request_id, uuid, output_type, status, title, prompt_text, output_url, output_json, accepted_media_file_id, created_by)
             VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)",
            [
                $this->workspaceId(),
                $requestId,
                $this->generateUuid(),
                $outputType,
                $status,
                $this->nullableSanitizedText($data['title'] ?? ''),
                $this->nullableSanitizedText($data['prompt_text'] ?? ''),
                $outputUrl,
                $this->normalizeJsonValue($this->sanitizeJsonCompatible($data['output_json'] ?? [])),
                !empty($data['accepted_media_file_id']) ? (int) $data['accepted_media_file_id'] : null,
                (int) ($data['created_by'] ?? ($_SESSION['user_id'] ?? 0)) ?: null,
            ]
        );

        return (int) Database::lastInsertId();
    }

    private function buildAiMediaBridgeContext(array $request, array $linkedRecords): array
    {
        $recentMedia = array_map(
            static fn(array $media): array => [
                'id' => (int) ($media['id'] ?? 0),
                'title' => (string) ($media['title'] ?? ''),
                'media_type' => (string) ($media['media_type'] ?? ''),
                'approval_status' => (string) ($media['approval_status'] ?? ''),
            ],
            $this->listMediaFiles([], 5, 0)
        );
        $brand = Database::tableExists('marketing_brand_profiles')
            ? (Database::queryOne(
                "SELECT name, voice, tone, value_props, proof_points, cta_defaults
                 FROM marketing_brand_profiles
                 WHERE workspace_id = ?
                 ORDER BY updated_at DESC LIMIT 1",
                [$this->workspaceId()]
            ) ?: [])
            : [];
        $contextItems = Database::tableExists('marketing_context_items')
            ? Database::query(
                "SELECT item_type, title, body
                 FROM marketing_context_items
                 WHERE workspace_id = ? AND status = 'active'
                 ORDER BY updated_at DESC LIMIT 8",
                [$this->workspaceId()]
            )
            : [];

        return [
            'request' => [
                'title' => (string) ($request['title'] ?? ''),
                'request_type' => (string) ($request['request_type'] ?? 'image'),
                'prompt_text' => (string) ($request['prompt_text'] ?? ''),
            ],
            'brand_profile' => $this->sanitizeJsonCompatible($brand),
            'context_items' => $this->sanitizeJsonCompatible($contextItems),
            'linked_records' => [
                'content_title' => (string) ($linkedRecords['content_item']['title'] ?? ''),
                'landing_page_title' => (string) ($linkedRecords['landing_page']['title'] ?? ''),
                'creative_brief_title' => (string) ($linkedRecords['creative_brief']['title'] ?? ''),
                'asset_request_title' => (string) ($linkedRecords['asset_request']['title'] ?? ''),
            ],
            'recent_media' => $recentMedia,
            'manual_first_boundary' => [
                'external_generation' => false,
                'requires_explicit_acceptance' => true,
                'does_not_overwrite_records' => true,
            ],
        ];
    }

    private function fallbackAiMediaBridgeResult(array $request, array $context): array
    {
        $type = (string) ($request['request_type'] ?? 'image');
        $title = (string) ($request['title'] ?? 'AI media request');
        $prompt = trim((string) ($request['prompt_text'] ?? ''));
        $subject = $prompt !== '' ? $prompt : $title;
        $outputType = match ($type) {
            'video', 'storyboard' => 'storyboard',
            'thumbnail' => 'thumbnail_prompt',
            default => 'prompt',
        };
        $format = match ($type) {
            'banner' => 'wide banner concept with safe text space',
            'thumbnail' => 'thumbnail concept with one clear focal point',
            'video' => 'short video storyboard',
            'storyboard' => 'scene-by-scene storyboard',
            default => 'image prompt',
        };

        $generatedPrompt = "Create a {$format} for {$subject}. Ground the visual in the saved brand voice, approved offers, and linked campaign context. Keep it review-ready, accessible, and suitable for manual publishing.";
        $outputJson = [
            'recommended_prompt' => $generatedPrompt,
            'negative_prompt' => 'Avoid unsupported claims, misleading logos, cluttered text, inaccessible contrast, and anything that implies automatic publishing.',
            'visual_notes' => [
                'Show the customer outcome clearly.',
                'Leave space for channel-specific copy.',
                'Add alt text, captions, and usage rights before export.',
            ],
            'acceptance_note' => 'Accepting this output creates a reference media record only. It does not overwrite content, landing pages, or assets.',
            'external_generation' => false,
            'context_used' => [
                'brand_profile' => !empty($context['brand_profile']),
                'context_items' => count((array) ($context['context_items'] ?? [])),
                'linked_content' => (string) ($context['linked_records']['content_title'] ?? '') !== '',
                'linked_landing_page' => (string) ($context['linked_records']['landing_page_title'] ?? '') !== '',
            ],
        ];
        if ($outputType === 'storyboard') {
            $outputJson['scenes'] = [
                ['scene' => 'Problem', 'direction' => 'Show the audience situation without exaggeration.'],
                ['scene' => 'Solution', 'direction' => 'Show the offer, workflow, or proof in context.'],
                ['scene' => 'Action', 'direction' => 'Close with a clear manual CTA and caption-ready end frame.'],
            ];
        }

        return [
            'output_type' => $outputType,
            'output_title' => ucwords(str_replace('_', ' ', $type)) . ' concept for ' . $title,
            'prompt_text' => $generatedPrompt,
            'output_url' => null,
            'output_json' => $outputJson,
        ];
    }

    private function mediaTypeFromAiMediaRequestType(string $requestType): string
    {
        return match ($requestType) {
            'image' => 'image',
            'video' => 'video',
            'thumbnail' => 'thumbnail',
            'banner' => 'banner',
            'storyboard' => 'document',
            default => 'other',
        };
    }

    private function decodeJsonLike(mixed $value): array
    {
        if (is_array($value)) {
            return $value;
        }
        if (is_string($value) && trim($value) !== '') {
            $decoded = json_decode($value, true);
            return is_array($decoded) ? $decoded : [];
        }

        return [];
    }

    private function sanitizeJsonCompatible(mixed $value): array
    {
        if (is_string($value)) {
            $decoded = json_decode($value, true);
            $value = is_array($decoded) ? $decoded : [];
        }
        if (!is_array($value)) {
            return [];
        }

        $clean = [];
        foreach ($value as $key => $item) {
            $cleanKey = is_int($key)
                ? $key
                : (preg_replace('/[^a-zA-Z0-9_]/', '', (string) $key) ?: '');
            if ($cleanKey === '') {
                continue;
            }
            if (is_array($item)) {
                $clean[$cleanKey] = $this->sanitizeJsonCompatible($item);
            } elseif (is_bool($item) || is_int($item) || is_float($item) || $item === null) {
                $clean[$cleanKey] = $item;
            } else {
                $clean[$cleanKey] = Security::sanitizeInput((string) $item, 'string');
            }
        }

        return $clean;
    }

    private function hydrateLandingPageRow(array $row): array
    {
        $row = $this->hydrateJsonFields($row, [
            'body_sections_json',
            'section_media_json',
            'gallery_media_json',
            'theme_settings_json',
            'cta_variants_json',
            'form_blocks_json',
            'seo_controls_json',
            'social_preview_json',
            'cta_blocks_json',
            'proof_blocks_json',
            'faq_blocks_json',
            'metadata_json',
            'publication_readiness_json',
            'design_document_json',
            'design_validation_json',
        ]);

        $workspaceId = (int) ($row['workspace_id'] ?? $this->workspaceId());
        $mediaIds = [];
        foreach ([
            'hero_media_file_id',
            'social_preview_media_file_id',
            'cta_media_file_id',
            'proof_media_file_id',
            'testimonial_media_file_id',
        ] as $field) {
            $id = (int) ($row[$field] ?? 0);
            if ($id > 0) {
                $mediaIds[] = $id;
            }
        }
        foreach (['section_media_json', 'gallery_media_json'] as $jsonField) {
            foreach ((array) ($row[$jsonField] ?? []) as $entry) {
                $id = is_array($entry) ? (int) ($entry['media_file_id'] ?? 0) : (int) $entry;
                if ($id > 0) {
                    $mediaIds[] = $id;
                }
            }
        }
        foreach ((array) ($row['design_document_json']['blocks'] ?? []) as $block) {
            if (!is_array($block)) {
                continue;
            }
            $props = is_array($block['props'] ?? null) ? $block['props'] : [];
            $id = (int) ($props['media_file_id'] ?? 0);
            if ($id > 0) {
                $mediaIds[] = $id;
            }
            foreach (preg_split('/[^0-9]+/', (string) ($props['media_ids'] ?? '')) ?: [] as $mediaId) {
                if ((int) $mediaId > 0) {
                    $mediaIds[] = (int) $mediaId;
                }
            }
        }

        $mediaById = $this->mediaRowsById($workspaceId, $mediaIds);
        $row['_media'] = [
            'hero' => $mediaById[(int) ($row['hero_media_file_id'] ?? 0)] ?? null,
            'social_preview' => $mediaById[(int) ($row['social_preview_media_file_id'] ?? 0)] ?? null,
            'cta' => $mediaById[(int) ($row['cta_media_file_id'] ?? 0)] ?? null,
            'proof' => $mediaById[(int) ($row['proof_media_file_id'] ?? 0)] ?? null,
            'testimonial' => $mediaById[(int) ($row['testimonial_media_file_id'] ?? 0)] ?? null,
            'by_id' => $mediaById,
        ];

        return $row;
    }

    /**
     * @return array<int,array<string,mixed>>
     */
    private function mediaRowsById(int $workspaceId, array $mediaIds): array
    {
        $mediaIds = array_values(array_unique(array_filter(array_map('intval', $mediaIds))));
        if ($mediaIds === [] || !Database::tableExists('marketing_media_files')) {
            return [];
        }

        $placeholders = implode(',', array_fill(0, count($mediaIds), '?'));
        $rows = Database::query(
            "SELECT *
             FROM marketing_media_files
             WHERE workspace_id = ? AND id IN ({$placeholders})",
            array_merge([$workspaceId], $mediaIds)
        );

        $byId = [];
        foreach ($rows as $row) {
            $row = $this->hydrateJsonFields($row, ['tags_json', 'metadata_json']);
            $byId[(int) $row['id']] = $row;
        }

        return $byId;
    }

    private function normalizeJsonValue(mixed $value): ?string
    {
        if ($value === null || $value === '') {
            return null;
        }

        return is_string($value) ? $value : json_encode($value, JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE);
    }

    private function sanitizeFlexibleArray(mixed $value): array
    {
        if (is_string($value)) {
            $decoded = json_decode($value, true);
            $value = is_array($decoded) ? $decoded : [];
        }
        if (!is_array($value)) {
            return [];
        }

        $clean = [];
        foreach ($value as $key => $item) {
            $key = preg_replace('/[^a-zA-Z0-9_]/', '', (string) $key) ?: '';
            if ($key === '') {
                continue;
            }
            if (is_array($item)) {
                $clean[$key] = $this->sanitizeFlexibleArray($item);
            } elseif (is_bool($item) || is_int($item) || is_float($item) || $item === null) {
                $clean[$key] = $item;
            } else {
                $clean[$key] = Security::sanitizeInput((string) $item, 'string');
            }
        }

        return $clean;
    }

    private function workflowClosureForContent(array $item, array $flags): array
    {
        $reasons = [];
        $reasonKeys = [];
        $countKeys = [];
        $severity = 'ready';
        $status = (string) ($item['status'] ?? '');
        $draft = trim((string) ($item['draft_body'] ?? ''));
        $mediaReadiness = (array) ($item['_media_readiness'] ?? []);

        $add = static function (string $key, string $message, string $countKey, string $level) use (&$reasons, &$reasonKeys, &$countKeys, &$severity): void {
            $reasons[] = $message;
            $reasonKeys[] = $key;
            if ($countKey !== '') {
                $countKeys[] = $countKey;
            }
            $weights = ['ready' => 0, 'warning' => 1, 'overdue' => 2, 'blocked' => 3];
            if (($weights[$level] ?? 0) > ($weights[$severity] ?? 0)) {
                $severity = $level;
            }
        };

        if (trim((string) ($item['blocked_reason'] ?? '')) !== '') {
            $add('blocked_reason', 'Blocked: ' . (string) $item['blocked_reason'], 'blocked_content', 'blocked');
        }
        if ((string) ($item['dependency_status'] ?? 'clear') === 'blocked') {
            $add('dependency_blocked', 'A production dependency is blocked.', 'blocked_content', 'blocked');
        } elseif ((string) ($item['dependency_status'] ?? 'clear') === 'waiting') {
            $add('dependency_waiting', 'A production dependency is waiting on another owner.', '', 'warning');
        }
        if ($status === 'review' && empty($flags['has_pending_approval'])) {
            $add('missing_approval', 'Content is in review without an active approval request.', 'missing_approval', 'blocked');
        }
        if (trim((string) ($item['target_audience'] ?? '')) === '' && empty($item['persona_id'])) {
            $add('missing_audience', 'Missing audience or persona context.', 'missing_audience', 'warning');
        }
        if ($draft === '') {
            $add('blank_draft', 'Draft body is empty.', '', 'blocked');
        } elseif (!$this->textHasMarketingCta($draft)) {
            $add('missing_cta', 'Draft copy needs a clear CTA.', 'missing_cta', 'warning');
        }
        foreach ((array) ($item['required_context_warnings_json'] ?? []) as $warning) {
            $warning = trim((string) $warning);
            if ($warning !== '') {
                $add('context_' . preg_replace('/[^a-z0-9_]+/', '_', strtolower($warning)), 'Context warning: ' . ucwords(str_replace('_', ' ', $warning)) . '.', '', 'warning');
            }
        }
        if (!empty($mediaReadiness['warnings'])) {
            $add('media_readiness', 'Media readiness needs attention: ' . implode(', ', array_map(static fn(string $warning): string => ucwords(str_replace('_', ' ', $warning)), (array) ($mediaReadiness['warnings'] ?? []))), 'missing_media', 'warning');
        }
        if (in_array($status, ['approved', 'scheduled'], true) && empty($flags['has_distribution'])) {
            $add('missing_distribution', 'Approved content has no open manual distribution draft.', 'missing_distribution', 'warning');
        }
        if (!empty($item['campaign_id']) && empty($flags['has_utm'])) {
            $add('missing_utm', 'Campaign-linked content does not have a UTM link yet.', 'missing_utm', 'warning');
        }
        if (!empty($item['scheduled_at']) && strtotime((string) $item['scheduled_at']) !== false && strtotime((string) $item['scheduled_at']) < time() && !in_array($status, ['published', 'archived'], true)) {
            $add('schedule_overdue', 'Scheduled date has passed without publication evidence.', '', 'overdue');
        }

        $reasons = array_values(array_unique(array_filter($reasons)));
        $nextAction = trim((string) ($item['next_action'] ?? ''));
        if ($nextAction === '' && $reasons !== []) {
            $firstReason = (string) ($reasonKeys[0] ?? '');
            $nextAction = match ($firstReason) {
                'blocked_reason', 'dependency_blocked', 'dependency_waiting' => 'Resolve the blocker or production dependency.',
                'missing_approval' => 'Request or restore the approval workflow.',
                'missing_audience' => 'Add persona or target audience context.',
                'missing_cta' => 'Add a clear next-step CTA.',
                'media_readiness' => 'Attach, approve, or complete accessibility metadata for media.',
                'missing_distribution' => 'Create a manual distribution draft.',
                'missing_utm' => 'Generate a UTM link for the campaign/content pair.',
                default => 'Review the content workflow blockers.',
            };
        }

        return [
            'severity' => $severity,
            'reasons' => $reasons,
            'reason_keys' => array_values(array_unique($reasonKeys)),
            'count_keys' => array_values(array_unique($countKeys)),
            'next_action' => $nextAction,
        ];
    }

    private function textHasMarketingCta(string $text): bool
    {
        return preg_match('/\b(book|schedule|contact|download|start|reply|call|request|learn more|get|buy|subscribe|register|join|try)\b/i', $text) === 1;
    }

    private function clearSavedViewDefaults(string $viewType, int $userId, string $scope, ?int $exceptId = null): void
    {
        if (!Database::tableExists('marketing_saved_views')) {
            return;
        }

        $where = 'workspace_id = ? AND view_type = ? AND scope = ?';
        $params = [$this->workspaceId(), $viewType, $scope];
        if ($scope === 'private') {
            $where .= ' AND user_id = ?';
            $params[] = $userId;
        }
        if ($exceptId !== null) {
            $where .= ' AND id <> ?';
            $params[] = $exceptId;
        }

        Database::execute("UPDATE marketing_saved_views SET is_default = 0 WHERE {$where}", $params);
    }

    private function logBulkAction(string $action, string $targetType, int $targetCount, array $input, ?int $userId = null): void
    {
        if (!Database::tableExists('marketing_bulk_action_log')) {
            return;
        }

        Database::execute(
            "INSERT INTO marketing_bulk_action_log (workspace_id, uuid, action, target_type, target_count, input_json, created_by)
             VALUES (?, ?, ?, ?, ?, ?, ?)",
            [
                $this->workspaceId(),
                $this->generateUuid(),
                Security::sanitizeInput($action, 'string'),
                Security::sanitizeInput($targetType, 'string'),
                $targetCount,
                $this->normalizeJsonValue($input),
                ($userId ?? 0) > 0 ? $userId : null,
            ]
        );
    }

    private function normalizeStringListJson(mixed $value): ?string
    {
        if (is_string($value)) {
            $decoded = json_decode($value, true);
            $value = is_array($decoded) ? $decoded : preg_split('/[,\\r\\n]+/', $value);
        }
        $items = [];
        foreach ((array) $value as $item) {
            $item = Security::sanitizeInput((string) $item, 'string');
            if ($item !== '') {
                $items[] = $item;
            }
        }

        return $items === [] ? null : json_encode(array_values(array_unique($items)), JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE);
    }

    private function normalizeBodySectionsJson(mixed $value): ?string
    {
        if (is_string($value)) {
            $decoded = json_decode($value, true);
            $value = is_array($decoded) ? $decoded : preg_split('/\\r?\\n\\s*\\r?\\n/', $value);
        }

        $sections = [];
        foreach ((array) $value as $section) {
            if (is_array($section)) {
                $heading = $this->nullableSanitizedText($section['heading'] ?? '');
                $body = $this->nullableSanitizedText($section['body'] ?? '');
            } else {
                $heading = null;
                $body = $this->nullableSanitizedText($section);
            }
            if ($heading !== null || $body !== null) {
                $sections[] = ['heading' => $heading, 'body' => $body];
            }
        }

        return $sections === [] ? null : json_encode($sections, JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE);
    }

    private function normalizeLandingSectionMediaJson(mixed $value): ?string
    {
        if (is_string($value)) {
            $decoded = json_decode($value, true);
            $value = is_array($decoded) ? $decoded : preg_split('/\r?\n+/', $value);
        }

        $items = [];
        foreach ((array) $value as $entry) {
            if (is_array($entry)) {
                $heading = $this->nullableSanitizedText($entry['heading'] ?? $entry['section'] ?? '');
                $mediaId = (int) ($entry['media_file_id'] ?? $entry['media_id'] ?? 0);
                $placement = $this->nullableSanitizedText($entry['placement'] ?? 'inline') ?? 'inline';
                $caption = $this->nullableSanitizedText($entry['caption'] ?? '');
            } else {
                $parts = array_map('trim', explode('|', (string) $entry));
                $heading = $this->nullableSanitizedText($parts[0] ?? '');
                $mediaId = (int) ($parts[1] ?? 0);
                $placement = $this->nullableSanitizedText($parts[2] ?? 'inline') ?? 'inline';
                $caption = $this->nullableSanitizedText($parts[3] ?? '');
            }
            if ($mediaId <= 0) {
                continue;
            }
            $this->assertWorkspaceRecord('marketing_media_files', $mediaId, $this->workspaceId());
            $items[] = [
                'heading' => $heading,
                'media_file_id' => $mediaId,
                'placement' => $placement,
                'caption' => $caption,
            ];
        }

        return $items === [] ? null : json_encode($items, JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE);
    }

    private function normalizeLandingGalleryMediaJson(mixed $value): ?string
    {
        if (is_string($value)) {
            $decoded = json_decode($value, true);
            $value = is_array($decoded) ? $decoded : preg_split('/[,\\r\\n]+/', $value);
        }

        $items = [];
        foreach ((array) $value as $entry) {
            $mediaId = is_array($entry)
                ? (int) ($entry['media_file_id'] ?? $entry['media_id'] ?? 0)
                : (int) $entry;
            if ($mediaId <= 0) {
                continue;
            }
            $this->assertWorkspaceRecord('marketing_media_files', $mediaId, $this->workspaceId());
            $items[] = [
                'media_file_id' => $mediaId,
                'caption' => is_array($entry) ? $this->nullableSanitizedText($entry['caption'] ?? '') : null,
            ];
        }

        return $items === [] ? null : json_encode($items, JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE);
    }

    private function countContent(string $condition): int
    {
        $row = Database::queryOne(
            "SELECT COUNT(*) AS count FROM marketing_content_items WHERE workspace_id = ? AND {$condition}",
            [$this->workspaceId()]
        );

        return (int) ($row['count'] ?? 0);
    }

    private function databaseIndexExists(string $indexName): bool
    {
        $row = Database::queryOne(
            "SELECT 1
             FROM information_schema.statistics
             WHERE table_schema = DATABASE()
               AND index_name = ?
             LIMIT 1",
            [$indexName]
        );

        return (bool) $row;
    }

    private function starterPackCleanupPreview(): array
    {
        $state = $this->loadMarketingOnboardingState();
        $starterPack = $this->starterPackState($state);
        $runUuid = (string) ($starterPack['run_uuid'] ?? '');
        $workspaceId = $this->workspaceId();
        $tables = [];
        foreach ([
            'marketing_brand_profiles',
            'marketing_personas',
            'marketing_context_items',
            'marketing_campaign_briefs',
            'marketing_seo_topics',
            'marketing_landing_pages',
            'marketing_content_items',
        ] as $table) {
            $tables[$table] = $this->countStarterMetadataRows($table, $runUuid);
        }

        $calendarCount = 0;
        if (Database::tableExists('marketing_calendar_milestones')) {
            $row = Database::queryOne(
                "SELECT COUNT(*) AS count
                 FROM marketing_calendar_milestones
                 WHERE workspace_id = ?
                   AND (
                        campaign_brief_id IN (
                            SELECT id FROM marketing_campaign_briefs
                            WHERE workspace_id = ? AND JSON_UNQUOTE(JSON_EXTRACT(metadata_json, '$.starter_pack_run_uuid')) = ?
                        )
                        OR content_item_id IN (
                            SELECT id FROM marketing_content_items
                            WHERE workspace_id = ? AND JSON_UNQUOTE(JSON_EXTRACT(metadata_json, '$.starter_pack_run_uuid')) = ?
                        )
                   )",
                [$workspaceId, $workspaceId, $runUuid, $workspaceId, $runUuid]
            );
            $calendarCount = (int) ($row['count'] ?? 0);
        }
        $tables['marketing_calendar_milestones'] = $calendarCount;

        $distributionCount = 0;
        if (Database::tableExists('marketing_distribution_posts')) {
            $row = Database::queryOne(
                "SELECT COUNT(*) AS count
                 FROM marketing_distribution_posts
                 WHERE workspace_id = ?
                   AND content_item_id IN (
                        SELECT id FROM marketing_content_items
                        WHERE workspace_id = ? AND JSON_UNQUOTE(JSON_EXTRACT(metadata_json, '$.starter_pack_run_uuid')) = ?
                   )",
                [$workspaceId, $workspaceId, $runUuid]
            );
            $distributionCount = (int) ($row['count'] ?? 0);
        }
        $tables['marketing_distribution_posts'] = $distributionCount;

        return [
            'created' => !empty($starterPack['created']),
            'archived' => !empty($starterPack['archived']),
            'run_uuid' => $runUuid !== '' ? $runUuid : null,
            'tables' => $tables,
            'total' => array_sum($tables),
        ];
    }

    private function countStarterMetadataRows(string $table, string $runUuid): int
    {
        if ($runUuid === '' || !Database::tableExists($table) || !Database::columnExists($table, 'metadata_json')) {
            return 0;
        }

        $row = Database::queryOne(
            "SELECT COUNT(*) AS count
             FROM {$table}
             WHERE workspace_id = ?
               AND JSON_UNQUOTE(JSON_EXTRACT(metadata_json, '$.starter_pack_run_uuid')) = ?",
            [$this->workspaceId(), $runUuid]
        );

        return (int) ($row['count'] ?? 0);
    }

    private function markStarterMetadataArchived(string $runUuid): void
    {
        if ($runUuid === '') {
            return;
        }

        foreach (['marketing_brand_profiles', 'marketing_personas'] as $table) {
            if (!Database::tableExists($table) || !Database::columnExists($table, 'metadata_json')) {
                continue;
            }
            Database::execute(
                "UPDATE {$table}
                 SET metadata_json = JSON_SET(COALESCE(metadata_json, JSON_OBJECT()), '$.starter_pack_archived', true, '$.starter_pack_archived_at', ?)
                 WHERE workspace_id = ?
                   AND JSON_UNQUOTE(JSON_EXTRACT(metadata_json, '$.starter_pack_run_uuid')) = ?",
                [date('c'), $this->workspaceId(), $runUuid]
            );
        }
    }

    public function listMarketingCampaignOptions(int $limit = 100): array
    {
        $this->assertMarketingPermission('marketing.read');
        return $this->activeCampaigns($limit);
    }

    private function activeCampaigns(int $limit): array
    {
        if (!Database::tableExists('campaigns')) {
            return [];
        }

        return Database::query(
            "SELECT c.id, c.name, c.status,
                    (SELECT COUNT(*) FROM campaign_enrollments ce WHERE ce.campaign_id = c.id) AS enrollment_count
             FROM campaigns c
             WHERE c.workspace_id = ? AND c.status = 'active'
             ORDER BY c.updated_at DESC
             LIMIT {$limit}",
            [$this->workspaceId()]
        );
    }

    /**
     * @return array{0:string,1:string}
     */
    private function analyticsPeriod(string $periodType, ?string $anchorDate): array
    {
        $periodType = $this->normalizeEnum($periodType, ['weekly', 'monthly'], 'analytics_period');
        $anchor = $anchorDate ? strtotime($anchorDate) : time();
        if ($anchor === false) {
            $anchor = time();
        }

        if ($periodType === 'monthly') {
            return [date('Y-m-01', $anchor), date('Y-m-t', $anchor)];
        }

        return [date('Y-m-d', strtotime('monday this week', $anchor)), date('Y-m-d', strtotime('sunday this week', $anchor))];
    }

    private function formSubmissionAnalytics(string $start, string $end): array
    {
        if (!Database::tableExists('form_submissions') || !Database::columnExists('form_submissions', 'workspace_id')) {
            return ['total' => 0, 'top_forms' => []];
        }

        $dateColumn = Database::columnExists('form_submissions', 'submitted_at') ? 'submitted_at' : 'created_at';
        if (!Database::columnExists('form_submissions', $dateColumn)) {
            return ['total' => 0, 'top_forms' => []];
        }

        $total = Database::queryOne(
            "SELECT COUNT(*) AS count FROM form_submissions WHERE workspace_id = ? AND {$dateColumn} >= ? AND {$dateColumn} < DATE_ADD(?, INTERVAL 1 DAY)",
            [$this->workspaceId(), $start, $end]
        );

        return [
            'total' => (int) ($total['count'] ?? 0),
            'top_forms' => $this->topForms(5),
        ];
    }

    private function attributedRevenueAnalytics(string $start, string $end): array
    {
        if (!Database::tableExists('attribution_results') || !Database::columnExists('attribution_results', 'workspace_id')) {
            return ['total' => 0.0, 'by_campaign' => []];
        }

        $rows = Database::query(
            "SELECT c.id AS campaign_id, COALESCE(c.name, 'Unassigned Campaign') AS campaign_name,
                    SUM(ar.credited_value) AS credited_revenue
             FROM attribution_results ar
             LEFT JOIN campaigns c ON c.id = ar.campaign_id
             WHERE ar.workspace_id = ?
               AND ar.conversion_at >= ?
               AND ar.conversion_at < DATE_ADD(?, INTERVAL 1 DAY)
             GROUP BY c.id, c.name
             ORDER BY credited_revenue DESC",
            [$this->workspaceId(), $start, $end]
        );

        return [
            'total' => array_sum(array_map(static fn(array $row): float => (float) ($row['credited_revenue'] ?? 0), $rows)),
            'by_campaign' => $rows,
        ];
    }

    private function topForms(int $limit): array
    {
        if (!Database::tableExists('forms')) {
            return [];
        }

        $submittedAtFilter = Database::columnExists('form_submissions', 'submitted_at')
            ? 'AND fs.submitted_at >= DATE_SUB(NOW(), INTERVAL 30 DAY)'
            : '';

        return Database::query(
            "SELECT f.id, f.name,
                    (SELECT COUNT(*)
                     FROM form_submissions fs
                     WHERE fs.workspace_id = f.workspace_id
                       AND (fs.form_id = f.uuid OR fs.form_definition_id = f.id)
                       {$submittedAtFilter}) AS submission_count
             FROM forms f
             WHERE f.workspace_id = ?
             ORDER BY submission_count DESC, f.updated_at DESC
             LIMIT {$limit}",
            [$this->workspaceId()]
        );
    }

    private function recentAttributedRevenue(int $limit): array
    {
        if (!Database::tableExists('attribution_results') || !Database::columnExists('attribution_results', 'workspace_id')) {
            return [];
        }

        return Database::query(
            "SELECT c.id AS campaign_id, COALESCE(c.name, 'Unassigned Campaign') AS campaign_name,
                    SUM(ar.credited_value) AS credited_revenue
             FROM attribution_results ar
             LEFT JOIN campaigns c ON c.id = ar.campaign_id
             WHERE ar.workspace_id = ?
               AND ar.conversion_at >= DATE_SUB(NOW(), INTERVAL 30 DAY)
             GROUP BY c.id, c.name
             ORDER BY credited_revenue DESC
             LIMIT {$limit}",
            [$this->workspaceId()]
        );
    }

    private function hydrateContentItem(array $row): array
    {
        foreach (['ai_context_json', 'metadata_json', 'approval_checklist_json', 'required_context_warnings_json', 'production_checklist_json'] as $field) {
            $row[$field] = !empty($row[$field]) && is_string($row[$field])
                ? (json_decode($row[$field], true) ?: [])
                : (is_array($row[$field] ?? null) ? $row[$field] : []);
        }

        $attachments = [];
        if (!empty($row['id']) && Database::tableExists('marketing_content_media')) {
            $attachments = $this->listContentMedia((int) $row['id']);
        }
        $row['_media'] = $attachments;
        $row['_media_readiness'] = $this->contentMediaReadiness($row, $attachments);

        return $row;
    }

    private function hydrateContentMediaRow(array $row): array
    {
        $row = $this->hydrateJsonFields($row, ['metadata_json']);
        $row['display_url'] = $this->mediaDisplayUrl($row);
        $row['effective_caption'] = trim((string) ($row['caption'] ?? '')) !== ''
            ? (string) $row['caption']
            : (string) ($row['media_caption'] ?? '');
        $row['effective_alt_text'] = trim((string) ($row['alt_text_override'] ?? '')) !== ''
            ? (string) $row['alt_text_override']
            : (string) ($row['media_alt_text'] ?? '');

        return $row;
    }

    private function contentMediaReadiness(array $item, array $attachments): array
    {
        $roles = array_values(array_unique(array_map(static fn(array $row): string => (string) ($row['role'] ?? ''), $attachments)));
        $mediaTypes = array_values(array_unique(array_map(static fn(array $row): string => (string) ($row['media_type'] ?? ''), $attachments)));
        $warnings = [];
        $contentType = (string) ($item['content_type'] ?? '');
        $channel = (string) ($item['channel'] ?? '');
        $hasRole = static fn(string $role): bool => in_array($role, $roles, true);
        $hasImageOrVideo = in_array('image', $mediaTypes, true) || in_array('video', $mediaTypes, true);

        if (in_array($contentType, ['blog_post', 'case_study'], true) && !$hasRole('featured')) {
            $warnings[] = 'featured_image_recommended';
        }
        if ((in_array($contentType, ['social_post', 'ad_copy'], true) || in_array($channel, ['linkedin', 'facebook', 'instagram', 'x', 'ads'], true)) && !$hasImageOrVideo) {
            $warnings[] = 'channel_image_or_video_recommended';
        }
        if (in_array($contentType, ['newsletter', 'email'], true) && !$hasRole('banner')) {
            $warnings[] = 'banner_recommended';
        }
        if ($contentType === 'video_script' && !$hasRole('video_source') && !$hasRole('reference')) {
            $warnings[] = 'source_or_reference_media_recommended';
        }

        foreach ($attachments as $attachment) {
            if ((string) ($attachment['media_type'] ?? '') === 'image' && trim((string) ($attachment['effective_alt_text'] ?? '')) === '') {
                $warnings[] = 'alt_text_missing';
            }
            if ((string) ($attachment['media_type'] ?? '') === 'video' && trim((string) ($attachment['effective_caption'] ?? $attachment['media_transcript'] ?? '')) === '') {
                $warnings[] = 'caption_or_transcript_recommended';
            }
        }

        return [
            'warnings' => array_values(array_unique($warnings)),
            'attachment_count' => count($attachments),
            'roles' => $roles,
            'media_types' => $mediaTypes,
        ];
    }

    private function recommendedContentMediaRoles(string $contentType, string $channel): array
    {
        $roles = ['inline'];
        if (in_array($contentType, ['blog_post', 'case_study'], true)) {
            $roles[] = 'featured';
        }
        if (in_array($contentType, ['newsletter', 'email'], true) || $channel === 'email') {
            $roles[] = 'banner';
        }
        if (in_array($contentType, ['social_post', 'ad_copy'], true) || in_array($channel, ['linkedin', 'facebook', 'instagram', 'x', 'ads'], true)) {
            $roles[] = 'thumbnail';
        }
        if ($contentType === 'video_script') {
            $roles[] = 'video_source';
            $roles[] = 'reference';
        }

        return array_values(array_unique($roles));
    }

    private function contentMediaWarningMessages(array $warnings, array $recommendedRoles): array
    {
        $messages = [
            'featured_image_recommended' => 'Attach a featured image for long-form content and case studies.',
            'channel_image_or_video_recommended' => 'Attach an image or video for channel-ready social or ad copy.',
            'banner_recommended' => 'Attach a banner for email or newsletter layout planning.',
            'source_or_reference_media_recommended' => 'Attach source or reference media for the video script.',
            'alt_text_missing' => 'Add alt text to image media before approval.',
            'caption_or_transcript_recommended' => 'Add a caption or transcript to video media before export.',
        ];
        $recommendations = [];
        foreach ($warnings as $warning) {
            $recommendations[] = $messages[(string) $warning] ?? 'Review media readiness warning: ' . (string) $warning;
        }
        if ($recommendations === []) {
            $recommendations[] = 'Media placement is in good shape. Keep rights, alt text, captions, and crop notes current.';
        }
        $recommendations[] = 'Recommended roles for this context: ' . implode(', ', $recommendedRoles) . '.';

        return array_values(array_unique($recommendations));
    }

    private function rankMediaForPlacement(array $mediaFiles, array $preferredRoles): array
    {
        $preferredImageRoles = array_intersect($preferredRoles, ['featured', 'thumbnail', 'banner', 'hero', 'social_preview', 'proof', 'cta', 'gallery']);
        $preferredVideoRoles = array_intersect($preferredRoles, ['video_source', 'reference', 'hero', 'proof', 'testimonial']);
        $ranked = [];
        foreach ($mediaFiles as $media) {
            $mediaType = (string) ($media['media_type'] ?? '');
            $score = 10;
            if ((string) ($media['approval_status'] ?? '') === 'approved') {
                $score += 20;
            }
            if (in_array((string) ($media['license_status'] ?? ''), ['owned', 'licensed'], true)) {
                $score += 15;
            }
            if ($preferredImageRoles !== [] && in_array($mediaType, ['image', 'logo', 'thumbnail', 'banner'], true)) {
                $score += 10;
            }
            if ($preferredVideoRoles !== [] && $mediaType === 'video') {
                $score += 10;
            }
            if (trim((string) ($media['alt_text'] ?? '')) !== '' || trim((string) ($media['caption'] ?? $media['transcript'] ?? '')) !== '') {
                $score += 5;
            }
            if (in_array((string) ($media['approval_status'] ?? ''), ['blocked', 'rejected', 'archived'], true)) {
                $score -= 40;
            }
            if (in_array((string) ($media['license_status'] ?? ''), ['expired', 'restricted'], true)) {
                $score -= 30;
            }
            $media['placement_score'] = $score;
            $media['display_url'] = $this->mediaDisplayUrl($media);
            $ranked[] = $media;
        }

        usort($ranked, static fn(array $left, array $right): int => ((int) ($right['placement_score'] ?? 0) <=> (int) ($left['placement_score'] ?? 0)) ?: strcmp((string) ($left['title'] ?? ''), (string) ($right['title'] ?? '')));

        return $ranked;
    }

    private function exportableContentMedia(int $contentItemId): array
    {
        if ($contentItemId <= 0 || !Database::tableExists('marketing_content_media')) {
            return [];
        }

        return array_map(
            static fn(array $attachment): array => [
                'media_file_id' => (int) ($attachment['media_file_id'] ?? 0),
                'role' => (string) ($attachment['role'] ?? 'attachment'),
                'title' => (string) ($attachment['media_title'] ?? ''),
                'media_type' => (string) ($attachment['media_type'] ?? ''),
                'url' => (string) ($attachment['display_url'] ?? ''),
                'caption' => (string) ($attachment['effective_caption'] ?? ''),
                'alt_text' => (string) ($attachment['effective_alt_text'] ?? ''),
                'placement_notes' => (string) ($attachment['placement_notes'] ?? ''),
                'crop_guidance' => (string) ($attachment['crop_guidance'] ?? ''),
                'sort_order' => (int) ($attachment['sort_order'] ?? 0),
                'approval_status' => (string) ($attachment['approval_status'] ?? ''),
                'license_status' => (string) ($attachment['license_status'] ?? ''),
                'expiry_date' => $attachment['expiry_date'] ?? null,
            ],
            $this->listContentMedia($contentItemId)
        );
    }

