    private function buildAiCreativeLinkedRecords(array $input): array
    {
        $workspaceId = $this->workspaceId();
        $records = [];

        $contentId = (int) ($input['content_item_id'] ?? 0);
        if ($contentId > 0) {
            $item = $this->getContentItem($contentId);
            if (!$item) {
                throw new RuntimeException('Marketing content item not found.');
            }
            $records['content_item'] = $item;
            $records['content_media'] = $this->listContentMedia($contentId);
        }

        $landingPageId = (int) ($input['landing_page_id'] ?? 0);
        if ($landingPageId > 0) {
            $page = $this->getLandingPage($landingPageId);
            if (!$page) {
                throw new RuntimeException('Marketing landing page not found.');
            }
            $records['landing_page'] = $page;
            $records['landing_page_readiness'] = $this->calculateLandingPagePublishingReadiness($page);
        }

        $mediaId = (int) ($input['media_file_id'] ?? 0);
        if ($mediaId > 0) {
            $media = $this->getMediaFile($mediaId);
            if (!$media) {
                throw new RuntimeException('Marketing media file not found.');
            }
            $records['media_file'] = $media;
        }

        $assetId = (int) ($input['asset_id'] ?? 0);
        if ($assetId > 0 && Database::tableExists('marketing_assets')) {
            $this->assertWorkspaceRecord('marketing_assets', $assetId, $workspaceId);
            $records['asset'] = Database::queryOne(
                'SELECT * FROM marketing_assets WHERE workspace_id = ? AND id = ?',
                [$workspaceId, $assetId]
            ) ?: [];
        }

        $creativeBriefId = (int) ($input['creative_brief_id'] ?? 0);
        if ($creativeBriefId > 0 && Database::tableExists('marketing_creative_briefs')) {
            $this->assertWorkspaceRecord('marketing_creative_briefs', $creativeBriefId, $workspaceId);
            $records['creative_brief'] = Database::queryOne(
                'SELECT * FROM marketing_creative_briefs WHERE workspace_id = ? AND id = ?',
                [$workspaceId, $creativeBriefId]
            ) ?: [];
        }

        $assetRequestId = (int) ($input['asset_request_id'] ?? 0);
        if ($assetRequestId > 0 && Database::tableExists('marketing_asset_requests')) {
            $this->assertWorkspaceRecord('marketing_asset_requests', $assetRequestId, $workspaceId);
            $records['asset_request'] = Database::queryOne(
                'SELECT * FROM marketing_asset_requests WHERE workspace_id = ? AND id = ?',
                [$workspaceId, $assetRequestId]
            ) ?: [];
        }

        return array_filter($records, static fn($record): bool => is_array($record) && $record !== []);
    }

