              asset_id, creative_brief_id, asset_request_id, prompt_key, input_json, context_json, provider_json,
              result_json, created_by)
             VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)",
            [
                $this->workspaceId(),
                $this->generateUuid(),
                $data['action'],
                $data['status'],
                $data['target_type'],
                $data['content_item_id'] ?? null,
                $data['landing_page_id'] ?? null,
                $data['media_file_id'] ?? null,
                $data['asset_id'] ?? null,
                $data['creative_brief_id'] ?? null,
                $data['asset_request_id'] ?? null,
                $data['prompt_key'] ?? null,
