    private function normalizeMarketingAiContextSurface(string $surface): string
    {
        $surface = strtolower(trim($surface));
        return in_array($surface, self::AI_CONTEXT_SNAPSHOT_SURFACES, true) ? $surface : 'custom';
    }

    private function normalizeMarketingAiContextSnapshotLinks(array $links, int $workspaceId): array
    {
        $normalized = [];
        foreach ([
            'assistant_run_id' => 'marketing_assistant_runs',
            'content_tool_run_id' => 'marketing_content_tool_runs',
            'creative_run_id' => 'marketing_ai_creative_runs',
            'campaign_copilot_run_id' => 'marketing_campaign_copilot_runs',
            'content_item_id' => 'marketing_content_items',
            'campaign_id' => 'campaigns',
            'campaign_brief_id' => 'marketing_campaign_briefs',
            'landing_page_id' => 'marketing_landing_pages',
        ] as $field => $table) {
            $id = (int) ($links[$field] ?? 0);
            if ($id > 0) {
                $this->assertWorkspaceRecord($table, $id, $workspaceId);
                $normalized[$field] = $id;
            } else {
                $normalized[$field] = null;
            }
        }
        $normalized['metadata_json'] = $this->sanitizeJsonCompatible($links['metadata_json'] ?? $links['metadata'] ?? []);

        return $normalized;
    }

    private function extractMarketingAiContextSnapshotEvidence(array $context, array $provider): array
    {
        $bundle = (array) ($context['context_bundle'] ?? $context['context_bundle_json'] ?? []);
        $bundleQuality = (array) ($bundle['bundle_quality'] ?? $context['bundle_quality'] ?? []);
        $workspaceBrain = (array) (
            $context['workspace_brain']
            ?? $bundle['blocks']['workspace_brain']
            ?? []
        );
        $missing = array_merge(
            (array) ($provider['missing_context'] ?? []),
            (array) ($provider['missing_context_flags'] ?? []),
            (array) ($workspaceBrain['missing_context'] ?? []),
            (array) ($bundleQuality['missing_context_flags'] ?? []),
            (array) ($bundleQuality['missing_workspace_context'] ?? [])
        );
        $recommended = array_merge(
            (array) ($provider['recommended_context_inputs'] ?? []),
            (array) ($workspaceBrain['recommended_inputs'] ?? [])
        );
        $linkedRecords = (array) (
            $context['linked_records']
            ?? $bundle['blocks']['linked_records']
            ?? []
        );
        $contextScore = (float) (
            $provider['context_score']
            ?? $bundleQuality['context_quality_score']
            ?? 0
        );
        if ($contextScore > 1) {
            $contextScore = $contextScore / 100;
        }
        $workspaceBrainScore = (int) (
            $provider['workspace_brain_score']
            ?? $workspaceBrain['score']
            ?? $bundleQuality['workspace_brain_score']
            ?? 0
        );

        return [
            'context_score' => round(max(0, min(1, $contextScore)), 4),
            'workspace_brain_score' => max(0, min(100, $workspaceBrainScore)),
            'missing_context' => $this->normalizeAiStringList($missing),
            'recommended_inputs' => $this->normalizeAiStringList($recommended),
            'linked_records' => $this->sanitizeJsonCompatible($linkedRecords),
        ];
    }

    private function marketingAiContextHash(array $contextBundle): string
    {
        $stable = $this->sortMarketingAiContextTree($contextBundle);
        return hash('sha256', $this->normalizeJsonValue($stable) ?: '{}');
    }

    private function sortMarketingAiContextTree(mixed $value): mixed
    {
        if (!is_array($value)) {
            return $value;
        }

        $isList = $value === [] || array_keys($value) === range(0, count($value) - 1);
        foreach ($value as $key => $item) {
            $value[$key] = $this->sortMarketingAiContextTree($item);
        }
        if (!$isList) {
            ksort($value);
        }

        return $value;
    }

    private function sanitizeToolInput(array $input): array
    {
        $clean = [];
        foreach ($input as $key => $value) {
            $key = preg_replace('/[^a-zA-Z0-9_]/', '', (string) $key) ?: '';
            if ($key === '') {
                continue;
            }
            if (is_array($value)) {
                $clean[$key] = array_map(static fn($item): string => Security::sanitizeInput((string) $item, 'string'), $value);
            } else {
                $clean[$key] = Security::sanitizeInput((string) $value, 'string');
            }
        }

        return $clean;
    }

    private function contentToolSource(array $item, array $input): string
    {
        $source = trim((string) ($input['source'] ?? $item['draft_body'] ?? ''));
        if ($source !== '') {
            return $source;
        }

        return trim((string) ($item['title'] ?? 'Untitled marketing content'));
    }

    private function outlineDraft(array $item): string
    {
        $title = (string) ($item['title'] ?? 'Marketing content');
        $audience = (string) ($item['target_audience'] ?? 'target audience');
        $objective = (string) ($item['objective'] ?? 'move the audience to the next step');

        return "Outline: {$title}\n\n"
            . "1. Hook\n"
            . "- Speak directly to {$audience}\n"
            . "- Name the problem or opportunity\n\n"
            . "2. Main Message\n"
            . "- Explain why this matters now\n"
            . "- Connect the message to {$objective}\n\n"
            . "3. Proof\n"
            . "- Add one proof point, example, or differentiator\n\n"
            . "4. Call To Action\n"
            . "- Give the reader one clear next step";
    }

    private function rewriteForChannel(string $source, string $channel): string
    {
        $source = trim($source);
        if ($channel === 'linkedin') {
            return "LinkedIn version:\n\n" . $source . "\n\nWhat would you improve first?";
        }
        if ($channel === 'email' || $channel === 'newsletter') {
            return "Subject: A practical next step\n\nHi there,\n\n" . $source . "\n\nBest,\nThe team";
        }
        if ($channel === 'sms' || $channel === 'whatsapp') {
            return substr(preg_replace('/\s+/', ' ', $source) ?: $source, 0, 280);
        }
        if ($channel === 'ads') {
            return "Headline: Solve the next marketing bottleneck\nPrimary text: " . substr(preg_replace('/\s+/', ' ', $source) ?: $source, 0, 180) . "\nCTA: Learn more";
        }

        return "For {$channel}:\n\n" . $source;
    }

    private function shortenDraft(string $source): string
    {
        $sentences = preg_split('/(?<=[.!?])\s+/', trim($source)) ?: [];
        $short = implode(' ', array_slice(array_filter($sentences), 0, 3));
        return $short !== '' ? $short : substr($source, 0, 320);
    }

    private function expandDraft(string $source, array $item): string
    {
        $objective = trim((string) ($item['objective'] ?? 'move the audience forward')) ?: 'move the audience forward';

        return rtrim($source) . "\n\n"
            . "Why this matters:\n"
            . "- The audience needs a clearer path to {$objective}.\n"
            . "- The message should connect the problem, proof, and next step.\n"
            . "- The follow-up should be easy to say yes to.\n\n"
            . "Next step: choose one action and make it simple to complete.";
    }

    private function changeDraftTone(string $source, string $tone): string
    {
        return "Tone: {$tone}\n\n" . $source;
    }

    private function defaultCta(string $provided): string
    {
        $provided = trim($provided);
        if ($provided !== '') {
            return Security::sanitizeInput($provided, 'string');
        }

        $cta = Database::tableExists('marketing_context_items')
            ? Database::queryOne(
                "SELECT title FROM marketing_context_items
                 WHERE workspace_id = ? AND item_type = 'default_cta' AND status = 'active'
                 ORDER BY updated_at DESC LIMIT 1",
                [$this->workspaceId()]
            )
            : null;

        return (string) ($cta['title'] ?? 'Book a short conversation');
    }

    /**
     * @return array<int,string>
     */
    private function toolChannels(mixed $value): array
    {
        $json = $this->normalizeStringListJson($value);
        $channels = $json ? (json_decode($json, true) ?: []) : ['linkedin', 'email', 'whatsapp'];
        $normalized = [];
        foreach ($channels as $channel) {
            $normalized[] = $this->normalizeEnum((string) $channel, self::CHANNELS, 'channel');
        }

        return array_values(array_unique($normalized));
    }

    private function scoreSeoDraft(string $source, array $item): array
    {
        $score = 30;
        $checks = [];
        $keyword = trim((string) ($item['seo_topic_keyword'] ?? ''));
        if ($keyword !== '' && stripos($source, $keyword) !== false) {
            $score += 25;
            $checks[] = 'Target keyword appears in draft';
        }
        if (str_word_count($source) >= 80) {
            $score += 20;
            $checks[] = 'Draft has enough substance for optimization';
        }
        if (preg_match('/\b(learn|book|request|download|get|start)\b/i', $source)) {
            $score += 15;
            $checks[] = 'Draft includes action-oriented language';
        }
        if (preg_match('/^.{20,90}$/m', trim(strtok($source, "\n") ?: ''))) {
            $score += 10;
            $checks[] = 'Opening line can work as a title or hook';
        }

        return ['score' => min(100, $score), 'checks' => $checks];
    }

    private function scoreBrandPersonaDraft(string $source, array $item): array
    {
        $score = 35;
        $checks = [];
        foreach (['brand_profile_name' => 'Brand context linked', 'persona_name' => 'Persona context linked'] as $field => $message) {
            if (!empty($item[$field])) {
                $score += 20;
                $checks[] = $message;
            }
        }
        if (!empty($item['target_audience']) && stripos($source, (string) $item['target_audience']) !== false) {
            $score += 15;
            $checks[] = 'Draft names the target audience';
        }
        if (!empty($item['objective']) && stripos($source, strtok((string) $item['objective'], ' ') ?: '') !== false) {
            $score += 10;
            $checks[] = 'Draft reflects the stated objective';
        }

        return ['score' => min(100, $score), 'checks' => $checks];
    }

