    private function countContextType(string $type): int
    {
        if (!Database::tableExists('marketing_context_items')) {
            return 0;
        }

        $row = Database::queryOne(
            "SELECT COUNT(*) AS count
             FROM marketing_context_items
             WHERE workspace_id = ? AND item_type = ? AND status = 'active'",
            [$this->workspaceId(), $type]
        );

        return (int) ($row['count'] ?? 0);
    }

    private function upsertMarketingOnboardingState(int $score): array
    {
        if (!Database::tableExists('marketing_onboarding_state')) {
            return [
                'readiness_score' => $score,
                'completed_steps_json' => [],
                'dismissed_steps_json' => [],
                'starter_pack_metadata_json' => [],
            ];
        }

        Database::execute(
            "INSERT INTO marketing_onboarding_state
                (workspace_id, readiness_score, completed_steps_json, dismissed_steps_json)
             VALUES (?, ?, JSON_ARRAY(), JSON_ARRAY())
             ON DUPLICATE KEY UPDATE
                readiness_score = VALUES(readiness_score)",
            [$this->workspaceId(), $score]
        );

        return $this->loadMarketingOnboardingState();
    }

    private function loadMarketingOnboardingState(): array
    {
        if (!Database::tableExists('marketing_onboarding_state')) {
            return [];
        }

        $row = Database::queryOne(
            'SELECT * FROM marketing_onboarding_state WHERE workspace_id = ? LIMIT 1',
            [$this->workspaceId()]
        ) ?: [];

        return $row ? $this->hydrateJsonFields($row, ['completed_steps_json', 'dismissed_steps_json', 'starter_pack_metadata_json']) : [];
    }

    private function starterPackState(array $state): array
    {
        $metadata = is_array($state['starter_pack_metadata_json'] ?? null)
            ? $state['starter_pack_metadata_json']
            : [];

        if ($metadata === []) {
            return [
                'created' => !empty($state['starter_pack_created_at']),
                'archived' => !empty($state['starter_pack_archived_at']),
                'created_at' => (string) ($state['starter_pack_created_at'] ?? ''),
                'archived_at' => (string) ($state['starter_pack_archived_at'] ?? ''),
                'created_counts' => [],
            ];
        }

        $metadata['created'] = !empty($metadata['created']) || !empty($state['starter_pack_created_at']);
        $metadata['archived'] = !empty($metadata['archived']) || !empty($state['starter_pack_archived_at']);
        $metadata['created_at'] = (string) ($state['starter_pack_created_at'] ?? ($metadata['created_at'] ?? ''));
        $metadata['archived_at'] = (string) ($state['starter_pack_archived_at'] ?? ($metadata['archived_at'] ?? ''));

        return $metadata;
    }

    private function saveStarterPackMetadata(array $summary, int $userId): void
    {
        Database::execute(
            "INSERT INTO marketing_onboarding_state
                (workspace_id, readiness_score, completed_steps_json, dismissed_steps_json, starter_pack_created_at, starter_pack_created_by, starter_pack_metadata_json)
             VALUES (?, ?, JSON_ARRAY(), JSON_ARRAY(), NOW(), ?, ?)
             ON DUPLICATE KEY UPDATE
                starter_pack_created_at = COALESCE(starter_pack_created_at, NOW()),
                starter_pack_created_by = COALESCE(starter_pack_created_by, VALUES(starter_pack_created_by)),
                starter_pack_metadata_json = VALUES(starter_pack_metadata_json),
                starter_pack_archived_at = NULL,
                starter_pack_archived_by = NULL",
            [
                $this->workspaceId(),
                (int) ($this->getMarketingOnboardingStatus()['score'] ?? 0),
                $userId > 0 ? $userId : null,
                json_encode($summary, JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE),
            ]
        );
    }

    private function normalizeOnboardingStepList(mixed $value): array
    {
        if (is_string($value)) {
            $decoded = json_decode($value, true);
            $value = is_array($decoded) ? $decoded : preg_split('/[,\\r\\n]+/', $value);
        }

        $allowed = array_keys($this->marketingOnboardingSteps());
        $steps = [];
        foreach ((array) $value as $step) {
            $step = preg_replace('/[^a-z0-9_]/', '', strtolower((string) $step)) ?: '';
            if ($step !== '' && in_array($step, $allowed, true)) {
                $steps[] = $step;
            }
        }

        return array_values(array_unique($steps));
    }

