    private function assistantRecommendation(string $assistantType, array $input, array $context): string
    {
        $prompt = trim((string) ($input['prompt'] ?? 'Improve marketing execution.'));
        $contextScore = (int) ($context['context_completeness']['score'] ?? 0);
        $contentCreated = (int) ($context['analytics']['content_velocity']['total_created'] ?? 0);

        $open = "Assistant: " . ucwords(str_replace('_', ' ', $assistantType)) . "\n"
            . "Prompt: {$prompt}\n\n";

        return $open
            . "Recommendation:\n"
            . "- Use the saved marketing context first. Current context completeness is {$contextScore}%.\n"
            . "- Build from the strongest active campaign or content item before creating new work.\n"
            . "- Keep this as a draft-side action until a human reviews it.\n\n"
            . "Next actions:\n"
            . "- Clarify the audience and offer.\n"
            . "- Produce one primary draft and one distribution variant.\n"
            . "- Add a review checkpoint before publication.\n\n"
            . "Recent velocity signal: {$contentCreated} content items were created in the current reporting window.";
    }

    private function marketingAssistantPromptKey(string $assistantType): string
    {
        if ($assistantType === 'performance_analyst') {
            return 'performance_analysis';
        }

        return in_array($assistantType, [
            'copywriter',
            'email_sequence_builder',
            'landing_page_optimizer',
            'repurposing',
        ], true)
            ? 'assistant_copywriter'
            : 'assistant_strategist';
    }

