    private function deterministicMarketingStrategyGaps(array $context): array
    {
        $opportunities = [];
        $addOpportunity = static function (
            string $title,
            string $type,
            string $priority,
            string $reason,
            string $recommendedAction,
            int $weekOffset = 0,
            array $links = []
        ) use (&$opportunities): void {
            $opportunities[] = [
                'title' => $title,
                'type' => $type,
                'priority' => $priority,
                'reason' => $reason,
                'recommended_action' => $recommendedAction,
                'week_offset' => $weekOffset,
            ] + $links;
        };

        $missingContext = array_values((array) ($context['context_completeness']['missing'] ?? []));
        foreach (array_slice($missingContext, 0, 8) as $missing) {
            $label = ucwords(str_replace('_', ' ', (string) $missing));
            $type = in_array($missing, ['brand_profile', 'persona', 'offer'], true) ? 'campaign' : 'content';
            if ($missing === 'compliance_term') {
                $type = 'review';
            }
            $addOpportunity(
                'Add ' . $label . ' context',
                $type,
                in_array($missing, ['brand_profile', 'persona', 'offer'], true) ? 'high' : 'medium',
                'Marketing context completeness is missing ' . $label . '.',
                'Create or update the missing ' . strtolower($label) . ' record before relying on AI-generated campaign recommendations.'
            );
        }

        $briefs = (array) ($context['briefs'] ?? []);
        if ($briefs === []) {
            $addOpportunity(
                'Create an active campaign brief',
                'campaign',
                'high',
                'No active campaign brief is available for AI planning.',
                'Create one campaign brief with objective, audience, offer, channels, timeline, and success metrics.'
            );
        }
        foreach (array_slice($briefs, 0, 5) as $brief) {
            $score = (int) ($brief['readiness_score'] ?? $brief['context_score'] ?? 0);
            if ($score > 0 && $score < 70) {
                $addOpportunity(
                    'Improve brief readiness: ' . (string) ($brief['title'] ?? 'Campaign brief'),
                    'campaign',
                    'high',
                    'This campaign brief is below the release-ready threshold.',
                    'Fill missing strategy fields and review the brief before content planning.',
                    0,
                    ['campaign_brief_id' => (int) ($brief['id'] ?? 0), 'campaign_id' => (int) ($brief['campaign_id'] ?? 0)]
                );
            }
        }

        $seenChannels = [];
        $seenStages = [];
        foreach ((array) ($context['content'] ?? []) as $item) {
            $seenChannels[] = (string) ($item['channel'] ?? '');
            $seenStages[] = (string) ($item['funnel_stage'] ?? '');
            $missing = [];
            if (trim((string) ($item['objective'] ?? '')) === '') {
                $missing[] = 'objective';
            }
            if (trim((string) ($item['target_audience'] ?? '')) === '') {
                $missing[] = 'audience';
            }
            if (trim((string) ($item['draft_body'] ?? '')) !== '' && stripos((string) $item['draft_body'], 'book') === false && stripos((string) $item['draft_body'], 'cta') === false) {
                $missing[] = 'CTA';
            }
            if (empty($item['seo_topic_id']) && in_array((string) ($item['content_type'] ?? ''), ['blog_post', 'case_study'], true)) {
                $missing[] = 'SEO topic';
            }
            if ($missing !== []) {
                $addOpportunity(
                    'Strengthen content context: ' . (string) ($item['title'] ?? 'Marketing content'),
                    'content',
                    'medium',
                    'This content item is missing ' . implode(', ', $missing) . '.',
                    'Add the missing content context before review or distribution.',
                    0,
                    ['content_item_id' => (int) ($item['id'] ?? 0), 'campaign_brief_id' => (int) ($item['campaign_brief_id'] ?? 0), 'campaign_id' => (int) ($item['campaign_id'] ?? 0)]
                );
            }
            if (count($opportunities) >= 12) {
                break;
            }
        }

        $seenChannels = array_values(array_unique(array_filter($seenChannels)));
        if (!in_array('email', $seenChannels, true)) {
            $addOpportunity('Plan an email nurture angle', 'content', 'medium', 'No active content currently covers the email channel.', 'Add one email or newsletter planning item tied to an active campaign.');
        }
        if (!in_array('linkedin', $seenChannels, true)) {
            $addOpportunity('Plan a LinkedIn distribution angle', 'content', 'medium', 'No active content currently covers LinkedIn.', 'Add one LinkedIn draft or repurpose item for the strongest campaign message.');
        }
        $seenStages = array_values(array_unique(array_filter($seenStages)));
        if (!in_array('conversion', $seenStages, true)) {
            $addOpportunity('Add conversion-stage content', 'campaign', 'medium', 'The current content mix has no conversion-stage item.', 'Plan one CTA-led conversion asset linked to a landing page or form.');
        }

        foreach (array_slice((array) ($context['overdue_queue'] ?? []), 0, 3) as $queueItem) {
            $addOpportunity(
                'Resolve overdue planning item: ' . (string) ($queueItem['title'] ?? 'Planning item'),
                'review',
                'high',
                'An existing planning queue item is overdue or blocked.',
                'Review ownership, unblock the item, or archive it if it is no longer relevant.',
                0,
                ['campaign_brief_id' => (int) ($queueItem['campaign_brief_id'] ?? 0), 'campaign_id' => (int) ($queueItem['campaign_id'] ?? 0)]
            );
        }

        return [
            'summary' => $opportunities === []
                ? 'No major deterministic marketing strategy gaps were found.'
                : 'Found ' . count($opportunities) . ' marketing strategy gap opportunities.',
            'opportunities' => array_slice($opportunities, 0, 15),
        ];
    }

    private function buildCampaignPlannerLinkedRecords(array $inputs): array
    {
        $workspaceId = $this->workspaceId();
        $records = [];
        $campaignId = (int) ($inputs['campaign_id'] ?? 0);
        if ($campaignId > 0 && Database::tableExists('campaigns')) {
            $records['campaign'] = Database::queryOne(
                "SELECT id, name, description, objective, channel_mix, status
                 FROM campaigns
                 WHERE workspace_id = ? AND id = ?",
                [$workspaceId, $campaignId]
            ) ?: [];
        }
        $personaId = (int) ($inputs['persona_id'] ?? 0);
        if ($personaId > 0 && Database::tableExists('marketing_personas')) {
            $records['persona'] = Database::queryOne(
                'SELECT * FROM marketing_personas WHERE workspace_id = ? AND id = ?',
                [$workspaceId, $personaId]
            ) ?: [];
        }
        $offerId = (int) ($inputs['offer_context_item_id'] ?? 0);
        if ($offerId > 0 && Database::tableExists('marketing_context_items')) {
            $records['offer'] = Database::queryOne(
                "SELECT * FROM marketing_context_items WHERE workspace_id = ? AND id = ? AND item_type = 'offer'",
                [$workspaceId, $offerId]
            ) ?: [];
        }

        return array_filter($records, static fn($record): bool => is_array($record) && $record !== []);
    }

    private function deterministicMarketingCampaignPlan(array $inputs, array $linkedRecords, array $context): array
    {
        $campaignName = trim((string) ($linkedRecords['campaign']['name'] ?? ''));
        $personaName = trim((string) ($linkedRecords['persona']['name'] ?? ''));
        $offerTitle = trim((string) ($linkedRecords['offer']['title'] ?? ''));
        $goal = trim((string) ($inputs['planning_goal'] ?? $inputs['prompt'] ?? ''));
        $concept = $campaignName !== '' ? $campaignName : ($goal !== '' ? $goal : 'Manual-first marketing AI operating loop');
        $audience = $personaName !== '' ? $personaName : 'Best-fit audience from the active CRM workspace';
        $offer = $offerTitle !== '' ? $offerTitle : 'Primary offer from Marketing Context Hub';
        $campaignId = (int) ($inputs['campaign_id'] ?? 0);

        $queue = [
            [
                'title' => 'Draft campaign brief for ' . $concept,
                'type' => 'campaign',
                'priority' => 'high',
                'reason' => 'Campaign planning should begin with a reviewable brief before content is created.',
                'recommended_action' => 'Create or update a campaign brief with objective, audience, offer, channels, timeline, and metrics.',
                'week_offset' => 0,
                'campaign_id' => $campaignId,
            ],
            [
                'title' => 'Plan content set for ' . $audience,
                'type' => 'content',
                'priority' => 'medium',
                'reason' => 'The campaign needs a connected content set across awareness, consideration, and conversion.',
                'recommended_action' => 'Plan one blog or guide, one social post, one email, and one conversion CTA asset.',
                'week_offset' => 1,
                'campaign_id' => $campaignId,
            ],
            [
                'title' => 'Review landing page need for ' . $offer,
                'type' => 'review',
                'priority' => 'medium',
                'reason' => 'Conversion campaigns need a reviewed destination before manual distribution.',
                'recommended_action' => 'Decide whether an existing landing page can support the offer or a new draft is needed.',
                'week_offset' => 1,
                'campaign_id' => $campaignId,
            ],
        ];

        return [
            'summary' => 'Generated a reviewable campaign plan with ' . count($queue) . ' queue suggestions.',
            'campaign_concept' => $concept,
            'recommended_audience' => $audience,
            'offer_angle' => $offer,
            'suggested_channels' => ['email', 'linkedin', 'blog'],
            'content_set' => ['Campaign brief', 'Long-form content draft', 'LinkedIn distribution post', 'Email nurture draft', 'Landing page review'],
            'landing_page_need' => 'Review or create a CRM-hosted landing page plan before manual distribution.',
            'queue_suggestions' => $queue,
            'context_counts' => $context['counts'] ?? [],
        ];
    }

    private function deterministicMarketingPerformanceAnalysis(array $performance, array $context): array
    {
        $working = [];
        $weakSpots = [];
        $nextTests = [];
        $queue = [];

        $channelRows = (array) ($performance['by_channel'] ?? []);
        if ($channelRows === []) {
            $weakSpots[] = 'No distribution channels have enough planned/exported data yet.';
            $nextTests[] = 'Create one manual distribution draft for the strongest active content item.';
            $queue[] = [
                'title' => 'Create first measurable distribution test',
                'type' => 'content',
                'priority' => 'high',
                'reason' => 'Performance analysis needs at least one planned/exported distribution item.',
                'recommended_action' => 'Create a manual distribution draft with a clear channel, CTA, and UTM link.',
                'week_offset' => 0,
            ];
        } else {
            foreach (array_slice($channelRows, 0, 3) as $row) {
                $working[] = ucwords(str_replace('_', ' ', (string) ($row['channel'] ?? 'channel'))) . ' has ' . (int) ($row['post_count'] ?? 0) . ' planned items.';
                if ((int) ($row['exported_count'] ?? 0) === 0) {
                    $weakSpots[] = ucwords(str_replace('_', ' ', (string) ($row['channel'] ?? 'channel'))) . ' has planned work but no exported bundle yet.';
                }
            }
            $queue[] = [
                'title' => 'Review highest-volume channel test',
                'type' => 'report',
                'priority' => 'medium',
                'reason' => 'A channel has enough planned work to review export and UTM readiness.',
                'recommended_action' => 'Compare planned copy, exported bundles, UTM links, and attributed outcomes for the strongest channel.',
                'week_offset' => 0,
            ];
        }

        $utmLinks = (int) ($performance['utm_links'] ?? 0);
        if ($utmLinks === 0) {
            $weakSpots[] = 'No UTM links exist for attribution follow-up.';
            $nextTests[] = 'Add UTM links to the next manually distributed campaign asset.';
            $queue[] = [
                'title' => 'Add UTM links for the next campaign test',
                'type' => 'campaign',
                'priority' => 'medium',
                'reason' => 'Without UTM links, performance analysis cannot connect manual distribution to outcomes.',
                'recommended_action' => 'Create UTM links for the next landing page or distribution destination.',
                'week_offset' => 0,
            ];
        } else {
            $working[] = $utmLinks . ' UTM links are available for attribution review.';
        }

        $roi = $performance['campaign_roi']['roi_percent'] ?? null;
        if ($roi === null) {
            $weakSpots[] = 'Campaign ROI is not available yet.';
            $nextTests[] = 'Add campaign budget and attribution data before comparing ROI.';
        } else {
            $working[] = 'Campaign ROI is currently ' . (string) $roi . '%.';
            if ((float) $roi < 0) {
                $queue[] = [
                    'title' => 'Review negative ROI campaign',
                    'type' => 'report',
                    'priority' => 'high',
                    'reason' => 'The latest campaign ROI is below zero.',
                    'recommended_action' => 'Review offer, channel, budget, and conversion quality before expanding spend.',
                    'week_offset' => 0,
                ];
            }
        }

        if ((int) ($context['counts']['content'] ?? 0) === 0) {
            $weakSpots[] = 'No active content exists for performance comparison.';
        }

        return [
            'summary' => 'Generated performance analysis with ' . count($queue) . ' queue suggestions.',
            'working' => $working !== [] ? $working : ['Performance baseline is still forming.'],
            'weak_spots' => $weakSpots,
            'next_tests' => $nextTests !== [] ? $nextTests : ['Review channel exports and UTM performance weekly.'],
            'queue_suggestions' => array_slice($queue, 0, 10),
        ];
    }

    private function normalizeMarketingAiOpportunityResult(array $candidate, array $fallback): array
    {
        $summary = Security::sanitizeInput(trim((string) ($candidate['summary'] ?? $fallback['summary'] ?? '')), 'string');
        $rawOpportunities = is_array($candidate['opportunities'] ?? null)
            ? (array) $candidate['opportunities']
            : (array) ($fallback['opportunities'] ?? []);
        $opportunities = [];
        foreach ($rawOpportunities as $opportunity) {
            if (!is_array($opportunity)) {
                continue;
            }
            $title = Security::sanitizeInput(trim((string) ($opportunity['title'] ?? '')), 'string');
            if ($title === '') {
                continue;
            }
            $opportunities[] = [
                'title' => $title,
                'type' => $this->normalizeMarketingAiQueueType((string) ($opportunity['type'] ?? $opportunity['item_type'] ?? 'other')),
                'priority' => $this->normalizeMarketingAiQueuePriority((string) ($opportunity['priority'] ?? 'medium')),
                'reason' => Security::sanitizeInput(trim((string) ($opportunity['reason'] ?? 'AI opportunity identified from Marketing context.')), 'string'),
                'recommended_action' => Security::sanitizeInput(trim((string) ($opportunity['recommended_action'] ?? $opportunity['action'] ?? 'Review this opportunity.')), 'string'),
                'week_offset' => max(0, min(12, (int) ($opportunity['week_offset'] ?? 0))),
                'content_item_id' => max(0, (int) ($opportunity['content_item_id'] ?? 0)),
                'campaign_brief_id' => max(0, (int) ($opportunity['campaign_brief_id'] ?? 0)),
                'campaign_id' => max(0, (int) ($opportunity['campaign_id'] ?? 0)),
            ];
        }

        return [
            'summary' => $summary !== '' ? $summary : (string) ($fallback['summary'] ?? 'Marketing AI opportunities are ready for review.'),
            'opportunities' => $opportunities !== [] ? array_slice($opportunities, 0, 15) : (array) ($fallback['opportunities'] ?? []),
        ];
    }

    private function normalizeMarketingCampaignPlannerResult(array $candidate, array $fallback): array
    {
        $summary = Security::sanitizeInput(trim((string) ($candidate['summary'] ?? $fallback['summary'] ?? '')), 'string');
        $queueFallback = ['opportunities' => (array) ($fallback['queue_suggestions'] ?? [])];
        $queueCandidate = ['opportunities' => (array) ($candidate['queue_suggestions'] ?? [])];
        $queue = $this->normalizeMarketingAiOpportunityResult($queueCandidate, $queueFallback)['opportunities'];

        return [
            'summary' => $summary !== '' ? $summary : (string) ($fallback['summary'] ?? 'Campaign plan generated for review.'),
            'campaign_concept' => Security::sanitizeInput(trim((string) ($candidate['campaign_concept'] ?? $fallback['campaign_concept'] ?? '')), 'string'),
            'recommended_audience' => Security::sanitizeInput(trim((string) ($candidate['recommended_audience'] ?? $fallback['recommended_audience'] ?? '')), 'string'),
            'offer_angle' => Security::sanitizeInput(trim((string) ($candidate['offer_angle'] ?? $fallback['offer_angle'] ?? '')), 'string'),
            'suggested_channels' => $this->normalizeAiStringList($candidate['suggested_channels'] ?? $fallback['suggested_channels'] ?? []),
            'content_set' => $this->normalizeAiStringList($candidate['content_set'] ?? $fallback['content_set'] ?? []),
            'landing_page_need' => Security::sanitizeInput(trim((string) ($candidate['landing_page_need'] ?? $fallback['landing_page_need'] ?? '')), 'string'),
            'queue_suggestions' => $queue,
        ];
    }

    private function normalizeMarketingPerformanceAnalysisResult(array $candidate, array $fallback): array
    {
        $queueFallback = ['opportunities' => (array) ($fallback['queue_suggestions'] ?? [])];
        $queueCandidate = ['opportunities' => (array) ($candidate['queue_suggestions'] ?? [])];
        $queue = $this->normalizeMarketingAiOpportunityResult($queueCandidate, $queueFallback)['opportunities'];

        return [
            'summary' => Security::sanitizeInput(trim((string) ($candidate['summary'] ?? $fallback['summary'] ?? 'Performance analysis generated for review.')), 'string'),
            'working' => $this->normalizeAiStringList($candidate['working'] ?? $fallback['working'] ?? []),
            'weak_spots' => $this->normalizeAiStringList($candidate['weak_spots'] ?? $fallback['weak_spots'] ?? []),
            'next_tests' => $this->normalizeAiStringList($candidate['next_tests'] ?? $fallback['next_tests'] ?? []),
            'queue_suggestions' => $queue,
        ];
    }

    private function marketingIntegrationReadinessRecommendations(array $checks): array
    {
        $recommendations = [];
        foreach ($checks as $key => $check) {
            if (!empty($check['ready'])) {
                continue;
            }
            $recommendations[] = match ($key) {
                'channel_exports' => 'Prepare or complete manual channel export bundles before external publishing.',
                'email_exports' => 'Complete email run export bundles and send checklists before any manual send.',
                'landing_page_tokens' => 'Complete approval and token publish readiness for CRM-hosted landing pages.',
                'utm_links' => 'Create UTM links before distributing campaign traffic manually.',
                'approvals' => 'Complete pending content approvals before release.',
                'assets' => 'Add or approve required assets before channel export.',
                'destination_checklists' => 'Complete destination URLs and channel checklists before export.',
                'crm_connections' => 'Connect Marketing to CRM campaigns, forms, contacts, deals, tasks, templates, tracking, and assets before relying on execution decisions.',
                default => 'Review integration readiness before release.',
            };
        }

        return array_values(array_unique($recommendations));
    }

    private function deterministicMarketingIntegrationReadinessReview(array $readiness): array
    {
        $opportunities = [];
        $add = static function (string $title, string $type, string $priority, string $reason, string $action) use (&$opportunities): void {
            $opportunities[] = [
                'title' => $title,
                'type' => $type,
                'priority' => $priority,
                'reason' => $reason,
                'recommended_action' => $action,
                'week_offset' => 0,
            ];
        };

        $checks = (array) ($readiness['checks'] ?? []);
        if (empty($checks['assets']['ready'])) {
            $add(
                'Add assets for manual channel exports',
                'asset',
                'high',
                'One or more channel exports or asset requests are missing approved assets.',
                'Attach approved assets or complete open asset requests before creating external channel packages.'
            );
        }
        if (empty($checks['approvals']['ready'])) {
            $add(
                'Complete pending marketing approvals',
                'review',
                'high',
                'Content approvals remain pending.',
                'Approve, reject, or update pending review items before manual distribution.'
            );
        }
        if (empty($checks['utm_links']['ready'])) {
            $add(
                'Create UTM links for manual distribution',
                'campaign',
                'medium',
                'Campaign traffic cannot be attributed without UTM links.',
                'Create UTM links for the next landing page or distribution destination before export.'
            );
        }
        if (empty($checks['channel_exports']['ready'])) {
            $add(
                'Prepare manual channel export bundles',
                'content',
                'medium',
                'Distribution posts need reviewable manual export bundles.',
                'Create or complete channel export bundles, then let a human mark them exported after external use.'
            );
        }
        if (empty($checks['email_exports']['ready'])) {
            $add(
                'Complete email run export checklist',
                'review',
                'medium',
                'Email runs need subject, body, send checklist, and export bundle readiness.',
                'Complete the send checklist and export bundle before any human sends outside the CRM.'
            );
        }
        if (empty($checks['landing_page_tokens']['ready'])) {
            $add(
                'Complete landing page token readiness',
                'campaign',
                'medium',
                'Landing pages need approval and CRM token publish readiness.',
                'Resolve missing landing fields and use the CRM token publish workflow only after approval.'
            );
        }
        if (empty($checks['destination_checklists']['ready'])) {
            $add(
                'Complete destination URLs and checklists',
                'review',
                'medium',
                'Some distribution posts or email runs need destination URL and checklist details.',
                'Add required destination, checklist, and export fields before packaging the work.'
            );
        }

        return [
            'summary' => 'Integration readiness review found ' . count($opportunities) . ' manual follow-up opportunities.',
            'opportunities' => array_slice($opportunities, 0, 12),
        ];
    }

    private function createMarketingAiQueueSuggestions(
        array $opportunities,
        string $aiPhase,
        string $promptKey,
        array $provider,
        float $contextScore,
        ?int $userId
    ): array {
        $created = [];
        foreach ($opportunities as $opportunity) {
            if (!is_array($opportunity) || trim((string) ($opportunity['title'] ?? '')) === '') {
                continue;
            }
            $metadata = [
                'source' => 'marketing_ai',
                'ai_phase' => $aiPhase,
                'prompt_key' => $promptKey,
                'context_score' => $contextScore,
                'provider' => $provider,
                'reason' => (string) ($opportunity['reason'] ?? ''),
                'recommended_action' => (string) ($opportunity['recommended_action'] ?? ''),
                'manual_first' => true,
                'external_publish' => false,
                'external_send' => false,
            ];
            $created[] = $this->createPlanningQueueItem([
                'title' => (string) $opportunity['title'],
                'item_type' => $this->normalizeMarketingAiQueueType((string) ($opportunity['type'] ?? 'other')),
                'priority' => $this->normalizeMarketingAiQueuePriority((string) ($opportunity['priority'] ?? 'medium')),
                'status' => 'planned',
                'week_start' => date('Y-m-d', strtotime('monday this week +' . max(0, (int) ($opportunity['week_offset'] ?? 0)) . ' weeks')),
                'due_at' => date('Y-m-d\TH:i', strtotime('friday this week +' . max(0, (int) ($opportunity['week_offset'] ?? 0)) . ' weeks 17:00')),
                'content_item_id' => (int) ($opportunity['content_item_id'] ?? 0),
                'campaign_brief_id' => (int) ($opportunity['campaign_brief_id'] ?? 0),
                'campaign_id' => (int) ($opportunity['campaign_id'] ?? 0),
                'owner_user_id' => $userId,
                'metadata_json' => $metadata,
                'created_by' => $userId,
            ]);
        }

        return $created;
    }

    private function normalizeMarketingAiQueueType(string $type): string
    {
        $type = strtolower(trim($type));
        return in_array($type, self::PLANNING_QUEUE_TYPES, true) ? $type : 'other';
    }

    private function normalizeMarketingAiQueuePriority(string $priority): string
    {
        $priority = strtolower(trim($priority));
        return in_array($priority, self::PLANNING_QUEUE_PRIORITIES, true) ? $priority : 'medium';
    }

    private function buildMarketingContextBundle(string $promptKey, array $inputs = [], array $linkedRecords = []): array
    {
        $contextCompleteness = Database::tableExists('marketing_context_items')
            ? $this->getContextCompleteness()
            : ['score' => 0, 'missing' => ['marketing_context_items']];
        $recentContent = Database::tableExists('marketing_content_items')
            ? $this->listContentItems(['exclude_status' => 'archived'], 5, 0)
            : [];
        $recentBriefs = Database::tableExists('marketing_campaign_briefs')
            ? $this->listCampaignBriefs(['status_open' => true], 5, 0)
            : [];
        $analytics = Database::tableExists('marketing_analytics_snapshots')
            ? $this->getMarketingAnalyticsSummary('weekly')
            : [];
        $workspaceBrain = $this->getMarketingAiWorkspaceBrain($this->currentUserId() ?: null);

        $quality = $this->scoreMarketingContextBundle($contextCompleteness, $inputs, $linkedRecords);
        $quality['workspace_brain_score'] = (int) ($workspaceBrain['score'] ?? 0);
        $quality['workspace_brain_status'] = (string) ($workspaceBrain['status'] ?? 'thin');
        $quality['missing_workspace_context'] = array_slice((array) ($workspaceBrain['missing_context'] ?? []), 0, 6);

        return [
            'surface' => self::AI_SURFACE,
            'prompt_key' => $promptKey,
            'bundle_quality' => $quality,
            'blocks' => [
                'inputs' => $inputs,
                'linked_records' => $linkedRecords,
                'context_completeness' => $contextCompleteness,
                'analytics' => $analytics,
                'recent_content' => $recentContent,
                'recent_briefs' => $recentBriefs,
                'workspace_brain' => $workspaceBrain,
            ],
        ];
    }

    private function buildCampaignBriefLinkedRecords(array $inputs): array
    {
        $workspaceId = $this->workspaceId();
        $records = [];

        $campaignId = (int) ($inputs['campaign_id'] ?? 0);
        if ($campaignId > 0 && Database::tableExists('campaigns')) {
            $records['campaign'] = Database::queryOne(
                "SELECT id, name, description, objective, channel_mix, status
                 FROM campaigns
                 WHERE workspace_id = ? AND id = ?",
                [$workspaceId, $campaignId]
            ) ?: [];
        }

        $personaId = (int) ($inputs['persona_id'] ?? 0);
        if ($personaId > 0 && Database::tableExists('marketing_personas')) {
            $records['persona'] = Database::queryOne(
                "SELECT *
                 FROM marketing_personas
                 WHERE workspace_id = ? AND id = ?",
                [$workspaceId, $personaId]
            ) ?: [];
        }

        foreach ([
            'offer_context_item_id' => 'offer',
            'content_pillar_context_item_id' => 'content_pillar',
        ] as $field => $key) {
            $id = (int) ($inputs[$field] ?? 0);
            if ($id > 0 && Database::tableExists('marketing_context_items')) {
                $records[$key] = Database::queryOne(
                    "SELECT *
                     FROM marketing_context_items
                     WHERE workspace_id = ? AND id = ?",
                    [$workspaceId, $id]
                ) ?: [];
            }
        }

        $landingPageId = (int) ($inputs['landing_page_id'] ?? 0);
        if ($landingPageId > 0 && Database::tableExists('marketing_landing_pages')) {
            $records['landing_page'] = Database::queryOne(
                "SELECT id, title, slug, headline, seo_title, meta_description, status
                 FROM marketing_landing_pages
                 WHERE workspace_id = ? AND id = ?",
                [$workspaceId, $landingPageId]
            ) ?: [];
        }

        return array_filter($records, static fn($record): bool => is_array($record) && $record !== []);
    }

    private function fallbackCampaignBriefDraft(array $inputs, array $linkedRecords): array
    {
        $campaignName = trim((string) ($linkedRecords['campaign']['name'] ?? ''));
        $personaName = trim((string) ($linkedRecords['persona']['name'] ?? ''));
        $offerTitle = trim((string) ($linkedRecords['offer']['title'] ?? ''));
        $pillarTitle = trim((string) ($linkedRecords['content_pillar']['title'] ?? ''));
        $landingTitle = trim((string) ($linkedRecords['landing_page']['title'] ?? ''));

        $objective = trim((string) ($inputs['objective'] ?? ''));
        if ($objective === '') {
            $objective = trim((string) ($linkedRecords['campaign']['objective'] ?? ''));
        }
        if ($objective === '') {
            $objective = $campaignName !== '' ? 'Drive measurable engagement for ' . $campaignName : 'Move the target audience to the next qualified step.';
        }

        $audience = trim((string) ($inputs['audience'] ?? ''));
        if ($audience === '') {
            $audience = $personaName !== '' ? $personaName : 'Primary campaign audience';
        }

        $offerText = trim((string) ($inputs['offer_text'] ?? ''));
        if ($offerText === '') {
            $offerText = $offerTitle !== '' ? $offerTitle : 'A clear, low-friction offer tied to the campaign objective.';
        }

        $channels = $this->normalizeAiStringList($inputs['channels'] ?? []);
        if ($channels === []) {
            $channels = ['email', 'linkedin', 'blog'];
        }

        return [
            'objective' => $objective,
            'audience' => $audience,
            'offer_text' => $offerText,
            'key_message' => trim((string) ($inputs['key_message'] ?? '')) ?: 'Help ' . $audience . ' achieve ' . strtolower($objective) . ' with ' . $offerText . '.',
            'channels' => $channels,
            'channel_plan' => $this->normalizeAiStringList($inputs['channel_plan'] ?? []) ?: array_map(
                static fn(string $channel): string => ucwords(str_replace('_', ' ', $channel)) . ': adapt the core message for review before publishing.',
                $channels
            ),
            'launch_timeline' => $this->normalizeAiStringList($inputs['launch_timeline'] ?? []) ?: [
                'Confirm campaign brief and message owner.',
                $landingTitle !== '' ? 'Review linked landing page: ' . $landingTitle . '.' : 'Prepare the primary conversion destination.',
                'Create channel drafts and route for review.',
                'Measure performance against success metrics.',
            ],
            'success_metrics' => trim((string) ($inputs['success_metrics'] ?? '')) ?: 'Track qualified engagement, conversion actions, review readiness, and channel-level response.',
            'strategy_notes' => array_values(array_filter([$pillarTitle !== '' ? 'Content pillar: ' . $pillarTitle : ''])),
        ];
    }

    private function normalizeGeneratedCampaignBriefFields(array $fields, array $fallback): array
    {
        $normalized = [];
        foreach (['objective', 'audience', 'offer_text', 'key_message', 'success_metrics'] as $field) {
            $value = $fields[$field] ?? $fallback[$field] ?? '';
            if (is_array($value)) {
                $value = implode("\n", $this->normalizeAiStringList($value));
            }
            $value = Security::sanitizeInput(trim((string) $value), 'string');
            $normalized[$field] = $value !== '' ? $value : (string) ($fallback[$field] ?? '');
        }

        foreach (['channels', 'channel_plan', 'launch_timeline'] as $field) {
            $list = $this->normalizeAiStringList($fields[$field] ?? []);
            $normalized[$field] = $list !== [] ? $list : $this->normalizeAiStringList($fallback[$field] ?? []);
        }

        return $normalized;
    }

    private function buildLandingPageLinkedRecords(array $inputs): array
    {
        $workspaceId = $this->workspaceId();
        $records = [];

        $campaignId = (int) ($inputs['campaign_id'] ?? 0);
        if ($campaignId > 0 && Database::tableExists('campaigns')) {
            $records['campaign'] = Database::queryOne(
                "SELECT id, name, description, objective, channel_mix, status
                 FROM campaigns
                 WHERE workspace_id = ? AND id = ?",
                [$workspaceId, $campaignId]
            ) ?: [];
        }

        $formId = (int) ($inputs['form_id'] ?? 0);
        if ($formId > 0 && Database::tableExists('forms')) {
            $records['form'] = Database::queryOne(
                "SELECT id, name, NULL AS description, success_message
                 FROM forms
                 WHERE workspace_id = ? AND id = ?",
                [$workspaceId, $formId]
            ) ?: [];
        }

        $mediaIds = array_values(array_filter(array_map('intval', [
            $inputs['hero_media_file_id'] ?? 0,
            $inputs['social_preview_media_file_id'] ?? 0,
            $inputs['cta_media_file_id'] ?? 0,
            $inputs['proof_media_file_id'] ?? 0,
            $inputs['testimonial_media_file_id'] ?? 0,
        ])));
        if ($mediaIds !== []) {
            $records['media'] = array_values($this->mediaRowsById($workspaceId, $mediaIds));
        }

        if (Database::tableExists('marketing_brand_profiles')) {
            $records['brand_profile'] = Database::queryOne(
                "SELECT *
                 FROM marketing_brand_profiles
                 WHERE workspace_id = ?
                 ORDER BY is_default DESC, updated_at DESC, id DESC
                 LIMIT 1",
                [$workspaceId]
            ) ?: [];
        }

        if (Database::tableExists('marketing_campaign_briefs')) {
            $records['campaign_brief'] = Database::queryOne(
                "SELECT *
                 FROM marketing_campaign_briefs
                 WHERE workspace_id = ? AND status <> 'archived'
                 ORDER BY updated_at DESC, id DESC
                 LIMIT 1",
                [$workspaceId]
            ) ?: [];
        }

        return array_filter($records, static fn($record): bool => is_array($record) && $record !== []);
    }

    private function landingPageMediaRecommendations(array $inputs, array $linkedRecords): array
    {
        $hasMedia = static fn(string $field): bool => (int) ($inputs[$field] ?? 0) > 0;
        $recommendations = [];
        if (!$hasMedia('hero_media_file_id')) {
            $recommendations[] = 'Add a hero image or short video that shows the offer, product, customer outcome, or campaign moment above the fold.';
        }
        if (!$hasMedia('social_preview_media_file_id')) {
            $recommendations[] = 'Add a social preview image so shared links have a deliberate thumbnail.';
        }
        if (!$hasMedia('proof_media_file_id') && !$hasMedia('testimonial_media_file_id')) {
            $recommendations[] = 'Add proof media such as a testimonial clip, customer screenshot, result graphic, or logo proof block.';
        }
        if (!$hasMedia('cta_media_file_id')) {
            $recommendations[] = 'Consider a CTA-supporting visual near the conversion action.';
        }
        foreach ((array) ($linkedRecords['media'] ?? []) as $media) {
            if ((string) ($media['media_type'] ?? '') === 'image' && trim((string) ($media['alt_text'] ?? '')) === '') {
                $recommendations[] = 'Add alt text for "' . (string) ($media['title'] ?? 'selected media') . '" before publishing.';
            }
            if ((string) ($media['media_type'] ?? '') === 'video' && trim((string) ($media['transcript'] ?? $media['caption'] ?? '')) === '') {
                $recommendations[] = 'Add a caption or transcript for "' . (string) ($media['title'] ?? 'selected video') . '" before publishing.';
            }
        }

        return array_values(array_unique($recommendations));
    }

    private function fallbackLandingPageCopyDraft(array $inputs, array $linkedRecords): array
    {
        $title = trim((string) ($inputs['title'] ?? 'Landing page'));
        $campaignName = trim((string) ($linkedRecords['campaign']['name'] ?? ''));
        $objective = trim((string) ($linkedRecords['campaign']['objective'] ?? $linkedRecords['campaign_brief']['objective'] ?? ''));
        $audience = trim((string) ($linkedRecords['campaign_brief']['audience'] ?? 'your target audience'));
        $offer = trim((string) ($linkedRecords['campaign_brief']['offer_text'] ?? 'the next best offer'));
        $goal = trim((string) ($inputs['conversion_goal'] ?? 'lead_capture')) ?: 'lead_capture';
        $headline = trim((string) ($inputs['headline'] ?? ''));
        if ($headline === '') {
            $headline = $campaignName !== '' ? $campaignName . ': a clearer path to action' : $title . ' for ' . $audience;
        }

        return [
            'headline' => $headline,
            'seo_title' => trim((string) ($inputs['seo_title'] ?? '')) ?: substr($headline, 0, 60),
            'meta_description' => trim((string) ($inputs['meta_description'] ?? '')) ?: 'Learn how ' . $audience . ' can move from interest to action with ' . $offer . '.',
            'body_sections' => $this->normalizeAiSectionBlocks($inputs['body_sections'] ?? []) ?: [
                [
                    'heading' => 'Make the next step obvious',
                    'body' => $objective !== '' ? 'This page helps ' . $audience . ' ' . strtolower($objective) . '.' : 'This page turns campaign interest into a concrete, reviewable next step.',
                ],
                [
                    'heading' => 'Why it matters now',
                    'body' => 'Use the saved campaign context, proof, and offer to explain the problem without unsupported claims.',
                ],
                [
                    'heading' => 'What happens next',
                    'body' => 'Give visitors one low-friction action and set expectations for follow-up.',
                ],
            ],
            'cta_blocks' => $this->normalizeAiSectionBlocks($inputs['cta_blocks'] ?? []) ?: [
                ['heading' => 'Start the conversation', 'body' => $goal === 'demo_request' ? 'Book a demo' : 'Request the next step'],
            ],
            'proof_blocks' => $this->normalizeAiSectionBlocks($inputs['proof_blocks'] ?? []) ?: [
                ['heading' => 'Proof to add', 'body' => 'Add customer evidence, quantified outcomes, or differentiators already saved in Marketing Context Hub.'],
            ],
            'faq_blocks' => $this->normalizeAiSectionBlocks($inputs['faq_blocks'] ?? []) ?: [
                ['heading' => 'What will happen after I submit?', 'body' => 'A team member reviews your request and follows up with the relevant next step.'],
                ['heading' => 'Is this automated publishing?', 'body' => 'No. This copy remains a draft until a human reviews and saves it.'],
            ],
            'thank_you_copy' => trim((string) ($inputs['thank_you_copy'] ?? '')) ?: 'Thanks. Your request has been received and the team will follow up with the next step.',
        ];
    }

    private function normalizeGeneratedLandingPageFields(array $fields, array $fallback): array
    {
        $normalized = [];
        foreach (['headline', 'seo_title', 'meta_description', 'thank_you_copy'] as $field) {
            $value = $fields[$field] ?? $fallback[$field] ?? '';
            if (is_array($value)) {
                $value = implode("\n", $this->normalizeAiStringList($value));
            }
            $value = $this->nullableSanitizedText($value) ?? '';
            $normalized[$field] = $value !== '' ? $value : (string) ($fallback[$field] ?? '');
        }

        foreach (['body_sections', 'cta_blocks', 'proof_blocks', 'faq_blocks'] as $field) {
            $blocks = $this->normalizeAiSectionBlocks($fields[$field] ?? []);
            $normalized[$field] = $blocks !== [] ? $blocks : $this->normalizeAiSectionBlocks($fallback[$field] ?? []);
        }

        return $normalized;
    }

    private function normalizeAiSectionBlocks($value): array
    {
        if (is_string($value)) {
            $decoded = json_decode($value, true);
            $value = is_array($decoded) ? $decoded : preg_split('/\r?\n\s*\r?\n/', $value);
        }
        if (!is_array($value)) {
            return [];
        }

        $blocks = [];
        foreach ($value as $block) {
            if (is_array($block)) {
                $heading = $this->nullableSanitizedText($block['question'] ?? $block['heading'] ?? $block['title'] ?? '');
                $body = $this->nullableSanitizedText($block['answer'] ?? $block['body'] ?? $block['copy'] ?? '');
            } else {
                $parts = preg_split('/\r?\n/', trim((string) $block), 2) ?: [];
                $heading = $this->nullableSanitizedText($parts[0] ?? '');
                $body = $this->nullableSanitizedText($parts[1] ?? '');
            }
            if ($heading !== null || $body !== null) {
                $blocks[] = ['heading' => $heading, 'body' => $body];
            }
        }

        return $blocks;
    }

    private function formatAiSectionBlocksForForm(array $blocks): string
    {
        return implode("\n\n", array_map(
            static fn(array $block): string => trim((string) ($block['heading'] ?? '') . "\n" . (string) ($block['body'] ?? '')),
            $blocks
        ));
    }

    private function normalizeAiStringList($value): array
    {
        if (is_string($value)) {
            $value = preg_split('/[\r\n,]+/', $value) ?: [];
        }
        if (!is_array($value)) {
            return [];
        }

        $items = [];
        foreach ($value as $item) {
            if (is_array($item)) {
                $item = implode(' ', array_filter(array_map(static fn($part): string => trim((string) $part), $item)));
            }
            $text = Security::sanitizeInput(trim((string) $item), 'string');
            if ($text !== '') {
                $items[] = $text;
            }
        }

        return array_values(array_unique($items));
    }

    private function scoreMarketingContextBundle(array $contextCompleteness, array $inputs = [], array $linkedRecords = []): array
    {
        $score = ((int) ($contextCompleteness['score'] ?? 0)) / 100;
        $missing = array_values(array_filter((array) ($contextCompleteness['missing'] ?? [])));

        foreach (['brand_profile', 'persona', 'campaign_brief'] as $key) {
            if (empty($linkedRecords[$key]) && empty($inputs[$key . '_id'])) {
                $missing[] = $key;
                $score -= 0.05;
            }
        }
        if (empty($inputs['objective']) && empty($linkedRecords['campaign_brief']['objective'])) {
            $missing[] = 'objective';
            $score -= 0.08;
        }
        if (empty($inputs['target_audience']) && empty($inputs['audience']) && empty($linkedRecords['persona'])) {
            $missing[] = 'audience';
            $score -= 0.08;
        }

        return [
            'context_quality_score' => max(0.0, min(1.0, round($score, 4))),
            'missing_context_flags' => array_values(array_unique($missing)),
        ];
    }

    private function runMarketingAiPrompt(
        string $promptKey,
        array $bundle,
        array $inputs,
        string $task,
        callable $fallback,
        bool $expectJson = false
    ): array {
        $runtimeControl = (new AIRuntimeControlService())->getEffectiveControl(self::AI_SURFACE);
        $provider = [
            'mode' => 'deterministic_fallback',
            'fallback_used' => true,
            'runtime_control' => $runtimeControl,
            'prompt_key' => $promptKey,
        ];
        $raw = '';
        $resolvedPrompt = [];
        $fallbackValue = $fallback();

        if (in_array((string) ($runtimeControl['control_mode'] ?? 'normal'), ['paused', 'diagnostics_only'], true)) {
            $provider['message'] = 'Marketing AI runtime is paused or diagnostics-only; deterministic fallback used.';
        } else {
            try {
                $resolvedPrompt = $this->aiService->buildPromptFromRegistry(self::AI_SURFACE, $promptKey, $bundle, $inputs);
                $raw = trim($this->aiService->processWithPrompt($task, $resolvedPrompt, [
                    'fast_fallback' => true,
                    'force_refresh' => true,
                    'credential_scope' => $this->marketingCredentialScope($promptKey),
                ]));
                $provider = $this->aiService->getLastProviderStatus() + $provider;
                $provider['fallback_used'] = $raw === '';
                $provider['prompt_version'] = (int) ($resolvedPrompt['prompt_version'] ?? 0);
                $provider['prompt_key'] = $promptKey;
                $provider['runtime_control'] = $runtimeControl;
            } catch (Throwable $e) {
                $provider['success'] = false;
                $provider['message'] = $e->getMessage();
            }
        }

        if ($expectJson) {
            $fallbackJson = is_array($fallbackValue) ? $fallbackValue : [];
            $decode = $raw !== ''
                ? $this->decodeMarketingAiJsonWithStatus($raw, $fallbackJson)
                : ['json' => $fallbackJson, 'status' => 'not_attempted'];
            $json = (array) $decode['json'];
            $provider['json_decode_status'] = (string) $decode['status'];
            if ($raw !== '' && $decode['status'] !== 'valid') {
                $provider['fallback_used'] = true;
                $provider['message'] = $provider['message'] ?? 'AI response was not valid JSON; deterministic fallback used.';
            }
            return [
                'text' => $raw,
                'json' => $json,
                'provider' => $provider,
                'resolved_prompt' => $resolvedPrompt,
                'context_bundle' => $bundle,
            ];
        }

        return [
            'text' => $raw !== '' ? $raw : (string) $fallbackValue,
            'json' => [],
            'provider' => $provider,
            'resolved_prompt' => $resolvedPrompt,
            'context_bundle' => $bundle,
        ];
    }

    private function marketingCredentialScope(string $promptKey): string
    {
        return in_array($promptKey, [
            'landing_page_copy',
            'campaign_planner',
            'quality_review',
            'assistant_copywriter',
            'brief_builder',
            'content_draft',
        ], true) || str_starts_with($promptKey, 'creative_')
            ? WorkspaceAIProviderConfigService::SCOPE_CONTENT_GENERATION
            : WorkspaceAIProviderConfigService::SCOPE_GENERAL;
    }

    private function decodeMarketingAiJson(string $raw, array $fallback): array
    {
        return $this->decodeMarketingAiJsonWithStatus($raw, $fallback)['json'];
    }

    private function decodeMarketingAiJsonWithStatus(string $raw, array $fallback): array
    {
        $candidate = trim($raw);
        $candidate = preg_replace('/^```(?:json)?\s*/i', '', $candidate) ?? $candidate;
        $candidate = preg_replace('/\s*```$/', '', $candidate) ?? $candidate;
        $start = strpos($candidate, '{');
        $end = strrpos($candidate, '}');
        if ($start !== false && $end !== false && $end >= $start) {
            $candidate = substr($candidate, $start, $end - $start + 1);
        }

        $decoded = json_decode($candidate, true);
        if (json_last_error() !== JSON_ERROR_NONE || !is_array($decoded)) {
            return ['json' => $fallback, 'status' => 'invalid_json'];
        }

        return ['json' => array_replace_recursive($fallback, $decoded), 'status' => 'valid'];
    }

    private function buildDraftContext(array $data): array
    {
        $campaign = [];
        $campaignId = (int) ($data['campaign_id'] ?? 0);
        if ($campaignId > 0 && Database::tableExists('campaigns')) {
            $campaign = Database::queryOne(
                "SELECT name, description, objective FROM campaigns WHERE workspace_id = ? AND id = ?",
                [$this->workspaceId(), $campaignId]
            ) ?: [];
        }

        $brief = [];
        $briefId = (int) ($data['campaign_brief_id'] ?? 0);
        if ($briefId > 0 && Database::tableExists('marketing_campaign_briefs')) {
            $brief = Database::queryOne(
                "SELECT title, objective, audience, offer_text, key_message, channels_json
                 FROM marketing_campaign_briefs
                 WHERE workspace_id = ? AND id = ?",
                [$this->workspaceId(), $briefId]
            ) ?: [];
        }

        $brandProfile = $this->strategyContextRow('marketing_brand_profiles', (int) ($data['brand_profile_id'] ?? 0), 'name, voice, tone, banned_words, value_props, proof_points, cta_defaults');
        $persona = $this->strategyContextRow('marketing_personas', (int) ($data['persona_id'] ?? 0), 'name, segment, pains, goals, objections, preferred_channels_json');
        $seoTopic = $this->strategyContextRow('marketing_seo_topics', (int) ($data['seo_topic_id'] ?? 0), 'keyword, intent, funnel_stage, priority, target_url, status');
        $landingPage = $this->strategyContextRow('marketing_landing_pages', (int) ($data['landing_page_id'] ?? 0), 'title, slug, headline, body_sections_json, status');
        $contextItems = Database::tableExists('marketing_context_items')
            ? $this->listContextItems(['status' => 'active'], 30, 0)
            : [];

        $strategy = [];
        try {
            $userId = (int) ($_SESSION['user_id'] ?? 0);
            if ($userId > 0) {
                $readiness = (new SmartTemplateContextService())->getReadiness($userId);
                $strategy = (array) ($readiness['context_snapshot'] ?? []);
            }
        } catch (Throwable $e) {
            $strategy = [];
        }

        return [
            'title' => Security::sanitizeInput((string) ($data['title'] ?? 'Untitled marketing content'), 'string'),
            'content_type' => $this->normalizeEnum((string) ($data['content_type'] ?? 'social_post'), self::CONTENT_TYPES, 'content_type'),
            'channel' => $this->normalizeEnum((string) ($data['channel'] ?? 'other'), self::CHANNELS, 'channel'),
            'funnel_stage' => Security::sanitizeInput((string) ($data['funnel_stage'] ?? ''), 'string'),
            'objective' => Security::sanitizeInput((string) ($data['objective'] ?? ''), 'string'),
            'target_audience' => Security::sanitizeInput((string) ($data['target_audience'] ?? ''), 'string'),
            'campaign' => $campaign,
            'campaign_brief' => $brief,
            'brand_profile' => $brandProfile,
            'persona' => $persona,
            'seo_topic' => $seoTopic,
            'landing_page' => $landingPage,
            'marketing_context' => $contextItems,
            'strategy' => $strategy,
        ];
    }

    private function strategyContextRow(string $table, int $id, string $columns): array
    {
        if ($id <= 0 || !Database::tableExists($table)) {
            return [];
        }

        return Database::queryOne(
            "SELECT {$columns} FROM {$table} WHERE workspace_id = ? AND id = ? LIMIT 1",
            [$this->workspaceId(), $id]
        ) ?: [];
    }

    private function buildDraftPrompt(array $context): string
    {
        return "Create a practical marketing draft for this CRM workspace.\n"
            . "Return only the draft content, no markdown fence.\n\n"
            . json_encode($context, JSON_PRETTY_PRINT | JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE);
    }

    private function fallbackDraft(array $context): string
    {
        $title = (string) ($context['title'] ?? 'Marketing draft');
        $audience = trim((string) ($context['target_audience'] ?? 'your target audience')) ?: 'your target audience';
        $objective = trim((string) ($context['objective'] ?? 'move the audience to the next step')) ?: 'move the audience to the next step';

        return "Draft: {$title}\n\n"
            . "Hi {$audience},\n\n"
            . "Here is the core idea: we understand the problem you are trying to solve, and we can help you make progress with a clear next step.\n\n"
            . "Why it matters:\n"
            . "- It reduces wasted effort.\n"
            . "- It gives your team a simpler path forward.\n"
            . "- It connects the work to a measurable business outcome.\n\n"
            . "Call to action: Reply or book a short conversation so we can help you {$objective}.";
    }

    private function assertWorkspaceRecord(string $table, int $id, int $workspaceId): void
    {
        if (!Database::tableExists($table)) {
            throw new RuntimeException('Linked record table is unavailable.');
        }

        $row = Database::queryOne("SELECT id FROM {$table} WHERE workspace_id = ? AND id = ? LIMIT 1", [$workspaceId, $id]);
        if (!$row) {
            throw new RuntimeException('Linked record was not found in the active workspace.');
        }
    }

    private function assertContextItemType(int $id, string $itemType, int $workspaceId): void
    {
        $row = Database::queryOne(
            "SELECT id FROM marketing_context_items WHERE workspace_id = ? AND id = ? AND item_type = ? LIMIT 1",
            [$workspaceId, $id, $itemType]
        );
        if (!$row) {
            throw new RuntimeException('Linked marketing context record has the wrong type.');
        }
    }

    private function assertEmailTemplateAvailable(int $id, int $workspaceId): void
    {
        if (!Database::tableExists('email_templates')) {
            throw new RuntimeException('Email templates are unavailable.');
        }

        $row = Database::queryOne(
            "SELECT et.id
             FROM email_templates et
             LEFT JOIN smart_template_sets sts ON sts.id = et.smart_template_set_id
             WHERE et.id = ?
               AND et.workspace_id = ?
               AND COALESCE(et.is_library, 0) = 0
               AND COALESCE(et.is_active, 1) = 1
               AND (
                    COALESCE(et.is_ai_generated, 0) = 0
                    OR et.smart_template_set_id IS NULL
                    OR sts.status = 'active'
               )
             LIMIT 1",
            [$id, $workspaceId]
        );
        if (!$row) {
            throw new RuntimeException('Linked email template was not found in the active workspace.');
        }
    }

    private function assertWorkspaceUser(int $userId, int $workspaceId): void
    {
        if (!Database::tableExists('workspace_memberships')) {
            return;
        }

        $row = Database::queryOne(
            "SELECT id FROM workspace_memberships WHERE workspace_id = ? AND user_id = ? AND membership_status = 'active' LIMIT 1",
            [$workspaceId, $userId]
        );
        if (!$row) {
            throw new RuntimeException('Owner must be an active member of the workspace.');
        }
    }

    private function normalizeEnum(string $value, array $allowed, string $field): string
    {
        $value = strtolower(trim($value));
        if (!in_array($value, $allowed, true)) {
            throw new \InvalidArgumentException('Invalid ' . str_replace('_', ' ', $field) . '.');
        }

        return $value;
    }

    private function allowedValuesForField(string $field): array
    {
        return match ($field) {
            'content_type' => self::CONTENT_TYPES,
            'channel' => self::CHANNELS,
            'status' => self::STATUSES,
            'production_stage' => self::CONTENT_PRODUCTION_STAGES,
            'dependency_status' => self::CONTENT_DEPENDENCY_HEALTH_STATUSES,
            default => [],
        };
    }

    private function normalizeDateBoundary(string $value, bool $endOfDay): string
    {
        $date = substr(trim($value), 0, 10);
        $parsed = \DateTimeImmutable::createFromFormat('!Y-m-d', $date);
        if (!$parsed) {
            throw new \InvalidArgumentException('Invalid scheduled date filter.');
        }

        return $parsed->format('Y-m-d') . ($endOfDay ? ' 23:59:59' : ' 00:00:00');
    }

    private function normalizeDate(string $value, string $label): string
    {
        $date = substr(trim($value), 0, 10);
        $parsed = \DateTimeImmutable::createFromFormat('!Y-m-d', $date);
        if (!$parsed) {
            throw new \InvalidArgumentException('Invalid ' . $label . '.');
        }

        return $parsed->format('Y-m-d');
    }

    private function normalizeWeekStart(?string $value = null): string
    {
        $value = trim((string) $value);
        $timestamp = $value !== '' ? strtotime(substr($value, 0, 10)) : time();
        if ($timestamp === false) {
            throw new \InvalidArgumentException('Invalid planning week.');
        }

        return date('Y-m-d', strtotime('monday this week', $timestamp));
    }

    private function normalizeDateTime(string $value): ?string
    {
        $value = trim($value);
        if ($value === '') {
            return null;
        }

        $value = str_replace('T', ' ', substr($value, 0, 16));
        $parsed = \DateTimeImmutable::createFromFormat('!Y-m-d H:i', $value);
        if (!$parsed) {
            throw new \InvalidArgumentException('Invalid date/time value.');
        }

        return $parsed->format('Y-m-d H:i:00');
    }

    private function generateUuid(): string
    {
        $data = random_bytes(16);
        $data[6] = chr(ord($data[6]) & 0x0f | 0x40);
        $data[8] = chr(ord($data[8]) & 0x3f | 0x80);
        return vsprintf('%s%s-%s-%s-%s-%s%s%s', str_split(bin2hex($data), 4));
    }

    private function generatePreviewToken(): string
    {
        return bin2hex(random_bytes(16));
    }

    /**
     * @return array{sql:string, params:array<int, int>}
     */
    private function workspaceClause(string $alias = ''): array
    {
        return $this->workspaceScope->workspaceClause($alias);
    }

    private function workspaceId(): int
    {
        return $this->workspaceScope->requireActiveWorkspaceId();
    }

    private function currentUserId(): int
    {
        return (int) ($_SESSION['user_id'] ?? 0);
    }
}
